# ---------------- imza ----------------
function Get-SigMark { return (-join ([char[]](0x13D6, 0x1D40, 0x13A5, 0x1D2E, 0x13CB, 0x1D40, 0x13D6))) }
function Get-SigName { return 'S. Tibet Tuncer' }
function Get-SigLine { return ((Get-SigMark) + '   ' + (Get-SigName)) }

# ---------------- genel yardimcilar ----------------
function Format-Size([double]$Bytes) {
    if ($Bytes -ge 1TB) { return ('{0:N2} TB' -f ($Bytes / 1TB)) }
    if ($Bytes -ge 1GB) { return ('{0:N2} GB' -f ($Bytes / 1GB)) }
    if ($Bytes -ge 1MB) { return ('{0:N0} MB' -f ($Bytes / 1MB)) }
    if ($Bytes -ge 1KB) { return ('{0:N0} KB' -f ($Bytes / 1KB)) }
    return ('{0:N0} B' -f $Bytes)
}

function Format-Duration([double]$Seconds) {
    if ($Seconds -lt 90) { return ('{0:N0} sn' -f $Seconds) }
    if ($Seconds -lt 5400) { return ('{0:N0} dk' -f ($Seconds / 60)) }
    if ($Seconds -lt 172800) { return ('{0:N1} saat' -f ($Seconds / 3600)) }
    return ('{0:N1} g' + [char]0x00FC + 'n') -f ($Seconds / 86400)
}

function Get-JsonProp($Obj, [string]$Name) {
    if ($null -eq $Obj) { return $null }
    if ($Obj -is [System.Collections.IDictionary]) {
        if ($Obj.Contains($Name)) { return $Obj[$Name] }
        return $null
    }
    $p = $Obj.PSObject.Properties[$Name]
    if ($null -eq $p) { return $null }
    return $p.Value
}

function ConvertTo-Hashtable($Obj) {
    if ($null -eq $Obj) { return $null }
    if ($Obj -is [System.Collections.IDictionary]) {
        $h = @{}
        foreach ($k in @($Obj.Keys)) { $h[[string]$k] = ConvertTo-Hashtable $Obj[$k] }
        return $h
    }
    if ($Obj -is [string] -or $Obj -is [ValueType]) { return $Obj }
    if ($Obj -is [System.Collections.IEnumerable]) {
        $list = New-Object System.Collections.ArrayList
        foreach ($i in $Obj) { [void]$list.Add((ConvertTo-Hashtable $i)) }
        return , $list.ToArray()
    }
    if ($Obj -is [System.Management.Automation.PSCustomObject]) {
        $h = @{}
        foreach ($p in $Obj.PSObject.Properties) { $h[[string]$p.Name] = ConvertTo-Hashtable $p.Value }
        return $h
    }
    return $Obj
}

function Save-JsonFile($Obj, [string]$Path, [int]$Depth = 6) {
    $json = ConvertTo-Json -InputObject $Obj -Depth $Depth
    $enc = New-Object System.Text.UTF8Encoding($false)
    # once gecici dosyaya yazilir, sonra yerine konur: yazarken kapanma / es zamanli yazim ayar dosyasini bozmaz
    $tmp = $Path + '.' + [string]$PID + '.tmp'
    [System.IO.File]::WriteAllText($tmp, $json, $enc)
    try {
        if ([System.IO.File]::Exists($Path)) { [System.IO.File]::Replace($tmp, $Path, [NullString]::Value) } else { [System.IO.File]::Move($tmp, $Path) }
    } catch {
        try { [System.IO.File]::Delete($tmp) } catch { }
        [System.IO.File]::WriteAllText($Path, $json, $enc)
    }
}

function Read-JsonFile([string]$Path) {
    return (ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($Path)))
}

