function Get-Settings {
    $s = Get-DefaultSettings
    try {
        if (Test-Path -LiteralPath $sync.SettingsFile) {
            $obj = ConvertTo-Hashtable (Read-JsonFile $sync.SettingsFile)
            if ($obj -is [hashtable]) {
                foreach ($k in @($obj.Keys)) { $s[$k] = $obj[$k] }
                # 10.0.0: varsayilan gorunum beyaz ve sade oldu. Eski surumden kalan kaydin gorunumu (tema, yerlesim, tasarim, saydamlik) bir kez yeni varsayilana tasinir;
                # tasimadan once ayarlarin kopyasi AyarYedekleri klasorune yazilir (Ayarlar > Sifirlama > Son sifirlamayi geri al eski gorunumu getirir). Kopya yazilamazsa
                # gorunume dokunulmaz. Yakinlastirma, ana ekran bicimi, pano ve diger tercihler korunur. LookVersion gecisin bir kez yapilmasini saglar,
                # LookNotice tek seferlik bilgi icindir. Gorunum anahtari hic olmayan (yeni) kayitta bilgi gosterilmez.
                if (-not $obj.ContainsKey('LookVersion') -and ($obj.ContainsKey('Theme') -or $obj.ContainsKey('Layout'))) {
                    $lookKeys = @('Theme', 'Layout', 'Design', 'Backdrop', 'WinOpacity', 'DsNav', 'DsRadius', 'DsFont', 'DsGraph', 'DsSkin')
                    $dflt = Get-DefaultSettings
                    $lookMoved = $false
                    foreach ($lk in $lookKeys) {
                        if ($obj.ContainsKey($lk) -and ([string]$obj[$lk]) -ne ([string]$dflt[$lk])) { $lookMoved = $true }
                    }
                    if ($lookMoved -and ([string](Save-SettingsBackup $obj 'gorunum')) -ne '') {
                        foreach ($lk in $lookKeys) { $s[$lk] = $dflt[$lk] }
                        $s.LookNotice = $true
                    }
                }
            }
        }
    } catch { }
    foreach ($k in @('BackupSources', 'MaintItems', 'AppliedIds', 'KnownDevices', 'BlockedDevices', 'NetOff', 'AutoRules', 'Games', 'RegDenied', 'Board')) { $s[$k] = @($s[$k]) }
    return $s
}

function Save-Settings($S) {
    try { if ($S -is [hashtable] -and $null -ne $sync -and $null -ne $sync.RegDenied) { $S['RegDenied'] = @(Get-RegDeniedList | Select-Object -First 60) } } catch { }
    try { Save-JsonFile $S $sync.SettingsFile 8 } catch { }
}

# ---------------- kayit (log) ----------------
function Write-LogFile([string]$Line) {
    $path = $sync.LogFile
    if ([string]::IsNullOrEmpty($path)) { return }
    for ($i = 0; $i -lt 3; $i++) {
        try {
            [System.IO.File]::AppendAllText($path, $Line + "`r`n", (New-Object System.Text.UTF8Encoding($true)))
            return
        } catch { Start-Sleep -Milliseconds 25 }
    }
}

function Write-WhLog([string]$Message, [string]$Level = 'INFO') {
    if ($script:Silent -eq $true) { return }
    $line = '{0}  {1,-5} {2}' -f (Get-Date -Format 'HH:mm:ss'), $Level, $Message
    try { $sync.Queue.Enqueue($line) } catch { }
    Write-LogFile $line
    if ($sync.Echo -eq $true) { Write-Host $line }
}

# Satiri oldugu gibi kuyruga ekler (zaman damgasi ve seviye olmadan)
function Write-Raw([string]$Line) {
    try { $sync.Queue.Enqueue($Line) } catch { }
    Write-LogFile $Line
    if ($sync.Echo -eq $true) { Write-Host $Line }
}

function Test-JobCancel { return ($null -ne $J -and $J.Cancel -eq $true) }

function Set-JobProgress([int]$Done, [int]$Total, [string]$Label = '') {
    if ($null -eq $J) { return }
    $J.Done = $Done
    $J.Total = $Total
    if ($Label -ne '') { $J.Label = $Label }
}

function Step-JobProgress([string]$Label = '') {
    if ($null -eq $J) { return }
    $J.Done = [int]$J.Done + 1
    if ($Label -ne '') { $J.Label = $Label }
}

$script:Changes = 0
$script:Skipped = 0
$script:Errors  = 0
function Add-Skip([string]$Message) { $script:Skipped++; Write-WhLog $Message 'SKIP' }
function Add-Plan([string]$Message) { $script:Changes++; Write-WhLog $Message 'PLAN' }
function Add-Done([string]$Message) { $script:Changes++; Write-WhLog $Message 'OK' }
function Add-Err([string]$Message)  { $script:Errors++;  Write-WhLog $Message 'ERR' }

# ---------------- kayit defteri (64 bit gorunum, HKCU -> hedef kullanici) ----------------
$script:GuidRx = '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}'

function Get-TargetSid {
    try { if ($null -ne $sync -and -not [string]::IsNullOrEmpty([string]$sync.TargetSid)) { return [string]$sync.TargetSid } } catch { }
    return ''
}

# HKCU\x  ->  HKU\<SID>\x   (arac, oturum acan kullanicidan farkli bir yonetici hesabiyla calisiyorsa)
function Resolve-RegPath([string]$Path) {
    if ($Path.StartsWith('HKCU\', [StringComparison]::OrdinalIgnoreCase)) {
        $sid = Get-TargetSid
        if ($sid -ne '') {
            $rest = $Path.Substring(5)
            if ($rest -match '^Software\\Classes(\\|$)') { return ('HKU\' + $sid + '_Classes' + $rest.Substring(16)) }
            return ('HKU\' + $sid + '\' + $rest)
        }
    }
    return $Path
}

function Get-RegBaseKey([string]$Hive) {
    $h = [Microsoft.Win32.RegistryHive]::CurrentUser
    if ($Hive -eq 'HKLM') { $h = [Microsoft.Win32.RegistryHive]::LocalMachine }
    elseif ($Hive -eq 'HKU') { $h = [Microsoft.Win32.RegistryHive]::Users }
    return [Microsoft.Win32.RegistryKey]::OpenBaseKey($h, [Microsoft.Win32.RegistryView]::Registry64)
}

function Split-RegPath([string]$Path) {
    $p = Resolve-RegPath $Path
    $i = $p.IndexOf('\')
    if ($i -lt 0) { return @($p, '') }
    return @($p.Substring(0, $i), $p.Substring($i + 1))
}

# @{ KeyExists; Exists; Kind; Value } doner
function Get-RegInfo([string]$Path, [string]$Name) {
    $info  = @{ KeyExists = $false; Exists = $false; Kind = $null; Value = $null }
    $parts = Split-RegPath $Path
    $base  = Get-RegBaseKey $parts[0]
    try {
        $key = $base.OpenSubKey($parts[1], $false)
        if ($null -ne $key) {
            $info.KeyExists = $true
            if (@($key.GetValueNames()) -contains $Name) {
                $info.Exists = $true
                $info.Kind   = $key.GetValueKind($Name).ToString()
                $info.Value  = $key.GetValue($Name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            }
            $key.Close()
        }
    } catch { } finally { $base.Close() }
    return $info
}

function Get-RegValue([string]$Path, [string]$Name, $Default = $null) {
    $i = Get-RegInfo $Path $Name
    if ($i.Exists) { return $i.Value }
    return $Default
}

function ConvertTo-RegData([string]$Kind, $Value) {
    switch ($Kind) {
        'DWord' {
            $l = [int64]$Value
            if ($l -gt 2147483647) { $l = $l - 4294967296 }
            return [int]$l
        }
        'QWord'       { return [long]$Value }
        'Binary'      { return , ([byte[]]@($Value)) }
        'MultiString' { return , ([string[]]@($Value)) }
        default       { return [string]$Value }
    }
}

function Set-RegData([string]$Path, [string]$Name, [string]$Kind, $Value) {
    $parts = Split-RegPath $Path
    $base  = Get-RegBaseKey $parts[0]
    try {
        $key = $base.CreateSubKey($parts[1])
        if ($null -eq $key) { throw ('Kayit defteri anahtari acilamadi: ' + $Path) }
        $data = ConvertTo-RegData $Kind $Value
        if ($Kind -eq 'Binary') { $data = [byte[]]$data }
        elseif ($Kind -eq 'MultiString') { $data = [string[]]$data }
        $key.SetValue($Name, $data, [Microsoft.Win32.RegistryValueKind]$Kind)
        $key.Close()
    } finally { $base.Close() }
}

function Remove-RegData([string]$Path, [string]$Name, [bool]$RemoveEmptyKey) {
    $parts = Split-RegPath $Path
    $base  = Get-RegBaseKey $parts[0]
    try {
        $key = $base.OpenSubKey($parts[1], $true)
        if ($null -ne $key) {
            $key.DeleteValue($Name, $false)
            $empty = ($key.ValueCount -eq 0 -and $key.SubKeyCount -eq 0)
            $key.Close()
            if ($RemoveEmptyKey -and $empty) { $base.DeleteSubKey($parts[1], $false) }
        }
    } finally { $base.Close() }
}

function Get-RegSubKeyNames([string]$Path) {
    $parts = Split-RegPath $Path
    $base  = Get-RegBaseKey $parts[0]
    $names = @()
    try {
        $key = $base.OpenSubKey($parts[1], $false)
        if ($null -ne $key) { $names = @($key.GetSubKeyNames()); $key.Close() }
    } catch { } finally { $base.Close() }
    return , $names
}

function Test-RegEqual($Info, [string]$Kind, $Value) {
    if (-not $Info.Exists) { return $false }
    if ($Info.Kind -ne $Kind) { return $false }
    if ($Kind -eq 'Binary' -or $Kind -eq 'MultiString') {
        return ((@($Info.Value) -join ',') -eq (@($Value) -join ','))
    }
    if ($Kind -eq 'DWord') { return ([int]$Info.Value -eq [int](ConvertTo-RegData 'DWord' $Value)) }
    return ([string]$Info.Value -eq [string]$Value)
}

function Format-RegData($Value) {
    if ($null -eq $Value) { return '(yok)' }
    if ($Value -is [byte[]]) { return ((@($Value) | ForEach-Object { $_.ToString('X2') }) -join ' ') }
    if ($Value -is [array]) { return (@($Value) -join ' | ') }
    return [string]$Value
}

# Guvenlik kapisi: bu yollara arac asla yazmaz (Defender, Guvenlik Duvari, UAC, Windows Update, kritik hizmetler)
$script:RegDenyPath = @(
    '^HKLM\\SYSTEM\\CurrentControlSet\\Services\\(WinDefend|WdFilter|WdNisSvc|WdNisDrv|WdBoot|Sense|SecurityHealthService|wscsvc|MpsSvc|BFE|mpssvc|wuauserv|UsoSvc|WaaSMedicSvc|TrustedInstaller|EventLog|RpcSs|RpcEptMapper|DcomLaunch|sppsvc|SamSs|LSM|ProfSvc|gpsvc|Schedule|Winmgmt|CryptSvc|Dhcp|Dnscache)(\\|$)',
    '^HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows Defender(\\|$)',
    '^HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows Advanced Threat Protection(\\|$)',
    '^HKLM\\SOFTWARE\\Policies\\Microsoft\\WindowsFirewall(\\|$)',
    '^HKLM\\SYSTEM\\CurrentControlSet\\Services\\SharedAccess\\Parameters\\FirewallPolicy(\\|$)',
    '^HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsUpdate\\AU$'
)
$script:RegDenyName = @(
    @{ P = '^HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System$'; N = '^(EnableLUA|ConsentPromptBehaviorAdmin|ConsentPromptBehaviorUser|PromptOnSecureDesktop|FilterAdministratorToken|LocalAccountTokenFilterPolicy|EnableVirtualization)$' },
    @{ P = '^HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsUpdate$'; N = '^(DisableWindowsUpdateAccess|SetDisableUXWUAccess|DoNotConnectToWindowsUpdateInternetLocations|WUServer|WUStatusServer|UseWUServer)$' },
    # Microsoft Store kapatilmaz
    @{ P = '^HKLM\\SOFTWARE\\Policies\\Microsoft\\WindowsStore$'; N = '^(RemoveWindowsStore|DisableStoreApps|RequirePrivateStoreOnly)$' },
    # Defender'in kendi (ilke disi) anahtarlari ve Kurcalama Korumasi
    @{ P = '^HKLM\\SOFTWARE\\Microsoft\\Windows Defender(\\Real-Time Protection|\\Features)?$'; N = '^(DisableAntiSpyware|DisableAntiVirus|DisableRealtimeMonitoring|DisableBehaviorMonitoring|DisableOnAccessProtection|DisableIOAVProtection|DisableScanOnRealtimeEnable|TamperProtection|TamperProtectionSource)$' },
    # SmartScreen, Guvenlik Merkezi uyarilari ve Sistem Korumasi
    @{ P = '^HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\System$'; N = '^(EnableSmartScreen|ShellSmartScreenLevel)$' },
    @{ P = '^HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Explorer$'; N = '^SmartScreenEnabled$' },
    @{ P = '^HKLM\\SOFTWARE\\Microsoft\\Security Center$'; N = '^(AntiVirusDisableNotify|AntiSpywareDisableNotify|FirewallDisableNotify|UpdatesDisableNotify)$' },
    @{ P = '^HKLM\\SOFTWARE\\(Policies\\)?Microsoft\\Windows NT\\(CurrentVersion\\)?SystemRestore$'; N = '^(DisableSR|DisableConfig)$' }
)

# Engel nedeni (metin) ya da '' (izinli)
function Test-RegWriteBlocked([string]$Path, [string]$Name) {
    foreach ($rx in $script:RegDenyPath) {
        if ($Path -match $rx) {
            if ($Path -match '^HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsUpdate\\AU$' -and $Name -match '^(NoAutoRebootWithLoggedOnUsers|AlwaysAutoRebootAtScheduledTime|AUPowerManagement)$') { continue }
            return 'guvenlik kapisi'
        }
    }
    foreach ($r in $script:RegDenyName) {
        if ($Path -match $r.P -and $Name -match $r.N) { return 'guvenlik kapisi' }
    }
    return ''
}

# ---------------- .reg dosyasi uretimi (geri alma kiti) ----------------
function ConvertTo-RegEsc([string]$Text) { return ($Text.Replace('\', '\\').Replace('"', '\"')) }

function ConvertTo-HexLine([byte[]]$Bytes, [string]$Prefix) {
    $hex = ((@($Bytes) | ForEach-Object { $_.ToString('x2') }) -join ',')
    return ($Prefix + $hex)
}

function ConvertTo-RegFileValue([string]$Kind, $Value) {
    switch ($Kind) {
        'DWord'  {
            $iv = [int](ConvertTo-RegData 'DWord' $Value)
            return ('dword:' + ([BitConverter]::ToUInt32([BitConverter]::GetBytes($iv), 0)).ToString('x8'))
        }
        'QWord'  { return (ConvertTo-HexLine ([BitConverter]::GetBytes([int64]$Value)) 'hex(b):') }
        'Binary' { return (ConvertTo-HexLine ([byte[]]@($Value)) 'hex:') }
        'ExpandString' { return (ConvertTo-HexLine ([System.Text.Encoding]::Unicode.GetBytes([string]$Value + [char]0)) 'hex(2):') }
        'MultiString' {
            $txt = ((@($Value) | ForEach-Object { [string]$_ }) -join [string][char]0) + [char]0 + [char]0
            return (ConvertTo-HexLine ([System.Text.Encoding]::Unicode.GetBytes($txt)) 'hex(7):')
        }
        default  { return ('"' + (ConvertTo-RegEsc ([string]$Value)) + '"') }
    }
}

function ConvertFrom-BackupText([string]$Kind, [string]$Text) {
    switch ($Kind) {
        'Binary' {
            $bytes = New-Object byte[] ([int]($Text.Length / 2))
            for ($i = 0; $i -lt $bytes.Length; $i++) { $bytes[$i] = [Convert]::ToByte($Text.Substring($i * 2, 2), 16) }
            return , $bytes
        }
        'MultiString' { return , ([string[]]$Text.Split([char]0)) }
        'DWord'       { return [int]$Text }
        'QWord'       { return [long]$Text }
        default       { return $Text }
    }
}

function ConvertTo-BackupText([string]$Kind, $Value) {
    if ($null -eq $Value) { return $null }
    switch ($Kind) {
        'Binary'      { return ((@($Value) | ForEach-Object { ([byte]$_).ToString('X2') }) -join '') }
        'MultiString' { return (@($Value) -join [string][char]0) }
        default       { return [string]$Value }
    }
}

# Gunluk (journal) kayitlarindan, eski degerleri geri yukleyen bir .reg dosyasi yazar
function Write-UndoRegFile($Items, [string]$File) {
    $seen = @{}
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("Windows Registry Editor Version 5.00`r`n`r`n")
    [void]$sb.Append("; Multimizer geri alma dosyasi. Cift tiklayarak degisiklikleri eski haline dondurebilirsiniz.`r`n`r`n")
    $count = 0
    $regItems = @(@($Items) | Where-Object { $_.T -eq 'Reg' })
    $grouped = $regItems | Group-Object { [string]$_.Path }
    foreach ($g in $grouped) {
        $hive = $g.Name
        $hive = $hive -replace '^HKLM\\', 'HKEY_LOCAL_MACHINE\'
        $hive = $hive -replace '^HKCU\\', 'HKEY_CURRENT_USER\'
        $hive = $hive -replace '^HKU\\', 'HKEY_USERS\'
        $lines = New-Object System.Collections.ArrayList
        foreach ($it in $g.Group) {
            $key = [string]$it.Path + '|' + [string]$it.Name
            if ($seen.ContainsKey($key)) { continue }
            $seen[$key] = $true
            $nm = '"' + (ConvertTo-RegEsc ([string]$it.Name)) + '"'
            if ([string]$it.Name -eq '') { $nm = '@' }
            if ($it.Existed) {
                $val = ConvertFrom-BackupText ([string]$it.Kind) ([string]$it.Data)
                [void]$lines.Add($nm + '=' + (ConvertTo-RegFileValue ([string]$it.Kind) $val))
            } else {
                [void]$lines.Add($nm + '=-')
            }
            $count++
        }
        if ($lines.Count -gt 0) {
            [void]$sb.Append('[' + $hive + "]`r`n")
            foreach ($l in $lines) { [void]$sb.Append($l + "`r`n") }
            [void]$sb.Append("`r`n")
        }
    }
    if ($count -gt 0) {
        [System.IO.File]::WriteAllText($File, $sb.ToString(), [System.Text.Encoding]::Unicode)
    }
    return $count
}

# ---------------- gunluk (journal): yazmadan ONCE kaydedilir ----------------
$script:JFile  = ''
$script:JItems = New-Object System.Collections.ArrayList

function Open-Journal([string]$File) {
    $script:JFile = $File
    $script:JItems = New-Object System.Collections.ArrayList
    $hdr = [ordered]@{
        Tool = 'Multimizer'; Version = [string]$sync.Version; Format = 2
        Created = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss'); Computer = $env:COMPUTERNAME
        User = [string]$sync.RunUser; Sid = (Get-TargetSid)
    }
    $line = ConvertTo-Json -InputObject $hdr -Compress
    [System.IO.File]::WriteAllText($File, $line + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
}

function Add-Journal($Item) {
    [void]$script:JItems.Add($Item)
    if ($script:JFile -ne '') {
        $line = ConvertTo-Json -InputObject $Item -Compress -Depth 5
        [System.IO.File]::AppendAllText($script:JFile, $line + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
    }
}

function Close-Journal {
    if ($script:JFile -eq '') { return }
    if ($script:JItems.Count -eq 0) {
        try { Remove-Item -LiteralPath $script:JFile -Force -ErrorAction SilentlyContinue } catch { }
        $script:JFile = ''
        return
    }
    try {
        $regFile = [System.IO.Path]::ChangeExtension($script:JFile, '.geri.reg')
        $n = Write-UndoRegFile $script:JItems.ToArray() $regFile
        if ($n -gt 0) { Write-WhLog ('Geri alma dosyasi yazildi (cift tiklayarak da donebilirsiniz): ' + $regFile) 'INFO' }
    } catch { Write-WhLog ('Geri alma .reg dosyasi yazilamadi: ' + $_.Exception.Message) 'WARN' }
    $script:JFile = ''
}

# Hem yeni (.jsonl) hem eski (v4 .json) yedek bicimini okur
function Read-Journal([string]$File) {
    $res = @{ Header = $null; Items = @() }
    $text = [System.IO.File]::ReadAllText($File)
    if ($File.EndsWith('.jsonl', [StringComparison]::OrdinalIgnoreCase)) {
        $items = New-Object System.Collections.ArrayList
        $first = $true
        foreach ($ln in ($text -split "`r?`n")) {
            if ([string]::IsNullOrWhiteSpace($ln)) { continue }
            try { $o = ConvertFrom-Json -InputObject $ln } catch { continue }
            if ($first) { $res.Header = $o; $first = $false; continue }
            [void]$items.Add($o)
        }
        $res.Items = $items.ToArray()
    } else {
        $o = ConvertFrom-Json -InputObject $text
        $res.Header = $o
        $res.Items = @($o.Items)
    }
    return $res
}

# ---------------- sistem tanima ----------------
# Acilis olcumu: Get-SystemProfile adimlarinin baslangictan gecen sureleri (ms); yalnizca ilk cagri olculur
$script:ProfSw = $null
$script:ProfMs = @{}
function Add-ProfMark([string]$Name) {
    try {
        if ($null -eq $script:ProfSw) { $script:ProfSw = [System.Diagnostics.Stopwatch]::StartNew() }
        if (-not $script:ProfMs.ContainsKey($Name)) { $script:ProfMs[$Name] = [int]$script:ProfSw.ElapsedMilliseconds }
    } catch { }
}

# Sistem diski turu/modeli: Storage modulu ilk cagrida yavas yuklenir (1-4 sn); profilin geri kalaniyla paralel bir calisma alaninda yurutulur
$script:DiskProbeBlock = {
    param([string]$Drive)
    $r = @{ Found = $false; Type = ''; Model = ''; Bus = '' }
    try {
        $part = Get-Partition -DriveLetter $Drive -ErrorAction Stop | Select-Object -First 1
        $pd = Get-PhysicalDisk -ErrorAction Stop | Where-Object { [string]$_.DeviceId -eq [string]$part.DiskNumber } | Select-Object -First 1
        if ($null -ne $pd) {
            $mt  = [string]$pd.MediaType
            $bus = [string]$pd.BusType
            $spin = -1
            if ($null -ne $pd.SpindleSpeed) { $spin = [double]$pd.SpindleSpeed }
            if ($mt -eq 'SSD' -or $mt -eq '4' -or $mt -eq 'SCM' -or $mt -eq '5' -or $bus -eq 'NVMe' -or $bus -eq '17') { $r.Type = 'SSD' }
            elseif ($mt -eq 'HDD' -or $mt -eq '3') { $r.Type = 'HDD' }
            elseif ($spin -eq 0) { $r.Type = 'SSD' }
            elseif ($spin -gt 0 -and $spin -lt 20000) { $r.Type = 'HDD' }
            $r.Model = [string]$pd.FriendlyName
            $r.Bus = $bus
            $r.Found = $true
        }
    } catch { }
    return $r
}

function Start-DiskProbe([string]$Drive) {
    $o = @{ Ps = $null; Ar = $null; Drive = $Drive }
    $ps = $null
    try {
        $ps = [powershell]::Create()
        [void]$ps.AddScript($script:DiskProbeBlock.ToString()).AddArgument($Drive)
        $o.Ar = $ps.BeginInvoke()
        $o.Ps = $ps
    } catch {
        try { if ($null -ne $ps) { $ps.Dispose() } } catch { }
        $o.Ps = $null
        $o.Ar = $null
    }
    return $o
}

# Paralel sorgunun sonucunu alir; baslatilamamissa ayni sorguyu burada calistirir. Zaman asiminda $null doner (disk turu bos kalir).
function Complete-DiskProbe($Probe) {
    $res = $null
    try {
        if ($null -ne $Probe -and $null -ne $Probe.Ps) {
            if ($Probe.Ar.AsyncWaitHandle.WaitOne(25000)) {
                try {
                    $out = @($Probe.Ps.EndInvoke($Probe.Ar))
                    if ($out.Count -gt 0) {
                        $it = $out[0]
                        if ($null -ne $it) {
                            $bo = $it.PSObject.BaseObject
                            if ($bo -is [hashtable]) { $res = $bo }
                        }
                    }
                } finally { try { $Probe.Ps.Dispose() } catch { } }
            } else {
                try { [void]$Probe.Ps.BeginStop($null, $null) } catch { }
            }
        } elseif ($null -ne $Probe -and [string]$Probe.Drive -ne '') {
            $res = & $script:DiskProbeBlock ([string]$Probe.Drive)
        }
    } catch { }
    return $res
}

function Get-SystemProfile {
    Add-ProfMark 'bas'
    $sd0 = [string]$env:SystemDrive
    if ($sd0 -eq '') { $sd0 = 'C:' }
    $diskProbe = Start-DiskProbe ($sd0.TrimEnd(':'))
    $p = @{
        Build = 0; UBR = 0; IsWin11 = $false; WinMajor = '10'; Version = ''; EditionId = ''
        Edition = ''; OsName = 'Windows'; IsLtsc = $false; FullTelemetryControl = $false
        RamGB = 0; CpuName = '?'; Cores = 0; Threads = 0; Arch = ''; Model = ''; Manufacturer = ''
        ConsoleUser = ''; RunUser = ''; UserMismatch = $false; IsVM = $false; IsLaptop = $false
        SysDrive = 'C'; DiskType = 'Unknown'; DiskModel = ''; BusType = ''; FreeGB = 0; SizeGB = 0
        Hostname = $env:COMPUTERNAME; JoinType = 'Workgroup'; Domain = ''; MdmManaged = $false; IsManaged = $false
        InstallDate = ''; TargetSid = ''
    }

    try {
        $cv = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
        $b = 0
        [void][int]::TryParse([string]$cv.CurrentBuildNumber, [ref]$b)
        $p.Build = $b
        $p.UBR = $cv.UBR
        $p.IsWin11 = ($b -ge 22000)
        if ($p.IsWin11) { $p.WinMajor = '11' }
        $v = [string]$cv.DisplayVersion
        if ([string]::IsNullOrEmpty($v)) { $v = [string]$cv.ReleaseId }
        $p.Version = $v
        $p.EditionId = [string]$cv.EditionID
        try { $p.InstallDate = ([DateTime]'1970-01-01').AddSeconds([double]$cv.InstallDate).ToString('yyyy-MM-dd') } catch { }
    } catch { }

    Add-ProfMark 'kayit'
    $ed = $p.EditionId
    if ($ed -match '^Core') { $ed = 'Home' }
    elseif ($ed -match '^Professional') { $ed = 'Pro' }
    elseif ($ed -match '^EnterpriseS') { $ed = 'Enterprise LTSC' }
    elseif ($ed -match '^Enterprise') { $ed = 'Enterprise' }
    elseif ($ed -match '^Education') { $ed = 'Education' }
    $p.Edition = $ed
    $p.OsName = ('Windows ' + $p.WinMajor + ' ' + $ed).Trim()
    $p.IsLtsc = ($p.EditionId -match 'EnterpriseS')
    $p.FullTelemetryControl = ($p.EditionId -match 'Enterprise|Education|Server|IoT')

    $cs = $null
    try {
        $cs  = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
        $os  = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $cpu = Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop | Select-Object -First 1
        $p.RamGB   = [math]::Round(([double]$cs.TotalPhysicalMemory) / 1GB, 1)
        $p.CpuName = (([string]$cpu.Name).Trim() -replace '\s+', ' ')
        $p.Cores   = [int]$cpu.NumberOfCores
        $p.Threads = [int]$cpu.NumberOfLogicalProcessors
        $p.Arch    = [string]$os.OSArchitecture
        $p.Manufacturer = ([string]$cs.Manufacturer).Trim()
        $p.Model   = ([string]$cs.Manufacturer + ' ' + [string]$cs.Model).Trim()
        $p.ConsoleUser = [string]$cs.UserName
        $p.IsVM = ($p.Model -match 'Virtual|VMware|VirtualBox|KVM|QEMU|Parallels')
        if ($cs.PartOfDomain -eq $true) { $p.JoinType = 'Domain'; $p.Domain = [string]$cs.Domain }
    } catch { }

    Add-ProfMark 'cim'
    try {
        $bat = @(Get-CimInstance -ClassName Win32_Battery -ErrorAction Stop)
        $p.IsLaptop = ($bat.Count -gt 0)
    } catch { }
    if (-not $p.IsLaptop -and $null -ne $cs -and [int]$cs.PCSystemType -eq 2) { $p.IsLaptop = $true }

    Add-ProfMark 'batarya'
    # Azure AD / Intune (kayit defteri ile, hizli)
    try {
        if ((Get-RegSubKeyNames 'HKLM\SYSTEM\CurrentControlSet\Control\CloudDomainJoin\JoinInfo').Count -gt 0) {
            if ($p.JoinType -eq 'Workgroup') { $p.JoinType = 'AzureAD' } else { $p.JoinType = $p.JoinType + '+AzureAD' }
        }
        foreach ($en in (Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Enrollments')) {
            $prov = [string](Get-RegValue ('HKLM\SOFTWARE\Microsoft\Enrollments\' + $en) 'ProviderID' '')
            if ($prov -ne '' -and $prov -ne 'Local_Management') { $p.MdmManaged = $true }
        }
    } catch { }
    $p.IsManaged = ($p.JoinType -ne 'Workgroup' -or $p.MdmManaged)

    # Oturum acan kullanici ile araci calistiran hesap ayni mi?
    $p.RunUser = [Security.Principal.WindowsIdentity]::GetCurrent().Name
    $p.UserMismatch = (-not [string]::IsNullOrEmpty($p.ConsoleUser) -and ($p.ConsoleUser -ne $p.RunUser))
    if ($p.UserMismatch) {
        try {
            $nt = New-Object System.Security.Principal.NTAccount($p.ConsoleUser)
            $sid = ($nt.Translate([System.Security.Principal.SecurityIdentifier])).Value
            $hiveOk = (Get-RegSubKeyNames 'HKU') -contains $sid
            if ($hiveOk) { $p.TargetSid = $sid }
        } catch { }
    }

    Add-ProfMark 'yonetim'
    $p.SysDrive = $env:SystemDrive.TrimEnd(':')
    # Bos/toplam alan: .NET DriveInfo aninda yanit verir; Storage modulu (Get-Volume) yalnizca yedek yol
    $volOk = $false
    try {
        $di = New-Object System.IO.DriveInfo($p.SysDrive)
        if ($di.IsReady -and [double]$di.TotalSize -gt 0) {
            $p.FreeGB = [math]::Round(([double]$di.TotalFreeSpace) / 1GB, 1)
            $p.SizeGB = [math]::Round(([double]$di.TotalSize) / 1GB, 1)
            $volOk = $true
        }
    } catch { }
    if (-not $volOk) {
        try {
            $vol = Get-Volume -DriveLetter $p.SysDrive -ErrorAction Stop
            $p.FreeGB = [math]::Round(([double]$vol.SizeRemaining) / 1GB, 1)
            $p.SizeGB = [math]::Round(([double]$vol.Size) / 1GB, 1)
        } catch {
            try {
                $drv = Get-PSDrive -Name $p.SysDrive -ErrorAction Stop
                $p.FreeGB = [math]::Round(([double]$drv.Free) / 1GB, 1)
                $p.SizeGB = [math]::Round(([double]$drv.Used + [double]$drv.Free) / 1GB, 1)
            } catch { }
        }
    }
    Add-ProfMark 'hacim'
    # Disk turu/modeli: profil adimlariyla paralel baslatilan sorgunun sonucu
    try {
        $dr = Complete-DiskProbe $diskProbe
        if ($null -ne $dr -and $dr.Found -eq $true) {
            if ([string]$dr.Type -ne '') { $p.DiskType = [string]$dr.Type }
            $p.DiskModel = [string]$dr.Model
            $p.BusType = [string]$dr.Bus
        }
    } catch { }
    Add-ProfMark 'disk'

    return $p
}

# Hedef kullanicinin profil klasorleri (HKCU yonlendirmesiyle uyumlu)
function Get-TargetProfile {
    $r = @{ Home = $env:USERPROFILE; LocalAppData = $env:LOCALAPPDATA; AppData = $env:APPDATA; Temp = [System.IO.Path]::GetTempPath().TrimEnd('\') }
    $sid = Get-TargetSid
    if ($sid -ne '') {
        $h = [string](Get-RegValue ('HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\' + $sid) 'ProfileImagePath' '')
        if ($h -ne '') {
            $h = [Environment]::ExpandEnvironmentVariables($h)
            $r.Home = $h
            $r.LocalAppData = Join-Path $h 'AppData\Local'
            $r.AppData = Join-Path $h 'AppData\Roaming'
            $r.Temp = Join-Path $h 'AppData\Local\Temp'
        }
    }
    return $r
}

# ==================================================================
#  CEKIRDEK 2 - islem (op) motoru: kayit defteri, hizmet, gorev, uygulama, Defender, DNS, ozellik, islev
#  Her islem: Onizle (hicbir sey degistirmez) veya Uygula (once gunluge yazar, sonra degistirir)
# ==================================================================
$script:Preview = $false
$script:Provisioned = $null
$script:FreedBytes = 0.0
$script:StartMap = @{ 'Auto' = 2; 'Automatic' = 2; 'Delayed' = 2; 'Manual' = 3; 'Disabled' = 4 }
$script:StartText = @{ 2 = 'Otomatik'; 3 = 'El ile'; 4 = ('Devre d' + [char]0x0131 + [char]0x015F + [char]0x0131) }

# ---------------- kayit defteri islemi ----------------
function Invoke-RegOp($Op) {
    $path = Resolve-RegPath ([string]$Op.Path)
    $name = [string]$Op.Name
    $label = $path + '\' + $name
    if ((Test-RegWriteBlocked $path $name) -ne '') { Add-Skip (('G' + [char]0x00FC + 'venlik kap' + [char]0x0131 + 's' + [char]0x0131 + ' nedeniyle atland' + [char]0x0131 + ': ') + $label); return }
    $info = Get-RegInfo $path $name
    if ($Op.Del -eq $true) {
        if (-not $info.Exists) { Add-Skip ('Zaten yok: ' + $label); return }
        if ($script:Preview) {
            if (Test-RegDenied $label) { Add-Skip (Get-RegDeniedText $label); return }
            Add-Plan ($label + ' : ' + (Format-RegData $info.Value) + ' -> (silinecek)'); return
        }
        Add-Journal @{ T = 'Reg'; Path = $path; Name = $name; KeyExisted = $info.KeyExists; Existed = $true; Kind = $info.Kind; Data = (ConvertTo-BackupText $info.Kind $info.Value) }
        try { Remove-RegData $path $name $false }
        catch {
            if (-not (Test-AccessDeniedEx $_.Exception)) { throw }
            Remove-LastJournalItem
            if (Test-ProcAdmin) { Register-RegDenied $label; Add-Skip (Get-RegDeniedText $label) } else { Add-Skip (Get-RegNoAdminText $label) }
            return
        }
        Clear-RegDenied $label
        Add-Done ($label + ' silindi')
        return
    }
    $kind = [string]$Op.Kind
    if ([string]::IsNullOrEmpty($kind)) { $kind = 'DWord' }
    $newText = Format-RegData (ConvertTo-RegData $kind $Op.Value)
    if (Test-RegEqual $info $kind $Op.Value) { Add-Skip ('Zaten uygun: ' + $label); return }
    if ($script:Preview) {
        if (Test-RegDenied $label) { Add-Skip (Get-RegDeniedText $label); return }
        Add-Plan ('{0} : {1} -> {2}' -f $label, (Format-RegData $info.Value), $newText); return
    }
    Add-Journal @{ T = 'Reg'; Path = $path; Name = $name; KeyExisted = $info.KeyExists; Existed = $info.Exists; Kind = $info.Kind; Data = (ConvertTo-BackupText $info.Kind $info.Value) }
    try { Set-RegData $path $name $kind $Op.Value }
    catch {
        if (-not (Test-AccessDeniedEx $_.Exception)) { throw }
        Remove-LastJournalItem
        if (Test-ProcAdmin) { Register-RegDenied $label; Add-Skip (Get-RegDeniedText $label) } else { Add-Skip (Get-RegNoAdminText $label) }
        return
    }
    Clear-RegDenied $label
    Add-Done ('{0} = {1}' -f $label, $newText)
}

# ---------------- hizmetler ----------------
# Kullanici basina olusan hizmetler (CDPUserSvc_1a2b3 gibi) icin sablon adini bulur
function Get-SvcTemplateName([string]$Name) {
    if ($Name -match '^(.+)_[0-9a-fA-F]{4,8}$') {
        $t = $Matches[1]
        if ((Get-RegInfo ('HKLM\SYSTEM\CurrentControlSet\Services\' + $t) 'Start').Exists) { return $t }
    }
    return $Name
}

function Get-SvcStartInfo([string]$Name) {
    $k = 'HKLM\SYSTEM\CurrentControlSet\Services\' + (Get-SvcTemplateName $Name)
    $s = Get-RegInfo $k 'Start'
    $d = Get-RegInfo $k 'DelayedAutostart'
    $t = Get-RegInfo $k 'Type'
    $start = $null
    if ($s.Exists) { $start = [int]$s.Value }
    $type = 0
    if ($t.Exists) { $type = [int]$t.Value }
    return @{ Start = $start; Delayed = ($d.Exists -and [int]$d.Value -eq 1); Type = $type; IsDriver = (($type -band 0x0B) -ne 0); IsUserSvc = (($type -band 0xC0) -ne 0) }
}

function Set-SvcStart([string]$Name, [int]$Start, [bool]$Delayed) {
    if ($Start -le 1) { return }
    $tpl = Get-SvcTemplateName $Name
    if ($tpl -ne $Name) {
        Set-RegData ('HKLM\SYSTEM\CurrentControlSet\Services\' + $tpl) 'Start' 'DWord' $Start
        return
    }
    $mode = 'demand'
    if ($Start -eq 2) { $mode = 'auto'; if ($Delayed) { $mode = 'delayed-auto' } }
    elseif ($Start -eq 4) { $mode = 'disabled' }
    $out = & sc.exe config $Name start= $mode 2>&1
    if ($LASTEXITCODE -ne 0) { throw ('sc.exe config ' + $Name + ' start= ' + $mode + ' : ' + (($out | Out-String).Trim())) }
}

function Test-SvcLocked([string]$Name) {
    $n = Get-SvcTemplateName $Name
    foreach ($rx in $script:SvcLockList) { if ($n -match $rx) { return $true } }
    return $false
}

function Invoke-SvcOp($Op) {
    $name = [string]$Op.Name
    if (Test-SvcLocked $name) { Add-Skip (('Korumal' + [char]0x0131 + ' hizmet, dokunulmaz: ') + $name); return }
    $tpl = Get-SvcTemplateName $name
    $svc = Get-Service -Name $name -ErrorAction SilentlyContinue
    $cur = Get-SvcStartInfo $name
    $isTemplateOnly = ($null -eq $svc -and $null -ne $cur.Start -and $cur.IsUserSvc)
    if ($null -eq $svc -and -not $isTemplateOnly) { Add-Skip ('Hizmet bu sistemde yok: ' + $name); return }
    if ($cur.IsDriver) { Add-Skip (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' hizmetlerine dokunulmaz: ') + $name); return }
    if ($null -ne $cur.Start -and $cur.Start -le 1) { Add-Skip (('Boot/sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ', dokunulmaz: ') + $name); return }
    $target = [int]$script:StartMap[[string]$Op.Start]
    $wantDelayed = ([string]$Op.Start -eq 'Delayed')
    $running = ($null -ne $svc -and $svc.Status -eq 'Running')
    $sameStart = ($cur.Start -eq $target -and ($target -ne 2 -or $cur.Delayed -eq $wantDelayed))
    if ($sameStart -and -not ($target -eq 4 -and $running)) { Add-Skip ('Hizmet zaten uygun: ' + $name); return }
    if ($target -eq 4 -and $null -ne $svc) {
        $dep = @($svc.DependentServices | Where-Object { $_.Status -eq 'Running' })
        if ($dep.Count -gt 0) {
            Add-Skip (('Hizmete ba' + [char]0x011F + 'l' + [char]0x0131 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'an hizmet var, atland' + [char]0x0131 + ': ') + $name + ' <- ' + (($dep | ForEach-Object { $_.Name }) -join ', '))
            return
        }
    }
    $fromTxt = [string]$cur.Start
    if ($null -ne $cur.Start -and $script:StartText.ContainsKey([int]$cur.Start)) { $fromTxt = $script:StartText[[int]$cur.Start] }
    if ($script:Preview) { Add-Plan ('Hizmet {0}: {1} -> {2}' -f $name, $fromTxt, $Op.Start); return }
    Add-Journal @{ T = 'Svc'; Name = $name; Start = $cur.Start; Delayed = $cur.Delayed; WasRunning = $running }
    if ($target -eq 4) {
        if ($null -ne $svc -and $running) { Stop-Service -Name $name -Force -NoWait -ErrorAction SilentlyContinue }
        if ($isTemplateOnly -or $tpl -ne $name) {
            foreach ($inst in @(Get-Service -Name ($tpl + '_*') -ErrorAction SilentlyContinue)) { Stop-Service -InputObject $inst -Force -NoWait -ErrorAction SilentlyContinue }
        }
    }
    Set-SvcStart $name $target $wantDelayed
    Add-Done ('Hizmet {0} -> {1}' -f $name, $Op.Start)
}

# ---------------- zamanlanmis gorevler ----------------
function Invoke-TaskOp($Op) {
    $label = [string]$Op.Path + [string]$Op.Name
    $t = Get-TaskCached ([string]$Op.Path) ([string]$Op.Name)
    if ($null -eq $t) { Add-Skip (('G' + [char]0x00F6 + 'rev bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde yok: ') + $label); return }
    $wantEnable = ([string]$Op.Action -eq 'Enable')
    $isDisabled = ([string]$t.State -eq 'Disabled')
    if ($wantEnable -and -not $isDisabled) { Add-Skip (('G' + [char]0x00F6 + 'rev zaten a' + [char]0x00E7 + [char]0x0131 + 'k: ') + $label); return }
    if (-not $wantEnable -and $isDisabled) { Add-Skip (('G' + [char]0x00F6 + 'rev zaten kapal' + [char]0x0131 + ': ') + $label); return }
    if ($script:Preview) {
        if ($wantEnable) { Add-Plan (('G' + [char]0x00F6 + 'rev a' + [char]0x00E7 + [char]0x0131 + 'lacak: ') + $label) } else { Add-Plan (('G' + [char]0x00F6 + 'rev kapat' + [char]0x0131 + 'lacak: ') + $label) }
        return
    }
    Add-Journal @{ T = 'Task'; Path = [string]$Op.Path; Name = [string]$Op.Name; WasDisabled = $isDisabled }
    if ($wantEnable) { Enable-ScheduledTask -TaskPath $Op.Path -TaskName $Op.Name -ErrorAction Stop | Out-Null; Add-Done (('G' + [char]0x00F6 + 'rev a' + [char]0x00E7 + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $label) }
    else { Disable-ScheduledTask -TaskPath $Op.Path -TaskName $Op.Name -ErrorAction Stop | Out-Null; Add-Done (('G' + [char]0x00F6 + 'rev kapat' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $label) }
}

# ---------------- Magaza uygulamalari ----------------
# Op.Name bir ad ya da * iceren desen olabilir. Koruma denetimi her gercek paket adina ayri uygulanir.
# Yonetici degilse "Get-AppxPackage -AllUsers" sonlandirici hata verir; bu durumda yalniz gecerli kullanicinin paketleri okunur.
function Get-AppxSafe([string]$Name = '') {
    $pk = @()
    try {
        if ($Name -ne '') { $pk = @(Get-AppxPackage -AllUsers -Name $Name -ErrorAction Stop) } else { $pk = @(Get-AppxPackage -AllUsers -ErrorAction Stop) }
    } catch { $pk = @() }
    if ($pk.Count -eq 0) {
        try {
            if ($Name -ne '') { $pk = @(Get-AppxPackage -Name $Name -ErrorAction Stop) } else { $pk = @(Get-AppxPackage -ErrorAction Stop) }
        } catch { $pk = @() }
    }
    return $pk
}

# Kaldirilan magaza uygulamasini paket klasorundeki AppxManifest.xml ile yeniden kaydeder (dosyalar duruyorsa). Donus: en az biri geri geldiyse $true
function Restore-AppxItem($It) {
    $ok = $false
    foreach ($loc in @($It.Locs)) {
        $mf = Join-Path ([string]$loc) 'AppxManifest.xml'
        if ([string]$loc -eq '' -or -not (Test-Path -LiteralPath $mf)) { continue }
        try {
            Add-AppxPackage -Register $mf -DisableDevelopmentMode -ErrorAction Stop
            Add-Done (('Uygulama geri kaydedildi: ') + [string]$It.Name)
            $ok = $true
        } catch { Write-WhLog (('Uygulama geri kaydedilemedi (') + [string]$It.Name + '): ' + $_.Exception.Message) 'WARN' }
    }
    return $ok
}

# Paket hala bir kullanicida kurulu mu? Kaldirma hata verse de paket cogu zaman gitmistir. Okunamazsa "kurulu" sayilir.
function Test-AppxStillThere([string]$Name, [string]$Full) {
    $all = $null
    try { $all = @(Get-AppxPackage -AllUsers -Name $Name -ErrorAction Stop) } catch { $all = $null }
    if ($null -eq $all) {
        try { $all = @(Get-AppxPackage -Name $Name -ErrorAction Stop) } catch { return $true }
    }
    foreach ($x in $all) {
        if ([string]$x.PackageFullName -ne $Full) { continue }
        $pui = @($x.PackageUserInformation | Where-Object { $null -ne $_ })
        if ($pui.Count -eq 0) { return $true }
        foreach ($u in $pui) { if ([string]$u.InstallState -eq 'Installed') { return $true } }
    }
    return $false
}

# Hata "yol bulunamadi" (0x80070003) mi? DISM ve Appx hatalari ic ice gelebilir; dile bagli ileti yerine kod denetlenir.
function Test-PathNotFoundError($Ex) {
    $e = $Ex
    while ($null -ne $e) {
        if ([int]$e.HResult -eq -2147024893) { return $true }
        if ([string]$e.Message -match '0x80070003') { return $true }
        $e = $e.InnerException
    }
    return $false
}

function Invoke-AppxOp($Op) {
    $name = [string]$Op.Name
    if ($null -eq $script:Provisioned) { try { $script:Provisioned = @(Get-AppxProvisionedPackage -Online -ErrorAction Stop) } catch { $script:Provisioned = @() } }
    $pkgs = @(Get-AppxSafe $name)
    $prov = @($script:Provisioned | Where-Object { $_.DisplayName -like $name })
    $keepP = @($pkgs | Where-Object { -not (Test-ProtectedApp ([string]$_.Name)) -and $_.NonRemovable -ne $true })
    $keepV = @($prov | Where-Object { -not (Test-ProtectedApp ([string]$_.DisplayName)) })
    if ($keepP.Count -eq 0 -and $keepV.Count -eq 0) {
        if ($pkgs.Count -gt 0 -or $prov.Count -gt 0) { Add-Skip (('Korumal' + [char]0x0131 + ' veya sistem uygulamas' + [char]0x0131 + ', dokunulmaz: ') + $name) }
        else { Add-Skip (('Uygulama y' + [char]0x00FC + 'kl' + [char]0x00FC + ' de' + [char]0x011F + 'il: ') + $name) }
        return
    }
    if ($script:Preview) { Add-Plan (('Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak uygulama: ') + $name); return }
    $locs = @($keepP | ForEach-Object { [string]$_.InstallLocation } | Where-Object { $_ -ne '' } | Sort-Object -Unique)
    $fulls = @($keepP | ForEach-Object { [string]$_.PackageFullName })
    Add-Journal @{ T = 'Appx'; Name = $name; Locs = $locs; Full = $fulls }
    $fail = New-Object System.Collections.ArrayList
    foreach ($p in $keepP) {
        $full = [string]$p.PackageFullName
        $err = ''
        try { Remove-AppxPackage -Package $full -AllUsers -ErrorAction Stop }
        catch {
            $err = $_.Exception.Message
            try { Remove-AppxPackage -Package $full -ErrorAction Stop; $err = '' } catch { $err = $_.Exception.Message }
        }
        if ($err -ne '' -and (Test-AppxStillThere ([string]$p.Name) $full)) { [void]$fail.Add($full + ': ' + $err) }
    }
    foreach ($pp in $keepV) {
        $pn = [string]$pp.PackageName
        try { Remove-AppxProvisionedPackage -Online -PackageName $pn -ErrorAction Stop | Out-Null }
        catch {
            if (Test-PathNotFoundError $_.Exception) { Write-WhLog (('Yeni hesaplara otomatik kurulum kayd' + [char]0x0131 + 'n' + [char]0x0131 + 'n dosyalar' + [char]0x0131 + ' zaten silinmi' + [char]0x015F + '; uygulama yeni hesaplara kurulmaz: ') + $pn) 'INFO' }
            else { Write-WhLog (('Uygulaman' + [char]0x0131 + 'n yeni hesaplara otomatik kurulum kayd' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (') + $pn + '): ' + $_.Exception.Message) 'WARN' }
        }
    }
    if ($keepV.Count -gt 0 -and $null -ne $script:Provisioned) {
        $gone = @($keepV | ForEach-Object { [string]$_.PackageName })
        $script:Provisioned = @($script:Provisioned | Where-Object { $gone -notcontains [string]$_.PackageName })
    }
    if ($fail.Count -gt 0) { throw (('Uygulama kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (') + $name + '): ' + ($fail.ToArray() -join '; ')) }
    Add-Done (('Uygulama kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $name)
}

# ---------------- Defender tercihleri (Set-MpPreference) ----------------
# Toplu durum olcumu partisi: icindeki onizlemelerde pahali okumalar (Defender tercihleri, gorev listesi) bir kez yapilir.
# Parti disinda ve gercek uygulamada her okuma tazedir. Ic ice cagrilabilir (derinlik sayaci).
$script:StateBatch = $null
function Start-StateBatch {
    if ($null -eq $script:StateBatch) { $script:StateBatch = @{ Depth = 0; Mp = $null; Tasks = $null; TasksOk = $false; Caps = $null; CapsFailed = $false } }
    $script:StateBatch.Depth = [int]$script:StateBatch.Depth + 1
}
function Stop-StateBatch {
    if ($null -eq $script:StateBatch) { return }
    $script:StateBatch.Depth = [int]$script:StateBatch.Depth - 1
    if ([int]$script:StateBatch.Depth -le 0) { $script:StateBatch = $null }
}
function Get-MpPrefCached {
    $b = $script:StateBatch
    if ($null -ne $b -and $script:Preview) {
        if ($null -eq $b.Mp) { $b.Mp = Get-MpPreference -ErrorAction Stop }
        return $b.Mp
    }
    return (Get-MpPreference -ErrorAction Stop)
}
function Get-TaskCached([string]$Path, [string]$Name) {
    $b = $script:StateBatch
    if ($null -ne $b -and $script:Preview) {
        if ($null -eq $b.Tasks) {
            $h = @{}
            try { foreach ($t in @(Get-ScheduledTask -ErrorAction Stop)) { $h[([string]$t.TaskPath + [string]$t.TaskName).ToLowerInvariant()] = $t }; $b.TasksOk = $true } catch { $b.TasksOk = $false }
            $b.Tasks = $h
        }
        $k = ($Path + $Name).ToLowerInvariant()
        if ($b.Tasks.ContainsKey($k)) { return $b.Tasks[$k] }
        # tam liste yonetici olarak okunduysa listede olmayan gorev yoktur; degilse tek tek sorulur
        if ([bool]$b.TasksOk -and [bool]$script:IsAdmin) { return $null }
    }
    return (Get-ScheduledTask -TaskPath $Path -TaskName $Name -ErrorAction SilentlyContinue)
}

function Invoke-MpOp($Op) {
    $name = [string]$Op.Name
    $want = $Op.Value
    $cur = $null
    try { $cur = (Get-MpPrefCached).$name } catch { $script:OpUnreadable = $true; Add-Skip (('Defender tercihi okunamad' + [char]0x0131 + ' (ba' + [char]0x015F + 'ka bir antivir' + [char]0x00FC + 's etkin olabilir): ') + $name); return }
    $curS = [string]$cur
    if ($cur -is [bool]) { $curS = ([string]$cur).ToLowerInvariant() }
    $wantS = [string]$want
    if ($want -is [bool]) { $wantS = ([string]$want).ToLowerInvariant() }
    if ($curS -eq $wantS) { Add-Skip ('Defender zaten uygun: ' + $name + ' = ' + $wantS); return }
    if ($script:Preview) { Add-Plan ('Defender {0}: {1} -> {2}' -f $name, $curS, $wantS); return }
    Add-Journal @{ T = 'Mp'; Name = $name; Prev = $curS; IsBool = ($cur -is [bool]) }
    $splat = @{}
    $splat[$name] = $want
    try { Set-MpPreference @splat -ErrorAction Stop }
    catch { throw (('Defender ayar' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'medi (Kurcalama Korumas' + [char]0x0131 + ' a' + [char]0x00E7 + [char]0x0131 + 'k olabilir): ') + $_.Exception.Message) }
    Add-Done ('Defender {0} = {1}' -f $name, $wantS)
}

# ---------------- DNS ----------------
function Get-AdapterDnsState($Adapter) {
    $guid = [string]$Adapter.InterfaceGuid
    $ns = [string](Get-RegValue ('HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\' + $guid) 'NameServer' '')
    $list = @()
    if ($ns.Trim() -ne '') { $list = @($ns -split '[,\s]+' | Where-Object { $_ -ne '' }) }
    return @{ Auto = ($list.Count -eq 0); Servers = $list }
}

function Invoke-DnsOp($Op) {
    $idx = [int]$Op.Index
    $ad = Get-NetAdapter -InterfaceIndex $idx -ErrorAction SilentlyContinue
    if ($null -eq $ad) { Add-Skip (('A' + [char]0x011F + ' kart' + [char]0x0131 + ' bulunamad' + [char]0x0131 + ': ') + $Op.Alias); return }
    $st = Get-AdapterDnsState $ad
    $auto = ([string]$Op.Servers -eq 'Auto')
    $wantList = @()
    if (-not $auto) { $wantList = @($Op.Servers) }
    $same = $false
    if ($auto) { $same = $st.Auto }
    elseif (-not $st.Auto) { $same = ((@($st.Servers) -join ',') -eq ((@($wantList) | Where-Object { $_ -notmatch ':' }) -join ',')) }
    if ($same) { Add-Skip ('DNS zaten uygun: ' + $ad.Name); return }
    $wantTxt = 'Otomatik (DHCP)'
    if (-not $auto) { $wantTxt = ($wantList -join ', ') }
    $curTxt = 'Otomatik (DHCP)'
    if (-not $st.Auto) { $curTxt = ($st.Servers -join ', ') }
    if ($script:Preview) { Add-Plan ('DNS {0}: {1} -> {2}' -f $ad.Name, $curTxt, $wantTxt); return }
    Add-Journal @{ T = 'Dns'; Index = $idx; Alias = [string]$ad.Name; PrevAuto = $st.Auto; Prev = @($st.Servers) }
    if ($auto) { Set-DnsClientServerAddress -InterfaceIndex $idx -ResetServerAddresses -ErrorAction Stop }
    else { Set-DnsClientServerAddress -InterfaceIndex $idx -ServerAddresses $wantList -ErrorAction Stop }
    try { Clear-DnsClientCache -ErrorAction SilentlyContinue } catch { }
    Add-Done ('DNS {0} -> {1}' -f $ad.Name, $wantTxt)
}

# ---------------- Windows istege bagli ozellikleri (SMB1, PowerShell 2 ...) ----------------
function Invoke-FeatureOp($Op) {
    $name = [string]$Op.Name
    $f = $null
    $readErr = ''
    try { $f = Get-WinFeatureInfo $name } catch { $readErr = $_.Exception.Message }
    if ($null -eq $f -and $readErr -ne '') { $script:OpUnreadable = $true; Add-Skip (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i okunamad' + [char]0x0131 + ' (') + $name + '): ' + $readErr); return }
    if ($null -eq $f) { Add-Skip (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde yok: ') + $name); return }
    $isOn = (@('Enabled', 'EnablePending') -contains [string]$f.State)
    $wantOn = ([string]$Op.State -eq 'Enabled')
    if ($isOn -eq $wantOn) { Add-Skip (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i zaten uygun: ') + $name); return }
    if ($script:Preview) { Add-Plan (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i ') + $name + ' : ' + [string]$f.State + ' -> ' + [string]$Op.State); return }
    $busy = Get-ServicingBusy
    if ($busy -ne '') {
        Write-WhLog ($busy + ('; Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i ' + [char]0x015F + 'imdi de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmedi (') + $name + ('). G' + [char]0x00FC + 'ncelleme bitince tekrar uygulay' + [char]0x0131 + 'n.')) 'WARN'
        Add-Skip (('Windows Update me' + [char]0x015F + 'gul, ertelendi: ') + $name)
        return
    }
    Add-Journal @{ T = 'Feature'; Name = $name; WasEnabled = $isOn }
    [void](Set-WinFeatureState $name $wantOn)
    Add-Done (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i ') + $name + ' -> ' + [string]$Op.State + (' (yeniden ba' + [char]0x015F + 'latma gerekebilir)'))
}

# ---------------- Guc plani ----------------
function Invoke-PowerPlan {
    # Guc sayfasindaki ile ayni yol: Modern Bekleme'de guc kipi (En iyi performans), klasik bilgisayarda Yuksek Performans plani
    Invoke-PowerSetOp @{ T = 'PowerSet'; Key = 'High' }
}

function Invoke-HibernateOff {
    $en = [int](Get-RegValue 'HKLM\SYSTEM\CurrentControlSet\Control\Power' 'HibernateEnabled' 1)
    if ($en -eq 0) { Add-Skip ('Haz' + [char]0x0131 + 'rda bekletme zaten kapal' + [char]0x0131); return }
    $sz = ''
    try { $hf = Get-Item -LiteralPath (Join-Path $env:SystemDrive 'hiberfil.sys') -Force -ErrorAction Stop; $sz = ' (' + (Format-Size $hf.Length) + (' alan a' + [char]0x00E7 + [char]0x0131 + 'lacak)') } catch { }
    if ($script:Preview) { Add-Plan (('Haz' + [char]0x0131 + 'rda bekletme ve H' + [char]0x0131 + 'zl' + [char]0x0131 + ' Ba' + [char]0x015F + 'lat kapat' + [char]0x0131 + 'lacak') + $sz); return }
    Add-Journal @{ T = 'Hiber'; WasOn = $true }
    & powercfg.exe /hibernate off | Out-Null
    Add-Done (('Haz' + [char]0x0131 + 'rda bekletme kapat' + [char]0x0131 + 'ld' + [char]0x0131) + $sz)
}

# ---------------- temizlik yardimcilari ----------------
# Baglanti/sembolik link izlemeden klasoru gezer
function Get-FilesSafe([string]$Root, [datetime]$OlderThan) {
    $list  = New-Object System.Collections.ArrayList
    if (-not (Test-Path -LiteralPath $Root -ErrorAction SilentlyContinue)) { return , $list }
    $stack = New-Object System.Collections.Stack
    $stack.Push($Root)
    while ($stack.Count -gt 0) {
        $dir = [string]$stack.Pop()
        foreach ($it in @(Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue)) {
            if (($it.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { continue }
            if ($it.PSIsContainer) { $stack.Push($it.FullName) }
            elseif ($it.LastWriteTime -lt $OlderThan) { [void]$list.Add($it) }
        }
    }
    return , $list
}

function Remove-FilesSafe($Files) {
    $freed = 0.0; $count = 0
    foreach ($f in $Files) {
        $len = [double]$f.Length
        try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; $freed += $len; $count++ } catch { }
    }
    return @{ Bytes = $freed; Count = $count }
}

function Remove-EmptyDirs([string]$Root) {
    if (-not (Test-Path -LiteralPath $Root -ErrorAction SilentlyContinue)) { return }
    foreach ($d in @(Get-ChildItem -LiteralPath $Root -Directory -Recurse -Force -ErrorAction SilentlyContinue | Sort-Object { $_.FullName.Length } -Descending)) {
        if (($d.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { continue }
        try { if (@(Get-ChildItem -LiteralPath $d.FullName -Force -ErrorAction SilentlyContinue).Count -eq 0) { Remove-Item -LiteralPath $d.FullName -Force -ErrorAction SilentlyContinue } } catch { }
    }
}

# Klasor listesini temizler (onizlemede yalnizca sayar). $MustMatch: kok klasor guvenlik denetimi (zorunlu)
function Clear-Folders([string]$Label, [string[]]$Dirs, [double]$AgeDays, [string]$MustMatch) {
    $limit = (Get-Date).AddDays(-1 * $AgeDays)
    if ($AgeDays -le 0) { $limit = [datetime]::MaxValue }
    $bytes = 0.0; $count = 0
    foreach ($d in @($Dirs)) {
        $d = ([string]$d).TrimEnd('\')
        if ($d.Length -lt 10 -or $d -notmatch $MustMatch -or -not (Test-Path -LiteralPath $d -ErrorAction SilentlyContinue)) { continue }
        $files = Get-FilesSafe $d $limit
        if ($script:Preview) {
            foreach ($f in $files) { $bytes += [double]$f.Length; $count++ }
        } else {
            $r = Remove-FilesSafe $files
            $bytes += $r.Bytes; $count += $r.Count
            if ($AgeDays -le 0) { Remove-EmptyDirs $d }
        }
    }
    $script:LastClean = @{ Bytes = $bytes; Count = $count }
    $msg = ('{0}: {1} dosya, {2}' -f $Label, $count, (Format-Size $bytes))
    if ($script:Preview) { Add-Plan $msg } else { Add-Done $msg; $script:FreedBytes += $bytes }
}

function Invoke-CleanTemp {
    $tp = Get-TargetProfile
    $dirs = @($tp.Temp, [System.IO.Path]::GetTempPath(), (Join-Path $env:WINDIR 'Temp')) | Select-Object -Unique
    Clear-Folders ('Ge' + [char]0x00E7 + 'ici dosyalar') $dirs 1 '\\Temp$'
}

function Get-BrowserCacheDirs {
    $tp = Get-TargetProfile
    $la = $tp.LocalAppData
    $roots = @(
        (Join-Path $la 'Google\Chrome\User Data'),
        (Join-Path $la 'Microsoft\Edge\User Data'),
        (Join-Path $la 'BraveSoftware\Brave-Browser\User Data'),
        (Join-Path $la 'Vivaldi\User Data'),
        (Join-Path $la 'Opera Software\Opera Stable'),
        (Join-Path $tp.AppData 'Opera Software\Opera Stable')
    )
    $dirs = New-Object System.Collections.ArrayList
    foreach ($r in $roots) {
        if (-not (Test-Path -LiteralPath $r)) { continue }
        $profiles = @(Get-ChildItem -LiteralPath $r -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile *' -or $_.Name -eq 'Guest Profile' })
        if ($profiles.Count -eq 0) { $profiles = @(Get-Item -LiteralPath $r) }
        foreach ($p in $profiles) {
            foreach ($sub in @('Cache', 'Code Cache', 'GPUCache', 'Service Worker\CacheStorage', 'DawnCache', 'GrShaderCache', 'ShaderCache')) {
                $x = Join-Path $p.FullName $sub
                if (Test-Path -LiteralPath $x) { [void]$dirs.Add($x) }
            }
        }
    }
    $ff = Join-Path $la 'Mozilla\Firefox\Profiles'
    if (Test-Path -LiteralPath $ff) {
        foreach ($p in @(Get-ChildItem -LiteralPath $ff -Directory -Force -ErrorAction SilentlyContinue)) {
            foreach ($sub in @('cache2', 'startupCache', 'thumbnails')) {
                $x = Join-Path $p.FullName $sub
                if (Test-Path -LiteralPath $x) { [void]$dirs.Add($x) }
            }
        }
    }
    return , $dirs.ToArray()
}

function Invoke-CleanBrowsers {
    $dirs = Get-BrowserCacheDirs
    Clear-Folders ('Taray' + [char]0x0131 + 'c' + [char]0x0131 + ' ' + [char]0x00F6 + 'nbellekleri (' + [char]0x00E7 + 'erez ve ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' silinmez)') $dirs 0 '(\\Cache|\\Code Cache|\\GPUCache|\\CacheStorage|\\DawnCache|\\GrShaderCache|\\ShaderCache|\\cache2|\\startupCache|\\thumbnails)$'
}

function Invoke-CleanWer {
    $tp = Get-TargetProfile
    $dirs = @(
        (Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportArchive'),
        (Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportQueue'),
        (Join-Path $env:ProgramData 'Microsoft\Windows\WER\Temp'),
        (Join-Path $tp.LocalAppData 'Microsoft\Windows\WER\ReportArchive'),
        (Join-Path $tp.LocalAppData 'Microsoft\Windows\WER\ReportQueue')
    )
    Clear-Folders ('Hata raporlama dosyalar' + [char]0x0131) $dirs 0 '\\WER\\(ReportArchive|ReportQueue|Temp)$'
}

function Invoke-CleanLogs {
    $dirs = @((Join-Path $env:WINDIR 'Logs\CBS'), (Join-Path $env:WINDIR 'Logs\DISM'), (Join-Path $env:WINDIR 'Logs\WindowsUpdate'))
    Clear-Folders ('Eski sistem g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kleri (14 g' + [char]0x00FC + 'nden eski)') $dirs 14 '\\Logs\\(CBS|DISM|WindowsUpdate)$'
}

function Invoke-CleanDumps {
    $dirs = @((Join-Path $env:WINDIR 'Minidump'), (Join-Path $env:WINDIR 'LiveKernelReports'))
    Clear-Folders ('Hata d' + [char]0x00F6 + 'k' + [char]0x00FC + 'mleri (minidump)') $dirs 0 '\\(Minidump|LiveKernelReports)$'
    $big = Join-Path $env:WINDIR 'MEMORY.DMP'
    if (Test-Path -LiteralPath $big) {
        $len = (Get-Item -LiteralPath $big -Force).Length
        if ($script:Preview) { Add-Plan ('MEMORY.DMP silinecek: ' + (Format-Size $len)) }
        else {
            try { Remove-Item -LiteralPath $big -Force -ErrorAction Stop; Add-Done ('MEMORY.DMP silindi: ' + (Format-Size $len)); $script:FreedBytes += $len }
            catch { Add-Skip ('MEMORY.DMP silinemedi (kullan' + [char]0x0131 + 'mda)') }
        }
    }
}

function Invoke-CleanUpdateCache {
    $dl = Join-Path $env:WINDIR 'SoftwareDistribution\Download'
    $ti = Get-Service -Name 'TrustedInstaller' -ErrorAction SilentlyContinue
    if ($null -ne $ti -and $ti.Status -eq 'Running') { Write-WhLog ([string][char]0x015E + 'u anda g' + [char]0x00FC + 'ncelleme kuruluyor; g' + [char]0x00FC + 'ncelleme ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i bu sefer atland' + [char]0x0131 + '.') 'WARN'; return }
    $files = Get-FilesSafe $dl ([datetime]::MaxValue)
    $bytes = 0.0
    foreach ($f in $files) { $bytes += [double]$f.Length }
    if ($script:Preview) { Add-Plan (('Windows Update ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i: yakla' + [char]0x015F + [char]0x0131 + 'k ') + (Format-Size $bytes) + ' silinecek'); return }
    $svcs = @('wuauserv', 'bits')
    $wasRunning = @{}
    foreach ($s in $svcs) {
        $o = Get-Service -Name $s -ErrorAction SilentlyContinue
        $wasRunning[$s] = ($null -ne $o -and $o.Status -eq 'Running')
        Stop-Service -Name $s -Force -ErrorAction SilentlyContinue
    }
    $r = @{ Bytes = 0.0 }
    try {
        $r = Remove-FilesSafe $files
        Get-ChildItem -LiteralPath $dl -Force -Directory -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
    } finally {
        foreach ($s in $svcs) { if ($wasRunning[$s]) { Start-Service -Name $s -ErrorAction SilentlyContinue } }
    }
    if (Get-Command -Name 'Delete-DeliveryOptimizationCache' -ErrorAction Ignore) {
        try { & 'Delete-DeliveryOptimizationCache' -Force -ErrorAction Stop | Out-Null } catch { }
    }
    $script:FreedBytes += $r.Bytes
    Add-Done (('G' + [char]0x00FC + 'ncelleme ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i temizlendi: ') + (Format-Size $r.Bytes))
}

function Invoke-EmptyRecycleBin {
    if ($script:Preview) { Add-Plan ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu bo' + [char]0x015F + 'alt' + [char]0x0131 + 'lacak (geri al' + [char]0x0131 + 'namaz)'); return }
    Clear-RecycleBin -Force -ErrorAction SilentlyContinue
    Add-Done ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu bo' + [char]0x015F + 'alt' + [char]0x0131 + 'ld' + [char]0x0131)
}

function Invoke-OptimizeDrive {
    $letter = $env:SystemDrive.TrimEnd(':')
    $dt = ''
    try { $dt = [string]$sync.Profile.DiskType } catch { }
    if ([string]::IsNullOrEmpty($dt)) { try { $dt = [string]$sync.DiskType } catch { } }
    if ([string]::IsNullOrEmpty($dt)) { $dt = 'Unknown' }
    if ($script:Preview) { Add-Plan ($letter + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' optimize edilecek (disk t' + [char]0x00FC + 'r' + [char]0x00FC + ': ') + $dt + ')'); return }
    Write-WhLog ("Disk optimizasyonu ba" + [char]0x015F + "lad" + [char]0x0131 + "; HDD'de uzun s" + [char]0x00FC + "rebilir...") 'INFO'
    if ($dt -eq 'SSD') { Optimize-Volume -DriveLetter $letter -ReTrim -ErrorAction Stop }
    elseif ($dt -eq 'HDD') { Optimize-Volume -DriveLetter $letter -Defrag -ErrorAction Stop }
    else { Optimize-Volume -DriveLetter $letter -ErrorAction Stop }
    Add-Done ($letter + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' optimize edildi'))
}

function Invoke-DismCleanup {
    $busy = Get-ServicingBusy
    if ($busy -ne '') { Add-Skip (('DISM bile' + [char]0x015F + 'en deposu temizli' + [char]0x011F + 'i ertelendi: ') + $busy); return }
    $pend = Get-CbsRebootPending
    if ($pend -ne '') { Add-Skip (('DISM bile' + [char]0x015F + 'en deposu temizli' + [char]0x011F + 'i ertelendi: Windows bir bile' + [char]0x015F + 'en de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmay' + [char]0x0131 + ' bekliyor (') + $pend + ('); yeniden ba' + [char]0x015F + 'latt' + [char]0x0131 + 'ktan sonra tekrar deneyin')); return }
    if ($script:Preview) { Add-Plan ('DISM bile' + [char]0x015F + 'en deposu temizli' + [char]0x011F + 'i yap' + [char]0x0131 + 'lacak'); return }
    Assert-DismReady
    Write-WhLog ('DISM ba' + [char]0x015F + 'lad' + [char]0x0131 + '; 10-40 dakika s' + [char]0x00FC + 'rebilir, l' + [char]0x00FC + 'tfen bekleyin...') 'INFO'
    $rc = Invoke-DismExe @('/Online', '/Cleanup-Image', '/StartComponentCleanup') 60
    if ($rc -ne 0 -and $rc -ne 3010) { throw (('DISM bile' + [char]0x015F + 'en deposu temizli' + [char]0x011F + 'i tamamlanamad' + [char]0x0131 + ': ') + (Get-DismCodeText $rc)) }
    Add-Done ('DISM temizli' + [char]0x011F + 'i tamamland' + [char]0x0131 + '')
}

# Disk Temizleme (cleanmgr) kategorileri: Windows.old, guncelleme temizligi vb.
function Invoke-CleanMgr($Op) {
    $items = @($Op.Args.Items)
    $base = 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VolumeCaches\'
    $have = Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VolumeCaches'
    $found = @($items | Where-Object { $have -contains $_ })
    if ($found.Count -eq 0) { Add-Skip 'Disk Temizleme kategorisi bu sistemde yok'; return }
    if ($script:Preview) { Add-Plan ('Disk Temizleme (cleanmgr) kategorileri temizlenecek: ' + ($found -join ', ')); return }
    Write-WhLog ('Disk Temizleme (cleanmgr) ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'yor; uzun s' + [char]0x00FC + 'rebilir...') 'INFO'
    foreach ($i in $found) { Set-RegData ($base + $i) 'StateFlags0099' 'DWord' 2 }
    try {
        [void](Start-Process -FilePath (Join-Path $env:WINDIR 'System32\cleanmgr.exe') -ArgumentList '/sagerun:99' -Wait -PassThru -WindowStyle Hidden)
    } finally {
        foreach ($i in $found) { Remove-RegData ($base + $i) 'StateFlags0099' $false }
    }
    Add-Done (('Disk Temizleme tamamland' + [char]0x0131 + ': ') + ($found -join ', '))
}

# ---------------- diger islevler ----------------
function Invoke-FlushDns {
    if ($script:Preview) { Add-Plan ('DNS ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i temizlenecek'); return }
    try { Clear-DnsClientCache -ErrorAction Stop } catch { & ipconfig.exe /flushdns | Out-Null }
    Add-Done ('DNS ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i temizlendi')
}

function Invoke-TimeSync {
    if ($script:Preview) { Add-Plan ('Saat sunucuyla e' + [char]0x015F + 'itlenecek'); return }
    $svc = Get-Service -Name 'W32Time' -ErrorAction SilentlyContinue
    if ($null -ne $svc -and $svc.Status -ne 'Running') { Start-Service -Name 'W32Time' -ErrorAction SilentlyContinue }
    $out = & w32tm.exe /resync 2>&1 | Out-String
    Add-Done (('Saat e' + [char]0x015F + 'itlendi: ') + $out.Trim().Split("`n")[0].Trim())
}

$script:AuditLogonSubs = @('{0CCE9215-69AE-11D9-BED3-505054503030}', '{0CCE9217-69AE-11D9-BED3-505054503030}', '{0CCE9235-69AE-11D9-BED3-505054503030}', '{0CCE9236-69AE-11D9-BED3-505054503030}')
# Dort alt kategori de basari+hata ile aciksa $true; okunamazsa $false (uygulama yoluna duser, orada gercek hata gorunur)
function Test-AuditLogonOn {
    foreach ($g in $script:AuditLogonSubs) {
        $txt = ''
        try { $txt = ((& auditpol.exe /get /subcategory:$g /r 2>$null) | Out-String) } catch { return $false }
        if ($LASTEXITCODE -ne 0 -or $txt -eq '') { return $false }
        $row = @($txt -split "`r?`n" | Where-Object { $_ -match ',' } | Select-Object -Skip 1 | Select-Object -First 1)
        if ($row.Count -eq 0) { return $false }
        $cells = [string]$row[0] -split ','
        $set = ''
        if ($cells.Count -ge 5) { $set = [string]$cells[4] } else { $set = [string]$cells[$cells.Count - 1] }
        # 'Inclusion Setting' sutunu: 'Success and Failure' / 'Basari ve Hata' (dil bagimsiz esleme)
        if ($set -notmatch '(?i)success.*failure|failure.*success|ba.ar.*hata|hata.*ba.ar') { return $false }
    }
    return $true
}

# Denetim ilkesi: auditpol /backup ile tam geri alma
function Invoke-AuditLogon {
    if (Test-AuditLogonOn) { Add-Skip ('Denetim ilkesi zaten etkin (oturum, hesap kilitleme, hesap y' + [char]0x00F6 + 'netimi, ilke de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i)'); return }
    if ($script:Preview) { Add-Plan ('Denetim ilkesi etkinle' + [char]0x015F + 'tirilecek: oturum a' + [char]0x00E7 + 'ma/kapatma, hesap kilitleme, kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' hesab' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi'); return }
    $bk = Join-Path $sync.BackupDir ('denetim-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.csv')
    & auditpol.exe /backup /file:$bk | Out-Null
    if ($LASTEXITCODE -ne 0) { throw ('auditpol yede' + [char]0x011F + 'i al' + [char]0x0131 + 'namad' + [char]0x0131) }
    Add-Journal @{ T = 'Audit'; File = $bk }
    foreach ($g in @('{0CCE9215-69AE-11D9-BED3-505054503030}', '{0CCE9217-69AE-11D9-BED3-505054503030}', '{0CCE9235-69AE-11D9-BED3-505054503030}', '{0CCE9236-69AE-11D9-BED3-505054503030}')) {
        & auditpol.exe /set /subcategory:$g /success:enable /failure:enable | Out-Null
    }
    Add-Done ('Denetim ilkesi etkinle' + [char]0x015F + 'tirildi (olay g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ': G' + [char]0x00FC + 'venlik)')
}

function Invoke-GuestOff {
    $u = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { $_.SID.Value -like '*-501' } | Select-Object -First 1
    if ($null -eq $u) { Add-Skip ('Konuk hesab' + [char]0x0131 + ' bulunamad' + [char]0x0131); return }
    if (-not $u.Enabled) { Add-Skip ('Konuk hesab' + [char]0x0131 + ' zaten kapal' + [char]0x0131); return }
    if ($script:Preview) { Add-Plan ('Konuk hesab' + [char]0x0131 + ' kapat' + [char]0x0131 + 'lacak'); return }
    Add-Journal @{ T = 'User'; Name = [string]$u.Name; WasEnabled = $true }
    Disable-LocalUser -Name $u.Name -ErrorAction Stop
    Add-Done ('Konuk hesab' + [char]0x0131 + ' kapat' + [char]0x0131 + 'ld' + [char]0x0131)
}

# ---------------- islev dagitici ----------------
function Invoke-FuncOp($Op) {
    switch ([string]$Op.Name) {
        'PowerPlan'        { Invoke-PowerPlan }
        'HibernateOff'     { Invoke-HibernateOff }
        'CleanTemp'        { Invoke-CleanTemp }
        'CleanBrowsers'    { Invoke-CleanBrowsers }
        'CleanWer'         { Invoke-CleanWer }
        'CleanLogs'        { Invoke-CleanLogs }
        'CleanDumps'       { Invoke-CleanDumps }
        'CleanUpdateCache' { Invoke-CleanUpdateCache }
        'EmptyRecycleBin'  { Invoke-EmptyRecycleBin }
        'OptimizeDrive'    { Invoke-OptimizeDrive }
        'DismCleanup'      { Invoke-DismCleanup }
        'CleanMgr'         { Invoke-CleanMgr $Op }
        'FlushDns'         { Invoke-FlushDns }
        'TimeSync'         { Invoke-TimeSync }
        'AuditLogon'       { Invoke-AuditLogon }
        'GuestOff'         { Invoke-GuestOff }
        'NetBiosOff'       { Invoke-NetBiosOff }
        'LockoutPolicy'    { Invoke-LockoutPolicy }
        'HostsBlock'       { Set-HostsBlock $true }
        'HostsUnblock'     { Set-HostsBlock $false }
        default            {
            if ($null -ne $script:FuncOps -and $script:FuncOps.ContainsKey([string]$Op.Name)) { & ([string]$script:FuncOps[[string]$Op.Name]) }
            else { throw (('Bilinmeyen i' + [char]0x015F + 'lev: ') + $Op.Name) }
        }
    }
}

function Invoke-Op($Op) {
    switch ([string]$Op.T) {
        'Reg'     { Invoke-RegOp $Op }
        'Svc'     { Invoke-SvcOp $Op }
        'Task'    { Invoke-TaskOp $Op }
        'Appx'    { Invoke-AppxOp $Op }
        'Mp'      { Invoke-MpOp $Op }
        'Dns'     { Invoke-DnsOp $Op }
        'Feature' { Invoke-FeatureOp $Op }
        'Func'    { Invoke-FuncOp $Op }
        'Fw'      { Invoke-FwOp $Op }
        'EvtLog'  { Invoke-EvtLogOp $Op }
        default   { Invoke-MoreOp $Op }
    }
}

# ---------------- Sistem Geri Yukleme noktasi ----------------
function Invoke-RestorePoint([string]$Desc = '') {
    $key = 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore'
    $old = Get-RegInfo $key 'SystemRestorePointCreationFrequency'
    Write-WhLog ('Sistem Geri Y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turuluyor (1-3 dakika s' + [char]0x00FC + 'rebilir)...') 'INFO'
    $ok = $false
    try {
        Enable-ComputerRestore -Drive ($env:SystemDrive + '\') -ErrorAction SilentlyContinue
        Set-RegData $key 'SystemRestorePointCreationFrequency' 'DWord' 0
        if ($Desc -eq '') { $Desc = 'Multimizer ' + (Get-Date -Format 'yyyy-MM-dd HH:mm') }
        Checkpoint-Computer -Description $Desc -RestorePointType 'MODIFY_SETTINGS' -ErrorAction Stop
        Write-WhLog ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turuldu.') 'OK'
        $ok = $true
    } catch {
        Write-WhLog (('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + $_.Exception.Message + ('. De' + [char]0x011F + 'i' + [char]0x015F + 'iklikler yine de yedekten geri al' + [char]0x0131 + 'nabilir.')) 'WARN'
    } finally {
        try {
            if ($old.Exists) { Set-RegData $key 'SystemRestorePointCreationFrequency' $old.Kind $old.Value }
            else { Remove-RegData $key 'SystemRestorePointCreationFrequency' $false }
        } catch { }
    }
    return $ok
}

# ---------------- plan calistirici ----------------
# Steps: @( @{ Title; Ops = @(op, ...) }, ... )
function Invoke-Plan($Steps, [bool]$RestorePoint) {
    $steps = @($Steps)
    $total = 0
    foreach ($s in $steps) { $total += @($s.Ops).Count }
    $doRp = ($RestorePoint -and -not $script:Preview)
    if ($doRp) { $total++ }
    Set-JobProgress 0 $total
    if (-not $script:Preview) {
        $jf = Join-Path $sync.BackupDir ('yedek-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.jsonl')
        Open-Journal $jf
    }
    Start-ScoreMeasure
    try {
        if ($doRp) { [void](Invoke-RestorePoint); Step-JobProgress }
        foreach ($s in $steps) {
            Write-WhLog ('=== ' + $s.Title) 'STEP'
            foreach ($op in @($s.Ops)) {
                try { Invoke-Op $op }
                catch { Add-Err ('Hata: ' + $_.Exception.Message) }
                Step-JobProgress
            }
        }
    } finally {
        if (-not $script:Preview) { try { [void](Invoke-LiveRefresh @($script:JItems)) } catch { }; Close-Journal }
        try { if ($steps.Count -gt 0) { Complete-ScoreMeasure ([string]$steps[0].Title) } } catch { }
    }
}

# ---------------- geri alma ----------------
# Geri alinamayan kayitlari yedekte birakir: oturum Gecmis sayfasinda kalir, yeniden baslatmadan sonra tekrar geri alinabilir.
# $Failed geri alma sirasindadir (dosyanin tersi); dosyaya ilk siralariyla yazilir.
function Save-UndoRemainder([string]$File, $Jr, $Failed) {
    $n = @($Failed).Count
    try {
        if ($File.EndsWith('.jsonl', [StringComparison]::OrdinalIgnoreCase)) {
            $keep = @($Failed)
            [array]::Reverse($keep)
            $sb = New-Object System.Text.StringBuilder
            if ($null -ne $Jr.Header) { [void]$sb.Append((ConvertTo-Json -InputObject $Jr.Header -Compress -Depth 5) + "`r`n") }
            foreach ($it in $keep) { [void]$sb.Append((ConvertTo-Json -InputObject $it -Compress -Depth 5) + "`r`n") }
            [System.IO.File]::WriteAllText($File, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
        }
    } catch { Write-LogFile ('Kalan geri alma kayitlari yazilamadi: ' + $_.Exception.Message) }
    Write-WhLog ([string]$n + (' kay' + [char]0x0131 + 't geri al' + [char]0x0131 + 'namad' + [char]0x0131 + '; bu yedek Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'nda kald' + [char]0x0131 + '. Bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'latt' + [char]0x0131 + 'ktan sonra yeniden geri alabilirsiniz.')) 'WARN'
}

function Invoke-Undo([string]$File) {
    $jr = Read-Journal $File
    $items = @($jr.Items)
    [array]::Reverse($items)
    Set-JobProgress 0 $items.Count
    $created = ''
    if ($null -ne $jr.Header) { $created = [string](Get-JsonProp $jr.Header 'Created') }
    Write-WhLog ('Yedek: ' + $created + ' (' + $items.Count + (' kay' + [char]0x0131 + 't)')) 'STEP'
    $undoFail = New-Object System.Collections.ArrayList
    foreach ($it in $items) {
        try {
            switch ([string]$it.T) {
                'Reg' {
                    if ($it.Existed) { Set-RegData $it.Path $it.Name $it.Kind (ConvertFrom-BackupText $it.Kind $it.Data) }
                    else { Remove-RegData $it.Path $it.Name (-not $it.KeyExisted) }
                    Add-Done (('Geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + $it.Path + '\' + $it.Name)
                }
                'Svc' {
                    if ($null -ne $it.Start) {
                        Set-SvcStart $it.Name ([int]$it.Start) ([bool]$it.Delayed)
                        if ($it.WasRunning) {
                            for ($k = 0; $k -lt 60; $k++) {
                                $sv = Get-Service -Name $it.Name -ErrorAction SilentlyContinue
                                if ($null -eq $sv -or $sv.Status -eq 'Running') { break }
                                if ($sv.Status -eq 'Stopped') { Start-Service -Name $it.Name -ErrorAction SilentlyContinue }
                                Start-Sleep -Milliseconds 500
                            }
                            $sv = Get-Service -Name $it.Name -ErrorAction SilentlyContinue
                            if ($null -ne $sv -and $sv.Status -ne 'Running') { throw (('Hizmet 30 sn i' + [char]0x00E7 + 'inde ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $it.Name) }
                        }
                    }
                    Add-Done (('Hizmet geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + $it.Name)
                }
                'Task' {
                    if ($it.WasDisabled -eq $true) { Disable-ScheduledTask -TaskPath $it.Path -TaskName $it.Name -ErrorAction Stop | Out-Null }
                    else { Enable-ScheduledTask -TaskPath $it.Path -TaskName $it.Name -ErrorAction Stop | Out-Null }
                    Add-Done (('G' + [char]0x00F6 + 'rev eski haline d' + [char]0x00F6 + 'nd' + [char]0x00FC + ': ') + $it.Path + $it.Name)
                }
                'Power' {
                    if ($it.Guid) { & powercfg.exe /setactive $it.Guid | Out-Null }
                    # uygulamanin olusturdugu plan (etkin degilse) silinir
                    $cr = [string]$it.Created
                    if ($cr -match ('^' + $script:GuidRx + '$') -and $cr -ne [string]$it.Guid) { try { & powercfg.exe /delete $cr 2>&1 | Out-Null } catch { } }
                    Add-Done ('G' + [char]0x00FC + [char]0x00E7 + ' plan' + [char]0x0131 + ' geri al' + [char]0x0131 + 'nd' + [char]0x0131)
                }
                'Hiber' {
                    & powercfg.exe /hibernate on | Out-Null
                    Add-Done ('Haz' + [char]0x0131 + 'rda bekletme yeniden a' + [char]0x00E7 + [char]0x0131 + 'ld' + [char]0x0131)
                }
                'Mp' {
                    $splat = @{}
                    if ($it.IsBool -eq $true) { $splat[[string]$it.Name] = ([string]$it.Prev -eq 'true') }
                    else { $splat[[string]$it.Name] = [int][string]$it.Prev }
                    Set-MpPreference @splat -ErrorAction Stop
                    Add-Done (('Defender geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + $it.Name)
                }
                'Dns' {
                    if ($it.PrevAuto -eq $true) { Set-DnsClientServerAddress -InterfaceIndex ([int]$it.Index) -ResetServerAddresses -ErrorAction Stop }
                    else { Set-DnsClientServerAddress -InterfaceIndex ([int]$it.Index) -ServerAddresses @($it.Prev) -ErrorAction Stop }
                    Add-Done (('DNS geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + $it.Alias)
                }
                'Feature' {
                    [void](Set-WinFeatureState ([string]$it.Name) ($it.WasEnabled -eq $true))
                    Add-Done (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + $it.Name)
                }
                'Audit' {
                    $af = [string]$it.File
                    & auditpol.exe /restore /file:$af | Out-Null
                    Add-Done ('Denetim ilkesi geri y' + [char]0x00FC + 'klendi')
                }
                'User' {
                    if ($it.WasEnabled -eq $true) { Enable-LocalUser -Name $it.Name -ErrorAction Stop }
                    Add-Done (('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' hesab' + [char]0x0131 + ' geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + $it.Name)
                }
                'Appx' {
                    if (-not (Restore-AppxItem $it)) { Write-WhLog (("Uygulama otomatik geri gelmez; Microsoft Store'dan yeniden y" + [char]0x00FC + "kleyebilirsiniz: ") + $it.Name) 'WARN' }
                }
                default { Undo-ExtraItem $it }
            }
        } catch { Add-Err ('Hata: ' + $_.Exception.Message); [void]$undoFail.Add($it) }
        Step-JobProgress
    }
    try { [void](Invoke-LiveRefresh $items) } catch { }
    if ($undoFail.Count -gt 0) { Save-UndoRemainder $File $jr $undoFail.ToArray(); return }
    try {
        $dn = [System.IO.Path]::ChangeExtension($File, '.geri-alindi' + [System.IO.Path]::GetExtension($File))
        Move-Item -LiteralPath $File -Destination $dn -Force -ErrorAction Stop
    } catch { }
}

# ---------------- onarim (SFC/DISM) akisi ----------------
function Invoke-Native([string]$Exe, [string[]]$NativeArgs) {
    $path = Join-Path (Join-Path $env:WINDIR 'System32') $Exe
    if (-not (Test-Path -LiteralPath $path)) { $path = $Exe }
    Write-WhLog (('Ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor: ') + $Exe + ' ' + ($NativeArgs -join ' ')) 'INFO'
    $global:LASTEXITCODE = 0
    & $path @NativeArgs 2>&1 | ForEach-Object {
        $line = ([string]$_) -replace "`0", ''
        $line = $line.TrimEnd([char]13)
        if ($line.Trim().Length -gt 0) { Write-Raw ('   ' + $line) }
    }
    return $LASTEXITCODE
}

function Invoke-Repair($Steps) {
    $steps = @($Steps)
    Set-JobProgress 0 $steps.Count
    $results = New-Object System.Collections.ArrayList
    foreach ($st in $steps) {
        Write-WhLog ('=== ' + $st.Label) 'STEP'
        $code = -1
        try { $code = Invoke-Native $st.Exe $st.NativeArgs }
        catch { Add-Err ('Hata: ' + $_.Exception.Message) }
        if ($code -eq 0) { Add-Done ($st.Label + (': tamamland' + [char]0x0131 + ' (' + [char]0x00E7 + [char]0x0131 + 'k' + [char]0x0131 + [char]0x015F + ' kodu 0)')) }
        elseif ($code -eq 3010) { Write-WhLog ($st.Label + (': tamamland' + [char]0x0131 + ', yeniden ba' + [char]0x015F + 'latma gerekiyor (kod 3010)')) 'WARN' }
        else { Write-WhLog ($st.Label + (': ' + [char]0x00E7 + [char]0x0131 + 'k' + [char]0x0131 + [char]0x015F + ' kodu ') + $code) 'WARN' }
        [void]$results.Add(@{ Id = $st.Id; Label = $st.Label; ExitCode = $code })
        Step-JobProgress
    }
    return $results.ToArray()
}

$script:RepairSteps = [ordered]@{
    Check   = @{ Id = 'DISM-Check'; Exe = 'Dism.exe'; NativeArgs = @('/Online', '/Cleanup-Image', '/CheckHealth'); Label = ('DISM - H' + [char]0x0131 + 'zl' + [char]0x0131 + ' sa' + [char]0x011F + 'l' + [char]0x0131 + 'k kontrol' + [char]0x00FC + ' (CheckHealth)') }
    SFC     = @{ Id = 'SFC'; Exe = 'sfc.exe'; NativeArgs = @('/scannow'); Label = ('SFC - Sistem Dosyas' + [char]0x0131 + ' Denetleyicisi (/scannow)') }
    Scan    = @{ Id = 'DISM-Scan'; Exe = 'Dism.exe'; NativeArgs = @('/Online', '/Cleanup-Image', '/ScanHealth'); Label = ('DISM - Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' tarama (ScanHealth)') }
    Restore = @{ Id = 'DISM-Restore'; Exe = 'Dism.exe'; NativeArgs = @('/Online', '/Cleanup-Image', '/RestoreHealth'); Label = ('DISM - Windows imaj' + [char]0x0131 + 'n' + [char]0x0131 + ' onar (RestoreHealth)') }
    ChkDsk  = @{ Id = 'CHKDSK'; Exe = 'chkdsk.exe'; NativeArgs = @($env:SystemDrive, '/scan'); Label = ('CHKDSK - ' + [char]0x00E7 + 'evrimi' + [char]0x00E7 + 'i disk taramas' + [char]0x0131 + ' (/scan)') }
}
function Get-RepairSet([string[]]$Keys) { return @($Keys | ForEach-Object { $script:RepairSteps[$_] }) }

# ==================================================================
#  CEKIRDEK 3 - ek islemler: guvenlik duvari grubu, olay gunlugu boyutu, hosts dosyasi
#  Geri alma icin Invoke-Undo icindeki 'default' dali Undo-ExtraItem'i cagirir.
# ==================================================================

# ---------------- Guvenlik duvari kural grubu (or. Uzak Masaustu) ----------------
function Invoke-FwOp($Op) {
    $grp = [string]$Op.Group
    $label = [string]$Op.Label
    if ($label -eq '') { $label = $grp }
    $rules = @()
    try { $rules = @(Get-NetFirewallRule -Group $grp -ErrorAction Stop) } catch { }
    if ($rules.Count -eq 0) { Add-Skip (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kural grubu bu sistemde yok: ') + $label); return }
    $on = @($rules | Where-Object { [string]$_.Enabled -eq 'True' })
    $want = [bool]$Op.Enable
    if ($want -and $on.Count -eq $rules.Count) { Add-Skip (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' grubu zaten a' + [char]0x00E7 + [char]0x0131 + 'k: ') + $label); return }
    if (-not $want -and $on.Count -eq 0) { Add-Skip (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' grubu zaten kapal' + [char]0x0131 + ': ') + $label); return }
    $verb = ('kapat' + [char]0x0131 + 'lacak')
    if ($want) { $verb = ('a' + [char]0x00E7 + [char]0x0131 + 'lacak') }
    if ($script:Preview) { Add-Plan (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kural grubu ') + $verb + ': ' + $label + ' (' + $rules.Count + ' kural)'); return }
    Add-Journal @{ T = 'Fw'; Group = $grp; Label = $label; OnNames = @($on | ForEach-Object { [string]$_.Name }) }
    if ($want) { Set-NetFirewallRule -Group $grp -Enabled True -ErrorAction Stop }
    else { Set-NetFirewallRule -Group $grp -Enabled False -ErrorAction Stop }
    Add-Done (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kural grubu ') + $label + ' -> ' + $(if ($want) { ('a' + [char]0x00E7 + [char]0x0131 + 'k') } else { ('kapal' + [char]0x0131) }))
}

# ---------------- Olay gunlugu azami boyutu ----------------
function Invoke-EvtLogOp($Op) {
    $name = [string]$Op.Name
    $wantBytes = [int64]$Op.MaxKB * 1024
    $log = $null
    try { $log = Get-WinEvent -ListLog $name -ErrorAction Stop } catch { }
    if ($null -eq $log) { Add-Skip (('Olay g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ' yok: ') + $name); return }
    $cur = [int64]$log.MaximumSizeInBytes
    if ($cur -ge $wantBytes) { Add-Skip (('Olay g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ' boyutu zaten yeterli: ') + $name + ' (' + (Format-Size $cur) + ')'); return }
    if ($script:Preview) { Add-Plan (('Olay g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ' ') + $name + ': ' + (Format-Size $cur) + ' -> ' + (Format-Size $wantBytes)); return }
    Add-Journal @{ T = 'EvtLog'; Name = $name; PrevBytes = $cur }
    & wevtutil.exe sl $name ('/ms:' + $wantBytes) | Out-Null
    if ($LASTEXITCODE -ne 0) { throw ('wevtutil sl ' + $name + (' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (kod ') + $LASTEXITCODE + ')') }
    Add-Done (('Olay g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ' ') + $name + ' -> ' + (Format-Size $wantBytes))
}

# ---------------- guvenlik ilkesi degerlerini (secedit) oku ----------------
function Get-SecPolValues {
    $tmp = Join-Path $env:TEMP ('wh-secpol-' + [guid]::NewGuid().ToString('N') + '.inf')
    $r = @{}
    try {
        & secedit.exe /export /cfg $tmp /areas SECURITYPOLICY | Out-Null
        if (Test-Path -LiteralPath $tmp) {
            foreach ($ln in [System.IO.File]::ReadAllLines($tmp)) {
                if ($ln -cmatch '^\s*([A-Za-z]+)\s*=\s*(.+?)\s*$') { $r[$Matches[1]] = $Matches[2] }
            }
        }
    } catch { } finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
    return $r
}

# Hesap kilitleme ilkesi: 10 hatali denemede 15 dakika kilitle (net accounts)
function Invoke-LockoutPolicy {
    $cur = Get-SecPolValues
    $thr = 0; $dur = 30; $win = 30
    if ($cur.ContainsKey('LockoutBadCount')) { $thr = [int]$cur['LockoutBadCount'] }
    if ($cur.ContainsKey('LockoutDuration')) { $dur = [int]$cur['LockoutDuration'] }
    if ($cur.ContainsKey('ResetLockoutCount')) { $win = [int]$cur['ResetLockoutCount'] }
    if ($thr -ge 1 -and $thr -le 10) { Add-Skip ('Hesap kilitleme zaten etkin (' + $thr + ' deneme)'); return }
    if ($script:Preview) { Add-Plan ('Hesap kilitleme: ' + $thr + (' -> 10 hatal' + [char]0x0131 + ' denemede 15 dakika kilit')); return }
    Add-Journal @{ T = 'NetAcc'; Thr = $thr; Dur = $dur; Win = $win }
    & net.exe accounts /lockoutthreshold:10 /lockoutduration:15 /lockoutwindow:15 | Out-Null
    if ($LASTEXITCODE -ne 0) { throw (('net accounts ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (kod ') + $LASTEXITCODE + ')') }
    Add-Done ('Hesap kilitleme etkinle' + [char]0x015F + 'tirildi: 10 hatal' + [char]0x0131 + ' denemede 15 dakika')
}

# ---------------- ek geri alma kayitlari ----------------
function Undo-ExtraItem($it) {
    switch ([string]$it.T) {
        'PowerMode' { Undo-PowerMode $it }
        'Fw' {
            $names = @($it.OnNames)
            foreach ($r in @(Get-NetFirewallRule -Group ([string]$it.Group) -ErrorAction SilentlyContinue)) {
                if ($names -contains [string]$r.Name) { Set-NetFirewallRule -Name $r.Name -Enabled True -ErrorAction SilentlyContinue }
                else { Set-NetFirewallRule -Name $r.Name -Enabled False -ErrorAction SilentlyContinue }
            }
            Add-Done (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' grubu eski haline d' + [char]0x00F6 + 'nd' + [char]0x00FC + ': ') + $it.Label)
        }
        'EvtLog' {
            & wevtutil.exe sl ([string]$it.Name) ('/ms:' + [int64]$it.PrevBytes) | Out-Null
            Add-Done (('Olay g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ' boyutu geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + $it.Name)
        }
        'NetAcc' {
            if ([int]$it.Thr -eq 0) { & net.exe accounts /lockoutthreshold:0 | Out-Null }
            else { & net.exe accounts /lockoutthreshold:([int]$it.Thr) /lockoutduration:([int]$it.Dur) /lockoutwindow:([int]$it.Win) | Out-Null }
            Add-Done ('Hesap kilitleme ilkesi geri al' + [char]0x0131 + 'nd' + [char]0x0131)
        }
        'Hosts' {
            $bak = [string]$it.Backup
            if ($bak -ne '' -and (Test-Path -LiteralPath $bak)) {
                Copy-Item -LiteralPath $bak -Destination (Join-Path $env:WINDIR 'System32\drivers\etc\hosts') -Force -ErrorAction Stop
                Add-Done ('hosts dosyas' + [char]0x0131 + ' yedekten geri y' + [char]0x00FC + 'klendi')
            }
        }
        default { Undo-MoreItem $it }
    }
}

