$script:HostsBegin = '# >>> Multimizer engel listesi (baslangic)'
$script:HostsBeginOld = '# >>> WinHizlandirici engel listesi (baslangic)'
$script:HostsEndOld   = '# <<< WinHizlandirici engel listesi (bitis)'
$script:HostsEnd   = '# <<< Multimizer engel listesi (bitis)'

$script:TrackerHosts = @(
    'vortex.data.microsoft.com', 'vortex-win.data.microsoft.com', 'telecommand.telemetry.microsoft.com',
    'oca.telemetry.microsoft.com', 'sqm.telemetry.microsoft.com', 'watson.telemetry.microsoft.com',
    'watson.microsoft.com', 'settings-sandbox.data.microsoft.com', 'v10.events.data.microsoft.com',
    'self.events.data.microsoft.com', 'browser.events.data.msn.com', 'telemetry.urs.microsoft.com',
    'redir.metaservices.microsoft.com', 'choice.microsoft.com', 'df.telemetry.microsoft.com',
    'reports.wes.df.telemetry.microsoft.com', 'services.wes.df.telemetry.microsoft.com',
    'ads.msn.com', 'adnxs.com', 'doubleclick.net', 'googleadservices.com', 'googlesyndication.com',
    'google-analytics.com', 'scorecardresearch.com', 'bat.bing.com'
)

function Get-HostsPath { return (Join-Path $env:WINDIR 'System32\drivers\etc\hosts') }

function Get-HostsBlockState {
    $p = Get-HostsPath
    $txt = ''
    try { $txt = [IO.File]::ReadAllText($p) } catch { }
    return @{ Installed = ($txt.Contains($script:HostsBegin) -or $txt.Contains($script:HostsBeginOld)); Path = $p; Length = $txt.Length }
}

function Set-HostsBlock([bool]$On) {
    $p = Get-HostsPath
    $txt = ''
    try { $txt = [IO.File]::ReadAllText($p) } catch { }
    $bak = Join-Path $sync.BackupDir ('hosts-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.bak')
    if ($script:Preview) {
        if ($On) { Add-Plan (('hosts dosyas' + [char]0x0131 + 'na ') + $script:TrackerHosts.Count + (' izleme/reklam alan' + [char]0x0131 + ' engeli eklenecek')) } else { Add-Plan ('hosts dosyas' + [char]0x0131 + 'ndaki engel listesi kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak') }
        return
    }
    if (Test-Path -LiteralPath $p) { Copy-Item -LiteralPath $p -Destination $bak -Force }
    Add-Journal @{ T = 'Hosts'; Backup = $bak }
    $rx = '(?s)\r?\n?' + [regex]::Escape($script:HostsBegin) + '.*?' + [regex]::Escape($script:HostsEnd) + '\r?\n?'
    $clean = [regex]::Replace($txt, $rx, "`r`n")
    $rxOld = '(?s)\r?\n?' + [regex]::Escape($script:HostsBeginOld) + '.*?' + [regex]::Escape($script:HostsEndOld) + '\r?\n?'
    $clean = [regex]::Replace($clean, $rxOld, "`r`n")
    $clean = $clean.TrimEnd() + "`r`n"
    if ($On) {
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.Append($clean)
        [void]$sb.Append("`r`n" + $script:HostsBegin + "`r`n")
        foreach ($h in $script:TrackerHosts) { [void]$sb.Append('0.0.0.0 ' + $h + "`r`n") }
        [void]$sb.Append($script:HostsEnd + "`r`n")
        $clean = $sb.ToString()
    }
    $enc = New-Object System.Text.UTF8Encoding($false)
    [IO.File]::WriteAllText($p, $clean, $enc)
    try { & ipconfig.exe /flushdns | Out-Null } catch { }
    if ($On) { Add-Done ('hosts: izleme/reklam alanlar' + [char]0x0131 + ' engellendi') } else { Add-Done ('hosts: engel listesi kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131) }
}

