#  AYAR KATALOGU (A): Gizlilik, Performans, Gorunum, Oyun, Temizlik
#  Seviye (Level): 1 = guvenli, 2 = dengeli, 3 = agresif, 4 = yalnizca elle (hicbir profil secmez)
#  OS: All | 10 | 11        When: '' | HDD | SSD | Desktop | Laptop
# ==================================================================
$script:Catalog = New-Object System.Collections.ArrayList

$script:CatNames = [ordered]@{
    Gizlilik   = 'Gizlilik ve izleme'
    Performans = 'Performans'
    Gorunum    = ('G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm ve Gezgin')
    Oyun       = 'Oyun'
    Ag         = ('A' + [char]0x011F)
    Temizlik   = 'Temizlik'
    Guvenlik   = ('G' + [char]0x00FC + 'venlik sertle' + [char]0x015F + 'tirme')
    Sirket     = ([string][char]0x015E + 'irket ilkeleri')
    Guncelleme = ('G' + [char]0x00FC + 'ncelleme ilkeleri')
}

function RegOp([string]$Path, [string]$Name, $Value, [string]$Kind = 'DWord') { return @{ T = 'Reg'; Path = $Path; Name = $Name; Kind = $Kind; Value = $Value } }
function RegDel([string]$Path, [string]$Name) { return @{ T = 'Reg'; Path = $Path; Name = $Name; Del = $true } }
function SvcOp([string]$Name, [string]$Start = 'Disabled') { return @{ T = 'Svc'; Name = $Name; Start = $Start } }
function TaskOp([string]$Path, [string]$Name, [string]$Action = 'Disable') { return @{ T = 'Task'; Path = $Path; Name = $Name; Action = $Action } }
function FuncOp([string]$Name, $FnArgs = $null) { return @{ T = 'Func'; Name = $Name; Args = $FnArgs } }
function MpOp([string]$Name, $Value) { return @{ T = 'Mp'; Name = $Name; Value = $Value } }
function FeatOp([string]$Name, [string]$State = 'Disabled') { return @{ T = 'Feature'; Name = $Name; State = $State } }
function FwOp([string]$Group, [bool]$Enable, [string]$Label = '') { return @{ T = 'Fw'; Group = $Group; Enable = $Enable; Label = $Label } }
function EvtOp([string]$Name, [int]$MaxKB) { return @{ T = 'EvtLog'; Name = $Name; MaxKB = $MaxKB } }

function Add-Tweak([hashtable]$T) {
    foreach ($k in @('OS', 'When', 'Group')) { if (-not $T.ContainsKey($k)) { $T[$k] = '' } }
    if ($T.OS -eq '') { $T.OS = 'All' }
    if (-not $T.ContainsKey('Level')) { $T.Level = 2 }
    if (-not $T.ContainsKey('Irrev')) { $T.Irrev = $false }
    if (-not $T.ContainsKey('Reboot')) { $T.Reboot = $false }
    if (-not $T.ContainsKey('Page')) { $T.Page = 'opt' }
    [void]$script:Catalog.Add($T)
}

