# ==================================================================
#  AYAR KATALOGU (B): Guvenlik sertlestirme, Sirket ilkeleri, Guncelleme ilkeleri
#  Guvenlik kapisi: Defender, Guvenlik Duvari (kapatma), UAC ve Windows Update hicbir ayarla kapatilmaz.
#  Seviye 4 = yalnizca elle secilir (hicbir hazir profil bunlari secmez).
# ==================================================================

# ============================ GUVENLIK ============================
Add-Tweak @{
    Id = 'Smb1'; Cat = 'Guvenlik'; Page = 'sec'; Level = 1; Reboot = $true
    Title = ('SMB 1.0 (eski dosya payla' + [char]0x015F + [char]0x0131 + 'm protokol' + [char]0x00FC + ') kapat')
    Desc  = ('WannaCry gibi fidye yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'mlar' + [char]0x0131 + 'n' + [char]0x0131 + 'n kulland' + [char]0x0131 + [char]0x011F + [char]0x0131 + ' eski ve g' + [char]0x00FC + 'vensiz protokold' + [char]0x00FC + 'r. Yeni cihazlar SMB 2/3 kullan' + [char]0x0131 + 'r; ' + [char]0x00E7 + 'ok eski NAS ve taray' + [char]0x0131 + 'c' + [char]0x0131 + 'lar yaln' + [char]0x0131 + 'zca SMB1 konu' + [char]0x015F + 'uyorsa etkilenir.')
    Ops = @(
        (RegOp 'HKLM\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters' 'SMB1' 0),
        (FeatOp 'SMB1Protocol' 'Disabled')
    )
}

Add-Tweak @{
    Id = 'AutoRun'; Cat = 'Guvenlik'; Page = 'sec'; Level = 1
    Title = ('Tak' + [char]0x0131 + 'lan USB/diskler i' + [char]0x00E7 + 'in otomatik ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'rmay' + [char]0x0131 + ' kapat')
    Desc  = ('USB bellekteki zararl' + [char]0x0131 + 'lar' + [char]0x0131 + 'n tak' + [char]0x0131 + 'l' + [char]0x0131 + 'r tak' + [char]0x0131 + 'lmaz kendili' + [char]0x011F + 'inden ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'mas' + [char]0x0131 + 'n' + [char]0x0131 + ' engeller. Dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'za her zamanki gibi eri' + [char]0x015F + 'irsiniz.')
    Ops = @(
        (RegOp 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer' 'NoDriveTypeAutoRun' 255),
        (RegOp 'HKCU\Software\Microsoft\Windows\CurrentVersion\Policies\Explorer' 'NoDriveTypeAutoRun' 255),
        (RegOp 'HKLM\SOFTWARE\Policies\Microsoft\Windows\Explorer' 'NoAutoplayfornonVolume' 1)
    )
}

Add-Tweak @{
