)

# Satirlari nesneye cevir
$script:SvcKb = New-Object System.Collections.ArrayList
$script:SvcKbRx = New-Object System.Collections.ArrayList
foreach ($ln in $script:SvcKbLines) {
    $f = $ln -split '::'
    if ($f.Count -lt 6) { continue }
    $e = @{ N = $f[0]; Rec = $f[1]; Risk = [int]$f[2]; Grp = $f[3]; What = $f[4]; IfOff = $f[5]; Cond = '' }
    if ($f.Count -ge 7) { $e.Cond = $f[6] }
    if ($e.N.StartsWith('~')) { $e.N = $e.N.Substring(1); [void]$script:SvcKbRx.Add($e) }
    else { [void]$script:SvcKb.Add($e) }
}
$script:SvcKbMap = @{}
foreach ($e in $script:SvcKb) { $script:SvcKbMap[$e.N.ToLowerInvariant()] = $e }

function Get-SvcKbEntry([string]$Name) {
    $k = $Name.ToLowerInvariant()
    if ($script:SvcKbMap.ContainsKey($k)) { return $script:SvcKbMap[$k] }
    foreach ($e in $script:SvcKbRx) { if ($Name -match $e.N) { return $e } }
    return $null
}

