# Hicbir kosulda kaldirilamaz (sistem, Magaza, codec, cerceveler)
$script:ProtectedApps = @(
    'Microsoft.WindowsStore', 'Microsoft.StorePurchaseApp', 'Microsoft.DesktopAppInstaller', 'Microsoft.Winget*',
    'Microsoft.VCLibs*', 'Microsoft.NET.*', 'Microsoft.UI.Xaml*', 'Microsoft.WindowsAppRuntime*', 'Microsoft.Services.Store*',
    'Microsoft.SecHealthUI', 'Microsoft.Windows.*', 'MicrosoftWindows.*', 'windows.*', 'Microsoft.WindowsCalculator',
    'Microsoft.ScreenSketch', 'Microsoft.WindowsNotepad', 'Microsoft.WindowsTerminal', 'Microsoft.Paint', 'Microsoft.*Extension*',
    'Microsoft.XboxIdentityProvider', 'Microsoft.Xbox.TCUI', 'Microsoft.AAD.BrokerPlugin', 'Microsoft.AccountsControl',
    'Microsoft.LockApp', 'Microsoft.MicrosoftEdge*', 'Microsoft.Edge*', 'Microsoft.Advertising.Xaml', 'Microsoft.ApplicationCompatibilityEnhancements',
    'Microsoft.WidgetsPlatformRuntime', 'Microsoft.StartExperiencesApp', 'Microsoft.CrossDevice', 'Microsoft.Win32WebViewHost'
)

function Test-ProtectedApp([string]$Name) {
    if ($Name -like 'Microsoft.Windows.DevHome' -or @($script:AppUnprotect) -contains $Name) { return $false }
    foreach ($pp in $script:ProtectedApps) { if ($Name -like $pp) { return $true } }
    return $false
}

# ---------------- baslangic programlari (Gorev Yoneticisi ile ayni mekanizma) ----------------
$script:StartupApprovedBase = 'Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\'

function Get-StartupItems {
    $items = New-Object System.Collections.ArrayList
    $ab = $script:StartupApprovedBase
    $sources = @(
        @{ Hive = 'HKCU'; Key = 'Software\Microsoft\Windows\CurrentVersion\Run'; Approved = ('HKCU\' + $ab + 'Run'); Src = ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' (Run)') },
        @{ Hive = 'HKLM'; Key = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Run'; Approved = ('HKLM\' + $ab + 'Run'); Src = ('T' + [char]0x00FC + 'm kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lar (Run)') },
        @{ Hive = 'HKLM'; Key = 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; Approved = ('HKLM\' + $ab + 'Run32'); Src = ('T' + [char]0x00FC + 'm kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lar (32 bit)') }
    )
    foreach ($s in $sources) {
        $parts = Split-RegPath ($s.Hive + '\' + $s.Key)
        $base = Get-RegBaseKey $parts[0]
        try {
            $k = $base.OpenSubKey($parts[1], $false)
            if ($null -ne $k) {
                foreach ($n in $k.GetValueNames()) {
                    if ([string]::IsNullOrEmpty($n)) { continue }
                    $cmd = [string]$k.GetValue($n, '', [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                    [void]$items.Add(@{ Name = $n; Command = $cmd; Approved = $s.Approved; Src = $s.Src; Enabled = $true; Kind = 'Run' })
                }
                $k.Close()
            }
        } catch { } finally { $base.Close() }
    }
    $folders = @(
        @{ Path = [Environment]::GetFolderPath('Startup'); Approved = ('HKCU\' + $ab + 'StartupFolder'); Src = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC) },
        @{ Path = [Environment]::GetFolderPath('CommonStartup'); Approved = ('HKLM\' + $ab + 'StartupFolder'); Src = ('Ortak ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC) }
    )
    foreach ($f in $folders) {
        if ([string]::IsNullOrEmpty($f.Path) -or -not (Test-Path -LiteralPath $f.Path)) { continue }
        foreach ($file in @(Get-ChildItem -LiteralPath $f.Path -Force -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer })) {
            if ($file.Name -ieq 'desktop.ini') { continue }
            [void]$items.Add(@{ Name = $file.Name; Command = $file.FullName; Approved = $f.Approved; Src = $f.Src; Enabled = $true; Kind = 'Folder' })
        }
    }
    foreach ($it in $items) {
        $info = Get-RegInfo $it.Approved $it.Name
        if ($info.Exists -and $info.Kind -eq 'Binary' -and @($info.Value).Count -gt 0) {
            $it.Enabled = (((([byte[]]$info.Value)[0]) -band 1) -eq 0)
        }
    }
    return , $items
}

# Bir baslangic ogesini acma/kapama islemi (Reg op; geri alma kitine yazilir)
function New-StartupOp($Item, [bool]$Enable) {
    $bytes = New-Object 'byte[]' 12
    if ($Enable) { $bytes[0] = 2 }
    else {
        $bytes[0] = 3
        $ft = [BitConverter]::GetBytes([int64](Get-Date).ToFileTimeUtc())
        for ($i = 0; $i -lt 8; $i++) { $bytes[4 + $i] = $ft[$i] }
    }
    return @{ T = 'Reg'; Path = [string]$Item.Approved; Name = [string]$Item.Name; Kind = 'Binary'; Value = $bytes }
}

# Oturum acilisinda calisan zamanlanmis gorevler (Microsoft disi olanlar)
function Get-LogonTasks {
    $list = New-Object System.Collections.ArrayList
    try {
        foreach ($t in @(Get-ScheduledTask -ErrorAction Stop)) {
            if ($t.TaskPath -like '\Microsoft\*') { continue }
            $trg = @($t.Triggers | Where-Object { $_.CimClass.CimClassName -match 'Logon|Boot' })
            if ($trg.Count -eq 0) { continue }
            $cmd = ''
            try { $a = $t.Actions | Select-Object -First 1; $cmd = ((([string]$a.Execute) + ' ' + ([string]$a.Arguments))).Trim() } catch { }
            [void]$list.Add(@{ Name = [string]$t.TaskName; Path = [string]$t.TaskPath; Command = $cmd; Enabled = ([string]$t.State -ne 'Disabled'); Src = ('Zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'rev'); Kind = 'Task' })
        }
    } catch { }
    return , $list
}

# ---------------- yuklu programlar (Programlar ve Ozellikler listesi) ----------------
function Get-InstalledPrograms {
    $list = New-Object System.Collections.ArrayList
    $seen = @{}
    $roots = @(
        @{ Hive = 'HKLM'; Key = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall' },
        @{ Hive = 'HKLM'; Key = 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall' },
        @{ Hive = 'HKCU'; Key = 'Software\Microsoft\Windows\CurrentVersion\Uninstall' }
    )
    foreach ($r in $roots) {
        $path = $r.Hive + '\' + $r.Key
        foreach ($sub in (Get-RegSubKeyNames $path)) {
            $kp = $path + '\' + $sub
            $dn = [string](Get-RegValue $kp 'DisplayName' '')
            if ($dn -eq '') { continue }
            if ([int](Get-RegValue $kp 'SystemComponent' 0) -eq 1) { continue }
            if ([string](Get-RegValue $kp 'ParentKeyName' '') -ne '') { continue }
            $ver = [string](Get-RegValue $kp 'DisplayVersion' '')
            $uk = $dn.ToLowerInvariant() + '|' + $ver
            if ($seen.ContainsKey($uk)) { continue }
            $seen[$uk] = $true
            $sz = [double](Get-RegValue $kp 'EstimatedSize' 0) * 1024
            $dt = [string](Get-RegValue $kp 'InstallDate' '')
            if ($dt -match '^\d{8}$') { $dt = $dt.Substring(0, 4) + '-' + $dt.Substring(4, 2) + '-' + $dt.Substring(6, 2) }
            [void]$list.Add(@{
                Name = $dn; Version = $ver; Publisher = [string](Get-RegValue $kp 'Publisher' ''); Date = $dt; Size = $sz
                Uninstall = [string](Get-RegValue $kp 'UninstallString' ''); Quiet = [string](Get-RegValue $kp 'QuietUninstallString' '')
                Location = [string](Get-RegValue $kp 'InstallLocation' ''); Key = $sub
            })
        }
    }
    return , @($list | Sort-Object { $_.Name.ToLowerInvariant() })
}

