    @{ N = ('Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i');       C = 'windowsdefender:';  A = '';                  D = ('Vir' + [char]0x00FC + 's ve tehdit korumas' + [char]0x0131 + ', g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + '.') },
    @{ N = ('A' + [char]0x011F + ' Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar' + [char]0x0131);         C = 'ncpa.cpl';          A = '';                  D = ('A' + [char]0x011F + ' kart' + [char]0x0131 + ' ayarlar' + [char]0x0131 + '.') },
    @{ N = ('Programlar ve ' + [char]0x00D6 + 'zellikler'); C = 'appwiz.cpl';       A = '';                  D = ('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' programlar' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'n.') },
    @{ N = ('G' + [char]0x00FC + [char]0x00E7 + ' Se' + [char]0x00E7 + 'enekleri');         C = 'powercfg.cpl';      A = '';                  D = ('G' + [char]0x00FC + [char]0x00E7 + ' planlar' + [char]0x0131 + '.') },
    @{ N = ('DirectX Tan' + [char]0x0131 + 'lama');        C = 'dxdiag.exe';        A = '';                  D = ('Ekran kart' + [char]0x0131 + ' ve ses tan' + [char]0x0131 + 'lama.') },
    @{ N = ('Yerel Grup ' + [char]0x0130 + 'lkesi');       C = 'gpedit.msc';        A = '';                  D = ('Yaln' + [char]0x0131 + 'zca Pro/Enterprise s' + [char]0x00FC + 'r' + [char]0x00FC + 'mlerinde bulunur.') },
    @{ N = ('Yerel Kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lar ve Gruplar'); C = 'lusrmgr.msc'; A = '';                  D = ('Yaln' + [char]0x0131 + 'zca Pro/Enterprise s' + [char]0x00FC + 'r' + [char]0x00FC + 'mlerinde bulunur.') },
    @{ N = ('Geli' + [char]0x015F + 'mi' + [char]0x015F + ' G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131); C = 'wf.msc';           A = '';                  D = ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kurallar' + [char]0x0131 + 'n' + [char]0x0131 + ' inceleyin.') },
    @{ N = ('Zamanlanm' + [char]0x0131 + [char]0x015F + ' G' + [char]0x00F6 + 'revler');    C = 'taskschd.msc';      A = '';                  D = ('Otomatik ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'an g' + [char]0x00F6 + 'revler.') },
    @{ N = 'BitLocker';               C = 'control.exe';       A = '/name Microsoft.BitLockerDriveEncryption'; D = ('Disk ' + [char]0x015F + 'ifreleme durumu.') }
)

# ==================================================================
#  ISLER (A): katalog yardimcilari, plan/geri alma/onarim, hizmetler, uygulamalar, baslangic, temizlik, bakim
#  Her is Job_Xxx($P) bicimindedir; arka plan is parcaciginda ($J paylasimli ilerleme tablosu) ya da
#  komut satiri kipinde dogrudan calisir. $sync.Profile sistem profilini tasir.
# ==================================================================

# ---------------- katalog yardimcilari ----------------
function Test-WhenOk([string]$When, $Pr) {
    if ($null -eq $Pr) { return $true }
    if ($When -eq 'HDD') { return ($Pr.DiskType -eq 'HDD') }
    if ($When -eq 'SSD') { return ($Pr.DiskType -eq 'SSD') }
    if ($When -eq 'Desktop') { return (-not $Pr.IsLaptop) }
    if ($When -eq 'Laptop') { return ([bool]$Pr.IsLaptop) }
    return $true
}

function Test-OsOk([string]$OS, $Pr) {
    if ($null -eq $Pr -or $OS -eq '' -or $OS -eq 'All') { return $true }
    return ($OS -eq [string]$Pr.WinMajor)
}

function Get-CatalogItem([string]$Id) {
    foreach ($c in $script:Catalog) { if ($c.Id -eq $Id) { return $c } }
    return $null
}

# Sayfa: opt | sec | org   (Kategori bos birakilirsa hepsi)
function Get-CatalogFor([string]$Page, [string]$Cat, $Pr) {
    $r = New-Object System.Collections.ArrayList
    foreach ($c in $script:Catalog) {
        if ($Page -ne '' -and $c.Page -ne $Page) { continue }
        if ($Cat -ne '' -and $c.Cat -ne $Cat) { continue }
        if (-not (Test-OsOk $c.OS $Pr)) { continue }
        [void]$r.Add($c)
    }
    return , $r.ToArray()
}

# Hazir profil: Level 1..3 (Level 4 hicbir profilde secilmez)
function Get-PresetIds([int]$Level, [string]$Page, $Pr) {
    $ids = New-Object System.Collections.ArrayList
    foreach ($c in (Get-CatalogFor $Page '' $Pr)) {
        if ($c.Level -ge 1 -and $c.Level -le $Level -and (Test-WhenOk $c.When $Pr)) { [void]$ids.Add([string]$c.Id) }
    }
    return , $ids.ToArray()
}

function New-StepsFromIds([string[]]$Ids) {
    $steps = New-Object System.Collections.ArrayList
    foreach ($id in @($Ids)) {
        $c = Get-CatalogItem $id
        if ($null -eq $c) { continue }
        [void]$steps.Add(@{ Id = $c.Id; Title = $c.Title; Ops = @($c.Ops); Reboot = [bool]$c.Reboot })
    }
    return , $steps.ToArray()
}

# ---------------- ortak calistirma yardimcilari ----------------
function Reset-Counters {
    $script:Changes = 0; $script:Skipped = 0; $script:Errors = 0
    $script:FreedBytes = 0.0; $script:Provisioned = $null; $script:CapWarned = $false
}

function Write-Thanks {
    Write-Raw ''
    Write-Raw ('  ' + ('=' * 34))
    Write-Raw ('   Te' + [char]0x015F + 'ekk' + [char]0x00FC + 'rler.   Multimizer   ')
    Write-Raw ('   ' + (Get-SigLine))
    Write-Raw ('  ' + ('=' * 34))
}

function Get-RunSummary([string]$What, [datetime]$Start) {
    $sec = ((Get-Date) - $Start).TotalSeconds
    $t = (('{0}: {1} de' + [char]0x011F + 'i' + [char]0x015F + 'iklik, {2} atland' + [char]0x0131 + ', {3} hata, {4}') -f $What, $script:Changes, $script:Skipped, $script:Errors, (Format-Duration $sec))
    if ($script:FreedBytes -gt 0) { $t += (', ' + (Format-Size $script:FreedBytes) + (' yer a' + [char]0x00E7 + [char]0x0131 + 'ld' + [char]0x0131)) }
    return $t
}

function Job_Plan($P) {
    Reset-Counters
    $script:Preview = [bool]$P.Preview
    $t0 = Get-Date
    $title = 'UYGULAMA'
    if ($script:Preview) { $title = ([string][char]0x00D6 + 'N' + [char]0x0130 + 'ZLEME (sistemde hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'mez)') }
    Write-WhLog ('--- ' + $title + ' ---') 'STEP'
    Invoke-Plan $P.Steps ([bool]$P.RestorePoint)
    if (-not $script:Preview) { try { [void](Update-AppliedAfterPlan $P.Steps) } catch { Write-LogFile ('Dogrulama atlandi: ' + $_.Exception.Message) } }
    $sum = Get-RunSummary $(if ($script:Preview) { ([string][char]0x00D6 + 'nizleme') } else { ('Tamamland' + [char]0x0131) }) $t0
    Write-WhLog $sum 'INFO'
    $reboot = $false
    foreach ($s in @($P.Steps)) { if ($s.Reboot -eq $true) { $reboot = $true } }
    if ($reboot -and -not $script:Preview -and $script:Changes -gt 0) { Write-WhLog ('Baz' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerin etkili olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') 'WARN' }
    if (-not $script:Preview) { Write-Thanks }
    return @{ Changes = $script:Changes; Skipped = $script:Skipped; Errors = $script:Errors; Freed = $script:FreedBytes; Preview = $script:Preview; Reboot = ($reboot -and -not $script:Preview); Summary = $sum }
}

function Job_Undo($P) {
    Reset-Counters
    $script:Preview = $false
    $t0 = Get-Date
    Invoke-Undo ([string]$P.File)
    try { Update-AppliedAfterUndo } catch { Write-LogFile ('Kayit guncellenemedi: ' + $_.Exception.Message) }
    $sum = Get-RunSummary 'Geri alma' $t0
    Write-WhLog $sum 'INFO'
    Write-Thanks
    return @{ Changes = $script:Changes; Errors = $script:Errors; Summary = $sum }
}

function Job_Repair($P) {
    Reset-Counters
    $t0 = Get-Date
    $keys = @($script:RepairSteps.Keys | Where-Object { $P.ContainsKey([string]$_) })
    $res = Invoke-Repair (Get-RepairSet $keys)
    Write-WhLog (('Onar' + [char]0x0131 + 'm tamamland' + [char]0x0131 + ': ') + (Format-Duration (((Get-Date) - $t0).TotalSeconds))) 'INFO'
    Write-Thanks
    return @{ Results = $res }
}

# ---------------- hizmetler ----------------
function Get-SvcContext {
    $pr = $sync.Profile
    $c = @{ Desktop = $true; NotManaged = $true; HDD = $false; NoPrinter = $false; NoBluetooth = $false; NoTouch = $false; NoXbox = $false; NoShares = $false }
    if ($null -ne $pr) {
        $c.Desktop = (-not $pr.IsLaptop)
        $c.NotManaged = (-not $pr.IsManaged)
        $c.HDD = ($pr.DiskType -eq 'HDD')
    }
    try {
        $pl = @(Get-CimInstance -ClassName Win32_Printer -ErrorAction Stop | Where-Object { [string]$_.Name -notmatch '(?i)pdf|xps|onenote|fax|send to|anydesk|cutepdf|dopdf' })
        $c.NoPrinter = ($pl.Count -eq 0)
    } catch { }
    try {
        $radio = @(Get-PnpDevice -Class Bluetooth -PresentOnly -ErrorAction Stop | Where-Object { [string]$_.InstanceId -match '^(USB|PCI|ACPI|SD)\\' })
        $paired = (Get-RegSubKeyNames 'HKLM\SYSTEM\CurrentControlSet\Services\BTHPORT\Parameters\Devices').Count
        $c.NoBluetooth = ($radio.Count -eq 0 -and $paired -eq 0)
    } catch { }
    try {
        if (-not ('Wh.Native' -as [type])) {
            Add-Type -Namespace Wh -Name Native -MemberDefinition '[System.Runtime.InteropServices.DllImport("user32.dll")] public static extern int GetSystemMetrics(int nIndex);'
        }
        $dg = [Wh.Native]::GetSystemMetrics(94)
        $c.NoTouch = (($dg -band 0x0F) -eq 0)
    } catch { }
    try {
        $xb = @(Get-AppxPackage -ErrorAction Stop | Where-Object { [string]$_.Name -match 'Minecraft|Forza|Halo|Gears|FlightSimulator|AgeOf|SeaOfThieves|Grounded|Hellblade|Starfield' })
        $c.NoXbox = ($xb.Count -eq 0)
    } catch { }
    try {
        $sh = @(Get-SmbShare -ErrorAction Stop | Where-Object { -not $_.Special })
        $c.NoShares = ($sh.Count -eq 0)
    } catch { }
    return $c
}

$script:CondNotes = @{
    NoPrinter = ('Bu bilgisayarda yaz' + [char]0x0131 + 'c' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor; dokunmay' + [char]0x0131 + 'n.')
    NoBluetooth = ('Bluetooth donan' + [char]0x0131 + 'm' + [char]0x0131 + ' veya e' + [char]0x015F + 'le' + [char]0x015F + 'mi' + [char]0x015F + ' cihaz var; dokunmay' + [char]0x0131 + 'n.')
    NoTouch = ('Dokunmatik ekran veya kalem alg' + [char]0x0131 + 'land' + [char]0x0131 + '; dokunmay' + [char]0x0131 + 'n.')
    Desktop = ('Bu bir diz' + [char]0x00FC + 'st' + [char]0x00FC + '/tablet; bu hizmet i' + [char]0x015F + 'e yarayabilir.')
    NotManaged = ('Bu bilgisayar kurum taraf' + [char]0x0131 + 'ndan y' + [char]0x00F6 + 'netiliyor; dokunmay' + [char]0x0131 + 'n.')
    NoXbox = ('Xbox/Store oyunlar' + [char]0x0131 + ' y' + [char]0x00FC + 'kl' + [char]0x00FC + '; dokunmay' + [char]0x0131 + 'n.')
    HDD = ('Disk SSD; bu ayar' + [char]0x0131 + 'n kazanc' + [char]0x0131 + ' yok, dokunmay' + [char]0x0131 + 'n.')
    NoShares = ('Bu bilgisayarda a' + [char]0x011F + ' payla' + [char]0x015F + [char]0x0131 + 'm' + [char]0x0131 + ' var; dokunmay' + [char]0x0131 + 'n.')
}

function Get-ServiceRows {
    $ctx = Get-SvcContext
    $cim = @(Get-CimInstance -ClassName Win32_Service -ErrorAction Stop)
    $byName = @{}
    $rows = New-Object System.Collections.ArrayList
    Set-JobProgress 0 $cim.Count 'Hizmetler okunuyor'
    foreach ($s in $cim) {
        Step-JobProgress
        $name = [string]$s.Name
        $disp = [string]$s.DisplayName
        $tpl = Get-SvcTemplateName $name
        $isUser = ($tpl -ne $name)
        if ($isUser) { $name = $tpl; $disp = ($disp -replace '_[0-9a-fA-F]{4,8}$', '') }
        if ($byName.ContainsKey($name)) {
            if ([string]$s.State -eq 'Running') { $byName[$name].State = 'Running' }
            continue
        }
        $mode = [string]$s.StartMode
        $delayed = $false
        try { $delayed = ([bool]$s.DelayedAutoStart) } catch { }
        if ($isUser) {
            $si = Get-SvcStartInfo $name
            if ($null -ne $si.Start) {
                if ($si.Start -eq 2) { $mode = 'Auto' } elseif ($si.Start -eq 3) { $mode = 'Manual' } elseif ($si.Start -eq 4) { $mode = 'Disabled' }
            }
        }
        $path = [string]$s.PathName
        $isMs = ($path.ToLowerInvariant() -cmatch '\\windows\\|\\windows defender\\|\\microsoft\\|\\windowsapps\\|svchost\.exe|^"?[a-z]:\\windows')
        $locked = (Test-SvcLocked $name)
        $kb = Get-SvcKbEntry $name
        $rec = 'Keep'; $risk = 2; $grp = 'Sistem'; $what = ''; $ifoff = ''; $note = ''
        $desc = [string]$s.Description
        if ($locked) {
            $rec = 'Lock'; $risk = 3
            $what = $desc; $ifoff = ('Bu hizmet Windows' + [char]0x2019 + 'un g' + [char]0x00FC + 'venlik ve ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'ma omurgas' + [char]0x0131 + 'n' + [char]0x0131 + 'n par' + [char]0x00E7 + 'as' + [char]0x0131 + 'd' + [char]0x0131 + 'r; ara' + [char]0x00E7 + ' ona dokunmaz.')
        } elseif ($null -ne $kb) {
            $rec = $kb.Rec; $risk = $kb.Risk; $grp = $kb.Grp; $what = $kb.What; $ifoff = $kb.IfOff
            if ($kb.Cond -ne '' -and $ctx[$kb.Cond] -ne $true) { $rec = 'Keep'; $note = [string]$script:CondNotes[$kb.Cond] }
        } else {
            $what = $desc
            if ($isMs) { $rec = 'Keep'; $grp = 'Sistem'; $ifoff = ('Bilinmeyen Microsoft hizmeti: dokunmaman' + [char]0x0131 + 'z ' + [char]0x00F6 + 'nerilir.') }
            else { $rec = 'Rev'; $grp = ([string][char]0x00DC + [char]0x00E7 + [char]0x00FC + 'nc' + [char]0x00FC + ' taraf'); $ifoff = ([string][char]0x00DC + [char]0x00E7 + [char]0x00FC + 'nc' + [char]0x00FC + ' taraf hizmet: ait oldu' + [char]0x011F + 'u program' + [char]0x0131 + ' kullan' + [char]0x0131 + 'p kullanmad' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + 'za g' + [char]0x00F6 + 're kendiniz karar verin.') }
        }
        # H?lihazirda onerilen duruma gelmis mi?
        $done = $false
        if ($rec -eq 'Off' -and $mode -eq 'Disabled') { $done = $true }
        if ($rec -eq 'Man' -and ($mode -eq 'Manual' -or $mode -eq 'Disabled')) { $done = $true }
        $row = @{
            Name = $name; Display = $disp; State = [string]$s.State; Mode = $mode; Delayed = $delayed; Account = [string]$s.StartName
            Path = $path; Desc = $desc; IsMs = $isMs; Locked = $locked; Rec = $rec; Risk = $risk; Grp = $grp
            What = $what; IfOff = $ifoff; Note = $note; Done = $done; PerUser = $isUser
        }
        $byName[$name] = $row
        [void]$rows.Add($row)
    }
    $rank = @{ Off = 0; Man = 1; Org = 2; Rev = 3; Keep = 4; Lock = 5 }
    $sorted = @($rows | Sort-Object @{ Expression = { $rank[[string]$_.Rec] } }, @{ Expression = { ([string]$_.Display).ToLowerInvariant() } })
    return , $sorted
}

function Job_Services($P) {
    $rows = Get-ServiceRows
    Write-WhLog ('Hizmetler okundu: ' + $rows.Count) 'INFO'
    return @{ Rows = $rows }
}

# Secili hizmetlerden islem listesi olusturur. Mode: Off | Man | Auto
function New-ServiceSteps($Names, [string]$Mode) {
    $ops = New-Object System.Collections.ArrayList
    $start = 'Disabled'
    if ($Mode -eq 'Man') { $start = 'Manual' } elseif ($Mode -eq 'Auto') { $start = 'Auto' }
    foreach ($n in @($Names)) { [void]$ops.Add(@{ T = 'Svc'; Name = [string]$n; Start = $start }) }
    $t = ('Se' + [char]0x00E7 + 'ili hizmetler: devre d' + [char]0x0131 + [char]0x015F + [char]0x0131)
    if ($Mode -eq 'Man') { $t = ('Se' + [char]0x00E7 + 'ili hizmetler: el ile') } elseif ($Mode -eq 'Auto') { $t = ('Se' + [char]0x00E7 + 'ili hizmetler: otomatik') }
    return , @(@{ Id = 'Services'; Title = $t; Ops = $ops.ToArray(); Reboot = $false })
}

# Hizmeti hemen baslat/durdur/yeniden baslat (baslangic turunu degistirmez)
function Job_ServiceAction($P) {
    $name = [string]$P.Name
    if (Test-SvcLocked $name) { Write-WhLog (('Korumal' + [char]0x0131 + ' hizmet: ') + $name) 'WARN'; return @{ Ok = $false } }
    try {
        switch ([string]$P.Action) {
            'Start'   { Start-Service -Name $name -ErrorAction Stop; Write-WhLog (('Hizmet ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $name) 'OK' }
            'Stop'    { Stop-Service -Name $name -Force -ErrorAction Stop; Write-WhLog ('Hizmet durduruldu: ' + $name) 'OK' }
            'Restart' { Restart-Service -Name $name -Force -ErrorAction Stop; Write-WhLog (('Hizmet yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $name) 'OK' }
        }
        return @{ Ok = $true }
    } catch {
        Write-WhLog (('Hizmet i' + [char]0x015F + 'lemi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (') + $name + '): ' + $_.Exception.Message) 'ERR'
        return @{ Ok = $false }
    }
}

# ---------------- Magaza uygulamalari ----------------
function Job_Apps($P) {
    $pk = @(Get-AppxSafe)
    $rows = New-Object System.Collections.ArrayList
    $used = @{}
    foreach ($a in $script:AppCatalog) {
        $m = @($pk | Where-Object { ([string]$_.Name) -like $a.P -and -not (Test-ProtectedApp ([string]$_.Name)) -and $_.NonRemovable -ne $true -and -not $used.ContainsKey([string]$_.PackageFullName) })
        if ($m.Count -eq 0) { continue }
        foreach ($x in $m) { $used[[string]$x.PackageFullName] = $true }
        [void]$rows.Add(@{ Pattern = $a.P; Display = $a.N; Pkg = [string]$m[0].Name; Count = $m.Count; R = [bool]$a.R; C = [bool]$a.C })
    }
    Write-WhLog (('Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir Ma' + [char]0x011F + 'aza uygulamas' + [char]0x0131 + ': ') + $rows.Count) 'INFO'
    return @{ Rows = $rows.ToArray() }
}

# ---------------- baslangic ----------------
function Get-CommandExe([string]$Cmd) {
    $c = [Environment]::ExpandEnvironmentVariables($Cmd.Trim())
    if ($c -match '^"([^"]+)"') { return $Matches[1] }
    if ($c -match '^(.+?\.(exe|bat|cmd|com|lnk|msc|vbs|ps1))(\s|$)') { return $Matches[1] }
    return $c
}

function Job_Startup($P) {
    $items = Get-StartupItems
    $tasks = Get-LogonTasks
    $rows = New-Object System.Collections.ArrayList
    $all = @($items) + @($tasks)
    Set-JobProgress 0 $all.Count ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' ' + [char]0x00F6 + [char]0x011F + 'eleri')
    foreach ($it in $all) {
        Step-JobProgress
        $exe = Get-CommandExe ([string]$it.Command)
        $pub = ''
        $exists = $false
        try {
            if ($exe -ne '' -and (Test-Path -LiteralPath $exe -PathType Leaf)) {
                $exists = $true
                $vi = (Get-Item -LiteralPath $exe -ErrorAction Stop).VersionInfo
                $pub = ([string]$vi.CompanyName).Trim()
            }
        } catch { }
        $it.Publisher = $pub; $it.Exists = $exists; $it.Exe = $exe
        $it.IsMs = ($pub -match 'Microsoft')
        [void]$rows.Add($it)
    }
    $sorted = @($rows | Sort-Object @{ Expression = { if ($_.Enabled) { 0 } else { 1 } } }, @{ Expression = { ([string]$_.Name).ToLowerInvariant() } })
    return @{ Rows = $sorted }
}

function Job_Programs($P) {
    $list = Get-InstalledPrograms
    Write-WhLog (('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' program: ') + @($list).Count) 'INFO'
    return @{ Rows = $list }
}

# ---------------- dizin boyutu (robocopy ozeti; dile bagli degil) ----------------
function Get-DirSizeFast([string]$Path) {
    $nul = Join-Path $env:TEMP 'wh_null_dest'
    $out = @(& robocopy.exe $Path $nul /L /E /BYTES /NJH /NP /NFL /NDL /R:0 /W:0 /XJ 2>&1)
    $nums = New-Object System.Collections.ArrayList
    foreach ($l in $out) {
        $s = [string]$l
        if ($s -match ':\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*$') { [void]$nums.Add(@([double]$Matches[1], [double]$Matches[2], [double]$Matches[3])) }
    }
    if ($nums.Count -ge 3) { return @{ Dirs = $nums[0][0]; Files = $nums[1][0]; Bytes = $nums[2][0] } }
    return @{ Dirs = 0; Files = 0; Bytes = 0.0 }
}

function Get-RecycleBinSize {
    $bytes = 0.0; $count = 0
    try {
        $sh = New-Object -ComObject Shell.Application
        $bin = $sh.NameSpace(10)
        foreach ($i in @($bin.Items())) { $bytes += [double]$i.Size; $count++ }
    } catch { }
    return @{ Bytes = $bytes; Count = $count }
}

# ---------------- temizlik taramasi (hicbir sey silmez) ----------------
function Job_CleanScan($P) {
    Reset-Counters
    $script:Preview = $true
    $res = New-Object System.Collections.ArrayList
    $defs = @(
        @{ Id = 'Temp'; N = ('Ge' + [char]0x00E7 + 'ici dosyalar'); Fn = 'Invoke-CleanTemp' },
        @{ Id = 'Browsers'; N = ('Taray' + [char]0x0131 + 'c' + [char]0x0131 + ' ' + [char]0x00F6 + 'nbellekleri'); Fn = 'Invoke-CleanBrowsers' },
        @{ Id = 'WerFiles'; N = ('Hata raporlama dosyalar' + [char]0x0131); Fn = 'Invoke-CleanWer' },
        @{ Id = 'Logs'; N = ('Eski sistem g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kleri'); Fn = 'Invoke-CleanLogs' },
        @{ Id = 'UpdCache'; N = ('Windows Update ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i'); Fn = 'Invoke-CleanUpdateCache' },
        @{ Id = 'Dumps'; N = ('Hata d' + [char]0x00F6 + 'k' + [char]0x00FC + 'mleri'); Fn = 'Invoke-CleanDumps' }
    )
    if ($null -ne $script:CleanExtraDefs) { $defs = @($defs) + @($script:CleanExtraDefs) }
    Set-JobProgress 0 ($defs.Count + 2) ('Taran' + [char]0x0131 + 'yor')
    foreach ($d in $defs) {
        if (Test-JobCancel) { break }
        $script:LastClean = @{ Bytes = 0.0; Count = 0 }
        try { & $d.Fn } catch { Write-WhLog (('Taranamad' + [char]0x0131 + ': ') + $d.N + ' - ' + $_.Exception.Message) 'WARN' }
        $b = [double]$script:LastClean.Bytes
        if ($d.Id -eq 'UpdCache') {
            $files = Get-FilesSafe (Join-Path $env:WINDIR 'SoftwareDistribution\Download') ([datetime]::MaxValue)
            $b = 0.0; foreach ($f in $files) { $b += [double]$f.Length }
        }
        [void]$res.Add(@{ Id = $d.Id; Name = $d.N; Bytes = $b; Count = [int]$script:LastClean.Count })
        Step-JobProgress
    }
    $rb = Get-RecycleBinSize
    [void]$res.Add(@{ Id = 'Recycle'; Name = ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu'); Bytes = $rb.Bytes; Count = $rb.Count })
    Step-JobProgress
    $wo = Join-Path $env:SystemDrive 'Windows.old'
    if (Test-Path -LiteralPath $wo) {
        $sz = Get-DirSizeFast $wo
        [void]$res.Add(@{ Id = 'WinOld'; Name = 'Eski Windows kurulumu (Windows.old)'; Bytes = $sz.Bytes; Count = [int]$sz.Files })
    }
    Step-JobProgress
    $total = 0.0
    foreach ($r in $res) { $total += [double]$r.Bytes }
    Write-WhLog (('Temizlenebilir alan: yakla' + [char]0x015F + [char]0x0131 + 'k ') + (Format-Size $total)) 'INFO'
    return @{ Rows = $res.ToArray(); Total = $total }
}

# Disk analizi: bir klasorun alt klasorlerini boyuta gore siralar
function Job_DiskUsage($P) {
    $root = [string]$P.Path
    if (-not (Test-Path -LiteralPath $root)) { Write-WhLog (('Klas' + [char]0x00F6 + 'r yok: ') + $root) 'ERR'; return @{ Rows = @() } }
    $dirs = @(Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue | Where-Object { ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq 0 })
    Set-JobProgress 0 ($dirs.Count + 1) ('Boyutlar hesaplan' + [char]0x0131 + 'yor')
    $rows = New-Object System.Collections.ArrayList
    $loose = 0.0
    foreach ($f in @(Get-ChildItem -LiteralPath $root -File -Force -ErrorAction SilentlyContinue)) { $loose += [double]$f.Length }
    [void]$rows.Add(@{ Name = ('(bu klas' + [char]0x00F6 + 'rdeki dosyalar)'); Path = $root; Bytes = $loose; Files = 0 })
    Step-JobProgress
    foreach ($d in $dirs) {
        if (Test-JobCancel) { break }
        $sz = Get-DirSizeFast $d.FullName
        [void]$rows.Add(@{ Name = $d.Name; Path = $d.FullName; Bytes = $sz.Bytes; Files = $sz.Files })
        Step-JobProgress (('Hesapland' + [char]0x0131 + ': ') + $d.Name)
    }
    $sorted = @($rows | Sort-Object { -1 * [double]$_.Bytes })
    return @{ Rows = $sorted }
}

# ---------------- bakim (komut satiri -Gorev Bakim ve arayuzde "Hizli bakim") ----------------
function Job_Maint($P) {
    Reset-Counters
    $script:Preview = [bool]$P.Preview
    $t0 = Get-Date
    $st = Get-Settings
    $ids = @($P.Items)
    if ($ids.Count -eq 0) { $ids = @($st.MaintItems) }
    $ok = New-Object System.Collections.ArrayList
    foreach ($id in $ids) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -ne $c -and $c.Cat -eq 'Temizlik' -and (Test-WhenOk $c.When $sync.Profile)) { [void]$ok.Add([string]$id) }
    }
    Write-WhLog (('=== Bak' + [char]0x0131 + 'm: ') + ($ok -join ', ')) 'STEP'
    Invoke-Plan (New-StepsFromIds $ok.ToArray()) $false
    $sum = Get-RunSummary ('Bak' + [char]0x0131 + 'm') $t0
    Write-WhLog $sum 'INFO'
    if (-not $script:Preview) {
        $st.LastMaint = (Get-Date).ToString('yyyy-MM-dd HH:mm')
        Save-Settings $st
        Write-Thanks
    }
    return @{ Changes = $script:Changes; Errors = $script:Errors; Freed = $script:FreedBytes; Summary = $sum }
}

# ==================================================================
#  ISLER (B): Windows Update (COM), winget (program guncelleme/kurulum), bekleyen yeniden baslatma
#  Windows Update ASLA kapatilmaz; burada yalnizca denetlenir ve istege bagli olarak kurulur.
# ==================================================================

function Get-PendingReboot {
    $r = New-Object System.Collections.ArrayList
    if ((Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update') -contains 'RebootRequired') { [void]$r.Add('Windows Update') }
    if ((Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing') -contains 'RebootPending') { [void]$r.Add(('Bile' + [char]0x015F + 'en servisi')) }
    $pf = Get-RegValue 'HKLM\SYSTEM\CurrentControlSet\Control\Session Manager' 'PendingFileRenameOperations' $null
    if ($null -ne $pf -and (Test-PendingRenameReal $pf)) { [void]$r.Add(('Bekleyen dosya i' + [char]0x015F + 'lemleri')) }
    return , $r.ToArray()
}

# ---------------- Windows Update ----------------
function Job_WuSearch($P) {
    Write-WhLog ('Windows Update taran' + [char]0x0131 + 'yor (1-3 dakika s' + [char]0x00FC + 'rebilir)...') 'INFO'
    $sess = New-Object -ComObject Microsoft.Update.Session
    $sess.ClientApplicationID = 'Multimizer'
    $searcher = $sess.CreateUpdateSearcher()
    $res = $searcher.Search('IsInstalled=0 and IsHidden=0')
    $rows = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt $res.Updates.Count; $i++) {
        $u = $res.Updates.Item($i)
        $cats = @()
        for ($k = 0; $k -lt $u.Categories.Count; $k++) { $cats += [string]$u.Categories.Item($k).Name }
        $kb = ''
        if ($u.KBArticleIDs.Count -gt 0) { $kb = 'KB' + [string]$u.KBArticleIDs.Item(0) }
        $reboot = $false
        try { $reboot = ([int]$u.InstallationBehavior.RebootBehavior -ne 0) } catch { }
        [void]$rows.Add(@{
            Id = [string]$u.Identity.UpdateID; Title = [string]$u.Title; KB = $kb; Size = [double]$u.MaxDownloadSize
            Severity = [string]$u.MsrcSeverity; Cats = ($cats -join ', '); IsDriver = ([int]$u.Type -eq 2)
            Downloaded = [bool]$u.IsDownloaded; Reboot = $reboot; Mandatory = [bool]$u.IsMandatory
        })
    }
    Write-WhLog (('Bekleyen g' + [char]0x00FC + 'ncelleme: ') + $rows.Count) 'INFO'
    $pend = Get-PendingReboot
    if ($pend.Count -gt 0) { Write-WhLog (('Yeniden ba' + [char]0x015F + 'latma bekliyor: ') + ($pend -join ', ')) 'WARN' }
    return @{ Rows = $rows.ToArray(); PendingReboot = $pend }
}

function Job_WuInstall($P) {
    $want = @($P.Ids)
    if ($want.Count -eq 0) { Write-WhLog ('G' + [char]0x00FC + 'ncelleme se' + [char]0x00E7 + 'ilmedi.') 'WARN'; return @{ Ok = $false } }
    Reset-Counters
    $sess = New-Object -ComObject Microsoft.Update.Session
    $sess.ClientApplicationID = 'Multimizer'
    $res = $sess.CreateUpdateSearcher().Search('IsInstalled=0 and IsHidden=0')
    $coll = New-Object -ComObject Microsoft.Update.UpdateColl
    for ($i = 0; $i -lt $res.Updates.Count; $i++) {
        $u = $res.Updates.Item($i)
        if ($want -contains [string]$u.Identity.UpdateID) {
            if (-not $u.EulaAccepted) { try { $u.AcceptEula() } catch { } }
            [void]$coll.Add($u)
        }
    }
    if ($coll.Count -eq 0) { Write-WhLog ('Se' + [char]0x00E7 + 'ilen g' + [char]0x00FC + 'ncellemeler art' + [char]0x0131 + 'k listede yok.') 'WARN'; return @{ Ok = $false } }
    Set-JobProgress 0 ($coll.Count * 2) ([string][char]0x0130 + 'ndiriliyor')
    Write-WhLog (([string][char]0x0130 + 'ndiriliyor: ') + $coll.Count + (' g' + [char]0x00FC + 'ncelleme...')) 'INFO'
    $dl = $sess.CreateUpdateDownloader()
    $dl.Updates = $coll
    $dr = $dl.Download()
    Set-JobProgress $coll.Count ($coll.Count * 2) 'Kuruluyor'
    if ([int]$dr.ResultCode -ge 4) { Write-WhLog (([string][char]0x0130 + 'ndirme ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (kod ') + [int]$dr.ResultCode + ')') 'ERR'; return @{ Ok = $false } }
    Write-WhLog ('Kuruluyor (bu s' + [char]0x0131 + 'rada bilgisayar' + [char]0x0131 + ' kapatmay' + [char]0x0131 + 'n)...') 'INFO'
    $inst = $sess.CreateUpdateInstaller()
    $inst.Updates = $coll
    $ir = $inst.Install()
    $okCount = 0
    for ($i = 0; $i -lt $coll.Count; $i++) {
        $ur = $ir.GetUpdateResult($i)
        $code = [int]$ur.ResultCode
        $title = [string]$coll.Item($i).Title
        if ($code -eq 2 -or $code -eq 3) { Add-Done ('Kuruldu: ' + $title); $okCount++ }
        else { Add-Err (('Kurulamad' + [char]0x0131 + ' (kod ') + $code + '): ' + $title) }
    }
    $reboot = [bool]$ir.RebootRequired
    if ($reboot) { Write-WhLog ('G' + [char]0x00FC + 'ncellemelerin tamamlanmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') 'WARN' }
    Write-Thanks
    return @{ Ok = ($okCount -gt 0); Installed = $okCount; Reboot = $reboot }
}

function Job_WuHistory($P) {
    $sess = New-Object -ComObject Microsoft.Update.Session
    $s = $sess.CreateUpdateSearcher()
    $n = [int]$s.GetTotalHistoryCount()
    if ($n -gt 80) { $n = 80 }
    $rows = New-Object System.Collections.ArrayList
    if ($n -gt 0) {
        $h = $s.QueryHistory(0, $n)
        for ($i = 0; $i -lt $h.Count; $i++) {
            $e = $h.Item($i)
            $result = 'Bilinmiyor'
            switch ([int]$e.ResultCode) { 2 { $result = ('Ba' + [char]0x015F + 'ar' + [char]0x0131 + 'l' + [char]0x0131) } 3 { $result = ('Uyar' + [char]0x0131 + 'yla ba' + [char]0x015F + 'ar' + [char]0x0131 + 'l' + [char]0x0131) } 4 { $result = ('Ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z') } 5 { $result = ([string][char]0x0130 + 'ptal') } 1 { $result = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'yor') } }
            [void]$rows.Add(@{ Title = [string]$e.Title; Date = ([datetime]$e.Date).ToString('yyyy-MM-dd HH:mm'); Result = $result; Op = [int]$e.Operation })
        }
    }
    return @{ Rows = $rows.ToArray() }
}

# ---------------- winget ----------------
function Get-WingetPath {
    $c = Get-Command -Name 'winget.exe' -ErrorAction Ignore
    if ($null -ne $c) { return [string]$c.Source }
    $la = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
    if (Test-Path -LiteralPath $la) { return $la }
    try {
        $pk = @(Get-AppxSafe 'Microsoft.DesktopAppInstaller') | Select-Object -First 1
        if ($null -ne $pk) {
            $x = Join-Path $pk.InstallLocation 'winget.exe'
            if (Test-Path -LiteralPath $x) { return $x }
        }
    } catch { }
    return ''
}

# winget tablo ciktisini (dilden bagimsiz, sutun konumlarindan) ayristirir
function ConvertFrom-WingetTable([string[]]$Lines) {
    $clean = New-Object System.Collections.ArrayList
    foreach ($ln in @($Lines)) {
        $t = [string]$ln
        $i = $t.LastIndexOf([char]13)
        if ($i -ge 0) { $t = $t.Substring($i + 1) }
        [void]$clean.Add($t.TrimEnd())
    }
    $rows = New-Object System.Collections.ArrayList
    $explicit = $false
    for ($i = 0; $i -lt $clean.Count; $i++) {
        $l = [string]$clean[$i]
        if ($l -match '^\s*-{5,}\s*$' -and $i -gt 0) {
            $hi = $i - 1
            while ($hi -gt 0 -and ([string]$clean[$hi]).Trim() -eq '') { $hi-- }
            $hdr = [string]$clean[$hi]
            $cols = @([regex]::Matches($hdr, '\S+(?: \S+)*') | ForEach-Object { $_.Index })
            if ($cols.Count -lt 3) { continue }
            $j = $i + 1
            while ($j -lt $clean.Count) {
                $row = [string]$clean[$j]
                if ($row.Trim() -eq '') { break }
                if ($row.Length -gt $cols[1]) {
                    $name = $row.Substring(0, $cols[1]).Trim()
                    $end2 = $row.Length
                    if ($cols.Count -gt 2) { $end2 = [math]::Min($row.Length, $cols[2]) }
                    $id = $row.Substring($cols[1], $end2 - $cols[1]).Trim()
                    $ver = ''; $avail = ''; $src = ''
                    if ($cols.Count -gt 2 -and $row.Length -gt $cols[2]) {
                        $e3 = $row.Length; if ($cols.Count -gt 3) { $e3 = [math]::Min($row.Length, $cols[3]) }
                        $ver = $row.Substring($cols[2], $e3 - $cols[2]).Trim()
                    }
                    if ($cols.Count -gt 3 -and $row.Length -gt $cols[3]) {
                        $e4 = $row.Length; if ($cols.Count -gt 4) { $e4 = [math]::Min($row.Length, $cols[4]) }
                        $avail = $row.Substring($cols[3], $e4 - $cols[3]).Trim()
                    }
                    if ($cols.Count -gt 4 -and $row.Length -gt $cols[4]) { $src = $row.Substring($cols[4]).Trim() }
                    if ($id -ne '' -and $id -notmatch '\s' -and $name -ne '') {
                        [void]$rows.Add(@{ Name = $name; Id = $id; Version = $ver; Available = $avail; Source = $src; Explicit = $explicit })
                    }
                }
                $j++
            }
            $i = $j
            $explicit = $true
        }
    }
    return , $rows.ToArray()
}

function Invoke-WingetRaw([string[]]$WgArgs) {
    $wg = Get-WingetPath
    if ($wg -eq '') { throw ('winget bulunamad' + [char]0x0131 + '. Microsoft Store' + [char]0x2019 + 'dan "Uygulama Y' + [char]0x00FC + 'kleyicisi" (App Installer) uygulamas' + [char]0x0131 + 'n' + [char]0x0131 + ' y' + [char]0x00FC + 'kleyin.') }
    try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }
    $global:LASTEXITCODE = 0
    $out = @(& $wg @WgArgs 2>&1 | ForEach-Object { [string]$_ })
    return @{ Lines = $out; Code = $LASTEXITCODE }
}

function Write-WingetLines($Lines) {
    foreach ($ln in @($Lines)) {
        $t = [string]$ln
        $i = $t.LastIndexOf([char]13)
        if ($i -ge 0) { $t = $t.Substring($i + 1) }
        $t = $t.Trim()
        if ($t -eq '' -or $t -match ('^[-\\|/\s' + [char]0x2588 + [char]0x2592 + [char]0x2591 + ']+$')) { continue }
        if ($t -match '^[\d\.]+\s*(KB|MB|GB)\s*/\s*[\d\.]+\s*(KB|MB|GB)$') { continue }
        Write-Raw ('   ' + $t)
    }
}

function Job_WingetCheck($P) {
    Write-WhLog ('Program g' + [char]0x00FC + 'ncellemeleri denetleniyor (winget)...') 'INFO'
    if (-not (Test-Online)) { Write-WhLog ([string][char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' yok.') 'WARN'; return @{ Rows = @(); Offline = $true } }
    $r = Invoke-WingetRaw @('upgrade', '--include-unknown', '--accept-source-agreements', '--disable-interactivity')
    $rows = ConvertFrom-WingetTable $r.Lines
    Write-WhLog (('G' + [char]0x00FC + 'ncellenebilir program: ') + @($rows).Count) 'INFO'
    return @{ Rows = $rows; Offline = $false }
}

function Job_WingetUpgrade($P) {
    $ids = @($P.Ids)
    Reset-Counters
    Set-JobProgress 0 $ids.Count ('Programlar g' + [char]0x00FC + 'ncelleniyor')
    $okN = 0
    foreach ($id in $ids) {
        if (Test-JobCancel) { Write-WhLog ([string][char]0x0130 + 'ptal edildi.') 'WARN'; break }
        if ($id -cnotmatch '^[A-Za-z0-9][A-Za-z0-9\.\-_\+]*$') { Add-Skip (('Ge' + [char]0x00E7 + 'ersiz paket kimli' + [char]0x011F + 'i: ') + $id); Step-JobProgress; continue }
        Write-WhLog (('=== G' + [char]0x00FC + 'ncelleniyor: ') + $id) 'STEP'
        try {
            $r = Invoke-WingetRaw @('upgrade', '--id', $id, '--exact', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity')
            Write-WingetLines $r.Lines
            if ($r.Code -eq 0) { Add-Done ($id + (' g' + [char]0x00FC + 'ncellendi')); $okN++ } else { Add-Err ($id + (': winget ' + [char]0x00E7 + [char]0x0131 + 'k' + [char]0x0131 + [char]0x015F + ' kodu ') + $r.Code) }
        } catch { Add-Err ($id + ': ' + $_.Exception.Message) }
        Step-JobProgress
    }
    Write-WhLog (('G' + [char]0x00FC + 'ncellenen program: ') + $okN + ' / ' + $ids.Count) 'INFO'
    Write-Thanks
    return @{ Ok = $okN; Total = $ids.Count }
}

function Job_WingetInstall($P) {
    $id = [string]$P.Id
    if ($id -cnotmatch '^[A-Za-z0-9][A-Za-z0-9\.\-_\+]*$') { Write-WhLog (('Ge' + [char]0x00E7 + 'ersiz paket kimli' + [char]0x011F + 'i: ') + $id) 'ERR'; return @{ Ok = $false } }
    Write-WhLog ('=== Kuruluyor: ' + $id + (' (winget deposu, imza/' + [char]0x00F6 + 'zet do' + [char]0x011F + 'rulamal' + [char]0x0131 + ')')) 'STEP'
    Set-JobProgress 0 1 'Kuruluyor'
    $ok = $false
    try {
        $r = Invoke-WingetRaw @('install', '--id', $id, '--exact', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity')
        Write-WingetLines $r.Lines
        if ($r.Code -eq 0) { Write-WhLog ($id + ' kuruldu') 'OK'; $ok = $true } else { Write-WhLog ($id + (': winget ' + [char]0x00E7 + [char]0x0131 + 'k' + [char]0x0131 + [char]0x015F + ' kodu ') + $r.Code) 'ERR' }
    } catch { Write-WhLog ($id + ': ' + $_.Exception.Message) 'ERR' }
    Set-JobProgress 1 1
    return @{ Ok = $ok }
}

# ==================================================================
#  ISLER (C): saglik ve guvenlik denetimi (yalnizca okur), duzeltme eylemleri
#  Bulgu: @{ Id; Cat (sec|perf|maint); Status (ok|info|warn|bad); Title; Detail; Action; Weight }
#  Eylem: @{ Kind = Tweak|Page|Run|Url; ... }
# ==================================================================
$script:Findings = New-Object System.Collections.ArrayList

function Add-Finding([string]$Id, [string]$Cat, [string]$Status, [string]$Title, [string]$Detail = '', $Action = $null, [int]$Weight = -1, $Fix = $null) {
    if ($Weight -lt 0) {
        $Weight = 0
        if ($Status -eq 'bad') { $Weight = 12 } elseif ($Status -eq 'warn') { $Weight = 5 }
    }
    [void]$script:Findings.Add(@{ Id = $Id; Cat = $Cat; Status = $Status; Title = $Title; Detail = $Detail; Action = $Action; Weight = $Weight; Fix = $Fix })
}

function Invoke-Check([string]$Name, [scriptblock]$Body) {
    if (Test-JobCancel) { return }
    try { & $Body }
    catch { Write-WhLog (('Denetim atland' + [char]0x0131 + ' (') + $Name + '): ' + $_.Exception.Message) 'WARN' }
    Step-JobProgress $Name
}

function Get-OsSupportInfo($Pr) {
    $now = Get-Date
    $v = [string]$Pr.Version
    $isHomePro = ($Pr.Edition -eq 'Home' -or $Pr.Edition -eq 'Pro')
    if (-not $Pr.IsWin11) {
        # Ev kullanicilari icin ESU en gec 13.10.2026'ya kadar; LTSC surumlerinin tarihi ayridir
        if ($Pr.IsLtsc -eq $true) {
            $ltEnd = [datetime]'2027-01-12'
            if ([int]$Pr.Build -le 17763) { $ltEnd = [datetime]'2029-01-09' }
            if ([int]$Pr.Build -le 14393) { $ltEnd = [datetime]'2026-10-13' }
            $ltDays = [int][math]::Ceiling(($ltEnd.Date - $now.Date).TotalDays)
            if ($ltDays -lt 0) { return @{ Status = 'bad'; Text = (('Windows 10 LTSC i' + [char]0x00E7 + 'in g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemeleri ') + $ltEnd.ToString('dd.MM.yyyy') + ' tarihinde sona erdi.') } }
            $ltSt = 'ok'; if ($ltDays -le 180) { $ltSt = 'warn' }
            return @{ Status = $ltSt; Text = (('Windows 10 LTSC: g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemeleri ') + $ltEnd.ToString('dd.MM.yyyy') + ' tarihine kadar (' + $ltDays + (' g' + [char]0x00FC + 'n).')) }
        }
        $esu = [datetime]'2026-10-13'
        $days = [int][math]::Ceiling(($esu.Date - $now.Date).TotalDays)
        if ($days -ge 0) {
            return @{ Status = 'warn'; Text = (('Windows 10 i' + [char]0x00E7 + 'in standart destek 14.10.2025 tarihinde bitti. G' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemeleri yaln' + [char]0x0131 + 'zca Geni' + [char]0x015F + 'letilmi' + [char]0x015F + ' G' + [char]0x00FC + 'venlik G' + [char]0x00FC + 'ncellemeleri (ESU) kayd' + [char]0x0131 + 'yla ve ev kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lar' + [char]0x0131 + ' i' + [char]0x00E7 + 'in en ge' + [char]0x00E7 + ' 13.10.2026 tarihine kadar (') + $days + (' g' + [char]0x00FC + 'n) s' + [char]0x00FC + 'rer; kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'ilseniz g' + [char]0x00FC + 'ncelleme alm' + [char]0x0131 + 'yorsunuz. Windows 11' + [char]0x2019 + 'e ge' + [char]0x00E7 + 'meyi planlay' + [char]0x0131 + 'n.')) }
        }
        return @{ Status = 'bad'; Text = (('Windows 10 i' + [char]0x00E7 + 'in ev kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lar' + [char]0x0131 + 'na verilen ESU d' + [char]0x00F6 + 'nemi 13.10.2026 tarihinde bitti. Kurumsal ESU' + [char]0x2019 + 'ya (en ' + [char]0x00E7 + 'ok 2028) kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'ilseniz bu bilgisayar g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemesi alm' + [char]0x0131 + 'yor. Windows 11' + [char]0x2019 + 'e ge' + [char]0x00E7 + 'in ya da bilgisayar' + [char]0x0131 + ' internete a' + [char]0x00E7 + '' + [char]0x0131 + 'k kullanmay' + [char]0x0131 + ' s' + [char]0x0131 + 'n' + [char]0x0131 + 'rlay' + [char]0x0131 + 'n.')) }
    }
    $table = @{
        '21H2' = @('2023-10-10', '2024-10-08'); '22H2' = @('2024-10-08', '2025-10-14'); '23H2' = @('2025-11-11', '2026-11-10')
        '24H2' = @('2026-10-13', '2027-10-12'); '25H2' = @('2027-10-12', '2028-10-10')
    }
    if ($Pr.IsLtsc -eq $true) {
        $ltEnd = [datetime]'2029-10-09'
        $ltDays = [int][math]::Ceiling(($ltEnd.Date - $now.Date).TotalDays)
        return @{ Status = 'ok'; Text = (('Windows 11 LTSC: g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemeleri ') + $ltEnd.ToString('dd.MM.yyyy') + ' tarihine kadar (' + $ltDays + (' g' + [char]0x00FC + 'n).')) }
    }
    if ($table.ContainsKey($v)) {
        $idx = 1; if ($isHomePro) { $idx = 0 }
        $end = [datetime]$table[$v][$idx]
        $days = [int](($end - $now).TotalDays)
        if ($days -lt 0) { return @{ Status = 'bad'; Text = ('Windows 11 ' + $v + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' i' + [char]0x00E7 + 'in g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemesi ') + $end.ToString('dd.MM.yyyy') + (' tarihinde sona erdi. S' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' y' + [char]0x00FC + 'kseltin.')) } }
        if ($days -le 120) { return @{ Status = 'warn'; Text = ('Windows 11 ' + $v + (' i' + [char]0x00E7 + 'in servis ') + $end.ToString('dd.MM.yyyy') + ' tarihinde bitiyor (' + $days + (' g' + [char]0x00FC + 'n kald' + [char]0x0131 + '). Yeni s' + [char]0x00FC + 'r' + [char]0x00FC + 'me y' + [char]0x00FC + 'kseltmeyi planlay' + [char]0x0131 + 'n.')) } }
        return @{ Status = 'ok'; Text = ('Windows 11 ' + $v + (' desteklenen s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde (servis sonu ') + $end.ToString('dd.MM.yyyy') + ').') }
    }
    return @{ Status = 'info'; Text = (('Windows 11 s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ': ') + $v) }
}

# ---------------- denetimler ----------------
function Chk_Defender {
    $av = @()
    try { $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntivirusProduct -ErrorAction Stop) } catch { }
    $mp = $null
    try { $mp = Get-MpComputerStatus -ErrorAction Stop } catch { }
    $third = @($av | Where-Object { [string]$_.displayName -notmatch 'Windows Defender|Microsoft Defender' } | ForEach-Object { [string]$_.displayName })
    if ($null -ne $mp -and $mp.RealTimeProtectionEnabled -eq $true) {
        Add-Finding 'av-rt' 'sec' 'ok' ('Vir' + [char]0x00FC + 's korumas' + [char]0x0131 + ' (Microsoft Defender) a' + [char]0x00E7 + [char]0x0131 + 'k') ('Ger' + [char]0x00E7 + 'ek zamanl' + [char]0x0131 + ' koruma ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'yor.')
        $age = [int]$mp.AntivirusSignatureAge
        if ($age -gt 7) { Add-Finding 'av-sig' 'sec' 'bad' (('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' ') + $age + (' g' + [char]0x00FC + 'n eski')) ('G' + [char]0x00FC + 'ncel tan' + [char]0x0131 + 'mlar olmadan yeni zararl' + [char]0x0131 + 'lar yakalanmaz.') @{ Kind = 'Run'; Key = 'DefUpdate'; Label = ('Tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncelle') } }
        elseif ($age -gt 3) { Add-Finding 'av-sig' 'sec' 'warn' (('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' ') + $age + (' g' + [char]0x00FC + 'n eski')) ('Windows Update ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'nda kendili' + [char]0x011F + 'inden g' + [char]0x00FC + 'ncellenir.') @{ Kind = 'Run'; Key = 'DefUpdate'; Label = ('Tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncelle') } }
        $qa = 0; $fa = 0
        # hic taranmadiysa Defender 4294967295 (UInt32.MaxValue) dondurur: [int] donusumu tasar; her deger ayri okunur, 9999 = hic
        try { if ($null -ne $mp.QuickScanAge) { $qa = [int][math]::Min(9999.0, [double]$mp.QuickScanAge) } } catch { }
        try { if ($null -ne $mp.FullScanAge) { $fa = [int][math]::Min(9999.0, [double]$mp.FullScanAge) } } catch { }
        if ($qa -gt 14 -and $fa -gt 30) { Add-Finding 'av-scan' 'sec' 'warn' ('Uzun s' + [char]0x00FC + 'redir vir' + [char]0x00FC + 's taramas' + [char]0x0131 + ' yap' + [char]0x0131 + 'lmad' + [char]0x0131) ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer.') @{ Kind = 'Run'; Key = 'DefScan'; Label = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama ba' + [char]0x015F + 'lat') } }
        if ($mp.IsTamperProtected -eq $true) { Add-Finding 'av-tamper' 'sec' 'ok' ('Kurcalama Korumas' + [char]0x0131 + ' a' + [char]0x00E7 + [char]0x0131 + 'k') ('Zararl' + [char]0x0131 + 'lar' + [char]0x0131 + 'n Defender ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + ' kapatmas' + [char]0x0131 + ' engelleniyor.') }
        else { Add-Finding 'av-tamper' 'sec' 'warn' ('Kurcalama Korumas' + [char]0x0131 + ' kapal' + [char]0x0131) ('Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i > Vir' + [char]0x00FC + 's ve tehdit korumas' + [char]0x0131 + ' > Ayarlar b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nden a' + [char]0x00E7 + [char]0x0131 + 'n.') @{ Kind = 'Url'; Url = 'windowsdefender:'; Label = ('Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i' + [char]0x2019 + 'ni a' + [char]0x00E7) } }
    } elseif ($third.Count -gt 0) {
        Add-Finding 'av-3p' 'sec' 'ok' (([string][char]0x00DC + [char]0x00E7 + [char]0x00FC + 'nc' + [char]0x00FC + ' taraf antivir' + [char]0x00FC + 's: ') + ($third -join ', ')) 'Microsoft Defender bu durumda pasif olabilir; bu normaldir.'
    } else {
        Add-Finding 'av-rt' 'sec' 'bad' ('Vir' + [char]0x00FC + 's korumas' + [char]0x0131 + ' kapal' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor') ('Ger' + [char]0x00E7 + 'ek zamanl' + [char]0x0131 + ' koruma a' + [char]0x00E7 + [char]0x0131 + 'k de' + [char]0x011F + 'il ve ba' + [char]0x015F + 'ka bir antivir' + [char]0x00FC + 's alg' + [char]0x0131 + 'lanmad' + [char]0x0131 + '.') @{ Kind = 'Url'; Url = 'windowsdefender:'; Label = ('Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i' + [char]0x2019 + 'ni a' + [char]0x00E7) } 20
    }
    try {
        $pref = Get-MpPreference -ErrorAction Stop
        $risky = @()
        foreach ($x in @($pref.ExclusionPath)) {
            $t = [string]$x
            if ($t -cmatch '^[A-Za-z]:\\?$' -or $t.ToLowerInvariant() -cmatch '\\temp\\?$|\\users\\[^\\]+\\?$|\\downloads\\?$') { $risky += $t }
        }
        $cnt = @($pref.ExclusionPath).Count + @($pref.ExclusionExtension).Count + @($pref.ExclusionProcess).Count
        if ($risky.Count -gt 0) { Add-Finding 'av-excl' 'sec' 'bad' ('Defender' + [char]0x2019 + 'da riskli d' + [char]0x0131 + [char]0x015F + 'lama var') (('T' + [char]0x00FC + 'm s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '/klas' + [char]0x00F6 + 'r taranm' + [char]0x0131 + 'yor: ') + ($risky -join '; ')) @{ Kind = 'Url'; Url = 'windowsdefender:'; Label = ('Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i' + [char]0x2019 + 'ni a' + [char]0x00E7) } }
        elseif ($cnt -gt 0) { Add-Finding 'av-excl' 'sec' 'info' (Get-ExclTitle $cnt) (Get-ExclDetail $pref) (Get-ExclAction) }
    } catch { }
}

function Chk_Firewall {
    $off = @()
    foreach ($p in @(Get-NetFirewallProfile -ErrorAction Stop)) { if ([string]$p.Enabled -ne 'True') { $off += [string]$p.Name } }
    if ($off.Count -eq 0) { Add-Finding 'fw' 'sec' 'ok' ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' t' + [char]0x00FC + 'm profillerde a' + [char]0x00E7 + [char]0x0131 + 'k') '' }
    else { Add-Finding 'fw' 'sec' 'bad' (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kapal' + [char]0x0131 + ': ') + ($off -join ', ')) ('Gelen ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar korunmuyor.') @{ Kind = 'Run'; Key = 'FwOn'; Label = ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7) } 15 }
}

function Chk_Uac {
    $lua = [int](Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableLUA' 1)
    $cp = [int](Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'ConsentPromptBehaviorAdmin' 5)
    if ($lua -eq 0) { Add-Finding 'uac' 'sec' 'bad' ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' Hesab' + [char]0x0131 + ' Denetimi (UAC) kapal' + [char]0x0131) ('Programlar y' + [char]0x00F6 + 'netici izni sormadan y' + [char]0x00FC + 'kselebilir.') @{ Kind = 'Url'; Url = 'UserAccountControlSettings.exe'; Label = ('UAC ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7) } 15 }
    elseif ($cp -eq 0) { Add-Finding 'uac' 'sec' 'warn' ('UAC y' + [char]0x00F6 + 'neticiler i' + [char]0x00E7 + 'in sormadan y' + [char]0x00FC + 'kseltiyor') ('Ayarlar > Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' Hesab' + [char]0x0131 + ' Denetimi' + [char]0x2019 + 'nden d' + [char]0x00FC + 'zeyi y' + [char]0x00FC + 'kseltin.') @{ Kind = 'Url'; Url = 'UserAccountControlSettings.exe'; Label = ('UAC ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7) } }
    else { Add-Finding 'uac' 'sec' 'ok' ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' Hesab' + [char]0x0131 + ' Denetimi (UAC) a' + [char]0x00E7 + [char]0x0131 + 'k') '' }
}

function Chk_Tpm {
    $tp = $null
    try { $tp = Get-Tpm -ErrorAction Stop } catch { }
    $sb = $null
    try { $sb = [bool](Confirm-SecureBootUEFI -ErrorAction Stop) } catch { }
    if ($null -ne $tp -and $tp.TpmPresent -eq $true) { Add-Finding 'tpm' 'sec' 'ok' ('TPM g' + [char]0x00FC + 'venlik ' + [char]0x00E7 + 'ipi var') '' }
    else { Add-Finding 'tpm' 'sec' 'info' ('TPM bulunamad' + [char]0x0131 + ' veya kapal' + [char]0x0131) ('Windows 11 ve BitLocker i' + [char]0x00E7 + 'in TPM 2.0 gerekir.') }
    if ($sb -eq $true) { Add-Finding 'sboot' 'sec' 'ok' ('G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme (Secure Boot) a' + [char]0x00E7 + [char]0x0131 + 'k') '' }
    elseif ($sb -eq $false) { Add-Finding 'sboot' 'sec' 'warn' ('G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme kapal' + [char]0x0131) ([string][char]0x00D6 + 'ny' + [char]0x00FC + 'kleme s' + [char]0x0131 + 'ras' + [char]0x0131 + 'nda zararl' + [char]0x0131 + ' yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm y' + [char]0x00FC + 'klenmesine kar' + [char]0x015F + [char]0x0131 + ' koruma yok. BIOS/UEFI ayarlar' + [char]0x0131 + 'ndan a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + 'r.') }
}

function Chk_OsSupport {
    $pr = $sync.Profile
    if ($null -eq $pr) { return }
    $i = Get-OsSupportInfo $pr
    Add-Finding 'os-eol' 'sec' $i.Status (('Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm deste' + [char]0x011F + 'i: ') + $pr.OsName + ' ' + $pr.Version) $i.Text $null
}

function Chk_Updates {
    $hf = @(Get-HotFix -ErrorAction Stop | Where-Object { $null -ne $_.InstalledOn } | Sort-Object InstalledOn -Descending)
    if ($hf.Count -gt 0) {
        $days = [int]((Get-Date) - [datetime]$hf[0].InstalledOn).TotalDays
        if ($days -gt 90) { Add-Finding 'wu-age' 'sec' 'bad' (('Son g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemesi ') + $days + (' g' + [char]0x00FC + 'n ' + [char]0x00F6 + 'nce kurulmu' + [char]0x015F)) ('G' + [char]0x00FC + 'ncellemeler uzun s' + [char]0x00FC + 'redir kurulmuyor.') @{ Kind = 'Page'; Page = 'updates'; Label = ('G' + [char]0x00FC + 'ncellemelere git') } 15 }
        elseif ($days -gt 45) { Add-Finding 'wu-age' 'sec' 'warn' (('Son g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemesi ') + $days + (' g' + [char]0x00FC + 'n ' + [char]0x00F6 + 'nce kurulmu' + [char]0x015F)) ('Windows g' + [char]0x00FC + 'ncellemelerini denetleyin.') @{ Kind = 'Page'; Page = 'updates'; Label = ('G' + [char]0x00FC + 'ncellemelere git') } }
        else { Add-Finding 'wu-age' 'sec' 'ok' (('Son g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemesi ') + $days + (' g' + [char]0x00FC + 'n ' + [char]0x00F6 + 'nce kurulmu' + [char]0x015F)) ('En son: ' + [string]$hf[0].HotFixID) }
    }
    $pend = Get-PendingReboot
    if ($pend.Count -gt 0) { Add-Finding 'reboot' 'maint' 'warn' ('Yeniden ba' + [char]0x015F + 'latma bekleniyor') ('Neden: ' + ($pend -join ', ') + ('. G' + [char]0x00FC + 'ncellemeler yeniden ba' + [char]0x015F + 'latmadan tamamlanmaz.')) @{ Kind = 'Run'; Key = 'Reboot'; Label = ('Yeniden ba' + [char]0x015F + 'lat') } }
}

function Chk_Accounts {
    $guest = $null; $adm = $null
    try {
        $us = @(Get-LocalUser -ErrorAction Stop)
        $guest = $us | Where-Object { $_.SID.Value -like '*-501' } | Select-Object -First 1
        $adm = $us | Where-Object { $_.SID.Value -like '*-500' } | Select-Object -First 1
        $nopw = @($us | Where-Object { $_.Enabled -and $_.PasswordRequired -eq $false -and $_.SID.Value -notlike '*-501' })
        if ($nopw.Count -gt 0) { Add-Finding 'acc-nopw' 'sec' 'bad' 'Parola gerektirmeyen etkin hesap var' ('Hesaplar: ' + (($nopw | ForEach-Object { $_.Name }) -join ', ')) $null 10 }
    } catch { }
    if ($null -ne $guest -and $guest.Enabled) { Add-Finding 'acc-guest' 'sec' 'warn' ('Konuk hesab' + [char]0x0131 + ' a' + [char]0x00E7 + [char]0x0131 + 'k') ('Parolas' + [char]0x0131 + 'z eri' + [char]0x015F + 'im kap' + [char]0x0131 + 's' + [char]0x0131 + ' olabilir.') @{ Kind = 'Tweak'; Id = 'GuestOff'; Label = 'Kapat' } }
    if ($null -ne $adm -and $adm.Enabled) { Add-Finding 'acc-admin' 'sec' 'warn' (('Yerle' + [char]0x015F + 'ik y' + [char]0x00F6 + 'netici hesab' + [char]0x0131 + ' (') + $adm.Name + (') a' + [char]0x00E7 + [char]0x0131 + 'k')) ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k kullan' + [char]0x0131 + 'm i' + [char]0x00E7 + 'in ayr' + [char]0x0131 + ' bir y' + [char]0x00F6 + 'netici hesab' + [char]0x0131 + ' kullan' + [char]0x0131 + 'n; yerle' + [char]0x015F + 'ik hesab' + [char]0x0131 + ' kapat' + [char]0x0131 + 'n.') $null }
    $members = @()
    try { $members = @(Get-LocalGroupMember -SID 'S-1-5-32-544' -ErrorAction Stop | ForEach-Object { [string]$_.Name }) } catch { }
    if ($members.Count -gt 3) { Add-Finding 'acc-adm' 'sec' 'warn' (('Y' + [char]0x00F6 + 'netici grubunda ') + $members.Count + (' ki' + [char]0x015F + 'i var')) (([string][char]0x00DC + 'yeler: ') + ($members -join ', ') + ('. Gereksiz y' + [char]0x00F6 + 'netici yetkilerini kald' + [char]0x0131 + 'r' + [char]0x0131 + 'n.')) $null }
    elseif ($members.Count -gt 0) { Add-Finding 'acc-adm' 'sec' 'info' (('Y' + [char]0x00F6 + 'neticiler: ') + ($members -join ', ')) '' }
}

function Chk_PasswordPolicy {
    $v = Get-SecPolValues
    if ($v.Count -eq 0) { return }
    $minLen = 0; if ($v.ContainsKey('MinimumPasswordLength')) { $minLen = [int]$v['MinimumPasswordLength'] }
    $lock = 0; if ($v.ContainsKey('LockoutBadCount')) { $lock = [int]$v['LockoutBadCount'] }
    if ($minLen -lt 8) { Add-Finding 'pw-len' 'sec' 'info' (('Asgari parola uzunlu' + [char]0x011F + 'u ilkesi: ') + $minLen) ([string][char]0x015E + 'irket bilgisayarlar' + [char]0x0131 + 'nda en az 8-12 karakter ' + [char]0x00F6 + 'nerilir (Yerel G' + [char]0x00FC + 'venlik ' + [char]0x0130 + 'lkesi / Grup ' + [char]0x0130 + 'lkesi).') $null }
    if ($lock -eq 0) { Add-Finding 'pw-lock' 'sec' 'warn' ('Hesap kilitleme kapal' + [char]0x0131) ('Parola deneme sald' + [char]0x0131 + 'r' + [char]0x0131 + 's' + [char]0x0131 + ' s' + [char]0x0131 + 'n' + [char]0x0131 + 'rs' + [char]0x0131 + 'z denenebilir.') @{ Kind = 'Tweak'; Id = 'Lockout'; Label = ('Etkinle' + [char]0x015F + 'tir') } }
    else { Add-Finding 'pw-lock' 'sec' 'ok' (('Hesap kilitleme a' + [char]0x00E7 + [char]0x0131 + 'k (') + $lock + ' deneme)') '' }
}

function Chk_Network {
    $cfg = $null
    try { $cfg = Get-SmbServerConfiguration -ErrorAction Stop } catch { }
    if ($null -ne $cfg -and $cfg.EnableSMB1Protocol -eq $true) { Add-Finding 'smb1' 'sec' 'bad' ('SMB 1.0 a' + [char]0x00E7 + [char]0x0131 + 'k') ('WannaCry t' + [char]0x00FC + 'r' + [char]0x00FC + ' sald' + [char]0x0131 + 'r' + [char]0x0131 + 'lar' + [char]0x0131 + 'n kulland' + [char]0x0131 + [char]0x011F + [char]0x0131 + ' eski protokol.') @{ Kind = 'Tweak'; Id = 'Smb1'; Label = 'Kapat' } }
    $deny = [int](Get-RegValue 'HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server' 'fDenyTSConnections' 1)
    if ($deny -eq 0) {
        $nla = [int](Get-RegValue 'HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' 'UserAuthentication' 1)
        if ($nla -eq 0) { Add-Finding 'rdp' 'sec' 'bad' ('Uzak Masa' + [char]0x00FC + 'st' + [char]0x00FC + ' a' + [char]0x00E7 + [char]0x0131 + 'k ve NLA kapal' + [char]0x0131) ([string][char]0x0130 + 'nternete a' + [char]0x00E7 + [char]0x0131 + 'ksa sald' + [char]0x0131 + 'rganlar oturum ekran' + [char]0x0131 + 'na ula' + [char]0x015F + 'abilir.') @{ Kind = 'Tweak'; Id = 'RdpNla'; Label = 'NLA zorunlu yap' } }
        else { Add-Finding 'rdp' 'sec' 'info' ('Uzak Masa' + [char]0x00FC + 'st' + [char]0x00FC + ' (RDP) a' + [char]0x00E7 + [char]0x0131 + 'k') ('Kullanm' + [char]0x0131 + 'yorsan' + [char]0x0131 + 'z kapat' + [char]0x0131 + 'n; kullan' + [char]0x0131 + 'yorsan' + [char]0x0131 + 'z internete do' + [char]0x011F + 'rudan a' + [char]0x00E7 + 'may' + [char]0x0131 + 'n (VPN kullan' + [char]0x0131 + 'n).') @{ Kind = 'Tweak'; Id = 'RdpOff'; Label = ('RDP' + [char]0x2019 + 'yi kapat') } }
    }
    $llmnr = Get-RegValue 'HKLM\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' 'EnableMulticast' $null
    if ($null -eq $llmnr -or [int]$llmnr -ne 0) { Add-Finding 'llmnr' 'sec' 'info' ('LLMNR ad ' + [char]0x00E7 + [char]0x00F6 + 'z' + [char]0x00FC + 'mlemesi a' + [char]0x00E7 + [char]0x0131 + 'k') ('Yerel a' + [char]0x011F + 'daki sald' + [char]0x0131 + 'rganlar' + [char]0x0131 + 'n parola ' + [char]0x00F6 + 'zeti ' + [char]0x00E7 + 'almas' + [char]0x0131 + 'nda kullan' + [char]0x0131 + 'lan eski protokol.') @{ Kind = 'Tweak'; Id = 'Llmnr'; Label = 'Kapat' } }
    $ar = Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer' 'NoDriveTypeAutoRun' $null
    if ($null -eq $ar -or [int]$ar -ne 255) { Add-Finding 'autorun' 'sec' 'info' ([string][char]0x00C7 + [char]0x0131 + 'kar' + [char]0x0131 + 'labilir disklerde otomatik ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'rma tam kapal' + [char]0x0131 + ' de' + [char]0x011F + 'il') ('USB bellekteki zararl' + [char]0x0131 + 'lar' + [char]0x0131 + 'n kendili' + [char]0x011F + 'inden ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'mas' + [char]0x0131 + 'n' + [char]0x0131 + ' engelleyin.') @{ Kind = 'Tweak'; Id = 'AutoRun'; Label = 'Kapat' } }
    try {
        $sh = @(Get-SmbShare -ErrorAction Stop | Where-Object { -not $_.Special })
        if ($sh.Count -gt 0) {
            $wide = @()
            foreach ($s in $sh) {
                $acc = @(Get-SmbShareAccess -Name $s.Name -ErrorAction SilentlyContinue | Where-Object { [string]$_.AccountName -match '^(Everyone|Herkes)$' -and [string]$_.AccessRight -eq 'Full' })
                if ($acc.Count -gt 0) { $wide += $s.Name }
            }
            if ($wide.Count -gt 0) { Add-Finding 'share-wide' 'sec' 'bad' ('Herkese tam yetkili payla' + [char]0x015F + [char]0x0131 + 'm var') (('Payla' + [char]0x015F + [char]0x0131 + 'mlar: ') + ($wide -join ', ')) $null }
            else { Add-Finding 'share' 'sec' 'info' (('A' + [char]0x011F + ' payla' + [char]0x015F + [char]0x0131 + 'm' + [char]0x0131 + ': ') + (($sh | ForEach-Object { $_.Name }) -join ', ')) ('Payla' + [char]0x015F + [char]0x0131 + 'mlar' + [char]0x0131 + ' ve eri' + [char]0x015F + 'im yetkilerini g' + [char]0x00F6 + 'zden ge' + [char]0x00E7 + 'irin.') }
        }
    } catch { }
    try {
        $lis = @(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object { [string]$_.LocalAddress -notmatch '^(127\.|::1|fe80)' })
        $risky = @($lis | Where-Object { @(21, 23, 69, 135, 139, 445, 3389, 5900, 5985, 5986) -contains [int]$_.LocalPort } | ForEach-Object { [int]$_.LocalPort } | Sort-Object -Unique)
        $tot = @($lis | ForEach-Object { [int]$_.LocalPort } | Sort-Object -Unique).Count
        if ($risky.Count -gt 0) { Add-Finding 'ports' 'sec' 'info' (('A' + [char]0x011F + 'dan eri' + [char]0x015F + 'ilebilen ') + $tot + ' port dinleniyor') ('Hassas olanlar: ' + ($risky -join ', ') + ('. A' + [char]0x011F + ' sayfas' + [char]0x0131 + 'nda hangi program dinledi' + [char]0x011F + 'ini g' + [char]0x00F6 + 'rebilirsiniz.')) @{ Kind = 'Page'; Page = 'network'; Label = ('A' + [char]0x011F + ' sayfas' + [char]0x0131) } }
        else { Add-Finding 'ports' 'sec' 'ok' (('A' + [char]0x011F + 'dan eri' + [char]0x015F + 'ilebilen ') + $tot + ' port dinleniyor; hassas port yok') '' }
    } catch { }
    try {
        $hp = Join-Path $env:WINDIR 'System32\drivers\etc\hosts'
        $bad = @()
        foreach ($ln in [System.IO.File]::ReadAllLines($hp)) {
            $t = $ln.Trim()
            if ($t -eq '' -or $t.StartsWith('#')) { continue }
            if ($t -match '(?i)windowsupdate|update\.microsoft|defender|virustotal|kaspersky|eset\.|avast|malwarebytes|symantec|bitdefender|sophos') { $bad += $t }
        }
        if ($bad.Count -gt 0) { Add-Finding 'hosts' 'sec' 'bad' ('hosts dosyas' + [char]0x0131 + ' g' + [char]0x00FC + 'venlik sitelerini engelliyor') (([string][char]0x015E + [char]0x00FC + 'pheli sat' + [char]0x0131 + 'rlar: ') + (($bad | Select-Object -First 3) -join ' | ')) $null 15 }
    } catch { }
}

function Chk_Persistence {
    $items = Get-StartupItems
    $sus = @()
    foreach ($it in $items) {
        $exe = Get-CommandExe ([string]$it.Command)
        if ($exe -match '(?i)\\AppData\\Local\\Temp\\|\\Users\\Public\\|\\Windows\\Temp\\|\\ProgramData\\[^\\]+\.(exe|bat|cmd|vbs|js)$') { $sus += [string]$it.Name }
    }
    if ($sus.Count -gt 0) { Add-Finding 'start-sus' 'sec' 'bad' ([string][char]0x015E + [char]0x00FC + 'pheli konumdan ba' + [char]0x015F + 'layan program var') (('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' ' + [char]0x00F6 + [char]0x011F + 'eleri: ') + ($sus -join ', ') + (' (Temp/Public klas' + [char]0x00F6 + 'rlerinden ba' + [char]0x015F + 'layan programlar zararl' + [char]0x0131 + ' olabilir)')) @{ Kind = 'Page'; Page = 'startup'; Label = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' sayfas' + [char]0x0131) } 12 }
    $en = @($items | Where-Object { $_.Enabled })
    if ($en.Count -gt 12) { Add-Finding 'start-n' 'perf' 'warn' (('A' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + 'ta ') + $en.Count + (' program ba' + [char]0x015F + 'l' + [char]0x0131 + 'yor')) ('Gereksizleri kapatmak a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + [char]0x0131 + ' h' + [char]0x0131 + 'zland' + [char]0x0131 + 'r' + [char]0x0131 + 'r.') @{ Kind = 'Page'; Page = 'startup'; Label = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' sayfas' + [char]0x0131) } }
    elseif ($en.Count -gt 7) { Add-Finding 'start-n' 'perf' 'info' (('A' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + 'ta ') + $en.Count + (' program ba' + [char]0x015F + 'l' + [char]0x0131 + 'yor')) ('Kullanmad' + [char]0x0131 + 'klar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' kapatabilirsiniz.') @{ Kind = 'Page'; Page = 'startup'; Label = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' sayfas' + [char]0x0131) } }
    else { Add-Finding 'start-n' 'perf' 'ok' (('A' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + 'ta ') + $en.Count + (' program ba' + [char]0x015F + 'l' + [char]0x0131 + 'yor')) '' }
}

function Chk_Events {
    $from = (Get-Date).AddHours(-24)
    $fail = @()
    try { $fail = @(Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 4625; StartTime = $from } -MaxEvents 1000 -ErrorAction Stop) } catch { }
    $any = $false
    try { $any = (@(Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 4624, 4625; StartTime = (Get-Date).AddDays(-7) } -MaxEvents 1 -ErrorAction Stop).Count -gt 0) } catch { }
    if (-not $any) { Add-Finding 'audit' 'sec' 'info' ('Oturum a' + [char]0x00E7 + 'ma olaylar' + [char]0x0131 + ' kaydedilmiyor') ('Sald' + [char]0x0131 + 'r' + [char]0x0131 + ' denemelerini g' + [char]0x00F6 + 'rebilmek i' + [char]0x00E7 + 'in oturum a' + [char]0x00E7 + 'ma denetimini a' + [char]0x00E7 + [char]0x0131 + 'n.') @{ Kind = 'Tweak'; Id = 'AuditLogon'; Label = ('Denetimi a' + [char]0x00E7) }; return }
    if ($fail.Count -ge 50) { Add-Finding 'logon-fail' 'sec' 'bad' ('Son 24 saatte ' + $fail.Count + (' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z oturum a' + [char]0x00E7 + 'ma denemesi')) ('Parola tahmin sald' + [char]0x0131 + 'r' + [char]0x0131 + 's' + [char]0x0131 + ' olabilir; RDP/payla' + [char]0x015F + [char]0x0131 + 'm d' + [char]0x0131 + [char]0x015F + 'ar' + [char]0x0131 + 'ya a' + [char]0x00E7 + [char]0x0131 + 'k m' + [char]0x0131 + ' kontrol edin.') $null 12 }
    elseif ($fail.Count -ge 10) { Add-Finding 'logon-fail' 'sec' 'warn' ('Son 24 saatte ' + $fail.Count + (' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z oturum a' + [char]0x00E7 + 'ma denemesi')) ('Birka' + [char]0x00E7 + ' yanl' + [char]0x0131 + [char]0x015F + ' parola normaldir; ' + [char]0x00E7 + 'ok fazlaysa a' + [char]0x011F + ' eri' + [char]0x015F + 'imini g' + [char]0x00F6 + 'zden ge' + [char]0x00E7 + 'irin.') $null }
    else { Add-Finding 'logon-fail' 'sec' 'ok' ('Son 24 saatte ' + $fail.Count + (' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z oturum a' + [char]0x00E7 + 'ma denemesi')) '' }
}

function Chk_Disks {
    $pr = $sync.Profile
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveType -eq 'Fixed' -and $_.DriveLetter -and $_.Size -gt 0 })) {
        $pct = [math]::Round(100.0 * [double]$v.SizeRemaining / [double]$v.Size, 0)
        $lbl = [string]$v.DriveLetter + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde %') + $pct + (' bo' + [char]0x015F + ' alan (') + (Format-Size ([double]$v.SizeRemaining)) + ')'
        if ($pct -lt 10) { Add-Finding ('free-' + $v.DriveLetter) 'perf' 'bad' $lbl ('Disk dolmak ' + [char]0x00FC + 'zere; Windows yava' + [char]0x015F + 'lar ve g' + [char]0x00FC + 'ncellemeler kurulamaz.') @{ Kind = 'Page'; Page = 'clean'; Label = ('Temizlik sayfas' + [char]0x0131) } 10 }
        elseif ($pct -lt 20) { Add-Finding ('free-' + $v.DriveLetter) 'perf' 'warn' $lbl ('Temizlik yaparak yer a' + [char]0x00E7 + [char]0x0131 + 'n.') @{ Kind = 'Page'; Page = 'clean'; Label = ('Temizlik sayfas' + [char]0x0131) } }
        else { Add-Finding ('free-' + $v.DriveLetter) 'perf' 'ok' $lbl '' }
    }
    foreach ($d in @(Get-PhysicalDisk -ErrorAction SilentlyContinue)) {
        $hs = [string]$d.HealthStatus
        $name = [string]$d.FriendlyName
        if ($hs -ne 'Healthy' -and $hs -ne '') { Add-Finding ('disk-' + $d.DeviceId) 'perf' 'bad' (('Disk sa' + [char]0x011F + 'l' + [char]0x0131 + [char]0x011F + [char]0x0131 + ': ') + $name + ' (' + $hs + ')') ([string][char]0x00D6 + 'nemli dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' hemen yedekleyin; disk ar' + [char]0x0131 + 'zalan' + [char]0x0131 + 'yor olabilir.') @{ Kind = 'Page'; Page = 'backup'; Label = ('Yedek sayfas' + [char]0x0131) } 18 }
        else {
            $extra = ''
            try {
                $rc = $d | Get-StorageReliabilityCounter -ErrorAction Stop
                if ($null -ne $rc) {
                    if ($null -ne $rc.Temperature -and [int]$rc.Temperature -gt 0) { $extra += (' | ' + [int]$rc.Temperature + (' ' + [char]0x00B0 + 'C')) }
                    if ($null -ne $rc.Wear -and [int]$rc.Wear -gt 0) { $extra += ((' | a' + [char]0x015F + [char]0x0131 + 'nma %') + [int]$rc.Wear) }
                    if ($null -ne $rc.Wear -and [int]$rc.Wear -ge 85) { Add-Finding ('wear-' + $d.DeviceId) 'perf' 'warn' (('SSD ' + [char]0x00F6 + 'mr' + [char]0x00FC + 'n' + [char]0x00FC + 'n %') + [int]$rc.Wear + ([string][char]0x2019 + 'i kullan' + [char]0x0131 + 'lm' + [char]0x0131 + [char]0x015F + ': ') + $name) ('Yak' + [char]0x0131 + 'nda yenilemeyi planlay' + [char]0x0131 + 'n ve d' + [char]0x00FC + 'zenli yedek al' + [char]0x0131 + 'n.') $null }
                }
            } catch { }
            Add-Finding ('disk-' + $d.DeviceId) 'perf' 'ok' (('Disk sa' + [char]0x011F + 'l' + [char]0x0131 + 'kl' + [char]0x0131 + ': ') + $name + $extra) ''
        }
    }
    if ($null -ne $pr -and $pr.DiskType -eq 'HDD') { Add-Finding 'hdd' 'perf' 'info' 'Sistem diski mekanik (HDD)' ('SSD' + [char]0x2019 + 'ye ge' + [char]0x00E7 + 'mek, bilgisayar' + [char]0x0131 + ' a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + ' ve uygulama h' + [char]0x0131 + 'z' + [char]0x0131 + 'nda en ' + [char]0x00E7 + 'ok h' + [char]0x0131 + 'zland' + [char]0x0131 + 'ran tek de' + [char]0x011F + 'i' + [char]0x015F + 'ikliktir.') $null }
}

function Chk_Memory {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
    $totalGB = [math]::Round([double]$os.TotalVisibleMemorySize / 1MB, 1)
    $usedPct = [math]::Round(100.0 * (1.0 - ([double]$os.FreePhysicalMemory / [double]$os.TotalVisibleMemorySize)), 0)
    if ($totalGB -lt 6) { Add-Finding 'ram' 'perf' 'warn' ('RAM az: ' + $totalGB + ' GB') ('Windows 11 ve taray' + [char]0x0131 + 'c' + [char]0x0131 + ' i' + [char]0x00E7 + 'in en az 8 GB ' + [char]0x00F6 + 'nerilir; RAM eklemek ' + [char]0x00E7 + 'ok fark ettirir.') $null }
    elseif ($totalGB -lt 12) { Add-Finding 'ram' 'perf' 'info' ('RAM: ' + $totalGB + ' GB (' + $usedPct + ('% kullan' + [char]0x0131 + 'mda)')) '' $null }
    else { Add-Finding 'ram' 'perf' 'ok' ('RAM: ' + $totalGB + ' GB (' + $usedPct + ('% kullan' + [char]0x0131 + 'mda)')) '' }
    $up = (Get-Date) - $os.LastBootUpTime
    if ($up.TotalDays -gt 14) { Add-Finding 'uptime' 'maint' 'info' ('Bilgisayar ' + [int]$up.TotalDays + (' g' + [char]0x00FC + 'nd' + [char]0x00FC + 'r yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmad' + [char]0x0131)) ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' a' + [char]0x00E7 + [char]0x0131 + 'ksa kapatma tam yeniden ba' + [char]0x015F + 'latma say' + [char]0x0131 + 'lmaz; arada Yeniden Ba' + [char]0x015F + 'lat kullan' + [char]0x0131 + 'n.') $null }
}

function Chk_Maintenance {
    $st = Get-Settings
    $lm = $null
    try { if ([string]$st.LastMaint -ne '') { $lm = [datetime]::Parse([string]$st.LastMaint) } } catch { }
    if ($null -eq $lm -or ((Get-Date) - $lm).TotalDays -gt 30) { Add-Finding 'maint' 'maint' 'info' ('Bak' + [char]0x0131 + 'm uzun s' + [char]0x00FC + 'redir yap' + [char]0x0131 + 'lmad' + [char]0x0131) ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm ge' + [char]0x00E7 + 'ici dosyalar' + [char]0x0131 + ' temizler ve diski optimize eder.') @{ Kind = 'Run'; Key = 'Maint'; Label = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm') } }
    else { Add-Finding 'maint' 'maint' 'ok' (('Son bak' + [char]0x0131 + 'm: ') + $st.LastMaint) '' }
    $lb = $null
    try { if ([string]$st.LastBackup -ne '') { $lb = [datetime]::Parse([string]$st.LastBackup) } } catch { }
    if ($null -eq $lb) { Add-Finding 'backup' 'maint' 'warn' ('Dosya yede' + [char]0x011F + 'i hi' + [char]0x00E7 + ' al' + [char]0x0131 + 'nmam' + [char]0x0131 + [char]0x015F) ('Fidye yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + ', disk ar' + [char]0x0131 + 'zas' + [char]0x0131 + ' veya silinme durumunda tek kurtulu' + [char]0x015F + ' yedektir.') @{ Kind = 'Page'; Page = 'backup'; Label = ('Yedek sayfas' + [char]0x0131) } 8 }
    elseif (((Get-Date) - $lb).TotalDays -gt 14) { Add-Finding 'backup' 'maint' 'warn' (('Son dosya yede' + [char]0x011F + 'i ') + [int]((Get-Date) - $lb).TotalDays + (' g' + [char]0x00FC + 'n ' + [char]0x00F6 + 'nce')) ('Yede' + [char]0x011F + 'i yenileyin.') @{ Kind = 'Page'; Page = 'backup'; Label = ('Yedek sayfas' + [char]0x0131) } }
    else { Add-Finding 'backup' 'maint' 'ok' (('Son dosya yede' + [char]0x011F + 'i: ') + $st.LastBackup) '' }
    try {
        $rp = @(Get-ComputerRestorePoint -ErrorAction Stop)
        if ($rp.Count -eq 0) { Add-Finding 'rp' 'maint' 'info' ('Sistem geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' yok') ('B' + [char]0x00FC + 'y' + [char]0x00FC + 'k de' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerden ' + [char]0x00F6 + 'nce bir geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turun.') @{ Kind = 'Run'; Key = 'RpCreate'; Label = ([string][char]0x015E + 'imdi olu' + [char]0x015F + 'tur') } }
        else { Add-Finding 'rp' 'maint' 'ok' (('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ': ') + $rp.Count) '' }
    } catch { Add-Finding 'rp' 'maint' 'info' ('Sistem Geri Y' + [char]0x00FC + 'kleme kapal' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor') ('Etkinle' + [char]0x015F + 'tirmek geri d' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + ' imk' + [char]0x00E2 + 'n' + [char]0x0131 + ' sa' + [char]0x011F + 'lar.') @{ Kind = 'Run'; Key = 'RpCreate'; Label = ('Etkinle' + [char]0x015F + 'tir ve olu' + [char]0x015F + 'tur') } }
}

# ---------------- ana saglik isi ----------------
function Get-HealthScore($Findings) {
    $pen = @{ sec = 0; perf = 0; maint = 0 }
    foreach ($f in $Findings) { $pen[[string]$f.Cat] += [int]$f.Weight }
    $sec = [math]::Max(0, 100 - $pen.sec)
    $perf = [math]::Max(0, 100 - $pen.perf)
    $mt = [math]::Max(0, 100 - $pen.maint)
    $all = [int][math]::Round(0.5 * $sec + 0.3 * $perf + 0.2 * $mt)
    return @{ Sec = [int]$sec; Perf = [int]$perf; Maint = [int]$mt; All = $all }
}

# Level: Quick (panel icin hizli) | Full (tam guvenlik ve saglik denetimi)
function Get-HealthFindings([string]$Level) {
    $script:Findings = New-Object System.Collections.ArrayList
    $script:SvcRowsCache = $null
    $checks = @(
        @{ N = ('Antivir' + [char]0x00FC + 's'); B = { Chk_Defender } }, @{ N = ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131); B = { Chk_Firewall } }, @{ N = 'UAC'; B = { Chk_Uac } },
        @{ N = ('G' + [char]0x00FC + 'ncellemeler'); B = { Chk_Updates } }, @{ N = 'Disk ve alan'; B = { Chk_Disks } }, @{ N = 'Bellek'; B = { Chk_Memory } },
        @{ N = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7); B = { Chk_Persistence } }, @{ N = ('Bak' + [char]0x0131 + 'm ve yedek'); B = { Chk_Maintenance } },
        @{ N = ('Uyguland' + [char]0x0131 + [char]0x011F + [char]0x0131 + ' ayarlar'); B = { Chk_Drift } }
    )
    if ($Level -eq 'Full') {
        $checks += @(
            @{ N = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm deste' + [char]0x011F + 'i'); B = { Chk_OsSupport } }, @{ N = ('Disk ' + [char]0x015F + 'ifreleme ve sa' + [char]0x011F + 'l' + [char]0x0131 + 'k'); B = { Chk_DiskProtect } }, @{ N = ('Disk hatalar' + [char]0x0131); B = { Chk_DiskErrors } }, @{ N = 'TPM ve Secure Boot'; B = { Chk_Tpm } },
            @{ N = 'Hesaplar'; B = { Chk_Accounts } }, @{ N = 'Parola ilkesi'; B = { Chk_PasswordPolicy } }, @{ N = ('A' + [char]0x011F + ' g' + [char]0x00FC + 'venli' + [char]0x011F + 'i'); B = { Chk_Network } },
            @{ N = ('Oturum olaylar' + [char]0x0131); B = { Chk_Events } }, @{ N = 'Hizmetler'; B = { Chk_Services } },
            @{ N = ('Hizmetler (derin)'); B = { Chk_ServicesDeep } }, @{ N = (('Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' kay' + [char]0x0131 + 'tlar' + [char]0x0131 + '')); B = { Chk_StartupDeep } },
            @{ N = (('Zamanlanm' + [char]0x0131 + '' + [char]0x015F + ' g' + [char]0x00F6 + 'revler')); B = { Chk_TasksDeep } }, @{ N = (('A' + [char]0x011F + ' (derin)')); B = { Chk_NetDeep } }, @{ N = ('A' + [char]0x011F + ' korumas' + [char]0x0131 + ''); B = { Chk_NetProtect } }, @{ N = ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ''); B = { Chk_ArpGuard } },
            @{ N = 'VPN ve gizlilik'; B = { Chk_Vpn } },
            @{ N = ('Windows 11 uyumlulu' + [char]0x011F + 'u'); B = { Chk_Win11 } },
            @{ N = ('Defender (derin)'); B = { Chk_DefenderDeep } }, @{ N = ('Sistem (derin)'); B = { Chk_SystemDeep } },
            @{ N = (('Donan' + [char]0x0131 + 'ma g' + [char]0x00F6 + 're ' + [char]0x00F6 + 'neriler')); B = { Chk_Adaptive } }, @{ N = ('Kamera ve mikrofon'); B = { Chk_PrivacyNow } },
            @{ N = ('Pil'); B = { Chk_Battery } }, @{ N = (('Sistem ' + [char]0x00E7 + '' + [char]0x00F6 + 'kmeleri')); B = { Chk_Crashes } },
            @{ N = (('Uygulama ' + [char]0x00E7 + '' + [char]0x00F6 + 'kmeleri')); B = { Chk_AppCrashes } }, @{ N = (('A' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' s' + [char]0x00FC + 'resi')); B = { Chk_BootTime } },
            @{ N = (('G' + [char]0x00FC + 'venlik duru' + [char]0x015F + 'u')); B = { Chk_Posture } }
        )
    }
    Set-JobProgress 0 $checks.Count 'Denetleniyor'
    foreach ($c in $checks) { Invoke-Check $c.N $c.B }
    foreach ($fnd in $script:Findings) { try { Resolve-FindingFix $fnd } catch { } }
    foreach ($fnd in $script:Findings) { try { Set-FindingStd $fnd } catch { } }
    return , @($script:Findings.ToArray())
}

function Job_Health($P) {
    $lvl = [string]$P.Level
    if ($lvl -eq '') { $lvl = 'Full' }
    $f = Get-HealthFindings $lvl
    $sc = Get-HealthScore $f
    $order = @{ bad = 0; warn = 1; info = 2; ok = 3 }
    $sorted = @($f | Sort-Object @{ Expression = { $order[[string]$_.Status] } }, @{ Expression = { [string]$_.Cat } })
    $st = Get-Settings
    $st.LastHealth = $sc.All
    Save-Settings $st
    Write-WhLog (('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ': ') + $sc.All + (' (g' + [char]0x00FC + 'venlik ') + $sc.Sec + ', performans ' + $sc.Perf + (', bak' + [char]0x0131 + 'm ') + $sc.Maint + ')') 'INFO'
    return @{ Findings = $sorted; Score = $sc }
}

# ---------------- duzeltme eylemleri ----------------
function Job_Action($P) {
    $key = [string]$P.Key
    try {
        switch ($key) {
            'DefUpdate' {
                Write-WhLog ('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncelleniyor...') 'INFO'
                Update-MpSignature -ErrorAction Stop
                Write-WhLog ('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncellendi.') 'OK'
            }
            'DefScan' {
                Write-WhLog ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' vir' + [char]0x00FC + 's taramas' + [char]0x0131 + ' ba' + [char]0x015F + 'lad' + [char]0x0131 + ' (birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer)...') 'INFO'
                Start-MpScan -ScanType QuickScan -ErrorAction Stop
                Write-WhLog ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' vir' + [char]0x00FC + 's taramas' + [char]0x0131 + ' tamamland' + [char]0x0131 + '.') 'OK'
            }
            'FwOn' {
                Set-NetFirewallProfile -Profile Domain, Private, Public -Enabled True -ErrorAction Stop
                Write-WhLog ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' t' + [char]0x00FC + 'm profillerde a' + [char]0x00E7 + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'OK'
            }
            'RpCreate' {
                $ok = Invoke-RestorePoint
                if (-not $ok) { Write-WhLog ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulamad' + [char]0x0131 + '.') 'WARN' }
            }
            'Maint' { return (Job_Maint @{ Items = @(); Preview = $false }) }
            default { Invoke-ActionExtra $key $P }
        }
        return @{ Ok = $true }
    } catch {
        Write-WhLog (('Eylem ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (') + $key + '): ' + $_.Exception.Message) 'ERR'
        return @{ Ok = $false }
    }
}

# ==================================================================
#  ISLER (D): envanter ve rapor, yedekleme/geri yukleme, silinen dosya kurtarma, ag araclari, canli izleme
# ==================================================================

# ---------------- envanter ----------------
function New-Section([string]$Title, [string[]]$Headers, $Rows) {
    return @{ Title = $Title; Headers = $Headers; Rows = @($Rows) }
}

function Get-Inventory {
    $pr = $sync.Profile
    if ($null -eq $pr) { $pr = Get-SystemProfile }
    $sec = New-Object System.Collections.ArrayList

    # --- sistem
    $bios = $null; $board = $null; $gpu = @(); $mem = @()
    try { $bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop } catch { }
    try { $board = Get-CimInstance -ClassName Win32_BaseBoard -ErrorAction Stop } catch { }
    try { $gpu = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop) } catch { }
    try { $mem = @(Get-CimInstance -ClassName Win32_PhysicalMemory -ErrorAction Stop) } catch { }
    $rows = New-Object System.Collections.ArrayList
    $add = { param($k, $v) [void]$rows.Add(@([string]$k, [string]$v)) }
    & $add ('Bilgisayar ad' + [char]0x0131) $pr.Hostname
    & $add ([string][char]0x00DC + 'retici / model') $pr.Model
    if ($null -ne $bios) { & $add ('Seri numaras' + [char]0x0131) ([string]$bios.SerialNumber); & $add 'BIOS' (([string]$bios.SMBIOSBIOSVersion) + ' (' + [string]$bios.Manufacturer + ')') }
    if ($null -ne $board) { & $add 'Anakart' (([string]$board.Manufacturer) + ' ' + ([string]$board.Product)) }
    & $add ([string][char]0x0130 + [char]0x015F + 'letim sistemi') ($pr.OsName + ' ' + $pr.Version + ' (derleme ' + $pr.Build + '.' + $pr.UBR + ')')
    & $add 'Kurulum tarihi' $pr.InstallDate
    & $add ('Etki alan' + [char]0x0131 + ' / kat' + [char]0x0131 + 'l' + [char]0x0131 + 'm') ($pr.JoinType + $(if ($pr.Domain -ne '') { ' - ' + $pr.Domain } else { '' }))
    & $add ('Kurumsal y' + [char]0x00F6 + 'netim (MDM)') $(if ($pr.MdmManaged) { 'Evet' } else { ('Hay' + [char]0x0131 + 'r') })
    & $add ([string][char]0x0130 + [char]0x015F + 'lemci') ($pr.CpuName + ' (' + $pr.Cores + (' ' + [char]0x00E7 + 'ekirdek, ') + $pr.Threads + (' i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + [char]0x011F + [char]0x0131 + ')'))
    $modTxt = ''
    if ($mem.Count -gt 0) { $modTxt = ' (' + $mem.Count + (' mod' + [char]0x00FC + 'l, ') + (($mem | ForEach-Object { [string]([math]::Round([double]$_.Capacity / 1GB, 0)) + ' GB' }) -join ' + ') + ')' }
    & $add 'Bellek (RAM)' ([string]$pr.RamGB + ' GB' + $modTxt)
    foreach ($g in $gpu) { & $add ('Ekran kart' + [char]0x0131) (([string]$g.Name) + (' - s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ') + ([string]$g.DriverVersion)) }
    & $add 'Sanal makine' $(if ($pr.IsVM) { 'Evet' } else { ('Hay' + [char]0x0131 + 'r') })
    & $add ('Cihaz t' + [char]0x00FC + 'r' + [char]0x00FC) $(if ($pr.IsLaptop) { ('Diz' + [char]0x00FC + 'st' + [char]0x00FC + '/tablet') } else { ('Masa' + [char]0x00FC + 'st' + [char]0x00FC) })
    & $add ('Oturum a' + [char]0x00E7 + 'an kullan' + [char]0x0131 + 'c' + [char]0x0131) ([string]$pr.ConsoleUser)
    [void]$sec.Add((New-Section 'Sistem' @(([string][char]0x00D6 + 'zellik'), ('De' + [char]0x011F + 'er')) $rows.ToArray()))

    # --- diskler
    $drows = New-Object System.Collections.ArrayList
    try {
        foreach ($d in @(Get-PhysicalDisk -ErrorAction Stop)) {
            [void]$drows.Add(@([string]$d.FriendlyName, [string]$d.MediaType, [string]$d.BusType, (Format-Size ([double]$d.Size)), [string]$d.HealthStatus))
        }
    } catch { }
    [void]$sec.Add((New-Section 'Fiziksel diskler' @('Disk', ('T' + [char]0x00FC + 'r'), 'Veri yolu', 'Boyut', ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k')) $drows.ToArray()))
    $vrows = New-Object System.Collections.ArrayList
    try {
        foreach ($v in @(Get-Volume -ErrorAction Stop | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' })) {
            [void]$vrows.Add(@(([string]$v.DriveLetter + ':'), [string]$v.FileSystemLabel, [string]$v.FileSystem, (Format-Size ([double]$v.Size)), (Format-Size ([double]$v.SizeRemaining))))
        }
    } catch { }
    [void]$sec.Add((New-Section ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler') @(('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC), 'Etiket', 'Dosya sistemi', 'Boyut', ('Bo' + [char]0x015F))  $vrows.ToArray()))

    # --- ag
    $nrows = New-Object System.Collections.ArrayList
    try {
        foreach ($c in @(Get-NetIPConfiguration -ErrorAction Stop | Where-Object { $null -ne $_.NetAdapter -and [string]$_.NetAdapter.Status -eq 'Up' })) {
            $ip4 = (@($c.IPv4Address | ForEach-Object { [string]$_.IPAddress }) -join ', ')
            $gw = (@($c.IPv4DefaultGateway | ForEach-Object { [string]$_.NextHop }) -join ', ')
            $dns = (@($c.DnsServer.ServerAddresses) -join ', ')
            [void]$nrows.Add(@([string]$c.InterfaceAlias, [string]$c.NetAdapter.MacAddress, $ip4, $gw, $dns, [string]$c.NetAdapter.LinkSpeed))
        }
    } catch { }
    [void]$sec.Add((New-Section ('A' + [char]0x011F + ' ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'lar' + [char]0x0131) @('Ad', 'MAC', 'IPv4', ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi'), 'DNS', ('H' + [char]0x0131 + 'z')) $nrows.ToArray()))

    # --- kullanicilar
    $urows = New-Object System.Collections.ArrayList
    try {
        $admins = @(Get-LocalGroupMember -SID 'S-1-5-32-544' -ErrorAction SilentlyContinue | ForEach-Object { [string]$_.Name })
        foreach ($u in @(Get-LocalUser -ErrorAction Stop)) {
            $isAdm = ($admins | Where-Object { $_ -like ('*\' + $u.Name) }).Count -gt 0
            $ll = ''; if ($null -ne $u.LastLogon) { $ll = ([datetime]$u.LastLogon).ToString('yyyy-MM-dd') }
            [void]$urows.Add(@([string]$u.Name, $(if ($u.Enabled) { ('A' + [char]0x00E7 + [char]0x0131 + 'k') } else { ('Kapal' + [char]0x0131) }), $(if ($isAdm) { 'Evet' } else { ('Hay' + [char]0x0131 + 'r') }), $(if ($u.PasswordRequired) { 'Evet' } else { 'HAYIR' }), $ll))
        }
    } catch { }
    [void]$sec.Add((New-Section ('Yerel kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lar') @('Hesap', 'Durum', ('Y' + [char]0x00F6 + 'netici'), ('Parola ' + [char]0x015F + 'art'), 'Son oturum') $urows.ToArray()))

    # --- guncellemeler
    $hrows = New-Object System.Collections.ArrayList
    try {
        foreach ($h in @(Get-HotFix -ErrorAction Stop | Sort-Object { if ($null -ne $_.InstalledOn) { [datetime]$_.InstalledOn } else { [datetime]::MinValue } } -Descending | Select-Object -First 20)) {
            $d = ''; if ($null -ne $h.InstalledOn) { $d = ([datetime]$h.InstalledOn).ToString('yyyy-MM-dd') }
            [void]$hrows.Add(@([string]$h.HotFixID, [string]$h.Description, $d))
        }
    } catch { }
    [void]$sec.Add((New-Section ('Son kurulan g' + [char]0x00FC + 'ncellemeler (20)') @('KB', ('T' + [char]0x00FC + 'r'), 'Tarih') $hrows.ToArray()))

    # --- baslangic
    $srows = New-Object System.Collections.ArrayList
    foreach ($it in (Get-StartupItems)) { [void]$srows.Add(@([string]$it.Name, [string]$it.Src, $(if ($it.Enabled) { ('A' + [char]0x00E7 + [char]0x0131 + 'k') } else { ('Kapal' + [char]0x0131) }), [string]$it.Command)) }
    [void]$sec.Add((New-Section ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' programlar' + [char]0x0131) @('Ad', 'Kaynak', 'Durum', 'Komut') $srows.ToArray()))

    # --- paylasimlar ve yazicilar
    $shrows = New-Object System.Collections.ArrayList
    try { foreach ($s in @(Get-SmbShare -ErrorAction Stop | Where-Object { -not $_.Special })) { [void]$shrows.Add(@([string]$s.Name, [string]$s.Path, [string]$s.Description)) } } catch { }
    if ($shrows.Count -gt 0) { [void]$sec.Add((New-Section ('A' + [char]0x011F + ' payla' + [char]0x015F + [char]0x0131 + 'mlar' + [char]0x0131) @('Ad', 'Yol', ('A' + [char]0x00E7 + [char]0x0131 + 'klama')) $shrows.ToArray())) }
    $prrows = New-Object System.Collections.ArrayList
    try { foreach ($p in @(Get-CimInstance -ClassName Win32_Printer -ErrorAction Stop)) { [void]$prrows.Add(@([string]$p.Name, [string]$p.DriverName, [string]$p.PortName)) } } catch { }
    if ($prrows.Count -gt 0) { [void]$sec.Add((New-Section ('Yaz' + [char]0x0131 + 'c' + [char]0x0131 + 'lar') @('Ad', ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC), ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + ' noktas' + [char]0x0131)) $prrows.ToArray())) }

    # --- yuklu programlar
    $prog = New-Object System.Collections.ArrayList
    foreach ($p in (Get-InstalledPrograms)) { [void]$prog.Add(@([string]$p.Name, [string]$p.Version, [string]$p.Publisher, [string]$p.Date)) }
    [void]$sec.Add((New-Section (('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' programlar (') + $prog.Count + ')') @('Program', ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm'), ('Yay' + [char]0x0131 + 'nc' + [char]0x0131), 'Kurulum') $prog.ToArray()))
    return $sec.ToArray()
}

function ConvertTo-HtmlText($v) { return [System.Net.WebUtility]::HtmlEncode([string]$v) }

function ConvertTo-ReportHtml($Sections, $Findings, $Score, [string]$Org, [string]$Contact, $Pr) {
    $sb = New-Object System.Text.StringBuilder
    $title = ('Multimizer - Sistem ve G' + [char]0x00FC + 'venlik Raporu')
    [void]$sb.AppendLine('<!DOCTYPE html><html lang="tr"><head><meta charset="utf-8"><title>' + (ConvertTo-HtmlText $title) + '</title>')
    [void]$sb.AppendLine('<style>body{font-family:Segoe UI,Arial,sans-serif;margin:0;background:#f3f5f9;color:#1b2333}.hd{background:linear-gradient(120deg,#0e1424,#26325a);color:#fff;padding:28px 40px}.hd h1{margin:0 0 6px;font-size:24px}.hd div{opacity:.8;font-size:13px}.wrap{max-width:1100px;margin:0 auto;padding:24px 40px}h2{border-left:5px solid #3ea6ff;padding-left:10px;margin-top:34px;font-size:18px}table{border-collapse:collapse;width:100%;background:#fff;box-shadow:0 1px 3px #0002;margin:10px 0;font-size:13px}th{background:#26325a;color:#fff;text-align:left;padding:7px 10px}td{padding:6px 10px;border-bottom:1px solid #e4e8f0;vertical-align:top;word-break:break-word}tr:nth-child(even) td{background:#f8f9fc}.sc{display:flex;gap:14px;flex-wrap:wrap}.card{background:#fff;border-radius:10px;padding:14px 22px;box-shadow:0 1px 3px #0002;min-width:150px}.card b{font-size:34px;display:block}.bad{color:#c62828;font-weight:600}.warn{color:#b26a00;font-weight:600}.ok{color:#2e7d32}.info{color:#37609b}.ft{text-align:center;color:#6b7690;font-size:12px;margin:34px 0 20px}@media print{.hd{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body>')
    [void]$sb.AppendLine('<div class="hd"><h1>' + (ConvertTo-HtmlText $title) + '</h1><div>' + (ConvertTo-HtmlText $Pr.Hostname) + ' &nbsp;|&nbsp; ' + (Get-Date -Format 'dd.MM.yyyy HH:mm'))
    if ($Org -ne '') { [void]$sb.Append(' &nbsp;|&nbsp; ' + (ConvertTo-HtmlText $Org)) }
    if ($Contact -ne '') { [void]$sb.Append(' &nbsp;|&nbsp; ' + (ConvertTo-HtmlText $Contact)) }
    [void]$sb.AppendLine('</div></div><div class="wrap">')
    [void]$sb.AppendLine(('<h2>Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + '</h2><div class="sc"><div class="card"><b>') + $Score.All + '</b>Genel</div><div class="card"><b>' + $Score.Sec + ('</b>G' + [char]0x00FC + 'venlik</div><div class="card"><b>') + $Score.Perf + '</b>Performans</div><div class="card"><b>' + $Score.Maint + ('</b>Bak' + [char]0x0131 + 'm ve yedek</div></div>'))
    [void]$sb.AppendLine(('<h2>Bulgular</h2><table><tr><th>Durum</th><th>Bulgu</th><th>Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '</th></tr>'))
    $stTxt = @{ bad = 'SORUN'; warn = 'UYARI'; info = ('B' + [char]0x0130 + 'LG' + [char]0x0130); ok = ([string][char]0x0130 + 'Y' + [char]0x0130) }
    foreach ($f in $Findings) {
        [void]$sb.AppendLine('<tr><td class="' + $f.Status + '">' + $stTxt[[string]$f.Status] + '</td><td>' + (ConvertTo-HtmlText $f.Title) + '</td><td>' + (ConvertTo-HtmlText $f.Detail) + '</td></tr>')
    }
    [void]$sb.AppendLine('</table>')
    foreach ($s in $Sections) {
        [void]$sb.AppendLine('<h2>' + (ConvertTo-HtmlText $s.Title) + '</h2><table><tr>')
        foreach ($h in $s.Headers) { [void]$sb.Append('<th>' + (ConvertTo-HtmlText $h) + '</th>') }
        [void]$sb.AppendLine('</tr>')
        foreach ($r in $s.Rows) {
            [void]$sb.Append('<tr>')
            foreach ($c in @($r)) { [void]$sb.Append('<td>' + (ConvertTo-HtmlText $c) + '</td>') }
            [void]$sb.AppendLine('</tr>')
        }
        [void]$sb.AppendLine('</table>')
    }
    [void]$sb.AppendLine(('</div><div class="ft">Multimizer v') + $sync.Version + ' &nbsp;&nbsp; ' + (ConvertTo-HtmlText (Get-SigLine)) + ('<br>Bu rapor yaln' + [char]0x0131 + 'zca bu bilgisayarda olu' + [char]0x015F + 'turuldu; hi' + [char]0x00E7 + 'bir veri d' + [char]0x0131 + [char]0x015F + 'ar' + [char]0x0131 + ' g' + [char]0x00F6 + 'nderilmedi.</div></body></html>'))
    return $sb.ToString()
}

function Job_Report($P) {
    Set-JobProgress 0 3 ('Envanter toplan' + [char]0x0131 + 'yor')
    $pr = $sync.Profile
    if ($null -eq $pr) { $pr = Get-SystemProfile }
    $inv = Get-Inventory
    try { $psec = Get-PostureReportSection; if ($null -ne $psec) { $inv = @($inv) + @($psec) } } catch { }
    Set-JobProgress 1 3 ('G' + [char]0x00FC + 'venlik ve sa' + [char]0x011F + 'l' + [char]0x0131 + 'k denetimi')
    $f = Get-HealthFindings 'Full'
    $order = @{ bad = 0; warn = 1; info = 2; ok = 3 }
    $f = @($f | Sort-Object @{ Expression = { $order[[string]$_.Status] } })
    $sc = Get-HealthScore $f
    Set-JobProgress 2 3 ('Rapor yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'yor')
    $st = Get-Settings
    $html = ConvertTo-ReportHtml $inv $f $sc ([string]$st.Org) ([string]$st.Contact) $pr
    $path = Join-Path $sync.ReportDir ('Rapor-' + $pr.Hostname + '-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.html')
    [System.IO.File]::WriteAllText($path, $html, (New-Object System.Text.UTF8Encoding($true)))
    $st.LastReport = (Get-Date).ToString('yyyy-MM-dd HH:mm')
    $st.LastHealth = $sc.All
    Save-Settings $st
    Set-JobProgress 3 3
    Write-WhLog ('Rapor kaydedildi: ' + $path) 'OK'
    Write-Thanks
    return @{ Path = $path; Score = $sc }
}

# ---------------- yedekleme ----------------
$script:RoboExcludeDirs = @('$RECYCLE.BIN', 'System Volume Information', 'node_modules', '.cache')
$script:RoboExcludeFiles = @('*.tmp', '~$*', 'Thumbs.db', 'desktop.ini', 'hiberfil.sys', 'pagefile.sys', 'swapfile.sys')

function Get-RoboSummary($Lines) {
    $nums = New-Object System.Collections.ArrayList
    foreach ($l in $Lines) {
        $s = [string]$l
        if ($s -match ':\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*$') {
            [void]$nums.Add(@([double]$Matches[1], [double]$Matches[2], [double]$Matches[3], [double]$Matches[4], [double]$Matches[5], [double]$Matches[6]))
        }
    }
    $r = @{ Files = 0.0; Copied = 0.0; Failed = 0.0; Bytes = 0.0 }
    if ($nums.Count -ge 3) { $r.Files = $nums[1][0]; $r.Copied = $nums[1][1]; $r.Failed = $nums[1][4]; $r.Bytes = $nums[2][1] }
    return $r
}

function Test-BackupDest([string]$Src, [string]$Dest) {
    $s = ([System.IO.Path]::GetFullPath($Src)).TrimEnd('\') + '\'
    $d = ([System.IO.Path]::GetFullPath($Dest)).TrimEnd('\') + '\'
    if ($d.StartsWith($s, [StringComparison]::OrdinalIgnoreCase)) { return ('Hedef klas' + [char]0x00F6 + 'r kayna' + [char]0x011F + [char]0x0131 + 'n i' + [char]0x00E7 + 'inde olamaz.') }
    if ($s.StartsWith($d, [StringComparison]::OrdinalIgnoreCase)) { return ('Kaynak, hedef klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'n i' + [char]0x00E7 + 'inde olamaz.') }
    if ($d.ToLowerInvariant() -cmatch '^[a-z]:\\(windows|program files|program files \(x86\))\\') { return ('Sistem klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' hedef olamaz.') }
    return ''
}

function Job_Backup($P) {
    Reset-Counters
    $preview = [bool]$P.Preview
    $st = Get-Settings
    $sources = @($P.Sources); if ($sources.Count -eq 0) { $sources = @($st.BackupSources) }
    $dest = [string]$P.Dest; if ($dest -eq '') { $dest = [string]$st.BackupDest }
    $mode = [string]$P.Mode; if ($mode -eq '') { $mode = [string]$st.BackupMode }
    if ($mode -eq 'Restic') {
        Write-WhLog ('' + [char]0x015E + 'ifreli (restic) yedek parola gerektirdi' + [char]0x011F + 'i i' + [char]0x00E7 + 'in zamanlanm' + [char]0x0131 + '' + [char]0x015F + ' ya da komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + 'nda atland' + [char]0x0131 + '. Yedek sayfas' + [char]0x0131 + 'ndan elle ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') 'WARN'
        return @{ Ok = $true; Files = 0; Bytes = 0; Dest = ''; Skipped = $true }
    }
    if ($sources.Count -eq 0 -or $dest -eq '') { Write-WhLog ('Yedeklenecek klas' + [char]0x00F6 + 'r veya hedef se' + [char]0x00E7 + 'ilmemi' + [char]0x015F + '.') 'ERR'; return @{ Ok = $false } }
    $hostName = $env:COMPUTERNAME
    $root = Join-Path $dest $hostName
    if ($mode -eq 'Tarihli') { $root = Join-Path $root (Get-Date -Format 'yyyy-MM-dd_HHmm') }
    try { if (-not $preview -and -not (Test-Path -LiteralPath $root)) { New-Item -ItemType Directory -Path $root -Force | Out-Null } }
    catch { Write-WhLog (('Hedef olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false } }
    $t0 = Get-Date
    Set-JobProgress 0 $sources.Count 'Yedekleniyor'
    $totBytes = 0.0; $totFiles = 0.0; $failed = 0.0; $okAll = $true
    $oem = (Get-OemEncoding)
    foreach ($src in $sources) {
        if (Test-JobCancel) { Write-WhLog ([string][char]0x0130 + 'ptal edildi.') 'WARN'; break }
        $src = [string]$src
        if (-not (Test-Path -LiteralPath $src -PathType Container)) { Add-Skip (('Kaynak klas' + [char]0x00F6 + 'r yok: ') + $src); Step-JobProgress; continue }
        $leaf = Split-Path -Leaf $src.TrimEnd('\')
        if ([string]::IsNullOrEmpty($leaf) -or $leaf -match ':') { $leaf = ($src -replace '[:\\]', '') + '_surucu' }
        $target = Join-Path $root $leaf
        $why = Test-BackupDest $src $target
        if ($why -ne '') { Add-Err ($src + ': ' + $why); $okAll = $false; Step-JobProgress; continue }
        Write-WhLog ('=== ' + $src + '  ->  ' + $target) 'STEP'
        $rbArgs = New-Object System.Collections.ArrayList
        foreach ($a in @($src, $target)) { [void]$rbArgs.Add($a) }
        if ($mode -eq 'Ayna') { [void]$rbArgs.Add('/MIR') } else { [void]$rbArgs.Add('/E') }
        foreach ($a in @('/R:1', '/W:1', '/XJ', '/FFT', '/DCOPY:DAT', '/COPY:DAT', '/NP', '/NDL', '/NFL', '/NJH', '/BYTES')) { [void]$rbArgs.Add($a) }
        if ($preview) { [void]$rbArgs.Add('/L') }
        [void]$rbArgs.Add('/XD'); foreach ($d in $script:RoboExcludeDirs) { [void]$rbArgs.Add($d) }
        [void]$rbArgs.Add('/XF'); foreach ($f in $script:RoboExcludeFiles) { [void]$rbArgs.Add($f) }
        $prev = [Console]::OutputEncoding
        try { [Console]::OutputEncoding = $oem } catch { }
        $global:LASTEXITCODE = 0
        $out = @(& robocopy.exe @($rbArgs.ToArray()) 2>&1 | ForEach-Object { [string]$_ })
        $code = $LASTEXITCODE
        try { [Console]::OutputEncoding = $prev } catch { }
        foreach ($l in $out) { if ($l -match '(?i)error|hata') { Write-Raw ('   ' + $l.Trim()) } }
        $sum = Get-RoboSummary $out
        $totBytes += $sum.Bytes; $totFiles += $sum.Copied; $failed += $sum.Failed
        if ($code -ge 8) { Add-Err ($src + ': robocopy hata kodu ' + $code); $okAll = $false }
        else {
            $verb = ('kopyaland' + [char]0x0131); if ($preview) { $verb = 'kopyalanacak' }
            Add-Done ($leaf + ': ' + [int]$sum.Copied + ' dosya ' + $verb + ' (' + (Format-Size $sum.Bytes) + ')')
        }
        Step-JobProgress
    }
    $msg = ('Yedekleme: ' + [int]$totFiles + ' dosya, ' + (Format-Size $totBytes) + ', ' + (Format-Duration (((Get-Date) - $t0).TotalSeconds)))
    if ($failed -gt 0) { $msg += (', ' + [int]$failed + (' dosya kopyalanamad' + [char]0x0131)) }
    Write-WhLog $msg 'INFO'
    if (-not $preview -and $okAll) { $st.LastBackup = (Get-Date).ToString('yyyy-MM-dd HH:mm'); Save-Settings $st }
    if (-not $preview) { Write-Thanks }
    return @{ Ok = $okAll; Files = $totFiles; Bytes = $totBytes; Dest = $root }
}

function Job_Restore($P) {
    $src = [string]$P.Source; $dst = [string]$P.Target
    if (-not (Test-Path -LiteralPath $src -PathType Container)) { Write-WhLog ('Kaynak yok: ' + $src) 'ERR'; return @{ Ok = $false } }
    if ($dst -eq '') { Write-WhLog ('Hedef klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'ilmedi.') 'ERR'; return @{ Ok = $false } }
    $why = Test-BackupDest $src $dst
    if ($why -ne '') { Write-WhLog $why 'ERR'; return @{ Ok = $false } }
    Write-WhLog (('=== Geri y' + [char]0x00FC + 'kleniyor: ') + $src + '  ->  ' + $dst + ('  (daha yeni dosyalar' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lmaz)')) 'STEP'
    Set-JobProgress 0 1 ('Geri y' + [char]0x00FC + 'kleniyor')
    $oem = (Get-OemEncoding)
    $prev = [Console]::OutputEncoding
    try { [Console]::OutputEncoding = $oem } catch { }
    $out = @(& robocopy.exe $src $dst /E /XO /R:1 /W:1 /XJ /COPY:DAT /DCOPY:DAT /NP /NDL /NFL /NJH /BYTES 2>&1 | ForEach-Object { [string]$_ })
    $code = $LASTEXITCODE
    try { [Console]::OutputEncoding = $prev } catch { }
    $sum = Get-RoboSummary $out
    Set-JobProgress 1 1
    if ($code -ge 8) { Write-WhLog (('Geri y' + [char]0x00FC + 'kleme hatayla sonu' + [char]0x00E7 + 'land' + [char]0x0131 + ' (kod ') + $code + ')') 'ERR'; return @{ Ok = $false } }
    Write-WhLog (('Geri y' + [char]0x00FC + 'klendi: ') + [int]$sum.Copied + ' dosya, ' + (Format-Size $sum.Bytes)) 'OK'
    Write-Thanks
    return @{ Ok = $true }
}

# ---------------- silinen dosya kurtarma ----------------
function Job_RecycleList($P) {
    $rows = New-Object System.Collections.ArrayList
    try {
        $sh = New-Object -ComObject Shell.Application
        $bin = $sh.NameSpace(10)
        foreach ($i in @($bin.Items())) {
            [void]$rows.Add(@{
                Name = [string]$i.Name; Orig = [string]$bin.GetDetailsOf($i, 1); Deleted = [string]$bin.GetDetailsOf($i, 2)
                Size = [double]$i.Size; Path = [string]$i.Path; IsDir = [bool]$i.IsFolder
            })
        }
    } catch { Write-WhLog (('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    Write-WhLog (('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu: ') + $rows.Count + (' ' + [char]0x00F6 + [char]0x011F + 'e')) 'INFO'
    return @{ Rows = $rows.ToArray() }
}

function Job_RecycleRestore($P) {
    $want = @($P.Paths)
    $n = 0
    try {
        $sh = New-Object -ComObject Shell.Application
        $bin = $sh.NameSpace(10)
        foreach ($i in @($bin.Items())) {
            if ($want -contains [string]$i.Path) {
                $done = $false
                try { $i.InvokeVerb('undelete'); $done = $true } catch { }
                if (-not $done) {
                    foreach ($v in @($i.Verbs())) {
                        if (([string]$v.Name).Replace('&', '') -match '(?i)restore|geri') { $v.DoIt(); $done = $true; break }
                    }
                }
                if ($done) { $n++; Write-WhLog (('Geri y' + [char]0x00FC + 'klendi: ') + [string]$i.Name) 'OK' } else { Write-WhLog (('Geri y' + [char]0x00FC + 'klenemedi: ') + [string]$i.Name) 'ERR' }
            }
        }
    } catch { Write-WhLog (('Geri y' + [char]0x00FC + 'kleme hatas' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR' }
    return @{ Restored = $n }
}

function Job_ShadowList($P) {
    $rows = New-Object System.Collections.ArrayList
    try {
        foreach ($s in @(Get-CimInstance -ClassName Win32_ShadowCopy -ErrorAction Stop)) {
            $d = ''; try { $d = ([datetime]$s.InstallDate).ToString('yyyy-MM-dd HH:mm') } catch { }
            [void]$rows.Add(@{ Id = [string]$s.ID; Date = $d; Device = [string]$s.DeviceObject; Volume = [string]$s.VolumeName })
        }
    } catch { }
    $rps = New-Object System.Collections.ArrayList
    try {
        foreach ($r in @(Get-ComputerRestorePoint -ErrorAction Stop)) {
            $d = ''; try { $d = ([Management.ManagementDateTimeConverter]::ToDateTime([string]$r.CreationTime)).ToString('yyyy-MM-dd HH:mm') } catch { }
            [void]$rps.Add(@{ Seq = [int]$r.SequenceNumber; Desc = [string]$r.Description; Date = $d })
        }
    } catch { }
    $trim = ''
    try {
        $o = (& fsutil.exe behavior query DisableDeleteNotify 2>&1 | Out-String)
        if ($o -match 'NTFS[^=]*=\s*(\d)') { if ($Matches[1] -eq '0') { $trim = 'On' } else { $trim = 'Off' } }
        elseif ($o -match '=\s*(\d)') { if ($Matches[1] -eq '0') { $trim = 'On' } else { $trim = 'Off' } }
    } catch { }
    return @{ Shadows = $rows.ToArray(); RestorePoints = $rps.ToArray(); Trim = $trim }
}

function Mount-ShadowCopy([string]$Device) {
    if ($Device -notmatch '^\\\\\?\\GLOBALROOT\\Device\\HarddiskVolumeShadowCopy\d+$') { throw ('Ge' + [char]0x00E7 + 'ersiz g' + [char]0x00F6 + 'lge kopya yolu') }
    $base = Join-Path $env:SystemDrive 'WhGolgeKopya'
    if (-not (Test-Path -LiteralPath $base)) { New-Item -ItemType Directory -Path $base -Force | Out-Null }
    $link = Join-Path $base (Get-Date -Format 'yyyyMMdd-HHmmss')
    $out = & cmd.exe /c mklink /d ('"' + $link + '"') ('"' + $Device + '\"') 2>&1 | Out-String
    if (-not (Test-Path -LiteralPath $link)) { throw (('Ba' + [char]0x011F + 'lant' + [char]0x0131 + ' olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + $out.Trim()) }
    return $link
}

function Remove-ShadowLinks {
    $base = Join-Path $env:SystemDrive 'WhGolgeKopya'
    if (-not (Test-Path -LiteralPath $base)) { return 0 }
    $n = 0
    foreach ($d in @(Get-ChildItem -LiteralPath $base -Force -ErrorAction SilentlyContinue)) {
        if (($d.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
            try { [System.IO.Directory]::Delete($d.FullName); $n++ } catch { }
        }
    }
    try { if (@(Get-ChildItem -LiteralPath $base -Force -ErrorAction SilentlyContinue).Count -eq 0) { Remove-Item -LiteralPath $base -Force } } catch { }
    return $n
}

function Find-PhotoRec {
    $roots = @((Join-Path $env:LOCALAPPDATA 'Microsoft\WinGet\Packages'), $env:ProgramFiles, ${env:ProgramFiles(x86)}, 'C:\Tools', (Join-Path $env:USERPROFILE 'Downloads'))
    foreach ($r in $roots) {
        if ([string]::IsNullOrEmpty($r) -or -not (Test-Path -LiteralPath $r)) { continue }
        try {
            $f = Get-ChildItem -LiteralPath $r -Filter 'qphotorec_win.exe' -Recurse -Depth 4 -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($null -ne $f) { return $f.FullName }
        } catch { }
    }
    return ''
}

# ---------------- ag ----------------
function Get-NetSnapshot {
    $snap = @{ Adapters = @(); Gateways = @(); Dns = @(); Procs = @(); Listen = @() }
    $ad = New-Object System.Collections.ArrayList
    $gws = New-Object System.Collections.ArrayList
    $dnsl = New-Object System.Collections.ArrayList
    try {
        foreach ($c in @(Get-NetIPConfiguration -ErrorAction Stop | Where-Object { $null -ne $_.NetAdapter -and [string]$_.NetAdapter.Status -eq 'Up' })) {
            $ip4 = ''; if ($c.IPv4Address) { $ip4 = [string]@($c.IPv4Address)[0].IPAddress }
            $gw = ''; if ($c.IPv4DefaultGateway) { $gw = [string]@($c.IPv4DefaultGateway)[0].NextHop; if ($gws -notcontains $gw) { [void]$gws.Add($gw) } }
            foreach ($d in @($c.DnsServer.ServerAddresses)) { if ($d -notmatch ':' -and $dnsl -notcontains $d) { [void]$dnsl.Add([string]$d) } }
            [void]$ad.Add(@{ Name = [string]$c.InterfaceAlias; Index = [int]$c.InterfaceIndex; Ip = $ip4; Gateway = $gw; Mac = [string]$c.NetAdapter.MacAddress; Speed = [string]$c.NetAdapter.LinkSpeed; Desc = [string]$c.NetAdapter.InterfaceDescription; Wifi = ([string]$c.NetAdapter.PhysicalMediaType -match '802.11|Wireless|Native') })
        }
    } catch { }
    $snap.Adapters = $ad.ToArray(); $snap.Gateways = $gws.ToArray(); $snap.Dns = $dnsl.ToArray()
    $pnames = @{}
    try { foreach ($p in @(Get-Process -ErrorAction SilentlyContinue)) { $pnames[[int]$p.Id] = [string]$p.ProcessName } } catch { }
    try {
        $est = @(Get-NetTCPConnection -State Established -ErrorAction Stop | Where-Object { [string]$_.RemoteAddress -notmatch '^(127\.|::1|0\.0\.0\.0|fe80)' })
        $grp = @{}
        foreach ($e in $est) {
            $pn = [string]$pnames[[int]$e.OwningProcess]; if ($pn -eq '') { $pn = 'PID ' + $e.OwningProcess }
            if (-not $grp.ContainsKey($pn)) { $grp[$pn] = @{ Name = $pn; Count = 0; Remotes = New-Object System.Collections.ArrayList } }
            $grp[$pn].Count++
            $ra = [string]$e.RemoteAddress + ':' + $e.RemotePort
            if ($grp[$pn].Remotes.Count -lt 4 -and $grp[$pn].Remotes -notcontains $ra) { [void]$grp[$pn].Remotes.Add($ra) }
        }
        $snap.Procs = @($grp.Values | Sort-Object { -1 * [int]$_.Count } | Select-Object -First 10 | ForEach-Object { @{ Name = $_.Name; Count = $_.Count; Remotes = $_.Remotes.ToArray() } })
    } catch { }
    try {
        $lis = @(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object { [string]$_.LocalAddress -notmatch '^(127\.|::1|fe80)' })
        $seen = @{}
        $ll = New-Object System.Collections.ArrayList
        foreach ($l in $lis) {
            $k = [string]$l.LocalPort + '|' + [string]$l.OwningProcess
            if ($seen.ContainsKey($k)) { continue }
            $seen[$k] = $true
            $pn = [string]$pnames[[int]$l.OwningProcess]
            [void]$ll.Add(@{ Port = [int]$l.LocalPort; Proc = $pn; Pid = [int]$l.OwningProcess; Addr = [string]$l.LocalAddress })
        }
        $snap.Listen = @($ll | Sort-Object { [int]$_.Port })
    } catch { }
    return $snap
}

function Job_Net($P) { return (Get-NetSnapshot) }

$script:DnsProviders = @(
    @{ Id = 'cloudflare'; N = 'Cloudflare'; Ips = @('1.1.1.1', '1.0.0.1'); D = ('Gizlilik odakl' + [char]0x0131 + ' (kay' + [char]0x0131 + 't tutmaz).') },
    @{ Id = 'google'; N = 'Google'; Ips = @('8.8.8.8', '8.8.4.4'); D = ([string][char]0x00C7 + 'ok g' + [char]0x00FC + 'venilir ve yayg' + [char]0x0131 + 'n.') },
    @{ Id = 'quad9'; N = 'Quad9'; Ips = @('9.9.9.9', '149.112.112.112'); D = ('Zararl' + [char]0x0131 + ' alan adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' engeller; k' + [char]0x00E2 + 'r amac' + [char]0x0131 + ' g' + [char]0x00FC + 'tmeyen.') },
    @{ Id = 'adguard'; N = 'AdGuard DNS'; Ips = @('94.140.14.14', '94.140.15.15'); D = ('Reklam ve izleyicileri DNS d' + [char]0x00FC + 'zeyinde engeller.') },
    @{ Id = 'opendns'; N = 'OpenDNS'; Ips = @('208.67.222.222', '208.67.220.220'); D = ('Cisco; iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' i' + [char]0x00E7 + 'erik filtreleri.') }
)

function Job_DnsBench($P) {
    $names = @('www.google.com', 'www.microsoft.com', 'www.wikipedia.org', 'www.amazon.com', 'github.com', 'www.cloudflare.com', 'www.youtube.com', 'www.reddit.com')
    $cands = New-Object System.Collections.ArrayList
    $cur = @()
    try { $cur = @(Get-DnsClientServerAddress -AddressFamily IPv4 -ErrorAction Stop | Where-Object { $_.ServerAddresses.Count -gt 0 -and $_.InterfaceAlias -notmatch 'Loopback|vEthernet|VMware|VirtualBox' } | ForEach-Object { $_.ServerAddresses } | Select-Object -First 1) } catch { }
    if ($cur.Count -gt 0) { [void]$cands.Add(@{ Id = 'current'; N = ([string][char]0x015E + 'u anki DNS'); Ip = [string]$cur[0]; Ips = @($cur) }) }
    foreach ($dp in $script:DnsProviders) { [void]$cands.Add(@{ Id = $dp.Id; N = $dp.N; Ip = [string]$dp.Ips[0]; Ips = $dp.Ips }) }
    Set-JobProgress 0 $cands.Count ('DNS h' + [char]0x0131 + 'z' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x00FC + 'l' + [char]0x00FC + 'yor')
    $res = New-Object System.Collections.ArrayList
    foreach ($c in $cands) {
        if (Test-JobCancel) { break }
        $times = New-Object System.Collections.ArrayList
        $fail = 0
        foreach ($n in $names) {
            for ($pass = 0; $pass -lt 2; $pass++) {
                $sw = [System.Diagnostics.Stopwatch]::StartNew()
                try { [void](Resolve-DnsName -Name $n -Server $c.Ip -Type A -DnsOnly -QuickTimeout -ErrorAction Stop); $sw.Stop(); if ($pass -eq 1) { [void]$times.Add($sw.Elapsed.TotalMilliseconds) } }
                catch { $sw.Stop(); if ($pass -eq 1) { $fail++ } }
            }
        }
        $avg = 9999.0
        if ($times.Count -gt 0) { $avg = ($times | Measure-Object -Average).Average }
        [void]$res.Add(@{ Id = $c.Id; Name = $c.N; Ip = $c.Ip; Ips = $c.Ips; Ms = [math]::Round($avg, 1); Fail = $fail })
        Step-JobProgress ($c.N + (' ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x00FC + 'ld' + [char]0x00FC))
    }
    $sorted = @($res | Sort-Object { [double]$_.Ms })
    foreach ($r in $sorted) { Write-WhLog ((('{0,-14} {1,-16} {2,7} ms  (ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: {3})') -f $r.Name, $r.Ip, $r.Ms, $r.Fail)) 'INFO' }
    return @{ Rows = $sorted }
}

# DNS degisikligi icin islem listesi (etkin fiziksel bagdastiricilar). Servers: 'Auto' ya da IP dizisi
function New-DnsSteps($Servers, $Adapters) {
    $ops = New-Object System.Collections.ArrayList
    foreach ($a in @($Adapters)) {
        $srv = $Servers
        if ([string]$Servers -ne 'Auto') { $srv = @($Servers) }
        [void]$ops.Add(@{ T = 'Dns'; Index = [int]$a.Index; Alias = [string]$a.Name; Servers = $srv })
    }
    return , @(@{ Id = 'Dns'; Title = ('DNS sunucular' + [char]0x0131 + 'n' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tir'); Ops = $ops.ToArray(); Reboot = $false })
}

function Invoke-NativeLines([string]$Exe, [string[]]$NativeArgs) {
    $oem = (Get-OemEncoding)
    $prev = [Console]::OutputEncoding
    try { [Console]::OutputEncoding = $oem } catch { }
    $global:LASTEXITCODE = 0
    try {
        & $Exe @NativeArgs 2>&1 | ForEach-Object {
            $t = ([string]$_).TrimEnd()
            if ($t.Trim().Length -gt 0) { Write-Raw ('   ' + $t) }
        }
    } finally { try { [Console]::OutputEncoding = $prev } catch { } }
    return $LASTEXITCODE
}

function Job_Ping($P) {
    $h = ([string]$P.Host).Trim()
    if ($h -cnotmatch '^[A-Za-z0-9][A-Za-z0-9\.\-:]{0,200}$') { Write-WhLog ('Ge' + [char]0x00E7 + 'ersiz adres.') 'ERR'; return @{ Ok = $false } }
    Set-JobProgress 0 2 'Ping'
    Write-WhLog ('=== ping ' + $h) 'STEP'
    [void](Invoke-NativeLines 'ping.exe' @('-n', '4', $h))
    Set-JobProgress 1 2 ([string][char]0x0130 + 'z s' + [char]0x00FC + 'rme')
    if ([bool]$P.Trace) {
        Write-WhLog ('=== tracert ' + $h) 'STEP'
        [void](Invoke-NativeLines 'tracert.exe' @('-d', '-h', '20', '-w', '1500', $h))
    }
    Set-JobProgress 2 2
    return @{ Ok = $true }
}

function Job_SpeedTest($P) {
    Write-WhLog ('H' + [char]0x0131 + 'z testi: yaln' + [char]0x0131 + 'zca speed.cloudflare.com ile konu' + [char]0x015F + 'ulur, ki' + [char]0x015F + 'isel veri g' + [char]0x00F6 + 'nderilmez.') 'INFO'
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    Set-JobProgress 0 3 'Gecikme'
    $lat = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt 4; $i++) {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $rq = [System.Net.WebRequest]::Create('https://speed.cloudflare.com/__down?bytes=0'); $rq.Timeout = 8000
            $rs = $rq.GetResponse(); $rs.Close(); $sw.Stop(); [void]$lat.Add($sw.Elapsed.TotalMilliseconds)
        } catch { $sw.Stop() }
    }
    $latMs = 0.0; if ($lat.Count -gt 0) { $latMs = ($lat | Measure-Object -Minimum).Minimum }
    Set-JobProgress 1 3 ([string][char]0x0130 + 'ndirme')
    $down = 0.0
    try {
        $bytes = 25000000
        $rq = [System.Net.WebRequest]::Create('https://speed.cloudflare.com/__down?bytes=' + $bytes); $rq.Timeout = 30000
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $rs = $rq.GetResponse(); $st = $rs.GetResponseStream()
        $buf = New-Object 'byte[]' 262144; $total = 0.0
        while (($n = $st.Read($buf, 0, $buf.Length)) -gt 0) { $total += $n; if (Test-JobCancel) { break } }
        $sw.Stop(); $st.Close(); $rs.Close()
        $down = ($total * 8.0 / 1000000.0) / $sw.Elapsed.TotalSeconds
    } catch { Write-WhLog (([string][char]0x0130 + 'ndirme testi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $_.Exception.Message) 'WARN' }
    Set-JobProgress 2 3 ('Y' + [char]0x00FC + 'kleme')
    $up = 0.0
    try {
        $data = New-Object 'byte[]' 8000000
        $rq = [System.Net.WebRequest]::Create('https://speed.cloudflare.com/__up'); $rq.Method = 'POST'; $rq.ContentLength = $data.Length; $rq.Timeout = 30000
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $os = $rq.GetRequestStream(); $os.Write($data, 0, $data.Length); $os.Close()
        $rs = $rq.GetResponse(); $rs.Close(); $sw.Stop()
        $up = ($data.Length * 8.0 / 1000000.0) / $sw.Elapsed.TotalSeconds
    } catch { Write-WhLog (('Y' + [char]0x00FC + 'kleme testi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $_.Exception.Message) 'WARN' }
    Set-JobProgress 3 3
    Write-WhLog ((('Sonu' + [char]0x00E7 + ': indirme {0:N1} Mb/sn | y' + [char]0x00FC + 'kleme {1:N1} Mb/sn | gecikme {2:N0} ms') -f $down, $up, $latMs)) 'OK'
    return @{ Down = $down; Up = $up; Latency = $latMs }
}

function Job_NetReset($P) {
    Write-WhLog ('=== A' + [char]0x011F + ' y' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor (Winsock, IP, DNS)') 'STEP'
    Set-JobProgress 0 4 ('A' + [char]0x011F + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama')
    foreach ($c in @(@('netsh.exe', @('winsock', 'reset')), @('netsh.exe', @('int', 'ip', 'reset')), @('ipconfig.exe', @('/flushdns')), @('ipconfig.exe', @('/registerdns')))) {
        [void](Invoke-NativeLines $c[0] $c[1])
        Step-JobProgress
    }
    Write-WhLog ('Tamamland' + [char]0x0131 + '. De' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerin etkili olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') 'WARN'
    Write-Thanks
    return @{ Reboot = $true }
}

# ---------------- islem listesi ----------------
$script:CriticalProcs = @('system', 'registry', 'smss', 'csrss', 'wininit', 'winlogon', 'services', 'lsass', 'svchost', 'dwm', 'fontdrvhost', 'msmpeng', 'securityhealthservice', 'memory compression', 'idle', 'sihost', 'explorer', 'taskhostw', 'ctfmon', 'audiodg')

function Job_Procs($P) {
    $rows = New-Object System.Collections.ArrayList
    foreach ($p in @(Get-Process -ErrorAction SilentlyContinue | Sort-Object WorkingSet64 -Descending | Select-Object -First 40)) {
        $path = ''
        try { $path = [string]$p.Path } catch { }
        $crit = ($script:CriticalProcs -contains $p.ProcessName.ToLowerInvariant())
        [void]$rows.Add(@{ Name = [string]$p.ProcessName; Pid = [int]$p.Id; Mem = [double]$p.WorkingSet64; Cpu = [double]$p.CPU; Path = $path; Critical = $crit; Title = [string]$p.MainWindowTitle })
    }
    return @{ Rows = $rows.ToArray() }
}

function Job_Kill($P) {
    $pid2 = [int]$P.Pid
    try {
        $p = Get-Process -Id $pid2 -ErrorAction Stop
        if ($script:CriticalProcs -contains $p.ProcessName.ToLowerInvariant()) { Write-WhLog (('Sistem i' + [char]0x015F + 'lemi sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'lamaz: ') + $p.ProcessName) 'WARN'; return @{ Ok = $false } }
        Stop-Process -Id $pid2 -Force -ErrorAction Stop
        Write-WhLog (([string][char]0x0130 + [char]0x015F + 'lem sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $p.ProcessName + ' (PID ' + $pid2 + ')') 'OK'
        return @{ Ok = $true }
    } catch { Write-WhLog (('Sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false } }
}

# ---------------- canli izleme (kendi is parcaciginda; $sync.Mon alanlarini gunceller) ----------------
# Ilke: hicbir olcum izlemeyi durduramaz, bellegi buyutemez ya da uygulama surecini dusuremez.
#  - Her olcumun kendi devre kesicisi vardir: art arda hata olursa bir sure atlanir, sonra yeniden denenir; hic calismadiysa birakilir.
#  - Ag: yonetilen NetworkInterface istatistikleri (PerformanceCounter / Get-Counter kullanilmaz).
#  - GPU: Get-Counter (PDH) yerine CIM sinifi. Sorgu WMI sunucu surecinde calisir; orada bir sorun olsa bile uygulama surecini etkilemez.
#  - Bellek: GlobalMemoryStatusEx (ComputerInfo); WMI her turda sorgulanmaz.
#  - Process nesneleri her turda Dispose edilir; sayaclar bir kez olusturulur.
#  - $sync.MonBeat her turda guncellenir: arayuz, izleme donarsa ya da kapanirsa onu yeniden baslatir (Test-MonitorAlive).

function New-MonBreaker([int]$Limit = 3, [int]$Cool = 6) {
    return @{ Fail = 0; Skip = 0; Limit = $Limit; Cool = $Cool; Total = 0; Trips = 0; Ever = $false; Dead = $false }
}

# $true ise bu deneme atlanir (sayac bir azalir). Hic basarmamis ve 3 kez devre kesmis olcum bir daha denenmez.
function Test-MonBreakerSkip($B) {
    if ($B.Dead -eq $true) { return $true }
    if ([int]$B.Skip -gt 0) { $B.Skip = [int]$B.Skip - 1; return $true }
    return $false
}

function Set-MonBreakerResult($B, [bool]$Ok) {
    if ($Ok) { $B.Fail = 0; $B.Ever = $true; return }
    $B.Total = [int]$B.Total + 1
    $B.Fail = [int]$B.Fail + 1
    if ([int]$B.Fail -ge [int]$B.Limit) {
        $B.Fail = 0
        $B.Skip = [int]$B.Cool
        $B.Trips = [int]$B.Trips + 1
        if ($B.Ever -ne $true -and [int]$B.Trips -ge 3) { $B.Dead = $true }
    }
}

# Bir olcumu devre kesici arkasinda calistirir. Atlandiysa $null; aksi halde @{ Ok = ...; V = deger }.
# Govde $null dondururse ya da hata verirse basarisiz sayilir.
function Invoke-MonStep($Breaker, [scriptblock]$Body) {
    if (Test-MonBreakerSkip $Breaker) { return $null }
    $r = $null
    try { $r = & $Body } catch { $r = $null }
    $ok = ($null -ne $r)
    Set-MonBreakerResult $Breaker $ok
    return @{ Ok = $ok; V = $r }
}

# ---- ag ----
# Fiziksel (kablolu / kablosuz) arayuzlerin toplam bayt sayaclari: arayuz kimligi -> @(alinan, gonderilen)
function Get-NetByteTotals {
    $res = @{}
    foreach ($ni in @([System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces())) {
        try {
            if ($ni.OperationalStatus -ne [System.Net.NetworkInformation.OperationalStatus]::Up) { continue }
            $t = $ni.NetworkInterfaceType
            if ($t -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Loopback -or $t -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Tunnel) { continue }
            if ([string]$ni.Description -match 'Virtual|Hyper-V|vEthernet|VMware|VirtualBox|Pseudo|isatap|Teredo|Miniport|Bluetooth|Loopback') { continue }
            $st = $ni.GetIPv4Statistics()
            $res[[string]$ni.Id] = @([double]$st.BytesReceived, [double]$st.BytesSent)
        } catch { }
    }
    return $res
}

# Iki olcum arasindaki fark / sure = bayt/sn. Windows'un IPv4 sayaclari 32 bittir (4 GB'ta basa sarar): negatif fark sarma sayilir.
# Iki olcumde de bulunan arayuzler toplanir (arayuz eklenip cikinca sicrama olmaz). Makul olmayan (> 5 GB/sn) degerler atilir.
function Get-NetRate($Prev, $Cur, [double]$Seconds) {
    $down = 0.0; $up = 0.0
    if ($null -eq $Prev -or $null -eq $Cur -or $Seconds -lt 0.05) { return @{ Down = 0.0; Up = 0.0 } }
    $wrap = 4294967296.0
    foreach ($k in @($Cur.Keys)) {
        if (-not $Prev.ContainsKey($k)) { continue }
        $a = $Cur[$k]; $b = $Prev[$k]
        for ($i = 0; $i -lt 2; $i++) {
            $d = [double]$a[$i] - [double]$b[$i]
            if ($d -lt 0) {
                if ([double]$b[$i] -lt $wrap -and [double]$a[$i] -lt $wrap) { $d += $wrap } else { $d = 0.0 }
            }
            if (($d / $Seconds) -gt 5000000000.0) { $d = 0.0 }
            if ($i -eq 0) { $down += $d } else { $up += $d }
        }
    }
    return @{ Down = ($down / $Seconds); Up = ($up / $Seconds) }
}

# ---- GPU ----
# GPU Engine satirlarindan (Name, UtilizationPercentage) en yuklu 3D motorun yuzdesini verir; ayni motoru kullanan islemler toplanir.
# -1 = bu bicimde satir yok (GPU yok / surucu sayac vermiyor).
function Get-GpuLoadFromRows($Rows) {
    $eng = @{}
    $seen = 0
    foreach ($r in @($Rows)) {
        $n = [string]$r.Name
        if ($n -match 'luid_(0x[0-9A-Fa-f]+_0x[0-9A-Fa-f]+)_phys_(\d+)_eng_(\d+)_engtype_(\w+)') {
            $seen++
            if ($Matches[4] -ne '3D') { continue }
            $key = $Matches[1] + '/' + $Matches[2] + '/' + $Matches[3]
            $v = 0.0
            try { $v = [double]$r.UtilizationPercentage } catch { $v = 0.0 }
            if ($eng.ContainsKey($key)) { $eng[$key] = [double]$eng[$key] + $v } else { $eng[$key] = $v }
        }
    }
    if ($seen -eq 0) { return -1.0 }
    $mx = 0.0
    foreach ($k in @($eng.Keys)) { if ([double]$eng[$k] -gt $mx) { $mx = [double]$eng[$k] } }
    return [math]::Min(100.0, [math]::Round($mx, 0))
}

function Get-MonGpuLoad {
    $rows = @(Get-CimInstance -ClassName Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine -OperationTimeoutSec 6 -ErrorAction Stop)
    return (Get-GpuLoadFromRows $rows)
}

# ---- bellek ----
$script:MonCi = $null
function Get-MonMemory {
    try {
        if ($null -eq $script:MonCi) {
            Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction Stop
            $script:MonCi = New-Object Microsoft.VisualBasic.Devices.ComputerInfo
        }
        $tot = [double]$script:MonCi.TotalPhysicalMemory
        $free = [double]$script:MonCi.AvailablePhysicalMemory
        if ($tot -gt 0) {
            return @{ Pct = [math]::Round(100.0 * (1.0 - $free / $tot), 0); UsedGB = [math]::Round(($tot - $free) / 1GB, 1); TotalGB = [math]::Round($tot / 1GB, 1) }
        }
    } catch { $script:MonCi = $null }
    $os = Get-CimInstance -ClassName Win32_OperatingSystem -OperationTimeoutSec 6 -ErrorAction Stop
    $tk = [double]$os.TotalVisibleMemorySize; $fk = [double]$os.FreePhysicalMemory
    if ($tk -le 0) { return $null }
    return @{ Pct = [math]::Round(100.0 * (1.0 - $fk / $tk), 0); UsedGB = [math]::Round(($tk - $fk) / 1MB, 1); TotalGB = [math]::Round($tk / 1MB, 1) }
}

# ---- sayaclar ----
function New-MonCounter([string]$Cat, [string]$Name, [string]$Inst) {
    try {
        $c = New-Object System.Diagnostics.PerformanceCounter($Cat, $Name, $Inst, $true)
        [void]$c.NextValue()
        return $c
    } catch { return $null }
}

function New-MonCpuCounter {
    $c = New-MonCounter 'Processor Information' '% Processor Utility' '_Total'
    if ($null -eq $c) { $c = New-MonCounter 'Processor' '% Processor Time' '_Total' }
    return $c
}

function Read-MonCounter($C) {
    $v = [double]$C.NextValue()
    if ([double]::IsNaN($v) -or [double]::IsInfinity($v)) { return $null }
    return [math]::Min(100.0, [math]::Max(0.0, [math]::Round($v, 0)))
}

# ---- en cok CPU kullanan islemler ----
# Prev: islem no -> @(toplam CPU sn, zaman). Donus: @{ Cur = yeni Prev; Top = en yuklu 5 }. Her Process nesnesi Dispose edilir.
function Get-MonTop($Prev, [int]$Cores) {
    $now = Get-Date
    $list = New-Object System.Collections.ArrayList
    $cur = @{}
    if ($Cores -lt 1) { $Cores = 1 }
    foreach ($p in @([System.Diagnostics.Process]::GetProcesses())) {
        try {
            $id = [int]$p.Id
            if ($id -eq 0) { continue }
            $t = $p.TotalProcessorTime.TotalSeconds
            $cur[$id] = @($t, $now)
            if ($Prev.ContainsKey($id)) {
                $dt = ($now - $Prev[$id][1]).TotalSeconds
                if ($dt -gt 0) {
                    $pct = 100.0 * ($t - $Prev[$id][0]) / $dt / $Cores
                    if ($pct -lt 0) { $pct = 0.0 }
                    [void]$list.Add(@{ Name = [string]$p.ProcessName; Cpu = [math]::Round($pct, 1); Mem = [double]$p.WorkingSet64; Pid = $id; Win = $false })
                }
            }
        } catch { } finally { try { $p.Dispose() } catch { } }
    }
    $top = @($list | Sort-Object { -1 * [double]$_.Cpu } | Select-Object -First 5)
    foreach ($tp in $top) {
        try {
            $pp = [System.Diagnostics.Process]::GetProcessById([int]$tp.Pid)
            try { $tp.Win = ($pp.MainWindowHandle -ne [IntPtr]::Zero) } finally { $pp.Dispose() }
        } catch { $tp.Win = $false }
    }
    return @{ Cur = $cur; Top = $top }
}

function Job_Monitor($P) {
    $interval = [int]$P.Interval; if ($interval -lt 1) { $interval = 2 }
    $cores = [Environment]::ProcessorCount
    $br = @{
        Cpu = (New-MonBreaker 3 10); Disk = (New-MonBreaker 3 10); Mem = (New-MonBreaker 3 5)
        Gpu = (New-MonBreaker 3 6); Temp = (New-MonBreaker 3 9); Game = (New-MonBreaker 3 6); Top = (New-MonBreaker 3 5); Net = (New-MonBreaker 3 10)
    }
    $st = @{ Cpu = $null; Disk = $null; NetPrev = $null; NetAt = $null; TopPrev = @{} }
    $last = @{ Cpu = 0.0; Disk = 0.0; Ram = 0.0; RamUsedGB = 0.0; RamTotalGB = 0.0; NetDown = 0.0; NetUp = 0.0; Gpu = -1.0; Temp = -1.0; Games = @(); Top = @() }
    $bootAt = $null
    try { $bootAt = (Get-CimInstance -ClassName Win32_OperatingSystem -OperationTimeoutSec 8 -ErrorAction Stop).LastBootUpTime } catch { }
    if ($null -eq $bootAt) {
        try {
            $tc = [double][Environment]::TickCount
            if ($tc -lt 0) { $tc += 4294967296.0 }
            $bootAt = (Get-Date).AddMilliseconds(-1.0 * $tc)
        } catch { }
    }
    $tick = 0
    $sw = New-Object System.Diagnostics.Stopwatch
    while ($sync.Stop -ne $true) {
        $sw.Restart()
        $m = @{}
        $m.Boot = $bootAt

        # CPU ve disk (sayaclar bir kez olusturulur; bozulursa atilir, devre kesici aciksa daha sonra yeniden kurulur)
        $s = Invoke-MonStep $br.Cpu {
            if ($null -eq $st.Cpu) { $st.Cpu = New-MonCpuCounter }
            if ($null -eq $st.Cpu) { return $null }
            try { return (Read-MonCounter $st.Cpu) } catch { try { $st.Cpu.Dispose() } catch { }; $st.Cpu = $null; return $null }
        }
        if ($null -ne $s -and $s.Ok) { $last.Cpu = [double]$s.V }
        $m.Cpu = $last.Cpu

        $s = Invoke-MonStep $br.Disk {
            if ($null -eq $st.Disk) { $st.Disk = New-MonCounter 'PhysicalDisk' '% Disk Time' '_Total' }
            if ($null -eq $st.Disk) { return $null }
            try { return (Read-MonCounter $st.Disk) } catch { try { $st.Disk.Dispose() } catch { }; $st.Disk = $null; return $null }
        }
        if ($null -ne $s -and $s.Ok) { $last.Disk = [double]$s.V }
        $m.Disk = $last.Disk

        # bellek
        $s = Invoke-MonStep $br.Mem { Get-MonMemory }
        if ($null -ne $s -and $s.Ok) { $last.Ram = [double]$s.V.Pct; $last.RamUsedGB = [double]$s.V.UsedGB; $last.RamTotalGB = [double]$s.V.TotalGB }
        $m.Ram = $last.Ram; $m.RamUsedGB = $last.RamUsedGB; $m.RamTotalGB = $last.RamTotalGB

        # ag: iki tur arasindaki bayt farki / gecen sure
        $s = Invoke-MonStep $br.Net { Get-NetByteTotals }
        if ($null -ne $s -and $s.Ok) {
            $nowAt = [DateTime]::UtcNow
            if ($null -ne $st.NetPrev -and $null -ne $st.NetAt) {
                $rate = Get-NetRate $st.NetPrev $s.V (($nowAt - $st.NetAt).TotalSeconds)
                $last.NetDown = [double]$rate.Down; $last.NetUp = [double]$rate.Up
            }
            $st.NetPrev = $s.V; $st.NetAt = $nowAt
        } elseif ($null -ne $s) { $last.NetDown = 0.0; $last.NetUp = 0.0 }
        $m.NetDown = $last.NetDown; $m.NetUp = $last.NetUp

        # GPU: her 5 turda bir (ilk tur atlanir; WMI sinifinin ilk cagrisi yavas olabilir). Guvenli kipte ya da ayar kapaliysa hic sorgulanmaz.
        if (($tick % 5) -eq 1 -and $sync.SafeMon -ne $true -and $sync.NoGpu -ne $true) {
            $s = Invoke-MonStep $br.Gpu { $v = Get-MonGpuLoad; if ([double]$v -lt 0) { $null } else { $v } }
            if ($null -ne $s -and $s.Ok) { $last.Gpu = [double]$s.V }
            elseif ($null -ne $s) { $last.Gpu = -1.0 }
        }
        if ($sync.SafeMon -eq $true -or $sync.NoGpu -eq $true) { $last.Gpu = -1.0 }
        $m.Gpu = $last.Gpu

        # sicaklik: her 5 turda bir; hic deger vermeyen (sensorsuz) makinelerde birkac denemeden sonra birakilir
        if (($tick % 5) -eq 3) {
            $s = Invoke-MonStep $br.Temp { $v = Get-ThermalTemp; if ([double]$v -le 0) { $null } else { $v } }
            if ($null -ne $s -and $s.Ok) { $last.Temp = [double]$s.V }
            elseif ($null -ne $s) { $last.Temp = -1.0 }
        }
        $m.Temp = $last.Temp
        if (($tick % 5) -eq 4 -and $sync.SafeMon -ne $true -and $sync.NoGpu -ne $true) { try { $last.GpuTemp = [double](Get-GpuTemp) } catch { $last.GpuTemp = -1.0 } }
        if ($null -eq $last.GpuTemp) { $last.GpuTemp = -1.0 }
        $m.GpuTemp = [double]$last.GpuTemp

        # calisan oyunlar (klasorler arayuzden $sync.GameDirs ile verilir; islem yolu okumak pahali oldugu icin 10 sn'de bir)
        if (($tick % 5) -eq 2 -and $null -ne $sync.GameDirs) {
            $s = Invoke-MonStep $br.Game { , @(Get-GmRunning @($sync.GameDirs)) }
            if ($null -ne $s -and $s.Ok) { $last.Games = $s.V } elseif ($null -ne $s) { $last.Games = @() }
        }
        $m.Games = $last.Games

        # en cok CPU kullanan islemler (her 3 turda)
        if (($tick % 3) -eq 0) {
            $s = Invoke-MonStep $br.Top { Get-MonTop $st.TopPrev $cores }
            if ($null -ne $s -and $s.Ok) { $st.TopPrev = $s.V.Cur; $last.Top = $s.V.Top }
        }
        $m.Top = $last.Top

        $m.Time = Get-Date
        $sync.MonWarmGpu = ($tick -lt 1); $sync.MonWarmTemp = ($tick -lt 3)
        $sync.Mon = $m
        $sync.MonBeat = [DateTime]::UtcNow
        $sync.MonDiag = @{ Tick = $tick; Ms = [int]$sw.ElapsedMilliseconds; GpuFail = [int]$br.Gpu.Total; TempFail = [int]$br.Temp.Total; NetFail = [int]$br.Net.Total; GpuDead = [bool]$br.Gpu.Dead; TempDead = [bool]$br.Temp.Dead }
        $tick++
        # ayrintili hata gunlugu aciksa bu calisma alaninda yutulan hatalar da yazilir (yaklasik 10 turda bir)
        if (($tick % 5) -eq 0 -and $sync.DebugLog -eq $true) { try { [void](Save-DebugErrors 'izleme') } catch { } }
        $slept = 0
        $iv = $interval
        if ($null -ne $sync.MonInterval -and [int]$sync.MonInterval -ge 1) { $iv = [int]$sync.MonInterval }
        while ($slept -lt ($iv * 1000) -and $sync.Stop -ne $true) { Start-Sleep -Milliseconds 250; $slept += 250 }
    }
    try { if ($null -ne $st.Cpu) { $st.Cpu.Dispose() } } catch { }
    try { if ($null -ne $st.Disk) { $st.Disk.Dispose() } } catch { }
    return @{ Stopped = $true }
}

