function Get-AppTitleText { return ('Multimizer') }

function Job_Inventory($P) {
    Set-JobProgress 0 1 ('Envanter toplan' + [char]0x0131 + 'yor')
    $inv = @(Get-Inventory)
    Set-JobProgress 1 1
    return @{ Sections = $inv }
}

# ---------------- uygulama simgesi (calisma aninda cizilir; dis dosya gerekmez) ----------------
function New-AppIconBitmap([int]$Size = 32) {
    # MULTIMIZER simgesi: gradyanli altigen + beyaz "M" (calisma aninda cizilir; dis dosya gerekmez)
    $bmp = New-Object System.Drawing.Bitmap -ArgumentList $Size, $Size
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $g.Clear([System.Drawing.Color]::Transparent)
    $k = $Size / 32.0
    $hx = @(16, 28, 28, 16, 4, 4)
    $hy = @(1.2, 8.2, 23.8, 30.8, 23.8, 8.2)
    $hex = New-Object 'System.Drawing.PointF[]' 6
    for ($i = 0; $i -lt 6; $i++) { $hex[$i] = New-Object System.Drawing.PointF -ArgumentList ([single]($hx[$i] * $k)), ([single]($hy[$i] * $k)) }
    $gp = New-Object System.Drawing.Drawing2D.GraphicsPath
    $gp.AddPolygon($hex)
    $rect = New-Object System.Drawing.Rectangle -ArgumentList 0, 0, $Size, $Size
    $c1 = [System.Drawing.Color]::FromArgb(34, 211, 238)
    $c2 = [System.Drawing.Color]::FromArgb(139, 92, 246)
    $br = New-Object System.Drawing.Drawing2D.LinearGradientBrush -ArgumentList $rect, $c1, $c2, ([single]55.0)
    $g.FillPath($br, $gp)
    $pen = New-Object System.Drawing.Pen -ArgumentList ([System.Drawing.Color]::White), ([single](2.8 * $k))
    $pen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
    $pen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
    $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
    $mx = @(10, 10, 16, 22, 22)
    $my = @(22.5, 10.5, 17.5, 10.5, 22.5)
    $m = New-Object 'System.Drawing.PointF[]' 5
    for ($i = 0; $i -lt 5; $i++) { $m[$i] = New-Object System.Drawing.PointF -ArgumentList ([single]($mx[$i] * $k)), ([single]($my[$i] * $k)) }
    $g.DrawLines($pen, $m)
    $pen.Dispose(); $br.Dispose(); $gp.Dispose(); $g.Dispose()
    return $bmp
}


# ICO dosyasi yazar (tek PNG imgeli; Windows Vista ve ustu okur)
function Save-AppIcon([string]$Path) {
    try { Add-Type -AssemblyName System.Drawing -ErrorAction SilentlyContinue } catch { }
    $bmp = New-AppIconBitmap 64
    $ms = New-Object System.IO.MemoryStream
    $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
    $png = $ms.ToArray()
    $bmp.Dispose(); $ms.Dispose()
    $fs = [System.IO.File]::Create($Path)
    try {
        $bw = New-Object System.IO.BinaryWriter($fs)
        $bw.Write([uint16]0); $bw.Write([uint16]1); $bw.Write([uint16]1)
        $bw.Write([byte]64); $bw.Write([byte]64); $bw.Write([byte]0); $bw.Write([byte]0)
        $bw.Write([uint16]1); $bw.Write([uint16]32)
        $bw.Write([uint32]$png.Length); $bw.Write([uint32]22)
        $bw.Write($png)
        $bw.Flush()
    } finally { $fs.Close() }
}


# Eski adla kurulmus zamanlanmis gorevleri ve kisayollari kaldirir (yeni adla yeniden kurulur)
function Remove-LegacyInstall {
    try {
        foreach ($t in @(Get-ScheduledTask -TaskPath '\WinHizlandirici\' -ErrorAction SilentlyContinue)) {
            try { Unregister-ScheduledTask -TaskName $t.TaskName -TaskPath '\WinHizlandirici\' -Confirm:$false -ErrorAction Stop } catch { }
        }
    } catch { }
    try {
        $old = 'Windows H' + [char]0x0131 + 'zland' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + '.lnk'
        foreach ($dir in @([Environment]::GetFolderPath('CommonPrograms'), [Environment]::GetFolderPath('CommonDesktopDirectory'))) {
            $f = Join-Path $dir $old
            if (Test-Path -LiteralPath $f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
        }
    } catch { }
}

# ---------------- kurulum ----------------
function Get-InstallDir { return (Join-Path $sync.DataDir 'Uygulama') }
function Get-InstalledScriptPath { return (Join-Path (Get-InstallDir) 'Multimizer.ps1') }

# Betigi kalici klasore kopyalar (zamanlanmis gorevler ve kisayollar bunu kullanir)
function Install-AppFiles {
    $dir = Get-InstallDir
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $dst = Get-InstalledScriptPath
    $src = [string]$sync.ScriptPath
    if ($src -eq '' -or -not (Test-Path -LiteralPath $src)) { throw ('Kaynak betik bulunamad' + [char]0x0131 + '.') }
    if ([System.IO.Path]::GetFullPath($src) -ne [System.IO.Path]::GetFullPath($dst)) {
        Copy-Item -LiteralPath $src -Destination $dst -Force
    }
    $srcDir = [System.IO.Path]::GetDirectoryName($src)
    if ([System.IO.Path]::GetFullPath($srcDir) -ne [System.IO.Path]::GetFullPath($dir)) {
        foreach ($sub in @('veri', 'Eklenti')) {
            $sp = Join-Path $srcDir $sub
            if (Test-Path -LiteralPath $sp -PathType Container) {
                $dp = Join-Path $dir $sub
                if (-not (Test-Path -LiteralPath $dp)) { New-Item -ItemType Directory -Path $dp -Force | Out-Null }
                Copy-Item -Path (Join-Path $sp '*') -Destination $dp -Recurse -Force
            }
        }
    }
    if ([System.IO.Path]::GetFullPath($srcDir) -ne [System.IO.Path]::GetFullPath($dir)) {
        foreach ($side in @('Acilis.ps1', 'Tani.ps1')) {
            $sp = Join-Path $srcDir $side
            if (Test-Path -LiteralPath $sp) { try { Copy-Item -LiteralPath $sp -Destination (Join-Path $dir $side) -Force } catch { } }
        }
    }
    Save-AppIcon (Join-Path $dir 'Multimizer.ico')
    return $dst
}

function New-AppShortcut([string]$LnkPath, [string]$ScriptPath, [string]$IconPath, [string]$Extra) {
    $ws = New-Object -ComObject WScript.Shell
    $l = $ws.CreateShortcut($LnkPath)
    $l.TargetPath = (Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe')
    $launch = $ScriptPath
    $ac = Join-Path (Split-Path -Parent $ScriptPath) 'Acilis.ps1'
    if (Test-Path -LiteralPath $ac) { $launch = $ac }
    $l.Arguments = ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -STA -File "' + $launch + '" ' + $Extra).Trim()
    $l.WorkingDirectory = (Split-Path -Parent $ScriptPath)
    $l.WindowStyle = 7
    $l.Description = (Get-AppTitleText)
    if (Test-Path -LiteralPath $IconPath) { $l.IconLocation = $IconPath }
    $l.Save()
    # "Yonetici olarak calistir" bayragi
    try {
        $b = [System.IO.File]::ReadAllBytes($LnkPath)
        if ($b.Length -gt 0x16) { $b[0x15] = ($b[0x15] -bor 0x20); [System.IO.File]::WriteAllBytes($LnkPath, $b) }
    } catch { }
}

function Get-ShortcutPaths {
    $t = Get-AppTitleText
    return @{
        Menu = (Join-Path ([Environment]::GetFolderPath('CommonPrograms')) ($t + '.lnk'))
        Desktop = (Join-Path ([Environment]::GetFolderPath('CommonDesktopDirectory')) ($t + '.lnk'))
    }
}

function Job_Install($P) {
    try {
        $dst = Install-AppFiles
        $ico = Join-Path (Get-InstallDir) 'Multimizer.ico'
        $sp = Get-ShortcutPaths
        New-AppShortcut $sp.Menu $dst $ico ''
        Write-WhLog (('Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + ' k' + [char]0x0131 + 'sayolu olu' + [char]0x015F + 'turuldu: ') + $sp.Menu) 'OK'
        if ([bool]$P.Desktop) { New-AppShortcut $sp.Desktop $dst $ico ''; Write-WhLog (('Masa' + [char]0x00FC + 'st' + [char]0x00FC + ' k' + [char]0x0131 + 'sayolu olu' + [char]0x015F + 'turuldu: ') + $sp.Desktop) 'OK' }
        $st = Get-Settings
        $st.Installed = $true
        Save-Settings $st
        Write-WhLog ('Uygulama kuruldu: ' + $dst) 'OK'
        return @{ Ok = $true; Path = $dst }
    } catch {
        Write-WhLog (('Kurulum ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false }
    }
}

function Job_Uninstall($P) {
    try {
        [void](Remove-AllAppTasks)
        $sp = Get-ShortcutPaths
        foreach ($f in @($sp.Menu, $sp.Desktop)) { if (Test-Path -LiteralPath $f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue; Write-WhLog (('K' + [char]0x0131 + 'sayol silindi: ') + $f) 'OK' } }
        $dir = Get-InstallDir
        if (Test-Path -LiteralPath $dir) { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue; Write-WhLog ('Uygulama klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' silindi (kay' + [char]0x0131 + 'tlar ve yedekler korunur).') 'OK' }
        $st = Get-Settings
        $st.Installed = $false; $st.Autostart = $false; $st.MaintEnabled = $false; $st.BackupSchedEnabled = $false; $st.ReportEnabled = $false
        Save-Settings $st
        return @{ Ok = $true }
    } catch {
        Write-WhLog (('Kald' + [char]0x0131 + 'rma ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false }
    }
}

# ---------------- zamanlanmis gorevler ----------------
$script:TaskFolder = '\Multimizer\'

function Get-TaskUser {
    $u = [string]$sync.RunUser
    if ($u -eq '') { $u = [Security.Principal.WindowsIdentity]::GetCurrent().Name }
    return $u
}

function ConvertTo-TaskTime([string]$Text, [string]$Default) {
    $t = $Text.Trim()
    if ($t -notmatch '^([01]?\d|2[0-3]):([0-5]\d)$') { $t = $Default }
    $p = $t.Split(':')
    return [datetime]::Today.AddHours([int]$p[0]).AddMinutes([int]$p[1])
}

function Register-AppTask([string]$Name, $Trigger, [string]$Mode, [string]$Desc) {
    $exe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $script = Get-InstalledScriptPath
    $argLine = ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $script + '" ' + $Mode)
    $act = New-ScheduledTaskAction -Execute $exe -Argument $argLine
    $prin = New-ScheduledTaskPrincipal -UserId (Get-TaskUser) -LogonType Interactive -RunLevel Highest
    $set = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Hours 3)
    $task = New-ScheduledTask -Action $act -Trigger $Trigger -Principal $prin -Settings $set -Description $Desc
    Register-ScheduledTask -TaskName $Name -TaskPath $script:TaskFolder -InputObject $task -Force | Out-Null
}

function Remove-AppTask([string]$Name) {
    try { Unregister-ScheduledTask -TaskName $Name -TaskPath $script:TaskFolder -Confirm:$false -ErrorAction Stop } catch { }
}

function Remove-AllAppTasks {
    foreach ($n in @('Bakim', 'Yedek', 'Rapor', 'Tepsi')) { Remove-AppTask $n }
    return $true
}

# Ayarlara gore gorevleri kurar / kaldirir
function Sync-AppTasks {
    Remove-LegacyInstall
    $st = Get-Settings
    $any = ($st.MaintEnabled -eq $true -or $st.BackupSchedEnabled -eq $true -or $st.ReportEnabled -eq $true -or $st.Autostart -eq $true)
    if ($any) { [void](Install-AppFiles) }
    $user = Get-TaskUser
    if ($st.MaintEnabled -eq $true) {
        $day = [string]$st.MaintDay; if ($day -eq '') { $day = 'Sunday' }
        $trg = New-ScheduledTaskTrigger -Weekly -DaysOfWeek $day -At (ConvertTo-TaskTime ([string]$st.MaintTime) '03:00')
        Register-AppTask 'Bakim' $trg '-Cli -Gorev Bakim -Sessiz' ('Multimizer: haftal' + [char]0x0131 + 'k bak' + [char]0x0131 + 'm (ge' + [char]0x00E7 + 'ici dosya temizli' + [char]0x011F + 'i, disk optimizasyonu)')
        Write-WhLog (('G' + [char]0x00F6 + 'rev kuruldu: haftal' + [char]0x0131 + 'k bak' + [char]0x0131 + 'm (') + $day + ' ' + [string]$st.MaintTime + ')') 'OK'
    } else { Remove-AppTask 'Bakim' }
    if ($st.BackupSchedEnabled -eq $true) {
        $trg = New-ScheduledTaskTrigger -Daily -At (ConvertTo-TaskTime ([string]$st.BackupSchedTime) '21:00')
        Register-AppTask 'Yedek' $trg '-Cli -Gorev Yedekle -Sessiz' ('Multimizer: g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k dosya yede' + [char]0x011F + 'i')
        Write-WhLog (('G' + [char]0x00F6 + 'rev kuruldu: g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k yedek (') + [string]$st.BackupSchedTime + ')') 'OK'
    } else { Remove-AppTask 'Yedek' }
    if ($st.ReportEnabled -eq $true) {
        $day = [string]$st.ReportDay; if ($day -eq '') { $day = 'Monday' }
        $trg = New-ScheduledTaskTrigger -Weekly -DaysOfWeek $day -At (ConvertTo-TaskTime ([string]$st.ReportTime) '08:30')
        Register-AppTask 'Rapor' $trg '-Cli -Gorev Rapor -Sessiz' ('Multimizer: haftal' + [char]0x0131 + 'k durum raporu')
        Write-WhLog (('G' + [char]0x00F6 + 'rev kuruldu: haftal' + [char]0x0131 + 'k rapor (') + $day + ' ' + [string]$st.ReportTime + ')') 'OK'
    } else { Remove-AppTask 'Rapor' }
    if ($st.Autostart -eq $true) {
        $trg = New-ScheduledTaskTrigger -AtLogOn -User $user
        try { $trg.Delay = 'PT30S' } catch { }
        Register-AppTask 'Tepsi' $trg '-Tepsi' ('Multimizer: oturum a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'nda tepside ba' + [char]0x015F + 'lat')
        Write-WhLog ('G' + [char]0x00F6 + 'rev kuruldu: oturum a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'nda tepside ba' + [char]0x015F + 'lat') 'OK'
    } else { Remove-AppTask 'Tepsi' }
}

function Job_SyncTasks($P) {
    try {
        Sync-AppTasks
        return @{ Ok = $true }
    } catch {
        Write-WhLog (('Zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'rev kurulamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false }
    }
}

function Job_TaskInfo($P) {
    $rows = New-Object System.Collections.ArrayList
    try {
        foreach ($t in @(Get-ScheduledTask -TaskPath $script:TaskFolder -ErrorAction Stop)) {
            $i = Get-ScheduledTaskInfo -InputObject $t -ErrorAction SilentlyContinue
            $nx = ''; $ls = ''; $res = 0
            if ($null -ne $i) {
                if ($i.NextRunTime -gt [datetime]'2000-01-01') { $nx = $i.NextRunTime.ToString('yyyy-MM-dd HH:mm') }
                if ($i.LastRunTime -gt [datetime]'2000-01-01') { $ls = $i.LastRunTime.ToString('yyyy-MM-dd HH:mm') }
                $res = [int]$i.LastTaskResult
            }
            [void]$rows.Add(@{ Name = [string]$t.TaskName; State = [string]$t.State; Next = $nx; Last = $ls; Result = $res; Desc = [string]$t.Description })
        }
    } catch { }
    return @{ Rows = $rows.ToArray() }
}

# ---------------- ayar profili (bir kez hazirla, bircok bilgisayara uygula) ----------------
function New-ProfileObject([string]$Name, $TweakIds, $Services, $Apps) {
    $st = Get-Settings
    return [ordered]@{
        Tool = 'Multimizer'; Format = 1; Name = $Name; Org = [string]$st.Org
        Created = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss'); Version = [string]$sync.Version
        Tweaks = @($TweakIds | ForEach-Object { [string]$_ })
        Services = @($Services | ForEach-Object { [ordered]@{ Name = [string]$_.Name; Mode = [string]$_.Mode } })
        Apps = @($Apps | ForEach-Object { [string]$_ })
    }
}

# Profil nesnesinden uygulanabilir adimlar uretir; dogrulama: yalnizca katalogdaki kimlikler, korumasiz hizmetler, listelenmis uygulamalar
function Get-ProfileSteps($Prof, [System.Collections.ArrayList]$Notes) {
    $steps = New-Object System.Collections.ArrayList
    $ids = New-Object System.Collections.ArrayList
    foreach ($id in @($Prof.Tweaks)) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -eq $c) { [void]$Notes.Add(('Katalogda yok, atland' + [char]0x0131 + ': ') + [string]$id); continue }
        if (-not (Test-OsOk ([string]$c.OS) $sync.Profile)) { [void]$Notes.Add(('Bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'ne uygun de' + [char]0x011F + 'il, atland' + [char]0x0131 + ': ') + [string]$id); continue }
        [void]$ids.Add([string]$id)
    }
    if ($ids.Count -gt 0) { foreach ($s in (New-StepsFromIds $ids.ToArray())) { [void]$steps.Add($s) } }
    foreach ($mode in @('Off', 'Man', 'Auto')) {
        $names = New-Object System.Collections.ArrayList
        foreach ($sv in @($Prof.Services)) {
            if ([string]$sv.Mode -ne $mode) { continue }
            $n = [string]$sv.Name
            if ($n -cnotmatch '^[A-Za-z0-9_\.\-]{1,80}$') { [void]$Notes.Add(('Ge' + [char]0x00E7 + 'ersiz hizmet ad' + [char]0x0131 + ', atland' + [char]0x0131 + ': ') + $n); continue }
            if (Test-SvcLocked $n) { [void]$Notes.Add(('Korumal' + [char]0x0131 + ' hizmet, atland' + [char]0x0131 + ': ') + $n); continue }
            [void]$names.Add($n)
        }
        if ($names.Count -gt 0) { foreach ($s in (New-ServiceSteps $names.ToArray() $mode)) { [void]$steps.Add($s) } }
    }
    $ops = New-Object System.Collections.ArrayList
    $known = @($script:AppCatalog | ForEach-Object { [string]$_.P })
    foreach ($a in @($Prof.Apps)) {
        if ($known -contains [string]$a) { [void]$ops.Add(@{ T = 'Appx'; Name = [string]$a }) }
        else { [void]$Notes.Add(('Uygulama listesinde yok, atland' + [char]0x0131 + ': ') + [string]$a) }
    }
    if ($ops.Count -gt 0) { [void]$steps.Add(@{ Id = 'Apps'; Title = ('Profil: Ma' + [char]0x011F + 'aza uygulamalar' + [char]0x0131); Ops = $ops.ToArray(); Reboot = $false }) }
    return , $steps.ToArray()
}

function Read-ProfileFile([string]$Path) {
    $o = Read-JsonFile $Path
    if ($null -eq $o -or (@('Multimizer', 'WinHizlandirici') -notcontains [string]$o.Tool)) { throw ('Bu dosya bir Multimizer profili de' + [char]0x011F + 'il.') }
    return $o
}

function Job_ProfileApply($P) {
    try {
        $prof = Read-ProfileFile ([string]$P.Path)
    } catch {
        Write-WhLog (('Profil okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false }
    }
    $notes = New-Object System.Collections.ArrayList
    $steps = Get-ProfileSteps $prof $notes
    Write-WhLog ('Profil: ' + [string]$prof.Name + ' (' + [string]$prof.Org + ', ' + [string]$prof.Created + ')') 'INFO'
    foreach ($n in $notes) { Write-WhLog $n 'WARN' }
    if (@($steps).Count -eq 0) { Write-WhLog ('Uygulanacak ad' + [char]0x0131 + 'm yok.') 'WARN'; return @{ Ok = $false } }
    return (Job_Plan @{ Steps = @($steps); Preview = [bool]$P.Preview; RestorePoint = [bool]$P.RestorePoint })
}

# ---------------- Islem kayit defteri ----------------
# ==================================================================
#  ISLEM KAYIT DEFTERI: yeni islem turleri (T = 'FwApp', 'FwDev', ...) ve geri alma kayitlari buraya baglanir.
#  Invoke-Op ve Undo-ExtraItem bilmedikleri turleri bu iki isleve devreder.
# ==================================================================
$script:MoreOps = @{}
$script:MoreUndo = @{}

function Invoke-MoreOp($Op) {
    $t = [string]$Op.T
    if ($script:MoreOps.ContainsKey($t)) { & $script:MoreOps[$t] $Op; return }
    throw (('Bilinmeyen i' + [char]0x015F + 'lem t' + [char]0x00FC + 'r' + [char]0x00FC + ': ') + $t)
}

function Undo-MoreItem($It) {
    $t = [string]$It.T
    if ($script:MoreUndo.ContainsKey($t)) { & $script:MoreUndo[$t] $It; return }
    Write-WhLog (('Bilinmeyen kay' + [char]0x0131 + 't t' + [char]0x00FC + 'r' + [char]0x00FC + ': ') + $t) 'WARN'
}

# ---------------- Uyarlama motoru ----------------
# ==================================================================
#  UYARLAMA MOTORU: her bilgisayara ayni recete uygulanmaz.
#  - Donanim sinifi (dusuk / orta / guclu) bellek, islemci ve disk turunden hesaplanir.
#  - Ozellik kapatan ayarlar yalnizca gercekten ihtiyac duyan donanimda onerilir.
#  - Bir ayarin uygulanip uygulanmadigi onizleme motoruyla (sistemi degistirmeden) olculur;
#    boylece "oneri kaldi mi", "uyguladigim ayar geri donmus mu" sorularina yanit verilir.
# ==================================================================

# Hangi ayar hangi donanimda onerilir?
#   Low     = yalnizca dusuk donanimda
#   Mid     = dusuk ve orta donanimda
#   LowDisk = yalnizca sistem diskinde yer azken
# Listede olmayan ayarlar (gizlilik, guvenli temizlik vb.) donanimdan bagimsizdir.
$script:NeedMap = @{
    VisualFx      = @{ Need = 'Low';     Why = ('G' + [char]0x00F6 + 'rsel efektler yaln' + [char]0x0131 + 'zca zay' + [char]0x0131 + 'f donan' + [char]0x0131 + 'mda hissedilir bir y' + [char]0x00FC + 'k olu' + [char]0x015F + 'turur.') }
    Transparency  = @{ Need = 'Low';     Why = ('Saydaml' + [char]0x0131 + 'k yaln' + [char]0x0131 + 'zca zay' + [char]0x0131 + 'f ekran kart' + [char]0x0131 + ' ve az bellekte fark yarat' + [char]0x0131 + 'r.') }
    Search        = @{ Need = 'Low';     Why = ('Dizin olu' + [char]0x015F + 'turma kapan' + [char]0x0131 + 'nca arama yava' + [char]0x015F + 'lar; yaln' + [char]0x0131 + 'zca mekanik diskli zay' + [char]0x0131 + 'f bilgisayarda de' + [char]0x011F + 'er.') }
    BgApps        = @{ Need = 'Low';     Why = ('Arka plan uygulamalar' + [char]0x0131 + ' bildirim ve e' + [char]0x015F + 'itleme sa' + [char]0x011F + 'lar; yaln' + [char]0x0131 + 'zca az bellekte kapatmaya de' + [char]0x011F + 'er.') }
    SysMain       = @{ Need = 'Mid';     Why = ('SysMain g' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' donan' + [char]0x0131 + 'mda uygulamalar' + [char]0x0131 + ' h' + [char]0x0131 + 'zl' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar; kapatmak yaln' + [char]0x0131 + 'zca mekanik diskte i' + [char]0x015F + 'e yarar.') }
    GameDvr       = @{ Need = 'Mid';     Why = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' donan' + [char]0x0131 + 'mda arka plan kayd' + [char]0x0131 + 'n' + [char]0x0131 + 'n maliyeti hissedilmez; kay' + [char]0x0131 + 't ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i a' + [char]0x00E7 + '' + [char]0x0131 + 'k kal' + [char]0x0131 + 'r.') }
    ShutdownSpeed = @{ Need = 'Mid';     Why = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' donan' + [char]0x0131 + 'm zaten h' + [char]0x0131 + 'zl' + [char]0x0131 + ' kapan' + [char]0x0131 + 'r.') }
    DefenderCpu   = @{ Need = 'Mid';     Why = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' i' + [char]0x015F + 'lemcide tarama s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' gereksizdir; tarama daha ' + [char]0x00E7 + 'abuk biter.') }
    PowerPlan     = @{ Need = 'Mid';     Why = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' donan' + [char]0x0131 + 'mda dengeli g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' yeterlidir.') }
    Edge          = @{ Need = 'Mid';     Why = 'Bellek bolken sekmeleri uyutmaya gerek yok.' }
    HibernateOff  = @{ Need = 'LowDisk'; Why = ('Diskte yeterince yer var; haz' + [char]0x0131 + 'rda bekletme ve H' + [char]0x0131 + 'zl' + [char]0x0131 + ' Ba' + [char]0x015F + 'lat a' + [char]0x00E7 + '' + [char]0x0131 + 'k kalabilir.') }
    Dumps         = @{ Need = 'LowDisk'; Why = ('Diskte yeterince yer var; d' + [char]0x00F6 + 'k' + [char]0x00FC + 'm dosyalar' + [char]0x0131 + ' hata incelemesi i' + [char]0x00E7 + 'in kalabilir.') }
}
foreach ($c in $script:Catalog) {
    $c.Need = ''
    $c.NeedWhy = ''
    if ($script:NeedMap.ContainsKey([string]$c.Id)) {
        $c.Need = [string]$script:NeedMap[[string]$c.Id].Need
        $c.NeedWhy = [string]$script:NeedMap[[string]$c.Id].Why
    }
}

$script:TierLabels = @{ Low = ('D' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'k donan' + [char]0x0131 + 'm'); Mid = ('Orta donan' + [char]0x0131 + 'm'); High = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' donan' + [char]0x0131 + 'm') }

# Donanim sinifi. Donen tablo: Tier (Low|Mid|High), Score (0-100), Label, Summary, Reasons, LowDisk, Known
function Get-MachineTier($Pr) {
    $r = @{ Tier = 'Mid'; Score = 50; Label = [string]$script:TierLabels['Mid']; Summary = ''; Reasons = @(); LowDisk = $false; Known = $false }
    if ($null -eq $Pr) { return $r }
    $ram = 0.0; $thr = 0; $free = 0.0; $size = 0.0
    try { $ram = [double]$Pr.RamGB } catch { }
    try { $thr = [int]$Pr.Threads } catch { }
    try { $free = [double]$Pr.FreeGB; $size = [double]$Pr.SizeGB } catch { }
    $disk = [string]$Pr.DiskType
    $bus = [string]$Pr.BusType
    $nvme = ($bus -eq 'NVMe' -or $bus -eq '17')
    if ($size -gt 0 -and ($free -lt 25 -or ($free / $size) -lt 0.12)) { $r.LowDisk = $true }

    $parts = New-Object System.Collections.ArrayList
    if ($ram -gt 0) { [void]$parts.Add(([string][int][math]::Round($ram)) + ' GB bellek') }
    if ($disk -eq 'SSD') { if ($nvme) { [void]$parts.Add('NVMe SSD') } else { [void]$parts.Add('SSD') } }
    elseif ($disk -eq 'HDD') { [void]$parts.Add('mekanik disk (HDD)') }
    if ($thr -gt 0) { [void]$parts.Add(([string]$thr) + (' i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + '')) }
    $r.Summary = ($parts -join (' ' + [char]0x00B7 + ' '))

    # Bellek ya da islemci okunamadiysa tahmin yurutme: orta kabul et, hicbir ozelligi zorla kapatma
    if ($ram -le 0 -or $thr -le 0) {
        $r.Reasons = @(('Donan' + [char]0x0131 + 'm bilgisi tam okunamad' + [char]0x0131 + '; orta d' + [char]0x00FC + 'zey varsay' + [char]0x0131 + 'ld' + [char]0x0131 + '.'))
        return $r
    }
    $r.Known = $true

    $s = 0
    if ($ram -gt 16.5) { $s += 40 } elseif ($ram -gt 12.5) { $s += 34 } elseif ($ram -gt 8.5) { $s += 27 } elseif ($ram -gt 6.5) { $s += 18 } elseif ($ram -gt 4.5) { $s += 9 }
    if ($thr -gt 8) { $s += 30 } elseif ($thr -gt 6) { $s += 25 } elseif ($thr -gt 4) { $s += 20 } elseif ($thr -gt 2) { $s += 12 }
    if ($disk -eq 'SSD') { if ($nvme) { $s += 30 } else { $s += 24 } } elseif ($disk -ne 'HDD') { $s += 14 }
    $r.Score = $s

    $why = New-Object System.Collections.ArrayList
    $tier = 'High'
    if ($ram -le 4.5 -or $thr -le 2 -or ($disk -eq 'HDD' -and $ram -le 8.5) -or $s -lt 46) {
        $tier = 'Low'
        if ($ram -le 4.5) { [void]$why.Add('Bellek 4 GB ya da daha az') }
        elseif ($ram -le 8.5) { [void]$why.Add(('Bellek s' + [char]0x0131 + 'n' + [char]0x0131 + 'rl' + [char]0x0131 + ' (') + [string][int][math]::Round($ram) + ' GB)') }
        if ($disk -eq 'HDD') { [void]$why.Add('Sistem diski mekanik (HDD)') }
        if ($thr -le 2) { [void]$why.Add(('' + [char]0x0130 + '' + [char]0x015F + 'lemci 2 i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + 'kl' + [char]0x0131 + '')) } elseif ($thr -le 4) { [void]$why.Add(('' + [char]0x0130 + '' + [char]0x015F + 'lemci 4 i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + 'kl' + [char]0x0131 + '')) }
    } elseif ($ram -le 8.5 -or $disk -eq 'HDD' -or $thr -le 4 -or $s -lt 72) {
        $tier = 'Mid'
        if ($ram -le 8.5) { [void]$why.Add('Bellek 8 GB') }
        if ($disk -eq 'HDD') { [void]$why.Add('Sistem diski mekanik (HDD)') }
        if ($thr -le 4) { [void]$why.Add(('' + [char]0x0130 + '' + [char]0x015F + 'lemci 4 i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + 'kl' + [char]0x0131 + '')) }
        if ($why.Count -eq 0) { [void]$why.Add(('Donan' + [char]0x0131 + 'm g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k i' + [char]0x015F + 'ler i' + [char]0x00E7 + 'in yeterli, a' + [char]0x011F + '' + [char]0x0131 + 'r y' + [char]0x00FC + 'kte s' + [char]0x0131 + 'n' + [char]0x0131 + 'rl' + [char]0x0131 + '')) }
    } else {
        [void]$why.Add(('Bellek, i' + [char]0x015F + 'lemci ve disk yeterli; ' + [char]0x00F6 + 'zellik kapatmaya gerek yok'))
    }
    if ($r.LowDisk) { [void]$why.Add('Sistem diskinde yer az (' + [string][int][math]::Round($free) + (' GB bo' + [char]0x015F + ')')) }
    $r.Tier = $tier
    $r.Label = [string]$script:TierLabels[$tier]
    $r.Reasons = $why.ToArray()
    return $r
}

function Get-CurrentTier {
    try { if ($null -ne $sync.Tier) { return $sync.Tier } } catch { }
    return (Get-MachineTier $sync.Profile)
}

function Test-NeedOk([string]$Need, $Tier) {
    if ($Need -eq '') { return $true }
    if ($null -eq $Tier) { return $false }
    if ($Need -eq 'Low') { return ([string]$Tier.Tier -eq 'Low') }
    if ($Need -eq 'Mid') { return ([string]$Tier.Tier -eq 'Low' -or [string]$Tier.Tier -eq 'Mid') }
    if ($Need -eq 'LowDisk') { return ($Tier.LowDisk -eq $true) }
    return $false
}

# Bu bilgisayar icin onerilen ayar kimlikleri (yalnizca "Hizlandir" sayfasi; guvenlik ayarlari donanimdan bagimsizdir)
function Get-AdaptiveIds([string]$Page, $Pr, $Tier) {
    $ids = New-Object System.Collections.ArrayList
    foreach ($c in (Get-CatalogFor $Page '' $Pr)) {
        $lv = [int]$c.Level
        if ($lv -lt 1 -or $lv -ge 4) { continue }
        if (-not (Test-WhenOk ([string]$c.When) $Pr)) { continue }
        $need = [string]$c.Need
        if ($need -ne '') { if (Test-NeedOk $need $Tier) { [void]$ids.Add([string]$c.Id) } }
        elseif ($lv -le 2) { [void]$ids.Add([string]$c.Id) }
    }
    return , $ids.ToArray()
}

# Bir ayarin bekleyen degisiklik sayisi (sistemi degistirmez):
#   -1 = olculemez (yalnizca temizlik gibi islev adimlari),  0 = tamamen uygulanmis,  N = N deger hala farkli
# Durumu okunabilen (onizlemesi mevcut durumu karsilastiran) islevler; digerleri tek yonludur ve olculemez
$script:FuncStateful = @('PowerPlan', 'HibernateOff', 'GuestOff', 'NetBiosOff', 'LockoutPolicy', 'AuditLogon')

function Get-TweakPending($Item, [bool]$NoTask = $false) {
    if ($null -eq $Item) { return -1 }
    $ops = @($Item.Ops | Where-Object { (@('Reg', 'Svc', 'Task', 'Mp', 'EvtLog', 'Cap', 'Feature', 'DxGlobal', 'NetLatency') -contains [string]$_.T) -or ([string]$_.T -eq 'Func' -and $script:FuncStateful -contains [string]$_.Name) })
    if ($NoTask) { $ops = @($ops | Where-Object { [string]$_.T -ne 'Task' }) }
    if ($ops.Count -eq 0) { return -1 }
    $keep = @($script:Changes, $script:Skipped, $script:Errors, $script:Preview, $script:Silent)
    $n = 0
    try {
        $script:Changes = 0
        $script:Preview = $true
        $script:Silent = $true
        $script:OpUnreadable = $false
        foreach ($op in $ops) { try { Invoke-Op $op } catch { } }
        $n = [int]$script:Changes
        if ($script:OpUnreadable) { $n = -1 }
    } finally {
        $script:Changes = $keep[0]; $script:Skipped = $keep[1]; $script:Errors = $keep[2]
        $script:Preview = $keep[3]; $script:Silent = $keep[4]
    }
    return $n
}

# Kayitli "uygulanmis ayarlar" listesi (geri donen ayarlari yakalamak icin)
function Get-AppliedIds {
    $st = Get-Settings
    $out = New-Object System.Collections.ArrayList
    foreach ($id in @($st.AppliedIds)) { if ([string]$id -ne '' -and -not $out.Contains([string]$id)) { [void]$out.Add([string]$id) } }
    return , $out.ToArray()
}

function Save-AppliedIds($Ids) {
    $st = Get-Settings
    $st.AppliedIds = @($Ids)
    Save-Settings $st
}

# Plan uygulandiktan sonra: her katalog ayari gercekten yerine oturdu mu? Oturanlar kayda gecer.
function Update-AppliedAfterPlan($Steps) {
    $cur = New-Object System.Collections.ArrayList
    foreach ($id in (Get-AppliedIds)) { [void]$cur.Add([string]$id) }
    $bad = 0
    foreach ($s in @($Steps)) {
        $c = Get-CatalogItem ([string]$s.Id)
        if ($null -eq $c) { continue }
        $p = Get-TweakPending $c
        if ($p -eq 0 -and (Test-TweakBlocked $c)) {
            Write-WhLog ('Windows bu ayar' + [char]0x0131 + ' korumaya alm' + [char]0x0131 + [char]0x015F + ', uygulanamad' + [char]0x0131 + ': ' + [string]$c.Title) 'INFO'
        } elseif ($p -eq 0) {
            if (-not $cur.Contains([string]$c.Id)) { [void]$cur.Add([string]$c.Id) }
        } elseif ($p -gt 0) {
            $bad++
            Write-WhLog (('Do' + [char]0x011F + 'rulama: "') + [string]$c.Title + ('" tam uygulanamad' + [char]0x0131 + ' (') + [string]$p + (' de' + [char]0x011F + 'er h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' farkl' + [char]0x0131 + ').')) 'WARN'
        }
    }
    Save-AppliedIds $cur.ToArray()
    return $bad
}

# Geri almadan sonra: artik yururlukte olmayan ayarlari kayittan dus (bilerek geri alinanlar "geri donmus" sayilmasin)
function Update-AppliedAfterUndo {
    $keep = New-Object System.Collections.ArrayList
    foreach ($id in (Get-AppliedIds)) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -eq $c) { continue }
        if ((Get-TweakPending $c) -eq 0) { [void]$keep.Add([string]$id) }
    }
    Save-AppliedIds $keep.ToArray()
}

# Uygulanmis olup sonradan (cogunlukla bir Windows guncellemesiyle) eski haline donen ayarlar
function Get-DriftedIds {
    $out = New-Object System.Collections.ArrayList
    Start-StateBatch
    try {
    foreach ($id in (Get-AppliedIds)) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -eq $c) { continue }
        if (-not (Test-OsOk ([string]$c.OS) $sync.Profile)) { continue }
        if ((Get-TweakPending $c $true) -gt 0) { [void]$out.Add([string]$id) }
    }
    } finally { Stop-StateBatch }
    return , $out.ToArray()
}

# Arayuz icin: sayfadaki her ayarin durumu + donanim sinifi + geri donenler
function Job_TweakStates($P) {
    $page = [string]$P.Page
    if ($page -eq '') { $page = 'opt' }
    $states = @{}
    $items = Get-CatalogFor $page '' $sync.Profile
    Set-JobProgress 0 $items.Count ('Ayarlar' + [char]0x0131 + 'n durumu okunuyor')
    Start-StateBatch
    try {
    foreach ($c in $items) {
        if (Test-JobCancel) { break }
        $pv = Get-TweakPending $c
        if ($pv -eq 0 -and (Test-TweakBlocked $c)) { $pv = -3 }
        $states[[string]$c.Id] = $pv
        Step-JobProgress
    }
    $drift = Get-DriftedIds
    } finally { Stop-StateBatch }
    return @{ Page = $page; States = $states; Drift = $drift; Tier = (Get-CurrentTier) }
}

# Hizmet satiri bu donanim icin "kapatilmasi onerilir" mi?
#   Guclu : yalnizca telemetri / eski / uzak erisim grubundaki risksiz hizmetler
#   Orta  : onerisi "kapat" olan risksiz (risk 1) hizmetler
#   Dusuk : onerisi "kapat" olan risk 1-2 hizmetler      (MaxRisk ile ust sinir daraltilabilir)
function Test-SvcAdaptive($Row, $Tier, [int]$MaxRisk = 2) {
    if ($null -eq $Row -or [string]$Row.Rec -ne 'Off' -or $Row.Done -eq $true -or $Row.Locked -eq $true) { return $false }
    $risk = [int]$Row.Risk
    $t = 'Mid'
    if ($null -ne $Tier) { $t = [string]$Tier.Tier }
    if ($t -eq 'High') {
        return ($risk -le 1 -and @('Telemetri', ('Eski ve kullan' + [char]0x0131 + 'lmayan'), ('Uzak eri' + [char]0x015F + 'im')) -contains [string]$Row.Grp)
    }
    if ($t -eq 'Low') { return ($risk -le [math]::Min(2, $MaxRisk)) }
    return ($risk -le 1)
}

# Komut satiri ve arayuz icin: "bu bilgisayara gore" plani.  P: Preview, RestorePoint, Services (bool)
function Job_Adaptive($P) {
    $pr = $sync.Profile
    $tier = Get-CurrentTier
    Write-WhLog (('Donan' + [char]0x0131 + 'm s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + ': ') + [string]$tier.Label + ' (' + [string]$tier.Summary + ')') 'INFO'
    foreach ($w in @($tier.Reasons)) { Write-WhLog ('  - ' + [string]$w) 'INFO' }
    $pick = New-Object System.Collections.ArrayList
    foreach ($id in (Get-AdaptiveIds 'opt' $pr $tier)) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -eq $c) { continue }
        $pend = Get-TweakPending $c
        if ($pend -eq 0) { continue }
        if ($pend -lt 0 -and [string]$c.Cat -eq 'Temizlik') { continue }
        [void]$pick.Add([string]$id)
    }
    $steps = New-Object System.Collections.ArrayList
    foreach ($s in (New-StepsFromIds ([string[]]$pick.ToArray()))) { [void]$steps.Add($s) }
    $svcN = 0
    if ($P.Services -eq $true) {
        $names = New-Object System.Collections.ArrayList
        try {
            foreach ($row in (Get-ServiceRows)) { if (Test-SvcAdaptive $row $tier 1) { [void]$names.Add([string]$row.Name) } }
        } catch { Write-WhLog (('Hizmetler okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
        $svcN = $names.Count
        if ($svcN -gt 0) { foreach ($s in (New-ServiceSteps $names.ToArray() 'Off')) { [void]$steps.Add($s) } }
    }
    Write-WhLog (('Bu bilgisayar i' + [char]0x00E7 + 'in ') + [string]$pick.Count + ' ayar ve ' + [string]$svcN + (' hizmet ' + [char]0x00F6 + 'nerisi var.')) 'INFO'
    if ($steps.Count -eq 0) {
        Write-WhLog ('Uygulanacak bir ' + [char]0x015F + 'ey yok; bu bilgisayar ' + [char]0x00F6 + 'nerilen durumda.') 'OK'
        return @{ Ok = $true; Changes = 0; Skipped = 0; Errors = 0; Freed = 0.0; Preview = [bool]$P.Preview; Reboot = $false; Summary = ('Uygulanacak bir ' + [char]0x015F + 'ey yok.'); Tier = $tier }
    }
    $res = Job_Plan @{ Steps = $steps.ToArray(); Preview = [bool]$P.Preview; RestorePoint = [bool]$P.RestorePoint }
    $res.Tier = $tier
    $res.Ok = ([int]$res.Errors -eq 0)
    return $res
}

# ---------------- Ek isler ----------------
# ==================================================================
#  ISLER (F): gizlilik izi (kamera / mikrofon / konum), buyuk ve kopya dosyalar, tasinma kiti,
#  program bazinda internet engeli, agdaki cihazlar (pasif), dosya ozeti / imza, guvenli silme
#  Hepsi "once goster" kuralina uyar; kalici olanlar ayrica onaylatilir.
# ==================================================================

# ---------------- kamera / mikrofon / konum: kim, en son ne zaman kullandi? (yalnizca okur) ----------------
function ConvertFrom-FileTimeValue($V) {
    try {
        $l = [long]$V
        if ($l -le 0) { return $null }
        return [datetime]::FromFileTime($l)
    } catch { return $null }
}

function Get-PrivacyAppName([string]$Key) {
    # Paketli uygulama: Microsoft.WindowsCamera_8wekyb3d8bbwe -> Microsoft.WindowsCamera ; masaustu: C:#Program Files#x#y.exe -> y.exe
    if ($Key.Contains('#')) {
        $p = $Key.Replace('#', '\')
        $leaf = $p
        $i = $p.LastIndexOf('\')
        if ($i -ge 0 -and $i -lt ($p.Length - 1)) { $leaf = $p.Substring($i + 1) }
        return @{ Name = $leaf; Path = $p }
    }
    $n = $Key
    $j = $n.LastIndexOf('_')
    if ($j -gt 0) { $n = $n.Substring(0, $j) }
    return @{ Name = $n; Path = '' }
}

function Get-PrivacyUsage {
    $caps = [ordered]@{ webcam = 'Kamera'; microphone = 'Mikrofon'; location = 'Konum' }
    $best = @{}
    foreach ($hive in @('HKCU', 'HKLM')) {
        foreach ($cap in @($caps.Keys)) {
            $base = $hive + '\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\' + $cap
            $keys = New-Object System.Collections.ArrayList
            foreach ($a in (Get-RegSubKeyNames $base)) {
                if ([string]$a -eq 'NonPackaged') {
                    foreach ($np in (Get-RegSubKeyNames ($base + '\NonPackaged'))) { [void]$keys.Add(@{ K = ($base + '\NonPackaged\' + [string]$np); A = [string]$np }) }
                } else { [void]$keys.Add(@{ K = ($base + '\' + [string]$a); A = [string]$a }) }
            }
            foreach ($k in $keys) {
                $st = Get-RegInfo $k.K 'LastUsedTimeStart'
                if (-not $st.Exists) { continue }
                $start = ConvertFrom-FileTimeValue $st.Value
                if ($null -eq $start) { continue }
                $sp = Get-RegInfo $k.K 'LastUsedTimeStop'
                $stop = $null
                if ($sp.Exists) { $stop = ConvertFrom-FileTimeValue $sp.Value }
                $inUse = ($null -eq $stop -or $stop -lt $start)
                $nm = Get-PrivacyAppName $k.A
                $id = [string]$cap + '|' + [string]$k.A
                if ($best.ContainsKey($id) -and $best[$id].Start -ge $start) { continue }
                $best[$id] = @{ Cap = [string]$cap; CapName = [string]$caps[$cap]; App = [string]$nm.Name; Path = [string]$nm.Path; Start = $start; Stop = $stop; InUse = $inUse }
            }
        }
    }
    $rows = @($best.Values | Sort-Object { $_.Start } -Descending)
    $out = New-Object System.Collections.ArrayList
    foreach ($r in $rows) {
        $when = $r.Start.ToString('dd.MM.yyyy HH:mm')
        [void]$out.Add(@{ Cap = $r.Cap; CapName = $r.CapName; App = $r.App; Path = $r.Path; When = $when; InUse = [bool]$r.InUse; Ticks = [double]$r.Start.Ticks })
    }
    return , $out.ToArray()
}

function Job_PrivacyUse($P) {
    $rows = Get-PrivacyUsage
    Write-WhLog (('Kamera / mikrofon / konum kullan' + [char]0x0131 + 'm kayd' + [char]0x0131 + ': ') + [string]$rows.Count + ' uygulama') 'INFO'
    return @{ Rows = $rows }
}

# ---------------- saglik: pil yipranmasi, mavi ekran / beklenmedik kapanma gecmisi ----------------
function Chk_Battery {
    $pr = $sync.Profile
    if ($null -eq $pr -or $pr.IsLaptop -ne $true) { return }
    $full = 0.0; $design = 0.0
    try {
        $f = @(Get-CimInstance -Namespace 'root/wmi' -ClassName BatteryFullChargedCapacity -ErrorAction Stop)
        $d = @(Get-CimInstance -Namespace 'root/wmi' -ClassName BatteryStaticData -ErrorAction Stop)
        if ($f.Count -gt 0) { $full = [double]$f[0].FullChargedCapacity }
        if ($d.Count -gt 0) { $design = [double]$d[0].DesignedCapacity }
    } catch { return }
    if ($full -le 0 -or $design -le 0) { return }
    $pct = [int][math]::Round(100.0 * $full / $design)
    if ($pct -gt 100) { $pct = 100 }
    $act = @{ Kind = 'Run'; Key = 'BatteryReport'; Label = 'Pil raporu' }
    if ($pct -lt 50) { Add-Finding 'batt' 'maint' 'warn' (('Pil sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' %') + [string]$pct + (' (y' + [char]0x0131 + 'pranm' + [char]0x0131 + '' + [char]0x015F + ')')) ('Pil ilk kapasitesinin yar' + [char]0x0131 + 's' + [char]0x0131 + 'ndan az' + [char]0x0131 + 'n' + [char]0x0131 + ' tutuyor; kullan' + [char]0x0131 + 'm s' + [char]0x00FC + 'resi k' + [char]0x0131 + 'sal' + [char]0x0131 + 'r. De' + [char]0x011F + 'i' + [char]0x015F + 'im d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'nebilirsiniz.') $act 3 }
    elseif ($pct -lt 75) { Add-Finding 'batt' 'maint' 'info' (('Pil sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' %') + [string]$pct) ('Pil ilk kapasitesinin bir k' + [char]0x0131 + 'sm' + [char]0x0131 + 'n' + [char]0x0131 + ' yitirmi' + [char]0x015F + '; bu ya' + [char]0x015F + 'taki bir pil i' + [char]0x00E7 + 'in ola' + [char]0x011F + 'an.') $act }
    else { Add-Finding 'batt' 'maint' 'ok' (('Pil sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' %') + [string]$pct) '' }
}

# ---------------- dosya dolasma (erisilemeyen klasorler atlanir, baglanti noktalarina girilmez) ----------------
$script:WalkSkipDirs = @('$RECYCLE.BIN', 'System Volume Information', 'WinSxS', 'Config.Msi')

# Root altindaki dosyalari gezer; boyutu MinBytes ve ustu olanlarin FileInfo nesnelerini dondurur (en cok Max adet)
function Get-FilesBySize([string]$Root, [double]$MinBytes, [int]$Max = 200000) {
    $out = New-Object System.Collections.ArrayList
    if (-not (Test-Path -LiteralPath $Root -PathType Container -ErrorAction SilentlyContinue)) { return , $out.ToArray() }
    $stack = New-Object System.Collections.Stack
    $stack.Push([string]$Root)
    $dirs = 0
    while ($stack.Count -gt 0) {
        if (Test-JobCancel) { break }
        $dir = [string]$stack.Pop()
        $dirs++
        if (($dirs % 200) -eq 0) { Set-JobProgress 0 0 (('Taran' + [char]0x0131 + 'yor: ') + $dir) }
        $di = $null
        try { $di = New-Object System.IO.DirectoryInfo -ArgumentList $dir } catch { continue }
        $files = $null
        try { $files = $di.GetFiles() } catch { $files = $null }
        if ($null -ne $files) {
            foreach ($f in $files) {
                if ([double]$f.Length -ge $MinBytes) {
                    [void]$out.Add($f)
                    if ($out.Count -ge $Max) { return , $out.ToArray() }
                }
            }
        }
        $subs = $null
        try { $subs = $di.GetDirectories() } catch { $subs = $null }
        if ($null -ne $subs) {
            foreach ($s in $subs) {
                if (($s.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { continue }
                if ($script:WalkSkipDirs -contains [string]$s.Name) { continue }
                $stack.Push([string]$s.FullName)
            }
        }
    }
    return , $out.ToArray()
}

# En buyuk dosyalar (yalnizca rapor).  P: Path, Top (varsayilan 100), MinMB (varsayilan 50)
function Job_LargeFiles($P) {
    $root = [string]$P.Path
    $top = 100; if ([int]$P.Top -gt 0) { $top = [int]$P.Top }
    $minMb = 50.0; if ([double]$P.MinMB -gt 0) { $minMb = [double]$P.MinMB }
    Write-WhLog (('En b' + [char]0x00FC + 'y' + [char]0x00FC + 'k dosyalar aran' + [char]0x0131 + 'yor: ') + $root + ' (en az ' + [string]$minMb + ' MB)') 'INFO'
    $files = Get-FilesBySize $root ($minMb * 1MB)
    $sorted = @($files | Sort-Object { [double]$_.Length } -Descending | Select-Object -First $top)
    $rows = New-Object System.Collections.ArrayList
    $total = 0.0
    foreach ($f in $sorted) {
        $total += [double]$f.Length
        [void]$rows.Add(@{ Name = [string]$f.Name; Path = [string]$f.FullName; Dir = [string]$f.DirectoryName; Size = [double]$f.Length; Date = $f.LastWriteTime.ToString('yyyy-MM-dd') })
    }
    Write-WhLog ([string]$rows.Count + (' b' + [char]0x00FC + 'y' + [char]0x00FC + 'k dosya bulundu, toplam ') + (Format-Size $total)) 'INFO'
    return @{ Rows = $rows.ToArray(); Total = $total; Root = $root }
}

function Get-FileHashHex([string]$Path, [double]$MaxBytes = 0) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $fs = $null
    try {
        $fs = New-Object System.IO.FileStream -ArgumentList $Path, ([System.IO.FileMode]::Open), ([System.IO.FileAccess]::Read), ([System.IO.FileShare]::ReadWrite)
        if ($MaxBytes -gt 0) {
            $buf = New-Object byte[] ([int]$MaxBytes)
            $n = $fs.Read($buf, 0, $buf.Length)
            $h = $sha.ComputeHash($buf, 0, $n)
        } else { $h = $sha.ComputeHash($fs) }
        return ([System.BitConverter]::ToString($h)).Replace('-', '').ToLowerInvariant()
    } finally {
        if ($null -ne $fs) { $fs.Dispose() }
        $sha.Dispose()
    }
}

# Kopya dosyalar (yalnizca rapor; hicbir sey silinmez).  P: Path, MinMB (varsayilan 1)
function Job_Duplicates($P) {
    $root = [string]$P.Path
    $minMb = 1.0; if ([double]$P.MinMB -gt 0) { $minMb = [double]$P.MinMB }
    Write-WhLog (('Kopya dosyalar aran' + [char]0x0131 + 'yor: ') + $root + ' (en az ' + [string]$minMb + ' MB)') 'INFO'
    $files = Get-FilesBySize $root ($minMb * 1MB)
    $bySize = @{}
    foreach ($f in $files) {
        $k = [string][long]$f.Length
        if (-not $bySize.ContainsKey($k)) { $bySize[$k] = New-Object System.Collections.ArrayList }
        [void]$bySize[$k].Add($f)
    }
    $cands = @($bySize.Values | Where-Object { $_.Count -gt 1 })
    $totalC = 0
    foreach ($c in $cands) { $totalC += $c.Count }
    Set-JobProgress 0 $totalC ('Ayn' + [char]0x0131 + ' boyuttaki dosyalar kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor')
    $groups = New-Object System.Collections.ArrayList
    foreach ($c in $cands) {
        if (Test-JobCancel) { break }
        # 1) ilk 64 KB ozeti  2) eslesenler icin tam ozet
        $byHead = @{}
        foreach ($f in $c) {
            Step-JobProgress
            $h = ''
            try { $h = Get-FileHashHex ([string]$f.FullName) 65536 } catch { continue }
            if (-not $byHead.ContainsKey($h)) { $byHead[$h] = New-Object System.Collections.ArrayList }
            [void]$byHead[$h].Add($f)
        }
        foreach ($hk in @($byHead.Keys)) {
            $set = $byHead[$hk]
            if ($set.Count -lt 2) { continue }
            $byFull = @{}
            foreach ($f in $set) {
                $h = ''
                if ([double]$f.Length -le 65536) { $h = $hk }
                else { try { $h = Get-FileHashHex ([string]$f.FullName) 0 } catch { continue } }
                if (-not $byFull.ContainsKey($h)) { $byFull[$h] = New-Object System.Collections.ArrayList }
                [void]$byFull[$h].Add($f)
            }
            foreach ($fk in @($byFull.Keys)) {
                $g = $byFull[$fk]
                if ($g.Count -lt 2) { continue }
                $size = [double]$g[0].Length
                $paths = @($g | ForEach-Object { [string]$_.FullName } | Sort-Object)
                [void]$groups.Add(@{ Size = $size; Count = $g.Count; Waste = ($size * ($g.Count - 1)); Files = $paths; Name = [string]$g[0].Name })
            }
        }
    }
    $sorted = @($groups | Sort-Object { [double]$_.Waste } -Descending | Select-Object -First 100)
    $waste = 0.0
    foreach ($g in $sorted) { $waste += [double]$g.Waste }
    Write-WhLog ([string]$sorted.Count + (' kopya grubu bulundu; kazan' + [char]0x0131 + 'labilir alan ') + (Format-Size $waste)) 'INFO'
    return @{ Rows = $sorted; Waste = $waste; Root = $root }
}

# ---------------- dosya ozeti ve dijital imza ----------------
function Job_FileInfo($P) {
    $path = [string]$P.Path
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { Write-WhLog (('Dosya bulunamad' + [char]0x0131 + ': ') + $path) 'ERR'; return @{ Ok = $false } }
    $r = @{ Ok = $true; Path = $path; Name = (Split-Path -Leaf $path); Size = 0.0; Sha256 = ''; SigStatus = ''; Signer = ''; Product = ''; Company = ''; Version = '' }
    try { $fi = New-Object System.IO.FileInfo -ArgumentList $path; $r.Size = [double]$fi.Length } catch { }
    try { $r.Sha256 = Get-FileHashHex $path 0 } catch { Write-WhLog (('' + [char]0x00D6 + 'zet hesaplanamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'; $r.Ok = $false }
    try {
        $sig = Get-AuthenticodeSignature -LiteralPath $path -ErrorAction Stop
        $r.SigStatus = [string]$sig.Status
        if ($null -ne $sig.SignerCertificate) { $r.Signer = [string]$sig.SignerCertificate.Subject }
    } catch { $r.SigStatus = ('Okunamad' + [char]0x0131 + '') }
    try {
        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($path)
        $r.Product = [string]$vi.ProductName; $r.Company = [string]$vi.CompanyName; $r.Version = [string]$vi.FileVersion
    } catch { }
    Write-WhLog ('SHA-256 ' + $r.Name + ': ' + $r.Sha256) 'INFO'
    return $r
}

# ---------------- guvenli silme (geri getirilemez) ----------------
# Mekanik diskte dosyanin uzerine bir kez rastgele veri yazmak yeterlidir. SSD'de denetleyici veriyi baska
# hucrelere tasidigi icin dosya bazinda uzerine yazma guvence vermez; orada dogru yol disk sifrelemedir.
# Test-SecureDeleteAllowed: 128_wipe_core.ps1 icindedir.
# Remove-FileSecure ve Job_SecureDelete (uzerine yazarak silme) Eklenti\GuvenliSilme.ps1 dosyasindadir; ilk kullanimda yuklenir.

# ---------------- program bazinda internet engeli (Windows Guvenlik Duvari kurali; geri alinir) ----------------
$script:FwGroup = 'Multimizer'

function Get-FwRuleId([string]$Program) {
    $sha = [System.Security.Cryptography.SHA1]::Create()
    try {
        $h = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Program.ToLowerInvariant()))
        return ('Multimizer-' + ([System.BitConverter]::ToString($h)).Replace('-', '').Substring(0, 16).ToLowerInvariant())
    } finally { $sha.Dispose() }
}

function Test-FwBlockAllowed([string]$Program) {
    if ([string]::IsNullOrEmpty($Program)) { return 'Program yolu bilinmiyor.' }
    $win = ([string]$env:WINDIR).TrimEnd('\') + '\'
    if ($Program.StartsWith($win, [StringComparison]::OrdinalIgnoreCase)) { return ('Windows bile' + [char]0x015F + 'enlerinin interneti kesilemez (g' + [char]0x00FC + 'ncelleme ve g' + [char]0x00FC + 'venlik bozulur).') }
    if ($Program -match '(?i)\\(Windows Defender|Microsoft\\Windows Defender|WindowsApps\\Microsoft\.SecHealthUI)') { return ('G' + [char]0x00FC + 'venlik yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + 'n' + [char]0x0131 + 'n interneti kesilemez.') }
    return ''
}

# Op: @{ T = 'FwApp'; Program = 'C:\...\x.exe'; On = $true|$false }
function Invoke-FwAppOp($Op) {
    $prog = [string]$Op.Program
    $on = ($Op.On -eq $true)
    $id = Get-FwRuleId $prog
    $leaf = Split-Path -Leaf $prog
    $existing = $null
    try { $existing = Get-NetFirewallRule -Name $id -ErrorAction Stop } catch { $existing = $null }
    if ($on) {
        $why = Test-FwBlockAllowed $prog
        if ($why -ne '') { Add-Skip ($leaf + ': ' + $why); return }
        if ($null -ne $existing) { Add-Skip (('' + [char]0x0130 + 'nternet engeli zaten var: ') + $leaf); return }
        if ($script:Preview) { Add-Plan (('' + [char]0x0130 + 'nternet eri' + [char]0x015F + 'imi engellenecek: ') + $prog); return }
        Add-Journal @{ T = 'FwApp'; Program = $prog; Id = $id }
        New-NetFirewallRule -Name $id -DisplayName ('Multimizer engel: ' + $leaf) -Description $prog -Group $script:FwGroup -Direction Outbound -Program $prog -Action Block -Profile Any -ErrorAction Stop | Out-Null
        Add-Done (('' + [char]0x0130 + 'nternet eri' + [char]0x015F + 'imi engellendi: ') + $leaf)
    } else {
        if ($null -eq $existing) { Add-Skip (('Engel kural' + [char]0x0131 + ' yok: ') + $leaf); return }
        if ($script:Preview) { Add-Plan (('' + [char]0x0130 + 'nternet engeli kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak: ') + $prog); return }
        Add-Journal @{ T = 'FwAppDel'; Program = $prog; Id = $id }
        Remove-NetFirewallRule -Name $id -ErrorAction Stop
        Add-Done (('' + [char]0x0130 + 'nternet engeli kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $leaf)
    }
}

function Undo-FwAppItem($It) {
    $prog = [string]$It.Program
    $id = [string]$It.Id
    $leaf = Split-Path -Leaf $prog
    if ([string]$It.T -eq 'FwApp') {
        try { Remove-NetFirewallRule -Name $id -ErrorAction Stop } catch { }
        Add-Done (('' + [char]0x0130 + 'nternet engeli kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $leaf)
    } else {
        $ex = $null
        try { $ex = Get-NetFirewallRule -Name $id -ErrorAction Stop } catch { $ex = $null }
        if ($null -eq $ex) {
            New-NetFirewallRule -Name $id -DisplayName ('Multimizer engel: ' + $leaf) -Description $prog -Group $script:FwGroup -Direction Outbound -Program $prog -Action Block -Profile Any -ErrorAction Stop | Out-Null
        }
        Add-Done (('' + [char]0x0130 + 'nternet engeli geri kondu: ') + $leaf)
    }
}

function Get-FwBlockRows {
    $rows = New-Object System.Collections.ArrayList
    try {
        foreach ($r in @(Get-NetFirewallRule -Group $script:FwGroup -ErrorAction Stop)) {
            $prog = [string]$r.Description
            [void]$rows.Add(@{ Id = [string]$r.Name; Program = $prog; Name = (Split-Path -Leaf $prog); Enabled = ([string]$r.Enabled -eq 'True') })
        }
    } catch { }
    return , $rows.ToArray()
}

function Job_FwBlocks($P) { return @{ Rows = (Get-FwBlockRows) } }

# ---------------- agimdaki cihazlar (pasif: yalnizca Windows'un komsu tablosu okunur, tarama yapilmaz) ----------------
function Resolve-HostNameQuick([string]$Ip, [int]$Ms = 250) {
    try {
        $ar = [System.Net.Dns]::BeginGetHostEntry($Ip, $null, $null)
        if ($ar.AsyncWaitHandle.WaitOne($Ms)) {
            $he = [System.Net.Dns]::EndGetHostEntry($ar)
            if ($null -ne $he -and [string]$he.HostName -ne $Ip) { return [string]$he.HostName }
        }
    } catch { }
    return ''
}

function Job_Neighbors($P) {
    $rows = New-Object System.Collections.ArrayList
    $gws = @()
    try { $gws = @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop | ForEach-Object { [string]$_.NextHop }) } catch { }
    $known = @((Get-Settings).KnownDevices | ForEach-Object { ([string]$_).ToUpperInvariant() })
    $seen = @{}
    $nb = @()
    try { $nb = @(Get-NetNeighbor -AddressFamily IPv4 -ErrorAction Stop) } catch { Write-WhLog (('Kom' + [char]0x015F + 'u tablosu okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    foreach ($n in $nb) {
        $ip = [string]$n.IPAddress
        $mac = ([string]$n.LinkLayerAddress).ToUpperInvariant()
        $st = [string]$n.State
        if ($mac -eq '' -or $mac -match '^(00-00-00-00-00-00|FF-FF-FF-FF-FF-FF)$') { continue }
        if ($mac -match '^01-00-5E' -or $ip -match '^(22[4-9]|23\d)\.' -or $ip -match '\.255$' -or $ip -match '^169\.254\.') { continue }
        if ($st -eq 'Unreachable' -or $st -eq 'Incomplete') { continue }
        if ($seen.ContainsKey($mac)) { continue }
        $seen[$mac] = $true
        $isGw = ($gws -contains $ip)
        $name = ''
        if ($rows.Count -lt 40) { $name = Resolve-HostNameQuick $ip }
        [void]$rows.Add(@{ Ip = $ip; Mac = $mac; State = $st; Gateway = $isGw; Name = $name; Known = ($known -contains $mac); Iface = [string]$n.InterfaceAlias })
    }
    $sorted = @($rows | Sort-Object { [version]([string]$_.Ip) })
    Write-WhLog (('A' + [char]0x011F + 'da g' + [char]0x00F6 + 'r' + [char]0x00FC + 'len cihaz: ') + [string]$sorted.Count) 'INFO'
    return @{ Rows = $sorted }
}

# ---------------- tasinma / format oncesi kit ----------------
# P: Dest (klasor), Drivers (bool), Wifi (bool)
function Job_MigrationKit($P) {
    $dest = [string]$P.Dest
    if ($dest -eq '' -or -not (Test-Path -LiteralPath $dest -PathType Container)) { Write-WhLog ('Hedef klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'ilmedi ya da yok.') 'ERR'; return @{ Ok = $false } }
    $kit = Join-Path $dest ('Multimizer-Kit-' + $env:COMPUTERNAME + '-' + (Get-Date -Format 'yyyyMMdd-HHmm'))
    try { New-Item -ItemType Directory -Path $kit -Force | Out-Null } catch { Write-WhLog (('Klas' + [char]0x00F6 + 'r olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false } }
    $items = New-Object System.Collections.ArrayList
    $steps = 3
    if ($P.Drivers -eq $true) { $steps++ }
    if ($P.Wifi -eq $true) { $steps++ }
    Set-JobProgress 0 $steps ('Ta' + [char]0x015F + '' + [char]0x0131 + 'ma paketi haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor')
    $utf8 = New-Object System.Text.UTF8Encoding($true)

    # 1) kurulu programlar: okunur liste + winget ile geri kurulabilir liste
    try {
        $sb = New-Object System.Text.StringBuilder
        foreach ($pg in (Get-InstalledPrograms)) { [void]$sb.AppendLine(([string]$pg.Name) + "`t" + ([string]$pg.Version) + "`t" + ([string]$pg.Publisher)) }
        [System.IO.File]::WriteAllText((Join-Path $kit 'programlar.txt'), $sb.ToString(), $utf8)
        [void]$items.Add(('programlar.txt (kurulu programlar' + [char]0x0131 + 'n listesi)'))
    } catch { Write-WhLog (('Program listesi yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    try {
        if ((Get-WingetPath) -ne '') {
            $wj = Join-Path $kit 'programlar-winget.json'
            [void](Invoke-WingetRaw @('export', '-o', $wj, '--accept-source-agreements', '--disable-interactivity'))
            if (Test-Path -LiteralPath $wj) { [void]$items.Add('programlar-winget.json (winget import ile toplu geri kurulum)') }
        } else { Write-WhLog ('winget yok; programlar-winget.json atland' + [char]0x0131 + '.') 'SKIP' }
    } catch { Write-WhLog (('winget d' + [char]0x0131 + '' + [char]0x015F + 'a aktarma atland' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    Step-JobProgress

    # 2) uygulanmis ayarlar profili (yeni kurulumda -Gorev Profil ile geri uygulanir)
    try {
        $prof = New-ProfileObject ('Paket ' + $env:COMPUTERNAME) (Get-AppliedIds) @() @()
        Save-JsonFile $prof (Join-Path $kit 'profil.json') 6
        [void]$items.Add(('profil.json (bu bilgisayarda uygulanm' + [char]0x0131 + '' + [char]0x015F + ' Multimizer ayarlar' + [char]0x0131 + ')'))
    } catch { Write-WhLog (('Profil yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    Step-JobProgress

    # 3) suruculer
    if ($P.Drivers -eq $true) {
        try {
            $dd = Join-Path $kit 'Suruculer'
            New-Item -ItemType Directory -Path $dd -Force | Out-Null
            Write-WhLog ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler d' + [char]0x0131 + '' + [char]0x015F + 'a aktar' + [char]0x0131 + 'l' + [char]0x0131 + 'yor (birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rebilir)...') 'INFO'
            $code = Invoke-Native 'pnputil.exe' @('/export-driver', '*', $dd)
            if ($code -eq 0) { [void]$items.Add(('Suruculer\ (' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'nc' + [char]0x00FC + ' taraf s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler; pnputil /add-driver ile geri y' + [char]0x00FC + 'klenir)')) }
            else { Write-WhLog (('pnputil ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu: ') + [string]$code) 'WARN' }
        } catch { Write-WhLog (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler d' + [char]0x0131 + '' + [char]0x015F + 'a aktar' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
        Step-JobProgress
    }

    # 4) Wi-Fi profilleri (parolalar duz metin olarak yazilir; kullanici bunu acikca secmis olmali)
    if ($P.Wifi -eq $true) {
        try {
            $wd = Join-Path $kit 'WiFi'
            New-Item -ItemType Directory -Path $wd -Force | Out-Null
            $xr = Import-MmExt 'WifiAktar'
            if ($xr.Ok -eq $true) {
                $code = Export-WifiProfilesWithKeys $wd
                if (@(Get-ChildItem -LiteralPath $wd -Filter '*.xml' -ErrorAction SilentlyContinue).Count -gt 0) { [void]$items.Add(('WiFi\ (kablosuz a' + [char]0x011F + ' profilleri, PAROLALAR A' + [char]0x00C7 + 'IK YAZILIDIR)')) }
            } else {
                Write-WhLog (('Wi-Fi profilleri d' + [char]0x0131 + '' + [char]0x015F + 'a aktar' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + [string]$xr.Error) 'WARN'
            }
        } catch { Write-WhLog (('Wi-Fi profilleri d' + [char]0x0131 + '' + [char]0x015F + 'a aktar' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
        Step-JobProgress
    }

    # 5) nasil geri yuklenir
    try {
        $t = New-Object System.Text.StringBuilder
        [void]$t.AppendLine(('MULTIMIZER TA' + [char]0x015E + 'IMA / FORMAT PAKET' + [char]0x0130 + ''))
        [void]$t.AppendLine('Bilgisayar: ' + $env:COMPUTERNAME + '    Tarih: ' + (Get-Date -Format 'dd.MM.yyyy HH:mm'))
        [void]$t.AppendLine('')
        [void]$t.AppendLine(('' + [char]0x0130 + '' + [char]0x00C7 + '' + [char]0x0130 + 'NDEK' + [char]0x0130 + 'LER'))
        foreach ($i in $items) { [void]$t.AppendLine('  - ' + [string]$i) }
        [void]$t.AppendLine('')
        [void]$t.AppendLine(('YEN' + [char]0x0130 + ' KURULUMDA GER' + [char]0x0130 + ' Y' + [char]0x00DC + 'KLEME (y' + [char]0x00F6 + 'netici olarak a' + [char]0x00E7 + '' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' PowerShell ya da Komut ' + [char]0x0130 + 'stemi)'))
        [void]$t.AppendLine('  Programlar :  winget import -i programlar-winget.json --accept-package-agreements --accept-source-agreements')
        [void]$t.AppendLine(('  S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler  :  pnputil /add-driver "Suruculer\*.inf" /subdirs /install'))
        [void]$t.AppendLine(('  Wi-Fi      :  WiFi klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'ndeki her dosya i' + [char]0x00E7 + 'in   netsh wlan add profile filename="dosya.xml"'))
        [void]$t.AppendLine(('  Ayarlar    :  Multimizer > ' + [char]0x015E + 'irket Y' + [char]0x00F6 + 'netimi > Profil uygula  (ya da  Multimizer.ps1 -Cli -Gorev Profil -Profil profil.json)'))
        [void]$t.AppendLine('')
        [void]$t.AppendLine(('Not: Bu paket ki' + [char]0x015F + 'isel dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' i' + [char]0x00E7 + 'ermez. Belgeler, Resimler gibi klas' + [char]0x00F6 + 'rler i' + [char]0x00E7 + 'in Yedek sayfas' + [char]0x0131 + 'ndaki dosya yede' + [char]0x011F + 'ini kullan' + [char]0x0131 + 'n.'))
        [void]$t.AppendLine(('WiFi klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' varsa i' + [char]0x00E7 + 'indeki parolalar d' + [char]0x00FC + 'z metindir; paketi g' + [char]0x00FC + 'vendi' + [char]0x011F + 'iniz bir yerde saklay' + [char]0x0131 + 'n, i' + [char]0x015F + 'iniz bitince silin.'))
        [System.IO.File]::WriteAllText((Join-Path $kit 'OKUBENI.txt'), $t.ToString(), $utf8)
    } catch { }
    Step-JobProgress
    Write-WhLog (('Ta' + [char]0x015F + '' + [char]0x0131 + 'ma paketi haz' + [char]0x0131 + 'r: ') + $kit) 'OK'
    return @{ Ok = $true; Path = $kit; Items = $items.ToArray() }
}

# ---------------- eklentiler: yalnizca veri (JSON). Kod calistirmaz; ayni onizleme ve guvenlik kapisindan gecer ----------------
$script:PluginNotes = New-Object System.Collections.ArrayList
$script:PluginCount = 0

function Get-PluginDirs {
    $dirs = New-Object System.Collections.ArrayList
    try { if (-not [string]::IsNullOrEmpty([string]$sync.ScriptPath)) { [void]$dirs.Add((Join-Path (Split-Path -Parent ([string]$sync.ScriptPath)) 'eklentiler')) } } catch { }
    try { if (-not [string]::IsNullOrEmpty([string]$sync.DataDir)) { [void]$dirs.Add((Join-Path ([string]$sync.DataDir) 'Eklentiler')) } } catch { }
    return , $dirs.ToArray()
}

# Tek bir eklenti islemini dogrular; gecerliyse katalog islemi (hashtable), degilse neden (metin) doner
function ConvertTo-PluginOp($O) {
    $t = [string](Get-JsonProp $O 'T')
    if ($t -eq 'Reg') {
        $path = [string](Get-JsonProp $O 'Path')
        $name = [string](Get-JsonProp $O 'Name')
        if ($path -notmatch '^(HKLM|HKCU)\\[^\\].*[^\\]$') { return (('ge' + [char]0x00E7 + 'ersiz kay' + [char]0x0131 + 't defteri yolu: ') + $path) }
        if ((Test-RegWriteBlocked $path $name) -ne '') { return (('g' + [char]0x00FC + 'venlik kap' + [char]0x0131 + 's' + [char]0x0131 + 'ndaki yola yaz' + [char]0x0131 + 'lamaz: ') + $path) }
        if ((Get-JsonProp $O 'Del') -eq $true) { return (RegDel $path $name) }
        $kind = [string](Get-JsonProp $O 'Kind')
        if ($kind -eq '') { $kind = 'DWord' }
        if (@('DWord', 'QWord', 'String', 'ExpandString') -notcontains $kind) { return (('desteklenmeyen de' + [char]0x011F + 'er t' + [char]0x00FC + 'r' + [char]0x00FC + ': ') + $kind) }
        $val = Get-JsonProp $O 'Value'
        if ($null -eq $val) { return (('de' + [char]0x011F + 'er eksik: ') + $path + '\' + $name) }
        if ($val -is [array] -or $val -is [System.Management.Automation.PSCustomObject]) { return (('de' + [char]0x011F + 'er say' + [char]0x0131 + ' ya da metin olmal' + [char]0x0131 + ': ') + $name) }
        if ($kind -eq 'DWord' -or $kind -eq 'QWord') {
            $num = 0L
            if (-not [long]::TryParse([string]$val, [ref]$num)) { return (('say' + [char]0x0131 + ' bekleniyordu: ') + $name) }
            return (RegOp $path $name $num $kind)
        }
        return (RegOp $path $name ([string]$val) $kind)
    }
    if ($t -eq 'Svc') {
        $name = [string](Get-JsonProp $O 'Name')
        $start = [string](Get-JsonProp $O 'Start')
        if ($name -cnotmatch '^[A-Za-z0-9_.\-]{1,80}$') { return (('ge' + [char]0x00E7 + 'ersiz hizmet ad' + [char]0x0131 + ': ') + $name) }
        if (@('Disabled', 'Manual', 'Auto') -notcontains $start) { return (('ge' + [char]0x00E7 + 'ersiz ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' t' + [char]0x00FC + 'r' + [char]0x00FC + ': ') + $start) }
        if (Test-SvcLocked $name) { return (('korumal' + [char]0x0131 + ' hizmet: ') + $name) }
        return (SvcOp $name $start)
    }
    if ($t -eq 'Task') {
        $path = [string](Get-JsonProp $O 'Path')
        $name = [string](Get-JsonProp $O 'Name')
        $act = [string](Get-JsonProp $O 'Action')
        if ($act -eq '') { $act = 'Disable' }
        if ($path -notmatch '^\\.*\\$' -or $name -eq '') { return (('ge' + [char]0x00E7 + 'ersiz g' + [char]0x00F6 + 'rev yolu: ') + $path + $name) }
        if (@('Disable', 'Enable') -notcontains $act) { return (('ge' + [char]0x00E7 + 'ersiz g' + [char]0x00F6 + 'rev eylemi: ') + $act) }
        return (TaskOp $path $name $act)
    }
    return (('desteklenmeyen i' + [char]0x015F + 'lem t' + [char]0x00FC + 'r' + [char]0x00FC + ': ') + $t + (' (yaln' + [char]0x0131 + 'zca Reg, Svc, Task)'))
}

function Import-PluginFile([string]$File) {
    $base = [System.IO.Path]::GetFileNameWithoutExtension($File)
    $safe = [regex]::Replace($base, '[^A-Za-z0-9]', '')
    if ($safe -eq '') { $safe = 'eklenti' }
    $obj = $null
    try { $obj = Read-JsonFile $File } catch { [void]$script:PluginNotes.Add($base + (': JSON okunamad' + [char]0x0131 + ' (') + $_.Exception.Message + ')'); return 0 }
    $pname = [string](Get-JsonProp $obj 'Name')
    if ($pname -eq '') { $pname = $base }
    $author = [string](Get-JsonProp $obj 'Author')
    $added = 0
    foreach ($tw in @(Get-JsonProp $obj 'Tweaks')) {
        if ($null -eq $tw) { continue }
        $id = [string](Get-JsonProp $tw 'Id')
        $title = [string](Get-JsonProp $tw 'Title')
        $desc = [string](Get-JsonProp $tw 'Desc')
        if ($id -cnotmatch '^[A-Za-z0-9_]{2,40}$') { [void]$script:PluginNotes.Add($pname + (': ge' + [char]0x00E7 + 'ersiz kimlik "') + $id + '"'); continue }
        if ($title.Length -lt 3 -or $title.Length -gt 140) { [void]$script:PluginNotes.Add($pname + '/' + $id + (': ba' + [char]0x015F + 'l' + [char]0x0131 + 'k 3-140 karakter olmal' + [char]0x0131 + '')); continue }
        if ($desc.Length -gt 800) { $desc = $desc.Substring(0, 800) }
        $lv = 3
        try { $lv = [int](Get-JsonProp $tw 'Level') } catch { $lv = 3 }
        if ($lv -lt 2) { $lv = 2 }
        if ($lv -gt 3) { $lv = 3 }
        $os = [string](Get-JsonProp $tw 'OS')
        if (@('10', '11') -notcontains $os) { $os = 'All' }
        $rawOps = @(Get-JsonProp $tw 'Ops')
        if ($rawOps.Count -lt 1 -or $rawOps.Count -gt 60) { [void]$script:PluginNotes.Add($pname + '/' + $id + (': 1-60 i' + [char]0x015F + 'lem olmal' + [char]0x0131 + '')); continue }
        $ops = New-Object System.Collections.ArrayList
        $bad = ''
        foreach ($o in $rawOps) {
            $c = ConvertTo-PluginOp $o
            if ($c -is [string]) { $bad = $c; break }
            [void]$ops.Add($c)
        }
        if ($bad -ne '') { [void]$script:PluginNotes.Add($pname + '/' + $id + ': ' + $bad); continue }
        $fullId = 'x_' + $safe + '_' + $id
        if ($null -ne (Get-CatalogItem $fullId)) { continue }
        $src = $pname
        if ($author -ne '') { $src += (' - ' + $author) }
        Add-Tweak @{
            Id = $fullId; Cat = 'Eklenti'; Level = $lv; OS = $os; Page = 'opt'
            Title = $title; Desc = ($desc + '  (Eklenti: ' + $src + ')')
            Reboot = ((Get-JsonProp $tw 'Reboot') -eq $true)
            Ops = $ops.ToArray(); Plugin = $pname
        }
        $added++
    }
    return $added
}

function Import-Plugins {
    $script:PluginNotes = New-Object System.Collections.ArrayList
    $n = 0
    foreach ($d in (Get-PluginDirs)) {
        if (-not (Test-Path -LiteralPath $d -PathType Container)) { continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $d -Filter '*.json' -File -ErrorAction SilentlyContinue | Sort-Object Name | Select-Object -First 50)) {
            try { $n += (Import-PluginFile $f.FullName) } catch { [void]$script:PluginNotes.Add($f.Name + ': ' + $_.Exception.Message) }
        }
    }
    $script:PluginCount = $n
    # Eklenti ayarlari hicbir hazir secime kendiliginden girmez; yalnizca elle isaretlenir
    foreach ($c in $script:Catalog) {
        if ($null -ne $c.Plugin -and [string]$c.Plugin -ne '') { $c.Need = 'Manual'; $c.NeedWhy = ('Eklenti ayarlar' + [char]0x0131 + ' yaln' + [char]0x0131 + 'zca elle se' + [char]0x00E7 + 'ilir.') }
    }
    return $n
}

