    OptFocus   = @{ T = 'Odak / oyun kipi'; D = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'kken arama dizini, SysMain gibi arka plan hizmetlerini ge' + [char]0x00E7 + 'ici olarak durdurur ve g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + 'n' + [char]0x0131 + ' y' + [char]0x00FC + 'kseltir; kapat' + [char]0x0131 + 'nca geri al' + [char]0x0131 + 'r. Yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r.') }
    OptRam     = @{ T = ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ''); D = ('Programlar' + [char]0x0131 + 'n kullanmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' belle' + [char]0x011F + 'i ve bekleme ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'ini bo' + [char]0x015F + 'alt' + [char]0x0131 + 'r. Etkisi ge' + [char]0x00E7 + 'icidir; Windows belle' + [char]0x011F + 'i zaten kendi y' + [char]0x00F6 + 'netir, s' + [char]0x0131 + 'k kullanmak sistemi yava' + [char]0x015F + 'lat' + [char]0x0131 + 'r.') }
    OptCrypto  = @{ T = ('Dosya ' + [char]0x015F + 'ifreleme (AES-256)'); D = ('Se' + [char]0x00E7 + 'ti' + [char]0x011F + 'iniz dosyalar' + [char]0x0131 + ' parolayla ' + [char]0x015F + 'ifreler (.mmz). Parolay' + [char]0x0131 + ' unutursan' + [char]0x0131 + 'z dosya kurtar' + [char]0x0131 + 'lamaz; ' + [char]0x00F6 + 'nemli dosyalar i' + [char]0x00E7 + 'in ayr' + [char]0x0131 + 'ca yedek tutun.') }
    OptScan    = @{ T = ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' a' + [char]0x011F + ' taramas' + [char]0x0131 + ' (portlar)'); D = ('A' + [char]0x011F + 'daki cihazlar' + [char]0x0131 + ' bulma her zaman a' + [char]0x00E7 + '' + [char]0x0131 + 'kt' + [char]0x0131 + 'r. Bu se' + [char]0x00E7 + 'enek, bulunan cihazlar' + [char]0x0131 + 'n yayg' + [char]0x0131 + 'n hizmet portlar' + [char]0x0131 + 'na tek tek ba' + [char]0x011F + 'lanmay' + [char]0x0131 + ' dener ve web aray' + [char]0x00FC + 'z' + [char]0x00FC + ' ba' + [char]0x015F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' okur; b' + [char]0x00F6 + 'ylece cihaz t' + [char]0x00FC + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' ve a' + [char]0x00E7 + '' + [char]0x0131 + 'k riskleri daha do' + [char]0x011F + 'ru belirler. Yaln' + [char]0x0131 + 'zca kendi a' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda kullan' + [char]0x0131 + 'n; baz' + [char]0x0131 + ' g' + [char]0x00FC + 'venlik yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'mlar' + [char]0x0131 + ' bunu uyar' + [char]0x0131 + 'yla kar' + [char]0x015F + '' + [char]0x0131 + 'lar.') }
    OptHostsMs = @{ T = ('Geni' + [char]0x015F + 'letilmi' + [char]0x015F + ' hosts listesi'); D = ('hosts engeline Windows telemetri sunucular' + [char]0x0131 + 'n' + [char]0x0131 + ' da ekler. Defender bu de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i "HostsFileHijack" olarak i' + [char]0x015F + 'aretleyip geri alabilir.') }
    OptVt      = @{ T = ('VirusTotal aramas' + [char]0x0131 + ''); D = ('Dosya ' + [char]0x00F6 + 'zeti ekran' + [char]0x0131 + 'na "VirusTotal''da ara" d' + [char]0x00FC + '' + [char]0x011F + 'mesi ekler. Yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'zet (SHA-256) taray' + [char]0x0131 + 'c' + [char]0x0131 + 'da a' + [char]0x00E7 + '' + [char]0x0131 + 'lan adrese gider; dosya y' + [char]0x00FC + 'klenmez.') }
}

function Get-OptValue([string]$Name, $Default = $false) {
    try {
        $st = Get-Settings
        if ($st.ContainsKey($Name) -and $null -ne $st[$Name]) { return $st[$Name] }
    } catch { }
    return $Default
}

function Test-Opt([string]$Name) { return ((Get-OptValue $Name $false) -eq $true) }

# AES-256 dosya sifreleme ve bellek bosaltici Eklenti\ klasorundeki ayri dosyalardadir (bkz. Veri ve eklenti dosyalari bolumu); gerektiginde yuklenir.

# ---------------- islem onceligi ----------------
# P: Pid, Level ('BelowNormal' | 'Normal' | 'AboveNormal')
function Job_Priority($P) {
    try {
        $pr = Get-Process -Id ([int]$P.Pid) -ErrorAction Stop
        if ($script:CriticalProcs -contains $pr.ProcessName.ToLowerInvariant()) { Write-WhLog (('Sistem i' + [char]0x015F + 'leminin ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'i de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmez: ') + $pr.ProcessName) 'WARN'; return @{ Ok = $false } }
        $lv = [string]$P.Level
        if (@('BelowNormal', 'Normal', 'AboveNormal') -notcontains $lv) { $lv = 'Normal' }
        $pr.PriorityClass = [System.Diagnostics.ProcessPriorityClass]$lv
        Write-WhLog (('' + [char]0x00D6 + 'ncelik de' + [char]0x011F + 'i' + [char]0x015F + 'ti: ') + $pr.ProcessName + ' -> ' + $lv + (' (program kapan' + [char]0x0131 + 'nca s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r)')) 'OK'
        return @{ Ok = $true }
    } catch { Write-WhLog (('' + [char]0x00D6 + 'ncelik de' + [char]0x011F + 'i' + [char]0x015F + 'tirilemedi: ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false } }
}

