$script:FocusServices = @('WSearch', 'SysMain', 'DiagTrack', 'DoSvc', 'MapsBroker', 'WerSvc')
$script:HighPerfGuid = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'

function Get-FocusFile { return (Join-Path ([string]$sync.DataDir) 'odak.json') }

function Get-FocusState {
    $f = Get-FocusFile
    if (-not (Test-Path -LiteralPath $f)) { return @{ On = $false; Stopped = @(); Plan = '' } }
    try {
        $o = ConvertTo-Hashtable (Read-JsonFile $f)
        # Bilgisayar yeniden basladiysa hizmetler zaten geri gelmistir: kip kapali sayilir
        $boot = (Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime
        if ($null -ne $o.At -and ([datetime][string]$o.At) -lt $boot) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue; return @{ On = $false; Stopped = @(); Plan = '' } }
        return @{ On = $true; Stopped = @($o.Stopped); Plan = [string]$o.Plan }
    } catch { return @{ On = $false; Stopped = @(); Plan = '' } }
}

function Job_FocusState($P) {
    $st = Get-FocusState
    return @{ On = ($st.On -eq $true); Count = @($st.Stopped).Count }
}

# P: On (bool)
function Job_Focus($P) {
    $f = Get-FocusFile
    $cur = Get-FocusState
    if ($P.On -eq $true) {
        if ($cur.On) { Write-WhLog ('Odak kipi zaten a' + [char]0x00E7 + '' + [char]0x0131 + 'k.') 'SKIP'; return @{ Ok = $true; On = $true; Count = @($cur.Stopped).Count } }
        $stopped = New-Object System.Collections.ArrayList
        foreach ($n in $script:FocusServices) {
            if (Test-SvcLocked $n) { continue }
            $s = Get-Service -Name $n -ErrorAction SilentlyContinue
            if ($null -eq $s -or [string]$s.Status -ne 'Running') { continue }
            try { Stop-Service -Name $n -Force -ErrorAction Stop; [void]$stopped.Add($n); Write-WhLog (('Ge' + [char]0x00E7 + 'ici olarak durduruldu: ') + $n) 'OK' }
            catch { Write-WhLog (('Durdurulamad' + [char]0x0131 + ': ') + $n) 'WARN' }
        }
        $plan = ''
        try {
            $m = [regex]::Match((& powercfg.exe /getactivescheme | Out-String), $script:GuidRx)
            if ($m.Success) { $plan = $m.Value }
            if ($plan -ne $script:HighPerfGuid -and ((& powercfg.exe /list | Out-String) -match $script:HighPerfGuid)) {
                & powercfg.exe /setactive $script:HighPerfGuid | Out-Null
                Write-WhLog ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' ge' + [char]0x00E7 + 'ici olarak Y' + [char]0x00FC + 'ksek Performans yap' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'OK'
            } else { $plan = '' }
        } catch { $plan = '' }
        Save-JsonFile @{ At = (Get-Date).ToString('s'); Stopped = $stopped.ToArray(); Plan = $plan } $f 4
        Write-WhLog (('Odak kipi a' + [char]0x00E7 + '' + [char]0x0131 + 'k: ') + [string]$stopped.Count + (' arka plan hizmeti durduruldu. Kapat' + [char]0x0131 + 'nca ya da yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'nca geri gelir.')) 'INFO'
        return @{ Ok = $true; On = $true; Count = $stopped.Count }
    }
    if (-not $cur.On) { Write-WhLog ('Odak kipi zaten kapal' + [char]0x0131 + '.') 'SKIP'; return @{ Ok = $true; On = $false; Count = 0 } }
    $back = 0
    foreach ($n in @($cur.Stopped)) {
        try { Start-Service -Name ([string]$n) -ErrorAction Stop; $back++ } catch { Write-WhLog (('Ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + [string]$n) 'WARN' }
    }
    if ([string]$cur.Plan -ne '') { try { & powercfg.exe /setactive ([string]$cur.Plan) | Out-Null } catch { } }
    Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
    Write-WhLog (('Odak kipi kapand' + [char]0x0131 + ': ') + [string]$back + (' hizmet yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + '.')) 'INFO'
    return @{ Ok = $true; On = $false; Count = $back }
}

# ---------------- ayar bekcisi: geri donen ayarlari sormadan yeniden uygular ----------------
function Job_Guard($P) {
    $ids = Get-DriftedIds
    if ($ids.Count -eq 0) { Write-WhLog ('Ayar bek' + [char]0x00E7 + 'isi: geri d' + [char]0x00F6 + 'nen ayar yok.') 'OK'; return @{ Ok = $true; Changes = 0; Errors = 0; Count = 0 } }
    Write-WhLog (('Ayar bek' + [char]0x00E7 + 'isi: ') + [string]$ids.Count + (' ayar eski h' + [char]0x00E2 + 'line d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + ', yeniden uygulan' + [char]0x0131 + 'yor.')) 'WARN'
    $res = Job_Plan @{ Steps = (New-StepsFromIds ([string[]]$ids)); Preview = $false; RestorePoint = $false }
    $res.Count = $ids.Count
    $res.Ok = ([int]$res.Errors -eq 0)
    return $res
}

# ---------------- ag taramasi (yalnizca yerel / ozel adresler) ----------------
function Test-PrivateIp([string]$Ip) {
    $a = $null
    if (-not [System.Net.IPAddress]::TryParse($Ip, [ref]$a)) { return $false }
    if ($a.AddressFamily -ne [System.Net.Sockets.AddressFamily]::InterNetwork) { return $false }
    $b = $a.GetAddressBytes()
    if ($b[0] -eq 10) { return $true }
    if ($b[0] -eq 172 -and $b[1] -ge 16 -and $b[1] -le 31) { return $true }
    if ($b[0] -eq 192 -and $b[1] -eq 168) { return $true }
    if ($b[0] -eq 169 -and $b[1] -eq 254) { return $true }
    return $false
}

# Kendi adresinin bulundugu /24 dilimindeki adresler (en cok 254; daha genis aglarda da yalnizca bu dilim)
function Get-SweepTargets([string]$Ip) {
    $out = New-Object System.Collections.ArrayList
    if (-not (Test-PrivateIp $Ip)) { return , $out.ToArray() }
    $p = $Ip.Split('.')
    $pre = $p[0] + '.' + $p[1] + '.' + $p[2] + '.'
    for ($i = 1; $i -le 254; $i++) { $t = $pre + [string]$i; if ($t -ne $Ip) { [void]$out.Add($t) } }
    return , $out.ToArray()
}

function Job_LanSweep($P) {
    $own = New-Object System.Collections.ArrayList
    try {
        foreach ($c in @(Get-NetIPConfiguration -ErrorAction Stop | Where-Object { $null -ne $_.NetAdapter -and [string]$_.NetAdapter.Status -eq 'Up' -and $_.IPv4DefaultGateway })) {
            if ($c.IPv4Address) { $ip = [string]@($c.IPv4Address)[0].IPAddress; if (Test-PrivateIp $ip) { [void]$own.Add($ip) } }
        }
    } catch { }
    if ($own.Count -eq 0) { Write-WhLog ('Taranacak yerel a' + [char]0x011F + ' bulunamad' + [char]0x0131 + ' (' + [char]0x00F6 + 'zel adresli etkin ba' + [char]0x011F + 'lant' + [char]0x0131 + ' yok).') 'WARN'; return (Job_Neighbors @{}) }
    foreach ($ip in $own) {
        $targets = Get-SweepTargets $ip
        Write-WhLog (('Yerel a' + [char]0x011F + ' taran' + [char]0x0131 + 'yor: ') + $ip + (' ' + [char]0x00E7 + 'evresindeki ') + [string]$targets.Count + ' adres') 'INFO'
        Set-JobProgress 0 0 ('A' + [char]0x011F + 'daki cihazlar aran' + [char]0x0131 + 'yor')
        $tasks = New-Object System.Collections.ArrayList
        $pings = New-Object System.Collections.ArrayList
        foreach ($t in $targets) {
            try { $pg = New-Object System.Net.NetworkInformation.Ping; [void]$pings.Add($pg); [void]$tasks.Add($pg.SendPingAsync([string]$t, 600)) } catch { }
        }
        try { [void][System.Threading.Tasks.Task]::WaitAll([System.Threading.Tasks.Task[]]$tasks.ToArray(), 6000) } catch { }
        # suren ping nesnesi serbest birakilmaz (bekleyen ICMP geri cagrisi kapatilmis tutamaca yazabilir): tamamlananlar hemen, kalanlar kisa bekleyisten sonra
        $late = New-Object System.Collections.ArrayList
        for ($pi = 0; $pi -lt $pings.Count; $pi++) {
            $done = $true
            try { if ($pi -lt $tasks.Count) { $done = [bool]$tasks[$pi].IsCompleted } } catch { }
            if ($done) { try { $pings[$pi].Dispose() } catch { } } else { [void]$late.Add($pings[$pi]) }
        }
        if ($late.Count -gt 0) { Start-Sleep -Milliseconds 1500; foreach ($pg in $late) { try { $pg.Dispose() } catch { } } }
        if (Test-JobCancel) { break }
    }
    return (Job_Neighbors @{})
}

$script:CommonPorts = [ordered]@{
    '21' = 'FTP'; '22' = 'SSH'; '23' = 'Telnet'; '25' = 'SMTP'; '53' = 'DNS'; '80' = 'HTTP'; '110' = 'POP3'; '135' = 'RPC'; '139' = 'NetBIOS'
    '143' = 'IMAP'; '443' = 'HTTPS'; '445' = 'SMB'; '515' = ('LPD yaz' + [char]0x0131 + 'c' + [char]0x0131 + ''); '631' = ('IPP yaz' + [char]0x0131 + 'c' + [char]0x0131 + ''); '1433' = 'SQL Server'; '3306' = 'MySQL'
    '3389' = ('Uzak Masa' + [char]0x00FC + 'st' + [char]0x00FC + ''); '5000' = 'UPnP'; '5357' = 'WSD'; '5900' = 'VNC'; '8080' = 'HTTP (8080)'; '8443' = 'HTTPS (8443)'; '9100' = ('Yaz' + [char]0x0131 + 'c' + [char]0x0131 + ' (RAW)')
}

# P: Host (yalnizca ozel / yerel adres)
function Job_PortCheck($P) {
    $ip = [string]$P.Host
    if (-not (Test-PrivateIp $ip)) { Write-WhLog (('Port denetimi yaln' + [char]0x0131 + 'zca yerel a' + [char]0x011F + ' adreslerinde yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r: ') + $ip) 'ERR'; return @{ Ok = $false; Open = @(); Host = $ip } }
    $open = New-Object System.Collections.ArrayList
    $keys = @($script:CommonPorts.Keys)
    Set-JobProgress 0 $keys.Count (('Portlara bak' + [char]0x0131 + 'l' + [char]0x0131 + 'yor: ') + $ip)
    foreach ($k in $keys) {
        if (Test-JobCancel) { break }
        $c = New-Object System.Net.Sockets.TcpClient
        try {
            $iar = $c.BeginConnect($ip, [int]$k, $null, $null)
            if ($iar.AsyncWaitHandle.WaitOne(350, $false)) {
                try { $c.EndConnect($iar) } catch { }
                if ($c.Connected) { [void]$open.Add(@{ Port = [int]$k; Name = [string]$script:CommonPorts[$k] }) }
            }
        } catch { } finally { try { $c.Close() } catch { } }
        Step-JobProgress
    }
    $txt = (@($open | ForEach-Object { [string]$_.Port + ' ' + [string]$_.Name }) -join ', ')
    if ($open.Count -eq 0) { Write-WhLog ($ip + (': yayg' + [char]0x0131 + 'n portlar' + [char]0x0131 + 'n hi' + [char]0x00E7 + 'biri a' + [char]0x00E7 + '' + [char]0x0131 + 'k de' + [char]0x011F + 'il.')) 'OK' } else { Write-WhLog ($ip + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'k portlar: ') + $txt) 'INFO' }
    return @{ Ok = $true; Open = $open.ToArray(); Host = $ip; Text = $txt }
}

# ---------------- PATH denetimi (eksik ve yinelenen girdiler) ----------------
$script:EnvKey = 'HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\Environment'

# Donus: @{ Entries = @(@{ Text; Expanded; Missing; Dup }); Clean = 'yeni deger'; Raw = 'simdiki deger'; Kind }
function Get-PathReport([string]$Raw) {
    $entries = New-Object System.Collections.ArrayList
    $keep = New-Object System.Collections.ArrayList
    $seen = @{}
    foreach ($part in $Raw.Split(';')) {
        $t = $part.Trim()
        if ($t -eq '') { continue }
        $exp = [Environment]::ExpandEnvironmentVariables($t).Trim('"')
        $key = $exp.TrimEnd('\').ToLowerInvariant()
        $dup = $seen.ContainsKey($key)
        $missing = $false
        try { $missing = (-not (Test-Path -LiteralPath $exp -PathType Container)) } catch { $missing = $true }
        if (-not $dup) { $seen[$key] = $true }
        [void]$entries.Add(@{ Text = $t; Expanded = $exp; Missing = $missing; Dup = $dup })
        if (-not $dup -and -not $missing) { [void]$keep.Add($t) }
    }
    return @{ Entries = $entries.ToArray(); Clean = ($keep.ToArray() -join ';'); Raw = $Raw }
}

function Job_PathInfo($P) {
    $i = Get-RegInfo $script:EnvKey 'Path'
    if (-not $i.Exists) { Write-WhLog ('Sistem PATH de' + [char]0x011F + 'eri okunamad' + [char]0x0131 + '.') 'ERR'; return @{ Ok = $false } }
    $rep = Get-PathReport ([string]$i.Value)
    $rep.Ok = $true
    $rep.Kind = [string]$i.Kind
    $rep.Bad = @($rep.Entries | Where-Object { $_.Missing -or $_.Dup }).Count
    return $rep
}

# Temizlenmis PATH'i yazan plan adimi (kayit defteri islemi oldugu icin onizlenir ve geri alinir)
function New-PathCleanSteps([string]$Clean, [string]$Kind) {
    if ($Kind -ne 'String') { $Kind = 'ExpandString' }
    return , @(@{ Id = 'PathClean'; Title = ('Sistem PATH: olmayan ve yinelenen klas' + [char]0x00F6 + 'rleri ' + [char]0x00E7 + '' + [char]0x0131 + 'kar'); Ops = @((RegOp $script:EnvKey 'Path' $Clean $Kind)); Reboot = $false })
}

