# ---------------- Duzeltme motoru ----------------
# ==================================================================
#  DUZELTME MOTORU: saglik bulgularindan "Duzelt" ve "Hepsini duzelt"
#  Her bulgu bir Fix (duzeltme tarifi) tasiyabilir. Tarifler yalnizca veridir (hashtable);
#  uygulama Job_Plan uzerinden gecer: onizleme, geri alma kaydi, dogrulama.
#
#  Fix.Mode:
#    Auto    : "Hepsini duzelt" kapsaminda; riski dusuk, yan etkisi bilinen, geri alinabilir
#    Click   : tek tek dugmeyle uygulanir; yan etkisi olabilecegi icin toplu duzeltmeye girmez
#    Guided  : ilgili sayfa ya da Windows ayari acilir (kullanici karar verir)
#    Manual  : yalnizca aciklama (yapilacak sey aractan yapilamaz)
#  Fix.Kind:
#    Tweak    : Ids = katalog ayarlari
#    Steps    : Steps = hazir plan adimlari (@{ Id; Title; Ops; Reboot })
#    Run      : Key = Job_Action eylemi
#    Adaptive : bu bilgisayara gore onerilen ayarlar (Level 1-2)
#    Drift    : uygulandiktan sonra geri donen ayarlar
#    Services : bu donanim icin kapatilmasi onerilen hizmetler (risk 1)
# ==================================================================

# Toplu duzeltmeye girebilecek katalog ayarlari (yan etkisi dusuk, geri alinabilir)
$script:AutoFixTweaks = @('Smb1', 'AutoRun', 'Llmnr', 'GuestOff', 'RdpNla', 'AuditLogon', 'Lockout', 'WDigest', 'NoLmHash', 'AnonEnum', 'NetStrongCrypto', 'Ps2Off')
# Toplu duzeltmeye girebilecek eylemler (Job_Action anahtarlari)
$script:AutoFixRuns = @('DefUpdate', 'DefScan', 'FwOn', 'RpCreate', 'Maint', 'WuSvcRestore')

function New-FixInfo([string]$Mode, [string]$Kind, [string]$Label, [string]$Note = '') {
    return @{ Mode = $Mode; Kind = $Kind; Label = $Label; Note = $Note; Ids = @(); Steps = @(); Key = '' }
}

function New-TweakFix([string[]]$Ids, [string]$Label, [string]$Mode = '') {
    if ($Mode -eq '') {
        $Mode = 'Auto'
        foreach ($i in $Ids) { if ($script:AutoFixTweaks -notcontains $i) { $Mode = 'Click' } }
    }
    $f = New-FixInfo $Mode 'Tweak' $Label
    $f.Ids = @($Ids)
    return $f
}

function New-StepsFix([string]$Mode, [string]$Label, $Steps, [string]$Note = '') {
    $f = New-FixInfo $Mode 'Steps' $Label $Note
    $f.Steps = @($Steps)
    return $f
}

function New-RunFix([string]$Key, [string]$Label, [string]$Mode = '') {
    if ($Mode -eq '') { if ($script:AutoFixRuns -contains $Key) { $Mode = 'Auto' } else { $Mode = 'Click' } }
    $f = New-FixInfo $Mode 'Run' $Label
    $f.Key = $Key
    return $f
}

# Eski (Action tabanli) bulgulara Fix turetir
function Resolve-FindingFix($F) {
    if ($null -ne $F.Fix) { return }
    if ($F.Status -eq 'ok') { return }
    $a = $F.Action
    if ($null -eq $a) { if ($F.Status -eq 'bad' -or $F.Status -eq 'warn') { $F.Fix = (New-FixInfo 'Manual' 'None' '') }; return }
    $k = [string]$a.Kind
    $lbl = [string]$a.Label
    if ($k -eq 'Tweak') {
        $F.Fix = (New-TweakFix @([string]$a.Id) $lbl)
    } elseif ($k -eq 'Run') {
        $key = [string]$a.Key
        if ($key -eq 'Reboot') { $F.Fix = (New-FixInfo 'Guided' 'Page' $lbl) }
        else { $F.Fix = (New-RunFix $key $lbl) }
    } elseif ($k -eq 'Page' -or $k -eq 'Url') {
        $F.Fix = (New-FixInfo 'Guided' $k $lbl)
    }
}

# Bulgu listesinden benzersiz duzeltme listesi (anahtar -> Fix). Ayni ayar iki bulguda gecerse tek kez.
function Get-FixList($Findings) {
    $out = New-Object System.Collections.ArrayList
    $seen = @{}
    foreach ($f in @($Findings)) {
        if ($null -eq $f.Fix) { continue }
        $m = [string]$f.Fix.Mode
        if ($m -ne 'Auto' -and $m -ne 'Click') { continue }
        $key = [string]$f.Id
        if ([string]$f.Fix.Kind -eq 'Tweak') { $key = 'tw:' + (@($f.Fix.Ids) -join ',') }
        elseif ([string]$f.Fix.Kind -eq 'Run') { $key = 'run:' + [string]$f.Fix.Key }
        elseif ([string]$f.Fix.Kind -ne 'Steps') { $key = 'k:' + [string]$f.Fix.Kind }
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        [void]$out.Add(@{ Id = [string]$f.Id; Title = [string]$f.Title; Status = [string]$f.Status; Cat = [string]$f.Cat; Fix = $f.Fix; Mode = $m })
    }
    return , $out.ToArray()
}

# ---------------- yeni islem turleri ----------------
# Guvenlik duvari profilinin varsayilan gelen/giden eylemi.  Op: @{ T='FwDefault'; Profile='Public'; Inbound='Block' }
function Invoke-FwDefaultOp($Op) {
    $pn = [string]$Op.Profile
    $p = Get-NetFirewallProfile -Name $pn -ErrorAction Stop
    $curIn = [string]$p.DefaultInboundAction
    $curOut = [string]$p.DefaultOutboundAction
    $wantIn = [string]$Op.Inbound
    if ($wantIn -eq '') { $wantIn = $curIn }
    $wantOut = [string]$Op.Outbound
    if ($wantOut -eq '') { $wantOut = $curOut }
    if ($curIn -eq $wantIn -and $curOut -eq $wantOut) { Add-Skip (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' varsay' + [char]0x0131 + 'lan' + [char]0x0131 + ' zaten uygun: ') + $pn); return }
    if ($script:Preview) { Add-Plan (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' ') + $pn + ': gelen ' + $curIn + ' -> ' + $wantIn + ', giden ' + $curOut + ' -> ' + $wantOut); return }
    Add-Journal @{ T = 'FwDefault'; Profile = $pn; PrevIn = $curIn; PrevOut = $curOut }
    Set-NetFirewallProfile -Name $pn -DefaultInboundAction $wantIn -DefaultOutboundAction $wantOut -ErrorAction Stop
    Add-Done (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' ') + $pn + ': gelen ' + $wantIn + ', giden ' + $wantOut)
}

function Undo-FwDefaultItem($It) {
    Set-NetFirewallProfile -Name ([string]$It.Profile) -DefaultInboundAction ([string]$It.PrevIn) -DefaultOutboundAction ([string]$It.PrevOut) -ErrorAction Stop
    Add-Done (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' varsay' + [char]0x0131 + 'lan' + [char]0x0131 + ' geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + [string]$It.Profile)
}

# Ag profili (Genel / Ozel).  Op: @{ T='NetProfile'; Index=12; Alias='Wi-Fi'; Category='Public' }
function Invoke-NetProfileOp($Op) {
    $idx = [int]$Op.Index
    $cp = Get-NetConnectionProfile -InterfaceIndex $idx -ErrorAction Stop
    $cur = [string]$cp.NetworkCategory
    $want = [string]$Op.Category
    if ($cur -eq 'DomainAuthenticated') { Add-Skip (('Etki alan' + [char]0x0131 + ' a' + [char]0x011F + '' + [char]0x0131 + ', profil de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmez: ') + [string]$Op.Alias); return }
    if ($cur -eq $want) { Add-Skip (('A' + [char]0x011F + ' profili zaten ') + $want + ': ' + [string]$Op.Alias); return }
    if ($script:Preview) { Add-Plan (('A' + [char]0x011F + ' profili ') + [string]$Op.Alias + ': ' + $cur + ' -> ' + $want); return }
    Add-Journal @{ T = 'NetProfile'; Index = $idx; Alias = [string]$Op.Alias; Prev = $cur }
    Set-NetConnectionProfile -InterfaceIndex $idx -NetworkCategory $want -ErrorAction Stop
    Add-Done (('A' + [char]0x011F + ' profili ') + [string]$Op.Alias + ' -> ' + $want)
}

function Undo-NetProfileItem($It) {
    Set-NetConnectionProfile -InterfaceIndex ([int]$It.Index) -NetworkCategory ([string]$It.Prev) -ErrorAction Stop
    Add-Done (('A' + [char]0x011F + ' profili geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + [string]$It.Alias)
}

# Kayitli Wi-Fi agina kendiliginden baglanmayi kapat / ac.  Op: @{ T='WlanMode'; Name='AG ADI'; Mode='manual' }
function Invoke-WlanModeOp($Op) {
    $name = [string]$Op.Name
    $want = [string]$Op.Mode
    if ($name -notmatch '^[^"\r\n]{1,64}$') { Add-Skip (('Ge' + [char]0x00E7 + 'ersiz Wi-Fi profil ad' + [char]0x0131 + '')); return }
    if ($script:Preview) { Add-Plan ('Wi-Fi "' + $name + ('": kendili' + [char]0x011F + 'inden ba' + [char]0x011F + 'lanma -> ') + $want); return }
    Add-Journal @{ T = 'WlanMode'; Name = $name; Prev = $(if ($want -eq 'manual') { 'auto' } else { 'manual' }) }
    $o = & netsh.exe wlan set profileparameter ('name=' + $name) ('connectionmode=' + $want) 2>&1
    if ($LASTEXITCODE -ne 0) { throw (('netsh ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$LASTEXITCODE + ': ' + (($o | Out-String).Trim())) }
    Add-Done ('Wi-Fi "' + $name + ('": kendili' + [char]0x011F + 'inden ba' + [char]0x011F + 'lanma ') + $(if ($want -eq 'manual') { ('kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '') } else { ('a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '') }))
}

function Undo-WlanModeItem($It) {
    [void](& netsh.exe wlan set profileparameter ('name=' + [string]$It.Name) ('connectionmode=' + [string]$It.Prev) 2>&1)
    Add-Done (('Wi-Fi profili geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ': ') + [string]$It.Name)
}

$script:MoreOps['FwDefault'] = 'Invoke-FwDefaultOp'
$script:MoreUndo['FwDefault'] = 'Undo-FwDefaultItem'
$script:MoreOps['NetProfile'] = 'Invoke-NetProfileOp'
$script:MoreUndo['NetProfile'] = 'Undo-NetProfileItem'
$script:MoreOps['WlanMode'] = 'Invoke-WlanModeOp'
$script:MoreUndo['WlanMode'] = 'Undo-WlanModeItem'

# ---------------- ek eylemler (Job_Action varsayilan dali) ----------------
# Baska modullerin ekledigi eylemler: anahtar -> islev adi
$script:ExtraActions = @{}

function Invoke-ActionExtra([string]$Key, $P) {
    switch ($Key) {
        'WuSvcRestore' {
            # Windows Update hizmetleri kapatilmissa Windows'un varsayilan haline (el ile baslat) dondurur
            foreach ($n in @('wuauserv', 'UsoSvc', 'BITS')) {
                $si = Get-SvcStartInfo $n
                if ($null -ne $si.Start -and $si.Start -eq 4) {
                    Set-SvcStart $n 3 $false
                    Write-WhLog (('Hizmet varsay' + [char]0x0131 + 'lana d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + ': ') + $n + (' (el ile ba' + [char]0x015F + 'lat)')) 'OK'
                }
            }
        }
        'BatteryReport' {
            $f = Join-Path ([string]$sync.ReportDir) ('pil-raporu-' + (Get-Date -Format 'yyyyMMdd-HHmm') + '.html')
            $o = & powercfg.exe /batteryreport /output $f 2>&1
            if (Test-Path -LiteralPath $f) { Write-WhLog (('Pil raporu haz' + [char]0x0131 + 'r: ') + $f) 'OK'; try { Start-Process -FilePath $f } catch { } }
            else { throw (('Pil raporu olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + (($o | Out-String).Trim())) }
        }
        default {
            if ($script:ExtraActions.ContainsKey($Key)) { & ([string]$script:ExtraActions[$Key]) $P }
            else { Write-WhLog ('Bilinmeyen eylem: ' + $Key) 'WARN' }
        }
    }
}

# ---------------- toplu duzeltme isi ----------------
# P: Fixes (Fix tarifleri), Preview, RestorePoint
function Job_FixAll($P) {
    $fixes = @($P.Fixes)
    $preview = ($P.Preview -eq $true)
    $tweakIds = New-Object System.Collections.ArrayList
    $steps = New-Object System.Collections.ArrayList
    $runKeys = New-Object System.Collections.ArrayList
    $wantAdaptive = $false; $wantDrift = $false; $wantSvc = $false
    foreach ($fx in $fixes) {
        switch ([string]$fx.Kind) {
            'Tweak'    { foreach ($id in @($fx.Ids)) { if (-not $tweakIds.Contains([string]$id)) { [void]$tweakIds.Add([string]$id) } } }
            'Steps'    { foreach ($s in @($fx.Steps)) { [void]$steps.Add($s) } }
            'Run'      { if (-not $runKeys.Contains([string]$fx.Key)) { [void]$runKeys.Add([string]$fx.Key) } }
            'Adaptive' { $wantAdaptive = $true }
            'Drift'    { $wantDrift = $true }
            'Services' { $wantSvc = $true }
        }
    }
    $pr = $sync.Profile
    $tier = Get-CurrentTier
    if ($wantAdaptive) {
        foreach ($id in (Get-AdaptiveIds 'opt' $pr $tier)) {
            $c = Get-CatalogItem ([string]$id)
            if ($null -eq $c -or [int]$c.Level -gt 2) { continue }
            $pend = Get-TweakPending $c
            if ($pend -eq 0) { continue }
            if ($pend -lt 0 -and [string]$c.Cat -eq 'Temizlik') { continue }
            if (-not $tweakIds.Contains([string]$id)) { [void]$tweakIds.Add([string]$id) }
        }
    }
    if ($wantDrift) {
        foreach ($id in (Get-DriftedIds)) { if (-not $tweakIds.Contains([string]$id)) { [void]$tweakIds.Add([string]$id) } }
    }
    $all = New-Object System.Collections.ArrayList
    if ($tweakIds.Count -gt 0) { foreach ($s in (New-StepsFromIds ([string[]]$tweakIds.ToArray()))) { [void]$all.Add($s) } }
    foreach ($s in $steps) { [void]$all.Add($s) }
    $svcN = 0
    if ($wantSvc) {
        $names = New-Object System.Collections.ArrayList
        try { foreach ($row in (Get-ServiceRows)) { if (Test-SvcAdaptive $row $tier 1) { [void]$names.Add([string]$row.Name) } } } catch { Write-WhLog (('Hizmetler okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
        $svcN = $names.Count
        if ($svcN -gt 0) { foreach ($s in (New-ServiceSteps $names.ToArray() 'Off')) { [void]$all.Add($s) } }
    }
    Write-WhLog (('D' + [char]0x00FC + 'zeltme plan' + [char]0x0131 + ': ') + [string]$tweakIds.Count + ' ayar, ' + [string]$steps.Count + (' ' + [char]0x00F6 + 'zel ad' + [char]0x0131 + 'm, ') + [string]$svcN + ' hizmet, ' + [string]$runKeys.Count + ' eylem') 'INFO'
    $res = @{ Changes = 0; Skipped = 0; Errors = 0; Freed = 0.0; Preview = $preview; Reboot = $false; Summary = ''; Ran = @() }
    $rpDone = $false
    if ($all.Count -gt 0) {
        $r = Job_Plan @{ Steps = $all.ToArray(); Preview = $preview; RestorePoint = ($P.RestorePoint -eq $true) }
        $res.Changes = [int]$r.Changes; $res.Skipped = [int]$r.Skipped; $res.Errors = [int]$r.Errors
        $res.Freed = [double]$r.Freed; $res.Reboot = ($r.Reboot -eq $true); $res.Summary = [string]$r.Summary
        $rpDone = ($P.RestorePoint -eq $true -and -not $preview)
    }
    $ran = New-Object System.Collections.ArrayList
    foreach ($k in $runKeys) {
        if ($k -eq 'RpCreate' -and $rpDone) { continue }
        if ($preview) { Write-WhLog (('' + [char]0x00D6 + 'N' + [char]0x0130 + 'ZLEME: ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak eylem: ') + $k) 'PLAN'; continue }
        $ra = Job_Action @{ Key = $k }
        if ($null -ne $ra -and $ra.Ok -eq $false) { $res.Errors = [int]$res.Errors + 1 } else { $res.Changes = [int]$res.Changes + 1 }
        [void]$ran.Add($k)
    }
    $res.Ran = $ran.ToArray()
    if ($res.Summary -eq '') { $res.Summary = ('D' + [char]0x00FC + 'zeltme tamamland' + [char]0x0131 + '.') }
    Write-WhLog (('D' + [char]0x00FC + 'zeltme: ') + [string]$res.Changes + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik, ') + [string]$res.Skipped + (' atland' + [char]0x0131 + ', ') + [string]$res.Errors + ' hata') 'INFO'
    return $res
}

# ---------------- Derin denetimler ----------------
# ==================================================================
#  DERIN DENETIMLER: hizmetler, baslangic, zamanlanmis gorevler, ag, Defender, sistem, uyarlama
#  Yalnizca okur. Her denetim kendi basina calisir; biri basarisiz olursa digerleri etkilenmez.
#  Duzeltilebilir bulgular bir Fix tarifi tasir (bkz. Duzeltme motoru bolumu).
# ==================================================================

$script:SvcRowsCache = $null

# Yazilabilir (dusuk guvenlikli) konumdan calisan yurutulebilir dosya mi?
function Test-UserWritablePath([string]$Path) {
    if ([string]::IsNullOrEmpty($Path)) { return $false }
    $lp = $Path.ToLowerInvariant()
    return ($lp -cmatch '\\(appdata|temp|downloads|users\\public|windows\\temp)\\' -or $lp -cmatch '^[a-z]:\\(users\\[^\\]+\\)?(desktop|documents)\\')
}

function Test-WindowsOwnPath([string]$Path) {
    $w = ([string]$env:WINDIR).TrimEnd('\')
    if ([string]::IsNullOrEmpty($Path)) { return $false }
    return ($Path.StartsWith($w + '\', [StringComparison]::OrdinalIgnoreCase) -or $Path -match '(?i)\\Windows Defender\\|\\WindowsApps\\Microsoft\.')
}

# Tirnaksiz ve bosluklu hizmet yolunu tirnaklar. Ham kayit degerini alir; duzeltilecek yoksa '' doner.
function Get-QuotedImagePath([string]$Raw) {
    $r = $Raw.Trim()
    if ($r -eq '' -or $r.StartsWith('"')) { return '' }
    $m = [regex]::Match($r, '^(?<exe>.+?\.(exe|bat|cmd|com))(?<rest>(\s.*)?)$', 'IgnoreCase')
    if (-not $m.Success) { return '' }
    $exe = $m.Groups['exe'].Value
    if ($exe -notmatch '\s') { return '' }
    $real = [Environment]::ExpandEnvironmentVariables($exe)
    if (-not (Test-Path -LiteralPath $real -PathType Leaf)) { return '' }
    return ('"' + $exe + '"' + $m.Groups['rest'].Value)
}

function Get-SvcRowsOnce {
    if ($null -ne $script:SvcRowsCache) { return $script:SvcRowsCache }
    $d0 = 0; $t0 = 0
    if ($null -ne $J) { $d0 = [int]$J.Done; $t0 = [int]$J.Total }
    $rows = Get-ServiceRows
    if ($null -ne $J) { $J.Done = $d0; $J.Total = $t0 }
    $script:SvcRowsCache = $rows
    return $rows
}

# ---------------- hizmetler (derin) ----------------
function Chk_ServicesDeep {
    $cim = @(Get-CimInstance -ClassName Win32_Service -ErrorAction Stop)
    $unq = New-Object System.Collections.ArrayList
    $orphan = New-Object System.Collections.ArrayList
    $userPath = New-Object System.Collections.ArrayList
    $cands = New-Object System.Collections.ArrayList
    foreach ($s in $cim) {
        $name = [string]$s.Name
        $path = [string]$s.PathName
        if ($path -eq '' -or (Test-SvcLocked $name)) { continue }
        $exe = Get-CommandExe $path
        $own = Test-WindowsOwnPath $exe
        $mode = [string]$s.StartMode
        # kullanici yazabilir konumdan calisan hizmet
        if (-not $own -and (Test-UserWritablePath $exe)) { [void]$userPath.Add(@{ Name = $name; Display = [string]$s.DisplayName; Exe = $exe }); continue }
        # tirnaksiz bosluklu yol (ayricalik yukseltme yolu)
        if (-not $own) {
            $reg = Get-RegInfo ('HKLM\SYSTEM\CurrentControlSet\Services\' + $name) 'ImagePath'
            if ($reg.Exists) {
                $q = Get-QuotedImagePath ([string]$reg.Value)
                if ($q -ne '') { [void]$unq.Add(@{ Name = $name; Display = [string]$s.DisplayName; Kind = [string]$reg.Kind; New = $q; Old = [string]$reg.Value }) }
            }
        }
        # ikili dosyasi yok olan, ama baslatilmaya ayarli hizmet
        if (-not $own -and $mode -ne 'Disabled' -and $exe -ne '' -and $exe -notmatch '(?i)svchost\.exe$') {
            if (-not (Test-Path -LiteralPath $exe)) { [void]$orphan.Add(@{ Name = $name; Display = [string]$s.DisplayName; Exe = $exe }) }
        }
        if (-not $own -and $mode -ne 'Disabled') { [void]$cands.Add(@{ Name = $name; Display = [string]$s.DisplayName; Exe = $exe }) }
    }
    # 1) kullanici yazabilir konumdan calisan hizmet
    if ($userPath.Count -gt 0) {
        $names = ($userPath | Select-Object -First 4 | ForEach-Object { [string]$_.Display + ' (' + [string]$_.Exe + ')' }) -join '; '
        Add-Finding 'svc-userpath' 'sec' 'bad' (('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nden ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an ') + [string]$userPath.Count + ' hizmet var') (('Hizmetler normalde Program Files gibi korumal' + [char]0x0131 + ' klas' + [char]0x00F6 + 'rlerden ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r. Tan' + [char]0x0131 + 'mad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z bir program zararl' + [char]0x0131 + ' olabilir. Tan' + [char]0x0131 + 'd' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z bir program olsa bile, bu hesapta ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an ba' + [char]0x015F + 'ka bir program hizmetin dosyas' + [char]0x0131 + 'n' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tirip sistem yetkisiyle ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rabilir; m' + [char]0x00FC + 'mk' + [char]0x00FC + 'nse program' + [char]0x0131 + ' Program Files alt' + [char]0x0131 + 'na kurun: ') + $names) @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') } 12
    }
    # 2) tirnaksiz yol
    if ($unq.Count -gt 0) {
        $ops = New-Object System.Collections.ArrayList
        foreach ($u in $unq) { [void]$ops.Add(@{ T = 'Reg'; Path = ('HKLM\SYSTEM\CurrentControlSet\Services\' + [string]$u.Name); Name = 'ImagePath'; Kind = [string]$u.Kind; Value = [string]$u.New }) }
        $st = @(@{ Id = 'SvcQuote'; Title = ('Hizmet yollar' + [char]0x0131 + 'n' + [char]0x0131 + ' t' + [char]0x0131 + 'rnakla (') + [string]$unq.Count + ' hizmet)'; Ops = $ops.ToArray(); Reboot = $false })
        $names = ($unq | Select-Object -First 5 | ForEach-Object { [string]$_.Display }) -join ', '
        Add-Finding 'svc-unquoted' 'sec' 'warn' ([string]$unq.Count + (' hizmetin yolu t' + [char]0x0131 + 'rnaks' + [char]0x0131 + 'z')) (('Bo' + [char]0x015F + 'luklu ve t' + [char]0x0131 + 'rnaks' + [char]0x0131 + 'z hizmet yollar' + [char]0x0131 + ', yerel bir sald' + [char]0x0131 + 'rgan' + [char]0x0131 + 'n yetki y' + [char]0x00FC + 'kseltmesine kap' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar. D' + [char]0x00FC + 'zeltme yolu t' + [char]0x0131 + 'rna' + [char]0x011F + 'a al' + [char]0x0131 + 'r, hizmetin ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + 'n' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez: ') + $names) $null 4 (New-StepsFix 'Auto' ('Yollar' + [char]0x0131 + ' t' + [char]0x0131 + 'rnakla') $st ('Hizmet kayd' + [char]0x0131 + 'ndaki ImagePath de' + [char]0x011F + 'eri t' + [char]0x0131 + 'rnaklan' + [char]0x0131 + 'r; geri al' + [char]0x0131 + 'nabilir.'))
    }
    # 3) yetim hizmet
    if ($orphan.Count -gt 0) {
        $ops = New-Object System.Collections.ArrayList
        foreach ($o in $orphan) { [void]$ops.Add(@{ T = 'Svc'; Name = [string]$o.Name; Start = 'Disabled' }) }
        $st = @(@{ Id = 'SvcOrphan'; Title = ('Dosyas' + [char]0x0131 + ' silinmi' + [char]0x015F + ' hizmetleri devre d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' b' + [char]0x0131 + 'rak (') + [string]$orphan.Count + ')'; Ops = $ops.ToArray(); Reboot = $false })
        $names = ($orphan | Select-Object -First 5 | ForEach-Object { [string]$_.Display }) -join ', '
        Add-Finding 'svc-orphan' 'maint' 'info' (('Program' + [char]0x0131 + ' silinmi' + [char]0x015F + ' ') + [string]$orphan.Count + (' hizmet kayd' + [char]0x0131 + ' kalm' + [char]0x0131 + '' + [char]0x015F + '')) (('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak dosyas' + [char]0x0131 + ' olmayan hizmetler her a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta hata ' + [char]0x00FC + 'retir: ') + $names) $null 1 (New-StepsFix 'Auto' ('Devre d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' b' + [char]0x0131 + 'rak') $st ('Hizmet silinmez, yaln' + [char]0x0131 + 'zca devre d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'l' + [char]0x0131 + 'r; geri al' + [char]0x0131 + 'nabilir.'))
    }
    # 4) beklenmedik coken hizmetler (son 14 gun)
    try {
        $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Id = 7031, 7034; StartTime = (Get-Date).AddDays(-14) } -MaxEvents 400 -ErrorAction Stop)
        $cnt = @{}
        foreach ($e in $ev) {
            $n = ''
            try { $n = [string]$e.Properties[0].Value } catch { }
            if ($n -ne '') { if ($cnt.ContainsKey($n)) { $cnt[$n]++ } else { $cnt[$n] = 1 } }
        }
        $bad = @($cnt.GetEnumerator() | Where-Object { $_.Value -ge 3 } | Sort-Object Value -Descending | Select-Object -First 4)
        if ($bad.Count -gt 0) {
            $txt = ($bad | ForEach-Object { [string]$_.Key + ' (' + [string]$_.Value + ' kez)' }) -join ', '
            Add-Finding 'svc-crash' 'maint' 'warn' (('Son 14 g' + [char]0x00FC + 'nde tekrar tekrar ' + [char]0x00E7 + '' + [char]0x00F6 + 'ken hizmet var')) (('Beklenmedik bi' + [char]0x00E7 + 'imde duran hizmetler: ') + $txt + ('. Program' + [char]0x0131 + ' g' + [char]0x00FC + 'ncelleyin ya da gerekmiyorsa hizmeti kapat' + [char]0x0131 + 'n.')) @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') } 3
        }
    } catch { }
    # 5) imzasiz / imzasi bozuk ucuncu taraf hizmet ikilileri (en cok 60 dosya)
    try {
        $seen = @{}
        $unsigned = New-Object System.Collections.ArrayList
        $tampered = New-Object System.Collections.ArrayList
        $n = 0
        foreach ($c in $cands) {
            if ($n -ge 60) { break }
            $e = [string]$c.Exe
            if ($e -eq '' -or $seen.ContainsKey($e.ToLowerInvariant()) -or -not (Test-Path -LiteralPath $e -PathType Leaf)) { continue }
            $seen[$e.ToLowerInvariant()] = $true
            $n++
            $sig = Get-AuthenticodeSignature -LiteralPath $e -ErrorAction SilentlyContinue
            if ($null -eq $sig) { continue }
            $sst = [string]$sig.Status
            if ($sst -eq 'HashMismatch') { [void]$tampered.Add([string]$c.Display) }
            elseif ($sst -eq 'NotSigned') { [void]$unsigned.Add([string]$c.Display) }
        }
        if ($tampered.Count -gt 0) {
            Add-Finding 'svc-tamper' 'sec' 'bad' ([string]$tampered.Count + (' hizmet dosyas' + [char]0x0131 + 'n' + [char]0x0131 + 'n imzas' + [char]0x0131 + ' bozuk')) (('Dosya imzaland' + [char]0x0131 + 'ktan sonra de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmi' + [char]0x015F + ': ') + (($tampered | Select-Object -First 4) -join ', ') + ('. Program' + [char]0x0131 + ' yeniden kurun ya da kald' + [char]0x0131 + 'r' + [char]0x0131 + 'n.')) @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') } 12
        }
        if ($unsigned.Count -gt 0) {
