# ---------------- hizmetler: bu donanima gore oneri (Chk_Services'in yerine gecer) ----------------
function Chk_Services {
    $rows = Get-SvcRowsOnce
    $tier = Get-CurrentTier
    $run = @($rows | Where-Object { ($_.Rec -eq 'Off' -or $_.Rec -eq 'Man') -and $_.Risk -le 2 -and -not $_.Done -and $_.State -eq 'Running' })
    $adapt = @($rows | Where-Object { Test-SvcAdaptive $_ $tier 1 })
    $t = [string]$tier.Tier
    if ($t -eq 'High' -and $run.Count -gt 0) {
        Add-Finding 'svc-run' 'perf' 'info' (('Bu bilgisayar g' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + '; ') + [string]$run.Count + (' ihtiya' + [char]0x00E7 + ' d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' hizmet ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor')) (('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' donan' + [char]0x0131 + 'mda bunlar' + [char]0x0131 + 'n kapat' + [char]0x0131 + 'lmas' + [char]0x0131 + ' hissedilir h' + [char]0x0131 + 'z kazand' + [char]0x0131 + 'rmaz; yaln' + [char]0x0131 + 'zca gizlilik ve g' + [char]0x00FC + 'venlik a' + [char]0x00E7 + '' + [char]0x0131 + 's' + [char]0x0131 + 'ndan i' + [char]0x015F + 'e yarar. Hizmetler sayfas' + [char]0x0131 + ' her birini a' + [char]0x00E7 + '' + [char]0x0131 + 'klar.')) @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') } 0
    } elseif ($run.Count -ge 8) {
        Add-Finding 'svc-run' 'perf' 'warn' ('Gereksiz olabilecek ' + [string]$run.Count + (' hizmet ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor')) (('Hizmetler sayfas' + [char]0x0131 + ' her birinin ne yapt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' ve kapat' + [char]0x0131 + 'rsan' + [char]0x0131 + 'z ne olaca' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'klar.')) @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') }
    } elseif ($run.Count -gt 0) {
        Add-Finding 'svc-run' 'perf' 'info' (('Kapat' + [char]0x0131 + 'labilir ') + [string]$run.Count + (' hizmet ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor')) '' @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') } 0
    } else {
        Add-Finding 'svc-run' 'perf' 'ok' ('Gereksiz hizmet y' + [char]0x00FC + 'k' + [char]0x00FC + ' d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'k') ''
    }
    if ($adapt.Count -gt 0) {
        $names = ($adapt | Select-Object -First 6 | ForEach-Object { [string]$_.Display }) -join ', '
        $fx = New-FixInfo 'Auto' 'Services' ('' + [char]0x00D6 + 'nerilen hizmetleri kapat') ('Yaln' + [char]0x0131 + 'zca risksiz, ba' + [char]0x011F + '' + [char]0x0131 + 'ml' + [char]0x0131 + 's' + [char]0x0131 + ' olmayan hizmetler; geri al' + [char]0x0131 + 'nabilir.')
        Add-Finding 'svc-adapt' 'perf' 'info' (('Bu bilgisayar i' + [char]0x00E7 + 'in ') + [string]$adapt.Count + (' hizmet g' + [char]0x00FC + 'venle kapat' + [char]0x0131 + 'labilir')) ([string]$tier.Label + (' s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + 'na g' + [char]0x00F6 + 're se' + [char]0x00E7 + 'ildi: ') + $names) @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') } 0 $fx
    }
