# ---------------- baslangic (derin) ----------------
function Chk_StartupDeep {
    $items = Get-StartupItems
    $dead = New-Object System.Collections.ArrayList
    foreach ($it in $items) {
        if ($it.Enabled -ne $true) { continue }
        $exe = Get-CommandExe ([string]$it.Command)
        if ($exe -eq '' -or $exe -cnotmatch '^[a-zA-Z]:\\') { continue }
        if ($exe -match '(?i)^(cmd|powershell|rundll32|wscript|cscript|mshta|explorer)(\.exe)?$') { continue }
        if (-not (Test-Path -LiteralPath $exe)) { [void]$dead.Add($it) }
    }
    if ($dead.Count -gt 0) {
        $ops = New-Object System.Collections.ArrayList
        foreach ($d in $dead) { [void]$ops.Add((New-StartupOp $d $false)) }
        $st = @(@{ Id = 'StartDead'; Title = ('Dosyas' + [char]0x0131 + ' olmayan ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' kay' + [char]0x0131 + 'tlar' + [char]0x0131 + 'n' + [char]0x0131 + ' kapat (') + [string]$dead.Count + ')'; Ops = $ops.ToArray(); Reboot = $false })
        $names = ($dead | Select-Object -First 5 | ForEach-Object { [string]$_.Name }) -join ', '
        Add-Finding 'start-dead' 'perf' 'info' (('Program' + [char]0x0131 + ' silinmi' + [char]0x015F + ' ') + [string]$dead.Count + (' ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' kayd' + [char]0x0131 + ' var')) (('Her a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta bo' + [char]0x015F + 'una aran' + [char]0x0131 + 'r: ') + $names) @{ Kind = 'Page'; Page = 'startup'; Label = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' sayfas' + [char]0x0131 + '') } 1 (New-StepsFix 'Auto' 'Kapat' $st ('Kay' + [char]0x0131 + 'tlar silinmez, G' + [char]0x00F6 + 'rev Y' + [char]0x00F6 + 'neticisi gibi devre d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'l' + [char]0x0131 + 'r; geri al' + [char]0x0131 + 'nabilir.'))
    }
}

# ---------------- zamanlanmis gorevler (derin) ----------------
function Chk_TasksDeep {
    $all = @(Get-ScheduledTask -ErrorAction Stop | Where-Object { $_.TaskPath -notlike '\Microsoft\*' -and $_.TaskPath -notlike ($script:TaskFolder + '*') })
    $susRx = Get-SuspiciousCmdRegex
    $sus = New-Object System.Collections.ArrayList
    $dead = New-Object System.Collections.ArrayList
    $tmp = New-Object System.Collections.ArrayList
    foreach ($t in $all) {
        $isDis = ([string]$t.State -eq 'Disabled')
        foreach ($a in @($t.Actions)) {
            $ex = [string]$a.Execute
            if ($ex -eq '') { continue }
            $args1 = [string]$a.Arguments
            $full = ($ex + ' ' + $args1)
            if ($full -match $susRx) { [void]$sus.Add(@{ Name = [string]$t.TaskName; Path = [string]$t.TaskPath }); break }
            $exe = Get-CommandExe $ex
            if ($exe -match '(?i)\\(Temp|Users\\Public)\\' -and -not $isDis) { [void]$tmp.Add(@{ Name = [string]$t.TaskName; Path = [string]$t.TaskPath }); break }
            if (-not $isDis -and $exe -cmatch '^[a-zA-Z]:\\' -and -not (Test-Path -LiteralPath $exe)) { [void]$dead.Add(@{ Name = [string]$t.TaskName; Path = [string]$t.TaskPath }); break }
        }
    }
    if ($sus.Count -gt 0) {
        $names = ($sus | Select-Object -First 4 | ForEach-Object { [string]$_.Path + [string]$_.Name }) -join '; '
        Add-Finding 'task-sus' 'sec' 'bad' (('Gizlenmi' + [char]0x015F + ' ya da internetten komut ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'ran ') + [string]$sus.Count + (' g' + [char]0x00F6 + 'rev var')) (('Kodlanm' + [char]0x0131 + '' + [char]0x015F + ' PowerShell, indirip ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma gibi kal' + [char]0x0131 + 'plar zararl' + [char]0x0131 + ' yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + 'n kal' + [char]0x0131 + 'c' + [char]0x0131 + 'l' + [char]0x0131 + 'k y' + [char]0x00F6 + 'ntemidir. Tan' + [char]0x0131 + 'mad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z g' + [char]0x00F6 + 'revleri devre d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'n: ') + $names) @{ Kind = 'Page'; Page = 'apps'; Label = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' ve g' + [char]0x00F6 + 'revler') } 12
    }
    if ($tmp.Count -gt 0) {
        $names = ($tmp | Select-Object -First 4 | ForEach-Object { [string]$_.Path + [string]$_.Name }) -join '; '
        Add-Finding 'task-tmp' 'sec' 'warn' (('Temp / Public klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nden ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an ') + [string]$tmp.Count + (' g' + [char]0x00F6 + 'rev var')) (('Bu klas' + [char]0x00F6 + 'rlerden ba' + [char]0x015F + 'layan g' + [char]0x00F6 + 'revler genellikle zararl' + [char]0x0131 + 'd' + [char]0x0131 + 'r: ') + $names) @{ Kind = 'Page'; Page = 'apps'; Label = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' ve g' + [char]0x00F6 + 'revler') } 6
    }
    if ($dead.Count -gt 0) {
        $ops = New-Object System.Collections.ArrayList
        foreach ($d in ($dead | Select-Object -First 40)) { [void]$ops.Add(@{ T = 'Task'; Path = [string]$d.Path; Name = [string]$d.Name; Action = 'Disable' }) }
        $st = @(@{ Id = 'TaskDead'; Title = ('Program' + [char]0x0131 + ' silinmi' + [char]0x015F + ' g' + [char]0x00F6 + 'revleri kapat (') + [string]$ops.Count + ')'; Ops = $ops.ToArray(); Reboot = $false })
        $names = ($dead | Select-Object -First 4 | ForEach-Object { [string]$_.Name }) -join ', '
        Add-Finding 'task-dead' 'maint' 'info' (('Program' + [char]0x0131 + ' silinmi' + [char]0x015F + ' ') + [string]$dead.Count + (' zamanlanm' + [char]0x0131 + '' + [char]0x015F + ' g' + [char]0x00F6 + 'rev var')) (('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak dosyas' + [char]0x0131 + ' olmayan g' + [char]0x00F6 + 'revler hata kayd' + [char]0x0131 + ' ' + [char]0x00FC + 'retir: ') + $names) $null 1 (New-StepsFix 'Auto' 'Kapat' $st ('G' + [char]0x00F6 + 'revler silinmez, devre d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'l' + [char]0x0131 + 'r; geri al' + [char]0x0131 + 'nabilir.'))
    }
}

# ---------------- ag (derin) ----------------
function Get-WlanProfileInfo {
    # netsh ciktisi dile bagli oldugundan profiller XML olarak disa aktarilir (parola yok)
    $out = New-Object System.Collections.ArrayList
    $dir = Join-Path ([System.IO.Path]::GetTempPath()) ('mm-wlan-' + [guid]::NewGuid().ToString('N'))
    try {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        [void](& netsh.exe wlan export profile ('folder=' + $dir) 2>&1)
        foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter '*.xml' -ErrorAction SilentlyContinue)) {
            try {
                $x = New-Object System.Xml.XmlDocument
                $x.Load($f.FullName)
                $ns = New-Object System.Xml.XmlNamespaceManager($x.NameTable)
                $ns.AddNamespace('w', 'http://www.microsoft.com/networking/WLAN/profile/v1')
                $name = [string]$x.SelectSingleNode('//w:WLANProfile/w:name', $ns).InnerText
                $mode = [string]$x.SelectSingleNode('//w:WLANProfile/w:connectionMode', $ns).InnerText
                $auth = [string]$x.SelectSingleNode('//w:authEncryption/w:authentication', $ns).InnerText
                $enc = [string]$x.SelectSingleNode('//w:authEncryption/w:encryption', $ns).InnerText
                [void]$out.Add(@{ Name = $name; Mode = $mode; Auth = $auth; Enc = $enc; Open = ($auth -eq 'open' -and $enc -eq 'none') })
            } catch { }
        }
    } catch { } finally {
        try { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    }
    return , $out.ToArray()
}

function Chk_NetDeep {
    # 1) guvenlik duvari: gelen varsayilan Allow ise
    try {
        foreach ($p in @(Get-NetFirewallProfile -ErrorAction Stop)) {
            if ([string]$p.Enabled -eq 'True' -and [string]$p.DefaultInboundAction -eq 'Allow') {
                $st = @(@{ Id = 'FwIn' + [string]$p.Name; Title = ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' ') + [string]$p.Name + (': gelen ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar' + [char]0x0131 + ' varsay' + [char]0x0131 + 'lan engelle'); Ops = @(@{ T = 'FwDefault'; Profile = [string]$p.Name; Inbound = 'Block' }); Reboot = $false })
                Add-Finding ('fw-in-' + [string]$p.Name) 'sec' 'bad' (('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' ') + [string]$p.Name + (' profilinde gelen ba' + [char]0x011F + 'lant' + [char]0x0131 + 'ya izin veriyor')) (('Varsay' + [char]0x0131 + 'lan gelen eylemi "' + [char]0x0130 + 'zin ver" olan profil, a' + [char]0x00E7 + '' + [char]0x0131 + 'k dinleyen her program' + [char]0x0131 + ' a' + [char]0x011F + 'a sunar. Windows varsay' + [char]0x0131 + 'lan' + [char]0x0131 + ' "Engelle"dir.')) $null 10 (New-StepsFix 'Auto' ('Gelen ba' + [char]0x011F + 'lant' + [char]0x0131 + 'y' + [char]0x0131 + ' engelle') $st ('' + [char]0x0130 + 'zin verdi' + [char]0x011F + 'iniz programlar' + [char]0x0131 + 'n kurallar' + [char]0x0131 + ' korunur; geri al' + [char]0x0131 + 'nabilir.'))
            }
        }
    } catch { }
    # 2) Wi-Fi: acik (sifresiz) aglara kendiliginden baglanma, acik agda Ozel profil
    $wl = Get-WlanProfileInfo
    $openAuto = @($wl | Where-Object { $_.Open -eq $true -and $_.Mode -eq 'auto' })
    if ($openAuto.Count -gt 0) {
        $ops = New-Object System.Collections.ArrayList
        foreach ($w in $openAuto) { [void]$ops.Add(@{ T = 'WlanMode'; Name = [string]$w.Name; Mode = 'manual' }) }
        $st = @(@{ Id = 'WlanOpen'; Title = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'k Wi-Fi a' + [char]0x011F + 'lar' + [char]0x0131 + 'na kendili' + [char]0x011F + 'inden ba' + [char]0x011F + 'lanmay' + [char]0x0131 + ' kapat (') + [string]$openAuto.Count + ')'; Ops = $ops.ToArray(); Reboot = $false })
        $names = ($openAuto | Select-Object -First 5 | ForEach-Object { [string]$_.Name }) -join ', '
        Add-Finding 'wifi-open' 'sec' 'warn' ('Bilgisayar ' + [string]$openAuto.Count + (' ' + [char]0x015F + 'ifresiz Wi-Fi a' + [char]0x011F + '' + [char]0x0131 + 'na kendili' + [char]0x011F + 'inden ba' + [char]0x011F + 'lan' + [char]0x0131 + 'r')) (('' + [char]0x015E + 'ifresiz a' + [char]0x011F + 'larda trafi' + [char]0x011F + 'iniz herkese a' + [char]0x00E7 + '' + [char]0x0131 + 'kt' + [char]0x0131 + 'r; sahte a' + [char]0x011F + ' kurup sizi kendine ba' + [char]0x011F + 'layan sald' + [char]0x0131 + 'r' + [char]0x0131 + 'lar da bu y' + [char]0x00FC + 'zden i' + [char]0x015F + 'e yarar. A' + [char]0x011F + 'lar: ') + $names) $null 4 (New-StepsFix 'Auto' ('Kendili' + [char]0x011F + 'inden ba' + [char]0x011F + 'lanmay' + [char]0x0131 + ' kapat') $st ('A' + [char]0x011F + 'lar silinmez; istedi' + [char]0x011F + 'inizde elle ba' + [char]0x011F + 'lan' + [char]0x0131 + 'rs' + [char]0x0131 + 'n' + [char]0x0131 + 'z. Geri al' + [char]0x0131 + 'nabilir.'))
    }
    try {
        $openNames = @($wl | Where-Object { $_.Open -eq $true } | ForEach-Object { [string]$_.Name })
        foreach ($cp in @(Get-NetConnectionProfile -ErrorAction Stop)) {
            if ([string]$cp.NetworkCategory -eq 'Private' -and $openNames -contains [string]$cp.Name) {
                $st = @(@{ Id = 'NetPub' + [string]$cp.InterfaceIndex; Title = ('A' + [char]0x011F + ' profilini Genel yap: ') + [string]$cp.Name; Ops = @(@{ T = 'NetProfile'; Index = [int]$cp.InterfaceIndex; Alias = [string]$cp.Name; Category = 'Public' }); Reboot = $false })
                Add-Finding ('net-private-open-' + [string]$cp.InterfaceIndex) 'sec' 'bad' (('' + [char]0x015E + 'ifresiz a' + [char]0x011F + ' "') + [string]$cp.Name + ('" ' + [char]0x00D6 + 'zel olarak i' + [char]0x015F + 'aretli')) (('' + [char]0x00D6 + 'zel profilde bilgisayar a' + [char]0x011F + 'daki di' + [char]0x011F + 'er cihazlara g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r ve payla' + [char]0x015F + '' + [char]0x0131 + 'ma a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r. ' + [char]0x015E + 'ifresiz bir a' + [char]0x011F + ' i' + [char]0x00E7 + 'in Genel profil gerekir.')) $null 10 (New-StepsFix 'Auto' 'Genel profile al' $st ('Yaln' + [char]0x0131 + 'zca bu a' + [char]0x011F + '' + [char]0x0131 + 'n profili de' + [char]0x011F + 'i' + [char]0x015F + 'ir; geri al' + [char]0x0131 + 'nabilir.'))
            }
        }
    } catch { }
    # 3) proxy ve PAC (yonetilmeyen bilgisayarda)
    $pr = $sync.Profile
    $managed = ($null -ne $pr -and $pr.IsManaged -eq $true)
    if (-not $managed) {
        $ik = 'HKCU\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
        $pe = [int](Get-RegValue $ik 'ProxyEnable' 0)
        $ps = [string](Get-RegValue $ik 'ProxyServer' '')
        $pac = [string](Get-RegValue $ik 'AutoConfigURL' '')
        if ($pe -eq 1 -and $ps -ne '' -and $ps -notmatch '^(127\.|localhost|\[::1\])') {
