    if ($null -eq $pref) { return }
    $puaNow = -1
    try { $puaNow = [int]$pref.PUAProtection } catch { }
    if ($puaNow -eq 0) {
        $st = @(@{ Id = 'MpPua'; Title = ('' + [char]0x0130 + 'stenmeyen uygulama korumas' + [char]0x0131 + 'n' + [char]0x0131 + ' (PUA) a' + [char]0x00E7 + ''); Ops = @(@{ T = 'Mp'; Name = 'PUAProtection'; Value = 1 }); Reboot = $false })
        Add-Finding 'av-pua' 'sec' 'warn' ('' + [char]0x0130 + 'stenmeyen uygulama korumas' + [char]0x0131 + ' kapal' + [char]0x0131 + '') ('Reklam yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + ' ve paketlenmi' + [char]0x015F + ' istenmeyen programlar (PUA) engellenmiyor.') $null 4 (New-StepsFix 'Auto' ('PUA korumas' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '') $st ('Yaln' + [char]0x0131 + 'zca istenmeyen/reklam yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'mlar' + [char]0x0131 + 'n' + [char]0x0131 + ' engeller; geri al' + [char]0x0131 + 'nabilir.'))
