        if ([int]$pref.MAPSReporting -eq 0) {
            $st = @(@{ Id = 'MpMaps'; Title = ('Bulut tabanl' + [char]0x0131 + ' korumay' + [char]0x0131 + ' a' + [char]0x00E7 + ''); Ops = @(@{ T = 'Mp'; Name = 'MAPSReporting'; Value = 2 }); Reboot = $false })
            Add-Finding 'av-cloud' 'sec' 'info' ('Defender bulut tabanl' + [char]0x0131 + ' koruma kapal' + [char]0x0131 + '') ('Yeni ve tan' + [char]0x0131 + 'mlanmam' + [char]0x0131 + '' + [char]0x015F + ' tehditler bulut sorgusuyla yakalan' + [char]0x0131 + 'r. A' + [char]0x00E7 + 'arsan' + [char]0x0131 + 'z ' + [char]0x015F + '' + [char]0x00FC + 'pheli dosyalar' + [char]0x0131 + 'n ' + [char]0x00F6 + 'zeti Microsoft' + [char]0x2019 + 'a g' + [char]0x00F6 + 'nderilir; gizlilik tercihinize g' + [char]0x00F6 + 're karar verin.') $null 0 (New-StepsFix 'Click' ('Bulut korumas' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '') $st ('Dosya ' + [char]0x00F6 + 'zetleri Microsoft' + [char]0x2019 + 'a g' + [char]0x00F6 + 'nderilir; geri al' + [char]0x0131 + 'nabilir.'))
        }
    } catch { }
    try {
        if ([int]$pref.EnableControlledFolderAccess -eq 0) {
            Add-Finding 'av-cfa' 'sec' 'info' ('Kontroll' + [char]0x00FC + ' klas' + [char]0x00F6 + 'r eri' + [char]0x015F + 'imi (fidye yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + ' korumas' + [char]0x0131 + ') kapal' + [char]0x0131 + '') ('Belgeler, Resimler gibi klas' + [char]0x00F6 + 'rleri izinsiz programlar' + [char]0x0131 + 'n de' + [char]0x011F + 'i' + [char]0x015F + 'tirmesini engeller. Baz' + [char]0x0131 + ' programlar' + [char]0x0131 + ' engelleyebilece' + [char]0x011F + 'i i' + [char]0x00E7 + 'in iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') @{ Kind = 'Url'; Url = 'windowsdefender://RansomwareProtection'; Label = ('Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i' + [char]0x2019 + 'nde a' + [char]0x00E7 + '') } 0
        }
    } catch { }
