# ---------------- sistem (derin) ----------------
function Get-DirSizeCapped([string]$Dir, [int]$MaxFiles = 25000) {
    $total = 0.0; $n = 0
    if (-not (Test-Path -LiteralPath $Dir -PathType Container)) { return 0.0 }
    try {
        foreach ($f in [System.IO.Directory]::EnumerateFiles($Dir, '*', [System.IO.SearchOption]::AllDirectories)) {
            try { $total += [double](New-Object System.IO.FileInfo -ArgumentList $f).Length } catch { }
            $n++
            if ($n -ge $MaxFiles) { break }
        }
    } catch { }
    return $total
}

function Chk_SystemDeep {
    # Windows Update hizmetleri kapatilmis mi?
    $off = @()
    foreach ($n in @('wuauserv', 'UsoSvc')) { $si = Get-SvcStartInfo $n; if ($null -ne $si.Start -and $si.Start -eq 4) { $off += $n } }
    if ($off.Count -gt 0) {
        Add-Finding 'wu-svc-off' 'sec' 'bad' (('Windows Update hizmeti kapat' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ': ') + ($off -join ', ')) ('G' + [char]0x00FC + 'ncelleme hizmeti kapal' + [char]0x0131 + 'yken g' + [char]0x00FC + 'venlik yamalar' + [char]0x0131 + ' kurulmaz. Genellikle bir "h' + [char]0x0131 + 'zland' + [char]0x0131 + 'rma" arac' + [char]0x0131 + ' ya da zararl' + [char]0x0131 + ' yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm kapat' + [char]0x0131 + 'r.') $null 15 (New-RunFix 'WuSvcRestore' ('Hizmeti varsay' + [char]0x0131 + 'lana d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r') 'Auto')
    }
    # SmartScreen
    $ss = [string](Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer' 'SmartScreenEnabled' '')
    if ($ss -eq 'Off') {
        $st = @(@{ Id = 'SmartScreen'; Title = ('SmartScreen' + [char]0x2019 + 'i uyar' + [char]0x0131 + ' moduna al'); Ops = @(@{ T = 'Reg'; Path = 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer'; Name = 'SmartScreenEnabled'; Kind = 'String'; Value = 'Warn' }); Reboot = $false })
        Add-Finding 'smartscreen' 'sec' 'warn' ('SmartScreen kapal' + [char]0x0131 + '') ('' + [char]0x0130 + 'ndirilen tan' + [char]0x0131 + 'nmayan programlar ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmadan ' + [char]0x00F6 + 'nce uyar' + [char]0x0131 + ' verilmez.') $null 5 (New-StepsFix 'Auto' ('SmartScreen' + [char]0x2019 + 'i a' + [char]0x00E7 + '') $st ('Geri al' + [char]0x0131 + 'nabilir.'))
    }
    # PowerShell 2.0 motoru (surum dusurme saldirilarinda kullanilir)
    $ps2 = Get-RegValue 'HKLM\SOFTWARE\Microsoft\PowerShell\1\PowerShellEngine' 'PowerShellVersion' $null
    if ($null -ne $ps2 -and [string]$ps2 -match '^2\.') {
        Add-Finding 'ps2' 'sec' 'info' ('PowerShell 2.0 motoru y' + [char]0x00FC + 'kl' + [char]0x00FC + '') ('Eski ve kay' + [char]0x0131 + 't tutmayan bu motor, sald' + [char]0x0131 + 'rganlar' + [char]0x0131 + 'n g' + [char]0x00FC + 'venlik denetimlerini a' + [char]0x015F + 'mak i' + [char]0x00E7 + 'in kulland' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' bir yoldur. Kapatmak hi' + [char]0x00E7 + 'bir g' + [char]0x00FC + 'ncel program' + [char]0x0131 + ' etkilemez.') $null 0 (New-TweakFix @('Ps2Off') ('PowerShell 2.0' + [char]0x2019 + '' + [char]0x0131 + ' kapat'))
    }
    # oturum acma parolasi kayit defterinde acik yazili mi?
    $wl = 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
    if ([string](Get-RegValue $wl 'AutoAdminLogon' '0') -eq '1') {
        $hasPw = (Get-RegInfo $wl 'DefaultPassword').Exists
        if ($hasPw) { Add-Finding 'autologon' 'sec' 'bad' ('Oturum a' + [char]0x00E7 + 'ma parolas' + [char]0x0131 + ' kay' + [char]0x0131 + 't defterinde a' + [char]0x00E7 + '' + [char]0x0131 + 'k yaz' + [char]0x0131 + 'l' + [char]0x0131 + '') ('Otomatik oturum a' + [char]0x00E7 + 'ma i' + [char]0x00E7 + 'in parola d' + [char]0x00FC + 'z metin olarak saklan' + [char]0x0131 + 'yor; bilgisayara eri' + [char]0x015F + 'en herkes okuyabilir. Otomatik oturum a' + [char]0x00E7 + 'may' + [char]0x0131 + ' kapat' + [char]0x0131 + 'n.') @{ Kind = 'Url'; Url = 'netplwiz.exe'; Label = ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' hesaplar' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '') } 12 }
        else { Add-Finding 'autologon' 'sec' 'info' ('Otomatik oturum a' + [char]0x00E7 + 'ma a' + [char]0x00E7 + '' + [char]0x0131 + 'k') ('Bilgisayar' + [char]0x0131 + ' a' + [char]0x00E7 + 'an herkes hesab' + [char]0x0131 + 'n' + [char]0x0131 + 'za girer. Ta' + [char]0x015F + '' + [char]0x0131 + 'nabilir bilgisayarlarda kapat' + [char]0x0131 + 'n.') @{ Kind = 'Url'; Url = 'netplwiz.exe'; Label = ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' hesaplar' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '') } 0 }
    }
    # surucu sorunu olan aygitlar
    try {
        $bad = @(Get-PnpDevice -PresentOnly -ErrorAction Stop | Where-Object { [string]$_.Status -eq 'Error' -and [string]$_.Class -ne '' })
        if ($bad.Count -gt 0) {
            $names = ($bad | Select-Object -First 4 | ForEach-Object { [string]$_.FriendlyName }) -join ', '
            Add-Finding 'pnp-err' 'maint' 'warn' ([string]$bad.Count + (' ayg' + [char]0x0131 + 't hata veriyor')) (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' eksik ya da bozuk ayg' + [char]0x0131 + 'tlar: ') + $names + ('. Windows Update' + [char]0x2019 + 'ten s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri denetleyin.')) @{ Kind = 'Page'; Page = 'updates'; Label = ('G' + [char]0x00FC + 'ncellemeler') } 3
        }
    } catch { }
    # bosaltilabilir gecici dosyalar
    try {
        $sz = 0.0
        foreach ($d in @($env:TEMP, (Join-Path $env:WINDIR 'Temp'), (Join-Path $env:WINDIR 'SoftwareDistribution\Download'))) { if (-not [string]::IsNullOrEmpty($d)) { $sz += (Get-DirSizeCapped $d 20000) } }
        $mb = $sz / 1MB
        if ($mb -ge 2048) { Add-Finding 'reclaim' 'perf' 'warn' (('Silinebilir ge' + [char]0x00E7 + 'ici dosyalar: ') + (Format-Size $sz)) ('Ge' + [char]0x00E7 + 'ici ve g' + [char]0x00FC + 'ncelleme ' + [char]0x00F6 + 'nbellek dosyalar' + [char]0x0131 + ' yer kapl' + [char]0x0131 + 'yor. G' + [char]0x00FC + 'venle temizlenir.') @{ Kind = 'Run'; Key = 'Maint'; Label = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm') } 3 (New-RunFix 'Maint' 'Temizle') }
        elseif ($mb -ge 500) { Add-Finding 'reclaim' 'perf' 'info' (('Silinebilir ge' + [char]0x00E7 + 'ici dosyalar: ') + (Format-Size $sz)) '' @{ Kind = 'Run'; Key = 'Maint'; Label = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm') } 0 (New-RunFix 'Maint' 'Temizle') }
    } catch { }
}

# ---------------- uyarlama ve sapma ----------------
function Chk_Adaptive {
    $pr = $sync.Profile
    $tier = Get-CurrentTier
    $lbl = [string]$tier.Label
    $why = (@($tier.Reasons) -join '; ')
    $ids = Get-AdaptiveIds 'opt' $pr $tier
    $pend = New-Object System.Collections.ArrayList
    foreach ($id in $ids) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -eq $c -or [int]$c.Level -gt 2) { continue }
        $p = Get-TweakPending $c
        if ($p -gt 0) { [void]$pend.Add([string]$c.Title) }
    }
    if ($tier.Tier -eq 'High') { Add-Finding 'tier' 'perf' 'ok' (('Donan' + [char]0x0131 + 'm s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + ': ') + $lbl) ($why + ('. H' + [char]0x0131 + 'z i' + [char]0x00E7 + 'in ' + [char]0x00F6 + 'zellik kapatmaya gerek yok.')) }
    elseif ($tier.Tier -eq 'Low') { Add-Finding 'tier' 'perf' 'info' (('Donan' + [char]0x0131 + 'm s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + ': ') + $lbl) ($why + ('. Optimizasyon ayarlar' + [char]0x0131 + ' bu bilgisayarda fark yarat' + [char]0x0131 + 'r.')) }
    else { Add-Finding 'tier' 'perf' 'info' (('Donan' + [char]0x0131 + 'm s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + ': ') + $lbl) $why }
    if ($pend.Count -gt 0) {
        $fx = New-FixInfo 'Auto' 'Adaptive' ('' + [char]0x00D6 + 'nerilenleri uygula') ('Yaln' + [char]0x0131 + 'zca bu donan' + [char]0x0131 + 'm i' + [char]0x00E7 + 'in anlaml' + [char]0x0131 + ', geri al' + [char]0x0131 + 'nabilir ayarlar.')
        $st = 'info'; $w = 0
        if ($tier.Tier -eq 'Low' -and $pend.Count -ge 4) { $st = 'warn'; $w = 4 }
        Add-Finding 'adapt' 'perf' $st (('Bu bilgisayar i' + [char]0x00E7 + 'in ') + [string]$pend.Count + (' ayar uygulanmam' + [char]0x0131 + '' + [char]0x015F + '')) ((@($pend | Select-Object -First 6) -join ', ')) @{ Kind = 'Page'; Page = 'optimize'; Label = ('Optimizasyon sayfas' + [char]0x0131 + '') } $w $fx
    }
}

function Chk_Drift {
    $d = Get-DriftedIds
    if ($d.Count -gt 0) {
        $names = New-Object System.Collections.ArrayList
        foreach ($id in $d) { $c = Get-CatalogItem ([string]$id); if ($null -ne $c) { [void]$names.Add([string]$c.Title) } }
        $fx = New-FixInfo 'Auto' 'Drift' ('Ayarlar' + [char]0x0131 + ' yeniden uygula') ('Daha ' + [char]0x00F6 + 'nce siz uygulad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z ayarlar; geri al' + [char]0x0131 + 'nabilir.')
        Add-Finding 'drift' 'maint' 'warn' (('Uygulad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z ') + [string]$d.Count + (' ayar Windows taraf' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'nm' + [char]0x0131 + '' + [char]0x015F + '')) ((@($names | Select-Object -First 5) -join ', ') + ('. B' + [char]0x00FC + 'y' + [char]0x00FC + 'k g' + [char]0x00FC + 'ncellemeler baz' + [char]0x0131 + ' ayarlar' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlar.')) @{ Kind = 'Page'; Page = 'optimize'; Label = ('Optimizasyon sayfas' + [char]0x0131 + '') } 3 $fx
    }
}

# ---------------- gizlilik: su an kullanimda olan kamera/mikrofon ----------------
function Chk_PrivacyNow {
    $rows = Get-PrivacyUsage
    $live = @($rows | Where-Object { $_.InUse -eq $true -and ($_.Cap -eq 'webcam' -or $_.Cap -eq 'microphone') })
    if ($live.Count -gt 0) {
