    google     = @{ N = 'Google'; Tpl = 'https://dns.google/dns-query'; Ips = @('8.8.8.8', '8.8.4.4', '2001:4860:4860::8888', '2001:4860:4860::8844') }
    quad9      = @{ N = 'Quad9'; Tpl = 'https://dns.quad9.net/dns-query'; Ips = @('9.9.9.9', '149.112.112.112', '2620:fe::fe', '2620:fe::9') }
    adguard    = @{ N = 'AdGuard DNS'; Tpl = 'https://dns.adguard-dns.com/dns-query'; Ips = @('94.140.14.14', '94.140.15.15', '2a10:50c0::ad1:ff', '2a10:50c0::ad2:ff') }
