function Get-OsBuildNumber { return [int][System.Environment]::OSVersion.Version.Build }

function Test-DohSupported {
    if ((Get-OsBuildNumber) -lt 22000) { return $false }
    return ($null -ne (Get-Command -Name 'Add-DnsClientDohServerAddress' -ErrorAction Ignore))
}

function Get-DohExisting {
    $ex = @{}
    try { foreach ($e in @(Get-DnsClientDohServerAddress -ErrorAction Stop)) { $ex[[string]$e.ServerAddress] = $e } } catch { }
    return $ex
}

function Get-DohState {
    $r = @{ Supported = (Test-DohSupported); Active = $false; Servers = @(); Provider = '' }
    if (-not $r.Supported) { return $r }
    $ex = Get-DohExisting
    $cur = New-Object System.Collections.ArrayList
    try {
        foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { [string]$_.Status -eq 'Up' })) {
            foreach ($e in @(Get-DnsClientServerAddress -InterfaceIndex ([int]$a.ifIndex) -AddressFamily IPv4 -ErrorAction Stop)) {
                foreach ($s in @($e.ServerAddresses)) { if (-not $cur.Contains([string]$s)) { [void]$cur.Add([string]$s) } }
            }
        }
    } catch { }
    $cov = 0
    foreach ($s in $cur) { if ($ex.ContainsKey($s) -and $ex[$s].AutoUpgrade -eq $true) { $cov++ } }
    $r.Servers = $cur.ToArray()
    $r.Active = ($cur.Count -gt 0 -and $cov -eq $cur.Count)
    if ($r.Active) {
        foreach ($k in $script:DohProviders.Keys) { if (@($script:DohProviders[$k].Ips) -contains [string]$cur[0]) { $r.Provider = [string]$script:DohProviders[$k].N } }
    }
    return $r
}

# Op: @{ T='DohReg'; Provider='cloudflare'|'google'|'quad9'|'adguard'|'off' }
function Invoke-DohRegOp($Op) {
    $id = [string]$Op.Provider
    if (-not (Test-DohSupported)) { Add-Skip ('' + [char]0x015E + 'ifreli DNS (DoH) yerle' + [char]0x015F + 'ik olarak yaln' + [char]0x0131 + 'zca Windows 11 ile desteklenir; taray' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'zdaki g' + [char]0x00FC + 'venli DNS ayar' + [char]0x0131 + 'n' + [char]0x0131 + ' kullan' + [char]0x0131 + 'n.'); return }
    $ex = Get-DohExisting
    $changed = New-Object System.Collections.ArrayList
    $added = New-Object System.Collections.ArrayList
    if ($id -eq 'off') {
        $todo = New-Object System.Collections.ArrayList
        foreach ($k in $script:DohProviders.Keys) {
            foreach ($ip in @($script:DohProviders[$k].Ips)) { if ($ex.ContainsKey($ip) -and $ex[$ip].AutoUpgrade -eq $true) { [void]$todo.Add($ip) } }
        }
        if ($todo.Count -eq 0) { Add-Skip ('Otomatik ' + [char]0x015F + 'ifreli DNS zaten kapal' + [char]0x0131 + '.'); return }
        if ($script:Preview) { Add-Plan (('' + [char]0x015E + 'ifreli DNS kapat' + [char]0x0131 + 'lacak (') + [string]$todo.Count + (' kay' + [char]0x0131 + 't).')); return }
        foreach ($ip in $todo) {
            $e = $ex[$ip]
            [void]$changed.Add(@{ Ip = $ip; Tpl = [string]$e.DohTemplate; Auto = [bool]$e.AutoUpgrade; Fallback = [bool]$e.AllowFallbackToUdp })
        }
        Add-Journal @{ T = 'DohReg'; Added = @(); Changed = $changed.ToArray() }
        foreach ($c in $changed) { Set-DnsClientDohServerAddress -ServerAddress ([string]$c.Ip) -DohTemplate ([string]$c.Tpl) -AutoUpgrade $false -ErrorAction Stop }
        Add-Done ('Otomatik ' + [char]0x015F + 'ifreli DNS (DoH) kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '.')
        return
    }
    if (-not $script:DohProviders.ContainsKey($id)) { Add-Skip (('Bu sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + ' i' + [char]0x00E7 + 'in DoH ' + [char]0x015F + 'ablonu yok: ') + $id); return }
    $prov = $script:DohProviders[$id]
    $need = New-Object System.Collections.ArrayList
    foreach ($ip in @($prov.Ips)) {
        if ($ex.ContainsKey($ip)) {
            $e = $ex[$ip]
            if ($e.AutoUpgrade -eq $true -and [string]$e.DohTemplate -eq [string]$prov.Tpl) { continue }
            [void]$changed.Add(@{ Ip = $ip; Tpl = [string]$e.DohTemplate; Auto = [bool]$e.AutoUpgrade; Fallback = [bool]$e.AllowFallbackToUdp })
        } else { [void]$added.Add($ip) }
        [void]$need.Add($ip)
    }
    if ($need.Count -eq 0) { Add-Skip (('' + [char]0x015E + 'ifreli DNS zaten kay' + [char]0x0131 + 'tl' + [char]0x0131 + ': ') + [string]$prov.N); return }
    if ($script:Preview) { Add-Plan (('' + [char]0x015E + 'ifreli DNS (DoH) kaydedilecek: ') + [string]$prov.N + ' (' + [string]$prov.Tpl + ')'); return }
    Add-Journal @{ T = 'DohReg'; Added = $added.ToArray(); Changed = $changed.ToArray() }
    foreach ($ip in $need) {
        if ($added.Contains($ip)) { Add-DnsClientDohServerAddress -ServerAddress $ip -DohTemplate ([string]$prov.Tpl) -AutoUpgrade $true -AllowFallbackToUdp $true -ErrorAction Stop | Out-Null }
        else { Set-DnsClientDohServerAddress -ServerAddress $ip -DohTemplate ([string]$prov.Tpl) -AutoUpgrade $true -AllowFallbackToUdp $true -ErrorAction Stop | Out-Null }
    }
    Add-Done (('' + [char]0x015E + 'ifreli DNS (DoH) etkin: ') + [string]$prov.N + ('. Sorgular HTTPS ile gider; sunucu yan' + [char]0x0131 + 't vermezse d' + [char]0x00FC + 'z DNS yede' + [char]0x011F + 'i kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'r.'))
}

function Undo-DohRegItem($It) {
    foreach ($ip in @($It.Added)) { try { Remove-DnsClientDohServerAddress -ServerAddress ([string]$ip) -ErrorAction Stop } catch { } }
    foreach ($c in @($It.Changed)) {
        try { Set-DnsClientDohServerAddress -ServerAddress ([string]$c.Ip) -DohTemplate ([string]$c.Tpl) -AutoUpgrade ([bool]$c.Auto) -AllowFallbackToUdp ([bool]$c.Fallback) -ErrorAction Stop } catch { }
    }
    Add-Done ('' + [char]0x015E + 'ifreli DNS kay' + [char]0x0131 + 'tlar' + [char]0x0131 + ' eski h' + [char]0x00E2 + 'line d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '.')
}
$script:MoreOps['DohReg'] = 'Invoke-DohRegOp'
$script:MoreUndo['DohReg'] = 'Undo-DohRegItem'

# DoH + DNS sunuculari icin plan adimlari. Provider: cloudflare|google|quad9|adguard|off
function New-DohSteps([string]$Provider, $Adapters) {
    $steps = New-Object System.Collections.ArrayList
    if ($Provider -eq 'off') {
        [void]$steps.Add(@{ Id = 'DohOff'; Title = ('Otomatik ' + [char]0x015F + 'ifreli DNS kapat'); Ops = @(@{ T = 'DohReg'; Provider = 'off' }); Reboot = $false })
        return $steps.ToArray()
    }
    if (-not $script:DohProviders.ContainsKey($Provider)) { return @() }
    [void]$steps.Add(@{ Id = 'DohOn'; Title = (('' + [char]0x015E + 'ifreli DNS kayd' + [char]0x0131 + ': ') + [string]$script:DohProviders[$Provider].N); Ops = @(@{ T = 'DohReg'; Provider = $Provider }); Reboot = $false })
    $v4 = @($script:DohProviders[$Provider].Ips | Where-Object { (Get-VpnIpKind ([string]$_)) -eq 4 })
    $dns = New-DnsSteps $v4 $Adapters
    foreach ($s in @($dns)) { [void]$steps.Add($s) }
    return $steps.ToArray()
}

# Akilli cok-agli ad cozumleme: VPN varken DNS sorgularinin fiziksel bagdastiriciya da gitmesini onler
function New-SmartNameStep {
    return @{ Id = 'SmartNameOff'; Title = ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' ' + [char]0x00E7 + 'ok-a' + [char]0x011F + 'l' + [char]0x0131 + ' ad ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mlemeyi kapat'); Ops = @(@{ T = 'Reg'; Path = 'HKLM\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient'; Name = 'DisableSmartNameResolution'; Kind = 'DWord'; Value = 1 }); Reboot = $false }
}

# ---------------- sizinti denetimi ----------------
function Get-ShortHash([string]$S) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $b = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($S))
        return ((($b | Select-Object -First 8) | ForEach-Object { $_.ToString('x2') }) -join '')
    } finally { $sha.Dispose() }
}

function ConvertFrom-CfTrace([string]$Text) {
    $h = @{}
    foreach ($line in ($Text -split "`n")) {
        $i = $line.IndexOf('=')
        if ($i -lt 1) { continue }
        $h[$line.Substring(0, $i).Trim().ToLowerInvariant()] = $line.Substring($i + 1).Trim()
    }
    $r = @{ Ok = $false; Ip = ''; Loc = ''; Warp = ''; Colo = '' }
    if ($h.ContainsKey('ip') -and (Get-VpnIpKind ([string]$h['ip'])) -ne 0) { $r.Ip = [string]$h['ip']; $r.Ok = $true }
    if ($h.ContainsKey('loc') -and [string]$h['loc'] -cmatch '^[A-Za-z]{2}$') { $r.Loc = ([string]$h['loc']).ToUpperInvariant() }
    if ($h.ContainsKey('warp') -and [string]$h['warp'] -match '^(on|off|plus)$') { $r.Warp = [string]$h['warp'] }
    if ($h.ContainsKey('colo') -and [string]$h['colo'] -cmatch '^[A-Za-z]{3,4}$') { $r.Colo = [string]$h['colo'] }
    return $r
}

function Invoke-VpnHttp([string]$Url, [int]$TimeoutMs) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $req = [System.Net.HttpWebRequest]::Create($Url)
    $req.Timeout = $TimeoutMs
    $req.ReadWriteTimeout = $TimeoutMs
    $req.UserAgent = 'Multimizer'
    $resp = $req.GetResponse()
    try {
        $st = $resp.GetResponseStream()
        $buf = New-Object byte[] 4096
        $n = $st.Read($buf, 0, 4096)
        return [System.Text.Encoding]::ASCII.GetString($buf, 0, $n)
    } finally { try { $resp.Close() } catch { } }
}

function Test-HasGlobalIpv6 {
    try {
        foreach ($a in @(Get-NetIPAddress -AddressFamily IPv6 -ErrorAction Stop)) {
            $t = [string]$a.IPAddress
            if ($t -match '^[23][0-9a-fA-F]{3}:') { return $true }
        }
    } catch { }
    return $false
}

# VPN bagdastiricilari disindaki etkin bagdastiricilarda tanimli DNS sunuculari
function Get-PhysicalDnsServers($VpnAliases) {
    $out = New-Object System.Collections.ArrayList
    $skip = @{}
    foreach ($v in @($VpnAliases)) { $skip[([string]$v).ToLowerInvariant()] = $true }
    try {
        foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { [string]$_.Status -eq 'Up' })) {
            if ($skip.ContainsKey(([string]$a.Name).ToLowerInvariant())) { continue }
            foreach ($e in @(Get-DnsClientServerAddress -InterfaceIndex ([int]$a.ifIndex) -ErrorAction Stop)) {
                foreach ($s in @($e.ServerAddresses)) { $t = [string]$s; if (-not $t.StartsWith('fe80') -and -not $out.Contains($t)) { [void]$out.Add($t) } }
            }
        }
    } catch { }
    return $out.ToArray()
}

# Sizinti raporu (saf islev). Satir: @{ Status (ok|info|warn|bad); Title; Detail }
function New-LeakReport($Trace4, [bool]$VpnActive, [string]$BaseHash, $Trace6, $PhysDns, [bool]$KsOn) {
    $rows = New-Object System.Collections.ArrayList
    $loc = ''
    if ([string]$Trace4.Loc -ne '') { $loc = ' (' + [string]$Trace4.Loc + ')' }
    [void]$rows.Add(@{ Status = 'info'; Title = (('' + [char]0x0130 + 'nternette g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen adresiniz: ') + [string]$Trace4.Ip + $loc); Detail = ('Web siteleri sizi bu adresle g' + [char]0x00F6 + 'r' + [char]0x00FC + 'r.') })
    if ([string]$Trace4.Warp -eq 'on' -or [string]$Trace4.Warp -eq 'plus') {
        [void]$rows.Add(@{ Status = 'info'; Title = ('Cloudflare WARP etkin g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor'); Detail = ('Trafik Cloudflare a' + [char]0x011F + '' + [char]0x0131 + ' ' + [char]0x00FC + 'zerinden ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'yor.') })
    }
    $cur = Get-ShortHash ([string]$Trace4.Ip)
    if ($VpnActive) {
        if ($BaseHash -eq '') {
            [void]$rows.Add(@{ Status = 'info'; Title = ('Kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'rma i' + [char]0x00E7 + 'in VPN kapal' + [char]0x0131 + 'yken ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm yok'); Detail = ('VPN ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + 'n' + [char]0x0131 + ' bir kez kapat' + [char]0x0131 + 'p bu testi ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n; sonra adresler kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') })
        } elseif ($cur -eq $BaseHash) {
            [void]$rows.Add(@{ Status = 'bad'; Title = ('Adresiniz VPN kapal' + [char]0x0131 + 'yken ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lenle ayn' + [char]0x0131 + ''); Detail = ('Trafik t' + [char]0x00FC + 'nelden ' + [char]0x00E7 + '' + [char]0x0131 + 'km' + [char]0x0131 + 'yor olabilir. Yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rmadaki AllowedIPs de' + [char]0x011F + 'erini (0.0.0.0/0, ::/0) ve istemci ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + ' denetleyin.') })
        } else {
            [void]$rows.Add(@{ Status = 'ok'; Title = ('Adresiniz VPN kapal' + [char]0x0131 + 'yken ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lenden farkl' + [char]0x0131 + ''); Detail = ('T' + [char]0x00FC + 'nel trafik ta' + [char]0x015F + '' + [char]0x0131 + 'yor.') })
        }
    } else {
        [void]$rows.Add(@{ Status = 'info'; Title = ('VPN etkin de' + [char]0x011F + 'il'); Detail = ('Bu adres internet sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'za aittir; ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm, VPN kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'rmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in kaydedildi.') })
    }
    if ($VpnActive -and $null -ne $Trace6) {
        if ($Trace6.Ok) { [void]$rows.Add(@{ Status = 'bad'; Title = (('IPv6 trafi' + [char]0x011F + 'i t' + [char]0x00FC + 'nel d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'ndan ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'yor: ') + [string]$Trace6.Ip); Detail = ('Yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rmaya ::/0 eklemek ya da kill-switch a' + [char]0x00E7 + 'mak bu s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + 'y' + [char]0x0131 + ' kapat' + [char]0x0131 + 'r.') }) }
        else { [void]$rows.Add(@{ Status = 'ok'; Title = ('IPv6 s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + 's' + [char]0x0131 + ' bulunmad' + [char]0x0131 + ''); Detail = ('IPv6 ' + [char]0x00FC + 'zerinden d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + ' ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' denendi, ula' + [char]0x015F + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') }) }
    }
    $pd = @($PhysDns)
    if ($VpnActive) {
        if ($pd.Count -gt 0 -and -not $KsOn) {
            [void]$rows.Add(@{ Status = 'warn'; Title = (('T' + [char]0x00FC + 'nel d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'ndaki ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'larda DNS sunucusu tan' + [char]0x0131 + 'ml' + [char]0x0131 + ': ') + ($pd -join ', ')); Detail = ('Windows bu sunucular' + [char]0x0131 + ' da sorgulayabilir (ak' + [char]0x0131 + 'll' + [char]0x0131 + ' ' + [char]0x00E7 + 'ok-a' + [char]0x011F + 'l' + [char]0x0131 + ' ad ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mleme). Kill-switch bunlar' + [char]0x0131 + ' engeller; ya da bu ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i kapat' + [char]0x0131 + 'n.') })
        } elseif ($pd.Count -gt 0) {
            [void]$rows.Add(@{ Status = 'ok'; Title = ('T' + [char]0x00FC + 'nel d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' DNS sorgular' + [char]0x0131 + ' kill-switch ile engelli'); Detail = (('Tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' sunucular: ') + ($pd -join ', ')) })
        } else {
            [void]$rows.Add(@{ Status = 'ok'; Title = ('T' + [char]0x00FC + 'nel d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' DNS sunucusu yok'); Detail = '' })
        }
    }
    return $rows.ToArray()
}

# Kullanici tetikler. En cok iki HTTPS istegi: www.cloudflare.com (IPv4/varsayilan) ve gerekirse IPv6 adresi.
function Job_LeakTest($P) {
    Set-JobProgress 0 4 ('S' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' denetimi')
    Write-WhLog ('S' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' denetimi: yaln' + [char]0x0131 + 'zca Cloudflare izleme sayfas' + [char]0x0131 + 'na tek istek gider; ki' + [char]0x015F + 'isel veri g' + [char]0x00F6 + 'nderilmez.') 'INFO'
    $act = Get-VpnActive
    $vpn = [bool]$act.Any
    Step-JobProgress
    $t4 = $null
    try { $t4 = ConvertFrom-CfTrace (Invoke-VpnHttp 'https://www.cloudflare.com/cdn-cgi/trace' 9000) }
    catch { Write-WhLog (('S' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' denetimi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false; Why = $_.Exception.Message } }
    if (-not $t4.Ok) { return @{ Ok = $false; Why = ('Yan' + [char]0x0131 + 't ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mlenemedi.') } }
    Step-JobProgress
    $S = Get-Settings
    $base = [string]$S.VpnBaseHash
    $t6 = $null
    if ($vpn -and (Test-HasGlobalIpv6)) {
        try { $t6 = ConvertFrom-CfTrace (Invoke-VpnHttp 'https://[2606:4700:4700::1111]/cdn-cgi/trace' 7000) } catch { $t6 = @{ Ok = $false } }
    }
    Step-JobProgress
    $aliases = @()
    foreach ($w in @($act.Wg)) { $aliases += [string]$w.Name }
    foreach ($w in @($act.Ike)) { $aliases += [string]$w.Name }
    foreach ($w in @($act.Other)) { $aliases += [string]$w.Name }
    $phys = Get-PhysicalDnsServers $aliases
    $ks = Get-KsState
    $rows = New-LeakReport $t4 $vpn $base $t6 $phys ([bool]($ks.Effective))
    if (-not $vpn) {
        $S = Get-Settings
        $S.VpnBaseHash = (Get-ShortHash ([string]$t4.Ip))
        Save-Settings $S
    }
    Step-JobProgress
    foreach ($r in $rows) { Write-WhLog ([string]$r.Title) 'INFO' }
    return @{ Ok = $true; Rows = $rows; Ip = [string]$t4.Ip; Loc = [string]$t4.Loc; Vpn = $vpn; At = (Get-Date).ToString('s') }
}

# ---------------- durum ve eylem isleri ----------------
function Job_KsContext($P) { return (Get-KsContext) }

function Job_VpnStatus($P) {
    Set-JobProgress 0 4 'VPN durumu okunuyor'
    $wgx = Get-WgExe
    $tun = @(Get-WgTunnels)
    Step-JobProgress
    $prof = @(Get-WinVpnProfiles)
    Step-JobProgress
    $act = Get-VpnActive
    $ks = Get-KsState
    $doh = Get-DohState
    Step-JobProgress
    $cl = @(Get-VpnClients)
    $S = Get-Settings
    Step-JobProgress
    return @{ WgExe = $wgx; Tunnels = $tun; Profiles = $prof; Active = $act; Ks = $ks; Doh = $doh; Clients = $cl; AllowLan = ($S.KsAllowLan -ne $false); BaseHash = [string]$S.VpnBaseHash; At = (Get-Date).ToString('s') }
}

# P: Op (WgImport|WgUp|WgDown|WgDel|IkeAdd|IkeUp|IkeDown|IkeDel|IkeStrong), Path, Name, Server, AllUser
function Job_VpnAction($P) {
    $op = [string]$P.Op
    $name = [string]$P.Name
    try {
        switch ($op) {
            'WgImport' {
                $r = Import-WgConfFile ([string]$P.Path)
                Write-WhLog (('WireGuard yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'e aktar' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + [string]$r.Summary.Endpoint + (' (t' + [char]0x00FC + 'nel ad' + [char]0x0131 + ': ') + [string]$r.Name + ')') 'OK'
                foreach ($w in @($r.Summary.Warnings)) { Write-WhLog (('Uyar' + [char]0x0131 + ': ') + [string]$w) 'WARN' }
                return @{ Ok = $true; Msg = (('T' + [char]0x00FC + 'nel eklendi: ') + [string]$r.Name); Name = [string]$r.Name; Warnings = @($r.Summary.Warnings) }
            }
            'WgUp' {
                if ((Get-KsState).Effective) { throw ('Kill-switch a' + [char]0x00E7 + '' + [char]0x0131 + 'kken t' + [char]0x00FC + 'nel de' + [char]0x011F + 'i' + [char]0x015F + 'tirilemez; ' + [char]0x00F6 + 'nce kill-switch kapat' + [char]0x0131 + 'n.') }
                $did = Start-WgTunnel $name
                if ($did) { Write-WhLog (('T' + [char]0x00FC + 'nel ba' + [char]0x011F + 'land' + [char]0x0131 + ': ') + $name) 'OK'; return @{ Ok = $true; Msg = (('Ba' + [char]0x011F + 'land' + [char]0x0131 + ': ') + $name) } }
                return @{ Ok = $true; Msg = (('Zaten ba' + [char]0x011F + 'l' + [char]0x0131 + ': ') + $name) }
            }
            'WgDown' {
                $did = Stop-WgTunnel $name
                if ($did) { Write-WhLog (('T' + [char]0x00FC + 'nel kesildi: ') + $name) 'OK' }
                return @{ Ok = $true; Msg = (('Ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kesildi: ') + $name) }
            }
            'WgDel' {
                Remove-WgConfig $name
                Write-WhLog (('T' + [char]0x00FC + 'nel yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rmas' + [char]0x0131 + ' silindi: ') + $name) 'OK'
                return @{ Ok = $true; Msg = ('Silindi: ' + $name) }
            }
            'IkeAdd' {
                Add-WinVpnProfile $name ([string]$P.Server)
                Write-WhLog ('Windows VPN profili eklendi: ' + $name + ' (IKEv2, parola kaydedilmez)') 'OK'
                return @{ Ok = $true; Msg = ('Profil eklendi: ' + $name) }
            }
            'IkeUp' {
                if ((Get-KsState).Effective) { throw ('Kill-switch a' + [char]0x00E7 + '' + [char]0x0131 + 'kken yeni ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kurulamaz; ' + [char]0x00F6 + 'nce kill-switch kapat' + [char]0x0131 + 'n.') }
                Connect-WinVpn $name
                return @{ Ok = $true; Msg = ('Windows ba' + [char]0x011F + 'lant' + [char]0x0131 + ' penceresi a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '; ba' + [char]0x011F + 'land' + [char]0x0131 + 'ktan sonra Yenile d' + [char]0x00FC + '' + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n.') }
            }
            'IkeDown' {
                Disconnect-WinVpn $name
                Write-WhLog ('Windows VPN kesildi: ' + $name) 'OK'
                return @{ Ok = $true; Msg = (('Ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kesildi: ') + $name) }
            }
            'IkeDel' {
                Remove-WinVpnProfile $name ([bool]$P.AllUser)
                Write-WhLog ('Windows VPN profili silindi: ' + $name) 'OK'
                return @{ Ok = $true; Msg = ('Silindi: ' + $name) }
            }
            'IkeStrong' {
                Set-WinVpnStrong $name
                Write-WhLog (('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' ' + [char]0x015F + 'ifre paketi uyguland' + [char]0x0131 + ': ') + $name + ' (sunucu GCM-AES, Group14 desteklemelidir)') 'OK'
                return @{ Ok = $true; Msg = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' ' + [char]0x015F + 'ifre paketi uyguland' + [char]0x0131 + '; sunucu desteklemiyorsa ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kurulamaz.') }
            }
            default { throw (('Bilinmeyen VPN i' + [char]0x015F + 'lemi: ') + $op) }
        }
    } catch {
        Write-WhLog (('VPN i' + [char]0x015F + 'lemi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (') + $op + '): ' + $_.Exception.Message) 'ERR'
        return @{ Ok = $false; Msg = [string]$_.Exception.Message }
    }
}

# ---------------- saglik denetimi ----------------
function Chk_Vpn {
    $ks = Get-KsState
    $act = Get-VpnActive
    if ($ks.On -and -not $act.Any) {
        Add-Finding 'vpn-ks-orphan' 'sec' 'bad' ('Kill-switch a' + [char]0x00E7 + '' + [char]0x0131 + 'k ama etkin VPN ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' yok') ('Giden trafik engellendi' + [char]0x011F + 'i i' + [char]0x00E7 + 'in internet eri' + [char]0x015F + 'imi kesik olabilir. Kill-switch kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'nca ba' + [char]0x011F + 'lant' + [char]0x0131 + ' normale d' + [char]0x00F6 + 'ner.') $null 12 (New-RunFix 'KsOff' 'Kill-switch kapat' 'Click')
    } elseif ($ks.On -and $ks.Rules -gt 0 -and @($ks.BlockProfiles).Count -eq 0) {
        Add-Finding 'vpn-ks-partial' 'sec' 'warn' ('Kill-switch kurallar' + [char]0x0131 + ' var ama giden trafik varsay' + [char]0x0131 + 'lan' + [char]0x0131 + ' Engelle de' + [char]0x011F + 'il') ('Kurallar' + [char]0x0131 + 'n etkisi yok. Kill-switch kapat' + [char]0x0131 + 'p gerekirse yeniden a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') $null 5 (New-RunFix 'KsOff' 'Kill-switch kapat' 'Click')
    }
    try {
        $pub = @(Get-NetConnectionProfile -ErrorAction Stop | Where-Object { [string]$_.NetworkCategory -eq 'Public' -and ([string]$_.IPv4Connectivity -eq 'Internet' -or [string]$_.IPv6Connectivity -eq 'Internet') })
        if ($pub.Count -gt 0 -and -not $act.Any) {
            Add-Finding 'vpn-public-novpn' 'sec' 'info' (('Genel a' + [char]0x011F + 'das' + [char]0x0131 + 'n' + [char]0x0131 + 'z ve VPN kullanm' + [char]0x0131 + 'yorsunuz: ') + [string]$pub[0].Name) ('Kafe, otel ve havaliman' + [char]0x0131 + ' gibi ortak a' + [char]0x011F + 'larda trafik a' + [char]0x011F + ' sahibinin ve di' + [char]0x011F + 'er kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lar' + [char]0x0131 + 'n eri' + [char]0x015F + 'imine a' + [char]0x00E7 + '' + [char]0x0131 + 'kt' + [char]0x0131 + 'r. HTTPS ' + [char]0x00E7 + 'o' + [char]0x011F + 'u i' + [char]0x00E7 + 'eri' + [char]0x011F + 'i korur ama ba' + [char]0x011F + 'land' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z siteler g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r; VPN bu g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'ya ta' + [char]0x015F + '' + [char]0x0131 + 'r.') @{ Kind = 'Page'; Page = 'network'; Sub = 'vpn'; Label = ('VPN sayfas' + [char]0x0131 + '') } 0
        }
    } catch { }
    $doh = Get-DohState
    if ($doh.Supported -and -not $doh.Active) {
        Add-Finding 'vpn-doh-off' 'sec' 'info' ('DNS sorgular' + [char]0x0131 + ' ' + [char]0x015F + 'ifresiz gidiyor') ('Ad ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mleme sorgular' + [char]0x0131 + ' (hangi siteye girdi' + [char]0x011F + 'iniz) a' + [char]0x011F + 'daki herkes taraf' + [char]0x0131 + 'ndan okunabilir. Windows 11, DNS sorgular' + [char]0x0131 + 'n' + [char]0x0131 + ' HTTPS ile g' + [char]0x00F6 + 'nderebilir.') @{ Kind = 'Page'; Page = 'network'; Sub = 'vpn'; Label = ('' + [char]0x015E + 'ifreli DNS a' + [char]0x00E7 + '') } 0
    }
}

# ---------------- Cekirdek ekleri ----------------
# ==================================================================
#  CEKIRDEK EKLERI: internet istegi denetimi, PhotoRec arama, eski kayit temizligi, Windows 11 uyumlulugu
#  Bu dosya arka plan islerinde de yuklenir; arayuze bagimli kod icermez.
# ==================================================================

# ---------------- internet istegi denetimi ----------------
# Uygulama kendiliginden hicbir adrese baglanmaz. Asagidaki ozellikler yalnizca siz baslatinca baglanir;
# Ayarlar > Internet istekleri bolumunden her biri kapatilabilir (kapaliysa is hic baslamaz).
$script:NetFeatures = [ordered]@{
    speed  = @{ T = ('H' + [char]0x0131 + 'z testi'); D = ('speed.cloudflare.com ile gecikme ve indirme h' + [char]0x0131 + 'z' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + 'er. Ki' + [char]0x015F + 'isel veri g' + [char]0x00F6 + 'ndermez.'); Jobs = @('Job_SpeedTest') }
    leak   = @{ T = ('VPN s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' s' + [char]0x0131 + 'namas' + [char]0x0131 + ''); D = ('cloudflare.com/cdn-cgi/trace adresine tek bir HTTPS iste' + [char]0x011F + 'i g' + [char]0x00F6 + 'nderir (g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen IP adresinizi okumak i' + [char]0x00E7 + 'in).'); Jobs = @('Job_LeakTest') }
    winget = @{ T = ('Program g' + [char]0x00FC + 'ncelleme ve kurma (winget)'); D = ('Windows' + [char]0x2019 + 'un kendi winget arac' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'r; paket listesi Microsoft' + [char]0x2019 + 'un winget kayna' + [char]0x011F + '' + [char]0x0131 + 'ndan gelir. ' + [char]0x0130 + 'ndirilen paketlerin ' + [char]0x00F6 + 'zeti winget taraf' + [char]0x0131 + 'ndan do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r.'); Jobs = @('Job_WingetCheck', 'Job_WingetUpgrade', 'Job_WingetInstall', 'Job_WingetPin', 'Job_WingetPinList') }
    wu     = @{ T = 'Windows Update arama ve kurma'; D = ('Windows' + [char]0x2019 + 'un kendi g' + [char]0x00FC + 'ncelleme hizmetiyle konu' + [char]0x015F + 'ur; bu uygulama arac' + [char]0x0131 + ' bir sunucu kullanmaz.'); Jobs = @('Job_WuSearch', 'Job_WuInstall') }
    dns    = @{ T = ('DNS h' + [char]0x0131 + 'z kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'rmas' + [char]0x0131 + ''); D = ('Se' + [char]0x00E7 + 'ili DNS sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'lar' + [char]0x0131 + 'na birka' + [char]0x00E7 + ' alan ad' + [char]0x0131 + ' sorgusu g' + [char]0x00F6 + 'nderir.'); Jobs = @('Job_DnsBench') }
    ping   = @{ T = 'Ping ve yol izleme'; D = ('Yaln' + [char]0x0131 + 'zca sizin yazd' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z adrese istek g' + [char]0x00F6 + 'nderir.'); Jobs = @('Job_Ping') }
}

function Get-NetOffList {
    $off = @()
    try { $st = Get-Settings; if ($null -ne $st.NetOff) { $off = @($st.NetOff | ForEach-Object { [string]$_ }) } } catch { }
    return $off
}

# Entry: is islevinin adi (or. Job_SpeedTest). Kapatilmis bir ozellige aitse $true doner.
function Test-NetBlocked([string]$Entry) {
    $off = @(Get-NetOffList)
    if ($off.Count -eq 0) { return $false }
    foreach ($k in $script:NetFeatures.Keys) {
        if ($off -contains [string]$k -and @($script:NetFeatures[$k].Jobs) -contains $Entry) { return $true }
    }
    return $false
}

function Get-NetBlockText([string]$Entry) {
    foreach ($k in $script:NetFeatures.Keys) {
        if (@($script:NetFeatures[$k].Jobs) -contains $Entry) { return ([string]$script:NetFeatures[$k].T + (' kapal' + [char]0x0131 + '. Ayarlar > ' + [char]0x0130 + 'nternet istekleri b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nden a' + [char]0x00E7 + 'abilirsiniz.')) }
    }
    return ('Bu ' + [char]0x00F6 + 'zellik Ayarlar > ' + [char]0x0130 + 'nternet istekleri b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nden kapat' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + '.')
}

# ---------------- PhotoRec yeri (klasor taramasi pencereyi dondurmasin diye arka planda) ----------------
function Job_FindPhotoRec($P) {
    $found = ''
    try { $found = [string](Find-PhotoRec) } catch { }
    return @{ Path = $found }
}

# ---------------- eski gunluk dosyalarini temizle ----------------
# Yalnizca Kayitlar klasorundeki .txt gunlukler silinir. Geri alma kayitlarina (Yedekler) ve raporlara dokunulmaz.
function Remove-OldLogs([int]$Days, [string]$Dir) {
    $n = 0
    if ($Days -lt 7) { $Days = 7 }
    if ([string]::IsNullOrEmpty($Dir) -or -not (Test-Path -LiteralPath $Dir -PathType Container)) { return 0 }
    $limit = (Get-Date).AddDays(-$Days)
    foreach ($f in @(Get-ChildItem -LiteralPath $Dir -Filter '*.txt' -File -ErrorAction SilentlyContinue)) {
        if ($f.LastWriteTime -lt $limit) {
            try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; $n++ } catch { }
        }
    }
    return $n
}

# ---------------- Windows 11 uyumluluk ozeti (yalnizca okur) ----------------
# Donus: Items = @(@{ N; Ok($true/$false/$null); Text }), Ready = hepsi uygun mu
function Get-Win11Readiness {
    $items = New-Object System.Collections.ArrayList
    $ready = $true
    $unknown = $false
    # islemci: 64 bit, 2+ cekirdek, 1 GHz+
    $cpuOk = $null; $cpuText = ('Okunamad' + [char]0x0131 + '')
    try {
        $cpu = Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop | Select-Object -First 1
        $ghz = [math]::Round(([double]$cpu.MaxClockSpeed) / 1000.0, 1)
        $cores = [int]$cpu.NumberOfCores
        $cpuOk = ($cores -ge 2 -and $ghz -ge 1.0 -and [int]$cpu.AddressWidth -eq 64)
        $cpuText = ([string]$cpu.Name).Trim() + ' (' + [string]$cores + (' ' + [char]0x00E7 + 'ekirdek, ') + [string]$ghz + ' GHz)'
    } catch { }
    [void]$items.Add(@{ N = ('' + [char]0x0130 + '' + [char]0x015F + 'lemci'); Ok = $cpuOk; Text = $cpuText + ('. ' + [char]0x0130 + '' + [char]0x015F + 'lemcinin Microsoft' + [char]0x2019 + 'un desteklenen listesinde olmas' + [char]0x0131 + ' da gerekir; bunu yaln' + [char]0x0131 + 'zca PC Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k Denetimi kesin s' + [char]0x00F6 + 'yler.') })
    # bellek: 4 GB
    $ramOk = $null; $ramText = ('Okunamad' + [char]0x0131 + '')
    try {
        $cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
        $gb = [math]::Round(([double]$cs.TotalPhysicalMemory) / 1GB, 1)
        $ramOk = ($gb -ge 3.8)
        $ramText = [string]$gb + ' GB (en az 4 GB gerekir)'
    } catch { }
    [void]$items.Add(@{ N = 'Bellek'; Ok = $ramOk; Text = $ramText })
    # depolama: 64 GB
    $dskOk = $null; $dskText = ('Okunamad' + [char]0x0131 + '')
    try {
        $sysDrive = [string]$env:SystemDrive
        $ld = Get-CimInstance -ClassName Win32_LogicalDisk -Filter ("DeviceID='" + $sysDrive + "'") -ErrorAction Stop
        $gb = [math]::Round(([double]$ld.Size) / 1GB, 0)
        $dskOk = ($gb -ge 64)
        $dskText = 'Sistem diski ' + [string]$gb + ' GB (en az 64 GB gerekir)'
    } catch { }
    [void]$items.Add(@{ N = 'Depolama'; Ok = $dskOk; Text = $dskText })
    # UEFI + Secure Boot
    $sbOk = $null; $sbText = ('Okunamad' + [char]0x0131 + ' (eski BIOS kipi olabilir)')
    try {
        $sb = Confirm-SecureBootUEFI -ErrorAction Stop
        $sbOk = ($sb -eq $true)
        if ($sbOk) { $sbText = ('UEFI ve G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme a' + [char]0x00E7 + '' + [char]0x0131 + 'k') } else { $sbText = ('UEFI var ama G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme kapal' + [char]0x0131 + ' (BIOS ayar' + [char]0x0131 + 'ndan a' + [char]0x00E7 + '' + [char]0x0131 + 'labilir)') }
    } catch {
        $m = [string]$_.Exception.Message
        if ($m -match 'not supported|desteklen') { $sbOk = $false; $sbText = ('Bu bilgisayar eski BIOS kipinde (UEFI de' + [char]0x011F + 'il); Windows 11 i' + [char]0x00E7 + 'in UEFI gerekir') }
    }
    [void]$items.Add(@{ N = ('UEFI ve G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme'); Ok = $sbOk; Text = $sbText })
    # TPM 2.0
    $tpmOk = $null; $tpmText = ('Okunamad' + [char]0x0131 + '')
    try {
        $tp = Get-CimInstance -Namespace 'root/cimv2/Security/MicrosoftTpm' -ClassName Win32_Tpm -ErrorAction Stop | Select-Object -First 1
        if ($null -eq $tp) { $tpmOk = $false; $tpmText = ('TPM bulunamad' + [char]0x0131 + ' veya BIOS' + [char]0x2019 + 'tan kapal' + [char]0x0131 + ' (fTPM / PTT ayar' + [char]0x0131 + 'na bak' + [char]0x0131 + 'n)') }
        else {
            $ver = [string]$tp.SpecVersion
            $tpmOk = ($ver -match '^2\.')
            $tpmText = 'TPM ' + ($ver -split ',')[0] + $(if ($tpmOk) { '' } else { ' (2.0 gerekir)' })
        }
    } catch { }
    [void]$items.Add(@{ N = 'TPM 2.0'; Ok = $tpmOk; Text = $tpmText })
    foreach ($it in $items) {
        if ($it.Ok -eq $false) { $ready = $false }
        if ($null -eq $it.Ok) { $unknown = $true }
    }
    return @{ Items = $items.ToArray(); Ready = $ready; Unknown = $unknown }
}

# Windows 10 kullananlar icin: bu bilgisayar Windows 11'e gecebilir mi (saglik raporunda gorunur; yalnizca okur)
function Chk_Win11 {
    $pr = $sync.Profile
    if ($null -eq $pr -or $pr.IsWin11 -eq $true) { return }
    $r = Get-Win11Readiness
    $lines = New-Object System.Collections.ArrayList
    foreach ($it in $r.Items) {
        $mark = ('okunamad' + [char]0x0131 + '')
        if ($it.Ok -eq $true) { $mark = 'uygun' } elseif ($it.Ok -eq $false) { $mark = ('UYGUN DE' + [char]0x011E + '' + [char]0x0130 + 'L') }
        [void]$lines.Add([string]$it.N + ' - ' + $mark + ': ' + [string]$it.Text)
    }
    $detail = ($lines.ToArray() -join "`r`n")
    $bad = @($r.Items | Where-Object { $_.Ok -eq $false } | ForEach-Object { [string]$_.N })
    if ($bad.Count -eq 0 -and $r.Unknown -ne $true) {
        Add-Finding 'w11' 'sec' 'info' ('Bu bilgisayar Windows 11 gereksinimlerini kar' + [char]0x015F + '' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') ($detail + "`r`n`r`nWindows Update sayfas$([char]0x0131)nda Windows 11 y$([char]0x00FC)kseltmesi g$([char]0x00F6)r$([char]0x00FC)n$([char]0x00FC)yorsa kurabilirsiniz; $([char]0x00F6)nce dosyalar$([char]0x0131)n$([char]0x0131)z$([char]0x0131)n yede$([char]0x011F)ini al$([char]0x0131)n.") @{ Kind = 'Url'; Url = 'ms-settings:windowsupdate' }
    } elseif ($bad.Count -gt 0) {
        $why = ('Bu bilgisayar Windows 11 gereksinimlerini kar' + [char]0x015F + '' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor: ') + ($bad -join ', ')
        $opt = "`r`n`r`nSe$([char]0x00E7)enekler: BIOS$([char]0x2019)ta TPM (fTPM / PTT) ve G$([char]0x00FC)venli $([char]0x00D6)ny$([char]0x00FC)kleme ayarlar$([char]0x0131)n$([char]0x0131) a$([char]0x00E7)mak bazen yeterlidir. Olmuyorsa Windows 10 i$([char]0x00E7)in ESU kayd$([char]0x0131) (ev kullan$([char]0x0131)c$([char]0x0131)lar$([char]0x0131) i$([char]0x00E7)in en $([char]0x00E7)ok 13.10.2026$([char]0x2019)ya kadar) ya da yeni bir bilgisayar d$([char]0x00FC)$([char]0x015F)$([char]0x00FC)n$([char]0x00FC)n; destek bittikten sonra Windows 10 g$([char]0x00FC)venlik g$([char]0x00FC)ncellemesi almaz."
        Add-Finding 'w11' 'sec' 'info' $why ($detail + $opt)
    } else {
        Add-Finding 'w11' 'sec' 'info' ('Windows 11 uyumlulu' + [char]0x011F + 'u tam belirlenemedi') ($detail + "`r`n`r`nKesin sonu$([char]0x00E7) i$([char]0x00E7)in Microsoft$([char]0x2019)un PC Sa$([char]0x011F)l$([char]0x0131)k Denetimi uygulamas$([char]0x0131)n$([char]0x0131) $([char]0x00E7)al$([char]0x0131)$([char]0x015F)t$([char]0x0131)rabilirsiniz.")
    }
}

# ---------------- Cekirdek ekleri (2) ----------------
# ==================================================================
#  CEKIRDEK EKLERI (2): buyuk / kopya dosyalari Geri Donusum Kutusu'na gonderme, Windows Update denetimi
#  (duraklat, ertele, suruculer, guncelleme kaldir), winget sabitleme, BitLocker kurtarma anahtari kontrolu,
#  restic ile sifreli ve surumlu dosya yedegi.
#  Arka plan islerinde de yuklenir; arayuze bagimli kod icermez.
# ==================================================================

# ---------------- dosyalari Geri Donusum Kutusu'na gonder ----------------
# Dosya kalici silinmez: Windows'un kendi kutusuna gider ve oradan geri alinabilir.
# Kutuya sigmayacak kadar buyuk dosyalarda ve cikarilabilir / ag suruculerinde Windows dosyayi kalici siler;
# bu yuzden o dosyalar atlanir ve Gezgin'de elle silinmesi soylenir.
function Get-RecycleVerdict([string]$Path, [double]$Size, [string]$DriveType, [double]$DriveTotal) {
    $why = Test-SecureDeleteAllowed $Path
    if ($why -ne '') { return $why }
    if ($DriveType -ne 'Fixed') { return ('' + [char]0x00C7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'labilir ve a' + [char]0x011F + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'lerinde Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu yoktur; dosya kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silinirdi. Gezgin' + [char]0x2019 + 'de elle silin.') }
    if ($DriveTotal -gt 0 -and $Size -gt ($DriveTotal * 0.03)) { return ('Dosya Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na s' + [char]0x0131 + '' + [char]0x011F + 'mayabilir (kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silinirdi). Gezgin' + [char]0x2019 + 'de elle silin.') }
    return ''
}

function Move-ToRecycle([string]$Path) {
    try { Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction Stop } catch { }
    [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin)
}

# P: Paths (dosya yollari)
function Job_RecycleFiles($P) {
    $moved = 0; $failed = 0; $skipped = 0; $bytes = 0.0
    $paths = @($P.Paths | ForEach-Object { [string]$_ } | Where-Object { $_ -ne '' })
    Write-WhLog (('--- GER' + [char]0x0130 + ' D' + [char]0x00D6 + 'N' + [char]0x00DC + '' + [char]0x015E + '' + [char]0x00DC + 'M KUTUSUNA G' + [char]0x00D6 + 'NDERME (') + [string]$paths.Count + (' dosya; Kutu' + [char]0x2019 + 'dan geri al' + [char]0x0131 + 'nabilir) ---')) 'STEP'
    Set-JobProgress 0 $paths.Count ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na g' + [char]0x00F6 + 'nderiliyor')
    foreach ($one in $paths) {
        if (Test-JobCancel) { Write-WhLog ('' + [char]0x0130 + 'ptal edildi.') 'WARN'; break }
        Step-JobProgress
        if (-not (Test-Path -LiteralPath $one -PathType Leaf)) { Write-WhLog (('Bulunamad' + [char]0x0131 + ': ') + $one) 'SKIP'; $skipped++; continue }
        $fi = $null
        try { $fi = New-Object System.IO.FileInfo -ArgumentList $one } catch { $failed++; continue }
        $dtype = 'Fixed'; $total = 0.0
        try {
            $di = New-Object System.IO.DriveInfo -ArgumentList ([System.IO.Path]::GetPathRoot($fi.FullName))
            $dtype = [string]$di.DriveType
            $total = [double]$di.TotalSize
        } catch { }
        $why = Get-RecycleVerdict $fi.FullName ([double]$fi.Length) $dtype $total
        if ($why -ne '') { Write-WhLog ($one + ': ' + $why) 'SKIP'; $skipped++; continue }
        try {
            Move-ToRecycle $fi.FullName
            $moved++; $bytes += [double]$fi.Length
            Write-WhLog ($one + (' ' + [char]0x2192 + ' Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu')) 'OK'
        } catch {
            $failed++
            Write-WhLog (('G' + [char]0x00F6 + 'nderilemedi: ') + $one + ' (' + $_.Exception.Message + ')') 'ERR'
        }
    }
    Write-WhLog ('Bitti: ' + [string]$moved + (' dosya Kutu' + [char]0x2019 + 'ya g' + [char]0x00F6 + 'nderildi (') + (Format-Size $bytes) + '), ' + [string]$skipped + (' atland' + [char]0x0131 + ', ') + [string]$failed + ' hata.') 'INFO'
    return @{ Ok = ($failed -eq 0); Moved = $moved; Skipped = $skipped; Failed = $failed; Bytes = $bytes }
}

# ---------------- Windows Update denetimi (kapatmaz; duraklatir, erteler, suruculeri ayirir) ----------------
$script:WuUxKey = 'HKLM\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings'
$script:WuPolKey = 'HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'

function ConvertFrom-WuTime($Text) {
    $s = [string]$Text
    if ($s -eq '') { return $null }
    $dt = [datetime]::MinValue
    $st = [System.Globalization.DateTimeStyles]'AdjustToUniversal, AssumeUniversal'
    if ([datetime]::TryParse($s, [System.Globalization.CultureInfo]::InvariantCulture, $st, [ref]$dt)) { return $dt }
    return $null
}

# Yalnizca okur. Paused / Until (UTC), DeferOn / DeferDays, NoDrivers
function Get-WuControlState {
    $now = (Get-Date).ToUniversalTime()
    $until = $null
    foreach ($n in @('PauseUpdatesExpiryTime', 'PauseFeatureUpdatesEndTime', 'PauseQualityUpdatesEndTime')) {
        $t = ConvertFrom-WuTime (Get-RegValue $script:WuUxKey $n '')
        if ($null -ne $t -and $t -gt $now -and ($null -eq $until -or $t -gt $until)) { $until = $t }
    }
    $defOn = ([int](Get-RegValue $script:WuPolKey 'DeferFeatureUpdates' 0) -eq 1)
    $defDays = [int](Get-RegValue $script:WuPolKey 'DeferFeatureUpdatesPeriodInDays' 0)
    $drv = ([int](Get-RegValue $script:WuPolKey 'ExcludeWUDriversInQualityUpdate' 0) -eq 1)
    return @{ Paused = ($null -ne $until); Until = $until; DeferOn = ($defOn -and $defDays -gt 0); DeferDays = $defDays; NoDrivers = $drv }
}

function Job_WuControl($P) { return (Get-WuControlState) }

# Days = 0: duraklatmayi kaldir. 1-35: Ayarlar uygulamasinin kullandigi degerlerle duraklat (sure dolunca Windows kendiliginden surdurur)
function New-WuPauseSteps([int]$Days) {
    if ($Days -lt 0 -or $Days -gt 35) { return @() }
    $names = @('PauseUpdatesStartTime', 'PauseUpdatesExpiryTime', 'PauseFeatureUpdatesStartTime', 'PauseFeatureUpdatesEndTime', 'PauseQualityUpdatesStartTime', 'PauseQualityUpdatesEndTime')
    $ops = New-Object System.Collections.ArrayList
    if ($Days -eq 0) {
        foreach ($n in $names) { [void]$ops.Add((RegDel $script:WuUxKey $n)) }
        return @(@{ Id = 'WuResume'; Title = ('Windows g' + [char]0x00FC + 'ncellemelerinin duraklat' + [char]0x0131 + 'lmas' + [char]0x0131 + 'n' + [char]0x0131 + ' kald' + [char]0x0131 + 'r'); Ops = $ops.ToArray(); Reboot = $false })
    }
    $start = (Get-Date).ToUniversalTime()
    $end = $start.AddDays($Days)
    $a = $start.ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", [System.Globalization.CultureInfo]::InvariantCulture)
    $b = $end.ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", [System.Globalization.CultureInfo]::InvariantCulture)
    [void]$ops.Add((RegOp $script:WuUxKey 'PauseUpdatesStartTime' $a 'String'))
    [void]$ops.Add((RegOp $script:WuUxKey 'PauseUpdatesExpiryTime' $b 'String'))
    [void]$ops.Add((RegOp $script:WuUxKey 'PauseFeatureUpdatesStartTime' $a 'String'))
    [void]$ops.Add((RegOp $script:WuUxKey 'PauseFeatureUpdatesEndTime' $b 'String'))
    [void]$ops.Add((RegOp $script:WuUxKey 'PauseQualityUpdatesStartTime' $a 'String'))
    [void]$ops.Add((RegOp $script:WuUxKey 'PauseQualityUpdatesEndTime' $b 'String'))
    return @(@{ Id = 'WuPause'; Title = (('Windows g' + [char]0x00FC + 'ncellemelerini ') + [string]$Days + (' g' + [char]0x00FC + 'n duraklat')); Ops = $ops.ToArray(); Reboot = $false })
}

# Days = 0: ertelemeyi kaldir. 1-365: ozellik guncellemelerini bu kadar gun ertele (guvenlik guncellemeleri etkilenmez)
function New-WuDeferSteps([int]$Days) {
    if ($Days -lt 0 -or $Days -gt 365) { return @() }
    if ($Days -eq 0) {
        $o = @((RegDel $script:WuPolKey 'DeferFeatureUpdates'), (RegDel $script:WuPolKey 'DeferFeatureUpdatesPeriodInDays'))
        return @(@{ Id = 'WuDeferOff'; Title = ('' + [char]0x00D6 + 'zellik g' + [char]0x00FC + 'ncellemesi ertelemesini kald' + [char]0x0131 + 'r'); Ops = $o; Reboot = $false })
    }
    $o2 = @((RegOp $script:WuPolKey 'DeferFeatureUpdates' 1), (RegOp $script:WuPolKey 'DeferFeatureUpdatesPeriodInDays' $Days))
    return @(@{ Id = 'WuDefer'; Title = (('' + [char]0x00D6 + 'zellik g' + [char]0x00FC + 'ncellemelerini ') + [string]$Days + (' g' + [char]0x00FC + 'n ertele')); Ops = $o2; Reboot = $false })
}

function New-WuDriverSteps([bool]$Exclude) {
    if ($Exclude) {
        return @(@{ Id = 'WuNoDrv'; Title = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri Windows Update ile alma'); Ops = @((RegOp $script:WuPolKey 'ExcludeWUDriversInQualityUpdate' 1)); Reboot = $false })
    }
    return @(@{ Id = 'WuDrv'; Title = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri yeniden Windows Update ile al'); Ops = @((RegDel $script:WuPolKey 'ExcludeWUDriversInQualityUpdate')); Reboot = $false })
}

# Kurulu guncellemeler (yalnizca okur)
function Job_InstalledUpdates($P) {
    $rows = New-Object System.Collections.ArrayList
    try {
        foreach ($h in @(Get-HotFix -ErrorAction Stop)) {
            $id = [string]$h.HotFixID
            if ($id -notmatch '^KB\d{6,8}$') { continue }
            $d = $null
            try { if ($null -ne $h.InstalledOn) { $d = [datetime]$h.InstalledOn } } catch { }
            [void]$rows.Add(@{ Id = $id; Desc = [string]$h.Description; Date = $d; DateText = $(if ($null -ne $d) { $d.ToString('yyyy-MM-dd') } else { '' }); By = [string]$h.InstalledBy })
        }
    } catch { Write-WhLog (('Kurulu g' + [char]0x00FC + 'ncellemeler okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    $sorted = @($rows | Sort-Object { if ($null -ne $_.Date) { [datetime]$_.Date } else { [datetime]::MinValue } } -Descending)
    Write-WhLog (('Kurulu g' + [char]0x00FC + 'ncelleme: ') + [string]$sorted.Count) 'INFO'
    return @{ Rows = $sorted }
}

# wusa cikis kodu -> sonuc. Ok: kaldirildi; Reboot: yeniden baslatma gerekir; Text: kullaniciya aciklama
function Get-WusaResult([int]$Code) {
    switch ($Code) {
        0 { return @{ Ok = $true; Reboot = $false; Skip = $false; Text = ('kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '') } }
        3010 { return @{ Ok = $true; Reboot = $true; Skip = $false; Text = ('kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ' (yeniden ba' + [char]0x015F + 'latma gerekir)') } }
        2359302 { return @{ Ok = $false; Reboot = $false; Skip = $true; Text = ('bu g' + [char]0x00FC + 'ncelleme zaten kurulu de' + [char]0x011F + 'il') } }
        -2145124329 { return @{ Ok = $false; Reboot = $false; Skip = $true; Text = ('bu g' + [char]0x00FC + 'ncelleme bu y' + [char]0x00F6 + 'ntemle kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor (birikimli g' + [char]0x00FC + 'ncellemeler Ayarlar > Windows Update > G' + [char]0x00FC + 'ncelleme ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i > G' + [char]0x00FC + 'ncellemeleri kald' + [char]0x0131 + 'r yolundan kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r)') } }
        5 { return @{ Ok = $false; Reboot = $false; Skip = $false; Text = ('eri' + [char]0x015F + 'im reddedildi') } }
        default { return @{ Ok = $false; Reboot = $false; Skip = $false; Text = (('wusa ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$Code) } }
    }
}

# P: Ids (KB numaralari). Geri alinamaz: Windows Update ayni guncellemeyi yeniden sunabilir
function Job_WuUninstall($P) {
    $ids = @($P.Ids | ForEach-Object { [string]$_ } | Where-Object { $_ -match '^KB\d{6,8}$' })
    Write-WhLog (('--- G' + [char]0x00DC + 'NCELLEME KALDIRMA (') + [string]$ids.Count + (' g' + [char]0x00FC + 'ncelleme, geri al' + [char]0x0131 + 'namaz) ---')) 'STEP'
    $okN = 0; $reboot = $false; $failed = 0
    Set-JobProgress 0 $ids.Count ('G' + [char]0x00FC + 'ncellemeler kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor')
    foreach ($id in $ids) {
        if (Test-JobCancel) { Write-WhLog ('' + [char]0x0130 + 'ptal edildi.') 'WARN'; break }
        $kb = $id.Substring(2)
        $code = -1
        try {
            $exe = Join-Path (Join-Path $env:WINDIR 'System32') 'wusa.exe'
            $pr = Start-Process -FilePath $exe -ArgumentList ('/uninstall /kb:' + $kb + ' /quiet /norestart') -Wait -PassThru -WindowStyle Hidden
            $code = [int]$pr.ExitCode
        } catch { Write-WhLog ($id + ': ' + $_.Exception.Message) 'ERR'; $failed++; Step-JobProgress; continue }
        $r = Get-WusaResult $code
        if ($r.Ok) { $okN++; if ($r.Reboot) { $reboot = $true }; Write-WhLog ($id + ' ' + $r.Text) 'OK' }
        elseif ($r.Skip) { Write-WhLog ($id + ': ' + $r.Text) 'SKIP' }
        else { $failed++; Write-WhLog ($id + ': ' + $r.Text) 'ERR' }
        Step-JobProgress
    }
    Write-WhLog (('Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lan: ') + [string]$okN + ' / ' + [string]$ids.Count) 'INFO'
    return @{ Ok = ($failed -eq 0); Removed = $okN; Reboot = $reboot; Failed = $failed }
}

# ---------------- winget sabitleme ("bunu guncelleme") ----------------
# P: Ids, Action = add | remove.  Sabitli program 'winget upgrade --all' ile ve bu uygulamanin toplu guncellemesinde atlanir.
function Job_WingetPin($P) {
    $act = [string]$P.Action
    if ($act -ne 'add' -and $act -ne 'remove') { return @{ Ok = $false; Done = 0 } }
    $ids = @($P.Ids | ForEach-Object { [string]$_ })
    $n = 0
    foreach ($id in $ids) {
        if ($id -cnotmatch '^[A-Za-z0-9][A-Za-z0-9\.\-_\+]*$') { Write-WhLog (('Ge' + [char]0x00E7 + 'ersiz paket kimli' + [char]0x011F + 'i: ') + $id) 'SKIP'; continue }
        try {
            $r = Invoke-WingetRaw @('pin', $act, '--id', $id, '--exact', '--accept-source-agreements', '--disable-interactivity')
            if ($r.Code -eq 0) { $n++; if ($act -eq 'add') { Write-WhLog ($id + (' sabitlendi (g' + [char]0x00FC + 'ncellenmez)')) 'OK' } else { Write-WhLog ($id + (' sabitlemesi kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '')) 'OK' } }
            else { Write-WingetLines $r.Lines; Write-WhLog ($id + (': winget ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$r.Code) 'ERR' }
        } catch { Write-WhLog ($id + ': ' + $_.Exception.Message) 'ERR' }
    }
    return @{ Ok = ($n -eq $ids.Count); Done = $n }
}

function Job_WingetPinList($P) {
    $ids = New-Object System.Collections.ArrayList
    try {
        $r = Invoke-WingetRaw @('pin', 'list', '--accept-source-agreements', '--disable-interactivity')
        $tbl = ConvertFrom-WingetTable $r.Lines
        foreach ($row in $tbl) { [void]$ids.Add([string]$row.Id) }
    } catch { Write-WhLog (('Sabitli programlar okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    return @{ Ids = $ids.ToArray() }
}

# ---------------- BitLocker: durum ve kurtarma anahtari ----------------
function Get-BlProtectorName([int]$Type) {
    switch ($Type) {
        1 { return 'TPM' }
        2 { return 'Harici anahtar' }
        3 { return ('Kurtarma parolas' + [char]0x0131 + '') }
        4 { return 'TPM + PIN' }
        5 { return ('TPM + ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' anahtar' + [char]0x0131 + '') }
        6 { return ('TPM + PIN + ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' anahtar' + [char]0x0131 + '') }
        7 { return 'Ortak anahtar' }
        8 { return 'Parola' }
        9 { return ('TPM sertifikas' + [char]0x0131 + '') }
        10 { return ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' kart') }
        default { return 'Bilinmeyen' }
    }
}

function Get-BlStatusText([int]$Protection, [int]$Conversion, [int]$Percent) {
    switch ($Conversion) {
        0 { return ('' + [char]0x015E + 'ifreli de' + [char]0x011F + 'il') }
        1 { if ($Protection -eq 1) { return ('' + [char]0x015E + 'ifreli ve koruma a' + [char]0x00E7 + '' + [char]0x0131 + 'k') } else { return ('' + [char]0x015E + 'ifreli ama koruma ask' + [char]0x0131 + 'da') } }
        2 { return (('' + [char]0x015E + 'ifreleniyor (%') + [string]$Percent + ')') }
        3 { return (('' + [char]0x015E + 'ifre ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'l' + [char]0x00FC + 'yor (%') + [string]$Percent + ')') }
        4 { return ('' + [char]0x015E + 'ifreleme duraklat' + [char]0x0131 + 'ld' + [char]0x0131 + '') }
        5 { return ('' + [char]0x015E + 'ifre ' + [char]0x00E7 + '' + [char]0x00F6 + 'zme duraklat' + [char]0x0131 + 'ld' + [char]0x0131 + '') }
        default { if ($Protection -eq 1) { return ('Koruma a' + [char]0x00E7 + '' + [char]0x0131 + 'k') } else { return ('Durum okunamad' + [char]0x0131 + '') } }
    }
}

# Yalnizca okur. Her surucu icin: Drive (C:), Protection, Conversion, Percent, Types (koruyucu turleri), RecoveryIds, HasRecovery
function Get-BitLockerVolumes {
    $out = New-Object System.Collections.ArrayList
    $vols = @()
    try { $vols = @(Get-CimInstance -Namespace 'root/cimv2/Security/MicrosoftVolumeEncryption' -ClassName Win32_EncryptableVolume -ErrorAction Stop) } catch { return $out.ToArray() }
    foreach ($v in $vols) {
        $drive = [string]$v.DriveLetter
        if ($drive -eq '') { continue }
        $prot = 2
        try { $prot = [int]$v.ProtectionStatus } catch { }
        $conv = -1; $pct = 0
        try { $cs = Invoke-CimMethod -InputObject $v -MethodName GetConversionStatus -ErrorAction Stop; $conv = [int]$cs.ConversionStatus; $pct = [int]$cs.EncryptionPercentage } catch { }
        $rec = @()
        try { $r = Invoke-CimMethod -InputObject $v -MethodName GetKeyProtectors -Arguments @{ KeyProtectorType = 3 } -ErrorAction Stop; $rec = @($r.VolumeKeyProtectorID | Where-Object { $_ }) } catch { }
        $types = New-Object System.Collections.ArrayList
        try {
            $all = Invoke-CimMethod -InputObject $v -MethodName GetKeyProtectors -Arguments @{ KeyProtectorType = 0 } -ErrorAction Stop
            foreach ($id in @($all.VolumeKeyProtectorID | Where-Object { $_ })) {
                $t = Invoke-CimMethod -InputObject $v -MethodName GetKeyProtectorType -Arguments @{ VolumeKeyProtectorID = $id } -ErrorAction Stop
                [void]$types.Add([int]$t.KeyProtectorType)
            }
        } catch { }
        [void]$out.Add(@{ Drive = $drive; Protection = $prot; Conversion = $conv; Percent = $pct; Types = $types.ToArray(); RecoveryIds = $rec; HasRecovery = ($rec.Count -gt 0) })
    }
    return $out.ToArray()
}

function Job_BitLockerInfo($P) {
    $rows = New-Object System.Collections.ArrayList
    foreach ($v in @(Get-BitLockerVolumes)) {
        $names = @($v.Types | ForEach-Object { Get-BlProtectorName ([int]$_) })
        [void]$rows.Add(@{
            Drive = $v.Drive
            Status = (Get-BlStatusText ([int]$v.Protection) ([int]$v.Conversion) ([int]$v.Percent))
            Protected = ([int]$v.Protection -eq 1)
            Encrypted = ([int]$v.Conversion -ne 0 -and [int]$v.Conversion -ne -1)
            Protectors = ($names -join ', ')
            HasRecovery = ($v.HasRecovery -eq $true)
        })
    }
    Write-WhLog (('BitLocker s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ': ') + [string]$rows.Count) 'INFO'
    return @{ Rows = $rows.ToArray() }
}

# Kullanici istegiyle: secili surucunun kurtarma parolalarini okur. Parola gunluge yazilmaz.
function Job_BitLockerKey($P) {
    $drive = ([string]$P.Drive).Trim().ToUpperInvariant()
    if ($drive -cmatch '^[A-Z]$') { $drive = $drive + ':' }
    if ($drive -cnotmatch '^[A-Z]:$') { Write-WhLog ('Ge' + [char]0x00E7 + 'ersiz s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '.') 'ERR'; return @{ Ok = $false; Keys = @() } }
    $keys = New-Object System.Collections.ArrayList
    try {
        $v = Get-CimInstance -Namespace 'root/cimv2/Security/MicrosoftVolumeEncryption' -ClassName Win32_EncryptableVolume -Filter ("DriveLetter='" + $drive + "'") -ErrorAction Stop | Select-Object -First 1
        if ($null -ne $v) {
            $r = Invoke-CimMethod -InputObject $v -MethodName GetKeyProtectors -Arguments @{ KeyProtectorType = 3 } -ErrorAction Stop
            foreach ($id in @($r.VolumeKeyProtectorID | Where-Object { $_ })) {
                $k = Invoke-CimMethod -InputObject $v -MethodName GetKeyProtectorNumericalPassword -Arguments @{ VolumeKeyProtectorID = $id } -ErrorAction Stop
                if ([string]$k.NumericalPassword -ne '') { [void]$keys.Add(@{ Id = [string]$id; Password = [string]$k.NumericalPassword }) }
            }
        }
    } catch { Write-WhLog (('Kurtarma anahtar' + [char]0x0131 + ' okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false; Keys = @() } }
    Write-WhLog ($drive + (' i' + [char]0x00E7 + 'in ') + [string]$keys.Count + (' kurtarma anahtar' + [char]0x0131 + ' okundu (kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' iste' + [char]0x011F + 'iyle; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'lmaz).')) 'INFO'
    return @{ Ok = ($keys.Count -gt 0); Drive = $drive; Keys = $keys.ToArray() }
}

# P: Drive. Sifreli bir surucuye kurtarma parolasi koruyucusu ekler (veri degismez; yalnizca yedek anahtar olusur).
# Anahtar gunluge yazilmaz; sonra "Anahtari goster" ile okunur.
function Job_BitLockerAddKey($P) {
    $drive = ([string]$P.Drive).Trim().ToUpperInvariant()
    if ($drive -cmatch '^[A-Z]$') { $drive = $drive + ':' }
    if ($drive -cnotmatch '^[A-Z]:$') { Write-WhLog ('Ge' + [char]0x00E7 + 'ersiz s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '.') 'ERR'; return @{ Ok = $false } }
    $vol = $null
    foreach ($v in @(Get-BitLockerVolumes)) { if ([string]$v.Drive -eq $drive) { $vol = $v } }
    if ($null -eq $vol) { Write-WhLog ($drive + (': BitLocker bilgisi okunamad' + [char]0x0131 + '.')) 'ERR'; return @{ Ok = $false } }
    $enc = ([int]$vol.Protection -eq 1) -or ([int]$vol.Conversion -gt 0)
    if (-not $enc) { Write-WhLog ($drive + (' ' + [char]0x015F + 'ifreli de' + [char]0x011F + 'il; kurtarma anahtar' + [char]0x0131 + ' eklenmez.')) 'ERR'; return @{ Ok = $false } }
    if ($vol.HasRecovery) { Write-WhLog ($drive + (' i' + [char]0x00E7 + 'in kurtarma anahtar' + [char]0x0131 + ' zaten tan' + [char]0x0131 + 'ml' + [char]0x0131 + '.')) 'INFO'; return @{ Ok = $true; Existing = $true } }
    try {
        [void](Add-BitLockerKeyProtector -MountPoint $drive -RecoveryPasswordProtector -ErrorAction Stop)
    } catch {
        Write-WhLog ($drive + (': kurtarma anahtar' + [char]0x0131 + ' eklenemedi: ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false }
    }
    Write-WhLog ($drive + (' i' + [char]0x00E7 + 'in kurtarma anahtar' + [char]0x0131 + ' eklendi (anahtar g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'lmaz).')) 'OK'
    return @{ Ok = $true; Existing = $false }
}

# Anahtar dosyasi metni: kullanici ayri bir diske / USB'ye kaydeder
function Format-BlKeyFile([string]$Drive, $Keys) {
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine(('BitLocker kurtarma anahtar' + [char]0x0131 + ''))
    [void]$sb.AppendLine('Bilgisayar : ' + [string]$env:COMPUTERNAME)
    [void]$sb.AppendLine(('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '    : ') + $Drive)
    [void]$sb.AppendLine('Tarih     : ' + (Get-Date).ToString('dd.MM.yyyy HH:mm'))
    [void]$sb.AppendLine('')
    foreach ($k in @($Keys)) {
        [void]$sb.AppendLine(('Anahtar kimli' + [char]0x011F + 'i : ') + [string]$k.Id)
        [void]$sb.AppendLine(('Kurtarma anahtar' + [char]0x0131 + ': ') + [string]$k.Password)
        [void]$sb.AppendLine('')
    }
    [void]$sb.AppendLine(('Bu dosyay' + [char]0x0131 + ' bilgisayar' + [char]0x0131 + 'n DI' + [char]0x015E + 'INDA (USB bellek, ba' + [char]0x015F + 'ka bir hesap ya da ka' + [char]0x011F + '' + [char]0x0131 + 'da yazd' + [char]0x0131 + 'r' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ') saklay' + [char]0x0131 + 'n.'))
    [void]$sb.AppendLine(('Bu anahtar' + [char]0x0131 + ' bilen herkes s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'zdeki verilere eri' + [char]0x015F + 'ebilir.'))
    return $sb.ToString()
}

# Saglik denetimi: BitLocker durumu ve kurtarma anahtari (eskisinin yerine gecer)
function Chk_BitLocker {
    $drive = ([string]$env:SystemDrive).ToUpperInvariant()
    $vol = $null
    foreach ($v in @(Get-BitLockerVolumes)) { if ([string]$v.Drive -eq $drive) { $vol = $v } }
    if ($null -eq $vol) {
        Add-Finding 'bl' 'sec' 'info' ('Disk ' + [char]0x015F + 'ifreleme (BitLocker) durumu okunamad' + [char]0x0131 + '') ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde BitLocker bulunmuyor olabilir (Home s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde "Cihaz ' + [char]0x015F + 'ifrelemesi" kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'r).')
        return
    }
    if ([int]$vol.Protection -eq 1) {
        Add-Finding 'bl' 'sec' 'ok' ('Sistem diski ' + [char]0x015F + 'ifreli (BitLocker)') ('Bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'rsa dosyalara eri' + [char]0x015F + 'ilemez.')
        if (-not $vol.HasRecovery) {
            Add-Finding 'bl-key' 'sec' 'warn' ('BitLocker kurtarma anahtar' + [char]0x0131 + ' tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' de' + [char]0x011F + 'il') (('Disk ' + [char]0x015F + 'ifreli ama kurtarma anahtar' + [char]0x0131 + ' bulunamad' + [char]0x0131 + '. BIOS ya da donan' + [char]0x0131 + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'inden sonra Windows anahtar sorarsa verilere eri' + [char]0x015F + 'emezsiniz. Kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + ' ekleyip yedekleyin.')) @{ Kind = 'Page'; Page = 'backup'; Sub = 'bl'; Label = 'BitLocker sekmesi' } 6
        } else {
            Add-Finding 'bl-key' 'sec' 'info' ('BitLocker kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n bir kopyas' + [char]0x0131 + ' bilgisayar' + [char]0x0131 + 'n d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda m' + [char]0x0131 + '?') (('Anahtar bu bilgisayarda tan' + [char]0x0131 + 'ml' + [char]0x0131 + '. Ama bilgisayar a' + [char]0x00E7 + '' + [char]0x0131 + 'lmazsa ya da BIOS g' + [char]0x00FC + 'ncellenirse sorulur; bir kopyas' + [char]0x0131 + ' bilgisayar' + [char]0x0131 + 'n DI' + [char]0x015E + 'INDA olmal' + [char]0x0131 + ': Microsoft hesab' + [char]0x0131 + 'n' + [char]0x0131 + 'z (aka.ms/myrecoverykey), ka' + [char]0x011F + '' + [char]0x0131 + 'da yazd' + [char]0x0131 + 'r' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' ya da USB bellekte. Yedek sayfas' + [char]0x0131 + 'ndaki BitLocker sekmesinden anahtar' + [char]0x0131 + ' g' + [char]0x00F6 + 'rebilir ve kaydedebilirsiniz.')) @{ Kind = 'Page'; Page = 'backup'; Sub = 'bl'; Label = 'BitLocker sekmesi' }
        }
    } else {
        Add-Finding 'bl' 'sec' 'warn' ('Sistem diski ' + [char]0x015F + 'ifreli de' + [char]0x011F + 'il') ('Diz' + [char]0x00FC + 'st' + [char]0x00FC + ' bilgisayarlarda disk ' + [char]0x015F + 'ifrelemesi ' + [char]0x00E7 + 'al' + [char]0x0131 + 'nt' + [char]0x0131 + '/kay' + [char]0x0131 + 'p durumunda veriyi korur. Kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + ' mutlaka saklay' + [char]0x0131 + 'n (Microsoft hesab' + [char]0x0131 + ' ya da yazd' + [char]0x0131 + 'r' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' ka' + [char]0x011F + '' + [char]0x0131 + 't).') @{ Kind = 'Page'; Page = 'backup'; Sub = 'bl'; Label = 'BitLocker sekmesi' }
    }
}

# ---------------- restic: sifreli ve surumlu dosya yedegi (istege bagli motor) ----------------
# restic acik kaynaktir (BSD-2). Bu uygulama onu kendi paketlemez; winget ile kurulur (winget paket ozetini dogrular)
# ya da kullanicinin kurdugu surum kullanilir. Parola yalnizca calisan islemin ortam degiskenine verilir; hicbir yere yazilmaz.
function Find-Restic {
    $c = $null
    try { $c = Get-Command -Name 'restic.exe' -ErrorAction Ignore } catch { }
    if ($null -ne $c) { return [string]$c.Source }
    try { $c = Get-Command -Name 'restic' -ErrorAction Ignore } catch { }
    if ($null -ne $c) { return [string]$c.Source }
    $cand = New-Object System.Collections.ArrayList
    if (-not [string]::IsNullOrEmpty($env:LOCALAPPDATA)) {
        [void]$cand.Add((Join-Path $env:LOCALAPPDATA 'Microsoft\WinGet\Links\restic.exe'))
        $pk = Join-Path $env:LOCALAPPDATA 'Microsoft\WinGet\Packages'
        if (Test-Path -LiteralPath $pk -PathType Container) {
            foreach ($d in @(Get-ChildItem -LiteralPath $pk -Directory -Filter 'restic.restic*' -ErrorAction SilentlyContinue)) {
                foreach ($f in @(Get-ChildItem -LiteralPath $d.FullName -Filter 'restic*.exe' -File -ErrorAction SilentlyContinue)) { [void]$cand.Add($f.FullName) }
            }
        }
    }
    if (-not [string]::IsNullOrEmpty($env:ProgramFiles)) { [void]$cand.Add((Join-Path $env:ProgramFiles 'restic\restic.exe')) }
    foreach ($p in $cand) { if (Test-Path -LiteralPath $p -PathType Leaf) { return [string]$p } }
    return ''
}

function Get-ResticRepoPath([string]$Dest) {
    return (Join-Path $Dest ('Multimizer-' + [string]$env:COMPUTERNAME + '.restic'))
}

function Test-ResticRepo([string]$Repo) {
    return (Test-Path -LiteralPath (Join-Path $Repo 'config') -PathType Leaf)
}

# Yedege katilmayacak (cop) adlar: robocopy yedegiyle ayni liste
function New-ResticBackupArgs([string]$Repo, $Sources, [bool]$DryRun) {
    $a = New-Object System.Collections.ArrayList
    foreach ($x in @('backup', '--repo', $Repo, '--json', '--tag', 'multimizer', '--exclude-caches')) { [void]$a.Add($x) }
    if ($DryRun) { [void]$a.Add('--dry-run') }
    foreach ($d in @($script:RoboExcludeDirs)) { if (-not [string]::IsNullOrEmpty([string]$d)) { [void]$a.Add('--exclude'); [void]$a.Add([string]$d) } }
    foreach ($f in @($script:RoboExcludeFiles)) { if (-not [string]::IsNullOrEmpty([string]$f)) { [void]$a.Add('--exclude'); [void]$a.Add([string]$f) } }
    foreach ($s in @($Sources)) { [void]$a.Add([string]$s) }
    return $a.ToArray()
}

function Format-ProcessArg([string]$A) {
    if ($A -eq '') { return '""' }
    if ($A -notmatch '[\s"]') { return $A }
    $s = $A -replace '(\\*)"', '$1$1\"'
    $s = $s -replace '(\\+)$', '$1$1'
    return ('"' + $s + '"')
}

# restic'i calistirir. Parola yalnizca bu islemin ortamina verilir. Donus: Code, Lines (stdout), Err (stderr)
function Invoke-Restic([string]$Exe, [string[]]$ArgList, [string]$Password, [scriptblock]$OnLine = $null) {
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $Exe
    $psi.Arguments = (@($ArgList | ForEach-Object { Format-ProcessArg ([string]$_) }) -join ' ')
    $psi.UseShellExecute = $false
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true
    $psi.EnvironmentVariables['RESTIC_PASSWORD'] = $Password
    $psi.EnvironmentVariables['RESTIC_PROGRESS_FPS'] = '0.2'
    try { $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8; $psi.StandardErrorEncoding = [System.Text.Encoding]::UTF8 } catch { }
    $proc = New-Object System.Diagnostics.Process
    $proc.StartInfo = $psi
    $lines = New-Object System.Collections.ArrayList
    [void]$proc.Start()
    $errTask = $proc.StandardError.ReadToEndAsync()
    while ($true) {
        $l = $proc.StandardOutput.ReadLine()
        if ($null -eq $l) { break }
        [void]$lines.Add($l)
        if ($null -ne $OnLine) { try { & $OnLine $l } catch { } }
        if (Test-JobCancel) { try { $proc.Kill() } catch { } ; break }
    }
    $proc.WaitForExit()
    $errText = ''
    try { $errText = [string]$errTask.Result } catch { }
    $code = [int]$proc.ExitCode
    $proc.Dispose()
    return @{ Code = $code; Lines = $lines.ToArray(); Err = $errText }
}

# restic --json ciktisindaki ozet satiri. Yoksa $null
function Get-ResticSummary($Lines) {
    $sum = $null
    foreach ($l in @($Lines)) {
        $t = ([string]$l).Trim()
        if (-not $t.StartsWith('{') -or $t.IndexOf('"summary"') -lt 0) { continue }
        try {
            $o = $t | ConvertFrom-Json -ErrorAction Stop
            if ([string]$o.message_type -eq 'summary') { $sum = $o }
        } catch { }
    }
    return $sum
}

function Get-ResticErrorText([string]$Err, [int]$Code) {
    $t = ([string]$Err).Trim()
    if ($t -match '(?i)wrong password|no key found|Fatal: unable to open config') { return ('Parola yanl' + [char]0x0131 + '' + [char]0x015F + ' ya da bu klas' + [char]0x00F6 + 'r bir restic deposu de' + [char]0x011F + 'il.') }
    if ($t -match '(?i)repository is already locked') { return ('Depo ba' + [char]0x015F + 'ka bir i' + [char]0x015F + 'lem taraf' + [char]0x0131 + 'ndan kilitli. Bir s' + [char]0x00FC + 're sonra yeniden deneyin.') }
    if ($t -eq '') { return (('restic ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$Code) }
    $first = ($t -split "`n")[0].Trim()
    if ($first.Length -gt 200) { $first = $first.Substring(0, 200) }
    return $first
}

# P: Sources, Dest, Password, Preview
function Job_ResticBackup($P) {
    Reset-Counters
    $preview = [bool]$P.Preview
    $st = Get-Settings
    $sources = @($P.Sources | Where-Object { $_ }); if ($sources.Count -eq 0) { $sources = @($st.BackupSources) }
    $dest = [string]$P.Dest; if ($dest -eq '') { $dest = [string]$st.BackupDest }
    $pw = [string]$P.Password
    $exe = Find-Restic
    if ($exe -eq '') { Write-WhLog ('restic bulunamad' + [char]0x0131 + '. Yedek sayfas' + [char]0x0131 + 'ndaki ' + [char]0x201C + 'restic' + [char]0x2019 + 'i kur (winget)' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesiyle kurun.') 'ERR'; return @{ Ok = $false } }
    if ($sources.Count -eq 0 -or $dest -eq '') { Write-WhLog ('Yedeklenecek klas' + [char]0x00F6 + 'r veya hedef se' + [char]0x00E7 + 'ilmemi' + [char]0x015F + '.') 'ERR'; return @{ Ok = $false } }
    if ($pw.Length -lt 8) { Write-WhLog ('Parola en az 8 karakter olmal' + [char]0x0131 + '.') 'ERR'; return @{ Ok = $false } }
    $repo = Get-ResticRepoPath $dest
    foreach ($s in $sources) {
        if (-not (Test-Path -LiteralPath ([string]$s) -PathType Container)) { Write-WhLog (('Kaynak klas' + [char]0x00F6 + 'r yok: ') + [string]$s) 'WARN'; continue }
        $why = Test-BackupDest ([string]$s) $repo
        if ($why -ne '') { Write-WhLog ([string]$s + ': ' + $why) 'ERR'; return @{ Ok = $false } }
    }
    $good = @($sources | Where-Object { Test-Path -LiteralPath ([string]$_) -PathType Container })
    if ($good.Count -eq 0) { Write-WhLog ('Yedeklenecek var olan bir klas' + [char]0x00F6 + 'r yok.') 'ERR'; return @{ Ok = $false } }
    $t0 = Get-Date
    Set-JobProgress 0 3 ('' + [char]0x015E + 'ifreli yedek')
    $isNew = -not (Test-ResticRepo $repo)
    if ($isNew -and -not $preview) {
        Write-WhLog (('=== Yeni ' + [char]0x015F + 'ifreli depo: ') + $repo) 'STEP'
        try { New-Item -ItemType Directory -Path $repo -Force | Out-Null } catch { Write-WhLog (('Hedef olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false } }
        $r0 = Invoke-Restic $exe @('init', '--repo', $repo) $pw
        if ($r0.Code -ne 0) { Write-WhLog (('Depo olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + (Get-ResticErrorText $r0.Err $r0.Code)) 'ERR'; return @{ Ok = $false } }
    } elseif ($isNew -and $preview) {
        Write-WhLog ('' + [char]0x00D6 + 'nizleme: depo hen' + [char]0x00FC + 'z yok; ilk yedekte olu' + [char]0x015F + 'turulur. Dosya say' + [char]0x0131 + 's' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yedek denenir.') 'INFO'
    }
    Set-JobProgress 1 3 ('' + [char]0x015E + 'ifreli yedek')
    Write-WhLog ('=== ' + $(if ($preview) { ('' + [char]0x00D6 + 'nizleme') } else { 'Yedekleniyor' }) + ': ' + (($good | ForEach-Object { [string]$_ }) -join ', ') + ('  ' + [char]0x2192 + '  ') + $repo) 'STEP'
    if ($preview -and $isNew) {
        # depo olmadan restic onizleme yapamaz: yalnizca dosya sayisi / boyut bu uygulamayla okunur
        $cnt = 0; $tot = 0.0
        foreach ($s in $good) { $fl = Get-FilesBySize ([string]$s) 0 500000; foreach ($f in $fl) { $cnt++; $tot += [double]$f.Length } }
        Write-WhLog (('' + [char]0x00D6 + 'nizleme: yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + [string]$cnt + ' dosya (' + (Format-Size $tot) + (') yedeklenecek. Hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '.')) 'INFO'
        return @{ Ok = $true; Files = $cnt; Bytes = $tot; Dest = $repo; Preview = $true }
    }
    $args1 = New-ResticBackupArgs $repo $good $preview
    $r1 = Invoke-Restic $exe $args1 $pw
    if ($r1.Code -ne 0 -and $r1.Code -ne 3) { Write-WhLog (('Yedekleme ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + (Get-ResticErrorText $r1.Err $r1.Code)) 'ERR'; return @{ Ok = $false } }
    if ($r1.Code -eq 3) { Write-WhLog ('Baz' + [char]0x0131 + ' dosyalar okunamad' + [char]0x0131 + ' (a' + [char]0x00E7 + '' + [char]0x0131 + 'k ya da eri' + [char]0x015F + 'im yok); geri kalan' + [char]0x0131 + ' yedeklendi.') 'WARN' }
    $sum = Get-ResticSummary $r1.Lines
    $files = 0.0; $bytes = 0.0; $added = 0.0; $snap = ''
    if ($null -ne $sum) {
        try { $files = [double]$sum.total_files_processed } catch { }
        try { $bytes = [double]$sum.total_bytes_processed } catch { }
        try { $added = [double]$sum.data_added } catch { }
        try { $snap = [string]$sum.snapshot_id } catch { }
    }
    if ($preview) {
        Write-WhLog (('' + [char]0x00D6 + 'nizleme: ') + [string][int]$files + ' dosya (' + (Format-Size $bytes) + (') i' + [char]0x015F + 'lenecek, depoya yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + (Format-Size $added) + (' eklenecek. Hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '.')) 'INFO'
        return @{ Ok = $true; Files = $files; Bytes = $bytes; Added = $added; Dest = $repo; Preview = $true }
    }
    Set-JobProgress 2 3 ('Eski s' + [char]0x00FC + 'r' + [char]0x00FC + 'mler ay' + [char]0x0131 + 'klan' + [char]0x0131 + 'yor')
    # surum politikasi: son 7 + haftalik 4 + aylik 6; yalnizca bu uygulamanin etiketli yedekleri
    $r2 = Invoke-Restic $exe @('forget', '--repo', $repo, '--tag', 'multimizer', '--keep-last', '7', '--keep-weekly', '4', '--keep-monthly', '6', '--prune') $pw
    if ($r2.Code -ne 0) { Write-WhLog (('Eski s' + [char]0x00FC + 'r' + [char]0x00FC + 'mler ay' + [char]0x0131 + 'klanamad' + [char]0x0131 + ': ') + (Get-ResticErrorText $r2.Err $r2.Code)) 'WARN' }
    Set-JobProgress 3 3 ('' + [char]0x015E + 'ifreli yedek')
    $msg = (('' + [char]0x015E + 'ifreli yedek: ') + [string][int]$files + (' dosya i' + [char]0x015F + 'lendi (') + (Format-Size $bytes) + '), depoya ' + (Format-Size $added) + ' eklendi, ' + (Format-Duration (((Get-Date) - $t0).TotalSeconds)))
    Write-WhLog $msg 'OK'
    $st.LastBackup = (Get-Date).ToString('yyyy-MM-dd HH:mm'); Save-Settings $st
    Write-Thanks
    return @{ Ok = $true; Files = $files; Bytes = $bytes; Added = $added; Dest = $repo; Snapshot = $snap }
}

# P: Dest, Password. Surum listesi (yalnizca okur)
function Job_ResticSnapshots($P) {
    $exe = Find-Restic
    if ($exe -eq '') { Write-WhLog ('restic bulunamad' + [char]0x0131 + '.') 'ERR'; return @{ Ok = $false; Rows = @() } }
    $st = Get-Settings
    $dest = [string]$P.Dest; if ($dest -eq '') { $dest = [string]$st.BackupDest }
    $repo = Get-ResticRepoPath $dest
    if (-not (Test-ResticRepo $repo)) { Write-WhLog (('' + [char]0x015E + 'ifreli depo yok: ') + $repo) 'WARN'; return @{ Ok = $true; Rows = @() } }
    $r = Invoke-Restic $exe @('snapshots', '--repo', $repo, '--json') ([string]$P.Password)
    if ($r.Code -ne 0) { Write-WhLog (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'mler okunamad' + [char]0x0131 + ': ') + (Get-ResticErrorText $r.Err $r.Code)) 'ERR'; return @{ Ok = $false; Rows = @() } }
    $rows = New-Object System.Collections.ArrayList
    try {
        $parsed = ($r.Lines -join "`n") | ConvertFrom-Json -ErrorAction Stop
        $arr = @($parsed)
        foreach ($s in $arr) {
            if ($null -eq $s) { continue }
            $tm = $null
            try { $tm = [datetime]::Parse([string]$s.time, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::RoundtripKind).ToLocalTime() } catch { }
            [void]$rows.Add(@{ Id = [string]$s.id; Short = [string]$s.short_id; Time = $tm; TimeText = $(if ($null -ne $tm) { $tm.ToString('yyyy-MM-dd HH:mm') } else { '' }); Host = [string]$s.hostname; Paths = (@($s.paths | ForEach-Object { [string]$_ }) -join ', ') })
        }
    } catch { Write-WhLog (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm listesi ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'lemedi: ') + $_.Exception.Message) 'ERR'; return @{ Ok = $false; Rows = @() } }
    $sorted = @($rows | Sort-Object { if ($null -ne $_.Time) { [datetime]$_.Time } else { [datetime]::MinValue } } -Descending)
    Write-WhLog (('Yedek s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ': ') + [string]$sorted.Count) 'INFO'
    return @{ Ok = $true; Rows = $sorted; Repo = $repo }
}

# P: Dest, Password, Snapshot (kimlik ya da latest), Target (bos bir klasor). Ozgun yerin uzerine yazmaz.
function Job_ResticRestore($P) {
    $exe = Find-Restic
    if ($exe -eq '') { Write-WhLog ('restic bulunamad' + [char]0x0131 + '.') 'ERR'; return @{ Ok = $false } }
    $st = Get-Settings
    $dest = [string]$P.Dest; if ($dest -eq '') { $dest = [string]$st.BackupDest }
    $repo = Get-ResticRepoPath $dest
    $snap = [string]$P.Snapshot
    $target = [string]$P.Target
    if ($snap -ne 'latest' -and $snap -notmatch '^[0-9a-f]{8,64}$') { Write-WhLog ('Ge' + [char]0x00E7 + 'ersiz s' + [char]0x00FC + 'r' + [char]0x00FC + 'm kimli' + [char]0x011F + 'i.') 'ERR'; return @{ Ok = $false } }
    if ($target -eq '' -or -not (Test-Path -LiteralPath $target -PathType Container)) { Write-WhLog ('Geri y' + [char]0x00FC + 'kleme klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' yok.') 'ERR'; return @{ Ok = $false } }
    $why = Test-SecureDeleteAllowed $target
    if ($why -ne '' -and $why -notmatch 'silinemez') { Write-WhLog $why 'ERR'; return @{ Ok = $false } }
    if (@(Get-ChildItem -LiteralPath $target -Force -ErrorAction SilentlyContinue).Count -gt 0) { Write-WhLog ('Geri y' + [char]0x00FC + 'kleme klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' bo' + [char]0x015F + ' olmal' + [char]0x0131 + ' (var olan dosyalar' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lmaz).') 'ERR'; return @{ Ok = $false } }
    if (-not (Test-ResticRepo $repo)) { Write-WhLog (('' + [char]0x015E + 'ifreli depo yok: ') + $repo) 'ERR'; return @{ Ok = $false } }
    Write-WhLog (('=== Geri y' + [char]0x00FC + 'kleniyor: ') + $snap + ('  ' + [char]0x2192 + '  ') + $target) 'STEP'
    Set-JobProgress 0 1 ('Geri y' + [char]0x00FC + 'kleniyor')
    $r = Invoke-Restic $exe @('restore', $snap, '--repo', $repo, '--target', $target) ([string]$P.Password)
    Set-JobProgress 1 1
    if ($r.Code -ne 0) { Write-WhLog (('Geri y' + [char]0x00FC + 'kleme ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + (Get-ResticErrorText $r.Err $r.Code)) 'ERR'; return @{ Ok = $false } }
    Write-WhLog ('Geri y' + [char]0x00FC + 'kleme tamamland' + [char]0x0131 + '.') 'OK'
    return @{ Ok = $true; Target = $target }
}

