# Arka plan isinin giris islevi -> gereken eklenti
$script:ExtOf = @{ 'Job_Crypt' = 'Sifreleme'; 'Job_MemTrim' = 'Bellek'; 'Job_SecureDelete' = 'GuvenliSilme'; 'Job_BlOp' = 'DiskKoruma'; 'Job_RecoverScan' = 'Kurtarma'; 'Job_RecoverParts' = 'Kurtarma'; 'Job_RecoverFiles' = 'Kurtarma'; 'Job_WipeFree' = 'DiskSilme'; 'Job_WipeRaw' = 'DiskSilme'; 'Job_TrimVolume' = 'DiskSilme' }
$script:ExtState = @{}

function Get-AppFolder {
    $p = ''
    try { $p = [string]$sync.ScriptPath } catch { }
    if ([string]::IsNullOrEmpty($p)) { return '' }
    try { return [System.IO.Path]::GetDirectoryName($p) } catch { return '' }
}

function Get-TextSha256([string]$Text) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $b = $null
    try { $b = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Text)) } finally { $sha.Dispose() }
    return (([System.BitConverter]::ToString($b)) -replace '-', '').ToLowerInvariant()
}

# Rel: 'veri/oui.txt' gibi. Satir sonlari (CRLF / LF) ozeti etkilemez.
# Donus: @{ Ok; Text; Error; Kind }   Kind: 'missing' | 'read' | 'hash' | ''
function Get-PackFileText([string]$Rel) {
    $dir = Get-AppFolder
    if ($dir -eq '') { return @{ Ok = $false; Text = ''; Error = ('Beti' + [char]0x011F + 'in klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' bilinmiyor.'); Kind = 'missing' } }
    $sep = [string][System.IO.Path]::DirectorySeparatorChar
    $path = [System.IO.Path]::Combine($dir, $Rel.Replace('/', $sep))
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        return @{ Ok = $false; Text = ''; Error = (('' + [char]0x201C + '') + $Rel + ('' + [char]0x201D + ' bulunamad' + [char]0x0131 + '. ZIP dosyas' + [char]0x0131 + 'n' + [char]0x0131 + 'n tamam' + [char]0x0131 + 'n' + [char]0x0131 + ' bir klas' + [char]0x00F6 + 're ' + [char]0x00E7 + '' + [char]0x0131 + 'kart' + [char]0x0131 + 'p Multimizer.ps1 ile yan yana b' + [char]0x0131 + 'rak' + [char]0x0131 + 'n.')); Kind = 'missing' }
    }
    $txt = ''
    try { $txt = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8) }
    catch { return @{ Ok = $false; Text = ''; Error = (('' + [char]0x201C + '') + $Rel + ('' + [char]0x201D + ' okunamad' + [char]0x0131 + ': ') + $_.Exception.Message); Kind = 'read' } }
    $want = ''
    if ($script:PackHash.ContainsKey($Rel)) { $want = [string]$script:PackHash[$Rel] }
    $got = Get-TextSha256 ($txt.Replace("`r`n", "`n"))
    if ($want -eq '' -or $got -ne $want) {
        return @{ Ok = $false; Text = ''; Error = (('' + [char]0x201C + '') + $Rel + ('' + [char]0x201D + ' bu Multimizer s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'yle uyu' + [char]0x015F + 'muyor ya da de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmi' + [char]0x015F + '. ZIP dosyas' + [char]0x0131 + 'n' + [char]0x0131 + ' yeniden ' + [char]0x00E7 + '' + [char]0x0131 + 'kart' + [char]0x0131 + 'n.')); Kind = 'hash' }
    }
    return @{ Ok = $true; Text = $txt; Error = ''; Kind = '' }
}

# Eklentiyi yuklemeden dosyanin yerinde ve dogru olup olmadigina bakar ('' = sorun yok)
function Get-ExtProblem([string]$Name) {
    $r = Get-PackFileText ('Eklenti/' + $Name + '.ps1')
    if ($r.Ok -eq $true) { return '' }
    return [string]$r.Error
}

function Test-AvBlockText([string]$Text) {
    return ($Text -match ('(?i)malicious|antivirus|ScriptContained|zararl|vir[u' + [char]0x00FC + ']s'))
}

# Eklentiyi bu oturuma yukler. Eklentideki islevler "global:" ile tanimlanir; boylece nereden yuklenirse yuklensin kalir.
# Sonuc oturum boyunca saklanir: engellenen bir eklenti her tiklamada yeniden denenmez (guvenlik yazilimi her seferinde uyarmasin).
function Import-MmExt([string]$Name) {
    if ($script:ExtState.ContainsKey($Name)) { return $script:ExtState[$Name] }
    $res = @{ Ok = $false; Error = ''; Blocked = $false }
    $r = Get-PackFileText ('Eklenti/' + $Name + '.ps1')
    if ($r.Ok -ne $true) {
        $res.Error = [string]$r.Error
    } else {
        try {
            $sb = [scriptblock]::Create([string]$r.Text)
            . $sb
            $res.Ok = $true
        } catch {
            $all = [string]$_.Exception.Message + ' ' + [string]$_.FullyQualifiedErrorId
            try { if ($null -ne $_.Exception.InnerException) { $all += ' ' + [string]$_.Exception.InnerException.Message } } catch { }
            if (Test-AvBlockText $all) {
                $res.Blocked = $true
                $res.Error = (('Windows Defender (AMSI) ' + [char]0x201C + '') + $Name + ('' + [char]0x201D + ' eklentisini engelledi, bu ' + [char]0x00F6 + 'zellik kullan' + [char]0x0131 + 'lamayacak; uygulaman' + [char]0x0131 + 'n geri kalan' + [char]0x0131 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r. Engelin ad' + [char]0x0131 + 'n' + [char]0x0131 + ' Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i > Vir' + [char]0x00FC + 's ve tehdit korumas' + [char]0x0131 + ' > Koruma ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nde g' + [char]0x00F6 + 'rebilirsiniz. Dosyaya g' + [char]0x00FC + 'veniyorsan' + [char]0x0131 + 'z orada ' + [char]0x201C + 'Cihazda izin ver' + [char]0x201D + ' diyebilir ya da Microsoft' + [char]0x2019 + 'a yanl' + [char]0x0131 + '' + [char]0x015F + ' tespit olarak bildirebilirsiniz.'))
            } else {
                $res.Error = (('Eklenti y' + [char]0x00FC + 'klenemedi (') + $Name + '): ' + [string]$_.Exception.Message)
            }
        }
    }
    $script:ExtState[$Name] = $res
    return $res
}

# Bir arka plan isinin eklentisi varsa yukler. '' = devam edilebilir, baska bir sey = isi baslatma nedeni
function Get-ExtError([string]$Entry) {
    if (-not $script:ExtOf.ContainsKey($Entry)) { return '' }
    $r = Import-MmExt ([string]$script:ExtOf[$Entry])
    if ($r.Ok -eq $true) { return '' }
    return [string]$r.Error
}

# ---------------- supheli komut kaliplari (veri\supheli-komutlar.txt) ----------------
$script:SusRx = $null
function Get-SuspiciousCmdRegex {
    if ($null -ne $script:SusRx) { return [string]$script:SusRx }
    # Dosya yoksa ya da ozeti tutmuyorsa yalnizca en belirgin kalip aranir
    $rx = '(?i)\s-e(nc|ncodedcommand)?\s+[A-Za-z0-9+/=]{24,}'
    try {
        $r = Get-PackFileText 'veri/supheli-komutlar.txt'
        if ($r.Ok -eq $true) {
            $parts = New-Object System.Collections.ArrayList
            foreach ($ln in $r.Text.Split("`n")) {
                $t = $ln.Trim()
                if ($t -eq '' -or $t.StartsWith('#')) { continue }
                [void]$parts.Add('(?:' + $t + ')')
            }
            if ($parts.Count -gt 0) { $rx = '(?i)' + ($parts.ToArray() -join '|') }
        } else {
            Write-WhLog (('' + [char]0x015E + '' + [char]0x00FC + 'pheli komut kurallar' + [char]0x0131 + ' y' + [char]0x00FC + 'klenemedi, k' + [char]0x0131 + 's' + [char]0x0131 + 'tl' + [char]0x0131 + ' kural kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'yor. ') + [string]$r.Error) 'WARN'
        }
    } catch { }
    $script:SusRx = $rx
    return $rx
}

