function Get-PwDef([string]$Key) {
    foreach ($d in $script:PwSet) { if ([string]$d.K -eq $Key) { return $d } }
    return $null
}

function Get-PwList {
    $txt = ''
    try { $txt = (& powercfg.exe /list 2>&1 | Out-String) } catch { }
    $rows = New-Object System.Collections.ArrayList
    foreach ($ln in ($txt -split "\r?\n")) {
        $m = [regex]::Match($ln, '(' + $script:GuidRx + ')\s+\((.*)\)\s*(\*)?\s*$')
        if (-not $m.Success) { continue }
        $star = ($m.Groups[3].Success -and $m.Groups[3].Value -eq '*')
        [void]$rows.Add(@{ Guid = $m.Groups[1].Value.ToLowerInvariant(); Name = $m.Groups[2].Value.Trim(); Active = $star })
    }
    return $rows.ToArray()
}

function Get-PwActive {
    $txt = ''
    try { $txt = (& powercfg.exe /getactivescheme 2>&1 | Out-String) } catch { }
    $m = [regex]::Match($txt, '(' + $script:GuidRx + ')\s*(?:\((.*?)\))?')
    if (-not $m.Success) { return @{ Guid = ''; Name = '' } }
    return @{ Guid = $m.Groups[1].Value.ToLowerInvariant(); Name = $m.Groups[2].Value.Trim() }
}

# Anahtar (Balanced / High ... ya da GUID) icin bu bilgisayardaki plan; yoksa $null
function Find-PwScheme([string]$Key, $List) {
    $gid = ''
    if ($script:PwKnown.Contains($Key)) { $gid = [string]$script:PwKnown[$Key].Guid }
    elseif ($Key -match ('^' + $script:GuidRx + '$')) { $gid = $Key.ToLowerInvariant() }
    foreach ($p in @($List)) { if ($gid -ne '' -and [string]$p.Guid -eq $gid) { return $p } }
    if ($script:PwKnown.Contains($Key)) {
        foreach ($p in @($List)) { if ([string]$p.Name -match [string]$script:PwKnown[$Key].Rx) { return $p } }
    }
    return $null
}

function Get-PwName([string]$Key, $List) {
    $p = Find-PwScheme $Key $List
    if ($null -ne $p) { return [string]$p.Name }
    if ($script:PwKnown.Contains($Key)) { return [string]$script:PwKnown[$Key].Name }
    return $Key
}

# powercfg /query ciktisinin son iki onaltilik degeri: fiste, pilde (dile bagli degildir)
function Get-PwValue([string]$Scheme, $Def) {
    $t = ''
    try { $t = (& powercfg.exe /query $Scheme ([string]$Def.Sub) ([string]$Def.Id) 2>&1 | Out-String) } catch { return $null }
    $m = [regex]::Matches($t, '0x[0-9a-fA-F]{1,8}\b')
    if ($m.Count -lt 2) { return $null }
    $ac = [Convert]::ToInt64($m[$m.Count - 2].Value.Substring(2), 16)
    $dc = [Convert]::ToInt64($m[$m.Count - 1].Value.Substring(2), 16)
    return @{ Ac = $ac; Dc = $dc }
}

function Get-PwSnapshot([string]$Scheme) {
    $snap = @{}
    if ($Scheme -eq '') { return $snap }
    foreach ($d in $script:PwSet) {
        $v = Get-PwValue $Scheme $d
        if ($null -ne $v) { $snap[[string]$d.K] = $v }
    }
    return $snap
}

function Format-PwValue($Def, $V) {
    if ($null -eq $V) { return '?' }
    $n = [int64]$V
    switch ([string]$Def.U) {
        'sec' {
            if ($n -le 0 -or $n -ge 2147483647) { return ('Hi' + [char]0x00E7 + 'bir zaman') }
            if ($n -lt 60) { return ([string]$n + ' sn') }
            if ($n -lt 3600) { return ([string][int][math]::Round($n / 60.0) + ' dk') }
            return ([string][math]::Round($n / 3600.0, 1) + ' sa')
        }
        'pct' { return (Format-Percent $n) }
        default {
            if ($null -ne $Def.O -and $Def.O.ContainsKey([int]$n)) { return [string]$Def.O[[int]$n] }
            return (('de' + [char]0x011F + 'er ') + [string]$n)
        }
    }
}

# Iki goruntu arasindaki farklar: @{ K; Label; AcFrom; AcTo; DcFrom; DcTo; Text }
function Compare-PwSnapshot($From, $To) {
    $rows = New-Object System.Collections.ArrayList
    foreach ($d in $script:PwSet) {
        $k = [string]$d.K
        if (-not $To.ContainsKey($k)) { continue }
        $a = $null; if ($From.ContainsKey($k)) { $a = $From[$k] }
        $b = $To[$k]
        $acSame = ($null -ne $a -and [int64]$a.Ac -eq [int64]$b.Ac)
        $dcSame = ($null -ne $a -and [int64]$a.Dc -eq [int64]$b.Dc)
        if ($acSame -and $dcSame) { continue }
        $fromAc = $null; $fromDc = $null
        if ($null -ne $a) { $fromAc = $a.Ac; $fromDc = $a.Dc }
        $parts = @()
        if (-not $acSame) { $parts += (('fi' + [char]0x015F + 'te: ') + (Format-PwValue $d $fromAc) + (' ' + [char]0x2192 + ' ') + (Format-PwValue $d $b.Ac)) }
        if (-not $dcSame) { $parts += ('pilde: ' + (Format-PwValue $d $fromDc) + (' ' + [char]0x2192 + ' ') + (Format-PwValue $d $b.Dc)) }
        [void]$rows.Add(@{ K = $k; Label = [string]$d.L; Parts = ($parts -join '; '); Text = ([string]$d.L + ' (' + ($parts -join '; ') + ')') })
    }
    return $rows.ToArray()
}

# Ozel plan adi: yalnizca harf, rakam, bosluk ve - _ . ( )  (en cok 40 karakter)
function Get-PwSafeName([string]$Name) {
    $n = ([string]$Name).Trim()
    $n = [regex]::Replace($n, '[^\p{L}\p{Nd} _\-\.\(\)]', '')
    if ($n.Length -gt 40) { $n = $n.Substring(0, 40).Trim() }
    if ($n -eq '') { $n = ('' + [char]0x00D6 + 'zel plan') }
    return $n
}

function Get-PwUniqueName([string]$Name, $List) {
    $base = Get-PwSafeName $Name
    $used = @(@($List) | ForEach-Object { ([string]$_.Name).ToLowerInvariant() })
    if ($used -notcontains $base.ToLowerInvariant()) { return $base }
    for ($i = 2; $i -lt 100; $i++) {
        $c = $base + ' (' + [string]$i + ')'
        if ($used -notcontains $c.ToLowerInvariant()) { return $c }
    }
    return ($base + ' ' + (Get-Date -Format 'HHmmss'))
}

# Windows'un yerlesik planini (Yuksek / Nihai / Dengeli / Tasarruf) bu bilgisayarda yoksa olusturur
function New-PwBuiltin([string]$Key) {
    if (-not $script:PwKnown.Contains($Key)) { return $null }
    $gid = [string]$script:PwKnown[$Key].Guid
    $out = ''
    try { $out = (& powercfg.exe /duplicatescheme $gid $gid 2>&1 | Out-String) } catch { }
    $m = [regex]::Match($out, $script:GuidRx)
    if ($LASTEXITCODE -ne 0 -or -not $m.Success) {
        try { $out = (& powercfg.exe /duplicatescheme $gid 2>&1 | Out-String) } catch { }
        $m = [regex]::Match($out, $script:GuidRx)
    }
    if (-not $m.Success) { return $null }
    $p = @{ Guid = $m.Value.ToLowerInvariant(); Name = [string]$script:PwKnown[$Key].Name; Active = $false }
    foreach ($q in (Get-PwList)) { if ([string]$q.Guid -eq [string]$p.Guid) { $p.Name = [string]$q.Name } }
    return $p
}

# ---------------- islemler (plan adimlari) ----------------
# Op: @{ T = 'PowerSet'; Key = 'High' | GUID }
function Invoke-PowerSetOp($Op) {
    $key = [string]$Op.Key
    if (Test-PwUseMode $key) { Invoke-PowerModeOp $key; return }
    $act = Get-PwActive
    $list = @(Get-PwList)
    if ($key -eq 'Best') {
        # Oyun kipi: Nihai performans; bu bilgisayarda olusturulamiyorsa Yuksek performans
        $key = 'Ultimate'
        if ($null -eq (Find-PwScheme 'Ultimate' $list) -and -not $script:Preview) {
            if ($null -eq (New-PwBuiltin 'Ultimate')) { $key = 'High' }
            $list = @(Get-PwList)
        }
    }
    $tg = Find-PwScheme $key $list
    $label = Get-PwName $key $list
    if ($null -ne $tg -and [string]$tg.Guid -eq [string]$act.Guid) { Add-Skip (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' zaten ') + $label); return }
    if ($script:Preview) {
        Add-Plan (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ': ') + [string]$act.Name + (' ' + [char]0x2192 + ' ') + $label)
        if ($null -ne $tg) {
            foreach ($d in (Compare-PwSnapshot (Get-PwSnapshot ([string]$act.Guid)) (Get-PwSnapshot ([string]$tg.Guid)))) { Add-Plan ('   ' + [string]$d.Text) }
        } else {
            Add-Plan ('   (' + $label + (' plan' + [char]0x0131 + ' bu bilgisayarda hen' + [char]0x00FC + 'z yok; uygulan' + [char]0x0131 + 'rken Windows' + [char]0x2019 + 'un yerle' + [char]0x015F + 'ik ' + [char]0x015F + 'ablonundan olu' + [char]0x015F + 'turulur)'))
        }
        return
    }
    $created = ''
    if ($null -eq $tg) { $tg = New-PwBuiltin $key; if ($null -ne $tg) { $created = [string]$tg.Guid } }
    if ($null -eq $tg) { throw ($label + (' plan' + [char]0x0131 + ' olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ' (bu bilgisayarda desteklenmiyor olabilir; Modern Bekleme).')) }
    Add-Journal @{ T = 'Power'; Guid = [string]$act.Guid; Created = $created }
    & powercfg.exe /setactive ([string]$tg.Guid) | Out-Null
    if ($LASTEXITCODE -ne 0) { throw ('powercfg /setactive ' + [string]$tg.Guid + (' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z')) }
    Add-Done (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ': ') + [string]$tg.Name)
}

# Op: @{ T = 'PowerCustom'; Name; Base = 'Balanced' | GUID; Values = @{ CpuMax = @{ Ac; Dc } ... }; Activate = $true }
function Invoke-PowerCustomOp($Op) {
    $list = @(Get-PwList)
    $act = Get-PwActive
    $name = Get-PwUniqueName ([string]$Op.Name) $list
    $baseKey = [string]$Op.Base
    $base = Find-PwScheme $baseKey $list
    $vals = $Op['Values']
    $keys = @()
    if ($vals -is [hashtable]) { $keys = @($script:PwSet | Where-Object { $vals.ContainsKey([string]$_.K) } | ForEach-Object { [string]$_.K }) }
    if ($script:Preview) {
        Add-Plan (('' + [char]0x00D6 + 'zel g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' olu' + [char]0x015F + 'turulacak: ' + [char]0x201C + '') + $name + ('' + [char]0x201D + ' (taban: ') + (Get-PwName $baseKey $list) + ')')
        foreach ($k in $keys) {
            $d = Get-PwDef $k; $v = $vals[$k]
            $parts = @()
            if ($null -ne $v.Ac) { $parts += (('fi' + [char]0x015F + 'te ') + (Format-PwValue $d $v.Ac)) }
            if ($null -ne $v.Dc) { $parts += ('pilde ' + (Format-PwValue $d $v.Dc)) }
            Add-Plan ('   ' + [string]$d.L + ': ' + ($parts -join ', '))
        }
        if ($Op.Activate -eq $true) { Add-Plan ('   Olu' + [char]0x015F + 'turulunca etkinle' + [char]0x015F + 'tirilecek') }
        return
    }
    if ($null -eq $base) { $base = New-PwBuiltin $baseKey }
    if ($null -eq $base) { throw (('Taban plan bulunamad' + [char]0x0131 + ': ') + $baseKey) }
    $out = (& powercfg.exe /duplicatescheme ([string]$base.Guid) 2>&1 | Out-String)
    $m = [regex]::Match($out, $script:GuidRx)
    if (-not $m.Success) { throw ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' kopyalanamad' + [char]0x0131 + '.') }
    $new = $m.Value.ToLowerInvariant()
    Add-Journal @{ T = 'PowerNew'; Guid = $new; Prev = [string]$act.Guid; Name = $name }
    & powercfg.exe /changename $new $name (('Multimizer ile olu' + [char]0x015F + 'turuldu')) | Out-Null
    foreach ($k in $keys) {
        $d = Get-PwDef $k; $v = $vals[$k]
        if ($null -ne $v.Ac) { & powercfg.exe /setacvalueindex $new ([string]$d.Sub) ([string]$d.Id) ([string][int64]$v.Ac) | Out-Null }
        if ($null -ne $v.Dc) { & powercfg.exe /setdcvalueindex $new ([string]$d.Sub) ([string]$d.Id) ([string][int64]$v.Dc) | Out-Null }
    }
    if ($Op.Activate -eq $true) {
        & powercfg.exe /setactive $new | Out-Null
        if ($LASTEXITCODE -ne 0) { throw ('Yeni plan etkinle' + [char]0x015F + 'tirilemedi.') }
    }
    Add-Done (('' + [char]0x00D6 + 'zel g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' olu' + [char]0x015F + 'turuldu: ') + $name + $(if ($Op.Activate -eq $true) { ' (etkin)' } else { '' }))
}

function Undo-PowerNewItem($It) {
    $act = Get-PwActive
    if ([string]$act.Guid -eq [string]$It.Guid) {
        $to = [string]$It.Prev
        if ($to -eq '' -or $to -eq [string]$It.Guid) { $to = [string]$script:PwKnown.Balanced.Guid }
        & powercfg.exe /setactive $to | Out-Null
    }
    & powercfg.exe /delete ([string]$It.Guid) | Out-Null
    Add-Done (('' + [char]0x00D6 + 'zel g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' silindi: ') + [string]$It.Name)
}

# Op: @{ T = 'PowerDelete'; Guid }  (yerlesik planlar silinmez; silinen planin disa aktarimi saklanir)
function Invoke-PowerDeleteOp($Op) {
    $gid = ([string]$Op.Guid).ToLowerInvariant()
    foreach ($k in $script:PwKnown.Keys) { if ([string]$script:PwKnown[$k].Guid -eq $gid) { Add-Skip ('Windows' + [char]0x2019 + 'un yerle' + [char]0x015F + 'ik planlar' + [char]0x0131 + ' silinmez.'); return } }
    $list = @(Get-PwList)
    $p = Find-PwScheme $gid $list
    if ($null -eq $p) { Add-Skip ('Plan bulunamad' + [char]0x0131 + '.'); return }
    if ($script:Preview) { Add-Plan (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' silinecek: ') + [string]$p.Name + (' (' + [char]0x00F6 + 'nce yede' + [char]0x011F + 'i al' + [char]0x0131 + 'n' + [char]0x0131 + 'r)')); return }
    $file = Join-Path $sync.BackupDir ('guc-plani-' + $gid + '.pow')
    & powercfg.exe /export $file $gid | Out-Null
    if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $file)) { throw ('Plan yede' + [char]0x011F + 'i al' + [char]0x0131 + 'namad' + [char]0x0131 + '; silinmedi.') }
    $wasActive = ([string](Get-PwActive).Guid -eq $gid)
    Add-Journal @{ T = 'PowerDel'; Guid = $gid; File = $file; Name = [string]$p.Name; WasActive = $wasActive }
    if ($wasActive) { & powercfg.exe /setactive ([string]$script:PwKnown.Balanced.Guid) | Out-Null }
    & powercfg.exe /delete $gid | Out-Null
    Add-Done (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' silindi: ') + [string]$p.Name)
}

function Undo-PowerDelItem($It) {
    if (-not (Test-Path -LiteralPath ([string]$It.File))) { throw ('Plan yede' + [char]0x011F + 'i bulunamad' + [char]0x0131 + '.') }
    & powercfg.exe /import ([string]$It.File) ([string]$It.Guid) | Out-Null
    if ([bool]$It.WasActive) { & powercfg.exe /setactive ([string]$It.Guid) | Out-Null }
    Add-Done (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' geri getirildi: ') + [string]$It.Name)
}

# Sicaklik korumasi vb. icin: etkin plandaki islemci ust sinirini degistirir (Value: yuzde, fiste ve pilde)
# Op: @{ T = 'PowerCpuMax'; Value = 80 }
function Limit-PwPct($V) {
    $n = [int]$V
    if ($n -lt 30) { $n = 30 }
    if ($n -gt 100) { $n = 100 }
    return $n
}

# Op: @{ T = 'PowerCpuMax'; Value = 80 }  ya da  @{ T = 'PowerCpuMax'; Ac = 100; Dc = 90 }  (en az %30)
function Invoke-PowerCpuMaxOp($Op) {
    $ac = 100; $dc = 100
    if ($null -ne $Op.Value) { $ac = Limit-PwPct $Op.Value; $dc = $ac }
    if ($null -ne $Op.Ac) { $ac = Limit-PwPct $Op.Ac }
    if ($null -ne $Op.Dc) { $dc = Limit-PwPct $Op.Dc }
    $act = Get-PwActive
    if ([string]$act.Guid -eq '') { throw ('Etkin g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' okunamad' + [char]0x0131 + '.') }
    $d = Get-PwDef 'CpuMax'
    $cur = Get-PwValue ([string]$act.Guid) $d
    $txt = (Format-Percent $ac)
    if ($dc -ne $ac) { $txt = (('fi' + [char]0x015F + 'te %') + [string]$ac + ', pilde %' + [string]$dc) }
    if ($null -ne $cur -and [int64]$cur.Ac -eq $ac -and [int64]$cur.Dc -eq $dc) { Add-Skip (('' + [char]0x0130 + '' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' zaten ') + $txt); return }
    if ($script:Preview) { Add-Plan (('' + [char]0x0130 + '' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' ') + $txt + (' yap' + [char]0x0131 + 'lacak (etkin plan: ') + [string]$act.Name + ')'); return }
    if ($null -ne $cur) { Add-Journal @{ T = 'PowerCpuMax'; Guid = [string]$act.Guid; Ac = [int64]$cur.Ac; Dc = [int64]$cur.Dc } }
    & powercfg.exe /setacvalueindex ([string]$act.Guid) ([string]$d.Sub) ([string]$d.Id) ([string]$ac) | Out-Null
    & powercfg.exe /setdcvalueindex ([string]$act.Guid) ([string]$d.Sub) ([string]$d.Id) ([string]$dc) | Out-Null
    & powercfg.exe /setactive ([string]$act.Guid) | Out-Null
    Add-Done (('' + [char]0x0130 + '' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' ') + $txt + (' yap' + [char]0x0131 + 'ld' + [char]0x0131 + ''))
}

function Undo-PowerCpuMaxItem($It) {
    $d = Get-PwDef 'CpuMax'
    & powercfg.exe /setacvalueindex ([string]$It.Guid) ([string]$d.Sub) ([string]$d.Id) ([string][int64]$It.Ac) | Out-Null
    & powercfg.exe /setdcvalueindex ([string]$It.Guid) ([string]$d.Sub) ([string]$d.Id) ([string][int64]$It.Dc) | Out-Null
    if ([string](Get-PwActive).Guid -eq [string]$It.Guid) { & powercfg.exe /setactive ([string]$It.Guid) | Out-Null }
    Add-Done ('' + [char]0x0130 + '' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' eski de' + [char]0x011F + 'erine d' + [char]0x00F6 + 'nd' + [char]0x00FC + '')
}

