function New-PowerSetSteps([string]$Key, [string]$Label = '') {
    $lbl = $Label
    if ($lbl -eq '') {
        $lbl = $Key
        if ($script:PwKnown.Contains($Key)) { $lbl = [string]$script:PwKnown[$Key].Name }
        if ($Key -eq 'Best') { $lbl = 'Nihai performans' }
    }
    return @(@{ Id = ('power.' + $Key); Title = (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ': ') + $lbl); Ops = @(@{ T = 'PowerSet'; Key = $Key }); Reboot = $false })
}

function New-PowerCustomSteps([string]$Name, [string]$Base, $Values, [bool]$Activate) {
    $op = @{ T = 'PowerCustom'; Name = $Name; Base = $Base; Values = $Values; Activate = $Activate }
    return @(@{ Id = 'power.custom'; Title = (('' + [char]0x00D6 + 'zel g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ': ') + (Get-PwSafeName $Name)); Ops = @($op); Reboot = $false })
}

# ---------------- canli guc durumu ----------------
$script:PwFormsOk = $false
function Get-PwLive {
    $r = @{ HasBattery = $false; Online = $true; Percent = -1; Minutes = -1; Charging = $false; Source = '' }
    try {
        if (-not $script:PwFormsOk) { Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop; $script:PwFormsOk = $true }
        $ps = [System.Windows.Forms.SystemInformation]::PowerStatus
        $r.Online = ([string]$ps.PowerLineStatus -eq 'Online')
        $bcs = [string]$ps.BatteryChargeStatus
        $r.HasBattery = ($bcs -notmatch 'NoSystemBattery')
        if ($r.HasBattery) {
            $pct = [double]$ps.BatteryLifePercent
            if ($pct -ge 0 -and $pct -le 1.0) { $r.Percent = [int][math]::Round($pct * 100.0) }
            $sec = [int]$ps.BatteryLifeRemaining
            if ($sec -gt 0) { $r.Minutes = [int][math]::Round($sec / 60.0) }
            $r.Charging = ($bcs -match 'Charging')
        }
        $r.Source = 'SystemInformation'
        return $r
    } catch { }
    try {
        $b = @(Get-CimInstance -ClassName Win32_Battery -ErrorAction Stop)
        if ($b.Count -gt 0) {
            $r.HasBattery = $true
            $r.Percent = [int]$b[0].EstimatedChargeRemaining
            $r.Online = ([int]$b[0].BatteryStatus -ne 1)
            $r.Charging = ([int]$b[0].BatteryStatus -eq 2)
            $rt = [int64]$b[0].EstimatedRunTime
            if ($rt -gt 0 -and $rt -lt 71582788) { $r.Minutes = [int]$rt }
        }
        $r.Source = 'Win32_Battery'
    } catch { }
    return $r
}

# Pil asinmasi: tasarim kapasitesi ile su anki tam dolum kapasitesi (root\wmi; yoksa $null)
function Get-PwBatteryWear {
    try {
        $full = @(Get-CimInstance -Namespace 'root/wmi' -ClassName 'BatteryFullChargedCapacity' -ErrorAction Stop)
        if ($full.Count -eq 0) { return $null }
        $stat = @(Get-CimInstance -Namespace 'root/wmi' -ClassName 'BatteryStaticData' -ErrorAction Stop)
        if ($stat.Count -eq 0) { return $null }
        $f = [double]$full[0].FullChargedCapacity
        $d = [double]$stat[0].DesignedCapacity
        if ($d -le 0 -or $f -le 0) { return $null }
        $wear = [math]::Round(100.0 * (1.0 - [math]::Min(1.0, $f / $d)), 1)
        $cyc = -1
        try { $cc = @(Get-CimInstance -Namespace 'root/wmi' -ClassName 'BatteryCycleCount' -ErrorAction Stop); if ($cc.Count -gt 0) { $cyc = [int]$cc[0].CycleCount } } catch { }
        return @{ Design = [int]$d; Full = [int]$f; Wear = $wear; Cycles = $cyc }
    } catch { return $null }
}

# Guc sayfasinin tek seferde okudugu her sey (sistemi degistirmez)
function Job_PowerInfo($P) {
    $list = @(Get-PwList)
    $act = Get-PwActive
    $snap = Get-PwSnapshot ([string]$act.Guid)
    $known = @{}
    foreach ($k in $script:PwKnown.Keys) {
        $sch = Find-PwScheme ([string]$k) $list
        $known[[string]$k] = ($null -ne $sch)
    }
    return @{ Plans = $list; Active = $act; Snap = $snap; Live = (Get-PwLive); Wear = (Get-PwBatteryWear); Known = $known; Time = (Get-Date); Mode = (Get-PwModeInfo) }
}

# Bir planin (ya da ozel degerlerin) etkin plana gore farklari
# P: Key (Balanced | GUID) ya da Base + Values
function Job_PowerPreview($P) {
    $list = @(Get-PwList)
    $act = Get-PwActive
    $cur = Get-PwSnapshot ([string]$act.Guid)
    $to = @{}
    $note = ''
    if ($null -ne $P['Values']) {
        $baseKey = [string]$P.Base
        $b = Find-PwScheme $baseKey $list
        if ($null -ne $b) { $to = Get-PwSnapshot ([string]$b.Guid) } else { $note = ('Taban plan bu bilgisayarda hen' + [char]0x00FC + 'z yok; farklar yakla' + [char]0x015F + '' + [char]0x0131 + 'k g' + [char]0x00F6 + 'sterilir.') }
        $vals = $P['Values']
        foreach ($d in $script:PwSet) {
            $k = [string]$d.K
            if (-not $vals.ContainsKey($k)) { continue }
            $o = @{ Ac = 0; Dc = 0 }
            if ($to.ContainsKey($k)) { $o = @{ Ac = $to[$k].Ac; Dc = $to[$k].Dc } }
            elseif ($cur.ContainsKey($k)) { $o = @{ Ac = $cur[$k].Ac; Dc = $cur[$k].Dc } }
            if ($null -ne $vals[$k].Ac) { $o.Ac = [int64]$vals[$k].Ac }
            if ($null -ne $vals[$k].Dc) { $o.Dc = [int64]$vals[$k].Dc }
            $to[$k] = $o
        }
    } else {
        $t = Find-PwScheme ([string]$P.Key) $list
        if ($null -eq $t) { $note = ((Get-PwName ([string]$P.Key) $list) + (' plan' + [char]0x0131 + ' bu bilgisayarda hen' + [char]0x00FC + 'z yok; uygulan' + [char]0x0131 + 'rken Windows' + [char]0x2019 + 'un yerle' + [char]0x015F + 'ik ' + [char]0x015F + 'ablonundan olu' + [char]0x015F + 'turulur.')) }
        else { $to = Get-PwSnapshot ([string]$t.Guid) }
    }
    $diff = @(Compare-PwSnapshot $cur $to)
    return @{ Diff = $diff; Note = $note; Active = [string]$act.Name }
}

# Dile bagli olmayan ham cikti: bu bilgisayarin destekledigi uyku durumlari
function Job_PowerStates($P) {
    $t = ''
    try { $t = (& powercfg.exe /a 2>&1 | Out-String) } catch { }
    return @{ Text = $t.Trim() }
}

# Enerji verimliligi raporu (yaklasik 15 saniye gozlem yapar)
function Invoke-EnergyReportAction($P) {
    $f = Join-Path ([string]$sync.ReportDir) ('enerji-raporu-' + (Get-Date -Format 'yyyyMMdd-HHmm') + '.html')
    Write-WhLog ('Enerji raporu haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor (yakla' + [char]0x015F + '' + [char]0x0131 + 'k 15 saniye; bu s' + [char]0x0131 + 'rada bilgisayar' + [char]0x0131 + ' kullanmay' + [char]0x0131 + 'n)...') 'INFO'
    $o = & powercfg.exe /energy /output $f /duration 15 2>&1
    if (Test-Path -LiteralPath $f) { Write-WhLog (('Enerji raporu haz' + [char]0x0131 + 'r: ') + $f) 'OK'; try { Start-Process -FilePath $f } catch { } }
    else { throw (('Enerji raporu olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + (($o | Out-String).Trim())) }
}
$script:ExtraActions['EnergyReport'] = 'Invoke-EnergyReportAction'

# ---------------- Oyun ----------------
# ==================================================================
#  OYUN: yuklu oyunlari bulma (Steam, Epic, GOG, elle eklenen), calisan oyun algisi, oyun basina ayarlar
#  Hicbir oyun dosyasina dokunulmaz; yalnizca Windows'un kendi oyun/grafik tercihleri yazilir, gunluge kaydedilir ve geri alinir.
# ==================================================================
$script:GmBadExe = '(?i)unins|uninst|crash|report|redist|vcredist|vc_redist|dxsetup|dotnet|setup|install|helper|updater|webhelper|anticheat|easyanticheat|eac_|battleye|beservice|prereq|cefsub|qtwebengine|ue4prereq|notification|bootstrap'
$script:GmSkipApp = '(?i)^steamworks common|^steam linux runtime|^proton |^steam controller|^steamvr|^wallpaper engine$|^steam client'
$script:GmFsoFlag = 'DISABLEDXMAXIMIZEDWINDOWEDMODE'
$script:GmGpuKey = 'HKCU\Software\Microsoft\DirectX\UserGpuPreferences'
$script:GmLayersKey = 'HKCU\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers'

function Get-GmSteamLibraries {
    $root = ''
    foreach ($pair in @(@('HKLM\SOFTWARE\WOW6432Node\Valve\Steam', 'InstallPath'), @('HKLM\SOFTWARE\Valve\Steam', 'InstallPath'), @('HKCU\Software\Valve\Steam', 'SteamPath'))) {
        $v = [string](Get-RegValue $pair[0] $pair[1] '')
        if ($v -ne '') { $root = $v; if ($v -cmatch '^[A-Za-z]:/') { $root = $v.Replace('/', '\') }; break }
    }
    $libs = New-Object System.Collections.ArrayList
    if ($root -eq '' -or -not (Test-Path -LiteralPath $root -PathType Container)) { return $libs.ToArray() }
    [void]$libs.Add($root)
    $vdf = Join-Path $root 'steamapps\libraryfolders.vdf'
    if (Test-Path -LiteralPath $vdf -PathType Leaf) {
        $txt = ''
        try { $txt = [System.IO.File]::ReadAllText($vdf) } catch { }
        foreach ($m in [regex]::Matches($txt, '"path"\s+"([^"]+)"')) {
            $p = $m.Groups[1].Value.Replace('\\', '\')
            if ($p -ne '' -and (Test-Path -LiteralPath $p -PathType Container) -and -not ($libs -contains $p)) { [void]$libs.Add($p) }
        }
    }
    return $libs.ToArray()
}

function Get-GmSteamGames {
    $out = New-Object System.Collections.ArrayList
    foreach ($lib in (Get-GmSteamLibraries)) {
        $sa = Join-Path $lib 'steamapps'
        if (-not (Test-Path -LiteralPath $sa -PathType Container)) { continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $sa -Filter 'appmanifest_*.acf' -File -ErrorAction SilentlyContinue)) {
            $t = ''
            try { $t = [System.IO.File]::ReadAllText($f.FullName) } catch { continue }
            $n = [regex]::Match($t, '"name"\s+"([^"]*)"')
            $d = [regex]::Match($t, '"installdir"\s+"([^"]*)"')
            $s = [regex]::Match($t, '"SizeOnDisk"\s+"(\d+)"')
            if (-not $n.Success -or -not $d.Success) { continue }
            $name = $n.Groups[1].Value
            if ($name -match $script:GmSkipApp) { continue }
            $dir = Join-Path (Join-Path $sa 'common') $d.Groups[1].Value
            if (-not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
            $size = 0.0
            if ($s.Success) { $size = [double]$s.Groups[1].Value }
            [void]$out.Add(@{ Name = $name; Store = 'Steam'; Dir = $dir; Exe = ''; Size = $size })
        }
    }
    return $out.ToArray()
}

function Get-GmEpicGames {
    $out = New-Object System.Collections.ArrayList
    $md = Join-Path $env:ProgramData 'Epic\EpicGamesLauncher\Data\Manifests'
    if (-not (Test-Path -LiteralPath $md -PathType Container)) { return $out.ToArray() }
    foreach ($f in @(Get-ChildItem -LiteralPath $md -Filter '*.item' -File -ErrorAction SilentlyContinue)) {
        try {
            $j = [System.IO.File]::ReadAllText($f.FullName) | ConvertFrom-Json
            $dir = [string]$j.InstallLocation
            if ($dir -eq '' -or -not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
            $exe = ''
            if ([string]$j.LaunchExecutable -ne '') { $exe = Join-Path $dir ([string]$j.LaunchExecutable) }
            $size = 0.0
            try { $size = [double]$j.InstallSize } catch { }
            [void]$out.Add(@{ Name = [string]$j.DisplayName; Store = 'Epic'; Dir = $dir; Exe = $exe; Size = $size })
        } catch { }
    }
    return $out.ToArray()
}

function Get-GmGogGames {
    $out = New-Object System.Collections.ArrayList
    try {
        foreach ($k in @(Get-ChildItem 'HKLM:\SOFTWARE\WOW6432Node\GOG.com\Games' -ErrorAction SilentlyContinue)) {
            $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if ($null -eq $p) { continue }
            $dir = [string]$p.path
            if ($dir -eq '' -or -not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
            [void]$out.Add(@{ Name = [string]$p.gameName; Store = 'GOG'; Dir = $dir; Exe = [string]$p.exe; Size = 0.0 })
        }
    } catch { }
    return $out.ToArray()
}

# Oyunun ana calistirilabilir dosyasi: ipucu varsa o, yoksa en buyuk uygun .exe (en cok 2 alt klasor derinliginde)
function Find-GmMainExe([string]$Dir, [string]$Hint) {
    if ($Hint -ne '' -and (Test-Path -LiteralPath $Hint -PathType Leaf)) { return $Hint }
    if ($Dir -eq '' -or -not (Test-Path -LiteralPath $Dir -PathType Container)) { return '' }
    $best = ''; $bestLen = -1.0
    try {
        $files = @(Get-ChildItem -LiteralPath $Dir -Filter '*.exe' -File -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object -First 400)
        foreach ($f in $files) {
            if ($f.Name -match $script:GmBadExe) { continue }
            if ([double]$f.Length -gt $bestLen) { $best = $f.FullName; $bestLen = [double]$f.Length }
        }
    } catch { }
    return $best
}

# P: Custom (elle eklenenler: @{ Name; Exe })
function Job_GameScan($P) {
    $all = New-Object System.Collections.ArrayList
    foreach ($g in @(Get-GmSteamGames)) { [void]$all.Add($g) }
    foreach ($g in @(Get-GmEpicGames)) { [void]$all.Add($g) }
    foreach ($g in @(Get-GmGogGames)) { [void]$all.Add($g) }
    foreach ($c in @($P.Custom)) {
        if ($null -eq $c) { continue }
        $exe = [string]$c.Exe
        if ($exe -eq '' -or -not (Test-Path -LiteralPath $exe -PathType Leaf)) { continue }
        $dir = [string](Split-Path -Parent $exe)
        $nm = [string]$c.Name; if ($nm -eq '') { $nm = [System.IO.Path]::GetFileNameWithoutExtension($exe) }
        [void]$all.Add(@{ Name = $nm; Store = 'Elle'; Dir = $dir; Exe = $exe; Size = 0.0 })
    }
    Set-JobProgress 0 $all.Count ('Oyunlar taran' + [char]0x0131 + 'yor')
    $seen = @{}
    $rows = New-Object System.Collections.ArrayList
    foreach ($g in $all) {
        if (Test-JobCancel) { break }
        Step-JobProgress
        $key = ([string]$g.Dir).ToLowerInvariant()
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        $g.Exe = Find-GmMainExe ([string]$g.Dir) ([string]$g.Exe)
        $g.Flags = Get-GmFlags ([string]$g.Exe)
        [void]$rows.Add($g)
    }
    $sorted = @($rows | Sort-Object { ([string]$_.Name).ToLowerInvariant() })
    Write-WhLog ('Bulunan oyun: ' + [string]$sorted.Count) 'INFO'
    return @{ Games = $sorted }
}

# Oyunun su an yapilandirilmis durumu (yalnizca okur)
function Get-GmFlags([string]$Exe) {
    $r = @{ Gpu = $false; Fso = $false }
    if ($Exe -eq '') { return $r }
    $g = [string](Get-RegValue $script:GmGpuKey $Exe '')
    if ($g -match 'GpuPreference=2') { $r.Gpu = $true }
    $l = [string](Get-RegValue $script:GmLayersKey $Exe '')
    if ($l -match $script:GmFsoFlag) { $r.Fso = $true }
    return $r
}

# Calisan oyunlar: islem yolu oyun klasorunun altinda olanlar.  Games: @{ Name; Dir; Exe }
function Get-GmRunning($Games) {
    $out = New-Object System.Collections.ArrayList
    $dirs = @()
    $sep = [string][System.IO.Path]::DirectorySeparatorChar
    foreach ($g in @($Games)) { if ([string]$g.Dir -ne '') { $dirs += @{ Name = [string]$g.Name; Dir = ([string]$g.Dir).TrimEnd('\', '/') + $sep } } }
    if ($dirs.Count -eq 0) { return $out.ToArray() }
    foreach ($p in @(Get-Process -ErrorAction SilentlyContinue)) {
        try {
            $path = ''
            try { $path = [string]$p.Path } catch { }
            if ($path -eq '') { continue }
            foreach ($d in $dirs) {
                if ($path.StartsWith($d.Dir, [StringComparison]::OrdinalIgnoreCase)) {
                    [void]$out.Add(@{ Name = [string]$d.Name; Pid = [int]$p.Id; Proc = [string]$p.ProcessName })
                    break
                }
            }
        } finally { try { $p.Dispose() } catch { } }
    }
    return $out.ToArray()
}

function Test-GmExePath([string]$Exe) {
    if ($Exe -cnotmatch '^[A-Za-z]:\\[^"<>|*?\r\n]+\.[Ee][Xx][Ee]$') { return $false }
    return (Test-Path -LiteralPath $Exe -PathType Leaf)
}

# Op: @{ T = 'GameFlags'; Exe; Gpu = $true/$false/$null; Fso = $true/$false/$null }  (true = uygula, false = kaldir, null = dokunma)
function Invoke-GameFlagsOp($Op) {
    $exe = [string]$Op.Exe
    if (-not (Test-GmExePath $exe)) { Add-Skip (('Oyun dosyas' + [char]0x0131 + ' bulunamad' + [char]0x0131 + ': ') + $exe); return }
    if ($null -ne $Op.Gpu) {
        if ($Op.Gpu -eq $true) { Invoke-RegOp (RegOp $script:GmGpuKey $exe 'GpuPreference=2;' 'String') }
        else { Invoke-RegOp (RegDel $script:GmGpuKey $exe) }
    }
    if ($null -ne $Op.Fso) {
        $cur = [string](Get-RegValue $script:GmLayersKey $exe '')
        $flags = @()
        if ($cur -ne '') { $flags = @(($cur -replace '^~\s*', '') -split '\s+' | Where-Object { $_ -ne '' }) }
        if ($Op.Fso -eq $true) {
            if ($flags -notcontains $script:GmFsoFlag) { $flags += $script:GmFsoFlag }
        } else {
            $flags = @($flags | Where-Object { $_ -ne $script:GmFsoFlag })
        }
        if ($flags.Count -gt 0) { Invoke-RegOp (RegOp $script:GmLayersKey $exe ('~ ' + ($flags -join ' ')) 'String') }
        elseif ($cur -ne '') { Invoke-RegOp (RegDel $script:GmLayersKey $exe) }
        else { Add-Skip ('Tam ekran en iyile' + [char]0x015F + 'tirmeleri zaten varsay' + [char]0x0131 + 'lan.') }
    }
}
$script:MoreOps['GameFlags'] = 'Invoke-GameFlagsOp'

function New-GameFlagSteps($Game, $Gpu, $Fso) {
    $title = ('Oyun ayar' + [char]0x0131 + ': ') + [string]$Game.Name
    return @(@{ Id = 'game.flags'; Title = $title; Ops = @(@{ T = 'GameFlags'; Exe = [string]$Game.Exe; Gpu = $Gpu; Fso = $Fso }); Reboot = $false })
}

# Calisan oyunun onceligini yukseltir (program kapaninca kendiliginden sifirlanir). Pids: islem numaralari
function Job_GameBoost($P) {
    $n = 0; $names = New-Object System.Collections.ArrayList
    foreach ($id in @($P.Pids)) {
        try {
            $pr = Get-Process -Id ([int]$id) -ErrorAction Stop
            if ($script:CriticalProcs -contains $pr.ProcessName.ToLowerInvariant()) { continue }
            $pr.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::AboveNormal
            $n++; [void]$names.Add([string]$pr.ProcessName)
        } catch { }
    }
    Write-WhLog (('Oyun ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'i y' + [char]0x00FC + 'kseltildi: ') + [string]$n + (' i' + [char]0x015F + 'lem (') + ($names -join ', ') + ('). Program kapan' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r.')) 'OK'
    return @{ Ok = ($n -gt 0); Count = $n }
}

# DirectX genel kullanici ayarlari (DirectXUserGlobalSettings = "Anahtar=Deger;..."): yalnizca verilen anahtarlar degisir, digerleri (or. AutoHDREnable) korunur
# Op: @{ T = 'DxGlobal'; Set = @{ VRROptimizeEnable = '1' } }
function Merge-DxGlobal([string]$Current, $Set) {
    $pairs = [ordered]@{}
    foreach ($part in ([string]$Current -split ';')) {
        if ($part -match '^\s*([^=\s]+)\s*=\s*(.*?)\s*$') { $pairs[$Matches[1]] = $Matches[2] }
    }
    foreach ($k in @($Set.Keys)) { $pairs[[string]$k] = [string]$Set[$k] }
    $out = @()
    foreach ($k in @($pairs.Keys)) { $out += ([string]$k + '=' + [string]$pairs[$k]) }
    if ($out.Count -eq 0) { return '' }
    return (($out -join ';') + ';')
}

function Invoke-DxGlobalOp($Op) {
    $cur = [string](Get-RegValue $script:GmGpuKey 'DirectXUserGlobalSettings' '')
    $new = Merge-DxGlobal $cur $Op.Set
    Invoke-RegOp (RegOp $script:GmGpuKey 'DirectXUserGlobalSettings' $new 'String')
}
$script:MoreOps['DxGlobal'] = 'Invoke-DxGlobalOp'
function DxGlobalOp($Set) { return @{ T = 'DxGlobal'; Set = $Set } }

# ---------------- Akilli temizlik ekleri ----------------
# ==================================================================
#  AKILLI TEMIZLIK EKLERI: golgelendirici onbellegi, kucuk resim onbellegi, kurulum gunlukleri, Teslim Iyilestirme onbellegi,
#  uygulama onbellekleri, eski geri yukleme noktalari, Prefetch, son kullanilanlar.
#  Yalnizca yeniden uretilebilen ya da kullanicinin istedigi seyler silinir; kullanici dosyalarina dokunulmaz.
#  Onizlemede hicbir sey silinmez.  Silinenler geri alinamaz (Irrev) olarak isaretlidir.
# ==================================================================
$script:FuncOps = @{}

# Dosya listesini siler (onizlemede yalnizca sayar). Clear-Folders ile ayni ozet bicimi
function Clear-FileList([string]$Label, $Files) {
    $bytes = 0.0; $count = 0
    $list = @($Files)
    if ($script:Preview) {
        foreach ($f in $list) { $bytes += [double]$f.Length; $count++ }
    } else {
        $r = Remove-FilesSafe $list
        $bytes = [double]$r.Bytes; $count = [int]$r.Count
    }
    $script:LastClean = @{ Bytes = $bytes; Count = $count }
    $msg = ('{0}: {1} dosya, {2}' -f $Label, $count, (Format-Size $bytes))
    if ($script:Preview) { Add-Plan $msg } else { Add-Done $msg; $script:FreedBytes += $bytes }
}

function Invoke-CleanShader {
    $la = (Get-TargetProfile).LocalAppData
    $dirs = @(
        (Join-Path $la 'D3DSCache'),
        (Join-Path $la 'NVIDIA\DXCache'),
        (Join-Path $la 'NVIDIA\GLCache'),
        (Join-Path $la 'AMD\DxCache'),
        (Join-Path $la 'AMD\GLCache'),
        (Join-Path $la 'Intel\ShaderCache'),
        (Join-Path $env:ProgramData 'NVIDIA Corporation\NV_Cache')
    )
    Clear-Folders ('G' + [char]0x00F6 + 'lgelendirici (shader) ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i') $dirs 0 '[\\/](D3DSCache|DXCache|GLCache|ShaderCache|NV_Cache)$'
}

function Invoke-CleanThumbs {
    $ex = Join-Path (Get-TargetProfile).LocalAppData 'Microsoft\Windows\Explorer'
    $files = New-Object System.Collections.ArrayList
    if (Test-Path -LiteralPath $ex -PathType Container) {
        foreach ($pat in @('thumbcache_*.db', 'iconcache_*.db')) {
            foreach ($f in @(Get-ChildItem -LiteralPath $ex -Filter $pat -File -Force -ErrorAction SilentlyContinue)) { [void]$files.Add($f) }
        }
    }
    Clear-FileList ('K' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k resim ve simge ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i') $files.ToArray()
}

function Invoke-CleanSetupLogs {
    $w = $env:WINDIR
    $dirs = @((Join-Path $w 'Panther'), (Join-Path $w 'Logs\SIH'), (Join-Path $w 'Logs\waasmedic'), (Join-Path $w 'Logs\NetSetup'), (Join-Path $w 'Logs\DPX'))
    Clear-Folders ('Kurulum ve bak' + [char]0x0131 + 'm g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kleri (14 g' + [char]0x00FC + 'nden eski)') $dirs 14 '[\\/](Panther|Logs[\\/](SIH|waasmedic|NetSetup|DPX))$'
}

function Invoke-CleanDelivery {
    $cache = Join-Path $env:WINDIR 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache'
    $bytes = 0.0
    foreach ($f in (Get-FilesSafe $cache ([datetime]::MaxValue))) { $bytes += [double]$f.Length }
    $label = ('Teslim ' + [char]0x0130 + 'yile' + [char]0x015F + 'tirme ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i')
    if ($script:Preview) { Add-Plan ($label + ': ' + (Format-Size $bytes)); $script:LastClean = @{ Bytes = $bytes; Count = 0 }; return }
    $cmd = Get-Command -Name 'Delete-DeliveryOptimizationCache' -ErrorAction Ignore
    if ($null -eq $cmd) { Add-Skip ($label + (': bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde temizleme komutu yok')); return }
    Delete-DeliveryOptimizationCache -Force -ErrorAction Stop
    $script:LastClean = @{ Bytes = $bytes; Count = 0 }
    $script:FreedBytes += $bytes
    Add-Done ($label + ' temizlendi (' + (Format-Size $bytes) + ')')
}

function Invoke-CleanAppCaches {
    $tp = Get-TargetProfile
    $ap = $tp.AppData; $la = $tp.LocalAppData
    $dirs = New-Object System.Collections.ArrayList
    $roots = @(
        (Join-Path $ap 'discord'), (Join-Path $ap 'Slack'), (Join-Path $ap 'Microsoft\Teams'), (Join-Path $ap 'Code'), (Join-Path $ap 'Zoom\bin')
    )
    foreach ($r in $roots) {
        foreach ($sub in @('Cache', 'Code Cache', 'GPUCache', 'blob_storage', 'CachedData', 'Service Worker\CacheStorage')) {
            $x = Join-Path $r $sub
            if (Test-Path -LiteralPath $x -PathType Container) { [void]$dirs.Add($x) }
        }
    }
    foreach ($x in @((Join-Path $la 'Steam\htmlcache'), (Join-Path $ap 'Adobe\Common\Media Cache Files'), (Join-Path $ap 'Adobe\Common\Media Cache'))) {
        if (Test-Path -LiteralPath $x -PathType Container) { [void]$dirs.Add($x) }
    }
    $epic = Join-Path $la 'EpicGamesLauncher\Saved'
    if (Test-Path -LiteralPath $epic -PathType Container) {
        foreach ($d in @(Get-ChildItem -LiteralPath $epic -Directory -Filter 'webcache*' -ErrorAction SilentlyContinue)) { [void]$dirs.Add($d.FullName) }
    }
    Clear-Folders ('Uygulama ' + [char]0x00F6 + 'nbellekleri (Discord, Slack, Teams, VS Code, Steam, Epic, Adobe)') $dirs.ToArray() 0 '[\\/](Cache|Code Cache|GPUCache|blob_storage|CachedData|CacheStorage|htmlcache|Media Cache Files|Media Cache|webcache[0-9]*)$'
}

function Invoke-CleanPrefetch {
    $dir = Join-Path $env:WINDIR 'Prefetch'
    $files = @()
    if (Test-Path -LiteralPath $dir -PathType Container) { $files = @(Get-ChildItem -LiteralPath $dir -Filter '*.pf' -File -Force -ErrorAction SilentlyContinue) }
    Clear-FileList ('Prefetch kay' + [char]0x0131 + 'tlar' + [char]0x0131 + '') $files
}

function Invoke-CleanRecent {
    $dir = Join-Path (Get-TargetProfile).AppData 'Microsoft\Windows\Recent'
    $files = @()
    if (Test-Path -LiteralPath $dir -PathType Container) { $files = @(Get-ChildItem -LiteralPath $dir -Filter '*.lnk' -File -Force -ErrorAction SilentlyContinue) }
    Clear-FileList ('Son kullan' + [char]0x0131 + 'lan dosya k' + [char]0x0131 + 'sayollar' + [char]0x0131 + '') $files
}

# En yeni geri yukleme noktasi kalir, eskileri silinir
function Invoke-CleanRestorePoints {
    $sc = @()
    try { $sc = @(Get-CimInstance -ClassName Win32_ShadowCopy -ErrorAction Stop | Sort-Object { $_.InstallDate }) } catch { }
    if ($sc.Count -le 1) { Add-Skip ('Silinecek eski geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' yok (en yenisi her zaman kal' + [char]0x0131 + 'r).'); return }
    $old = @($sc | Select-Object -First ($sc.Count - 1))
    if ($script:Preview) { Add-Plan (('Eski geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ' silinecek: ') + [string]$old.Count + (' adet (en yenisi kal' + [char]0x0131 + 'r)')); return }
    $n = 0
    foreach ($s in $old) { try { Remove-CimInstance -InputObject $s -ErrorAction Stop; $n++ } catch { } }
    Add-Done (('Eski geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ' silindi: ') + [string]$n + ' adet')
}

$script:FuncOps['CleanShader'] = 'Invoke-CleanShader'
$script:FuncOps['CleanThumbs'] = 'Invoke-CleanThumbs'
$script:FuncOps['CleanSetupLogs'] = 'Invoke-CleanSetupLogs'
$script:FuncOps['CleanDelivery'] = 'Invoke-CleanDelivery'
$script:FuncOps['CleanAppCaches'] = 'Invoke-CleanAppCaches'
$script:FuncOps['CleanPrefetch'] = 'Invoke-CleanPrefetch'
$script:FuncOps['CleanRecent'] = 'Invoke-CleanRecent'
$script:FuncOps['CleanRestorePoints'] = 'Invoke-CleanRestorePoints'

# Taramada gorunen ek kategoriler (Job_CleanScan bunlari da dener)
$script:CleanExtraDefs = @(
    @{ Id = 'Shader'; N = ('G' + [char]0x00F6 + 'lgelendirici (shader) ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i'); Fn = 'Invoke-CleanShader' },
    @{ Id = 'Thumbs'; N = ('K' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k resim ve simge ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i'); Fn = 'Invoke-CleanThumbs' },
    @{ Id = 'SetupLogs'; N = ('Kurulum ve bak' + [char]0x0131 + 'm g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kleri'); Fn = 'Invoke-CleanSetupLogs' },
    @{ Id = 'Delivery'; N = ('Teslim ' + [char]0x0130 + 'yile' + [char]0x015F + 'tirme ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i'); Fn = 'Invoke-CleanDelivery' },
    @{ Id = 'AppCaches'; N = ('Uygulama ' + [char]0x00F6 + 'nbellekleri'); Fn = 'Invoke-CleanAppCaches' }
)

# ---------------- Windows istege bagli bilesenleri (Steps Recorder, WordPad, PowerShell ISE ...) ----------------
# Op: @{ T = 'Cap'; Match = 'App.StepsRecorder'; State = 'Absent' }   (Match: bilesen adinin basi)
$script:CapReadFailed = $false
$script:CapWarned = $false
# Bilesen kurulu mu? Yeniden baslatma bekleyen kurulum kurulu, bekleyen kaldirma kurulu degil sayilir.
function Test-CapOn([string]$State) { return (@('Installed', 'InstallPending') -contains $State) }
function Read-CapListFresh {
    $script:CapReadFailed = $false
    try { return , @(Get-WindowsCapability -Online -ErrorAction Stop) }
    catch {
        $script:CapReadFailed = $true
        if (-not $script:CapWarned) { $script:CapWarned = $true; Write-WhLog (('Bile' + [char]0x015F + 'en listesi okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
        return , @()
    }
}
# Toplu durum olcumu partisinde liste bir kez okunur; parti disinda ve gercek uygulamada her okuma tazedir.
function Get-CapList {
    $b = $script:StateBatch
    if ($null -ne $b -and $script:Preview) {
        if ($null -eq $b.Caps) { $b.Caps = Read-CapListFresh; $b.CapsFailed = $script:CapReadFailed }
        $script:CapReadFailed = [bool]$b.CapsFailed
        return $b.Caps
    }
    return (Read-CapListFresh)
}

function Invoke-CapOp($Op) {
    $match = [string]$Op.Match
    if ($match -cnotmatch '^[A-Za-z0-9\.\-_~]{3,80}$') { Add-Skip ('Ge' + [char]0x00E7 + 'ersiz bile' + [char]0x015F + 'en ad' + [char]0x0131 + '.'); return }
    $all = Get-CapList
    if ($script:CapReadFailed) { $script:OpUnreadable = $true; Add-Skip (('Windows bile' + [char]0x015F + 'en listesi okunamad' + [char]0x0131 + ' (y' + [char]0x00F6 + 'netici gerekir): ') + $match); return }
    $found = @($all | Where-Object { ([string]$_.Name) -like ($match + '*') })
    if ($found.Count -eq 0) { Add-Skip (('Windows bile' + [char]0x015F + 'eni bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde yok: ') + $match); return }
    $wantAbsent = ([string]$Op.State -ne 'Installed')
    foreach ($c in $found) {
        $isOn = Test-CapOn ([string]$c.State)
        if ($isOn -ne $wantAbsent) { Add-Skip (('Windows bile' + [char]0x015F + 'eni zaten uygun: ') + [string]$c.Name); continue }
        if ($script:Preview) {
            if ($wantAbsent) { Add-Plan (('Windows bile' + [char]0x015F + 'eni kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak: ') + [string]$c.Name) } else { Add-Plan (('Windows bile' + [char]0x015F + 'eni kurulacak (internet gerekir): ') + [string]$c.Name) }
            continue
        }
        $busy = Get-ServicingBusy
        if ($busy -ne '') {
            Write-WhLog ($busy + ('; Windows bile' + [char]0x015F + 'eni ' + [char]0x015F + 'imdi de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmedi (') + [string]$c.Name + ('). G' + [char]0x00FC + 'ncelleme bitince tekrar uygulay' + [char]0x0131 + 'n.')) 'WARN'
            Add-Skip (('Windows Update me' + [char]0x015F + 'gul, ertelendi: ') + [string]$c.Name)
            continue
        }
        Add-Journal @{ T = 'Cap'; Name = [string]$c.Name; WasInstalled = $isOn }
        [void](Set-WinCapabilityState ([string]$c.Name) (-not $wantAbsent))
        Add-Done (('Windows bile' + [char]0x015F + 'eni ') + $(if ($wantAbsent) { ('kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '') } else { 'kuruldu' }) + ': ' + [string]$c.Name + (' (yeniden ba' + [char]0x015F + 'latma gerekebilir)'))
    }
}

function Undo-CapItem($It) {
    if ([bool]$It.WasInstalled) { [void](Set-WinCapabilityState ([string]$It.Name) $true); Add-Done (('Windows bile' + [char]0x015F + 'eni geri kuruldu: ') + [string]$It.Name) }
    else { [void](Set-WinCapabilityState ([string]$It.Name) $false); Add-Done (('Windows bile' + [char]0x015F + 'eni yeniden kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + [string]$It.Name) }
}
$script:MoreOps['Cap'] = 'Invoke-CapOp'
$script:MoreUndo['Cap'] = 'Undo-CapItem'
function CapOp([string]$Match, [string]$State = 'Absent') { return @{ T = 'Cap'; Match = $Match; State = $State } }

# ---------------- TCP gecikme ayari (Nagle) - ag arayuzu basina ----------------
# Op: @{ T = 'NetLatency'; On = $true }  IP adresi olan her arayuzde TcpAckFrequency=1 ve TCPNoDelay=1
function Invoke-NetLatencyOp($Op) {
    $base = 'HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
    $ids = @()
    try {
        $ids = @(Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces' -ErrorAction Stop | ForEach-Object { $_.PSChildName })
    } catch { }
    $n = 0
    foreach ($id in $ids) {
        if ($id -notmatch '^\{[0-9A-Fa-f\-]{36}\}$') { continue }
        $ip = [string](Get-RegValue ($base + '\' + $id) 'DhcpIPAddress' '')
        if ($ip -eq '') { $ip = [string](@(Get-RegValue ($base + '\' + $id) 'IPAddress' @()) | Select-Object -First 1) }
        if ($ip -eq '' -or $ip -eq '0.0.0.0') { continue }
        $n++
        if ($Op.On -eq $true) {
            Invoke-RegOp (RegOp ($base + '\' + $id) 'TcpAckFrequency' 1)
            Invoke-RegOp (RegOp ($base + '\' + $id) 'TCPNoDelay' 1)
        } else {
            Invoke-RegOp (RegDel ($base + '\' + $id) 'TcpAckFrequency')
            Invoke-RegOp (RegDel ($base + '\' + $id) 'TCPNoDelay')
        }
    }
    if ($n -eq 0) { Add-Skip ('IP adresi olan a' + [char]0x011F + ' aray' + [char]0x00FC + 'z' + [char]0x00FC + ' bulunamad' + [char]0x0131 + '.') }
}
$script:MoreOps['NetLatency'] = 'Invoke-NetLatencyOp'
function NetLatencyOp([bool]$On = $true) { return @{ T = 'NetLatency'; On = $On } }

# ---------------- Sikistirma ----------------
# ==================================================================
#  SIKISTIRMA: CompactOS (Windows sistem dosyalari) ve klasor sikistirma (NTFS / Windows'un kendi compact.exe araci)
#  Dosyalar silinmez; sikistirma seffaftir (programlar farki gormez) ve geri alinabilir.
#  Onizleme yalnizca olcer. Kazanc, islemden once ve sonra surucudeki bos alan karsilastirilarak gosterilir.
# ==================================================================
$script:CpAlgos = [ordered]@{
    xpress4k  = @{ Name = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' (XPRESS 4K)');       Exe = 'xpress4k';  Info = ('En h' + [char]0x0131 + 'zl' + [char]0x0131 + '; oyun ve program klas' + [char]0x00F6 + 'rleri i' + [char]0x00E7 + 'in ' + [char]0x00F6 + 'nerilir.') }
    xpress8k  = @{ Name = 'Dengeli (XPRESS 8K)';     Exe = 'xpress8k';  Info = ('H' + [char]0x0131 + 'z ve kazan' + [char]0x00E7 + ' aras' + [char]0x0131 + 'nda denge.') }
    xpress16k = @{ Name = ('Y' + [char]0x00FC + 'ksek (XPRESS 16K)');     Exe = 'xpress16k'; Info = ('Daha ' + [char]0x00E7 + 'ok yer kazand' + [char]0x0131 + 'r' + [char]0x0131 + 'r, a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' biraz yava' + [char]0x015F + 'lar.') }
    lzx       = @{ Name = ('En y' + [char]0x00FC + 'ksek (LZX)');         Exe = 'lzx';       Info = ('En ' + [char]0x00E7 + 'ok yer kazand' + [char]0x0131 + 'r' + [char]0x0131 + 'r; yava' + [char]0x015F + ' i' + [char]0x015F + 'lemcide ve s' + [char]0x0131 + 'k de' + [char]0x011F + 'i' + [char]0x015F + 'en dosyalarda ' + [char]0x00F6 + 'nerilmez.') }
    lznt1     = @{ Name = 'Klasik NTFS (belgeler)';  Exe = '';          Info = ('Belge ve metin dosyalar' + [char]0x0131 + ' i' + [char]0x00E7 + 'in; klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' i' + [char]0x015F + 'aretler, sonradan eklenen dosyalar da s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.') }
}

# Sikistirilmasi anlamsiz (zaten sikisik) dosya uzantilari
$script:CpSkipExt = '(?i)\.(zip|rar|7z|gz|bz2|xz|zst|cab|msi|msix|appx|jpg|jpeg|png|gif|webp|heic|avif|mp3|mp4|m4a|m4v|mkv|avi|mov|wmv|webm|flac|aac|ogg|opus|wma|pdf|docx|xlsx|pptx|odt|apk|jar|wim|esd|iso|vhd|vhdx|bik|bk2|wem|ytdl)$'
$script:CpBinExt = '(?i)\.(exe|dll|sys|ocx|lib|pdb|obj|so|node|pak|dat|bin|assets|resS|bundle|unity3d|uasset|uexp|ubulk|pck|vpk|bsp|mdl|vtf|fsb|bank)$'
$script:CpTextExt = '(?i)\.(txt|log|xml|json|ini|cfg|csv|html|htm|js|css|ts|cs|cpp|h|py|md|yml|yaml|sql|dds|tga|bmp|wav|ttf|otf|lua)$'

# Sikistirmaya uygun mu?  Bos doner = uygun; aksi halde nedenini yazar.
function Test-CompressAllowed([string]$Path) {
    if ($Path -eq '' -or $Path -cnotmatch '^[A-Za-z]:\\') { return ('Yerel bir klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in (' + [char]0x00F6 + 'r. C:\Oyunlar).') }
    $p = $Path.TrimEnd('\')
    if ($p.Length -le 2) { return ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'n tamam' + [char]0x0131 + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz; bir klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in.') }
    if (-not (Test-Path -LiteralPath $p -PathType Container)) { return ('Klas' + [char]0x00F6 + 'r bulunamad' + [char]0x0131 + '.') }
    $deny = '^[a-z]:\\(windows|\$recycle\.bin|system volume information|recovery|boot|efi|perflogs)(\\|$)|\\winsxs(\\|$)|\\windowsapps(\\|$)|\\windows defender|\\microsoft\\windows defender|\\appdata\\local\\packages(\\|$)|\\onedrive|\\multimizer(\\|$)'
    if ($p.ToLowerInvariant() -cmatch $deny) { return ('Bu klas' + [char]0x00F6 + 'r Windows ya da g' + [char]0x00FC + 'venlik i' + [char]0x00E7 + 'in gereklidir; s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz.') }
    if ($p.ToLowerInvariant() -cmatch '^[a-z]:\\users\\[^\\]+$') { return ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'n tamam' + [char]0x0131 + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz; i' + [char]0x00E7 + 'inden bir klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in.') }
    if ($p.ToLowerInvariant() -cmatch '^[a-z]:\\(program files|program files \(x86\)|programdata|users)$') { return ('Bu ana klas' + [char]0x00F6 + 'r s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz; i' + [char]0x00E7 + 'indeki bir program' + [char]0x0131 + 'n klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' se' + [char]0x00E7 + 'in.') }
    try {
        $di = New-Object System.IO.DriveInfo($p.Substring(0, 1))
        if ($di.DriveType -ne [System.IO.DriveType]::Fixed) { return ('Yaln' + [char]0x0131 + 'zca bu bilgisayardaki sabit s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler desteklenir.') }
        if ([string]$di.DriveFormat -ne 'NTFS') { return ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma yaln' + [char]0x0131 + 'zca NTFS s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'lerde ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.') }
    } catch { return ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' okunamad' + [char]0x0131 + '.') }
    try {
        $it = Get-Item -LiteralPath $p -Force -ErrorAction Stop
        if (($it.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { return ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + ' (junction) klas' + [char]0x00F6 + 'rleri s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz.') }
    } catch { return ('Klas' + [char]0x00F6 + 'r okunamad' + [char]0x0131 + '.') }
    return ''
}

# Klasorun boyutu ve tahmini kazanci (yalnizca okur). Tahmin; gercek kazanc islemden sonra olculur.
function Get-CpEstimate([string]$Path, [int]$MaxFiles = 60000) {
    $total = 0.0; $skip = 0.0; $bin = 0.0; $txt = 0.0; $other = 0.0; $n = 0; $cut = $false
    try {
        $stack = New-Object System.Collections.Stack
        $stack.Push($Path)
        while ($stack.Count -gt 0 -and -not $cut) {
            $dir = [string]$stack.Pop()
            foreach ($it in @(Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue)) {
                if (($it.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { continue }
                if ($it.PSIsContainer) { $stack.Push($it.FullName); continue }
                $len = [double]$it.Length
                $total += $len; $n++
                if ($it.Name -match $script:CpSkipExt) { $skip += $len }
                elseif ($it.Name -match $script:CpBinExt) { $bin += $len }
                elseif ($it.Name -match $script:CpTextExt) { $txt += $len }
                else { $other += $len }
                if ($n -ge $MaxFiles) { $cut = $true; break }
            }
        }
    } catch { }
    # deneyime dayali kaba oranlar: ikili/yurutulebilir ~%38, metin/gorsel veri ~%55, diger ~%22, zaten sikisik 0
    $save = 0.38 * $bin + 0.55 * $txt + 0.22 * $other
    return @{ Bytes = $total; Files = $n; Save = [math]::Round($save, 0); Skip = $skip; Cut = $cut }
}

function Get-CpDriveFree([string]$Path) {
    try { return [double](New-Object System.IO.DriveInfo($Path.Substring(0, 1))).AvailableFreeSpace } catch { return -1.0 }
}

function Invoke-CompactExe([string[]]$Args2) {
    $o = & compact.exe @Args2 2>&1
    return @{ Rc = $LASTEXITCODE; Out = (($o | Out-String).Trim()) }
}

# Op: @{ T = 'Compress'; Path; Algo = 'xpress4k' | ... | 'lznt1'; Mode = 'compress' | 'decompress' }
function Invoke-CompressOp($Op) {
    $path = ([string]$Op.Path).TrimEnd('\')
    $algo = [string]$Op.Algo
    if (-not $script:CpAlgos.Contains($algo)) { $algo = 'xpress4k' }
    $mode = [string]$Op.Mode
    $why = Test-CompressAllowed $path
    if ($why -ne '') { Add-Skip (('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmad' + [char]0x0131 + ' (') + $path + '): ' + $why); return }
    if ($mode -eq 'decompress') {
        if ($script:Preview) { Add-Plan (('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak: ') + $path); return }
        [void](Invoke-CompactExe @('/u', '/s:' + $path, '/i', '/q'))
        [void](Invoke-CompactExe @('/u', '/s:' + $path, '/i', '/q', '/exe'))
        Add-Done (('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $path)
        return
    }
    $est = Get-CpEstimate $path
    $estTxt = ((Format-Size ([double]$est.Bytes)) + (', tahmini kazan' + [char]0x00E7 + ' ') + (Format-Size ([double]$est.Save)))
    if ($est.Cut) { $estTxt += (' (ilk 60 bin dosyaya g' + [char]0x00F6 + 're)') }
    if ($script:Preview) { Add-Plan (('Klas' + [char]0x00F6 + 'r s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak: ') + $path + ' (' + $estTxt + (', y' + [char]0x00F6 + 'ntem: ') + [string]$script:CpAlgos[$algo].Name + ')'); return }
    $before = Get-CpDriveFree $path
    Add-Journal @{ T = 'Compress'; Path = $path; Algo = $algo }
    # alt klasor alt klasor: iptal edilebilir ve ilerleme gorunur
    $subs = @(Get-ChildItem -LiteralPath $path -Directory -Force -ErrorAction SilentlyContinue | Where-Object { ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq 0 })
    $exeArg = @()
    if ([string]$script:CpAlgos[$algo].Exe -ne '') { $exeArg = @('/exe:' + [string]$script:CpAlgos[$algo].Exe) }
    $fail = 0
    if ($algo -eq 'lznt1') { [void](Invoke-CompactExe @('/c', $path, '/i', '/q')) }
    $r = Invoke-CompactExe (@('/c', ($path + '\*'), '/i', '/q') + $exeArg)
    if ($r.Rc -ne 0) { $fail++ }
    foreach ($s in $subs) {
        if (Test-JobCancel) { Write-WhLog ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' iste' + [char]0x011F + 'iyle durduruldu.') 'WARN'; break }
        $r = Invoke-CompactExe (@('/c', ('/s:' + $s.FullName), '/i', '/q') + $exeArg)
        if ($r.Rc -ne 0) { $fail++ }
    }
    $after = Get-CpDriveFree $path
    $gain = 0.0
    if ($before -ge 0 -and $after -ge 0) { $gain = [math]::Max(0.0, $after - $before) }
    $msg = (('Klas' + [char]0x00F6 + 'r s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $path)
    if ($gain -gt 0) { $msg += ((' ' + [char]0x2014 + ' ') + (Format-Size $gain) + (' yer a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '')) }
    if ($fail -gt 0) { $msg += (' (' + [string]$fail + (' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mde baz' + [char]0x0131 + ' dosyalar atland' + [char]0x0131 + ': kullan' + [char]0x0131 + 'mda ya da s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lamaz)')) }
    Add-Done $msg
}

function Undo-CompressItem($It) {
    $path = [string]$It.Path
    if (-not (Test-Path -LiteralPath $path -PathType Container)) { Add-Skip (('Klas' + [char]0x00F6 + 'r yok: ') + $path); return }
    [void](Invoke-CompactExe @('/u', ('/s:' + $path), '/i', '/q'))
    [void](Invoke-CompactExe @('/u', ('/s:' + $path), '/i', '/q', '/exe'))
    Add-Done (('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $path)
}

# CompactOS durumu: on | off | unknown  (compact.exe ciktisi Windows diline gore degisir; belirsizse unknown)
function Get-CompactOsState {
    $t = ''
    try { $t = (& compact.exe /compactos:query 2>&1 | Out-String) } catch { return 'unknown' }
    $t = $t.Trim()
    if ($t -eq '') { return 'unknown' }
    if ($t -match ('(?i)\b(not|nicht|pas|non|no est' + [char]0x00E1 + ')\b|de' + [char]0x011F + 'il|degil|n' + [char]0x00E3 + 'o|' + [char]0x043D + '' + [char]0x0435 + ' ')) { return 'off' }
    if ($t -match ('(?i)compact|s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r|sikistir|kompakt|compact')) { return 'on' }
    return 'unknown'
}

# Op: @{ T = 'CompactOs'; State = 'always' | 'never' }
function Invoke-CompactOsOp($Op) {
    $want = [string]$Op.State
    if ($want -ne 'always' -and $want -ne 'never') { throw ('Ge' + [char]0x00E7 + 'ersiz CompactOS durumu.') }
    $cur = Get-CompactOsState
    if ($want -eq 'always' -and $cur -eq 'on') { Add-Skip ('CompactOS zaten a' + [char]0x00E7 + '' + [char]0x0131 + 'k.'); return }
    if ($want -eq 'never' -and $cur -eq 'off') { Add-Skip ('CompactOS zaten kapal' + [char]0x0131 + '.'); return }
    if ($script:Preview) {
        if ($want -eq 'always') { Add-Plan ('CompactOS a' + [char]0x00E7 + '' + [char]0x0131 + 'lacak: Windows sistem dosyalar' + [char]0x0131 + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r (genelde 2-4 GB yer a' + [char]0x00E7 + 'ar, birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer, geri al' + [char]0x0131 + 'nabilir).') }
        else { Add-Plan ('CompactOS kapat' + [char]0x0131 + 'lacak: Windows sistem dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'n s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rmas' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') }
        return
    }
    $before = Get-CpDriveFree $env:SystemDrive
    Add-Journal @{ T = 'CompactOs'; Prev = $cur; State = $want }
    $r = Invoke-CompactExe @(('/compactos:' + $want))
    if ($r.Rc -ne 0) { throw ('compact.exe /compactos:' + $want + (' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $r.Out) }
    $after = Get-CpDriveFree $env:SystemDrive
    $msg = 'CompactOS ' + $(if ($want -eq 'always') { ('a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '') } else { ('kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '') })
    if ($want -eq 'always' -and $before -ge 0 -and $after -gt $before) { $msg += ((' ' + [char]0x2014 + ' ') + (Format-Size ($after - $before)) + (' yer a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '')) }
    Add-Done $msg
}

function Undo-CompactOsItem($It) {
    if ([string]$It.Prev -eq 'off' -and [string]$It.State -eq 'always') { [void](Invoke-CompactExe @('/compactos:never')); Add-Done ('CompactOS kapat' + [char]0x0131 + 'ld' + [char]0x0131 + ' (eski haline d' + [char]0x00F6 + 'nd' + [char]0x00FC + ')') }
    elseif ([string]$It.Prev -eq 'on' -and [string]$It.State -eq 'never') { [void](Invoke-CompactExe @('/compactos:always')); Add-Done ('CompactOS yeniden a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ' (eski haline d' + [char]0x00F6 + 'nd' + [char]0x00FC + ')') }
    else { Add-Skip ('CompactOS ' + [char]0x00F6 + 'nceki durumu bilinmiyor; elle de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmedi.') }
}

$script:MoreOps['Compress'] = 'Invoke-CompressOp'
$script:MoreOps['CompactOs'] = 'Invoke-CompactOsOp'
$script:MoreUndo['Compress'] = 'Undo-CompressItem'
$script:MoreUndo['CompactOs'] = 'Undo-CompactOsItem'

function New-CompressSteps($Paths, [string]$Algo, [string]$Mode = 'compress') {
    $steps = New-Object System.Collections.ArrayList
    foreach ($p in @($Paths)) {
        $leaf = [string]$p
        try { $leaf = [string](Split-Path -Leaf ([string]$p).TrimEnd('\')) } catch { }
        $ti = ('Klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r: '); if ($Mode -eq 'decompress') { $ti = ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rmay' + [char]0x0131 + ' kald' + [char]0x0131 + 'r: ') }
        [void]$steps.Add(@{ Id = 'compress'; Title = ($ti + $leaf); Ops = @(@{ T = 'Compress'; Path = [string]$p; Algo = $Algo; Mode = $Mode }); Reboot = $false })
    }
    return $steps.ToArray()
}

# Onerilen klasorler: oyun kitapliklari ve Program Files altindaki buyuk program klasorleri (yalnizca okur)
# P: Games (oyun klasorleri), MinMB
function Job_CompressScan($P) {
    $min = [double]250
    if ($null -ne $P.MinMB) { $min = [double]$P.MinMB }
    $cands = New-Object System.Collections.ArrayList
    $seen = @{}
    $games = @($P.Games | Where-Object { $null -ne $_ })
    if ($games.Count -eq 0) { $games = @(Get-GmSteamGames) + @(Get-GmEpicGames) + @(Get-GmGogGames) }
    foreach ($g in $games) {
        $d = ([string]$g.Dir).TrimEnd('\')
        if ($d -eq '' -or $seen.ContainsKey($d.ToLowerInvariant())) { continue }
        $seen[$d.ToLowerInvariant()] = $true
        [void]$cands.Add(@{ Path = $d; Name = [string]$g.Name; Kind = 'Oyun' })
    }
    foreach ($root in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
        if ([string]$root -eq '' -or -not (Test-Path -LiteralPath $root -PathType Container)) { continue }
        foreach ($d in @(Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue)) {
            if ((Test-CompressAllowed $d.FullName) -ne '') { continue }
            if ($d.Name -match '(?i)^(Windows|Microsoft|Common Files|Internet Explorer|WindowsPowerShell|Reference Assemblies|dotnet|Uninstall Information|Intel|NVIDIA|AMD|Realtek|Waves)') { continue }
            $k = $d.FullName.ToLowerInvariant()
            if ($seen.ContainsKey($k)) { continue }
            $seen[$k] = $true
            [void]$cands.Add(@{ Path = $d.FullName; Name = $d.Name; Kind = 'Program' })
        }
    }
    Set-JobProgress 0 $cands.Count ('Klas' + [char]0x00F6 + 'r boyutlar' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor')
    $rows = New-Object System.Collections.ArrayList
    foreach ($c in $cands) {
        if (Test-JobCancel) { break }
        Step-JobProgress
        if ((Test-CompressAllowed ([string]$c.Path)) -ne '') { continue }
        $sz = Get-DirSizeFast ([string]$c.Path)
        if ([double]$sz.Bytes -lt ($min * 1MB)) { continue }
        [void]$rows.Add(@{ Path = [string]$c.Path; Name = [string]$c.Name; Kind = [string]$c.Kind; Bytes = [double]$sz.Bytes; Files = [int]$sz.Files })
    }
    $sorted = @($rows | Sort-Object { -1 * [double]$_.Bytes })
    return @{ Rows = $sorted; Free = (Get-CpDriveFree $env:SystemDrive); CompactOs = (Get-CompactOsState) }
}

# Secilen klasor icin olcum ve tahmin (yalnizca okur)
function Job_CompressEstimate($P) {
    $path = ([string]$P.Path).TrimEnd('\')
    $why = Test-CompressAllowed $path
    if ($why -ne '') { return @{ Ok = $false; Why = $why; Path = $path } }
    $e = Get-CpEstimate $path
    return @{ Ok = $true; Path = $path; Bytes = [double]$e.Bytes; Files = [int]$e.Files; Save = [double]$e.Save; Skip = [double]$e.Skip; Cut = [bool]$e.Cut }
}

# ---------------- Akilli bakim ----------------
# ==================================================================
#  AKILLI BAKIM (yerel): isi izleme, otomasyon kurallari, performans artirici, gizlilik kalkani, sifir dokunus, donanim omru
#  "Akilli" burada kural tabanli demektir: karar bu bilgisayarin kendi olcumleriyle verilir, hicbir veri disari gonderilmez,
#  hicbir bulut hizmeti kullanilmaz. Hepsi kapali gelir; her degisiklik onizlenir, gunluge yazilir ve geri alinir.
# ==================================================================

# ---------------- isi ----------------
# Islemci/sistem sicakligi ( dereceC); okunamazsa -1.  Once ACPI isi bolgeleri, sonra performans sayaci.
# ACPI isi bolgesi yonetici izni ister ya da hic yoktur; bir kez basarisiz olursa 10 dakika boyunca yeniden denenmez
$script:ThermAcpiRetryAt = [DateTime]::MinValue
function Get-ThermalTemp {
    $best = -1.0
    if ([DateTime]::UtcNow -ge $script:ThermAcpiRetryAt) {
        try {
            foreach ($z in @(Get-CimInstance -Namespace 'root/wmi' -ClassName 'MSAcpi_ThermalZoneTemperature' -OperationTimeoutSec 5 -ErrorAction Stop)) {
                $c = ([double]$z.CurrentTemperature / 10.0) - 273.15
                if ($c -gt 10 -and $c -lt 130 -and $c -gt $best) { $best = $c }
            }
        } catch { $script:ThermAcpiRetryAt = [DateTime]::UtcNow.AddMinutes(10) }
    }
    if ($best -lt 0) {
        try {
            foreach ($z in @(Get-CimInstance -ClassName 'Win32_PerfFormattedData_Counters_ThermalZoneInformation' -OperationTimeoutSec 5 -ErrorAction Stop)) {
                $c = [double]$z.Temperature - 273.15
                if ($c -gt 10 -and $c -lt 130 -and $c -gt $best) { $best = $c }
            }
        } catch { }
    }
    if ($best -lt 0) { return -1.0 }
    return [math]::Round($best, 1)
}

# ---------------- otomasyon kurallari ----------------
# Kosul turleri.  Num: sayisal esik (Op: gt/lt, Val, For: kac saniye surerse);  Event: kenar tetikli;  Time: gun/saat
$script:AuWhen = [ordered]@{
    Ram     = @{ L = ('Bellek dolulu' + [char]0x011F + 'u (%)');            K = 'Num'; Unit = '%';  Def = 90; Op = 'gt'; For = 120 }
    Cpu     = @{ L = ('' + [char]0x0130 + '' + [char]0x015F + 'lemci y' + [char]0x00FC + 'k' + [char]0x00FC + ' (%)');               K = 'Num'; Unit = '%';  Def = 95; Op = 'gt'; For = 60 }
    Temp    = @{ L = ('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k (' + [char]0x00B0 + 'C)');                  K = 'Num'; Unit = ('' + [char]0x00B0 + 'C'); Def = 88; Op = 'gt'; For = 30 }
    Battery = @{ L = ('Pil y' + [char]0x00FC + 'zdesi (%)');                K = 'Num'; Unit = '%';  Def = 20; Op = 'lt'; For = 0 }
    Disk    = @{ L = ('Bo' + [char]0x015F + ' disk alan' + [char]0x0131 + ' (GB)');            K = 'Num'; Unit = 'GB'; Def = 10; Op = 'lt'; For = 0 }
    Plug    = @{ L = ('G' + [char]0x00FC + '' + [char]0x00E7 + ' kayna' + [char]0x011F + '' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ince');          K = 'Event'; Args = @{ on = ('Fi' + [char]0x015F + 'e tak' + [char]0x0131 + 'l' + [char]0x0131 + 'nca'); off = ('Fi' + [char]0x015F + 'ten ' + [char]0x00E7 + 'ekilince') } }
    Game    = @{ L = ('Oyun a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca / kapan' + [char]0x0131 + 'nca');      K = 'Event'; Args = @{ start = ('Oyun a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca'); stop = ('Oyun kapan' + [char]0x0131 + 'nca') } }
    Time    = @{ L = ('Belirli g' + [char]0x00FC + 'n ve saatte');          K = 'Time' }
    Logon   = @{ L = ('Uygulama a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca');              K = 'Event'; Args = @{ start = ('Uygulama a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca') } }
}

# Eylemler (Arg: secenek anahtari)
$script:AuDo = [ordered]@{
    Power   = @{ L = ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + 'n' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tir');           Args = @{ Balanced = 'Dengeli'; Saver = ('G' + [char]0x00FC + '' + [char]0x00E7 + ' tasarrufu'); High = ('Y' + [char]0x00FC + 'ksek performans'); Ultimate = 'Nihai performans' } }
    Clean   = @{ L = ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' temizlik (g' + [char]0x00FC + 'venli kategoriler)') }
    Mem     = @{ L = ('Belle' + [char]0x011F + 'i bo' + [char]0x015F + 'alt (Ayarlar' + [char]0x2019 + 'dan a' + [char]0x00E7 + '' + [char]0x0131 + 'ksa)') }
    Focus   = @{ L = 'Odak kipi';                       Args = @{ on = ('A' + [char]0x00E7 + ''); off = 'Kapat' } }
    Cap     = @{ L = ('' + [char]0x0130 + '' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + '');              Args = @{ '80' = '%80 yap'; '100' = ('%100' + [char]0x2019 + 'e d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r') } }
    Notify  = @{ L = ('Bildirim g' + [char]0x00F6 + 'ster') }
    Health  = @{ L = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + '') }
    Privacy = @{ L = ('Gizlilik kalkan' + [char]0x0131 + 'n' + [char]0x0131 + ' uygula') }
}

# Hazir kural sablonlari (eklenince kapali gelir; kullanici acar)
$script:AuTemplates = @(
    @{ Name = ('Pil %20' + [char]0x2019 + 'nin alt' + [char]0x0131 + 'na inince g' + [char]0x00FC + '' + [char]0x00E7 + ' tasarrufuna ge' + [char]0x00E7 + ''); When = @{ Kind = 'Battery'; Op = 'lt'; Val = 20; For = 0 }; Do = @{ Kind = 'Power'; Arg = 'Saver' }; Cool = 30 }
    @{ Name = ('Fi' + [char]0x015F + 'e tak' + [char]0x0131 + 'l' + [char]0x0131 + 'nca dengeli plana d' + [char]0x00F6 + 'n'); When = @{ Kind = 'Plug'; Arg = 'on' }; Do = @{ Kind = 'Power'; Arg = 'Balanced' }; Cool = 1 }
    @{ Name = ('Oyun a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca nihai performans'); When = @{ Kind = 'Game'; Arg = 'start' }; Do = @{ Kind = 'Power'; Arg = 'Ultimate' }; Cool = 1 }
    @{ Name = ('Oyun kapan' + [char]0x0131 + 'nca dengeli plana d' + [char]0x00F6 + 'n'); When = @{ Kind = 'Game'; Arg = 'stop' }; Do = @{ Kind = 'Power'; Arg = 'Balanced' }; Cool = 1 }
    @{ Name = ('Bellek 2 dakika %90' + [char]0x2019 + '' + [char]0x0131 + 'n ' + [char]0x00FC + 'st' + [char]0x00FC + 'nde kal' + [char]0x0131 + 'rsa belle' + [char]0x011F + 'i bo' + [char]0x015F + 'alt'); When = @{ Kind = 'Ram'; Op = 'gt'; Val = 90; For = 120 }; Do = @{ Kind = 'Mem' }; Cool = 20 }
    @{ Name = ('Bo' + [char]0x015F + ' disk 10 GB' + [char]0x2019 + '' + [char]0x0131 + 'n alt' + [char]0x0131 + 'na inerse bildir'); When = @{ Kind = 'Disk'; Op = 'lt'; Val = 10; For = 0 }; Do = @{ Kind = 'Notify'; Arg = ('Bo' + [char]0x015F + ' disk alan' + [char]0x0131 + ' 10 GB' + [char]0x2019 + '' + [char]0x0131 + 'n alt' + [char]0x0131 + 'na indi. Temizlik sayfas' + [char]0x0131 + 'ndan yer a' + [char]0x00E7 + 'abilirsiniz.') }; Cool = 720 }
    @{ Name = ('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k 88 ' + [char]0x00B0 + 'C' + [char]0x2019 + 'yi a' + [char]0x015F + 'arsa i' + [char]0x015F + 'lemciyi %80' + [char]0x2019 + 'e s' + [char]0x0131 + 'n' + [char]0x0131 + 'rla'); When = @{ Kind = 'Temp'; Op = 'gt'; Val = 88; For = 30 }; Do = @{ Kind = 'Cap'; Arg = '80' }; Cool = 30 }
    @{ Name = ('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k 70 ' + [char]0x00B0 + 'C' + [char]0x2019 + 'nin alt' + [char]0x0131 + 'na inince s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' kald' + [char]0x0131 + 'r'); When = @{ Kind = 'Temp'; Op = 'lt'; Val = 70; For = 120 }; Do = @{ Kind = 'Cap'; Arg = '100' }; Cool = 30 }
    @{ Name = ('Her Pazar 03:00' + [char]0x2019 + 'te g' + [char]0x00FC + 'venli temizlik'); When = @{ Kind = 'Time'; At = '03:00'; Days = @(0) }; Do = @{ Kind = 'Clean' }; Cool = 600 }
)

function New-AuRule($Template) {
    $id = [guid]::NewGuid().ToString('N').Substring(0, 8)
    $w = @{}; foreach ($k in @($Template.When.Keys)) { $w[$k] = $Template.When[$k] }
    $d = @{}; foreach ($k in @($Template.Do.Keys)) { $d[$k] = $Template.Do[$k] }
    if ($w.ContainsKey('Days')) { $w.Days = @($w.Days) }
    return @{ Id = $id; On = $false; Name = [string]$Template.Name; When = $w; Do = $d; Cool = [int]$Template.Cool; Last = '' }
}

# Kuralin tek satirlik Turkce ozeti
function Get-AuRuleText($Rule) {
    $w = $Rule.When; $d = $Rule.Do
    $wd = $script:AuWhen[[string]$w.Kind]
    $dd = $script:AuDo[[string]$d.Kind]
    if ($null -eq $wd -or $null -eq $dd) { return [string]$Rule.Name }
    $a = ''
    switch ([string]$wd.K) {
        'Num' {
            $op = ('' + [char]0x00FC + 'st' + [char]0x00FC + 'ne ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'nca'); if ([string]$w.Op -eq 'lt') { $op = ('alt' + [char]0x0131 + 'na inince') }
            $a = ((Tr ([string]$wd.L)) + ' ' + [string]$w.Val + ' ' + [string]$wd.Unit + ' ' + (Tr $op))
            if ([int]$w.For -gt 0) { $a += (' ' + (Format-Tr (('(en az {0} sn s' + [char]0x00FC + 'rerse)')) ([int]$w.For))) }
        }
        'Time' {
            $days = @($w.Days)
            $names = @('Pazar', 'Pazartesi', ('Sal' + [char]0x0131 + ''), ('' + [char]0x00C7 + 'ar' + [char]0x015F + 'amba'), ('Per' + [char]0x015F + 'embe'), 'Cuma', 'Cumartesi')
            $dt = (Tr ('Her g' + [char]0x00FC + 'n'))
            if ($days.Count -gt 0 -and $days.Count -lt 7) { $dt = (($days | ForEach-Object { Tr ([string]$names[[int]$_ % 7]) }) -join ', ') }
            $a = ($dt + ' ' + [string]$w.At)
        }
        default { if ($null -ne $wd.Args -and $wd.Args.ContainsKey([string]$w.Arg)) { $a = (Tr ([string]$wd.Args[[string]$w.Arg])) } else { $a = (Tr ([string]$wd.L)) } }
    }
    $b = (Tr ([string]$dd.L))
    if ($null -ne $dd.Args -and $dd.Args.ContainsKey([string]$d.Arg)) { $b += (': ' + (Tr ([string]$dd.Args[[string]$d.Arg]))) }
    elseif ([string]$d.Kind -eq 'Notify' -and [string]$d.Arg -ne '') { $b += (': ' + (Tr ([string]$d.Arg))) }
    return ($a + (' ' + [char]0x2192 + ' ') + $b)
}

# Kural simdi calismali mi?  S: olcumler; Rt: kuralin calisma ani kaydi (cagiran saklar); Now: simdiki zaman
# S: Ram, Cpu, Temp, Battery, HasBattery, Online, FreeGB, GameOn, Started (ilk turda $true)
function Test-AuRule($Rule, $S, $Rt, [datetime]$Now) {
    $w = $Rule.When
    $wd = $script:AuWhen[[string]$w.Kind]
    if ($null -eq $wd) { return $false }
    $cool = [int]$Rule.Cool
    if ($null -ne $Rt.LastFire -and $cool -gt 0 -and ($Now - [datetime]$Rt.LastFire).TotalMinutes -lt $cool) {
        # bekleme suresindeyken kenar bilgisi yine de guncellenir
        $fire = $false
    } else { $fire = $true }
    $hit = $false
    switch ([string]$wd.K) {
        'Num' {
            $val = $null
            switch ([string]$w.Kind) {
                'Ram' { $val = $S.Ram } 'Cpu' { $val = $S.Cpu } 'Temp' { $val = $S.Temp }
                'Battery' { if ($S.HasBattery -eq $true) { $val = $S.Battery } }
                'Disk' { $val = $S.FreeGB }
            }
            $ok = $false
            if ($null -ne $val -and [double]$val -ge 0) {
                if ([string]$w.Op -eq 'lt') { $ok = ([double]$val -lt [double]$w.Val) } else { $ok = ([double]$val -gt [double]$w.Val) }
            }
            if (-not $ok) { $Rt.Since = $null; $Rt.Fired = $false }
            else {
                if ($null -eq $Rt.Since) { $Rt.Since = $Now }
                if (-not $Rt.Fired -and ($Now - [datetime]$Rt.Since).TotalSeconds -ge [double]$w.For) { $hit = $true }
            }
        }
        'Event' {
            switch ([string]$w.Kind) {
                'Plug' {
                    if ($null -ne $Rt.Prev -and [bool]$Rt.Prev -ne [bool]$S.Online) {
                        if ([string]$w.Arg -eq 'on' -and [bool]$S.Online) { $hit = $true }
                        if ([string]$w.Arg -eq 'off' -and -not [bool]$S.Online) { $hit = $true }
                    }
                    $Rt.Prev = [bool]$S.Online
                }
                'Game' {
                    if ($null -ne $Rt.Prev -and [bool]$Rt.Prev -ne [bool]$S.GameOn) {
                        if ([string]$w.Arg -eq 'start' -and [bool]$S.GameOn) { $hit = $true }
                        if ([string]$w.Arg -eq 'stop' -and -not [bool]$S.GameOn) { $hit = $true }
                    }
                    $Rt.Prev = [bool]$S.GameOn
                }
                'Logon' { if ($S.Started -eq $true -and -not $Rt.Fired) { $hit = $true } }
            }
        }
        'Time' {
            $at = [string]$w.At
            if ($at -match '^([01]?[0-9]|2[0-3]):([0-5][0-9])$') {
                $days = @($w.Days)
                $today = [int]$Now.DayOfWeek
                $dayOk = ($days.Count -eq 0 -or $days -contains $today)
                $nowTxt = $Now.ToString('HH:mm')
                $want = ('{0:00}:{1}' -f [int]$Matches[1], $Matches[2])
                if ($dayOk -and $nowTxt -eq $want -and [string]$Rt.Day -ne $Now.ToString('yyyyMMdd')) { $hit = $true }
            }
        }
    }
    if ($hit -and $fire) {
        $Rt.LastFire = $Now
        $Rt.Fired = $true
        if ([string]$wd.K -eq 'Time') { $Rt.Day = $Now.ToString('yyyyMMdd') }
        return $true
    }
    return $false
}

# ---------------- gizlilik kalkani ----------------
# Gizlilik kategorisindeki guvenli (duzey 1-2) ayarlar
function Get-PrivacyShieldIds {
    $ids = New-Object System.Collections.ArrayList
    foreach ($c in (Get-CatalogFor 'opt' 'Gizlilik' $sync.Profile)) {
        if ([int]$c.Level -lt 1 -or [int]$c.Level -gt 2) { continue }
        if (-not (Test-WhenOk ([string]$c.When) $sync.Profile)) { continue }
        [void]$ids.Add([string]$c.Id)
    }
    return $ids.ToArray()
}

function Job_PrivacyStatus($P) {
    $all = Get-PrivacyShieldIds
    $pending = New-Object System.Collections.ArrayList
    $applied = 0
    Set-JobProgress 0 $all.Count ('Gizlilik ayarlar' + [char]0x0131 + ' denetleniyor')
    foreach ($id in $all) {
        if (Test-JobCancel) { break }
        $c = Get-CatalogItem ([string]$id)
        $n = Get-TweakPending $c
        if ($n -eq 0) { $applied++ } elseif ($n -gt 0) { [void]$pending.Add([string]$id) }
        Step-JobProgress
    }
    return @{ Total = $all.Count; Applied = $applied; Pending = $pending.ToArray() }
}

# Sifir dokunus: yalnizca duzey 1 (guvenli) ve bu bilgisayara uygun ayarlar + gecici dosya temizligi.  P: Preview, RestorePoint
function Job_SmartZero($P) {
    $pr = $sync.Profile
    $tier = Get-CurrentTier
    $pick = New-Object System.Collections.ArrayList
    foreach ($id in (Get-AdaptiveIds 'opt' $pr $tier)) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -eq $c -or [int]$c.Level -gt 1) { continue }
        if ([string]$c.Cat -eq 'Temizlik' -and [string]$c.Id -ne 'Temp') { continue }
        $n = Get-TweakPending $c
        if ($n -eq 0) { continue }
        [void]$pick.Add([string]$id)
    }
    Write-WhLog (('S' + [char]0x0131 + 'f' + [char]0x0131 + 'r dokunu' + [char]0x015F + ': ') + [string]$pick.Count + (' g' + [char]0x00FC + 'venli ayar ' + [char]0x00F6 + 'nerildi (donan' + [char]0x0131 + 'm s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + ': ') + [string]$tier.Label + ').') 'INFO'
    $steps = New-StepsFromIds ([string[]]$pick.ToArray())
    if (@($steps).Count -eq 0) {
        Write-WhLog ('Uygulanacak bir ' + [char]0x015F + 'ey yok; bu bilgisayar zaten ' + [char]0x00F6 + 'nerilen durumda.') 'OK'
        return @{ Ok = $true; Changes = 0; Skipped = 0; Errors = 0; Freed = 0.0; Preview = [bool]$P.Preview; Reboot = $false; Summary = ('Uygulanacak bir ' + [char]0x015F + 'ey yok.') }
    }
    $res = Job_Plan @{ Steps = $steps; Preview = [bool]$P.Preview; RestorePoint = [bool]$P.RestorePoint }
    $res.Ok = ([int]$res.Errors -eq 0)
    return $res
}

# ---------------- performans artirici ----------------
# En cok islemci kullanan arka plan islemlerinden oncelik dusurulebilecekleri secer.  Top: izleyicinin son listesi
function Get-BoostTargets($Top, [double]$MinCpu = 15.0) {
    $out = New-Object System.Collections.ArrayList
    foreach ($t in @($Top)) {
        $nm = ([string]$t.Name).ToLowerInvariant()
        if ($script:CriticalProcs -contains $nm) { continue }
        if ($nm -match '^(multimizer|powershell|pwsh|conhost|msedgewebview2|searchhost|startmenuexperiencehost|shellexperiencehost|textinputhost|runtimebroker|system|idle)$') { continue }
        if ($t.Win -eq $true) { continue }
        if ([double]$t.Cpu -lt $MinCpu) { continue }
        if ([int]$t.Pid -le 4) { continue }
        [void]$out.Add($t)
    }
    return $out.ToArray()
}

# ---------------- donanim sagligi ve omru ----------------
function Add-LifeRow($List, [string]$Title, [string]$Value, [string]$Status, [string]$Hint) {
    [void]$List.Add(@{ Title = $Title; Value = $Value; Status = $Status; Hint = $Hint })
}

function Job_Lifespan($P) {
    $rows = New-Object System.Collections.ArrayList
    # diskler
    try {
        foreach ($d in @(Get-PhysicalDisk -ErrorAction Stop)) {
            $name = ([string]$d.FriendlyName).Trim()
            $type = [string]$d.MediaType
            $health = [string]$d.HealthStatus
            $st = 'ok'; $hint = ('Disk sa' + [char]0x011F + 'l' + [char]0x0131 + 'kl' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor.')
            if ($health -ne 'Healthy') { $st = 'bad'; $hint = ('Windows bu diski sa' + [char]0x011F + 'l' + [char]0x0131 + 'ks' + [char]0x0131 + 'z i' + [char]0x015F + 'aretledi. ' + [char]0x00D6 + 'nemli dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' hemen yedekleyin.') }
            $extra = @()
            $rc = $null
            try { $rc = $d | Get-StorageReliabilityCounter -ErrorAction Stop } catch { }
            if ($null -ne $rc) {
                if ($null -ne $rc.Wear -and [int]$rc.Wear -gt 0) {
                    $extra += (('a' + [char]0x015F + '' + [char]0x0131 + 'nma %') + [string][int]$rc.Wear)
                    if ([int]$rc.Wear -ge 90) { $st = 'bad'; $hint = ('SSD ' + [char]0x00F6 + 'mr' + [char]0x00FC + 'n' + [char]0x00FC + 'n sonuna yakla' + [char]0x015F + 'm' + [char]0x0131 + '' + [char]0x015F + '. Yedek al' + [char]0x0131 + 'n ve yenisini planlay' + [char]0x0131 + 'n.') }
                    elseif ([int]$rc.Wear -ge 70 -and $st -eq 'ok') { $st = 'warn'; $hint = ('SSD ' + [char]0x00F6 + 'mr' + [char]0x00FC + 'n' + [char]0x00FC + 'n b' + [char]0x00FC + 'y' + [char]0x00FC + 'k b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + ' kullan' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + '; d' + [char]0x00FC + 'zenli yedek al' + [char]0x0131 + 'n.') }
                }
                if ($null -ne $rc.Temperature -and [int]$rc.Temperature -gt 0) {
                    $extra += ([string][int]$rc.Temperature + (' ' + [char]0x00B0 + 'C'))
                    if ([int]$rc.Temperature -ge 70 -and $st -eq 'ok') { $st = 'warn'; $hint = ('Disk s' + [char]0x0131 + 'cak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor; kasa havaland' + [char]0x0131 + 'rmas' + [char]0x0131 + 'n' + [char]0x0131 + ' kontrol edin.') }
                }
                if ($null -ne $rc.PowerOnHours -and [int64]$rc.PowerOnHours -gt 0) { $extra += ([string][int64]$rc.PowerOnHours + (' saat ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'm' + [char]0x0131 + '' + [char]0x015F + '')) }
                if ($null -ne $rc.ReadErrorsUncorrected -and [int64]$rc.ReadErrorsUncorrected -gt 0) {
                    $st = 'bad'; $hint = ('Disk d' + [char]0x00FC + 'zeltilemeyen okuma hatalar' + [char]0x0131 + ' bildiriyor. Yedek al' + [char]0x0131 + 'n.')
                    $extra += ([string][int64]$rc.ReadErrorsUncorrected + (' d' + [char]0x00FC + 'zeltilemeyen okuma hatas' + [char]0x0131 + ''))
                }
            }
            $val = ($type + ', ' + (Format-Size ([double]$d.Size)) + ', ' + $health)
            if ($extra.Count -gt 0) { $val += ((' ' + [char]0x00B7 + ' ') + ($extra -join (' ' + [char]0x00B7 + ' '))) }
            Add-LifeRow $rows ('Disk: ' + $name) $val $st $hint
        }
    } catch { Add-LifeRow $rows 'Diskler' ('Okunamad' + [char]0x0131 + '') 'warn' ('Disk sa' + [char]0x011F + 'l' + [char]0x0131 + 'k bilgisi bu bilgisayarda okunamad' + [char]0x0131 + '.') }
    # pil
    $w = Get-PwBatteryWear
    if ($null -ne $w) {
        $st = 'ok'; $hint = 'Pil kapasitesi iyi durumda.'
        if ([double]$w.Wear -ge 60) { $st = 'bad'; $hint = ('Pil kapasitesinin yar' + [char]0x0131 + 's' + [char]0x0131 + 'ndan fazlas' + [char]0x0131 + ' kaybolmu' + [char]0x015F + '; de' + [char]0x011F + 'i' + [char]0x015F + 'tirmeyi d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'n' + [char]0x00FC + 'n.') }
        elseif ([double]$w.Wear -ge 35) { $st = 'warn'; $hint = ('Pil ya' + [char]0x015F + 'lanm' + [char]0x0131 + '' + [char]0x015F + '; ' + [char]0x015F + 'arj s' + [char]0x00FC + 'resi k' + [char]0x0131 + 'sald' + [char]0x0131 + '. Tam ' + [char]0x015F + 'arj/bo' + [char]0x015F + 'alma d' + [char]0x00F6 + 'ng' + [char]0x00FC + 'lerinden ka' + [char]0x00E7 + '' + [char]0x0131 + 'n' + [char]0x0131 + 'n.') }
        $val = (('tasar' + [char]0x0131 + 'm ') + [string]$w.Design + (' mWh, ' + [char]0x015F + 'imdi ') + [string]$w.Full + (' mWh (a' + [char]0x015F + '' + [char]0x0131 + 'nma %') + [string]$w.Wear + ')')
        if ([int]$w.Cycles -ge 0) { $val += ((' ' + [char]0x00B7 + ' ') + [string]$w.Cycles + (' ' + [char]0x015F + 'arj d' + [char]0x00F6 + 'ng' + [char]0x00FC + 's' + [char]0x00FC + '')) }
        Add-LifeRow $rows 'Pil' $val $st $hint
    }
    # sicaklik
    $t = Get-ThermalTemp
    if ($t -gt 0) {
        $st = 'ok'; $hint = ('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k normal.')
        if ($t -ge 90) { $st = 'bad'; $hint = ('' + [char]0x00C7 + 'ok s' + [char]0x0131 + 'cak. Fan ve so' + [char]0x011F + 'utucuyu temizleyin; ' + [char]0x0131 + 's' + [char]0x0131 + 'l macun ya' + [char]0x015F + 'lanm' + [char]0x0131 + '' + [char]0x015F + ' olabilir.') }
        elseif ($t -ge 80) { $st = 'warn'; $hint = ('Y' + [char]0x00FC + 'ksek. Havaland' + [char]0x0131 + 'rmay' + [char]0x0131 + ' ve tozu kontrol edin; G' + [char]0x00FC + '' + [char]0x00E7 + ' sayfas' + [char]0x0131 + 'ndan ' + [char]0x201C + 'Sessiz ve serin' + [char]0x201D + ' plan' + [char]0x0131 + ' deneyin.') }
        Add-LifeRow $rows ('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k (' + [char]0x015F + 'imdi)') ([string]$t + (' ' + [char]0x00B0 + 'C')) $st $hint
    } else {
        Add-LifeRow $rows ('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k') ('Okunamad' + [char]0x0131 + '') 'info' ('Bu bilgisayar ' + [char]0x0131 + 's' + [char]0x0131 + ' sens' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' Windows' + [char]0x2019 + 'a a' + [char]0x00E7 + 'm' + [char]0x0131 + 'yor. ' + [char]0x00DC + 'reticinin arac' + [char]0x0131 + ' ya da HWiNFO gibi bir program gerekir.')
    }
    # acik kalma suresi
    try {
        $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $days = [math]::Round(((Get-Date) - $os.LastBootUpTime).TotalDays, 1)
        $st = 'ok'; $hint = ('D' + [char]0x00FC + 'zenli yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor.')
        if ($days -ge 30) { $st = 'warn'; $hint = ('Bilgisayar bir aydan uzun s' + [char]0x00FC + 'redir yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + '; g' + [char]0x00FC + 'ncellemeler ve bellek s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') }
        elseif ($days -ge 14) { $st = 'warn'; $hint = ('' + [char]0x0130 + 'ki haftadan uzun s' + [char]0x00FC + 'redir a' + [char]0x00E7 + '' + [char]0x0131 + 'k; yeniden ba' + [char]0x015F + 'latmak iyi gelir.') }
        Add-LifeRow $rows ('A' + [char]0x00E7 + '' + [char]0x0131 + 'k kalma s' + [char]0x00FC + 'resi') ([string]$days + (' g' + [char]0x00FC + 'n')) $st $hint
    } catch { }
    # bos yer
    try {
        $di = New-Object System.IO.DriveInfo($env:SystemDrive.Substring(0, 1))
        $pct = 100.0 * [double]$di.AvailableFreeSpace / [double]$di.TotalSize
        $st = 'ok'; $hint = ('Yeterli bo' + [char]0x015F + ' yer var.')
        if ($pct -lt 5) { $st = 'bad'; $hint = ('Sistem diskinde yer neredeyse bitti; Windows ve programlar yava' + [char]0x015F + 'lar. Temizlik sayfas' + [char]0x0131 + 'n' + [char]0x0131 + ' kullan' + [char]0x0131 + 'n.') }
        elseif ($pct -lt 12) { $st = 'warn'; $hint = ('Sistem diskinde yer azal' + [char]0x0131 + 'yor; SSD' + [char]0x2019 + 'ler bo' + [char]0x015F + ' alan azald' + [char]0x0131 + 'k' + [char]0x00E7 + 'a yava' + [char]0x015F + 'lar ve daha ' + [char]0x00E7 + 'ok y' + [char]0x0131 + 'pran' + [char]0x0131 + 'r.') }
        Add-LifeRow $rows ('Sistem diski bo' + [char]0x015F + ' yer') ((Format-Size ([double]$di.AvailableFreeSpace)) + ' (%' + [string][int][math]::Round($pct) + ')') $st $hint
    } catch { }
    # bekleyen yeniden baslatma
    try {
        $pend = Get-PendingReboot
        $pend = @($pend)
        if ($pend.Count -gt 0) { Add-LifeRow $rows ('Bekleyen yeniden ba' + [char]0x015F + 'latma') ($pend -join ', ') 'warn' ('Bir g' + [char]0x00FC + 'ncelleme ya da kurulum yeniden ba' + [char]0x015F + 'latma bekliyor.') }
    } catch { }
    return @{ Rows = $rows.ToArray() }
}

# Verilen katalog kimliklerinin olculen durumu (0 = uygulanmis, N = bekleyen deger, -1 = olculemez)
function Job_TweakStateIds($P) {
    $states = @{}
    Start-StateBatch
    try {
    foreach ($id in @($P.Ids)) {
        if (Test-JobCancel) { break }
        $c = Get-CatalogItem ([string]$id)
        if ($null -ne $c) {
            $pv = Get-TweakPending $c
            if ($pv -eq 0 -and (Test-TweakBlocked $c)) { $pv = -3 }
            $states[[string]$id] = $pv
        }
    }
    } finally { Stop-StateBatch }
    return @{ States = $states }
}

