$script:SmSafeClean = @('Temp', 'WerFiles', 'Logs', 'SetupLogs', 'Delivery', 'UpdCache')

# ---------------- Genisletilmis ayar katalogu ----------------
# ==================================================================
#  GENISLETILMIS AYAR KATALOGU: gizlilik, arayuz ve kisisellestirme, Windows ozellikleri, sistem, oyun, ag, uygulamalar (Edge)
#  Kurallar: her ayar gercek bir Windows ayari/ilkesidir, onizlenir, eski degeri kaydedilir ve geri alinir.
#  Defender, Guvenlik Duvari, UAC, SmartScreen, Windows Update ve Microsoft Store'u kapatan ayar YOKTUR (bilerek).
#  Duzey: 1 guvenli - 2 dengeli - 3 agresif - 4 yalnizca elle (hicbir hazir profilde secilmez; zevk/kullanim tercihi)
# ==================================================================
$script:CatNames['Sistem'] = 'Sistem'
$script:CatNames['Ozellik'] = ('Windows ' + [char]0x00F6 + 'zellikleri ve bile' + [char]0x015F + 'enler')
$script:ExtTweakIds = New-Object System.Collections.ArrayList

# Satir bicimi:  'YOL|AD|TUR|DEGER'   (TUR: DWord | String | QWord) ya da silmek icin 'YOL|AD|Del'
function Add-RegTweak {
    param([string]$Id, [string]$Cat, [int]$Level, [string]$Title, [string]$Desc, [string[]]$Reg = @(), $Ops = @(),
        [bool]$Reboot = $false, [string]$OS = '', [string]$When = '', [string]$Need = '', [string]$NeedWhy = '', [string]$Page = 'opt')
    $list = New-Object System.Collections.ArrayList
    foreach ($line in @($Reg)) {
        if ([string]$line -eq '') { continue }
        $p = ([string]$line).Split('|')
        if ($p.Count -eq 3 -and $p[2] -eq 'Del') { [void]$list.Add((RegDel $p[0] $p[1])); continue }
        if ($p.Count -ne 4) { throw (('Ge' + [char]0x00E7 + 'ersiz kay' + [char]0x0131 + 't sat' + [char]0x0131 + 'r' + [char]0x0131 + ' (') + $Id + '): ' + $line) }
        $v = $p[3]
        if ($p[2] -eq 'DWord' -or $p[2] -eq 'QWord') { $v = [int64]$p[3] }
        [void]$list.Add((RegOp $p[0] $p[1] $v $p[2]))
    }
    foreach ($o in @($Ops)) { if ($null -ne $o) { [void]$list.Add($o) } }
    $t = @{ Id = $Id; Cat = $Cat; Level = $Level; Title = $Title; Desc = $Desc; Ops = $list.ToArray(); Reboot = $Reboot; OS = $OS; When = $When; Page = $Page }
    if ($Need -ne '') { $t.Need = $Need; $t.NeedWhy = $NeedWhy }
    Add-Tweak $t
    [void]$script:ExtTweakIds.Add($Id)
}

