    -Desc ('Windows' + [char]0x2019 + 'un ' + [char]0x00E7 + 'evredeki ' + [char]0x00FC + 'cretli Wi-Fi hizmetlerini ' + [char]0x00F6 + 'nermesi kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') `
    -Reg @('HKLM\SOFTWARE\Microsoft\WlanSvc\AnqpCache|OsuRegistrationStatus|DWord|0', 'HKLM\SOFTWARE\Microsoft\PolicyManager\default\WiFi\AllowWiFiHotSpotReporting|value|DWord|0')

Remove-Variable -Name adv, cdm, edge, cam, perms -ErrorAction SilentlyContinue

