# ---------------- Windows'un korudugu kayit degerleri ----------------
# ==================================================================
#  WINDOWS'UN KORUDUGU KAYIT DEGERLERI
#  Bazi anahtarlari (or. Pencere Ogeleri ilkesi: HKLM\SOFTWARE\Policies\Microsoft\Dsh) Windows yonetici hesabina bile yazdirmaz
#  (UnauthorizedAccessException). Bu bir program hatasi degildir:
#    - deger "korumali" diye kaydedilir (ayarlar.json > RegDenied),
#    - onizleme ve dogrulama onu bir daha "uygulanacak" saymaz (yoksa her duzeltmede ayni ayar yeniden denenir, hata yazilir ve
#      saglik denetimi sonsuza dek "uygulanmamis ayar var" der),
#    - gercek uygulama sirasinda yine denenir (Windows ileride izin verirse yazilir ve kayit silinir),
#    - denenen ama yazilamayan degisiklik gunlukten (geri alma kaydindan) cikarilir.
#  Test-RegWriteBlocked (uygulamanin kendi yasak listesi) bu bolumden etkilenmez; o liste ayridir.
# ==================================================================
$script:RegDeniedMax = 60

# Ozel durum zincirinde "erisim reddedildi" var mi? (.NET yontem cagrilari ozel durumu MethodInvocationException icine sarar)
function Test-AccessDeniedEx($Ex) {
    $e = $Ex
    $n = 0
    while ($null -ne $e -and $n -lt 8) {
        if ($e -is [System.UnauthorizedAccessException] -or $e -is [System.Security.SecurityException]) { return $true }
        $e = $e.InnerException
        $n++
    }
    return $false
}

function Test-RegDenied([string]$Label) {
    try {
        if ($null -eq $sync -or $null -eq $sync.RegDenied) { return $false }
        return [bool]$sync.RegDenied.ContainsKey($Label.ToLowerInvariant())
    } catch { return $false }
}

function Get-RegDeniedList {
    $out = @()
    try { if ($null -ne $sync -and $null -ne $sync.RegDenied) { $out = @($sync.RegDenied.Keys | Sort-Object) } } catch { }
    return $out
}

function Save-RegDenied {
    try {
        $st = Get-Settings
        $st.RegDenied = @(Get-RegDeniedList | Select-Object -First $script:RegDeniedMax)
        Save-Settings $st
    } catch { }
}

function Register-RegDenied([string]$Label) {
    try {
        if ($null -eq $sync.RegDenied) { return }
        if (-not (Test-ProcAdmin)) { return }
        $k = $Label.ToLowerInvariant()
        if ($sync.RegDenied.ContainsKey($k)) { return }
        if ($sync.RegDenied.Count -ge [int]$script:RegDeniedMax) { return }
        $sync.RegDenied[$k] = $true
        Save-RegDenied
    } catch { }
}

function Clear-RegDenied([string]$Label) {
    try {
        if ($null -eq $sync.RegDenied) { return }
        $k = $Label.ToLowerInvariant()
        if ($sync.RegDenied.ContainsKey($k)) { $sync.RegDenied.Remove($k); Save-RegDenied }
    } catch { }
}

# Kayit defteri isleminin etiketi (Invoke-RegOp ile ayni bicim)
function Get-RegOpLabel($Op) {
    return ((Resolve-RegPath ([string]$Op.Path)) + '\' + [string]$Op.Name)
}

# Ayarin kayit islemlerinden biri Windows tarafindan korunuyorsa $true (arayuzde "Windows engelliyor" yazilir)
function Test-TweakBlocked($Item) {
    try {
        if ($null -eq $Item) { return $false }
        if (@(Get-RegDeniedList).Count -eq 0) { return $false }
        foreach ($op in @($Item.Ops)) {
            if ([string]$op.T -ne 'Reg') { continue }
            if (Test-RegDenied (Get-RegOpLabel $op)) { return $true }
        }
    } catch { }
    return $false
}

# Gunlugun (geri alma kaydinin) son girdisini siler: yazma reddedildiyse yapilmayan degisiklik "geri alinacakmis" gibi gorunmesin.
# Dosyanin ilk satiri basliktir; ona dokunulmaz.
function Remove-LastJournalItem {
    try {
        if ($script:JItems.Count -gt 0) { $script:JItems.RemoveAt($script:JItems.Count - 1) }
        if ($script:JFile -ne '' -and (Test-Path -LiteralPath $script:JFile)) {
            $lines = @([System.IO.File]::ReadAllLines($script:JFile))
            $last = $lines.Count - 1
            while ($last -ge 0 -and [string]::IsNullOrWhiteSpace($lines[$last])) { $last-- }
            if ($last -ge 1) {
                $keep = @($lines[0..($last - 1)])
                [System.IO.File]::WriteAllText($script:JFile, (($keep -join "`r`n") + "`r`n"), (New-Object System.Text.UTF8Encoding($false)))
            }
        }
    } catch { }
}

# Bu surecin yonetici olup olmadigi. Gercek uygulama her zaman yukseltilmis calisir; yalnizca -Duman denemesi yonetici olmadan acilabilir.
# Yonetici olmayan oturumda bir degerin yazilamamasi "Windows korumali" demek degildir; bu yuzden kalici korumali kaydi tutulmaz.
function Test-ProcAdmin {
    if ($null -eq $script:ProcAdminCache) {
        $v = $false
        try { $v = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } catch { $v = $false }
        $script:ProcAdminCache = [bool]$v
    }
    return [bool]$script:ProcAdminCache
}

function Get-RegNoAdminText([string]$Label) {
    return (('Y' + [char]0x00F6 + 'netici izni gerekiyor; y' + [char]0x00F6 + 'netici olmayan oturumda de' + [char]0x011F + 'i' + [char]0x015F + 'tirilemedi: ') + $Label)
}

function Get-RegDeniedText([string]$Label) {
    return (('Windows bu kayd' + [char]0x0131 + ' korumaya alm' + [char]0x0131 + '' + [char]0x015F + ', y' + [char]0x00F6 + 'netici olsan' + [char]0x0131 + 'z da de' + [char]0x011F + 'i' + [char]0x015F + 'tirilemedi (hata de' + [char]0x011F + 'ildir): ') + $Label)
}

# ---------------- Ayrintili hata gunlugu ----------------
# ==================================================================
#  AYRINTILI HATA GUNLUGU  (Baslat.bat -DebugLog  ya da  Ayarlar > Gorunum > Kararlilik)
#  Kapaliyken hicbir sey yapilmaz. Acikken: try / catch ile yakalanip yutulan hatalar ve -ErrorAction SilentlyContinue ile
#  susturulan hatalar da PowerShell'in $Error listesinde birikir. Bu modul listeyi duzenli aralikla okur ve her yeni kaydi
#  Kayitlar klasorundeki ayrinti-GUN.txt dosyasina yazar: saat, kaynak, hata turu / kimligi, ileti, betik satiri, islev zinciri
#  ve o satirin metni. Hata kimligi (FullyQualifiedErrorId) dilden bagimsizdir; ileti Windows'un diliyle gelir.
#  Sinirlar: ayni hata (yol ve sayilar yok sayilarak) bir dakikada bir kez yazilir, otekiler sayilir; dakikada en cok 200 satir;
#  dosya bir gunde 2 MB'ta kesilir. Hicbir sistem ayarina dokunulmaz, hicbir sey disari gonderilmez.
#  Kaynak: ana (arayuz / komut satiri), is (arka plan isi), izleme (canli izleme). Betik satiri Multimizer.ps1 dosyasina goredir;
#  is ve izleme calisma alanlarinda cekirdek betige gore olculen satir, $sync.CoreLineBase ile dosya satirina cevrilir.
#  Bu kod hem arayuz is parcaciginda hem arka plan calisma alanlarinda yukludur.
# ==================================================================

$script:DbgLast = $null
$script:DbgMaxBytes = 2097152
$script:DbgRecMax = 200
$script:DbgPerMin = 200
# Program hatasi olasiligi yuksek hata kimlikleri: bos degere yontem cagrisi, tanimsiz komut / yontem / degisken, baglanamayan parametre
$script:DbgCodeIds = '^(InvokeMethodOnNull|CommandNotFoundException|MethodNotFound|PropertyNotFound|NullArray|VariableIsUndefined|ParameterBinding|ParameterArgument|ArgumentNull)'

function Test-DebugLogOn {
    try { return ($sync.DebugLog -eq $true) } catch { return $false }
}

function Initialize-DebugTables {
    if ($null -eq $sync.DbgStat) { $sync.DbgStat = [hashtable]::Synchronized(@{}) }
    if ($null -eq $sync.DbgSeen) { $sync.DbgSeen = [hashtable]::Synchronized(@{}) }
}

# Gunlugu acar / kapatir (calisma alanlari $sync uzerinden ayni durumu gorur). Acikken $Error listesi 1024 kayda cikarilir.
function Set-DebugLogState([bool]$On) {
    $sync.DebugLog = $On
    if ($On) {
        Initialize-DebugTables
        try { Set-Variable -Name MaximumErrorCount -Value 1024 -Scope Global } catch { }
    }
}

# Ayni kusurun farkli dosya yolu ya da sayiyla yinelenmesi tek kayit sayilsin diye ileti sadelestirilir
function Get-DebugKey([string]$Kind, [string]$Id, [string]$Msg, [int]$Line) {
    $m = $Msg
    if ($m.Length -gt 300) { $m = $m.Substring(0, 300) }
    $m = $m -replace "'[^']*'", "'*'"
    $m = $m -replace '"[^"]*"', '"*"'
    $m = $m -creplace '[A-Za-z]:\\[^\s,;]*', '<yol>'
    $m = $m -replace '\d+', '#'
    if ($m.Length -gt 90) { $m = $m.Substring(0, 90) }
    return ($Kind + '|' + $Id + '|' + [string]$Line + '|' + $m)
}

function Test-DebugCodeError([string]$Id) {
    if ([string]::IsNullOrEmpty($Id)) { return $false }
    return ($Id -match $script:DbgCodeIds)
}

# Bir $Error kaydini (ErrorRecord ya da Exception) alanlarina ayirir; her alan okunamasa bile sonuc doner
function Get-DebugErrorInfo($Rec, [string]$Source = 'ana') {
    $d = @{ Kind = ''; Id = ''; Cat = ''; Msg = ''; Line = 0; Text = ''; Cmd = ''; Chain = ''; Src = $Source }
    try {
        $ex = $null
        if ($Rec -is [System.Management.Automation.ErrorRecord]) { $ex = $Rec.Exception } elseif ($Rec -is [System.Exception]) { $ex = $Rec }
        if ($null -ne $ex) {
            $d.Kind = $ex.GetType().Name
            $d.Msg = ([string]$ex.Message -replace '\s+', ' ').Trim()
        }
        if ($Rec -is [System.Management.Automation.ErrorRecord]) {
            $d.Id = [string]$Rec.FullyQualifiedErrorId
            $d.Cat = [string]$Rec.CategoryInfo.Category
            $ii = $Rec.InvocationInfo
            if ($null -ne $ii) {
                $d.Line = [int]$ii.ScriptLineNumber
                $t = ([string]$ii.Line -replace '\s+', ' ').Trim()
                if ($t.Length -gt 160) { $t = $t.Substring(0, 160) }
                $d.Text = $t
                if ($null -ne $ii.MyCommand) { $d.Cmd = [string]$ii.MyCommand.Name }
            }
            $names = New-Object System.Collections.ArrayList
            foreach ($mt in [regex]::Matches([string]$Rec.ScriptStackTrace, '(?m)^at ([^,\r\n]+),')) {
                $nm = $mt.Groups[1].Value.Trim()
                if ($nm -ne '<ScriptBlock>' -and $names.Count -lt 4) { [void]$names.Add($nm) }
            }
            $d.Chain = ($names.ToArray() -join ' < ')
        }
    } catch { }
    if ($Source -ne 'ana' -and [int]$d.Line -gt 0) {
        try { $d.Line = [int]$d.Line + [int]$sync.CoreLineBase } catch { }
    }
    return $d
}

# Gunluk dosyasina metin ekler (Kayitlar\ayrinti-GUN.txt). Dosya sinirina ulasildiysa $false doner.
function Add-DebugFileText([string]$Text) {
    $dir = [string]$sync.LogDir
    if ([string]::IsNullOrEmpty($dir)) { return $false }
    $day = Get-Date -Format 'yyyyMMdd'
    $f = Join-Path $dir ('ayrinti-' + $day + '.txt')
    $enc = New-Object System.Text.UTF8Encoding($true)
    if ([string]$sync.DbgDay -ne $day) {
        $sync.DbgDay = $day
        $sync.DbgBytes = [long]0
        $sync.DbgFull = $false
        try {
            if (Test-Path -LiteralPath $f) {
                $sync.DbgBytes = [long](Get-Item -LiteralPath $f).Length
            } else {
                $h = '# Multimizer ' + [string]$sync.Version + (' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' hata g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + '. Kaynak: ana = aray' + [char]0x00FC + 'z / komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ', is = arka plan i' + [char]0x015F + 'i, izleme = canl' + [char]0x0131 + ' izleme. Sat' + [char]0x0131 + 'r numaralar' + [char]0x0131 + ' Multimizer.ps1 dosyas' + [char]0x0131 + 'na g' + [char]0x00F6 + 'redir.') + "`r`n"
                [System.IO.File]::AppendAllText($f, $h, $enc)
                $sync.DbgBytes = [long]$h.Length
            }
        } catch { }
    }
    if ($sync.DbgFull -eq $true) { return $false }
    if ([long]$sync.DbgBytes -ge $script:DbgMaxBytes) {
        $sync.DbgFull = $true
        try { [System.IO.File]::AppendAllText($f, ((Get-Date -Format 'HH:mm:ss') + ('  (g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k dosyas' + [char]0x0131 + ' s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'na ula' + [char]0x015F + 't' + [char]0x0131 + '; bu g' + [char]0x00FC + 'n i' + [char]0x00E7 + 'in yeni sat' + [char]0x0131 + 'r yaz' + [char]0x0131 + 'lmayacak)') + "`r`n"), $enc) } catch { }
        return $false
    }
    for ($i = 0; $i -lt 3; $i++) {
        try {
            [System.IO.File]::AppendAllText($f, $Text, $enc)
            $sync.DbgBytes = [long]$sync.DbgBytes + [long]$Text.Length
            return $true
        } catch { Start-Sleep -Milliseconds 25 }
    }
    return $false
}

# Tek kaydi ozet tablosuna isler ve (60 sn icinde yinelenmiyorsa, dakika siniri asilmadiysa) dosyaya yazar
function Write-DebugRecord([string]$Source, $Rec) {
    $d = Get-DebugErrorInfo $Rec $Source
    $msg = [string]$d.Msg
    if ($msg.Length -gt 300) { $msg = $msg.Substring(0, 300) + '...' }
    $key = Get-DebugKey ([string]$d.Kind) ([string]$d.Id) $msg ([int]$d.Line)
    $now = [DateTime]::UtcNow
    Initialize-DebugTables
    $stat = $sync.DbgStat
    if ($stat.ContainsKey($key)) {
        $stat[$key].N = [int]$stat[$key].N + 1
    } elseif ($stat.Count -lt 600) {
        $stat[$key] = @{ N = 1; Kind = [string]$d.Kind; Id = [string]$d.Id; Msg = $msg; Line = [int]$d.Line; Text = [string]$d.Text; Chain = [string]$d.Chain; Src = $Source }
    }
    $seen = $sync.DbgSeen
    $note = ''
    if ($seen.ContainsKey($key)) {
        $e = $seen[$key]
        if (($now - $e.T).TotalSeconds -lt 60) { $e.N = [int]$e.N + 1; return }
        if ([int]$e.N -gt 0) { $note = '  (son dakikada ' + [string]$e.N + ' kez daha)' }
    }
    if ($seen.Count -gt 600) { $seen.Clear() }
    $seen[$key] = @{ T = $now; N = 0 }
    if (($now.Ticks - [long]$sync.DbgWin) -gt 600000000) { $sync.DbgWin = [long]$now.Ticks; $sync.DbgWinN = 0 }
    $sync.DbgWinN = [int]$sync.DbgWinN + 1
    if ([int]$sync.DbgWinN -gt $script:DbgPerMin) { return }
    $head = (Get-Date -Format 'HH:mm:ss') + '  [' + $Source + ']  ' + [string]$d.Kind
    if ([string]$d.Id -ne '' -and [string]$d.Id -ne [string]$d.Kind) { $head += ' / ' + [string]$d.Id }
    $head += ': ' + $msg + $note
    $sub = ''
    if ([int]$d.Line -gt 0) { $sub += ('sat' + [char]0x0131 + 'r ') + [string]$d.Line }
    if ([string]$d.Chain -ne '') { $sub += ('  i' + [char]0x015F + 'lev: ') + [string]$d.Chain }
    if ([string]$d.Text -ne '') { $sub += '  >>  ' + [string]$d.Text }
    $txt = $head + "`r`n"
    if ($sub.Trim() -ne '') { $txt += '          ' + $sub.Trim() + "`r`n" }
    [void](Add-DebugFileText $txt)
}

# $Error listesindeki yeni kayitlari (son islenenden sonrakiler) eskiden yeniye yazar. Kapaliyken hemen doner.
# Dondurdugu sayi: islenen kayit sayisi.
function Save-DebugErrors([string]$Source = 'ana') {
    if ($sync.DebugLog -ne $true) { return 0 }
    $done = 0
    try {
        $cnt = $Error.Count
        if ($cnt -gt 0) {
            $newest = $Error[0]
            if (-not [object]::ReferenceEquals($newest, $script:DbgLast)) {
                $recs = New-Object System.Collections.ArrayList
                for ($i = 0; $i -lt $cnt -and $recs.Count -lt $script:DbgRecMax; $i++) {
                    $r = $Error[$i]
                    if ([object]::ReferenceEquals($r, $script:DbgLast)) { break }
                    [void]$recs.Add($r)
                }
                for ($i = $recs.Count - 1; $i -ge 0; $i--) { Write-DebugRecord $Source $recs[$i]; $done++ }
            }
        }
    } catch { }
    # bu islevin kendi yutulan hatalari bir sonraki turda yeniden islenmesin
    try { if ($Error.Count -gt 0) { $script:DbgLast = $Error[0] } } catch { }
    return $done
}

# Ozet: en sik yinelenen hatalar (satir basina bir hata turu). Program hatasi olasiligi yuksek olanlar [kod?] ile isaretlenir.
function Get-DebugSummary([int]$Top = 30) {
    $stat = $sync.DbgStat
    if ($null -eq $stat -or $stat.Count -eq 0) { return }
    $rows = New-Object System.Collections.ArrayList
    foreach ($k in @($stat.Keys)) { [void]$rows.Add([pscustomobject]@{ N = [int]$stat[$k].N; E = $stat[$k] }) }
    $i = 0
    foreach ($r in @($rows | Sort-Object -Property N -Descending)) {
        if ($i -ge $Top) { break }
        $i++
        $e = $r.E
        $flag = ''
        if (Test-DebugCodeError ([string]$e.Id)) { $flag = '[kod?] ' }
        $s = ('{0,5}x  {1}{2}' -f [int]$e.N, $flag, [string]$e.Kind)
        if ([string]$e.Id -ne '' -and [string]$e.Id -ne [string]$e.Kind) { $s += ' / ' + [string]$e.Id }
        $s += ': ' + [string]$e.Msg
        if ([int]$e.Line -gt 0) { $s += ('  | sat' + [char]0x0131 + 'r ') + [string]$e.Line }
        if ([string]$e.Chain -ne '') { $s += ' (' + [string]$e.Chain + ')' }
        if ([string]$e.Text -ne '') { $s += '  >> ' + [string]$e.Text }
        $s
    }
}

# Ozet sayilari: Kinds = farkli hata turu, Total = toplam kayit, Code = [kod?] isaretli tur sayisi
function Get-DebugCounts {
    $kinds = 0; $total = 0; $code = 0
    $stat = $sync.DbgStat
    if ($null -ne $stat) {
        foreach ($k in @($stat.Keys)) {
            $kinds++
            $total += [int]$stat[$k].N
            if (Test-DebugCodeError ([string]$stat[$k].Id)) { $code++ }
        }
    }
    return @{ Kinds = $kinds; Total = $total; Code = $code }
}


# ---------------- kararlilik cozumleyici: mavi ekran, uygulama cokmesi, acilis suresi ----------------
# ==================================================================
#  KARARLILIK COZUMLEYICI: mavi ekran kodlari, uygulama cokmeleri ve acilis suresi
#  Yalnizca olay gunluklerini okur, hicbir seyi degistirmez. Olay metinleri Windows diline bagli oldugundan yalnizca olay kimlikleri ve veri
#  alanlari kullanilir; Turkce, Ingilizce ya da baska dilli Windows'ta ayni sonucu verir. Her bulgu nedenini ve atilacak adimi soyler.
#  Yeniden baslatma isteyen bellek sinamasi gibi adimlar yalnizca kullanici dugmeye basinca Windows'un kendi aracini acar.
# ==================================================================

# Hata denetimi (mavi ekran) kodlari. Bicim: 'KOD|AD|TUR'. KOD buyuk harfli onaltilik, bastaki sifirlar atilmis (0x0000000A -> A).
# TUR: driver (surucu), gpu (ekran karti), memory (bellek), disk (disk ve dosya sistemi), hardware (islemci, anakart, asiri hiz, guc),
#      system (Windows dosyalari), power (guc gecisi), manual (elle uretilmis). Adlar Microsoft'un hata denetimi kodu basvurusundaki adlardir.
$script:BugcheckList = @(
    'A|IRQL_NOT_LESS_OR_EQUAL|driver',
    '1A|MEMORY_MANAGEMENT|memory',
    '1E|KMODE_EXCEPTION_NOT_HANDLED|driver',
    '23|FAT_FILE_SYSTEM|disk',
    '24|NTFS_FILE_SYSTEM|disk',
    '2E|DATA_BUS_ERROR|memory',
    '3B|SYSTEM_SERVICE_EXCEPTION|driver',
    '3F|NO_MORE_SYSTEM_PTES|driver',
    '4E|PFN_LIST_CORRUPT|memory',
    '50|PAGE_FAULT_IN_NONPAGED_AREA|memory',
    '51|REGISTRY_ERROR|disk',
    '77|KERNEL_STACK_INPAGE_ERROR|disk',
    '7A|KERNEL_DATA_INPAGE_ERROR|disk',
    '7B|INACCESSIBLE_BOOT_DEVICE|disk',
    '7E|SYSTEM_THREAD_EXCEPTION_NOT_HANDLED|driver',
    '7F|UNEXPECTED_KERNEL_MODE_TRAP|hardware',
    '8E|KERNEL_MODE_EXCEPTION_NOT_HANDLED|driver',
    '9C|MACHINE_CHECK_EXCEPTION|hardware',
    '9F|DRIVER_POWER_STATE_FAILURE|power',
    'A0|INTERNAL_POWER_ERROR|power',
    'BE|ATTEMPTED_WRITE_TO_READONLY_MEMORY|driver',
    'C2|BAD_POOL_CALLER|driver',
    'C4|DRIVER_VERIFIER_DETECTED_VIOLATION|driver',
    'C5|DRIVER_CORRUPTED_EXPOOL|driver',
    'CA|PNP_DETECTED_FATAL_ERROR|driver',
    'D1|DRIVER_IRQL_NOT_LESS_OR_EQUAL|driver',
    'D5|DRIVER_PAGE_FAULT_IN_FREED_SPECIAL_POOL|driver',
    'E2|MANUALLY_INITIATED_CRASH|manual',
    'EA|THREAD_STUCK_IN_DEVICE_DRIVER|gpu',
    'EF|CRITICAL_PROCESS_DIED|system',
    'F4|CRITICAL_OBJECT_TERMINATION|disk',
    'FC|ATTEMPTED_EXECUTE_OF_NOEXECUTE_MEMORY|driver',
    '101|CLOCK_WATCHDOG_TIMEOUT|hardware',
    '109|CRITICAL_STRUCTURE_CORRUPTION|hardware',
    '116|VIDEO_TDR_FAILURE|gpu',
    '117|VIDEO_TDR_TIMEOUT_DETECTED|gpu',
    '119|VIDEO_SCHEDULER_INTERNAL_ERROR|gpu',
    '124|WHEA_UNCORRECTABLE_ERROR|hardware',
    '133|DPC_WATCHDOG_VIOLATION|driver',
    '139|KERNEL_SECURITY_CHECK_FAILURE|driver',
    '13A|KERNEL_MODE_HEAP_CORRUPTION|driver',
    '141|VIDEO_ENGINE_TIMEOUT_DETECTED|gpu',
    '154|UNEXPECTED_STORE_EXCEPTION|disk',
    '1CA|SYNTHETIC_WATCHDOG_TIMEOUT|hardware',
    'C000021A|STATUS_SYSTEM_PROCESS_TERMINATED|system'
)
$script:BugcheckInfo = @{}
foreach ($bcLine in $script:BugcheckList) {
    $bcPart = ([string]$bcLine).Split('|')
    $script:BugcheckInfo[[string]$bcPart[0]] = @{ Key = [string]$bcPart[0]; Hex = ('0x' + ([string]$bcPart[0]).PadLeft(8, '0')); Name = [string]$bcPart[1]; Kind = [string]$bcPart[2] }
}

# "0x00000133 (0x0000000000000001, ...)" -> "133"; sayi bulunamazsa bos
function ConvertTo-BugcheckKey([string]$Text) {
    $m = [regex]::Match([string]$Text, '(?i)0x([0-9a-f]{1,8})')
    if (-not $m.Success) { return '' }
    $h = $m.Groups[1].Value.TrimStart('0').ToUpperInvariant()
    if ($h -eq '') { $h = '0' }
    return $h
}

# Bilinmeyen kod: Ad bos, Tur other
function Get-BugcheckInfo([string]$Key) {
    $k = ([string]$Key).Trim().ToUpperInvariant()
    if ($script:BugcheckInfo.ContainsKey($k)) { return $script:BugcheckInfo[$k] }
    $pad = $k
    if ($pad -eq '') { $pad = '0' }
    return @{ Key = $k; Hex = ('0x' + $pad.PadLeft(8, '0')); Name = ''; Kind = 'other' }
}

function Format-BugcheckLabel($Row) {
    if ([string]$Row.Name -ne '') { return ([string]$Row.Name + ' (' + [string]$Row.Hex + ')') }
    return ('kod ' + [string]$Row.Hex)
}

