        $a.Do = ('Windows' + [char]0x2019 + 'u ve s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri g' + [char]0x00FC + 'ncelleyin, Ara' + [char]0x00E7 + 'lar > Onar' + [char]0x0131 + 'm' + [char]0x2019 + 'da sistem dosyas' + [char]0x0131 + ' denetimini ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n. Kodu Microsoft' + [char]0x2019 + 'un ' + [char]0x201C + 'Hata denetimi kodu ba' + [char]0x015F + 'vurusu' + [char]0x201D + ' sayfas' + [char]0x0131 + 'nda aratabilirsiniz.')
    }
    return $a
}

function New-BugcheckAction($Advice) {
    if ([string]$Advice.Run -eq 'MemDiag') { return @{ Kind = 'Run'; Key = 'MemDiag'; Label = ('Bellek s' + [char]0x0131 + 'namas' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '') } }
    if ([string]$Advice.Page -eq 'solve') { return (New-SolveAction 'disk' '' ('Diskleri a' + [char]0x00E7 + '')) }
    return @{ Kind = 'Page'; Page = 'tools'; Label = ('Onar' + [char]0x0131 + 'm') }
}

# Windows Bellek Tanilama'yi acar; sinama ve yeniden baslatma secenegini kullanici kendisi secer
function Invoke-MemDiagAction($P) {
    $exe = Join-Path ([string]$env:WINDIR) 'System32\MdSched.exe'
    if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) { throw ('Windows Bellek Tan' + [char]0x0131 + 'lama bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde bulunamad' + [char]0x0131 + '.') }
    Start-Process -FilePath $exe | Out-Null
    Write-WhLog ('Windows Bellek Tan' + [char]0x0131 + 'lama a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '. S' + [char]0x0131 + 'namay' + [char]0x0131 + ' ba' + [char]0x015F + 'lat' + [char]0x0131 + 'rsan' + [char]0x0131 + 'z bilgisayar yeniden ba' + [char]0x015F + 'lar; ' + [char]0x00F6 + 'nce a' + [char]0x00E7 + '' + [char]0x0131 + 'k dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' kaydedin.') 'INFO'
}
$script:ExtraActions['MemDiag'] = 'Invoke-MemDiagAction'

# Olay veri alanlari: Ad -> deger (XML'den; dile bagli degil)
function Get-EventDataMap($Ev) {
    $m = @{}
    try {
        $x = [xml]$Ev.ToXml()
        foreach ($d in @($x.Event.EventData.Data)) {
            if ($null -ne $d -and $null -ne $d.Name) { $m[[string]$d.Name] = [string]$d.'#text' }
        }
    } catch { }
    return $m
}

function ConvertTo-MsValue($Value) {
    $d = 0.0
    if ([double]::TryParse([string]$Value, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { return $d }
    return 0.0
}

function Get-NumMedian($Values) {
    $v = @(@($Values) | ForEach-Object { [double]$_ } | Sort-Object)
    if ($v.Count -eq 0) { return 0.0 }
    $mid = [int][math]::Floor($v.Count / 2)
    if (($v.Count % 2) -eq 1) { return [double]$v[$mid] }
    return (([double]$v[$mid - 1] + [double]$v[$mid]) / 2.0)
}

# Bir sayac tablosunda (ad -> adet) en cok gecen ad; esitlikte alfabetik ilk
function Get-CountTopKey($Counts) {
    $best = ''
    $bestN = 0
    foreach ($k in (@($Counts.Keys) | Sort-Object)) {
        if ([int]$Counts[$k] -gt $bestN) { $best = [string]$k; $bestN = [int]$Counts[$k] }
    }
    return $best
}

# ---------------- mavi ekran ----------------
# Donus: @(@{ Time; Key }) (yeni kayitlar onde olmak zorunda degil). Sistem gunlugu, WER-SystemErrorReporting 1001
function Get-BugcheckEvents([int]$Days = 30) {
    $out = New-Object System.Collections.ArrayList
    $evs = @()
    try { $evs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WER-SystemErrorReporting'; Id = 1001; StartTime = (Get-Date).AddDays(-$Days) } -MaxEvents 100 -ErrorAction Stop) } catch { $evs = @() }
    foreach ($e in $evs) {
        $txt = ''
        try { if ($e.Properties.Count -gt 0) { $txt = [string]$e.Properties[0].Value } } catch { $txt = '' }
        $k = ConvertTo-BugcheckKey $txt
        if ($k -eq '') { try { $k = ConvertTo-BugcheckKey ([string]$e.Message) } catch { $k = '' } }
        if ($k -eq '') { continue }
        [void]$out.Add(@{ Time = [datetime]$e.TimeCreated; Key = $k })
    }
    return , $out.ToArray()
}

# Mavi ekran olmadan gerceklesen beklenmedik kapanmalar (Kernel-Power 41, BugcheckCode 0)
function Get-PowerLossCount([int]$Days = 30) {
    $n = 0
    $evs = @()
    try { $evs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Kernel-Power'; Id = 41; StartTime = (Get-Date).AddDays(-$Days) } -MaxEvents 100 -ErrorAction Stop) } catch { return 0 }
    foreach ($e in $evs) {
        $m = Get-EventDataMap $e
        $bc = 0.0
        if ($m.ContainsKey('BugcheckCode')) { $bc = ConvertTo-MsValue $m['BugcheckCode'] }
        if ($bc -eq 0) { $n++ }
    }
    return $n
}

# Kodlara gore ozet: Total (elle uretilenler haric), Manual, Last, Rows (en sik olan onde)
function Get-BugcheckSummary($Events) {
    $by = @{}
    $manual = 0
    $last = [datetime]'2000-01-01'
    foreach ($e in @($Events)) {
        $k = [string]$e.Key
        if ($k -eq '') { continue }
        $inf = Get-BugcheckInfo $k
        if ([string]$inf.Kind -eq 'manual') { $manual++; continue }
        if (-not $by.ContainsKey($k)) { $by[$k] = @{ Count = 0; Last = [datetime]'2000-01-01' } }
        $by[$k].Count = [int]$by[$k].Count + 1
        if ($e.Time -gt $by[$k].Last) { $by[$k].Last = $e.Time }
        if ($e.Time -gt $last) { $last = $e.Time }
    }
    $rows = New-Object System.Collections.ArrayList
    foreach ($k in $by.Keys) {
        $inf = Get-BugcheckInfo ([string]$k)
        [void]$rows.Add(@{ Key = [string]$k; Hex = [string]$inf.Hex; Name = [string]$inf.Name; Kind = [string]$inf.Kind; Count = [int]$by[$k].Count; Last = $by[$k].Last })
    }
    $sorted = @($rows | Sort-Object @{ Expression = { [int]$_.Count }; Descending = $true }, @{ Expression = { $_.Last }; Descending = $true }, @{ Expression = { [string]$_.Key } })
    $total = 0
    foreach ($r in $sorted) { $total += [int]$r.Count }
    return @{ Total = $total; Manual = $manual; Last = $last; Rows = $sorted }
}

# En sik gorulen kodun turu; o bilinmiyorsa bilinen ilk tur
function Get-BugcheckDominantKind($Summary) {
    $rows = @($Summary.Rows)
    if ($rows.Count -eq 0) { return 'other' }
    if ([string]$rows[0].Kind -ne 'other') { return [string]$rows[0].Kind }
    foreach ($r in $rows) { if ([string]$r.Kind -ne 'other') { return [string]$r.Kind } }
    return 'other'
}

function Add-BugcheckFindings($Summary, [int]$Days, [int]$PowerLoss) {
    $d = [string]$Days
    $n = [int]$Summary.Total
    if ($n -eq 0) {
        Add-Finding 'bsod' 'maint' 'ok' ('Son ' + $d + (' g' + [char]0x00FC + 'nde mavi ekran hatas' + [char]0x0131 + ' yok')) ''
    } else {
        $rows = @($Summary.Rows)
        $kind = Get-BugcheckDominantKind $Summary
        $adv = Get-BugcheckAdvice $kind
        $parts = New-Object System.Collections.ArrayList
        [void]$parts.Add('Son hata: ' + $Summary.Last.ToString('dd.MM.yyyy HH:mm') + '.')
        if ($rows.Count -gt 1) {
            $oth = New-Object System.Collections.ArrayList
            foreach ($r in @($rows | Select-Object -Skip 1 -First 3)) { [void]$oth.Add((Format-BugcheckLabel $r) + ' ' + [string]$r.Count + ' kez') }
            [void]$parts.Add(('Di' + [char]0x011F + 'er kodlar: ') + ($oth.ToArray() -join ', ') + '.')
        }
        [void]$parts.Add([string]$adv.Why)
        if ([string]$adv.Do -ne '') { [void]$parts.Add([string]$adv.Do) }
        $status = 'info'
        $w = 0
        if ($n -ge 3) { $status = 'warn'; $w = 6 }
        $title = 'Son ' + $d + (' g' + [char]0x00FC + 'nde ') + [string]$n + (' mavi ekran hatas' + [char]0x0131 + ': ') + (Format-BugcheckLabel $rows[0])
        Add-Finding 'bsod' 'maint' $status $title ($parts.ToArray() -join ' ') (New-BugcheckAction $adv) $w
    }
    if ($PowerLoss -ge 3) {
        Add-Finding 'pwr41' 'maint' 'info' ('Son ' + $d + (' g' + [char]0x00FC + 'nde ') + [string]$PowerLoss + ' beklenmedik kapanma') ('Bunlar mavi ekran vermeden kapanm' + [char]0x0131 + '' + [char]0x015F + ': bilgisayar kendili' + [char]0x011F + 'inden kapand' + [char]0x0131 + ' ya da g' + [char]0x00FC + '' + [char]0x00E7 + ' kesildi. Elektrik kesintisi, a' + [char]0x015F + '' + [char]0x0131 + 'r' + [char]0x0131 + ' ' + [char]0x0131 + 's' + [char]0x0131 + 'nma, gev' + [char]0x015F + 'ek g' + [char]0x00FC + '' + [char]0x00E7 + ' ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' ya da g' + [char]0x00FC + '' + [char]0x00E7 + ' kayna' + [char]0x011F + '' + [char]0x0131 + ' sorunu olabilir; diz' + [char]0x00FC + 'st' + [char]0x00FC + 'nde ' + [char]0x015F + 'arj kablosunu ve pili de deneyin.')
    }
}

function Chk_Crashes {
    $days = 30
    $ev = Get-BugcheckEvents $days
    $sum = Get-BugcheckSummary $ev
    $loss = Get-PowerLossCount $days
    Add-BugcheckFindings $sum $days $loss
}

# ---------------- uygulama cokmeleri ----------------
# Application Error (1000) ve Application Hang (1002). Donus: @(@{ Time; Kind (crash | hang); App; Module; Code; Path })
function Get-AppCrashEvents([int]$Days = 30) {
    $out = New-Object System.Collections.ArrayList
    $since = (Get-Date).AddDays(-$Days)
    $evs = @()
    try { $evs = @(Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Application Error'; Id = 1000; StartTime = $since } -MaxEvents 400 -ErrorAction Stop) } catch { $evs = @() }
    foreach ($e in $evs) {
        $p = $null
        try { $p = $e.Properties } catch { $p = $null }
        if ($null -eq $p -or $p.Count -lt 7) { continue }
        $path = ''
        if ($p.Count -gt 10) { $path = [string]$p[10].Value }
        [void]$out.Add(@{ Time = [datetime]$e.TimeCreated; Kind = 'crash'; App = [string]$p[0].Value; Module = [string]$p[3].Value; Code = [string]$p[6].Value; Path = $path })
    }
    $hv = @()
    try { $hv = @(Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Application Hang'; Id = 1002; StartTime = $since } -MaxEvents 200 -ErrorAction Stop) } catch { $hv = @() }
    foreach ($e in $hv) {
        $p = $null
        try { $p = $e.Properties } catch { $p = $null }
        if ($null -eq $p -or $p.Count -lt 1) { continue }
        $path = ''
        if ($p.Count -gt 5) { $path = [string]$p[5].Value }
        [void]$out.Add(@{ Time = [datetime]$e.TimeCreated; Kind = 'hang'; App = [string]$p[0].Value; Module = ''; Code = ''; Path = $path })
    }
    return , $out.ToArray()
}

# Programa gore ozet: Total, Rows (en cok kayit olan onde; her satir: App, Count, Crashes, Hangs, Last, Path, Module, Code)
function Get-AppCrashSummary($Events, [int]$Top = 5) {
    $by = @{}
    $total = 0
    foreach ($e in @($Events)) {
        $app = ([string]$e.App).Trim().ToLowerInvariant()
        if ($app -eq '') { continue }
        $total++
        if (-not $by.ContainsKey($app)) { $by[$app] = @{ Crashes = 0; Hangs = 0; Last = [datetime]'2000-01-01'; Mods = @{}; Codes = @{}; Path = '' } }
        $r = $by[$app]
        if ([string]$e.Kind -eq 'hang') { $r.Hangs = [int]$r.Hangs + 1 } else { $r.Crashes = [int]$r.Crashes + 1 }
        if ($e.Time -gt $r.Last) {
            $r.Last = $e.Time
            if ([string]$e.Path -ne '') { $r.Path = [string]$e.Path }
        }
        $m = ([string]$e.Module).Trim().ToLowerInvariant()
        if ($m -ne '') { if ($r.Mods.ContainsKey($m)) { $r.Mods[$m] = [int]$r.Mods[$m] + 1 } else { $r.Mods[$m] = 1 } }
        $c = ([string]$e.Code).Trim().ToLowerInvariant()
        if ($c -ne '') { if ($r.Codes.ContainsKey($c)) { $r.Codes[$c] = [int]$r.Codes[$c] + 1 } else { $r.Codes[$c] = 1 } }
    }
    $rows = New-Object System.Collections.ArrayList
    foreach ($k in $by.Keys) {
        $r = $by[$k]
        [void]$rows.Add(@{ App = [string]$k; Count = ([int]$r.Crashes + [int]$r.Hangs); Crashes = [int]$r.Crashes; Hangs = [int]$r.Hangs; Last = $r.Last; Path = [string]$r.Path
            Module = (Get-CountTopKey $r.Mods); Code = (Get-CountTopKey $r.Codes) })
    }
    $sorted = @($rows | Sort-Object @{ Expression = { [int]$_.Count }; Descending = $true }, @{ Expression = { $_.Last }; Descending = $true }, @{ Expression = { [string]$_.App } })
    return @{ Total = $total; Rows = @($sorted | Select-Object -First $Top) }
}

# Calisma zamani kitapliklari (Visual C++, DirectX); yukleyici hatalari: DLL bulunamadi / baslatilamadi / gecersiz goruntu
$script:RuntimeModuleRx = '^(vcruntime|msvcp|msvcr|vcomp|concrt|mfc[0-9]|d3dx9|d3dx10|d3dx11|d3dcompiler|xinput1|xaudio2|x3daudio|xapofx)'
$script:GpuModuleRx = '^(nvwgf2um|nvd3dum|nvoglv|nvlddmkm|nvcuda|nvapi|atidxx|atiumd|amdxx|amdvlk|atio6axx|igd[0-9a-z]*umd|ig9icd|igc64)'
$script:SystemAppRx = '^(explorer|dwm|svchost|sihost|searchhost|searchapp|startmenuexperiencehost|shellexperiencehost|runtimebroker|taskhostw|ctfmon|textinputhost|lockapp|winlogon|csrss|services|lsass|fontdrvhost|wudfhost|dllhost|conhost|audiodg|spoolsv|msedgewebview2)\.exe$'

function Test-SystemAppRow($Row) {
    $app = [string]$Row.App
    if ($app -match $script:SystemAppRx) { return $true }
    $win = ([string]$env:WINDIR).ToLowerInvariant()
    $pth = ([string]$Row.Path).ToLowerInvariant()
    if ($win -ne '' -and $pth.StartsWith($win + '\') -and -not $pth.StartsWith($win + '\temp\')) { return $true }
    return $false
}

# Bir program satiri icin tur, neden, atilacak adim ve eylem
function Get-AppCrashAdvice($Row) {
    $a = @{ Kind = 'generic'; Why = ''; Do = ''; Action = $null }
    $mod = [string]$Row.Module
    $code = [string]$Row.Code
    $app = [string]$Row.App
    $loader = ($code -eq 'c0000135' -or $code -eq 'c0000142' -or $code -eq 'c000007b')
    if ($loader -or ($mod -ne '' -and $mod -match $script:RuntimeModuleRx)) {
        $a.Kind = 'runtime'
        $a.Why = ('Program, eksik ya da bozuk bir ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + ' kitapl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' (Visual C++, DirectX ya da benzeri) y' + [char]0x00FC + 'z' + [char]0x00FC + 'nden a' + [char]0x00E7 + '' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor veya ' + [char]0x00E7 + '' + [char]0x00F6 + 'k' + [char]0x00FC + 'yor.')
        $a.Do = ('Microsoft' + [char]0x2019 + 'un sayfas' + [char]0x0131 + 'ndan Visual C++ Yeniden Da' + [char]0x011F + '' + [char]0x0131 + 't' + [char]0x0131 + 'labilir paketini (x64 ve x86) kurun ya da onar' + [char]0x0131 + 'n; eski oyunlar i' + [char]0x00E7 + 'in DirectX Son Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' ' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma Zaman' + [char]0x0131 + ' da gerekebilir. Olmazsa program' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'p yeniden kurun.')
        $a.Action = @{ Kind = 'Url'; Url = 'https://learn.microsoft.com/cpp/windows/latest-supported-vc-redist'; Label = ('Visual C++ paketini a' + [char]0x00E7 + '') }
    } elseif ($mod -ne '' -and $mod -match $script:GpuModuleRx) {
        $a.Kind = 'gpu'
        $a.Why = ('' + [char]0x00C7 + '' + [char]0x00F6 + 'kme noktas' + [char]0x0131 + ' ekran kart' + [char]0x0131 + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor.')
        $a.Do = ('Ekran kart' + [char]0x0131 + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + ' ' + [char]0x00FC + 'reticisinden indirip ' + [char]0x201C + 'temiz kurulum' + [char]0x201D + ' se' + [char]0x00E7 + 'ene' + [char]0x011F + 'iyle yeniden kurun; a' + [char]0x015F + '' + [char]0x0131 + 'r' + [char]0x0131 + ' h' + [char]0x0131 + 'z ve oyun i' + [char]0x00E7 + 'i bindirmeleri (overlay) kapat' + [char]0x0131 + 'p deneyin.')
    } elseif ($app -match '^(powershell|pwsh)\.exe$') {
        $a.Kind = 'powershell'
        $a.Why = ('Bir PowerShell oturumu ' + [char]0x00E7 + '' + [char]0x00F6 + 'km' + [char]0x00FC + '' + [char]0x015F + '. Multimizer de Windows PowerShell ' + [char]0x00FC + 'zerinde ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' i' + [char]0x00E7 + 'in ' + [char]0x00E7 + '' + [char]0x00F6 + 'ken oturum bu uygulamaya ait olabilir.')
        $a.Do = ('' + [char]0x00C7 + '' + [char]0x00F6 + 'kme Multimizer ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'rken oluyorsa Ayarlar > G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm > Kararl' + [char]0x0131 + 'l' + [char]0x0131 + 'k b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nden ' + [char]0x201C + 'G' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim (yaln' + [char]0x0131 + 'zca yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'mla ' + [char]0x00E7 + 'iz)' + [char]0x201D + ' se' + [char]0x00E7 + 'ene' + [char]0x011F + 'ini a' + [char]0x00E7 + '' + [char]0x0131 + 'n. Ayn' + [char]0x0131 + ' yerdeki ' + [char]0x201C + 'Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' hata g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + '' + [char]0x201D + ' se' + [char]0x00E7 + 'ene' + [char]0x011F + 'i sorunun izini Kay' + [char]0x0131 + 'tlar klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'ne yazar.')
        $a.Action = @{ Kind = 'Page'; Page = 'settings'; Label = ('Ayarlar' + [char]0x0131 + ' a' + [char]0x00E7 + '') }
    } elseif (Test-SystemAppRow $Row) {
        $a.Kind = 'system'
        $a.Why = ('Bir Windows bile' + [char]0x015F + 'eni ' + [char]0x00E7 + '' + [char]0x00F6 + 'k' + [char]0x00FC + 'yor. Bozulmu' + [char]0x015F + ' sistem dosyalar' + [char]0x0131 + ', yar' + [char]0x0131 + 'm kalm' + [char]0x0131 + '' + [char]0x015F + ' bir g' + [char]0x00FC + 'ncelleme ya da uyumsuz bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' bunun nedeni olabilir.')
        $a.Do = ('Ara' + [char]0x00E7 + 'lar > Onar' + [char]0x0131 + 'm' + [char]0x2019 + 'da sistem dosyas' + [char]0x0131 + ' denetimini (SFC) ve DISM onar' + [char]0x0131 + 'm' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n. Sorun bir g' + [char]0x00FC + 'ncellemeden ya da s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'den sonra ba' + [char]0x015F + 'lad' + [char]0x0131 + 'ysa onu geri al' + [char]0x0131 + 'n.')
        $a.Action = @{ Kind = 'Page'; Page = 'tools'; Label = ('Onar' + [char]0x0131 + 'm') }
    } elseif ($code -eq 'e0434352') {
        $a.Kind = 'dotnet'
        $a.Why = ('Program, .NET taraf' + [char]0x0131 + 'nda yakalanmam' + [char]0x0131 + '' + [char]0x015F + ' bir hatayla kapand' + [char]0x0131 + '.')
        $a.Do = ('Program' + [char]0x0131 + ' en son s' + [char]0x00FC + 'r' + [char]0x00FC + 'me g' + [char]0x00FC + 'ncelleyin. Windows Update' + [char]0x2019 + 'in .NET Framework g' + [char]0x00FC + 'ncellemelerini kurdu' + [char]0x011F + 'unu denetleyin; s' + [char]0x00FC + 'rerse program' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'p yeniden kurun.')
    } elseif ([int]$Row.Hangs -gt [int]$Row.Crashes) {
        $a.Kind = 'hang'
        $a.Why = ('Program s' + [char]0x0131 + 'k s' + [char]0x0131 + 'k yan' + [char]0x0131 + 't vermeyi b' + [char]0x0131 + 'rak' + [char]0x0131 + 'yor. Yava' + [char]0x015F + ' disk, bellek yetersizli' + [char]0x011F + 'i ya da program' + [char]0x0131 + 'n bir eklentisi s' + [char]0x0131 + 'k nedenlerdir.')
        $a.Do = ('Program' + [char]0x0131 + 'n eklentilerini kapat' + [char]0x0131 + 'p deneyin, bo' + [char]0x015F + ' bellek ve disk alan' + [char]0x0131 + 'na bak' + [char]0x0131 + 'n, program' + [char]0x0131 + ' g' + [char]0x00FC + 'ncelleyin. Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' sayfas' + [char]0x0131 + 'ndan arka planda gereksiz ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an programlar' + [char]0x0131 + ' kapatmak da yard' + [char]0x0131 + 'mc' + [char]0x0131 + ' olur.')
    } else {
        $a.Why = ('Program tekrar tekrar kapan' + [char]0x0131 + 'yor. ' + [char]0x00C7 + 'o' + [char]0x011F + 'unlukla program' + [char]0x0131 + 'n kendi hatas' + [char]0x0131 + ' ya da bir eklentisi sorumludur.')
        $a.Do = ('Program' + [char]0x0131 + ' en son s' + [char]0x00FC + 'r' + [char]0x00FC + 'me g' + [char]0x00FC + 'ncelleyin, eklentilerini kapat' + [char]0x0131 + 'n, olmazsa kald' + [char]0x0131 + 'r' + [char]0x0131 + 'p yeniden kurun. S' + [char]0x00FC + 'rerse ' + [char]0x00FC + 'reticiye bildirin.')
    }
    return $a
}

function Add-AppCrashFindings($Sum, [int]$Days) {
    $d = [string]$Days
    $rows = @($Sum.Rows)
    if ([int]$Sum.Total -eq 0 -or $rows.Count -eq 0) {
        Add-Finding 'app-crash' 'maint' 'ok' ('Son ' + $d + (' g' + [char]0x00FC + 'nde uygulama ' + [char]0x00E7 + '' + [char]0x00F6 + 'kmesi yok')) ''
        return
    }
    $top = $rows[0]
    if ([int]$top.Count -lt 2) {
        Add-Finding 'app-crash' 'maint' 'ok' ('Son ' + $d + (' g' + [char]0x00FC + 'nde belirgin uygulama ' + [char]0x00E7 + '' + [char]0x00F6 + 'kmesi yok')) (('Tek t' + [char]0x00FC + 'k kay' + [char]0x0131 + 't var (') + [string]$Sum.Total + (' olay); yinelenen bir sorun g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor.'))
        return
    }
    $adv = Get-AppCrashAdvice $top
    $what = New-Object System.Collections.ArrayList
    if ([int]$top.Crashes -gt 0) { [void]$what.Add([string]$top.Crashes + (' kez ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + '')) }
    if ([int]$top.Hangs -gt 0) { [void]$what.Add([string]$top.Hangs + (' kez yan' + [char]0x0131 + 't vermedi')) }
    $title = ('' + [char]0x201C + '') + [string]$top.App + ('' + [char]0x201D + ' son ') + $d + (' g' + [char]0x00FC + 'nde ') + ($what.ToArray() -join ' ve ')
    $parts = New-Object System.Collections.ArrayList
    [void]$parts.Add(('Son kay' + [char]0x0131 + 't: ') + $top.Last.ToString('dd.MM.yyyy HH:mm') + '.')
    if ([string]$top.Module -ne '') {
        $pt = [string]$top.Module
        if ([string]$top.Code -ne '') { $pt += ' (' + [string]$top.Code + ')' }
        [void]$parts.Add(('' + [char]0x00C7 + '' + [char]0x00F6 + 'kme noktas' + [char]0x0131 + ': ') + $pt + '.')
    }
    if ($rows.Count -gt 1) {
        $oth = New-Object System.Collections.ArrayList
        foreach ($r in @($rows | Select-Object -Skip 1 -First 3)) { [void]$oth.Add([string]$r.App + ' (' + [string]$r.Count + ')') }
        [void]$parts.Add(('Di' + [char]0x011F + 'er: ') + ($oth.ToArray() -join ', ') + '.')
    }
    [void]$parts.Add([string]$adv.Why)
    [void]$parts.Add([string]$adv.Do)
    $status = 'info'
    $w = 0
    if ([int]$top.Count -ge 5) { $status = 'warn'; $w = 3 }
    Add-Finding 'app-crash' 'maint' $status $title ($parts.ToArray() -join ' ') $adv.Action $w
}

function Chk_AppCrashes {
    $days = 30
    $ev = Get-AppCrashEvents $days
    $sum = Get-AppCrashSummary $ev
    Add-AppCrashFindings $sum $days
}

# ---------------- acilis suresi ----------------
# Microsoft-Windows-Diagnostics-Performance/Operational: 100 acilis suresi; 101 uygulama, 102 surucu, 103 hizmet, 109 aygit acilisi yavaslatti
# Donus: @{ Boots = @(@{ Time; BootMs; MainMs; PostMs }); Slow = @(@{ Time; Id; Name; Friendly; TotalMs; DegradeMs }) }
function Get-BootEvents([int]$Days = 14) {
    $log = 'Microsoft-Windows-Diagnostics-Performance/Operational'
    $boots = New-Object System.Collections.ArrayList
    $slow = New-Object System.Collections.ArrayList
    $evs = @()
    try { $evs = @(Get-WinEvent -FilterHashtable @{ LogName = $log; Id = 100 } -MaxEvents 15 -ErrorAction Stop) } catch { $evs = @() }
    foreach ($e in $evs) {
        $m = Get-EventDataMap $e
        $bt = 0.0; $mp = 0.0; $pb = 0.0
        if ($m.ContainsKey('BootTime')) { $bt = ConvertTo-MsValue $m['BootTime'] }
        if ($m.ContainsKey('MainPathBootTime')) { $mp = ConvertTo-MsValue $m['MainPathBootTime'] }
        if ($m.ContainsKey('BootPostBootTime')) { $pb = ConvertTo-MsValue $m['BootPostBootTime'] }
        if ($bt -le 0 -and $mp -le 0) { continue }
        [void]$boots.Add(@{ Time = [datetime]$e.TimeCreated; BootMs = $bt; MainMs = $mp; PostMs = $pb })
    }
    $sv = @()
    try { $sv = @(Get-WinEvent -FilterHashtable @{ LogName = $log; Id = @(101, 102, 103, 109); StartTime = (Get-Date).AddDays(-$Days) } -MaxEvents 200 -ErrorAction Stop) } catch { $sv = @() }
    foreach ($e in $sv) {
        $m = Get-EventDataMap $e
        $nm = ''
        if ($m.ContainsKey('Name')) { $nm = [string]$m['Name'] }
        if ($nm -eq '') { try { if ($e.Properties.Count -gt 0) { $nm = [string]$e.Properties[0].Value } } catch { $nm = '' } }
        $fr = ''
        if ($m.ContainsKey('FriendlyName')) { $fr = [string]$m['FriendlyName'] }
        $tt = 0.0; $dg = 0.0
        if ($m.ContainsKey('TotalTime')) { $tt = ConvertTo-MsValue $m['TotalTime'] }
        if ($m.ContainsKey('DegradationTime')) { $dg = ConvertTo-MsValue $m['DegradationTime'] }
        [void]$slow.Add(@{ Time = [datetime]$e.TimeCreated; Id = [int]$e.Id; Name = $nm; Friendly = $fr; TotalMs = $tt; DegradeMs = $dg })
    }
    return @{ Boots = $boots.ToArray(); Slow = $slow.ToArray() }
}

# Ozet: Count (acilis sayisi, en cok 10), Last (son acilis), MedianMain (ms), Slow (en cok yavaslatan 3: Name, Id, Count, Max)
function Get-BootSummary($Boots, $Slow) {
    $b = @(@($Boots) | Sort-Object { $_.Time } -Descending | Select-Object -First 10)
    $slowRows = New-Object System.Collections.ArrayList
    $by = @{}
    foreach ($s in @($Slow)) {
        $nm = ([string]$s.Name).Trim()
        if ($nm -eq '') { continue }
        $key = $nm.ToLowerInvariant()
        if (-not $by.ContainsKey($key)) { $by[$key] = @{ Name = $nm; Id = [int]$s.Id; Count = 0; Max = 0.0 } }
        $by[$key].Count = [int]$by[$key].Count + 1
        if ([double]$s.DegradeMs -gt [double]$by[$key].Max) { $by[$key].Max = [double]$s.DegradeMs }
    }
    foreach ($k in $by.Keys) {
        if ([double]$by[$k].Max -lt 3000) { continue }
        [void]$slowRows.Add(@{ Name = [string]$by[$k].Name; Id = [int]$by[$k].Id; Count = [int]$by[$k].Count; Max = [double]$by[$k].Max })
    }
    $slowSorted = @($slowRows | Sort-Object @{ Expression = { [double]$_.Max }; Descending = $true } | Select-Object -First 3)
    if ($b.Count -eq 0) { return @{ Count = 0; Last = $null; MedianMain = 0.0; Slow = $slowSorted } }
    $mains = @($b | ForEach-Object { [double]$_.MainMs })
    return @{ Count = $b.Count; Last = $b[0]; MedianMain = (Get-NumMedian $mains); Slow = $slowSorted }
}

function Format-BootSeconds([double]$Ms) {
    return ([string][int][math]::Round($Ms / 1000.0))
}

function Get-BootSlowKindText([int]$Id) {
    if ($Id -eq 101) { return 'uygulama' }
    if ($Id -eq 102) { return ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '') }
    if ($Id -eq 103) { return 'hizmet' }
    if ($Id -eq 109) { return ('ayg' + [char]0x0131 + 't') }
    return ('bile' + [char]0x015F + 'en')
}

function Add-BootFindings($Sum, [string]$DiskType) {
    if ([int]$Sum.Count -eq 0 -or $null -eq $Sum.Last) { return }
    $hdd = ($DiskType -eq 'HDD')
    $okMs = 45000.0
    $warnMs = 90000.0
    if ($hdd) { $okMs = 90000.0; $warnMs = 150000.0 }
    $med = [double]$Sum.MedianMain
    $last = $Sum.Last
    $title = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' s' + [char]0x00FC + 'resi: masa' + [char]0x00FC + 'st' + [char]0x00FC + ' ') + (Format-BootSeconds ([double]$last.MainMs)) + ' sn'
    if ([int]$Sum.Count -ge 3) { $title += ' (son ' + [string]$Sum.Count + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'n ortancas' + [char]0x0131 + ' ') + (Format-BootSeconds $med) + ' sn)' }
    $parts = New-Object System.Collections.ArrayList
    [void]$parts.Add(('Son a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' toplam ') + (Format-BootSeconds ([double]$last.BootMs)) + (' sn s' + [char]0x00FC + 'rd' + [char]0x00FC + ': masa' + [char]0x00FC + 'st' + [char]0x00FC + ' ') + (Format-BootSeconds ([double]$last.MainMs)) + (' sn, arka plandaki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' i' + [char]0x015F + 'leri ') + (Format-BootSeconds ([double]$last.PostMs)) + ' sn.')
    $slow = @($Sum.Slow)
    $hasApp = $false; $hasSvc = $false; $hasDrv = $false
    if ($slow.Count -gt 0) {
        $items = New-Object System.Collections.ArrayList
        foreach ($s in $slow) {
            [void]$items.Add([string]$s.Name + ' (' + (Get-BootSlowKindText ([int]$s.Id)) + ', +' + (Format-BootSeconds ([double]$s.Max)) + ' sn)')
            if ([int]$s.Id -eq 101) { $hasApp = $true } elseif ([int]$s.Id -eq 103) { $hasSvc = $true } elseif ([int]$s.Id -eq 102) { $hasDrv = $true }
        }
        [void]$parts.Add(('Windows' + [char]0x2019 + 'un son 14 g' + [char]0x00FC + 'nde a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' en ' + [char]0x00E7 + 'ok yava' + [char]0x015F + 'latt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' kaydettikleri: ') + ($items.ToArray() -join ', ') + '.')
    }
    $status = 'ok'
    if ($med -gt $warnMs) { $status = 'warn' } elseif ($med -gt $okMs) { $status = 'info' }
    $act = $null
    if ($status -ne 'ok') {
        if ($hasApp) { [void]$parts.Add(('Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' sayfas' + [char]0x0131 + 'ndan gerekmeyen programlar' + [char]0x0131 + ' kapatmak a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' k' + [char]0x0131 + 'salt' + [char]0x0131 + 'r.')); $act = @{ Kind = 'Page'; Page = 'startup'; Label = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' sayfas' + [char]0x0131 + '') } }
        if ($hasSvc) { [void]$parts.Add(('Hizmetler sayfas' + [char]0x0131 + 'nda ilgili hizmetin ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' t' + [char]0x00FC + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' g' + [char]0x00F6 + 'zden ge' + [char]0x00E7 + 'irebilirsiniz.')); if ($null -eq $act) { $act = @{ Kind = 'Page'; Page = 'services'; Label = ('Hizmetler sayfas' + [char]0x0131 + '') } } }
        if ($hasDrv) { [void]$parts.Add(('Yava' + [char]0x015F + 'latan s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' i' + [char]0x00E7 + 'in ' + [char]0x00FC + 'reticisinin g' + [char]0x00FC + 'ncel s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'n' + [char]0x00FC + ' kurun.')) }
        if ($slow.Count -eq 0) { [void]$parts.Add(('Bu s' + [char]0x00FC + 're ' + [char]0x00E7 + 'o' + [char]0x011F + 'unlukla bellenimin (BIOS/UEFI) ba' + [char]0x015F + 'latma s' + [char]0x00FC + 'resine ve y' + [char]0x00FC + 'kl' + [char]0x00FC + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ile hizmet say' + [char]0x0131 + 's' + [char]0x0131 + 'na ba' + [char]0x011F + 'l' + [char]0x0131 + 'd' + [char]0x0131 + 'r; BIOS' + [char]0x2019 + 'ta ' + [char]0x201C + 'H' + [char]0x0131 + 'zl' + [char]0x0131 + ' ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme' + [char]0x201D + ' (Fast Boot) se' + [char]0x00E7 + 'ene' + [char]0x011F + 'ini de denetleyin.')) }
    }
    $w = 0
    if ($status -eq 'warn') { $w = 2 }
    Add-Finding 'boot-time' 'perf' $status $title ($parts.ToArray() -join ' ') $act $w
}

function Chk_BootTime {
    $ev = Get-BootEvents 14
    $sum = Get-BootSummary $ev.Boots $ev.Slow
    $dt = ''
    try { $dt = [string]$sync.Profile.DiskType } catch { $dt = '' }
    Add-BootFindings $sum $dt
}

