# Sorun gidericinin plan adimlari. Donus: @(@{ Id; Title; Ops; Reboot })
function Get-SlvTroubleSteps([string]$Key) {
    $out = New-Object System.Collections.ArrayList
    foreach ($s in $script:SlvSymptoms) {
        if ([string]$s.K -ne $Key) { continue }
        $n = @($s.Steps).Count
        $i = 0
        foreach ($st in @($s.Steps)) {
            $i++
            $rb = ($s.Reboot -eq $true -and $i -eq $n)
            [void]$out.Add(@{ Id = [string]$st.Id; Title = [string]$st.Title; Ops = @((FuncOp ([string]$st.Fn))); Reboot = $rb })
        }
    }
    return , $out.ToArray()
}

function Get-SlvSymptom([string]$Key) {
    foreach ($s in $script:SlvSymptoms) { if ([string]$s.K -eq $Key) { return $s } }
    return $null
}

# ---------------- sorun giderici islemleri (onizleme destekli, FuncOp olarak kayitli) ----------------
function Stop-SlvService([string]$Name) {
    $svc = Get-Service -Name $Name -ErrorAction SilentlyContinue
    if ($null -eq $svc) { return $false }
    if ($svc.Status -ne 'Stopped') { Stop-Service -Name $Name -Force -ErrorAction SilentlyContinue }
    for ($i = 0; $i -lt 20; $i++) {
        $svc.Refresh()
        if ($svc.Status -eq 'Stopped') { return $true }
        Start-Sleep -Milliseconds 500
    }
    return $false
}

function Invoke-RenewIpOp {
    if ($script:Preview) { Add-Plan ('IP adresi b' + [char]0x0131 + 'rak' + [char]0x0131 + 'l' + [char]0x0131 + 'p yeniden al' + [char]0x0131 + 'nacak (ba' + [char]0x011F + 'lant' + [char]0x0131 + ' birka' + [char]0x00E7 + ' saniye kesilir)'); return }
    & ipconfig.exe /release 2>&1 | Out-Null
    Start-Sleep -Seconds 2
    & ipconfig.exe /renew 2>&1 | Out-Null
    Add-Done 'IP adresi yenilendi'
}

function Invoke-NetStackResetOp {
    if ($script:Preview) { Add-Plan ('Winsock ve TCP/IP y' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlanacak (etkili olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'latma gerekir)'); return }
    & netsh.exe winsock reset 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) { throw (('Winsock s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlanamad' + [char]0x0131 + ' (' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$LASTEXITCODE + ')') }
    & netsh.exe int ip reset 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) { Add-Skip ('TCP/IP s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlamas' + [char]0x0131 + ' k' + [char]0x0131 + 'smen tamamland' + [char]0x0131 + ' (baz' + [char]0x0131 + ' kay' + [char]0x0131 + 't anahtarlar' + [char]0x0131 + ' Windows taraf' + [char]0x0131 + 'ndan korunuyor)') }
    Add-Done ('Winsock ve TCP/IP y' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + '; yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'nca etkili olur')
}

function Invoke-RestartAudioOp {
    if ($script:Preview) { Add-Plan ('Ses hizmetleri (AudioEndpointBuilder, Audiosrv) yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak'); return }
    $names = @('AudioEndpointBuilder', 'Audiosrv')
    foreach ($n in $names) {
        $svc = Get-Service -Name $n -ErrorAction SilentlyContinue
        if ($null -eq $svc) { Add-Skip ('Hizmet yok: ' + $n); continue }
        Restart-Service -Name $n -Force -ErrorAction Stop
    }
    foreach ($n in $names) {
        $svc = Get-Service -Name $n -ErrorAction SilentlyContinue
        if ($null -ne $svc -and [string]$svc.Status -ne 'Running') { Start-Service -Name $n -ErrorAction Stop }
    }
    Add-Done ('Ses hizmetleri yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + '')
}

function Invoke-ClearSpoolerOp {
    $dir = Join-Path (Join-Path (Join-Path ([string]$env:WINDIR) 'System32') 'spool') 'PRINTERS'
    if ($script:Preview) { Add-Plan (('Yazd' + [char]0x0131 + 'rma Biriktiricisi durdurulacak, ') + $dir + (' i' + [char]0x00E7 + 'indeki bekleyen i' + [char]0x015F + 'ler silinecek, hizmet yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak')); return }
    $stopped = Stop-SlvService 'Spooler'
    $n = 0
    if (Test-Path -LiteralPath $dir -PathType Container) {
        foreach ($f in @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue)) {
            try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; $n++ } catch { }
        }
    }
    Start-Service -Name 'Spooler' -ErrorAction SilentlyContinue
    if (-not $stopped) { Add-Skip ('Yazd' + [char]0x0131 + 'rma Biriktiricisi tam durmad' + [char]0x0131 + '; bekleyen i' + [char]0x015F + 'ler silinemeyebilir') }
    Add-Done (('Yazd' + [char]0x0131 + 'rma kuyru' + [char]0x011F + 'u temizlendi (') + [string]$n + (' bekleyen i' + [char]0x015F + ' silindi)'))
}

function Invoke-ResetWuComponentsOp {
    $win = [string]$env:WINDIR
    $sd = Join-Path $win 'SoftwareDistribution'
    $cr = Join-Path (Join-Path $win 'System32') 'catroot2'
    if ($script:Preview) { Add-Plan ('G' + [char]0x00FC + 'ncelleme hizmetleri durdurulacak; SoftwareDistribution ve catroot2 klas' + [char]0x00F6 + 'rleri ' + [char]0x201C + '.bak' + [char]0x201D + ' ad' + [char]0x0131 + 'yla kenara al' + [char]0x0131 + 'nacak; hizmetler yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak'); return }
    $svcs = @('wuauserv', 'bits', 'cryptsvc', 'msiserver')
    foreach ($n in $svcs) { [void](Stop-SlvService $n) }
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $moved = 0
    try {
        foreach ($d in @($sd, $cr)) {
            if (Test-Path -LiteralPath $d -PathType Container) {
                Rename-Item -LiteralPath $d -NewName ((Split-Path -Leaf $d) + '.bak-' + $stamp) -ErrorAction Stop
                $moved++
            }
        }
    } finally {
        foreach ($n in $svcs) { Start-Service -Name $n -ErrorAction SilentlyContinue }
    }
    Add-Done (('Windows Update bile' + [char]0x015F + 'enleri s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + ' (') + [string]$moved + (' klas' + [char]0x00F6 + 'r yedeklendi; bir sorun kalmazsa ' + [char]0x201C + '.bak' + [char]0x201D + ' klas' + [char]0x00F6 + 'rlerini silebilirsiniz)'))
}

function Get-IconCacheFiles {
    $la = [string]$env:LOCALAPPDATA
    $list = New-Object System.Collections.ArrayList
    $f1 = Join-Path $la 'IconCache.db'
    if (Test-Path -LiteralPath $f1 -PathType Leaf) { [void]$list.Add($f1) }
    $ex = Join-Path (Join-Path (Join-Path $la 'Microsoft') 'Windows') 'Explorer'
    if (Test-Path -LiteralPath $ex -PathType Container) {
        foreach ($f in @(Get-ChildItem -LiteralPath $ex -Filter 'iconcache_*.db' -File -ErrorAction SilentlyContinue)) { [void]$list.Add($f.FullName) }
    }
    return $list.ToArray()
}

function Invoke-RebuildIconCacheOp {
    if ($script:Preview) { Add-Plan ('Windows Gezgini yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak ve simge ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i silinecek (Windows yeniden olu' + [char]0x015F + 'turur)'); return }
    $removed = 0
    for ($try = 0; $try -lt 3; $try++) {
        Get-Process -Name explorer -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        Start-Sleep -Milliseconds 800
        foreach ($f in @(Get-IconCacheFiles)) {
            try { Remove-Item -LiteralPath $f -Force -ErrorAction Stop; $removed++ } catch { }
        }
        if (@(Get-IconCacheFiles).Count -eq 0) { break }
    }
    $left = @(Get-IconCacheFiles).Count
    for ($w = 0; $w -lt 8; $w++) {
        if (@(Get-Process -Name explorer -ErrorAction SilentlyContinue).Count -gt 0) { break }
        Start-Sleep -Milliseconds 500
    }
    if (@(Get-Process -Name explorer -ErrorAction SilentlyContinue).Count -eq 0) { Start-Process -FilePath 'explorer.exe' | Out-Null }
    if ($left -gt 0) { Add-Skip ([string]$left + (' ' + [char]0x00F6 + 'nbellek dosyas' + [char]0x0131 + ' kullan' + [char]0x0131 + 'mda oldu' + [char]0x011F + 'u i' + [char]0x00E7 + 'in silinemedi; oturumu kapat' + [char]0x0131 + 'p a' + [char]0x00E7 + '' + [char]0x0131 + 'nca yenilenir')) }
    Add-Done (('Simge ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i yenilendi (') + [string]$removed + (' dosya), Gezgin yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + ''))
}

$script:FuncOps['RenewIp'] = 'Invoke-RenewIpOp'
$script:FuncOps['NetStackReset'] = 'Invoke-NetStackResetOp'
$script:FuncOps['RestartAudio'] = 'Invoke-RestartAudioOp'
$script:FuncOps['ClearSpooler'] = 'Invoke-ClearSpoolerOp'
$script:FuncOps['ResetWuComponents'] = 'Invoke-ResetWuComponentsOp'
$script:FuncOps['RebuildIconCache'] = 'Invoke-RebuildIconCacheOp'

# ---------------- disk koruma ve saglik ----------------
# ==================================================================
#  DISK KORUMA VE SAGLIK (9.0.0): surucu modeli, BitLocker etkinlestirme plani, dosya sistemi ve G/C hata denetimi.
#  Okuyan ve planlayan islevler burada; BitLocker'i acan, askiya alan, kilitleyen ve kaldiran islevler Eklenti\DiskKoruma.ps1
#  dosyasindadir ve yalnizca kullanici ilgili dugmeye basinca yuklenir. Her degistirme islemi once planlanir ve onay ister.
# ==================================================================

function Get-BlMethodName([int]$Method) {
    switch ($Method) {
        1 { return ('AES-128 (yay' + [char]0x0131 + 'c' + [char]0x0131 + 'l' + [char]0x0131 + ')') }
        2 { return ('AES-256 (yay' + [char]0x0131 + 'c' + [char]0x0131 + 'l' + [char]0x0131 + ')') }
        3 { return 'AES-128' }
        4 { return 'AES-256' }
        5 { return ('Donan' + [char]0x0131 + 'm ' + [char]0x015F + 'ifrelemesi') }
        6 { return 'XTS-AES 128' }
        7 { return 'XTS-AES 256' }
        default { return '' }
    }
}

# Okur. Donus: @{ IsAdmin; Edition; Win11; TpmPresent; TpmReady; SecureBoot; OsDrive; CanEnable; OnBattery; HasBattery; OsBlState (Job_SlvDisks doldurur) }
function Get-SlvEnv {
    $adm = $false
    try { $adm = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } catch { $adm = $false }
    $e = @{ IsAdmin = $adm; Edition = ''; Win11 = $false; TpmPresent = $false; TpmReady = $false; SecureBoot = $null; OsDrive = ([string]$env:SystemDrive).ToUpperInvariant(); CanEnable = $false; OnBattery = $false; HasBattery = $false; OsBlState = '' }
    $p = $null
    try { $p = $sync.Profile } catch { $p = $null }
    if ($null -ne $p) { $e.Edition = [string]$p.Edition; $e.Win11 = ($p.IsWin11 -eq $true) }
    try { $t = Get-Tpm -ErrorAction Stop; $e.TpmPresent = ($t.TpmPresent -eq $true); $e.TpmReady = ($t.TpmReady -eq $true) } catch { }
    try { $e.SecureBoot = [bool](Confirm-SecureBootUEFI -ErrorAction Stop) } catch { $e.SecureBoot = $null }
    $e.CanEnable = (($null -ne (Get-Command -Name 'Enable-BitLocker' -ErrorAction Ignore)) -and ($e.Edition -ne 'Home'))
    try {
        $bt = @(Get-CimInstance -ClassName Win32_Battery -ErrorAction Stop)
        if ($bt.Count -gt 0) { $e.HasBattery = $true; $e.OnBattery = ([int]$bt[0].BatteryStatus -eq 1) }
    } catch { }
    return $e
}

# Okur. Her bolum icin: Drive (C:), Letter, Label, FileSystem, DriveType, Size, Free, DiskNumber, Media, Bus, DiskName, DiskHealth, Dirty, Bl (Get-BitLockerVolumes satiri ya da $null)
function Get-SlvDisks {
    $bl = @{}
    foreach ($b in @(Get-BitLockerVolumes)) { $bl[([string]$b.Drive).ToUpperInvariant()] = $b }
    $phys = @{}
    try { foreach ($pd in @(Get-PhysicalDisk -ErrorAction Stop)) { $phys[[string]$pd.DeviceId] = $pd } } catch { }
    $dirty = @{}
    try {
        foreach ($wv in @(Get-CimInstance -ClassName Win32_Volume -Filter 'DriveType=3' -ErrorAction Stop)) {
            if ([string]$wv.DriveLetter -ne '') { $dirty[([string]$wv.DriveLetter).ToUpperInvariant()] = ($wv.DirtyBitSet -eq $true) }
        }
    } catch { }
    $out = New-Object System.Collections.ArrayList
    $vols = @()
    try { $vols = @(Get-Volume -ErrorAction Stop | Where-Object { $_.DriveLetter -and ($_.DriveType -eq 'Fixed' -or $_.DriveType -eq 'Removable') }) } catch { $vols = @() }
    foreach ($v in $vols) {
        $dl = ([string]$v.DriveLetter).ToUpperInvariant() + ':'
        $row = @{ Drive = $dl; Letter = [string]$v.DriveLetter; Label = [string]$v.FileSystemLabel; FileSystem = [string]$v.FileSystem; DriveType = [string]$v.DriveType; Size = [double]$v.Size; Free = [double]$v.SizeRemaining
            DiskNumber = -1; Media = ''; Bus = ''; DiskName = ''; DiskHealth = ''; Dirty = ($dirty.ContainsKey($dl) -and $dirty[$dl] -eq $true); Bl = $null }
        try { $pt = Get-Partition -DriveLetter $v.DriveLetter -ErrorAction Stop | Select-Object -First 1; $row.DiskNumber = [int]$pt.DiskNumber } catch { }
        if ($row.DiskNumber -ge 0 -and $phys.ContainsKey([string]$row.DiskNumber)) {
            $pd = $phys[[string]$row.DiskNumber]
            $row.Media = [string]$pd.MediaType; $row.Bus = [string]$pd.BusType; $row.DiskName = [string]$pd.FriendlyName; $row.DiskHealth = [string]$pd.HealthStatus
        }
        if ($bl.ContainsKey($dl)) { $row.Bl = $bl[$dl] }
        [void]$out.Add($row)
    }
    return , $out.ToArray()
}

# Fiziksel diskler (surucu harfi olsun olmasin): Silinen dosyalar sekmesi harfsiz bolumleri ve bozuk diskleri de taramak icin kullanir.
# Donus: @{ Number; Name; Size; Bus; Media; Style; IsSystem; Offline; Letters (surucu harfleri); UniqueId; Serial; ReadOnly; Clustered; Pool; Sector;
#         Roles (diske dogrudan yazmayi engelleyen nedenler); Parts (@{ Number; Offset; Size; Letter; Type; IsSystem; IsBoot; IsActive; Fs; Label }) } dizisi
# Silme sekmesi bu kayitlari kullanir; kimlik alanlari (UniqueId, Serial, Name, Size) onay anindaki karsilastirma icindir.
function Get-SlvPhysDisks {
    $out = New-Object System.Collections.ArrayList
    $disks = @()
    try { $disks = @(Get-Disk -ErrorAction Stop) } catch { return , $out.ToArray() }
    $pds = @{}
    try { foreach ($pd in @(Get-PhysicalDisk -ErrorAction Stop)) { $pds[[string]$pd.DeviceId] = $pd } } catch { }
    $vols = @{}
    try { foreach ($v in @(Get-Volume -ErrorAction Stop)) { if ($v.DriveLetter) { $vols[([string]$v.DriveLetter).ToUpperInvariant() + ':'] = $v } } } catch { }
    # Windows'un, Multimizer'in ya da gecici dosyalarin bulundugu suruculer (silme sekmesi bu disklere dogrudan yazmaz)
    $prot = @{}
    try { $prot = Get-WipeProtectedLetters } catch { $prot = @{} }
    foreach ($dk in $disks) {
        $n = [int]$dk.Number
        $row = @{ Number = $n; Name = ([string]$dk.FriendlyName).Trim(); Size = [double]$dk.Size; Bus = [string]$dk.BusType; Media = ''; Style = [string]$dk.PartitionStyle
            IsSystem = ($dk.IsSystem -eq $true -or $dk.IsBoot -eq $true); Offline = ($dk.IsOffline -eq $true); Letters = @(); Parts = @()
            UniqueId = ([string]$dk.UniqueId).Trim(); Serial = ([string]$dk.SerialNumber).Trim(); ReadOnly = ($dk.IsReadOnly -eq $true); Clustered = ($dk.IsClustered -eq $true)
            Pool = $false; Sector = 512; Roles = @() }
        try { if ([int]$dk.LogicalSectorSize -ge 512) { $row.Sector = [int]$dk.LogicalSectorSize } } catch { }
        if ($pds.ContainsKey([string]$n)) {
            $row.Media = [string]$pds[[string]$n].MediaType
            try { $row.Pool = (@($pds[[string]$n].CannotPoolReason) -contains 'In a Pool') } catch { }
        }
        $letters = New-Object System.Collections.ArrayList
        $plist = New-Object System.Collections.ArrayList
        $roles = New-Object System.Collections.ArrayList
        try {
            foreach ($pt in @(Get-Partition -DiskNumber $n -ErrorAction Stop)) {
                $l = ''
                if ($pt.DriveLetter) { $l = ([string]$pt.DriveLetter).ToUpperInvariant() + ':' }
                $fs = ''
                $lbl = ''
                if ($l -ne '' -and $vols.ContainsKey($l)) { $fs = [string]$vols[$l].FileSystem; $lbl = [string]$vols[$l].FileSystemLabel }
                [void]$plist.Add(@{ Number = [int]$pt.PartitionNumber; Offset = [double]$pt.Offset; Size = [double]$pt.Size; Letter = $l; Type = [string]$pt.Type
                    IsSystem = ($pt.IsSystem -eq $true); IsBoot = ($pt.IsBoot -eq $true); IsActive = ($pt.IsActive -eq $true); Fs = $fs; Label = $lbl })
                if ($l -ne '') {
                    [void]$letters.Add($l)
                    if ($prot.ContainsKey($l)) { [void]$roles.Add(($l + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ': ') + [string]$prot[$l])) }
                }
            }
        } catch { }
        $row.Letters = $letters.ToArray()
        $row.Parts = $plist.ToArray()
        $row.Roles = $roles.ToArray()
        [void]$out.Add($row)
    }
    return , $out.ToArray()
}

# Bir surucunun sifreleme durumu: none | encrypted | suspended | working | locked | unknown
function Get-BlState($Disk) {
    $b = $Disk.Bl
    if ($null -eq $b) { return 'unknown' }
    $c = [int]$b.Conversion
    $p = [int]$b.Protection
    if ($c -eq 0) { return 'none' }
    if ($c -ge 2 -and $c -le 5) { return 'working' }
    if ($c -eq 1) {
        if ($p -eq 1) { return 'encrypted' }
        if ($p -eq 0) { return 'suspended' }
        return 'unknown'
    }
    if ($c -lt 0 -and $p -eq 2) { return 'locked' }
    return 'unknown'
}

# Sifreleme kapsami: mekanik diskte tum surucu (silinmis dosyalarin kalintilari da sifrelenir); SSD ve cikarilabilir surucude
# yalnizca kullanilan alan (SSD'de silinen alani zaten TRIM bosaltir). Donus: Full | Used
function Get-BlScope($Vol) {
    if ([string]$Vol.Media -eq 'HDD') { return 'Full' }
    return 'Used'
}

function Get-BlScopeText([string]$Scope) {
    if ($Scope -eq 'Full') { return ('t' + [char]0x00FC + 'm s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '; silinmi' + [char]0x015F + ' dosyalar' + [char]0x0131 + 'n kal' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' da ' + [char]0x015F + 'ifrelenir') }
    return ('yaln' + [char]0x0131 + 'zca kullan' + [char]0x0131 + 'lan alan')
}

# BitLocker'i bu surucude acmak mumkun mu? Yalnizca planlar, hicbir sey degistirmez.
# Donus: @{ Ok; Why; Method (Tpm | RecoveryPassword | DeviceEncryption | ''); Steps; Warnings; NeedsReboot; IsOs }
function Test-BlEnablePlan($Vol, $Sys) {
    $r = @{ Ok = $false; Why = ''; Method = ''; Steps = @(); Warnings = @(); NeedsReboot = $false; IsOs = $false; Scope = ''; Cipher = '' }
    $drive = ([string]$Vol.Drive).ToUpperInvariant()
    $isOs = ($drive -eq ([string]$Sys.OsDrive).ToUpperInvariant())
    $r.IsOs = $isOs
    $state = Get-BlState $Vol
    if ($state -ne 'none') {
        if ($state -eq 'unknown') { $r.Why = ('' + [char]0x015E + 'ifreleme durumu okunamad' + [char]0x0131 + '; Multimizer' + [char]0x2019 + '' + [char]0x0131 + ' y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n.') } else { $r.Why = ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' zaten ' + [char]0x015F + 'ifreli ya da ' + [char]0x015F + 'ifreleniyor.') }
        return $r
    }
    if ($Sys.IsAdmin -ne $true) { $r.Why = ('' + [char]0x015E + 'ifrelemeyi ba' + [char]0x015F + 'latmak i' + [char]0x00E7 + 'in Multimizer' + [char]0x2019 + '' + [char]0x0131 + ' y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n.'); return $r }
    if (@('NTFS', 'FAT32', 'exFAT') -notcontains [string]$Vol.FileSystem) { $r.Why = ('Bu dosya sistemi ' + [char]0x015F + 'ifrelenemez (NTFS, FAT32 ya da exFAT olmal' + [char]0x0131 + ').'); return $r }
    if ($Sys.CanEnable -ne $true) {
        if ([string]$Sys.Edition -eq 'Home' -and $isOs -and $Sys.TpmPresent -eq $true) {
            $r.Ok = $true; $r.Method = 'DeviceEncryption'
            $r.Steps = @(('Windows Home' + [char]0x2019 + 'da tam BitLocker yoktur. Ayarlar > Gizlilik ve g' + [char]0x00FC + 'venlik > Cihaz ' + [char]0x015F + 'ifrelemesi sayfas' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r; oradan a' + [char]0x00E7 + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda Windows kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + ' Microsoft hesab' + [char]0x0131 + 'n' + [char]0x0131 + 'za kaydeder.'))
            return $r
        }
        $r.Why = ('Bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde BitLocker yok (Home). Cihaz ' + [char]0x015F + 'ifrelemesi i' + [char]0x00E7 + 'in TPM 2.0 gerekir; yoksa 7-Zip, VeraCrypt gibi a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak ara' + [char]0x00E7 + 'lar kullan' + [char]0x0131 + 'labilir.')
        return $r
    }
    if ($isOs) {
        if ($Sys.TpmPresent -ne $true) { $r.Why = ('Bu bilgisayarda TPM bulunamad' + [char]0x0131 + ' ya da BIOS' + [char]0x2019 + 'ta kapal' + [char]0x0131 + '. Sistem diskini ' + [char]0x015F + 'ifrelemek i' + [char]0x00E7 + 'in TPM gerekir; BIOS/UEFI' + [char]0x2019 + 'de ' + [char]0x201C + 'fTPM / PTT' + [char]0x201D + ' se' + [char]0x00E7 + 'ene' + [char]0x011F + 'ini a' + [char]0x00E7 + '' + [char]0x0131 + 'n.'); return $r }
        if ($Sys.TpmReady -ne $true) { $r.Why = ('TPM var ama kullan' + [char]0x0131 + 'ma haz' + [char]0x0131 + 'r de' + [char]0x011F + 'il. Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i > Cihaz g' + [char]0x00FC + 'venli' + [char]0x011F + 'i > G' + [char]0x00FC + 'venlik i' + [char]0x015F + 'lemcisi ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + 'ndan TPM' + [char]0x2019 + 'i haz' + [char]0x0131 + 'rlay' + [char]0x0131 + 'n.'); return $r }
        $r.Method = 'Tpm'
        $r.Scope = Get-BlScope $Vol
        $r.Cipher = 'XtsAes256'
        $r.Steps = @(('TPM koruyucusu eklenir (' + [char]0x015F + 'ifre sormadan a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r).'), ('Kurtarma parolas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulur ve sizin se' + [char]0x00E7 + 'ti' + [char]0x011F + 'iniz klas' + [char]0x00F6 + 're kaydedilip do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r.'), (('Yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'nca donan' + [char]0x0131 + 'm s' + [char]0x0131 + 'namas' + [char]0x0131 + ' yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve ' + [char]0x015F + 'ifreleme arka planda ba' + [char]0x015F + 'lar (XTS-AES 256, ') + (Get-BlScopeText $r.Scope) + ').'))
        $r.NeedsReboot = $true
        if ($Sys.SecureBoot -eq $false) { $r.Warnings += ('G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme (Secure Boot) kapal' + [char]0x0131 + '; BitLocker yine ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r ama ' + [char]0x00F6 + 'ny' + [char]0x00FC + 'kleme zinciri korunmaz.') }
    } else {
        $r.Method = 'RecoveryPassword'
        $r.Scope = Get-BlScope $Vol
        $r.Cipher = 'XtsAes256'
        if ([string]$Vol.DriveType -eq 'Removable') { $r.Cipher = 'Aes256' }
        $r.Steps = @(('Kurtarma parolas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulur ve sizin se' + [char]0x00E7 + 'ti' + [char]0x011F + 'iniz klas' + [char]0x00F6 + 're kaydedilip do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r.'), (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ' + [char]0x015F + 'ifrelenmeye ba' + [char]0x015F + 'lar (') + $(if ($r.Cipher -eq 'Aes256') { 'AES-256' } else { 'XTS-AES 256' }) + ', ' + (Get-BlScopeText $r.Scope) + ').'), ('Sistem diski de ' + [char]0x015F + 'ifreliyse s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' oturum a' + [char]0x00E7 + '' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r.'))
        if ([string]$Vol.DriveType -eq 'Removable') { $r.Warnings += ('' + [char]0x00C7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'labilir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' tak' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' her bilgisayarda kurtarma parolas' + [char]0x0131 + ' ister. Parolay' + [char]0x0131 + ' kaybederseniz verilere eri' + [char]0x015F + 'ilemez.') }
    }
    if ($Sys.HasBattery -eq $true -and $Sys.OnBattery -eq $true) { $r.Warnings += ('Diz' + [char]0x00FC + 'st' + [char]0x00FC + ' pil ile ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor; ' + [char]0x015F + 'ifreleme s' + [char]0x00FC + 'rerken ' + [char]0x015F + 'arj cihaz' + [char]0x0131 + 'n' + [char]0x0131 + ' tak' + [char]0x0131 + 'n.') }
    if ([double]$Vol.Size -gt 0 -and [double]$Vol.Free / [double]$Vol.Size -lt 0.05) { $r.Warnings += ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de bo' + [char]0x015F + ' alan %5' + [char]0x2019 + 'in alt' + [char]0x0131 + 'nda; ' + [char]0x015F + 'ifrelemeden ' + [char]0x00F6 + 'nce yer a' + [char]0x00E7 + 'man' + [char]0x0131 + 'z ' + [char]0x00F6 + 'nerilir.') }
    $r.Ok = $true
    return $r
}

# Anahtar dosyasinin konumu guvenli mi? '' = uygun. Anahtar, sifrelenen surucude saklanirsa ise yaramaz.
function Test-BlKeyDir([string]$Dir, [string]$Drive) {
    $d = ([string]$Dir).Trim()
    if ($d -eq '') { return ('Anahtar' + [char]0x0131 + 'n kaydedilece' + [char]0x011F + 'i klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in.') }
    if ($d -match '[\*\?"<>\|]') { return ('Klas' + [char]0x00F6 + 'r yolunda ge' + [char]0x00E7 + 'ersiz karakter var.') }
    if ($d.Length -lt 3 -or $d.Substring(1, 2) -ne ':\') { return ('Anahtar yerel bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'deki klas' + [char]0x00F6 + 're kaydedilmeli (' + [char]0x00F6 + 'r. D:\Anahtarlar).') }
    $dl = $d.Substring(0, 1).ToUpperInvariant()
    $target = ([string]$Drive).Trim().TrimEnd(':').ToUpperInvariant()
    if ($dl -eq $target) { return ('Anahtar' + [char]0x0131 + ' ' + [char]0x015F + 'ifrelenecek s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye kaydetmeyin; s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye eri' + [char]0x015F + 'emedi' + [char]0x011F + 'inizde anahtara da eri' + [char]0x015F + 'emezsiniz. USB bellek ya da ba' + [char]0x015F + 'ka bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' se' + [char]0x00E7 + 'in.') }
    return ''
}

function Get-BlKeyFileName([string]$Drive) {
    $l = ([string]$Drive).Trim().TrimEnd(':').ToUpperInvariant()
    $pc = ([string]$env:COMPUTERNAME) -creplace '[^A-Za-z0-9\-_]', ''
    if ($pc -eq '') { $pc = 'PC' }
    return ('BitLocker-kurtarma-' + $l + '-' + $pc + '.txt')
}

# ---------------- surucu bolumleri: arayuzde gosterilecek satirlar ----------------
function Format-SlvMedia($D) {
    $m = [string]$D.Media
    $b = [string]$D.Bus
    $t = ''
    if ($m -eq 'SSD') { $t = 'SSD' } elseif ($m -eq 'HDD') { $t = 'HDD' }
    if ($b -eq 'NVMe') { if ($t -eq '') { $t = 'NVMe' } else { $t = $t + ' (NVMe)' } }
    elseif ($b -eq 'USB') { if ($t -eq '') { $t = 'USB' } else { $t = $t + ' (USB)' } }
    return $t
}

# Donus: dizi; her oge @{ Kind = 'head' | 'row'; Title; Detail; Br; Do; Label }  (Do bossa dugme yok)
function Get-SlvDiskRows($D, $Sys) {
    $rows = New-Object System.Collections.ArrayList
    $name = [string]$D.Drive
    if ([string]$D.Label -ne '') { $name += '  ' + [string]$D.Label }
    $head = $name
    $media = Format-SlvMedia $D
    $bits = New-Object System.Collections.ArrayList
    if ([string]$D.FileSystem -ne '') { [void]$bits.Add([string]$D.FileSystem) }
    if ([double]$D.Size -gt 0) { [void]$bits.Add((Format-Size ([double]$D.Size)) + ', ' + (Format-Size ([double]$D.Free)) + (' bo' + [char]0x015F + '')) }
    if ($media -ne '') { [void]$bits.Add($media) }
    if ([string]$D.DiskName -ne '') { [void]$bits.Add([string]$D.DiskName) }
    [void]$rows.Add(@{ Kind = 'head'; Title = $head + '   ' + ($bits.ToArray() -join ('  ' + [char]0x00B7 + '  ')) })

    $state = Get-BlState $D
    $plan = Test-BlEnablePlan $D $Sys
    $isOs = (([string]$D.Drive).ToUpperInvariant() -eq ([string]$Sys.OsDrive).ToUpperInvariant())
    $b = $D.Bl
    if ($state -eq 'encrypted') {
        $det = ('' + [char]0x015E + 'ifreli ve koruma a' + [char]0x00E7 + '' + [char]0x0131 + 'k.')
        if ($null -ne $b) { $mn = @($b.Types | ForEach-Object { Get-BlProtectorName ([int]$_) }); if ($mn.Count -gt 0) { $det += ' Koruyucular: ' + ($mn -join ', ') + '.' } }
        if ($null -ne $b -and $b.HasRecovery -ne $true) { [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker: kurtarma anahtar' + [char]0x0131 + ' tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' de' + [char]0x011F + 'il'); Detail = $det + (' Anahtar olmadan bir donan' + [char]0x0131 + 'm ya da BIOS de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'inden sonra verilere eri' + [char]0x015F + 'ilemeyebilir.'); Br = 'BrBad'; Do = 'BlAddKey'; Label = ('Kurtarma anahtar' + [char]0x0131 + ' ekle') }) }
        else { [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker: ' + [char]0x015F + 'ifreli'); Detail = $det; Br = 'BrGood'; Do = 'BlKey'; Label = ('Anahtar' + [char]0x0131 + ' g' + [char]0x00F6 + 'ster'); Do2 = 'BlSave'; Label2 = 'Dosyaya kaydet...' }) }
        $rows.Add(@{ Kind = 'row'; Title = ('BitLocker i' + [char]0x015F + 'lemleri'); Detail = ('G' + [char]0x00FC + 'ncelleme ya da BIOS de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i ' + [char]0x00F6 + 'ncesinde koruma ge' + [char]0x00E7 + 'ici olarak ask' + [char]0x0131 + 'ya al' + [char]0x0131 + 'nabilir.'); Br = 'BrFaint'; Do = 'BlSuspend'; Label = ('Korumay' + [char]0x0131 + ' ask' + [char]0x0131 + 'ya al'); Do2 = 'BlDisable'; Label2 = ('' + [char]0x015E + 'ifrelemeyi kald' + [char]0x0131 + 'r...') }) | Out-Null
        if (-not $isOs -and [string]$D.DriveType -eq 'Fixed' -and $null -ne $b -and @($b.Types) -notcontains 2 -and ($Sys.OsBlState -eq 'encrypted' -or $Sys.OsBlState -eq 'working')) {
            $rows.Add(@{ Kind = 'row'; Title = ('Otomatik a' + [char]0x00E7 + 'ma kapal' + [char]0x0131 + ''); Detail = ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' her a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta kurtarma anahtar' + [char]0x0131 + ' isteyebilir. Otomatik a' + [char]0x00E7 + 'ma, sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' de a' + [char]0x00E7 + 'ar (yaln' + [char]0x0131 + 'zca bu bilgisayarda).'); Br = 'BrWarn'; Do = 'BlAutoUnlock'; Label = ('Otomatik a' + [char]0x00E7 + 'may' + [char]0x0131 + ' a' + [char]0x00E7 + '') }) | Out-Null
        }
        if (-not $isOs -and [string]$D.DriveType -ne '') { $rows.Add(@{ Kind = 'row'; Title = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' kilitle'); Detail = ('Kilitlenen s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye parola ya da kurtarma anahtar' + [char]0x0131 + ' olmadan eri' + [char]0x015F + 'ilemez.'); Br = 'BrFaint'; Do = 'BlLock'; Label = 'Kilitle' }) | Out-Null }
    } elseif ($state -eq 'suspended') {
        [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker: koruma ask' + [char]0x0131 + 'da'); Detail = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ' + [char]0x015F + 'ifreli ama koruma kapal' + [char]0x0131 + '; veriler ' + [char]0x015F + 'u anda anahtars' + [char]0x0131 + 'z okunabilir. ' + [char]0x0130 + '' + [char]0x015F + 'iniz bitince korumay' + [char]0x0131 + ' s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'n.'); Br = 'BrWarn'; Do = 'BlResume'; Label = ('Korumay' + [char]0x0131 + ' s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r') })
    } elseif ($state -eq 'working') {
        $pc = 0; if ($null -ne $b) { $pc = [int]$b.Percent }
        [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker: i' + [char]0x015F + 'lem s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor (%') + [string]$pc + ')'; Detail = ('' + [char]0x015E + 'ifreleme ya da ' + [char]0x015F + 'ifre ' + [char]0x00E7 + '' + [char]0x00F6 + 'zme arka planda s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor. Bilgisayar kapan' + [char]0x0131 + 'rsa kald' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' yerden devam eder.'); Br = 'BrInfo'; Do = ''; Label = '' })
    } elseif ($state -eq 'none') {
        if ($plan.Ok -eq $true) {
            $lbl = ('' + [char]0x015E + 'ifrelemeyi ba' + [char]0x015F + 'lat')
            if ($plan.Method -eq 'DeviceEncryption') { $lbl = ('Cihaz ' + [char]0x015F + 'ifrelemesini a' + [char]0x00E7 + '') }
            $br = 'BrFaint'; if ($isOs) { $br = 'BrWarn' }
            [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker: ' + [char]0x015F + 'ifreli de' + [char]0x011F + 'il'); Detail = (($plan.Steps | Select-Object -First 1) + (' Bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'r ya da kaybolursa diskteki dosyalara eri' + [char]0x015F + 'ilebilir.')); Br = $br; Do = 'BlEnable'; Label = $lbl })
        } else {
            [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker: ' + [char]0x015F + 'ifreli de' + [char]0x011F + 'il'); Detail = [string]$plan.Why; Br = 'BrFaint'; Do = ''; Label = '' })
        }
    } elseif ($state -eq 'locked') {
        [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker: s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' kilitli'); Detail = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ' + [char]0x015F + 'ifreli ve kilitli. Dosya Gezgini' + [char]0x2019 + 'nde s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye ' + [char]0x00E7 + 'ift t' + [char]0x0131 + 'klay' + [char]0x0131 + 'p parolay' + [char]0x0131 + ' ya da kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + ' girerek a' + [char]0x00E7 + '' + [char]0x0131 + 'n.'); Br = 'BrInfo'; Do = ''; Label = '' })
        return , $rows.ToArray()
    } else {
        [void]$rows.Add(@{ Kind = 'row'; Title = ('BitLocker durumu okunamad' + [char]0x0131 + ''); Detail = ('Y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n ya da bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde BitLocker olmayabilir.'); Br = 'BrFaint'; Do = ''; Label = '' })
    }
    if ([string]$D.DiskHealth -ne '' -and [string]$D.DiskHealth -ne 'Healthy') {
        [void]$rows.Add(@{ Kind = 'row'; Title = ('Disk sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ': ') + [string]$D.DiskHealth; Detail = ('Windows bu diskin sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'n bozuldu' + [char]0x011F + 'unu bildiriyor. ' + [char]0x00D6 + 'nemli dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' hemen yedekleyin.'); Br = 'BrBad'; Do = 'Backup'; Label = ('Yedekleme sayfas' + [char]0x0131 + '') })
    }
    if ($D.Dirty -eq $true) {
        [void]$rows.Add(@{ Kind = 'row'; Title = ('Dosya sistemi hata bildirmi' + [char]0x015F + ' (kirli bit)'); Detail = ('Windows bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'n d' + [char]0x00FC + 'zg' + [char]0x00FC + 'n kapanmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' ya da dosya sistemi hatas' + [char]0x0131 + ' buldu' + [char]0x011F + 'unu i' + [char]0x015F + 'aretlemi' + [char]0x015F + '. Onar' + [char]0x0131 + 'm s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' k' + [char]0x0131 + 'sa s' + [char]0x00FC + 're kullan' + [char]0x0131 + 'lamaz yapabilir; sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' yeniden ba' + [char]0x015F + 'latmada onar' + [char]0x0131 + 'l' + [char]0x0131 + 'r.'); Br = 'BrWarn'; Do = 'DiskRepair'; Label = 'Onar' })
    } elseif ([string]$D.FileSystem -eq 'NTFS') {
        [void]$rows.Add(@{ Kind = 'row'; Title = 'Dosya sistemi denetimi'; Detail = ('' + [char]0x00C7 + 'evrimi' + [char]0x00E7 + 'i, salt okunur tarama yapar; hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'eyi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez.'); Br = 'BrFaint'; Do = 'DiskScan'; Label = 'Tara' })
    }
    $rows.Add(@{ Kind = 'row'; Title = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' iyile' + [char]0x015F + 'tirme'); Detail = ('SSD' + [char]0x2019 + 'de TRIM, mekanik diskte birle' + [char]0x015F + 'tirme ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'r.'); Br = 'BrFaint'; Do = 'DiskOptimize'; Label = ('' + [char]0x0130 + 'yile' + [char]0x015F + 'tir') }) | Out-Null
    return , $rows.ToArray()
}

# ---------------- bulgular ----------------
function Add-DiskProtectFindings($Disks, $Sys) {
    $osd = ([string]$Sys.OsDrive).ToUpperInvariant()
    $os = $null
    foreach ($d in @($Disks)) { if (([string]$d.Drive).ToUpperInvariant() -eq $osd) { $os = $d } }
    $act = New-SolveAction 'disk' '' 'Diskler sekmesi'
    $state = 'unknown'
    if ($null -ne $os) { $state = Get-BlState $os }
    if ($state -eq 'unknown') {
        if ([string]$Sys.Edition -eq 'Home') {
            Add-Finding 'bl' 'sec' 'info' ('Disk ' + [char]0x015F + 'ifreleme: Windows Home' + [char]0x2019 + 'da tam BitLocker yok') ('Home s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde yaln' + [char]0x0131 + 'zca ' + [char]0x201C + 'Cihaz ' + [char]0x015F + 'ifrelemesi' + [char]0x201D + ' bulunur ve TPM 2.0 gerektirir. Ayarlar > Gizlilik ve g' + [char]0x00FC + 'venlik > Cihaz ' + [char]0x015F + 'ifrelemesi sayfas' + [char]0x0131 + 'na bak' + [char]0x0131 + 'n.') $act 0
        } else {
            Add-Finding 'bl' 'sec' 'info' ('Disk ' + [char]0x015F + 'ifreleme (BitLocker) durumu okunamad' + [char]0x0131 + '') ('Multimizer' + [char]0x2019 + '' + [char]0x0131 + ' y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n. Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde BitLocker bulunmuyor da olabilir.') $act 0
        }
    } elseif ($state -eq 'encrypted') {
        Add-Finding 'bl' 'sec' 'ok' ('Sistem diski ' + [char]0x015F + 'ifreli (BitLocker)') ('Bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'rsa diskteki dosyalara eri' + [char]0x015F + 'ilemez.')
        if ($os.Bl.HasRecovery -ne $true) {
            Add-Finding 'bl-key' 'sec' 'warn' ('BitLocker kurtarma anahtar' + [char]0x0131 + ' tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' de' + [char]0x011F + 'il') ('Disk ' + [char]0x015F + 'ifreli ama kurtarma anahtar' + [char]0x0131 + ' yok. BIOS g' + [char]0x00FC + 'ncellemesi ya da donan' + [char]0x0131 + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'inden sonra Windows anahtar sorarsa verilere eri' + [char]0x015F + 'emezsiniz. Anahtar ekleyip bilgisayar' + [char]0x0131 + 'n d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda saklay' + [char]0x0131 + 'n.') (New-SolveAction 'disk' '' 'Anahtar ekle')
        }
    } elseif ($state -eq 'suspended') {
        Add-Finding 'bl' 'sec' 'warn' ('BitLocker korumas' + [char]0x0131 + ' ask' + [char]0x0131 + 'da') ('Sistem diski ' + [char]0x015F + 'ifreli ama koruma ge' + [char]0x00E7 + 'ici olarak kapat' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + '; bu s' + [char]0x0131 + 'rada veriler anahtars' + [char]0x0131 + 'z okunabilir. G' + [char]0x00FC + 'ncelleme ya da BIOS i' + [char]0x015F + 'i bittiyse korumay' + [char]0x0131 + ' s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'n.') $act -1 (New-RunFix 'BlResume' ('Korumay' + [char]0x0131 + ' s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r') 'Click')
    } elseif ($state -eq 'working') {
        Add-Finding 'bl' 'sec' 'info' ('Sistem diski ' + [char]0x015F + 'ifreleniyor') (('' + [char]0x015E + 'ifreleme arka planda s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor (%') + [string]$os.Bl.Percent + ('). Bilgisayar kapan' + [char]0x0131 + 'rsa kald' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' yerden devam eder.')) $null 0
    } else {
        $plan = Test-BlEnablePlan $os $Sys
        $detail = ('Sistem diski ' + [char]0x015F + 'ifreli de' + [char]0x011F + 'il. Bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'r ya da kaybolursa diskteki dosyalara eri' + [char]0x015F + 'ilebilir.')
        if ($plan.Ok -eq $true) {
            if ($plan.Method -eq 'DeviceEncryption') { $detail += (' Cihaz ' + [char]0x015F + 'ifrelemesini ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi' + [char]0x2019 + 'nden a' + [char]0x00E7 + 'abilirsiniz.') }
            else { $detail += (' ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi ' + [char]0x015F + 'ifrelemeyi sizin yerinize ba' + [char]0x015F + 'lat' + [char]0x0131 + 'r; anahtar' + [char]0x0131 + ' kaydetmeniz yeterli.') }
        } else { $detail += ' ' + [string]$plan.Why }
        $st = 'warn'
        if ($Sys.HasBattery -ne $true) { $st = 'info' }
        Add-Finding 'bl' 'sec' $st ('Sistem diski ' + [char]0x015F + 'ifreli de' + [char]0x011F + 'il') $detail (New-SolveAction 'disk' '' ('' + [char]0x015E + 'ifrelemeyi ba' + [char]0x015F + 'lat'))
    }
    $open = New-Object System.Collections.ArrayList
    foreach ($d in @($Disks)) {
        if (([string]$d.Drive).ToUpperInvariant() -eq $osd -or [string]$d.DriveType -ne 'Fixed') { continue }
        if ((Get-BlState $d) -eq 'none' -and [double]$d.Size -gt 0) { [void]$open.Add([string]$d.Drive) }
    }
    if ($open.Count -gt 0) {
        Add-Finding 'bl-data' 'sec' 'info' (('' + [char]0x015E + 'ifrelenmemi' + [char]0x015F + ' veri s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri: ') + ($open.ToArray() -join ', ')) ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'lerdeki dosyalar bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'rsa okunabilir. ' + [char]0x0130 + 'sterseniz ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi' + [char]0x2019 + 'nden ' + [char]0x015F + 'ifreleyebilirsiniz.') (New-SolveAction 'disk' '' 'Diskler sekmesi') 0
    }
}

function Add-VolumeHealthFindings($Disks) {
    foreach ($d in @($Disks)) {
        $dr = [string]$d.Drive
        if ($d.Dirty -eq $true) {
            $isOs = ($dr.ToUpperInvariant() -eq ([string]$env:SystemDrive).ToUpperInvariant())
            $note = ''
            if ($isOs) { $note = (' Sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' bir sonraki yeniden ba' + [char]0x015F + 'latmada onar' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') }
            Add-Finding ('fs-dirty-' + $dr.TrimEnd(':')) 'maint' 'warn' ($dr + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde dosya sistemi hatas' + [char]0x0131 + ' i' + [char]0x015F + 'aretli')) (('Windows bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' ' + [char]0x201C + 'kirli' + [char]0x201D + ' olarak i' + [char]0x015F + 'aretlemi' + [char]0x015F + ': d' + [char]0x00FC + 'zg' + [char]0x00FC + 'n kapanmam' + [char]0x0131 + '' + [char]0x015F + ' ya da dosya sistemi hatas' + [char]0x0131 + ' bulunmu' + [char]0x015F + ' olabilir.') + $note) $null -1 (New-StepsFix 'Click' ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' onar') @(@{ Id = 'chkdsk-' + $dr.TrimEnd(':'); Title = $dr + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + ' onar'); Ops = @(@{ T = 'ChkdskRepair'; Drive = $dr }); Reboot = $isOs }))
        }
    }
}

# ---------------- dosya sistemi onarimi (onizleme ve gunluk destekli) ----------------
function Invoke-ChkdskRepairOp($Op) {
    $dr = ([string]$Op.Drive).Trim().ToUpperInvariant()
    if ($dr -cnotmatch '^[A-Z]:?$') { throw (('Ge' + [char]0x00E7 + 'ersiz s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ': ') + $dr) }
    $letter = $dr.Substring(0, 1)
    if ($script:Preview) { Add-Plan ($letter + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde dosya sistemi onar' + [char]0x0131 + 'm' + [char]0x0131 + ' (Repair-Volume -SpotFix) ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak')); return }
    $r = Repair-Volume -DriveLetter $letter -SpotFix -ErrorAction Stop
    Add-Done ($letter + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' onar' + [char]0x0131 + 'ld' + [char]0x0131 + ' ya da yeniden ba' + [char]0x015F + 'latmada onar' + [char]0x0131 + 'lmak ' + [char]0x00FC + 'zere i' + [char]0x015F + 'aretlendi (') + [string]$r + ')')
}
$script:MoreOps['ChkdskRepair'] = 'Invoke-ChkdskRepairOp'

# Cevrimici salt okunur tarama ve iyilestirme eylemleri (Job_Action anahtarlariyla cagrilir; P.Drive tek harf)
function Invoke-SlvDriveAction([string]$Kind, $P) {
    $dr = ([string]$P.Drive).Trim().TrimEnd(':').ToUpperInvariant()
    if ($dr -cnotmatch '^[A-Z]$') { throw ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' harfi ge' + [char]0x00E7 + 'ersiz.') }
    if ($Kind -eq 'scan') {
        Write-WhLog ($dr + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' taran' + [char]0x0131 + 'yor (salt okunur)...')) 'INFO'
        $r = Repair-Volume -DriveLetter $dr -Scan -ErrorAction Stop
        Write-WhLog ($dr + ': tarama sonucu: ' + [string]$r) 'OK'
    } elseif ($Kind -eq 'optimize') {
        Write-WhLog ($dr + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' iyile' + [char]0x015F + 'tiriliyor...')) 'INFO'
        Optimize-Volume -DriveLetter $dr -ErrorAction Stop | Out-Null
        Write-WhLog ($dr + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' iyile' + [char]0x015F + 'tirildi.')) 'OK'
    }
}

function Invoke-BlResumeAction($P) {
    $d = ''
    try { $d = ([string]$P.Drive).Trim() } catch { $d = '' }
    if ($d -eq '') { $d = [string]$env:SystemDrive }
    if ($d.Length -eq 1) { $d += ':' }
    if ($d -cnotmatch '^[A-Za-z]:$') { throw ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ge' + [char]0x00E7 + 'ersiz.') }
    Resume-BitLocker -MountPoint $d -ErrorAction Stop | Out-Null
    Write-WhLog ($d + (' i' + [char]0x00E7 + 'in BitLocker korumas' + [char]0x0131 + ' s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '.')) 'OK'
}
$script:ExtraActions['BlResume'] = 'Invoke-BlResumeAction'

# ---------------- disk G/C hatalari (olay gunlugu) ----------------
# Disk: 7 bozuk blok, 11 denetleyici hatasi, 51 disk bellegi G/C hatasi, 52 ariza ongorusu (S.M.A.R.T.), 153 yeniden denenen G/C, 157 aygit beklenmedik cikarildi; Ntfs: 55 dosya sistemi bozuk, 140 yazma tutarsizligi
function Get-DiskErrorEvents([int]$Days = 30) {
    $out = New-Object System.Collections.ArrayList
    $evs = @()
    try { $evs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = @('disk', 'Ntfs', 'Microsoft-Windows-Ntfs'); Id = @(7, 11, 51, 52, 55, 140, 153, 157); StartTime = (Get-Date).AddDays(-$Days) } -MaxEvents 500 -ErrorAction Stop) } catch { $evs = @() }
    foreach ($e in $evs) { [void]$out.Add(@{ Time = [datetime]$e.TimeCreated; Id = [int]$e.Id; Source = [string]$e.ProviderName }) }
    return , $out.ToArray()
}

# Donus: @{ Counts (kimlik -> adet); Last; Total }
function Get-DiskErrorSummary($Events) {
    $c = @{}
    $last = [datetime]'2000-01-01'
    $total = 0
    foreach ($e in @($Events)) {
        $k = [string][int]$e.Id
        if ($c.ContainsKey($k)) { $c[$k] = [int]$c[$k] + 1 } else { $c[$k] = 1 }
        if ($e.Time -gt $last) { $last = $e.Time }
        $total++
    }
    return @{ Counts = $c; Last = $last; Total = $total }
}

function Get-DiskErrCount($Sum, [int]$Id) {
    $k = [string]$Id
    if ($Sum.Counts.ContainsKey($k)) { return [int]$Sum.Counts[$k] }
    return 0
}

function Add-DiskErrorFindings($Sum, [int]$Days) {
    $d = [string]$Days
    $pred = Get-DiskErrCount $Sum 52
    $bad = (Get-DiskErrCount $Sum 7) + (Get-DiskErrCount $Sum 11) + (Get-DiskErrCount $Sum 55)
    $soft = (Get-DiskErrCount $Sum 51) + (Get-DiskErrCount $Sum 153) + (Get-DiskErrCount $Sum 140)
    $act = New-SolveAction 'disk' '' 'Diskler sekmesi'
    if ($pred -gt 0) {
        Add-Finding 'disk-pred' 'maint' 'bad' ('Windows bir diskin yak' + [char]0x0131 + 'nda bozulaca' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' bildirdi') ('Son ' + $d + (' g' + [char]0x00FC + 'nde disk s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' ar' + [char]0x0131 + 'za ' + [char]0x00F6 + 'ng' + [char]0x00F6 + 'r' + [char]0x00FC + 's' + [char]0x00FC + ' (S.M.A.R.T.) bildirdi. Bu uyar' + [char]0x0131 + ' ciddiye al' + [char]0x0131 + 'nmal' + [char]0x0131 + 'd' + [char]0x0131 + 'r: ' + [char]0x00F6 + 'nemli dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' hemen ba' + [char]0x015F + 'ka bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye yedekleyin ve diski de' + [char]0x011F + 'i' + [char]0x015F + 'tirmeyi planlay' + [char]0x0131 + 'n.')) (New-SolveAction 'recover' '' 'Yedekle ve kurtar') 14
    }
    if ($bad -gt 0) {
        Add-Finding 'disk-io' 'maint' 'warn' ('Son ' + $d + (' g' + [char]0x00FC + 'nde ') + [string]$bad + (' disk ya da dosya sistemi hatas' + [char]0x0131 + '')) (('Windows bozuk blok, denetleyici hatas' + [char]0x0131 + ' ya da dosya sistemi bozulmas' + [char]0x0131 + ' kaydetmi' + [char]0x015F + ' (son kay' + [char]0x0131 + 't ') + $Sum.Last.ToString('dd.MM.yyyy HH:mm') + ('). Diskin ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kablosunu ve portunu denetleyin, Diskler sekmesinden dosya sistemi taramas' + [char]0x0131 + ' yap' + [char]0x0131 + 'n ve yedek al' + [char]0x0131 + 'n; s' + [char]0x00FC + 'rerse diski de' + [char]0x011F + 'i' + [char]0x015F + 'tirin.')) $act 6
    } elseif ($soft -ge 5) {
        Add-Finding 'disk-io' 'maint' 'info' ('Son ' + $d + (' g' + [char]0x00FC + 'nde ') + [string]$soft + (' disk G/' + [char]0x00C7 + ' yeniden denemesi')) ('Disk i' + [char]0x015F + 'lemleri yeniden denenmi' + [char]0x015F + ' ya da zaman a' + [char]0x015F + '' + [char]0x0131 + 'm' + [char]0x0131 + 'na u' + [char]0x011F + 'ram' + [char]0x0131 + '' + [char]0x015F + '. Genellikle gev' + [char]0x015F + 'ek bir USB ya da SATA ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + 'ndan, zay' + [char]0x0131 + 'f g' + [char]0x00FC + '' + [char]0x00E7 + ' kayna' + [char]0x011F + '' + [char]0x0131 + 'ndan veya yava' + [char]0x015F + 'layan bir diskten olur.') $act 0
    } elseif ($pred -eq 0) {
        Add-Finding 'disk-io' 'maint' 'ok' ('Son ' + $d + (' g' + [char]0x00FC + 'nde disk hatas' + [char]0x0131 + ' kayd' + [char]0x0131 + ' yok')) ''
    }
}

function Chk_DiskProtect {
    $sys = Get-SlvEnv
    $disks = Get-SlvDisks
    Add-DiskProtectFindings $disks $sys
    Add-VolumeHealthFindings $disks
}

function Chk_DiskErrors {
    $days = 30
    $sum = Get-DiskErrorSummary (Get-DiskErrorEvents $days)
    Add-DiskErrorFindings $sum $days
}

# ---------------- cozum merkezi: arka plan isleri ----------------
# ==================================================================
#  COZUM MERKEZI ARKA PLAN ISLERI: diskleri okuma ve surucu islemleri
# ==================================================================

# Diskleri ve BitLocker durumlarini okur; arayuzun cizecegi satirlari ve surucu secicilerin kullandigi ozet bilgileri (etiket, dosya sistemi, boyut, ortam) da hazirlar (hicbir seyi degistirmez)
function Job_SlvDisks($P) {
    try {
        $sysEnv = Get-SlvEnv
        $disks = Get-SlvDisks
        foreach ($d in @($disks)) { if ([string]$d.Drive -eq [string]$sysEnv.OsDrive) { $sysEnv.OsBlState = Get-BlState $d } }
        $out = New-Object System.Collections.ArrayList
        foreach ($d in @($disks)) {
            [void]$out.Add(@{ Drive = [string]$d.Drive; Type = [string]$d.DriveType; State = (Get-BlState $d); Plan = (Test-BlEnablePlan $d $sysEnv); Rows = (Get-SlvDiskRows $d $sysEnv)
                Label = [string]$d.Label; Fs = [string]$d.FileSystem; Size = [double]$d.Size; Free = [double]$d.Free; Media = [string]$d.Media; Bus = [string]$d.Bus; DiskName = [string]$d.DiskName })
        }
        $phys = @()
        try { $phys = Get-SlvPhysDisks } catch { Write-WhLog (('Fiziksel diskler okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
        return @{ Ok = $true; Sys = $sysEnv; Disks = $out.ToArray(); Phys = $phys }
    } catch {
        Write-WhLog (('Diskler okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false; Error = $_.Exception.Message }
    }
}

# Kind: scan (salt okunur tarama) | optimize (TRIM ya da birlestirme)
function Job_SlvDiskOp($P) {
    $kind = [string]$P.Kind
    try {
        if ($kind -ne 'scan' -and $kind -ne 'optimize') { throw (('Bilinmeyen disk i' + [char]0x015F + 'lemi: ') + $kind) }
        Invoke-SlvDriveAction $kind @{ Drive = [string]$P.Drive }
        return @{ Ok = $true; Kind = $kind }
    } catch {
        Write-WhLog (('Disk i' + [char]0x015F + 'lemi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (') + $kind + '): ' + $_.Exception.Message) 'ERR'
        return @{ Ok = $false; Kind = $kind; Error = $_.Exception.Message }
    }
}

# ---------------- cozum merkezi: bilgisayar bilgisi toplama ----------------
# ==================================================================
#  COZUM MERKEZI: "Bilgisayarim" bilgilerini toplama (arka plan isi)
#  Yalnizca okur. Bu bolum cekirdekte durur cunku Job_PcInfo arka plan calisma alaninda calisir; sekmenin cizimi ve yorumlamasi 126_solve_pc.ps1 icindedir.
# ==================================================================
function Get-PcText($V) {
    if ($null -eq $V) { return '' }
    $t = [regex]::Replace([string]$V, '[\u0000-\u001F\u007F]', ' ')
    return ([regex]::Replace($t, '\s+', ' ')).Trim()
}

# SMBIOS bellek turu kodu -> ad
function Get-PcMemTypeName([int]$Code) {
    switch ($Code) {
        18 { return 'DDR' }
        19 { return 'DDR2' }
        20 { return 'DDR2' }
        24 { return 'DDR3' }
        26 { return 'DDR4' }
        27 { return 'LPDDR' }
        28 { return 'LPDDR2' }
        29 { return 'LPDDR3' }
        30 { return 'LPDDR4' }
        34 { return 'DDR5' }
        35 { return 'LPDDR5' }
    }
    return ''
}

function Format-PcGb([double]$Gb) {
    $r = [math]::Round($Gb, 1)
    if ($r -eq [math]::Floor($r)) { return ([string][int]$r + ' GB') }
    return ($r.ToString('0.0', [System.Globalization.CultureInfo]::InvariantCulture) + ' GB')
}

function Format-PcSpan([double]$Hours) {
    if ($Hours -lt 1) { return ([string][int][math]::Floor($Hours * 60) + ' dk') }
    if ($Hours -lt 24) {
        $h = [int][math]::Floor($Hours)
        return ([string]$h + ' saat')
    }
    $d = [int][math]::Floor($Hours / 24)
    $h2 = [int][math]::Floor($Hours - $d * 24)
    return ([string]$d + (' g' + [char]0x00FC + 'n ') + [string]$h2 + ' saat')
}

# Ortam ve veri yolu -> kisa tur adi
function Get-PcDiskKind([string]$Media, [string]$Bus) {
    if ($Bus -eq 'USB') { return 'USB disk' }
    if ($Bus -eq 'NVMe' -or $Bus -eq '17') { return 'NVMe SSD' }
    if ($Media -eq 'SSD' -or $Media -eq '4') { return 'SSD' }
    if ($Media -eq 'HDD' -or $Media -eq '3') { return 'HDD' }
    if ($Bus -eq 'SD' -or $Bus -eq 'MMC') { return ('Bellek kart' + [char]0x0131 + '') }
    return 'Disk'
}

function Get-PcCim([string]$Class, [string]$Ns = 'root\cimv2', [string]$Filter = '') {
    try {
        if ($Filter -ne '') { return @(Get-CimInstance -Namespace $Ns -ClassName $Class -Filter $Filter -ErrorAction Stop) }
        return @(Get-CimInstance -Namespace $Ns -ClassName $Class -ErrorAction Stop)
    } catch { return @() }
}

# Bilgisayari okur (yalnizca okuma). Her bolum ayri korunur; bir sorgu basarisiz olursa o bolum bos kalir.
function Get-PcInfo {
    $admin = $false
    try { $admin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } catch { }
    $I = @{ Ok = $true; At = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Admin = $admin
        Machine = @{ Maker = ''; Model = ''; Kind = ''; IsVm = $false; Board = ''; Bios = ''; BiosDate = ''; Firmware = ''; SecureBoot = $null; Tpm = @{ Known = $false; Present = $false; Ready = $false; Version = '' } }
        Os = @{ Name = ''; Version = ''; Build = 0; Ubr = 0; Arch = ''; Installed = ''; Boot = ''; UptimeHours = [double]0 }
        Cpu = @{ Name = ''; Cores = 0; Threads = 0; Mhz = 0; L2KB = 0; L3KB = 0; Virt = $null }
        Mem = @{ TotalGB = [double]0; SlotCount = 0; MaxGB = [double]0; Modules = @() }
        Gpu = @(); Disks = @(); Net = @(); Battery = $null; Problems = @(); SysDrive = @{ Letter = ''; FreeGB = [double]0; SizeGB = [double]0 } }

    # bilgisayar, BIOS, anakart
    try {
        $cs = @(Get-PcCim 'Win32_ComputerSystem') | Select-Object -First 1
        if ($null -ne $cs) {
            $I.Machine.Maker = Get-PcText $cs.Manufacturer
            $I.Machine.Model = Get-PcText $cs.Model
            $I.Mem.TotalGB = [math]::Round([double]$cs.TotalPhysicalMemory / 1GB, 1)
            $I.Machine.IsVm = ((Get-PcText ($cs.Manufacturer + ' ' + $cs.Model)) -match 'Virtual|VMware|VirtualBox|KVM|QEMU|Parallels|Hyper-V')
            $pt = 0
            try { $pt = [int]$cs.PCSystemType } catch { }
            if ($pt -eq 1) { $I.Machine.Kind = ('Masa' + [char]0x00FC + 'st' + [char]0x00FC + '') } elseif ($pt -eq 2) { $I.Machine.Kind = ('Diz' + [char]0x00FC + 'st' + [char]0x00FC + '') } elseif ($pt -eq 3) { $I.Machine.Kind = ('' + [char]0x0130 + '' + [char]0x015F + ' istasyonu') }
        }
    } catch { }
    try {
        $bios = @(Get-PcCim 'Win32_BIOS') | Select-Object -First 1
        if ($null -ne $bios) {
            $I.Machine.Bios = Get-PcText ($bios.Manufacturer + ' ' + $bios.SMBIOSBIOSVersion)
            try { if ($null -ne $bios.ReleaseDate) { $I.Machine.BiosDate = ([datetime]$bios.ReleaseDate).ToString('dd.MM.yyyy') } } catch { }
        }
        $bb = @(Get-PcCim 'Win32_BaseBoard') | Select-Object -First 1
        if ($null -ne $bb) { $I.Machine.Board = Get-PcText ($bb.Manufacturer + ' ' + $bb.Product) }
    } catch { }
    try {
        $fw = Get-RegValue 'HKLM\SYSTEM\CurrentControlSet\Control' 'PEFirmwareType' $null
        if ($null -ne $fw) { if ([int]$fw -eq 2) { $I.Machine.Firmware = 'UEFI' } elseif ([int]$fw -eq 1) { $I.Machine.Firmware = 'Eski BIOS' } }
        $sb = Get-RegValue 'HKLM\SYSTEM\CurrentControlSet\Control\SecureBoot\State' 'UEFISecureBootEnabled' $null
        if ($null -ne $sb) { $I.Machine.SecureBoot = ([int]$sb -eq 1) }
    } catch { }
    try {
        $tp = @(Get-PcCim 'Win32_Tpm' 'root\cimv2\Security\MicrosoftTpm') | Select-Object -First 1
        if ($null -ne $tp) {
            $I.Machine.Tpm.Known = $true
            $I.Machine.Tpm.Present = $true
            $I.Machine.Tpm.Ready = ($tp.IsEnabled_InitialValue -eq $true -and $tp.IsActivated_InitialValue -eq $true)
            $I.Machine.Tpm.Version = (Get-PcText $tp.SpecVersion).Split(',')[0].Trim()
        } elseif ($admin) {
            $I.Machine.Tpm.Known = $true
        }
    } catch { }

    # Windows
    try {
        $os = @(Get-PcCim 'Win32_OperatingSystem') | Select-Object -First 1
        if ($null -ne $os) {
            $I.Os.Name = (Get-PcText $os.Caption) -replace '^Microsoft\s+', ''
            $I.Os.Arch = Get-PcText $os.OSArchitecture
            $b = 0
            [void][int]::TryParse([string]$os.BuildNumber, [ref]$b)
            $I.Os.Build = $b
            try { $I.Os.Installed = ([datetime]$os.InstallDate).ToString('dd.MM.yyyy') } catch { }
            try {
                $boot = [datetime]$os.LastBootUpTime
                $I.Os.Boot = $boot.ToString('dd.MM.yyyy HH:mm')
                $I.Os.UptimeHours = [math]::Round(((Get-Date) - $boot).TotalHours, 1)
            } catch { }
        }
        $I.Os.Version = [string](Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'DisplayVersion' '')
        $I.Os.Ubr = [int](Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'UBR' 0)
    } catch { }

    # islemci
    try {
        $cp = @(Get-PcCim 'Win32_Processor')
        if ($cp.Count -gt 0) {
            $I.Cpu.Name = Get-PcText $cp[0].Name
            foreach ($c in $cp) { $I.Cpu.Cores += [int]$c.NumberOfCores; $I.Cpu.Threads += [int]$c.NumberOfLogicalProcessors }
            $I.Cpu.Mhz = [int]$cp[0].MaxClockSpeed
            $I.Cpu.L2KB = [int]$cp[0].L2CacheSize
            $I.Cpu.L3KB = [int]$cp[0].L3CacheSize
            if ($null -ne $cp[0].VirtualizationFirmwareEnabled) { $I.Cpu.Virt = ($cp[0].VirtualizationFirmwareEnabled -eq $true) }
        }
    } catch { }

    # bellek modulleri
    try {
        $mods = New-Object System.Collections.ArrayList
        foreach ($m in @(Get-PcCim 'Win32_PhysicalMemory')) {
            $tn = ''
            try { $tn = Get-PcMemTypeName ([int]$m.SMBIOSMemoryType) } catch { }
            [void]$mods.Add(@{ Slot = (Get-PcText $m.DeviceLocator); Bank = (Get-PcText $m.BankLabel); CapGB = [math]::Round([double]$m.Capacity / 1GB, 1); Type = $tn
                Rated = [int]$m.Speed; Running = [int]$m.ConfiguredClockSpeed; Maker = (Get-PcText $m.Manufacturer); Part = (Get-PcText $m.PartNumber) })
        }
        $I.Mem.Modules = $mods.ToArray()
        $arr = @(Get-PcCim 'Win32_PhysicalMemoryArray')
        foreach ($a in $arr) {
            $I.Mem.SlotCount += [int]$a.MemoryDevices
            $I.Mem.MaxGB += [math]::Round([double]$a.MaxCapacity / 1MB, 0)
        }
    } catch { }

    # ekran kartlari
    try {
        $gl = New-Object System.Collections.ArrayList
        foreach ($g in @(Get-PcCim 'Win32_VideoController')) {
            $dd = ''
            try { if ($null -ne $g.DriverDate) { $dd = ([datetime]$g.DriverDate).ToString('dd.MM.yyyy') } } catch { }
            $res = ''
            if ([int]$g.CurrentHorizontalResolution -gt 0) { $res = [string][int]$g.CurrentHorizontalResolution + 'x' + [string][int]$g.CurrentVerticalResolution + ' @ ' + [string][int]$g.CurrentRefreshRate + ' Hz' }
            [void]$gl.Add(@{ Name = (Get-PcText $g.Name); Driver = (Get-PcText $g.DriverVersion); DriverDate = $dd; Res = $res })
        }
        $I.Gpu = $gl.ToArray()
    } catch { }

    # diskler
    try {
        $health = @{}
        try { foreach ($pd in @(Get-PhysicalDisk -ErrorAction Stop)) { $health[[string]$pd.DeviceId] = [string]$pd.HealthStatus } } catch { }
        $dl = New-Object System.Collections.ArrayList
        $phys = Get-SlvPhysDisks
        foreach ($d in @($phys)) {
            $h = ''
            if ($health.ContainsKey([string]$d.Number)) { $h = [string]$health[[string]$d.Number] }
            [void]$dl.Add(@{ Number = [int]$d.Number; Name = (Get-PcText $d.Name); Kind = (Get-PcDiskKind ([string]$d.Media) ([string]$d.Bus)); Bus = [string]$d.Bus
                SizeGB = [math]::Round([double]$d.Size / 1GB, 0); Style = [string]$d.Style; Letters = @($d.Letters); Health = $h; IsSystem = ($d.IsSystem -eq $true) })
        }
        $I.Disks = $dl.ToArray()
    } catch { }
    try {
        $sd = [string]$env:SystemDrive
        if ($sd -ne '') {
            $di = New-Object System.IO.DriveInfo -ArgumentList $sd
            $I.SysDrive.Letter = $sd
            $I.SysDrive.FreeGB = [math]::Round([double]$di.AvailableFreeSpace / 1GB, 1)
            $I.SysDrive.SizeGB = [math]::Round([double]$di.TotalSize / 1GB, 1)
        }
    } catch { }

    # ag bagdastiricilari (yalnizca fiziksel)
    try {
        $nl = New-Object System.Collections.ArrayList
        foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop)) {
            $mt = [string]$a.PhysicalMediaType
            $kind = ('A' + [char]0x011F + '')
            if ($mt -match '802\.11') { $kind = 'Wi-Fi' } elseif ($mt -match '802\.3') { $kind = 'Ethernet' } elseif ($mt -match 'Bluetooth') { $kind = 'Bluetooth' }
            [void]$nl.Add(@{ Name = (Get-PcText $a.InterfaceDescription); Kind = $kind; Speed = (Get-PcText $a.LinkSpeed); Up = ([string]$a.Status -eq 'Up') })
        }
        $I.Net = $nl.ToArray()
    } catch { }

    # pil
    try {
        $batt = @(Get-PcCim 'Win32_Battery') | Select-Object -First 1
        if ($null -ne $batt) {
            $bi = @{ Percent = [int]$batt.EstimatedChargeRemaining; Charging = ([int]$batt.BatteryStatus -ne 1); DesignMWh = 0; FullMWh = 0; WearPct = -1 }
            try {
                $ds = @(Get-PcCim 'BatteryStaticData' 'root\wmi') | Select-Object -First 1
                $fc = @(Get-PcCim 'BatteryFullChargedCapacity' 'root\wmi') | Select-Object -First 1
                if ($null -ne $ds) { $bi.DesignMWh = [int]$ds.DesignedCapacity }
                if ($null -ne $fc) { $bi.FullMWh = [int]$fc.FullChargedCapacity }
                if ($bi.DesignMWh -gt 0 -and $bi.FullMWh -gt 0) { $bi.WearPct = [int][math]::Max(0, [math]::Round(100 - ($bi.FullMWh * 100.0 / $bi.DesignMWh), 0)) }
            } catch { }
            $I.Battery = $bi
            if ($I.Machine.Kind -eq '') { $I.Machine.Kind = ('Diz' + [char]0x00FC + 'st' + [char]0x00FC + '') }
        }
    } catch { }
    if ($I.Machine.IsVm) { $I.Machine.Kind = 'Sanal makine' }

    # sorunlu aygitlar (devre disi birakilmis olanlar sayilmaz)
    try {
        $pl = New-Object System.Collections.ArrayList
        foreach ($p in @(Get-PcCim 'Win32_PnPEntity' 'root\cimv2' 'ConfigManagerErrorCode <> 0 AND ConfigManagerErrorCode <> 22')) {
            if ($pl.Count -ge 12) { break }
            [void]$pl.Add(@{ Name = (Get-PcText $p.Name); Code = [int]$p.ConfigManagerErrorCode })
        }
        $I.Problems = $pl.ToArray()
    } catch { }
    return $I
}

function Job_PcInfo($P) {
    try {
        Write-WhLog ('Bilgisayar bilgileri okunuyor (yaln' + [char]0x0131 + 'zca okuma)...') 'INFO'
        $info = Get-PcInfo
        return @{ Ok = $true; Info = $info }
    } catch {
        Write-WhLog (('Bilgisayar bilgileri okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false; Error = $_.Exception.Message }
    }
}

# ---------------- kalici silme cekirdegi ----------------
# ==================================================================
#  KALICI SILME CEKIRDEGI (9.0.0): yontemler, sure tahmini, disk korumalari ve kimlik denetimi.
#  Burada yalnizca okuyan ve karar veren islevler var; diske yazan kod Eklenti\DiskSilme.ps1 dosyasindadir ve yalnizca
#  kullanici onay verdikten sonra yuklenir. Hicbir islev Windows Update, Defender, Guvenlik Duvari ya da UAC'ye dokunmaz.
#  Guvenlik kurallari:
#   1. Windows'un calistigi, Multimizer'in ya da gecici dosyalarin bulundugu disklere dogrudan yazilmaz (yalnizca bos alan temizligi yapilir).
#   2. Cevrimdisi, salt okunur, depolama havuzu uyesi ve kumelenmis disklere dokunulmaz.
#   3. Disk, onay verildigi andaki boyut, ad ve seri numarasiyla islem aninda yeniden karsilastirilir; uyusmazsa islem baslamaz.
#   4. Geri dondurulemez islemler (bolum ya da disk silme) icin hedefin adi elle yazdirilir.
# ==================================================================

# ---------------- yontemler ----------------
# Anahtarlar: random (tek gecis rastgele), zero (tek gecis sifir), dod3 (sifir, bir, rastgele), random3 (uc gecis rastgele)
function Get-WipeMethodKey([string]$Method) {
    $m = ([string]$Method).Trim().ToLowerInvariant()
    if (@('random', 'zero', 'dod3', 'random3') -contains $m) { return $m }
    return 'random'
}

# Gecis desenleri: 0 = rastgele (AES-256-CTR akisi), 1 = sifir, 2 = 0xFF
function Get-WipeModes([string]$Method) {
    switch (Get-WipeMethodKey $Method) {
        'zero'    { return , @(1) }
        'dod3'    { return , @(1, 2, 0) }
        'random3' { return , @(0, 0, 0) }
    }
    return , @(0)
}

function Get-WipeMethodName([string]$Method) {
    switch (Get-WipeMethodKey $Method) {
        'zero'    { return ('tek ge' + [char]0x00E7 + 'i' + [char]0x015F + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'r') }
        'dod3'    { return ('3 ge' + [char]0x00E7 + 'i' + [char]0x015F + ' (s' + [char]0x0131 + 'f' + [char]0x0131 + 'r, bir, rastgele)') }
        'random3' { return ('3 ge' + [char]0x00E7 + 'i' + [char]0x015F + ' rastgele') }
    }
    return ('tek ge' + [char]0x00E7 + 'i' + [char]0x015F + ' rastgele')
}

# Acilir liste ogeleri: @{ Key; Name } dizileri (arayuz New-Choice ile cevirir)
function Get-WipeMethodList {
    return , @(
        @{ Key = 'random'; Name = ('Tek ge' + [char]0x00E7 + 'i' + [char]0x015F + ' rastgele (' + [char]0x00F6 + 'nerilir)') },
        @{ Key = 'zero'; Name = ('Tek ge' + [char]0x00E7 + 'i' + [char]0x015F + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'r (h' + [char]0x0131 + 'zl' + [char]0x0131 + ')') },
        @{ Key = 'dod3'; Name = ('3 ge' + [char]0x00E7 + 'i' + [char]0x015F + ': s' + [char]0x0131 + 'f' + [char]0x0131 + 'r, bir, rastgele') },
        @{ Key = 'random3'; Name = ('3 ge' + [char]0x00E7 + 'i' + [char]0x015F + ' rastgele (yava' + [char]0x015F + ')') }
    )
}

function Get-WipeVerifyKey([string]$Verify) {
    $v = ([string]$Verify).Trim().ToLowerInvariant()
    if (@('none', 'sample', 'full') -contains $v) { return $v }
    return 'sample'
}

function Get-WipeVerifyList {
    return , @(
        @{ Key = 'sample'; Name = ('Do' + [char]0x011F + 'rula: ' + [char]0x00F6 + 'rnekle (h' + [char]0x0131 + 'zl' + [char]0x0131 + ')') },
        @{ Key = 'full'; Name = ('Do' + [char]0x011F + 'rula: tamam' + [char]0x0131 + 'n' + [char]0x0131 + ' oku (yava' + [char]0x015F + ')') },
        @{ Key = 'none'; Name = ('Do' + [char]0x011F + 'rulama yapma') }
    )
}

function Get-WipeVerifyName([string]$Verify) {
    switch (Get-WipeVerifyKey $Verify) {
        'full' { return ('tamam' + [char]0x0131 + ' geri okunup kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r') }
        'none' { return ('do' + [char]0x011F + 'rulama yap' + [char]0x0131 + 'lmaz') }
    }
    return ('' + [char]0x00F6 + 'rnekler geri okunup kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r')
}

# Disk ya da bolum silindikten sonra ne yapilsin: none (bos birak), ntfs, exfat, fat32
function Get-WipeAfterKey([string]$After) {
    $a = ([string]$After).Trim().ToLowerInvariant()
    if (@('none', 'ntfs', 'exfat', 'fat32') -contains $a) { return $a }
    return 'none'
}

function Get-WipeAfterList {
    return , @(
        @{ Key = 'none'; Name = ('Sonra: bo' + [char]0x015F + ' b' + [char]0x0131 + 'rak') },
        @{ Key = 'ntfs'; Name = ('Sonra: NTFS olarak bi' + [char]0x00E7 + 'imle') },
        @{ Key = 'exfat'; Name = ('Sonra: exFAT olarak bi' + [char]0x00E7 + 'imle') },
        @{ Key = 'fat32'; Name = ('Sonra: FAT32 olarak bi' + [char]0x00E7 + 'imle (en ' + [char]0x00E7 + 'ok 32 GB)') }
    )
}

function Get-WipeAfterName([string]$After) {
    switch (Get-WipeAfterKey $After) {
        'ntfs'  { return ('NTFS olarak bi' + [char]0x00E7 + 'imlenir') }
        'exfat' { return ('exFAT olarak bi' + [char]0x00E7 + 'imlenir') }
        'fat32' { return ('FAT32 olarak bi' + [char]0x00E7 + 'imlenir') }
    }
    return ('bo' + [char]0x015F + ' (ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ') b' + [char]0x0131 + 'rak' + [char]0x0131 + 'l' + [char]0x0131 + 'r')
}

# ---------------- sure ve ilerleme ----------------
function Format-WipeEta([double]$Seconds) {
    if ($Seconds -lt 0 -or [double]::IsNaN($Seconds) -or [double]::IsInfinity($Seconds)) { return 'bilinmiyor' }
    $s = [int][math]::Round($Seconds)
    if ($s -lt 45) { return 'bir dakikadan az' }
    $m = [int][math]::Round($s / 60.0)
    if ($m -lt 60) { return [string]$m + ' dk' }
    $h = [int][math]::Floor($m / 60.0)
    $mm = $m - $h * 60
    if ($h -ge 48) { return [string][int][math]::Round($h / 24.0) + (' g' + [char]0x00FC + 'n') }
    if ($mm -eq 0) { return [string]$h + ' sa' }
    return [string]$h + ' sa ' + [string]$mm + ' dk'
}

# Ortama gore beklenen yazma hizi (bayt/sn). Sifre akisi uretimi de islemciyi sinirlar (yaklasik 450 MB/sn).
function Get-WipeRate([string]$Bus, [string]$Media) {
    $r = [double]80MB
    if ($Bus -eq 'USB') { $r = [double]25MB }
    elseif ($Media -eq 'HDD') { $r = [double]110MB }
    elseif ($Bus -eq 'NVMe') { $r = [double]450MB }
    elseif ($Media -eq 'SSD') { $r = [double]350MB }
    elseif ($Bus -eq 'SD' -or $Bus -eq 'MMC') { $r = [double]20MB }
    return $r
}

# Tahmini sure: @{ Lo; Hi (sn); Text }. Passes: yazma gecisi sayisi; Verify: none | sample | full
function Get-WipeEstimate([double]$Bytes, [int]$Passes, [string]$Verify, [string]$Bus, [string]$Media) {
    if ($Passes -lt 1) { $Passes = 1 }
    $rate = Get-WipeRate $Bus $Media
    $work = $Bytes * $Passes
    if ((Get-WipeVerifyKey $Verify) -eq 'full') { $work += $Bytes }
    elseif ((Get-WipeVerifyKey $Verify) -eq 'sample') { $work += [math]::Min($Bytes, [double]256MB) }
    $lo = $work / $rate
    $hi = $lo * 2.2
    $txt = ('yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + (Format-WipeEta $lo)
    if ($lo -ge 90) { $txt = ('yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + (Format-WipeEta $lo) + (' ' + [char]0x2013 + ' ') + (Format-WipeEta $hi) }
    return @{ Lo = $lo; Hi = $hi; Text = $txt }
}

# Is paneli etiketi: "Disk 2 siliniyor . Yaziliyor . %37 . 85 MB/sn . kalan 12 dk"
function Get-WipeProgressLabel([string]$Label, [string]$Stage, [double]$Done, [double]$Total, [double]$Seconds) {
    $t = $Label
    if ($Stage -ne '') { $t += (' ' + [char]0x00B7 + ' ') + $Stage }
    if ($Total -gt 0) { $t += (' ' + [char]0x00B7 + ' %') + [string][int][math]::Floor([math]::Min($Done, $Total) * 100.0 / $Total) }
    if ($Seconds -ge 3 -and $Done -gt 0) {
        $rate = $Done / $Seconds
        $t += (' ' + [char]0x00B7 + ' ') + (Format-Size $rate) + '/sn'
        if ($Total -gt $Done) { $t += (' ' + [char]0x00B7 + ' kalan ') + (Format-WipeEta (($Total - $Done) / $rate)) }
    }
    return $t
}

# Karsilastirma icin metni sadelestirir: Turkce harfler ASCII karsiligina cevrilir, bosluklar teklestirilir, kucuk harfe indirilir.
# Boylece "Disk 2 Bolum 1" yerine "disk 2 bolum 1" yazilmasi da kabul edilir.
function ConvertTo-WipeFold([string]$Text) {
    $s = [string]$Text
    $pairs = @(@(246, 'o'), @(214, 'o'), @(252, 'u'), @(220, 'u'), @(305, 'i'), @(304, 'i'), @(351, 's'), @(350, 's'), @(231, 'c'), @(199, 'c'), @(287, 'g'), @(286, 'g'))
    foreach ($p in $pairs) { $s = $s.Replace([string][char][int]$p[0], [string]$p[1]) }
    $s = ($s -replace '\s+', ' ').Trim()
    return $s.ToLowerInvariant()
}

# Elle yazilan onay metni eslesiyor mu? Buyuk/kucuk harf, Turkce harf ve fazla bosluk onemsenmez.
function Test-WipeTyped([string]$Typed, [string]$Expect) {
    $b = ConvertTo-WipeFold $Expect
    if ($b -eq '') { return $false }
    return ((ConvertTo-WipeFold $Typed) -eq $b)
}

# Surucude birakilacak pay: toplamin %1'i (en az 512 MB); Windows surucusunde %3 (en az 2 GB)
function Get-WipeReserve([double]$Total, [bool]$IsOs) {
    $pct = 0.01
    $min = [double]536870912
    if ($IsOs) { $pct = 0.03; $min = [double]2147483648 }
    return [double][math]::Max($min, [math]::Floor($Total * $pct))
}

# ---------------- korumalar ----------------
# Dogrudan yazilmamasi gereken surucu harfleri: @{ 'C:' = 'neden' }
function Get-WipeProtectedLetters {
    $map = @{}
    $sd = ([string]$env:SystemDrive).Trim().ToUpperInvariant()
    if ($sd.Length -ge 2) { $map[$sd.Substring(0, 2)] = ('Windows bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor') }
    $adds = New-Object System.Collections.ArrayList
    $app = ''
    try { $app = [string](Get-AppFolder) } catch { $app = '' }
    [void]$adds.Add(@($app, ('Multimizer bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor')))
    $tmp = ''
    try { $tmp = [System.IO.Path]::GetTempPath() } catch { $tmp = '' }
    [void]$adds.Add(@($tmp, ('ge' + [char]0x00E7 + 'ici dosyalar bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de duruyor')))
    [void]$adds.Add(@([string]$env:USERPROFILE, ('kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' profili bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de')))
    foreach ($a in $adds) {
        $p = ([string]$a[0]).Trim()
        if ($p.Length -ge 2 -and $p.Substring(1, 1) -eq ':') {
            $l = $p.Substring(0, 1).ToUpperInvariant() + ':'
            if (-not $map.ContainsKey($l)) { $map[$l] = [string]$a[1] }
        }
    }
    try {
        foreach ($pf in @(Get-CimInstance -ClassName Win32_PageFileUsage -ErrorAction Stop)) {
            $n = ([string]$pf.Name).Trim()
            if ($n.Length -ge 2 -and $n.Substring(1, 1) -eq ':') {
                $l = $n.Substring(0, 1).ToUpperInvariant() + ':'
                if (-not $map.ContainsKey($l)) { $map[$l] = ('sayfa dosyas' + [char]0x0131 + ' bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de') }
            }
        }
    } catch { }
    return $map
}

# Canli disk modeli (hicbir sey degistirmez). Donus: $null (disk yok) ya da
# @{ Number; Name; Size; UniqueId; Serial; Bus; Media; Style; IsSystem; IsBoot; Offline; ReadOnly; Clustered; Pool; Sector; Letters; Roles; Parts }
# Parts: @{ Number; Offset; Size; Letter; Type; IsSystem; IsBoot; IsActive; Fs; Label }
function Get-WipeDiskLive([int]$Number) {
    $dk = $null
    try { $dk = Get-Disk -Number $Number -ErrorAction Stop } catch { return $null }
    if ($null -eq $dk) { return $null }
    $m = @{ Number = $Number; Name = ([string]$dk.FriendlyName).Trim(); Size = [double]$dk.Size; UniqueId = ([string]$dk.UniqueId).Trim(); Serial = ([string]$dk.SerialNumber).Trim()
        Bus = [string]$dk.BusType; Media = ''; Style = [string]$dk.PartitionStyle; IsSystem = ($dk.IsSystem -eq $true); IsBoot = ($dk.IsBoot -eq $true)
        Offline = ($dk.IsOffline -eq $true); ReadOnly = ($dk.IsReadOnly -eq $true); Clustered = ($dk.IsClustered -eq $true); Pool = $false; Sector = 512
        Letters = @(); Roles = @(); Parts = @() }
    try { if ([int]$dk.LogicalSectorSize -ge 512) { $m.Sector = [int]$dk.LogicalSectorSize } } catch { }
    try {
        $pd = Get-PhysicalDisk -ErrorAction Stop | Where-Object { [string]$_.DeviceId -eq [string]$Number } | Select-Object -First 1
        if ($null -ne $pd) {
            $m.Media = [string]$pd.MediaType
            try { $m.Pool = (@($pd.CannotPoolReason) -contains 'In a Pool') } catch { }
        }
    } catch { }
    $letters = New-Object System.Collections.ArrayList
    $parts = New-Object System.Collections.ArrayList
    $vols = @{}
    try { foreach ($v in @(Get-Volume -ErrorAction Stop)) { if ($v.DriveLetter) { $vols[([string]$v.DriveLetter).ToUpperInvariant() + ':'] = $v } } } catch { }
    try {
        foreach ($pt in @(Get-Partition -DiskNumber $Number -ErrorAction Stop)) {
            $l = ''
            if ($pt.DriveLetter) { $l = ([string]$pt.DriveLetter).ToUpperInvariant() + ':' }
            $fs = ''
            $lbl = ''
            if ($l -ne '' -and $vols.ContainsKey($l)) { $fs = [string]$vols[$l].FileSystem; $lbl = [string]$vols[$l].FileSystemLabel }
            [void]$parts.Add(@{ Number = [int]$pt.PartitionNumber; Offset = [double]$pt.Offset; Size = [double]$pt.Size; Letter = $l; Type = [string]$pt.Type
                IsSystem = ($pt.IsSystem -eq $true); IsBoot = ($pt.IsBoot -eq $true); IsActive = ($pt.IsActive -eq $true); Fs = $fs; Label = $lbl })
            if ($l -ne '') { [void]$letters.Add($l) }
        }
    } catch { }
    $m.Letters = $letters.ToArray()
    $m.Parts = $parts.ToArray()
    $prot = Get-WipeProtectedLetters
    $roles = New-Object System.Collections.ArrayList
    foreach ($l in $m.Letters) {
        if ($prot.ContainsKey($l)) { [void]$roles.Add(($l + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ': ') + [string]$prot[$l])) }
    }
    $m.Roles = $roles.ToArray()
    return $m
}

# Bu diske dogrudan yazilabilir mi? Scope: Unallocated | Partition | Disk. Donus: '' = uygun, aksi halde neden.
function Test-WipeDiskAllowed($Live, [string]$Scope) {
    if ($null -eq $Live) { return ('Disk bulunamad' + [char]0x0131 + ' (' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' olabilir).') }
    if ($Live.IsSystem -eq $true -or $Live.IsBoot -eq $true) { return ('Windows bu diskte ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor. Bu diske do' + [char]0x011F + 'rudan yaz' + [char]0x0131 + 'lmaz; yaln' + [char]0x0131 + 'zca s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'lerin bo' + [char]0x015F + ' alan' + [char]0x0131 + ' temizlenebilir.') }
    $roles = @($Live.Roles)
    if ($roles.Count -gt 0) { return (('Bu diske do' + [char]0x011F + 'rudan yaz' + [char]0x0131 + 'lmaz: ') + [string]$roles[0] + '.') }
    if ($Live.Offline -eq $true) { return ('Disk ' + [char]0x00E7 + 'evrimd' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + '. Disk Y' + [char]0x00F6 + 'netimi' + [char]0x2019 + 'nden ' + [char]0x00E7 + 'evrimi' + [char]0x00E7 + 'i yap' + [char]0x0131 + 'p yeniden deneyin.') }
    if ($Live.ReadOnly -eq $true) { return ('Disk salt okunur (yazma korumal' + [char]0x0131 + ').') }
    if ($Live.Pool -eq $true) { return ('Disk bir depolama alanlar' + [char]0x0131 + ' havuzunun ' + [char]0x00FC + 'yesi; havuzu Windows' + [char]0x2019 + 'tan kald' + [char]0x0131 + 'rmadan silinemez.') }
    if ($Live.Clustered -eq $true) { return ('Disk bir k' + [char]0x00FC + 'me yap' + [char]0x0131 + 's' + [char]0x0131 + 'n' + [char]0x0131 + 'n par' + [char]0x00E7 + 'as' + [char]0x0131 + '; silinemez.') }
    if ([string]$Live.Bus -eq 'Spaces') { return ('Bu bir Depolama Alanlar' + [char]0x0131 + ' sanal diski; Windows' + [char]0x2019 + 'tan y' + [char]0x00F6 + 'netilmeli.') }
    if ([double]$Live.Size -le 0) { return ('Disk boyutu okunamad' + [char]0x0131 + '.') }
    if (@('Unallocated', 'Partition', 'Disk') -notcontains $Scope) { return ('Bilinmeyen silme kapsam' + [char]0x0131 + '.') }
    return ''
}

# Bolum silinebilir mi? Donus: '' = uygun, aksi halde neden.
function Test-WipePartAllowed($Live, $Part) {
    if ($null -eq $Part) { return ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm bulunamad' + [char]0x0131 + ' (disk de' + [char]0x011F + 'i' + [char]0x015F + 'mi' + [char]0x015F + ' olabilir).') }
    if ($Part.IsSystem -eq $true -or $Part.IsBoot -eq $true) { return ('Bu b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm Windows' + [char]0x2019 + 'a ait; silinemez.') }
    if ([double]$Part.Size -le 0) { return ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm boyutu okunamad' + [char]0x0131 + '.') }
    return ''
}

# Onay anindaki bilgiler (Expect) islem anindaki canli diskle uyusuyor mu? Donus: '' = uyusuyor, aksi halde neden.
function Test-WipeIdentity($Live, $Expect) {
    if ($null -eq $Live) { return ('Disk bulunamad' + [char]0x0131 + ' (' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' olabilir).') }
    if ($null -eq $Expect) { return ('Disk kimli' + [char]0x011F + 'i do' + [char]0x011F + 'rulanamad' + [char]0x0131 + '; i' + [char]0x015F + 'lem ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmad' + [char]0x0131 + '.') }
    $bad = $false
    if ($null -ne $Expect.Size -and [double]$Expect.Size -gt 0 -and [double]$Live.Size -ne [double]$Expect.Size) { $bad = $true }
    $en = ([string]$Expect.Name).Trim()
    if ($en -ne '' -and ([string]$Live.Name).Trim() -ne '' -and $en.ToLowerInvariant() -ne ([string]$Live.Name).Trim().ToLowerInvariant()) { $bad = $true }
    $eu = ([string]$Expect.UniqueId).Trim()
    if ($eu -ne '' -and ([string]$Live.UniqueId).Trim() -ne '' -and $eu.ToLowerInvariant() -ne ([string]$Live.UniqueId).Trim().ToLowerInvariant()) { $bad = $true }
    $es = ([string]$Expect.Serial).Trim()
    if ($es -ne '' -and ([string]$Live.Serial).Trim() -ne '' -and $es.ToLowerInvariant() -ne ([string]$Live.Serial).Trim().ToLowerInvariant()) { $bad = $true }
    if ($bad) { return ('Disk, onay verdi' + [char]0x011F + 'iniz andan sonra de' + [char]0x011F + 'i' + [char]0x015F + 'mi' + [char]0x015F + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor (boyut, ad ya da seri numaras' + [char]0x0131 + ' uyu' + [char]0x015F + 'muyor). G' + [char]0x00FC + 'venli' + [char]0x011F + 'iniz i' + [char]0x00E7 + 'in i' + [char]0x015F + 'lem ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmad' + [char]0x0131 + '; diskleri yenileyip yeniden se' + [char]0x00E7 + 'in.') }
    return ''
}

# Disk satirindan bir silme hedefi bilgisi cikarir (onay anindaki kimlik): @{ Size; Name; UniqueId; Serial }
function Get-WipeExpect($Disk) {
    return @{ Size = [double]$Disk.Size; Name = ([string]$Disk.Name).Trim(); UniqueId = ([string]$Disk.UniqueId).Trim(); Serial = ([string]$Disk.Serial).Trim() }
}

# ---------------- dosya ve klasor silme korumalari ----------------
# Bu yol kalici silinebilir mi? '' = evet, aksi halde neden. Silinmeyenler: surucu koku; Windows, Program Files ve icleri; ProgramData, Users,
# kullanici profilinin, AppData'nin ve kisisel klasorlerin (Masaustu, Belgeler, Indirilenler ...) kendisi; Multimizer'in calistigi klasor ve ici.
# Mesajlar "silinemez" sozcugunu tasir: geri yukleme hedefi denetimi bu sozcuge bakarak yalnizca silme yasaklarini gecer.
function Test-SecureDeleteAllowed([string]$Path) {
    $full = ''
    try { $full = [System.IO.Path]::GetFullPath($Path) } catch { return ('Ge' + [char]0x00E7 + 'ersiz yol.') }
    $sep = [string][System.IO.Path]::DirectorySeparatorChar
    $t = $full.TrimEnd('\', '/')
    if ($t.Length -le 3) { return ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' k' + [char]0x00F6 + 'k' + [char]0x00FC + ' silinemez.') }
    $deny = New-Object System.Collections.ArrayList
    foreach ($v in @($env:WINDIR, $env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramData, $env:USERPROFILE, $env:PUBLIC, $env:SystemDrive)) {
        if (-not [string]::IsNullOrEmpty($v)) { [void]$deny.Add(([string]$v).TrimEnd('\', '/')) }
    }
    $sd = ([string]$env:SystemDrive).TrimEnd('\', '/')
    if ($sd -ne '') { foreach ($n in @('Users', 'Documents and Settings')) { [void]$deny.Add($sd + $sep + $n) } }
    foreach ($d in $deny) {
        if ($t.Equals($d, [StringComparison]::OrdinalIgnoreCase)) { return ('Sistem klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' silinemez.') }
    }
    foreach ($v in @($env:WINDIR, $env:ProgramFiles, ${env:ProgramFiles(x86)})) {
        if ([string]::IsNullOrEmpty($v)) { continue }
        $pre = ([string]$v).TrimEnd('\', '/') + $sep
        if ($t.StartsWith($pre, [StringComparison]::OrdinalIgnoreCase)) { return ('Windows ve program klas' + [char]0x00F6 + 'rlerinin i' + [char]0x00E7 + 'i silinemez.') }
    }
    # kullanicinin kisisel klasorlerinin kendisi (icindeki dosya ve alt klasorler silinebilir)
    $own = New-Object System.Collections.ArrayList
    foreach ($v in @($env:APPDATA, $env:LOCALAPPDATA, $env:OneDrive, $env:OneDriveConsumer, $env:OneDriveCommercial)) {
        if (-not [string]::IsNullOrEmpty($v)) { [void]$own.Add(([string]$v).TrimEnd('\', '/')) }
    }
    if (-not [string]::IsNullOrEmpty($env:USERPROFILE)) {
        $up = ([string]$env:USERPROFILE).TrimEnd('\', '/')
        foreach ($n in @('AppData', 'Downloads', 'Desktop', 'Documents', 'Pictures', 'Music', 'Videos')) { [void]$own.Add($up + $sep + $n) }
    }
    foreach ($f in @('Desktop', 'MyDocuments', 'MyPictures', 'MyMusic', 'MyVideos', 'ApplicationData', 'LocalApplicationData', 'CommonApplicationData')) {
        try { $p = [Environment]::GetFolderPath($f); if (-not [string]::IsNullOrEmpty($p)) { [void]$own.Add($p.TrimEnd('\', '/')) } } catch { }
    }
    foreach ($d in $own) {
        if ($d.Length -gt 3 -and $t.Equals($d, [StringComparison]::OrdinalIgnoreCase)) { return ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' klas' + [char]0x00F6 + 'rlerinin kendisi silinemez; i' + [char]0x00E7 + 'indeki dosyalar' + [char]0x0131 + ' ya da alt klas' + [char]0x00F6 + 'rleri se' + [char]0x00E7 + 'in.') }
    }
    # Multimizer'in calistigi klasor (ve onu iceren klasorler)
    $app = ''
    try { $app = ([string](Get-AppFolder)).TrimEnd('\', '/') } catch { $app = '' }
    if ($app.Length -gt 3) {
        if ($t.Equals($app, [StringComparison]::OrdinalIgnoreCase) -or $t.StartsWith($app + $sep, [StringComparison]::OrdinalIgnoreCase)) { return ('Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' klas' + [char]0x00F6 + 'r silinemez.') }
        if ($app.StartsWith($t + $sep, [StringComparison]::OrdinalIgnoreCase)) { return ('Bu klas' + [char]0x00F6 + 'r, Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' i' + [char]0x00E7 + 'eriyor; silinemez.') }
    }
    return ''
}

# ---------------- cozum merkezi: hazirlik denetimi ve kurulumu ----------------
# ==================================================================
#  COZUM MERKEZI: "Hazirlik" denetimi ve kurulumu (cekirdek)
#  Multimizer'in ve kullandigi araclarin ihtiyac duydugu bilesenleri okur (yalnizca okuma) ve eksik olanlarin kurulmasini saglar.
#  Kurulum yalnizca kullanici onaylarsa, yalnizca asagidaki izin listesindeki Microsoft paketleri icin ve winget'in kendi paket ozeti
#  (SHA-256) dogrulamasiyla yapilir. Bu bolum cekirdekte durur cunku denetim ve kurulum arka plan calisma alaninda calisir;
#  sekmenin cizimi 127_solve_prep.ps1 icindedir.
# ==================================================================

# Eklenti adlari (acilis kendi kendini sinama ve Hazirlik sekmesi ayni listeyi kullanir)
$script:MmExtNames = @('Sifreleme', 'Bellek', 'GuvenliSilme', 'WifiAktar', 'DiskKoruma', 'Kurtarma', 'DiskSilme', 'Parola')

# Kurulabilecek paketler: winget kimligi -> gorunen ad. Baska kimlik hicbir kosulda kurulmaz.
$script:PrepPackages = @{
    'Microsoft.VCRedist.2015+.x64'      = ('Visual C++ 2015-2022 ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + ' (x64)')
    'Microsoft.VCRedist.2015+.x86'      = ('Visual C++ 2015-2022 ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + ' (x86)')
    'Microsoft.VCRedist.2015+.arm64'    = ('Visual C++ 2015-2022 ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + ' (ARM64)')
    'Microsoft.DirectX'                 = ('DirectX eski ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + ' (D3DX9, XAudio, XInput)')
    'Microsoft.DotNet.DesktopRuntime.10' = ('.NET 10 Masa' + [char]0x00FC + 'st' + [char]0x00FC + ' ' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma Zaman' + [char]0x0131 + '')
}

# '' = bu paket kurulabilir, aksi halde nedeni
function Test-PrepPackage([string]$Id) {
    if ($Id -cnotmatch '^[A-Za-z0-9][A-Za-z0-9\.\-_\+]*$') { return (('Ge' + [char]0x00E7 + 'ersiz paket kimli' + [char]0x011F + 'i: ') + $Id) }
    if (-not $script:PrepPackages.ContainsKey($Id)) { return ($Id + (' izin listesinde de' + [char]0x011F + 'il; kurulmad' + [char]0x0131 + '.')) }
    return ''
}

# winget cikis kodu -> sonuc. Ok: paket artik kurulu; Reboot: yeniden baslatma gerekiyor; Text: kisa aciklama
function Get-PrepWingetResult([int]$Code) {
    $r = @{ Ok = $false; Reboot = $false; Already = $false; Text = '' }
    switch ($Code) {
        0 { $r.Ok = $true; $r.Text = 'kuruldu' }
        3010 { $r.Ok = $true; $r.Reboot = $true; $r.Text = ('kuruldu, yeniden ba' + [char]0x015F + 'latma gerekiyor') }
        1641 { $r.Ok = $true; $r.Reboot = $true; $r.Text = ('kuruldu, yeniden ba' + [char]0x015F + 'latma gerekiyor') }
        -1978335189 { $r.Ok = $true; $r.Already = $true; $r.Text = 'zaten kurulu' }
        -1978335135 { $r.Ok = $true; $r.Already = $true; $r.Text = 'zaten kurulu' }
        -1978334963 { $r.Ok = $true; $r.Already = $true; $r.Text = 'zaten kurulu' }
        -1978335153 { $r.Ok = $true; $r.Already = $true; $r.Text = 'zaten kurulu' }
        -1978334967 { $r.Ok = $true; $r.Reboot = $true; $r.Text = ('kuruldu, yeniden ba' + [char]0x015F + 'latma gerekiyor') }
        -1978334965 { $r.Ok = $true; $r.Reboot = $true; $r.Text = ('kuruldu, yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') }
        -1978334966 { $r.Reboot = $true; $r.Text = ('' + [char]0x00F6 + 'nce bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n, sonra yeniden deneyin') }
        -1978335212 { $r.Text = ('winget deposunda bulunamad' + [char]0x0131 + '') }
        -1978335209 { $r.Text = ('winget deposunda bulunamad' + [char]0x0131 + '') }
        -1978335179 { $r.Text = ('winget deposunda bulunamad' + [char]0x0131 + '') }
        -1978335216 { $r.Text = 'bu bilgisayara uygun kurulum paketi yok' }
        -1978334957 { $r.Text = 'bu sistem desteklenmiyor' }
        -1978335215 { $r.Text = ('indirilen dosyan' + [char]0x0131 + 'n ' + [char]0x00F6 + 'zeti paketle uyu' + [char]0x015F + 'mad' + [char]0x0131 + '; g' + [char]0x00FC + 'venli' + [char]0x011F + 'iniz i' + [char]0x00E7 + 'in kurulmad' + [char]0x0131 + '') }
        default { $r.Text = ('winget ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$Code }
    }
    return $r
}

# .NET Framework Release anahtari -> surum adi ('' = 4.5'ten eski ya da bilinmiyor)
function Get-PrepNetName([int]$Release) {
    if ($Release -ge 533320) { return '4.8.1' }
    if ($Release -ge 528040) { return '4.8' }
    if ($Release -ge 461808) { return '4.7.2' }
    if ($Release -ge 461308) { return '4.7.1' }
    if ($Release -ge 460798) { return '4.7' }
    if ($Release -ge 394802) { return '4.6.2' }
    if ($Release -ge 394254) { return '4.6.1' }
    if ($Release -ge 393295) { return '4.6' }
    if ($Release -ge 379893) { return '4.5.2' }
    if ($Release -ge 378675) { return '4.5.1' }
    if ($Release -ge 378389) { return '4.5' }
    return ''
}

# Visual C++ 2015-2022 yeniden dagitilabilir paketi (kayit defterinden). Arch: x64 | x86 | arm64
function Get-PrepVcRuntime([string]$Arch) {
    $r = @{ Arch = $Arch; Installed = $false; Version = ''; Major = 0; Minor = 0; Build = 0 }
    $paths = @()
    if ($Arch -eq 'x64') { $paths = @('HKLM\SOFTWARE\Microsoft\VisualStudio\14.0\VC\Runtimes\x64') }
    elseif ($Arch -eq 'x86') { $paths = @('HKLM\SOFTWARE\WOW6432Node\Microsoft\VisualStudio\14.0\VC\Runtimes\x86', 'HKLM\SOFTWARE\Microsoft\VisualStudio\14.0\VC\Runtimes\x86') }
    elseif ($Arch -eq 'arm64') { $paths = @('HKLM\SOFTWARE\Microsoft\VisualStudio\14.0\VC\Runtimes\ARM64') }
    foreach ($p in $paths) {
        $inst = Get-RegValue $p 'Installed' $null
        if ($null -ne $inst -and [int]$inst -eq 1) {
            $r.Installed = $true
            $r.Version = [string](Get-RegValue $p 'Version' '')
            $r.Major = [int](Get-RegValue $p 'Major' 0)
            $r.Minor = [int](Get-RegValue $p 'Minor' 0)
            $r.Build = [int](Get-RegValue $p 'Bld' 0)
            break
        }
    }
    return $r
}

# Kurulu .NET (Core) Masaustu Calisma Zamani surumleri (kayit defterinden); dizi doner, "$x = Get-PrepDotnetDesktop" ile alin
function Get-PrepDotnetDesktop {
    $vers = New-Object System.Collections.ArrayList
    foreach ($key in @('HKLM:\SOFTWARE\dotnet\Setup\InstalledVersions\x64\sharedfx\Microsoft.WindowsDesktop.App', 'HKLM:\SOFTWARE\dotnet\Setup\InstalledVersions\arm64\sharedfx\Microsoft.WindowsDesktop.App', 'HKLM:\SOFTWARE\dotnet\Setup\InstalledVersions\x86\sharedfx\Microsoft.WindowsDesktop.App', 'HKLM:\SOFTWARE\WOW6432Node\dotnet\Setup\InstalledVersions\x86\sharedfx\Microsoft.WindowsDesktop.App')) {
        try {
            $p = Get-ItemProperty -LiteralPath $key -ErrorAction Stop
            foreach ($pr in $p.PSObject.Properties) {
                if ($pr.Name -match '^\d+\.\d+\.\d+' -and -not $vers.Contains([string]$pr.Name)) { [void]$vers.Add([string]$pr.Name) }
            }
        } catch { }
    }
    return , $vers.ToArray()
}

# Eski DirectX calisma zamani (D3DX9): x64 ve x86 kopyalari
function Get-PrepDirectX {
    $r = @{ Native = $false; X86 = $false; Is64 = [Environment]::Is64BitOperatingSystem }
    $w = [string]$env:SystemRoot
    if ($w -eq '') { return $r }
    $r.Native = [bool](Test-Path -LiteralPath (Join-Path $w 'System32\d3dx9_43.dll') -PathType Leaf)
    if ($r.Is64) { $r.X86 = [bool](Test-Path -LiteralPath (Join-Path $w 'SysWOW64\d3dx9_43.dll') -PathType Leaf) } else { $r.X86 = $r.Native }
    return $r
}

# C# derleyicisi (Add-Type buna dayanir; kurtarma ve silme motorlari derlenir)
function Get-PrepCsc {
    $r = @{ Found = $false; Path = '' }
    $w = [string]$env:SystemRoot
    if ($w -eq '') { return $r }
    foreach ($c in @((Join-Path $w 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'), (Join-Path $w 'Microsoft.NET\Framework\v4.0.30319\csc.exe'))) {
        if (Test-Path -LiteralPath $c -PathType Leaf) { $r.Found = $true; $r.Path = $c; break }
    }
    return $r
}

function Get-PrepSysDrive {
    $r = @{ Letter = ''; FreeGB = [double]0; SizeGB = [double]0 }
    try {
        $sd = [string]$env:SystemDrive
        if ($sd -eq '') { $sd = 'C:' }
        $di = New-Object System.IO.DriveInfo($sd)
        $r.Letter = $sd
        $r.FreeGB = [math]::Round([double]$di.AvailableFreeSpace / 1GB, 1)
        $r.SizeGB = [math]::Round([double]$di.TotalSize / 1GB, 1)
    } catch { }
    return $r
}

function Test-PrepWmi {
    try {
        $o = @(Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop)
        if ($o.Count -gt 0) { return @{ Ok = $true; Error = '' } }
        return @{ Ok = $false; Error = ('Sorgu sonu' + [char]0x00E7 + ' d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'rmedi.') }
    } catch { return @{ Ok = $false; Error = [string]$_.Exception.Message } }
}

# Klasore yazilabiliyor mu? Denemek icin kendi kucuk gecici dosyasini yazip siler.
function Test-PrepWritable([string]$Dir) {
    if ([string]::IsNullOrEmpty($Dir)) { return @{ Ok = $false; Error = ('Klas' + [char]0x00F6 + 'r bilinmiyor.') } }
    try {
        if (-not (Test-Path -LiteralPath $Dir)) { New-Item -ItemType Directory -Path $Dir -Force -ErrorAction Stop | Out-Null }
        $f = Join-Path $Dir ('yazma-denemesi-' + [guid]::NewGuid().ToString('N') + '.tmp')
        [System.IO.File]::WriteAllText($f, 'x')
        Remove-Item -LiteralPath $f -Force -ErrorAction Stop
        return @{ Ok = $true; Error = '' }
    } catch { return @{ Ok = $false; Error = [string]$_.Exception.Message } }
}

# Sistem Korumasi (geri yukleme noktalari) sistem surucusunde acik mi? Known = $false: okunamadi.
function Get-PrepProtect([string]$Drive) {
    $r = @{ Known = $false; On = $false; Policy = $false }
    try {
        $dis = Get-RegValue 'HKLM\SOFTWARE\Policies\Microsoft\Windows NT\SystemRestore' 'DisableSR' $null
        if ($null -ne $dis -and [int]$dis -eq 1) { $r.Known = $true; $r.Policy = $true; return $r }
        $v = Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SPP\Clients' '{09F7EDC5-294E-4180-AF6A-FB0E6A0E9513}' $null
        $r.Known = $true
        if ($null -ne $v -and $Drive -cmatch '^([A-Za-z]):') {
            $tag = '(' + $Matches[1].ToUpperInvariant() + '%3A)'
            foreach ($x in @($v)) { if (([string]$x).ToUpperInvariant().Contains($tag)) { $r.On = $true } }
        }
    } catch { $r.Known = $false }
    return $r
}

# Bilgisayari okur (yalnizca okuma). Her bolum ayri korunur; bir okuma basarisiz olursa o bolum bos kalir.
# NoNet: internet baglantisi sinanmaz (aga hic cikilmaz); Online bos kalir ve baglanti satiri gosterilmez.
function Get-PrepState([bool]$NoNet = $false) {
    $admin = $false
    try { $admin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } catch { }
    $S = @{ Ok = $true; At = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Admin = $admin
        Ps = @{ Version = ''; Major = 0; Minor = 0; Edition = '' }
        Os = @{ Name = ''; Build = 0; Display = ''; Is64 = [Environment]::Is64BitOperatingSystem; Arm = $false }
        Net = @{ Release = 0; Name = '' }
        Csc = @{ Found = $false; Path = '' }
        Vc = @{ X64 = $null; X86 = $null; Arm64 = $null }
        Dx = $null; Dotnet = @()
        Winget = @{ Path = ''; Version = '' }
        Wmi = @{ Ok = $true; Error = '' }
        Disk = @{ Letter = ''; FreeGB = [double]0; SizeGB = [double]0 }
        Online = $null
        Data = @{ Path = ''; Ok = $true; Error = '' }
        Exts = @()
        Protect = @{ Known = $false; On = $false; Policy = $false } }

    try {
        $pv = $PSVersionTable.PSVersion
        $S.Ps.Version = [string]$pv
        $S.Ps.Major = [int]$pv.Major
        $S.Ps.Minor = [int]$pv.Minor
        $S.Ps.Edition = [string]$PSVersionTable.PSEdition
    } catch { }
    try {
        $k = 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
        $S.Os.Build = [int](Get-RegValue $k 'CurrentBuildNumber' 0)
        $S.Os.Display = [string](Get-RegValue $k 'DisplayVersion' '')
        if ($S.Os.Build -ge 22000) { $S.Os.Name = 'Windows 11' } elseif ($S.Os.Build -gt 0) { $S.Os.Name = 'Windows 10' }
        $arch = [string]$env:PROCESSOR_ARCHITEW6432
        if ($arch -eq '') { $arch = [string]$env:PROCESSOR_ARCHITECTURE }
        $S.Os.Arm = ($arch -match '^ARM')
    } catch { }
    try {
        $S.Net.Release = [int](Get-RegValue 'HKLM\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' 'Release' 0)
        $S.Net.Name = Get-PrepNetName $S.Net.Release
    } catch { }
    try { $S.Csc = Get-PrepCsc } catch { }
    try {
        $S.Vc.X64 = Get-PrepVcRuntime 'x64'
        $S.Vc.X86 = Get-PrepVcRuntime 'x86'
        if ($S.Os.Arm) { $S.Vc.Arm64 = Get-PrepVcRuntime 'arm64' }
    } catch { }
    try { $S.Dx = Get-PrepDirectX } catch { }
    try { $S.Dotnet = Get-PrepDotnetDesktop } catch { }
    try {
        $wg = Get-WingetPath
        $S.Winget.Path = [string]$wg
        if ($wg -ne '') {
            $o = @(& $wg '--version' 2>&1 | ForEach-Object { [string]$_ })
            if ($o.Count -gt 0) { $S.Winget.Version = ([string]$o[0]).Trim() }
        }
    } catch { }
    try { $S.Wmi = Test-PrepWmi } catch { }
    try { $S.Disk = Get-PrepSysDrive } catch { }
    if (-not $NoNet) { try { $S.Online = [bool](Test-Online) } catch { } }
    try {
        $dd = ''
        try { $dd = [string]$sync.DataDir } catch { }
        $S.Data.Path = $dd
        $w = Test-PrepWritable $dd
        $S.Data.Ok = [bool]$w.Ok
        $S.Data.Error = [string]$w.Error
    } catch { }
    try {
        $ex = New-Object System.Collections.ArrayList
        foreach ($n in @($script:MmExtNames)) { [void]$ex.Add(@{ Name = [string]$n; Problem = [string](Get-ExtProblem ([string]$n)) }) }
        $S.Exts = $ex.ToArray()
    } catch { }
    try { $S.Protect = Get-PrepProtect ([string]$S.Disk.Letter) } catch { }
    return $S
}

function Job_PrepCheck($P) {
    try {
        $nn = $false
        try { if ($null -ne $P -and $P.ContainsKey('NoNet')) { $nn = ($P['NoNet'] -eq $true) } } catch { }
        if ($nn) { Write-WhLog ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k denetimi yap' + [char]0x0131 + 'l' + [char]0x0131 + 'yor (yaln' + [char]0x0131 + 'zca okuma; a' + [char]0x011F + 'a ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'lmaz)...') 'INFO' }
        else { Write-WhLog ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k denetimi yap' + [char]0x0131 + 'l' + [char]0x0131 + 'yor (yaln' + [char]0x0131 + 'zca okuma)...') 'INFO' }
        return @{ Ok = $true; State = (Get-PrepState $nn) }
    } catch {
        Write-WhLog (('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k denetimi yap' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false; Error = $_.Exception.Message }
    }
}

# ---------------- yorumlama (saf mantik) ----------------
function New-PrepItem([string]$Key, [string]$Group, [string]$Status, [string]$Title, [string]$Detail, $Fix = $null) {
    return @{ Key = $Key; Group = $Group; Status = $Status; Title = $Title; Detail = $Detail; Fix = $Fix }
}

function New-PrepFix([string]$Do, [string]$Label, $Extra = $null) {
    $f = @{ Do = $Do; Label = $Label }
    if ($null -ne $Extra) { foreach ($k in @($Extra.Keys)) { $f[$k] = $Extra[$k] } }
    return $f
}

# Visual C++ satiri: yuklu degil ya da eski ise kurulum dugmesi
function Get-PrepVcItem($Vc, [string]$Arch, [string]$Id, [string]$Label) {
    $title = ('Visual C++ ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + ' (') + $Label + ')'
    $fix = New-PrepFix 'Winget' 'Kur' @{ Id = $Id; Name = [string]$script:PrepPackages[$Id] }
    if ($null -eq $Vc -or $Vc.Installed -ne $true) {
        return (New-PrepItem ('vc' + $Arch) 'rec' 'warn' $title ('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' de' + [char]0x011F + 'il. Bir' + [char]0x00E7 + 'ok program ve Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n kurdu' + [char]0x011F + 'u baz' + [char]0x0131 + ' ara' + [char]0x00E7 + 'lar bu paketi ister; yoksa ' + [char]0x201C + 'VCRUNTIME140.dll bulunamad' + [char]0x0131 + '' + [char]0x201D + ' gibi hatalar ' + [char]0x00E7 + '' + [char]0x0131 + 'kar.') $fix)
    }
    $ver = [string]$Vc.Version
    if ($ver -eq '') { $ver = [string]$Vc.Major + '.' + [string]$Vc.Minor }
    if ([int]$Vc.Major -eq 14 -and [int]$Vc.Minor -lt 30) {
        return (New-PrepItem ('vc' + $Arch) 'rec' 'warn' $title (('Eski s' + [char]0x00FC + 'r' + [char]0x00FC + 'm kurulu (') + $ver + ('). Yeni programlar 2019 sonras' + [char]0x0131 + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' ister; g' + [char]0x00FC + 'ncelleyin.')) $fix)
    }
    return (New-PrepItem ('vc' + $Arch) 'rec' 'ok' $title ('Kurulu (' + $ver + ').'))
}

# Tarama sonucundan satirlar: @( @{ Key; Group (req | rec | opt); Status (ok | info | warn | bad); Title; Detail; Fix } ).
# Fix: $null ya da @{ Do = Winget | Url | Page | Wmi; Label; ... }
function Get-PrepItems($S, [bool]$Expert = $false) {
    $n = New-Object System.Collections.ArrayList
    $os64 = ($S.Os.Is64 -eq $true)

    # ---- zorunlu
    $psv = [string]$S.Ps.Version
    if ($psv -eq '') { $psv = [string]$S.Ps.Major + '.' + [string]$S.Ps.Minor }
    if ([int]$S.Ps.Major -gt 5 -or ([int]$S.Ps.Major -eq 5 -and [int]$S.Ps.Minor -ge 1)) {
        [void]$n.Add((New-PrepItem 'ps' 'req' 'ok' 'Windows PowerShell 5.1' (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm ') + $psv + ('. Multimizer bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mle ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.'))))
    } else {
        [void]$n.Add((New-PrepItem 'ps' 'req' 'bad' 'Windows PowerShell 5.1' (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm ') + $psv + (' bulundu; Multimizer Windows PowerShell 5.1 ister. Windows 10 ve 11' + [char]0x2019 + 'de yerle' + [char]0x015F + 'iktir; eski sistemde ' + [char]0x201C + 'Windows Management Framework 5.1' + [char]0x201D + ' kurulmal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.'))))
    }

    $rel = [int]$S.Net.Release
    $nn = [string]$S.Net.Name
    $wu = New-PrepFix 'Url' ('Windows Update' + [char]0x2019 + 'i a' + [char]0x00E7 + '') @{ Url = 'ms-settings:windowsupdate' }
    if ($rel -ge 461808) {
        [void]$n.Add((New-PrepItem 'net' 'req' 'ok' '.NET Framework' (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm ') + $nn + (' kurulu. Aray' + [char]0x00FC + 'z (WPF) ve motorlar' + [char]0x0131 + 'n derlenmesi i' + [char]0x00E7 + 'in gerekli s' + [char]0x00FC + 'r' + [char]0x00FC + 'm var.'))))
    } elseif ($rel -ge 379893) {
        [void]$n.Add((New-PrepItem 'net' 'req' 'warn' '.NET Framework' (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm ') + $nn + (' kurulu; 4.7.2 ve ' + [char]0x00FC + 'zeri ' + [char]0x00F6 + 'nerilir. Windows Update ile g' + [char]0x00FC + 'ncellenir.')) $wu))
    } else {
        $cur = ('Okunamad' + [char]0x0131 + '')
        if ($nn -ne '') { $cur = $nn }
        [void]$n.Add((New-PrepItem 'net' 'req' 'bad' '.NET Framework' (('Gerekli s' + [char]0x00FC + 'r' + [char]0x00FC + 'm bulunamad' + [char]0x0131 + ' (' + [char]0x015F + 'u an: ') + $cur + ('). En az 4.5.2, ' + [char]0x00F6 + 'nerilen 4.7.2 ve ' + [char]0x00FC + 'zeri. Windows Update ile kurulur.')) $wu))
    }

    if ($S.Csc.Found -eq $true) {
        [void]$n.Add((New-PrepItem 'csc' 'req' 'ok' 'C# derleyicisi' ('Bulundu. Silinen dosya kurtarma ve kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silme motorlar' + [char]0x0131 + ' ilk kullan' + [char]0x0131 + 'mda bununla derlenir.')))
    } else {
        [void]$n.Add((New-PrepItem 'csc' 'req' 'bad' 'C# derleyicisi' ('csc.exe bulunamad' + [char]0x0131 + '; kurtarma ve kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silme motorlar' + [char]0x0131 + ' derlenemez. .NET Framework onar' + [char]0x0131 + 'm' + [char]0x0131 + ' i' + [char]0x00E7 + 'in Windows Update' + [char]0x2019 + 'i ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n.') $wu))
    }

    if ($S.Wmi.Ok -eq $true) {
        [void]$n.Add((New-PrepItem 'wmi' 'req' 'ok' ('WMI (CIM) sorgular' + [char]0x0131 + '') ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor. Bilgisayar tan' + [char]0x0131 + 'ma ve bir' + [char]0x00E7 + 'ok denetim buna dayan' + [char]0x0131 + 'r.')))
    } else {
        $we = [string]$S.Wmi.Error
        if ($we.Length -gt 160) { $we = $we.Substring(0, 157) + '...' }
        [void]$n.Add((New-PrepItem 'wmi' 'req' 'bad' ('WMI (CIM) sorgular' + [char]0x0131 + '') (('Sorgu ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $we + (' WMI deposu bozulmu' + [char]0x015F + ' olabilir; bir' + [char]0x00E7 + 'ok denetim ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'maz. Do' + [char]0x011F + 'rulama ve onar' + [char]0x0131 + 'm Microsoft' + [char]0x2019 + 'un kendi winmgmt arac' + [char]0x0131 + 'yla yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r.')) (New-PrepFix 'Wmi' ('Do' + [char]0x011F + 'rula ve onar'))))
    }

    $bld = [int]$S.Os.Build
    $osn = [string]$S.Os.Name
    if ($osn -eq '') { $osn = 'Windows' }
    $osd = $osn
    if ([string]$S.Os.Display -ne '') { $osd += ' ' + [string]$S.Os.Display }
    if ($bld -gt 0) { $osd += ' (derleme ' + [string]$bld + ')' }
    if ($bld -ge 19041) {
        [void]$n.Add((New-PrepItem 'os' 'req' 'ok' ('Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + '') ($osd + ('. Desteklenen bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'm.'))))
    } elseif ($bld -ge 10240) {
        [void]$n.Add((New-PrepItem 'os' 'req' 'warn' ('Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + '') ($osd + ('. Eski s' + [char]0x00FC + 'r' + [char]0x00FC + 'm; baz' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellikler ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mayabilir. Windows Update ile g' + [char]0x00FC + 'ncelleyin.')) $wu))
    } elseif ($bld -gt 0) {
        [void]$n.Add((New-PrepItem 'os' 'req' 'bad' ('Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + '') ($osd + ('. Multimizer Windows 10 ve 11 i' + [char]0x00E7 + 'indir.'))))
    } else {
        [void]$n.Add((New-PrepItem 'os' 'req' 'info' ('Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + '') ('Okunamad' + [char]0x0131 + '.')))
    }

    $bad = @($S.Exts | Where-Object { [string]$_.Problem -ne '' })
    if (@($S.Exts).Count -eq 0) {
        [void]$n.Add((New-PrepItem 'ext' 'req' 'info' 'Multimizer eklentileri' 'Denetlenemedi.'))
    } elseif ($bad.Count -eq 0) {
        [void]$n.Add((New-PrepItem 'ext' 'req' 'ok' 'Multimizer eklentileri' ([string]@($S.Exts).Count + (' eklentinin hepsi yerinde ve ' + [char]0x00F6 + 'zetleri do' + [char]0x011F + 'ru (kurtarma, silme, ' + [char]0x015F + 'ifreleme, bellek, Wi-Fi ve disk koruma).'))))
    } else {
        $names = (@($bad | ForEach-Object { [string]$_.Name }) -join ', ')
        [void]$n.Add((New-PrepItem 'ext' 'req' 'bad' 'Multimizer eklentileri' ([string]$bad.Count + (' eklenti eksik ya da de' + [char]0x011F + 'i' + [char]0x015F + 'mi' + [char]0x015F + ': ') + $names + ('. ZIP dosyas' + [char]0x0131 + 'n' + [char]0x0131 + 'n tamam' + [char]0x0131 + 'n' + [char]0x0131 + ' yeni bir klas' + [char]0x00F6 + 're ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'p Baslat.bat' + [char]0x2019 + '' + [char]0x0131 + ' oradan ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n. ') + [string]$bad[0].Problem)))
    }

    if ($S.Data.Ok -eq $true) {
        [void]$n.Add((New-PrepItem 'data' 'req' 'ok' ('Veri klas' + [char]0x00F6 + 'r' + [char]0x00FC + '') (('Yaz' + [char]0x0131 + 'labiliyor (') + [string]$S.Data.Path + ('). Ayarlar, g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kler ve yedekler burada tutulur.'))))
    } else {
        [void]$n.Add((New-PrepItem 'data' 'req' 'bad' ('Veri klas' + [char]0x00F6 + 'r' + [char]0x00FC + '') (('Yaz' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor (') + [string]$S.Data.Path + '): ' + [string]$S.Data.Error + (' Ayarlar ve g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kler kaydedilemez.'))))
    }

    # ---- onerilen
    if ($S.Admin -eq $true) {
        [void]$n.Add((New-PrepItem 'admin' 'rec' 'ok' ('Y' + [char]0x00F6 + 'netici haklar' + [char]0x0131 + '') ('Var. Disk, g' + [char]0x00FC + 'venlik ve sistem i' + [char]0x015F + 'lemleri yap' + [char]0x0131 + 'labilir.')))
    } else {
        [void]$n.Add((New-PrepItem 'admin' 'rec' 'warn' ('Y' + [char]0x00F6 + 'netici haklar' + [char]0x0131 + '') ('Yok. Disk, g' + [char]0x00FC + 'venlik ve sistem i' + [char]0x015F + 'lemleri i' + [char]0x00E7 + 'in gerekir; Multimizer' + [char]0x2019 + '' + [char]0x0131 + ' Baslat.bat ile a' + [char]0x00E7 + '' + [char]0x0131 + 'n, izin penceresinde ' + [char]0x201C + 'Evet' + [char]0x201D + ' deyin.')))
    }

    $fg = [double]$S.Disk.FreeGB
    $sg = [double]$S.Disk.SizeGB
    $dl = [string]$S.Disk.Letter
    if ($sg -gt 0) {
        $pc = [int][math]::Round($fg * 100.0 / $sg)
        $txt = $dl + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde ') + (Format-PcGb $fg) + (' bo' + [char]0x015F + ' (%') + [string]$pc + ').'
        $clean = New-PrepFix 'Page' 'Temizlik' @{ Page = 'clean'; Sub = '' }
        if ($fg -lt 2) { [void]$n.Add((New-PrepItem 'space' 'rec' 'bad' ('Sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde bo' + [char]0x015F + ' alan') ($txt + (' Windows g' + [char]0x00FC + 'ncellemeleri ve geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yer yok; ' + [char]0x00F6 + 'nce yer a' + [char]0x00E7 + '' + [char]0x0131 + 'n.')) $clean)) }
        elseif ($fg -lt 10 -or $pc -lt 8) { [void]$n.Add((New-PrepItem 'space' 'rec' 'warn' ('Sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde bo' + [char]0x015F + ' alan') ($txt + (' G' + [char]0x00FC + 'ncellemeler, sanal bellek ve geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ' i' + [char]0x00E7 + 'in en az 10 GB ' + [char]0x00F6 + 'nerilir.')) $clean)) }
        else { [void]$n.Add((New-PrepItem 'space' 'rec' 'ok' ('Sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde bo' + [char]0x015F + ' alan') $txt)) }
    } else {
        [void]$n.Add((New-PrepItem 'space' 'rec' 'info' ('Sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde bo' + [char]0x015F + ' alan') ('Okunamad' + [char]0x0131 + '.')))
    }

    if ([string]$S.Winget.Path -ne '') {
        $wv = ''
        if ([string]$S.Winget.Version -ne '') { $wv = ' (' + [string]$S.Winget.Version + ')' }
        [void]$n.Add((New-PrepItem 'winget' 'rec' 'ok' ('winget (Uygulama Y' + [char]0x00FC + 'kleyicisi)') ('Kurulu' + $wv + ('. Eksik bile' + [char]0x015F + 'enler ve ara' + [char]0x00E7 + 'lar Microsoft' + [char]0x2019 + 'un bu arac' + [char]0x0131 + 'yla, paket ' + [char]0x00F6 + 'zeti do' + [char]0x011F + 'rulanarak kurulur.'))))
    } else {
        [void]$n.Add((New-PrepItem 'winget' 'rec' 'warn' ('winget (Uygulama Y' + [char]0x00FC + 'kleyicisi)') ('Bulunamad' + [char]0x0131 + '. Bile' + [char]0x015F + 'en ve ara' + [char]0x00E7 + ' kurulumlar' + [char]0x0131 + ' buna dayan' + [char]0x0131 + 'r. Microsoft Store' + [char]0x2019 + 'daki ' + [char]0x201C + 'Uygulama Y' + [char]0x00FC + 'kleyicisi' + [char]0x201D + 'ni (App Installer) y' + [char]0x00FC + 'kleyin, sonra Denetle' + [char]0x2019 + 'ye bas' + [char]0x0131 + 'n.') (New-PrepFix 'Url' ('Store' + [char]0x2019 + 'da a' + [char]0x00E7 + '') @{ Url = 'ms-windows-store://pdp/?ProductId=9NBLGGH4NNS1' })))
    }

    [void]$n.Add((Get-PrepVcItem $S.Vc.X64 'x64' 'Microsoft.VCRedist.2015+.x64' 'x64'))
    if ($os64) { [void]$n.Add((Get-PrepVcItem $S.Vc.X86 'x86' 'Microsoft.VCRedist.2015+.x86' 'x86')) }
    if ($S.Os.Arm -eq $true -and $null -ne $S.Vc.Arm64) { [void]$n.Add((Get-PrepVcItem $S.Vc.Arm64 'arm64' 'Microsoft.VCRedist.2015+.arm64' 'ARM64')) }

    $pt = $S.Protect
    if ($pt.Policy -eq $true) {
        [void]$n.Add((New-PrepItem 'restore' 'rec' 'warn' ('Sistem Korumas' + [char]0x0131 + ' (geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ')') ('Bir ilke taraf' + [char]0x0131 + 'ndan kapat' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + '. Multimizer de' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerden ' + [char]0x00F6 + 'nce geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' alamaz; i' + [char]0x015F + 'lemler yine de ' + [char]0x00F6 + 'nizlenir ve ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'ten geri al' + [char]0x0131 + 'nabilir.')))
    } elseif ($pt.Known -eq $true -and $pt.On -eq $true) {
        [void]$n.Add((New-PrepItem 'restore' 'rec' 'ok' ('Sistem Korumas' + [char]0x0131 + ' (geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ')') ($dl + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde a' + [char]0x00E7 + '' + [char]0x0131 + 'k. B' + [char]0x00FC + 'y' + [char]0x00FC + 'k de' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerden ' + [char]0x00F6 + 'nce geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.'))))
    } elseif ($pt.Known -eq $true) {
        [void]$n.Add((New-PrepItem 'restore' 'rec' 'info' ('Sistem Korumas' + [char]0x0131 + ' (geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ')') ('Kapal' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor. Multimizer, geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' almas' + [char]0x0131 + ' gerekti' + [char]0x011F + 'inde bunu sizin i' + [char]0x00E7 + 'in a' + [char]0x00E7 + 'ar; Ayarlar' + [char]0x2019 + 'dan geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + 'n' + [char]0x0131 + ' kapatmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z s' + [char]0x00FC + 'rece ek bir ' + [char]0x015F + 'ey yapman' + [char]0x0131 + 'z gerekmez.')))
    } else {
        [void]$n.Add((New-PrepItem 'restore' 'rec' 'info' ('Sistem Korumas' + [char]0x0131 + ' (geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + ')') ('Durumu okunamad' + [char]0x0131 + '.')))
    }

    if ($S.Online -eq $true) {
        [void]$n.Add((New-PrepItem 'online' 'rec' 'ok' ('' + [char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + '') ('Var. Bile' + [char]0x015F + 'en indirme ve g' + [char]0x00FC + 'ncelleme denetimi yap' + [char]0x0131 + 'labilir.')))
    } elseif ($S.Online -eq $false) {
        [void]$n.Add((New-PrepItem 'online' 'rec' 'info' ('' + [char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + '') ('Yok ya da engelli g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor. Bile' + [char]0x015F + 'en kurulumlar' + [char]0x0131 + ' ve g' + [char]0x00FC + 'ncelleme denetimi i' + [char]0x00E7 + 'in gerekir; Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n di' + [char]0x011F + 'er ' + [char]0x00F6 + 'zellikleri ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + 'z ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.')))
    }

    # ---- istege bagli
    $dx = $S.Dx
    $dxFix = New-PrepFix 'Winget' 'Kur' @{ Id = 'Microsoft.DirectX'; Name = [string]$script:PrepPackages['Microsoft.DirectX'] }
    if ($null -ne $dx) {
        if ($dx.Native -eq $true -and $dx.X86 -eq $true) {
            [void]$n.Add((New-PrepItem 'dx' 'opt' 'ok' ('DirectX eski ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + '') ('D3DX9 dosyalar' + [char]0x0131 + ' kurulu. Eski oyun ve programlar i' + [char]0x00E7 + 'in yeterli.')))
        } else {
            [void]$n.Add((New-PrepItem 'dx' 'opt' 'info' ('DirectX eski ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zaman' + [char]0x0131 + '') ('D3DX9 dosyalar' + [char]0x0131 + ' yok. Yaln' + [char]0x0131 + 'zca eski oyunlar ve eski programlar ' + [char]0x201C + 'd3dx9_43.dll bulunamad' + [char]0x0131 + '' + [char]0x201D + ' hatas' + [char]0x0131 + ' verirse gerekir; Multimizer i' + [char]0x00E7 + 'in gerekmez.') $dxFix))
        }
    }

    $dv = @($S.Dotnet)
    $hi = ''
    foreach ($v in $dv) {
        $mj = 0
        if (([string]$v) -match '^(\d+)\.') { $mj = [int]$Matches[1] }
        if ($mj -ge 8) { $hi = [string]$v }
    }
    if ($hi -ne '') {
        [void]$n.Add((New-PrepItem 'dotnet' 'opt' 'ok' ('.NET Masa' + [char]0x00FC + 'st' + [char]0x00FC + ' ' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma Zaman' + [char]0x0131 + '') ('Kurulu (' + $hi + ('). Yeni .NET ile yaz' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' programlar ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.'))))
    } else {
        [void]$n.Add((New-PrepItem 'dotnet' 'opt' 'info' ('.NET Masa' + [char]0x00FC + 'st' + [char]0x00FC + ' ' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma Zaman' + [char]0x0131 + '') ('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' de' + [char]0x011F + 'il. Yeni .NET ile yaz' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' baz' + [char]0x0131 + ' programlar (' + [char]0x00F6 + 'r. donan' + [char]0x0131 + 'm izleme ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ') bunu ister; Multimizer i' + [char]0x00E7 + 'in gerekmez.') (New-PrepFix 'Winget' 'Kur' @{ Id = 'Microsoft.DotNet.DesktopRuntime.10'; Name = [string]$script:PrepPackages['Microsoft.DotNet.DesktopRuntime.10'] })))
    }

    # Uzman kipi: ham degerler
    if ($Expert) {
        $ex = @{}
        $ex['ps'] = ('T' + [char]0x00FC + 'r: ') + [string]$S.Ps.Edition + '.'
        if ($rel -gt 0) { $ex['net'] = ('Release anahtar' + [char]0x0131 + ': ') + [string]$rel + '.' }
        if ($S.Csc.Found -eq $true) { $ex['csc'] = 'Yol: ' + [string]$S.Csc.Path }
        if ([string]$S.Winget.Path -ne '') { $ex['winget'] = 'Yol: ' + [string]$S.Winget.Path }
        if ($null -ne $S.Vc.X64 -and $S.Vc.X64.Installed -eq $true) { $ex['vcx64'] = 'Derleme: ' + [string]$S.Vc.X64.Build + '.' }
        if ($dv.Count -gt 0) { $ex['dotnet'] = ('Bulunan s' + [char]0x00FC + 'r' + [char]0x00FC + 'mler: ') + ($dv -join ', ') + '.' }
        if ([string]$S.Data.Path -ne '') { $ex['data'] = 'Yol: ' + [string]$S.Data.Path }
        foreach ($it in $n) {
            if ($ex.ContainsKey([string]$it.Key)) { $it.Detail = [string]$it.Detail + '  ' + [string]$ex[[string]$it.Key] }
        }
    }
    return , $n.ToArray()
}

# Ozet: @{ Bad; Warn; Info; Ok; Total; Level (good | warn | bad); Text }
function Get-PrepSummary($Items) {
    $b = 0; $w = 0; $i = 0; $o = 0
    foreach ($x in @($Items)) {
        switch ([string]$x.Status) { 'bad' { $b++ } 'warn' { $w++ } 'info' { $i++ } default { $o++ } }
    }
    $total = $b + $w + $i + $o
    $lvl = 'good'
    $txt = ('Her ' + [char]0x015F + 'ey haz' + [char]0x0131 + 'r: ') + [string]$total + ' denetimin hepsi uygun.'
    if ($b -gt 0) { $lvl = 'bad'; $txt = [string]$b + (' zorunlu ya da ' + [char]0x00F6 + 'nemli eksik var') ; if ($w -gt 0) { $txt += ', ' + [string]$w + (' ' + [char]0x00F6 + 'neri') }; $txt += ('. ' + [char]0x00D6 + 'nce k' + [char]0x0131 + 'rm' + [char]0x0131 + 'z' + [char]0x0131 + ' sat' + [char]0x0131 + 'rlara bak' + [char]0x0131 + 'n.') }
    elseif ($w -gt 0) { $lvl = 'warn'; $txt = ('Multimizer ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r; ') + [string]$w + (' ' + [char]0x00F6 + 'nerilen bile' + [char]0x015F + 'en eksik ya da eski.') }
    elseif ($i -gt 0) { $txt = ('Her ' + [char]0x015F + 'ey haz' + [char]0x0131 + 'r; ') + [string]$i + (' iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' bile' + [char]0x015F + 'en kurulabilir.') }
    return @{ Bad = $b; Warn = $w; Info = $i; Ok = $o; Total = $total; Level = $lvl; Text = $txt }
}

# "Eksikleri gider" icin kurulacak paketler: @( @{ Key; Id; Name } ). Keys bossa tum uygun satirlar; ok olanlar ve tekrarlayan kimlikler atlanir.
function Get-PrepInstallList($Items, $Keys = $null) {
    $out = New-Object System.Collections.ArrayList
    $seen = @{}
    $want = @()
    if ($null -ne $Keys) { $want = @($Keys | ForEach-Object { [string]$_ }) }
    foreach ($x in @($Items)) {
        if ($null -eq $x.Fix -or [string]$x.Fix.Do -ne 'Winget') { continue }
        if ([string]$x.Status -eq 'ok') { continue }
        if ($want.Count -gt 0 -and $want -notcontains [string]$x.Key) { continue }
        $id = [string]$x.Fix.Id
        if ($seen.ContainsKey($id.ToLowerInvariant())) { continue }
        $seen[$id.ToLowerInvariant()] = $true
        [void]$out.Add(@{ Key = [string]$x.Key; Id = $id; Name = [string]$x.Fix.Name })
    }
    return , $out.ToArray()
}

# ---------------- kurulum ve onarim (onayli) ----------------
# P: Ids (izin listesindeki winget kimlikleri). Kurulumlar sirayla yapilir; her paketin sonucu ayri bildirilir.
function Job_PrepInstall($P) {
    $ids = New-Object System.Collections.ArrayList
    foreach ($x in @($P.Ids)) { $s = [string]$x; if ($s -ne '' -and -not $ids.Contains($s)) { [void]$ids.Add($s) } }
    $out = @{ Ok = $false; Items = @(); Reboot = $false; Done = 0; Failed = 0; Canceled = $false; Error = '' }
    if ($ids.Count -eq 0) { $out.Error = ('Kurulacak bile' + [char]0x015F + 'en se' + [char]0x00E7 + 'ilmedi.'); return $out }
    if ((Get-WingetPath) -eq '') {
        $out.Error = ('winget bulunamad' + [char]0x0131 + '. Microsoft Store' + [char]0x2019 + 'dan ' + [char]0x201C + 'Uygulama Y' + [char]0x00FC + 'kleyicisi' + [char]0x201D + 'ni (App Installer) y' + [char]0x00FC + 'kleyin.')
        Write-WhLog $out.Error 'ERR'
        return $out
    }
    Reset-Counters
    Set-JobProgress 0 $ids.Count ('Bile' + [char]0x015F + 'enler kuruluyor')
    $items = New-Object System.Collections.ArrayList
    foreach ($id in $ids) {
        if (Test-JobCancel) { $out.Canceled = $true; Write-WhLog ('' + [char]0x0130 + 'ptal edildi.') 'WARN'; break }
        $chk = Test-PrepPackage $id
        if ($chk -ne '') {
            Add-Err $chk
            [void]$items.Add(@{ Id = $id; Ok = $false; Code = 0; Text = $chk })
            $out.Failed++
            Step-JobProgress
            continue
        }
        Write-WhLog ('=== Kuruluyor: ' + $id + (' (winget deposu; paket ' + [char]0x00F6 + 'zeti winget taraf' + [char]0x0131 + 'ndan do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r)')) 'STEP'
        $code = -1
        try {
            $r = Invoke-WingetRaw @('install', '--id', $id, '--exact', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity')
            Write-WingetLines $r.Lines
            $code = [int]$r.Code
        } catch { Write-WhLog ($id + ': ' + $_.Exception.Message) 'ERR' }
        $res = Get-PrepWingetResult $code
        if ($res.Ok -eq $true) { Add-Done ($id + ': ' + $res.Text); $out.Done++ } else { Add-Err ($id + ': ' + $res.Text); $out.Failed++ }
        if ($res.Reboot -eq $true) { $out.Reboot = $true }
        [void]$items.Add(@{ Id = $id; Ok = ($res.Ok -eq $true); Code = $code; Text = [string]$res.Text })
        Step-JobProgress
    }
    $out.Items = $items.ToArray()
    $out.Ok = ($out.Failed -eq 0 -and $out.Canceled -ne $true -and $out.Done -gt 0)
    if ($out.Failed -gt 0 -and $out.Done -eq 0 -and [string]$out.Error -eq '') { $out.Error = [string]$items[0].Text }
    Write-WhLog (('Kurulan bile' + [char]0x015F + 'en: ') + [string]$out.Done + ' / ' + [string]$ids.Count) 'INFO'
    return $out
}

# WMI deposunu dogrular; tutarsizsa Microsoft'un winmgmt araciyla onarir (kayitli veriyi korur). Donus: @{ Ok; Verified; Salvaged; Text }
function Invoke-PrepWmiRepair {
    $r = @{ Ok = $false; Verified = $false; Salvaged = $false; Text = '' }
    $o = @(& winmgmt.exe /verifyrepository 2>&1 | ForEach-Object { [string]$_ })
    $code = [int]$LASTEXITCODE
    $txt = ($o -join ' ').Trim()
    if ($txt -ne '') { Write-WhLog ('winmgmt /verifyrepository: ' + $txt) 'INFO' }
    $incons = ($txt -match ('(?i)inconsistent|not consistent|tutars[' + [char]0x0131 + 'i]z|tutarl[' + [char]0x0131 + 'i]\s+de[' + [char]0x011F + 'g]il'))
    if ($code -eq 0 -and -not $incons) { $r.Ok = $true; $r.Verified = $true; $r.Text = ('WMI deposu tutarl' + [char]0x0131 + '; onar' + [char]0x0131 + 'm gerekmedi.'); return $r }
    Write-WhLog ('WMI deposu tutars' + [char]0x0131 + 'z g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor; winmgmt /salvagerepository ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor...') 'WARN'
    $o2 = @(& winmgmt.exe /salvagerepository 2>&1 | ForEach-Object { [string]$_ })
    $c2 = [int]$LASTEXITCODE
    $t2 = ($o2 -join ' ').Trim()
    if ($t2 -ne '') { Write-WhLog ('winmgmt /salvagerepository: ' + $t2) 'INFO' }
    $r.Salvaged = $true
    if ($c2 -ne 0) { $r.Text = ('WMI deposu onar' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (winmgmt ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$c2 + ').'; return $r }
    $v = Test-PrepWmi
    if ($v.Ok -eq $true) { $r.Ok = $true; $r.Verified = $true; $r.Text = ('WMI deposu onar' + [char]0x0131 + 'ld' + [char]0x0131 + '; sorgular ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor.') } else { $r.Text = ('WMI deposu onar' + [char]0x0131 + 'ld' + [char]0x0131 + ' ama sorgu h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + [string]$v.Error }
    return $r
}

function Job_PrepWmi($P) {
    try {
        $r = Invoke-PrepWmiRepair
        if ($r.Ok -eq $true) { Write-WhLog $r.Text 'OK' } else { Write-WhLog $r.Text 'ERR' }
        return $r
    } catch {
        Write-WhLog (('WMI denetimi yap' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false; Verified = $false; Salvaged = $false; Text = [string]$_.Exception.Message }
    }
}

