    ('7zip.7zip|7-Zip|verim|Igor Pavlov|' + [char]0x00DC + 'cretsiz, a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynakl' + [char]0x0131 + ' ar' + [char]0x015F + 'iv arac' + [char]0x0131 + '; zip, 7z, rar ve bir' + [char]0x00E7 + 'ok bi' + [char]0x00E7 + 'imi a' + [char]0x00E7 + 'ar ve olu' + [char]0x015F + 'turur.|https://www.7-zip.org/|%ProgramFiles%\7-Zip\7zFM.exe;%ProgramFiles(x86)%\7-Zip\7zFM.exe'),
    ('voidtools.Everything|Everything|verim|voidtools|Dosya ve klas' + [char]0x00F6 + 'r adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' arar; b' + [char]0x00FC + 'y' + [char]0x00FC + 'k disklerde bile sonu' + [char]0x00E7 + ' yazarken g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.|https://www.voidtools.com/|%ProgramFiles%\Everything\Everything.exe;%ProgramFiles(x86)%\Everything\Everything.exe;%LOCALAPPDATA%\Programs\Everything\Everything.exe'),
    ('Microsoft.PowerToys|PowerToys|verim|Microsoft|Windows i' + [char]0x00E7 + 'in ' + [char]0x00FC + 'retkenlik ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ': pencere d' + [char]0x00FC + 'zenleyici, toplu yeniden adland' + [char]0x0131 + 'rma, renk se' + [char]0x00E7 + 'ici ve daha fazlas' + [char]0x0131 + '.|https://learn.microsoft.com/windows/powertoys/|%ProgramFiles%\PowerToys\PowerToys.exe;%LOCALAPPDATA%\PowerToys\PowerToys.exe;%LOCALAPPDATA%\Programs\PowerToys\PowerToys.exe')
)
$script:ExtToolCache = $null

# Katalog: @( @{ Id; Name; Group; Publisher; Desc; Home; Exe } )
function Get-ExtToolCatalog {
    if ($null -ne $script:ExtToolCache) { return , $script:ExtToolCache }
    $out = New-Object System.Collections.ArrayList
    foreach ($r in $script:ExtToolRows) {
        $f = ([string]$r).Split('|')
        if ($f.Count -lt 7) { continue }
        [void]$out.Add(@{ Id = $f[0].Trim(); Name = $f[1].Trim(); Group = $f[2].Trim(); Publisher = $f[3].Trim(); Desc = $f[4].Trim(); Home = $f[5].Trim(); Exe = $f[6].Trim() })
    }
    $script:ExtToolCache = $out.ToArray()
    return , $script:ExtToolCache
}

# Kimlige gore katalog satiri (buyuk/kucuk harf onemsiz); yoksa $null
function Get-ExtTool([string]$Id) {
    $cat = Get-ExtToolCatalog
    foreach ($t in $cat) { if ([string]$t.Id -eq $Id) { return $t } }
    return $null
}

# Kurulabilir mi? '' = evet; aksi halde nedeni
function Test-ExtToolId([string]$Id) {
    if ($Id -cnotmatch '^[A-Za-z0-9][A-Za-z0-9\.\-_\+]*\z') { return (('Ge' + [char]0x00E7 + 'ersiz paket kimli' + [char]0x011F + 'i: ') + $Id) }
    if ($null -eq (Get-ExtTool $Id)) { return ($Id + (' izin listesinde de' + [char]0x011F + 'il; kurulmad' + [char]0x0131 + '.')) }
    return ''
}

# Yol kaliplarini acar: ortam degiskenleri genisletilir, {WG} iki winget kokune cevrilir, acilamayan degiskenli yollar atlanir
function Expand-ExtToolPaths([string]$Patterns) {
    $out = New-Object System.Collections.ArrayList
    foreach ($p in @($Patterns -split ';')) {
        $q = $p.Trim()
        if ($q -eq '') { continue }
        $variants = @($q)
        if ($q.Contains('{WG}')) { $variants = @($q.Replace('{WG}', '%LOCALAPPDATA%\Microsoft\WinGet'), $q.Replace('{WG}', '%ProgramFiles%\WinGet')) }
        foreach ($v in $variants) {
            $e = [Environment]::ExpandEnvironmentVariables($v)
            if ($e.Contains('%')) { continue }
            [void]$out.Add($e)
        }
    }
    return , $out.ToArray()
}

# Aracin calistirilabilir dosyasi kuruluysa yolu, degilse ''. Yalnizca dosya var mi diye bakar; hicbir sey calistirmaz.
function Find-ExtToolExe($Tool) {
    $paths = Expand-ExtToolPaths ([string]$Tool.Exe)
    $sep = [System.IO.Path]::DirectorySeparatorChar
    foreach ($p0 in $paths) {
        $p = $p0.Replace('\', [string]$sep)
        try {
            $wi = $p.IndexOfAny([char[]]@('*', '?'))
            if ($wi -ge 0) {
                # joker karakterden onceki sabit bolum (kullanici klasoru gibi) oldugu gibi eslessin: [ ] gibi karakterler kacirilir
                $si = $p.LastIndexOf($sep, $wi)
                $q = $p
                if ($si -ge 0) { $q = [System.Management.Automation.WildcardPattern]::Escape($p.Substring(0, $si + 1)) + $p.Substring($si + 1) }
                $f = Get-ChildItem -Path $q -File -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($null -ne $f) { return [string]$f.FullName }
            } elseif (Test-Path -LiteralPath $p -PathType Leaf) { return $p }
        } catch { }
    }
    return ''
}

# Katalogdaki her arac icin kurulu mu ve nerede: @( @{ Id; Installed; Path } )
function Get-ExtToolStates {
    $cat = Get-ExtToolCatalog
    $out = New-Object System.Collections.ArrayList
    foreach ($t in $cat) {
        $path = ''
        try { $path = Find-ExtToolExe $t } catch { $path = '' }
        [void]$out.Add(@{ Id = [string]$t.Id; Installed = ($path -ne ''); Path = [string]$path })
    }
    return , $out.ToArray()
}

# Denetim isi: yalnizca dosya var mi diye bakar
function Job_ExtToolScan($P) {
    try {
        Write-WhLog (('D' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + 'lar denetleniyor (yaln' + [char]0x0131 + 'zca okuma)...')) 'INFO'
        $items = Get-ExtToolStates
        $n = 0
        foreach ($i in $items) { if ($i.Installed -eq $true) { $n++ } }
        Write-WhLog (('Kurulu d' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + ': ') + [string]$n + ' / ' + [string]@($items).Count) 'INFO'
        return @{ Ok = $true; Items = $items; At = (Get-Date).ToString('dd.MM.yyyy HH:mm') }
    } catch {
        Write-WhLog (('D' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + 'lar denetlenemedi: ') + $_.Exception.Message) 'ERR'
        return @{ Ok = $false; Error = $_.Exception.Message }
    }
}

# Kurulum isi: P.Id yalnizca izin listesindeki bir kimlik olabilir. Donus: @{ Ok; Id; Name; Text; Reboot; Already; Code; Path }
function Job_ExtToolInstall($P) {
    $id = ''
    try { $id = [string]$P.Id } catch { $id = '' }
    $out = @{ Ok = $false; Id = $id; Name = ''; Text = ''; Reboot = $false; Already = $false; Code = 0; Path = '' }
    $why = Test-ExtToolId $id
    if ($why -ne '') { $out.Text = $why; Write-WhLog $why 'ERR'; return $out }
    $tool = Get-ExtTool $id
    $id = [string]$tool.Id
    $out.Id = $id
    $out.Name = [string]$tool.Name
    if ((Get-WingetPath) -eq '') {
        $out.Text = (('winget bulunamad' + [char]0x0131 + '. Microsoft Store' + [char]0x2019 + 'dan ' + [char]0x201C + 'Uygulama Y' + [char]0x00FC + 'kleyicisi' + [char]0x201D + 'ni (App Installer) y' + [char]0x00FC + 'kleyin.'))
        Write-WhLog $out.Text 'ERR'
        return $out
    }
    Set-JobProgress 0 1 ($out.Name + ' kuruluyor')
    Write-WhLog ('=== Kuruluyor: ' + $out.Name + ' (' + $id + ('; winget deposu, paket ' + [char]0x00F6 + 'zeti winget taraf' + [char]0x0131 + 'ndan do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r)')) 'STEP'
    $code = -1
    try {
        $r = Invoke-WingetRaw @('install', '--id', $id, '--exact', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity')
        Write-WingetLines $r.Lines
        $code = [int]$r.Code
    } catch { Write-WhLog ($id + ': ' + $_.Exception.Message) 'ERR' }
    $res = Get-PrepWingetResult $code
    $out.Code = $code
    $out.Ok = ($res.Ok -eq $true)
    $out.Reboot = ($res.Reboot -eq $true)
    $out.Already = ($res.Already -eq $true)
    $out.Text = [string]$res.Text
    if ($out.Ok) {
        try { $out.Path = Find-ExtToolExe $tool } catch { $out.Path = '' }
        Write-WhLog ($out.Name + ': ' + $out.Text) 'OK'
    } else {
        Write-WhLog ($out.Name + ': ' + $out.Text) 'ERR'
    }
    Set-JobProgress 1 1
    return $out
}

# ---------------- guncelleme denetimi ve dosya butunlugu: cekirdek ----------------
# ==================================================================
#  GUNCELLEME DENETIMI (istege bagli; yalnizca siz baslatinca)
#  Uygulama kendiliginden hicbir adrese baglanmaz. "Guncellemeleri denetle"ye basinca Ayarlar'da verdiginiz HTTPS adresinden kucuk bir
#  bildirim dosyasi (JSON) okunur: yalnizca surum numarasi, indirme adresi ve SHA-256 ozeti. Kimlik, bilgisayar adi ya da baska veri gonderilmez.
#  Indirme yalnizca onayinizla yapilir; dosyanin SHA-256 ozeti bildirimdekiyle tutmazsa dosya silinir. Hicbir sey kendiliginden kurulmaz ya da calistirilmaz.
#  Bildirim bicimi (kendi dosyaniz):  { "version": "9.0.1", "url": "https://.../Multimizer-9.0.1.zip", "sha256": "64 onaltilik hane", "size": 2900000, "notes": "...", "page": "https://..." }
#  GitHub'in "releases/latest" yaniti da okunur (tag_name, Multimizer-*.zip eki, ekin sha256 ozeti); ozet yoksa yalnizca duyurulur, indirme kapali kalir.
#  SHA-256 dosyanin bozulmadigini ve yolda degismedigini gosterir; yayinci hesabinin ele gecirilmesine karsi koruma degildir.
# ==================================================================
$script:UpdateMaxManifest = 262144
$script:UpdateMaxDownload = 314572800
$script:UpdateMaxHops = 5
$script:UpdateAgent = 'Multimizer-Guncelleme'

# '9.0.1' ya da 'v9.0.1' -> dort sayi; gecersizse $null
function ConvertTo-AppVersionParts([string]$V) {
    $t = $V.Trim()
    if ($t.StartsWith('v', [StringComparison]::OrdinalIgnoreCase)) { $t = $t.Substring(1) }
    if ($t -notmatch '^[0-9]{1,5}(\.[0-9]{1,5}){1,3}\z') { return $null }
    $parts = New-Object System.Collections.ArrayList
    foreach ($p in $t.Split('.')) { [void]$parts.Add([int]$p) }
    while ($parts.Count -lt 4) { [void]$parts.Add(0) }
    return , $parts.ToArray()
}

# -1: A < B, 0: esit, 1: A > B, $null: karsilastirilamaz (bicim gecersiz)
function Compare-AppVersion([string]$A, [string]$B) {
    $pa = ConvertTo-AppVersionParts $A
    $pb = ConvertTo-AppVersionParts $B
    if ($null -eq $pa -or $null -eq $pb) { return $null }
    for ($i = 0; $i -lt 4; $i++) {
        if ($pa[$i] -lt $pb[$i]) { return -1 }
        if ($pa[$i] -gt $pb[$i]) { return 1 }
    }
    return 0
}

# '' = adres kullanilabilir, aksi halde nedeni. Yalnizca HTTPS, kullanici bilgisiz, varsayilan kapi.
function Test-UpdateUrl([string]$Url) {
    if ([string]::IsNullOrWhiteSpace($Url)) { return ('' + [char]0x00D6 + 'nce g' + [char]0x00FC + 'ncelleme bildirim adresini (HTTPS) girin.') }
    if ($Url.Length -gt 600 -or $Url -match '[\s\x00-\x1f]') { return ('Adres ge' + [char]0x00E7 + 'ersiz (bo' + [char]0x015F + 'luk ya da denetim karakteri i' + [char]0x00E7 + 'eriyor, ya da ' + [char]0x00E7 + 'ok uzun).') }
    $u = $null
    if (-not [System.Uri]::TryCreate($Url, [System.UriKind]::Absolute, [ref]$u)) { return ('Adres ge' + [char]0x00E7 + 'ersiz.') }
    if ($u.Scheme -ne 'https') { return ('Adres https:// ile ba' + [char]0x015F + 'lamal' + [char]0x0131 + '; ' + [char]0x015F + 'ifresiz ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kullan' + [char]0x0131 + 'lmaz.') }
    if ($u.UserInfo -ne '') { return ('Adres kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' ad' + [char]0x0131 + ' ya da parola i' + [char]0x00E7 + 'eremez.') }
    if ($u.Host -eq '' -or -not $u.IsDefaultPort) { return ('Adres ge' + [char]0x00E7 + 'ersiz (sunucu ad' + [char]0x0131 + ' yok ya da ' + [char]0x00F6 + 'zel bir kap' + [char]0x0131 + ' kullan' + [char]0x0131 + 'yor).') }
    return ''
}

# Bir GitHub deposunun adresi (https://github.com/sahip/depo) verildiyse, o deponun "en son surum" API adresine cevirir.
# Baska adresler oldugu gibi kalir; gecersiz adres de degismeden doner (denetimi Test-UpdateUrl yapar).
function ConvertTo-UpdateFeedUrl([string]$Url) {
    $t = $Url.Trim()
    if ((Test-UpdateUrl $t) -ne '') { return $t }
    $u = New-Object System.Uri($t)
    if ($u.Host -ne 'github.com' -and $u.Host -ne 'www.github.com') { return $t }
    $seg = @($u.AbsolutePath.Trim('/').Split('/') | Where-Object { $_ -ne '' })
    if ($seg.Count -lt 2) { return $t }
    $owner = [string]$seg[0]
    $repo = ([string]$seg[1]) -replace '(?i)\.git\z', ''
    if ($owner -cnotmatch '^[A-Za-z0-9][A-Za-z0-9\-]{0,38}\z') { return $t }
    if ($repo -cnotmatch '^[A-Za-z0-9._\-]{1,100}\z' -or $repo -match '^\.+\z') { return $t }
    if ($seg.Count -gt 2 -and [string]$seg[2] -ne 'releases') { return $t }
    return ('https://api.github.com/repos/' + $owner + '/' + $repo + '/releases/latest')
}

# Bildirimdeki metni duz ve kisa tutar: denetim karakterleri atilir, en cok 600 karakter
function Format-UpdateNotes([string]$Text) {
    $t = ($Text -replace '[\x00-\x08\x0b\x0c\x0e-\x1f]', '').Trim()
    $t = ($t -replace '\r\n', "`n" -replace '\n{3,}', "`n`n")
    if ($t.Length -gt 600) { $t = $t.Substring(0, 597) + '...' }
    return $t
}

# Bildirim nesnesini (ConvertFrom-Json ciktisi) dogrular.
# Donus: @{ Ok; Version; Url; Sha256; Size; Notes; Page; Download; Why; Error }   Ok = surum okunabildi, Download = guvenle indirilebilir
function ConvertFrom-UpdateInfo($Obj) {
    $r = @{ Ok = $false; Version = ''; Url = ''; Sha256 = ''; Size = [long]0; Notes = ''; Page = ''; Download = $false; Why = ''; Error = '' }
    if ($null -eq $Obj) { $r.Error = ('Bildirim dosyas' + [char]0x0131 + ' bo' + [char]0x015F + '.'); return $r }
    $ver = [string](Get-JsonProp $Obj 'version')
    $url = [string](Get-JsonProp $Obj 'url')
    $sha = [string](Get-JsonProp $Obj 'sha256')
    $size = Get-JsonProp $Obj 'size'
    $notes = [string](Get-JsonProp $Obj 'notes')
    $page = [string](Get-JsonProp $Obj 'page')
    $tag = [string](Get-JsonProp $Obj 'tag_name')
    if ($ver -eq '' -and $tag -ne '') {
        $ver = $tag
        $page = [string](Get-JsonProp $Obj 'html_url')
        $notes = [string](Get-JsonProp $Obj 'body')
        foreach ($a in @(Get-JsonProp $Obj 'assets')) {
            $nm = [string](Get-JsonProp $a 'name')
            if ($nm -match '(?i)^Multimizer-[0-9]+(\.[0-9]+){1,3}\.zip\z') {
                $url = [string](Get-JsonProp $a 'browser_download_url')
                $size = Get-JsonProp $a 'size'
                $dg = [string](Get-JsonProp $a 'digest')
                if ($dg -match '(?i)^sha256:([0-9a-f]{64})\z') { $sha = $Matches[1] }
                break
            }
        }
    }
    if ($null -eq (ConvertTo-AppVersionParts $ver)) { $r.Error = ('Bildirimdeki s' + [char]0x00FC + 'r' + [char]0x00FC + 'm numaras' + [char]0x0131 + ' ge' + [char]0x00E7 + 'ersiz.'); return $r }
    $r.Version = $ver.Trim()
    if ($r.Version.StartsWith('v', [StringComparison]::OrdinalIgnoreCase)) { $r.Version = $r.Version.Substring(1) }
    $r.Ok = $true
    $r.Notes = Format-UpdateNotes $notes
    if ($page -ne '' -and (Test-UpdateUrl $page) -eq '') { $r.Page = $page }
    $n = [long]0
    if ($null -ne $size -and [long]::TryParse([string]$size, [ref]$n) -and $n -gt 0 -and $n -le $script:UpdateMaxDownload) { $r.Size = $n }
    if ($url -eq '') { $r.Why = 'Bildirimde indirme adresi yok.'; return $r }
    $uw = Test-UpdateUrl $url
    if ($uw -ne '') { $r.Why = ('' + [char]0x0130 + 'ndirme adresi g' + [char]0x00FC + 'venli de' + [char]0x011F + 'il: ') + $uw; return $r }
    $uu = New-Object System.Uri($url)
    if ($uu.AbsolutePath -notmatch '(?i)\.zip\z') { $r.Why = ('' + [char]0x0130 + 'ndirme adresi bir ZIP dosyas' + [char]0x0131 + 'na ' + [char]0x00E7 + '' + [char]0x0131 + 'km' + [char]0x0131 + 'yor.'); return $r }
    if ($sha -notmatch '(?i)^[0-9a-f]{64}\z') { $r.Why = ('Bildirimde SHA-256 ' + [char]0x00F6 + 'zeti yok; g' + [char]0x00FC + 'venli' + [char]0x011F + 'iniz i' + [char]0x00E7 + 'in indirme kapal' + [char]0x0131 + '.'); return $r }
    $r.Url = $url
    $r.Sha256 = $sha.ToLowerInvariant()
    $r.Download = $true
    return $r
}

# Tek bir istek (yonlendirme izlenmez). Dest bossa govde bellege okunur, doluysa dosyaya yazilir; SHA-256 okunurken hesaplanir.
# Donus: @{ Code; Location; Bytes; Sha256; Length; Error }
function Send-UpdateHop([string]$Url, [string]$Dest, [long]$MaxBytes, [int]$TimeoutSec) {
    $res = @{ Code = 0; Location = ''; Bytes = $null; Sha256 = ''; Length = [long]0; Error = '' }
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $resp = $null
    $st = $null
    $fs = $null
    $sha = $null
    try {
        $rq = [System.Net.HttpWebRequest]::Create($Url)
        $rq.Method = 'GET'
        $rq.AllowAutoRedirect = $false
        $rq.Timeout = $TimeoutSec * 1000
        $rq.ReadWriteTimeout = $TimeoutSec * 1000
        $rq.UserAgent = [string]$script:UpdateAgent
        try { $rq.Proxy = [System.Net.WebRequest]::GetSystemWebProxy(); $rq.Proxy.Credentials = [System.Net.CredentialCache]::DefaultCredentials } catch { }
        try {
            $resp = $rq.GetResponse()
        } catch [System.Net.WebException] {
            $resp = $_.Exception.Response
            if ($null -eq $resp) { throw }
        }
        $res.Code = [int]$resp.StatusCode
        $loc = $resp.Headers['Location']
        if ($null -ne $loc) { $res.Location = [string]$loc }
        if ($res.Code -ge 200 -and $res.Code -lt 300) {
            if ($resp.ContentLength -gt $MaxBytes) { $res.Error = ('Dosya beklenenden b' + [char]0x00FC + 'y' + [char]0x00FC + 'k (s' + [char]0x0131 + 'n' + [char]0x0131 + 'r ') + (Format-Size $MaxBytes) + ').'; return $res }
            $st = $resp.GetResponseStream()
            $buf = New-Object 'byte[]' 65536
            $total = [long]0
            $ms = $null
            if ($Dest -eq '') { $ms = New-Object System.IO.MemoryStream } else { $fs = New-Object System.IO.FileStream($Dest, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None) }
            $sha = [System.Security.Cryptography.SHA256]::Create()
            while ($true) {
                $n = $st.Read($buf, 0, $buf.Length)
                if ($n -le 0) { break }
                $total += $n
                if ($total -gt $MaxBytes) { $res.Error = ('Dosya beklenenden b' + [char]0x00FC + 'y' + [char]0x00FC + 'k (s' + [char]0x0131 + 'n' + [char]0x0131 + 'r ') + (Format-Size $MaxBytes) + ').'; break }
                [void]$sha.TransformBlock($buf, 0, $n, $null, 0)
                if ($null -ne $ms) { $ms.Write($buf, 0, $n) } else { $fs.Write($buf, 0, $n) }
                if (Test-JobCancel) { $res.Error = ('' + [char]0x0130 + 'ptal edildi.'); break }
            }
            if ($res.Error -eq '') {
                [void]$sha.TransformFinalBlock((New-Object 'byte[]' 0), 0, 0)
                $res.Sha256 = (([System.BitConverter]::ToString($sha.Hash)) -replace '-', '').ToLowerInvariant()
                $res.Length = $total
                if ($null -ne $ms) { $res.Bytes = $ms.ToArray() }
            }
        }
    } catch {
        $res.Error = ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kurulamad' + [char]0x0131 + ' ya da kesildi: ') + $_.Exception.Message
    } finally {
        if ($null -ne $fs) { try { $fs.Dispose() } catch { } }
        if ($null -ne $st) { try { $st.Dispose() } catch { } }
        if ($null -ne $resp) { try { $resp.Close() } catch { } }
        if ($null -ne $sha) { try { $sha.Dispose() } catch { } }
    }
    return $res
}

# Yonlendirmeleri elle izler: her adim HTTPS olmali, en cok $script:UpdateMaxHops yonlendirme.
# Donus: @{ Ok; Bytes; Sha256; Length; FinalUrl; Error }
function Invoke-UpdateFetch([string]$Url, [string]$Dest, [long]$MaxBytes, [int]$TimeoutSec = 20) {
    $out = @{ Ok = $false; Bytes = $null; Sha256 = ''; Length = [long]0; FinalUrl = $Url; Error = '' }
    $cur = $Url
    for ($hop = 0; $hop -le $script:UpdateMaxHops; $hop++) {
        $why = Test-UpdateUrl $cur
        if ($why -ne '') { $out.Error = $why; return $out }
        $r = Send-UpdateHop $cur $Dest $MaxBytes $TimeoutSec
        if ([string]$r.Error -ne '') { $out.Error = [string]$r.Error; return $out }
        $code = [int]$r.Code
        if ($code -ge 300 -and $code -lt 400 -and $code -ne 304) {
            $loc = [string]$r.Location
            if ($loc -eq '') { $out.Error = ('Sunucu ba' + [char]0x015F + 'ka bir adrese y' + [char]0x00F6 + 'nlendirdi ama adres vermedi.'); return $out }
            $next = ''
            try { $next = (New-Object System.Uri((New-Object System.Uri($cur)), $loc)).AbsoluteUri } catch { $out.Error = ('Y' + [char]0x00F6 + 'nlendirme adresi ge' + [char]0x00E7 + 'ersiz.'); return $out }
            $cur = $next
            continue
        }
        if ($code -ge 200 -and $code -lt 300) {
            $out.Ok = $true
            $out.Bytes = $r.Bytes
            $out.Sha256 = [string]$r.Sha256
            $out.Length = [long]$r.Length
            $out.FinalUrl = $cur
            return $out
        }
        $out.Error = 'Sunucu ' + [string]$code + (' yan' + [char]0x0131 + 't' + [char]0x0131 + ' verdi.')
        return $out
    }
    $out.Error = ('' + [char]0x00C7 + 'ok fazla y' + [char]0x00F6 + 'nlendirme.')
    return $out
}

# Denetim isi: P.Url = bildirim adresi, P.Current = calisan surum
function Job_UpdateCheck($P) {
    $url = ''
    $cur = ''
    try { $url = [string]$P.Url } catch { $url = '' }
    try { $cur = [string]$P.Current } catch { $cur = '' }
    $out = @{ Ok = $false; Current = $cur; Latest = ''; Newer = $false; Info = $null; Error = ''; At = (Get-Date).ToString('dd.MM.yyyy HH:mm') }
    $why = Test-UpdateUrl $url
    if ($why -ne '') { $out.Error = $why; Write-WhLog (('G' + [char]0x00FC + 'ncelleme denetimi yap' + [char]0x0131 + 'lmad' + [char]0x0131 + ': ') + $why) 'WARN'; return $out }
    $feed = ConvertTo-UpdateFeedUrl $url
    $hostName = (New-Object System.Uri($feed)).Host
    Write-WhLog (('G' + [char]0x00FC + 'ncelleme denetimi: ') + $hostName + (' adresinden k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k bir bildirim dosyas' + [char]0x0131 + ' okunuyor (kimlik ya da ki' + [char]0x015F + 'isel veri g' + [char]0x00F6 + 'nderilmez).')) 'INFO'
    Set-JobProgress 0 1 ('G' + [char]0x00FC + 'ncelleme denetleniyor')
    $f = Invoke-UpdateFetch $feed '' $script:UpdateMaxManifest 20
    if ($f.Ok -ne $true) {
        $out.Error = [string]$f.Error
        if ($hostName -eq 'api.github.com' -and $out.Error -match '\b404\b') { $out.Error += (' Depo gizli olabilir ya da hen' + [char]0x00FC + 'z bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'm yay' + [char]0x0131 + 'mlanmam' + [char]0x0131 + '' + [char]0x015F + ' olabilir.') }
        Write-WhLog (('G' + [char]0x00FC + 'ncelleme denetimi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $out.Error) 'ERR'
        return $out
    }
    $txt = ''
    try { $txt = (New-Object System.Text.UTF8Encoding($false)).GetString([byte[]]$f.Bytes).TrimStart([char]0xFEFF) } catch { $txt = '' }
    $obj = $null
    try { $obj = ConvertFrom-Json -InputObject $txt } catch { $obj = $null }
    if ($null -eq $obj) { $out.Error = ('Bildirim dosyas' + [char]0x0131 + ' okunamad' + [char]0x0131 + ' (ge' + [char]0x00E7 + 'erli bir JSON de' + [char]0x011F + 'il).'); Write-WhLog $out.Error 'ERR'; return $out }
    $info = ConvertFrom-UpdateInfo $obj
    if ($info.Ok -ne $true) { $out.Error = [string]$info.Error; Write-WhLog (('G' + [char]0x00FC + 'ncelleme bildirimi ge' + [char]0x00E7 + 'ersiz: ') + $out.Error) 'ERR'; return $out }
    $cmp = Compare-AppVersion ([string]$info.Version) $cur
    $out.Ok = $true
    $out.Info = $info
    $out.Latest = [string]$info.Version
    $out.Newer = ($cmp -eq 1)
    if ($out.Newer) { Write-WhLog (('Yeni s' + [char]0x00FC + 'r' + [char]0x00FC + 'm var: ') + $out.Latest + (' (' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an: ') + $cur + ')') 'OK' } else { Write-WhLog (('G' + [char]0x00FC + 'ncelsiniz (yay' + [char]0x0131 + 'mlanan en son s' + [char]0x00FC + 'r' + [char]0x00FC + 'm: ') + $out.Latest + ')') 'OK' }
    Set-JobProgress 1 1
    return $out
}

# Indirme klasoru: veri klasorunun altindaki Guncelleme
function Get-UpdateDir {
    return (Join-Path ([string]$sync.DataDir) 'Guncelleme')
}

# Indirme isi: P.Url, P.Sha256, P.Version, P.Size. Once gecici dosyaya iner, ozet tutarsa adini degistirir; tutmazsa siler. Hicbir sey calistirilmaz.
# Donus: @{ Ok; Path; Size; Sha256; Already; Error }
function Job_UpdateDownload($P) {
    $url = ''
    $sha = ''
    $ver = ''
    try { $url = [string]$P.Url } catch { $url = '' }
    try { $sha = ([string]$P.Sha256).ToLowerInvariant() } catch { $sha = '' }
    try { $ver = [string]$P.Version } catch { $ver = '' }
    $out = @{ Ok = $false; Path = ''; Size = [long]0; Sha256 = ''; Already = $false; Error = '' }
    $why = Test-UpdateUrl $url
    if ($why -ne '') { $out.Error = $why; Write-WhLog (('G' + [char]0x00FC + 'ncelleme indirilmedi: ') + $why) 'ERR'; return $out }
    if ($sha -notmatch '^[0-9a-f]{64}\z') { $out.Error = ('SHA-256 ' + [char]0x00F6 + 'zeti ge' + [char]0x00E7 + 'ersiz; g' + [char]0x00FC + 'venli' + [char]0x011F + 'iniz i' + [char]0x00E7 + 'in indirilmedi.'); Write-WhLog $out.Error 'ERR'; return $out }
    if ($null -eq (ConvertTo-AppVersionParts $ver)) { $out.Error = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm numaras' + [char]0x0131 + ' ge' + [char]0x00E7 + 'ersiz.'); Write-WhLog $out.Error 'ERR'; return $out }
    if ((New-Object System.Uri($url)).AbsolutePath -notmatch '(?i)\.zip\z') { $out.Error = ('' + [char]0x0130 + 'ndirme adresi bir ZIP dosyas' + [char]0x0131 + 'na ' + [char]0x00E7 + '' + [char]0x0131 + 'km' + [char]0x0131 + 'yor.'); Write-WhLog $out.Error 'ERR'; return $out }
    $dir = Get-UpdateDir
    $dirErr = ''
    try { if (-not (Test-Path -LiteralPath $dir -PathType Container)) { [void](New-Item -ItemType Directory -Path $dir -Force -ErrorAction Stop) } } catch { $dirErr = $_.Exception.Message }
    if ($dirErr -eq '' -and -not (Test-Path -LiteralPath $dir -PathType Container)) { $dirErr = ('o ad ba' + [char]0x015F + 'ka bir dosyaya ait') }
    if ($dirErr -ne '') { $out.Error = ('' + [char]0x0130 + 'ndirme klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + $dirErr; Write-WhLog $out.Error 'ERR'; return $out }
    $final = Join-Path $dir ('Multimizer-' + $ver.TrimStart('v', 'V') + '.zip')
    $tmp = $final + '.indiriliyor'
    if (Test-Path -LiteralPath $final -PathType Leaf) {
        $have = ''
        try { $have = (Get-FileHash -LiteralPath $final -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant() } catch { $have = '' }
        if ($have -eq $sha) {
            $out.Ok = $true; $out.Already = $true; $out.Path = $final; $out.Sha256 = $have
            try { $out.Size = (Get-Item -LiteralPath $final -ErrorAction Stop).Length } catch { }
            Write-WhLog (('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'm zaten indirilmi' + [char]0x015F + ' ve ' + [char]0x00F6 + 'zeti do' + [char]0x011F + 'ru: ') + $final) 'OK'
            return $out
        }
    }
    Write-WhLog (('G' + [char]0x00FC + 'ncelleme indiriliyor (') + (New-Object System.Uri($url)).Host + ('); dosya yaln' + [char]0x0131 + 'zca indirilir, ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz.')) 'STEP'
    Set-JobProgress 0 1 ('G' + [char]0x00FC + 'ncelleme indiriliyor')
    $f = Invoke-UpdateFetch $url $tmp $script:UpdateMaxDownload 30
    if ($f.Ok -ne $true) {
        try { if (Test-Path -LiteralPath $tmp -PathType Leaf) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } } catch { }
        $out.Error = [string]$f.Error
        Write-WhLog (('G' + [char]0x00FC + 'ncelleme indirilemedi: ') + $out.Error) 'ERR'
        return $out
    }
    if ([string]$f.Sha256 -ne $sha) {
        try { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } catch { }
        $out.Error = ('' + [char]0x0130 + 'ndirilen dosyan' + [char]0x0131 + 'n SHA-256 ' + [char]0x00F6 + 'zeti bildirimdekiyle uyu' + [char]0x015F + 'mad' + [char]0x0131 + '; g' + [char]0x00FC + 'venli' + [char]0x011F + 'iniz i' + [char]0x00E7 + 'in dosya silindi.')
        Write-WhLog $out.Error 'ERR'
        return $out
    }
    try {
        if (Test-Path -LiteralPath $final -PathType Leaf) { Remove-Item -LiteralPath $final -Force -ErrorAction Stop }
        Move-Item -LiteralPath $tmp -Destination $final -Force -ErrorAction Stop
    } catch {
        $out.Error = ('' + [char]0x0130 + 'ndirilen dosya yerine konamad' + [char]0x0131 + ': ') + $_.Exception.Message
        Write-WhLog $out.Error 'ERR'
        return $out
    }
    $out.Ok = $true
    $out.Path = $final
    $out.Size = [long]$f.Length
    $out.Sha256 = [string]$f.Sha256
    Write-WhLog (('G' + [char]0x00FC + 'ncelleme indirildi ve SHA-256 ' + [char]0x00F6 + 'zeti do' + [char]0x011F + 'ruland' + [char]0x0131 + ': ') + $final) 'OK'
    Set-JobProgress 1 1
    return $out
}

# Dosya butunlugu: derleme sirasinda betige yazilan ozetlerle yan dosyalari (Eklenti, veri) karsilastirir. Yalnizca okur.
# Donus: @{ Total; Good; Bad = @( @{ Rel; Kind } ) }   Kind: missing | read | hash
function Get-PackIntegrity {
    $bad = New-Object System.Collections.ArrayList
    $keys = @($script:PackHash.Keys | Sort-Object)
    foreach ($rel in $keys) {
        $r = Get-PackFileText ([string]$rel)
        if ($r.Ok -ne $true) { [void]$bad.Add(@{ Rel = [string]$rel; Kind = [string]$r.Kind }) }
    }
    return @{ Total = $keys.Count; Good = ($keys.Count - $bad.Count); Bad = $bad.ToArray() }
}

# Arka plan isi: yan dosyalarin ozetleri + calisan betigin kendi SHA-256 ozeti (yayimlanan ozetle karsilastirmak icin). Yalnizca okur.
function Job_IntegrityCheck($P) {
    $out = @{ Ok = $false; Total = 0; Good = 0; Bad = @(); ScriptPath = ''; ScriptSha256 = ''; Error = ''; At = (Get-Date).ToString('dd.MM.yyyy HH:mm') }
    try {
        Set-JobProgress 0 1 ('Dosya b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' denetleniyor')
        $r = Get-PackIntegrity
        $out.Total = [int]$r.Total
        $out.Good = [int]$r.Good
        $out.Bad = @($r.Bad)
        $sp = ''
        try { $sp = [string]$sync.ScriptPath } catch { $sp = '' }
        if ($sp -ne '' -and (Test-Path -LiteralPath $sp -PathType Leaf)) {
            $out.ScriptPath = $sp
            try { $out.ScriptSha256 = (Get-FileHash -LiteralPath $sp -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant() } catch { $out.ScriptSha256 = '' }
        }
        $out.Ok = $true
        if ($out.Bad.Count -eq 0) { Write-WhLog (('Dosya b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ': ') + [string]$out.Good + ' / ' + [string]$out.Total + (' yan dosya do' + [char]0x011F + 'ru.')) 'OK' }
        else {
            Write-WhLog (('Dosya b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ': ') + [string]$out.Good + ' / ' + [string]$out.Total + (' yan dosya do' + [char]0x011F + 'ru; ') + [string]$out.Bad.Count + ' dosyada sorun var.') 'WARN'
            foreach ($b in $out.Bad) { Write-WhLog ('  sorunlu: ' + [string]$b.Rel + ' (' + [string]$b.Kind + ')') 'WARN' }
        }
        Set-JobProgress 1 1
    } catch {
        $out.Error = $_.Exception.Message
        Write-WhLog (('Dosya b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' denetlenemedi: ') + $out.Error) 'ERR'
    }
    return $out
}

# "Internet istekleri" listesine eklenir; kapatilirsa iki is de hic baslamaz.
$script:NetFeatures['update'] = @{ T = ('G' + [char]0x00FC + 'ncelleme denetimi ve indirme'); D = ('Yaln' + [char]0x0131 + 'zca ' + [char]0x201C + 'G' + [char]0x00FC + 'ncellemeleri denetle' + [char]0x201D + 'ye bast' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda, Ayarlar' + [char]0x2019 + 'da verdi' + [char]0x011F + 'iniz HTTPS adresinden k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'm bildirimi okur. ' + [char]0x0130 + 'ndirme ayr' + [char]0x0131 + 'ca onay' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' ister; kimlik ya da ki' + [char]0x015F + 'isel veri g' + [char]0x00F6 + 'nderilmez.'); Jobs = @('Job_UpdateCheck', 'Job_UpdateDownload') }

# ---------------- oem kodlama ve kultur sinamasi ----------------
# ==================================================================
#  OEM KODLAMA VE KULTUR SINAMASI (cekirdek)
#  Turkce ve Azerice kulturde .NET Framework duzenli ifadeleri buyuk "I" harfini [A-Za-z] ile eslestirmez:
#  "Input" -match '^[A-Za-z]+$' ve "INTEL" -match 'intel' yanlis cikar, bilgisayar adindaki I silinir, I: surucusu reddedilir.
#  Set-MmCulture (betigin basinda tanimlidir) sayi ve tarih bicimini kullanicinin kulturunden alip buyuk/kucuk harf
#  kuralini degismez kulturden alir. Bu dosya: konsol programlarinin cikti kodlamasi ve korumanin sinamasi.
# ==================================================================

# Sistemin OEM kod sayfasi (konsol programlarinin cikti kodlamasi). Kullanicinin bolgesel kulturune degil isletim sistemi ayarina bakar;
# kayit defteri okunamazsa yuklu arayuz dilinin OEM sayfasina, o da olmazsa 437'ye duser.
function Get-OemEncoding {
    if ($null -ne $script:OemEnc) { return $script:OemEnc }
    $cp = 0
    try {
        $v = (Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Nls\CodePage' -Name 'OEMCP' -ErrorAction Stop).OEMCP
        [void][int]::TryParse([string]$v, [ref]$cp)
    } catch { $cp = 0 }
    if ($cp -le 0) { try { $cp = [int][System.Globalization.CultureInfo]::InstalledUICulture.TextInfo.OEMCodePage } catch { $cp = 0 } }
    $enc = $null
    if ($cp -gt 0) { try { $enc = [System.Text.Encoding]::GetEncoding($cp) } catch { $enc = $null } }
    if ($null -eq $enc) { try { $enc = [System.Text.Encoding]::GetEncoding(437) } catch { $enc = [System.Text.Encoding]::UTF8 } }
    $script:OemEnc = $enc
    return $enc
}

# Kultur sinamasi: Turkce "I/i" yuzunden bozulabilecek eslesmeleri dener. Donus: @{ Ok; Bad; Culture; Upper }
# Ana is parcaciginda da arka plan calisma alaninda da ayni sonuc beklenir (Set-MmCulture her ikisinde de cagrilir).
function Test-MmCultureProbe {
    param($P = $null)
    $bad = New-Object System.Collections.ArrayList
    try {
        if (-not ('Input' -match '^[A-Za-z]+$')) { [void]$bad.Add(('[A-Za-z] ile b' + [char]0x00FC + 'y' + [char]0x00FC + 'k I')) }
        if (-not ('INTEL' -match 'intel') -or -not ('intel' -match 'INTEL')) { [void]$bad.Add('INTEL / intel') }
        if (-not ('NVIDIA GeForce' -match '^nvidia ')) { [void]$bad.Add('NVIDIA / nvidia') }
        if (-not ('I:\Yedek' -match '^[A-Za-z]:\\')) { [void]$bad.Add(('I: s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' harfi')) }
        if (-not ('INFO  basladi' -match '^[A-Z]+\s')) { [void]$bad.Add(('g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k d' + [char]0x00FC + 'zeyi INFO')) }
        if (('OFIS-PC' -replace '[^A-Za-z0-9\-_]', '') -cne 'OFIS-PC') { [void]$bad.Add(('bilgisayar ad' + [char]0x0131 + ' temizleme')) }
        if (-not [regex]::IsMatch('Info', '(?i)^[a-z]+$')) { [void]$bad.Add('(?i) ile [a-z]') }
        if ((([string]'I').ToLower() -cne 'i') -or (([string]'i').ToUpper() -cne 'I')) { [void]$bad.Add('ToLower / ToUpper') }
        # @{} tablolari: Windows PowerShell 5.1 anahtar karsilastiricisini surec basinda, kullanicinin kulturuyle bir kez kurar ve saklar;
        # is parcacigi kulturu bunu degistirmez (Turkcede @{ Info = 1 }['info'] bos doner). Bu yuzden anahtarlar ToLowerInvariant() ile
        # normallestirilir (ToLower() ile ayni sonucu vermelidir) ve harf boyu degisebilen dis metinler acik karsilastiricili tabloda tutulur.
        $h = @{}
        $h[([string]'INFO').ToLowerInvariant()] = 1
        $h[([string]'Input').ToLower()] = 2
        if ($h[([string]'Info').ToLowerInvariant()] -ne 1 -or -not $h.ContainsKey(([string]'INPUT').ToLowerInvariant())) { [void]$bad.Add(('s' + [char]0x00F6 + 'zl' + [char]0x00FC + 'k anahtar' + [char]0x0131 + ' normalle' + [char]0x015F + 'tirme')) }
        $t = New-Object System.Collections.Hashtable ([System.StringComparer]::OrdinalIgnoreCase)
        $t['Info'] = 1
        if ($t['info'] -ne 1 -or -not $t.ContainsKey('INFO')) { [void]$bad.Add(('a' + [char]0x00E7 + '' + [char]0x0131 + 'k kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'l' + [char]0x0131 + ' tablo')) }
    } catch { [void]$bad.Add(('s' + [char]0x0131 + 'nama hatas' + [char]0x0131 + ': ') + $_.Exception.Message) }
    $cn = ''
    try { $cn = [string][System.Threading.Thread]::CurrentThread.CurrentCulture.Name } catch { $cn = '' }
    return @{ Ok = ($bad.Count -eq 0); Bad = @($bad.ToArray()); Culture = $cn; Upper = ([string]'i').ToUpper() }
}

# ---------------- dil destegi: cekirdek ----------------
# ==================================================================
#  DIL DESTEGI: cekirdek (dil dosyalari, Tr islevi, otomatik dil secimi, sagdan sola yazim)
# ==================================================================
# Kaynak dil Turkcedir; Turkce metnin kendisi kimliktir (gettext tarzi), bu yuzden Turkce icin dil dosyasi yoktur.
# Dil dosyasi: veri\dil\<kod>.lang (UTF-8). Ust bilgi satirlari "#anahtar: deger" bicimindedir, sonra her satir
#   Turkce metin <SEKME> ceviri
# Kacis: \\ -> \   \t -> sekme   \n -> satir sonu   \r -> satir basi.
# Sablon: kimlikte {0} {1} ... dinamik parcayi gosterir ("Silindi: {0} dosya"). Ceviri bu yer tutucularin sirasini degistirebilir.
# Arama sirasi: secili dil (birebir, bastaki/sondaki bosluk, sablon) -> Ingilizce -> Turkce (metin oldugu gibi kalir).
# Kullanicinin kendi dil dosyalari %ProgramData%\Multimizer\dil klasorune konur; ayni kodlu uygulama dosyasinin yerine gecer.

$script:LangOn = $false          # Turkce disinda bir dil etkin mi
$script:LangCode = 'tr'
$script:LangTag = 'tr-TR'
$script:LangRtl = $false
$script:LangName = ''
$script:LangPrimary = $null      # @{ Code; Map; Tpl; Meta; N; NTpl }
$script:LangFallback = $null     # Ingilizce paket (secili dil Ingilizce degilse)
$script:LangList = $null
$script:LangTrack = $false       # kalite denetimi: istenen ama cevirisi olmayan metinleri sayar
$script:LangMiss = $null
$script:LangSeen = $null
$script:LangKeyLen = 5
$script:LangCache = $null         # metin -> cevrilmis metin (yalnizca izleme kapaliyken)
$script:LangPrefixRx = New-Object System.Text.RegularExpressions.Regex(('^(\s*(?:>>>|' + [char]0x2192 + ')\s+)(.+)$'), [System.Text.RegularExpressions.RegexOptions]::Singleline)
$script:LangBracketRx = New-Object System.Text.RegularExpressions.Regex('^(.*?)\s{2}\[(.+)\]\s*$', [System.Text.RegularExpressions.RegexOptions]::Singleline)
$script:LangCountRx = New-Object System.Text.RegularExpressions.Regex('^(.+?) \(([^()]+)\)$', [System.Text.RegularExpressions.RegexOptions]::Singleline)
$script:LangUpperRx = New-Object System.Text.RegularExpressions.Regex('\p{Lu}{2}')
$script:LangLowerRx = New-Object System.Text.RegularExpressions.Regex('\p{Ll}')
$script:LangFull = $true             # son Find-LangText sonucu eksiksiz cevrildi mi (parcalara bolunen metinlerde)
$script:LangLetterRx = New-Object System.Text.RegularExpressions.Regex('\p{L}{2}')
$script:LangUpperCulture = $null   # buyuk harf donusumunde kullanilan kultur (etkin dilin kulturu)
$script:LangLogRx = New-Object System.Text.RegularExpressions.Regex('^(\d\d:\d\d:\d\d\s+\S+\s+)(.+)$', [System.Text.RegularExpressions.RegexOptions]::Singleline)
$script:LangOut = $null           # izleme acikken Tr'nin urettigi cevrilmis metinler (cift cevirinin eksik sayilmamasi icin)
$script:LangPctStyle = 0         # yuzde yazimi: 0 = %40 (Turkce), 1 = 40%, 2 = 40 % (bolunmez bosluk)

function Get-LangUnescaped([string]$s) {
    if ($s.IndexOf([char]92) -lt 0) { return $s }
    $sb = New-Object System.Text.StringBuilder
    $n = $s.Length
    $i = 0
    while ($i -lt $n) {
        $c = $s[$i]
        if ($c -eq [char]92 -and ($i + 1) -lt $n) {
            $d = $s[$i + 1]
            if ($d -eq 't') { [void]$sb.Append("`t"); $i += 2; continue }
            if ($d -eq 'n') { [void]$sb.Append("`n"); $i += 2; continue }
            if ($d -eq 'r') { [void]$sb.Append("`r"); $i += 2; continue }
            if ($d -eq '\') { [void]$sb.Append('\'); $i += 2; continue }
        }
        [void]$sb.Append($c)
        $i++
    }
    return $sb.ToString()
}

function Get-LangFolders {
    $list = New-Object System.Collections.ArrayList
    $app = ''
    try { $app = Get-AppFolder } catch { $app = '' }
    if ($app -ne '') { [void]$list.Add([System.IO.Path]::Combine($app, 'veri', 'dil')) }
    $pd = ''
    try { $pd = [Environment]::GetFolderPath('CommonApplicationData') } catch { $pd = '' }
    if ($pd -ne '') { [void]$list.Add([System.IO.Path]::Combine($pd, 'Multimizer', 'dil')) }
    return $list.ToArray()
}

# Sablon kimligini ({0} ...) duzenli ifadeye cevirir ve paketin dizinine ekler
function Add-LangTemplate($Pack, [string]$Id, [string]$Out) {
    $parts = [regex]::Split($Id, '\{(\d+)\}')
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append('^')
    $lits = 0
    $longest = ''
    for ($i = 0; $i -lt $parts.Length; $i++) {
        if (($i % 2) -eq 0) {
            $lit = [string]$parts[$i]
            if ($lit.Length -gt $longest.Length) { $longest = $lit }
            # bitisik yer tutucular (ornek "{0}{1}") belirsizdir: sablon olarak eklenmez
            if ($i -gt 0 -and $i -lt ($parts.Length - 1) -and $lit.Length -eq 0) { return }
            $lits += $lit.Trim().Length
            [void]$sb.Append([regex]::Escape($lit))
        } else {
            [void]$sb.Append('(?<g' + [string]$parts[$i] + '>.*?)')
        }
    }
    [void]$sb.Append('\z')
    # tek basina anlam tasimayan sablonlar ("{0}: {1}") her metinle eslesirdi
    if ($lits -lt 2) { return }
    # Duzenli ifade ilk kullanimda kurulur (acilista binlerce sablonu derlemek gereksiz bekletir)
    $rx = $null
    $key = [string]$parts[0]
    if ($key.Length -gt $script:LangKeyLen) { $key = $key.Substring(0, $script:LangKeyLen) }
    $list = $null
    if (-not $Pack.Tpl.TryGetValue($key, [ref]$list)) {
        $list = New-Object System.Collections.ArrayList
        $Pack.Tpl[$key] = $list
    }
    $suf = [string]$parts[$parts.Length - 1]
    [void]$list.Add(@{ Rx = $rx; Src = $sb.ToString(); Out = $Out; W = $lits; Id = $Id; Suf = $suf; Lit = $longest })
    $Pack.NTpl = [int]$Pack.NTpl + 1
}

# Dil dosyasinin metnini okur (ust bilgi + metinler)
function Read-LangPack([string]$Text, [string]$Code) {
    $pack = @{
        Code = $Code
        Map = (New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::Ordinal))
        Tpl = (New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::Ordinal))
        Meta = @{}
        N = 0
        NTpl = 0
    }
    foreach ($ln0 in ($Text -split "`n")) {
        $ln = $ln0
        if ($ln.Length -gt 0 -and $ln[$ln.Length - 1] -eq "`r") { $ln = $ln.Substring(0, $ln.Length - 1) }
        if ($ln.Length -eq 0) { continue }
        if ($ln[0] -eq '#') {
            $m = [regex]::Match($ln, '^#\s*([A-Za-z]+)\s*:\s*(.*)$')
            if ($m.Success) { $pack.Meta[$m.Groups[1].Value.ToLowerInvariant()] = $m.Groups[2].Value.Trim() }
            continue
        }
        $tab = $ln.IndexOf([char]9)
        if ($tab -lt 1) { continue }
        $out = Get-LangUnescaped ($ln.Substring($tab + 1))
        if ($out.Length -eq 0) { continue }
        $id = Get-LangUnescaped ($ln.Substring(0, $tab))
        if ($id.IndexOf([char]123) -ge 0 -and [regex]::IsMatch($id, '\{\d+\}')) { Add-LangTemplate $pack $id $out } else { $pack.Map[$id] = $out }
        $pack.N = [int]$pack.N + 1
    }
    # ayni on ekli sablonlarda uzun (ayrintili) olan once denenir
    foreach ($k in @($pack.Tpl.Keys)) {
        $l = $pack.Tpl[$k]
        if ($l.Count -gt 1) {
            $sorted = @($l | Sort-Object -Property @{ Expression = { -[int]$_.W } })
            $nl = New-Object System.Collections.ArrayList
            foreach ($e in $sorted) { [void]$nl.Add($e) }
            $pack.Tpl[$k] = $nl
        }
    }
    return $pack
}

# Ust bilgi satirlarini okur (dosyanin tamamini yuklemeden)
function Read-LangHeader([string]$Path) {
    $meta = @{}
    $sr = $null
    try {
        $sr = New-Object System.IO.StreamReader($Path, [System.Text.Encoding]::UTF8)
        while ($true) {
            $ln = $sr.ReadLine()
            if ($null -eq $ln) { break }
            if ($ln.Length -eq 0) { continue }
            if ($ln[0] -ne '#') { break }
            $m = [regex]::Match($ln, '^#\s*([A-Za-z]+)\s*:\s*(.*)$')
            if ($m.Success) { $meta[$m.Groups[1].Value.ToLowerInvariant()] = $m.Groups[2].Value.Trim() }
        }
    } catch { } finally { if ($null -ne $sr) { $sr.Dispose() } }
    return $meta
}

# Kullanilabilir diller: Turkce (kaynak) + bulunan dil dosyalari. Ayni kodda kullanici dosyasi uygulama dosyasinin yerine gecer.
# Donus listesi acilir (virgulsuz); cagiran @(Get-LangList) yazar.
function Get-LangList([bool]$Refresh = $false) {
    if (-not $Refresh -and $null -ne $script:LangList) { return $script:LangList }
    $res = New-Object System.Collections.ArrayList
    [void]$res.Add(@{ Code = 'tr'; Native = 'T' + [char]0x00FC + 'rk' + [char]0x00E7 + 'e'; English = 'Turkish'; Rtl = $false; Tag = 'tr-TR'; Match = 'tr'; Path = ''; Coverage = 100; User = $false })
    $byCode = @{}
    $folders = @(Get-LangFolders)
    $isUser = $false
    foreach ($dir in $folders) {
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) { $isUser = $true; continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter '*.lang' -File -ErrorAction SilentlyContinue)) {
            $code = $f.BaseName.ToLowerInvariant()
            if ($code -cnotmatch '^[a-z]{2,3}(-[a-z0-9]{2,8})?$' -or $code -eq 'tr') { continue }
            $h = Read-LangHeader $f.FullName
            $nm = [string]$h['native']
            if ($nm -eq '') { $nm = $code }
            $en = [string]$h['name']
            if ($en -eq '') { $en = $code }
            $rtl = ([string]$h['rtl'] -eq '1')
            $tag = [string]$h['tag']
            if ($tag -eq '') { $tag = $code }
            $mt = [string]$h['match']
            if ($mt -eq '') { $mt = $code }
            $cov = 0
            try { $cov = [int]$h['coverage'] } catch { $cov = 0 }
            $byCode[$code] = @{ Code = $code; Native = $nm; English = $en; Rtl = $rtl; Tag = $tag; Match = $mt.ToLowerInvariant(); Path = $f.FullName; Coverage = $cov; User = $isUser }
        }
        $isUser = $true
    }
    foreach ($k in @($byCode.Keys | Sort-Object)) { [void]$res.Add($byCode[$k]) }
    $script:LangList = $res
    return $res
}

# Bir kulturun (ornek "de-DE", "zh-Hans-CN") en uygun dil kodunu bulur; yoksa ''
function Find-LangForCulture([string]$CultureName) {
    $c = $CultureName.ToLowerInvariant()
    if ($c -eq '') { return '' }
    $best = ''
    $bestLen = 0
    foreach ($l in @(Get-LangList)) {
        foreach ($m in ([string]$l.Match -split ',')) {
            $mm = $m.Trim()
            if ($mm -eq '') { continue }
            if (($c -eq $mm -or $c.StartsWith(($mm + '-'), [System.StringComparison]::Ordinal)) -and $mm.Length -gt $bestLen) { $best = [string]$l.Code; $bestLen = $mm.Length }
        }
    }
    return $best
}

function Get-SystemLangCode {
    $name = ''
    try { $name = [System.Globalization.CultureInfo]::CurrentUICulture.Name } catch { $name = '' }
    $code = Find-LangForCulture $name
    if ($code -ne '') { return $code }
    return 'en'
}

# Ayar degeri (auto | kod) -> kullanilacak dil kodu. Bilinmeyen kod otomatik gibi islenir.
function Resolve-LangCode([string]$Want) {
    $w = $Want.Trim().ToLowerInvariant()
    if ($w -eq '' -or $w -eq 'auto') { $w = Get-SystemLangCode }
    if ($w -eq 'tr') { return 'tr' }
    foreach ($l in @(Get-LangList)) { if ([string]$l.Code -eq $w) { return $w } }
    $c = Find-LangForCulture $w
    if ($c -ne '') { return $c }
    foreach ($l in @(Get-LangList)) { if ([string]$l.Code -eq 'en') { return 'en' } }
    return 'tr'
}

function Import-LangPackFile([string]$Code) {
    foreach ($l in @(Get-LangList)) {
        if ([string]$l.Code -ne $Code -or [string]$l.Path -eq '') { continue }
        try {
            $txt = [System.IO.File]::ReadAllText([string]$l.Path, [System.Text.Encoding]::UTF8)
            return (Read-LangPack $txt $Code)
        } catch {
            try { Write-WhLog ('Dil dosyasi okunamad' + [char]0x0131 + ' (' + $Code + '): ' + $_.Exception.Message) 'WARN' } catch { }
        }
    }
    return $null
}

# Etkin dili ayarlar. 'tr' kaynak dildir (cevri yapilmaz).
function Set-LangActive([string]$Code) {
    $script:LangCache = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::Ordinal)
    $script:LangPrimary = $null
    $script:LangFallback = $null
    $script:LangOn = $false
    $script:LangRtl = $false
    $script:LangPctStyle = 0
    $script:LangUpperCulture = $null
    $script:LangCode = 'tr'
    $script:LangTag = 'tr-TR'
    $script:LangName = 'T' + [char]0x00FC + 'rk' + [char]0x00E7 + 'e'
    if ($Code -eq 'tr') { return }
    $p = Import-LangPackFile $Code
    if ($null -eq $p) { return }
    $script:LangPrimary = $p
    $script:LangCode = $Code
    $script:LangPctStyle = Get-LangPercentStyle $Code
    foreach ($l in @(Get-LangList)) {
        if ([string]$l.Code -eq $Code) { $script:LangRtl = [bool]$l.Rtl; $script:LangTag = [string]$l.Tag; $script:LangName = [string]$l.Native }
    }
    try { $script:LangUpperCulture = [System.Globalization.CultureInfo]::GetCultureInfo([string]$script:LangTag) } catch { $script:LangUpperCulture = $null }
    if ($Code -ne 'en') { $script:LangFallback = Import-LangPackFile 'en' }
    $script:LangOn = $true
}

# Acilista bir kez: komut satiri (-Dil), ortam (MM_DIL), ayar (Language) sirasiyla bakilir
function Initialize-Lang {
    $want = ''
    try { $want = [string]$script:Settings.Language } catch { $want = '' }
    $env1 = ''
    try { $env1 = [string]$env:MM_DIL } catch { $env1 = '' }
    if ($env1 -ne '') { $want = $env1 }
    $arg = ''
    try { $arg = [string]$Dil } catch { $arg = '' }
    if ($arg -ne '') { $want = $arg }
    $code = 'tr'
    try { $code = Resolve-LangCode $want } catch { $code = 'tr' }
    try { Set-LangActive $code } catch { $script:LangOn = $false }
    $tr = ''
    try { $tr = [string]$env:MM_DIL_IZLE } catch { $tr = '' }
    if ($tr -eq '1' -and $script:LangOn) { Enable-LangTrack }
}

function Enable-LangTrack {
    $script:LangTrack = $true
    $script:LangMiss = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::Ordinal)
    $script:LangSeen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    $script:LangOut = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
}

function Find-LangIn($Pack, [string]$s, [int]$Depth) {
    $v = $null
    if ($Pack.Map.TryGetValue($s, [ref]$v)) { return $v }
    # bastaki ve sondaki bosluklar korunur
    $ls = $s.Length - $s.TrimStart().Length
    $te = $s.Length - $s.TrimEnd().Length
    if (($ls + $te) -gt 0 -and ($ls + $te) -lt $s.Length) {
        $core = $s.Substring($ls, $s.Length - $ls - $te)
        if ($Pack.Map.TryGetValue($core, [ref]$v)) { return ($s.Substring(0, $ls) + $v + $s.Substring($s.Length - $te)) }
    }
    if ($Pack.NTpl -gt 0 -and $Depth -lt 4) {
        $max = $s.Length
        if ($max -gt $script:LangKeyLen) { $max = $script:LangKeyLen }
        for ($n = 0; $n -le $max; $n++) {
            $list = $null
            if ($Pack.Tpl.TryGetValue($s.Substring(0, $n), [ref]$list)) {
                foreach ($e in $list) {
                    if ($e.Suf.Length -gt 0 -and -not $s.EndsWith($e.Suf, [System.StringComparison]::Ordinal)) { continue }
                    if ($e.Lit.Length -gt 1 -and $s.IndexOf($e.Lit, [System.StringComparison]::Ordinal) -lt 0) { continue }
                    $rx = $e.Rx
                    if ($null -eq $rx) {
                        try { $rx = New-Object System.Text.RegularExpressions.Regex([string]$e.Src, [System.Text.RegularExpressions.RegexOptions]::Singleline) } catch { $rx = $false }
                        $e.Rx = $rx
                    }
                    if ($rx -is [bool]) { continue }
                    $m = $rx.Match($s)
                    if ($m.Success) { return (Format-LangTemplate $e $m $Depth) }
                }
            }
        }
    }
    return $null
}

# Sablonun yer tutucularini yakalanan parcalarla (onlar da cevrilerek) doldurur
function Format-LangTemplate($E, $M, [int]$Depth) {
    $out = [string]$E.Out
    $sb = New-Object System.Text.StringBuilder
    $pos = 0
    foreach ($x in [regex]::Matches($out, '\{(\d+)\}')) {
        [void]$sb.Append($out.Substring($pos, $x.Index - $pos))
        $g = $M.Groups['g' + $x.Groups[1].Value]
        if ($g.Success) {
            $part = [string]$g.Value
            $tp = $null
            if ($part.Length -ge 2) { $tp = Find-LangText $part ($Depth + 1) }
            if ($null -ne $tp) { [void]$sb.Append($tp) } else { [void]$sb.Append($part) }
        } else { [void]$sb.Append($x.Value) }
        $pos = $x.Index + $x.Length
    }
    [void]$sb.Append($out.Substring($pos))
    return $sb.ToString()
}

# Yalnizca kayitli ceviriler: birebir, bastaki/sondaki bosluk ve sablon (secili dil, sonra Ingilizce yedek)
function Find-LangDirect([string]$s, [int]$Depth) {
    $r = $null
    if ($null -ne $script:LangPrimary) { $r = Find-LangIn $script:LangPrimary $s $Depth; if ($null -ne $r) { return $r } }
    if ($null -ne $script:LangFallback) { $r = Find-LangIn $script:LangFallback $s $Depth; if ($null -ne $r) { return $r } }
    return $null
}

# Cumle sonu ve ayirac noktalama: Cince ve Japoncada tam genislikli isaretler kullanilir
function Get-LangPunct([string]$P) {
    $c = [string]$script:LangCode
    if ($c -eq 'zh' -or $c -eq 'zh-hant' -or $c -eq 'ja') {
        if ($P -eq '.') { return [string][char]0x3002 }
        if ($P -eq ';') { return [string][char]0xFF1B }
    }
    return $P
}

# Metnin cevirisini bulur; yoksa $null. Sonucun eksiksiz cevrilip cevrilmedigi $script:LangFull'a yazilir:
# kayitli (birebir, bosluk, sablon) ceviri eksiksizdir; parcalara bolunerek bulunan ceviri ancak cevrilmesi gereken her parca bulunduysa eksiksizdir.
# Birden cok bolme yolu varsa ilk eksiksiz sonuc doner; hicbiri eksiksiz degilse ilk kismi sonuc doner.
function Find-LangText([string]$s, [int]$Depth) {
    $script:LangFull = $true
    $r = Find-LangDirect $s $Depth
    if ($null -ne $r) { return $r }
    $script:LangFull = $false
    if ($Depth -ge 3 -or $s.Length -lt 2) { return $null }
    $nd = $Depth + 1
    $best = $null
    $res = $null
    $tf = $false
    $n1 = $s.Length

    # yalnizca buyuk/kucuk harf farki olan metin ("Yedek ve Kurtarma" / "Yedek ve kurtarma" / "YEDEK VE KURTARMA")
    if ($n1 -ge 3 -and $n1 -le 160 -and $s.IndexOf([char]10) -lt 0) {
        $fz = Find-LangFolded $s
        if ($null -ne $fz) {
            if ($script:LangUpperRx.IsMatch($s) -and -not $script:LangLowerRx.IsMatch($s)) { $fz = Convert-LangUpper $fz }
            $script:LangFull = $true
            return $fz
        }
    }

    # cok satirli metin: her satir ayri cevrilir
    if ($s.IndexOf([char]10) -ge 0) {
        $lines = $s -split "`n"
        $any = $false
        $all = $true
        $outl = New-Object System.Collections.ArrayList
        foreach ($ln in $lines) {
            $core = $ln
            $cr = ''
            if ($core.Length -gt 0 -and $core[$core.Length - 1] -eq [char]13) { $core = $core.Substring(0, $core.Length - 1); $cr = "`r" }
            $t = $null
            if ($core.Length -ge 2) { $t = Find-LangText $core $nd; $tf = $script:LangFull }
            if ($null -ne $t) { $any = $true; if (-not $tf) { $all = $false }; [void]$outl.Add($t + $cr) }
            else { if ($script:LangLetterRx.IsMatch($core)) { $all = $false }; [void]$outl.Add($ln) }
        }
        if ($any) {
            $res = ($outl.ToArray() -join "`n")
            if ($all) { $script:LangFull = $true; return $res }
            if ($null -eq $best) { $best = $res }
        }
    }
    if ($n1 -gt 700) { return $best }

    # "Parca  .  Parca" biciminde birlesik metin (etiket + kategori gibi): her parca ayri cevrilir
    if ($s.IndexOf([char]0x00B7) -ge 0) {
        foreach ($sep in @(('  ' + [char]0x00B7 + '  '), (' ' + [char]0x00B7 + ' '))) {
            if ($s.IndexOf($sep, [System.StringComparison]::Ordinal) -lt 0) { continue }
            $segs = $s.Split(@($sep), [System.StringSplitOptions]::None)
            if ($segs.Count -lt 2) { continue }
            $anySeg = $false
            $allSeg = $true
            $outSeg = New-Object System.Collections.ArrayList
            foreach ($sg in $segs) {
                $ts = $null
                if ($sg.Length -ge 2) { $ts = Find-LangText $sg $nd; $tf = $script:LangFull }
                if ($null -ne $ts) { $anySeg = $true; if (-not $tf) { $allSeg = $false }; [void]$outSeg.Add($ts) }
                else { if ($script:LangLetterRx.IsMatch($sg)) { $allSeg = $false }; [void]$outSeg.Add($sg) }
            }
            if ($anySeg) {
                $res = ($outSeg.ToArray() -join $sep)
                if ($allSeg) { $script:LangFull = $true; return $res }
                if ($null -eq $best) { $best = $res }
            }
            break
        }
    }

    # onek isareti (">>> ", "->  " gibi): onek korunur, kalan metin cevrilir
    $pm = $script:LangPrefixRx.Match($s)
    if ($pm.Success -and $pm.Groups[2].Value.Length -ge 2) {
        $tp = Find-LangText $pm.Groups[2].Value $nd
        $tf = $script:LangFull
        if ($null -ne $tp) {
            $res = $pm.Groups[1].Value + $tp
            if ($tf) { $script:LangFull = $true; return $res }
            if ($null -eq $best) { $best = $res }
        }
    }

    # "SS:DD:SS  SEVIYE  ileti" gunluk satiri: yalnizca ileti cevrilir
    if ($n1 -ge 14 -and $s[2] -eq ':' -and $s[5] -eq ':') {
        $lm = $script:LangLogRx.Match($s)
        if ($lm.Success) {
            $lt = Find-LangText $lm.Groups[2].Value $nd
            $tf = $script:LangFull
            if ($null -ne $lt) {
                $res = $lm.Groups[1].Value + $lt
                if ($tf) { $script:LangFull = $true; return $res }
                if ($null -eq $best) { $best = $res }
            }
        }
    }

    # "metin  [not]" biciminde sona eklenmis koseli parantezli not: metin ve not parcalari ayri cevrilir
    if ($s[$n1 - 1] -eq ']' -and $s.IndexOf('  [', [System.StringComparison]::Ordinal) -gt 0) {
        $bm = $script:LangBracketRx.Match($s)
        if ($bm.Success) {
            $hd = $bm.Groups[1].Value
            $tg = $bm.Groups[2].Value
            $hdT = Find-LangText $hd $nd
            $hf = $script:LangFull
            $tgT = Find-LangTag $tg $nd
            $gf = $script:LangFull
            if ($null -ne $hdT -or $null -ne $tgT) {
                $full = ($null -ne $hdT -and $hf -and $null -ne $tgT -and $gf)
                if ($null -eq $hdT) { $hdT = $hd }
                if ($null -eq $tgT) { $tgT = $tg }
                $res = ($hdT + '  [' + $tgT + ']')
                if ($full) { $script:LangFull = $true; return $res }
                if ($null -eq $best) { $best = $res }
            }
        }
    }

    # "sol " + ok + " sag" biciminde kural ya da yonlendirme: iki yan ayri cevrilir
    $arrow = ' ' + [char]0x2192 + ' '
    $ai = $s.IndexOf($arrow, [System.StringComparison]::Ordinal)
    if ($ai -gt 0 -and $ai + 3 -lt $n1) {
        $la = $s.Substring(0, $ai)
        $ra = $s.Substring($ai + 3)
        $laT = $null; $raT = $null; $lf = $true; $rf = $true
        if ($la.Length -ge 2) { $laT = Find-LangText $la $nd; $lf = $script:LangFull }
        if ($ra.Length -ge 2) { $raT = Find-LangText $ra $nd; $rf = $script:LangFull }
        if ($null -ne $laT -or $null -ne $raT) {
            $full = ($null -ne $laT -and $lf -and $null -ne $raT -and $rf)
            if ($null -eq $laT) { $laT = $la }
            if ($null -eq $raT) { $raT = $ra }
            $res = ($laT + $arrow + $raT)
            if ($full) { $script:LangFull = $true; return $res }
            if ($null -eq $best) { $best = $res }
        }
    }

    # cumle sonundaki nokta: nokta olmadan kayitli metin bulunursa sonuna dilin cumle sonu isareti eklenir
    if ($n1 -ge 4 -and $s[$n1 - 1] -eq '.' -and $s[$n1 - 2] -ne '.') {
        $tp = Find-LangText $s.Substring(0, $n1 - 1) $nd
        $tf = $script:LangFull
        if ($null -ne $tp) {
            $res = $tp
            $lc = [int]$tp[$tp.Length - 1]
            if ($lc -ne 46 -and $lc -ne 33 -and $lc -ne 63 -and $lc -ne 0x2026 -and $lc -ne 0x3002 -and $lc -ne 0xFF01 -and $lc -ne 0xFF1F) { $res = $tp + (Get-LangPunct '.') }
            if ($tf) { $script:LangFull = $true; return $res }
            if ($null -eq $best) { $best = $res }
        }
    }

    # "Metin (3)" ya da "Metin (not)" biciminde parantezli ek: metin ve (sayi degilse) ek cevrilir, sayac korunur
    if ($n1 -ge 6 -and $s[$n1 - 1] -eq ')') {
        $cm = $script:LangCountRx.Match($s)
        if ($cm.Success) {
            $hdc = Find-LangText $cm.Groups[1].Value $nd
            $hcf = $script:LangFull
            $tl = $cm.Groups[2].Value
            $tlT = $null
            if ($tl.Length -ge 3 -and -not [char]::IsDigit($tl[0])) { $tlT = Find-LangTag $tl $nd }
            if ($null -ne $hdc -or $null -ne $tlT) {
                $full = ($null -ne $hdc -and $hcf)
                if ($null -eq $hdc) { $hdc = $cm.Groups[1].Value }
                if ($null -eq $tlT) { $tlT = $tl }
                $res = ($hdc + ' (' + $tlT + ')')
                if ($full) { $script:LangFull = $true; return $res }
                if ($null -eq $best) { $best = $res }
            }
        }
    }

    # "Metin..." biciminde sonu uc nokta olan ilerleme metni
    if ($n1 -ge 6) {
        $el = ''
        if ($s.EndsWith('...', [System.StringComparison]::Ordinal)) { $el = '...' } elseif ($s[$n1 - 1] -eq [char]0x2026) { $el = [string][char]0x2026 }
        if ($el.Length -gt 0) {
            $hde = Find-LangText $s.Substring(0, $n1 - $el.Length) $nd
            $tf = $script:LangFull
            if ($null -ne $hde) {
                $res = $hde + $el
                if ($tf) { $script:LangFull = $true; return $res }
                if ($null -eq $best) { $best = $res }
            }
        }
    }

    # "Etiket: deger" ya da "Ad: aciklama": etiket cevrilir (iki nokta ile ya da iki noktasiz kayitli olabilir), kalan metin bulunabilirse cevrilir
    if ($n1 -ge 6) {
        $ci = $s.IndexOf(': ', [System.StringComparison]::Ordinal)
        $guard = 0
        while ($ci -gt 1 -and $ci + 2 -lt $n1 -and $guard -lt 3) {
            $guard++
            $labT = Find-LangDirect $s.Substring(0, $ci + 1) $nd
            if ($null -eq $labT) {
                $labN = Find-LangText $s.Substring(0, $ci) $nd
                if ($null -ne $labN -and $script:LangFull) { $labT = $labN + ':' }
            }
            if ($null -ne $labT) {
                $rest = $s.Substring($ci + 2)
                $restT = $null
                $rf = $false
                if ($rest.Length -ge 2) { $restT = Find-LangText $rest $nd; $rf = $script:LangFull }
                $full = ($null -ne $restT -and $rf)
                if ($null -eq $restT) { $restT = $rest }
                $glue = ' '
                if ($labT[$labT.Length - 1] -eq [char]0xFF1A) { $glue = '' }
                $res = ($labT + $glue + $restT)
                if ($full) { $script:LangFull = $true; return $res }
                if ($null -eq $best) { $best = $res }
                break
            }
            $ci = $s.IndexOf(': ', $ci + 2, [System.StringComparison]::Ordinal)
        }
    }

    # birden cok cumleden ya da ";" ile ayrilmis parcalardan olusan metin: her parca (ya da ardisik parcalar) ayri cevrilir
    if ($n1 -ge 14) {
        $jr = Find-LangJoined $s '. ' $Depth
        $jf = $script:LangFull
        if ($null -ne $jr) {
            if ($jf) { $script:LangFull = $true; return $jr }
            if ($null -eq $best) { $best = $jr }
        }
        if ($s.IndexOf('; ', [System.StringComparison]::Ordinal) -gt 0) {
            $jr = Find-LangJoined $s '; ' $Depth
            $jf = $script:LangFull
            if ($null -ne $jr) {
                if ($jf) { $script:LangFull = $true; return $jr }
                if ($null -eq $best) { $best = $jr }
            }
        }
    }

    # TAMAMI BUYUK HARFLI baslik ("YEDEK VE KURTARMA"): kucuk harfli karsiligi cevrilir, sonuc buyuk harfe cevrilir
    if ($n1 -ge 3 -and $n1 -le 80 -and $script:LangUpperRx.IsMatch($s) -and -not $script:LangLowerRx.IsMatch($s)) {
        $lo = Convert-LangTrLower $s
        $up = Find-LangText (Convert-LangTrUpperFirst $lo) $nd
        $uf = $script:LangFull
        if ($null -eq $up) { $up = Find-LangText $lo $nd; $uf = $script:LangFull }
        if ($null -ne $up) {
            $res = Convert-LangUpper $up
            if ($uf) { $script:LangFull = $true; return $res }
            if ($null -eq $best) { $best = $res }
        }
    }
    $script:LangFull = $false
    return $best
}

# Ayiracla (". " ya da "; ") birlestirilmis parcalari cevirir. Her konumda once en uzun ardisik parca grubu aranir
# (kataloga birden cok cumleli metin olarak girmis olabilir); bulunamayan parca oldugu gibi kalir.
function Find-LangJoined([string]$s, [string]$Sep, [int]$Depth) {
    $script:LangFull = $false
    $parts = $s.Split(@($Sep), [System.StringSplitOptions]::None)
    $n = $parts.Count
    if ($n -lt 2 -or $n -gt 14) { return $null }
    $punct = $Sep.Substring(0, 1)
    $pOut = Get-LangPunct $punct
    $outp = New-Object System.Collections.ArrayList
    $any = $false
    $all = $true
    $i = 0
    while ($i -lt $n) {
        $hit = $null
        $hitJ = $i
        $hitFull = $false
        for ($j = $n - 1; $j -ge $i; $j--) {
            if ($i -eq 0 -and $j -eq $n - 1) { continue }
            $core = ($parts[$i..$j] -join $Sep)
            $last = ($j -eq $n - 1)
            $multi = ($j -gt $i)
            $t = $null
            $tfull = $true
            if (-not $last) {
                if ($multi) { $t = Find-LangDirect ($core + $punct) ($Depth + 1) } else { $t = Find-LangText ($core + $punct) ($Depth + 1); $tfull = $script:LangFull }
            }
            if ($null -eq $t -and $core.Length -ge 3) {
                $t0 = $null
                if ($multi) { $t0 = Find-LangDirect $core ($Depth + 1); $tfull = $true } else { $t0 = Find-LangText $core ($Depth + 1); $tfull = $script:LangFull }
                if ($null -ne $t0) {
                    $t = $t0
                    if (-not $last) {
                        $lc = [int]$t0[$t0.Length - 1]
                        if ($lc -ne [int]$punct[0] -and $lc -ne [int]$pOut[0]) { $t = $t0 + $pOut }
                    }
                }
            }
            if ($null -ne $t) { $hit = $t; $hitJ = $j; $hitFull = $tfull; break }
        }
        if ($null -ne $hit) {
            $any = $true
            if (-not $hitFull) { $all = $false }
            [void]$outp.Add($hit)
            $i = $hitJ + 1
        } else {
            $own = $parts[$i]
            if ($i -lt $n - 1) { $own = $own + $punct }
            if ($script:LangLetterRx.IsMatch($own)) { $all = $false }
            [void]$outp.Add($own)
            $i++
        }
    }
    if (-not $any) { $script:LangFull = $false; return $null }
    $script:LangFull = $all
    return ($outp.ToArray() -join ' ')
}

# Turkce buyuk/kucuk harf donusumu (kulturden bagimsiz): I -> dotless i, dotted I -> i
function Convert-LangTrLower([string]$s) {
    return $s.Replace([string][char]0x0130, 'i').Replace('I', [string][char]0x0131).ToLowerInvariant()
}

function Convert-LangTrUpperFirst([string]$s) {
    if ($s.Length -eq 0) { return $s }
    $c = [int]$s[0]
    $u = ([string]$s[0]).ToUpperInvariant()
    if ($c -eq 105) { $u = [string][char]0x0130 } elseif ($c -eq 0x0131) { $u = 'I' }
    return ($u + $s.Substring(1))
}

# Buyuk/kucuk harfi farkli yazilmis metinler icin kucuk harfe indirilmis dizin (ilk kullanimda kurulur): secili dil, sonra Ingilizce yedek
function Find-LangFolded([string]$s) {
    $k = Convert-LangTrLower $s.Trim()
    if ($k.Length -lt 3) { return $null }
    foreach ($p in @($script:LangPrimary, $script:LangFallback)) {
        if ($null -eq $p) { continue }
        if ($null -eq $p.Fold) {
            $f = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::Ordinal)
            foreach ($kv in $p.Map.GetEnumerator()) {
                $lk = Convert-LangTrLower ([string]$kv.Key)
                if (-not $f.ContainsKey($lk)) { $f[$lk] = [string]$kv.Value }
            }
            $p.Fold = $f
        }
        $v = $null
        if ($p.Fold.TryGetValue($k, [ref]$v)) { return $v }
    }
    return $null
}

# Cevrilen basligi etkin dilin kulturune gore buyuk harfe cevirir (Cince, Japonca, Arapca gibi buyuk/kucuk harfi olmayan dillerde degismez)
function Convert-LangUpper([string]$s) {
    $cu = $script:LangUpperCulture
    if ($null -eq $cu) { return $s.ToUpperInvariant() }
    return $s.ToUpper($cu)
}

# Koseli parantez ici not: butun olarak, yoksa ", " ile ayrilmis parcalar halinde cevrilir
function Find-LangTag([string]$s, [int]$Depth) {
    $r = Find-LangText $s $Depth
    if ($null -ne $r) { return $r }
    $script:LangFull = $false
    if ($Depth -ge 3) { return $null }
    $i = $s.IndexOf(', ', [System.StringComparison]::Ordinal)
    while ($i -gt 0) {
        $left = $s.Substring(0, $i)
        $lt = Find-LangText $left ($Depth + 1)
        $lf = $script:LangFull
        if ($null -ne $lt) {
            $right = $s.Substring($i + 2)
            $rt = Find-LangTag $right ($Depth + 1)
            $rf = $script:LangFull
            if ($null -eq $rt) { $rt = $right; $rf = $false }
            $script:LangFull = ($lf -and $rf)
            return ($lt + ', ' + $rt)
        }
        $i = $s.IndexOf(', ', $i + 2, [System.StringComparison]::Ordinal)
    }
    $script:LangFull = $false
    return $null
}

function Add-LangMiss([string]$s) {
    if ($null -eq $script:LangMiss) { return }
    if (-not [regex]::IsMatch($s, '[^\W\d_]{2}')) { return }
    # daha once cevrilmis bir ciktinin yeniden Tr'den gecmesi eksik sayilmaz
    if ($null -ne $script:LangOut -and $script:LangOut.Contains($s)) { return }
    # boyut, hiz, sicaklik gibi yalnizca olcu degeri olan ve dosya yolu olan metinler cevrilmez
    if ([regex]::IsMatch($s, '^[\d.,\s]+(?:[KMGT]i?B(?:/s)?|[Mm]b/s|[Kk]b/s|%|ms|s|MHz|GHz|W|V|rpm)$')) { return }
    if ([regex]::IsMatch($s, '^[A-Za-z]:\\')) { return }
    $n = 0
    if ($script:LangMiss.TryGetValue($s, [ref]$n)) { $script:LangMiss[$s] = $n + 1 } else { $script:LangMiss[$s] = 1 }
}

# Yuzde yazimi: Turkcede "%40"; Almanca, Fransizca, Ispanyolca, Rusca gibi dillerde "40 %" (bolunmez bosluk),
# Ingilizce, Cince, Japonca, Arapca gibi dillerde "40%"
$script:LangPctRx = New-Object System.Text.RegularExpressions.Regex(('(?<![\p{L}\p{N}\\/%._])%(\d+(?:[.,]\d+)?)(?![\p{L}\p{N}\x27' + [char]0x2019 + '])'))

function Get-LangPercentStyle([string]$Code) {
    $c = $Code.ToLowerInvariant()
    $i = $c.IndexOf('-')
    if ($i -gt 0) { $c = $c.Substring(0, $i) }
    if ($c -eq 'tr') { return 0 }
    foreach ($x in @('de', 'fr', 'es', 'ru', 'pl', 'cs', 'sk', 'sl', 'hr', 'sr', 'bg', 'uk', 'sv', 'nb', 'no', 'da', 'fi', 'nl', 'hu', 'ro', 'el', 'lt', 'lv', 'et')) {
        if ($c -eq $x) { return 2 }
    }
    return 1
}

function Convert-LangPercent([string]$s) {
    if ([int]$script:LangPctStyle -eq 0 -or $s.IndexOf('%') -lt 0) { return $s }
    $rep = '${1}%'
    if ([int]$script:LangPctStyle -eq 2) { $rep = '${1}' + [string][char]0x00A0 + '%' }
    return $script:LangPctRx.Replace($s, $rep)
}

# Sayisal degeri etkin dilin yuzde bicimiyle yazar: Format-Percent 40 -> %40 / 40% / 40 %
function Format-Percent($V) { return (Convert-LangPercent ('%' + [string]$V)) }

# Sagdan sola dillerde yalnizca Latin harf ve rakamdan olusan cok sozcuklu metinler (surum, birim, donanim adi gibi)
# sozcuk sirasi ters dizilir ("Windows 11 Home" -> "Home 11 Windows"); soldan saga isaretiyle (LRM) sarilarak duzeltilir
$script:LangBidiRx = New-Object System.Text.RegularExpressions.Regex(('[' + [char]0x0590 + '-' + [char]0x08FF + '' + [char]0xFB1D + '-' + [char]0xFDFF + '' + [char]0xFE70 + '-' + [char]0xFEFF + ']'))

function Convert-LangBidi([string]$s) {
    if ($s.Length -lt 3 -or $s.Length -gt 600) { return $s }
    $c0 = $s[0]
    if ($c0 -eq [char]0x200E -or $c0 -eq [char]0x200F) { return $s }
    if ($script:LangBidiRx.IsMatch($s)) { return $s }
    if (-not [regex]::IsMatch($s, '[A-Za-z0-9]')) { return $s }
    if (-not [regex]::IsMatch($s, '[\s.:;!?)\]]')) { return $s }
    return ([string][char]0x200E + $s + [string][char]0x200E)
}

# Arayuz metnini etkin dile cevirir. Turkce secili ya da metin dize degilse oldugu gibi doner.
function Tr($Text) {
    if (-not $script:LangOn) { return $Text }
    if ($Text -isnot [string]) { return $Text }
    $s = [string]$Text
    if ($s.Length -lt 2) { return $s }
    $c = $script:LangCache
    $hit = $null
    if (-not $script:LangTrack -and $null -ne $c -and $c.TryGetValue($s, [ref]$hit)) { return $hit }
    $r = Find-LangText $s 0
    if ($null -ne $r) {
        if ($r.IndexOf('%') -ge 0) { $r = Convert-LangPercent $r }
        if ($script:LangRtl) { $r = Convert-LangBidi $r }
        if ($script:LangTrack) { if (-not $script:LangFull -and [regex]::IsMatch($r, '[\u011F\u0131\u0130\u015E\u015F\u011E]')) { Add-LangMiss $s }; [void]$script:LangSeen.Add($r); [void]$script:LangOut.Add($r) } elseif ($null -ne $c -and $s.Length -le 400) { if ($c.Count -ge 20000) { $c.Clear() }; $c[$s] = $r }
        return $r
    }
    $s2 = $s
    if ($s.IndexOf('%') -ge 0) { $s2 = Convert-LangPercent $s2 }
    if ($script:LangRtl) { $s2 = Convert-LangBidi $s2 }
    if ($script:LangTrack) { Add-LangMiss $s; [void]$script:LangSeen.Add($s2) } elseif ($null -ne $c -and $s.Length -le 400) { if ($c.Count -ge 20000) { $c.Clear() }; $c[$s] = $s2 }
    return $s2
}

# Cevirili metne ornekle degerler koyar: Format-Tr 'Silindi: {0} dosya' 5
function Format-Tr([string]$Id, $Args0 = $null, $Args1 = $null, $Args2 = $null) {
    $t = Tr $Id
    $vals = @($Args0, $Args1, $Args2)
    for ($i = 0; $i -lt 3; $i++) {
        if ($t.Contains('{' + [string]$i + '}')) { $t = $t.Replace('{' + [string]$i + '}', [string]$vals[$i]) }
    }
    return $t
}

# ---------------- XAML ----------------
# Metin ozniteliklerinin degerlerini cevirir ("{" ile baslayan baglamalar ve @@Yer@@ tutucular dokunulmaz)
$script:LangXamlRx = New-Object System.Text.RegularExpressions.Regex('(\b(?:Text|Content|ToolTip|Header|Title|Watermark)=")([^"]*)(")')

function ConvertTo-XamlAttr([string]$s) {
    $e = $s.Replace('&', '&amp;').Replace('<', '&lt;').Replace('"', '&quot;')
    if ($e.IndexOf([char]10) -ge 0 -or $e.IndexOf([char]13) -ge 0 -or $e.IndexOf([char]9) -ge 0) { $e = $e.Replace("`r", '&#13;').Replace("`n", '&#10;').Replace("`t", '&#9;') }
    return $e
}

function Convert-XamlText([string]$Xaml) {
    if (-not $script:LangOn) { return $Xaml }
    $sb = New-Object System.Text.StringBuilder
    $pos = 0
    foreach ($m in $script:LangXamlRx.Matches($Xaml)) {
        $val = $m.Groups[2].Value
        if ($val.Length -lt 2 -or $val[0] -eq [char]123 -or $val.Contains('@@')) { continue }
        $plain = [System.Net.WebUtility]::HtmlDecode($val)
        $tr = Tr $plain
        if ([string]$tr -ceq $plain) { continue }
        [void]$sb.Append($Xaml.Substring($pos, $m.Groups[2].Index - $pos))
        [void]$sb.Append((ConvertTo-XamlAttr ([string]$tr)))
        $pos = $m.Groups[2].Index + $m.Groups[2].Length
    }
    if ($pos -eq 0) { return $Xaml }
    [void]$sb.Append($Xaml.Substring($pos))
    return $sb.ToString()
}

# Pencerenin dil etiketi (yazi tipi secimi icin) ve yazim yonu
function Set-WindowLanguage($Win) {
    if ($null -eq $Win -or -not $script:LangOn) { return }
    try { $Win.Language = [System.Windows.Markup.XmlLanguage]::GetLanguage($script:LangTag) } catch { }
    if ($script:LangRtl) { try { $Win.FlowDirection = [System.Windows.FlowDirection]::RightToLeft } catch { } }
}

# XAML metnini ceviri uygulayarak nesneye cevirir (XamlReader.Parse yerine kullanilir)
function Read-LocalXaml([string]$Xaml) {
    $x = $Xaml
    if ($script:LangOn) { $x = Convert-XamlText $Xaml }
    $obj = [System.Windows.Markup.XamlReader]::Parse($x)
    if ($script:LangOn -and $obj -is [System.Windows.Window]) { Set-WindowLanguage $obj }
    return , $obj
}

# ---------------- gunluk satiri ----------------
# "SS:DD:SS  SEVIYE  ileti" bicimindeki satirda yalnizca ileti cevrilir
function Convert-LogLineText([string]$Line) {
    if (-not $script:LangOn -or $Line.Length -lt 14) { return $Line }
    $m = [regex]::Match($Line, '^(\d\d:\d\d:\d\d\s+\S+\s+)(.+)$')
    if ($m.Success) { return ($m.Groups[1].Value + (Tr $m.Groups[2].Value)) }
    return (Tr $Line)
}

# ---------------- kalite denetimi ----------------
function Save-LangMiss {
    if ($null -eq $script:LangMiss) { return '' }
    $path = Join-Path ([System.IO.Path]::GetTempPath()) 'Multimizer-dil-eksik.txt'
    $sb = New-Object System.Text.StringBuilder
    foreach ($k in @($script:LangMiss.Keys | Sort-Object)) {
        [void]$sb.Append([string]$script:LangMiss[$k] + "`t" + $k.Replace('\', '\\').Replace("`t", '\t').Replace("`r", '\r').Replace("`n", '\n') + "`r`n")
    }
    [System.IO.File]::WriteAllText($path, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
    return $path
}

# ---------------- ayarlari sifirla: cekirdek ----------------
# ==================================================================
#  AYARLARI SIFIRLA (cekirdek): uygulama tercihlerini varsayilana dondurur
#  Beyaz liste: yalnizca asagidaki anahtarlar sifirlanir. Windows uzerinde yapilan degisiklikler, zamanlanmis gorevler, yedekleme ayarlari,
#  ag koruma durumu, uygulanan duzeltme kayitlari, guncelleme adresi ve kuruluma ait bilgi korunur (listede olmayan anahtara dokunulmaz;
#  yeni eklenen bir ayar, listeye yazilmadikca sifirlanmaz).
#  Her sifirlamadan once ayarlarin bir kopyasi ProgramData\Multimizer\AyarYedekleri klasorune yazilir (en yeni 10 kopya tutulur);
#  "Son sifirlamayi geri al" bu kopyayi geri yukler. Kopya yazilamazsa sifirlama yapilmaz.
#  Bu dosya arayuze dokunmaz; Ayarlar sayfasindaki kart ve komut satiri (-Gorev AyarSifirla) bu islevleri cagirir.
# ==================================================================

# Gorunum kapsami: tema, yerlesim, yakinlastirma, tasarim ve ayrintilari, ana ekran bicimi, saydamlik, hareket, kaydirma, odak halkasi, mini izleyici konumu
$script:ResetLookKeys = @('Theme', 'Layout', 'Zoom', 'Design', 'HomeMode', 'DsNav', 'DsRadius', 'DsFont', 'DsGraph', 'DsSkin', 'Backdrop', 'WinOpacity', 'ReduceMotion', 'SmoothScroll', 'ToTopButton', 'FullDesc', 'FocusRing', 'TouchTargets', 'WidgetCorner', 'WidgetOpacity', 'WidgetX', 'WidgetY')
# Tercihler kapsami: gorunume ek olarak dil, kullanim kipi, bildirim, tepsi, izleme, gunluk, guvenli silme ve ana ekran pano duzeni
$script:ResetPrefKeys = @('Language', 'Mode', 'ExpertConfirm', 'RestorePoint', 'HideConsole', 'TrayMinimize', 'TrayOnMinimize', 'TrayHints', 'Notify', 'MonitorSec', 'MonGpu', 'KeepLogDays', 'WipePasses', 'DebugLog', 'Board', 'BoardCustom')

# Her sey kapsami: bu anahtarlar DISINDAKI tum ayarlar varsayilana doner (kurulum bilgisi ve gecis isaretleri korunur)
$script:ResetKeepKeys = @('Installed', 'LookVersion', 'LookNotice', 'FixLevel', 'PrepSeen', 'UpdateUrl', 'Org', 'Contact', 'ManagedOverride')

# 'Gorunum' | 'Tercihler' | 'Fabrika' | '' (tanimsiz). Komut satiri degeri de buradan gecer.
function ConvertTo-ResetScope([string]$Name) {
    $v = ([string]$Name).Trim().ToLowerInvariant()
    if ($v -eq '' -or $v -eq 'gorunum' -or $v -eq 'look') { return 'Gorunum' }
    if ($v -eq 'fabrika' -or $v -eq 'hersey' -or $v -eq 'factory') { return 'Fabrika' }
    if ($v -eq 'tercihler' -or $v -eq 'tumu' -or $v -eq 'hepsi' -or $v -eq 'all') { return 'Tercihler' }
    return ''
}

# Kapsamdaki anahtarlar (Gorunum ya da Tercihler = gorunum + tercihler)
function Get-ResetKeyList([string]$Scope) {
    $k = New-Object System.Collections.ArrayList
    if ($Scope -eq 'Fabrika') {
        foreach ($x in @((Get-DefaultSettings).Keys | Sort-Object)) { if ($script:ResetKeepKeys -notcontains [string]$x) { [void]$k.Add([string]$x) } }
        return $k.ToArray()
    }
    foreach ($x in $script:ResetLookKeys) { [void]$k.Add([string]$x) }
    if ($Scope -eq 'Tercihler') { foreach ($x in $script:ResetPrefKeys) { [void]$k.Add([string]$x) } }
    return $k.ToArray()
}

# Bir ayar degerinin karsilastirma imzasi (dizi ve tablo degerleri icin de calisir)
function Get-ValueSig($V) {
    try { return [string](ConvertTo-Json -InputObject $V -Compress -Depth 6) } catch { return [string]$V }
}

# Saf: ayar tablosunun sifirlanmis kopyasini ve degisen anahtarlarin listesini verir; dosyaya ve bellege dokunmaz.
# Donus: @{ Settings; Changed; Scope }
function Get-ResetResult($Current, [string]$Scope) {
    $def = Get-DefaultSettings
    $new = @{}
    foreach ($k in @($Current.Keys)) { $new[[string]$k] = $Current[$k] }
    $changed = New-Object System.Collections.ArrayList
    foreach ($k in @(Get-ResetKeyList $Scope)) {
        if (-not $def.ContainsKey($k)) { continue }
        $same = $false
        if ($new.ContainsKey($k)) { $same = ((Get-ValueSig $new[$k]) -ceq (Get-ValueSig $def[$k])) }
        if (-not $same) { [void]$changed.Add([string]$k) }
        $new[$k] = $def[$k]
    }
    # sifirlanmis gorunum yeni kayit sayilir: eski varsayilana tasima ve tek seferlik bilgi yeniden calismaz
    $new['LookVersion'] = 10
    $new['LookNotice'] = $false
    return @{ Settings = $new; Changed = $changed.ToArray(); Scope = $Scope }
}

function Get-SettingsBackupDir {
    $root = ''
    try { $root = [string]$sync.DataDir } catch { $root = '' }
    if ($root -eq '') { try { $root = [string]$script:DataDir } catch { $root = '' } }
    return (Join-Path $root 'AyarYedekleri')
}

# Ayarlarin bir kopyasini AyarYedekleri klasorune yazar; kopyanin yolunu verir (yazilamazsa bos). Etiket: gorunum | tercihler | geri-alma
function Save-SettingsBackup($S, [string]$Tag) {
    try {
        $dir = Get-SettingsBackupDir
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) { [void](New-Item -ItemType Directory -Path $dir -Force -ErrorAction Stop) }
        $stamp = (Get-Date).ToString('yyyyMMdd-HHmmss')
        # ayni saniyede yazilan kopyalar (etiketi ne olursa olsun) sira numarasi alir; boylece siralama her zaman olusturulma sirasini izler
        $n = 1
        foreach ($e in @(Get-SettingsBackupFiles)) { if ([string]$e.Key -ceq $stamp.Replace('-', '') -and [int]$e.Seq -ge $n) { $n = [int]$e.Seq + 1 } }
        $path = ''
        while ($true) {
            $sfx = ''
            if ($n -gt 1) { $sfx = '-' + [string]$n }
            $path = Join-Path $dir ('ayarlar-' + $stamp + '-' + $Tag + $sfx + '.json')
            if (-not (Test-Path -LiteralPath $path)) { break }
            $n++
        }
        Save-JsonFile $S $path 8
        if (-not (Test-Path -LiteralPath $path)) { return '' }
        $all = @(Get-SettingsBackupFiles)
        for ($i = 10; $i -lt $all.Count; $i++) { try { Remove-Item -LiteralPath $all[$i].Path -Force -ErrorAction Stop } catch { } }
        return $path
    } catch { return '' }
}

# AyarYedekleri klasorundeki kopyalar, yeniden eskiye (damga, ayni saniyedeki kopyalarda sira numarasi): @{ Path; Name; Time; Scope; Key; Seq }
# Tanimsiz adli dosyalar listelenmez ve silinmez.
function Get-SettingsBackupFiles {
    $out = New-Object System.Collections.ArrayList
    try {
        $dir = Get-SettingsBackupDir
        if (Test-Path -LiteralPath $dir -PathType Container) {
            foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter 'ayarlar-*.json' -File -ErrorAction SilentlyContinue)) {
                $m = [regex]::Match($f.Name, '^ayarlar-(\d{8})-(\d{6})-(gorunum|tercihler|fabrika|geri-alma)(?:-(\d+))?\.json$')
                if (-not $m.Success) { continue }
                $seq = 1
                if ($m.Groups[4].Success) { $seq = [int]$m.Groups[4].Value }
                $t = [datetime]::MinValue
                if (-not [datetime]::TryParseExact(($m.Groups[1].Value + $m.Groups[2].Value), 'yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$t)) { $t = $f.LastWriteTime }
                [void]$out.Add(@{ Path = $f.FullName; Name = $f.Name; Time = $t; Scope = [string]$m.Groups[3].Value; Key = ($m.Groups[1].Value + $m.Groups[2].Value); Seq = $seq })
            }
        }
    } catch { }
    $arr = @($out.ToArray() | Sort-Object -Property @{ Expression = { [string]$_.Key }; Descending = $true }, @{ Expression = { [int]$_.Seq }; Descending = $true })
    # duz dizi doner (cagiranlar @() ile sarar); 'return , $arr' kullanilsa @() icinde ic ice dizi olusurdu
    return $arr
}

# Geri alinabilir sifirlama kopyalari, yeniden eskiye: @{ Path; Name; Time; Scope }  (geri alma oncesi kopyalar listelenmez)
function Get-ResetBackups {
    $out = New-Object System.Collections.ArrayList
    foreach ($b in @(Get-SettingsBackupFiles)) {
        if ([string]$b.Scope -eq 'geri-alma') { continue }
        [void]$out.Add(@{ Path = [string]$b.Path; Name = [string]$b.Name; Time = $b.Time; Scope = [string]$b.Scope })
    }
    return $out.ToArray()
}

# Kopyayi okur; ayar dosyasi gibi gorunmuyorsa $null
function Read-SettingsBackup([string]$Path) {
    try {
        if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
        $obj = ConvertTo-Hashtable (Read-JsonFile $Path)
        if ($obj -is [hashtable] -and ($obj.ContainsKey('Theme') -or $obj.ContainsKey('Layout') -or $obj.ContainsKey('Mode'))) { return $obj }
    } catch { }
    return $null
}

# Kopyayi ayar dosyasina geri yazar (once gecerli ayarlarin kopyasi 'geri-alma' etiketiyle saklanir). Arayuz belleginin yenilenmesi cagirana aittir.
function Restore-SettingsFromBackup([string]$Path, $Current) {
    $obj = Read-SettingsBackup $Path
    if ($null -eq $obj) { return $false }
    if ($null -ne $Current) { [void](Save-SettingsBackup $Current 'geri-alma') }
    # eski surumden alinmis kopyada LookVersion yoktur; yazilmazsa ilk acilista gorunum yeniden yeni varsayilana tasinirdi
    $obj['LookVersion'] = 10
    $obj['LookNotice'] = $false
    try { Save-JsonFile $obj $sync.SettingsFile 8 } catch { return $false }
    return (Test-Path -LiteralPath $sync.SettingsFile)
}

# Arayuz baska bir surecte aciksa $true (arayuz kapanirken kendi ayarlarini yazar; bu yuzden o sirada dosya degistirilmez)
function Test-GuiRunning {
    $m = $null
    $busy = $false
    try {
        $m = New-Object System.Threading.Mutex($false, 'Global\Multimizer-Arayuz')
        $got = $false
        try { $got = $m.WaitOne(0) } catch [System.Threading.AbandonedMutexException] { $got = $true }
        if ($got) { try { $m.ReleaseMutex() } catch { } } else { $busy = $true }
    } catch { $busy = $false }
    finally { try { if ($null -ne $m) { $m.Dispose() } } catch { } }
    return $busy
}

# Arayuz kapaliyken (komut satiri): kayitli ayarlari sifirlar. Donus: @{ Ok; Changed; Backup }
function Reset-SettingsFile([string]$Scope) {
    $cur = Get-Settings
    $tag = 'gorunum'
    if ($Scope -eq 'Tercihler') { $tag = 'tercihler' }
    if ($Scope -eq 'Fabrika') { $tag = 'fabrika' }
    $bk = Save-SettingsBackup $cur $tag
    if ($bk -eq '') { return @{ Ok = $false; Changed = @(); Backup = '' } }
    $r = Get-ResetResult $cur $Scope
    Save-Settings $r.Settings
    return @{ Ok = $true; Changed = @($r.Changed); Backup = $bk }
}

# -Gorev AyarSifirla -Deger Gorunum | Tercihler
function Invoke-CliResetSettings {
    $scope = ConvertTo-ResetScope ([string]$Deger)
    if ($scope -eq '') { Write-WhLog ('Kullan' + [char]0x0131 + 'm: -Gorev AyarSifirla -Deger Gorunum | Tercihler') 'ERR'; return 1 }
    if (Test-GuiRunning) { Write-WhLog ('Uygulama a' + [char]0x00E7 + '' + [char]0x0131 + 'kken ayarlar komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'ndan s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlanamaz; ' + [char]0x00F6 + 'nce uygulamay' + [char]0x0131 + ' kapat' + [char]0x0131 + 'n.') 'ERR'; return 3 }
    $r = Reset-SettingsFile $scope
    if ($r.Ok -ne $true) { Write-WhLog ('Ayar kopyas' + [char]0x0131 + ' yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + '; s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '.') 'ERR'; return 1 }
    $n = @($r.Changed).Count
    if ($scope -eq 'Tercihler') { Write-WhLog (Format-Tr ('Uygulama tercihleri s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + ' ({0} ayar de' + [char]0x011F + 'i' + [char]0x015F + 'ti).') $n) 'OK' }
    else { Write-WhLog (Format-Tr ('G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm ayarlar' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + ' ({0} ayar de' + [char]0x011F + 'i' + [char]0x015F + 'ti).') $n) 'OK' }
    Write-WhLog (Format-Tr ('' + [char]0x00D6 + 'nceki ayarlar' + [char]0x0131 + 'n kopyas' + [char]0x0131 + ': {0}') ([string]$r.Backup)) 'INFO'
    return 0
}

# ---------------- her sey: Windows'ta yapilan degisikliklerin tamami ----------------
# Geri alinabilir gunlukler, yeniden eskiye (geri alinmis olanlar listelenmez)
function Get-UndoableJournals([string]$Dir) {
    $out = New-Object System.Collections.ArrayList
    try {
        if ([string]$Dir -ne '' -and (Test-Path -LiteralPath $Dir -PathType Container)) {
            foreach ($f in @(Get-ChildItem -LiteralPath $Dir -Filter 'yedek-*.jsonl' -File -ErrorAction SilentlyContinue | Sort-Object Name -Descending)) {
                if ($f.Name -match '^yedek-\d{8}-\d{6}\.jsonl$') { [void]$out.Add($f.FullName) }
            }
        }
    } catch { }
    return $out.ToArray()
}

# Tum gunlukleri yeniden eskiye geri alir. Donus: @{ Files; Changes; Errors; Summary }
function Job_UndoAll($P) {
    Reset-Counters
    $script:Preview = $false
    $t0 = Get-Date
    $files = @(Get-UndoableJournals ([string]$sync.BackupDir))
    Write-WhLog (('Geri al' + [char]0x0131 + 'nacak kay' + [char]0x0131 + 't dosyas' + [char]0x0131 + ': ') + [string]$files.Count) 'STEP'
    foreach ($f in $files) {
        try { Invoke-Undo ([string]$f) } catch { Add-Err ('Hata: ' + $_.Exception.Message) }
    }
    try { Update-AppliedAfterUndo } catch { Write-LogFile ('Kayit guncellenemedi: ' + $_.Exception.Message) }
    $sum = Get-RunSummary ('T' + [char]0x00FC + 'm' + [char]0x00FC + 'n' + [char]0x00FC + ' geri alma') $t0
    Write-WhLog $sum 'INFO'
    return @{ Files = $files.Count; Changes = $script:Changes; Errors = $script:Errors; Summary = $sum }
}

# ---------------- ust cubuk: dil dugmesi modeli ----------------
# ==================================================================
#  UST CUBUK (cekirdek): dil dugmesinin gosterimi ve acilir listenin modeli
#  Saf mantik: ekrana dokunmaz; testlerde sahte ayarlarla denenir.
#  Dil secimi yeniden baslatmayla uygulanir (bkz. 141_i18n_ui.ps1); Windows dili zaten secilen dilse yeniden baslatma gerekmez.
# ==================================================================

# Dil kodunun dugmedeki kisa gosterimi: 'tr' -> 'TR'; bolge/yazi eki olan kodlar dil etiketinin bolgesini alir ('zh-hant' -> 'ZH-TW')
function Get-LangShortCode([string]$Code) {
    $c = $Code.Trim().ToLowerInvariant()
    if ($c -eq '') { return '--' }
    $i = $c.IndexOf('-')
    if ($i -lt 0) { return $c.ToUpperInvariant() }
    $base = $c.Substring(0, $i)
    $tag = ''
    foreach ($l in @(Get-LangList)) { if ([string]$l.Code -eq $c) { $tag = [string]$l.Tag } }
    $j = $tag.IndexOf('-')
    if ($j -gt 0 -and $j -lt ($tag.Length - 1)) { return ($base + '-' + $tag.Substring($j + 1)).ToUpperInvariant() }
    return $c.ToUpperInvariant()
}

# Kayitli dil secimi: 'auto' ya da kucuk harfli dil kodu
function Get-LangStoredKey {
    $k = 'auto'
    try { $v = [string]$script:Settings.Language; if ($v.Trim() -ne '') { $k = $v.Trim().ToLowerInvariant() } } catch { }
    return $k
}

# Dil adlari ozel addir: ceviri denetiminde (izleme acikken) eksik ceviri ya da sizinti sayilmaz
function Add-LangNameOut([string]$Text) {
    if ($null -ne $script:LangOut -and $Text.Length -gt 0) { [void]$script:LangOut.Add($Text) }
}

# Acilir liste satirlari: Otomatik + Turkce + bulunan dil dosyalari. Kayit: Code, Name (yerel ad), Sub (ikinci satir), Chip (kisa kod), Checked (kayitli secim)
# Donus acilir (virgulsuz); cagiran @(Get-LangMenuModel) yazar.
function Get-LangMenuModel {
    $stored = Get-LangStoredKey
    $mark = $stored
    if ($stored -ne 'auto') { $mark = Resolve-LangCode $stored }
    $list = @(Get-LangList)
    foreach ($l in $list) { Add-LangNameOut ([string]$l.Native) }
    $sys = Get-SystemLangCode
    $sysName = $sys
    foreach ($l in $list) { if ([string]$l.Code -eq $sys) { $sysName = [string]$l.Native } }
    $rows = New-Object System.Collections.ArrayList
    $subAuto = Format-Tr 'Windows ekran dili: {0}' $sysName
    Add-LangNameOut $subAuto
    [void]$rows.Add(@{ Code = 'auto'; Name = (Tr 'Otomatik'); Sub = $subAuto; Chip = ''; Checked = ($stored -eq 'auto') })
    foreach ($l in $list) {
        $code = [string]$l.Code
        $sub = [string]$l.English
        $cov = 0
        try { $cov = [int]$l.Coverage } catch { $cov = 0 }
        if ($code -ne 'tr' -and $cov -gt 0 -and $cov -lt 100) { $sub = $sub + '  ' + [char]0x00B7 + '  ' + (Format-Percent $cov) }
        $chip = Get-LangShortCode $code
        Add-LangNameOut $sub
        Add-LangNameOut $chip
        [void]$rows.Add(@{ Code = $code; Name = [string]$l.Native; Sub = $sub; Chip = $chip; Checked = (($stored -ne 'auto') -and ($mark -eq $code)) })
    }
    return $rows.ToArray()
}

# Dil dugmesinin yazisi ve aracipucu: calisan arayuz dilini gosterir (secim yeniden baslatmayla uygulanir)
function Get-LangButtonInfo {
    $run = [string]$script:LangCode
    if ($run -eq '') { $run = 'tr' }
    $name = $run
    foreach ($l in @(Get-LangList)) { if ([string]$l.Code -eq $run) { $name = [string]$l.Native } }
    Add-LangNameOut $name
    $code = Get-LangShortCode $run
    Add-LangNameOut $code
    $tip = ''
    if ((Get-LangStoredKey) -eq 'auto') { $tip = Format-Tr ('Aray' + [char]0x00FC + 'z dili: {0} (otomatik)') $name } else { $tip = Format-Tr ('Aray' + [char]0x00FC + 'z dili: {0}') $name }
    Add-LangNameOut $tip
    return @{ Code = $code; Name = $name; Tip = $tip }
}

# Bir dil secimi icin gereken islem: 'yok' (bilinmeyen dil) | 'ayni' (degisiklik yok) | 'kaydet' (arayuz dili degismiyor: yalnizca ayar yazilir) | 'yeniden' (yeniden baslatma gerekir)
function Get-LangChangePlan([string]$Key) {
    $k = $Key.Trim().ToLowerInvariant()
    if ($k -eq '') { return 'yok' }
    $eff = $k
    if ($k -eq 'auto') { $eff = Get-SystemLangCode } else {
        $known = $false
        foreach ($l in @(Get-LangList)) { if ([string]$l.Code -eq $k) { $known = $true } }
        if (-not $known) { return 'yok' }
    }
    $run = [string]$script:LangCode
    if ($run -eq '') { $run = 'tr' }
    if ($k -eq (Get-LangStoredKey) -and $eff -eq $run) { return 'ayni' }
    if ($eff -eq $run) { return 'kaydet' }
    return 'yeniden'
}

# ---------------- gercek makine duzeltmeleri: cekirdek ----------------
# ==================================================================
#  GERCEK MAKINE DUZELTMELERI (cekirdek)
#  Bu bolumdeki her islem sonucunu sistemden geri okuyarak dogrular; "yapildi" yalnizca dogrulama tutarsa yazilir.
#    - Guc kipi: Modern Bekleme (S0) kullanan bilgisayarlarda Windows yalnizca Dengeli planina izin verir;
#      performans duzeyi "guc kipi" (En iyi performans / Dengeli / En iyi guc verimliligi) ile ayarlanir.
#    - Ekran karti sicakligi: Gorev Yoneticisi'nin kullandigi surucu arayuzunden (D3DKMT) okunur.
#    - Gorsel efektler: kayit degerleri oturum kapatmadan uygulanir (SystemParametersInfo + ayar degisikligi yayini).
#    - Oturum: bilgisayar kapanirken sona eren oturum cokme sayilmaz; guvenli kip sorunsuz oturumlardan sonra kendiliginden kapanir.
#    - Yeniden baslatma: shutdown.exe cikis koduyla dogrulanir.
# ==================================================================

$script:SysNativeOk = $null
$script:SysNativeSrc = @'
using System;
using System.Runtime.InteropServices;
namespace WH {
  public static class Sys {
    [StructLayout(LayoutKind.Sequential)] struct LUID { public uint Low; public int High; }
    [StructLayout(LayoutKind.Sequential)] struct ADAPTERINFO { public uint hAdapter; public LUID AdapterLuid; public uint NumOfSources; public int bPrecise; }
    [StructLayout(LayoutKind.Sequential)] struct ENUM2 { public uint NumAdapters; public IntPtr pAdapters; }
    [StructLayout(LayoutKind.Sequential)] struct QAI { public uint hAdapter; public uint Type; public IntPtr pData; public uint Size; }
    [StructLayout(LayoutKind.Sequential)] struct CLOSEAD { public uint hAdapter; }
    [StructLayout(LayoutKind.Sequential, Pack = 8)] struct PERF { public uint PhysicalAdapterIndex; public ulong MemoryFrequency; public ulong MaxMemoryFrequency; public ulong MaxMemoryFrequencyOC; public ulong MemoryBandwidth; public ulong PCIEBandwidth; public uint FanRPM; public uint Power; public uint Temperature; public byte PowerStateOverride; }
    [StructLayout(LayoutKind.Sequential)] struct ANIMATIONINFO { public uint cbSize; public int iMinAnimate; }
    [DllImport("gdi32.dll")] static extern int D3DKMTEnumAdapters2(ref ENUM2 e);
    [DllImport("gdi32.dll")] static extern int D3DKMTQueryAdapterInfo(ref QAI q);
    [DllImport("gdi32.dll")] static extern int D3DKMTCloseAdapter(ref CLOSEAD c);
    [DllImport("powrprof.dll")] static extern uint PowerGetEffectiveOverlayScheme(out Guid g);
    [DllImport("powrprof.dll")] static extern uint PowerSetActiveOverlayScheme(Guid g);
    [DllImport("powrprof.dll", EntryPoint = "PowerSetUserConfiguredACPowerMode")] static extern uint SetAcMode(ref Guid g);
    [DllImport("powrprof.dll", EntryPoint = "PowerSetUserConfiguredDCPowerMode")] static extern uint SetDcMode(ref Guid g);
    [DllImport("powrprof.dll", EntryPoint = "PowerGetUserConfiguredACPowerMode")] static extern uint GetAcMode(out Guid g);
    [DllImport("powrprof.dll", EntryPoint = "PowerGetUserConfiguredDCPowerMode")] static extern uint GetDcMode(out Guid g);
    [DllImport("powrprof.dll")] static extern byte GetPwrCapabilities([Out] byte[] caps);
    [DllImport("user32.dll", SetLastError = true)] static extern bool SystemParametersInfo(uint action, uint param, IntPtr pv, uint flags);
    [DllImport("user32.dll", SetLastError = true, EntryPoint = "SystemParametersInfo")] static extern bool SystemParametersInfoAnim(uint action, uint param, ref ANIMATIONINFO pv, uint flags);
    [DllImport("user32.dll", SetLastError = true, EntryPoint = "SystemParametersInfo")] static extern bool SystemParametersInfoGet(uint action, uint param, ref int pv, uint flags);
    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)] static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint msg, IntPtr wParam, string lParam, uint flags, uint timeout, out IntPtr result);

    // En sicak ekran karti (derece C); okunamazsa -1.
    public static double GpuTemp() {
      double best = -1.0;
      ENUM2 e = new ENUM2();
      if (D3DKMTEnumAdapters2(ref e) != 0 || e.NumAdapters == 0 || e.NumAdapters > 64) return best;
      int sz = Marshal.SizeOf(typeof(ADAPTERINFO));
      e.pAdapters = Marshal.AllocHGlobal(sz * (int)e.NumAdapters);
      try {
        if (D3DKMTEnumAdapters2(ref e) != 0) return best;
        int psz = Marshal.SizeOf(typeof(PERF));
        for (int i = 0; i < e.NumAdapters; i++) {
          ADAPTERINFO a = (ADAPTERINFO)Marshal.PtrToStructure(new IntPtr(e.pAdapters.ToInt64() + (long)i * sz), typeof(ADAPTERINFO));
          IntPtr p = Marshal.AllocHGlobal(psz);
          try {
            for (int k = 0; k < psz; k++) Marshal.WriteByte(p, k, 0);
            QAI q = new QAI(); q.hAdapter = a.hAdapter; q.Type = 62; q.pData = p; q.Size = (uint)psz;
            if (D3DKMTQueryAdapterInfo(ref q) == 0) {
              PERF pf = (PERF)Marshal.PtrToStructure(p, typeof(PERF));
              double c = pf.Temperature / 10.0;
              if (c > 5.0 && c < 150.0 && c > best) best = c;
            }
          } finally {
            Marshal.FreeHGlobal(p);
            CLOSEAD cl = new CLOSEAD(); cl.hAdapter = a.hAdapter; D3DKMTCloseAdapter(ref cl);
          }
        }
      } finally { Marshal.FreeHGlobal(e.pAdapters); }
      return best;
    }

    // Modern Bekleme (S0 dusuk guc bosta): SYSTEM_POWER_CAPABILITIES.AoAc
    public static bool ModernStandby() {
      try { byte[] b = new byte[128]; if (GetPwrCapabilities(b) == 0) return false; return b[20] != 0; } catch { return false; }
    }

    public static string GetMode() {
      try { Guid g; if (PowerGetEffectiveOverlayScheme(out g) == 0) return g.ToString(); } catch { }
      return "";
    }

    // Kullanicinin sectigi kip (fiste, pilde); okunamazsa bos
    public static string GetUserMode(bool dc) {
      try { Guid g; uint r = dc ? GetDcMode(out g) : GetAcMode(out g); if (r == 0) return g.ToString(); } catch { }
      return "";
    }

    // 0 = basarili. Once belgelenmis Windows 11 islevleri (fis ve pil ayri), olmazsa etkin kaynak icin eski islev.
    public static uint SetMode(string ac, string dc) {
      Guid a = new Guid(ac); Guid d = new Guid(dc);
      try {
        uint r1 = SetAcMode(ref a); uint r2 = SetDcMode(ref d);
        if (r1 == 0 && r2 == 0) return 0;
      } catch (EntryPointNotFoundException) { }
      catch (DllNotFoundException) { return 2; }
      try { return PowerSetActiveOverlayScheme(a); } catch { return 1; }
    }

    public static bool SetSpiBool(uint setAction, bool on) { return SystemParametersInfo(setAction, 0, on ? new IntPtr(1) : IntPtr.Zero, 2); }
    public static bool SetSpiUi(uint setAction, uint value) { return SystemParametersInfo(setAction, value, IntPtr.Zero, 2); }
    public static bool SetMinAnimate(bool on) { ANIMATIONINFO ai = new ANIMATIONINFO(); ai.cbSize = 8; ai.iMinAnimate = on ? 1 : 0; return SystemParametersInfoAnim(0x0049, 8, ref ai, 2); }
    public static int GetSpi(uint getAction) { int v = 0; SystemParametersInfoGet(getAction, 0, ref v, 0); return v; }
    public static void Broadcast(string area) { IntPtr r; SendMessageTimeout(new IntPtr(0xFFFF), 0x001A, IntPtr.Zero, area, 0x0002, 1000, out r); }
  }
}
'@

# Yerel islevler bir kez derlenir (uygulama alani genelinde; arka plan calisma alanlari da ayni turu gorur)
function Initialize-SysNative {
    if ($null -ne ('WH.Sys' -as [type])) { $script:SysNativeOk = $true; return $true }
    if ($script:SysNativeOk -eq $false) { return $false }
    try { Add-Type -TypeDefinition $script:SysNativeSrc -ErrorAction Stop; $script:SysNativeOk = $true }
    catch { $script:SysNativeOk = $false; try { Write-WhLog ('SysNative: ' + $_.Exception.Message) } catch { } }
    return [bool]$script:SysNativeOk
}

# ---------------- ekran karti sicakligi ----------------
function Get-GpuTemp {
    if (-not (Initialize-SysNative)) { return -1.0 }
    try { $v = [double][WH.Sys]::GpuTemp(); if ($v -gt 0) { return [math]::Round($v, 0) } } catch { }
    return -1.0
}

# ---------------- guc kipi ----------------
$script:PwModes = [ordered]@{
    Perf     = @{ Guid = 'ded574b5-45a0-4f42-8737-46345c09c238'; Name = 'En iyi performans' }
    Balanced = @{ Guid = '00000000-0000-0000-0000-000000000000'; Name = 'Dengeli' }
    Saver    = @{ Guid = '961cc777-2547-4f9d-8174-7d86181b8a7a'; Name = ('En iyi g' + [char]0x00FC + '' + [char]0x00E7 + ' verimlili' + [char]0x011F + 'i') }
}

function Test-PwModernStandby {
    if (-not (Initialize-SysNative)) { return $false }
    try { return [bool][WH.Sys]::ModernStandby() } catch { return $false }
}

# Plan anahtari -> guc kipi anahtari ('' = bu anahtar bir guc kipine karsilik gelmez)
function Get-PwModeKeyFor([string]$PlanKey) {
    switch ($PlanKey) {
        'High' { return 'Perf' } 'Ultimate' { return 'Perf' } 'Best' { return 'Perf' }
        'Balanced' { return 'Balanced' } 'Saver' { return 'Saver' }
    }
    return ''
}

function Get-PwModeKeyOfGuid([string]$Guid) {
    $g = $Guid.Trim().ToLowerInvariant()
    foreach ($k in $script:PwModes.Keys) { if ([string]$script:PwModes[$k].Guid -eq $g) { return [string]$k } }
    return ''
}

# Su an yururlukteki guc kipi: @{ Ok; Key; Name; Guid; Modern }
function Get-PwModeInfo {
    $r = @{ Ok = $false; Key = ''; Name = ''; Guid = ''; Modern = $false }
    if (-not (Initialize-SysNative)) { return $r }
    try {
        $r.Modern = [bool][WH.Sys]::ModernStandby()
        $g = [string][WH.Sys]::GetMode()
        if ($g -eq '') { return $r }
        $r.Guid = $g.ToLowerInvariant()
        $r.Key = Get-PwModeKeyOfGuid $r.Guid
        if ($r.Key -ne '') { $r.Name = [string]$script:PwModes[$r.Key].Name; $r.Ok = $true }
    } catch { }
    return $r
}

# Plan anahtari guc kipiyle mi uygulanmali?  Modern Bekleme'de Windows Dengeli disindaki yerlesik planlari sunmaz.
function Test-PwUseMode([string]$PlanKey) {
    if ((Get-PwModeKeyFor $PlanKey) -eq '') { return $false }
    return (Test-PwModernStandby)
}

# Op: @{ T = 'PowerSet'; Key } -> Modern Bekleme'de guc kipi olarak uygulanir. Sonuc geri okunarak dogrulanir.
function Invoke-PowerModeOp([string]$PlanKey) {
    $mk = Get-PwModeKeyFor $PlanKey
    $tg = $script:PwModes[$mk]
    $cur = Get-PwModeInfo
    $act = Get-PwActive
    $balGuid = [string]$script:PwKnown.Balanced.Guid
    $onBalanced = ([string]$act.Guid -eq $balGuid)
    if ($cur.Ok -and [string]$cur.Guid -eq [string]$tg.Guid -and $onBalanced) { Add-Skip (('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi zaten ') + [string]$tg.Name); return }
    if ($script:Preview) {
        $from = 'bilinmiyor'
        if ($cur.Ok) { $from = [string]$cur.Name }
        Add-Plan (('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi: ') + $from + (' ' + [char]0x2192 + ' ') + [string]$tg.Name)
        Add-Plan ('   (Bu bilgisayar Modern Bekleme kullan' + [char]0x0131 + 'yor: Windows yaln' + [char]0x0131 + 'zca Dengeli plan' + [char]0x0131 + 'n' + [char]0x0131 + ' sunar, performans d' + [char]0x00FC + 'zeyi g' + [char]0x00FC + '' + [char]0x00E7 + ' kipiyle ayarlan' + [char]0x0131 + 'r.)')
        if (-not $onBalanced) { Add-Plan (('   Etkin plan Dengeli yap' + [char]0x0131 + 'lacak (g' + [char]0x00FC + '' + [char]0x00E7 + ' kipi yaln' + [char]0x0131 + 'zca Dengeli plan' + [char]0x0131 + 'nda ge' + [char]0x00E7 + 'erlidir): ') + [string]$act.Name) }
        return
    }
    if (-not $onBalanced) {
        Add-Journal @{ T = 'Power'; Guid = [string]$act.Guid }
        & powercfg.exe /setactive $balGuid | Out-Null
        if ($LASTEXITCODE -ne 0) { throw ('Dengeli plan etkinle' + [char]0x015F + 'tirilemedi (powercfg /setactive).') }
    }
    $pa = [string][WH.Sys]::GetUserMode($false); $pd = [string][WH.Sys]::GetUserMode($true)
    if ($pa -eq '') { $pa = [string]$cur.Guid }
    if ($pd -eq '') { $pd = [string]$cur.Guid }
    Add-Journal @{ T = 'PowerMode'; Ac = $pa; Dc = $pd }
    $rc = [WH.Sys]::SetMode([string]$tg.Guid, [string]$tg.Guid)
    if ($rc -ne 0) { throw (('Windows g' + [char]0x00FC + '' + [char]0x00E7 + ' kipini de' + [char]0x011F + 'i' + [char]0x015F + 'tirmedi (kod ') + [string]$rc + ').') }
    $now = Get-PwModeInfo
    if (-not $now.Ok -or [string]$now.Guid -ne [string]$tg.Guid) {
        $seen = ('okunamad' + [char]0x0131 + '')
        if ($now.Ok) { $seen = [string]$now.Name }
        throw (('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi do' + [char]0x011F + 'rulanamad' + [char]0x0131 + ': istenen ') + [string]$tg.Name + (', y' + [char]0x00FC + 'r' + [char]0x00FC + 'rl' + [char]0x00FC + 'kteki ') + $seen + ('. ' + [char]0x00DC + 'reticinin g' + [char]0x00FC + '' + [char]0x00E7 + ' yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + ' ya da bir kurum ilkesi kipi kilitliyor olabilir.'))
    }
    Add-Done (('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi: ') + [string]$tg.Name + (' (do' + [char]0x011F + 'ruland' + [char]0x0131 + ')'))
}

function Undo-PowerMode($It) {
    if (-not (Initialize-SysNative)) { throw ('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi geri al' + [char]0x0131 + 'namad' + [char]0x0131 + ' (yerel i' + [char]0x015F + 'lev y' + [char]0x00FC + 'klenemedi).') }
    $a = [string]$It.Ac; $d = [string]$It.Dc
    if ($a -eq '') { $a = [string]$script:PwModes.Balanced.Guid }
    if ($d -eq '') { $d = $a }
    $rc = [WH.Sys]::SetMode($a, $d)
    if ($rc -ne 0) { throw (('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi geri al' + [char]0x0131 + 'namad' + [char]0x0131 + ' (kod ') + [string]$rc + ').') }
    Add-Done ('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi geri al' + [char]0x0131 + 'nd' + [char]0x0131 + '')
}

# ---------------- gorsel efektlerin aninda uygulanmasi ----------------
# UserPreferencesMask bitleri: SPI_GET degeri = 0x1000 + bit * 2, SPI_SET = SPI_GET + 1
$script:LiveMaskBits = @(1, 2, 3, 9, 10, 11, 12, 13, 18, 33)
$script:LiveRegRx = '(?i)\\Control Panel\\Desktop|\\Explorer\\VisualEffects|\\Explorer\\Advanced|\\Themes\\Personalize|\\Windows\\DWM'

# Gunluk kayitlari arasinda gorsel ayar var mi?
function Test-LiveRefreshNeeded($Items) {
    foreach ($it in @($Items)) {
        if ($null -eq $it) { continue }
        if ([string]$it.T -eq 'Reg' -and [string]$it.Path -match $script:LiveRegRx) { return $true }
    }
    return $false
}

# Maske baytlarindan bit degeri
function Get-MaskBit([byte[]]$Mask, [int]$Bit) {
    $i = [int][math]::Floor($Bit / 8)
    if ($null -eq $Mask -or $i -ge $Mask.Length) { return $null }
    return (([int]$Mask[$i] -band (1 -shl ($Bit % 8))) -ne 0)
}

# Kayit defterindeki gorsel ayarlari calisan oturuma uygular. Donus: uygulanan ayar sayisi (-1: yerel islev yok)
function Invoke-LiveRefresh($Items) {
    if (-not (Test-LiveRefreshNeeded $Items)) { return 0 }
    if (-not (Initialize-SysNative)) { return -1 }
    $n = 0
    try {
        $desk = 'HKCU\Control Panel\Desktop'
        $raw = Get-RegValue $desk 'UserPreferencesMask' $null
        $mask = $null
        if ($null -ne $raw) { try { $mask = [byte[]]@($raw) } catch { $mask = $null } }
        if ($null -ne $mask -and $mask.Length -ge 4) {
            foreach ($b in $script:LiveMaskBits) {
                $v = Get-MaskBit $mask $b
                if ($null -eq $v) { continue }
                if ([WH.Sys]::SetSpiBool([uint32](0x1000 + $b * 2 + 1), [bool]$v)) { $n++ }
            }
        }
        $ma = [string](Get-RegValue ($desk + '\WindowMetrics') 'MinAnimate' '')
        if ($ma -ne '') { if ([WH.Sys]::SetMinAnimate(($ma -eq '1'))) { $n++ } }
        $df = [string](Get-RegValue $desk 'DragFullWindows' '')
        if ($df -ne '') { if ([WH.Sys]::SetSpiUi(0x0025, [uint32]([int]($df -eq '1')))) { $n++ } }
        $md = [string](Get-RegValue $desk 'MenuShowDelay' '')
        if ($md -match '^\d+$') { if ([WH.Sys]::SetSpiUi(0x006B, [uint32]$md)) { $n++ } }
        foreach ($area in @('WindowMetrics', 'ImmersiveColorSet', 'TraySettings', 'Environment')) { [WH.Sys]::Broadcast($area) }
    } catch { Write-WhLog (('G' + [char]0x00F6 + 'rsel ayarlar oturuma uygulan' + [char]0x0131 + 'rken hata: ') + $_.Exception.Message) 'WARN'; return $n }
    if ($n -gt 0) { Write-WhLog ('G' + [char]0x00F6 + 'rsel ayarlar oturum kapatmadan uyguland' + [char]0x0131 + ' (baz' + [char]0x0131 + ' pencereler yeniden a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca tam yans' + [char]0x0131 + 'r).') 'INFO' }
    return $n
}

# ---------------- yeniden baslatma bekleyen dosya islemleri ----------------
# PendingFileRenameOperations ciftlerden olusur (kaynak, hedef). Hedefi bos olan cift "acilista sil" demektir;
# uygulamalarin geride biraktigi bu tur kayitlar yeniden baslatma gerektirmez. Yalnizca dosya degistiren ciftler sayilir.
function Test-PendingRenameReal($Value) {
    $a = @($Value)
    if ($a.Count -eq 0) { return $false }
    for ($i = 0; $i -lt $a.Count; $i += 2) {
        $src = [string]$a[$i]
        $dst = ''
        if (($i + 1) -lt $a.Count) { $dst = [string]$a[$i + 1] }
        if ($src.Trim() -eq '') { continue }
        if ($dst.Trim() -ne '') { return $true }
    }
    return $false
}

# ---------------- oturum: bilgisayar kapanirken sona erme ----------------
function Get-SystemBootTime {
    try { return [DateTime](Get-CimInstance -ClassName Win32_OperatingSystem -OperationTimeoutSec 5 -ErrorAction Stop).LastBootUpTime } catch { }
    try { return (Get-Date).AddSeconds(-1.0 * [System.Diagnostics.Stopwatch]::GetTimestamp() / [System.Diagnostics.Stopwatch]::Frequency) } catch { }
    return [DateTime]::MinValue
}

# Onceki oturumun son izi bilgisayarin son acilisindan onceyse oturum, Windows kapanirken sona ermistir (cokme degildir).
function Test-EndedBySystem([DateTime]$LastTrace, [DateTime]$Boot) {
    if ($Boot -eq [DateTime]::MinValue -or $LastTrace -eq [DateTime]::MinValue) { return $false }
    return ($LastTrace -lt $Boot)
}

function Test-SessionEndedBySystem {
    try {
        if ([string]$script:TraceFile -eq '' -or -not (Test-Path -LiteralPath $script:TraceFile)) { return $false }
        $last = (Get-Item -LiteralPath $script:TraceFile).LastWriteTime
        return (Test-EndedBySystem $last (Get-SystemBootTime))
    } catch { return $false }
}

# Guvenli kipten kendiliginden cikis karari.
#   Why: 'user' (kullanici Ayarlar'dan acti) | 'auto' | '' (eski surumden kalan; otomatik sayilir)
#   Donus: $true = guvenli cizim kapatilmali
function Test-SafeModeRelease([bool]$SafeRender, [string]$Why, [int]$CleanStreak, [bool]$PrevCrashed, [int]$FixLevel) {
    if (-not $SafeRender -or $PrevCrashed) { return $false }
    if ($Why -eq 'user') { return $false }
    if ($FixLevel -lt 1) { return $true }
    return ($CleanStreak -ge 3)
}

# ---------------- yeniden baslatma ----------------
# shutdown.exe bagimsiz degiskenleri tek satirda ve aciklamasi tirnak icinde verilir; cikis kodu 0 degilse basarisizdir.
function Get-RestartArgLine([bool]$Firmware, [int]$Seconds) {
    $a = '/r'
    if ($Firmware) { $a += ' /fw' }
    return ($a + ' /t ' + [string]$Seconds + ' /c "Multimizer: yeniden baslatma"')
}

function Start-SystemRestart([bool]$Firmware = $false, [int]$Seconds = 30) {
    $exe = Join-Path (Join-Path $env:WINDIR 'System32') 'shutdown.exe'
    $p = Start-Process -FilePath $exe -ArgumentList (Get-RestartArgLine $Firmware $Seconds) -WindowStyle Hidden -Wait -PassThru -ErrorAction Stop
    $code = [int]$p.ExitCode
    if ($code -ne 0) { throw (('shutdown.exe ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$code) }
    return $true
}

# ---------------- gercek makine duzeltmeleri: durum ve metinler ----------------
# ==================================================================
#  GERCEK MAKINE DUZELTMELERI (durum ve metinler)
#  Guvenli kipin kendiliginden kapanmasi, olculemeyen degerlerin nedeni, guc kipi satiri, Defender dislama bulgusu.
# ==================================================================

$script:SafeReleased = $false
$script:PrevBySystem = $false

# Oturum acilirken: guvenli cizim kalici mi kalsin?  Girdi: ayardaki kalici deger (bu acilista otomatik acildiysa $true).
# Elle acilmamis guvenli kip, art arda uc sorunsuz oturumdan sonra (ya da bu surume ilk geciste bir kez) kapatilir.
# Cekirdek: ayar anahtarlarini dosyaya ve bellekteki kopyaya yazar (arayuzdeki Set-SettingsKeys'in cekirdek karsiligi)
function Set-CoreSettingKeys($Keys) {
    try {
        $st = Get-Settings
        foreach ($k in @($Keys.Keys)) { $st[[string]$k] = $Keys[$k] }
        Save-Settings $st
    } catch { }
    if ($null -ne $script:Settings) { foreach ($k in @($Keys.Keys)) { try { $script:Settings[[string]$k] = $Keys[$k] } catch { } } }
}

function Update-SafeModeState([bool]$Persist) {
    $keys = @{}
    $why = ''; $clean = 0; $fix = 0
    try { $why = [string]$script:Settings.SafeRenderWhy } catch { }
    try { $clean = [int]$script:Settings.CleanStreak } catch { }
    try { $fix = [int]$script:Settings.FixLevel } catch { }
    if ($script:SafeRenderAuto) { $why = 'auto'; $keys['SafeRenderWhy'] = 'auto' }
    if ($script:PrevCrashed -and $clean -ne 0) { $clean = 0; $keys['CleanStreak'] = 0 }
    $out = $Persist
    if (Test-SafeModeRelease $Persist $why $clean ([bool]$script:PrevCrashed) $fix) {
        $keys['SafeRender'] = $false; $keys['SafeRenderWhy'] = ''; $keys['CleanStreak'] = 0; $keys['CrashStreak'] = 0
        $script:SafeReleased = $true
        $out = $false
    }
    if ($fix -lt 1) { $keys['FixLevel'] = 1; $keys['OptCrypto'] = $true }   # dosya sifreleme artik varsayilan olarak acik
    if ($keys.Count -gt 0) { Set-CoreSettingKeys $keys }
    return $out
}

# Duzgun kapanan her oturum sayilir (guvenli kipten cikis karari icin)
function Step-CleanStreak {
    if ($script:Settings.SafeRender -ne $true) { return }
    $n = 0
    try { $n = [int]$script:Settings.CleanStreak } catch { }
    if ($n -lt 99) { Set-CoreSettingKeys @{ CleanStreak = ($n + 1) } }
}

# Ekran karti yuku okunamadiginda gosterilecek neden
function Get-GpuOffText {
    if ($sync.SafeMon -eq $true) { return ('g' + [char]0x00FC + 'venli kipte kapal' + [char]0x0131 + '') }
    if ($sync.NoGpu -eq $true) { return ('ayarlardan kapal' + [char]0x0131 + '') }
    # izleme dongusu ilk olcumu henuz yapmadiysa "olculemedi" demek yanlis olur
    if ($sync.MonWarmGpu -ne $false) { return ('' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor' + [char]0x2026 + '') }
    return ('' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemedi')
}

# Sicaklik okunamadiginda alt yazi: ilk olcum beklenirken "olculuyor", sonrasinda "sensor yok"
function Get-TempOffText {
    if ($sync.MonWarmTemp -ne $false) { return ('' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor' + [char]0x2026 + '') }
    return ('sens' + [char]0x00F6 + 'r yok')
}

# Sicaklik alt yazisi: ekran karti sicakligi okunuyorsa eklenir
function Get-TempSubText($M, [string]$Base) {
    $g = -1.0
    try { if ($M.ContainsKey('GpuTemp')) { $g = [double]$M.GpuTemp } } catch { }
    if ($g -gt 0) { return ((Tr $Base) + (' ' + [char]0x00B7 + ' ') + (Tr ('ekran kart' + [char]0x0131 + '')) + ' ' + [string][int]$g + ('' + [char]0x00B0 + '')) }
    return $Base
}

# Guc sayfasi: etkin planin yanina yururlukteki guc kipi
function Update-PwModeLine($Info) {
    try {
        $m = $Info.Mode
        if ($null -eq $m -or $m.Ok -ne $true -or $null -eq $ui.pw_LivePlan) { return }
        $t = [string]$ui.pw_LivePlan.Text + ('  ' + [char]0x00B7 + '  ') + (Tr ('G' + [char]0x00FC + '' + [char]0x00E7 + ' kipi')) + ': ' + (Tr ([string]$m.Name))
        if ($m.Modern -eq $true) { $t += '  (' + (Tr ('Modern Bekleme: performans d' + [char]0x00FC + 'zeyi g' + [char]0x00FC + '' + [char]0x00E7 + ' kipiyle ayarlan' + [char]0x0131 + 'r')) + ')' }
        $ui.pw_LivePlan.Text = (Tr $($t))
    } catch { }
}

# ---------------- Defender dislama bulgusu ----------------
function Get-ExclTitle([int]$Count) { return (('Defender d' + [char]0x0131 + '' + [char]0x015F + 'lama listesi: ') + [string]$Count + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e')) }

function Get-ExclDetail($Pref) {
    $all = New-Object System.Collections.ArrayList
    foreach ($x in @($Pref.ExclusionPath)) { if ([string]$x -ne '') { [void]$all.Add([string]$x) } }
    foreach ($x in @($Pref.ExclusionProcess)) { if ([string]$x -ne '') { [void]$all.Add([string]$x) } }
    foreach ($x in @($Pref.ExclusionExtension)) { if ([string]$x -ne '') { [void]$all.Add('*.' + ([string]$x).TrimStart('.')) } }
    $shown = @($all | Select-Object -First 5)
    $t = 'Taranmayanlar: ' + ($shown -join '; ')
    if ($all.Count -gt $shown.Count) { $t += ' (+' + [string]($all.Count - $shown.Count) + ')' }
    return ($t + ('. Zararl' + [char]0x0131 + 'lar kendilerini d' + [char]0x0131 + '' + [char]0x015F + 'lamaya ekleyebilir; tan' + [char]0x0131 + 'mad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z ' + [char]0x00F6 + '' + [char]0x011F + 'eyi Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i' + [char]0x2019 + 'nden kald' + [char]0x0131 + 'r' + [char]0x0131 + 'n. Multimizer bu listeyi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez.'))
}

function Get-ExclAction { return @{ Kind = 'Url'; Url = 'windowsdefender://exclusions'; Label = ('D' + [char]0x0131 + '' + [char]0x015F + 'lamalar' + [char]0x0131 + ' a' + [char]0x00E7 + '') } }

# ---------------- yardimcilar: cekirdek ----------------
# ==================================================================
#  YARDIMCILAR (cekirdek): parola uretici, toplu yeniden adlandirma, once/sonra karnesi, internete baglanan programlar,
#  acik kaynak lisans bilgisi ve alternatif onerici, Firefox gizlilik ilkeleri, yardim paketi, yeni bilgisayar adimlari.
#  Bu dosya arayuze dokunmaz. Sistemi degistiren iki islem (yeniden adlandirma, guvenlik duvari engeli) plan motorundan gecer:
#  once onizleme, sonra uygulama; her ikisi de Gecmis sayfasindan geri alinir.
# ==================================================================

# ---------------- parola uretici ----------------
# Karistirilan karakterler (0 O o 1 l I) hicbir kumede yoktur.
$script:PwCharSets = [ordered]@{
    Lower  = 'abcdefghijkmnpqrstuvwxyz'
    Upper  = 'ABCDEFGHJKLMNPQRSTUVWXYZ'
    Digit  = '23456789'
    Symbol = '!#$%&*+-=?@_'
}
$script:PwLengths = @(12, 16, 20, 24, 32)

# Secilen karakter kumeleri (kucuk harf her zaman vardir). Uretim Eklenti\Parola.ps1 icindedir: New-RandomPassword <uzunluk> <kumeler>
function Get-PasswordSets([bool]$Upper, [bool]$Digit, [bool]$Symbol) {
    $sets = New-Object System.Collections.ArrayList
    [void]$sets.Add([string]$script:PwCharSets.Lower)
    if ($Upper) { [void]$sets.Add([string]$script:PwCharSets.Upper) }
    if ($Digit) { [void]$sets.Add([string]$script:PwCharSets.Digit) }
    if ($Symbol) { [void]$sets.Add([string]$script:PwCharSets.Symbol) }
    return , [string[]]$sets.ToArray()
}

# Yaklasik entropi (bit): uzunluk x log2(havuz)
function Get-PasswordBits([int]$Length, [bool]$Upper, [bool]$Digit, [bool]$Symbol) {
    $n = ((Get-PasswordSets $Upper $Digit $Symbol) -join '').Length
    return [int][math]::Floor($Length * [math]::Log($n, 2))
}

function Get-PasswordStrengthText([int]$Bits) {
    if ($Bits -lt 60) { return ('zay' + [char]0x0131 + 'f') }
    if ($Bits -lt 80) { return 'iyi' }
    if ($Bits -lt 110) { return ('g' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + '') }
    return ('' + [char]0x00E7 + 'ok g' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + '')
}

# Listedeki bir sonraki uzunluk (son degerden sonra basa doner)
function Get-NextPwLength([int]$Current) {
    $a = @($script:PwLengths)
    for ($i = 0; $i -lt $a.Count; $i++) { if ([int]$a[$i] -gt $Current) { return [int]$a[$i] } }
    return [int]$a[0]
}

# ---------------- toplu yeniden adlandirma ----------------
$script:RenameModes = @('Number', 'Replace', 'DatePrefix', 'Lower', 'Dash')
$script:RenameMax = 5000

# Dosya adinda gecersiz karakterleri atar; sondaki nokta ve boslugu kirpar
function Get-SafeFileName([string]$Name) {
    $s = [regex]::Replace([string]$Name, '[\\/:\*\?"<>\|\x00-\x1F]', '')
    return $s.Trim().TrimEnd('.', ' ')
}

function Split-FileName([string]$Name) {
    $i = $Name.LastIndexOf('.')
    if ($i -le 0) { return @{ Stem = $Name; Ext = '' } }
    return @{ Stem = $Name.Substring(0, $i); Ext = $Name.Substring($i) }
}

# Saf: yeniden adlandirma plani.
#   Items: @(@{ Name; Time }) (yalnizca adi degisecek dosyalar)   Existing: klasordeki butun adlar
#   Mode : Number (Arg = temel ad) | Replace (Arg = 'eski=>yeni') | DatePrefix | Lower | Dash
#   Donus: @{ Rows = @(@{ Old; New; Problem }); Changes; Problems; Error }
function Get-RenamePlan($Items, [string]$Mode, [string]$Arg, $Existing = @()) {
    $res = @{ Rows = @(); Changes = 0; Problems = 0; Error = '' }
    if ($script:RenameModes -notcontains $Mode) { $res.Error = ('Bilinmeyen yeniden adland' + [char]0x0131 + 'rma t' + [char]0x00FC + 'r' + [char]0x00FC + '.'); return $res }
    $list = @(@($Items) | Where-Object { $null -ne $_ -and [string]$_.Name -ne '' } | Sort-Object { ([string]$_.Name).ToLowerInvariant() })
    $from = ''; $to = ''
    if ($Mode -eq 'Replace') {
        $ix = ([string]$Arg).IndexOf('=>')
        if ($ix -le 0) { $res.Error = ('Bi' + [char]0x00E7 + 'im: eski=>yeni (' + [char]0x00F6 + 'rnek: IMG_=>Tatil ). Silmek i' + [char]0x00E7 + 'in sa' + [char]0x011F + ' taraf' + [char]0x0131 + ' bo' + [char]0x015F + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'n.'); return $res }
        $from = ([string]$Arg).Substring(0, $ix); $to = ([string]$Arg).Substring($ix + 2)
    }
    $base = Get-SafeFileName ([string]$Arg)
    if ($Mode -eq 'Number' -and $base -eq '') { $base = 'Dosya' }
    $pad = [math]::Max(2, ([string]$list.Count).Length)
    $rows = New-Object System.Collections.ArrayList
    $n = 0
    foreach ($it in $list) {
        $n++
        $old = [string]$it.Name
        $p = Split-FileName $old
        $new = $old
        switch ($Mode) {
            'Number' { $new = $base + ' ' + ([string]$n).PadLeft($pad, '0') + [string]$p.Ext }
            'Replace' { $new = [regex]::Replace([string]$p.Stem, [regex]::Escape($from), $to.Replace('$', '$$'), 'IgnoreCase') + [string]$p.Ext }
            'DatePrefix' {
                $d = ''
                try { $d = ([datetime]$it.Time).ToString('yyyy-MM-dd') } catch { $d = '' }
                if ($d -ne '' -and -not $old.StartsWith($d)) { $new = $d + ' ' + $old }
            }
            'Lower' { $new = $old.ToLowerInvariant() }
            'Dash' { $new = ([regex]::Replace([string]$p.Stem, '[\s_]+', '-')).Trim('-') + [string]$p.Ext }
        }
        $new = Get-SafeFileName $new
        if ($new -ceq $old) { continue }
        $empty = ($new.Trim() -eq '' -or ([string]$p.Ext -ne '' -and $new -eq [string]$p.Ext))
        [void]$rows.Add(@{ Old = $old; New = $new; Problem = ''; Empty = $empty })
    }
    # sorunlar: bos ad, cok uzun ad, ayni ad, klasorde kalan baska dosyayla cakisma
    $leaving = @{}
    foreach ($r in $rows) { $leaving[([string]$r.Old).ToLowerInvariant()] = $true }
    $seen = @{}
    foreach ($r in $rows) { $k = ([string]$r.New).ToLowerInvariant(); if ($seen.ContainsKey($k)) { $seen[$k] = [int]$seen[$k] + 1 } else { $seen[$k] = 1 } }
    $stay = @{}
    foreach ($e in @($Existing)) { $k = ([string]$e).ToLowerInvariant(); if ($k -ne '' -and -not $leaving.ContainsKey($k)) { $stay[$k] = $true } }
    $bad = 0
    foreach ($r in $rows) {
        $k = ([string]$r.New).ToLowerInvariant()
        if ($r.Empty -eq $true) { $r.Problem = ('ad bo' + [char]0x015F + ' kal' + [char]0x0131 + 'yor') }
        elseif (([string]$r.New).Length -gt 240) { $r.Problem = ('ad ' + [char]0x00E7 + 'ok uzun') }
        elseif ([int]$seen[$k] -gt 1) { $r.Problem = ('ayn' + [char]0x0131 + ' ad birden ' + [char]0x00E7 + 'ok dosyaya d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'yor') }
        elseif ($stay.ContainsKey($k)) { $r.Problem = ('klas' + [char]0x00F6 + 'rde bu adda ba' + [char]0x015F + 'ka bir dosya var') }
        if ([string]$r.Problem -ne '') { $bad++ }
    }
    $res.Rows = $rows.ToArray(); $res.Changes = $rows.Count; $res.Problems = $bad
    return $res
}

# Sistem klasorlerinde toplu yeniden adlandirma yapilmaz. '' = izin var
function Test-RenameDirAllowed([string]$Dir) {
    if ([string]$Dir -eq '') { return ('Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'ilmedi.') }
    $d = ([string]$Dir).TrimEnd('\') + '\'
    $blocked = New-Object System.Collections.ArrayList
    foreach ($v in @($env:WINDIR, $env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramData)) { if ([string]$v -ne '') { [void]$blocked.Add(([string]$v).TrimEnd('\') + '\') } }
    foreach ($b in $blocked) { if ($d.StartsWith([string]$b, [StringComparison]::OrdinalIgnoreCase)) { return ('Windows ve program klas' + [char]0x00F6 + 'rlerinde toplu yeniden adland' + [char]0x0131 + 'rma yap' + [char]0x0131 + 'lmaz.') } }
    if ($d -cmatch '^[A-Za-z]:\\$') { return ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'n k' + [char]0x00F6 + 'k klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nde toplu yeniden adland' + [char]0x0131 + 'rma yap' + [char]0x0131 + 'lmaz; bir alt klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in.') }
    return ''
}

# Klasordeki dosyalar (alt klasorler, gizli ve sistem dosyalari haric)
function Job_RenameScan($P) {
    $dir = [string]$P.Dir
    $why = Test-RenameDirAllowed $dir
    if ($why -ne '') { return @{ Ok = $false; Error = $why } }
    if (-not (Test-Path -LiteralPath $dir -PathType Container)) { return @{ Ok = $false; Error = ('Klas' + [char]0x00F6 + 'r bulunamad' + [char]0x0131 + '.') } }
    $items = New-Object System.Collections.ArrayList
    foreach ($f in @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue)) {
        if (($f.Attributes -band [System.IO.FileAttributes]::Hidden) -or ($f.Attributes -band [System.IO.FileAttributes]::System)) { continue }
        [void]$items.Add(@{ Name = [string]$f.Name; Time = $f.LastWriteTime })
        if ($items.Count -gt $script:RenameMax) { return @{ Ok = $false; Error = (('Klas' + [char]0x00F6 + 'rde ') + [string]$script:RenameMax + (' dosyadan fazlas' + [char]0x0131 + ' var; daha k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k bir klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in.')) } }
    }
    return @{ Ok = $true; Dir = $dir; Items = $items.ToArray() }
}

# Iki asamali yeniden adlandirma (ad degis tokusunda cakisma olmaz). Donus: basarili ciftler
function Invoke-RenamePairs([string]$Dir, $Pairs) {
    $tmp = New-Object System.Collections.ArrayList
    $tag = '~mm-' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '-'
    $i = 0
    try {
        foreach ($p in @($Pairs)) {
            $i++
            $t = $tag + [string]$i
            Rename-Item -LiteralPath (Join-Path $Dir ([string]$p.Old)) -NewName $t -ErrorAction Stop
            [void]$tmp.Add(@{ Tmp = $t; Old = [string]$p.Old; New = [string]$p.New })
        }
    } catch {
        foreach ($x in $tmp) { try { Rename-Item -LiteralPath (Join-Path $Dir ([string]$x.Tmp)) -NewName ([string]$x.Old) -ErrorAction Stop } catch { } }
        throw (('Yeniden adland' + [char]0x0131 + 'rma ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + ', hi' + [char]0x00E7 + 'bir dosya de' + [char]0x011F + 'i' + [char]0x015F + 'medi: ') + $_.Exception.Message)
    }
    $done = New-Object System.Collections.ArrayList
    foreach ($x in $tmp) {
        try {
            Rename-Item -LiteralPath (Join-Path $Dir ([string]$x.Tmp)) -NewName ([string]$x.New) -ErrorAction Stop
            [void]$done.Add(@{ Old = [string]$x.Old; New = [string]$x.New })
        } catch {
            try { Rename-Item -LiteralPath (Join-Path $Dir ([string]$x.Tmp)) -NewName ([string]$x.Old) -ErrorAction Stop } catch { }
            Add-Err (([string]$x.Old) + ': ' + $_.Exception.Message)
        }
    }
    return $done.ToArray()
}

# Op: @{ T = 'Rename'; Dir; Pairs = @(@{ Old; New }) }
function Invoke-RenameOp($Op) {
    $dir = [string]$Op.Dir
    $pairs = @($Op.Pairs)
    $why = Test-RenameDirAllowed $dir
    if ($why -ne '') { throw $why }
    if ($pairs.Count -eq 0) { Add-Skip ('Ad' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ecek dosya yok'); return }
    if ($script:Preview) {
        $k = 0
        foreach ($p in $pairs) {
            $k++
            if ($k -le 25) { Add-Plan (([string]$p.Old) + ('  ' + [char]0x2192 + '  ') + ([string]$p.New)) }
        }
        if ($pairs.Count -gt 25) { Add-Plan ('... ve ' + [string]($pairs.Count - 25) + ' dosya daha') }
        return
    }
    $done = @(Invoke-RenamePairs $dir $pairs)
    if ($done.Count -gt 0) {
        Add-Journal @{ T = 'Rename'; Dir = $dir; Pairs = $done }
        Add-Done ([string]$done.Count + (' dosya yeniden adland' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + $dir)
    }
}

function Undo-RenameItem($It) {
    $dir = [string]$It.Dir
    $back = New-Object System.Collections.ArrayList
    foreach ($p in @($It.Pairs)) {
        if (Test-Path -LiteralPath (Join-Path $dir ([string]$p.New))) { [void]$back.Add(@{ Old = [string]$p.New; New = [string]$p.Old }) }
    }
    if ($back.Count -eq 0) { Add-Skip ('Yeniden adland' + [char]0x0131 + 'r' + [char]0x0131 + 'lan dosyalar yerinde de' + [char]0x011F + 'il; geri al' + [char]0x0131 + 'nacak bir ' + [char]0x015F + 'ey yok'); return }
    $done = @(Invoke-RenamePairs $dir $back.ToArray())
    Add-Done ([string]$done.Count + (' dosyan' + [char]0x0131 + 'n ad' + [char]0x0131 + ' eski h' + [char]0x00E2 + 'line d' + [char]0x00F6 + 'nd' + [char]0x00FC + ': ') + $dir)
}
$script:MoreOps['Rename'] = 'Invoke-RenameOp'
$script:MoreUndo['Rename'] = 'Undo-RenameItem'

# ---------------- once / sonra karnesi ----------------
$script:ScoreBefore = $null
$script:ScoreKeep = 400

function Get-ScoreFile { return (Join-Path $script:DataDir 'karne.jsonl') }

# Olcum: calisan hizmet, islem, bos bellek (MB), sistem surucusunde bos alan (GB)
function Get-ScoreSnapshot {
    $s = @{ Time = (Get-Date).ToString('s'); Svc = -1; Proc = -1; FreeMb = -1; DiskFreeGb = -1.0 }
    try { $s.Svc = @(Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' }).Count } catch { }
    try { $s.Proc = @(Get-Process -ErrorAction SilentlyContinue).Count } catch { }
    try { $os = Get-CimInstance -ClassName Win32_OperatingSystem -OperationTimeoutSec 5 -ErrorAction Stop; $s.FreeMb = [int]([double]$os.FreePhysicalMemory / 1024) } catch { }
    try { $d = New-Object System.IO.DriveInfo ([string]$env:SystemDrive); $s.DiskFreeGb = [math]::Round($d.AvailableFreeSpace / 1GB, 1) } catch { }
    return $s
}

# Saf: iki olcum arasindaki fark (olculemeyen deger 0 sayilir)
function Get-ScoreDelta($A, $B) {
    $d = @{ Svc = 0; Proc = 0; FreeMb = 0; DiskFreeGb = 0.0 }
    if ($null -eq $A -or $null -eq $B) { return $d }
    foreach ($k in @('Svc', 'Proc', 'FreeMb')) { if ([int]$A[$k] -ge 0 -and [int]$B[$k] -ge 0) { $d[$k] = [int]$B[$k] - [int]$A[$k] } }
    if ([double]$A.DiskFreeGb -ge 0 -and [double]$B.DiskFreeGb -ge 0) { $d.DiskFreeGb = [math]::Round([double]$B.DiskFreeGb - [double]$A.DiskFreeGb, 1) }
    return $d
}

function Format-Signed($V, [string]$Unit = '') {
    $n = [double]$V
    $nf = New-Object System.Globalization.NumberFormatInfo
    $nf.NumberDecimalSeparator = ','
    $t = ([math]::Abs($n)).ToString('0.#', $nf)
    if ($n -gt 0) { return ('+' + $t + $Unit) }
    if ($n -lt 0) { return (('' + [char]0x2212 + '') + $t + $Unit) }
    return ('0' + $Unit)
}

# Saf: "calisan hizmet 142 -> 139 (?3) . islem 201 -> 196 (?5) . bos bellek 6100 -> 6400 MB (+300) . bos alan 120 -> 122 GB (+2)"
function Format-ScoreLine($A, $B) {
    if ($null -eq $A -or $null -eq $B) { return '' }
    $d = Get-ScoreDelta $A $B
    $p = New-Object System.Collections.ArrayList
    if ([int]$A.Svc -ge 0 -and [int]$B.Svc -ge 0) { [void]$p.Add(('' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an hizmet ') + [string]$A.Svc + (' ' + [char]0x2192 + ' ') + [string]$B.Svc + ' (' + (Format-Signed $d.Svc) + ')') }
    if ([int]$A.Proc -ge 0 -and [int]$B.Proc -ge 0) { [void]$p.Add(('i' + [char]0x015F + 'lem ') + [string]$A.Proc + (' ' + [char]0x2192 + ' ') + [string]$B.Proc + ' (' + (Format-Signed $d.Proc) + ')') }
    if ([int]$A.FreeMb -ge 0 -and [int]$B.FreeMb -ge 0) { [void]$p.Add(('bo' + [char]0x015F + ' bellek ') + [string]$A.FreeMb + (' ' + [char]0x2192 + ' ') + [string]$B.FreeMb + ' MB (' + (Format-Signed $d.FreeMb) + ')') }
    if ([double]$A.DiskFreeGb -ge 0 -and [double]$B.DiskFreeGb -ge 0) { [void]$p.Add(('bo' + [char]0x015F + ' alan ') + [string]$A.DiskFreeGb + (' ' + [char]0x2192 + ' ') + [string]$B.DiskFreeGb + ' GB (' + (Format-Signed $d.DiskFreeGb) + ')') }
    return ($p -join (' ' + [char]0x00B7 + ' '))
}

function Read-ScoreEntries([int]$Max = 60) {
    $out = New-Object System.Collections.ArrayList
    try {
        $f = Get-ScoreFile
        if (Test-Path -LiteralPath $f) {
            foreach ($l in @(Get-Content -LiteralPath $f -Encoding UTF8 -ErrorAction Stop)) {
                if ([string]$l -eq '') { continue }
                try { $o = ConvertTo-Hashtable ($l | ConvertFrom-Json); if ($o -is [hashtable] -and $o.ContainsKey('A') -and $o.ContainsKey('B')) { [void]$out.Add($o) } } catch { }
            }
        }
    } catch { }
    $a = $out.ToArray()
    if ($a.Count -gt $Max) { $a = @($a[($a.Count - $Max)..($a.Count - 1)]) }
    [array]::Reverse($a)
    return , $a
}

function Add-ScoreEntry([string]$Label, $A, $B, [int]$Changes) {
    try {
        $f = Get-ScoreFile
        $line = (@{ Label = $Label; Changes = $Changes; A = $A; B = $B } | ConvertTo-Json -Compress -Depth 4)
        $lines = New-Object System.Collections.ArrayList
        if (Test-Path -LiteralPath $f) { foreach ($l in @(Get-Content -LiteralPath $f -Encoding UTF8 -ErrorAction SilentlyContinue)) { if ([string]$l -ne '') { [void]$lines.Add([string]$l) } } }
        [void]$lines.Add($line)
        while ($lines.Count -gt $script:ScoreKeep) { $lines.RemoveAt(0) }
        [System.IO.File]::WriteAllLines($f, [string[]]$lines.ToArray(), (New-Object System.Text.UTF8Encoding($false)))
        return $true
    } catch { return $false }
}

# Plan basinda ve sonunda cagrilir (yalnizca gercek uygulamada). Degisiklik yoksa kayit yazilmaz.
function Start-ScoreMeasure { if (-not $script:Preview) { try { $script:ScoreBefore = Get-ScoreSnapshot } catch { $script:ScoreBefore = $null } } }

function Complete-ScoreMeasure([string]$Label) {
    if ($script:Preview -or $null -eq $script:ScoreBefore) { return }
    $a = $script:ScoreBefore
    $script:ScoreBefore = $null
    if ([int]$script:Changes -le 0) { return }
    try {
        $b = Get-ScoreSnapshot
        $t = Format-ScoreLine $a $b
        if ($t -ne '') { Write-WhLog (('Karne (' + [char]0x00F6 + 'nce ' + [char]0x2192 + ' sonra): ') + $t) 'INFO' }
        [void](Add-ScoreEntry $Label $a $b ([int]$script:Changes))
    } catch { }
}

# Saf: son N gundeki kayitlarin ozeti
function Get-ScoreSummary($Entries, [int]$Days, [datetime]$Now) {
    $r = @{ Count = 0; Changes = 0; Svc = 0; DiskFreeGb = 0.0 }
    foreach ($e in @($Entries)) {
        if ($null -eq $e) { continue }
        $t = [datetime]::MinValue
        try { $t = [datetime]::Parse([string]$e.B.Time, [System.Globalization.CultureInfo]::InvariantCulture) } catch { continue }
        if (($Now - $t).TotalDays -gt $Days) { continue }
        $d = Get-ScoreDelta $e.A $e.B
        $r.Count++; $r.Changes += [int]$e.Changes; $r.Svc += [int]$d.Svc
        if ([double]$d.DiskFreeGb -gt 0) { $r.DiskFreeGb = [math]::Round([double]$r.DiskFreeGb + [double]$d.DiskFreeGb, 1) }
    }
    return $r
}

# Kendi isleminde calisan hizmetlerin bellek kullanimi (paylasilan svchost islemleri sayilmaz)
function Get-ServiceMemTop([int]$N = 8) {
    $out = New-Object System.Collections.ArrayList
    try {
        $svc = @(Get-CimInstance -ClassName Win32_Service -OperationTimeoutSec 8 -ErrorAction Stop | Where-Object { [int]$_.ProcessId -gt 0 -and [string]$_.State -eq 'Running' })
        $byPid = @{}
        foreach ($s in $svc) { $k = [string]$s.ProcessId; if (-not $byPid.ContainsKey($k)) { $byPid[$k] = New-Object System.Collections.ArrayList }; [void]$byPid[$k].Add($s) }
        foreach ($k in @($byPid.Keys)) {
            if ($byPid[$k].Count -ne 1) { continue }
            $s = $byPid[$k][0]
            try {
                $p = Get-Process -Id ([int]$k) -ErrorAction Stop
                [void]$out.Add(@{ Name = [string]$s.Name; Display = [string]$s.DisplayName; Mb = [int]($p.WorkingSet64 / 1MB) })
            } catch { }
        }
    } catch { }
    return @($out.ToArray() | Sort-Object { -1 * [int]$_.Mb } | Select-Object -First $N)
}

function Job_ScoreView($P) {
    $boots = @()
    try { $boots = @((Get-BootEvents 30).Boots | Sort-Object { $_.Time } -Descending | Select-Object -First 6) } catch { $boots = @() }
    return @{ Ok = $true; Now = (Get-ScoreSnapshot); Entries = (Read-ScoreEntries 40); Services = @(Get-ServiceMemTop 8); Boots = $boots }
}

# ---------------- internete baglanan programlar ----------------
function Test-PrivateAddress([string]$Ip) {
    $a = ([string]$Ip).Trim().ToLowerInvariant()
    if ($a -eq '' -or $a -eq '::' -or $a -eq '0.0.0.0') { return $true }
    if ($a -eq '::1' -or $a.StartsWith('127.')) { return $true }
    if ($a.StartsWith('10.') -or $a.StartsWith('192.168.') -or $a.StartsWith('169.254.')) { return $true }
    if ($a -match '^172\.(1[6-9]|2\d|3[01])\.') { return $true }
    if ($a -match '^100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.') { return $true }
    if ($a.StartsWith('fe80:') -or $a.StartsWith('fc') -or $a.StartsWith('fd')) { return $true }
    return $false
}

# Saf: baglantilari programa gore toplar.
#   Conns: @(@{ Pid; Remote; Port })   Procs: @{ pid = @{ Name; Path } }
#   Donus: @(@{ Name; Path; Count; Hosts; Sample; Ports }) internet baglantisi en cok olandan aza
function Get-NetTalkers($Conns, $Procs) {
    $by = @{}
    foreach ($c in @($Conns)) {
        if ($null -eq $c) { continue }
        $ip = [string]$c.Remote
        if (Test-PrivateAddress $ip) { continue }
        $procId = [string]$c.Pid
        $name = 'PID ' + $procId; $path = ''
        if ($null -ne $Procs -and $Procs.ContainsKey($procId)) { $name = [string]$Procs[$procId].Name; $path = [string]$Procs[$procId].Path }
        $k = $path
        if ($k -eq '') { $k = 'ad:' + $name }
        $k = $k.ToLowerInvariant()
        if (-not $by.ContainsKey($k)) { $by[$k] = @{ Name = $name; Path = $path; Count = 0; Ips = @{}; Ports = @{} } }
        $by[$k].Count++
        $by[$k].Ips[$ip] = $true
        $by[$k].Ports[[string]$c.Port] = $true
    }
    $out = New-Object System.Collections.ArrayList
    foreach ($k in @($by.Keys)) {
        $e = $by[$k]
        $ips = @($e.Ips.Keys | Sort-Object)
        [void]$out.Add(@{ Name = [string]$e.Name; Path = [string]$e.Path; Count = [int]$e.Count; Hosts = $ips.Count; Sample = (@($ips | Select-Object -First 3) -join ', '); Ports = (@($e.Ports.Keys | Sort-Object { [int]$_ } | Select-Object -First 4) -join ', ') })
    }
    return @($out.ToArray() | Sort-Object @{ Expression = { [int]$_.Count }; Descending = $true }, @{ Expression = { [string]$_.Name } })
}

function Job_NetTalkers($P) {
    $conns = New-Object System.Collections.ArrayList
    $procs = @{}
    try {
        foreach ($c in @(Get-NetTCPConnection -State Established -ErrorAction Stop)) {
            [void]$conns.Add(@{ Pid = [int]$c.OwningProcess; Remote = [string]$c.RemoteAddress; Port = [int]$c.RemotePort })
        }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message } }
    foreach ($procId in @($conns | ForEach-Object { [string]$_.Pid } | Select-Object -Unique)) {
        try {
            $p = Get-Process -Id ([int]$procId) -ErrorAction Stop
            $path = ''
            try { $path = [string]$p.Path } catch { $path = '' }
            $procs[$procId] = @{ Name = [string]$p.ProcessName; Path = $path }
        } catch { }
    }
    $rows = @(Get-NetTalkers $conns.ToArray() $procs)
    foreach ($r in $rows) {
        $r.Blocked = $false; $r.CanBlock = $false; $r.Why = ''
        if ([string]$r.Path -ne '') {
            try { $r.Why = [string](Test-FwBlockAllowed ([string]$r.Path)); $r.CanBlock = ($r.Why -eq '') } catch { }
            try { [void](Get-NetFirewallRule -Name (Get-FwRuleId ([string]$r.Path)) -ErrorAction Stop); $r.Blocked = $true } catch { }
        } else { $r.Why = ('Program yolu okunamad' + [char]0x0131 + ' (sistem i' + [char]0x015F + 'lemi olabilir).') }
    }
    return @{ Ok = $true; Rows = $rows; Total = $conns.Count; At = (Get-Date).ToString('HH:mm:ss') }
}

