    @{ Rx = '(?i)^(Any Video Converter|Freemake)';        Id = 'HandBrake.HandBrake';               Name = 'HandBrake';    Why = ('video d' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + 't' + [char]0x00FC + 'r' + [char]0x00FC + 'r; filigran ve ek yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm teklifi yoktur') }
