    foreach ($k in @('HKLM\SOFTWARE\Mozilla\Mozilla Firefox', 'HKLM\SOFTWARE\WOW6432Node\Mozilla\Mozilla Firefox', 'HKCU\Software\Mozilla\Mozilla Firefox')) {
