# ---------------- yardim paketi ----------------
# Saf: metinden kisisel izleri siler (kullanici adi, bilgisayar adi, kullanici klasoru, IPv4, MAC, e-posta)
function Protect-SupportText([string]$Text, [string]$User, [string]$Computer) {
    $t = [string]$Text
    if ($t -eq '') { return '' }
    # once e-posta, MAC ve IP: kullanici adi e-posta adresinin parcasi olabilir
    $t = [regex]::Replace($t, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '<e-posta>')
    $t = [regex]::Replace($t, '(?<![0-9A-Fa-f])(?:[0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}(?![0-9A-Fa-f])', '<mac>')
    $t = [regex]::Replace($t, '(?<![\d.])(?:\d{1,3}\.){3}\d{1,3}(?![\d.])', '<ip>')
    if ([string]$User -ne '') {
        $t = [regex]::Replace($t, '(?i)([A-Za-z]:\\Users\\)' + [regex]::Escape($User), ('${1}<kullan' + [char]0x0131 + 'c' + [char]0x0131 + '>'))
        if ($User.Length -ge 3) { $t = [regex]::Replace($t, '(?i)(?<![A-Za-z0-9])' + [regex]::Escape($User) + '(?![A-Za-z0-9])', ('<kullan' + [char]0x0131 + 'c' + [char]0x0131 + '>')) }
    }
    if ([string]$Computer -ne '' -and $Computer.Length -ge 3) { $t = [regex]::Replace($t, '(?i)(?<![A-Za-z0-9])' + [regex]::Escape($Computer) + '(?![A-Za-z0-9])', '<bilgisayar>') }
    return $t
}

# Saf: pakete girecek ayar kopyasi (kisi, kurum, ag ve yol bilgisi cikarilir)
$script:SupportDropKeys = @('Contact', 'Org', 'BackupDest', 'BackupSources', 'GwBaseline', 'DeviceNames', 'KnownDevices', 'BlockedDevices', 'VpnName', 'VpnBaseHash', 'KillSwitchPrev', 'UpdateUrl', 'Games', 'NetOff')
function Get-SupportSettings($Settings) {
    $o = @{}
    if ($null -eq $Settings) { return $o }
    foreach ($k in @($Settings.Keys)) { if ($script:SupportDropKeys -notcontains [string]$k) { $o[[string]$k] = $Settings[$k] } }
    return $o
}

# Paketi hazirlar: surum, sistem ozeti, ayarlar (arindirilmis), son gunluk ve iz dosyalari (arindirilmis). Donus: @{ Ok; Path; Files; Error }
function Job_SupportBundle($P) {
    $dest = [string]$P.Dest
    if ($dest -eq '' -or -not (Test-Path -LiteralPath $dest -PathType Container)) { return @{ Ok = $false; Error = ('Hedef klas' + [char]0x00F6 + 'r bulunamad' + [char]0x0131 + '.') } }
    $user = [string]$env:USERNAME; $pc = [string]$env:COMPUTERNAME
    $work = Join-Path ([System.IO.Path]::GetTempPath()) ('mm-yardim-' + [guid]::NewGuid().ToString('N'))
    $n = 0
    try {
        [void](New-Item -ItemType Directory -Path $work -Force)
        $enc = New-Object System.Text.UTF8Encoding($true)
        $info = New-Object System.Collections.ArrayList
        [void]$info.Add('Multimizer ' + [string]$script:AppVersion)
        try { $os = Get-CimInstance -ClassName Win32_OperatingSystem -OperationTimeoutSec 5 -ErrorAction Stop; [void]$info.Add([string]$os.Caption + ' derleme ' + [string]$os.BuildNumber + ' ' + [string]$os.OSArchitecture) } catch { }
        try { $cs = Get-CimInstance -ClassName Win32_ComputerSystem -OperationTimeoutSec 5 -ErrorAction Stop; [void]$info.Add([string]$cs.Manufacturer + ' ' + [string]$cs.Model + (' ' + [char]0x00B7 + ' bellek ') + [string][int]([double]$cs.TotalPhysicalMemory / 1GB) + ' GB') } catch { }
        try { [void]$info.Add('PowerShell ' + $PSVersionTable.PSVersion.ToString() + (' ' + [char]0x00B7 + ' k' + [char]0x00FC + 'lt' + [char]0x00FC + 'r ') + [System.Globalization.CultureInfo]::CurrentUICulture.Name) } catch { }
        [void]$info.Add(('Haz' + [char]0x0131 + 'rland' + [char]0x0131 + ': ') + (Get-Date).ToString('yyyy-MM-dd HH:mm'))
        [System.IO.File]::WriteAllText((Join-Path $work 'ozet.txt'), (Protect-SupportText ($info -join "`r`n") $user $pc), $enc); $n++
        try { [System.IO.File]::WriteAllText((Join-Path $work 'ayarlar.json'), (Protect-SupportText ((Get-SupportSettings (Get-Settings)) | ConvertTo-Json -Depth 6) $user $pc), $enc); $n++ } catch { }
        $files = @()
        try { $files = @(Get-ChildItem -LiteralPath $script:LogDir -File -ErrorAction Stop | Where-Object { $_.Name -match '^(kayit-|hata-|oturum-iz)' } | Sort-Object LastWriteTime -Descending | Select-Object -First 8) } catch { $files = @() }
        foreach ($f in $files) {
            try {
                $txt = [System.IO.File]::ReadAllText($f.FullName)
                if ($txt.Length -gt 400000) { $txt = $txt.Substring($txt.Length - 400000) }
                [System.IO.File]::WriteAllText((Join-Path $work $f.Name), (Protect-SupportText $txt $user $pc), $enc); $n++
            } catch { }
        }
        $zip = Join-Path $dest ('Multimizer-yardim-' + (Get-Date -Format 'yyyyMMdd-HHmm') + '.zip')
        if (Test-Path -LiteralPath $zip) { Remove-Item -LiteralPath $zip -Force -ErrorAction Stop }
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
        [System.IO.Compression.ZipFile]::CreateFromDirectory($work, $zip)
        return @{ Ok = $true; Path = $zip; Files = $n }
    } catch { return @{ Ok = $false; Error = $_.Exception.Message } }
    finally { try { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
}

# ---------------- yeni bilgisayar / format sonrasi adimlari ----------------
# Saf: adim listesi. State: @{ Applied (uygulanan ayar sayisi); BackupDest; UseCase; PrepSeen; AppVersion }
#   Donus: @(@{ Key; Title; Detail; Done; Page; Tab; Btn })
function Get-SetupSteps($State) {
    $ap = 0; try { $ap = [int]$State.Applied } catch { }
    $steps = New-Object System.Collections.ArrayList
    [void]$steps.Add(@{ Key = 'updates'; Title = ('1 ' + [char]0x00B7 + ' Windows ve s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' g' + [char]0x00FC + 'ncellemeleri'); Detail = ('' + [char]0x00D6 + 'nce Windows' + [char]0x2019 + 'u g' + [char]0x00FC + 'ncelleyin: g' + [char]0x00FC + 'venlik yamalar' + [char]0x0131 + ' ve s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler di' + [char]0x011F + 'er ad' + [char]0x0131 + 'mlar' + [char]0x0131 + 'n sa' + [char]0x011F + 'l' + [char]0x0131 + 'kl' + [char]0x0131 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in gerekir.'); Done = $false; Page = 'updates'; Tab = ''; Btn = ('G' + [char]0x00FC + 'ncellemeler') })
    [void]$steps.Add(@{ Key = 'prep'; Title = ('2 ' + [char]0x00B7 + ' Eksik bile' + [char]0x015F + 'enler (Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k)'); Detail = ('Oyunlar' + [char]0x0131 + 'n ve programlar' + [char]0x0131 + 'n istedi' + [char]0x011F + 'i ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma zamanlar' + [char]0x0131 + ' (Visual C++, .NET, DirectX) denetlenir; eksik olan buradan kurulur.'); Done = ([string]$State.PrepSeen -ne '' -and [string]$State.PrepSeen -eq [string]$State.AppVersion); Page = 'solve'; Tab = 'prep'; Btn = ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k') })
    [void]$steps.Add(@{ Key = 'tune'; Title = ('3 ' + [char]0x00B7 + ' ' + [char]0x00D6 + 'nerilen ayarlar'); Detail = ('Donan' + [char]0x0131 + 'm' + [char]0x0131 + 'n' + [char]0x0131 + 'za ve kullan' + [char]0x0131 + 'm t' + [char]0x00FC + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'ze g' + [char]0x00F6 + 're ' + [char]0x00F6 + 'nerilen gizlilik ve performans ayarlar' + [char]0x0131 + '. ' + [char]0x00D6 + 'nce ' + [char]0x00F6 + 'nizleme g' + [char]0x00F6 + 'sterilir; her ' + [char]0x015F + 'ey geri al' + [char]0x0131 + 'nabilir.'); Done = ($ap -gt 0); Page = 'optimize'; Tab = ''; Btn = ('' + [char]0x0130 + 'yile' + [char]0x015F + 'tir') })
    [void]$steps.Add(@{ Key = 'apps'; Title = ('4 ' + [char]0x00B7 + ' Temel programlar (a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak)'); Detail = ('Taray' + [char]0x0131 + 'c' + [char]0x0131 + ', ar' + [char]0x015F + 'iv, ofis, medya oynat' + [char]0x0131 + 'c' + [char]0x0131 + ' gibi temel programlar winget deposundan imza do' + [char]0x011F + 'rulamas' + [char]0x0131 + 'yla kurulur.'); Done = $false; Page = 'apps'; Tab = 'foss'; Btn = 'Programlar' })
    [void]$steps.Add(@{ Key = 'backup'; Title = ('5 ' + [char]0x00B7 + ' Yedekleme hedefi'); Detail = ('Belgelerinizin d' + [char]0x00FC + 'zenli kopyas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bir hedef (ikinci disk ya da harici disk) se' + [char]0x00E7 + 'in.'); Done = ([string]$State.BackupDest -ne ''); Page = 'backup'; Tab = ''; Btn = 'Yedekleme' })
    [void]$steps.Add(@{ Key = 'health'; Title = ('6 ' + [char]0x00B7 + ' Son denetim'); Detail = ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ' g' + [char]0x00FC + 'venlik, performans ve bak' + [char]0x0131 + 'm durumunu tek ekranda g' + [char]0x00F6 + 'sterir.'); Done = $false; Page = 'board'; Tab = ''; Btn = 'Durum' })
    return $steps.ToArray()
}

# ---------------- disk sifrelemeyi acma ----------------
# Windows Home: BitLocker yonetimi yoktur; sistem surucusu Ayarlar'daki "Cihaz sifrelemesi" ile sifrelenir.
function Test-HomeEdition([string]$EditionId = '') {
    $e = $EditionId
    if ($e -eq '') { $e = [string](Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'EditionID' '') }
    return ($e -match '^Core')
}

# Saf: bu surucu icin sifrelemeyi acma yolu.  'Enable' (uygulama icinden) | 'Panel' (Windows BitLocker penceresi) | 'Settings' (Cihaz sifrelemesi) | 'None'
function Get-BlEnableRoute([string]$Drive, [string]$SystemDrive, [bool]$IsHome) {
    $d = ([string]$Drive).TrimEnd('\').ToUpperInvariant()
    $s = ([string]$SystemDrive).TrimEnd('\').ToUpperInvariant()
    if ($d -cnotmatch '^[A-Z]:$') { return 'None' }
    if ($IsHome) { if ($d -eq $s) { return 'Settings' } else { return 'None' } }
    if ($d -eq $s) { return 'Enable' }
    return 'Panel'
}

# Sistem surucusunde BitLocker'i baslatir: TPM + 48 haneli kurtarma parolasi, yalnizca kullanilan alan.
# Windows once donanim sinamasi ister; sifreleme yeniden baslatmadan sonra baslar. Sonuc geri okunarak dogrulanir.
function Job_BitLockerEnable($P) {
    $drive = ([string]$P.Drive).TrimEnd('\')
    if ($drive -cnotmatch '^[A-Za-z]:$') { return @{ Ok = $false; Error = ('Ge' + [char]0x00E7 + 'ersiz s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '.') } }
    if ((Get-BlEnableRoute $drive ([string]$env:SystemDrive) (Test-HomeEdition)) -ne 'Enable') { return @{ Ok = $false; Error = ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' uygulama i' + [char]0x00E7 + 'inden ' + [char]0x015F + 'ifrelenemez.') } }
    $exe = Join-Path (Join-Path $env:WINDIR 'System32') 'manage-bde.exe'
    if (-not (Test-Path -LiteralPath $exe)) { return @{ Ok = $false; Error = ('manage-bde.exe bulunamad' + [char]0x0131 + '.') } }
    Write-WhLog (('=== BitLocker a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'yor: ') + $drive) 'STEP'
    $txt = ''
    try { $txt = (& $exe -on $drive -UsedSpaceOnly -RecoveryPassword 2>&1 | Out-String) } catch { return @{ Ok = $false; Error = $_.Exception.Message } }
    $code = $LASTEXITCODE
    # kurtarma parolasi gunluge yazilmaz
    $safe = [regex]::Replace($txt, '(\d{6}-){7}\d{6}', ('<kurtarma parolas' + [char]0x0131 + ' gizlendi>'))
    foreach ($l in @($safe -split "`r?`n")) { if ($l.Trim() -ne '') { Write-WhLog ('   ' + $l.Trim()) 'INFO' } }
    if ($code -ne 0) { Write-WhLog (('manage-bde ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$code) 'ERR'; return @{ Ok = $false; Error = (('Windows ' + [char]0x015F + 'ifrelemeyi ba' + [char]0x015F + 'latmad' + [char]0x0131 + ' (kod ') + [string]$code + ('). Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.')) } }
    $v = @(Get-BitLockerVolumes | Where-Object { ([string]$_.Drive).TrimEnd('\') -ieq $drive } | Select-Object -First 1)
    $has = ($v.Count -gt 0 -and $v[0].HasRecovery -eq $true)
    if (-not $has) { Write-WhLog ('BitLocker komutu tamamland' + [char]0x0131 + ' ama kurtarma anahtar' + [char]0x0131 + ' do' + [char]0x011F + 'rulanamad' + [char]0x0131 + '.') 'WARN' }
    else { Write-WhLog ('BitLocker ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + '; kurtarma anahtar' + [char]0x0131 + ' tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' (do' + [char]0x011F + 'ruland' + [char]0x0131 + ').') 'OK' }
    return @{ Ok = $true; Verified = $has; Reboot = ($txt -match '(?i)restart|yeniden ba') }
}

