$script:AskTopics = $null
function Get-AskTopics {
    if ($null -eq $script:AskTopics) { $script:AskTopics = @(Get-AskTopicData) }
    return $script:AskTopics
}

$script:AskStop = @('ve', 'ile', 'bir', 'bu', 'su', 'ne', 'nasil', 'neden', 'nicin', 'icin', 'mi', 'mu', 'cok', 'daha', 'en', 'ben', 'benim', 'bana', 'beni', 'var', 'yok', 'da', 'de', 'ki', 'ama', 'gibi', 'olan', 'olarak',
    'istiyorum', 'lazim', 'gerek', 'yapabilirim', 'yaparim', 'yapilir', 'edebilirim', 'bilgisayar', 'bilgisayarim', 'pc', 'windows', 'the', 'my', 'is', 'how', 'to')

# Her dilin kendi baglaclari: dil dosyasindaki ceviri bosluklu liste olarak gelir; ceviri yoksa yalnizca Turkce liste kullanilir
$script:AskStopMore = ('ve ile bir bu ' + [char]0x015F + 'u ne nas' + [char]0x0131 + 'l neden i' + [char]0x00E7 + 'in ' + [char]0x00E7 + 'ok daha')

# Saf: metni esleme bicimine getirir: kucuk harf, Latin aksanlari kaldirilmis (s->s, e->e, ?->ss), Turkce i/I kurali.
# Tablo acik yazilidir: .NET'in Normalize islevi degismez kulturde (sinama ortami) aksan ayirmaz.
$script:AskFoldMap = $null
function Get-AskFoldMap {
    if ($null -ne $script:AskFoldMap) { return $script:AskFoldMap }
    $m = @{}
    $groups = @(
        @('a', ('' + [char]0x00E0 + '' + [char]0x00E1 + '' + [char]0x00E2 + '' + [char]0x00E3 + '' + [char]0x00E4 + '' + [char]0x00E5 + '' + [char]0x0101 + '' + [char]0x0103 + '' + [char]0x0105 + '')), @('c', ('' + [char]0x00E7 + '' + [char]0x0107 + '' + [char]0x010D + '' + [char]0x0109 + '' + [char]0x010B + '')), @('d', ('' + [char]0x010F + '' + [char]0x0111 + '')), @('e', ('' + [char]0x00E8 + '' + [char]0x00E9 + '' + [char]0x00EA + '' + [char]0x00EB + '' + [char]0x0113 + '' + [char]0x0115 + '' + [char]0x0117 + '' + [char]0x0119 + '' + [char]0x011B + '')), @('g', ('' + [char]0x011F + '' + [char]0x011D + '' + [char]0x0121 + '' + [char]0x0123 + '')), @('h', ('' + [char]0x0125 + '' + [char]0x0127 + '')), @('i', ('' + [char]0x00EC + '' + [char]0x00ED + '' + [char]0x00EE + '' + [char]0x00EF + '' + [char]0x0129 + '' + [char]0x012B + '' + [char]0x012D + '' + [char]0x012F + '' + [char]0x0131 + '')),
        @('j', ('' + [char]0x0135 + '')), @('k', ('' + [char]0x0137 + '')), @('l', ('' + [char]0x013A + '' + [char]0x013C + '' + [char]0x013E + '' + [char]0x0140 + '' + [char]0x0142 + '')), @('n', ('' + [char]0x00F1 + '' + [char]0x0144 + '' + [char]0x0146 + '' + [char]0x0148 + '' + [char]0x0149 + '')), @('o', ('' + [char]0x00F2 + '' + [char]0x00F3 + '' + [char]0x00F4 + '' + [char]0x00F5 + '' + [char]0x00F6 + '' + [char]0x00F8 + '' + [char]0x014D + '' + [char]0x014F + '' + [char]0x0151 + '')), @('r', ('' + [char]0x0155 + '' + [char]0x0157 + '' + [char]0x0159 + '')), @('s', ('' + [char]0x015F + '' + [char]0x015B + '' + [char]0x015D + '' + [char]0x0161 + '' + [char]0x0219 + '')), @('t', ('' + [char]0x0163 + '' + [char]0x0165 + '' + [char]0x0167 + '' + [char]0x021B + '')),
        @('u', ('' + [char]0x00F9 + '' + [char]0x00FA + '' + [char]0x00FB + '' + [char]0x00FC + '' + [char]0x0169 + '' + [char]0x016B + '' + [char]0x016D + '' + [char]0x016F + '' + [char]0x0171 + '' + [char]0x0173 + '')), @('w', ('' + [char]0x0175 + '')), @('y', ('' + [char]0x00FD + '' + [char]0x00FF + '' + [char]0x0177 + '')), @('z', ('' + [char]0x017A + '' + [char]0x017C + '' + [char]0x017E + '')), @('ss', ('' + [char]0x00DF + '')), @('ae', ('' + [char]0x00E6 + '')), @('oe', ('' + [char]0x0153 + '')), @(('' + [char]0x0435 + ''), ('' + [char]0x0451 + '')))
    foreach ($g in $groups) { foreach ($ch in ([string]$g[1]).ToCharArray()) { $m[[int]$ch] = [string]$g[0] } }
    $script:AskFoldMap = $m
    return $m
}
function ConvertTo-AskKey([string]$Text) {
    $t = ([string]$Text).Replace([string][char]0x0130, 'i').Replace([string][char]0x0131, 'i').ToLowerInvariant()
    $map = Get-AskFoldMap
    $sb = New-Object System.Text.StringBuilder
    foreach ($ch in $t.ToCharArray()) {
        $code = [int]$ch
        if ($map.ContainsKey($code)) { [void]$sb.Append($map[$code]) }
        elseif ([System.Globalization.CharUnicodeInfo]::GetUnicodeCategory($ch) -ne [System.Globalization.UnicodeCategory]::NonSpacingMark) { [void]$sb.Append($ch) }
    }
    return $sb.ToString()
}

# Saf: metin Cince/Japonca/Korece harf iceriyor mu (bosluksuz yazilan diller: govde icerme ile eslenir)
function Test-AskCjk([string]$Text) {
    return [regex]::IsMatch([string]$Text, '[\u3040-\u30FF\u3400-\u4DBF\u4E00-\u9FFF\uAC00-\uD7AF]')
}

# Saf: soru metni -> anlamli sozcukler (kucuk harf, sadelestirilmis; baglaclar atilir). Her dilin harfleri korunur.
function Get-AskTokens([string]$Text) {
    $q = ConvertTo-AskKey ([string]$Text)
    $stop = New-Object System.Collections.ArrayList
    foreach ($w in @($script:AskStop)) { [void]$stop.Add($w) }
    foreach ($w in @((ConvertTo-AskKey (Tr $script:AskStopMore)) -split '\s+')) { if ($w -ne '' -and -not $stop.Contains($w)) { [void]$stop.Add($w) } }
    $out = New-Object System.Collections.ArrayList
    foreach ($w in @($q -csplit '[^\p{L}\p{N}]+')) {
        if ($w.Length -lt 2 -or $stop.Contains($w)) { continue }
        if (-not $out.Contains($w)) { [void]$out.Add($w) }
    }
    return , $out.ToArray()
}

# Saf: konunun govdeleri. Dil dosyasinda cevirisi varsa o dilin govdeleri, yoksa Turkce govdeler; ikisi de esleme bicimine getirilir.
function Get-AskStems($Topic) {
    $w = [string]$Topic.W
    $tr = [string](Tr $w)
    $all = $w
    if ($tr -ne '' -and $tr -ne $w) { $all = $w + ' ' + $tr }
    $out = New-Object System.Collections.ArrayList
    foreach ($s in @((ConvertTo-AskKey $all) -split '\s+')) { if ($s -ne '' -and -not $out.Contains($s)) { [void]$out.Add($s) } }
    return , $out.ToArray()
}

# Saf: konu puani. Tam esleme 3; sozcuk govdeyle basliyorsa (govde en az 4 harf) 2; Cince/Japonca/Korece govde sozcugun icinde geciyorsa 3.
function Get-AskScore($Topic, $Tokens) {
    $stems = Get-AskStems $Topic
    $stems = @($stems)
    $score = 0
    foreach ($t in @($Tokens)) {
        $best = 0
        foreach ($s in $stems) {
            if ($t -eq $s) { $best = 3; break }
            if ($s.Length -ge 4 -and $t.Length -gt $s.Length -and $t.StartsWith($s)) { if ($best -lt 2) { $best = 2 } }
            elseif ((Test-AskCjk $s) -and $t.Length -gt $s.Length -and $t.Contains($s)) { $best = 3; break }
        }
        $score += $best
    }
    return $score
}

# Saf: en iyi konular (puani 2 ve uzeri), puana gore; esit puanda tablo sirasi
function Get-AskMatches([string]$Text, [int]$Max = 2) {
    $tok = Get-AskTokens $Text
    $hits = New-Object System.Collections.ArrayList
    if ($tok.Count -eq 0) { return , $hits.ToArray() }
    $i = 0
    foreach ($tp in @(Get-AskTopics)) {
        $s = Get-AskScore $tp $tok
        if ($s -ge 2) { [void]$hits.Add(@{ Topic = $tp; Score = $s; Order = $i }) }
        $i++
    }
    $sorted = @($hits.ToArray() | Sort-Object @{ Expression = { [int]$_.Score }; Descending = $true }, @{ Expression = { [int]$_.Order } })
    return , @($sorted | Select-Object -First $Max)
}

# Saf: soruya cevap.  Commands: komut adi -> aciklama (komut satirinin tablosu)   PageHits: sayfa/eylem aramasinin sonuclari (@{ Text; Tag })
#   Donus: @{ Kind = 'topic' | 'command' | 'pages' | 'none'; Title; Text; Actions = @(@{ L; Tag }); Also = '' }
function Get-AskAnswer([string]$Text, $Commands = $null, $PageHits = @()) {
    $q = ([string]$Text).Trim()
    $res = @{ Kind = 'none'; Title = ''; Text = ''; Actions = @(); Also = '' }
    if ($q -eq '') { return $res }
    $first = ''
    $parts = @((ConvertTo-AskKey $q) -split '\s+' | Where-Object { $_ -ne '' })
    if ($parts.Count -gt 0) { $first = [string]$parts[0] }
    if ($null -ne $Commands -and $first -ne '' -and $first -ne 'yardim' -and $Commands.Contains($first) -and $parts.Count -le 3) {
        $res.Kind = 'command'; $res.Title = 'Komut: ' + $first
        $res.Text = [string]$Commands[$first]
        $res.Actions = @(@{ L = ('Komutu ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r'); Tag = ('cmd:' + $q) })
        return $res
    }
    $m = Get-AskMatches $q 2
    if ($m.Count -gt 0) {
        $t = $m[0].Topic
        $res.Kind = 'topic'; $res.Title = [string]$t.T; $res.Text = [string]$t.A; $res.Actions = @($t.Do)
        if ($m.Count -gt 1 -and [int]$m[1].Score -ge 3) { $res.Also = [string]$m[1].Topic.T; $res.AlsoKey = [string]$m[1].Topic.K }
        return $res
    }
    $ph = @(@($PageHits) | Where-Object { $null -ne $_ } | Select-Object -First 4)
    if ($ph.Count -gt 0) {
        $res.Kind = 'pages'; $res.Title = 'Bununla ilgili sayfalar'
        $res.Text = ('Tam bir cevab' + [char]0x0131 + 'm yok ama arad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z bu sayfalardan birinde olabilir.')
        $res.Actions = @($ph | ForEach-Object { @{ L = [string]$_.Text; Tag = [string]$_.Tag } })
        return $res
    }
    $res.Title = ('Bunu bulamad' + [char]0x0131 + 'm')
    $res.Text = ('Soruyu birka' + [char]0x00E7 + ' s' + [char]0x00F6 + 'zc' + [char]0x00FC + 'kle, ne oldu' + [char]0x011F + 'unu ya da ne yapmak istedi' + [char]0x011F + 'inizi yazarak deneyin: ' + [char]0x201C + 'bilgisayar yava' + [char]0x015F + '' + [char]0x201D + ', ' + [char]0x201C + 'disk doldu' + [char]0x201D + ', ' + [char]0x201C + 'internet kopuyor' + [char]0x201D + ', ' + [char]0x201C + 'silinen dosya' + [char]0x201D + ', ' + [char]0x201C + 'parola ' + [char]0x00FC + 'ret' + [char]0x201D + '.')
    return $res
}

# Saf: bos ekranda gosterilecek ornek sorular
function Get-AskSamples {
    return @(@(Get-AskTopics) | Where-Object { [string]$_.Q -ne '' } | ForEach-Object { [string]$_.Q })
}

function Get-AskTopic([string]$Key) {
    foreach ($t in @(Get-AskTopics)) { if ([string]$t.K -eq $Key) { return $t } }
    return $null
}

# Saf: sol cubuk icin sayfanin alt sekmeleri. Xaml: sayfanin XAML metni. Donus: @(@{ Key; Text })
function Get-PageSubTabs([string]$Xaml) {
    $out = New-Object System.Collections.ArrayList
    if ([string]$Xaml -eq '') { return , $out.ToArray() }
    foreach ($m in [regex]::Matches($Xaml, 'x:Name="[a-z]+_Tab_([A-Za-z0-9]+)" Content="([^"]*)"')) {
        [void]$out.Add(@{ Key = $m.Groups[1].Value; Text = [System.Net.WebUtility]::HtmlDecode($m.Groups[2].Value) })
    }
    return , $out.ToArray()
}

# Saf: aciklama metni tek satira indirilecek kadar uzun mu?
function Test-DescLong([string]$Text, [int]$Limit = 64) {
    return (([string]$Text).Trim().Length -gt $Limit)
}

# Saf: sayfa XAML'inde aciklama paragraflarini isaretler (TxtDim bicimli, satir kaydirmali, adsiz TextBlock -> Tag="desc")
function Add-DescTags([string]$Xaml) {
    return [regex]::Replace([string]$Xaml, '<TextBlock (?![^>]*\bTag=)(?![^>]*x:Name=)(?=[^>]*Style="\{DynamicResource TxtDim\}")(?=[^>]*TextWrapping="Wrap")', '<TextBlock Tag="desc" ')
}

# ---------------- servis: DISM sure siniri, Windows Update mesgul denetimi ----------------
# ---------------- Windows bilesen servisi (DISM): mesgul denetimi ve sure sinirli calistirma ----------------
# Gercek bilgisayarda (17.11.2026) Windows Update bir guncelleme kurarken Enable-WindowsOptionalFeature 1,5 saat bekleyip
# 0x80240021 (Windows Update zaman asimi) verdi; o surede islem asili kaldi ve ozellik geri acilamadi.
# Windows ozelligi ve bilesen islemleri artik:
#  1) DISM'i ayri bir surecte calistirir ve en cok $script:DismLimitMin dakika bekler; asili kalirsa sureci kapatip acik bir hata verir,
#  2) ozelligi once yalnizca yerel kaynakla acmayi dener (/LimitAccess: Windows Update'e gitmez, saniyeler icinde sonuclanir),
#  3) yerel kaynak yetmezse ve Windows Update o anda guncelleme kurmuyorsa Windows Update kaynagiyla (yine sure sinirli) dener.
$script:DismLimitMin = 15
# Bu oturumda DISM "once yeniden baslatin" turunden bir kodla reddetti mi (canli denetim kurtarmayi buna gore erteler)
$script:DismNeedsReboot = $false
# Bu oturumda bir DISM sure sinirini asti mi? Astiysa bilesen hizmeti (TrustedInstaller) isi arka planda surduruyor olabilir:
# gercek bilgisayarda (17.11.2026) sure dolunca kapatilan DISM'den sonraki ozellik islemi 20 dakika asili kaldi. Bu bayrak acikken
# yeni DISM islemi baslatilmaz; acik bir hata ile yeniden baslatma istenir.
$script:DismTimedOut = $false

# Windows Update su anda guncelleme kuruyor mu? Donus: '' (hayir) ya da nedeni anlatan metin
function Get-ServicingBusy {
    try {
        $inst = New-Object -ComObject Microsoft.Update.Installer
        if ([bool]$inst.IsBusy) { return ('Windows Update ' + [char]0x015F + 'u anda bir g' + [char]0x00FC + 'ncelleme kuruyor') }
    } catch { }
    return ''
}

# dism.exe yolu (32 bit PowerShell 64 bit Windows'ta Sysnative uzerinden; 32 bit DISM calisan 64 bit sisteme hizmet veremez)
function Get-DismExePath {
    $p = Join-Path $env:WINDIR 'System32\dism.exe'
    try { if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { $p = Join-Path $env:WINDIR 'Sysnative\dism.exe' } } catch { }
    return $p
}

# DISM cikis kodunun onaltilik yazimi ve aciklamasi
function Get-DismCodeText([int64]$Code) {
    if ($Code -eq -1) { return ('DISM ' + $script:DismLimitMin + (' dakikada bitmedi (Windows Update me' + [char]0x015F + 'gul olabilir)')) }
    $u = [uint32]($Code -band 0xFFFFFFFFL)
    $hex = '0x' + $u.ToString('X8')
    switch ($hex) {
        '0x800F081F' { return ($hex + (': Windows bu ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'in kaynak dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + ' bulamad' + [char]0x0131 + '')) }
        '0x800F0906' { return ($hex + (': kaynak dosyalar indirilemedi (internet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ')')) }
        '0x800F0907' { return ($hex + (': kurum ilkesi Windows Update kayna' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' engelliyor')) }
        '0x800F0954' { return ($hex + (': Windows Update kayna' + [char]0x011F + '' + [char]0x0131 + 'na ula' + [char]0x015F + '' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (kurum ilkesi / WSUS)')) }
        '0x80240021' { return ($hex + (': Windows Update zaman a' + [char]0x015F + '' + [char]0x0131 + 'm' + [char]0x0131 + 'na u' + [char]0x011F + 'rad' + [char]0x0131 + '')) }
        '0x800F0922' { return ($hex + (': i' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '')) }
        '0x800F080C' { return ($hex + (': Windows bu ' + [char]0x00F6 + 'zellik ad' + [char]0x0131 + 'n' + [char]0x0131 + ' tan' + [char]0x0131 + 'm' + [char]0x0131 + 'yor')) }
        '0x80070005' { return ($hex + (': eri' + [char]0x015F + 'im reddedildi (y' + [char]0x00F6 + 'netici izni gerekir)')) }
        '0x800F0831' { return ($hex + (': bile' + [char]0x015F + 'en deposunda eksik paket var')) }
        '0x800F082F' { return ($hex + (': Windows bekleyen bir i' + [char]0x015F + 'lem i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmay' + [char]0x0131 + ' bekliyor')) }
        '0x80070BC9' { return ($hex + (': ' + [char]0x00F6 + 'nceki bir kurulum yeniden ba' + [char]0x015F + 'latma bekliyor')) }
        '0x800F0806' { return ($hex + (': bekleyen bir bile' + [char]0x015F + 'en i' + [char]0x015F + 'lemi var; ' + [char]0x00F6 + 'nce bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n')) }
        '0x800F0912' { return ($hex + (': ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'in dosyalar' + [char]0x0131 + ' bu bilgisayarda yok; Windows Update' + [char]0x2019 + 'ten indirilmesi gerekiyor')) }
        '0x800F0915' { return ($hex + (': ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'in i' + [char]0x00E7 + 'eri' + [char]0x011F + 'i hi' + [char]0x00E7 + 'bir kaynakta bulunamad' + [char]0x0131 + '')) }
        '0x800F0950' { return ($hex + (': bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' i' + [char]0x00E7 + 'in iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' i' + [char]0x00E7 + 'erik bulunamad' + [char]0x0131 + '')) }
        '0x80240438' { return ($hex + (': Windows Update hizmetine ula' + [char]0x015F + '' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (a' + [char]0x011F + ', g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' ya da vekil sunucu)')) }
        '0x0000371B' { return ($hex + (': Windows bile' + [char]0x015F + 'en kurulum ad' + [char]0x0131 + 'm' + [char]0x0131 + ' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z oldu (' + [char]0x00E7 + 'o' + [char]0x011F + 'unlukla bekleyen bir de' + [char]0x011F + 'i' + [char]0x015F + 'iklik y' + [char]0x00FC + 'z' + [char]0x00FC + 'nden)')) }
    }
    return ('kod ' + $hex)
}

# dism.exe'yi ayri surecte, sure siniriyla calistirir. Donus: cikis kodu (-1: sure doldu, surec kapatildi)
function Invoke-DismExe([string[]]$DismArgs, [int]$LimitMin = 0) {
    if ($LimitMin -le 0) { $LimitMin = $script:DismLimitMin }
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = Get-DismExePath
    $psi.Arguments = ($DismArgs -join ' ')
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $p = [System.Diagnostics.Process]::Start($psi)
    if ($null -eq $p) { throw ('dism.exe ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') }
    if (-not $p.WaitForExit($LimitMin * 60000)) {
        # asili kalan DISM ve yardimci sureci (DismHost.exe) kapatilir; islem bilesen servisinde tamamlanmamissa geri sarilir
        try { foreach ($ch in @(Get-CimInstance -ClassName Win32_Process -Filter ('ParentProcessId=' + [string]$p.Id) -ErrorAction Stop)) { try { Stop-Process -Id ([int]$ch.ProcessId) -Force -ErrorAction Stop } catch { } } } catch { }
        try { $p.Kill() } catch { }
        try { [void]$p.WaitForExit(5000) } catch { }
        $script:DismTimedOut = $true
        return -1
    }
    return [int]$p.ExitCode
}

# Bilesen servisi (CBS) yeniden baslatma bekliyor mu? Donus: '' ya da bekleyen anahtarin adi. Bekleyen islem varken
# DISM bilesen deposu temizligi 0x800F0806 ile basarisiz olur (cihazda 18.11.2026).
# Bu DISM kodu kaynak eksikligi degil, bekleyen bir degisiklik / yeniden baslatma geregi mi? O zaman Windows Update kaynagiyla
# ikinci deneme ise yaramaz (cihazda 0x371B iki kaynakta da ayni geldi); hemen yeniden baslatma onerilir.
function Test-DismRebootCode([int64]$Code) {
    if ($Code -eq 0 -or $Code -eq -1 -or $Code -eq 3010) { return $false }
    $hex = '0x' + ([uint32]($Code -band 0xFFFFFFFFL)).ToString('X8')
    return (@('0x800F0806', '0x800F082F', '0x80070BC9', '0x0000371B') -contains $hex)
}

function Get-CbsRebootPending {
    try {
        $cbs = Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
        foreach ($k in @('RebootPending', 'RebootInProgress', 'PackagesPending')) { if ($cbs -contains $k) { return $k } }
    } catch { }
    return ''
}

# Bu oturumda bir DISM sure sinirini astiysa yeni DISM islemi baslatilmaz (bilesen hizmeti hala calisiyor olabilir)
function Assert-DismReady {
    if ($script:DismTimedOut) { throw ('' + [char]0x00F6 + 'nceki bir DISM i' + [char]0x015F + 'lemi s' + [char]0x00FC + 're s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x015F + 't' + [char]0x0131 + '; Windows bile' + [char]0x015F + 'en hizmeti h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor olabilir. Bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p tekrar deneyin.') }
}

# Windows ozelligini acar/kapatir (dism.exe, sure sinirli). Donus: $true = yeniden baslatma gerekiyor. Basarisizlikta aciklamali hata atar.
function Set-WinFeatureState([string]$Name, [bool]$On) {
    if ($Name -cnotmatch '^[A-Za-z0-9\.\-_]{2,120}$') { throw (('Ge' + [char]0x00E7 + 'ersiz Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i ad' + [char]0x0131 + ': ') + $Name) }
    Assert-DismReady
    if (-not $On) {
        $rc = Invoke-DismExe @('/Online', '/Disable-Feature', ('/FeatureName:' + $Name), '/NoRestart', '/Quiet')
        if ($rc -eq 0) { return $false }
        if ($rc -eq 3010) { return $true }
        throw (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i kapat' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (') + $Name + '): ' + (Get-DismCodeText $rc))
    }
    $rc = Invoke-DismExe @('/Online', '/Enable-Feature', ('/FeatureName:' + $Name), '/All', '/NoRestart', '/LimitAccess', '/Quiet')
    if ($rc -eq 0) { return $false }
    if ($rc -eq 3010) { return $true }
    $first = Get-DismCodeText $rc
    # yerel deneme sure sinirini astiysa bilesen hizmeti mesguldur: Windows Update kaynagiyla ikinci bir uzun deneme yapilmaz
    if (Test-DismRebootCode $rc) { $script:DismNeedsReboot = $true }
    if ($rc -eq -1 -or (Test-DismRebootCode $rc)) { throw (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (') + $Name + '): ' + $first + ('. Bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p tekrar deneyin.')) }
    $busy = Get-ServicingBusy
    if ($busy -ne '') { throw (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (') + $Name + '): ' + $first + '. ' + $busy + ('; g' + [char]0x00FC + 'ncelleme bitince (gerekirse yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p) tekrar deneyin.')) }
    Write-WhLog ('Yerel kaynak yetmedi (' + $first + ('); Windows Update kayna' + [char]0x011F + '' + [char]0x0131 + ' deneniyor: ') + $Name) 'INFO'
    $rc2 = Invoke-DismExe @('/Online', '/Enable-Feature', ('/FeatureName:' + $Name), '/All', '/NoRestart', '/Quiet')
    if ($rc2 -eq 0) { return $false }
    if ($rc2 -eq 3010) { return $true }
    if (Test-DismRebootCode $rc2) { $script:DismNeedsReboot = $true }
    throw (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (') + $Name + '): yerel kaynak ' + $first + ('; Windows Update kayna' + [char]0x011F + '' + [char]0x0131 + ' ') + (Get-DismCodeText $rc2) + ('. Bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p tekrar deneyin.'))
}

# Windows bilesenini (istege bagli ozellik / FOD) kaldirir ya da kurar (dism.exe, sure sinirli). Donus: $true = yeniden baslatma gerekiyor
function Set-WinCapabilityState([string]$Name, [bool]$Present) {
    if ($Name -cnotmatch '^[A-Za-z0-9\.\-_~]{3,160}$') { throw (('Ge' + [char]0x00E7 + 'ersiz Windows bile' + [char]0x015F + 'eni ad' + [char]0x0131 + ': ') + $Name) }
    Assert-DismReady
    if (-not $Present) {
        $rc = Invoke-DismExe @('/Online', '/Remove-Capability', ('/CapabilityName:' + $Name), '/NoRestart', '/Quiet')
        if ($rc -eq 0) { return $false }
        if ($rc -eq 3010) { return $true }
        throw (('Windows bile' + [char]0x015F + 'eni kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (') + $Name + '): ' + (Get-DismCodeText $rc))
    }
    $rc = Invoke-DismExe @('/Online', '/Add-Capability', ('/CapabilityName:' + $Name), '/LimitAccess', '/NoRestart', '/Quiet')
    if ($rc -eq 0) { return $false }
    if ($rc -eq 3010) { return $true }
    $first = Get-DismCodeText $rc
    if (Test-DismRebootCode $rc) { $script:DismNeedsReboot = $true }
    if ($rc -eq -1 -or (Test-DismRebootCode $rc)) { throw (('Windows bile' + [char]0x015F + 'eni kurulamad' + [char]0x0131 + ' (') + $Name + '): ' + $first + ('. Bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p tekrar deneyin.')) }
    $busy = Get-ServicingBusy
    if ($busy -ne '') { throw (('Windows bile' + [char]0x015F + 'eni kurulamad' + [char]0x0131 + ' (') + $Name + '): ' + $first + '. ' + $busy + ('; g' + [char]0x00FC + 'ncelleme bitince tekrar deneyin.')) }
    Write-WhLog ('Yerel kaynak yetmedi (' + $first + ('); Windows Update kayna' + [char]0x011F + '' + [char]0x0131 + ' deneniyor: ') + $Name) 'INFO'
    $rc2 = Invoke-DismExe @('/Online', '/Add-Capability', ('/CapabilityName:' + $Name), '/NoRestart', '/Quiet')
    if ($rc2 -eq 0) { return $false }
    if ($rc2 -eq 3010) { return $true }
    if (Test-DismRebootCode $rc2) { $script:DismNeedsReboot = $true }
    throw (('Windows bile' + [char]0x015F + 'eni kurulamad' + [char]0x0131 + ' (') + $Name + '): yerel kaynak ' + $first + ('; Windows Update kayna' + [char]0x011F + '' + [char]0x0131 + ' ') + (Get-DismCodeText $rc2) + ('. ' + [char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + 'n' + [char]0x0131 + ' denetleyip tekrar deneyin.'))
}

# Windows istege bagli ozelliginin durumu. DISM (Get-WindowsOptionalFeature) yonetici ister; yonetici degilken ya da DISM
# okuyamazsa Win32_OptionalFeature (WMI, standart kullaniciya acik) kullanilir. Donus: $null = bu surumde yok; aksi halde
# FeatureName/State tasiyan nesne (State: Enabled, Disabled, DisabledWithPayloadRemoved...). Okunamazsa hata firlatir.
$script:WmiFeatState = @{ 1 = 'Enabled'; 2 = 'Disabled'; 3 = 'DisabledWithPayloadRemoved' }
function Get-WinFeatureWmi([string]$Name) {
    if ($Name -cnotmatch '^[A-Za-z0-9\.\-_]{2,120}$') { throw (('Ge' + [char]0x00E7 + 'ersiz Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i ad' + [char]0x0131 + ': ') + $Name) }
    $b = $script:StateBatch
    $st = $null
    if ($null -ne $b) {
        if ($null -eq $b.Feat) {
            $m = @{}
            foreach ($x in @(Get-CimInstance -ClassName Win32_OptionalFeature -ErrorAction Stop)) { if ($null -ne $x) { $m[[string]$x.Name] = [int]$x.InstallState } }
            $b.Feat = $m
        }
        if (-not $b.Feat.ContainsKey($Name)) { return $null }
        $st = [int]$b.Feat[$Name]
    } else {
        $q = @(Get-CimInstance -ClassName Win32_OptionalFeature -Filter ("Name='" + $Name + "'") -ErrorAction Stop | Where-Object { $null -ne $_ })
        if ($q.Count -eq 0) { return $null }
        $st = [int]$q[0].InstallState
    }
    if (-not $script:WmiFeatState.ContainsKey($st)) { throw (('Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'inin durumu belirsiz (') + $Name + ', InstallState=' + $st + ')') }
    return [pscustomobject]@{ FeatureName = $Name; State = [string]$script:WmiFeatState[$st]; Source = 'wmi' }
}

function Get-WinFeatureInfo([string]$Name) {
    $err = ''
    $b = $script:StateBatch
    $skipDism = ((-not [bool]$script:IsAdmin) -or ($null -ne $b -and [bool]$b.FeatDismBad))
    if (-not $skipDism) {
        try { return (Get-WindowsOptionalFeature -Online -FeatureName $Name -ErrorAction Stop) }
        catch { $err = $_.Exception.Message; if ($null -ne $b) { $b.FeatDismBad = $true } }
    }
    try { return (Get-WinFeatureWmi $Name) }
    catch {
        if ($err -eq '') { $err = $_.Exception.Message } else { $err = $err + ' / WMI: ' + $_.Exception.Message }
        throw $err
    }
}
}
# ==================================================================
#  Cekirdegi yukle: arayuz is parcaciginda ve (Start-Async ile) is parcaciklarinda ayni kod kullanilir.
# ==================================================================
Set-SplashStep 'cekirdek'
$script:CoreText = $CoreCode.ToString()
. $CoreCode
# arka plan calisma alanlarinda cekirdek metne gore olculen satir numarasi dosya satirina cevrilir
try { $sync.CoreLineBase = [int]$CoreCode.Ast.Extent.StartLineNumber - 1 } catch { $sync.CoreLineBase = 0 }

# ==================================================================
#  ARKA PLAN IS CALISTIRICI
#  - Tek bir "is" runspace'i (STA) cekirdek kodla hazirlanir; isler sirayla calisir.
#  - Canli izleme ayri bir runspace'te surekli calisir ($sync.Mon guncellenir).
#  - Is ilerlemesi paylasimli $J tablosundan, gunluk satirlari $sync.Queue kuyrugundan okunur.
# ==================================================================
$script:Work = $null
$script:MonWork = $null
$script:Cur = $null
$script:AsyncQueue = New-Object System.Collections.ArrayList

$script:AsyncWrapper = @'
try { [void](Set-MmCulture) } catch { }
try {
    if (Test-NetBlocked $Entry) { Write-WhLog (Get-NetBlockText $Entry) 'WARN' }
    else {
        $xe = Get-ExtError $Entry
        if ($xe -ne '') { Write-WhLog $xe 'ERR'; @{ Ok = $false; ExtError = $xe } }
        else { & $Entry $P }
    }
}
catch {
    $wl = ''
    try { $wl = ([string]$_.InvocationInfo.Line).Trim(); if ($wl.Length -gt 140) { $wl = $wl.Substring(0, 140) } } catch { }
    Write-WhLog ('Beklenmeyen hata: ' + $_.Exception.Message + '  [satir ' + $_.InvocationInfo.ScriptLineNumber + ': ' + $wl + ']') 'ERR'
    try { $J.Error = $_.Exception.Message } catch { }
}
finally {
    try { [void](Save-DebugErrors 'is') } catch { }
}
'@

function New-CoreRunspace {
    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = [System.Threading.ApartmentState]::STA
    $rs.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
    $rs.Open()
    $rs.SessionStateProxy.SetVariable('sync', $sync)
    $rs.SessionStateProxy.SetVariable('CoreText', $script:CoreText)
    $rs.SessionStateProxy.SetVariable('CultureText', $script:CultureText)
    $rs.SessionStateProxy.SetVariable('J', $null)
    $rs.SessionStateProxy.SetVariable('P', $null)
    $rs.SessionStateProxy.SetVariable('Entry', '')
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript('$ErrorActionPreference = ''Continue''; $ProgressPreference = ''SilentlyContinue''; . ([scriptblock]::Create($CultureText)); [void](Set-MmCulture); . ([scriptblock]::Create($CoreText))')
    $ar = $ps.BeginInvoke()
    return @{ Rs = $rs; Ps = $ps; Ar = $ar; Ready = $false }
}

function Wait-CoreRunspace($W) {
    if ($W.Ready) { return }
    try { [void]$W.Ar.AsyncWaitHandle.WaitOne() } catch { }
    try { [void]$W.Ps.EndInvoke($W.Ar) } catch { Write-LogFile ('Runspace hazirlanamadi: ' + $_.Exception.Message) }
    try { $W.Ps.Dispose() } catch { }
    $W.Ready = $true
}

# Is runspace'ini arka planda isit (pencere acilirken)
function Initialize-Work {
    if ($null -eq $script:Work) { $script:Work = New-CoreRunspace }
}

# Arka planda is baslatir. $OnDone, sonuc tablosu (hashtable ya da $null) ile arayuz is parcaciginda cagrilir.
function Start-Async {
    param([string]$Name, [string]$Entry, $Params = $null, [scriptblock]$OnDone = $null, [string]$Label = '', [bool]$Quiet = $false, [bool]$Queue = $false)
    if ($null -ne $script:Cur) {
        # Arka plandaki sessiz bir tarama suruyorsa kullanici istegi reddedilmez, siraya alinir
        if ($Queue -or $script:Cur.Quiet -eq $true) {
            $item = @{ Name = $Name; Entry = $Entry; Params = $Params; OnDone = $OnDone; Label = $Label; Quiet = $Quiet }
            for ($qi = 0; $qi -lt $script:AsyncQueue.Count; $qi++) {
                if ([string]$script:AsyncQueue[$qi].Name -eq $Name) { $script:AsyncQueue[$qi] = $item; return $true }
            }
            [void]$script:AsyncQueue.Add($item)
            return $true
        }
        Show-Toast (('Ba' + [char]0x015F + 'ka bir i' + [char]0x015F + 'lem s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor: ') + $script:Cur.Label) 'warn'
        return $false
    }
    if ($null -eq $Params) { $Params = @{} }
    Initialize-Work
    Wait-CoreRunspace $script:Work
    $jt = [hashtable]::Synchronized(@{ Done = 0; Total = 0; Label = $Label; State = 'Running'; Error = $null; Cancel = $false })
    $rs = $script:Work.Rs
    $rs.SessionStateProxy.SetVariable('J', $jt)
    $rs.SessionStateProxy.SetVariable('P', $Params)
    $rs.SessionStateProxy.SetVariable('Entry', $Entry)
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($script:AsyncWrapper)
    $ar = $ps.BeginInvoke()
    $script:Cur = @{ Name = $Name; Entry = $Entry; Ps = $ps; Ar = $ar; J = $jt; OnDone = $OnDone; Label = $Label; Quiet = $Quiet; Start = (Get-Date) }
    try { Add-Trace ('is basladi: ' + $Name + ' (' + $Entry + ')') } catch { }
    if (-not $Quiet) {
        Write-WhLog ('>>> ' + $Label) 'STEP'
        Set-BusyUi $true $Label
    }
    return $true
}

function Stop-Async {
    if ($null -ne $script:Cur) {
        try { $script:Cur.J.Cancel = $true } catch { }
        Write-WhLog ([string][char]0x0130 + 'ptal istendi, i' + [char]0x015F + 'lem g' + [char]0x00FC + 'venli bir noktada duracak...') 'WARN'
    }
}

function Test-AsyncBusy { return ($null -ne $script:Cur) }

# Arayuz zamanlayicisi cagirir: gunluk satirlarini bosaltir, ilerlemeyi gosterir, biten isi tamamlar
function Update-AsyncUi {
    $n = 0
    $line = $null
    while ($n -lt 250 -and $sync.Queue.TryDequeue([ref]$line)) {
        Add-LogLine ([string]$line)
        $n++
    }
    if ($null -eq $script:Cur) { return }
    $c = $script:Cur
    if (-not $c.Quiet) {
        $j = $c.J
        Set-JobUi ([int]$j.Done) ([int]$j.Total) ([string]$j.Label)
    }
    if ($c.Ar.IsCompleted) { Complete-Async }
}

function Complete-Async {
    $c = $script:Cur
    $script:Cur = $null
    try { Add-Trace ('is bitti: ' + [string]$c.Name + ' (' + [string][int]((Get-Date) - $c.Start).TotalSeconds + ' sn)') } catch { }
    $res = $null
    try {
        $out = $c.Ps.EndInvoke($c.Ar)
        foreach ($o in @($out)) {
            $b = $o
            if ($b -is [psobject]) { $b = $b.psobject.BaseObject }
            if ($b -is [hashtable]) { $res = $b }
        }
    } catch { Write-WhLog (([string][char]0x0130 + [char]0x015F + ' tamamlanamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR' }
    try {
        $en = 0
        $etotal = @($c.Ps.Streams.Error).Count
        foreach ($e in $c.Ps.Streams.Error) {
            $en++
            if ($en -gt 8) { Write-LogFile ('HATA-AKISI: ... toplam ' + [string]$etotal + ' kayit, ilk 8 yazildi'); break }
            $d = [string]$e
            try {
                $el = ''
                if ($null -ne $e.InvocationInfo) { $el = ([string]$e.InvocationInfo.Line).Trim(); if ($el.Length -gt 120) { $el = $el.Substring(0, 120) } }
                $d += '  [' + [string]$e.FullyQualifiedErrorId + '; ' + [string]$e.CategoryInfo.Category
                if ($el -ne '') { $d += '; ' + $el }
                $d += ']'
            } catch { }
            Write-LogFile ('HATA-AKISI: ' + $d)
        }
    } catch { }
    # 4) is basarisizsa kullanici bilgilendirilir (liste sonsuza dek "taraniyor..." kalmaz)
    try {
        if ($null -eq $res -and -not $c.Quiet -and -not [string]::IsNullOrEmpty([string]$c.J.Error)) {
            $jl = ([string]$c.Label) -replace '\.\.\.$', ''
            Show-Toast ($jl + ': tamamlanamad' + [char]0x0131 + '. ' + [string]$c.J.Error) 'bad'
        }
    } catch { }
    try { $c.Ps.Dispose() } catch { }
    $line = $null
    while ($sync.Queue.TryDequeue([ref]$line)) { Add-LogLine ([string]$line) }
    if (-not $c.Quiet) { Set-BusyUi $false '' }
    try { $script:Settings = Get-Settings } catch { }
    if ($null -ne $c.OnDone) {
        try { & $c.OnDone $res } catch { Show-Crash $_ ('OnDone: ' + $c.Name) }
    }
    if ($null -eq $script:Cur -and $script:AsyncQueue.Count -gt 0) {
        $nx = $script:AsyncQueue[0]
        $script:AsyncQueue.RemoveAt(0)
        [void](Start-Async $nx.Name $nx.Entry $nx.Params $nx.OnDone $nx.Label $nx.Quiet $false)
    }
}

# ---------------- canli izleme ----------------
function Start-Monitor {
    if ($null -ne $script:MonWork) { return }
    $sync.Stop = $false
    $w = New-CoreRunspace
    $script:MonWork = $w
    $script:MonStarter = $true
}

# Izleme runspace'i hazir olunca isi baslatir (Update zamanlayicisi cagirir)
function Update-MonitorStart {
    if ($null -eq $script:MonWork -or $script:MonWork.Ready -or -not $script:MonStarter) { return }
    if (-not $script:MonWork.Ar.IsCompleted) { return }
    Wait-CoreRunspace $script:MonWork
    $script:MonStarter = $false
    $rs = $script:MonWork.Rs
    $rs.SessionStateProxy.SetVariable('P', @{ Interval = 2 })
    $rs.SessionStateProxy.SetVariable('Entry', 'Job_Monitor')
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($script:AsyncWrapper)
    $script:MonWork.Run = $ps
    $script:MonWork.RunAr = $ps.BeginInvoke()
}

function Stop-AllWork {
    $sync.Stop = $true
    try { if ($null -ne $script:Cur) { $script:Cur.J.Cancel = $true } } catch { }
    foreach ($w in @($script:MonWork, $script:Work)) {
        if ($null -eq $w) { continue }
        try {
            if ($null -ne $w.Run) { [void]$w.Run.BeginStop($null, $null) }
        } catch { }
    }
    Start-Sleep -Milliseconds 300
    foreach ($w in @($script:MonWork, $script:Work)) {
        if ($null -eq $w) { continue }
        try { $w.Rs.Close() } catch { }
    }
}

