<Style x:Key="ComboToggle" TargetType="ToggleButton">
  <Setter Property="OverridesDefaultStyle" Value="True"/>
  <Setter Property="IsTabStop" Value="False"/>
  <Setter Property="Focusable" Value="False"/>
  <Setter Property="ClickMode" Value="Press"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="ToggleButton">
        <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="{DynamicResource RadBtn}" SnapsToDevicePixels="True">
          <Grid>
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="32"/>
            </Grid.ColumnDefinitions>
            <Path x:Name="Arrow" Grid.Column="1" HorizontalAlignment="Center" VerticalAlignment="Center" Data="M0,0 L4.5,4.5 L9,0" Stroke="{DynamicResource BrDim}" StrokeThickness="1.7" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"/>
          </Grid>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource BrAccent}"/>
          </Trigger>
          <Trigger Property="IsChecked" Value="True">
            <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource BrAccent}"/>
            <Setter TargetName="Arrow" Property="Stroke" Value="{DynamicResource BrAccent}"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
<Style x:Key="ComboItem" TargetType="ComboBoxItem">
  <Setter Property="OverridesDefaultStyle" Value="True"/>
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Padding" Value="10,7"/>
  <Setter Property="FontSize" Value="13"/>
  <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
  <Setter Property="SnapsToDevicePixels" Value="True"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="AutomationProperties.Name" Value="{Binding [Name]}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="ComboBoxItem">
        <Border x:Name="Bd" Background="Transparent" CornerRadius="{DynamicResource RadBtn}" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
          <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsHighlighted" Value="True">
            <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BrHover}"/>
          </Trigger>
          <Trigger Property="IsSelected" Value="True">
            <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BrActiveBg}"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter Property="Opacity" Value="0.4"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
<Style x:Key="Combo" TargetType="ComboBox">
  <Setter Property="OverridesDefaultStyle" Value="True"/>
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Background" Value="{DynamicResource BrCard}"/>
  <Setter Property="BorderBrush" Value="{DynamicResource BrLine2}"/>
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="Padding" Value="12,6,12,6"/>
  <Setter Property="FontSize" Value="13"/>
  <Setter Property="MinHeight" Value="36"/>
  <Setter Property="Width" Value="300"/>
  <Setter Property="MaxDropDownHeight" Value="420"/>
  <Setter Property="HorizontalAlignment" Value="Left"/>
  <Setter Property="Cursor" Value="Hand"/>
  <Setter Property="SnapsToDevicePixels" Value="True"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
  <Setter Property="ScrollViewer.VerticalScrollBarVisibility" Value="Auto"/>
  <Setter Property="ItemContainerStyle" Value="{DynamicResource ComboItem}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="ComboBox">
        <Grid>
          <ToggleButton x:Name="Tg" Style="{StaticResource ComboToggle}" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" IsChecked="{Binding Path=IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}"/>
          <ContentPresenter x:Name="Cp" IsHitTestVisible="False" Margin="{TemplateBinding Padding}" HorizontalAlignment="Left" VerticalAlignment="Center" Content="{TemplateBinding SelectionBoxItem}" ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentStringFormat="{TemplateBinding SelectionBoxItemStringFormat}"/>
          <Popup x:Name="PART_Popup" Placement="Bottom" IsOpen="{TemplateBinding IsDropDownOpen}" AllowsTransparency="True" Focusable="False" PopupAnimation="Fade">
            <Border Margin="4,6,4,12" MinWidth="{Binding ActualWidth, ElementName=Tg}" MaxHeight="{TemplateBinding MaxDropDownHeight}" Background="{DynamicResource BrPanel2}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1" CornerRadius="{DynamicResource RadCard}" Padding="4" SnapsToDevicePixels="True">
              <Border.Effect>
                <DropShadowEffect BlurRadius="16" ShadowDepth="3" Opacity="0.35" Color="#000000"/>
              </Border.Effect>
              <ScrollViewer CanContentScroll="True" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                <ItemsPresenter KeyboardNavigation.DirectionalNavigation="Contained"/>
              </ScrollViewer>
            </Border>
          </Popup>
        </Grid>
        <ControlTemplate.Triggers>
          <Trigger Property="IsEnabled" Value="False">
            <Setter Property="Opacity" Value="0.45"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
<DataTemplate x:Key="ComboText">
  <TextBlock Text="{Binding [Name]}" TextTrimming="CharacterEllipsis"/>
</DataTemplate>
<DataTemplate x:Key="ComboTheme">
  <StackPanel Orientation="Horizontal">
    <StackPanel Orientation="Horizontal" Margin="0,0,10,0" VerticalAlignment="Center">
      <Ellipse Width="16" Height="16" Fill="{Binding [C1]}" Stroke="{DynamicResource BrLine2}" StrokeThickness="1"/>
      <Ellipse Width="16" Height="16" Fill="{Binding [C2]}" Stroke="{DynamicResource BrLine2}" StrokeThickness="1" Margin="-5,0,0,0"/>
      <Ellipse Width="16" Height="16" Fill="{Binding [C3]}" Stroke="{DynamicResource BrLine2}" StrokeThickness="1" Margin="-5,0,0,0"/>
      <Ellipse Width="16" Height="16" Fill="{Binding [C4]}" Stroke="{DynamicResource BrLine2}" StrokeThickness="1" Margin="-5,0,0,0"/>
    </StackPanel>
    <TextBlock Text="{Binding [Name]}" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
  </StackPanel>
</DataTemplate>

