<Style x:Key="ToolCard" TargetType="Button">
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Background" Value="{DynamicResource BrCard}"/>
  <Setter Property="BorderBrush" Value="{DynamicResource BrLine}"/>
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="Cursor" Value="Hand"/>
  <Setter Property="Margin" Value="4"/>
  <Setter Property="Padding" Value="6"/>
  <Setter Property="Height" Value="104"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="Button">
        <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="10" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource BrGold}"/>
            <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BrGoldBg}"/>
          </Trigger>
          <Trigger Property="IsPressed" Value="True">
            <Setter TargetName="Bd" Property="Opacity" Value="0.75"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter TargetName="Bd" Property="Opacity" Value="0.4"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style x:Key="RailItem" TargetType="RadioButton">
  <Setter Property="GroupName" Value="rail"/>
  <Setter Property="Height" Value="56"/>
  <Setter Property="Foreground" Value="{DynamicResource BrDim}"/>
  <Setter Property="Cursor" Value="Hand"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="RadioButton">
        <Grid x:Name="G" Background="Transparent">
          <Border x:Name="Bar" Width="3" HorizontalAlignment="Left" Background="{DynamicResource BrAccent}" Visibility="Collapsed" CornerRadius="0,2,2,0" Margin="0,10"/>
          <Border x:Name="Bg" Margin="7,3" CornerRadius="{DynamicResource RadCard}" Background="Transparent"/>
          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Grid>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="Bg" Property="Background" Value="{DynamicResource BrHover}"/>
            <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
          </Trigger>
          <Trigger Property="IsChecked" Value="True">
            <Setter TargetName="Bar" Property="Visibility" Value="Visible"/>
            <Setter TargetName="Bg" Property="Background" Value="{DynamicResource BrActiveBg}"/>
            <Setter Property="Foreground" Value="{DynamicResource BrAccent}"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style x:Key="Seg" TargetType="RadioButton">
  <Setter Property="MinHeight" Value="{DynamicResource TouchMin}"/>
  <Setter Property="MinWidth" Value="{DynamicResource TouchMin}"/>
  <Setter Property="Foreground" Value="{DynamicResource BrDim}"/>
  <Setter Property="Background" Value="Transparent"/>
  <Setter Property="BorderBrush" Value="Transparent"/>
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="Padding" Value="14,6"/>
  <Setter Property="FontSize" Value="11.5"/>
  <Setter Property="FontWeight" Value="SemiBold"/>
  <Setter Property="Cursor" Value="Hand"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="RadioButton">
        <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="{DynamicResource RadBtn}" Padding="{TemplateBinding Padding}">
          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BrHover}"/>
            <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
          </Trigger>
          <Trigger Property="IsChecked" Value="True">
            <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BrActiveBg}"/>
            <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource BrAccentDim}"/>
            <Setter Property="Foreground" Value="{DynamicResource BrAccent}"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
<Style x:Key="Chip" TargetType="RadioButton" BasedOn="{StaticResource Seg}">
  <Setter Property="Padding" Value="11,3"/>
  <Setter Property="Margin" Value="0,0,6,0"/>
  <Setter Property="FontWeight" Value="Normal"/>
  <Setter Property="BorderBrush" Value="{DynamicResource BrLine}"/>
</Style>

<Style TargetType="CheckBox">
  <Setter Property="MinHeight" Value="{DynamicResource TouchMin}"/>
  <Setter Property="MinWidth" Value="{DynamicResource TouchMin}"/>
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Cursor" Value="Hand"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="VerticalContentAlignment" Value="Center"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="CheckBox">
        <Grid Background="Transparent" SnapsToDevicePixels="True">
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="Auto"/>
            <ColumnDefinition Width="*"/>
          </Grid.ColumnDefinitions>
          <Border x:Name="Box" Width="18" Height="18" CornerRadius="4" Background="{DynamicResource BrCard}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1.5" VerticalAlignment="Center">
            <Path x:Name="Tick" Data="M3,8 L6.5,11.5 L12,4.5" Stroke="{DynamicResource BrOnAccent}" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed"/>
          </Border>
          <ContentPresenter Grid.Column="1" Margin="9,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True"/>
        </Grid>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="Box" Property="BorderBrush" Value="{DynamicResource BrAccent}"/>
          </Trigger>
          <Trigger Property="IsChecked" Value="True">
            <Setter TargetName="Box" Property="Background" Value="{DynamicResource BrAccent}"/>
            <Setter TargetName="Box" Property="BorderBrush" Value="{DynamicResource BrAccent}"/>
            <Setter TargetName="Tick" Property="Visibility" Value="Visible"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter Property="Opacity" Value="0.45"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style x:Key="Toggle" TargetType="CheckBox">
  <Setter Property="MinHeight" Value="{DynamicResource TouchMin}"/>
  <Setter Property="MinWidth" Value="{DynamicResource TouchMin}"/>
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Cursor" Value="Hand"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="CheckBox">
        <Grid Background="Transparent" SnapsToDevicePixels="True">
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="Auto"/>
            <ColumnDefinition Width="*"/>
          </Grid.ColumnDefinitions>
          <Border x:Name="Track" Width="38" Height="20" CornerRadius="10" Background="{DynamicResource BrLine}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1" VerticalAlignment="Center">
            <Ellipse x:Name="Knob" Width="14" Height="14" HorizontalAlignment="Left" Margin="2,0,0,0" Fill="{DynamicResource BrDim}"/>
          </Border>
          <ContentPresenter Grid.Column="1" Margin="10,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True">
            <ContentPresenter.Resources>
              <Style TargetType="TextBlock"><Setter Property="TextWrapping" Value="Wrap"/></Style>
            </ContentPresenter.Resources>
          </ContentPresenter>
        </Grid>
        <ControlTemplate.Triggers>
          <Trigger Property="IsChecked" Value="True">
            <Setter TargetName="Track" Property="Background" Value="{DynamicResource BrAccentDim}"/>
            <Setter TargetName="Track" Property="BorderBrush" Value="{DynamicResource BrAccent}"/>
            <Setter TargetName="Knob" Property="HorizontalAlignment" Value="Right"/>
            <Setter TargetName="Knob" Property="Margin" Value="0,0,2,0"/>
            <Setter TargetName="Knob" Property="Fill" Value="#FFFFFF"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter Property="Opacity" Value="0.45"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style TargetType="TextBox">
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Background" Value="{DynamicResource BrCard}"/>
  <Setter Property="BorderBrush" Value="{DynamicResource BrLine}"/>
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="CaretBrush" Value="{DynamicResource BrAccent}"/>
  <Setter Property="SelectionBrush" Value="{DynamicResource BrAccentDim}"/>
  <Setter Property="Padding" Value="8,5"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="TextBox">
        <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="{DynamicResource RadBtn}" SnapsToDevicePixels="True">
          <ScrollViewer x:Name="PART_ContentHost" Focusable="False" HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Hidden" Margin="{TemplateBinding Padding}"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsKeyboardFocused" Value="True">
            <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource BrAccent}"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter Property="Opacity" Value="0.5"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style TargetType="PasswordBox">
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Background" Value="{DynamicResource BrCard}"/>
  <Setter Property="BorderBrush" Value="{DynamicResource BrLine}"/>
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="CaretBrush" Value="{DynamicResource BrAccent}"/>
  <Setter Property="SelectionBrush" Value="{DynamicResource BrAccentDim}"/>
  <Setter Property="Padding" Value="8,5"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="PasswordBox">
        <Border x:Name="PwBd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="{DynamicResource RadBtn}" SnapsToDevicePixels="True">
          <ScrollViewer x:Name="PART_ContentHost" Focusable="False" HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Hidden" Margin="{TemplateBinding Padding}"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsKeyboardFocused" Value="True">
            <Setter TargetName="PwBd" Property="BorderBrush" Value="{DynamicResource BrAccent}"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter Property="Opacity" Value="0.5"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style TargetType="ProgressBar">
  <Setter Property="Height" Value="6"/>
  <Setter Property="Minimum" Value="0"/>
  <Setter Property="Maximum" Value="100"/>
  <Setter Property="Background" Value="{DynamicResource BrLine}"/>
  <Setter Property="Foreground" Value="{DynamicResource BrAccent}"/>
  <Setter Property="BorderThickness" Value="0"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="ProgressBar">
        <Grid>
          <Border x:Name="PART_Track" Background="{TemplateBinding Background}" CornerRadius="3"/>
          <Border x:Name="PART_Indicator" HorizontalAlignment="Left" Background="{TemplateBinding Foreground}" CornerRadius="3"/>
        </Grid>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style x:Key="ScrollThumb" TargetType="Thumb">
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="Thumb">
        <Border x:Name="Th" Background="{DynamicResource BrLine2}" CornerRadius="3" Margin="1"/>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="Th" Property="Background" Value="{DynamicResource BrAccentDim}"/>
          </Trigger>
          <Trigger Property="IsDragging" Value="True">
            <Setter TargetName="Th" Property="Background" Value="{DynamicResource BrAccent}"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
<Style x:Key="ScrollPage" TargetType="RepeatButton">
  <Setter Property="Focusable" Value="False"/>
  <Setter Property="IsTabStop" Value="False"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="RepeatButton">
        <Border Background="Transparent"/>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
<Style TargetType="ScrollBar">
  <Setter Property="Background" Value="Transparent"/>
  <Setter Property="Width" Value="11"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="ScrollBar">
        <Grid Background="Transparent">
          <Track x:Name="PART_Track" IsDirectionReversed="True">
            <Track.DecreaseRepeatButton>
              <RepeatButton Command="ScrollBar.PageUpCommand" Style="{StaticResource ScrollPage}"/>
            </Track.DecreaseRepeatButton>
            <Track.Thumb>
              <Thumb Style="{StaticResource ScrollThumb}"/>
            </Track.Thumb>
            <Track.IncreaseRepeatButton>
              <RepeatButton Command="ScrollBar.PageDownCommand" Style="{StaticResource ScrollPage}"/>
            </Track.IncreaseRepeatButton>
          </Track>
        </Grid>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
  <Style.Triggers>
    <Trigger Property="Orientation" Value="Horizontal">
      <Setter Property="Width" Value="Auto"/>
      <Setter Property="Height" Value="11"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ScrollBar">
            <Grid Background="Transparent">
              <Track x:Name="PART_Track" IsDirectionReversed="False">
                <Track.DecreaseRepeatButton>
                  <RepeatButton Command="ScrollBar.PageLeftCommand" Style="{StaticResource ScrollPage}"/>
                </Track.DecreaseRepeatButton>
                <Track.Thumb>
                  <Thumb Style="{StaticResource ScrollThumb}"/>
                </Track.Thumb>
                <Track.IncreaseRepeatButton>
                  <RepeatButton Command="ScrollBar.PageRightCommand" Style="{StaticResource ScrollPage}"/>
                </Track.IncreaseRepeatButton>
              </Track>
            </Grid>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Trigger>
  </Style.Triggers>
</Style>

<Style TargetType="ToolTip">
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="Background" Value="{DynamicResource BrPanel2}"/>
  <Setter Property="BorderBrush" Value="{DynamicResource BrLine2}"/>
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="Padding" Value="9,6"/>
  <Setter Property="FontSize" Value="12"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="ToolTip">
        <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6" Padding="{TemplateBinding Padding}">
          <ContentPresenter MaxWidth="360"/>
        </Border>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>

<Style x:Key="AcItem" TargetType="ListBoxItem">
  <Setter Property="Padding" Value="8,4"/>
  <Setter Property="Cursor" Value="Hand"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="ListBoxItem">
        <Border x:Name="Bd" Background="Transparent" Padding="{TemplateBinding Padding}" CornerRadius="4">
          <ContentPresenter/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsSelected" Value="True">
            <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BrHover}"/>
          </Trigger>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BrHover}"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
<Style x:Key="AcList" TargetType="ListBox">
  <Setter Property="Background" Value="Transparent"/>
  <Setter Property="BorderThickness" Value="0"/>
  <Setter Property="Foreground" Value="{DynamicResource BrText}"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="ItemContainerStyle" Value="{DynamicResource AcItem}"/>
</Style>
'@

# ==================================================================
#  ARAYUZ: ana pencere (Multimizer kabugu): baslik cubugu, sol simge seridi, islem gunlugu, sayfa alani,
#  komut satiri ve durum cubugu.  @@ICONS@@ ve @@RES@@ calisma aninda doldurulur.
# ==================================================================
$script:XamlMain = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        xmlns:shell="clr-namespace:System.Windows.Shell;assembly=PresentationFramework"
        xmlns:sys="clr-namespace:System;assembly=mscorlib"
        x:Name="Win" Title="Multimizer" Width="1380" Height="840" MinWidth="1060" MinHeight="660"
        WindowStyle="None" ResizeMode="CanResize" WindowStartupLocation="CenterScreen"
        Background="{DynamicResource BrBg}" Foreground="{DynamicResource BrText}"
        FontFamily="Segoe UI" FontSize="13" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <shell:WindowChrome.WindowChrome>
    <shell:WindowChrome CaptionHeight="46" ResizeBorderThickness="6" GlassFrameThickness="0" CornerRadius="0" UseAeroCaptionButtons="False"/>
  </shell:WindowChrome.WindowChrome>
  <Window.Resources>
    @@ICONS@@
    @@RES@@
  </Window.Resources>
  <Border x:Name="Root" Background="{DynamicResource BrBgGrad}" BorderBrush="{DynamicResource BrLine}" BorderThickness="1">
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="46"/>
        <RowDefinition Height="*"/>
        <RowDefinition Height="26"/>
      </Grid.RowDefinitions>

      <!-- ===== BA&#x015E;LIK &#x00C7;UBU&#x011E;U ===== -->
      <Grid Grid.Row="0" Background="{DynamicResource BrTitle}">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="Auto"/>
          <ColumnDefinition Width="*"/>
          <ColumnDefinition Width="Auto"/>
        </Grid.ColumnDefinitions>
        <StackPanel x:Name="TitleLeft" Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center" Margin="14,0,0,0">
          <Button x:Name="BtnMenu" Style="{DynamicResource BtnTitle}" Width="38" Margin="-8,0,8,0" Visibility="Collapsed" shell:WindowChrome.IsHitTestVisibleInChrome="True" ToolTip="Men&#x00FC;">
            <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoMenu}" Width="18" Height="18"/>
          </Button>
          <Button x:Name="BtnHome" Style="{DynamicResource BtnBrand}" shell:WindowChrome.IsHitTestVisibleInChrome="True" ToolTip="Ana sayfa: durum panosuna d&#x00F6;n">
            <StackPanel Orientation="Horizontal">
              <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoLogo}" Width="24" Height="24" Foreground="{DynamicResource BrAccent2}"/>
              <TextBlock Text="MULTIMIZER" FontSize="15" FontWeight="Bold" Foreground="{DynamicResource BrText}" Margin="10,0,0,0" VerticalAlignment="Center"/>
            </StackPanel>
          </Button>
          <TextBlock x:Name="TxtTitleSep" Text=" // " FontSize="15" Foreground="{DynamicResource BrAccent}" VerticalAlignment="Center"/>
          <TextBlock x:Name="TxtTagline" Text="OPT&#x0130;M&#x0130;ZASYON &#x00B7; G&#x00DC;VENL&#x0130;K &#x00B7; A&#x011E; KORUMA" FontSize="12" Foreground="{DynamicResource BrDim}" VerticalAlignment="Center"/>
        </StackPanel>
        <StackPanel x:Name="TitleCenter" Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center" shell:WindowChrome.IsHitTestVisibleInChrome="True">
          <Border x:Name="TitlePill" Background="{DynamicResource BrCard}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1" CornerRadius="{DynamicResource RadBtn}" Padding="16,5" MinWidth="190">
            <TextBlock x:Name="TxtPageName" Text="DURUM PANOSU" FontSize="11.5" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
          </Border>
          <Border Margin="10,0,0,0" Background="{DynamicResource BrCard}" BorderBrush="{DynamicResource BrLine}" BorderThickness="1" CornerRadius="{DynamicResource RadBtn}" Padding="2">
            <StackPanel Orientation="Horizontal">
              <RadioButton x:Name="SegUser" Style="{DynamicResource Seg}" GroupName="mode" Content="KULLANICI" ToolTip="Basit ve g&#x00FC;venli: uygulama sizin i&#x00E7;in se&#x00E7;er"/>
              <RadioButton x:Name="SegExpert" Style="{DynamicResource Seg}" GroupName="mode" Content="UZMAN" ToolTip="Tam denetim: her ayar&#x0131; siz se&#x00E7;ersiniz"/>
            </StackPanel>
          </Border>
          <Border x:Name="LangCapsule" Margin="10,0,0,0" Background="{DynamicResource BrCard}" BorderBrush="{DynamicResource BrLine}" BorderThickness="1" CornerRadius="{DynamicResource RadBtn}" Padding="2">
            <Button x:Name="BtnLang" Style="{DynamicResource BtnLangCap}" ToolTip="Aray&#x00FC;z dili">
              <StackPanel Orientation="Horizontal">
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoGlobe}" Width="15" Height="15" Foreground="{DynamicResource BrAccent}"/>
                <TextBlock x:Name="TxtLangCode" Text="TR" Margin="7,0,0,0" VerticalAlignment="Center"/>
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoChevD}" Width="11" Height="11" Margin="6,1,0,0" Foreground="{DynamicResource BrDim}" VerticalAlignment="Center"/>
              </StackPanel>
            </Button>
          </Border>
          <Border x:Name="AskCapsule" Margin="10,0,0,0" Background="{DynamicResource BrCard}" BorderBrush="{DynamicResource BrLine}" BorderThickness="1" CornerRadius="{DynamicResource RadBtn}" Padding="2">
            <Button x:Name="BtnAsk" Style="{DynamicResource BtnLangCap}" ToolTip="Asistan: sorunuzu yaz&#x0131;n ya da bir i&#x015F;lem aray&#x0131;n (F1)">
              <StackPanel Orientation="Horizontal">
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoSearch}" Width="15" Height="15" Foreground="{DynamicResource BrAccent}"/>
                <TextBlock x:Name="TxtAskHint" Text="Sor ya da ara" Margin="7,0,2,0" VerticalAlignment="Center" Foreground="{DynamicResource BrDim}"/>
              </StackPanel>
            </Button>
          </Border>
          <Popup x:Name="LangPop" Placement="Bottom" StaysOpen="False" AllowsTransparency="True" PopupAnimation="Fade">
            <Border Background="{DynamicResource BrPanel2}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1" CornerRadius="12" Padding="6" Margin="10,4,10,14" MinWidth="272">
              <Border.Effect>
                <DropShadowEffect BlurRadius="16" ShadowDepth="3" Opacity="0.30" Color="#000000"/>
              </Border.Effect>
              <StackPanel>
                <TextBlock Text="ARAY&#x00DC;Z D&#x0130;L&#x0130;" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource BrFaint}" Margin="10,6,0,4"/>
                <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" MaxHeight="430">
                  <StackPanel x:Name="LangItems" KeyboardNavigation.DirectionalNavigation="Cycle"/>
                </ScrollViewer>
                <Border BorderBrush="{DynamicResource BrLine}" BorderThickness="0,1,0,0" Margin="4,6,4,0" Padding="6,8,6,2">
                  <TextBlock Text="Dil de&#x011F;i&#x015F;ince uygulama kendini yeniden ba&#x015F;lat&#x0131;r." FontSize="11" Foreground="{DynamicResource BrDim}" TextWrapping="Wrap" MaxWidth="250"/>
                </Border>
              </StackPanel>
            </Border>
          </Popup>
        </StackPanel>
        <StackPanel x:Name="TitleRight" Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center" shell:WindowChrome.IsHitTestVisibleInChrome="True">
          <TextBlock x:Name="TxtJobLbl" Text="&#x0130;&#x015F;lem:" FontSize="11.5" Foreground="{DynamicResource BrDim}" VerticalAlignment="Center"/>
          <Ellipse x:Name="DotBusy" Width="8" Height="8" Margin="6,0,4,0" Fill="{DynamicResource BrGood}"/>
          <TextBlock x:Name="TxtBusy" Text="Haz&#x0131;r" FontSize="11.5" Foreground="{DynamicResource BrGood}" VerticalAlignment="Center" MinWidth="46"/>
          <TextBlock x:Name="TxtConnLbl" Text="BA&#x011E;LANTI" FontSize="11.5" Foreground="{DynamicResource BrDim}" VerticalAlignment="Center" Margin="14,0,0,0"/>
          <Ellipse x:Name="DotNet" Width="8" Height="8" Margin="6,0,10,0" Fill="{DynamicResource BrFaint}"/>
          <Button x:Name="BtnKsOff" Style="{DynamicResource BtnMini}" Content="Kill-switch: KAPAT" Margin="0,0,10,0" Visibility="Collapsed" Foreground="{DynamicResource BrBad}" ToolTip="Kill-switch a&#x00E7;&#x0131;k: giden trafik engelli. T&#x0131;klay&#x0131;nca kapan&#x0131;r ve internet eri&#x015F;imi normale d&#x00F6;ner."/>
          <Button x:Name="BtnLogToggle" Style="{DynamicResource BtnTitle}" Width="38" ToolTip="&#x0130;&#x015F;lem g&#x00FC;nl&#x00FC;&#x011F;&#x00FC;n&#x00FC; g&#x00F6;ster / gizle">
            <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoList}" Width="18" Height="18"/>
          </Button>
          <Button x:Name="BtnCmdToggle" Style="{DynamicResource BtnTitle}" Width="38" ToolTip="Komut sat&#x0131;r&#x0131;n&#x0131; g&#x00F6;ster / gizle (Ctrl+K)">
            <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoTerminal}" Width="18" Height="18"/>
          </Button>
          <Button x:Name="BtnPower" Style="{DynamicResource BtnTitle}" Width="38" ToolTip="Uygulamay&#x0131; tamamen kapat (Ctrl+Q)">
            <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoPower}" Width="18" Height="18"/>
          </Button>
          <Button x:Name="BtnMin" Style="{DynamicResource BtnTitle}" ToolTip="Simge durumuna k&#x00FC;&#x00E7;&#x00FC;lt (ayara g&#x00F6;re sa&#x011F; alttaki tepsiye iner)">
            <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoMinus}" Width="16" Height="16"/>
          </Button>
          <Button x:Name="BtnMax" Style="{DynamicResource BtnTitle}" ToolTip="B&#x00FC;y&#x00FC;t / eski boyut">
            <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoSquare}" Width="14" Height="14"/>
          </Button>
          <Button x:Name="BtnClose" Style="{DynamicResource BtnTitleClose}" ToolTip="Kapat (ayara g&#x00F6;re sa&#x011F; alttaki tepsiye iner; tamamen kapatmak i&#x00E7;in g&#x00FC;&#x00E7; d&#x00FC;&#x011F;mesi)">
            <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoX}" Width="16" Height="16"/>
          </Button>
        </StackPanel>
      </Grid>

      <!-- ===== G&#x00D6;VDE ===== -->
      <Grid x:Name="BodyGrid" Grid.Row="1">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="72"/>
          <ColumnDefinition x:Name="ColLog" Width="330"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>

        <!-- simge &#x015F;eridi -->
        <Border x:Name="RailHost" Grid.Column="0" Background="{DynamicResource BrRail}" BorderBrush="{DynamicResource BrLine}" BorderThickness="0,0,1,0">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="*"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <ScrollViewer x:Name="RailScroll" Grid.Row="0" VerticalScrollBarVisibility="Hidden" HorizontalScrollBarVisibility="Disabled" Margin="0,6,0,0">
              <StackPanel>
                <RadioButton x:Name="Rail_panel" Style="{DynamicResource RailItem}" Tag="panel" ToolTip="Durum panosu: kaynaklar, sa&#x011F;l&#x0131;k, a&#x011F; topolojisi">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoHome}"/>
                    <TextBlock Text="Panel" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_optimize" Style="{DynamicResource RailItem}" Tag="optimize" ToolTip="Optimizasyon: gizlilik, performans, g&#x00F6;r&#x00FC;n&#x00FC;m ve oyun ayarlar&#x0131;">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoBolt}"/>
                    <TextBlock Text="Optimizasyon" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_services" Style="{DynamicResource RailItem}" Tag="services" ToolTip="Hizmetler: her hizmetin ne i&#x015F;e yarad&#x0131;&#x011F;&#x0131; ve kapat&#x0131;rsan&#x0131;z ne olaca&#x011F;&#x0131;">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoGear}"/>
                    <TextBlock Text="Hizmetler" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_apps" Style="{DynamicResource RailItem}" Tag="apps" ToolTip="Uygulamalar: gereksizleri kald&#x0131;r, ba&#x015F;lang&#x0131;&#x00E7; programlar&#x0131;, &#x00FC;cretsiz ara&#x00E7;lar">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoApps}"/>
                    <TextBlock Text="Uygulama" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_clean" Style="{DynamicResource RailItem}" Tag="clean" ToolTip="Temizlik: gereksiz dosyalar, disk analizi, bak&#x0131;m">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoTrash}"/>
                    <TextBlock Text="Temizlik" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_power" Style="{DynamicResource RailItem}" Tag="power" ToolTip="G&#x00FC;&#x00E7;: planlar, &#x00F6;nizleme, &#x00F6;zel plan, pil ve enerji raporu">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoPower}"/>
                    <TextBlock Text="G&#x00FC;&#x00E7;" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_gaming" Style="{DynamicResource RailItem}" Tag="gaming" ToolTip="Oyun: canl&#x0131; g&#x00F6;stergeler, oyunlar&#x0131;m, oyun kipi ve oyun ayarlar&#x0131;">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoGamepad}"/>
                    <TextBlock Text="Oyun" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_smart" Style="{DynamicResource RailItem}" Tag="smart" ToolTip="Ak&#x0131;ll&#x0131; bak&#x0131;m: performans art&#x0131;r&#x0131;c&#x0131;, &#x0131;s&#x0131; y&#x00F6;netimi, gizlilik kalkan&#x0131;, otomasyon, donan&#x0131;m &#x00F6;mr&#x00FC;">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoSpark}"/>
                    <TextBlock Text="Ak&#x0131;ll&#x0131;" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_security" Style="{DynamicResource RailItem}" Tag="security" ToolTip="G&#x00FC;venlik: denetim ve sertle&#x015F;tirme">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoShieldCheck}"/>
                    <TextBlock Text="G&#x00FC;venlik" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_updates" Style="{DynamicResource RailItem}" Tag="updates" ToolTip="G&#x00FC;ncellemeler: Windows, programlar ve s&#x00FC;r&#x00FC;c&#x00FC; durumu">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoRefresh}"/>
                    <TextBlock Text="G&#x00FC;ncelle" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_network" Style="{DynamicResource RailItem}" Tag="network" ToolTip="A&#x011F;: cihazlar, koruma, VPN, DNS, h&#x0131;z testi, ba&#x011F;lant&#x0131;lar, a&#x00E7;&#x0131;k portlar">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoGlobe}"/>
                    <TextBlock Text="A&#x011F;" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_solve" Style="{DynamicResource RailItem}" Tag="solve" ToolTip="&#x00C7;&#x00F6;z&#x00FC;m Merkezi: sorunlar&#x0131; bulur ve d&#x00FC;zeltir; disk &#x015F;ifreleme, silinen dosya kurtarma, sorun gidericiler">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoSolve}"/>
                    <TextBlock Text="&#x00C7;&#x00F6;z&#x00FC;m" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_backup" Style="{DynamicResource RailItem}" Tag="backup" ToolTip="Yedek ve kurtarma: dosya yede&#x011F;i, silinen dosya kurtarma">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoDisk}"/>
                    <TextBlock Text="Yedek" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_company" Style="{DynamicResource RailItem}" Tag="company" ToolTip="&#x015E;irket: rapor, envanter, ilkeler, zamanlanm&#x0131;&#x015F; g&#x00F6;revler">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoBuilding}"/>
                    <TextBlock Text="&#x015E;irket" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton x:Name="Rail_tools" Style="{DynamicResource RailItem}" Tag="tools" ToolTip="Ara&#x00E7;lar: Windows ara&#x00E7;lar&#x0131;, i&#x015F;lemler, onar&#x0131;m">
                  <StackPanel HorizontalAlignment="Center">
                    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoTools}"/>
                    <TextBlock Text="Ara&#x00E7;lar" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                  </StackPanel>
                </RadioButton>
              </StackPanel>
            </ScrollViewer>
            <StackPanel x:Name="FlyRail" Grid.Row="0" Visibility="Collapsed" Margin="0,18,0,0" HorizontalAlignment="Center"/>
            <StackPanel x:Name="RailBottom" Grid.Row="1" Margin="0,0,0,6">
              <RadioButton x:Name="Rail_history" Style="{DynamicResource RailItem}" Tag="history" ToolTip="Ge&#x00E7;mi&#x015F; ve geri alma">
                <StackPanel HorizontalAlignment="Center">
                  <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoUndo}"/>
                  <TextBlock Text="Ge&#x00E7;mi&#x015F;" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                </StackPanel>
              </RadioButton>
              <RadioButton x:Name="Rail_settings" Style="{DynamicResource RailItem}" Tag="settings" ToolTip="Ayarlar">
                <StackPanel HorizontalAlignment="Center">
                  <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoSliders}"/>
                  <TextBlock Text="Ayarlar" FontSize="9.5" HorizontalAlignment="Center" Margin="0,3,0,0"/>
                </StackPanel>
              </RadioButton>
            </StackPanel>
          </Grid>
        </Border>

        <!-- i&#x015F;lem g&#x00FC;nl&#x00FC;&#x011F;&#x00FC; -->
        <Border x:Name="LogPanel" Grid.Column="1" Style="{DynamicResource Card}" Margin="8,8,0,8" Padding="0">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="*"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <Grid Grid.Row="0" Margin="14,10,10,6">
              <TextBlock Text="&#x0130;&#x015E;LEM G&#x00DC;NL&#x00DC;&#x011E;&#x00DC;" Style="{DynamicResource TxtCardTitle}"/>
              <TextBlock x:Name="TxtLogCount" Text="" HorizontalAlignment="Right" FontSize="11" Foreground="{DynamicResource BrFaint}" VerticalAlignment="Center"/>
            </Grid>
            <Border x:Name="JobPanel" Grid.Row="1" Visibility="Collapsed" Background="{DynamicResource BrCard}" BorderBrush="{DynamicResource BrLine}" BorderThickness="0,1,0,1" Padding="14,8">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel Grid.Column="0" Margin="0,0,10,0">
                  <TextBlock x:Name="JobLabel" Text="" FontSize="12" Foreground="{DynamicResource BrText}" TextTrimming="CharacterEllipsis"/>
                  <ProgressBar x:Name="JobBar" Margin="0,6,0,0" Value="0"/>
                  <TextBlock x:Name="JobPct" Text="" FontSize="11" Foreground="{DynamicResource BrDim}" Margin="0,4,0,0"/>
                </StackPanel>
                <Button x:Name="BtnCancel" Grid.Column="1" Style="{DynamicResource BtnDanger}" Content="Durdur" Padding="10,5" VerticalAlignment="Center"/>
              </Grid>
            </Border>
            <ScrollViewer x:Name="LogScroll" Grid.Row="2" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="10,6,4,6">
              <StackPanel x:Name="LogStack"/>
            </ScrollViewer>
            <StackPanel Grid.Row="3" Orientation="Horizontal" Margin="10,0,10,10">
              <Button x:Name="BtnLogClear" Style="{DynamicResource BtnMini}" Content="Temizle"/>
              <Button x:Name="BtnLogCopy" Style="{DynamicResource BtnMini}" Content="Kopyala" Margin="6,0,0,0"/>
              <Button x:Name="BtnLogOpen" Style="{DynamicResource BtnMini}" Content="Kay&#x0131;t klas&#x00F6;r&#x00FC;" Margin="6,0,0,0"/>
            </StackPanel>
          </Grid>
        </Border>

        <!-- sayfa alan&#x0131; + komut sat&#x0131;r&#x0131; -->
        <Grid Grid.Column="2">
          <Grid.RowDefinitions>
            <RowDefinition Height="*"/>
            <RowDefinition x:Name="RowCmd" Height="Auto"/>
          </Grid.RowDefinitions>
          <Grid Grid.Row="0" Margin="8,8,8,0">
            <Grid x:Name="PageHost"/>
            <StackPanel x:Name="ToastHost" VerticalAlignment="Bottom" HorizontalAlignment="Right" Margin="0,0,14,12"/>
          </Grid>
          <Border x:Name="CmdPanel" Grid.Row="1" Style="{DynamicResource Card}" Margin="8,8,8,8" Padding="0" Height="160">
            <Grid>
              <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="Auto"/>
              </Grid.RowDefinitions>
              <Grid Grid.Row="0" Margin="14,9,14,2">
                <TextBlock Text="KOMUT SATIRI" Style="{DynamicResource TxtCardTitle}"/>
                <TextBlock Text="yard&#x0131;m yaz&#x0131;n &#x00B7; Tab ile tamamlar" HorizontalAlignment="Right" FontSize="11" Foreground="{DynamicResource BrFaint}" VerticalAlignment="Center"/>
              </Grid>
              <ScrollViewer x:Name="CmdScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="12,0,6,0">
                <StackPanel x:Name="CmdOut"/>
              </ScrollViewer>
              <Grid Grid.Row="2" Margin="12,4,12,10">
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="Auto"/>
                  <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                <TextBlock Grid.Column="0" Text="&gt;" FontFamily="{DynamicResource FontMono}" FontSize="14" Foreground="{DynamicResource BrAccent}" VerticalAlignment="Center" Margin="2,0,8,0"/>
                <TextBox x:Name="CmdInput" Grid.Column="1" FontFamily="{DynamicResource FontMono}" FontSize="12.5" Padding="8,5" Background="{DynamicResource BrBg}"/>
                <Popup x:Name="CmdPop" PlacementTarget="{Binding ElementName=CmdInput}" Placement="Top" StaysOpen="True" AllowsTransparency="True" IsOpen="False">
                  <Border Background="{DynamicResource BrPanel2}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1" CornerRadius="6" Padding="3" MinWidth="420" MaxHeight="240" Margin="0,0,0,4">
                    <ListBox x:Name="CmdList" Style="{DynamicResource AcList}"/>
                  </Border>
                </Popup>
              </Grid>
            </Grid>
          </Border>
        </Grid>
      </Grid>

      <!-- ===== DURUM &#x00C7;UBU&#x011E;U ===== -->
      <Grid Grid.Row="2" Background="{DynamicResource BrTitle}">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="Auto"/>
          <ColumnDefinition Width="*"/>
          <ColumnDefinition Width="Auto"/>
        </Grid.ColumnDefinitions>
        <StackPanel Grid.Column="0" Orientation="Horizontal" Margin="14,0,0,0" VerticalAlignment="Center">
          <TextBlock x:Name="TxtSig" Text="" FontSize="11.5" Foreground="{DynamicResource BrGold}"/>
          <TextBlock x:Name="TxtVer" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" Margin="12,0,0,0"/>
        </StackPanel>
        <TextBlock x:Name="TxtSys" Grid.Column="1" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
        <StackPanel Grid.Column="2" Orientation="Horizontal" Margin="0,0,14,0" VerticalAlignment="Center">
          <TextBlock x:Name="TxtHealth" Text="" FontSize="11" Foreground="{DynamicResource BrDim}"/>
          <TextBlock x:Name="TxtClock" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" Margin="14,0,0,0"/>
        </StackPanel>
      </Grid>

      <!-- ===== ONAY / B&#x0130;LG&#x0130; / G&#x0130;R&#x0130;&#x015E; KUTUSU (pencere i&#x00E7;i) ===== -->
      <Grid x:Name="AskOverlay" Grid.RowSpan="3" Visibility="Collapsed" Background="{DynamicResource BrOverlay}">
        <Border x:Name="AskCard" Style="{DynamicResource Card}" Width="640" MaxHeight="600" HorizontalAlignment="Center" VerticalAlignment="Top" Margin="0,58,0,0" Padding="0" BorderBrush="{DynamicResource BrLine2}" Background="{DynamicResource BrPanel2}">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="*"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <Grid Grid.Row="0" Margin="18,14,12,4">
              <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoSpark}" Width="17" Height="17" Foreground="{DynamicResource BrAccent}" VerticalAlignment="Center"/>
                <TextBlock Text="Asistan" Style="{DynamicResource TxtH2}" Margin="9,0,0,0" VerticalAlignment="Center"/>
                <TextBlock Text="yerel &#x00B7; veri g&#x00F6;ndermez" FontSize="11" Foreground="{DynamicResource BrFaint}" Margin="10,3,0,0" VerticalAlignment="Center"/>
              </StackPanel>
              <Button x:Name="AskClose" Style="{DynamicResource BtnMini}" Content="Kapat (Esc)" HorizontalAlignment="Right" VerticalAlignment="Center"/>
            </Grid>
            <ScrollViewer x:Name="AskScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="0,4,4,0" MinHeight="150">
              <StackPanel x:Name="AskChat" Margin="18,2,12,6"/>
            </ScrollViewer>
            <WrapPanel x:Name="AskChips" Grid.Row="2" Margin="18,6,16,0"/>
            <Grid Grid.Row="3" Margin="18,6,16,16">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <TextBox x:Name="AskInput" Grid.Column="0" FontSize="13" Padding="10,7" MaxLength="200"/>
              <Button x:Name="AskSend" Grid.Column="1" Style="{DynamicResource BtnPrimary}" Content="Sor" Margin="8,0,0,0" Padding="18,7"/>
            </Grid>
          </Grid>
        </Border>
      </Grid>
      <Grid x:Name="Overlay" Grid.RowSpan="3" Visibility="Collapsed" Background="{DynamicResource BrOverlay}">
        <Border Style="{DynamicResource Card}" Width="540" HorizontalAlignment="Center" VerticalAlignment="Center" Padding="22" Margin="0" BorderBrush="{DynamicResource BrLine2}" Background="{DynamicResource BrPanel2}">
          <StackPanel>
            <TextBlock x:Name="OvTitle" Style="{DynamicResource TxtH2}" Text=""/>
            <ScrollViewer MaxHeight="380" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="0,10,0,0">
              <TextBlock x:Name="OvText" Style="{DynamicResource TxtBody}" Text=""/>
            </ScrollViewer>
            <StackPanel x:Name="OvChoices" Margin="0,12,0,0" Visibility="Collapsed"/>
            <TextBox x:Name="OvInput" Margin="0,12,0,0" Visibility="Collapsed"/>
            <PasswordBox x:Name="OvPw1" Margin="0,12,0,0" Visibility="Collapsed"/>
            <PasswordBox x:Name="OvPw2" Margin="0,8,0,0" Visibility="Collapsed"/>
            <TextBlock x:Name="OvErr" Style="{DynamicResource TxtDim}" Foreground="{DynamicResource BrBad}" Margin="0,8,0,0" Visibility="Collapsed"/>
            <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,18,0,0">
              <Button x:Name="OvCancel" Style="{DynamicResource BtnGhost}" Content="Vazge&#x00E7;" Margin="0,0,8,0"/>
              <Button x:Name="OvOk" Style="{DynamicResource BtnPrimary}" Content="Tamam" MinWidth="90"/>
            </StackPanel>
          </StackPanel>
        </Border>
      </Grid>
    </Grid>
  </Border>
</Window>
'@

# ==================================================================
#  ARAYUZ: satir sablonlari (XamlReader ile calisma aninda uretilir). @@Ad@@ = XML kacisli metin;
#  @@BrXxx@@ / @@IcoXxx@@ = kaynak anahtari. Olay isleyicileri kodda eklenir (XAML'de olay yok).
# ==================================================================
$script:Row_Toast = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Background="{DynamicResource BrPanel2}" BorderBrush="{DynamicResource @@BrCol@@}" BorderThickness="1,1,1,1" CornerRadius="8" Padding="12,9" Margin="0,6,0,0" MaxWidth="440">
  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="*"/>
    </Grid.ColumnDefinitions>
    <ContentControl Grid.Column="0" Style="{DynamicResource Icon}" Tag="{DynamicResource @@IcoName@@}" Width="18" Height="18" Foreground="{DynamicResource @@BrCol@@}" VerticalAlignment="Top" Margin="0,1,10,0"/>
    <TextBlock Grid.Column="1" Text="@@Text@@" Style="{DynamicResource TxtBody}" FontSize="12.5"/>
  </Grid>
</Border>
'@

# Genel liste satiri: onay kutusu + renkli nokta + baslik/ayrinti + etiket + iki dugme
$script:Row_Item = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Style="{DynamicResource Row}" Margin="0,0,0,5" Padding="10,8">
  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="Auto"/>
    </Grid.ColumnDefinitions>
    <CheckBox x:Name="Chk" Grid.Column="0" VerticalAlignment="Center" Margin="0,0,10,0"/>
    <Ellipse x:Name="Dot" Grid.Column="1" Width="8" Height="8" Fill="{DynamicResource @@BrCol@@}" VerticalAlignment="Center" Margin="0,0,10,0"/>
    <StackPanel Grid.Column="2" VerticalAlignment="Center">
      <TextBlock x:Name="Ttl" Text="@@Title@@" Style="{DynamicResource TxtBody}" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/>
      <TextBlock x:Name="Det" Text="@@Detail@@" Style="{DynamicResource TxtDim}" FontSize="11.5" TextWrapping="Wrap" Margin="0,2,0,0"/>
    </StackPanel>
    <TextBlock x:Name="Tag" Grid.Column="3" Text="@@Tag@@" Foreground="{DynamicResource @@BrCol@@}" FontSize="11.5" FontWeight="SemiBold" VerticalAlignment="Center" Margin="10,0,6,0"/>
    <Button x:Name="Act" Grid.Column="4" Content="@@Btn1@@" Style="{DynamicResource BtnMini}" Margin="6,0,0,0" VerticalAlignment="Center"/>
    <Button x:Name="Act2" Grid.Column="5" Content="@@Btn2@@" Style="{DynamicResource BtnMini}" Margin="6,0,0,0" VerticalAlignment="Center"/>
  </Grid>
</Border>
'@

# Pano bulgusu: nokta + baslik/ayrinti + eylem dugmesi
$script:Row_Finding = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Style="{DynamicResource Row}" Margin="0,0,0,5" Padding="10,8">
  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="Auto"/>
    </Grid.ColumnDefinitions>
    <Ellipse Grid.Column="0" Width="8" Height="8" Fill="{DynamicResource @@BrCol@@}" VerticalAlignment="Top" Margin="0,5,10,0"/>
    <StackPanel Grid.Column="1" VerticalAlignment="Center">
      <TextBlock x:Name="Ttl" Text="@@Title@@" Style="{DynamicResource TxtBody}" FontWeight="SemiBold" TextWrapping="Wrap"/>
      <TextBlock x:Name="Det" Text="@@Detail@@" Style="{DynamicResource TxtDim}" FontSize="11.5" TextWrapping="Wrap" Margin="0,2,0,0"/>
    </StackPanel>
    <Button x:Name="Fx" Grid.Column="2" Content="@@FixBtn@@" Style="{DynamicResource BtnPrimary}" Padding="9,4" FontSize="11.5" Margin="10,0,0,0" VerticalAlignment="Center"/>
    <Button x:Name="Act" Grid.Column="3" Content="@@Btn@@" Style="{DynamicResource BtnMini}" Margin="6,0,0,0" VerticalAlignment="Center"/>
  </Grid>
</Border>
'@

# Anahtar / deger satiri (bilgi kartlari)
$script:Row_Kv = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,0,5">
  <Grid.ColumnDefinitions>
    <ColumnDefinition Width="170"/>
    <ColumnDefinition Width="*"/>
  </Grid.ColumnDefinitions>
  <TextBlock Grid.Column="0" Text="@@Key@@" Style="{DynamicResource TxtDim}" FontSize="12"/>
  <TextBlock Grid.Column="1" Text="@@Val@@" Style="{DynamicResource TxtBody}" FontSize="12.5" TextWrapping="Wrap"/>
</Grid>
'@

# Komut satiri otomatik tamamlama ogesi
$script:Row_CmdItem = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Grid.ColumnDefinitions>
    <ColumnDefinition Width="132"/>
    <ColumnDefinition Width="*"/>
  </Grid.ColumnDefinitions>
  <TextBlock Grid.Column="0" Text="@@Name@@" Style="{DynamicResource TxtMono}" Foreground="{DynamicResource BrAccent}"/>
  <TextBlock Grid.Column="1" Text="@@Desc@@" Style="{DynamicResource TxtDim}" FontSize="11.5" TextTrimming="CharacterEllipsis"/>
</Grid>
'@

# Bolum basligi (liste icinde)
$script:Row_Head = @'
<TextBlock xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Text="@@Text@@" Style="{DynamicResource TxtCardTitle}" Margin="4,10,0,6"/>
'@

# ==================================================================
#  SAYFA XAML: Durum panosu (ana ekran): kaynak gostergeleri, saglik, ag topolojisi, arac kutusu
# ==================================================================
$script:Page_panel = @'
<ScrollViewer xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
              VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
  <Grid Margin="0,0,6,8">
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="316"/>
    </Grid.ColumnDefinitions>

    <StackPanel Grid.Column="0" Margin="0,0,10,0">

      <!-- S&#x0130;STEM KAYNAKLARI -->
      <Border Style="{DynamicResource Card}">
        <StackPanel>
          <Grid Margin="0,0,0,10">
            <TextBlock Text="S&#x0130;STEM KAYNAKLARI" Style="{DynamicResource TxtCardTitle}"/>
            <TextBlock x:Name="pn_SysLine" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Right" VerticalAlignment="Center"/>
          </Grid>
          <Grid>
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="1.35*"/>
            </Grid.ColumnDefinitions>

            <StackPanel Grid.Column="0" HorizontalAlignment="Center">
              <Grid Width="118" Height="108">
                <Ellipse Width="104" Height="104" Stroke="{DynamicResource BrLine}" StrokeThickness="9" StrokeDashArray="24.87,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse x:Name="pn_GCpu" Width="104" Height="104" Stroke="{DynamicResource BrCpu}" StrokeThickness="9" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                  <Ellipse.Effect>
                    <DropShadowEffect Color="#4FA3FF" BlurRadius="12" ShadowDepth="0" Opacity="0.55"/>
                  </Ellipse.Effect>
                </Ellipse>
                <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                  <TextBlock x:Name="pn_VCpu" Text="--" FontSize="25" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
                  <TextBlock Text="CPU" FontSize="11" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
                </StackPanel>
              </Grid>
              <TextBlock x:Name="pn_DCpu" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="132"/>
            </StackPanel>

            <StackPanel Grid.Column="1" HorizontalAlignment="Center">
              <Grid Width="118" Height="108">
                <Ellipse Width="104" Height="104" Stroke="{DynamicResource BrLine}" StrokeThickness="9" StrokeDashArray="24.87,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse x:Name="pn_GRam" Width="104" Height="104" Stroke="{DynamicResource BrRam}" StrokeThickness="9" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                  <Ellipse.Effect>
                    <DropShadowEffect Color="#8C6BFF" BlurRadius="12" ShadowDepth="0" Opacity="0.55"/>
                  </Ellipse.Effect>
                </Ellipse>
                <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                  <TextBlock x:Name="pn_VRam" Text="--" FontSize="25" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
                  <TextBlock Text="RAM" FontSize="11" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
                </StackPanel>
              </Grid>
              <TextBlock x:Name="pn_DRam" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="132"/>
            </StackPanel>

            <StackPanel Grid.Column="2" HorizontalAlignment="Center">
              <Grid Width="118" Height="108">
                <Ellipse Width="104" Height="104" Stroke="{DynamicResource BrLine}" StrokeThickness="9" StrokeDashArray="24.87,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse x:Name="pn_GGpu" Width="104" Height="104" Stroke="{DynamicResource BrGpu}" StrokeThickness="9" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                  <Ellipse.Effect>
                    <DropShadowEffect Color="#3EE6A8" BlurRadius="12" ShadowDepth="0" Opacity="0.55"/>
                  </Ellipse.Effect>
                </Ellipse>
                <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                  <TextBlock x:Name="pn_VGpu" Text="--" FontSize="25" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
                  <TextBlock Text="GPU" FontSize="11" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
                </StackPanel>
              </Grid>
              <TextBlock x:Name="pn_DGpu" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="132"/>
            </StackPanel>

            <StackPanel Grid.Column="3" HorizontalAlignment="Center">
              <Grid Width="118" Height="108">
                <Ellipse Width="104" Height="104" Stroke="{DynamicResource BrLine}" StrokeThickness="9" StrokeDashArray="24.87,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse x:Name="pn_GDisk" Width="104" Height="104" Stroke="{DynamicResource BrDisk}" StrokeThickness="9" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="135"/>
                  </Ellipse.RenderTransform>
                  <Ellipse.Effect>
                    <DropShadowEffect Color="#E2A93F" BlurRadius="12" ShadowDepth="0" Opacity="0.5"/>
                  </Ellipse.Effect>
                </Ellipse>
                <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                  <TextBlock x:Name="pn_VDisk" Text="--" FontSize="25" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
                  <TextBlock Text="D&#x0130;SK" FontSize="11" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
                </StackPanel>
              </Grid>
              <TextBlock x:Name="pn_DDisk" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="132"/>
            </StackPanel>

            <StackPanel Grid.Column="4" Margin="14,4,0,0">
              <TextBlock Text="A&#x011E; TRAF&#x0130;&#x011E;&#x0130;" FontSize="11" FontWeight="SemiBold" Foreground="{DynamicResource BrDim}"/>
              <Grid Margin="0,10,0,0">
                <TextBlock Text="&#x0130;ndirme" FontSize="11.5" Foreground="{DynamicResource BrDim}"/>
                <TextBlock x:Name="pn_TxtDown" Text="0 Mb/sn" FontSize="11.5" Foreground="{DynamicResource BrText}" HorizontalAlignment="Right"/>
              </Grid>
              <ProgressBar x:Name="pn_BarDown" Margin="0,4,0,0" Maximum="100" Value="0"/>
              <Grid Margin="0,12,0,0">
                <TextBlock Text="Y&#x00FC;kleme" FontSize="11.5" Foreground="{DynamicResource BrDim}"/>
                <TextBlock x:Name="pn_TxtUp" Text="0 Mb/sn" FontSize="11.5" Foreground="{DynamicResource BrText}" HorizontalAlignment="Right"/>
              </Grid>
              <ProgressBar x:Name="pn_BarUp" Margin="0,4,0,0" Maximum="100" Value="0" Foreground="{DynamicResource BrAccent2}"/>
              <TextBlock Text="EN &#x00C7;OK &#x0130;&#x015E;LEMC&#x0130; KULLANAN" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource BrFaint}" Margin="0,14,0,4" TextWrapping="Wrap"/>
              <StackPanel x:Name="pn_Top"/>
            </StackPanel>
          </Grid>
        </StackPanel>
      </Border>

      <!-- S&#x0130;STEM SA&#x011E;LI&#x011E;I -->
      <Border Style="{DynamicResource Card}">
        <StackPanel>
          <Grid Margin="0,0,0,10">
            <TextBlock Text="S&#x0130;STEM SA&#x011E;LI&#x011E;I VE &#x00D6;NER&#x0130;LER" Style="{DynamicResource TxtCardTitle}"/>
            <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
              <Button x:Name="pn_BtnFixAll" Style="{DynamicResource BtnPrimary}" Padding="9,4" FontSize="11.5" Content="Hepsini d&#x00FC;zelt" Margin="0,0,6,0" Visibility="Collapsed"/>
              <Button x:Name="pn_BtnHealth" Style="{DynamicResource BtnMini}" Content="H&#x0131;zl&#x0131; tara"/>
              <Button x:Name="pn_BtnHealthFull" Style="{DynamicResource BtnMini}" Content="Tam g&#x00FC;venlik denetimi" Margin="6,0,0,0"/>
            </StackPanel>
          </Grid>
          <Grid>
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="190"/>
              <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>
            <StackPanel Grid.Column="0">
              <Grid Width="112" Height="112" HorizontalAlignment="Center">
                <Ellipse Width="104" Height="104" Stroke="{DynamicResource BrLine}" StrokeThickness="8"/>
                <Ellipse x:Name="pn_GScore" Width="104" Height="104" Stroke="{DynamicResource BrGood}" StrokeThickness="8" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                  <Ellipse.RenderTransform>
                    <RotateTransform Angle="-90"/>
                  </Ellipse.RenderTransform>
                </Ellipse>
                <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
                  <TextBlock x:Name="pn_VScore" Text="--" FontSize="30" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
                  <TextBlock Text="SA&#x011E;LIK PUANI" FontSize="9.5" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
                </StackPanel>
              </Grid>
              <Grid Margin="0,10,0,0">
                <TextBlock Text="G&#x00FC;venlik" FontSize="11" Foreground="{DynamicResource BrDim}"/>
                <TextBlock x:Name="pn_VSec" Text="--" FontSize="11" Foreground="{DynamicResource BrText}" HorizontalAlignment="Right"/>
              </Grid>
              <ProgressBar x:Name="pn_BarSec" Margin="0,3,0,0" Height="4"/>
              <Grid Margin="0,7,0,0">
                <TextBlock Text="Performans" FontSize="11" Foreground="{DynamicResource BrDim}"/>
                <TextBlock x:Name="pn_VPerf" Text="--" FontSize="11" Foreground="{DynamicResource BrText}" HorizontalAlignment="Right"/>
              </Grid>
              <ProgressBar x:Name="pn_BarPerf" Margin="0,3,0,0" Height="4" Foreground="{DynamicResource BrBlue}"/>
              <Grid Margin="0,7,0,0">
                <TextBlock Text="Bak&#x0131;m" FontSize="11" Foreground="{DynamicResource BrDim}"/>
                <TextBlock x:Name="pn_VMaint" Text="--" FontSize="11" Foreground="{DynamicResource BrText}" HorizontalAlignment="Right"/>
              </Grid>
              <ProgressBar x:Name="pn_BarMaint" Margin="0,3,0,0" Height="4" Foreground="{DynamicResource BrGold}"/>
            </StackPanel>
            <StackPanel Grid.Column="1" Margin="14,0,0,0">
              <TextBlock x:Name="pn_HealthNote" Text="Hen&#x00FC;z taranmad&#x0131;. &#x201C;H&#x0131;zl&#x0131; tara&#x201D; d&#x00FC;&#x011F;mesine bas&#x0131;n." Style="{DynamicResource TxtDim}" Margin="0,0,0,8"/>
              <StackPanel x:Name="pn_Findings"/>
            </StackPanel>
          </Grid>
        </StackPanel>
      </Border>

      <!-- A&#x011E; TOPOLOJ&#x0130;S&#x0130; -->
      <Border Style="{DynamicResource Card}">
        <StackPanel>
          <Grid Margin="0,0,0,10">
            <TextBlock Text="A&#x011E; TOPOLOJ&#x0130;S&#x0130;" Style="{DynamicResource TxtCardTitle}"/>
            <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
              <TextBlock x:Name="pn_TopoInfo" Text="" FontSize="11" Foreground="{DynamicResource BrFaint}" VerticalAlignment="Center" Margin="0,0,10,0"/>
              <RadioButton x:Name="pn_TopoModeLan" Content="Yerel a&#x011F;" GroupName="pn_topomode" Style="{DynamicResource Chip}" IsChecked="True" Margin="0,0,4,0"/>
              <RadioButton x:Name="pn_TopoModeConn" Content="Ba&#x011F;lant&#x0131;lar" GroupName="pn_topomode" Style="{DynamicResource Chip}" Margin="0,0,10,0"/>
              <Button x:Name="pn_BtnTopo" Style="{DynamicResource BtnMini}" Content="A&#x011F;&#x0131; tara"/>
            </StackPanel>
          </Grid>
          <Border CornerRadius="8" BorderBrush="{DynamicResource BrLine}" BorderThickness="1" Background="{DynamicResource BrMapBg}" ClipToBounds="True">
            <Canvas x:Name="pn_Topo" Height="320" ClipToBounds="True" Background="Transparent">
              <Border x:Name="pn_TopoTip" Visibility="Collapsed" Background="{DynamicResource BrTipBg}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1" CornerRadius="6" Padding="10,7" MaxWidth="280" Panel.ZIndex="50" IsHitTestVisible="False">
                <TextBlock x:Name="pn_TopoTipTxt" FontSize="11.5" Foreground="{DynamicResource BrText}" TextWrapping="Wrap"/>
              </Border>
            </Canvas>
          </Border>
          <TextBlock x:Name="pn_TopoHint" Text="D&#x00FC;&#x011F;&#x00FC;mlerin &#x00FC;zerine gelin: ba&#x011F;lant&#x0131; say&#x0131;s&#x0131; ve uzak adresler g&#x00F6;r&#x00FC;n&#x00FC;r. K&#x0131;rm&#x0131;z&#x0131; d&#x00FC;&#x011F;&#x00FC;m d&#x0131;&#x015F;ar&#x0131;dan eri&#x015F;ilebilen portlar&#x0131; g&#x00F6;sterir." Style="{DynamicResource TxtDim}" FontSize="11" Margin="0,8,0,0"/>
        </StackPanel>
      </Border>
    </StackPanel>

    <StackPanel Grid.Column="1">

      <!-- ARA&#x00C7; KUTUSU -->
      <Border Style="{DynamicResource Card}" Padding="10">
        <StackPanel>
          <Grid Margin="4,2,4,6">
            <TextBlock Text="ARA&#x00C7; KUTUSU" Style="{DynamicResource TxtCardTitle}"/>
          </Grid>
          <UniformGrid Columns="2">
            <Button x:Name="pn_T1" Style="{DynamicResource ToolCard}" ToolTip="Ge&#x00E7;ici dosyalar&#x0131; temizler, diski optimize eder">
              <StackPanel>
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoTools}" Width="34" Height="34" Foreground="{DynamicResource BrGold}" HorizontalAlignment="Center"/>
                <TextBlock Text="H&#x0131;zl&#x0131; Bak&#x0131;m" FontSize="12" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center" Margin="0,8,0,0"/>
                <TextBlock Text="temizlik &#x00B7; disk" FontSize="10.5" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
              </StackPanel>
            </Button>
            <Button x:Name="pn_T2" Style="{DynamicResource ToolCard}" ToolTip="Sa&#x011F;l&#x0131;k puan&#x0131;n&#x0131; ve &#x00F6;nerileri yeniler">
              <StackPanel>
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoPulse}" Width="34" Height="34" Foreground="{DynamicResource BrGold}" HorizontalAlignment="Center"/>
                <TextBlock Text="Sa&#x011F;l&#x0131;k Taramas&#x0131;" FontSize="12" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center" Margin="0,8,0,0"/>
                <TextBlock Text="puan &#x00B7; &#x00F6;neriler" FontSize="10.5" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
              </StackPanel>
            </Button>
            <Button x:Name="pn_T3" Style="{DynamicResource ToolCard}" ToolTip="Tam g&#x00FC;venlik denetimini ba&#x015F;lat&#x0131;r">
              <StackPanel>
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoShieldCheck}" Width="34" Height="34" Foreground="{DynamicResource BrGold}" HorizontalAlignment="Center"/>
                <TextBlock Text="G&#x00FC;venlik Denetimi" FontSize="12" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center" Margin="0,8,0,0"/>
                <TextBlock Text="Defender &#x00B7; duvar &#x00B7; hesap" FontSize="10.5" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
              </StackPanel>
            </Button>
            <Button x:Name="pn_T4" Style="{DynamicResource ToolCard}" ToolTip="&#x00D6;nerilen ayarlarla sistemi h&#x0131;zland&#x0131;r&#x0131;r">
              <StackPanel>
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoBolt}" Width="34" Height="34" Foreground="{DynamicResource BrGold}" HorizontalAlignment="Center"/>
                <TextBlock Text="Optimizasyon" FontSize="12" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center" Margin="0,8,0,0"/>
                <TextBlock Text="&#x00F6;nerilen ayarlar" FontSize="10.5" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
              </StackPanel>
            </Button>
            <Button x:Name="pn_T5" Style="{DynamicResource ToolCard}" ToolTip="Ayarlardaki klas&#x00F6;rleri yedekler">
              <StackPanel>
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoDisk}" Width="34" Height="34" Foreground="{DynamicResource BrGold}" HorizontalAlignment="Center"/>
                <TextBlock Text="Yedekle" FontSize="12" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center" Margin="0,8,0,0"/>
                <TextBlock Text="dosyalar&#x0131;n&#x0131;z g&#x00FC;vende" FontSize="10.5" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
              </StackPanel>
            </Button>
            <Button x:Name="pn_T6" Style="{DynamicResource ToolCard}" ToolTip="HTML durum ve envanter raporu olu&#x015F;turur">
              <StackPanel>
                <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource IcoReport}" Width="34" Height="34" Foreground="{DynamicResource BrGold}" HorizontalAlignment="Center"/>
                <TextBlock Text="Rapor Olu&#x015F;tur" FontSize="12" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center" Margin="0,8,0,0"/>
                <TextBlock Text="envanter &#x00B7; durum" FontSize="10.5" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
              </StackPanel>
            </Button>
          </UniformGrid>
        </StackPanel>
      </Border>

      <!-- BU B&#x0130;LG&#x0130;SAYAR -->
      <Border Style="{DynamicResource Card}">
        <StackPanel>
          <TextBlock Text="BU B&#x0130;LG&#x0130;SAYAR" Style="{DynamicResource TxtCardTitle}" Margin="0,0,0,8"/>
          <Grid>
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="82"/>
              <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <TextBlock Grid.Row="0" Grid.Column="0" Text="Windows" FontSize="11.5" Foreground="{DynamicResource BrDim}" Margin="0,3"/>
            <TextBlock x:Name="pn_SiOs" Grid.Row="0" Grid.Column="1" Text="..." FontSize="11.5" Foreground="{DynamicResource BrText}" TextWrapping="Wrap" Margin="0,3"/>
            <TextBlock Grid.Row="1" Grid.Column="0" Text="&#x0130;&#x015F;lemci" FontSize="11.5" Foreground="{DynamicResource BrDim}" Margin="0,3"/>
            <TextBlock x:Name="pn_SiCpu" Grid.Row="1" Grid.Column="1" Text="..." FontSize="11.5" Foreground="{DynamicResource BrText}" TextWrapping="Wrap" Margin="0,3"/>
            <TextBlock Grid.Row="2" Grid.Column="0" Text="Bellek" FontSize="11.5" Foreground="{DynamicResource BrDim}" Margin="0,3"/>
            <TextBlock x:Name="pn_SiRam" Grid.Row="2" Grid.Column="1" Text="..." FontSize="11.5" Foreground="{DynamicResource BrText}" Margin="0,3"/>
            <TextBlock Grid.Row="3" Grid.Column="0" Text="Disk" FontSize="11.5" Foreground="{DynamicResource BrDim}" Margin="0,3"/>
            <TextBlock x:Name="pn_SiDisk" Grid.Row="3" Grid.Column="1" Text="..." FontSize="11.5" Foreground="{DynamicResource BrText}" TextWrapping="Wrap" Margin="0,3"/>
            <TextBlock Grid.Row="4" Grid.Column="0" Text="Bilgisayar" FontSize="11.5" Foreground="{DynamicResource BrDim}" Margin="0,3"/>
            <TextBlock x:Name="pn_SiHost" Grid.Row="4" Grid.Column="1" Text="..." FontSize="11.5" Foreground="{DynamicResource BrText}" TextWrapping="Wrap" Margin="0,3"/>
            <TextBlock Grid.Row="5" Grid.Column="0" Text="Y&#x00F6;netim" FontSize="11.5" Foreground="{DynamicResource BrDim}" Margin="0,3"/>
            <TextBlock x:Name="pn_SiMgmt" Grid.Row="5" Grid.Column="1" Text="..." FontSize="11.5" Foreground="{DynamicResource BrText}" TextWrapping="Wrap" Margin="0,3"/>
            <TextBlock Grid.Row="6" Grid.Column="0" Text="A&#x00E7;&#x0131;k kalma" FontSize="11.5" Foreground="{DynamicResource BrDim}" Margin="0,3"/>
            <TextBlock x:Name="pn_SiUp" Grid.Row="6" Grid.Column="1" Text="..." FontSize="11.5" Foreground="{DynamicResource BrText}" Margin="0,3"/>
          </Grid>
        </StackPanel>
      </Border>

      <!-- HIZLI DURUM -->
      <Border Style="{DynamicResource Card}">
        <StackPanel>
          <TextBlock Text="HIZLI DURUM" Style="{DynamicResource TxtCardTitle}" Margin="0,0,0,8"/>
          <TextBlock x:Name="pn_QsMaint" Text="" Style="{DynamicResource TxtDim}" Margin="0,2"/>
          <TextBlock x:Name="pn_QsBackup" Text="" Style="{DynamicResource TxtDim}" Margin="0,2"/>
          <TextBlock x:Name="pn_QsReboot" Text="" Style="{DynamicResource TxtDim}" Margin="0,2"/>
          <TextBlock x:Name="pn_QsRp" Text="" Style="{DynamicResource TxtDim}" Margin="0,2"/>
        </StackPanel>
      </Border>
    </StackPanel>
  </Grid>
</ScrollViewer>
'@

# ==================================================================
#  SAYFA XAML (tools/pages_gen.py ile uretilir; elle duzenlemeyin)
# ==================================================================
$script:Page_optimize = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="op_Title" Text="Optimizasyon" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="op_Desc" Text="Gizlilik, performans ve g&#x00F6;r&#x00FC;n&#x00FC;m ayarlar&#x0131;n&#x0131; g&#x00FC;venle uygular. Her de&#x011F;i&#x015F;iklik kaydedilir ve Ge&#x00E7;mi&#x015F; sayfas&#x0131;ndan geri al&#x0131;n&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,3,0,0"/>
  </StackPanel>
  <WrapPanel x:Name="op_Tabs" Grid.Row="1" Margin="0,0,0,8">
    <RadioButton x:Name="op_Tab_all" Content="T&#x00FC;m&#x00FC;" Tag="all" GroupName="op_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="op_Tab_Gizlilik" Content="Gizlilik" Tag="Gizlilik" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="op_Tab_Performans" Content="Performans" Tag="Performans" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="op_Tab_Gorunum" Content="G&#x00F6;r&#x00FC;n&#x00FC;m" Tag="Gorunum" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="op_Tab_Oyun" Content="Oyun" Tag="Oyun" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="op_Tab_Ag" Content="A&#x011F;" Tag="Ag" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="op_Tab_Temizlik" Content="Temizlik" Tag="Temizlik" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="op_Tab_Sistem" Content="Sistem" Tag="Sistem" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="op_Tab_Ozellik" Content="Windows &#x00F6;zellikleri" Tag="Ozellik" GroupName="op_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="op_Bar" Grid.Row="2" Margin="0,0,0,4">
<Button x:Name="op_PA" Content="Bu bilgisayara g&#x00F6;re" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="op_P1" Content="G&#x00FC;venli" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="op_P2" Content="Dengeli (&#x00F6;nerilen)" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="op_P3" Content="Maksimum" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="op_P0" Content="Hi&#x00E7;biri" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="op_PDrift" Content="Geri d&#x00F6;nenleri se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" Visibility="Collapsed" />
<CheckBox x:Name="op_Rp" Content="&#x00D6;nce geri y&#x00FC;kleme noktas&#x0131; olu&#x015F;tur" Margin="0,0,14,6" VerticalAlignment="Center" IsChecked="True" />
<Button x:Name="op_Preview" Content="&#x00D6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" />
<Button x:Name="op_Apply" Content="Se&#x00E7;ilenleri uygula" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" />
  </WrapPanel>
  <StackPanel Grid.Row="3">
<Border x:Name="op_TierCard" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="0">
<Grid>
  <Grid.ColumnDefinitions><ColumnDefinition Width="4"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
  <Border x:Name="op_TierBar" Grid.Column="0" Background="{DynamicResource BrAccent}" CornerRadius="7,0,0,7"/>
  <StackPanel Grid.Column="1" Margin="16,12,16,12">
    <TextBlock Text="BU B&#x0130;LG&#x0130;SAYAR" Style="{DynamicResource TxtCardTitle}"/>
    <TextBlock x:Name="op_TierName" Text="" Style="{DynamicResource TxtH2}" Margin="0,6,0,0"/>
    <TextBlock x:Name="op_TierSum" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,2,0,0"/>
    <TextBlock x:Name="op_TierWhy" Text="" Style="{DynamicResource TxtBody}" TextWrapping="Wrap" Margin="0,8,0,0"/>
  </StackPanel>
</Grid>
</Border>
<Border x:Name="op_UserCard" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="16">
<StackPanel>
  <TextBlock Text="S&#x0130;Z&#x0130;N &#x0130;&#x00C7;&#x0130;N SE&#x00C7;&#x0130;LEN AYARLAR" Style="{DynamicResource TxtCardTitle}"/>
  <TextBlock x:Name="op_UserText" Text="" Style="{DynamicResource TxtBody}" TextWrapping="Wrap" Margin="0,8,0,0"/>
  <TextBlock Text="Tek tek se&#x00E7;mek ve her ayar&#x0131;n ayr&#x0131;nt&#x0131;s&#x0131;n&#x0131; g&#x00F6;rmek i&#x00E7;in sa&#x011F; &#x00FC;stten Uzman kipine ge&#x00E7;in. &#x00D6;nizle d&#x00FC;&#x011F;mesi sistemde hi&#x00E7;bir &#x015F;ey de&#x011F;i&#x015F;tirmez." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,8,0,0"/>
</StackPanel>
</Border>
  </StackPanel>
  <Grid Grid.Row="4">
    <Border x:Name="op_ListCard" Grid.Column="0" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="op_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="op_List"/>
      </ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="op_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

$script:Page_services = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="sv_Title" Text="Hizmet Y&#x00F6;neticisi" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="sv_Desc" Text="Windows hizmetlerini her biri i&#x00E7;in &quot;ne yapar, kapat&#x0131;rsam ne olur&quot; bilgisiyle y&#x00F6;netin. G&#x00FC;venlik ve &#x00E7;al&#x0131;&#x015F;ma omurgas&#x0131; hizmetleri korunur ve kapat&#x0131;lamaz." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,3,0,0"/>
  </StackPanel>
  <WrapPanel x:Name="sv_Tabs" Grid.Row="1" Margin="0,0,0,8">
    <RadioButton x:Name="sv_Tab_Off" Content="&#x00D6;nerilen: kapat" Tag="Off" GroupName="sv_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="sv_Tab_Man" Content="El ile yap" Tag="Man" GroupName="sv_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sv_Tab_Org" Content="&#x015E;irket i&#x00E7;in" Tag="Org" GroupName="sv_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sv_Tab_Rev" Content="G&#x00F6;zden ge&#x00E7;ir" Tag="Rev" GroupName="sv_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sv_Tab_Keep" Content="Korunan" Tag="Keep" GroupName="sv_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sv_Tab_Run" Content="&#x00C7;al&#x0131;&#x015F;an" Tag="Run" GroupName="sv_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sv_Tab_All" Content="T&#x00FC;m&#x00FC;" Tag="All" GroupName="sv_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="sv_Bar" Grid.Row="2" Margin="0,0,0,4">
<Button x:Name="sv_Refresh" Content="Yenile" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" />
<Button x:Name="sv_PSafe" Content="G&#x00FC;venli se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="sv_PRec" Content="&#x00D6;nerilenleri se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="sv_PTier" Content="Bu bilgisayara g&#x00F6;re se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="sv_POrg" Content="&#x015E;irket &#x00F6;nerisini se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="sv_PNone" Content="Se&#x00E7;imi temizle" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="sv_Preview" Content="&#x00D6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" />
<Button x:Name="sv_Off" Content="Devre d&#x0131;&#x015F;&#x0131; b&#x0131;rak" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" />
<Button x:Name="sv_Man" Content="El ile yap" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" />
<Button x:Name="sv_Auto" Content="Otomatik yap" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" />
  </WrapPanel>
  <StackPanel Grid.Row="3">
<DockPanel Margin="0,0,0,8" LastChildFill="True"><TextBlock x:Name="sv_Count" DockPanel.Dock="Right" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="10,0,0,0"/><TextBlock Text="Ara" DockPanel.Dock="Left" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBox x:Name="sv_Filter"/></DockPanel>
  </StackPanel>
  <Grid Grid.Row="4">
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="300"/></Grid.ColumnDefinitions>
    <Border x:Name="sv_ListCard" Grid.Column="0" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="sv_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="sv_List"/>
      </ScrollViewer>
    </Border>
    <Border Grid.Column="1" Style="{DynamicResource Card}" Margin="10,0,0,0" Padding="14">
<ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel>
  <TextBlock Text="AYRINTI" Style="{DynamicResource TxtCardTitle}"/>
  <TextBlock x:Name="sv_DName" Text="Bir hizmet se&#x00E7;in" Style="{DynamicResource TxtH2}" TextWrapping="Wrap" Margin="0,8,0,0"/>
  <TextBlock x:Name="sv_DSub" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,2,0,8"/>
  <TextBlock x:Name="sv_DRec" Text="" FontWeight="SemiBold" FontSize="12.5" TextWrapping="Wrap" Margin="0,0,0,8"/>
  <TextBlock Text="Ne i&#x015F;e yarar" Style="{DynamicResource TxtDim}" FontSize="11"/>
  <TextBlock x:Name="sv_DWhat" Text="" Style="{DynamicResource TxtBody}" TextWrapping="Wrap" Margin="0,2,0,8"/>
  <TextBlock Text="Kapat&#x0131;rsam ne olur" Style="{DynamicResource TxtDim}" FontSize="11"/>
  <TextBlock x:Name="sv_DIfOff" Text="" Style="{DynamicResource TxtBody}" TextWrapping="Wrap" Margin="0,2,0,8"/>
  <TextBlock x:Name="sv_DNote" Text="" Foreground="{DynamicResource BrWarn}" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>
  <TextBlock Text="Dosya yolu / hesap" Style="{DynamicResource TxtDim}" FontSize="11"/>
  <TextBlock x:Name="sv_DPath" Text="" Style="{DynamicResource TxtMono}" TextWrapping="Wrap" Margin="0,2,0,10"/>
  <WrapPanel>
    <Button x:Name="sv_DStart" Content="Ba&#x015F;lat" Style="{DynamicResource BtnMini}" Margin="0,0,6,6"/>
    <Button x:Name="sv_DStop" Content="Durdur" Style="{DynamicResource BtnMini}" Margin="0,0,6,6"/>
    <Button x:Name="sv_DRestart" Content="Yeniden ba&#x015F;lat" Style="{DynamicResource BtnMini}" Margin="0,0,6,6"/>
  </WrapPanel>
</StackPanel></ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="sv_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

$script:Page_apps = @'
