  </WrapPanel>
  <StackPanel Grid.Row="3">
<DockPanel Margin="0,0,0,8" LastChildFill="True"><TextBlock Text="Ara" DockPanel.Dock="Left" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBox x:Name="ap_Filter"/></DockPanel>
