  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="sc_Title" Text="G&#x00FC;venlik" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="sc_Desc" Text="Tam g&#x00FC;venlik denetimi, sertle&#x015F;tirme ayarlar&#x0131; ve Defender / g&#x00FC;venlik duvar&#x0131; i&#x015F;lemleri. Defender, G&#x00FC;venlik Duvar&#x0131; ve UAC bu ara&#x00E7;la asla kapat&#x0131;lmaz." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,3,0,0"/>
  </StackPanel>
  <WrapPanel x:Name="sc_Tabs" Grid.Row="1" Margin="0,0,0,8">
    <RadioButton x:Name="sc_Tab_audit" Content="Denetim" Tag="audit" GroupName="sc_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="sc_Tab_fix" Content="D&#x00FC;zeltme plan&#x0131;" Tag="fix" GroupName="sc_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sc_Tab_harden" Content="Sertle&#x015F;tirme" Tag="harden" GroupName="sc_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sc_Tab_quick" Content="H&#x0131;zl&#x0131; i&#x015F;lemler" Tag="quick" GroupName="sc_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="sc_Bar" Grid.Row="2" Margin="0,0,0,4">
<Button x:Name="sc_Scan" Content="Tam denetimi &#x00E7;al&#x0131;&#x015F;t&#x0131;r" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" />
<Button x:Name="sc_P1" Content="&#x00D6;nerilenleri se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_P0" Content="Se&#x00E7;imi temizle" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_Preview" Content="&#x00D6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_Apply" Content="Se&#x00E7;ilenleri uygula" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_FixAll" Content="Hepsini d&#x00FC;zelt" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_FixPick" Content="Otomatik olanlar&#x0131; se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_FixNone" Content="Se&#x00E7;imi temizle" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_FixPrev" Content="&#x00D6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="sc_FixRun" Content="Se&#x00E7;ilenleri d&#x00FC;zelt" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
  </WrapPanel>
  <StackPanel Grid.Row="3">
<Border x:Name="sc_Card" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="14">
<StackPanel Orientation="Horizontal">
  <Grid Width="74" Height="74" Margin="0,0,16,0">
    <Ellipse Width="66" Height="66" Stroke="{DynamicResource BrLine}" StrokeThickness="7"/>
    <Ellipse x:Name="sc_GScore" Width="66" Height="66" Stroke="{DynamicResource BrGood}" StrokeThickness="7" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
      <Ellipse.RenderTransform><RotateTransform Angle="-90"/></Ellipse.RenderTransform>
    </Ellipse>
    <TextBlock x:Name="sc_VScore" Text="--" FontSize="22" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
  </Grid>
  <StackPanel VerticalAlignment="Center">
    <TextBlock x:Name="sc_Sum" Text="Hen&#x00FC;z denetim yap&#x0131;lmad&#x0131;." Style="{DynamicResource TxtH2}"/>
    <TextBlock x:Name="sc_Sub" Text="Tam denetim hesaplar, parolalar, a&#x011F;, disk &#x015F;ifreleme, g&#x00FC;ncellemeler ve kal&#x0131;c&#x0131;l&#x0131;k noktalar&#x0131;n&#x0131; salt okunur inceler." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" MaxWidth="560" Margin="0,3,0,0"/>
  </StackPanel>
</StackPanel>
</Border>
  </StackPanel>
  <Grid Grid.Row="4">
    <Border x:Name="sc_ListCard" Grid.Column="0" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="sc_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="sc_List"/>
      </ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="sc_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

$script:Page_updates = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="up_Title" Text="G&#x00FC;ncellemeler" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="up_Desc" Text="Windows g&#x00FC;ncellemelerini ve programlar&#x0131; g&#x00FC;ncel tutun. Windows Update bu ara&#x00E7;la kapat&#x0131;lmaz; yaln&#x0131;zca denetlenir ve iste&#x011F;e g&#x00F6;re kurulur." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,3,0,0"/>
  </StackPanel>
  <WrapPanel x:Name="up_Tabs" Grid.Row="1" Margin="0,0,0,8">
    <RadioButton x:Name="up_Tab_wu" Content="Windows Update" Tag="wu" GroupName="up_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="up_Tab_winget" Content="Programlar (winget)" Tag="winget" GroupName="up_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="up_Tab_ctl" Content="Denetim" Tag="ctl" GroupName="up_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="up_Tab_inst" Content="Kurulu g&#x00FC;ncellemeler" Tag="inst" GroupName="up_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="up_Tab_hist" Content="G&#x00FC;ncelleme ge&#x00E7;mi&#x015F;i" Tag="hist" GroupName="up_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="up_Bar" Grid.Row="2" Margin="0,0,0,4">
<Button x:Name="up_Check" Content="Denetle" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" />
<Button x:Name="up_SelAll" Content="T&#x00FC;m&#x00FC;n&#x00FC; se&#x00E7;" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="up_SelNone" Content="Se&#x00E7;imi temizle" Style="{DynamicResource BtnMini}" Margin="0,0,8,6" />
<Button x:Name="up_Install" Content="Se&#x00E7;ilenleri kur" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" />
<Button x:Name="up_Pin" Content="Se&#x00E7;ilenleri sabitle (g&#x00FC;ncelleme)" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_PinList" Content="Sabitlenenler" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_Unpin" Content="Sabitlemeyi kald&#x0131;r" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_Pause" Content="G&#x00FC;ncellemeleri duraklat..." Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_Resume" Content="Duraklatmay&#x0131; kald&#x0131;r" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_Defer" Content="&#x00D6;zellik g&#x00FC;ncellemelerini ertele..." Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_DeferOff" Content="Ertelemeyi kald&#x0131;r" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_DrvToggle" Content="S&#x00FC;r&#x00FC;c&#x00FC;leri Windows Update&#x2019;ten alma" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="up_Uninstall" Content="Se&#x00E7;ilenleri kald&#x0131;r" Style="{DynamicResource BtnDanger}" Margin="0,0,8,6" Visibility="Collapsed" />
  </WrapPanel>
  <StackPanel Grid.Row="3">
<Border x:Name="up_Banner" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="12" Visibility="Collapsed">
<DockPanel LastChildFill="True">
  <Button x:Name="up_Reboot" DockPanel.Dock="Right" Content="Yeniden ba&#x015F;lat" Style="{DynamicResource BtnDanger}" VerticalAlignment="Center" Margin="12,0,0,0"/>
  <TextBlock x:Name="up_BannerText" Text="" Style="{DynamicResource TxtBody}" TextWrapping="Wrap" VerticalAlignment="Center"/>
</DockPanel>
</Border>
  </StackPanel>
  <Grid Grid.Row="4">
    <Border x:Name="up_ListCard" Grid.Column="0" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="up_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="up_List"/>
      </ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="up_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

$script:Page_network = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="nw_Title" Text="A&#x011F; Ara&#x00E7;lar&#x0131;" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="nw_Desc" Text="A&#x011F;daki cihazlar&#x0131; bulun, t&#x00FC;rlerini g&#x00F6;r&#x00FC;n, tan&#x0131;mad&#x0131;klar&#x0131;n&#x0131;z&#x0131; engelleyin; a&#x011F; koruman&#x0131;z&#x0131; denetleyin; VPN, &#x015F;ifreli DNS ve kill-switch ile gezinmenizi koruyun; ba&#x011F;lant&#x0131;lar&#x0131;, a&#x00E7;&#x0131;k portlar&#x0131;, DNS ve internet h&#x0131;z&#x0131;n&#x0131; inceleyin." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,3,0,0"/>
  </StackPanel>
  <WrapPanel x:Name="nw_Tabs" Grid.Row="1" Margin="0,0,0,8">
    <RadioButton x:Name="nw_Tab_over" Content="Genel bak&#x0131;&#x015F;" Tag="over" GroupName="nw_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="nw_Tab_dev" Content="Cihazlar" Tag="dev" GroupName="nw_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="nw_Tab_prot" Content="Koruma" Tag="prot" GroupName="nw_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="nw_Tab_vpn" Content="VPN ve gizlilik" Tag="vpn" GroupName="nw_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="nw_Tab_dns" Content="DNS" Tag="dns" GroupName="nw_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="nw_Tab_ping" Content="Ping ve yol izleme" Tag="ping" GroupName="nw_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="nw_Tab_speed" Content="H&#x0131;z testi" Tag="speed" GroupName="nw_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="nw_Tab_fix" Content="Onar&#x0131;m ve engelleme" Tag="fix" GroupName="nw_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="nw_Bar" Grid.Row="2" Margin="0,0,0,4">
<Button x:Name="nw_Refresh" Content="Yenile" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" />
<Button x:Name="nw_ScanQuick" Content="A&#x011F;&#x0131; tara" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_ScanDeep" Content="Ayr&#x0131;nt&#x0131;l&#x0131; tara" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DevTrust" Content="Tan&#x0131;d&#x0131;k i&#x015F;aretle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DevTrustAll" Content="Hepsini tan&#x0131;d&#x0131;k say" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DevName" Content="Adland&#x0131;r" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DevBlock" Content="Engelle" Style="{DynamicResource BtnDanger}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DevUnblock" Content="Engeli kald&#x0131;r" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DevKick" Content="A&#x011F;dan &#x00E7;&#x0131;kar" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DevPorts" Content="Portlara bak" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_ProtScan" Content="Korumay&#x0131; denetle" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_ProtAll" Content="Otomatik d&#x00FC;zeltmeleri uygula" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_ProtPick" Content="Se&#x00E7;ilenleri d&#x00FC;zelt" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_PubWifi" Content="Genel Wi-Fi kalkan&#x0131;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_PubPrev" Content="&#x00D6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_VpnRefresh" Content="Yenile" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_VpnWgImport" Content="WireGuard i&#x00E7;e aktar" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_VpnIke" Content="Windows VPN ekle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_KsOn" Content="Kill-switch a&#x00E7;" Style="{DynamicResource BtnDanger}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_KsOff" Content="Kill-switch kapat" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_VpnLeak" Content="S&#x0131;z&#x0131;nt&#x0131; s&#x0131;namas&#x0131;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DnsBench" Content="DNS h&#x0131;zlar&#x0131;n&#x0131; &#x00F6;l&#x00E7;" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DnsApply" Content="Se&#x00E7;ili DNS&#x2019;i uygula" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_DnsAuto" Content="Otomati&#x011F;e d&#x00F6;nd&#x00FC;r" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_SpeedGo" Content="H&#x0131;z testini ba&#x015F;lat" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_FlushDns" Content="DNS &#x00F6;nbelle&#x011F;ini temizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="nw_NetReset" Content="A&#x011F; y&#x0131;&#x011F;&#x0131;n&#x0131;n&#x0131; s&#x0131;f&#x0131;rla" Style="{DynamicResource BtnDanger}" Margin="0,0,8,6" Visibility="Collapsed" />
  </WrapPanel>
  <StackPanel Grid.Row="3">
<Border x:Name="nw_DevBox" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="12" Visibility="Collapsed">
<WrapPanel>
  <TextBlock Text="Ara" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,8,6"/>
  <TextBox x:Name="nw_DevFilter" Width="220" Margin="0,0,14,6"/>
  <CheckBox x:Name="nw_DevNew" Content="Yaln&#x0131;zca tan&#x0131;d&#x0131;k olmayanlar" Style="{DynamicResource Toggle}" Margin="0,0,14,6" VerticalAlignment="Center"/>
  <TextBlock x:Name="nw_DevSum" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,0,6" TextWrapping="Wrap"/>
</WrapPanel>
</Border>
<Border x:Name="nw_ProtBox" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="12" Visibility="Collapsed">
<StackPanel>
  <TextBlock Text="Bu sekme bu bilgisayar&#x0131;n a&#x011F; taraf&#x0131;n&#x0131; denetler: g&#x00FC;venlik duvar&#x0131;, payla&#x015F;&#x0131;mlar, Wi-Fi &#x015F;ifrelemesi, DNS ve a&#x011F; ge&#x00E7;idi b&#x00FC;t&#x00FC;nl&#x00FC;&#x011F;&#x00FC;. D&#x00FC;zeltmeler &#x00F6;nce &#x00F6;nizlenir, geri al&#x0131;nabilir; yeniden ba&#x015F;latma isteyenler kendili&#x011F;inden uygulanmaz." Style="{DynamicResource TxtDim}" TextWrapping="Wrap"/>
  <CheckBox x:Name="nw_Watch" Content="A&#x011F; izleme: 5 dakikada bir sessiz tarama yap; yeni cihaz ve a&#x011F; ge&#x00E7;idi de&#x011F;i&#x015F;ikli&#x011F;ini bildir" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
</StackPanel>
</Border>
<Border x:Name="nw_VpnBox" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="12" Visibility="Collapsed">
<StackPanel>
  <TextBlock Text="VPN trafi&#x011F;inizi sa&#x011F;lay&#x0131;c&#x0131;n&#x0131;za ta&#x015F;&#x0131;r: internet sa&#x011F;lay&#x0131;c&#x0131;n&#x0131;z ve ortak Wi-Fi sahibi neye girdi&#x011F;inizi g&#x00F6;remez, ama VPN sa&#x011F;lay&#x0131;c&#x0131;s&#x0131; g&#x00F6;r&#x00FC;r. Kill-switch, VPN koparsa trafi&#x011F;in korumas&#x0131;z yoldan &#x00E7;&#x0131;kmas&#x0131;n&#x0131; Windows G&#x00FC;venlik Duvar&#x0131; ile engeller; kurulduktan sonra otomatik do&#x011F;rulan&#x0131;r ve her zaman kapat&#x0131;labilir." Style="{DynamicResource TxtDim}" TextWrapping="Wrap"/>
  <CheckBox x:Name="nw_KsLan" Content="Kill-switch a&#x00E7;&#x0131;kken yerel a&#x011F;a (yaz&#x0131;c&#x0131;, NAS, y&#x00F6;nlendirici) izin ver" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
</StackPanel>
</Border>
<Border x:Name="nw_PingBox" Style="{DynamicResource Card}" Margin="0,0,0,10" Padding="12" Visibility="Collapsed">
<WrapPanel>
  <TextBlock Text="Adres" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,8,6"/>
  <TextBox x:Name="nw_Host" Width="260" Text="1.1.1.1" Margin="0,0,8,6"/>
  <Button x:Name="nw_PingGo" Content="Ping" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6"/>
  <Button x:Name="nw_TraceGo" Content="Yol izle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6"/>
</WrapPanel>
</Border>
  </StackPanel>
  <Grid Grid.Row="4">
    <Border x:Name="nw_ListCard" Grid.Column="0" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="nw_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="nw_List"/>
      </ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="nw_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

$script:Page_backup = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="bk_Title" Text="Yedek ve Kurtarma" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="bk_Desc" Text="Dosyalar&#x0131;n&#x0131;z&#x0131; yedekleyin, Geri D&#x00F6;n&#x00FC;&#x015F;&#x00FC;m Kutusu ve &#x00D6;nceki S&#x00FC;r&#x00FC;mler&#x2019;den silinen dosyalar&#x0131; geri al&#x0131;n, geri y&#x00FC;kleme noktalar&#x0131;n&#x0131; y&#x00F6;netin." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,3,0,0"/>
  </StackPanel>
  <WrapPanel x:Name="bk_Tabs" Grid.Row="1" Margin="0,0,0,8">
