    <RadioButton x:Name="bk_Tab_recycle" Content="Geri D&#x00F6;n&#x00FC;&#x015F;&#x00FC;m Kutusu" Tag="recycle" GroupName="bk_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="bk_Tab_shadow" Content="&#x00D6;nceki s&#x00FC;r&#x00FC;mler" Tag="shadow" GroupName="bk_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="bk_Tab_points" Content="Geri y&#x00FC;kleme noktalar&#x0131;" Tag="points" GroupName="bk_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="bk_Tab_recover" Content="Silinmi&#x015F; dosya kurtarma" Tag="recover" GroupName="bk_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="bk_Tab_bl" Content="BitLocker" Tag="bl" GroupName="bk_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="bk_Tab_kit" Content="Ta&#x015F;&#x0131;ma paketi" Tag="kit" GroupName="bk_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="bk_Bar" Grid.Row="2" Margin="0,0,0,4">
