<Button x:Name="bk_Run" Content="Yedeklemeyi ba&#x015F;lat" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" />
<Button x:Name="bk_Restore" Content="Yedekten geri y&#x00FC;kle..." Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" />
<Button x:Name="bk_RbRestore" Content="Se&#x00E7;ilenleri geri y&#x00FC;kle" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="bk_RbRefresh" Content="Yenile" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="bk_RpNew" Content="Geri y&#x00FC;kleme noktas&#x0131; olu&#x015F;tur" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="bk_RpOpen" Content="Sistem Geri Y&#x00FC;kleme&#x2019;yi a&#x00E7;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="bk_PhotoGet" Content="PhotoRec&#x2019;i kur (winget)" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="bk_PhotoRun" Content="PhotoRec&#x2019;i ba&#x015F;lat" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed" />
<CheckBox x:Name="bk_KitDrv" Content="S&#x00FC;r&#x00FC;c&#x00FC;leri de ekle" Margin="0,0,14,6" VerticalAlignment="Center" Visibility="Collapsed" />
<CheckBox x:Name="bk_KitWifi" Content="Wi-Fi profillerini de ekle" Margin="0,0,14,6" VerticalAlignment="Center" Visibility="Collapsed" />
