<Button x:Name="bk_BlRefresh" Content="Yenile" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="bk_BlWeb" Content="Microsoft hesab&#x0131;mdaki anahtarlar" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
<Button x:Name="bk_ResticGet" Content="restic&#x2019;i kur (winget)" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed" />
