    <RadioButton x:Name="bk_ModeDate" Content="Tarihli klas&#x00F6;r (her yedek ayr&#x0131;)" GroupName="bkmode" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="bk_ModeRestic" Content="&#x015E;ifreli ve s&#x00FC;r&#x00FC;ml&#x00FC; (restic)" GroupName="bkmode" Style="{DynamicResource Chip}"/>
