$script:Page_settings = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="st_Title" Text="Ayarlar" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="st_Desc" Text="Davran&#x0131;&#x015F;, g&#x00F6;r&#x00FC;n&#x00FC;m, iste&#x011F;e ba&#x011F;l&#x0131; &#x00F6;zellikler, internet istekleri, otomatik bak&#x0131;m ve kurulum se&#x00E7;enekleri." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,3,0,0"/>
  </StackPanel>
  <ScrollViewer Grid.Row="4" Grid.RowSpan="2" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
<StackPanel Margin="0,0,10,12">
  <Border Style="{DynamicResource Card}" Padding="16" Margin="0,0,0,10">
    <StackPanel>
      <TextBlock Text="Dil / Language" Style="{DynamicResource TxtCardTitle}"/>
