      <CheckBox x:Name="st_TrayMin" Content="Simge durumuna k&#x00FC;&#x00E7;&#x00FC;lt&#x00FC;nce de tepsiye insin (g&#x00F6;rev &#x00E7;ubu&#x011F;unda yer kaplamaz)" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <TextBlock Text="Tamamen kapatmak i&#x00E7;in sa&#x011F; &#x00FC;stteki g&#x00FC;&#x00E7; d&#x00FC;&#x011F;mesi, Ctrl + Q ya da tepsi simgesinin men&#x00FC;s&#x00FC;ndeki Tamamen kapat kullan&#x0131;l&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="40,3,0,0"/>
      <CheckBox x:Name="st_Notify" Content="Bildirim g&#x00F6;ster (bak&#x0131;m tamamland&#x0131;, sistem yo&#x011F;un, g&#x00FC;ncelleme var)" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <CheckBox x:Name="st_Rp" Content="De&#x011F;i&#x015F;iklik yapmadan &#x00F6;nce geri y&#x00FC;kleme noktas&#x0131; olu&#x015F;tur" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <CheckBox x:Name="st_Confirm" Content="Uzman kipinde riskli i&#x015F;lemlerden &#x00F6;nce onay iste" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <WrapPanel Margin="0,12,0,0">
        <TextBlock Text="Kullan&#x0131;m t&#x00FC;r&#x00FC;" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,10,0"/>
        <TextBlock x:Name="st_UseCaseText" Text="" Style="{DynamicResource TxtBody}" VerticalAlignment="Center" Margin="0,0,12,0"/>
        <Button x:Name="st_UseCase" Content="De&#x011F;i&#x015F;tir..." Style="{DynamicResource BtnGhost}"/>
      </WrapPanel>
      <WrapPanel Margin="0,12,0,0">
        <TextBlock Text="Canl&#x0131; izleme aral&#x0131;&#x011F;&#x0131;" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,10,0"/>
        <RadioButton x:Name="st_Mon1" Content="1 sn" Tag="1" GroupName="stmon" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Mon2" Content="2 sn" Tag="2" GroupName="stmon" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Mon5" Content="5 sn" Tag="5" GroupName="stmon" Style="{DynamicResource Chip}"/>
      </WrapPanel>
    </StackPanel>
  </Border>
  <Border Style="{DynamicResource Card}" Padding="16" Margin="0,0,0,10">
    <StackPanel>
      <TextBlock Text="G&#x00D6;R&#x00DC;N&#x00DC;M" Style="{DynamicResource TxtCardTitle}"/>
      <TextBlock Text="Renk temas&#x0131;, tasar&#x0131;m (men&#x00FC; ve ana ekran bi&#x00E7;imi) ve yerle&#x015F;im (yo&#x011F;unluk) ayr&#x0131; ayr&#x0131; se&#x00E7;ilir; istedi&#x011F;iniz birle&#x015F;imi kurabilirsiniz. Haz&#x0131;r g&#x00F6;r&#x00FC;n&#x00FC;mler hepsini birlikte uygular. Hi&#x00E7;biri sistem ayar&#x0131;na dokunmaz." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Haz&#x0131;r g&#x00F6;r&#x00FC;n&#x00FC;m" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_LookSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock Text="Renk ve bi&#x00E7;im" Style="{DynamicResource TxtDim}" FontWeight="SemiBold" Margin="0,18,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Tema" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_ThemeSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboTheme}"/>
      </Grid>
      <TextBlock x:Name="st_ThDesc" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Tasar&#x0131;m" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_DesignSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock x:Name="st_DsDesc" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
