        <ComboBox x:Name="st_LayoutSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock x:Name="st_LyDesc" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <TextBlock Text="Ana ekran" Style="{DynamicResource TxtDim}" FontWeight="SemiBold" Margin="0,18,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Ana ekran bi&#x00E7;imi" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_HomeSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock x:Name="st_HomeDesc" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <WrapPanel Margin="0,8,0,0">
        <Button x:Name="st_BoardEdit" Content="Ana ekran&#x0131; d&#x00FC;zenle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6"/>
        <Button x:Name="st_BoardReset" Content="Ana ekran d&#x00FC;zenini s&#x0131;f&#x0131;rla" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6"/>
      </WrapPanel>
      <TextBlock Text="Saydaml&#x0131;k ve &#x00F6;l&#x00E7;ek" Style="{DynamicResource TxtDim}" FontWeight="SemiBold" Margin="0,18,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Saydaml&#x0131;k efekti" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_BackdropSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Y&#x00FC;zey opakl&#x0131;&#x011F;&#x0131;" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_OpacitySel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock x:Name="st_BdDesc" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <TextBlock Text="Efekti Windows &#x00E7;izer; Multimizer yaln&#x0131;zca y&#x00FC;zeyleri yar&#x0131; saydam boyar. Opakl&#x0131;k d&#x00FC;&#x015F;t&#x00FC;k&#x00E7;e arka plan daha &#x00E7;ok g&#x00F6;r&#x00FC;n&#x00FC;r; okunabilirlik i&#x00E7;in %70 - %90 &#x00F6;nerilir. G&#x00FC;venli ba&#x015F;lang&#x0131;&#x00E7;ta, g&#x00FC;venli &#x00E7;izim kipinde, y&#x00FC;ksek kar&#x015F;&#x0131;tl&#x0131;kta ve uzak masa&#x00FC;st&#x00FC;nde saydaml&#x0131;k kapal&#x0131; kal&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Yak&#x0131;nla&#x015F;t&#x0131;rma" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_ZoomSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock Text="Ctrl + fare tekerle&#x011F;i ya da Ctrl + (+ / -) ile de de&#x011F;i&#x015F;ir; Ctrl + 0 y&#x00FC;zde y&#x00FC;ze d&#x00F6;nd&#x00FC;r&#x00FC;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Dokunma hedefleri" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_TouchSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock Text="Otomatik: dokunmatik ekran varsa B&#x00FC;y&#x00FC;k. B&#x00FC;y&#x00FC;k: d&#x00FC;&#x011F;meler, sekmeler ve onay kutular&#x0131; en az 40 piksel olur (Kompakt yerle&#x015F;imde 32)." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <CheckBox x:Name="st_DsAdv" Content="Tasar&#x0131;m ayr&#x0131;nt&#x0131;lar&#x0131;n&#x0131; tek tek se&#x00E7;" Style="{DynamicResource Toggle}" Margin="0,16,0,0"/>
      <StackPanel x:Name="st_DsAdvPanel" Visibility="Collapsed">
      <TextBlock Text="Se&#x00E7;medi&#x011F;iniz ayr&#x0131;nt&#x0131; tasar&#x0131;m&#x0131;n kendi de&#x011F;erini kullan&#x0131;r. Tasar&#x0131;m&#x0131; de&#x011F;i&#x015F;tirmek ayr&#x0131;nt&#x0131;lar&#x0131; tasar&#x0131;m&#x0131;n de&#x011F;erlerine d&#x00F6;nd&#x00FC;r&#x00FC;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Men&#x00FC; bi&#x00E7;imi" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_DsNavSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="K&#x00F6;&#x015F;eler" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_DsRadiusSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Yaz&#x0131; tipi" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_DsFontSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <Grid Margin="0,10,0,0">
