        </Grid.ColumnDefinitions>
        <TextBlock Text="Grafik bi&#x00E7;imi" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_DsGraphSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="Par&#x00E7;a g&#x00F6;r&#x00FC;n&#x00FC;m&#x00FC;" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_DsSkinSel" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
        <Button x:Name="st_DsReset" Content="Tasar&#x0131;m&#x0131;n kendi de&#x011F;erlerine d&#x00F6;n" Style="{DynamicResource BtnGhost}" HorizontalAlignment="Left" Margin="0,10,0,0"/>
      </StackPanel>
      <TextBlock Text="Hareket ve kayd&#x0131;rma" Style="{DynamicResource TxtDim}" FontWeight="SemiBold" Margin="0,18,0,0"/>
      <CheckBox x:Name="st_ReduceMotion" Content="Animasyonlar&#x0131; azalt" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <TextBlock Text="Windows&#x2019;ta animasyonlar kapal&#x0131;ysa ya da bilgisayarda 4 GB&#x2019;tan az bellek varsa animasyonlar bu se&#x00E7;enek kapal&#x0131; olsa da kendili&#x011F;inden k&#x0131;s&#x0131;l&#x0131;r. Sade yerle&#x015F;imde her zaman k&#x0131;s&#x0131;l&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="40,3,0,0"/>
      <CheckBox x:Name="st_Smooth" Content="Yumu&#x015F;ak kayd&#x0131;rma (tekerlek ve klavyeyle)" Style="{DynamicResource Toggle}" Margin="0,10,0,0"/>
      <CheckBox x:Name="st_ToTop" Content="A&#x015F;a&#x011F;&#x0131; inince ba&#x015F;a d&#x00F6;n d&#x00FC;&#x011F;mesini g&#x00F6;ster" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <CheckBox x:Name="st_FullDesc" Content="A&#x00E7;&#x0131;klamalar&#x0131; tam g&#x00F6;ster (kapal&#x0131;yken tek sat&#x0131;r g&#x00F6;r&#x00FC;n&#x00FC;r; tamam&#x0131; &#x00FC;zerine gelince okunur)" Style="{DynamicResource Toggle}" Margin="0,8,0,0" ToolTip="De&#x011F;i&#x015F;iklik, sayfalar yeniden a&#x00E7;&#x0131;ld&#x0131;&#x011F;&#x0131;nda (uygulama yeniden ba&#x015F;lat&#x0131;l&#x0131;nca) t&#x00FC;m&#x00FC;yle ge&#x00E7;erli olur."/>
      <CheckBox x:Name="st_FocusRing" Content="Klavyeyle gezerken se&#x00E7;ili &#x00F6;&#x011F;enin &#x00E7;evresine &#x00E7;er&#x00E7;eve &#x00E7;iz" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <TextBlock Text="Kararl&#x0131;l&#x0131;k" Style="{DynamicResource TxtDim}" FontWeight="SemiBold" Margin="0,18,0,0"/>
      <CheckBox x:Name="st_SafeRender" Content="G&#x00FC;venli &#x00E7;izim (yaln&#x0131;zca yaz&#x0131;l&#x0131;mla &#x00E7;iz)" Style="{DynamicResource Toggle}" Margin="0,8,0,0"/>
      <TextBlock Text="Pencere ekran kart&#x0131;yla de&#x011F;il i&#x015F;lemciyle &#x00E7;izilir; ekran kart&#x0131; ve s&#x0131;cakl&#x0131;k izleme ile saydaml&#x0131;k kapan&#x0131;r. Ekran kart&#x0131; s&#x00FC;r&#x00FC;c&#x00FC;s&#x00FC;nden kaynaklanan kapanmalara kar&#x015F;&#x0131;d&#x0131;r. Uygulama art arda iki kez beklenmedik bi&#x00E7;imde kapan&#x0131;rsa bu se&#x00E7;enek kendili&#x011F;inden a&#x00E7;&#x0131;l&#x0131;r; sorun ge&#x00E7;tiyse buradan kapat&#x0131;n. Bir sonraki a&#x00E7;&#x0131;l&#x0131;&#x015F;ta etkin olur." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="40,3,0,0"/>
      <CheckBox x:Name="st_MonGpu" Content="Ekran kart&#x0131; y&#x00FC;k&#x00FC;n&#x00FC; izle" Style="{DynamicResource Toggle}" Margin="0,10,0,0"/>
      <TextBlock Text="Canl&#x0131; izlemede ekran kart&#x0131; (3B) y&#x00FC;k&#x00FC; okunur ve g&#x00F6;stergelerde g&#x00F6;r&#x00FC;n&#x00FC;r. Kapal&#x0131;yken bu de&#x011F;er okunmaz; i&#x015F;lemci, bellek, disk ve a&#x011F; izlenmeye devam eder." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="40,3,0,0"/>
      <CheckBox x:Name="st_DebugLog" Content="Ayr&#x0131;nt&#x0131;l&#x0131; hata g&#x00FC;nl&#x00FC;&#x011F;&#x00FC; (yutulan hatalar da kaydedilsin)" Style="{DynamicResource Toggle}" Margin="0,10,0,0"/>
      <TextBlock Text="Kapal&#x0131;yken hi&#x00E7;bir &#x015F;ey yaz&#x0131;lmaz. A&#x00E7;&#x0131;kken uygulaman&#x0131;n sessizce ge&#x00E7;i&#x015F;tirdi&#x011F;i hatalar da Kay&#x0131;tlar klas&#x00F6;r&#x00FC;ndeki ayrinti-G&#x00DC;N.txt dosyas&#x0131;na (hata t&#x00FC;r&#x00FC;, ileti, sat&#x0131;r, i&#x015F;lev) yaz&#x0131;l&#x0131;r; sorun ararken i&#x015F;e yarar. Ayn&#x0131; hata dakikada bir kez yaz&#x0131;l&#x0131;r, dosya g&#x00FC;nde 2 MB&#x2019;ta kesilir. Baslat.bat -DebugLog ile a&#x00E7;&#x0131;l&#x0131;rsan&#x0131;z oturum boyunca a&#x00E7;&#x0131;k kal&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="40,3,0,0"/>
    </StackPanel>
  </Border>
  <Border Style="{DynamicResource Card}" Padding="16" Margin="0,0,0,10">
    <StackPanel>
      <TextBlock Text="OTOMAT&#x0130;K BAKIM" Style="{DynamicResource TxtCardTitle}"/>
      <TextBlock Text="Haftal&#x0131;k bak&#x0131;m, siz oturum a&#x00E7;&#x0131;kken sessizce &#x00E7;al&#x0131;&#x015F;&#x0131;r. Yaln&#x0131;zca a&#x015F;a&#x011F;&#x0131;da i&#x015F;aretli temizlik ad&#x0131;mlar&#x0131; uygulan&#x0131;r; geri al&#x0131;namaz olanlar yaln&#x0131;zca ge&#x00E7;ici dosyalard&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <CheckBox x:Name="st_MaintOn" Content="Haftal&#x0131;k bak&#x0131;m&#x0131; zamanla" Style="{DynamicResource Toggle}" Margin="0,10,0,0"/>
      <WrapPanel Margin="0,10,0,0">
        <TextBlock Text="G&#x00FC;n" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,8,0"/>
        <RadioButton x:Name="st_Day_Monday" Content="Pzt" Tag="Monday" GroupName="stday" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Day_Tuesday" Content="Sal" Tag="Tuesday" GroupName="stday" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Day_Wednesday" Content="&#x00C7;ar" Tag="Wednesday" GroupName="stday" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Day_Thursday" Content="Per" Tag="Thursday" GroupName="stday" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Day_Friday" Content="Cum" Tag="Friday" GroupName="stday" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Day_Saturday" Content="Cmt" Tag="Saturday" GroupName="stday" Style="{DynamicResource Chip}"/>
        <RadioButton x:Name="st_Day_Sunday" Content="Paz" Tag="Sunday" GroupName="stday" Style="{DynamicResource Chip}"/>
        <Rectangle Width="14"/>
