        <TextBox x:Name="st_MaintTime" Width="70"/>
      </WrapPanel>
      <TextBlock Text="Bak&#x0131;m ad&#x0131;mlar&#x0131;" Style="{DynamicResource TxtDim}" Margin="0,12,0,4"/>
      <StackPanel x:Name="st_MaintList"/>
      <CheckBox x:Name="st_RepOn" Content="Her Pazartesi 08:30&#x2019;da sistem raporu olu&#x015F;tur (Raporlar klas&#x00F6;r&#x00FC;ne)" Style="{DynamicResource Toggle}" Margin="0,14,0,0"/>
      <CheckBox x:Name="st_BkOn" Content="Her g&#x00FC;n dosya yede&#x011F;ini zamanla (Yedek sayfas&#x0131;ndaki kaynak ve hedefle)" Style="{DynamicResource Toggle}" Margin="0,14,0,0"/>
      <WrapPanel Margin="0,10,0,0">
        <TextBlock Text="Yedek saati (SS:DD)" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,8,0"/>
        <TextBox x:Name="st_BkTime" Width="70"/>
      </WrapPanel>
      <Button x:Name="st_Sched" Content="Zamanlamay&#x0131; kaydet ve uygula" Style="{DynamicResource BtnPrimary}" HorizontalAlignment="Left" Margin="0,14,0,0"/>
    </StackPanel>
  </Border>
  <Border Style="{DynamicResource Card}" Padding="16" Margin="0,0,0,10">
    <StackPanel>
      <TextBlock Text="&#x0130;STE&#x011E;E BA&#x011E;LI &#x00D6;ZELL&#x0130;KLER" Style="{DynamicResource TxtCardTitle}"/>
