      <StackPanel x:Name="st_OptList"/>
      <WrapPanel Margin="0,14,0,0">
        <TextBlock Text="G&#x00FC;venli silmede ge&#x00E7;i&#x015F; say&#x0131;s&#x0131;" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" Margin="0,0,10,0"/>
