        <Button x:Name="st_UpdPage" Content="S&#x00FC;r&#x00FC;m sayfas&#x0131;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
        <Button x:Name="st_UpdFolder" Content="&#x0130;ndirilenler klas&#x00F6;r&#x00FC;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
