      <TextBlock x:Name="st_UpdState" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,2,0,0"/>
      <Border Height="1" Background="{DynamicResource BrLine}" Margin="0,12,0,12"/>
      <TextBlock Text="Dosya b&#x00FC;t&#x00FC;nl&#x00FC;&#x011F;&#x00FC;" Style="{DynamicResource TxtBody}" FontWeight="SemiBold"/>
      <TextBlock Text="Eklenti ve veri dosyalar&#x0131;n&#x0131;n, bu s&#x00FC;r&#x00FC;mle birlikte derlenen SHA-256 &#x00F6;zetleriyle tutup tutmad&#x0131;&#x011F;&#x0131;na bakar. Yaln&#x0131;zca okur; hi&#x00E7;bir dosyay&#x0131; de&#x011F;i&#x015F;tirmez." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,4,0,0"/>
      <Button x:Name="st_IntCheck" Content="Dosya b&#x00FC;t&#x00FC;nl&#x00FC;&#x011F;&#x00FC;n&#x00FC; denetle" Style="{DynamicResource BtnGhost}" HorizontalAlignment="Left" Margin="0,8,0,6"/>
      <TextBlock x:Name="st_IntState" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,2,0,0"/>
    </StackPanel>
  </Border>
  <Border Style="{DynamicResource Card}" Padding="16" Margin="0,0,0,10">
    <StackPanel>
      <TextBlock Text="SIFIRLAMA" Style="{DynamicResource TxtCardTitle}"/>
      <TextBlock Text="&#x00DC;&#x00E7; kapsam vard&#x0131;r: yaln&#x0131;zca g&#x00F6;r&#x00FC;n&#x00FC;m, t&#x00FC;m uygulama tercihleri ya da her &#x015F;ey (Multimizer&#x2019;&#x0131;n Windows&#x2019;ta yapt&#x0131;&#x011F;&#x0131; geri al&#x0131;nabilir de&#x011F;i&#x015F;iklikler dahil). &#x0130;lk iki kapsamda Windows &#x00FC;zerinde yap&#x0131;lan de&#x011F;i&#x015F;iklikler, zamanlanm&#x0131;&#x015F; g&#x00F6;revler ve yedekleme ayarlar&#x0131; de&#x011F;i&#x015F;mez." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <Grid Margin="0,10,0,0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="170"/>
          <ColumnDefinition Width="*"/>
