        <TextBlock Text="Kapsam" Style="{DynamicResource TxtBody}" VerticalAlignment="Center"/>
        <ComboBox x:Name="st_ResetScope" Grid.Column="1" Style="{DynamicResource Combo}" ItemTemplate="{DynamicResource ComboText}"/>
      </Grid>
      <TextBlock x:Name="st_ResetNote" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,6,0,0"/>
      <WrapPanel Margin="0,8,0,0">
        <Button x:Name="st_ResetRun" Content="Varsay&#x0131;lana s&#x0131;f&#x0131;rla" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6"/>
        <Button x:Name="st_ResetUndo" Content="Son s&#x0131;f&#x0131;rlamay&#x0131; geri al" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" IsEnabled="False"/>
        <Button x:Name="st_ResetFolder" Content="Ayar kopyalar&#x0131; klas&#x00F6;r&#x00FC;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6"/>
      </WrapPanel>
      <TextBlock x:Name="st_ResetState" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,2,0,0"/>
    </StackPanel>
  </Border>
  <Border Style="{DynamicResource Card}" Padding="16">
    <StackPanel>
      <TextBlock Text="HAKKINDA" Style="{DynamicResource TxtCardTitle}"/>
      <TextBlock x:Name="st_About" Text="" Style="{DynamicResource TxtBody}" TextWrapping="Wrap" Margin="0,8,0,0"/>
      <TextBlock Text="Bu ara&#x00E7; Windows&#x2019;un Defender, G&#x00FC;venlik Duvar&#x0131;, UAC ve Windows Update &#x00F6;zelliklerini hi&#x00E7;bir ko&#x015F;ulda kapatmaz. Lisans etkinle&#x015F;tirme ya da lisans atlatma i&#x015F;lemi yapmaz." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,8,0,0"/>
      <TextBlock x:Name="st_Sig" Text="" Foreground="{DynamicResource BrAccent}" FontSize="13" Margin="0,10,0,0"/>
    </StackPanel>
  </Border>
</StackPanel>
  </ScrollViewer>
</Grid>
'@

# ==================================================================
#  ARAYUZ CEKIRDEGI: yardimcilar, gunluk paneli, bildirim, onay kutusu, cokme kaydi
#  Kurallar: olay isleyicileri script kapsamindaki $ui / $script: degiskenlerini kullanir (kapanis yok),
#            her isleyici Invoke-Safe icinde calisir; hata gunluge ve ekrana duser, uygulama kapanmaz.
# ==================================================================
$ui = @{}
$script:Win = $null
$script:Pages = @{}
$script:Settings = $null
$script:Quitting = $false
$script:BrushCache = @{}
$script:Toasts = New-Object System.Collections.ArrayList
$script:LogAdded = $false
$script:LogCount = 0
$script:JobIndet = $false
$script:CmdEcho = $false
$script:OvAction = $null
$script:OvMode = 'confirm'
$script:VisOn = $null
$script:VisOff = $null
try {
    $script:VisOn = [System.Windows.Visibility]::Visible
    $script:VisOff = [System.Windows.Visibility]::Collapsed
} catch { }

# Get-Br (koddan uretilen ogelerin fircalari): bkz. Sync-CodeBrushes (ozel kopya)

function ConvertTo-XmlText($Text) {
    if ($null -eq $Text) { return '' }
    return [System.Security.SecurityElement]::Escape([string]$Text)
}

# ---------------- kayit (cokme) ----------------
function Show-Crash($Err, [string]$Where = '') {
    $msg = ''
    $detail = ''
    try {
        $msg = [string]$Err.Exception.Message
        $detail = ([string]$Err.InvocationInfo.PositionMessage) + ' | ' + ([string]$Err.ScriptStackTrace)
    } catch { $msg = [string]$Err }
    Write-CrashLog ('[' + $Where + '] ' + $msg + ' :: ' + ($detail -replace '\s+', ' '))
    # ayni hata kisa surede cok yinelenirse ekrana ve oturum gunlugune her seferinde yazilmaz
    $burst = $false
    try { $burst = [bool](Test-ErrorBurst ($Where + '|' + $msg)) } catch { $burst = $false }
    if (-not $burst) {
        try { Write-WhLog ('Hata (' + $Where + '): ' + $msg) 'ERR' } catch { }
        try { Show-Toast ('Hata: ' + $msg) 'bad' } catch { }
    }
}

function Invoke-Safe([scriptblock]$Body, [string]$Where = '') {
    try { & $Body } catch { Show-Crash $_ $Where }
}

# ---------------- XAML yardimcilari ----------------
function New-XamlObject([string]$Xaml) {
    return Read-LocalXaml ($Xaml)
}

# Belgedeki x:Name'leri $ui tablosuna kaydeder (kok eleman uzerinden FindName)
function Register-XamlNames([string]$Xaml, $Root) {
    foreach ($m in [regex]::Matches($Xaml, 'x:Name="([A-Za-z0-9_]+)"')) {
        $n = $m.Groups[1].Value
        $ctl = $Root.FindName($n)
        if ($null -ne $ctl) { $ui[$n] = $ctl }
    }
}

# Satir sablonu: @@Ad@@ yer tutuculari XML kacisli degerlerle degistirilir; kaynak anahtari yer tutuculari (Br*/Ico*) oldugu gibi
function Expand-Template([string]$Template, $Vars) {
    $t = $Template
    foreach ($k in @($Vars.Keys)) {
        $v = [string]$Vars[$k]
        if ($k -like 'Br*' -or $k -like 'Ico*') { $t = $t.Replace('@@' + $k + '@@', $v) }
        else {
            # '{' ile baslayan nitelik degeri XAML'de isaretleme uzantisi sayilir; '{}' oneki bunu onler
            $v = [string](Tr $v)
            if ($v.StartsWith('{')) { $v = '{}' + $v }
            $t = $t.Replace('@@' + $k + '@@', (ConvertTo-XmlText $v))
        }
    }
    return $t
}

# Sablondan satir olusturur. Donen nesnenin FindName'i ile icindeki adli kontrollere erisilir.
function New-RowElement([string]$TemplateName, $Vars) {
    $tpl = (Get-Variable -Scope Script -Name ('Row_' + $TemplateName) -ValueOnly)
    $xaml = Expand-Template $tpl $Vars
    $el = Read-LocalXaml ($xaml)
    try { Set-DescCompact $el } catch { }
    return $el
}

function Clear-Panel($Panel) { $Panel.Children.Clear() }

function Add-Note($Panel, [string]$Text, [string]$Kind = 'dim') {
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.Text = (Tr $($Text))
    $tb.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $tb.Margin = New-Object System.Windows.Thickness(2, 6, 2, 6)
    $tb.FontSize = 12.5
    $key = 'BrDim'
    if ($Kind -eq 'bad') { $key = 'BrBad' } elseif ($Kind -eq 'good') { $key = 'BrGood' } elseif ($Kind -eq 'warn') { $key = 'BrWarn' }
    $tb.Foreground = (Get-Br $key)
    [void]$Panel.Children.Add($tb)
}

# ---------------- gunluk paneli ----------------
function Add-LogLine([string]$Line) {
    $Line = Convert-LogLineText $Line
    $key = 'BrLogGreen'
    if ($Line -cmatch '^\d{2}:\d{2}:\d{2}\s+([A-Z]+)\s') {
        switch ($Matches[1]) {
            'STEP' { $key = 'BrAccent' }
            'OK'   { $key = 'BrGood' }
            'WARN' { $key = 'BrWarn' }
            'ERR'  { $key = 'BrBad' }
            'PLAN' { $key = 'BrAccent2' }
            'SKIP' { $key = 'BrFaint' }
            default { $key = 'BrLogGreen' }
        }
    }
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.Text = $Line # Tr:yok
    $tb.Style = $script:Win.FindResource('TxtMono')
    $tb.Foreground = (Get-Br $key)
    [void]$ui.LogStack.Children.Add($tb)
    try { Push-BoardLog $Line $key } catch { }
    while ($ui.LogStack.Children.Count -gt 700) { $ui.LogStack.Children.RemoveAt(0) }
    $script:LogAdded = $true
    $script:LogCount++
    if ($script:CmdEcho) { Add-CmdLine $Line $key }
}

function Sync-LogScroll {
    if ($script:LogAdded) {
        $script:LogAdded = $false
        $ui.LogScroll.ScrollToEnd()
        $ui.TxtLogCount.Text = (Tr $([string]$ui.LogStack.Children.Count + (' sat' + [char]0x0131 + 'r')))
    }
}

function Clear-Log {
    $ui.LogStack.Children.Clear()
    $ui.TxtLogCount.Text = (Tr $(''))
}

# Komut satiri ciktisi
function Add-CmdLine([string]$Text, [string]$BrKey = 'BrText') {
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.Text = (Tr $($Text))
    $tb.Style = $script:Win.FindResource('TxtMono')
    $tb.Foreground = (Get-Br $BrKey)
    [void]$ui.CmdOut.Children.Add($tb)
    while ($ui.CmdOut.Children.Count -gt 400) { $ui.CmdOut.Children.RemoveAt(0) }
    $ui.CmdScroll.ScrollToEnd()
}

# ---------------- islem cubugu / mesgul durumu ----------------
function Start-IndeterminateBar {
    if ($script:JobIndet) { return }
    $script:JobIndet = $true
    if ($script:ReduceMotion -eq $true) { $ui.JobBar.Value = 100; return }
    $anim = New-Object System.Windows.Media.Animation.DoubleAnimation
    $anim.From = 0
    $anim.To = 100
    $anim.Duration = New-Object System.Windows.Duration -ArgumentList ([TimeSpan]::FromSeconds(1.4))
    $anim.AutoReverse = $true
    $anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $ui.JobBar.Maximum = 100
    $ui.JobBar.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty, $anim)
}

function Stop-IndeterminateBar {
    if (-not $script:JobIndet) { return }
    $script:JobIndet = $false
    $ui.JobBar.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty, $null)
    $ui.JobBar.Value = 0
}

function Set-JobUi([int]$Done, [int]$Total, [string]$Label) {
    if ($Label -ne '') { $ui.JobLabel.Text = (Tr $($Label)) }
    if ($Total -le 0) {
        Start-IndeterminateBar
        $ui.JobPct.Text = (Tr $(''))
    } else {
        Stop-IndeterminateBar
        $ui.JobBar.Maximum = $Total
        $ui.JobBar.Value = [math]::Min($Done, $Total)
        $pct = [int][math]::Round(100.0 * $Done / $Total)
        $ui.JobPct.Text = (Tr $(([string]$Done + ' / ' + [string]$Total + '   %' + [string]$pct)))
    }
}

function Set-BusyUi([bool]$On, [string]$Label) {
    if ($On) {
        $ui.JobPanel.Visibility = $script:VisOn
        $ui.JobLabel.Text = (Tr $($Label))
        $ui.JobPct.Text = (Tr $(''))
        $ui.JobBar.Value = 0
        $ui.DotBusy.Fill = (Get-Br 'BrWarn')
        $ui.TxtBusy.Foreground = (Get-Br 'BrWarn')
        $ui.TxtBusy.Text = (Tr $(([string][char]0x00C7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'yor')))
        if (($ui.ColLog.Width.Value -lt 10) -and (Test-LogAutoOpen)) {
            $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList ([double]$script:LogOpenWidth)
            $script:LogAutoOff = $false
            try { Update-PanelReflow } catch { }
        }
    } else {
        Stop-IndeterminateBar
        $ui.JobPanel.Visibility = $script:VisOff
        $ui.DotBusy.Fill = (Get-Br 'BrGood')
        $ui.TxtBusy.Foreground = (Get-Br 'BrGood')
        $ui.TxtBusy.Text = (Tr $(('Haz' + [char]0x0131 + 'r')))
    }
    Sync-LogScroll
}

# ---------------- bildirim karti (pencere ici) ----------------
function Show-Toast([string]$Text, [string]$Kind = 'info') {
    try {
        $br = 'BrInfo'; $ico = 'IcoInfo'
        if ($Kind -eq 'good') { $br = 'BrGood'; $ico = 'IcoCheck' }
        elseif ($Kind -eq 'warn') { $br = 'BrWarn'; $ico = 'IcoAlert' }
        elseif ($Kind -eq 'bad') { $br = 'BrBad'; $ico = 'IcoAlert' }
        $el = New-RowElement 'Toast' @{ Text = $Text; BrCol = $br; IcoName = $ico }
        [void]$ui.ToastHost.Children.Add($el)
        $secs = 5
        if ($Kind -eq 'bad') { $secs = 9 }
        [void]$script:Toasts.Add(@{ El = $el; Expire = (Get-Date).AddSeconds($secs) })
        while ($ui.ToastHost.Children.Count -gt 5) { $ui.ToastHost.Children.RemoveAt(0); if ($script:Toasts.Count -gt 0) { $script:Toasts.RemoveAt(0) } }
    } catch { Write-CrashLog ('Toast: ' + $_.Exception.Message) }
}

function Update-Toasts {
    if ($script:Toasts.Count -eq 0) { return }
    $now = Get-Date
    for ($i = $script:Toasts.Count - 1; $i -ge 0; $i--) {
        if ($script:Toasts[$i].Expire -lt $now) {
            try { $ui.ToastHost.Children.Remove($script:Toasts[$i].El) } catch { }
            $script:Toasts.RemoveAt($i)
        }
    }
}

# ---------------- pencere ici onay / bilgi / giris kutusu (geri cagirmali) ----------------
function Show-Overlay([string]$Title, [string]$Text, [string]$OkText, [bool]$ShowCancel, [bool]$Danger, [bool]$WithInput, [string]$InputText, [scriptblock]$OnOk) {
    $ui.OvTitle.Text = (Tr $($Title))
    $ui.OvText.Text = (Tr $($Text))
    $ui.OvOk.Content = (Tr $($OkText))
    if ($ShowCancel) { $ui.OvCancel.Visibility = $script:VisOn } else { $ui.OvCancel.Visibility = $script:VisOff }
    if ($Danger) { $ui.OvOk.Style = $script:Win.FindResource('BtnDanger') } else { $ui.OvOk.Style = $script:Win.FindResource('BtnPrimary') }
    if ($WithInput) { $ui.OvInput.Visibility = $script:VisOn; $ui.OvInput.Text = (Tr $($InputText)) } else { $ui.OvInput.Visibility = $script:VisOff }
    $script:OvAction = $OnOk
    $script:OvMode = 'confirm'
    $ui.OvPw1.Visibility = $script:VisOff
    $ui.OvPw2.Visibility = $script:VisOff
    $ui.OvErr.Visibility = $script:VisOff
    $ui.OvChoices.Visibility = $script:VisOff
    $ui.OvOk.Visibility = $script:VisOn
    $ui.OvCancel.Content = (Tr $(('Vazge' + [char]0x00E7 + '')))
    $ui.Overlay.Visibility = $script:VisOn
    if ($WithInput) { [void]$ui.OvInput.Focus(); $ui.OvInput.SelectAll() } else { [void]$ui.OvOk.Focus() }
}

function Show-Confirm([string]$Title, [string]$Text, [string]$OkText, [scriptblock]$OnOk, [bool]$Danger = $false) {
    Show-Overlay $Title $Text $OkText $true $Danger $false '' $OnOk
}

function Show-Message([string]$Title, [string]$Text) {
    Show-Overlay $Title $Text 'Tamam' $false $false $false '' $null
}

function Show-Input([string]$Title, [string]$Text, [string]$Default, [scriptblock]$OnOk) {
    Show-Overlay $Title $Text 'Tamam' $true $false $true $Default $OnOk
}

function Close-Overlay { $ui.Overlay.Visibility = $script:VisOff; $ui.OvText.Text = (Tr $('')) }

function Complete-Overlay([bool]$Ok) {
    $act = $script:OvAction
    $txt = ''
    if ($ui.OvInput.Visibility -eq $script:VisOn) { $txt = [string]$ui.OvInput.Text }
    if ($script:OvMode -eq 'password') {
        if ($Ok) {
            $p1 = [string]$ui.OvPw1.Password
            $why = ''
            if ($p1.Length -lt 8) { $why = ('Parola en az 8 karakter olmal' + [char]0x0131 + '.') }
            elseif ($script:OvPwConfirm -eq $true -and $p1 -ne [string]$ui.OvPw2.Password) { $why = ('' + [char]0x0130 + 'ki parola birbiriyle ayn' + [char]0x0131 + ' de' + [char]0x011F + 'il.') }
            if ($why -ne '') { $ui.OvErr.Text = (Tr $($why)); $ui.OvErr.Visibility = $script:VisOn; return }
            $txt = $p1
        }
        $ui.OvPw1.Password = ''
        $ui.OvPw2.Password = ''
        $ui.OvPw1.Visibility = $script:VisOff
        $ui.OvPw2.Visibility = $script:VisOff
        $ui.OvErr.Visibility = $script:VisOff
        $script:OvMode = 'confirm'
    }
    Close-Overlay
    $script:OvAction = $null
    if ($Ok -and $null -ne $act) {
        try { & $act $txt } catch { Show-Crash $_ 'Onay' }
    }
}

# ---------------- dosya / klasor seciciler ----------------
function Select-Folder([string]$Desc) {
    $d = New-Object System.Windows.Forms.FolderBrowserDialog
    $d.Description = (Tr $Desc)
    $d.ShowNewFolderButton = $true
    if ($d.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { return [string]$d.SelectedPath }
    return ''
}

function Select-OpenFile([string]$Filter) {
    $d = New-Object Microsoft.Win32.OpenFileDialog
    $d.Filter = $Filter
    if ($d.ShowDialog() -eq $true) { return [string]$d.FileName }
    return ''
}

function Select-SaveFile([string]$Filter, [string]$Name) {
    $d = New-Object Microsoft.Win32.SaveFileDialog
    $d.Filter = $Filter
    $d.FileName = $Name
    if ($d.ShowDialog() -eq $true) { return [string]$d.FileName }
    return ''
}

# ---------------- dis islemler ----------------
function Open-Path([string]$Path) {
    if ($script:SmokeMode) { Add-SmokeLine ('      (acilmadi) ' + $Path); return }
    try { Start-Process -FilePath $Path -ErrorAction Stop | Out-Null } catch { Show-Toast (('A' + [char]0x00E7 + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $Path) 'warn' }
}

function Open-Url([string]$Url) {
    if ($script:SmokeMode) { Add-SmokeLine ('      (acilmadi) ' + $Url); return }
    try {
        if ($Url -match '^(https?://|windowsdefender:|ms-settings:|ms-windows-store:)') { Start-Process -FilePath $Url -ErrorAction Stop | Out-Null }
        else { Start-Process -FilePath 'cmd.exe' -ArgumentList ('/c start "" ' + $Url) -WindowStyle Hidden -ErrorAction Stop | Out-Null }
    } catch { Show-Toast (('A' + [char]0x00E7 + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $Url) 'warn' }
}

function Open-Folder([string]$Path) {
    if ($script:SmokeMode) { Add-SmokeLine ('      (acilmadi) ' + $Path); return }
    try {
        if (-not (Test-Path -LiteralPath $Path)) { New-Item -ItemType Directory -Path $Path -Force | Out-Null }
        Start-Process -FilePath 'explorer.exe' -ArgumentList ('"' + $Path + '"') | Out-Null
    } catch { Show-Toast (('Klas' + [char]0x00F6 + 'r a' + [char]0x00E7 + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $Path) 'warn' }
}

# Turkce harfleri sadelestirir (komut eslestirme ve arama icin)
function ConvertTo-AsciiKey([string]$Text) {
    $t = $Text.ToLowerInvariant()
    $map = @{ 0x0131 = 'i'; 0x0130 = 'i'; 0x015F = 's'; 0x011F = 'g'; 0x00E7 = 'c'; 0x00F6 = 'o'; 0x00FC = 'u'; 0x0307 = '' }
    $sb = New-Object System.Text.StringBuilder
    foreach ($ch in $t.ToCharArray()) {
        $code = [int]$ch
        if ($map.ContainsKey($code)) { [void]$sb.Append($map[$code]) } else { [void]$sb.Append($ch) }
    }
    return $sb.ToString()
}

# Boyut metni ve yuzde yardimcilari
function Format-Pct([double]$V) { return (Format-Percent ([int][math]::Round($V))) }

function Set-Visible($El, [bool]$On) {
    if ($On) { $El.Visibility = $script:VisOn } else { $El.Visibility = $script:VisOff }
}

# ==================================================================
#  SAYFA: Durum panosu  (gostergeler, saglik, ag topolojisi, arac kutusu)
# ==================================================================
$script:Health = $null
$script:HealthAt = [datetime]::MinValue
$script:TopoSnap = $null
$script:TopoAt = [datetime]::MinValue
$script:TopoW = 0
$script:NetPeak = 10.0

function Format-HealthTime([string]$Fmt) {
    if ($script:HealthAt -eq [datetime]::MinValue) { return ('g' + [char]0x00FC + 'ncelleniyor') }
    return $script:HealthAt.ToString($Fmt)
}

# Halka gostergesi: Units = tam halkanin cizgi birimi uzunlugu (270 derece icin 24.87; tam daire icin 37.70)
function Set-Ring($Ellipse, [double]$Pct, [double]$Units) {
    if ($Pct -lt 0) { $Pct = 0 }
    if ($Pct -gt 100) { $Pct = 100 }
    $len = [math]::Max(0.001, $Pct / 100.0 * $Units)
    $txt = $len.ToString('0.###', [System.Globalization.CultureInfo]::InvariantCulture) + ',100'
    $Ellipse.StrokeDashArray = [System.Windows.Media.DoubleCollection]::Parse($txt)
    if ($Pct -lt 0.5) { $Ellipse.Opacity = 0.0 } else { $Ellipse.Opacity = 1.0 }
}

function Format-Mbps([double]$BytesPerSec) {
    $mb = $BytesPerSec * 8.0 / 1000000.0
    if ($mb -ge 100) { return ([string][int]$mb + ' Mb/sn') }
    return ($mb.ToString('0.0') + ' Mb/sn')
}

function Update-Gauges($M) {
    $cpu = [double]$M.Cpu
    Set-Ring $ui.pn_GCpu $cpu 24.87
    $ui.pn_VCpu.Text = (Tr $((Format-Percent ([int]$cpu))))
    $ui.pn_DCpu.Text = (Tr $($script:CpuShort))
    $ram = [double]$M.Ram
    Set-Ring $ui.pn_GRam $ram 24.87
    $ui.pn_VRam.Text = (Tr $((Format-Percent ([int]$ram))))
    $ui.pn_DRam.Text = (Tr $(([string]$M.RamUsedGB + ' / ' + [string]$M.RamTotalGB + ' GB')))
    $gpu = [double]$M.Gpu
    if ($gpu -ge 0) {
        Set-Ring $ui.pn_GGpu $gpu 24.87
        $ui.pn_VGpu.Text = (Tr $((Format-Percent ([int]$gpu))))
        $ui.pn_DGpu.Text = (Tr $(('ekran kart' + [char]0x0131 + ' (3B)')))
    } else {
        Set-Ring $ui.pn_GGpu 0 24.87
        $ui.pn_VGpu.Text = (Tr $('--'))
        $ui.pn_DGpu.Text = (Tr $((Get-GpuOffText)))
    }
    $p = $sync.Profile
    if ($null -ne $p -and [double]$p.SizeGB -gt 0) {
        $used = 100.0 * ([double]$p.SizeGB - [double]$p.FreeGB) / [double]$p.SizeGB
        Set-Ring $ui.pn_GDisk $used 24.87
        $ui.pn_VDisk.Text = (Tr $((Format-Percent ([int]$used))))
        $ui.pn_DDisk.Text = (Tr $(([string]$p.SysDrive + ': ' + [string]$p.FreeGB + (' GB bo' + [char]0x015F + ' ' + [char]0x00B7 + ' etkinlik %') + [string][int][double]$M.Disk)))
    }
    $down = [double]$M.NetDown; $up = [double]$M.NetUp
    $ui.pn_TxtDown.Text = (Tr $(Format-Mbps $down))
    $ui.pn_TxtUp.Text = (Tr $(Format-Mbps $up))
    $mbDown = $down * 8.0 / 1000000.0; $mbUp = $up * 8.0 / 1000000.0
    $script:NetPeak = [math]::Max(10.0, [math]::Max($script:NetPeak * 0.97, [math]::Max($mbDown, $mbUp)))
    $ui.pn_BarDown.Value = [math]::Min(100.0, 100.0 * $mbDown / $script:NetPeak)
    $ui.pn_BarUp.Value = [math]::Min(100.0, 100.0 * $mbUp / $script:NetPeak)
    $ui.pn_Top.Children.Clear()
    if ($M.ContainsKey('Top')) {
        foreach ($t in @($M.Top)) {
            $g = New-Object System.Windows.Controls.Grid
            $a = New-Object System.Windows.Controls.TextBlock
            $a.Text = (Tr $([string]$t.Name)); $a.FontSize = 11.5; $a.Foreground = (Get-Br 'BrText'); $a.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis; $a.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 0, 44, 0
            $b = New-Object System.Windows.Controls.TextBlock
            $b.Text = (Tr $((Format-Percent ([double]$t.Cpu)))); $b.FontSize = 11.5; $b.Foreground = (Get-Br 'BrDim'); $b.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
            [void]$g.Children.Add($a); [void]$g.Children.Add($b)
            $g.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 1, 0, 1
            [void]$ui.pn_Top.Children.Add($g)
        }
    }
    if ($M.ContainsKey('Boot') -and $null -ne $M.Boot) {
        try { $ui.pn_SiUp.Text = (Tr $((Format-Duration (((Get-Date) - [datetime]$M.Boot).TotalSeconds)))) } catch { }
    }
}

# ---------------- bu bilgisayar karti ----------------
function Update-SysInfo {
    $p = $sync.Profile
    if ($null -eq $p) { return }
    $ui.pn_SiOs.Text = (Tr $(([string]$p.OsName + ' ' + [string]$p.Version + ' (derleme ' + [string]$p.Build + '.' + [string]$p.UBR + ')')))
    $ui.pn_SiCpu.Text = (Tr $(([string]$p.CpuName + (' ' + [char]0x00B7 + ' ') + [string]$p.Cores + (' ' + [char]0x00E7 + 'ekirdek / ') + [string]$p.Threads + (' i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + [char]0x011F + [char]0x0131))))
    $ui.pn_SiRam.Text = (Tr $(([string]$p.RamGB + ' GB')))
    $dk = [string]$p.DiskType
    if ($dk -eq 'Unknown') { $dk = '' }
    $ui.pn_SiDisk.Text = (Tr $((([string]$p.SysDrive + ': ' + $dk + ' ' + [string]$p.DiskModel).Trim() + (' ' + [char]0x2014 + ' ') + [string]$p.FreeGB + (' GB bo' + [char]0x015F + ' / ') + [string]$p.SizeGB + ' GB')))
    $ui.pn_SiHost.Text = (Tr $(([string]$p.Hostname + (' ' + [char]0x00B7 + ' ') + [string]$p.Model)))
    $mg = ('Ba' + [char]0x011F + [char]0x0131 + 'ms' + [char]0x0131 + 'z (i' + [char]0x015F + ' grubu)')
    if ([string]$p.JoinType -match 'Domain') { $mg = ('Etki alan' + [char]0x0131 + ': ') + [string]$p.Domain }
    elseif ([string]$p.JoinType -match 'AzureAD') { $mg = 'Microsoft Entra ID (Azure AD)' }
    if ($p.MdmManaged) { $mg += (' ' + [char]0x00B7 + ' MDM/Intune') }
    $ui.pn_SiMgmt.Text = (Tr $($mg))
    $ui.TxtSys.Text = (Tr $(([string]$p.OsName + ' ' + [string]$p.Version + '   |   ' + [string]$p.Hostname + '   |   ' + [string]$p.RunUser)))
    $cn = [string]$p.CpuName
    $cn = [regex]::Replace($cn, '\(R\)|\(TM\)|CPU|Processor|@.*$', '')
    $script:CpuShort = ($cn -replace '\s+', ' ').Trim()
    $ui.pn_SysLine.Text = (Tr $(([string]$p.Threads + (' i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + [char]0x011F + [char]0x0131 + ' ' + [char]0x00B7 + ' ') + [string]$p.RamGB + ' GB RAM')))
}

function Update-QuickStatus {
    $st = $script:Settings
    $lm = [string]$st.LastMaint
    if ($lm -eq '') { $ui.pn_QsMaint.Text = (Tr $(('Bak' + [char]0x0131 + 'm: hen' + [char]0x00FC + 'z yap' + [char]0x0131 + 'lmad' + [char]0x0131))) } else { $ui.pn_QsMaint.Text = (Tr $((('Son bak' + [char]0x0131 + 'm: ') + $lm))) }
    $lb = [string]$st.LastBackup
    if ($lb -eq '') { $ui.pn_QsBackup.Text = (Tr $(('Dosya yede' + [char]0x011F + 'i: hen' + [char]0x00FC + 'z al' + [char]0x0131 + 'nmad' + [char]0x0131))) } else { $ui.pn_QsBackup.Text = (Tr $(('Son yedek: ' + $lb))) }
    $rb = ''; $rp = ''
    if ($null -ne $script:Health) {
        foreach ($f in @($script:Health.Findings)) {
            if ($f.Id -eq 'reboot') { $rb = [string]$f.Title }
            if ($f.Id -eq 'rp') { $rp = [string]$f.Title }
        }
        if ($rb -eq '') { $rb = ('Yeniden ba' + [char]0x015F + 'latma beklenmiyor') }
    }
    $ui.pn_QsReboot.Text = (Tr $($rb))
    $ui.pn_QsRp.Text = (Tr $($rp))
}

# ---------------- saglik ----------------
function Update-HealthUi {
    $h = $script:Health
    if ($null -eq $h) { return }
    try { Update-BoardHealth } catch { }
    $sc = $h.Score
    $all = [double]$sc.All
    $key = 'BrGood'
    if ($all -lt 60) { $key = 'BrBad' } elseif ($all -lt 80) { $key = 'BrWarn' }
    $ui.pn_GScore.Stroke = (Get-Br $key)
    Set-Ring $ui.pn_GScore $all 37.7
    $ui.pn_VScore.Text = (Tr $([string][int]$all))
    $ui.pn_VSec.Text = (Tr $([string]$sc.Sec)); $ui.pn_BarSec.Value = [double]$sc.Sec
    $ui.pn_VPerf.Text = (Tr $([string]$sc.Perf)); $ui.pn_BarPerf.Value = [double]$sc.Perf
    $ui.pn_VMaint.Text = (Tr $([string]$sc.Maint)); $ui.pn_BarMaint.Value = [double]$sc.Maint
    $ui.TxtHealth.Text = (Tr $((('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k: ') + [string][int]$all)))
    if ($all -lt 60) { $ui.TxtHealth.Foreground = (Get-Br 'BrBad') } elseif ($all -lt 80) { $ui.TxtHealth.Foreground = (Get-Br 'BrWarn') } else { $ui.TxtHealth.Foreground = (Get-Br 'BrGood') }
    $ui.pn_Findings.Children.Clear()
    $issues = @($h.Findings | Where-Object { $_.Status -ne 'ok' })
    $okN = @($h.Findings | Where-Object { $_.Status -eq 'ok' }).Count
    if ($issues.Count -eq 0) {
        $ui.pn_HealthNote.Text = (Tr $((('Her ' + [char]0x015F + 'ey yolunda g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor. ') + $okN + (' denetim ba' + [char]0x015F + 'ar' + [char]0x0131 + 'l' + [char]0x0131 + '.'))))
    } else {
        $ui.pn_HealthNote.Text = (Tr $(([string]$issues.Count + (' ' + [char]0x00F6 + 'neri ' + [char]0x00B7 + ' ') + $okN + (' denetim ba' + [char]0x015F + 'ar' + [char]0x0131 + 'l' + [char]0x0131 + ' ' + [char]0x00B7 + ' ') + (Format-HealthTime 'HH:mm'))))
    }
    $shown = 0
    foreach ($f in $issues) {
        if ($shown -ge 8) { break }
        $shown++
        $br = 'BrInfo'
        if ($f.Status -eq 'bad') { $br = 'BrBad' } elseif ($f.Status -eq 'warn') { $br = 'BrWarn' }
        $btn = ''
        if ($null -ne $f.Action -and $f.Action.ContainsKey('Label')) { $btn = [string]$f.Action.Label }
        $fx = $null
        if ($null -ne $f.Fix -and ([string]$f.Fix.Mode -eq 'Auto' -or [string]$f.Fix.Mode -eq 'Click')) { $fx = $f.Fix }
        $ak = ''
        if ($null -ne $f.Action) { $ak = [string]$f.Action.Kind }
        # Eylem dugmesi duzeltmeyle ayni isi yapiyorsa yalnizca "Duzelt" gosterilir
        if ($null -ne $fx -and ($ak -eq 'Tweak' -or $ak -eq 'Run')) { $btn = '' }
        $fxBtn = ''
        if ($null -ne $fx) { $fxBtn = ('D' + [char]0x00FC + 'zelt') }
        $det = [string]$f.Detail
        if ($det.Length -gt 170) { $det = $det.Substring(0, 167) + '...' }
        $row = New-RowElement 'Finding' @{ Title = [string]$f.Title; Detail = $det; BrCol = $br; Btn = $btn; FixBtn = $fxBtn }
        $b = $row.FindName('Act')
        if ($btn -eq '') { $b.Visibility = $script:VisOff } else { $b.Tag = $f.Action; $b.Add_Click($script:H_FindingAct) }
        $fb = $row.FindName('Fx')
        if ($fxBtn -eq '') { $fb.Visibility = $script:VisOff } else { $fb.Tag = @{ Id = [string]$f.Id; Title = [string]$f.Title; Fix = $fx; Mode = [string]$fx.Mode }; $fb.Add_Click($script:H_FixOne) }
        [void]$ui.pn_Findings.Children.Add($row)
    }
    if ($issues.Count -gt $shown) { Add-Note $ui.pn_Findings ('... ve ' + [string]($issues.Count - $shown) + (' ' + [char]0x00F6 + 'neri daha. T' + [char]0x00FC + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar i' + [char]0x00E7 + 'in G' + [char]0x00FC + 'venlik sayfas' + [char]0x0131 + 'ndaki tam denetimi ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n.')) }
    Update-QuickStatus
    Update-FixButtons
    $fn = 'Update-SecurityFromHealth'
    if (Get-Command -Name $fn -CommandType Function -ErrorAction Ignore) { & $fn }
    if (Get-Command -Name 'Update-SolveFromHealth' -CommandType Function -ErrorAction Ignore) { Update-SolveFromHealth }
}

$script:H_FindingAct = { param($s, $e) Invoke-Safe { Invoke-FindingAction $s.Tag } 'Bulgu eylemi' }

function Invoke-FindingAction($A) {
    if ($null -eq $A) { return }
    switch ([string]$A.Kind) {
        'Tweak' {
            $id = [string]$A.Id
            $c = Get-CatalogItem $id
            if ($null -eq $c) { Show-Toast ('Bu d' + [char]0x00FC + 'zeltme bu sistemde bulunamad' + [char]0x0131 + '.') 'warn'; return }
            $steps = New-StepsFromIds @($id)
            Show-Confirm ('D' + [char]0x00FC + 'zeltmeyi uygula') ([string]$c.Title + "`r`n`r`n" + [string]$c.Desc + ("`r`n`r`nDe" + [char]0x011F + "i" + [char]0x015F + "iklik geri al" + [char]0x0131 + "nabilir (Ge" + [char]0x00E7 + "mi" + [char]0x015F + " sayfas" + [char]0x0131 + ").")) 'Uygula' { Start-PlanJob $script:PendingSteps (('D' + [char]0x00FC + 'zeltme: ') + $script:PendingTitle) $false $false { Start-HealthScan 'Quick' $true } }
            $script:PendingSteps = $steps
            $script:PendingTitle = [string]$c.Title
        }
        'Page' { Open-Page ([string]$A.Page) ([string]$A.Sub) }
        'Run' {
            $k = [string]$A.Key
            if ($k -eq 'Reboot') { Request-Reboot; return }
            [void](Start-Async 'Action' 'Job_Action' @{ Key = $k } { param($r) $script:Settings = Get-Settings; Update-QuickStatus; Start-HealthScan 'Quick' $true } ('Eylem: ' + $k))
        }
        'Url' { Open-Url ([string]$A.Url) }
    }
}

# Saglik taramasi: Level Quick | Full. Queue = arka planda sessiz calistir
function Start-HealthScan([string]$Level, [bool]$Quiet = $false) {
    $lbl = ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131)
    if ($Level -eq 'Full') { $lbl = ('Tam g' + [char]0x00FC + 'venlik ve sa' + [char]0x011F + 'l' + [char]0x0131 + 'k denetimi') }
    $script:HealthLevel = $Level
    [void](Start-Async 'Health' 'Job_Health' @{ Level = $Level } {
        param($r)
        if ($null -eq $r) { Show-Toast ('Tarama tamamlanamad' + [char]0x0131 + '.') 'warn'; return }
        $script:Health = $r
        $script:HealthAt = Get-Date
        Update-HealthUi
        if ($script:HealthLevel -eq 'Full') { Show-Toast (('Denetim tamamland' + [char]0x0131 + ': sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ' ') + [string]$r.Score.All) 'good' }
    } $lbl $Quiet $true)
}


# ---------------- Duzeltme arayuzu ----------------
# ==================================================================
#  DUZELTME ARAYUZU: her bulguda "Duzelt", panelde ve Guvenlik sayfasinda "Hepsini duzelt",
#  Guvenlik sayfasinda "Duzeltme plani" sekmesi. Uygulama her zaman onaydan sonra, gunluge yazilarak
#  ve geri alinabilir bicimde (Job_FixAll -> Job_Plan) yapilir.
# ==================================================================
$script:FixPending = @()
$script:FixScoreBefore = -1
$script:FxSel = @{}

function Get-FixItems {
    if ($null -eq $script:Health) { return , @() }
    $l = Get-FixList $script:Health.Findings
    return , $l
}

function Get-FixModeInfo([string]$Mode) {
    switch ($Mode) {
        'Auto'   { return @{ Text = 'Otomatik'; Br = 'BrAccent' } }
        'Click'  { return @{ Text = ('Onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla'); Br = 'BrWarn' } }
        'Guided' { return @{ Text = 'Sayfadan'; Br = 'BrBlue' } }
        default  { return @{ Text = 'Elle'; Br = 'BrFaint' } }
    }
}

function Test-FixUndoable($Items) {
    foreach ($it in @($Items)) {
        if (@('Tweak', 'Steps', 'Adaptive', 'Drift', 'Services') -contains [string]$it.Fix.Kind) { return $true }
    }
    return $false
}

function Get-FixDetailText($It) {
    $fx = $It.Fix
    $parts = New-Object System.Collections.ArrayList
    [void]$parts.Add([string]$It.Title)
    if ([string]$fx.Kind -eq 'Tweak' -and @($fx.Ids).Count -eq 1) {
        $c = Get-CatalogItem ([string]$fx.Ids[0])
        if ($null -ne $c -and [string]$c.Desc -ne '') { [void]$parts.Add([string]$c.Desc) }
    }
    if ([string]$fx.Note -ne '') { [void]$parts.Add([string]$fx.Note) }
    return ($parts -join "`r`n`r`n")
}

# Onay penceresi ve uygulama.  Items: Get-FixList ogeleri (Title, Fix)
function Start-FixFlow($Items, [string]$Title) {
    $arr = @($Items)
    if ($arr.Count -eq 0) { Show-Toast (('D' + [char]0x00FC + 'zeltilecek bir ' + [char]0x015F + 'ey yok.')) 'info'; return }
    $script:FixPending = $arr
    if ($arr.Count -eq 1) {
        $txt = Get-FixDetailText $arr[0]
    } else {
        $names = @($arr | ForEach-Object { [string]$_.Fix.Label + (' ' + [char]0x2014 + ' ') + [string]$_.Title })
        $txt = [string]$arr.Count + " d$([char]0x00FC)zeltme uygulanacak:`r`n`r`n" + (Format-NameList $names 10)
    }
    if (Test-FixUndoable $arr) {
        $txt += "`r`n`r`nDe$([char]0x011F)i$([char]0x015F)iklikler kaydedilir; Ge$([char]0x00E7)mi$([char]0x015F) sayfas$([char]0x0131)ndan geri al$([char]0x0131)nabilir."
        if ($script:Settings.RestorePoint -eq $true) { $txt += (' ' + [char]0x00D6 + 'nce geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulur.') }
    }
    Show-Confirm $Title $txt ('D' + [char]0x00FC + 'zelt') { Invoke-FixRun $script:FixPending $false }
}

function Invoke-FixRun($Items, [bool]$Preview) {
    $arr = @($Items)
    if ($arr.Count -eq 0) { return }
    $fixes = @($arr | ForEach-Object { $_.Fix })
    if ($null -ne $script:Health) { $script:FixScoreBefore = [int]$script:Health.Score.All } else { $script:FixScoreBefore = -1 }
    $lbl = ('D' + [char]0x00FC + 'zeltmeler uygulan' + [char]0x0131 + 'yor')
    if ($Preview) { $lbl = ('D' + [char]0x00FC + 'zeltme ' + [char]0x00F6 + 'nizlemesi') }
    $rp = ((-not $Preview) -and ($script:Settings.RestorePoint -eq $true))
    [void](Start-Async 'Fix' 'Job_FixAll' @{ Fixes = $fixes; Preview = $Preview; RestorePoint = $rp } { param($r) Complete-FixRun $r } $lbl)
}

function Complete-FixRun($R) {
    if ($null -eq $R) { Show-Toast (('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.')) 'bad'; return }
    $script:Settings = Get-Settings
    $script:HealthAt = [datetime]::MinValue
    if ($R.Preview -eq $true) {
        Show-Toast ((('' + [char]0x00D6 + 'nizleme tamamland' + [char]0x0131 + ': ')) + [string]$R.Changes + ((' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yap' + [char]0x0131 + 'lacak, ')) + [string]$R.Skipped + ((' atlanacak. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' soldaki g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.'))) 'info'
        return
    }
    $kind = 'good'
    if ([int]$R.Errors -gt 0) { $kind = 'warn' }
    Show-Toast ([string]$R.Summary) $kind
    Show-Notify (('D' + [char]0x00FC + 'zeltme tamamland' + [char]0x0131 + '')) ([string]$R.Summary) $kind
    Start-FixRescan
    try { if ([string]$script:UiState.Page -eq 'network' -and $script:NwTab -eq 'prot') { Start-NpScan } } catch { }
    if ($R.Reboot -eq $true) { Request-Reboot }
}

# Duzeltmeden sonra ayni kapsamda yeniden tarar; onceki ve yeni puani gosterir
function Start-FixRescan {
    $lvl = [string]$script:HealthLevel
    if ($lvl -eq '') { $lvl = 'Quick' }
    $script:HealthLevel = $lvl
    [void](Start-Async 'Health' 'Job_Health' @{ Level = $lvl } {
        param($r)
        if ($null -eq $r) { return }
        $script:Health = $r
        $script:HealthAt = Get-Date
        Update-HealthUi
        $b = [int]$script:FixScoreBefore
        $a = [int]$r.Score.All
        $fl = Get-FixList $r.Findings
        $left = @($fl | Where-Object { $_.Mode -eq 'Auto' }).Count
        if ($b -ge 0) {
            $msg = (('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ' ') + [string]$b + (' ' + [char]0x2192 + ' ') + [string]$a)
            if ($left -gt 0) { $msg += (('. Kalan otomatik d' + [char]0x00FC + 'zeltme: ') + [string]$left) }
            $k = 'info'
            if ($a -gt $b) { $k = 'good' }
            Show-Toast $msg $k
        }
    } ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k yeniden denetleniyor') $false $true)
}

# Hepsini duzelt: yalnizca "Otomatik" duzeltmeler (dusuk riskli, geri alinabilir)
function Start-FixAll {
    if ($null -eq $script:Health) { Show-Toast (('' + [char]0x00D6 + 'nce bir tarama yap' + [char]0x0131 + 'n.')) 'warn'; return }
    $list = Get-FixItems
    $auto = @($list | Where-Object { $_.Mode -eq 'Auto' })
    $click = @($list | Where-Object { $_.Mode -eq 'Click' })
    if ($auto.Count -eq 0) {
        if ($click.Count -gt 0) {
            Show-Toast (('Otomatik d' + [char]0x00FC + 'zeltilecek bulgu yok; ') + [string]$click.Count + (' bulgu tek tek onay' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' bekliyor.')) 'info'
            Open-Page 'security' 'fix'
        } else {
            Show-Toast (('D' + [char]0x00FC + 'zeltilebilecek bulgu yok.')) 'good'
        }
        return
    }
    $script:FixPending = $auto
    $names = @($auto | ForEach-Object { [string]$_.Fix.Label + (' ' + [char]0x2014 + ' ') + [string]$_.Title })
    $txt = [string]$auto.Count + " d$([char]0x00FC)zeltme uygulanacak:`r`n`r`n" + (Format-NameList $names 12)
    if ($click.Count -gt 0) { $txt += "`r`n`r`n" + [string]$click.Count + (' bulgu yan etki i' + [char]0x00E7 + 'erebilece' + [char]0x011F + 'i i' + [char]0x00E7 + 'in burada uygulanmaz; G' + [char]0x00FC + 'venlik sayfas' + [char]0x0131 + 'ndaki D' + [char]0x00FC + 'zeltme plan' + [char]0x0131 + 'ndan tek tek se' + [char]0x00E7 + 'ebilirsiniz.') }
    if (Test-FixUndoable $auto) {
        $txt += "`r`n`r`nDe$([char]0x011F)i$([char]0x015F)iklikler kaydedilir; Ge$([char]0x00E7)mi$([char]0x015F) sayfas$([char]0x0131)ndan geri al$([char]0x0131)nabilir."
        if ($script:Settings.RestorePoint -eq $true) { $txt += (' ' + [char]0x00D6 + 'nce geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulur.') }
    }
    Show-Confirm (('Hepsini d' + [char]0x00FC + 'zelt')) $txt ('D' + [char]0x00FC + 'zelt') { Invoke-FixRun $script:FixPending $false }
}

function Update-FixButtons {
    $list = Get-FixItems
    $auto = @($list | Where-Object { $_.Mode -eq 'Auto' }).Count
    $b = $ui['pn_BtnFixAll']
    if ($null -ne $b) {
        if ($auto -gt 0) { $b.Content = (Tr $((('Hepsini d' + [char]0x00FC + 'zelt (') + [string]$auto + ')'))); $b.Visibility = $script:VisOn } else { $b.Visibility = $script:VisOff }
    }
    $s = $ui['sc_FixAll']
    if ($null -ne $s) {
        $s.Content = (Tr $((('Hepsini d' + [char]0x00FC + 'zelt (') + [string]$auto + ')')))
        if ($script:ScTab -eq 'audit' -and $auto -gt 0) { $s.Visibility = $script:VisOn } else { $s.Visibility = $script:VisOff }
    }
}

$script:H_FixOne = { param($s, $e) Invoke-Safe { Start-FixFlow @($s.Tag) (('D' + [char]0x00FC + 'zeltmeyi uygula')) } ('D' + [char]0x00FC + 'zeltme') }
$script:H_ScFix = { param($s, $e) Invoke-Safe { Start-FixFlow @($s.Tag) (('D' + [char]0x00FC + 'zeltmeyi uygula')) } ('D' + [char]0x00FC + 'zeltme') }

# ---------------- Guvenlik sayfasi: Duzeltme plani sekmesi ----------------
$script:H_FxChk = { param($s, $e) $script:FxSel[[string]$s.Tag] = ($s.IsChecked -eq $true); Update-FxFoot }

function Get-FxSelectedItems {
    $out = New-Object System.Collections.ArrayList
    foreach ($it in (Get-FixItems)) {
        if ($script:FxSel[[string]$it.Id] -eq $true) { [void]$out.Add($it) }
    }
    return , $out.ToArray()
}

function Update-FxFoot {
    $n = (Get-FxSelectedItems).Count
    $ui.sc_Foot.Text = (Tr $(([string]$n + (' d' + [char]0x00FC + 'zeltme se' + [char]0x00E7 + 'ili. ' + [char]0x201C + '' + [char]0x00D6 + 'nizle' + [char]0x201D + ' ile hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'tirmeden ne yap' + [char]0x0131 + 'laca' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00F6 + 'rebilirsiniz.'))))
}

function Render-ScFix {
    $ui.sc_List.Children.Clear()
    $h = $script:Health
    if ($null -eq $h) {
        Add-Note $ui.sc_List (('Hen' + [char]0x00FC + 'z denetim yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '. ' + [char]0x201C + 'Tam denetimi ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n; bulunan sorunlar burada bir d' + [char]0x00FC + 'zeltme plan' + [char]0x0131 + 'na d' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r.'))
        $ui.sc_Foot.Text = (Tr $(''))
        return
    }
    $list = Get-FixItems
    $auto = @($list | Where-Object { $_.Mode -eq 'Auto' })
    $click = @($list | Where-Object { $_.Mode -eq 'Click' })
    $open = @($h.Findings | Where-Object { [string]$_.Status -ne 'ok' -and $null -ne $_.Fix })
    $guided = @($open | Where-Object { [string]$_.Fix.Mode -eq 'Guided' })
    $manual = @($open | Where-Object { [string]$_.Fix.Mode -eq 'Manual' })
    if ($list.Count -eq 0 -and $guided.Count -eq 0 -and $manual.Count -eq 0) {
        Add-Note $ui.sc_List (('D' + [char]0x00FC + 'zeltilecek bir bulgu yok. Her ' + [char]0x015F + 'ey yolunda g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor.')) 'good'
        $ui.sc_Foot.Text = (Tr $(''))
        return
    }
    foreach ($g in @(@{ T = ('Otomatik d' + [char]0x00FC + 'zeltilebilir'); L = $auto }, @{ T = ('Onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla d' + [char]0x00FC + 'zeltilebilir'); L = $click })) {
        if (@($g.L).Count -eq 0) { continue }
        Add-HeadRow $ui.sc_List ($g.T + ' (' + [string]@($g.L).Count + ')')
        foreach ($it in @($g.L)) {
            $mi = Get-FixModeInfo ([string]$it.Mode)
            $br = 'BrInfo'
            if ($it.Status -eq 'bad') { $br = 'BrBad' } elseif ($it.Status -eq 'warn') { $br = 'BrWarn' }
            $f = $null
            foreach ($x in $h.Findings) { if ([string]$x.Id -eq [string]$it.Id) { $f = $x; break } }
            $det = ''
            if ($null -ne $f) { $det = [string]$f.Detail }
            if ([string]$it.Fix.Note -ne '') { $det = ($det + '  [' + [string]$it.Fix.Note + ']').Trim() }
            if ($det.Length -gt 330) { $det = $det.Substring(0, 327) + '...' }
            if (-not $script:FxSel.ContainsKey([string]$it.Id)) { $script:FxSel[[string]$it.Id] = ($it.Mode -eq 'Auto') }
            $row = New-ItemRow @{ Title = [string]$it.Title; Detail = $det; Tag = ($mi.Text + (' ' + [char]0x00B7 + ' ') + [string]$it.Fix.Label); BrCol = $br } @{ Id = [string]$it.Id } $true ($script:FxSel[[string]$it.Id] -eq $true)
            $chk = $row.FindName('Chk')
            $chk.Tag = [string]$it.Id
            $chk.Add_Click($script:H_FxChk)
            [void]$ui.sc_List.Children.Add($row)
        }
    }
    if ($guided.Count -gt 0) {
        Add-HeadRow $ui.sc_List (('' + [char]0x0130 + 'lgili sayfadan yap' + [char]0x0131 + 'lacaklar (') + [string]$guided.Count + ')')
        foreach ($f in $guided) {
            $br = 'BrInfo'
            if ($f.Status -eq 'bad') { $br = 'BrBad' } elseif ($f.Status -eq 'warn') { $br = 'BrWarn' }
            $btn = [string]$f.Fix.Label
            if ($btn -eq '' -and $null -ne $f.Action) { $btn = [string]$f.Action.Label }
            $row = New-ItemRow @{ Title = [string]$f.Title; Detail = [string]$f.Detail; Tag = (Get-CatLabel ([string]$f.Cat)); BrCol = $br; Btn1 = $btn } @{ Action = $f.Action; Id = [string]$f.Id } $false $false
            if ($btn -ne '') { $row.FindName('Act').Add_Click($script:H_ScAct) }
            [void]$ui.sc_List.Children.Add($row)
        }
    }
    if ($manual.Count -gt 0) {
        Add-HeadRow $ui.sc_List (('Elle yap' + [char]0x0131 + 'lacaklar (') + [string]$manual.Count + ')')
        foreach ($f in $manual) {
            $br = 'BrInfo'
            if ($f.Status -eq 'bad') { $br = 'BrBad' } elseif ($f.Status -eq 'warn') { $br = 'BrWarn' }
            $row = New-ItemRow @{ Title = [string]$f.Title; Detail = [string]$f.Detail; Tag = (Get-CatLabel ([string]$f.Cat)); BrCol = $br } @{ Id = [string]$f.Id } $false $false
            [void]$ui.sc_List.Children.Add($row)
        }
    }
    Update-FxFoot
}

# ---------------- ag topolojisi ----------------
$script:TopoRisky = @(21, 22, 23, 135, 139, 445, 1433, 3306, 3389, 5432, 5900, 5985, 5986)

function Set-CanvasPos($El, [double]$X, [double]$Y) {
    [System.Windows.Controls.Canvas]::SetLeft($El, $X)
    [System.Windows.Controls.Canvas]::SetTop($El, $Y)
}

$script:H_TopoEnter = {
    param($s, $e)
    try {
        $ui.pn_TopoTipTxt.Text = (Tr $([string]$s.Tag))
        $pos = [System.Windows.Input.Mouse]::GetPosition($ui.pn_Topo)
        $x = $pos.X + 16; $y = $pos.Y + 14
        if ($x + 270 -gt $ui.pn_Topo.ActualWidth) { $x = [math]::Max(4, $pos.X - 280) }
        if ($y + 110 -gt $ui.pn_Topo.ActualHeight) { $y = [math]::Max(4, $ui.pn_Topo.ActualHeight - 120) }
        Set-CanvasPos $ui.pn_TopoTip $x $y
        $ui.pn_TopoTip.Visibility = $script:VisOn
    } catch { }
}
$script:H_TopoLeave = { param($s, $e) try { $ui.pn_TopoTip.Visibility = $script:VisOff } catch { } }

function Add-TopoEdge([double]$X1, [double]$Y1, [double]$X2, [double]$Y2, [double]$Weight, [string]$BrKey, [double]$Secs) {
    # Not: parametre adlariyla yalnizca buyuk/kucuk harfi farkli degisken kullanilmaz ($ax gibi),
    # aksi halde atama tipli parametreye yapilir ve "DoubleAnimation -> Double" hatasi olusur.
    $ln = New-Object System.Windows.Shapes.Line
    $ln.X1 = $X1; $ln.Y1 = $Y1; $ln.X2 = $X2; $ln.Y2 = $Y2
    $ln.Stroke = (Get-Br $BrKey)
    $ln.StrokeThickness = [math]::Min(3.5, 1.0 + $Weight / 5.0)
    $ln.Opacity = 0.45
    $ln.IsHitTestVisible = $false
    [void]$ui.pn_Topo.Children.Add($ln)
    $dot = New-Object System.Windows.Shapes.Ellipse
    $dot.Width = 5; $dot.Height = 5
    $dot.Fill = (Get-Br 'BrText')
    $dot.IsHitTestVisible = $false
    Set-CanvasPos $dot ($X1 - 2.5) ($Y1 - 2.5)
    [void]$ui.pn_Topo.Children.Add($dot)
    if ($script:ReduceMotion -eq $true) { return }
    try {
        $dsec = [double]$Secs
        if ($dsec -lt 0.5) { $dsec = 0.5 }
        $animX = New-Object System.Windows.Media.Animation.DoubleAnimation
        $animX.From = [double]($X1 - 2.5)
        $animX.To = [double]($X2 - 2.5)
        $animX.Duration = New-Object System.Windows.Duration -ArgumentList ([TimeSpan]::FromSeconds($dsec))
        $animX.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $animY = New-Object System.Windows.Media.Animation.DoubleAnimation
        $animY.From = [double]($Y1 - 2.5)
        $animY.To = [double]($Y2 - 2.5)
        $animY.Duration = New-Object System.Windows.Duration -ArgumentList ([TimeSpan]::FromSeconds($dsec))
        $animY.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $dot.BeginAnimation([System.Windows.Controls.Canvas]::LeftProperty, $animX)
        $dot.BeginAnimation([System.Windows.Controls.Canvas]::TopProperty, $animY)
    } catch {
        # Animasyon kurulamazsa nokta sabit kalir; topoloji yine cizilir
        Write-LogFile ('Topoloji animasyonu atlandi: ' + $_.Exception.Message)
    }
}

function Add-TopoNode([double]$Cx, [double]$Cy, [double]$R, [string]$BrKey, [string]$Label, [string]$Info) {
    $el = New-Object System.Windows.Shapes.Ellipse
    $el.Width = 2 * $R; $el.Height = 2 * $R
    $el.Fill = (Get-Br 'BrPanel2')
    $el.Stroke = (Get-Br $BrKey)
    $el.StrokeThickness = 2.5
    $el.Cursor = [System.Windows.Input.Cursors]::Hand
    $el.Tag = $Info
    $eff = New-Object System.Windows.Media.Effects.DropShadowEffect
    $eff.Color = ([System.Windows.Media.SolidColorBrush](Get-Br $BrKey)).Color
    $eff.BlurRadius = 14; $eff.ShadowDepth = 0; $eff.Opacity = 0.85
    $el.Effect = $eff
    $el.Add_MouseEnter($script:H_TopoEnter)
    $el.Add_MouseLeave($script:H_TopoLeave)
    Set-CanvasPos $el ($Cx - $R) ($Cy - $R)
    [void]$ui.pn_Topo.Children.Add($el)
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.Text = (Tr $($Label)); $tb.FontSize = 10.5; $tb.Foreground = (Get-Br 'BrDim'); $tb.Width = 110; $tb.TextAlignment = [System.Windows.TextAlignment]::Center
    $tb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis; $tb.IsHitTestVisible = $false
    Set-CanvasPos $tb ($Cx - 55) ($Cy + $R + 3)
    [void]$ui.pn_Topo.Children.Add($tb)
}

function Draw-ConnTopology {
    $snap = $script:TopoSnap
    if ($null -eq $snap) { return }
    $W = [double]$ui.pn_Topo.ActualWidth
    if ($W -lt 200) { $W = 760 }
    $H = [double]$ui.pn_Topo.Height
    $script:TopoW = $W
    $keep = $ui.pn_TopoTip
    $ui.pn_Topo.Children.Clear()
    [void]$ui.pn_Topo.Children.Add($keep)
    $keep.Visibility = $script:VisOff

    $ad = @($snap.Adapters)
    $ip = ''; $mac = ''
    if ($ad.Count -gt 0) { $ip = [string]$ad[0].Ip; $mac = [string]$ad[0].Mac }
    $pcx = 0.40 * $W; $pcy = 0.50 * $H
    $gwx = 0.62 * $W; $gwy = 0.50 * $H
    $inx = 0.86 * $W; $iny = 0.50 * $H
    $procs = @($snap.Procs | Select-Object -First 6)
    $remoteTotal = 0
    foreach ($p in $procs) { $remoteTotal += [int]$p.Count }

    # kenarlar once (dugumlerin altinda kalsin)
    Add-TopoEdge $pcx $pcy $gwx $gwy 6 'BrAccent' 2.4
    Add-TopoEdge $gwx $gwy $inx $iny ([math]::Min(20, $remoteTotal)) 'BrAccent2' 2.0
    $dns = @($snap.Dns | Select-Object -First 3)
    $dnsPos = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt $dns.Count; $i++) {
        $dx = $gwx + (($i - ($dns.Count - 1) / 2.0) * 0.10 * $W)
        $dy = 0.14 * $H
        [void]$dnsPos.Add(@($dx, $dy))
        Add-TopoEdge $gwx $gwy $dx $dy 3 'BrAccent' (2.6 + 0.3 * $i)
    }
    $pPos = New-Object System.Collections.ArrayList
    $n = $procs.Count
    for ($i = 0; $i -lt $n; $i++) {
        $deg = 180.0
        if ($n -gt 1) { $deg = 180.0 + ($i - ($n - 1) / 2.0) * (80.0 / ($n - 1)) * 1.0 }
        $rad = $deg * [math]::PI / 180.0
        $px = $pcx + 0.30 * $W * [math]::Cos($rad)
        $py = $pcy + 0.40 * $H * [math]::Sin($rad)
        [void]$pPos.Add(@($px, $py))
        Add-TopoEdge $pcx $pcy $px $py ([int]$procs[$i].Count) 'BrBlue' (2.2 + 0.25 * $i)
    }
    $lis = @($snap.Listen)
    $risky = @($lis | Where-Object { $script:TopoRisky -contains [int]$_.Port })
    $lx = $pcx; $ly = 0.88 * $H
    if ($lis.Count -gt 0) { Add-TopoEdge $pcx $pcy $lx $ly 3 'BrFaint' 3.0 }

    # dugumler
    $pcInfo = ('Bu bilgisayar' + "`r`n" + [string]$env:COMPUTERNAME + "`r`nIP: " + $ip + "`r`nMAC: " + $mac + ("`r`nEtkin ba" + [char]0x011F + "da" + [char]0x015F + "t" + [char]0x0131 + "r" + [char]0x0131 + "c" + [char]0x0131 + ": ") + [string]$ad.Count)
    Add-TopoNode $pcx $pcy 16 'BrAccent' 'Bu bilgisayar' $pcInfo
    $gw = ''
    if (@($snap.Gateways).Count -gt 0) { $gw = [string]@($snap.Gateways)[0] }
    Add-TopoNode $gwx $gwy 12 'BrAccent2' ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi') (('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi (y' + [char]0x00F6 + 'nlendirici)') + "`r`nAdres: " + $gw + ("`r`nT" + [char]0x00FC + "m internet trafi" + [char]0x011F + "i buradan ge" + [char]0x00E7 + "er."))
    Add-TopoNode $inx $iny 18 'BrBlue' ([string][char]0x0130 + 'nternet') (([string][char]0x0130 + 'nternet') + ("`r`nD" + [char]0x0131 + [char]0x015F + " ba" + [char]0x011F + "lant" + [char]0x0131 + " say" + [char]0x0131 + "s" + [char]0x0131 + ": ") + [string]$remoteTotal + ("`r`nEn " + [char]0x00E7 + "ok ba" + [char]0x011F + "lanan: ") + $(if ($procs.Count -gt 0) { [string]$procs[0].Name } else { '-' }))
    for ($i = 0; $i -lt $dns.Count; $i++) {
        Add-TopoNode ([double]$dnsPos[$i][0]) ([double]$dnsPos[$i][1]) 8 'BrAccent' ('DNS ' + [string]$dns[$i]) ('DNS sunucusu' + "`r`n" + [string]$dns[$i] + ("`r`nAlan adlar" + [char]0x0131 + "n" + [char]0x0131 + " IP adresine " + [char]0x00E7 + "evirir. A" + [char]0x011F + " sayfas" + [char]0x0131 + "ndan daha h" + [char]0x0131 + "zl" + [char]0x0131 + "s" + [char]0x0131 + "n" + [char]0x0131 + " se" + [char]0x00E7 + "ebilirsiniz."))
    }
    for ($i = 0; $i -lt $n; $i++) {
        $p = $procs[$i]
        $r = [math]::Min(12.0, 6.0 + [double]$p.Count / 3.0)
        $info = ([string]$p.Name + ("`r`nBa" + [char]0x011F + "lant" + [char]0x0131 + ": ") + [string]$p.Count + "`r`nUzak: " + (@($p.Remotes) -join ', '))
        Add-TopoNode ([double]$pPos[$i][0]) ([double]$pPos[$i][1]) $r 'BrBlue' ([string]$p.Name) $info
    }
    if ($lis.Count -gt 0) {
        $col = 'BrGold'
        if ($risky.Count -gt 0) { $col = 'BrBad' }
        $ports = @($lis | Select-Object -First 10 | ForEach-Object { [string]$_.Port + ' (' + [string]$_.Proc + ')' })
        $inf = (('D' + [char]0x0131 + [char]0x015F + 'ar' + [char]0x0131 + 'dan eri' + [char]0x015F + 'ilebilen portlar: ') + [string]$lis.Count + "`r`n" + ($ports -join ', '))
        if ($risky.Count -gt 0) { $inf += ("`r`nDikkat: " + [string]$risky.Count + ' hassas port (SMB/RDP/vb.) dinleniyor.') }
        Add-TopoNode $lx $ly 11 $col (('A' + [char]0x00E7 + [char]0x0131 + 'k portlar: ') + [string]$lis.Count) $inf
    }
    $ui.pn_TopoInfo.Text = (Tr $(([string]$remoteTotal + (' d' + [char]0x0131 + [char]0x015F + ' ba' + [char]0x011F + 'lant' + [char]0x0131 + ' ' + [char]0x00B7 + ' ') + [string]$lis.Count + (' dinleyen port ' + [char]0x00B7 + ' ') + $script:TopoAt.ToString('HH:mm:ss'))))
}

function Start-TopoScan([bool]$Queue = $true) {
    [void](Start-Async 'Topo' 'Job_Net' @{} {
        param($r)
        if ($null -eq $r) { return }
        $script:TopoSnap = $r
        $script:TopoAt = Get-Date
        if ($script:UiState.Page -eq 'panel') { Draw-Topology }
    } ('A' + [char]0x011F + ' topolojisi') $true $Queue)
}

# ---------------- hizli bakim ----------------
function Start-QuickMaint {
    $ids = @($script:Settings.MaintItems)
    $names = @()
    foreach ($id in $ids) { $c = Get-CatalogItem ([string]$id); if ($null -ne $c) { $names += (([string][char]0x2022 + ' ') + [string]$c.Title) } }
    if ($names.Count -eq 0) { Show-Toast ('Ayarlarda se' + [char]0x00E7 + 'ili bak' + [char]0x0131 + 'm ad' + [char]0x0131 + 'm' + [char]0x0131 + ' yok.') 'warn'; return }
    Show-Confirm ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm') (([string][char]0x015E + "u ad" + [char]0x0131 + "mlar " + [char]0x00E7 + "al" + [char]0x0131 + [char]0x015F + "acak:`r`n`r`n") + ($names -join "`r`n") + ("`r`n`r`nSilinen ge" + [char]0x00E7 + "ici dosyalar geri getirilemez; di" + [char]0x011F + "er ayarlar geri al" + [char]0x0131 + "nabilir.")) ('Ba' + [char]0x015F + 'lat') {
        [void](Start-Async 'Maint' 'Job_Maint' @{ Items = @(); Preview = $false } {
            param($r)
            if ($null -eq $r) { return }
            Show-Toast ([string]$r.Summary) 'good'
            Show-Notify ('Bak' + [char]0x0131 + 'm tamamland' + [char]0x0131) ([string]$r.Summary) 'good'
            $script:Settings = Get-Settings
            Update-QuickStatus
        } ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm'))
    }
}


# ---------------- Ag arayuzu ----------------
# ==================================================================
#  AG ARAYUZU: "Cihazlar" ve "Koruma" sekmeleri, panelde yerel ag haritasi, ag izleme
#  Tarama her zaman kullanici istegiyle baslar (ag izleme aciksa 5 dakikada bir sessiz tarama).
#  Engelleme yalnizca bu bilgisayarin guvenlik duvarina kural ekler; geri alinabilir.
# ==================================================================
$script:LanSnap = $null
$script:LanAt = [datetime]::MinValue
$script:LanQuiet = $false
$script:LanNotified = @{}
$script:TopoMode = 'lan'
$script:NpSnap = $null
$script:NpAt = [datetime]::MinValue
$script:NpSel = @{}
$script:DevPending = @()
$script:DevFocusMac = ''
$script:OptThen = $null
$script:DevRenameMac = ''
$script:NetWatchTimer = $null

function Set-OptValue([string]$Name, $Value) {
    $st = Get-Settings
    $st[$Name] = $Value
    Save-Settings $st
    $script:Settings = Get-Settings
}

function Get-AgeText([datetime]$At) {
    if ($At -eq [datetime]::MinValue) { return ('hi' + [char]0x00E7 + '') }
    $m = [int]((Get-Date) - $At).TotalMinutes
    if ($m -lt 1) { return ('az ' + [char]0x00F6 + 'nce') }
    if ($m -lt 60) { return ([string]$m + (' dk ' + [char]0x00F6 + 'nce')) }
    $h = [int][math]::Floor($m / 60)
    if ($h -lt 48) { return ([string]$h + (' sa ' + [char]0x00F6 + 'nce')) }
    return ([string][int][math]::Floor($h / 24) + (' g' + [char]0x00FC + 'n ' + [char]0x00F6 + 'nce'))
}

# Son tarama diskte duruyorsa panel acilir acilmaz onunla cizilir (yeni tarama baslatilmaz)
function Initialize-LanSnap {
    if ($null -ne $script:LanSnap) { return }
    $o = Read-LanLast
    if ($null -eq $o) { return }
    $o.Ok = $true
    $o.Alerts = @()
    $o.BlockedOffline = @()
    $at = [datetime]::MinValue
    try { $at = [datetime]::Parse([string]$o.At, [System.Globalization.CultureInfo]::InvariantCulture) } catch { }
    $script:LanSnap = $o
    $script:LanAt = $at
}

# ---------------- cihaz metinleri ----------------
function Get-DevBrKey($D) {
    if ($D.Blocked -eq $true) { return 'BrBad' }
    $ti = Get-DevTypeInfo ([string]$D.Type)
    if ($D.IsSelf -ne $true -and $D.IsGateway -ne $true -and @($D.Risks | Where-Object { $_.Sev -eq 'bad' }).Count -gt 0) { return 'BrBad' }
    return [string]$ti.Br
}

function Format-DevTag($D) {
    $ti = Get-DevTypeInfo ([string]$D.Type)
    $t = [string]$ti.L
    if ($D.IsSelf -eq $true) { return $t }
    if ([string]$D.Type -ne 'unknown') { $t += (' ' + [char]0x00B7 + ' %') + [string]$D.Conf }
    if ($D.Blocked -eq $true) { $t += (' ' + [char]0x00B7 + ' ENGELL' + [char]0x0130 + '') }
    elseif ($D.Fresh -eq $true) { $t += (' ' + [char]0x00B7 + ' YEN' + [char]0x0130 + '') }
    elseif ($D.New -eq $true -and $script:Settings.KnownDevices.Count -gt 0) { $t += (' ' + [char]0x00B7 + ' tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k de' + [char]0x011F + 'il') }
    return $t
}

function Format-DevDetail($D) {
    $p = New-Object System.Collections.ArrayList
    [void]$p.Add([string]$D.Ip)
    if ([string]$D.Mac -ne '') { [void]$p.Add([string]$D.Mac) }
    $sm = Get-DeviceSummary $D
    if ($sm -ne '') { [void]$p.Add($sm) }
    $line = $p -join (' ' + [char]0x00B7 + ' ')
    $rk = @($D.Risks)
    if ($rk.Count -gt 0 -and $D.Blocked -ne $true) {
        $t = [string]$rk[0].Text
        if ($t.Length -gt 120) { $t = $t.Substring(0, 117) + '...' }
        $line += "  $([char]0x2014)  Uyar$([char]0x0131): " + $t
    }
    return $line
}

function Get-DevDetailText($D) {
    $ti = Get-DevTypeInfo ([string]$D.Type)
    $l = New-Object System.Collections.ArrayList
    [void]$l.Add(('T' + [char]0x00FC + 'r: ') + [string]$ti.L + $(if ([string]$D.Type -ne 'unknown' -and $D.IsSelf -ne $true) { (' (g' + [char]0x00FC + 'ven %') + [string]$D.Conf + ')' } else { '' }))
    [void]$l.Add('Adres: ' + [string]$D.Ip)
    if ([string]$D.Mac -ne '') {
        $m = 'MAC: ' + [string]$D.Mac
        if ($D.Random -eq $true) { $m += (' (rastgele / ' + [char]0x00F6 + 'zel adres)') }
        [void]$l.Add($m)
    }
    if ([string]$D.Vendor -ne '') { [void]$l.Add(('' + [char]0x00DC + 'retici: ') + [string]$D.Vendor) }
    if ([string]$D.Model -ne '') { [void]$l.Add('Model: ' + [string]$D.Model) }
    if ([string]$D.Os -ne '') { [void]$l.Add('Sistem: ' + [string]$D.Os) }
    if ([string]$D.Name -ne '') { [void]$l.Add('Ad: ' + [string]$D.Name + ' (' + [string]$D.NameSrc + ')') }
    if ([string]$D.Workgroup -ne '') { [void]$l.Add(('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma grubu: ') + [string]$D.Workgroup) }
    $sv = @($D.Services)
    if ($sv.Count -gt 0) { [void]$l.Add(('Tan' + [char]0x0131 + 'tt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' hizmetler: ') + (($sv | Select-Object -First 12) -join ', ')) }
    $pt = @($D.Ports)
    if ($pt.Count -gt 0) { [void]$l.Add(('A' + [char]0x00E7 + '' + [char]0x0131 + 'k portlar: ') + ($pt -join ', ')) }
    if ([string]$D.HttpTitle -ne '') { [void]$l.Add(('Web aray' + [char]0x00FC + 'z' + [char]0x00FC + ' ba' + [char]0x015F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ': ') + [string]$D.HttpTitle) }
    if ([string]$D.FirstSeen -ne '') { [void]$l.Add(('' + [char]0x0130 + 'lk g' + [char]0x00F6 + 'r' + [char]0x00FC + 'lme: ') + ([string]$D.FirstSeen).Replace('T', ' ')) }
    $st = 'Durum: '
    if ($D.IsSelf -eq $true) { $st += 'bu bilgisayar' }
    elseif ($D.IsGateway -eq $true) { $st += ('a' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi (y' + [char]0x00F6 + 'nlendirici)') }
    elseif ($D.Known -eq $true) { $st += ('tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k') }
    else { $st += ('tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k de' + [char]0x011F + 'il') }
    if ($D.Blocked -eq $true) { $st += ', bu bilgisayarda engelli' }
    [void]$l.Add($st)
    $why = @($D.Why)
    if ($why.Count -gt 0) {
        [void]$l.Add('')
        [void]$l.Add(('Neden b' + [char]0x00F6 + 'yle d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'nd' + [char]0x00FC + 'k?'))
        foreach ($w in $why) { [void]$l.Add(('' + [char]0x2022 + ' ') + [string]$w) }
    }
    $rk = @($D.Risks)
    if ($rk.Count -gt 0) {
        [void]$l.Add('')
        [void]$l.Add('Dikkat edilecekler')
        foreach ($r in $rk) { [void]$l.Add(('' + [char]0x2022 + ' ') + [string]$r.Text) }
    }
    return ($l -join "`r`n")
}

function Show-DevDetail($D) {
    Show-Message (Get-DeviceTitle $D) (Get-DevDetailText $D)
}

# ---------------- tarama ----------------
function Start-LanScan([bool]$Deep = $false, [bool]$Quiet = $false) {
    $lbl = ('Yerel a' + [char]0x011F + ' taran' + [char]0x0131 + 'yor')
    if ($Deep) { $lbl = ('Yerel a' + [char]0x011F + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' taran' + [char]0x0131 + 'yor') }
    $script:LanQuiet = $Quiet
    [void](Start-Async 'LanScan' 'Job_LanScan' @{ Deep = $Deep } { param($r) Complete-LanScan $r } $lbl $Quiet $true)
}

function Complete-LanScan($R) {
    $quiet = ($script:LanQuiet -eq $true)
    if ($null -eq $R -or $R.Ok -ne $true) {
        $why = ('A' + [char]0x011F + ' taranamad' + [char]0x0131 + '.')
        if ($null -ne $R -and [string]$R.Error -ne '') { $why = [string]$R.Error }
        if (-not $quiet) { Show-Toast $why 'warn' }
        return
    }
    $script:Settings = Get-Settings
    $script:LanSnap = $R
    $script:LanAt = Get-Date
    $script:HealthAt = [datetime]::MinValue
    if (-not $quiet) {
        $n = @($R.Devices).Count
        $nn = @($R.Devices | Where-Object { $_.New -eq $true }).Count
        $msg = [string]$n + ' cihaz bulundu'
        if ($script:Settings.KnownDevices.Count -gt 0 -and $nn -gt 0) { $msg += ', ' + [string]$nn + (' tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k olmayan') }
        Show-Toast ($msg + '.') 'good'
    }
    foreach ($a in @($R.Alerts)) {
        $k = [string]$a.Key + '|' + [string]$a.Text
        if ($script:LanNotified.ContainsKey($k)) { continue }
        $script:LanNotified[$k] = $true
        $kind = 'warn'
        if ([string]$a.Sev -eq 'bad') { $kind = 'bad' }
        if ($quiet -or [string]$a.Sev -eq 'bad') {
            Show-Toast ([string]$a.Text) $kind
            Show-Notify ('A' + [char]0x011F + ' uyar' + [char]0x0131 + 's' + [char]0x0131 + '') ([string]$a.Text) $kind
        }
    }
    $pg = [string]$script:UiState.Page
    if ($pg -eq 'panel' -and $script:TopoMode -eq 'lan' -and $null -ne $ui['pn_Topo']) { Draw-Topology }
    if ($pg -eq 'network' -and $script:NwTab -eq 'dev') { Render-NwDev }
}

# Port gerektiren islemler icin istege bagli ozellik onayi
function Confirm-OptScan([scriptblock]$Then) {
    if (Test-Opt 'OptScan') { & $Then; return }
    $script:OptThen = $Then
    Show-Confirm ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' a' + [char]0x011F + ' taramas' + [char]0x0131 + '') ("Ayr$([char]0x0131)nt$([char]0x0131)l$([char]0x0131) tarama, bulunan her cihaz$([char]0x0131)n yayg$([char]0x0131)n hizmet portlar$([char]0x0131)na (yaz$([char]0x0131)c$([char]0x0131), kamera, SMB, uzak masa$([char]0x00FC)st$([char]0x00FC) vb.) tek ba$([char]0x011F)lant$([char]0x0131) dener ve web aray$([char]0x00FC)z$([char]0x00FC) ba$([char]0x015F)l$([char]0x0131)$([char]0x011F)$([char]0x0131)n$([char]0x0131) okur. Cihaz t$([char]0x00FC)r$([char]0x00FC)n$([char]0x00FC) ve a$([char]0x00E7)$([char]0x0131)k riskleri bu sayede daha do$([char]0x011F)ru bulur.`r`n`r`nYaln$([char]0x0131)zca kendi a$([char]0x011F)$([char]0x0131)n$([char]0x0131)zda kullan$([char]0x0131)n. Baz$([char]0x0131) g$([char]0x00FC)venlik yaz$([char]0x0131)l$([char]0x0131)mlar$([char]0x0131) bu i$([char]0x015F)lemi uyar$([char]0x0131)yla kar$([char]0x015F)$([char]0x0131)lar. Bu $([char]0x00F6)zellik iste$([char]0x011F)e ba$([char]0x011F)l$([char]0x0131)d$([char]0x0131)r ve $([char]0x015F)u an kapal$([char]0x0131); a$([char]0x00E7)$([char]0x0131)p devam edilsin mi? (Ayarlar > $([char]0x0130)ste$([char]0x011F)e ba$([char]0x011F)l$([char]0x0131) $([char]0x00F6)zelliklerden kapatabilirsiniz.)") ('A' + [char]0x00E7 + ' ve devam et') {
        Set-OptValue 'OptScan' $true
        $t = $script:OptThen
        $script:OptThen = $null
        if ($null -ne $t) { & $t }
    }
}

# ---------------- Cihazlar sekmesi ----------------
$script:H_DevInfo = { param($s, $e) Invoke-Safe { Show-DevDetail $s.Tag.Dev } ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') }
$script:H_DevBlockOne = {
    param($s, $e)
    Invoke-Safe {
        $on = (-not ($s.Tag.Dev.Blocked -eq $true))
        Start-DevBlock @($s.Tag) $on
    } 'Engelle'
}

function Render-NwDev {
    $ui.nw_List.Children.Clear()
    Initialize-LanSnap
    $s = $script:LanSnap
    if ($null -eq $s) {
        $ui.nw_DevSum.Text = (Tr $(('Hen' + [char]0x00FC + 'z tarama yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '.')))
        Add-Note $ui.nw_List (('' + [char]0x201C + 'A' + [char]0x011F + '' + [char]0x0131 + ' tara' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesi yerel a' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zdaki t' + [char]0x00FC + 'm cihazlar' + [char]0x0131 + ' bulur ve her birinin t' + [char]0x00FC + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' (telefon, TV, yaz' + [char]0x0131 + 'c' + [char]0x0131 + ', kamera, y' + [char]0x00F6 + 'nlendirici vb.) belirler. Yaln' + [char]0x0131 + 'zca kendi ' + [char]0x00F6 + 'zel a' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z taran' + [char]0x0131 + 'r; cihazlara hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmez.'))
        $ui.nw_Foot.Text = (Tr $(''))
        return
    }
    $devs = @($s.Devices)
    $known = @($script:Settings.KnownDevices).Count
    $nNew = @($devs | Where-Object { $_.New -eq $true }).Count
    $nBlk = @($devs | Where-Object { $_.Blocked -eq $true }).Count
    $c = $s.Ctx
    $mode = ('h' + [char]0x0131 + 'zl' + [char]0x0131 + '')
    if ($s.Deep -eq $true) { $mode = ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + '') }
    $sum = [string]$devs.Count + ' cihaz'
    if ($known -gt 0) { $sum += (' ' + [char]0x00B7 + ' ') + [string]$nNew + (' tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k olmayan') }
    if ($nBlk -gt 0) { $sum += (' ' + [char]0x00B7 + ' ') + [string]$nBlk + ' engelli' }
    $net = [string]$c.Ip + '/' + [string]$c.Prefix
    if ([string]$c.Ssid -ne '') { $net = [string]$c.Ssid + (' ' + [char]0x00B7 + ' ') + $net }
    $ui.nw_DevSum.Text = (Tr $($sum + ('   |   A' + [char]0x011F + ': ') + $net + '   |   ' + $mode + ' tarama, ' + (Get-AgeText $script:LanAt)))

    $alerts = @($s.Alerts)
    if ($alerts.Count -gt 0) {
        Add-HeadRow $ui.nw_List (('Uyar' + [char]0x0131 + 'lar (') + [string]$alerts.Count + ')')
        foreach ($a in $alerts) {
            $k = 'warn'; if ([string]$a.Sev -eq 'bad') { $k = 'bad' }
            Add-Note $ui.nw_List ([string]$a.Text) $k
        }
    }
    if ($known -eq 0) {
        Add-Note $ui.nw_List (('Hen' + [char]0x00FC + 'z tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k i' + [char]0x015F + 'aretlenmi' + [char]0x015F + ' cihaz yok. Kendi cihazlar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin (' + [char]0x201C + 'Tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k i' + [char]0x015F + 'aretle' + [char]0x201D + ' ya da ' + [char]0x201C + 'Hepsini tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k say' + [char]0x201D + '); bundan sonra listede olmayan her cihaz ' + [char]0x201C + 'yeni' + [char]0x201D + ' diye ' + [char]0x00F6 + 'ne ' + [char]0x00E7 + '' + [char]0x0131 + 'kar ve a' + [char]0x011F + ' izleme a' + [char]0x00E7 + '' + [char]0x0131 + 'ksa bildirim gelir.'))
    }
    $flt = Get-FilterText $ui.nw_DevFilter
    $onlyNew = ($ui.nw_DevNew.IsChecked -eq $true)
    $shown = 0
    $rows = New-Object System.Collections.ArrayList
    foreach ($d in $devs) {
        if ($onlyNew -and $d.New -ne $true) { continue }
        if ($flt -ne '') {
            $hay = ConvertTo-AsciiKey ((Get-DeviceTitle $d) + ' ' + [string]$d.Ip + ' ' + [string]$d.Mac + ' ' + [string]$d.Vendor + ' ' + [string]$d.Model + ' ' + [string](Get-DevTypeInfo ([string]$d.Type)).L + ' ' + [string]$d.Os)
            if ($hay.IndexOf($flt) -lt 0) { continue }
        }
        [void]$rows.Add($d)
    }
    Add-HeadRow $ui.nw_List ('Cihazlar (' + [string]$rows.Count + ')')
    foreach ($d in $rows) {
        $chk = ($d.IsSelf -ne $true -and $d.IsGateway -ne $true -and [string]$d.MacKey -ne '')
        $b2 = ''
        if ($chk) { if ($d.Blocked -eq $true) { $b2 = ('Engeli kald' + [char]0x0131 + 'r') } else { $b2 = 'Engelle' } }
        $row = New-ItemRow @{ Title = (Get-DeviceTitle $d); Detail = (Format-DevDetail $d); Tag = (Format-DevTag $d); BrCol = (Get-DevBrKey $d); Btn1 = ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ''); Btn2 = $b2 } @{ Mac = [string]$d.MacKey; Dev = $d } $chk $false
        $row.FindName('Act').Add_Click($script:H_DevInfo)
        if ($b2 -ne '') { $row.FindName('Act2').Add_Click($script:H_DevBlockOne) }
        [void]$ui.nw_List.Children.Add($row)
        $shown++
    }
    if ($shown -eq 0) { Add-Note $ui.nw_List ('S' + [char]0x00FC + 'zgece uyan cihaz yok.') }
    $off = @($s.BlockedOffline)
    if ($off.Count -gt 0) {
        Add-HeadRow $ui.nw_List (('Engelli ama ' + [char]0x015F + 'u an a' + [char]0x011F + 'da g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nmeyen (') + [string]$off.Count + ')')
        foreach ($b in $off) {
            $od = @{ MacKey = [string]$b.Mac; Mac = (Format-Mac ([string]$b.Mac)); Ip = [string]$b.Ip; Name = [string]$b.Name; Type = 'unknown'; Blocked = $true; IsSelf = $false; IsGateway = $false; Offline = $true; Why = @(); Risks = @(); Services = @(); Ports = @() }
            $ttl = $b.Name; if ([string]$ttl -eq '') { $ttl = Format-Mac ([string]$b.Mac) }
            $row = New-ItemRow @{ Title = [string]$ttl; Detail = ([string]$b.Ip + (' ' + [char]0x00B7 + ' ') + (Format-Mac ([string]$b.Mac))); Tag = ('ENGELL' + [char]0x0130 + ' ' + [char]0x00B7 + ' ' + [char]0x00E7 + 'evrimd' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ''); BrCol = 'BrBad'; Btn2 = ('Engeli kald' + [char]0x0131 + 'r') } @{ Mac = [string]$b.Mac; Dev = $od } $true $false
            $row.FindName('Act2').Add_Click($script:H_DevBlockOne)
            [void]$ui.nw_List.Children.Add($row)
        }
    }
    $ui.nw_Foot.Text = (Tr $((('Engelle: yaln' + [char]0x0131 + 'zca bu bilgisayar o cihazla konu' + [char]0x015F + 'maz (g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kural' + [char]0x0131 + '; Ge' + [char]0x00E7 + 'mi' + [char]0x015F + '' + [char]0x2019 + 'ten geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r). Cihaz' + [char]0x0131 + ' a' + [char]0x011F + 'dan atmak i' + [char]0x00E7 + 'in y' + [char]0x00F6 + 'nlendirici gerekir: ' + [char]0x201C + 'A' + [char]0x011F + 'dan atma ad' + [char]0x0131 + 'mlar' + [char]0x0131 + '' + [char]0x201D + '.'))))
    if ([string]$script:DevFocusMac -ne '') {
        $fr = Get-RowByKey $ui.nw_List 'Mac' ([string]$script:DevFocusMac)
        $script:DevFocusMac = ''
        if ($null -ne $fr) { try { $fr.BringIntoView() } catch { } }
    }
}

function Get-DevSelection {
    $sel = Get-CheckedData $ui.nw_List
    return , @($sel)
}

function Start-DevBlock($Rows, [bool]$On) {
    $arr = @($Rows | Where-Object { $null -ne $_ -and $null -ne $_.Dev -and $_.Dev.IsSelf -ne $true -and $_.Dev.IsGateway -ne $true })
    if ($arr.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce engellenecek cihaz' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin (bu bilgisayar ve y' + [char]0x00F6 + 'nlendirici engellenemez).') 'warn'; return }
    $steps = New-Object System.Collections.ArrayList
    $names = New-Object System.Collections.ArrayList
    foreach ($r in $arr) {
        [void]$steps.Add((New-DevBlockStep $r.Dev $On))
        [void]$names.Add((Get-DeviceTitle $r.Dev) + ' (' + [string]$r.Dev.Ip + ')')
    }
    $script:DevPending = $steps.ToArray()
    if ($On) {
        $txt = (Format-NameList $names 10) + "`r`n`r`nBu bilgisayar bu cihazlarla konu$([char]0x015F)may$([char]0x0131) keser (dosya payla$([char]0x015F)$([char]0x0131)m$([char]0x0131), yaz$([char]0x0131)c$([char]0x0131), ekran yans$([char]0x0131)tma vb.). Cihaz a$([char]0x011F)dan at$([char]0x0131)lmaz; bunun i$([char]0x00E7)in y$([char]0x00F6)nlendirici gerekir. Kural Windows G$([char]0x00FC)venlik Duvar$([char]0x0131)$([char]0x2019)nda $([char]0x201C)Multimizer cihaz engeli$([char]0x201D) grubunda g$([char]0x00F6)r$([char]0x00FC)n$([char]0x00FC)r; Ge$([char]0x00E7)mi$([char]0x015F) sayfas$([char]0x0131)ndan ya da buradan geri al$([char]0x0131)n$([char]0x0131)r."
        Show-Confirm ('Cihaz' + [char]0x0131 + ' bu bilgisayarda engelle') $txt 'Engelle' { Start-PlanJob $script:DevPending 'Cihaz engelleniyor' $false $false { Start-LanScan $false } }
    } else {
        Show-Confirm ('Engeli kald' + [char]0x0131 + 'r') ((Format-NameList $names 10) + "`r`n`r`nBu cihazlarla ba$([char]0x011F)lant$([char]0x0131) yeniden serbest kal$([char]0x0131)r.") ('Kald' + [char]0x0131 + 'r') { Start-PlanJob $script:DevPending ('Engel kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { Start-LanScan $false } }
    }
}

function Set-DevKnown($Macs, [bool]$Known) {
    $st = Get-Settings
    $set = @{}
    foreach ($m in @($st.KnownDevices)) { $k = ConvertTo-MacKey ([string]$m); if ($k -ne '') { $set[$k] = $true } }
    foreach ($m in @($Macs)) {
        $k = ConvertTo-MacKey ([string]$m)
        if ($k -eq '') { continue }
        if ($Known) { $set[$k] = $true } else { $set.Remove($k) }
    }
    $st.KnownDevices = @($set.Keys | Sort-Object | ForEach-Object { Format-Mac ([string]$_) })
    Save-Settings $st
    $script:Settings = Get-Settings
    # anlik yansit
    if ($null -ne $script:LanSnap) {
        $ks = @{}
        foreach ($m in @($script:Settings.KnownDevices)) { $ks[(ConvertTo-MacKey ([string]$m))] = $true }
        foreach ($x in @($script:LanSnap.Devices)) {
            $mk = [string]$x.MacKey
            $x.Known = ($mk -ne '' -and $ks.ContainsKey($mk))
            $x.New = ((-not $x.Known) -and $x.IsSelf -ne $true -and $x.IsGateway -ne $true)
            if ($x.Known) { $x.Fresh = $false }
        }
    }
}

function Start-DevRename($Row) {
    $d = $Row.Dev
    $script:DevRenameMac = [string]$d.MacKey
    Show-Input ('Cihaz' + [char]0x0131 + ' adland' + [char]0x0131 + 'r') (('' + [char]0x201C + '') + (Get-DeviceTitle $d) + ('' + [char]0x201D + ' i' + [char]0x00E7 + 'in g' + [char]0x00F6 + 'r' + [char]0x00FC + 'necek ad (bo' + [char]0x015F + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'rsan' + [char]0x0131 + 'z cihaz' + [char]0x0131 + 'n kendi bildirdi' + [char]0x011F + 'i ad kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'r):')) ([string]$d.UserName) {
        param($txt)
        $mac = [string]$script:DevRenameMac
        $name = ConvertTo-CleanText ([string]$txt) 40
        $st = Get-Settings
        $map = @{}
        if ($st.DeviceNames -is [hashtable]) { $map = $st.DeviceNames }
        foreach ($k in @($map.Keys)) { if ((ConvertTo-MacKey ([string]$k)) -eq $mac) { $map.Remove($k) } }
        if ($name -ne '') { $map[(Format-Mac $mac)] = $name }
        $st.DeviceNames = $map
        Save-Settings $st
        $script:Settings = Get-Settings
        if ($null -ne $script:LanSnap) {
            foreach ($x in @($script:LanSnap.Devices)) {
                if ([string]$x.MacKey -eq $mac) {
                    $x.UserName = $name
                    if ($name -ne '') { $x.Name = $name } else { $x.Name = [string]$x.AutoName }
                }
            }
        }
        if ($script:NwTab -eq 'dev') { Render-NwDev }
    }
}

function Show-KickGuide($D) {
    $gw = ''
    if ($null -ne $script:LanSnap) { $gw = [string]$script:LanSnap.Ctx.Gateway }
    $nm = Get-DeviceTitle $D
    $txt = $nm + ' (' + [string]$D.Ip + ', MAC ' + [string]$D.Mac + ") cihaz$([char]0x0131)n$([char]0x0131) a$([char]0x011F)dan atmak i$([char]0x00E7)in y$([char]0x00F6)nlendiricinin y$([char]0x00F6)netim sayfas$([char]0x0131) gerekir. Bu uygulama ba$([char]0x015F)ka cihazlar$([char]0x0131)n ba$([char]0x011F)lant$([char]0x0131)s$([char]0x0131)na m$([char]0x00FC)dahale etmez; yaln$([char]0x0131)zca sizin y$([char]0x00F6)nlendiricinizde, sizin yetkinizle yap$([char]0x0131)labilecek ad$([char]0x0131)mlar$([char]0x0131) g$([char]0x00F6)sterir.`r`n`r`n"
    $txt += "1. Y$([char]0x00F6)nlendirici sayfas$([char]0x0131)n$([char]0x0131) a$([char]0x00E7)$([char]0x0131)n: http://" + $gw + " (kullan$([char]0x0131)c$([char]0x0131) ad$([char]0x0131) ve parola genelde y$([char]0x00F6)nlendiricinin alt$([char]0x0131)ndaki etikette ya da internet sa$([char]0x011F)lay$([char]0x0131)c$([char]0x0131)n$([char]0x0131)z$([char]0x0131)n belgesinde yazar).`r`n"
    $txt += "2. $([char]0x201C)Ba$([char]0x011F)l$([char]0x0131) cihazlar$([char]0x201D), $([char]0x201C)A$([char]0x011F) haritas$([char]0x0131)$([char]0x201D), $([char]0x201C)Wi-Fi > MAC filtresi$([char]0x201D) ya da $([char]0x201C)Ebeveyn denetimi$([char]0x201D) b$([char]0x00F6)l$([char]0x00FC)m$([char]0x00FC)nde bu MAC adresini bulun: " + [string]$D.Mac + ". $([char]0x201C)Engelle / Kara liste$([char]0x201D) se$([char]0x00E7)ene$([char]0x011F)ini ya da MAC filtresini kullan$([char]0x0131)n.`r`n"
    $txt += "3. Cihaz sizin de$([char]0x011F)ilse ayr$([char]0x0131)ca Wi-Fi parolas$([char]0x0131)n$([char]0x0131) de$([char]0x011F)i$([char]0x015F)tirin (WPA2-AES ya da WPA3), WPS$([char]0x2019)i kapat$([char]0x0131)n ve y$([char]0x00F6)netici parolas$([char]0x0131)n$([char]0x0131) varsay$([char]0x0131)landan de$([char]0x011F)i$([char]0x015F)tirin. Parolay$([char]0x0131) de$([char]0x011F)i$([char]0x015F)tirince t$([char]0x00FC)m cihazlar d$([char]0x00FC)$([char]0x015F)er; kendi cihazlar$([char]0x0131)n$([char]0x0131)z$([char]0x0131) yeni parolayla yeniden ba$([char]0x011F)lars$([char]0x0131)n$([char]0x0131)z.`r`n"
    if ($D.Random -eq $true) { $txt += "`r`nNot: Bu cihaz rastgele ($([char]0x00F6)zel) MAC adresi kullan$([char]0x0131)yor; adres her a$([char]0x011F) i$([char]0x00E7)in sabit olsa da cihaz $([char]0x00F6)zelli$([char]0x011F)i kapat$([char]0x0131)rsa yeni bir adresle gelebilir. Bu y$([char]0x00FC)zden parola de$([char]0x011F)i$([char]0x015F)tirmek MAC filtresinden daha kal$([char]0x0131)c$([char]0x0131)d$([char]0x0131)r.`r`n" }
    $txt += "`r`n$([char]0x201C)A$([char]0x00E7)$([char]0x201D) dedi$([char]0x011F)inizde MAC adresi panoya kopyalan$([char]0x0131)r ve y$([char]0x00F6)nlendirici sayfas$([char]0x0131) taray$([char]0x0131)c$([char]0x0131)da a$([char]0x00E7)$([char]0x0131)l$([char]0x0131)r."
    $script:KickMac = [string]$D.Mac
    $script:KickGw = $gw
    Show-Confirm ('A' + [char]0x011F + 'dan ' + [char]0x00E7 + '' + [char]0x0131 + 'karma ad' + [char]0x0131 + 'mlar' + [char]0x0131 + '') $txt ('A' + [char]0x00E7 + '') {
        try { [System.Windows.Clipboard]::SetText([string]$script:KickMac) } catch { }
        if ([string]$script:KickGw -ne '') { Open-Url ('http://' + [string]$script:KickGw + '/') }
    }
}

function Start-DevPortCheck($D) {
    $script:PortHost = [string]$D.Ip
    Confirm-OptScan {
        [void](Start-Async 'PortCheck' 'Job_PortCheck' @{ Host = $script:PortHost } {
            param($r)
            if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Port denetimi yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'warn'; return }
            $t = [string]$r.Text
            if ($t -eq '') { $t = ('Yayg' + [char]0x0131 + 'n portlar' + [char]0x0131 + 'n hi' + [char]0x00E7 + 'biri a' + [char]0x00E7 + '' + [char]0x0131 + 'k de' + [char]0x011F + 'il.') }
            Show-Message (('A' + [char]0x00E7 + '' + [char]0x0131 + 'k portlar: ') + [string]$r.Host) $t
        } (('Portlara bak' + [char]0x0131 + 'l' + [char]0x0131 + 'yor')))
    }
}

# ---------------- Koruma sekmesi ----------------
function Start-NpScan {
    [void](Start-Async 'NetProtect' 'Job_NetProtect' @{} { param($r) Complete-NpScan $r } ('A' + [char]0x011F + ' korumas' + [char]0x0131 + ' denetleniyor') $false $true)
}

function Complete-NpScan($R) {
    if ($null -eq $R) { Show-Toast ('A' + [char]0x011F + ' korumas' + [char]0x0131 + ' denetlenemedi; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn'; return }
    $script:NpSnap = $R
    $script:NpAt = Get-Date
    if ([string]$script:UiState.Page -eq 'network' -and $script:NwTab -eq 'prot') { Render-NwProt }
}

function Get-CatTr([string]$C) {
    switch ($C) {
        'Public' { return 'Genel' }
        'Private' { return ('' + [char]0x00D6 + 'zel') }
        'DomainAuthenticated' { return ('Etki alan' + [char]0x0131 + '') }
        default { return $C }
    }
}

function Get-DnsVerdict([string]$Ip, [string]$Gw) {
    $known = @{ '1.1.1.1' = 'Cloudflare'; '1.0.0.1' = 'Cloudflare'; '8.8.8.8' = 'Google'; '8.8.4.4' = 'Google'; '9.9.9.9' = 'Quad9'; '149.112.112.112' = 'Quad9'; '208.67.222.222' = 'OpenDNS'; '208.67.220.220' = 'OpenDNS'; '94.140.14.14' = 'AdGuard'; '94.140.15.15' = 'AdGuard' }
    if ($Ip -eq $Gw) { return @{ Text = ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi (y' + [char]0x00F6 + 'nlendirici) ' + [char]0x2014 + ' normal'); Br = 'BrGood' } }
    if ($known.ContainsKey($Ip)) { return @{ Text = ('Tan' + [char]0x0131 + 'nan genel DNS: ') + [string]$known[$Ip]; Br = 'BrGood' } }
    if (Test-PrivateIp $Ip) { return @{ Text = ('Yerel adres (Pi-hole ya da ikinci bir y' + [char]0x00F6 + 'nlendirici olabilir)'); Br = 'BrAccent' } }
    return @{ Text = ('Tan' + [char]0x0131 + 'nmayan genel adres: internet sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'nki olabilir; tan' + [char]0x0131 + 'm' + [char]0x0131 + 'yorsan' + [char]0x0131 + 'z DNS ele ge' + [char]0x00E7 + 'irilmi' + [char]0x015F + ' olabilir'); Br = 'BrWarn' }
}

$script:H_NpChk = { param($s, $e) $script:NpSel[[string]$s.Tag] = ($s.IsChecked -eq $true) }
$script:H_NpFix = { param($s, $e) Invoke-Safe { Start-FixFlow @($s.Tag.Item) (('D' + [char]0x00FC + 'zeltmeyi uygula')) } ('D' + [char]0x00FC + 'zeltme') }
$script:H_NpProfile = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        $want = 'Public'
        if ([string]$d.Cat -eq 'Public') { $want = 'Private' }
        $script:NpStep = @(@{ Id = 'NetProf' + [string]$d.Index; Title = ('A' + [char]0x011F + ' profilini ') + (Get-CatTr $want) + ' yap: ' + [string]$d.Name; Ops = @(@{ T = 'NetProfile'; Index = [int]$d.Index; Alias = [string]$d.Name; Category = $want }); Reboot = $false })
        $why = ('Genel profilde bilgisayar' + [char]0x0131 + 'n' + [char]0x0131 + 'z a' + [char]0x011F + 'daki di' + [char]0x011F + 'er cihazlara g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nmez ve payla' + [char]0x015F + '' + [char]0x0131 + 'mlar kapal' + [char]0x0131 + ' kal' + [char]0x0131 + 'r (kafe, otel, havaliman' + [char]0x0131 + ' i' + [char]0x00E7 + 'in). ' + [char]0x00D6 + 'zel profil yaln' + [char]0x0131 + 'zca g' + [char]0x00FC + 'vendi' + [char]0x011F + 'iniz ev/i' + [char]0x015F + ' a' + [char]0x011F + '' + [char]0x0131 + ' i' + [char]0x00E7 + 'indir.')
        Show-Confirm ('A' + [char]0x011F + ' profilini de' + [char]0x011F + 'i' + [char]0x015F + 'tir') ([string]$d.Name + (' a' + [char]0x011F + '' + [char]0x0131 + ' ') + (Get-CatTr $want) + (' yap' + [char]0x0131 + 'lacak.') + "`r`n`r`n" + $why + "`r`n`r`nGeri al$([char]0x0131)nabilir.") ('De' + [char]0x011F + 'i' + [char]0x015F + 'tir') { Start-PlanJob $script:NpStep ('A' + [char]0x011F + ' profili de' + [char]0x011F + 'i' + [char]0x015F + 'tiriliyor') $false $false { Start-NpScan } }
    } 'Profil'
}
$script:H_NpPin = {
    param($s, $e)
    Invoke-Safe {
        $i = $s.Tag
        if ([string]$i.GwMac -eq '' -or [string]$i.Gateway -eq '') { Show-Toast ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idinin MAC adresi okunamad' + [char]0x0131 + '.') 'warn'; return }
        $mac = [string]$i.Baseline
        if ($mac -eq '') { $mac = [string]$i.GwMac }
        $script:NpStep = @(@{ Id = 'ArpPin'; Title = ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idini sabitle: ') + [string]$i.Gateway; Ops = @(@{ T = 'ArpPin'; Ip = [string]$i.Gateway; Mac = $mac; Index = [int]$i.Index }); Reboot = $false })
        Show-Confirm ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idini sabitle') (('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi ') + [string]$i.Gateway + ' bu oturum boyunca ' + (Format-Mac $mac) + " MAC adresine sabitlenir. A$([char]0x011F)daki bir cihaz kendini y$([char]0x00F6)nlendirici gibi tan$([char]0x0131)tsa (ARP sahtecili$([char]0x011F)i) bile trafi$([char]0x011F)iniz bu adrese gider.`r`n`r`nYeniden ba$([char]0x015F)lat$([char]0x0131)nca kay$([char]0x0131)t kalkar; y$([char]0x00F6)nlendiriciyi ger$([char]0x00E7)ekten de$([char]0x011F)i$([char]0x015F)tirdiyseniz ba$([char]0x011F)lant$([char]0x0131) kopar, Ge$([char]0x00E7)mi$([char]0x015F) sayfas$([char]0x0131)ndan geri al$([char]0x0131)n.") 'Sabitle' { Start-PlanJob $script:NpStep ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi sabitleniyor') $false $false { Start-NpScan } }
    } 'Sabitle'
}
$script:H_NpTrust = {
    param($s, $e)
    Invoke-Safe {
        Show-Confirm ('Yeni a' + [char]0x011F + ' ge' + [char]0x00E7 + 'idine g' + [char]0x00FC + 'ven') ("A$([char]0x011F) ge$([char]0x00E7)idinin $([char]0x015F)u anki MAC adresi g$([char]0x00FC)venilir olarak kaydedilecek. Y$([char]0x00F6)nlendiriciyi kendiniz de$([char]0x011F)i$([char]0x015F)tirdiyseniz ya da farkl$([char]0x0131) bir a$([char]0x011F)a ge$([char]0x00E7)tiyseniz bunu yap$([char]0x0131)n; aksi h$([char]0x00E2)lde uyar$([char]0x0131)y$([char]0x0131) yok saymay$([char]0x0131)n.") ('G' + [char]0x00FC + 'ven') {
            [void](Start-Async 'GwTrust' 'Job_Action' @{ Key = 'GwTrust' } { param($r) Start-NpScan } ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi kaydediliyor'))
        }
    } ('G' + [char]0x00FC + 'ven')
}

function Get-NpSelectedItems {
    $out = New-Object System.Collections.ArrayList
    if ($null -eq $script:NpSnap) { return , $out.ToArray() }
    $fl = Get-FixList $script:NpSnap.Findings
    foreach ($it in $fl) { if ($script:NpSel[[string]$it.Id] -eq $true) { [void]$out.Add($it) } }
    return , $out.ToArray()
}

function Render-NwProt {
    $ui.nw_List.Children.Clear()
    $s = $script:NpSnap
    $ui.nw_Watch.IsChecked = ($script:Settings.NetWatch -eq $true)
    if ($null -eq $s) {
        Add-Note $ui.nw_List ('A' + [char]0x011F + ' korumas' + [char]0x0131 + ' denetleniyor...')
        Start-NpScan
        return
    }
    $i = $s.Info
    # genel Wi-Fi modu
    $row = New-ItemRow @{ Title = 'Genel Wi-Fi modu'; Detail = ('Kafe, otel, havaliman' + [char]0x0131 + ' gibi herkese a' + [char]0x00E7 + '' + [char]0x0131 + 'k a' + [char]0x011F + 'lar i' + [char]0x00E7 + 'in s' + [char]0x0131 + 'k' + [char]0x0131 + ' koruma: ba' + [char]0x011F + 'l' + [char]0x0131 + ' a' + [char]0x011F + 'lar Genel profile al' + [char]0x0131 + 'n' + [char]0x0131 + 'r, gelen ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar engellenir, Genel profilde a' + [char]0x011F + ' ke' + [char]0x015F + 'fi ve dosya payla' + [char]0x015F + '' + [char]0x0131 + 'm' + [char]0x0131 + ' kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'r, ' + [char]0x015F + 'ifresiz Wi-Fi a' + [char]0x011F + 'lar' + [char]0x0131 + 'na kendili' + [char]0x011F + 'inden ba' + [char]0x011F + 'lanma durur. Hepsi geri al' + [char]0x0131 + 'nabilir.'); Tag = ('tek t' + [char]0x0131 + 'kla'); BrCol = 'BrAccent'; Btn1 = 'Uygula'; Btn2 = ('' + [char]0x00D6 + 'nizle') } @{ K = 'pub' } $false $false
    $row.FindName('Act').Add_Click({ param($s2, $e2) Invoke-Safe { Start-PublicWifi $false } 'Genel Wi-Fi' })
    $row.FindName('Act2').Add_Click({ param($s2, $e2) Invoke-Safe { Start-PublicWifi $true } 'Genel Wi-Fi' })
    [void]$ui.nw_List.Children.Add($row)

    Add-HeadRow $ui.nw_List ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n durumu')
    foreach ($p in @($i.Profiles)) {
        $cat = [string]$p.Category
        $br = 'BrGood'
        if ($cat -eq 'Public') { $br = 'BrAccent' }
        $b1 = ''
        if ($cat -eq 'Public') { $b1 = ('' + [char]0x00D6 + 'zel yap') } elseif ($cat -eq 'Private') { $b1 = 'Genel yap' }
        $r = New-ItemRow @{ Title = ('A' + [char]0x011F + ': ') + [string]$p.Name; Detail = 'Profil: ' + (Get-CatTr $cat) + $(if ($cat -eq 'Private') { (' ' + [char]0x2014 + ' ev/i' + [char]0x015F + ' a' + [char]0x011F + '' + [char]0x0131 + ' i' + [char]0x00E7 + 'in uygundur; herkese a' + [char]0x00E7 + '' + [char]0x0131 + 'k a' + [char]0x011F + 'daysan' + [char]0x0131 + 'z Genel yap' + [char]0x0131 + 'n') } elseif ($cat -eq 'Public') { (' ' + [char]0x2014 + ' bilgisayar a' + [char]0x011F + 'da g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nmez') } else { '' }); Tag = (Get-CatTr $cat); BrCol = $br; Btn1 = $b1 } @{ Index = [int]$p.Index; Name = [string]$p.Name; Cat = $cat } $false $false
        if ($b1 -ne '') { $r.FindName('Act').Add_Click($script:H_NpProfile) }
        [void]$ui.nw_List.Children.Add($r)
    }
    $fw = @($i.Fw)
    if ($fw.Count -gt 0) {
        $off = @($fw | Where-Object { $_.Enabled -ne $true })
        $t = (($fw | ForEach-Object { (Get-CatTr ([string]$_.Name)) + ': ' + $(if ($_.Enabled) { ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k, gelen ') + [string]$_.In } else { 'KAPALI' }) }) -join ('  ' + [char]0x00B7 + '  '))
        $br = 'BrGood'; if ($off.Count -gt 0) { $br = 'BrBad' }
        Add-KvRow $ui.nw_List ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + '') $t
        if ($off.Count -gt 0) { Add-Note $ui.nw_List ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kapal' + [char]0x0131 + ' bir profil var; a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'daki bulgulardan a' + [char]0x00E7 + 'abilirsiniz.') 'bad' }
    }
    if ([string]$i.Gateway -ne '') {
        $stx = ('Kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'il (ilk g' + [char]0x00F6 + 'r' + [char]0x00FC + '' + [char]0x015F + 'te kaydedildi)')
        $br = 'BrAccent'
        switch ([string]$i.GwStatus) {
            'ok' { $stx = ('Do' + [char]0x011F + 'ruland' + [char]0x0131 + ': MAC adresi kay' + [char]0x0131 + 'tl' + [char]0x0131 + 'yla ayn' + [char]0x0131 + ''); $br = 'BrGood' }
            'changed' { $stx = ('DE' + [char]0x011E + '' + [char]0x0130 + '' + [char]0x015E + 'M' + [char]0x0130 + '' + [char]0x015E + ': kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' ') + (Format-Mac ([string]$i.Baseline)) + (' ' + [char]0x2192 + ' ' + [char]0x015F + 'imdi ') + (Format-Mac ([string]$i.GwMac)); $br = 'BrBad' }
            'unknown' { $stx = ('MAC adresi okunamad' + [char]0x0131 + ''); $br = 'BrFaint' }
        }
        $b2 = ''
        if ([string]$i.GwStatus -eq 'changed') { $b2 = ('Yeni adrese g' + [char]0x00FC + 'ven') }
        $d = @{ Gateway = [string]$i.Gateway; GwMac = [string]$i.GwMac; Baseline = [string]$i.Baseline; Index = [int]$i.Index }
        $r = New-ItemRow @{ Title = ('A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ': ') + [string]$i.Gateway; Detail = $stx + ('. Sabitlemek, a' + [char]0x011F + 'daki bir cihaz' + [char]0x0131 + 'n kendini y' + [char]0x00F6 + 'nlendirici gibi tan' + [char]0x0131 + 'tmas' + [char]0x0131 + 'na (ARP sahtecili' + [char]0x011F + 'i) kar' + [char]0x015F + '' + [char]0x0131 + ' korur.'); Tag = (Format-Mac ([string]$i.GwMac)); BrCol = $br; Btn1 = 'Sabitle'; Btn2 = $b2 } $d $false $false
        $r.FindName('Act').Add_Click($script:H_NpPin)
        if ($b2 -ne '') { $r.FindName('Act2').Add_Click($script:H_NpTrust) }
        [void]$ui.nw_List.Children.Add($r)
        foreach ($dn in @($i.Dns)) {
            $v = Get-DnsVerdict ([string]$dn) ([string]$i.Gateway)
            $r = New-ItemRow @{ Title = 'DNS sunucusu: ' + [string]$dn; Detail = [string]$v.Text; BrCol = [string]$v.Br } @{} $false $false
            [void]$ui.nw_List.Children.Add($r)
        }
    }
    foreach ($w in @($i.Wifi)) {
        $cur = @($i.Profiles | Where-Object { [string]$_.Name -eq [string]$w.Name })
        if ($cur.Count -eq 0) { continue }
        $auth = [string]$w.Auth; $enc = [string]$w.Enc
        $br = 'BrGood'; $note = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + '')
        if ($w.Open -eq $true) { $br = 'BrBad'; $note = ('' + [char]0x015E + 'ifresiz a' + [char]0x011F + ': trafi' + [char]0x011F + 'iniz herkese a' + [char]0x00E7 + '' + [char]0x0131 + 'kt' + [char]0x0131 + 'r; VPN kullan' + [char]0x0131 + 'n') }
        elseif ($enc.ToUpperInvariant() -eq 'WEP' -or $enc.ToUpperInvariant() -eq 'TKIP' -or $auth.ToLowerInvariant() -eq 'shared' -or $auth.ToLowerInvariant() -eq 'wpa' -or $auth.ToLowerInvariant() -eq 'wpapsk') { $br = 'BrWarn'; $note = ('Eski ' + [char]0x015F + 'ifreleme: y' + [char]0x00F6 + 'nlendiriciden WPA2-AES ya da WPA3 se' + [char]0x00E7 + 'in') }
        $r = New-ItemRow @{ Title = ('Wi-Fi g' + [char]0x00FC + 'venli' + [char]0x011F + 'i: ') + [string]$w.Name; Detail = $note; Tag = ($auth + ' / ' + $enc); BrCol = $br } @{} $false $false
        [void]$ui.nw_List.Children.Add($r)
    }

    # bulgular
    $fl = Get-FixList $s.Findings
    $auto = @($fl | Where-Object { $_.Mode -eq 'Auto' })
    $click = @($fl | Where-Object { $_.Mode -eq 'Click' })
    $open = @($s.Findings | Where-Object { [string]$_.Status -ne 'ok' -and $null -ne $_.Fix })
    $guided = @($open | Where-Object { [string]$_.Fix.Mode -eq 'Guided' })
    $manual = @($open | Where-Object { [string]$_.Fix.Mode -eq 'Manual' })
    if ($fl.Count -eq 0 -and $guided.Count -eq 0 -and $manual.Count -eq 0) {
        Add-HeadRow $ui.nw_List 'Bulgular'
        Add-Note $ui.nw_List ('A' + [char]0x011F + 'la ilgili a' + [char]0x00E7 + '' + [char]0x0131 + 'k bir bulgu yok.') 'good'
    }
    foreach ($g in @(@{ T = ('Otomatik d' + [char]0x00FC + 'zeltilebilir'); L = $auto }, @{ T = ('Onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla d' + [char]0x00FC + 'zeltilebilir'); L = $click })) {
        if (@($g.L).Count -eq 0) { continue }
        Add-HeadRow $ui.nw_List ($g.T + ' (' + [string]@($g.L).Count + ')')
        foreach ($it in @($g.L)) {
            $br = 'BrInfo'
            if ($it.Status -eq 'bad') { $br = 'BrBad' } elseif ($it.Status -eq 'warn') { $br = 'BrWarn' }
            $f = $null
            foreach ($x in $s.Findings) { if ([string]$x.Id -eq [string]$it.Id) { $f = $x; break } }
            $det = ''
            if ($null -ne $f) { $det = [string]$f.Detail }
            if ([string]$it.Fix.Note -ne '') { $det = ($det + '  [' + [string]$it.Fix.Note + ']').Trim() }
            if ($det.Length -gt 320) { $det = $det.Substring(0, 317) + '...' }
            if (-not $script:NpSel.ContainsKey([string]$it.Id)) { $script:NpSel[[string]$it.Id] = ($it.Mode -eq 'Auto') }
            $mi = Get-FixModeInfo ([string]$it.Mode)
            $r = New-ItemRow @{ Title = [string]$it.Title; Detail = $det; Tag = ($mi.Text + (' ' + [char]0x00B7 + ' ') + [string]$it.Fix.Label); BrCol = $br; Btn1 = ('D' + [char]0x00FC + 'zelt') } @{ Item = $it; Id = [string]$it.Id } $true ($script:NpSel[[string]$it.Id] -eq $true)
            $chk = $r.FindName('Chk')
            $chk.Tag = [string]$it.Id
            $chk.Add_Click($script:H_NpChk)
            $r.FindName('Act').Add_Click($script:H_NpFix)
            [void]$ui.nw_List.Children.Add($r)
        }
    }
    foreach ($g in @(@{ T = ('' + [char]0x0130 + 'lgili sayfadan yap' + [char]0x0131 + 'lacaklar'); L = $guided }, @{ T = ('Elle yap' + [char]0x0131 + 'lacaklar'); L = $manual })) {
        if (@($g.L).Count -eq 0) { continue }
        Add-HeadRow $ui.nw_List ($g.T + ' (' + [string]@($g.L).Count + ')')
        foreach ($f in @($g.L)) {
            $br = 'BrInfo'
            if ($f.Status -eq 'bad') { $br = 'BrBad' } elseif ($f.Status -eq 'warn') { $br = 'BrWarn' }
            $btn = [string]$f.Fix.Label
            if ($btn -eq '' -and $null -ne $f.Action) { $btn = [string]$f.Action.Label }
            $r = New-ItemRow @{ Title = [string]$f.Title; Detail = [string]$f.Detail; Tag = (Get-CatLabel ([string]$f.Cat)); BrCol = $br; Btn1 = $btn } @{ Action = $f.Action; Id = [string]$f.Id } $false $false
            if ($btn -ne '') { $r.FindName('Act').Add_Click($script:H_ScAct) }
            [void]$ui.nw_List.Children.Add($r)
        }
    }
    $ui.nw_Foot.Text = (Tr $('Son denetim: ' + $script:NpAt.ToString('HH:mm:ss') + ('. D' + [char]0x00FC + 'zeltmeler ' + [char]0x00F6 + 'nce onay' + [char]0x0131 + 'n' + [char]0x0131 + 'za sunulur, g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.')))
}

function Start-PublicWifi([bool]$Preview) {
    $script:PlanAfter = { Start-NpScan }
    $lbl = ('Genel Wi-Fi modu uygulan' + [char]0x0131 + 'yor')
    if ($Preview) { $lbl = ('Genel Wi-Fi modu ' + [char]0x00F6 + 'nizlemesi') }
    if ($Preview) {
        [void](Start-Async 'PubWifi' 'Job_PublicWifi' @{ Preview = $true } { param($r) Complete-PlanJob $r } $lbl)
        return
    }
    Show-Confirm 'Genel Wi-Fi modu' ("$([char]0x015E)unlar uygulan$([char]0x0131)r:`r`n$([char]0x2022) $([char]0x00D6)zel i$([char]0x015F)aretli a$([char]0x011F)lar Genel profile al$([char]0x0131)n$([char]0x0131)r`r`n$([char]0x2022) Genel profilde gelen ba$([char]0x011F)lant$([char]0x0131)lar engellenir`r`n$([char]0x2022) Genel profilde a$([char]0x011F) ke$([char]0x015F)fi ve dosya payla$([char]0x015F)$([char]0x0131)m$([char]0x0131) kurallar$([char]0x0131) kapat$([char]0x0131)l$([char]0x0131)r`r`n$([char]0x2022) $([char]0x015E)ifresiz Wi-Fi a$([char]0x011F)lar$([char]0x0131)na kendili$([char]0x011F)inden ba$([char]0x011F)lanma durdurulur`r`n`r`n$([char]0x00D6)nce $([char]0x201C)$([char]0x00D6)nizle$([char]0x201D) ile ayr$([char]0x0131)nt$([char]0x0131)y$([char]0x0131) g$([char]0x00F6)rebilirsiniz. Hepsi Ge$([char]0x00E7)mi$([char]0x015F) sayfas$([char]0x0131)ndan geri al$([char]0x0131)n$([char]0x0131)r.") 'Uygula' {
        [void](Start-Async 'PubWifi' 'Job_PublicWifi' @{ Preview = $false } { param($r) Complete-PlanJob $r } ('Genel Wi-Fi modu uygulan' + [char]0x0131 + 'yor'))
    }
}

# ---------------- ag izleme (istege bagli) ----------------
function Initialize-NetWatch {
    if ($null -ne $script:NetWatchTimer) { return }
    $script:NetWatchTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:NetWatchTimer.Interval = [TimeSpan]::FromMinutes(5)
    $script:NetWatchTimer.Add_Tick({
        try {
            if ($script:Settings.NetWatch -ne $true) { return }
            if (Test-AsyncBusy) { return }
            Start-LanScan $false $true
        } catch { Write-CrashLog ('NetWatch: ' + $_.Exception.Message) }
    })
    $script:NetWatchTimer.Start()
}

