        $ui.pn_BtnTopo.Content = (Tr $(('A' + [char]0x011F + '' + [char]0x0131 + ' tara')))
        $ui.pn_TopoHint.Text = (Tr $(('D' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + 'mlerin ' + [char]0x00FC + 'zerine gelin: cihaz' + [char]0x0131 + 'n t' + [char]0x00FC + 'r' + [char]0x00FC + ', adresi ve neden o t' + [char]0x00FC + 'rde say' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r; t' + [char]0x0131 + 'klay' + [char]0x0131 + 'nca Cihazlar sekmesi a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r. Sar' + [char]0x0131 + ' ' + [char]0x00E7 + 'er' + [char]0x00E7 + 'eve tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k olmayan, k' + [char]0x0131 + 'rm' + [char]0x0131 + 'z' + [char]0x0131 + ' engelli ya da a' + [char]0x00E7 + '' + [char]0x0131 + 'kl' + [char]0x0131 + ' cihazd' + [char]0x0131 + 'r.')))
    } else {
        $ui.pn_BtnTopo.Content = (Tr $('Yenile'))
        $ui.pn_TopoHint.Text = (Tr $(('D' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + 'mlerin ' + [char]0x00FC + 'zerine gelin: ba' + [char]0x011F + 'lant' + [char]0x0131 + ' say' + [char]0x0131 + 's' + [char]0x0131 + ' ve uzak adresler g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r. K' + [char]0x0131 + 'rm' + [char]0x0131 + 'z' + [char]0x0131 + ' d' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + 'm d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + 'dan eri' + [char]0x015F + 'ilebilen portlar' + [char]0x0131 + ' g' + [char]0x00F6 + 'sterir.')))
    }
