function Invoke-TopoRefresh {
    if ($script:TopoMode -eq 'lan') { Start-LanScan $false $false } else { Start-TopoScan $false }
}

$script:H_LanNodeClick = {
    param($s, $e)
    try {
        $script:DevFocusMac = [string]$s.DataContext
        Open-Page 'network' 'dev'
    } catch { }
}

function Add-LanNode($D, [double]$Cx, [double]$Cy, [double]$R, [string]$Label, [string]$Info) {
    $ti = Get-DevTypeInfo ([string]$D.Type)
    $brKey = Get-DevBrKey $D
    if ($D.New -eq $true -and $D.Blocked -ne $true -and $script:Settings.KnownDevices.Count -gt 0 -and $brKey -ne 'BrBad') { $brKey = 'BrWarn' }
    $br = Get-Br $brKey
    $shape = [string]$ti.Shape
    $el = $null
    if ($shape -eq 'diamond') {
        $el = New-Object System.Windows.Shapes.Polygon
        $k = $R * 1.25
        [void]$el.Points.Add((New-Object System.Windows.Point -ArgumentList ([double]$Cx), ([double]($Cy - $k))))
        [void]$el.Points.Add((New-Object System.Windows.Point -ArgumentList ([double]($Cx + $k)), ([double]$Cy)))
        [void]$el.Points.Add((New-Object System.Windows.Point -ArgumentList ([double]$Cx), ([double]($Cy + $k))))
        [void]$el.Points.Add((New-Object System.Windows.Point -ArgumentList ([double]($Cx - $k)), ([double]$Cy)))
    } elseif ($shape -eq 'rect') {
        $el = New-Object System.Windows.Shapes.Rectangle
        $el.Width = 2.2 * $R; $el.Height = 1.7 * $R
        $el.RadiusX = 4; $el.RadiusY = 4
        Set-CanvasPos $el ($Cx - 1.1 * $R) ($Cy - 0.85 * $R)
    } else {
        $el = New-Object System.Windows.Shapes.Ellipse
        $el.Width = 2 * $R; $el.Height = 2 * $R
        Set-CanvasPos $el ($Cx - $R) ($Cy - $R)
    }
    $el.Fill = (Get-Br 'BrPanel2')
    $el.Stroke = $br
    $el.StrokeThickness = 2.2
    if ($D.Blocked -eq $true -or ($D.New -eq $true -and [string]$D.Type -eq 'unknown')) {
        $dc = New-Object System.Windows.Media.DoubleCollection
        [void]$dc.Add(3); [void]$dc.Add(2)
        $el.StrokeDashArray = $dc
    }
    $el.Cursor = [System.Windows.Input.Cursors]::Hand
    $el.Tag = $Info
    $el.DataContext = [string]$D.MacKey
    $eff = New-Object System.Windows.Media.Effects.DropShadowEffect
    $eff.Color = ([System.Windows.Media.SolidColorBrush]$br).Color
    $eff.BlurRadius = 12; $eff.ShadowDepth = 0; $eff.Opacity = 0.8
    $el.Effect = $eff
    $el.Add_MouseEnter($script:H_TopoEnter)
    $el.Add_MouseLeave($script:H_TopoLeave)
    $el.Add_MouseLeftButtonUp($script:H_LanNodeClick)
    [void]$ui.pn_Topo.Children.Add($el)
    $g = New-Object System.Windows.Controls.TextBlock
    $g.Text = (Tr $([string]$ti.G))
    $g.FontSize = 8.5; $g.FontWeight = [System.Windows.FontWeights]::Bold
    $g.Foreground = $br
    $g.Width = 2 * $R; $g.TextAlignment = [System.Windows.TextAlignment]::Center
    $g.IsHitTestVisible = $false
    Set-CanvasPos $g ($Cx - $R) ($Cy - 6)
    [void]$ui.pn_Topo.Children.Add($g)
    if ($Label -ne '') {
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.Text = (Tr $($Label)); $tb.FontSize = 10; $tb.Foreground = (Get-Br 'BrDim')
        $tb.Width = 84; $tb.TextAlignment = [System.Windows.TextAlignment]::Center
        $tb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis; $tb.IsHitTestVisible = $false
        Set-CanvasPos $tb ($Cx - 42) ($Cy + $R + 2)
        [void]$ui.pn_Topo.Children.Add($tb)
    }
}

function Add-LanEdge([double]$X1, [double]$Y1, [double]$X2, [double]$Y2, [string]$BrKey, [bool]$Dashed) {
    $ln = New-Object System.Windows.Shapes.Line
    $ln.X1 = $X1; $ln.Y1 = $Y1; $ln.X2 = $X2; $ln.Y2 = $Y2
    $ln.Stroke = (Get-Br $BrKey)
    $ln.StrokeThickness = 1.2
    $ln.Opacity = 0.4
    $ln.IsHitTestVisible = $false
    if ($Dashed) {
        $dc = New-Object System.Windows.Media.DoubleCollection
        [void]$dc.Add(4); [void]$dc.Add(3)
        $ln.StrokeDashArray = $dc
    }
    [void]$ui.pn_Topo.Children.Add($ln)
}

function Get-LanNodeInfo($D) {
    $ti = Get-DevTypeInfo ([string]$D.Type)
    $l = New-Object System.Collections.ArrayList
    [void]$l.Add((Get-DeviceTitle $D))
    $t = [string]$ti.L
    if ([string]$D.Type -ne 'unknown' -and $D.IsSelf -ne $true) { $t += ' (%' + [string]$D.Conf + ')' }
    [void]$l.Add($t)
    [void]$l.Add('IP: ' + [string]$D.Ip)
    if ([string]$D.Mac -ne '') { [void]$l.Add('MAC: ' + [string]$D.Mac) }
    $sm = Get-DeviceSummary $D
    if ($sm -ne '') { [void]$l.Add($sm) }
    $why = @($D.Why)
    if ($why.Count -gt 0) { [void]$l.Add('Neden: ' + [string]$why[0]) }
    if ($D.Blocked -eq $true) { [void]$l.Add(('ENGELL' + [char]0x0130 + ' (bu bilgisayarda)')) }
    elseif ($D.Fresh -eq $true) { [void]$l.Add(('YEN' + [char]0x0130 + ' cihaz')) }
    elseif ($D.New -eq $true -and $script:Settings.KnownDevices.Count -gt 0) { [void]$l.Add(('Tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k de' + [char]0x011F + 'il')) }
    $rk = @($D.Risks)
    if ($rk.Count -gt 0 -and $D.Blocked -ne $true) { [void]$l.Add(('Uyar' + [char]0x0131 + ': ') + [string]$rk[0].Text) }
    return ($l -join "`r`n")
}

function Draw-LanTopology {
    Initialize-LanSnap
    $snap = $script:LanSnap
    $W = [double]$ui.pn_Topo.ActualWidth
    if ($W -lt 200) { $W = 760 }
    $H = [double]$ui.pn_Topo.Height
    $script:TopoW = $W
    $keep = $ui.pn_TopoTip
    $ui.pn_Topo.Children.Clear()
    [void]$ui.pn_Topo.Children.Add($keep)
    $keep.Visibility = $script:VisOff
    if ($null -eq $snap -or @($snap.Devices).Count -eq 0) {
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.Text = (Tr $("Yerel a$([char]0x011F) hen$([char]0x00FC)z taranmad$([char]0x0131).`r`n$([char]0x201C)A$([char]0x011F)$([char]0x0131) tara$([char]0x201D) d$([char]0x00FC)$([char]0x011F)mesi cihazlar$([char]0x0131)n$([char]0x0131)z$([char]0x0131) bulur ve t$([char]0x00FC)rlerini belirler.`r`n(Yaln$([char]0x0131)zca kendi $([char]0x00F6)zel a$([char]0x011F)$([char]0x0131)n$([char]0x0131)z taran$([char]0x0131)r.)"))
        $tb.FontSize = 13; $tb.Foreground = (Get-Br 'BrDim'); $tb.TextAlignment = [System.Windows.TextAlignment]::Center
        $tb.Width = $W; $tb.IsHitTestVisible = $false
        Set-CanvasPos $tb 0 ($H / 2 - 36)
        [void]$ui.pn_Topo.Children.Add($tb)
        $ui.pn_TopoInfo.Text = (Tr $(''))
        return
    }
    $devs = @($snap.Devices)
    $gw = $null
    foreach ($d in $devs) { if ($d.IsGateway -eq $true) { $gw = $d; break } }
    $order = @{}
    $oi = 0
    foreach ($t in @('self', 'router', 'ap', 'pc', 'server', 'nas', 'phone', 'tv', 'speaker', 'console', 'printer', 'camera', 'iot', 'sbc', 'vm', 'unknown')) { $order[$t] = $oi; $oi++ }
    $others = @($devs | Where-Object { $_.IsGateway -ne $true } | Sort-Object @{ Expression = { if ($_.IsSelf -eq $true) { -1 } elseif ($order.ContainsKey([string]$_.Type)) { [int]$order[[string]$_.Type] } else { 99 } } }, @{ Expression = { ConvertTo-IpNum ([string]$_.Ip) } })
    $n = $others.Count
    $rcx = 0.52 * $W; $rcy = 0.52 * $H
    # internet dugumu
    $inx = 0.07 * $W; $iny = 0.14 * $H
    Add-TopoEdge $inx $iny $rcx $rcy 8 'BrBlue' 3.0
    # halka yerlesimi
    $n1 = $n
    $n2 = 0
    if ($n -gt 14) { $n1 = [int][math]::Ceiling($n * 0.62); $n2 = $n - $n1 }
    $pos = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt $n1; $i++) {
        $a = (180.0 + 360.0 * $i / $n1) * [math]::PI / 180.0
        [void]$pos.Add(@(($rcx + 0.36 * $W * [math]::Cos($a)), ($rcy + 0.36 * $H * [math]::Sin($a))))
    }
    for ($i = 0; $i -lt $n2; $i++) {
        $a = (180.0 + 360.0 * ($i + 0.5) / $n2) * [math]::PI / 180.0
        [void]$pos.Add(@(($rcx + 0.19 * $W * [math]::Cos($a)), ($rcy + 0.2 * $H * [math]::Sin($a))))
    }
    # kenarlar
    for ($i = 0; $i -lt $n; $i++) {
        $d = $others[$i]
        $key = 'BrFaint'
        if ($d.IsSelf -eq $true) { $key = 'BrAccent' } elseif ($d.Blocked -eq $true) { $key = 'BrBad' }
        if ($d.IsSelf -eq $true) { Add-TopoEdge ([double]$pos[$i][0]) ([double]$pos[$i][1]) $rcx $rcy 6 'BrAccent' 2.2 }
        else { Add-LanEdge ([double]$pos[$i][0]) ([double]$pos[$i][1]) $rcx $rcy $key ($d.Blocked -eq $true) }
    }
    # dugumler
    $gwInfo = ('Y' + [char]0x00F6 + 'nlendirici')
    $gwDev = $gw
    if ($null -ne $gwDev) { $gwInfo = Get-LanNodeInfo $gwDev }
    Add-TopoNode $inx $iny 16 'BrBlue' ('' + [char]0x0130 + 'nternet') (('' + [char]0x0130 + 'nternet') + "`r`nT$([char]0x00FC)m d$([char]0x0131)$([char]0x015F) trafik y$([char]0x00F6)nlendirici $([char]0x00FC)zerinden ge$([char]0x00E7)er.")
    if ($null -ne $gwDev) {
        Add-LanNode $gwDev $rcx $rcy 17 ('Y' + [char]0x00F6 + 'nlendirici') $gwInfo
    } else {
        Add-TopoNode $rcx $rcy 15 'BrAccent2' ('A' + [char]0x011F + '') ('Y' + [char]0x00F6 + 'nlendirici bulunamad' + [char]0x0131 + '')
    }
    for ($i = 0; $i -lt $n; $i++) {
        $d = $others[$i]
        $lab = ''
        if ($n -le 12) { $lab = Get-DeviceTitle $d; if ($lab.Length -gt 16) { $lab = $lab.Substring(0, 15) + ('' + [char]0x2026 + '') } }
        elseif ($n -le 24) { $lab = [string]$d.Ip; $lab = $lab.Substring($lab.LastIndexOf('.')) }
        $rr = 11.0
        if ($n -gt 24) { $rr = 8.5 }
        Add-LanNode $d ([double]$pos[$i][0]) ([double]$pos[$i][1]) $rr $lab (Get-LanNodeInfo $d)
    }
    $nn = @($devs | Where-Object { $_.New -eq $true }).Count
    $inf = [string]$devs.Count + ' cihaz'
    if ($script:Settings.KnownDevices.Count -gt 0) { $inf += (' ' + [char]0x00B7 + ' ') + [string]$nn + (' tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k olmayan') }
    $ui.pn_TopoInfo.Text = (Tr $($inf + (' ' + [char]0x00B7 + ' ') + (Get-AgeText $script:LanAt)))
}

# Baglanti haritasi eski islev adiyla durur; kip secimine gore biri cizilir
function Draw-Topology {
    if ($script:TopoMode -eq 'lan') { Draw-LanTopology }
    elseif ($null -ne $script:TopoSnap) { Draw-ConnTopology }
    else {
        # baglanti haritasi henuz yok: tuvali temizle ve (sessizce) hazirla
        $keep = $ui.pn_TopoTip
        $ui.pn_Topo.Children.Clear()
        [void]$ui.pn_Topo.Children.Add($keep)
        $keep.Visibility = $script:VisOff
        $ui.pn_TopoInfo.Text = (Tr $(('ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar okunuyor...')))
        Start-TopoScan $true
    }
    Update-TopoModeUi
}

function Init-LanTopoUi {
    $ui.pn_TopoModeLan.Add_Checked({ Invoke-Safe { $script:TopoMode = 'lan'; Draw-Topology } 'Topoloji' })
    $ui.pn_TopoModeConn.Add_Checked({ Invoke-Safe { $script:TopoMode = 'conn'; Draw-Topology } 'Topoloji' })
    Update-TopoModeUi
}

# ---------------- Ag sayfasi dugmeleri ----------------
function Init-LanUi {
    $ui.nw_ScanQuick.Add_Click({ Invoke-Safe { Start-LanScan $false $false } ('A' + [char]0x011F + '' + [char]0x0131 + ' tara') })
    $ui.nw_ScanDeep.Add_Click({ Invoke-Safe { Confirm-OptScan { Start-LanScan $true $false } } ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' tara') })
    $ui.nw_DevFilter.Add_TextChanged({ try { if ($script:NwTab -eq 'dev') { Render-NwDev } } catch { } })
    $ui.nw_DevNew.Add_Click({ Invoke-Safe { if ($script:NwTab -eq 'dev') { Render-NwDev } } ('S' + [char]0x00FC + 'z') })
    $ui.nw_DevTrust.Add_Click({
        Invoke-Safe {
            $sel = Get-DevSelection
            if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce cihazlar' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
            $allKnown = $true
            foreach ($r in $sel) { if ($r.Dev.Known -ne $true) { $allKnown = $false } }
            Set-DevKnown @($sel | ForEach-Object { [string]$_.Mac }) (-not $allKnown)
            if ($allKnown) { Show-Toast ('Se' + [char]0x00E7 + 'ilenler tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k listesinden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'info' } else { Show-Toast ('Se' + [char]0x00E7 + 'ilenler tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k olarak i' + [char]0x015F + 'aretlendi.') 'good' }
            Render-NwDev
        } ('Tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k')
    })
    $ui.nw_DevTrustAll.Add_Click({
        Invoke-Safe {
            if ($null -eq $script:LanSnap) { Show-Toast ('' + [char]0x00D6 + 'nce a' + [char]0x011F + '' + [char]0x0131 + ' taray' + [char]0x0131 + 'n.') 'warn'; return }
            $n = @($script:LanSnap.Devices | Where-Object { $_.IsSelf -ne $true -and $_.IsGateway -ne $true -and [string]$_.MacKey -ne '' }).Count
            Show-Confirm ('Hepsini tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k say') (('' + [char]0x015E + 'u an listedeki ') + [string]$n + " cihaz$([char]0x0131)n hepsi sizin ya da bildi$([char]0x011F)iniz cihazlar olarak i$([char]0x015F)aretlenecek. Bundan sonra a$([char]0x011F)a kat$([char]0x0131)lan her yeni cihaz $([char]0x201C)yeni$([char]0x201D) diye $([char]0x00F6)ne $([char]0x00E7)$([char]0x0131)kar.`r`n`r`nListede tan$([char]0x0131)mad$([char]0x0131)$([char]0x011F)$([char]0x0131)n$([char]0x0131)z bir cihaz varsa $([char]0x00F6)nce onu i$([char]0x015F)aretsiz b$([char]0x0131)rak$([char]0x0131)p tek tek i$([char]0x015F)aretleyin.") ('Tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k say') {
                $macs = @($script:LanSnap.Devices | Where-Object { $_.IsSelf -ne $true -and $_.IsGateway -ne $true -and [string]$_.MacKey -ne '' } | ForEach-Object { [string]$_.MacKey })
                Set-DevKnown $macs $true
                Show-Toast ('Listedeki cihazlar tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k olarak i' + [char]0x015F + 'aretlendi.') 'good'
                Render-NwDev
            }
        } ('Tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k')
    })
    $ui.nw_DevName.Add_Click({
        Invoke-Safe {
            $sel = Get-DevSelection
            if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce adland' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak cihaz' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
            Start-DevRename $sel[0]
        } ('Adland' + [char]0x0131 + 'r')
    })
    $ui.nw_DevBlock.Add_Click({ Invoke-Safe { Start-DevBlock (Get-DevSelection) $true } 'Engelle' })
    $ui.nw_DevUnblock.Add_Click({ Invoke-Safe { Start-DevBlock (Get-DevSelection) $false } ('Engeli kald' + [char]0x0131 + 'r') })
    $ui.nw_DevKick.Add_Click({
        Invoke-Safe {
            $sel = Get-DevSelection
            if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce cihaz' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
            Show-KickGuide $sel[0].Dev
        } ('A' + [char]0x011F + 'dan ' + [char]0x00E7 + '' + [char]0x0131 + 'kar')
    })
    $ui.nw_DevPorts.Add_Click({
        Invoke-Safe {
            $sel = Get-DevSelection
            if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce cihaz' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
            Start-DevPortCheck $sel[0].Dev
        } 'Port'
    })
    $ui.nw_ProtScan.Add_Click({ Invoke-Safe { Start-NpScan } 'Denetle' })
    $ui.nw_ProtAll.Add_Click({
        Invoke-Safe {
            if ($null -eq $script:NpSnap) { Show-Toast ('' + [char]0x00D6 + 'nce denetimi ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n.') 'warn'; return }
            $fl = Get-FixList $script:NpSnap.Findings
            $auto = @($fl | Where-Object { $_.Mode -eq 'Auto' })
            if ($auto.Count -eq 0) { Show-Toast ('Otomatik d' + [char]0x00FC + 'zeltilecek bulgu yok.') 'good'; return }
            Start-FixFlow $auto ('Otomatik d' + [char]0x00FC + 'zeltmeleri uygula')
        } ('D' + [char]0x00FC + 'zelt')
    })
    $ui.nw_ProtPick.Add_Click({
        Invoke-Safe {
            $sel = Get-NpSelectedItems
            if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce d' + [char]0x00FC + 'zeltilecek maddeleri i' + [char]0x015F + 'aretleyin.') 'warn'; return }
            Start-FixFlow $sel ('Se' + [char]0x00E7 + 'ilenleri d' + [char]0x00FC + 'zelt')
        } ('D' + [char]0x00FC + 'zelt')
    })
    $ui.nw_PubWifi.Add_Click({ Invoke-Safe { Start-PublicWifi $false } 'Genel Wi-Fi' })
    $ui.nw_PubPrev.Add_Click({ Invoke-Safe { Start-PublicWifi $true } 'Genel Wi-Fi' })
    $ui.nw_Watch.Add_Click({
        Invoke-Safe {
            $on = ($ui.nw_Watch.IsChecked -eq $true)
            Set-OptValue 'NetWatch' $on
            if ($on) { Show-Toast ('A' + [char]0x011F + ' izleme a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ': 5 dakikada bir sessiz tarama yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') 'good' } else { Show-Toast ('A' + [char]0x011F + ' izleme kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'info' }
        } ('A' + [char]0x011F + ' izleme')
    })
}


# ---------------- Arayuz: VPN ve gizlilik ----------------
# ==================================================================
#  ARAYUZ: Ag > "VPN ve gizlilik" sekmesi, baslik cubugundaki kill-switch dugmesi, tepsi ogesi
# ==================================================================
$script:VpnSnap = $null
$script:VpnLeak = $null
$script:VpnPendingName = ''
$script:VpnCtx = $null
$script:VpnMsg = ''
$script:VpnAfter = $null
$script:VpnPendingAll = $false
$script:VpnPendingId = ''
$script:VpnPendingServer = ''
$script:KsWired = $false

function Start-VpnStatus {
    [void](Start-Async 'VpnStatus' 'Job_VpnStatus' @{} {
        param($r)
        if ($null -eq $r) { return }
        $script:VpnSnap = $r
        Update-KsButton
        if ([string]$script:UiState.Page -eq 'network' -and $script:NwTab -eq 'vpn') { Render-NwVpn }
    } 'VPN durumu' $false $true)
}

# Baslik cubugundaki acil kapatma dugmesi ve tepsi ogesi, kill-switch acikken gorunur
function Test-KsUiOn {
    $on = ($script:Settings.KillSwitch -eq $true)
    if ($null -ne $script:VpnSnap) { $on = [bool]$script:VpnSnap.Ks.On }
    return $on
}

function Update-KsButton {
    try { Set-Visible $ui.BtnKsOff (Test-KsUiOn) } catch { }
    try { Update-TrayMenuState } catch { }
}

# Acil kapatma: is kuyrugundan bagimsiz, dogrudan calisir
function Start-KsOffNow {
    try {
        Disable-KillSwitchNow
        $script:Settings = Get-Settings
        $script:VpnSnap = $null
        Update-KsButton
        Show-Toast ('Kill-switch kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '; internet eri' + [char]0x015F + 'imi normale d' + [char]0x00F6 + 'nd' + [char]0x00FC + '.') 'good'
        if ([string]$script:UiState.Page -eq 'network' -and $script:NwTab -eq 'vpn') { Start-VpnStatus }
    } catch {
        Show-Message ('Kill-switch kapat' + [char]0x0131 + 'lamad' + [char]0x0131 + '') ('Hata: ' + $_.Exception.Message + "`r`n`r`nY$([char]0x00F6)netici komut sat$([char]0x0131)r$([char]0x0131)nda $([char]0x015F)u komutu $([char]0x00E7)al$([char]0x0131)$([char]0x015F)t$([char]0x0131)rarak giden trafik engelini elle kald$([char]0x0131)rabilirsiniz:`r`n`r`nnetsh advfirewall set allprofiles firewallpolicy blockinbound,allowoutbound")
    }
}

function Get-VpnStateText($S) {
    $a = $S.Active
    $names = New-Object System.Collections.ArrayList
    foreach ($w in @($a.Wg)) { [void]$names.Add('WireGuard: ' + [string]$w.Name) }
    foreach ($w in @($a.Ike)) { [void]$names.Add('Windows VPN: ' + [string]$w.Name) }
    foreach ($w in @($a.Other)) { [void]$names.Add([string]$w.Desc) }
    if ($names.Count -eq 0) { return ('Ba' + [char]0x011F + 'l' + [char]0x0131 + ' de' + [char]0x011F + 'il') }
    return ($names -join ('  ' + [char]0x00B7 + '  '))
}

function Render-NwVpn {
    $ui.nw_List.Children.Clear()
    $ui.nw_KsLan.IsChecked = ($script:Settings.KsAllowLan -ne $false)
    $s = $script:VpnSnap
    if ($null -eq $s) {
        Add-Note $ui.nw_List 'VPN ve gizlilik durumu okunuyor...'
        Start-VpnStatus
        if ($null -eq $script:NwSnap) { Start-NwScan }
        return
    }
    $act = $s.Active
    # --- durum
    Add-HeadRow $ui.nw_List 'Durum'
    $vpnBr = 'BrFaint'; $vpnTag = ('ba' + [char]0x011F + 'l' + [char]0x0131 + ' de' + [char]0x011F + 'il')
    if ($act.Any) { $vpnBr = 'BrGood'; $vpnTag = ('ba' + [char]0x011F + 'l' + [char]0x0131 + '') }
    $r = New-ItemRow @{ Title = ('VPN ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ''); Detail = (Get-VpnStateText $s); Tag = $vpnTag; BrCol = $vpnBr } @{} $false $false
    [void]$ui.nw_List.Children.Add($r)
    $ks = $s.Ks
    $ksBr = 'BrFaint'; $ksTag = ('kapal' + [char]0x0131 + ''); $ksDet = ('Kapal' + [char]0x0131 + 'yken VPN koparsa trafi' + [char]0x011F + 'iniz sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'ya a' + [char]0x00E7 + '' + [char]0x0131 + 'k a' + [char]0x011F + 'dan, korumas' + [char]0x0131 + 'z gider.')
    if ($ks.Effective) { $ksBr = 'BrGood'; $ksTag = ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k'); $ksDet = ('Giden trafik varsay' + [char]0x0131 + 'lan' + [char]0x0131 + ' Engelle; yaln' + [char]0x0131 + 'zca VPN sunucusu ve t' + [char]0x00FC + 'nel ge' + [char]0x00E7 + 'ebilir. VPN koparsa internet de kesilir.') }
    elseif ($ks.On) { $ksBr = 'BrWarn'; $ksTag = ('yar' + [char]0x0131 + 'm'); $ksDet = ('Kurallar ya da varsay' + [char]0x0131 + 'lan eksik; etkisiz olabilir. Kapat' + [char]0x0131 + 'p yeniden a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') }
    $r = New-ItemRow @{ Title = 'Kill-switch'; Detail = $ksDet; Tag = $ksTag; BrCol = $ksBr } @{} $false $false
    [void]$ui.nw_List.Children.Add($r)
    $dohBr = 'BrFaint'; $dohTag = ('kapal' + [char]0x0131 + ''); $dohDet = ('DNS sorgular' + [char]0x0131 + ' (hangi siteye girdi' + [char]0x011F + 'iniz) ' + [char]0x015F + 'ifresiz gider.')
    if (-not $s.Doh.Supported) { $dohTag = 'desteklenmiyor'; $dohDet = ('Yerle' + [char]0x015F + 'ik ' + [char]0x015F + 'ifreli DNS yaln' + [char]0x0131 + 'zca Windows 11 ile gelir. Taray' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n "g' + [char]0x00FC + 'venli DNS" ayar' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'n (Edge, Chrome, Firefox: Gizlilik > G' + [char]0x00FC + 'venlik > G' + [char]0x00FC + 'venli DNS).') }
    elseif ($s.Doh.Active) { $dohBr = 'BrGood'; $dohTag = ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k'); $dohDet = ('DNS sorgular' + [char]0x0131 + ' HTTPS ile gidiyor') + $(if ([string]$s.Doh.Provider -ne '') { ' (' + [string]$s.Doh.Provider + ')' } else { '' }) + '.' }
    $r = New-ItemRow @{ Title = ('' + [char]0x015E + 'ifreli DNS'); Detail = $dohDet; Tag = $dohTag; BrCol = $dohBr } @{} $false $false
    [void]$ui.nw_List.Children.Add($r)
    if ($script:VpnMsg -ne '' -and $null -ne $script:VpnMsg) { Add-Note $ui.nw_List ([string]$script:VpnMsg) 'dim' }

    # --- WireGuard
    Add-HeadRow $ui.nw_List ('WireGuard t' + [char]0x00FC + 'nelleri')
    if ([string]$s.WgExe -eq '') {
        $c = @($s.Clients | Where-Object { [string]$_.Id -eq 'WireGuard.WireGuard' })
        $r = New-ItemRow @{ Title = ('WireGuard kurulu de' + [char]0x011F + 'il'); Detail = ('Ba' + [char]0x011F + 'lanmak i' + [char]0x00E7 + 'in resm' + [char]0x00EE + ' WireGuard istemcisi gerekir (winget deposundan, imza ve ' + [char]0x00F6 + 'zet do' + [char]0x011F + 'rulamal' + [char]0x0131 + ' kurulur). Kurulumdan sonra yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rma dosyan' + [char]0x0131 + 'z' + [char]0x0131 + ' i' + [char]0x00E7 + 'e aktar' + [char]0x0131 + 'n.'); Tag = 'gerekli'; BrCol = 'BrWarn'; Btn1 = 'WireGuard kur' } @{ Id = 'WireGuard.WireGuard'; Name = 'WireGuard' } $false $false
        $r.FindName('Act').Add_Click($script:H_VpnInstall)
        [void]$ui.nw_List.Children.Add($r)
    }
    $tun = @($s.Tunnels)
    if ($tun.Count -eq 0) {
        Add-Note $ui.nw_List ('Hen' + [char]0x00FC + 'z t' + [char]0x00FC + 'nel yok. Sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'zdan ya da kendi sunucunuzdan ald' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z .conf dosyas' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x201C + 'WireGuard i' + [char]0x00E7 + 'e aktar' + [char]0x201D + ' ile ekleyin. Dosya burada do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r; komut ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'ran sat' + [char]0x0131 + 'rlar (PostUp vb.) ve bozuk anahtarlar reddedilir.')
    }
    foreach ($t in $tun) {
        $det = ''
        if ([string]$t.Err -ne '') { $det = ('Yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rma ge' + [char]0x00E7 + 'ersiz: ') + [string]$t.Err }
        elseif ($t.Mine -eq $true) {
            $det = 'Sunucu ' + [string]$t.Endpoint + ('  ' + [char]0x00B7 + '  adres ') + (@($t.Addresses) -join ', ')
            if (@($t.Dns).Count -gt 0) { $det += ('  ' + [char]0x00B7 + '  DNS ') + (@($t.Dns) -join ', ') }
            if ($t.Full4 -and $t.Full6) { $det += ('  ' + [char]0x00B7 + '  t' + [char]0x00FC + 'm trafik t' + [char]0x00FC + 'nelden') } elseif ($t.Full4) { $det += ('  ' + [char]0x00B7 + '  IPv4 t' + [char]0x00FC + 'nelden (IPv6 d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + 'da)') } else { $det += ('  ' + [char]0x00B7 + '  b' + [char]0x00F6 + 'l' + [char]0x00FC + 'nm' + [char]0x00FC + '' + [char]0x015F + ' t' + [char]0x00FC + 'nel') }
            if (@($t.Warnings).Count -gt 0) { $det += ('  ' + [char]0x00B7 + '  ') + [string]$t.Warnings[0] }
        } else { $det = ('WireGuard uygulamas' + [char]0x0131 + 'nda tan' + [char]0x0131 + 'ml' + [char]0x0131 + '; buradan yaln' + [char]0x0131 + 'zca kesilebilir.') }
        $br = 'BrFaint'; $tag = ('ba' + [char]0x011F + 'l' + [char]0x0131 + ' de' + [char]0x011F + 'il')
        if ($t.Up -eq $true) { $br = 'BrGood'; $tag = ('ba' + [char]0x011F + 'l' + [char]0x0131 + '') }
        $b1 = ('Ba' + [char]0x011F + 'lan'); if ($t.Up -eq $true) { $b1 = 'Kes' }
        if ($t.Mine -ne $true -and $t.Up -ne $true) { $b1 = '' }
        if ([string]$t.Err -ne '') { $b1 = ''; $br = 'BrBad'; $tag = ('hatal' + [char]0x0131 + '') }
        $b2 = ''; if ($t.Mine -eq $true) { $b2 = 'Sil' }
        $d = @{ Name = [string]$t.Name; Up = ($t.Up -eq $true); Mine = ($t.Mine -eq $true) }
        $r = New-ItemRow @{ Title = [string]$t.Name; Detail = $det; Tag = $tag; BrCol = $br; Btn1 = $b1; Btn2 = $b2 } $d $false $false
        if ($b1 -ne '') { $r.FindName('Act').Add_Click($script:H_VpnWg) }
        if ($b2 -ne '') { $r.FindName('Act2').Add_Click($script:H_VpnWgDel) }
        [void]$ui.nw_List.Children.Add($r)
    }

    # --- Windows VPN profilleri
    Add-HeadRow $ui.nw_List 'Windows VPN profilleri (IKEv2)'
    $prof = @($s.Profiles)
    if ($prof.Count -eq 0) { Add-Note $ui.nw_List ('Windows' + [char]0x2019 + 'un kendi VPN istemcisiyle IKEv2 sunucusuna ba' + [char]0x011F + 'lanabilirsiniz (kurumsal VPN ya da IKEv2 sunan sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'lar). ' + [char]0x201C + 'Windows VPN ekle' + [char]0x201D + ' ile profil olu' + [char]0x015F + 'turun; parola kaydedilmez, ba' + [char]0x011F + 'lan' + [char]0x0131 + 'rken Windows sorar.') }
    foreach ($p in $prof) {
        $br = 'BrFaint'; $tag = ('ba' + [char]0x011F + 'l' + [char]0x0131 + ' de' + [char]0x011F + 'il')
        if ($p.Connected) { $br = 'BrGood'; $tag = ('ba' + [char]0x011F + 'l' + [char]0x0131 + '') }
        $det = 'Sunucu ' + [string]$p.Server + ('  ' + [char]0x00B7 + '  ') + [string]$p.Tunnel + ('  ' + [char]0x00B7 + '  ') + [string]$p.Auth + ('  ' + [char]0x00B7 + '  ' + [char]0x015F + 'ifreleme: ') + [string]$p.Enc
        if ($p.Split) { $det += ('  ' + [char]0x00B7 + '  b' + [char]0x00F6 + 'l' + [char]0x00FC + 'nm' + [char]0x00FC + '' + [char]0x015F + ' t' + [char]0x00FC + 'nel') }
        $b1 = ('Ba' + [char]0x011F + 'lan'); if ($p.Connected) { $b1 = 'Kes' }
        $d = @{ Name = [string]$p.Name; Up = [bool]$p.Connected; AllUser = [bool]$p.AllUser }
        $r = New-ItemRow @{ Title = [string]$p.Name; Detail = $det; Tag = $tag; BrCol = $br; Btn1 = $b1; Btn2 = 'Sil' } $d $false $false
        $r.FindName('Act').Add_Click($script:H_VpnIke)
        $r.FindName('Act2').Add_Click($script:H_VpnIkeDel)
        [void]$ui.nw_List.Children.Add($r)
    }

    # --- sifreli DNS
    Add-HeadRow $ui.nw_List ('' + [char]0x015E + 'ifreli DNS (DoH)')
    if ($s.Doh.Supported) {
        foreach ($k in @('cloudflare', 'google', 'quad9', 'adguard')) {
            $pv = $script:DohProviders[$k]
            $isOn = ($s.Doh.Active -eq $true -and [string]$s.Doh.Provider -eq [string]$pv.N)
            $tag = ''; $br = 'BrFaint'
            if ($isOn) { $tag = 'etkin'; $br = 'BrGood' }
            $desc = ''
            foreach ($dp in $script:DnsProviders) { if ([string]$dp.Id -eq $k) { $desc = [string]$dp.D } }
            $r = New-ItemRow @{ Title = [string]$pv.N; Detail = ($desc + '  ' + [string]$pv.Tpl); Tag = $tag; BrCol = $br; Btn1 = ('Etkinle' + [char]0x015F + 'tir') } @{ Provider = $k; Name = [string]$pv.N } $false $false
            $r.FindName('Act').Add_Click($script:H_VpnDoh)
            [void]$ui.nw_List.Children.Add($r)
        }
        $r = New-ItemRow @{ Title = ('Otomatik ' + [char]0x015F + 'ifreli DNS' + [char]0x2019 + 'i kapat'); Detail = ('DNS sunucular' + [char]0x0131 + ' sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n verdi' + [char]0x011F + 'i (DHCP) ayara d' + [char]0x00F6 + 'ner.'); Tag = ''; BrCol = 'BrFaint'; Btn1 = 'Kapat' } @{ Provider = 'off'; Name = 'Kapat' } $false $false
        $r.FindName('Act').Add_Click($script:H_VpnDoh)
        [void]$ui.nw_List.Children.Add($r)
        Add-Note $ui.nw_List ('DNS ' + [char]0x015F + 'ifrelemesi, hangi alan adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' sorgulad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' a' + [char]0x011F + 'daki ' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'nc' + [char]0x00FC + ' ki' + [char]0x015F + 'ilerden saklar; se' + [char]0x00E7 + 'ti' + [char]0x011F + 'iniz DNS sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + ' sorgular' + [char]0x0131 + ' yine g' + [char]0x00F6 + 'r' + [char]0x00FC + 'r. Sunucu yan' + [char]0x0131 + 't vermezse Windows d' + [char]0x00FC + 'z DNS yede' + [char]0x011F + 'ine d' + [char]0x00F6 + 'ner (ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kopmaz).')
    } else {
        Add-Note $ui.nw_List ('Bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde yerle' + [char]0x015F + 'ik DoH yok. Taray' + [char]0x0131 + 'c' + [char]0x0131 + 'da a' + [char]0x00E7 + '' + [char]0x0131 + 'n: Edge ve Chrome i' + [char]0x00E7 + 'in Ayarlar > Gizlilik ve g' + [char]0x00FC + 'venlik > G' + [char]0x00FC + 'venli DNS kullan; Firefox i' + [char]0x00E7 + 'in Ayarlar > Gizlilik ve G' + [char]0x00FC + 'venlik > DNS over HTTPS.')
    }

    # --- istemciler
    Add-HeadRow $ui.nw_List ('' + [char]0x00D6 + 'nerilen resm' + [char]0x00EE + ' istemciler')
    foreach ($c in @($s.Clients)) {
        $tag = ('kurulu de' + [char]0x011F + 'il'); $br = 'BrFaint'; $b1 = 'Kur'
        if ($c.Installed) { $tag = 'kurulu'; $br = 'BrGood'; $b1 = '' }
        $r = New-ItemRow @{ Title = [string]$c.Name; Detail = [string]$c.Desc; Tag = $tag; BrCol = $br; Btn1 = $b1 } @{ Id = [string]$c.Id; Name = [string]$c.Name } $false $false
        if ($b1 -ne '') { $r.FindName('Act').Add_Click($script:H_VpnInstall) }
        [void]$ui.nw_List.Children.Add($r)
    }
    Add-Note $ui.nw_List ('' + [char]0x00DC + 'cretsiz ve tan' + [char]0x0131 + 't' + [char]0x0131 + 'm' + [char]0x0131 + ' belirsiz VPN uygulamalar' + [char]0x0131 + 'ndan ka' + [char]0x00E7 + '' + [char]0x0131 + 'n' + [char]0x0131 + 'n: trafi' + [char]0x011F + 'iniz o ' + [char]0x015F + 'irketin sunucular' + [char]0x0131 + 'ndan ge' + [char]0x00E7 + 'er ve kay' + [char]0x0131 + 't tutulup sat' + [char]0x0131 + 'labilir. VPN sizi internet sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'zdan ve ortak Wi-Fi sahibinden saklar, ama g' + [char]0x00FC + 'veni VPN sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + 'na ta' + [char]0x015F + '' + [char]0x0131 + 'r; ad' + [char]0x0131 + 'n' + [char]0x0131 + 'za a' + [char]0x00E7 + '' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' hesaplarda oturum a' + [char]0x00E7 + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda kim oldu' + [char]0x011F + 'unuzu yine g' + [char]0x00F6 + 'sterirsiniz.')

    # --- sizinti sinamasi
    $lk = $script:VpnLeak
    if ($null -ne $lk) {
        Add-HeadRow $ui.nw_List ('S' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' s' + [char]0x0131 + 'namas' + [char]0x0131 + '')
        foreach ($row in @($lk.Rows)) {
            $br = 'BrInfo'
            switch ([string]$row.Status) { 'ok' { $br = 'BrGood' } 'warn' { $br = 'BrWarn' } 'bad' { $br = 'BrBad' } }
            $b1 = ''; $dd = @{}
            if ([string]$row.Title -like ('T' + [char]0x00FC + 'nel d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'ndaki ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'larda DNS*')) { $b1 = ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' ad ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mlemeyi kapat'); $dd = @{ K = 'smart' } }
            $r = New-ItemRow @{ Title = [string]$row.Title; Detail = [string]$row.Detail; Tag = ''; BrCol = $br; Btn1 = $b1 } $dd $false $false
            if ($b1 -ne '') { $r.FindName('Act').Add_Click($script:H_VpnSmart) }
            [void]$ui.nw_List.Children.Add($r)
        }
        Add-Note $ui.nw_List ('Bu s' + [char]0x0131 + 'nama adresinizin d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + 'dan nas' + [char]0x0131 + 'l g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nd' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + 'n' + [char]0x00FC + ' ve yerel DNS yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rmas' + [char]0x0131 + 'n' + [char]0x0131 + ' denetler; a' + [char]0x011F + ' paketlerini yakalamaz.')
    }
    $ui.nw_Foot.Text = (Tr $(('Bu uygulama kendi t' + [char]0x00FC + 'nel ya da ' + [char]0x015F + 'ifreleme kodu i' + [char]0x00E7 + 'ermez: WireGuard' + [char]0x2019 + '' + [char]0x0131 + ' resm' + [char]0x00EE + ' istemciyle, IKEv2' + [char]0x2019 + 'yi Windows' + [char]0x2019 + 'un yerle' + [char]0x015F + 'ik bile' + [char]0x015F + 'eniyle ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'r. Kill-switch yaln' + [char]0x0131 + 'zca Windows G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + ' kurallar' + [char]0x0131 + 'd' + [char]0x0131 + 'r ve her zaman kapat' + [char]0x0131 + 'labilir.')))
}

# ---------------- eylemler ----------------
function Invoke-VpnAct([hashtable]$P, [string]$Label, [scriptblock]$After = $null) {
    $script:VpnAfter = $After
    [void](Start-Async 'VpnAct' 'Job_VpnAction' $P {
        param($r)
        $a = $script:VpnAfter
        $script:VpnAfter = $null
        if ($null -eq $r) { Show-Toast ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
        $script:VpnMsg = ''
        if ($r.Ok -eq $true) { Show-Toast ([string]$r.Msg) 'good' } else { Show-Toast ([string]$r.Msg) 'bad' }
        if ($null -ne $a) { try { & $a $r } catch { Show-Crash $_ 'VPN' } }
        $script:VpnSnap = $null
        Start-VpnStatus
    } $Label)
}

$script:H_VpnWg = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        if ($d.Up -eq $true) {
            $msg = ('T' + [char]0x00FC + 'nel kesilecek: ') + [string]$d.Name
            if ($script:VpnSnap.Ks.Effective) { $msg += "`r`n`r`nKill-switch a$([char]0x00E7)$([char]0x0131)k: ba$([char]0x011F)lant$([char]0x0131) kesilirse internet de kesilir. $([char]0x00D6)nce kill-switch$([char]0x2019)i kapatmak isteyebilirsiniz." }
            $script:VpnPendingName = [string]$d.Name
            Show-Confirm ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'y' + [char]0x0131 + ' kes') $msg 'Kes' { Invoke-VpnAct @{ Op = 'WgDown'; Name = $script:VpnPendingName } ('T' + [char]0x00FC + 'nel kesiliyor') }
        } else {
            Invoke-VpnAct @{ Op = 'WgUp'; Name = [string]$d.Name } (('Ba' + [char]0x011F + 'lan' + [char]0x0131 + 'l' + [char]0x0131 + 'yor: ') + [string]$d.Name)
        }
    } 'VPN'
}

$script:H_VpnWgDel = {
    param($s, $e)
    Invoke-Safe {
        $script:VpnPendingName = [string]$s.Tag.Name
        Show-Confirm ('T' + [char]0x00FC + 'neli sil') ([string]$s.Tag.Name + " t$([char]0x00FC)nelinin yap$([char]0x0131)land$([char]0x0131)rmas$([char]0x0131) ($([char]0x00F6)zel anahtar dahil) bu bilgisayardan silinecek; ba$([char]0x011F)l$([char]0x0131)ysa $([char]0x00F6)nce kesilir. Sa$([char]0x011F)lay$([char]0x0131)c$([char]0x0131)n$([char]0x0131)zdan dosyay$([char]0x0131) yeniden alman$([char]0x0131)z gerekebilir.") 'Sil' { Invoke-VpnAct @{ Op = 'WgDel'; Name = $script:VpnPendingName } ('T' + [char]0x00FC + 'nel siliniyor') } $true
    } 'VPN'
}

$script:H_VpnIke = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        if ($d.Up -eq $true) { Invoke-VpnAct @{ Op = 'IkeDown'; Name = [string]$d.Name } ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kesiliyor') }
        else { Invoke-VpnAct @{ Op = 'IkeUp'; Name = [string]$d.Name } ('Ba' + [char]0x011F + 'lan' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') }
    } 'VPN'
}

$script:H_VpnIkeDel = {
    param($s, $e)
    Invoke-Safe {
        $script:VpnPendingName = [string]$s.Tag.Name
        $script:VpnPendingAll = ($s.Tag.AllUser -eq $true)
        Show-Confirm 'Profili sil' ([string]$s.Tag.Name + (' adl' + [char]0x0131 + ' Windows VPN profili silinecek.')) 'Sil' { Invoke-VpnAct @{ Op = 'IkeDel'; Name = $script:VpnPendingName; AllUser = $script:VpnPendingAll } 'Profil siliniyor' } $true
    } 'VPN'
}

$script:H_VpnInstall = {
    param($s, $e)
    Invoke-Safe {
        $script:VpnPendingId = [string]$s.Tag.Id
        $script:VpnPendingName = [string]$s.Tag.Name
        Show-Confirm ('' + [char]0x0130 + 'stemci kur') ([string]$s.Tag.Name + " winget deposundan kurulacak (paket imzas$([char]0x0131) ve $([char]0x00F6)zeti winget taraf$([char]0x0131)ndan do$([char]0x011F)rulan$([char]0x0131)r). Kurulum birka$([char]0x00E7) dakika s$([char]0x00FC)rebilir.") 'Kur' {
            [void](Start-Async 'Winget' 'Job_WingetInstall' @{ Id = $script:VpnPendingId } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('' + [char]0x0130 + 'stemci kuruldu.') 'good' } else { Show-Toast ('Kurulum tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
                $script:VpnSnap = $null
                Start-VpnStatus
            } ('Kuruluyor: ' + $script:VpnPendingName))
        }
    } 'VPN'
}

$script:H_VpnDoh = {
    param($s, $e)
    Invoke-Safe {
        if ($null -eq $script:NwSnap -or @($script:NwSnap.Adapters).Count -eq 0) {
            Show-Toast ('Etkin a' + [char]0x011F + ' ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + ' bulunamad' + [char]0x0131 + '; ' + [char]0x00F6 + 'nce Genel bak' + [char]0x0131 + '' + [char]0x015F + ' sekmesinden a' + [char]0x011F + '' + [char]0x0131 + ' okuyun.') 'warn'
            Start-NwScan
            return
        }
        $prov = [string]$s.Tag.Provider
        $ad = @($script:NwSnap.Adapters)
        $steps = New-DohSteps $prov $ad
        $script:PendingSteps = $steps
        $txt = ''
        if ($prov -eq 'off') { $txt = "Otomatik $([char]0x015F)ifreli DNS kapat$([char]0x0131)lacak ve DNS sunucular$([char]0x0131) sa$([char]0x011F)lay$([char]0x0131)c$([char]0x0131)n$([char]0x0131)z$([char]0x0131)n verdi$([char]0x011F)i (DHCP) ayara d$([char]0x00F6)necek.`r`n`r`nGeri al$([char]0x0131)nabilir." }
        else { $txt = [string]$s.Tag.Name + " $([char]0x015F)ifreli DNS olarak ayarlanacak (" + [string]$ad.Count + " ba$([char]0x011F)da$([char]0x015F)t$([char]0x0131)r$([char]0x0131)c$([char]0x0131)). DNS sorgular$([char]0x0131) HTTPS ile gider; sunucu yan$([char]0x0131)t vermezse d$([char]0x00FC)z DNS yede$([char]0x011F)i kullan$([char]0x0131)l$([char]0x0131)r.`r`n`r`nGeri al$([char]0x0131)nabilir."}
        Show-Confirm ('' + [char]0x015E + 'ifreli DNS') $txt 'Uygula' {
            Start-PlanJob $script:PendingSteps ('' + [char]0x015E + 'ifreli DNS ayarlan' + [char]0x0131 + 'yor') $false $false { $script:NwSnap = $null; Start-NwScan; $script:VpnSnap = $null; Start-VpnStatus }
        }
    } 'DoH'
}

$script:H_VpnSmart = {
    param($s, $e)
    Invoke-Safe {
        $script:PendingSteps = @(New-SmartNameStep)
        Show-Confirm ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' ad ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mlemeyi kapat') ("Windows normalde DNS sorgusunu t$([char]0x00FC)m a$([char]0x011F) ba$([char]0x011F)da$([char]0x015F)t$([char]0x0131)r$([char]0x0131)c$([char]0x0131)lar$([char]0x0131)na paralel g$([char]0x00F6)nderir; VPN a$([char]0x00E7)$([char]0x0131)kken bu, sorgular$([char]0x0131)n t$([char]0x00FC)nelin d$([char]0x0131)$([char]0x015F)$([char]0x0131)na da $([char]0x00E7)$([char]0x0131)kmas$([char]0x0131)na yol a$([char]0x00E7)ar. Bu ayar kapat$([char]0x0131)l$([char]0x0131)r (Grup $([char]0x0130)lkesi: Ak$([char]0x0131)ll$([char]0x0131) $([char]0x00E7)ok-a$([char]0x011F)l$([char]0x0131) ad $([char]0x00E7)$([char]0x00F6)z$([char]0x00FC)mlemeyi kapat).`r`n`r`nGeri al$([char]0x0131)nabilir.") 'Kapat' {
            Start-PlanJob $script:PendingSteps ('Ad ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mleme ayarlan' + [char]0x0131 + 'yor') $false $false { }
        }
    } 'DNS'
}

function Start-KsOn {
    [void](Start-Async 'KsCtx' 'Job_KsContext' @{} {
        param($r)
        if ($null -eq $r) { Show-Toast ('VPN durumu okunamad' + [char]0x0131 + '.') 'bad'; return }
        if ($r.Ok -ne $true) { Show-Message ('Kill-switch a' + [char]0x00E7 + '' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') ([string]$r.Why); return }
        $script:VpnCtx = $r
        $dnsTxt = ('T' + [char]0x00FC + 'nelde DNS sunucusu bulunamad' + [char]0x0131 + '; ayr' + [char]0x0131 + ' bir DNS s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' engeli eklenmeyecek.')
        if (@($r.Dns).Count -gt 0) { $dnsTxt = ('' + [char]0x0130 + 'zin verilen DNS: ') + (@($r.Dns) -join ', ') + (' (t' + [char]0x00FC + 'nel d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'na DNS sorgusu engellenir).') }
        $lan = ('Yerel a' + [char]0x011F + 'a (yaz' + [char]0x0131 + 'c' + [char]0x0131 + ', NAS, y' + [char]0x00F6 + 'nlendirici) eri' + [char]0x015F + 'im kapal' + [char]0x0131 + '.')
        if ($r.AllowLan) { $lan = ('Yerel a' + [char]0x011F + 'a eri' + [char]0x015F + 'im a' + [char]0x00E7 + '' + [char]0x0131 + 'k (Kapatmak i' + [char]0x00E7 + 'in a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'daki se' + [char]0x00E7 + 'ene' + [char]0x011F + 'i de' + [char]0x011F + 'i' + [char]0x015F + 'tirin).') }
        $txt = ('Ba' + [char]0x011F + 'l' + [char]0x0131 + ' t' + [char]0x00FC + 'nel: ') + [string]$r.Name + "`r`n" + ('Ge' + [char]0x00E7 + 'mesine izin verilen sunucu: ') + (@($r.Endpoints) -join ', ') + "`r`n" + $dnsTxt + "`r`n" + $lan + "`r`n`r`n" +
            "Windows G$([char]0x00FC)venlik Duvar$([char]0x0131)$([char]0x2019)nda giden trafik varsay$([char]0x0131)lan$([char]0x0131) ENGELLE olacak; yaln$([char]0x0131)zca VPN sunucusu ve t$([char]0x00FC)nel aray$([char]0x00FC)z$([char]0x00FC) ge$([char]0x00E7)ecek. VPN koparsa internet de kesilir; ama$([char]0x00E7) budur.`r`n`r`n" +
            "Kurduktan sonra internet ve ad $([char]0x00E7)$([char]0x00F6)z$([char]0x00FC)mleme s$([char]0x0131)nan$([char]0x0131)r, $([char]0x00E7)al$([char]0x0131)$([char]0x015F)mazsa kendili$([char]0x011F)inden geri al$([char]0x0131)n$([char]0x0131)r.`r`nKapatma yollar$([char]0x0131): bu sayfadaki Kill-switch kapat d$([char]0x00FC)$([char]0x011F)mesi, ba$([char]0x015F)l$([char]0x0131)k $([char]0x00E7)ubu$([char]0x011F)undaki KAPAT d$([char]0x00FC)$([char]0x011F)mesi, tepsi men$([char]0x00FC)s$([char]0x00FC) ve  Multimizer.ps1 -Cli -Gorev KorumaAc."
        Show-Confirm ('Kill-switch a' + [char]0x00E7 + '') $txt ('A' + [char]0x00E7 + '') {
            $stp = New-KsStep $script:VpnCtx $true
            Start-PlanJob @($stp) 'Kill-switch kuruluyor' $false $false {
                param($R)
                $script:VpnSnap = $null
                Update-KsButton
                if ($null -ne $R -and [int]$R.Changes -gt 0) {
                    [void](Start-Async 'KsVerify' 'Job_KsVerify' @{} {
                        param($v)
                        $script:Settings = Get-Settings
                        $script:VpnSnap = $null
                        if ($null -ne $v -and $v.Ok -eq $true) { Show-Toast ('Kill-switch a' + [char]0x00E7 + '' + [char]0x0131 + 'k ve do' + [char]0x011F + 'ruland' + [char]0x0131 + ': internet t' + [char]0x00FC + 'nel ' + [char]0x00FC + 'zerinden ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor.') 'good' }
                        elseif ($null -ne $v) { Show-Message ('Kill-switch geri al' + [char]0x0131 + 'nd' + [char]0x0131 + '') ('Kurulumdan sonra ' + [string]$v.Why + " Bu y$([char]0x00FC)zden kill-switch kapat$([char]0x0131)ld$([char]0x0131) ve internet eri$([char]0x015F)imi eski h$([char]0x00E2)line d$([char]0x00F6)nd$([char]0x00FC).`r`n`r`nT$([char]0x00FC)nelin DNS ayar$([char]0x0131)n$([char]0x0131) ve AllowedIPs de$([char]0x011F)erini denetleyin; sorun s$([char]0x00FC)rerse kill-switch$([char]0x2019)i kullanmay$([char]0x0131)n.") }
                        Update-KsButton
                        Start-VpnStatus
                    } ('Kill-switch do' + [char]0x011F + 'rulan' + [char]0x0131 + 'yor'))
                } else { Start-VpnStatus }
            }
        } $true
    } ('Kill-switch haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor'))
}

function Start-LeakTest {
    Show-Confirm ('S' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' s' + [char]0x0131 + 'namas' + [char]0x0131 + '') "Cloudflare$([char]0x2019)$([char]0x0131)n izleme sayfas$([char]0x0131)na (www.cloudflare.com/cdn-cgi/trace) tek bir HTTPS iste$([char]0x011F)i g$([char]0x00F6)nderilir; IPv6 varsa ikinci bir istek daha. Ki$([char]0x015F)isel veri g$([char]0x00F6)nderilmez; adresiniz zaten her istekte kar$([char]0x015F)$([char]0x0131) taraf$([char]0x00E7)a g$([char]0x00F6)r$([char]0x00FC)l$([char]0x00FC)r. VPN kapal$([char]0x0131)yken yap$([char]0x0131)lan $([char]0x00F6)l$([char]0x00E7)$([char]0x00FC)m kar$([char]0x015F)$([char]0x0131)la$([char]0x015F)t$([char]0x0131)rma i$([char]0x00E7)in ($([char]0x00F6)zet olarak) saklan$([char]0x0131)r." ('S' + [char]0x0131 + 'na') {
        [void](Start-Async 'Leak' 'Job_LeakTest' @{} {
            param($r)
            if ($null -eq $r -or $r.Ok -ne $true) {
                $why = ''; if ($null -ne $r) { $why = [string]$r.Why }
                Show-Toast (('S' + [char]0x0131 + 'nama yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '. ') + $why) 'warn'
                return
            }
            $script:VpnLeak = $r
            $script:Settings = Get-Settings
            if ([string]$script:UiState.Page -eq 'network' -and $script:NwTab -eq 'vpn') { Render-NwVpn }
        } ('S' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' s' + [char]0x0131 + 'namas' + [char]0x0131 + ''))
    }
}

function Init-VpnUi {
    $ui.nw_VpnRefresh.Add_Click({ Invoke-Safe { $script:VpnSnap = $null; Render-NwVpn } 'Yenile' })
    $ui.nw_VpnWgImport.Add_Click({
        Invoke-Safe {
            $f = Select-OpenFile ('WireGuard yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rmas' + [char]0x0131 + ' (*.conf)|*.conf;*.txt|T' + [char]0x00FC + 'm dosyalar (*.*)|*.*')
            if ($f -eq '') { return }
            Invoke-VpnAct @{ Op = 'WgImport'; Path = $f } ('Yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rma do' + [char]0x011F + 'rulan' + [char]0x0131 + 'yor') {
                param($r)
                if ($r.Ok -eq $true -and @($r.Warnings).Count -gt 0) {
                    Show-Message ('Yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rma eklendi, uyar' + [char]0x0131 + 'lar var') ((@($r.Warnings) | ForEach-Object { [string][char]0x2022 + ' ' + [string]$_ }) -join "`r`n")
                } elseif ($r.Ok -ne $true) {
                    Show-Message ('Yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rma reddedildi') ([string]$r.Msg)
                }
            }
        } ('' + [char]0x0130 + '' + [char]0x00E7 + 'e aktar')
    })
    $ui.nw_VpnIke.Add_Click({
        Invoke-Safe {
            Show-Input 'Windows VPN profili' ('Profil ad' + [char]0x0131 + ' (harf, rakam, bo' + [char]0x015F + 'luk, nokta, tire):') 'VPN' {
                param($nm)
                $script:VpnPendingName = ([string]$nm).Trim()
                if (-not (Test-VpnProfileName $script:VpnPendingName)) { Show-Toast ('Profil ad' + [char]0x0131 + ' ge' + [char]0x00E7 + 'ersiz.') 'warn'; return }
                Show-Input 'Windows VPN profili' ('Sunucu adresi (sa' + [char]0x011F + 'lay' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n IKEv2 sunucusu, ' + [char]0x00F6 + 'r. vpn.ornek.com):') '' {
                    param($srv)
                    $sv = ([string]$srv).Trim()
                    if (-not (Test-VpnServerText $sv)) { Show-Toast ('Sunucu adresi ge' + [char]0x00E7 + 'ersiz.') 'warn'; return }
                    $script:VpnPendingServer = $sv
                    Invoke-VpnAct @{ Op = 'IkeAdd'; Name = $script:VpnPendingName; Server = $sv } 'Profil ekleniyor' {
                        param($r)
                        if ($r.Ok -eq $true) {
                            Show-Confirm ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' ' + [char]0x015F + 'ifre paketi') "Sunucunuz GCM-AES ve DH Group14 (PFS 2048) destekliyorsa daha g$([char]0x00FC)$([char]0x00E7)l$([char]0x00FC) bir $([char]0x015F)ifre paketi uygulanabilir. Desteklemiyorsa ba$([char]0x011F)lant$([char]0x0131) kurulamaz; emin de$([char]0x011F)ilseniz Windows varsay$([char]0x0131)lan$([char]0x0131)n$([char]0x0131) b$([char]0x0131)rak$([char]0x0131)n." 'Uygula' { Invoke-VpnAct @{ Op = 'IkeStrong'; Name = $script:VpnPendingName } ('' + [char]0x015E + 'ifre paketi uygulan' + [char]0x0131 + 'yor') }
                        }
                    }
                }
            }
        } 'Windows VPN'
    })
    $ui.nw_KsOn.Add_Click({ Invoke-Safe { Start-KsOn } 'Kill-switch' })
    $ui.nw_KsOff.Add_Click({ Invoke-Safe { Start-KsOffNow } 'Kill-switch' })
    $ui.nw_VpnLeak.Add_Click({ Invoke-Safe { Start-LeakTest } ('S' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + '') })
    $ui.nw_KsLan.Add_Click({
        Invoke-Safe {
            $script:Settings.KsAllowLan = ($ui.nw_KsLan.IsChecked -eq $true)
            Save-Settings $script:Settings
            if ($null -ne $script:VpnSnap -and $script:VpnSnap.Ks.Effective) { Show-Toast ('De' + [char]0x011F + 'i' + [char]0x015F + 'iklik, kill-switch yeniden a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca ge' + [char]0x00E7 + 'erli olur.') 'info' }
        } 'Kill-switch'
    })
}

# Kill-switch acik kalmissa (uygulama kapanip acilinca) dugmeyi hemen goster
function Initialize-KsWatch {
    if (-not $script:KsWired) {
        $script:KsWired = $true
        try { $ui.BtnKsOff.Add_Click({ Invoke-Safe { Start-KsOffNow } 'Kill-switch' }) } catch { }
    }
    try { Update-KsButton } catch { }
}


# ---------------- Arayuz ekleri ----------------
# ==================================================================
#  ARAYUZ EKLERI: parola kutusu, gorunum (tema / animasyon), Ayarlar sayfasindaki istege bagli ozellikler,
#  internet istekleri, kayit saklama suresi, ayar bekcisi zamanlayicisi, tasinma kiti sekmesi
# ==================================================================

# ---------------- parola kutusu (sifreleme icin) ----------------
# Confirm: parola iki kez sorulur. OnOk parolayi parametre olarak alir; parola alanlari kapaninca temizlenir.
$script:OvPwConfirm = $false

function Show-Password([string]$Title, [string]$Text, [bool]$Confirm, [scriptblock]$OnOk) {
    $ui.OvPw1.Password = ''
    $ui.OvPw2.Password = ''
    $ui.OvErr.Text = (Tr $(''))
    $ui.OvErr.Visibility = $script:VisOff
    Show-Overlay $Title $Text 'Tamam' $true $false $false '' $OnOk
    $script:OvMode = 'password'
    $script:OvPwConfirm = $Confirm
    $ui.OvPw1.Visibility = $script:VisOn
    if ($Confirm) { $ui.OvPw2.Visibility = $script:VisOn } else { $ui.OvPw2.Visibility = $script:VisOff }
    [void]$ui.OvPw1.Focus()
}

# ---------------- gorunum: tema ve animasyon ----------------
# Acik (beyaz) varsayilan temadir. XAML'e Neon (koyu neon) renkleri gomulur; acilista Set-AppTheme paleti pencere kaynaklarina yerinde yazar. Koyu: daha az doygun. Yuksek: siyah zemin, beyaz yazi.
# Hacker: siyah zemin, fosfor yesili. Sade artik tema degil yerlesimdir (bkz. Gorunum bolumu).
# ==================================================================
#  TEMA PALETLERI (tek kaynak)
#  $script:Themes     : her tema ayni firca anahtarlarini tasir; Set-AppTheme bu renkleri pencere kaynaklarina yerinde yazar.
#  $script:ThemeGrads : arka plan gecisinin (BrBgGrad) uc rengi.
#  Yazi / zemin karsitligi WCAG olcusuyle denetlenir (tests/t_theme.ps1). Yari saydam (#AARRGGBB) renkler yalnizca cam temalarinin
#  Card / Rail / Panel / baslik cubugunda bulunur; diger her sey opaktir.
#  *Soft anahtarlari: renkli simge ciplerinin zemini (ayni rengin kart rengiyle %14-20 karisimi); ana ekran kartlari, anlamlarina gore
#  (saglik yesil, ag mavi, bakim altin, gelismis eflatun...) kendi renginde simge ve cip alir (bkz. BoardActionAccent).
# ==================================================================
$script:Themes = [ordered]@{
    # Neon (Futuristik)
    Neon = [ordered]@{
        BrBg = '#080B16'; BrTitle = '#0A0F1F'; BrRail = '#0A0F1E'; BrPanel = '#0E1427'; BrPanel2 = '#131B35'; BrCard = '#141C38'
        BrLine = '#222C52'; BrLine2 = '#34406F'; BrHover = '#1A2347'; BrActiveBg = '#0F2F33'
        BrText = '#E2E8F8'; BrDim = '#8591B8'; BrFaint = '#5E6A94'
        BrAccent = '#2FE0B5'; BrAccentDim = '#1B8C74'; BrAccent2 = '#8C6BFF'; BrBlue = '#4FA3FF'
        BrGold = '#E2A93F'; BrGoldDim = '#7A5C22'; BrGoldBg = '#1B1710'
        BrGood = '#34D399'; BrWarn = '#F6B94B'; BrBad = '#FF5C7C'; BrInfo = '#6EA8FF'; BrLogGreen = '#52E08F'; BrOverlay = '#D0050810'
        BrOnAccent = '#04110E'; BrDangerBg = '#2A1019'; BrDangerFg = '#FF9DB0'; BrMapBg = '#0A0F20'; BrTipBg = '#E6131B35'
        BrBlueSoft = '#203760'; BrGoodSoft = '#1A414B'; BrAccent2Soft = '#2C2C60'
    }
    # Koyu (grafit zemin, mavi ve eflatun vurgu)
    Koyu = [ordered]@{
        BrBg = '#0F1115'; BrTitle = '#13161B'; BrRail = '#111419'; BrPanel = '#171A21'; BrPanel2 = '#1C2029'; BrCard = '#1E222B'
        BrLine = '#2A2F3B'; BrLine2 = '#3A4150'; BrHover = '#262B36'; BrActiveBg = '#1A2B4C'
        BrText = '#E8ECF4'; BrDim = '#A1A9BA'; BrFaint = '#7B8497'
        BrAccent = '#6EA8FF'; BrAccentDim = '#2F66C9'; BrAccent2 = '#B79CFF'; BrBlue = '#5CC8F2'
        BrGold = '#F0B94D'; BrGoldDim = '#7A6430'; BrGoldBg = '#211D12'
