# Arka plan gecisinin (BrBgGrad) uc rengi
$script:ThemeGrads = @{
    Neon   = @('#0D1426', '#080B16', '#0A0D1C')
    Koyu   = @('#151922', '#0F1115', '#12151B')
    Acik   = @('#FBFCFE', '#F6F8FB', '#FBFCFE')
    Kum    = @('#FDF9F1', '#F5EEE1', '#F9ECE4')
    Yuksek = @('#000000', '#000000', '#000000')
    Hacker = @('#020C05', '#000000', '#010703')
    Cam    = @('#C4DBFF', '#DDD0FF', '#FFCFE8')
    Holo   = @('#071B3A', '#1A0B3D', '#2A0B3A')
    Akis   = @('#1B3FAE', '#6A22B0', '#9A1F74')
    Uzay   = @('#14061F', '#2A0A33', '#3D0A22')
}
$script:ThemeName = 'Neon'
$script:ThemeFail = 0


# ONEMLI - tema, pencere kaynaklarindaki fircalarin RENGINI yerinde degistirir; kaynak sozlugune yeni nesne YAZMAZ.
# Neden: PowerShell'de .NET dizinleyicisine atama ($kaynaklar[$anahtar] = New-Object ...) nesneyi PSObject sarmalayicisiyla
# saklar. WPF bunu Brush olarak okuyamaz ("PSObject ... Brush turune atilamadi") ve pencere cizilirken uygulama kapanir.
# Yerinde guncelleme bu hatayi kokunden kaldirir. Koddan uretilen ogelerin fircalari ayridir (Get-Br / Sync-CodeBrushes asagida).
function Set-BrushColor($Res, [string]$Key, [string]$Hex) {
    $col = [System.Windows.Media.Color][System.Windows.Media.ColorConverter]::ConvertFromString($Hex)
    $cur = $null
    try { $cur = $Res[$Key] } catch { $cur = $null }
    if (($cur -is [System.Windows.Media.SolidColorBrush]) -and (-not $cur.IsFrozen)) {
        $cur.Color = $col
        return $true
    }
    # Yedek yol (dondurulmus ya da eksik firca): yontem cagrisi sarmalayiciyi acar, dizinleyici acmaz.
    # Koddan uretilen ogelerin fircalari (Get-Br) ayri kopyalardir ve Sync-CodeBrushes ile guncellenir; burada dokunulmaz.
    $nb = [System.Windows.Media.SolidColorBrush]::new($col)
    if ($Res.Contains($Key)) { $Res.Remove($Key) }
    $Res.Add($Key, $nb)
    return $true
}

# Koddan uretilen ogelerin (gunluk satiri, komut satiri, surec satiri, not, topoloji cizgisi...) fircalari.
# Pencere kaynaklarindaki fircalar dondurulmus olabilir (stillerde StaticResource ile kullanilanlar WPF'ce dondurulur). Dondurulmus fircaya
# yerinde renk yazilamaz; Set-BrushColor onu sozlukte yeni nesneyle degistirir ve koddaki ogeler eski nesneyi tutmaya devam ederdi
# (beyaz temada eski neon renkli gunluk satirlari gibi). Bu yuzden koda, kaynagin DONDURULMAMIS OZEL kopyasi verilir; tema her
# degistiginde Sync-CodeBrushes bu kopyalarin rengini yerinde gunceller, ogeler ayni nesneyi tuttugu icin hepsi birlikte degisir.
function Get-Br([string]$Key) {
    $b = $script:BrushCache[$Key]
    if ($null -ne $b) { return $b }
    $res = $script:Win.FindResource($Key)
    if ($res -is [System.Windows.Media.SolidColorBrush]) { $b = $res.Clone() } else { $b = $res }
    $script:BrushCache[$Key] = $b
    return $b
}

# Onbellekteki ozel fircalarin rengini pencere kaynaklarindaki guncel renge ceker. Dondurdugu sayi: rengi degisen firca adedi.
function Sync-CodeBrushes {
    $n = 0
    foreach ($k in @($script:BrushCache.Keys)) {
        $b = $script:BrushCache[$k]
        if (($b -is [System.Windows.Media.SolidColorBrush]) -and (-not $b.IsFrozen)) {
            $res = $null
            try { $res = $script:Win.TryFindResource([string]$k) } catch { $res = $null }
            if (($res -is [System.Windows.Media.SolidColorBrush]) -and ($b.Color -ne $res.Color)) { $b.Color = $res.Color; $n++ }
        }
    }
    return $n
}

# Koddaki fircalar temayla uyusuyor mu? Uyusmayanlarin adlarini dondurur (bossa tamam). Ayrica gunluk ve komut satirindaki her satirin
# onbellekteki (guncellenen) fircayi tuttugu denetlenir; oyle olmayan satir tema degisince eski rengini korurdu.
function Get-CodeBrushProblems {
    $bad = New-Object System.Collections.ArrayList
    $vals = New-Object System.Collections.ArrayList
    foreach ($k in @($script:BrushCache.Keys)) {
        $b = $script:BrushCache[$k]
        [void]$vals.Add($b)
        if ($b -is [System.Windows.Media.SolidColorBrush]) {
            $res = $null
            try { $res = $script:Win.TryFindResource([string]$k) } catch { $res = $null }
            if (($res -is [System.Windows.Media.SolidColorBrush]) -and ($b.Color -ne $res.Color)) { [void]$bad.Add([string]$k) }
        }
    }
    foreach ($pn in @('LogStack', 'CmdOut')) {
        $pnl = $ui[$pn]
        if ($null -eq $pnl) { continue }
        $miss = 0
        foreach ($c in $pnl.Children) {
            $f = $c.Foreground
            $hit = $false
            foreach ($v in $vals) { if ([object]::ReferenceEquals($v, $f)) { $hit = $true; break } }
            if (-not $hit) { $miss++ }
        }
        if ($miss -gt 0) { [void]$bad.Add($pn + (' (' + [char]0x00F6 + 'nbellek d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' f' + [char]0x0131 + 'r' + [char]0x00E7 + 'al' + [char]0x0131 + ' sat' + [char]0x0131 + 'r: ') + [string]$miss + ')') }
    }
    return $bad.ToArray()
}

# Kaynaklardaki fircalar secili temayla uyusuyor mu? Uyusmayan anahtarlarin adlarini dondurur (bossa tema tam oturmustur).
function Get-ThemeProblems([string]$Name) {
    $bad = New-Object System.Collections.ArrayList
    if (-not $script:Themes.Contains($Name)) { [void]$bad.Add('?'); return $bad.ToArray() }
    $tbl = $script:Themes[$Name]
    foreach ($k in @($tbl.Keys)) {
        $cur = $null
        try { $cur = $script:Win.Resources[[string]$k] } catch { $cur = $null }
        if (-not ($cur -is [System.Windows.Media.SolidColorBrush])) { [void]$bad.Add([string]$k); continue }
        $want = [System.Windows.Media.Color][System.Windows.Media.ColorConverter]::ConvertFromString((Get-GlassHex ([string]$k) ([string]$tbl[$k])))
        if ($cur.Color -ne $want) { [void]$bad.Add([string]$k) }
    }
    return $bad.ToArray()
}

# Temayi uygular. Basarisiz renk sayisi $script:ThemeFail icinde kalir (0 = tam).
function Set-AppTheme([string]$Name) {
    if (-not $script:Themes.Contains($Name)) { $Name = 'Neon' }
    try { Initialize-GlassState $Name } catch { $script:GlassAlpha = 1.0 }
    $tbl = $script:Themes[$Name]
    $res = $script:Win.Resources
    $fail = 0
    foreach ($k in @($tbl.Keys)) {
        try { [void](Set-BrushColor $res ([string]$k) (Get-GlassHex ([string]$k) ([string]$tbl[$k]))) }
        catch { $fail++; Write-WhLog (('Tema rengi uygulanamad' + [char]0x0131 + ': ') + [string]$k + ' (' + $_.Exception.Message + ')') 'WARN' }
    }
    try {
        $g = $res['BrBgGrad']
        $cols = @($script:ThemeGrads[$Name])
        if (($g -is [System.Windows.Media.LinearGradientBrush]) -and (-not $g.IsFrozen) -and $g.GradientStops.Count -ge 3 -and $cols.Count -ge 3) {
            for ($i = 0; $i -lt 3; $i++) {
                $g.GradientStops[$i].Color = [System.Windows.Media.Color][System.Windows.Media.ColorConverter]::ConvertFromString((Get-GlassHex 'BrBg' ([string]$cols[$i])))
            }
        }
    } catch { $fail++; Write-WhLog (('Tema arka plan' + [char]0x0131 + ' uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    # Koddan uretilmis ogeler (gunluk satirlari, surec satirlari, notlar...) yeni renkleri alsin
    try { [void](Sync-CodeBrushes) } catch { $fail++; Write-WhLog (('Kod f' + [char]0x0131 + 'r' + [char]0x00E7 + 'alar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncellenemedi: ') + $_.Exception.Message) 'WARN' }
    $left = @(Get-ThemeProblems $Name)
    if ($left.Count -gt 0) { $fail = [math]::Max($fail, $left.Count) }
    $script:ThemeName = $Name
    $script:ThemeFail = $fail
    try { Update-GlassTheme } catch { Write-CrashLog ('Saydamlik (tema): ' + $_.Exception.Message) }
}

# Animasyonlar su durumlarda kisilir: Ayarlar'da istenmisse, Sade yerlesim, Windows'ta animasyonlar kapaliysa, 4 GB'tan az bellek
function Update-ReduceMotion {
    $r = ($script:Settings.ReduceMotion -eq $true) -or ([string]$script:Settings.Layout -eq 'Sade')
    try { if (-not [System.Windows.SystemParameters]::ClientAreaAnimation) { $r = $true } } catch { }
    try { $gb = [double]$sync.Profile.RamGB; if ($gb -gt 0 -and $gb -lt 4) { $r = $true } } catch { }
    $script:ReduceMotion = $r
}

function Initialize-Appearance {
    $raw = [string]$script:Settings.Theme
    $t = ConvertTo-ThemeKey $raw
    # Kayitli eski "Sade" tema artik yerlesimdir: renkler Koyu'ya tasinir, animasyonlar kapali kalir
    if ($raw -eq 'Sade') { Set-SettingsKeys @{ Theme = 'Koyu'; ReduceMotion = $true } }
    # Windows yuksek karsitlik kipindeyse ve tema secilmemisse yuksek karsitlik uygulanir (guvenli baslangicta uygulanmaz)
    try { if (-not $script:SafeBoot -and [System.Windows.SystemParameters]::HighContrast -and $t -eq 'Acik') { $t = 'Yuksek' } } catch { }
    try { Initialize-GlassState $t } catch { $script:GlassAlpha = 1.0 }
    if ($t -ne 'Neon' -or $script:GlassAlpha -lt 0.999) {
        # Tema tam oturmazsa pencere acilmadan once varsayilan gorunume donulur (kayitli secim de duzeltilir)
        $ok = $true
        try { Set-AppTheme $t; if ($script:ThemeFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Tema uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
        if (-not $ok) {
            try { Disable-GlassState } catch { }
            Write-WhLog ('Tema (' + $t + (') tam uygulanamad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' i' + [char]0x00E7 + 'in g' + [char]0x00FC + 'venli g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'me d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + '.')) 'WARN'
            try { Set-AppTheme 'Neon' } catch { }
            if ([string]$script:Settings.Theme -eq $t) { Set-SettingsKeys @{ Theme = 'Neon' } }
        }
    }
    Update-ReduceMotion
}

# ---------------- Ayarlar: satir uretici ----------------
$script:StOptBoxes = @{}
$script:StNetBoxes = @{}

function Add-StToggleRow($Panel, [string]$Title, [string]$Detail, [bool]$Checked, [string]$Tag, [scriptblock]$OnClick) {
    $cb = New-Object System.Windows.Controls.CheckBox
    $cb.Content = (Tr $($Title))
    $cb.Style = $script:Win.FindResource('Toggle')
    $cb.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 12, 0, 0
    $cb.IsChecked = $Checked
    $cb.Tag = $Tag
    $cb.Add_Click($OnClick)
    [void]$Panel.Children.Add($cb)
    if ($Detail -ne '') {
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.Text = (Tr $($Detail))
        $tb.Style = $script:Win.FindResource('TxtDim')
        $tb.Margin = New-Object System.Windows.Thickness -ArgumentList 40, 3, 0, 0
        [void]$Panel.Children.Add($tb)
    }
    return $cb
}

# ---------------- Ayarlar: istege bagli ozellikler ----------------
$script:H_StOpt = {
    param($s, $e)
    if ($script:StLoading) { return }
    Invoke-Safe {
        $name = [string]$s.Tag
        $on = ($s.IsChecked -eq $true)
        Set-OptValue $name $on
        $title = [string]$script:OptInfo[$name].T
        if ($on) { Show-Toast ($title + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '.')) 'info' } else { Show-Toast ($title + (' kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '.')) 'info' }
        if ($name -eq 'OptFocus' -and -not $on) {
            # Odak kipi acikken ozellik kapatilirsa durdurulan hizmetler geri baslatilir
            [void](Start-Async 'Focus' 'Job_Focus' @{ On = $false } { param($r) $script:TlFocus = $false } ('Odak kipi kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $true $true)
        }
        if ($name -eq 'OptGuard' -and $on) { Start-GuardCheck $true }
    } 'Ayar'
}

$script:H_StWipe = {
    param($s, $e)
    if ($script:StLoading) { return }
    Invoke-Safe {
        Set-OptValue 'WipePasses' ([int]$s.Tag)
        Show-Toast (('G' + [char]0x00FC + 'venli silme: ') + [string]$s.Tag + (' ge' + [char]0x00E7 + 'i' + [char]0x015F + '.')) 'info'
    } 'Ayar'
}

function Render-StOptional {
    $ui.st_OptList.Children.Clear()
    $script:StOptBoxes = @{}
    foreach ($k in @($script:OptInfo.Keys)) {
        $inf = $script:OptInfo[$k]
        $cb = Add-StToggleRow $ui.st_OptList ([string]$inf.T) ([string]$inf.D) (Test-Opt ([string]$k)) ([string]$k) $script:H_StOpt
        $script:StOptBoxes[[string]$k] = $cb
    }
    $cur = 1
    try { $cur = [int](Get-OptValue 'WipePasses' 1) } catch { $cur = 1 }
    foreach ($n in @(1, 3, 7, 35)) { $ui['st_Wipe' + [string]$n].IsChecked = ($cur -eq $n) }
}

# ---------------- Ayarlar: internet istekleri ----------------
$script:H_StNet = {
    param($s, $e)
    if ($script:StLoading) { return }
    Invoke-Safe {
        $key = [string]$s.Tag
        $off = @(Get-NetOffList | Where-Object { $_ -ne $key })
        if ($s.IsChecked -ne $true) { $off += $key }
        Set-OptValue 'NetOff' @($off)
        if ($s.IsChecked -eq $true) { Show-Toast ([string]$script:NetFeatures[$key].T + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'k.')) 'info' } else { Show-Toast ([string]$script:NetFeatures[$key].T + (' kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '; bu ' + [char]0x00F6 + 'zellik internete ' + [char]0x00E7 + '' + [char]0x0131 + 'kmaz.')) 'info' }
    } 'Ayar'
}

function Render-StNet {
    $ui.st_NetList.Children.Clear()
    $script:StNetBoxes = @{}
    $off = @(Get-NetOffList)
    foreach ($k in @($script:NetFeatures.Keys)) {
        $f = $script:NetFeatures[$k]
        $cb = Add-StToggleRow $ui.st_NetList ([string]$f.T) ([string]$f.D) ($off -notcontains [string]$k) ([string]$k) $script:H_StNet
        $script:StNetBoxes[[string]$k] = $cb
    }
}

# ---------------- Ayarlar: yukleme / kaydetme ----------------
# Gorunum kartindaki acilir listelerin ve anahtarlarin islevleri kendi bolumlerindedir: Gorunum (tema, yerlesim, yakinlastirma,
# hazir gorunum), Tasarim (tasarim, ana ekran bicimi, tasarim ayrintilari), Saydamlik ve Kararlilik.
$script:StLookParts = @('Look', 'Design', 'Glass', 'Safe')

function Load-StExtra {
    foreach ($p in $script:StLookParts) {
        $fn = 'Load-St' + $p
        try { & $fn } catch { Write-CrashLog ('Ayar (' + $fn + '): ' + $_.Exception.Message) }
    }
    $keep = 60
    try { $keep = [int]$script:Settings.KeepLogDays } catch { $keep = 60 }
    if ($keep -le 30) { $ui.st_Keep30.IsChecked = $true } elseif ($keep -le 60) { $ui.st_Keep60.IsChecked = $true } elseif ($keep -le 180) { $ui.st_Keep180.IsChecked = $true } else { $ui.st_Keep365.IsChecked = $true }
    Render-StOptional
    Render-StNet
    Load-StUpdate
    Load-StLang
    Load-StReset
    $ui.st_UseCaseText.Text = (Tr $((Get-UseCaseTitle ([string]$script:Settings.UseCase))))
    [System.Windows.Automation.AutomationProperties]::SetName($ui.st_UseCase, (Tr ('De' + [char]0x011F + 'i' + [char]0x015F + 'tir...')) + ', ' + (Tr ('Kullan' + [char]0x0131 + 'm t' + [char]0x00FC + 'r' + [char]0x00FC + '')))
}

function Save-StExtra {
    if ($script:StLoading) { return }
    $s = $script:Settings
    foreach ($p in $script:StLookParts) {
        $fn = 'Save-St' + $p
        try { & $fn } catch { Write-CrashLog ('Ayar (' + $fn + '): ' + $_.Exception.Message) }
    }
    foreach ($d in @(30, 60, 180, 365)) {
        if ($ui['st_Keep' + [string]$d].IsChecked -eq $true) { $s.KeepLogDays = $d }
    }
    Save-Settings $s
    Update-ReduceMotion
    try { Sync-StPresetBox } catch { }
}

# Acilir listede secim degisince ve anahtara tiklaninca gorunum kaydedilir (programla yapilan secimler StLoading ile elenir)
$script:H_StLookChanged = {
    param($s, $e)
    if ($script:StLoading) { return }
    Invoke-Safe { Save-StExtra } 'Ayar'
}

# Hazir gorunum listesi: secilen birlesim tema, yerlesim, tasarim, saydamlik ve yakinlastirmayi birlikte uygular
$script:H_StLookPreset = {
    param($s, $e)
    if ($script:StLoading) { return }
