        if ($k -ne '' -and $k -ne 'Ozel') {
            Apply-LookPreset $k
            Show-Toast (('Haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm uyguland' + [char]0x0131 + ': ') + [string]$script:LookPresetNames[$k] + '.') 'info'
        }
    } 'Ayar'
}

function Init-StExtra {
    foreach ($fn in @('Initialize-StLookChoices', 'Initialize-StDesignChoices', 'Initialize-StGlassChoices')) {
        try { & $fn } catch { Write-CrashLog ('Ayar (' + $fn + '): ' + $_.Exception.Message) }
    }
    foreach ($n in @('st_ThemeSel', 'st_LayoutSel', 'st_ZoomSel', 'st_TouchSel', 'st_DesignSel', 'st_HomeSel', 'st_BackdropSel', 'st_OpacitySel',
                     'st_DsNavSel', 'st_DsRadiusSel', 'st_DsFontSel', 'st_DsGraphSel', 'st_DsSkinSel')) {
        $ui[$n].Add_SelectionChanged($script:H_StLookChanged)
