    $ui.st_LookSel.Add_SelectionChanged($script:H_StLookPreset)
    foreach ($n in @('st_ReduceMotion', 'st_Smooth', 'st_ToTop', 'st_FullDesc', 'st_FocusRing', 'st_SafeRender', 'st_MonGpu', 'st_DebugLog', 'st_Keep30', 'st_Keep60', 'st_Keep180', 'st_Keep365')) {
        $ui[$n].Add_Click($script:H_StLookChanged)
    }
    # Tasarim ayrintilari paneli: isaret programla degisse de panel ayni kalir
    $ui.st_DsAdv.Add_Checked({ $ui.st_DsAdvPanel.Visibility = [System.Windows.Visibility]::Visible })
    $ui.st_DsAdv.Add_Unchecked({ $ui.st_DsAdvPanel.Visibility = [System.Windows.Visibility]::Collapsed })
    $ui.st_DsReset.Add_Click({
        Invoke-Safe {
            [void](Reset-DesignOverrides)
            Sync-StLookControls
            Save-Settings $script:Settings
            Show-Toast ('Tasar' + [char]0x0131 + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n kendi de' + [char]0x011F + 'erlerine d' + [char]0x00F6 + 'nd' + [char]0x00FC + '.') 'info'
        } 'Ayar'
    })
    $ui.st_BoardEdit.Add_Click({ Invoke-Safe { Open-BoardEditor } 'Ana ekran' })
    $ui.st_BoardReset.Add_Click({
        Invoke-Safe {
            Reset-BoardLayout
            Show-Toast ('Ana ekran bu tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zenine d' + [char]0x00F6 + 'nd' + [char]0x00FC + '.') 'info'
        } 'Ana ekran'
    })
    foreach ($n in @(1, 3, 7, 35)) {
        $c = $ui['st_Wipe' + [string]$n]
        $c.Tag = [string]$n
        $c.Add_Click($script:H_StWipe)
    }
    $ui.st_UseCase.Add_Click({ Invoke-Safe { Show-UseCaseChoice $false } ('Kullan' + [char]0x0131 + 'm t' + [char]0x00FC + 'r' + [char]0x00FC + '') })
    $ui.st_CleanLogs.Add_Click({
        Invoke-Safe {
            $n = Remove-OldLogs ([int]$script:Settings.KeepLogDays) $script:LogDir
            Show-Toast ([string]$n + (' eski g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k dosyas' + [char]0x0131 + ' silindi.')) 'good'
        } ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'kler')
    })
}

# ---------------- ayar bekcisi ----------------
# Aciksa (OptGuard): Windows'un geri cevirdigi ayarlari gunde bir kez kendiliginden yeniden uygular (geri alinabilir kayitla).
# Kapaliysa: yalnizca kac ayarin geri dondugunu bildirir.
function Start-GuardCheck([bool]$Force = $false) {
    if (-not $Force) {
        $last = [datetime]::MinValue
        try { if ([string]$script:Settings.LastGuard -ne '') { $last = [datetime][string]$script:Settings.LastGuard } } catch { }
        if (((Get-Date) - $last).TotalHours -lt 20) { return }
    }
    if (Test-Opt 'OptGuard') {
        [void](Start-Async 'Guard' 'Job_Guard' @{} {
            param($r)
            $script:Settings.LastGuard = (Get-Date).ToString('s')
            Save-Settings $script:Settings
            if ($null -ne $r -and [int]$r.Count -gt 0) {
                Show-Notify ('Ayar bek' + [char]0x00E7 + 'isi') ([string]$r.Count + (' ayar geri d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + 't' + [char]0x00FC + ', yeniden uyguland' + [char]0x0131 + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'nda.')) 'info'
                Show-Toast (('Ayar bek' + [char]0x00E7 + 'isi: ') + [string]$r.Count + (' ayar yeniden uyguland' + [char]0x0131 + '.')) 'info'
            }
        } ('Ayar bek' + [char]0x00E7 + 'isi') $true $true)
    } else {
        [void](Start-Async 'TweakStates' 'Job_TweakStates' @{ Page = 'opt' } {
            param($r)
            if ($null -eq $r) { return }
            $script:OpStates = $r.States
            $script:OpDrift = @($r.Drift)
            $script:Settings.LastGuard = (Get-Date).ToString('s')
            Save-Settings $script:Settings
            $n = @($r.Drift).Count
            if ($n -gt 0) { Show-Notify ('Baz' + [char]0x0131 + ' ayarlar geri d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + '') ([string]$n + (' ayar eski haline d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + '. Optimizasyon sayfas' + [char]0x0131 + 'nda "Geri d' + [char]0x00F6 + 'nenleri se' + [char]0x00E7 + '" ile yeniden uygulayabilirsiniz.')) 'warn' }
        } ('Ayarlar' + [char]0x0131 + 'n durumu okunuyor') $true $true)
    }
}

function Initialize-GuardWatch {
    $script:GuardTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:GuardTimer.Interval = [TimeSpan]::FromSeconds(45)
    $script:GuardTimer.Add_Tick({
        try {
            # ilk calisma 45 sn sonra; sonra 6 saatte bir bakar (20 saatten yeni ise bir sey yapmaz)
            $script:GuardTimer.Interval = [TimeSpan]::FromHours(6)
            Start-GuardCheck $false
        } catch { Write-CrashLog ('GuardTimer: ' + $_.Exception.Message) }
    })
    $script:GuardTimer.Start()
}

