function Render-BkKit {
    $ui.bk_List.Children.Clear()
    Add-Note $ui.bk_List ('Bilgisayar' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlamadan ya da yenisine ge' + [char]0x00E7 + 'meden ' + [char]0x00F6 + 'nce, yeniden kurulumu kolayla' + [char]0x015F + 't' + [char]0x0131 + 'ran k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k bir klas' + [char]0x00F6 + 'r haz' + [char]0x0131 + 'rlar. Ki' + [char]0x015F + 'isel dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' i' + [char]0x00E7 + 'ermez; onlar i' + [char]0x00E7 + 'in ' + [char]0x201C + 'Dosya yede' + [char]0x011F + 'i' + [char]0x201D + ' sekmesini kullan' + [char]0x0131 + 'n.')
    Add-HeadRow $ui.bk_List ('Paketin i' + [char]0x00E7 + 'inde ne olur')
    Add-KvRow $ui.bk_List 'Kurulu programlar' ('Okunur liste ve winget ile toplu geri kurulum dosyas' + [char]0x0131 + '')
    Add-KvRow $ui.bk_List 'Multimizer profili' ('Bu bilgisayarda uygulad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z ayarlar; yeni kurulumda tek ad' + [char]0x0131 + 'mda geri uygulan' + [char]0x0131 + 'r')
    Add-KvRow $ui.bk_List ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler (iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ')') ('' + [char]0x00DC + '' + [char]0x00E7 + '' + [char]0x00FC + 'nc' + [char]0x00FC + ' taraf s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'lerin tamam' + [char]0x0131 + '; 1-3 GB yer tutabilir, birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer')
    Add-KvRow $ui.bk_List ('Wi-Fi profilleri (iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ')') ('Kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' kablosuz a' + [char]0x011F + 'lar. Parolalar dosyaya a' + [char]0x00E7 + '' + [char]0x0131 + 'k yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r; paketi g' + [char]0x00FC + 'vendi' + [char]0x011F + 'iniz bir yerde saklay' + [char]0x0131 + 'n')
    if ($null -ne $script:BkKit) {
        Add-HeadRow $ui.bk_List ('Son haz' + [char]0x0131 + 'rlanan paket')
        $row = New-ItemRow @{ Title = [string]$script:BkKit.Path; Detail = (@($script:BkKit.Items) -join '   |   '); BrCol = 'BrGood'; Btn1 = ('Klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' a' + [char]0x00E7 + '') } @{ Path = [string]$script:BkKit.Path } $false $false
        $row.FindName('Act').Add_Click($script:H_BkKitOpen)
        [void]$ui.bk_List.Children.Add($row)
    }
    $ui.bk_Foot.Text = (Tr $(('Paketi harici diske ya da USB belle' + [char]0x011F + 'e kaydedin; s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlayaca' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z diske kaydederseniz o da silinir.')))
}

function Start-BkKit {
    $dest = Select-Folder ('Paketin kaydedilece' + [char]0x011F + 'i klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (tercihen harici disk ya da USB bellek)')
    if ($dest -eq '') { return }
    $script:PendingKit = @{ Dest = $dest; Drivers = ($ui.bk_KitDrv.IsChecked -eq $true); Wifi = ($ui.bk_KitWifi.IsChecked -eq $true) }
    $txt = (('Paket ' + [char]0x015F + 'u klas' + [char]0x00F6 + 're haz' + [char]0x0131 + 'rlanacak:') + "`r`n" + $dest)
    if ($script:PendingKit.Drivers) { $txt += "`r`n`r`nS$([char]0x00FC)r$([char]0x00FC)c$([char]0x00FC)ler de eklenecek (birka$([char]0x00E7) dakika s$([char]0x00FC)rebilir)." }
    if ($script:PendingKit.Wifi) { $txt += "`r`n`r`nD$([char]0x0130)KKAT: Wi-Fi parolalar$([char]0x0131) dosyalara d$([char]0x00FC)z metin olarak yaz$([char]0x0131)lacak. Kiti ba$([char]0x015F)kalar$([char]0x0131)n$([char]0x0131)n eri$([char]0x015F)ebilece$([char]0x011F)i bir yere koymay$([char]0x0131)n." }
    Show-Confirm ('Ta' + [char]0x015F + '' + [char]0x0131 + 'ma paketini olu' + [char]0x015F + 'tur') $txt ('Olu' + [char]0x015F + 'tur') {
        [void](Start-Async 'Kit' 'Job_MigrationKit' $script:PendingKit {
            param($r)
            if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Paket haz' + [char]0x0131 + 'rlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
            $script:BkKit = $r
            Show-Toast ('Ta' + [char]0x015F + '' + [char]0x0131 + 'ma paketi haz' + [char]0x0131 + 'r.') 'good'
            Show-Notify ('Ta' + [char]0x015F + '' + [char]0x0131 + 'ma paketi haz' + [char]0x0131 + 'r') ([string]$r.Path) 'good'
            if ($script:UiState.Page -eq 'backup' -and $script:BkTab -eq 'kit') { Render-BkKit }
        } ('Ta' + [char]0x015F + '' + [char]0x0131 + 'ma paketi haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor'))
    } ($script:PendingKit.Wifi -eq $true)
}

function Load-BkPhoto {
    [void](Start-Async 'PhotoRec' 'Job_FindPhotoRec' @{} {
        param($r)
        $script:BkPhoto = ''
        if ($null -ne $r) { $script:BkPhoto = [string]$r.Path }
        if ($script:UiState.Page -eq 'backup' -and $script:BkTab -eq 'recover') { Render-BkRecover }
    } ('PhotoRec aran' + [char]0x0131 + 'yor') $true $true)
}

