    if (($null -eq $script:Health -or $script:HealthAt -eq [datetime]::MinValue) -and $null -ne $sync.Profile) { Start-HealthScan 'Quick' $true }
    Initialize-LanSnap
    if ($script:TopoMode -eq 'lan') { Draw-Topology }
    elseif ($null -eq $script:TopoSnap -or ((Get-Date) - $script:TopoAt).TotalSeconds -gt 90) { Start-TopoScan $true }
    elseif ($script:TopoW -eq 0 -or [math]::Abs([double]$ui.pn_Topo.ActualWidth - $script:TopoW) -gt 30) { Draw-Topology }
