# ==================================================================
#  ARAYUZ ORTAK: liste satirlari, sekmeler, plan isi, yeniden baslatma, yedek/rapor kisayollari
# ==================================================================
$script:Loaded = @{}
$script:PlanAfter = $null
$script:PendingSteps = $null
$script:PendingTitle = ''

$script:BrByRec = @{ Off = 'BrAccent'; Man = 'BrBlue'; Org = 'BrAccent2'; Rev = 'BrWarn'; Keep = 'BrFaint'; Lock = 'BrBad' }

function Test-Stale([string]$Key, [int]$Secs) {
    if (-not $script:Loaded.ContainsKey($Key)) { return $true }
    return (((Get-Date) - $script:Loaded[$Key]).TotalSeconds -gt $Secs)
}
function Set-Loaded([string]$Key) { $script:Loaded[$Key] = Get-Date }
function Clear-Loaded([string]$Prefix) {
    foreach ($k in @($script:Loaded.Keys)) { if ($k.StartsWith($Prefix)) { $script:Loaded.Remove($k) } }
}

# ---------------- satir olusturma ----------------
# V: Title, Detail, Tag, BrCol, Btn1, Btn2   |  Data: satirin .Tag degeri (hashtable)
function New-ItemRow($V, $Data, [bool]$Check, [bool]$Checked) {
    $vars = @{ Title = ''; Detail = ''; Tag = ''; BrCol = 'BrFaint'; Btn1 = ''; Btn2 = '' }
    foreach ($k in @($V.Keys)) { $vars[$k] = [string]$V[$k] }
    $row = New-RowElement 'Item' $vars
    $row.Tag = $Data
    $chk = $row.FindName('Chk')
    if ($Check) { $chk.IsChecked = $Checked } else { $chk.Visibility = $script:VisOff }
    $a1 = $row.FindName('Act'); $a2 = $row.FindName('Act2')
    if ($vars.Btn1 -eq '') { $a1.Visibility = $script:VisOff } else { $a1.Tag = $Data }
    if ($vars.Btn2 -eq '') { $a2.Visibility = $script:VisOff } else { $a2.Tag = $Data }
    if ($vars.Detail -eq '') { $row.FindName('Det').Visibility = $script:VisOff }
    if ($vars.Tag -eq '') { $row.FindName('Tag').Visibility = $script:VisOff }
    return $row
}

function Add-HeadRow($Panel, [string]$Text) {
    $el = New-RowElement 'Head' @{ Text = $Text }
    [void]$Panel.Children.Add($el)
}

function Add-KvRow($Panel, [string]$Key, [string]$Val) {
    $el = New-RowElement 'Kv' @{ Key = $Key; Val = $Val }
    [void]$Panel.Children.Add($el)
}

function Set-ListNote($Panel, [string]$Text, [string]$Kind = 'dim') {
    $Panel.Children.Clear()
    Add-Note $Panel $Text $Kind
}

function Get-RowCheck($Row) {
    if ($Row -isnot [System.Windows.Controls.Border]) { return $null }
    return $Row.FindName('Chk')
}

# Gorunur ve isaretli satirlarin veri nesneleri
function Get-CheckedData($Panel) {
    $r = New-Object System.Collections.ArrayList
    foreach ($row in $Panel.Children) {
        $c = Get-RowCheck $row
        if ($null -eq $c) { continue }
        if ($row.Visibility -ne $script:VisOn -or $c.Visibility -ne $script:VisOn) { continue }
        if ($c.IsChecked -eq $true) { [void]$r.Add($row.Tag) }
    }
    return , $r.ToArray()
}

# Gorunur satirlarda onay kutularini olcute gore ayarlar; olcut veri nesnesini alir, true/false doner
function Set-RowChecks($Panel, [scriptblock]$Pred) {
    foreach ($row in $Panel.Children) {
        $c = Get-RowCheck $row
        if ($null -eq $c -or $c.Visibility -ne $script:VisOn) { continue }
        $c.IsChecked = [bool](& $Pred $row.Tag)
    }
}

function Get-RowByKey($Panel, [string]$Prop, [string]$Value) {
    foreach ($row in $Panel.Children) {
        if ($row -isnot [System.Windows.Controls.Border]) { continue }
        $d = $row.Tag
        if ($d -is [hashtable] -and [string]$d[$Prop] -eq $Value) { return $row }
    }
    return $null
}

# ---------------- sekmeler ----------------
function Register-Tabs([string]$P, $Keys, [scriptblock]$Handler) {
    foreach ($k in @($Keys)) {
        $c = $ui[$P + '_Tab_' + $k]
        if ($null -ne $c) { $c.Add_Checked($Handler) }
    }
}

# Sekmeyi secer. Zaten seciliyse $false doner (cagiran yukleyiciyi kendisi calistirir)
function Select-TabChip([string]$P, [string]$Key) {
    $c = $ui[$P + '_Tab_' + $Key]
    if ($null -eq $c) { return $false }
    if ($c.IsChecked -eq $true) { return $false }
    $c.IsChecked = $true
    return $true
}

function Get-TabKey([string]$P, $Keys, [string]$Default) {
    foreach ($k in @($Keys)) {
        $c = $ui[$P + '_Tab_' + $k]
        if ($null -ne $c -and $c.IsChecked -eq $true) { return $k }
    }
    return $Default
}

function Show-OnlyBar([string]$P, $ShowNames) {
    # Cubuktaki dugmelerden yalnizca verilenler gorunur
    $bar = $ui[$P + '_Bar']
    if ($null -eq $bar) { return }
    foreach ($el in $bar.Children) {
        $n = [string]$el.Name
        if ($n -eq '') { continue }
        if (@($ShowNames) -contains $n) { $el.Visibility = $script:VisOn } else { $el.Visibility = $script:VisOff }
    }
}

# Metin kutusu icerigi degisince cagrilir (suzme)
function Get-FilterText($Box) {
    return (ConvertTo-AsciiKey ([string]$Box.Text)).Trim()
}

# ---------------- plan isi (uygula / onizle) ----------------
function Start-PlanJob($Steps, [string]$Label, [bool]$Preview, [bool]$RestorePoint, [scriptblock]$After = $null) {
    $steps = @($Steps)
    if ($steps.Count -eq 0) { Show-Toast ('Se' + [char]0x00E7 + 'ili ' + [char]0x00F6 + [char]0x011F + 'e yok.') 'warn'; return }
    $script:PlanAfter = $After
    $p = @{ Steps = $steps; Preview = $Preview; RestorePoint = $RestorePoint }
    $ok = Start-Async 'Plan' 'Job_Plan' $p { param($r) Complete-PlanJob $r } $Label
    if (-not $ok) { $script:PlanAfter = $null }
}

function Complete-PlanJob($R) {
    $after = $script:PlanAfter
    $script:PlanAfter = $null
    if ($null -eq $R) { Show-Toast ([string][char]0x0130 + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
    $script:Settings = Get-Settings
    $script:HealthAt = [datetime]::MinValue
    if ($R.Preview -eq $true) {
        Show-Toast (([string][char]0x00D6 + 'nizleme tamamland' + [char]0x0131 + ': ') + [string]$R.Changes + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yap' + [char]0x0131 + 'lacak, ') + [string]$R.Skipped + (' atlanacak. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' soldaki g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.')) 'info'
        return
    }
    $kind = 'good'
    if ([int]$R.Errors -gt 0) { $kind = 'warn' }
    Show-Toast ([string]$R.Summary) $kind
    Show-Notify ([string][char]0x0130 + [char]0x015F + 'lem tamamland' + [char]0x0131) ([string]$R.Summary) $kind
    if ($null -ne $after) { try { & $after $R } catch { Show-Crash $_ ('Plan sonras' + [char]0x0131) } }
    if ($R.Reboot -eq $true) { Request-Reboot }
}

# Onay metni icin kisa bir liste
function Format-NameList($Names, [int]$Max = 12) {
    $arr = @($Names)
    $lines = New-Object System.Collections.ArrayList
    $i = 0
    foreach ($n in $arr) {
        if ($i -ge $Max) { break }
        [void]$lines.Add([string][char]0x2022 + ' ' + [string]$n)
        $i++
    }
    if ($arr.Count -gt $Max) { [void]$lines.Add('... ve ' + [string]($arr.Count - $Max) + (' ' + [char]0x00F6 + [char]0x011F + 'e daha')) }
    return ($lines -join "`r`n")
}

function Request-Reboot {
    Show-Confirm ('Yeniden ba' + [char]0x015F + 'latma gerekli') ('Baz' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerin etkili olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bilgisayar' + [char]0x0131 + 'n yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmas' + [char]0x0131 + ' gerekir. A' + [char]0x00E7 + [char]0x0131 + 'k i' + [char]0x015F + 'lerinizi kaydedin. ' + [char]0x015E + 'imdi yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ls' + [char]0x0131 + 'n m' + [char]0x0131 + '? (30 saniye sonra ba' + [char]0x015F + 'lar; komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'na "iptal" yazarak durdurabilirsiniz.)') ('Yeniden ba' + [char]0x015F + 'lat') {
        try {
            [void](Start-SystemRestart $false 30)
            Show-Toast ('Bilgisayar 30 saniye sonra yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak. ' + [char]0x0130 + 'ptal i' + [char]0x00E7 + 'in komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'na "iptal" yaz' + [char]0x0131 + 'n.') 'warn'
        } catch { Show-Toast ('Yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'bad' }
    } $true
}

# ---------------- yedek ve rapor kisayollari ----------------
function Start-BackupNow([bool]$Preview = $false) {
    $st = $script:Settings
    if (@($st.BackupSources).Count -eq 0 -or [string]$st.BackupDest -eq '') {
        Show-Toast ([string][char]0x00D6 + 'nce Yedek sayfas' + [char]0x0131 + 'nda yedeklenecek klas' + [char]0x00F6 + 'rleri ve hedefi se' + [char]0x00E7 + 'in.') 'warn'
        Open-Page 'backup'
        return
    }
    if ([string]$st.BackupMode -eq 'Restic') { Start-ResticBackup $Preview; return }
    $lbl = ('Dosya yede' + [char]0x011F + 'i')
    if ($Preview) { $lbl = ('Yedek ' + [char]0x00F6 + 'nizlemesi') }
    $script:BackupWasPreview = $Preview
    [void](Start-Async 'Backup' 'Job_Backup' @{ Preview = $Preview; Sources = @(); Dest = ''; Mode = '' } {
        param($r)
        $script:Settings = Get-Settings
        if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Yedekleme tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
        if ($script:BackupWasPreview -eq $true) {
            Show-Toast (([string][char]0x00D6 + 'nizleme: ') + [string]$r.Files + ' dosya (' + (Format-Size ([double]$r.Bytes)) + (') yedeklenecek. Hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey kopyalanmad' + [char]0x0131 + '.')) 'info'
            return
        }
        $msg = ('Yedekleme tamamland' + [char]0x0131 + ': ' + [string]$r.Files + ' dosya, ' + (Format-Size ([double]$r.Bytes)))
        Show-Toast $msg 'good'
        Show-Notify ('Yedekleme tamamland' + [char]0x0131) $msg 'good'
        if ($script:UiState.Page -eq 'panel') { Update-QuickStatus }
        if ($script:UiState.Page -eq 'backup' -and $script:BkTab -eq 'files') { Render-BkFiles }
    } $lbl)
}

function Start-ReportNow {
    [void](Start-Async 'Report' 'Job_Report' @{} {
        param($r)
        $script:Settings = Get-Settings
        if ($null -eq $r) { Show-Toast ('Rapor olu' + [char]0x015F + 'turulamad' + [char]0x0131 + '.') 'bad'; return }
        Show-Toast (('Rapor haz' + [char]0x0131 + 'r (sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ' ') + [string]$r.Score.All + ('). Taray' + [char]0x0131 + 'c' + [char]0x0131 + 'da a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + 'yor.')) 'good'
        Show-Notify ('Rapor haz' + [char]0x0131 + 'r') (('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ' ') + [string]$r.Score.All) 'good'
        Open-Path ([string]$r.Path)
    } 'Sistem raporu')
}

# Bir is sonucundaki "Rows" dizisini guvenle alir
function Get-ResultRows($R) {
    if ($null -eq $R) { return @() }
    if ($R.ContainsKey('Rows')) { return @($R.Rows) }
    return @()
}

function Format-Mem([double]$Bytes) { return (Format-Size $Bytes) }

function ConvertTo-StateText([string]$S) {
    switch ($S) {
        'Running' { return ([string][char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'yor') }
        'Stopped' { return 'durdu' }
        'Paused' { return ('duraklat' + [char]0x0131 + 'ld' + [char]0x0131) }
        default { return $S.ToLowerInvariant() }
    }
}

function ConvertTo-ModeText([string]$M, [bool]$Delayed) {
    switch ($M) {
        'Auto' { if ($Delayed) { return 'otomatik (gecikmeli)' } else { return 'otomatik' } }
        'Manual' { return 'el ile' }
        'Disabled' { return ('devre d' + [char]0x0131 + [char]0x015F + [char]0x0131) }
        'Boot' { return ([string][char]0x00F6 + 'ny' + [char]0x00FC + 'kleme') }
        'System' { return 'sistem' }
        default { return $M.ToLowerInvariant() }
    }
}

function Limit-Text([string]$T, [int]$Max) {
    if ($T.Length -le $Max) { return $T }
    return ($T.Substring(0, $Max - 3) + '...')
}


# ---------------- Sayfa: Hizlandir ----------------
# ==================================================================
#  SAYFA: Hizlandir (katalogdaki gizlilik / performans / gorunum / oyun / ag / temizlik ayarlari)
#  Varsayilan secim "Bu bilgisayara gore": donanim sinifina gore yapilir, zaten uygulanmis olanlar atlanir.
# ==================================================================
$script:OpTabs = @('all', 'Gizlilik', 'Performans', 'Gorunum', 'Oyun', 'Ag', 'Temizlik', 'Sistem', 'Ozellik')
$script:OpSel = @{}
$script:OpItems = @()
$script:OpCat = 'all'
$script:OpInit = $false
$script:OpPreset = 'auto'
$script:OpStates = $null
$script:OpDrift = @()

function Get-OpLevelInfo([int]$Level) {
    switch ($Level) {
        1 { return @{ Text = ('G' + [char]0x00FC + 'venli'); Br = 'BrGood' } }
        2 { return @{ Text = 'Dengeli'; Br = 'BrInfo' } }
        3 { return @{ Text = 'Agresif'; Br = 'BrWarn' } }
        default { return @{ Text = ('Yaln' + [char]0x0131 + 'zca elle'); Br = 'BrBad' } }
    }
}

# Ayarin olculen durumu: -2 = henuz okunmadi, -1 = olculemez, 0 = uygulanmis, N = bekleyen deger sayisi
function Get-OpState([string]$Id) {
    if ($null -eq $script:OpStates) { return -2 }
    if (-not $script:OpStates.ContainsKey($Id)) { return -2 }
    return [int]$script:OpStates[$Id]
}

# Kind: auto (bu bilgisayara gore) | 1 | 2 | 3 (hazir duzeyler) | 0 (hicbiri) | drift (geri donenler)
function Set-OpPreset([string]$Kind, [bool]$Quiet = $false) {
    $script:OpPreset = $Kind
    $script:OpSel = @{}
    $ids = @()
    if ($Kind -eq 'auto') { $ids = Get-AdaptiveIds 'opt' $sync.Profile (Get-CurrentTier) }
    elseif ($Kind -eq 'drift') { $ids = @($script:OpDrift) }
    elseif ($Kind -eq '1' -or $Kind -eq '2' -or $Kind -eq '3') { $ids = Get-PresetIds ([int]$Kind) 'opt' $sync.Profile }
    foreach ($id in @($ids)) {
        # "Bu bilgisayara gore" seciminde zaten uygulanmis ayarlar yeniden secilmez
        if ($Kind -eq 'auto' -and @(0, -3) -contains (Get-OpState ([string]$id))) { continue }
        $script:OpSel[[string]$id] = $true
    }
    Update-OpUi
    if (-not $Quiet -and $Kind -eq '0') { Show-Toast ('Se' + [char]0x00E7 + 'im temizlendi.') 'info' }
}

function Get-OpSelectedIds {
    $ids = New-Object System.Collections.ArrayList
    foreach ($c in $script:OpItems) {
        if ($script:OpSel[[string]$c.Id] -eq $true) { [void]$ids.Add([string]$c.Id) }
    }
    return , $ids.ToArray()
}

function Update-OpTierCard {
    $t = Get-CurrentTier
    $ui.op_TierName.Text = (Tr $([string]$t.Label))
    $ui.op_TierSum.Text = (Tr $([string]$t.Summary))
    $key = 'BrAccent'
    if ([string]$t.Tier -eq 'Low') { $key = 'BrWarn' } elseif ([string]$t.Tier -eq 'High') { $key = 'BrGood' }
    $ui.op_TierBar.Background = (Get-Br $key)
    $why = (@($t.Reasons) -join '. ')
    if ($why -ne '') { $why += '. ' }
    if ([string]$t.Tier -eq 'High') { $why += ('Bu y' + [char]0x00FC + 'zden yaln' + [char]0x0131 + 'zca gizlilik ve bak' + [char]0x0131 + 'm ayarlar' + [char]0x0131 + ' ' + [char]0x00F6 + 'nerilir; g' + [char]0x00F6 + 'rsel efektler, arka plan uygulamalar' + [char]0x0131 + ' ve benzeri ' + [char]0x00F6 + 'zelliklere dokunulmaz.') }
    elseif ([string]$t.Tier -eq 'Low') { $why += ('Bu y' + [char]0x00FC + 'zden gizlilik ayarlar' + [char]0x0131 + 'na ek olarak g' + [char]0x00F6 + 'rsel efektler ve arka plan y' + [char]0x00FC + 'k' + [char]0x00FC + ' de azalt' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') }
    else { $why += ('Gizlilik ayarlar' + [char]0x0131 + 'na ek olarak yaln' + [char]0x0131 + 'zca belirgin kazan' + [char]0x00E7 + ' sa' + [char]0x011F + 'layan performans ayarlar' + [char]0x0131 + ' ' + [char]0x00F6 + 'nerilir; g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'me dokunulmaz.') }
    $ui.op_TierWhy.Text = (Tr $($why))
}

function Update-OpUi {
    $ids = Get-OpSelectedIds
    $ui.op_Foot.Text = (Tr $(([string]$ids.Count + (' ayar se' + [char]0x00E7 + 'ili'))))
    $n = @($script:OpDrift).Count
    Set-Visible $ui.op_PDrift ($n -gt 0)
    if ($n -gt 0) { $ui.op_PDrift.Content = (Tr $((('Geri d' + [char]0x00F6 + 'nenleri se' + [char]0x00E7 + ' (') + [string]$n + ')'))) }

    # kullanici kipi ozeti
    $byCat = @{}
    $irrev = New-Object System.Collections.ArrayList
    $reboot = 0
    $capRm = 0
    foreach ($id in $ids) {
        $c = Get-CatalogItem $id
        if ($null -eq $c) { continue }
        $cn = [string]$script:CatNames[[string]$c.Cat]
        if (-not $byCat.ContainsKey($cn)) { $byCat[$cn] = 0 }
        $byCat[$cn]++
        if ($c.Irrev -eq $true) { [void]$irrev.Add([string]$c.Title) }
        if ($c.Reboot -eq $true) { $reboot++ }
        if (@(@($c.Ops) | Where-Object { [string]$_.T -eq 'Cap' -and [string]$_.State -ne 'Installed' }).Count -gt 0) { $capRm++ }
    }
    $parts = @()
    foreach ($k in @($byCat.Keys | Sort-Object)) { $parts += ($k + ' (' + [string]$byCat[$k] + ')') }
    $t = ''
    if ($ids.Count -eq 0) {
        if ($script:OpPreset -eq 'auto' -and $null -ne $script:OpStates) { $t = ('Bu bilgisayar ' + [char]0x00F6 + 'nerilen durumda; uygulanacak ayar kalmad' + [char]0x0131 + '.') }
        else { $t = ('Hi' + [char]0x00E7 + 'bir ayar se' + [char]0x00E7 + 'ili de' + [char]0x011F + 'il. Yukar' + [char]0x0131 + 'dan ' + [char]0x201C + 'Bu bilgisayara g' + [char]0x00F6 + 're' + [char]0x201D + ' ya da bir haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zey se' + [char]0x00E7 + 'in.') }
    } else {
        $t = ([string]$ids.Count + ' ayar uygulanacak: ' + ($parts -join ', ') + '.')
        if ($irrev.Count -gt 0) { $t += ("`r`n`r`nGeri al$([char]0x0131)namayan ad$([char]0x0131)mlar yaln$([char]0x0131)zca ge$([char]0x00E7)ici dosya temizli$([char]0x011F)idir (" + [string]$irrev.Count + (' ad' + [char]0x0131 + 'm). Ki' + [char]0x015F + 'isel dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'za dokunulmaz.')) }
        if ($reboot -gt 0) { $t += ("`r`nBaz$([char]0x0131) de$([char]0x011F)i$([char]0x015F)iklikler i$([char]0x00E7)in yeniden ba$([char]0x015F)latma gerekecek.") }
        if ($capRm -gt 0) { $t += ("`r`n" + [string]$capRm + (' Windows bile' + [char]0x015F + 'eni kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak. Geri al' + [char]0x0131 + 'rken dosyalar' + [char]0x0131 + ' Windows Update' + [char]0x2019 + 'ten yeniden indirilir; internet gerekir ve Windows ' + [char]0x00F6 + 'nizleme (Insider) s' + [char]0x00FC + 'r' + [char]0x00FC + 'mlerinde i' + [char]0x00E7 + 'erik her zaman bulunmayabilir.')) }
    }
    if ($script:OpPreset -eq 'auto') {
        $tier = Get-CurrentTier
        $done = 0
        $left = New-Object System.Collections.ArrayList
        foreach ($c in $script:OpItems) {
            if ([int]$c.Level -ge 4) { continue }
            if ([string]$c.Need -ne '' -and -not (Test-NeedOk ([string]$c.Need) $tier)) { [void]$left.Add([string]$c.Title) }
        }
        foreach ($id in (Get-AdaptiveIds 'opt' $sync.Profile $tier)) { if ((Get-OpState ([string]$id)) -eq 0) { $done++ } }
        if ($done -gt 0) { $t += ("`r`n`r`n$([char]0x00D6)nerilen ayarlardan " + [string]$done + (' tanesi zaten uygulanm' + [char]0x0131 + '' + [char]0x015F + '; onlar yeniden se' + [char]0x00E7 + 'ilmedi.')) }
        if ($left.Count -gt 0) {
            $show = @($left | Select-Object -First 4)
            $more = ''
            if ($left.Count -gt 4) { $more = (' ve ' + [string]($left.Count - 4) + ' ayar daha') }
            $t += ("`r`n`r`nBu donan$([char]0x0131)mda gerek olmad$([char]0x0131)$([char]0x011F)$([char]0x0131) i$([char]0x00E7)in dokunulmayanlar: " + ($show -join '; ') + $more + '.')
        }
    }
    $ui.op_UserText.Text = (Tr $($t))
}

$script:H_OpChk = {
    param($s, $e)
    $script:OpSel[[string]$s.Tag] = ($s.IsChecked -eq $true)
    $script:OpPreset = 'custom'
    Update-OpUi
}

function Render-OpList {
    $ui.op_List.Children.Clear()
    $tier = Get-CurrentTier
    $shown = 0
    foreach ($c in $script:OpItems) {
        if ($script:OpCat -ne 'all' -and [string]$c.Cat -ne $script:OpCat) { continue }
        $id = [string]$c.Id
        $lv = Get-OpLevelInfo ([int]$c.Level)
        $det = [string]$c.Desc
        if ($det.Length -gt 230) { $det = $det.Substring(0, 227) + '...' }
        $flags = @()
        if ($c.Irrev -eq $true) { $flags += ('geri al' + [char]0x0131 + 'namaz') }
        if ($c.Reboot -eq $true) { $flags += ('yeniden ba' + [char]0x015F + 'latma gerekir') }
        if (-not (Test-WhenOk ([string]$c.When) $sync.Profile)) { $flags += ('bu bilgisayar i' + [char]0x00E7 + 'in gereksiz') }
        elseif ([string]$c.Need -ne '') {
            if (Test-NeedOk ([string]$c.Need) $tier) { $flags += ('bu donan' + [char]0x0131 + 'm i' + [char]0x00E7 + 'in ' + [char]0x00F6 + 'nerilir') } else { $flags += (('bu donan' + [char]0x0131 + 'mda gerekmez: ') + [string]$c.NeedWhy) }
        }
        if ($flags.Count -gt 0) { $det += ('  [' + ($flags -join ', ') + ']') }
        $tag = $lv.Text + ('  ' + [char]0x00B7 + '  ') + [string]$script:CatNames[[string]$c.Cat]
        $br = $lv.Br
        $st = Get-OpState $id
        if (@($script:OpDrift) -contains $id) { $tag = ('GER' + [char]0x0130 + ' D' + [char]0x00D6 + 'NM' + [char]0x00DC + '' + [char]0x015E + '  ' + [char]0x00B7 + '  ') + $tag; $br = 'BrWarn' }
        elseif ($st -eq -3) { $tag = ('Windows engelliyor  ' + [char]0x00B7 + '  ') + $tag; $br = 'BrFaint' }
        elseif ($st -eq 0) { $tag = ('uygulanm' + [char]0x0131 + '' + [char]0x015F + '  ' + [char]0x00B7 + '  ') + $tag; $br = 'BrFaint' }
        $row = New-ItemRow @{ Title = [string]$c.Title; Detail = $det; Tag = $tag; BrCol = $br } @{ Id = $id } $true ($script:OpSel[$id] -eq $true)
        $chk = $row.FindName('Chk')
        $chk.Tag = $id
        $chk.Add_Click($script:H_OpChk)
        [void]$ui.op_List.Children.Add($row)
        $shown++
    }
    if ($shown -eq 0) { Add-Note $ui.op_List 'Bu kategoride ayar yok.' }
}

# Ayarlarin gercek durumunu arka planda okur (sistemi degistirmez)
function Start-OpStates {
    [void](Start-Async 'TweakStates' 'Job_TweakStates' @{ Page = 'opt' } {
        param($r)
        if ($null -eq $r) { return }
        $script:OpStates = $r.States
        $script:OpDrift = @($r.Drift)
        Set-Loaded 'opstates'
        if (-not $script:OpInit) { return }
        if ($script:OpPreset -eq 'auto') { Set-OpPreset 'auto' $true } else { Update-OpUi }
        Render-OpList
    } ('Ayarlar' + [char]0x0131 + 'n durumu okunuyor') $true $true)
}

function Select-Sub_optimize([string]$Sub) {
    if ($Sub -eq 'drift') { Set-OpPreset 'drift'; Render-OpList; return }
    if (-not (Select-TabChip 'op' $Sub)) { $script:OpCat = $Sub; Render-OpList }
}

function Update-PageMode_optimize {
    $exp = ($script:UiState.Mode -eq 'Expert')
    Set-Visible $ui.op_Tabs $exp
    Set-Visible $ui.op_ListCard $exp
    Set-Visible $ui.op_UserCard (-not $exp)
    Set-Visible $ui.op_P0 $exp
}

function Start-OpApply([bool]$Preview) {
    $ids = Get-OpSelectedIds
    if ($ids.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce uygulanacak ayarlar' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') 'warn'; return }
    $steps = New-StepsFromIds $ids
    $rp = ($ui.op_Rp.IsChecked -eq $true)
    if ($Preview) { Start-PlanJob $steps ('' + [char]0x00D6 + 'nizleme: ayarlar') $true $false; return }
    $irrev = @($ids | ForEach-Object { Get-CatalogItem $_ } | Where-Object { $_.Irrev -eq $true } | ForEach-Object { [string]$_.Title })
    $txt = ([string]$ids.Count + ' ayar uygulanacak.')
    if ($rp) { $txt += ("`r`n$([char]0x00D6)nce bir geri y$([char]0x00FC)kleme noktas$([char]0x0131) olu$([char]0x015F)turulur.") }
    $txt += ("`r`nEski de$([char]0x011F)erler kaydedilir; Ge$([char]0x00E7)mi$([char]0x015F) sayfas$([char]0x0131)ndan tek t$([char]0x0131)kla geri alabilirsiniz.")
    if ($irrev.Count -gt 0) { $txt += ("`r`n`r`nGeri al$([char]0x0131)namayanlar (yaln$([char]0x0131)zca ge$([char]0x00E7)ici dosya silme):`r`n" + (Format-NameList $irrev 8)) }
    $script:PendingSteps = $steps
    $script:PendingRp = $rp
    Show-Confirm ('Ayarlar' + [char]0x0131 + ' uygula') $txt 'Uygula' {
        Start-PlanJob $script:PendingSteps ('Ayarlar uygulan' + [char]0x0131 + 'yor') $false $script:PendingRp { Start-OpStates }
    }
}

function Init-Page_optimize {
    $script:OpItems = (Get-CatalogFor 'opt' '' $sync.Profile)
    $ui.op_Rp.IsChecked = ($script:Settings.RestorePoint -eq $true)
    Register-Tabs 'op' $script:OpTabs { param($s, $e) Invoke-Safe { $script:OpCat = [string]$s.Tag; Render-OpList } 'Sekme' }
    $ui.op_PA.Add_Click({ Invoke-Safe { Set-OpPreset 'auto'; Render-OpList } 'Profil' })
    $ui.op_P1.Add_Click({ Invoke-Safe { Set-OpPreset '1'; Render-OpList } 'Profil' })
    $ui.op_P2.Add_Click({ Invoke-Safe { Set-OpPreset '2'; Render-OpList } 'Profil' })
    $ui.op_P3.Add_Click({ Invoke-Safe { Set-OpPreset '3'; Render-OpList } 'Profil' })
    $ui.op_P0.Add_Click({ Invoke-Safe { Set-OpPreset '0'; Render-OpList } 'Profil' })
    $ui.op_PDrift.Add_Click({ Invoke-Safe { Set-OpPreset 'drift'; Render-OpList } 'Profil' })
    $ui.op_Preview.Add_Click({ Invoke-Safe { Start-OpApply $true } ('' + [char]0x00D6 + 'nizle') })
    $ui.op_Apply.Add_Click({ Invoke-Safe { Start-OpApply $false } 'Uygula' })
    $ui.op_Rp.Add_Click({ $script:Settings.RestorePoint = ($ui.op_Rp.IsChecked -eq $true); Save-Settings $script:Settings })
    $script:OpInit = $true
    Update-OpTierCard
    Set-OpPreset 'auto' $true
    Render-OpList
    Update-PageMode_optimize
}

function Show-Page_optimize {
    if ($script:OpItems.Count -eq 0) { $script:OpItems = (Get-CatalogFor 'opt' '' $sync.Profile) }
    Update-OpTierCard
    Update-OpUi
    if (Test-Stale 'opstates' 120) { Start-OpStates }
}

# ==================================================================
#  SAYFA: Hizmet Yoneticisi
#  Her hizmet icin bilgi tabanindan "ne yapar / kapatirsam ne olur" gosterilir.
#  Hazir secimler yalnizca Off/Man onerilerini (ve ayrica istenirse Org'u) secer; Rev/Keep/Lock asla otomatik secilmez.
# ==================================================================
$script:SvTabs = @('Off', 'Man', 'Org', 'Rev', 'Keep', 'Run', 'All')
$script:SvRows = @()
$script:SvTab = 'Off'
$script:SvSel = $null
$script:SvMap = @{}

function Get-RecText([string]$Rec) {
    switch ($Rec) {
        'Off' { return ('Kapat' + [char]0x0131 + 'labilir') }
        'Man' { return 'El ile olabilir' }
        'Org' { return ([string][char]0x015E + 'irkete g' + [char]0x00F6 + 're') }
        'Rev' { return ('G' + [char]0x00F6 + 'zden ge' + [char]0x00E7 + 'ir') }
        'Keep' { return ('Dokunmay' + [char]0x0131 + 'n') }
        'Lock' { return ('Korumal' + [char]0x0131) }
        default { return $Rec }
    }
}

function Get-RecLong([string]$Rec) {
    switch ($Rec) {
        'Off' { return ([string][char]0x00D6 + 'neri: kapat' + [char]0x0131 + 'labilir (' + [char]0x00E7 + 'o' + [char]0x011F + 'u kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' i' + [char]0x00E7 + 'in gereksiz).') }
        'Man' { return ([string][char]0x00D6 + 'neri: ' + [char]0x201C + 'El ile' + [char]0x201D + ' yap' + [char]0x0131 + 'n; gerekti' + [char]0x011F + 'inde Windows kendisi ba' + [char]0x015F + 'lat' + [char]0x0131 + 'r.') }
        'Org' { return ([string][char]0x00D6 + 'neri: ' + [char]0x015F + 'irkette gerek yoksa kapat' + [char]0x0131 + 'n; BT politikan' + [char]0x0131 + 'za g' + [char]0x00F6 + 're karar verin.') }
        'Rev' { return ('G' + [char]0x00F6 + 'zden ge' + [char]0x00E7 + 'irin: ' + [char]0x00FC + [char]0x00E7 + [char]0x00FC + 'nc' + [char]0x00FC + ' taraf veya bilinmeyen hizmet; ait oldu' + [char]0x011F + 'u program' + [char]0x0131 + ' kullan' + [char]0x0131 + 'p kullanmad' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + 'za bak' + [char]0x0131 + 'n.') }
        'Keep' { return ('Dokunmaman' + [char]0x0131 + 'z ' + [char]0x00F6 + 'nerilir; Windows' + [char]0x2019 + 'un do' + [char]0x011F + 'ru ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'mas' + [char]0x0131 + ' buna ba' + [char]0x011F + 'l' + [char]0x0131 + ' olabilir.') }
        'Lock' { return ('Korumal' + [char]0x0131 + ': bu ara' + [char]0x00E7 + ' bu hizmeti de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez.') }
        default { return '' }
    }
}

function Get-SvDetailText($R) {
    $parts = @([string]$R.Name, (ConvertTo-StateText ([string]$R.State)), (ConvertTo-ModeText ([string]$R.Mode) ([bool]$R.Delayed)), [string]$R.Grp)
    $s = ($parts -join (' ' + [char]0x00B7 + ' '))
    if ($R.Done -eq $true) { $s += (' ' + [char]0x00B7 + ' zaten ' + [char]0x00F6 + 'nerilen durumda') }
    return $s
}

function Test-SvVisible($R, [string]$Tab, [string]$Q) {
    $ok = $false
    switch ($Tab) {
        'Off' { $ok = ($R.Rec -eq 'Off') }
        'Man' { $ok = ($R.Rec -eq 'Man') }
        'Org' { $ok = ($R.Rec -eq 'Org') }
        'Rev' { $ok = ($R.Rec -eq 'Rev') }
        'Keep' { $ok = ($R.Rec -eq 'Keep' -or $R.Rec -eq 'Lock') }
        'Run' { $ok = ($R.State -eq 'Running') }
        default { $ok = $true }
    }
    if (-not $ok) { return $false }
    if ($Q -ne '' -and ([string]$R.Search).IndexOf($Q) -lt 0) { return $false }
    return $true
}

function Update-SvFilter {
    $q = Get-FilterText $ui.sv_Filter
    $vis = 0; $sel = 0
    foreach ($row in $ui.sv_List.Children) {
        if ($row -isnot [System.Windows.Controls.Border]) { continue }
        $d = $row.Tag
        if (Test-SvVisible $d $script:SvTab $q) {
            $row.Visibility = $script:VisOn; $vis++
            $c = $row.FindName('Chk')
            if ($c.IsChecked -eq $true) { $sel++ }
        } else { $row.Visibility = $script:VisOff }
    }
    $ui.sv_Count.Text = (Tr $(([string]$vis + (' hizmet g' + [char]0x00F6 + 'steriliyor ' + [char]0x00B7 + ' ') + [string]$sel + (' se' + [char]0x00E7 + 'ili'))))
}

function Update-SvSelCount {
    $n = (Get-CheckedData $ui.sv_List).Count
    $vis = 0
    foreach ($row in $ui.sv_List.Children) { if ($row -is [System.Windows.Controls.Border] -and $row.Visibility -eq $script:VisOn) { $vis++ } }
    $ui.sv_Count.Text = (Tr $(([string]$vis + (' hizmet g' + [char]0x00F6 + 'steriliyor ' + [char]0x00B7 + ' ') + [string]$n + (' se' + [char]0x00E7 + 'ili'))))
}

function Show-SvDetail($R) {
    if ($null -eq $R) { return }
    $script:SvSel = $R
    $ui.sv_DName.Text = (Tr $([string]$R.Display))
    $ui.sv_DSub.Text = (Tr $((Get-SvDetailText $R)))
    $ui.sv_DRec.Text = (Tr $((Get-RecLong ([string]$R.Rec))))
    $ui.sv_DRec.Foreground = (Get-Br ([string]$script:BrByRec[[string]$R.Rec]))
    $w = [string]$R.What
    if ($w -eq '') { $w = ('A' + [char]0x00E7 + [char]0x0131 + 'klama bulunamad' + [char]0x0131 + '.') }
    $ui.sv_DWhat.Text = (Tr $($w))
    $i = [string]$R.IfOff
    if ($i -eq '') { $i = ('Bilgi yok; emin de' + [char]0x011F + 'ilseniz dokunmay' + [char]0x0131 + 'n.') }
    $ui.sv_DIfOff.Text = (Tr $($i))
    $ui.sv_DNote.Text = (Tr $([string]$R.Note))
    $ui.sv_DPath.Text = (Tr $((([string]$R.Path + '  [' + [string]$R.Account + ']').Trim())))
    $locked = ($R.Locked -eq $true)
    $ui.sv_DStart.IsEnabled = (-not $locked)
    $ui.sv_DStop.IsEnabled = (-not $locked)
    $ui.sv_DRestart.IsEnabled = (-not $locked)
}

$script:H_SvRowClick = { param($s, $e) try { Show-SvDetail $s.Tag } catch { } }
$script:H_SvChk = { param($s, $e) Invoke-Safe { Update-SvSelCount } ('Se' + [char]0x00E7 + 'im') }

function Render-Services {
    $ui.sv_List.Children.Clear()
    $script:SvMap = @{}
    $n = 0
    foreach ($r in $script:SvRows) {
        $r.Search = (ConvertTo-AsciiKey (([string]$r.Display) + ' ' + ([string]$r.Name) + ' ' + ([string]$r.What) + ' ' + ([string]$r.Desc)))
        $canSel = ($r.Rec -ne 'Lock')
        $br = [string]$script:BrByRec[[string]$r.Rec]
        $row = New-ItemRow @{ Title = [string]$r.Display; Detail = (Get-SvDetailText $r); Tag = (Get-RecText ([string]$r.Rec)); BrCol = $br } $r $canSel $false
        $row.Add_MouseLeftButtonUp($script:H_SvRowClick)
        if ($canSel) { $row.FindName('Chk').Add_Click($script:H_SvChk) }
        $script:SvMap[[string]$r.Name] = $row
        [void]$ui.sv_List.Children.Add($row)
        $n++
    }
    Update-SvFilter
    $ui.sv_Foot.Text = (Tr $(([string]$n + (' hizmet okundu. Sat' + [char]0x0131 + 'ra t' + [char]0x0131 + 'klay' + [char]0x0131 + 'nca sa' + [char]0x011F + 'da ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 's' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r. Hizmetler ' + [char]0x201C + [char]0x00F6 + 'nizle' + [char]0x201D + ' ile ' + [char]0x00F6 + 'nce denenebilir; her de' + [char]0x011F + 'i' + [char]0x015F + 'iklik geri al' + [char]0x0131 + 'nabilir.'))))
}

function Load-Services([bool]$Force = $false) {
    if (-not $Force -and -not (Test-Stale 'services' 180) -and $script:SvRows.Count -gt 0) { Update-SvFilter; return }
    Set-ListNote $ui.sv_List 'Hizmetler okunuyor...'
    [void](Start-Async 'Services' 'Job_Services' @{} {
        param($r)
        if ($null -eq $r) { Set-ListNote $ui.sv_List ('Hizmetler okunamad' + [char]0x0131 + '.') 'bad'; return }
        $script:SvRows = @($r.Rows)
        Set-Loaded 'services'
        Render-Services
    } 'Hizmetler okunuyor' $false $true)
}

function Select-SvPreset([string]$Kind) {
    $cnt = 0
    $tierObj = Get-CurrentTier
    foreach ($row in $ui.sv_List.Children) {
        if ($row -isnot [System.Windows.Controls.Border]) { continue }
        if ($row.Visibility -ne $script:VisOn) { continue }
        $c = $row.FindName('Chk')
        if ($c.Visibility -ne $script:VisOn) { continue }
        $d = $row.Tag
        $on = $false
        switch ($Kind) {
            'Safe' { $on = ($d.Rec -eq 'Off' -and [int]$d.Risk -le 1 -and $d.Done -ne $true) }
            'Rec' { $on = (($d.Rec -eq 'Off' -or $d.Rec -eq 'Man') -and [int]$d.Risk -le 2 -and $d.Done -ne $true) }
            'Org' { $on = ($d.Rec -eq 'Org' -and $d.Done -ne $true) }
            'Tier' { $on = (Test-SvcAdaptive $d $tierObj 1) }
            default { $on = $false }
        }
        $c.IsChecked = $on
        if ($on) { $cnt++ }
    }
    # gorunmeyen satirlar da secilmesin
    foreach ($row in $ui.sv_List.Children) {
        if ($row -isnot [System.Windows.Controls.Border]) { continue }
        if ($row.Visibility -ne $script:VisOn) { $c = $row.FindName('Chk'); if ($Kind -eq 'None') { $c.IsChecked = $false } }
    }
    if ($Kind -ne 'None') {
        if ($cnt -eq 0) { Show-Toast ('Bu sekmede bu ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x00FC + 'te uyan hizmet yok. Sekmeyi ' + [char]0x201C + 'T' + [char]0x00FC + 'm' + [char]0x00FC + [char]0x201D + ' yap' + [char]0x0131 + 'p tekrar deneyin.') 'info' }
        elseif ($Kind -eq 'Tier') { Show-Toast ([string]$cnt + (' hizmet se' + [char]0x00E7 + 'ildi (') + [string]$tierObj.Label + (' s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + 'na g' + [char]0x00F6 + 're; riskli olanlar ' + [char]0x00F6 + 'nerilmez). ' + [char]0x00D6 + 'nizle ile ne olaca' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00F6 + 'rebilirsiniz.')) 'info' }
        else { Show-Toast ([string]$cnt + (' hizmet se' + [char]0x00E7 + 'ildi. ' + [char]0x00D6 + 'nizle ile ne olaca' + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00F6 + 'rebilirsiniz.')) 'info' }
    }
    Update-SvSelCount
}

# Mode: Off | Man | Auto
function Start-SvApply([string]$Mode, [bool]$Preview) {
    $sel = (Get-CheckedData $ui.sv_List)
    if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce hizmet se' + [char]0x00E7 + 'in (onay kutular' + [char]0x0131 + ').') 'warn'; return }
    $names = @($sel | ForEach-Object { [string]$_.Name })
    if ($Preview) {
        $pm = 'Off'
        if (@($sel | Where-Object { $_.Rec -ne 'Man' }).Count -eq 0) { $pm = 'Man' }
        Start-PlanJob (New-ServiceSteps $names $pm) ([string][char]0x00D6 + 'nizleme: hizmetler') $true $false
        return
    }
    $steps = New-ServiceSteps $names $Mode
    $word = ('devre d' + [char]0x0131 + [char]0x015F + [char]0x0131 + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'lacak')
    if ($Mode -eq 'Man') { $word = ('el ile (gerekti' + [char]0x011F + 'inde ba' + [char]0x015F + 'layan) yap' + [char]0x0131 + 'lacak') } elseif ($Mode -eq 'Auto') { $word = ('otomatik ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak') }
    $risky = @($sel | Where-Object { $_.Rec -eq 'Keep' -or $_.Rec -eq 'Rev' } | ForEach-Object { [string]$_.Display })
    $txt = ([string]$names.Count + ' hizmet ' + $word + ":`r`n`r`n" + (Format-NameList @($sel | ForEach-Object { [string]$_.Display }) 10))
    $danger = $false
    if ($Mode -ne 'Auto' -and $risky.Count -gt 0) {
        $txt += (("`r`n`r`nD" + [char]0x0130 + "KKAT: ") + [string]$risky.Count + (' hizmet ' + [char]0x201C + 'g' + [char]0x00F6 + 'zden ge' + [char]0x00E7 + 'ir / dokunmay' + [char]0x0131 + 'n' + [char]0x201D + ' s' + [char]0x0131 + 'n' + [char]0x0131 + 'f' + [char]0x0131 + 'nda. Emin de' + [char]0x011F + 'ilseniz se' + [char]0x00E7 + 'imden ' + [char]0x00E7 + [char]0x0131 + 'kar' + [char]0x0131 + 'n:') + "`r`n" + (Format-NameList $risky 6))
        $danger = $true
    }
    $txt += (("`r`n`r`nEski ba" + [char]0x015F + "lang" + [char]0x0131 + [char]0x00E7 + " t" + [char]0x00FC + "rleri kaydedilir; Ge" + [char]0x00E7 + "mi" + [char]0x015F + " sayfas" + [char]0x0131 + "ndan geri al" + [char]0x0131 + "nabilir. De" + [char]0x011F + "i" + [char]0x015F + "iklikten " + [char]0x00F6 + "nce geri y" + [char]0x00FC + "kleme noktas" + [char]0x0131 + " olu" + [char]0x015F + "turulur."))
    $script:PendingSteps = $steps
    Show-Confirm ('Hizmetleri de' + [char]0x011F + 'i' + [char]0x015F + 'tir') $txt 'Uygula' {
        Start-PlanJob $script:PendingSteps ('Hizmetler de' + [char]0x011F + 'i' + [char]0x015F + 'tiriliyor') $false ($script:Settings.RestorePoint -eq $true) { Clear-Loaded 'services'; Load-Services $true }
    } $danger
}

function Start-SvAction([string]$Action) {
    $r = $script:SvSel
    if ($null -eq $r) { Show-Toast ([string][char]0x00D6 + 'nce listeden bir hizmet se' + [char]0x00E7 + 'in.') 'warn'; return }
    $name = [string]$r.Name
    if ($r.PerUser -eq $true) { Show-Toast ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'ya ' + [char]0x00F6 + 'zel hizmet ' + [char]0x00F6 + 'rnekleri buradan ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'p durdurulamaz.') 'warn'; return }
    $script:SvActName = $name
    [void](Start-Async 'SvcAct' 'Job_ServiceAction' @{ Name = $name; Action = $Action } {
        param($res)
        $n = [string]$script:SvActName
        try {
            $svc = Get-Service -Name $n -ErrorAction Stop
            $row = $script:SvMap[$n]
            if ($null -ne $row) {
                $d = $row.Tag
                $d.State = [string]$svc.Status
                $row.FindName('Det').Text = (Tr $((Get-SvDetailText $d)))
            }
            if ($null -ne $script:SvSel -and [string]$script:SvSel.Name -eq $n) { Show-SvDetail $script:SvSel }
        } catch { }
        if ($null -ne $res -and $res.Ok -eq $true) { Show-Toast ('Hizmet i' + [char]0x015F + 'lemi tamamland' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Hizmet i' + [char]0x015F + 'lemi ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
    } ('Hizmet: ' + $name))
}

function Init-Page_services {
    Register-Tabs 'sv' $script:SvTabs { param($s, $e) Invoke-Safe { $script:SvTab = [string]$s.Tag; Update-SvFilter } 'Sekme' }
    $ui.sv_Filter.Add_TextChanged({ Invoke-Safe { Update-SvFilter } ('S' + [char]0x00FC + 'z') })
    $ui.sv_Refresh.Add_Click({ Invoke-Safe { Load-Services $true } 'Yenile' })
    $ui.sv_PSafe.Add_Click({ Invoke-Safe { Select-SvPreset 'Safe' } ('Se' + [char]0x00E7) })
    $ui.sv_PRec.Add_Click({ Invoke-Safe { Select-SvPreset 'Rec' } ('Se' + [char]0x00E7) })
    $ui.sv_PTier.Add_Click({ Invoke-Safe { Select-SvPreset 'Tier' } ('Se' + [char]0x00E7) })
    $ui.sv_POrg.Add_Click({ Invoke-Safe { Select-SvPreset 'Org' } ('Se' + [char]0x00E7) })
    $ui.sv_PNone.Add_Click({ Invoke-Safe { Select-SvPreset 'None' } ('Se' + [char]0x00E7) })
    $ui.sv_Preview.Add_Click({ Invoke-Safe { Start-SvApply 'Off' $true } ([string][char]0x00D6 + 'nizle') })
    $ui.sv_Off.Add_Click({ Invoke-Safe { Start-SvApply 'Off' $false } 'Uygula' })
    $ui.sv_Man.Add_Click({ Invoke-Safe { Start-SvApply 'Man' $false } 'Uygula' })
    $ui.sv_Auto.Add_Click({ Invoke-Safe { Start-SvApply 'Auto' $false } 'Uygula' })
    $ui.sv_DStart.Add_Click({ Invoke-Safe { Start-SvAction 'Start' } ('Ba' + [char]0x015F + 'lat') })
    $ui.sv_DStop.Add_Click({ Invoke-Safe { Start-SvAction 'Stop' } 'Durdur' })
    $ui.sv_DRestart.Add_Click({ Invoke-Safe { Start-SvAction 'Restart' } 'Yeniden' })
}

function Select-Sub_services([string]$Sub) {
    if (-not (Select-TabChip 'sv' $Sub)) { $script:SvTab = $Sub; Update-SvFilter }
}

function Show-Page_services { Load-Services $false }

# ==================================================================
#  SAYFA: Uygulamalar ve Baslangic  (Magaza uygulamalari, baslangic, yuklu programlar, ucretsiz araclar)
# ==================================================================
$script:ApTabs = @('store', 'startup', 'programs', 'foss')
$script:ApTab = 'store'
$script:ApData = @{ store = $null; startup = $null; programs = $null }
$script:StartupHeavy = '(?i)spotify|steam|discord|epicgames|teams|skype|zoom|adobe.*(update|updater|arm|gc)|ccleaner|utorrent|bittorrent|itunes|ipod|java.*update|jusched|onenote|cortana|dropbox|googledrive|yourphone|phoneexperience|origin|battle\.net|riotclient|gamebar|msedge.*(auto|boot)|livemessenger|realplayer|quicktime'

function Test-ApManaged {
    $p = $sync.Profile
    if ($null -eq $p) { return $false }
    return ($p.IsManaged -eq $true)
}

function Set-ApBar([string]$Tab) {
    switch ($Tab) {
        'store' {
            Show-OnlyBar 'ap' @('ap_Refresh', 'ap_Rec', 'ap_Clear', 'ap_Alt', 'ap_Main')
            $ui.ap_Rec.Content = (Tr $(([string][char]0x00D6 + 'nerilenleri se' + [char]0x00E7))); $ui.ap_Alt.Content = (Tr $(([string][char]0x00D6 + 'nizle'))); $ui.ap_Main.Content = (Tr $(('Se' + [char]0x00E7 + 'ilenleri kald' + [char]0x0131 + 'r')))
            $ui.ap_Main.Style = $script:Win.FindResource('BtnDanger')
        }
        'startup' {
            Show-OnlyBar 'ap' @('ap_Refresh', 'ap_Rec', 'ap_Clear', 'ap_Alt', 'ap_Main')
            $ui.ap_Rec.Content = (Tr $(('Gereksizleri se' + [char]0x00E7))); $ui.ap_Alt.Content = (Tr $(('Se' + [char]0x00E7 + 'ilenleri a' + [char]0x00E7))); $ui.ap_Main.Content = (Tr $(('Se' + [char]0x00E7 + 'ilenleri kapat')))
            $ui.ap_Main.Style = $script:Win.FindResource('BtnPrimary')
        }
        'programs' { Show-OnlyBar 'ap' @('ap_Refresh') }
        'foss' {
            Show-OnlyBar 'ap' @('ap_Clear', 'ap_Main')
            $ui.ap_Main.Content = (Tr $(('Se' + [char]0x00E7 + 'ilenleri kur')))
            $ui.ap_Main.Style = $script:Win.FindResource('BtnPrimary')
        }
    }
}

# ---------------- ortak suzme ----------------
function Update-ApFilter {
    $q = Get-FilterText $ui.ap_Filter
    $vis = 0
    foreach ($row in $ui.ap_List.Children) {
        if ($row -isnot [System.Windows.Controls.Border]) { continue }
        $d = $row.Tag
        $ok = $true
        if ($q -ne '' -and $d -is [hashtable] -and ([string]$d.Search).IndexOf($q) -lt 0) { $ok = $false }
        if ($ok) { $row.Visibility = $script:VisOn; $vis++ } else { $row.Visibility = $script:VisOff }
    }
}

# ---------------- Magaza uygulamalari ----------------
function Render-ApStore {
    $ui.ap_List.Children.Clear()
    $rows = @($script:ApData.store)
    if ($rows.Count -eq 0) { Add-Note $ui.ap_List ('Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir gereksiz Ma' + [char]0x011F + 'aza uygulamas' + [char]0x0131 + ' bulunamad' + [char]0x0131 + '; sistem temiz g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor.') 'good'; $ui.ap_Foot.Text = (Tr $('')); return }
    $managed = Test-ApManaged
    foreach ($r in $rows) {
        $rec = ($r.R -eq $true)
        if ($managed) { $rec = ($r.C -eq $true) }
        $tag = ''
        $br = 'BrFaint'
        if ($rec) { $tag = ([string][char]0x00D6 + 'nerilir'); $br = 'BrAccent' }
        $det = [string]$r.Pkg
        if ([int]$r.Count -gt 1) { $det += ((' ' + [char]0x00B7 + ' ') + [string]$r.Count + ' paket') }
        $d = @{ Pattern = [string]$r.Pattern; Display = [string]$r.Display; Rec = $rec; Search = (ConvertTo-AsciiKey (([string]$r.Display) + ' ' + ([string]$r.Pkg))) }
        $row = New-ItemRow @{ Title = [string]$r.Display; Detail = $det; Tag = $tag; BrCol = $br } $d $true $false
        [void]$ui.ap_List.Children.Add($row)
    }
    $ui.ap_Foot.Text = (Tr $(([string]$rows.Count + (' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir uygulama. Windows' + [char]0x2019 + 'un ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'mas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in gerekenler (Ma' + [char]0x011F + 'aza, Hesaplar, G' + [char]0x00FC + 'venlik vb.) listede yoktur ve korunur.'))))
    Update-ApFilter
}

function Start-ApStore([bool]$Preview) {
    $sel = (Get-CheckedData $ui.ap_List)
    if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak uygulamalar' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') 'warn'; return }
    $ops = @($sel | ForEach-Object { @{ T = 'Appx'; Name = [string]$_.Pattern } })
    $steps = @(@{ Id = 'Apps'; Title = ('Se' + [char]0x00E7 + 'ili Ma' + [char]0x011F + 'aza uygulamalar' + [char]0x0131); Ops = $ops; Reboot = $false })
    if ($Preview) { Start-PlanJob $steps ([string][char]0x00D6 + 'nizleme: uygulamalar') $true $false; return }
    $script:PendingSteps = $steps
    Show-Confirm ('Uygulamalar' + [char]0x0131 + ' kald' + [char]0x0131 + 'r') ([string]$sel.Count + (" uygulama kald" + [char]0x0131 + "r" + [char]0x0131 + "lacak:`r`n`r`n") + (Format-NameList @($sel | ForEach-Object { [string]$_.Display }) 10) + ("`r`n`r`n" + [char]0x0130 + "sterseniz Microsoft Store" + [char]0x2019 + "dan yeniden kurabilirsiniz.")) ('Kald' + [char]0x0131 + 'r') {
        Start-PlanJob $script:PendingSteps ('Uygulamalar kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false ($script:Settings.RestorePoint -eq $true) { Load-ApTab 'store' $true }
    } $true
}

# ---------------- baslangic ----------------
function Render-ApStartup {
    $ui.ap_List.Children.Clear()
    $rows = @($script:ApData.startup)
    if ($rows.Count -eq 0) { Add-Note $ui.ap_List ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + 'ta ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'an ' + [char]0x00F6 + [char]0x011F + 'e bulunamad' + [char]0x0131 + '.'); $ui.ap_Foot.Text = (Tr $('')); return }
    $on = 0
    foreach ($r in $rows) {
        $pub = [string]$r.Publisher
        if ($pub -eq '') { $pub = ('yay' + [char]0x0131 + 'nc' + [char]0x0131 + ' bilinmiyor') }
        $det = ([string]$r.Src + (' ' + [char]0x00B7 + ' ') + $pub + (' ' + [char]0x00B7 + ' ') + (Limit-Text ([string]$r.Command) 90))
        $tag = ('Kapal' + [char]0x0131); $br = 'BrFaint'
        if ($r.Enabled -eq $true) { $tag = ('A' + [char]0x00E7 + [char]0x0131 + 'k'); $br = 'BrGood'; $on++ }
        if ($r.Kind -ne 'Task' -and $r.Exists -ne $true -and [string]$r.Exe -ne '') { $tag = $tag + (' ' + [char]0x00B7 + ' dosya yok'); $br = 'BrWarn' }
        $heavy = ([string]$r.Name -match $script:StartupHeavy) -or ([string]$r.Command -match $script:StartupHeavy)
        $d = @{ Item = $r; Name = [string]$r.Name; Heavy = $heavy; Search = (ConvertTo-AsciiKey (([string]$r.Name) + ' ' + $pub + ' ' + ([string]$r.Command))) }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = $det; Tag = $tag; BrCol = $br } $d $true $false
        [void]$ui.ap_List.Children.Add($row)
    }
    $ui.ap_Foot.Text = (Tr $(([string]$on + (' a' + [char]0x00E7 + [char]0x0131 + 'k ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' ' + [char]0x00F6 + [char]0x011F + 'esi. ' + [char]0x00D6 + [char]0x011F + 'eleri silmeyiz; yaln' + [char]0x0131 + 'zca Windows' + [char]0x2019 + 'un kendi ' + [char]0x201C + 'ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' uygulamalar' + [char]0x0131 + [char]0x201D + ' anahtar' + [char]0x0131 + 'yla kapat' + [char]0x0131 + 'r' + [char]0x0131 + 'z, istedi' + [char]0x011F + 'iniz an yeniden a' + [char]0x00E7 + 'abilirsiniz.'))))
    Update-ApFilter
}

function New-StartupStepOps($Items, [bool]$Enable) {
    $ops = New-Object System.Collections.ArrayList
    foreach ($it in @($Items)) {
        if ($it.Kind -eq 'Task') {
            $act = 'Disable'; if ($Enable) { $act = 'Enable' }
            [void]$ops.Add(@{ T = 'Task'; Path = [string]$it.Path; Name = [string]$it.Name; Action = $act })
        } else {
            [void]$ops.Add((New-StartupOp $it $Enable))
        }
    }
    return , $ops.ToArray()
}

function Start-ApStartup([bool]$Enable) {
    $sel = (Get-CheckedData $ui.ap_List)
    if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce ' + [char]0x00F6 + [char]0x011F + 'e se' + [char]0x00E7 + 'in.') 'warn'; return }
    $items = @($sel | ForEach-Object { $_.Item })
    $ops = New-StartupStepOps $items $Enable
    $t = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' ' + [char]0x00F6 + [char]0x011F + 'elerini kapat')
    if ($Enable) { $t = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' ' + [char]0x00F6 + [char]0x011F + 'elerini a' + [char]0x00E7) }
    $steps = @(@{ Id = 'Startup'; Title = $t; Ops = $ops; Reboot = $false })
    $script:PendingSteps = $steps
    Show-Confirm $t ([string]$sel.Count + (" " + [char]0x00F6 + [char]0x011F + "e i" + [char]0x015F + "lenecek:`r`n`r`n") + (Format-NameList @($sel | ForEach-Object { [string]$_.Name }) 10) + ("`r`n`r`nDe" + [char]0x011F + "i" + [char]0x015F + "iklik bir sonraki oturum a" + [char]0x00E7 + [char]0x0131 + "l" + [char]0x0131 + [char]0x015F + [char]0x0131 + "nda etkili olur; geri al" + [char]0x0131 + "nabilir.")) 'Tamam' {
        Start-PlanJob $script:PendingSteps ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' ' + [char]0x00F6 + [char]0x011F + 'eleri') $false $false { Load-ApTab 'startup' $true }
    }
}

# ---------------- yuklu programlar ----------------
$script:H_ProgUninstall = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        $cmd = [string]$d.Uninstall
        if ($cmd -eq '') { Show-Toast ('Bu program i' + [char]0x00E7 + 'in kald' + [char]0x0131 + 'rma komutu kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'il.') 'warn'; return }
        $script:PendingUninstall = $cmd
        Show-Confirm ('Program' + [char]0x0131 + ' kald' + [char]0x0131 + 'r') ([string]$d.Name + (" kald" + [char]0x0131 + "r" + [char]0x0131 + "lacak. Program" + [char]0x0131 + "n kendi kald" + [char]0x0131 + "r" + [char]0x0131 + "c" + [char]0x0131 + "s" + [char]0x0131 + " a" + [char]0x00E7 + [char]0x0131 + "l" + [char]0x0131 + "r; sorular size sorulur.")) ('Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'y' + [char]0x0131 + ' a' + [char]0x00E7) {
            try {
                Start-Process -FilePath 'cmd.exe' -ArgumentList ('/s /c "' + $script:PendingUninstall + '"') -WindowStyle Hidden | Out-Null
                Show-Toast ('Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + ' ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + '. Bittikten sonra listeyi yenileyin.') 'info'
            } catch { Show-Toast ('Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + ' ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'bad' }
        } $true
    } ('Kald' + [char]0x0131 + 'r')
}

$script:H_ProgFolder = {
    param($s, $e)
    Invoke-Safe {
        $loc = [string]$s.Tag.Location
        if ($loc -ne '' -and (Test-Path -LiteralPath $loc)) { Open-Folder $loc } else { Show-Toast ('Kurulum klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'il.') 'info' }
    } ('Klas' + [char]0x00F6 + 'r')
}

function Render-ApPrograms {
    $ui.ap_List.Children.Clear()
    $rows = @($script:ApData.programs)
    if ($rows.Count -eq 0) { Add-Note $ui.ap_List ('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' program listesi okunamad' + [char]0x0131 + '.'); return }
    $total = 0.0
    foreach ($r in $rows) {
        $bits = @()
        if ([string]$r.Publisher -ne '') { $bits += [string]$r.Publisher }
        if ([string]$r.Version -ne '') { $bits += (('s' + [char]0x00FC + 'r' + [char]0x00FC + 'm ') + [string]$r.Version) }
        if ([string]$r.Date -ne '') { $bits += [string]$r.Date }
        $sz = ''
        if ([double]$r.Size -gt 0) { $sz = (Format-Size ([double]$r.Size)); $total += [double]$r.Size }
        $b1 = ''; if ([string]$r.Uninstall -ne '') { $b1 = ('Kald' + [char]0x0131 + 'r') }
        $b2 = ''; if ([string]$r.Location -ne '') { $b2 = ('Klas' + [char]0x00F6 + 'r') }
        $d = @{ Name = [string]$r.Name; Uninstall = [string]$r.Uninstall; Location = [string]$r.Location; Search = (ConvertTo-AsciiKey (([string]$r.Name) + ' ' + ([string]$r.Publisher))) }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = ($bits -join (' ' + [char]0x00B7 + ' ')); Tag = $sz; BrCol = 'BrAccent2'; Btn1 = $b1; Btn2 = $b2 } $d $false $false
        if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_ProgUninstall) }
        if ($b2 -ne '') { $row.FindName('Act2').Add_Click($script:H_ProgFolder) }
        [void]$ui.ap_List.Children.Add($row)
    }
    $ui.ap_Foot.Text = (Tr $(([string]$rows.Count + (' program ' + [char]0x00B7 + ' kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' toplam boyut yakla' + [char]0x015F + [char]0x0131 + 'k ') + (Format-Size $total) + ('. ' + [char]0x201C + 'Kald' + [char]0x0131 + 'r' + [char]0x201D + ' program' + [char]0x0131 + 'n kendi kald' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar.'))))
    Update-ApFilter
}

# ---------------- ucretsiz ve acik kaynak araclar ----------------
function Render-ApFoss {
    $ui.ap_List.Children.Clear()
    $last = ''
    Add-FossFilterRow
    $openOnly = ($script:Settings.FossOpenOnly -eq $true)
    foreach ($t in $script:FossTools) {
        if (Test-FossHidden $t $openOnly) { continue }
        if ([string]$t.Cat -ne $last) { Add-HeadRow $ui.ap_List ([string]$t.Cat); $last = [string]$t.Cat }
        $d = @{ Id = [string]$t.Id; Name = [string]$t.N; Search = (ConvertTo-AsciiKey (([string]$t.N) + ' ' + ([string]$t.D) + ' ' + ([string]$t.Cat))) }
        $row = New-ItemRow @{ Title = [string]$t.N; Detail = (Get-FossDetail $t); Tag = [string]$t.Id; BrCol = 'BrAccent2' } $d $true $false
        [void]$ui.ap_List.Children.Add($row)
    }
    $ui.ap_Foot.Text = (Tr $(('Programlar Microsoft' + [char]0x2019 + 'un winget deposundan, yay' + [char]0x0131 + 'nc' + [char]0x0131 + ' imzas' + [char]0x0131 + ' ve ' + [char]0x00F6 + 'zet (hash) do' + [char]0x011F + 'rulamas' + [char]0x0131 + 'yla sessiz kurulur. ' + [char]0x0130 + 'nternet gerekir. Reklam yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + ' veya paketli ek program kurulmaz.')))
    Update-ApFilter
}

function Start-ApFoss {
    $sel = (Get-CheckedData $ui.ap_List)
    if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce kurulacak ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') 'warn'; return }
    $script:PendingFoss = $sel
    Show-Confirm ('Ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ' kur') ([string]$sel.Count + (" ara" + [char]0x00E7 + " winget ile kurulacak:`r`n`r`n") + (Format-NameList @($sel | ForEach-Object { [string]$_.Name }) 10)) 'Kur' {
        foreach ($t in @($script:PendingFoss)) {
            $nm = [string]$t.Name
            [void](Start-Async 'Foss' 'Job_WingetInstall' @{ Id = [string]$t.Id } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Kurulum tamamland' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Kurulum ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
            } ('Kuruluyor: ' + $nm) $false $true)
        }
    }
}

# ---------------- yukleme ----------------
# Her sekmenin kendi tamamlama blogu vardir (is sirada beklese bile sonuc dogru sekmeye yazilir)
function Complete-ApLoad([string]$Tab, $R) {
    if ($null -eq $R) {
        if ($script:ApTab -eq $Tab) { Set-ListNote $ui.ap_List ('Okunamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
        return
    }
    $script:ApData[$Tab] = @(Get-ResultRows $R)
    Set-Loaded ('apps:' + $Tab)
    if ($script:ApTab -eq $Tab) { Render-ApCurrent }
}
$script:ApDone = @{
    store    = { param($r) Complete-ApLoad 'store' $r }
    startup  = { param($r) Complete-ApLoad 'startup' $r }
    programs = { param($r) Complete-ApLoad 'programs' $r }
}

function Load-ApTab([string]$Tab, [bool]$Force = $false) {
    $script:ApTab = $Tab
    Set-ApBar $Tab
    $ui.ap_Filter.Text = (Tr $(''))
    switch ($Tab) {
        'foss' { Render-ApFoss; return }
    }
    $job = @{ store = 'Job_Apps'; startup = 'Job_Startup'; programs = 'Job_Programs' }[$Tab]
    $lbl = @{ store = ('Ma' + [char]0x011F + 'aza uygulamalar' + [char]0x0131 + ' taran' + [char]0x0131 + 'yor'); startup = ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7 + ' ' + [char]0x00F6 + [char]0x011F + 'eleri okunuyor'); programs = ('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' programlar okunuyor') }[$Tab]
    if (-not $Force -and $null -ne $script:ApData[$Tab] -and -not (Test-Stale ('apps:' + $Tab) 300)) { Render-ApCurrent; return }
    Set-ListNote $ui.ap_List ($lbl + '...')
    [void](Start-Async ('Ap_' + $Tab) $job @{} $script:ApDone[$Tab] $lbl $false $true)
}

function Render-ApCurrent {
    switch ($script:ApTab) {
        'store' { Render-ApStore }
        'startup' { Render-ApStartup }
        'programs' { Render-ApPrograms }
        'foss' { Render-ApFoss }
    }
}

function Init-Page_apps {
    Register-Tabs 'ap' $script:ApTabs { param($s, $e) Invoke-Safe { Load-ApTab ([string]$s.Tag) $false } 'Sekme' }
    $ui.ap_Filter.Add_TextChanged({ Invoke-Safe { Update-ApFilter } ('S' + [char]0x00FC + 'z') })
    $ui.ap_Refresh.Add_Click({ Invoke-Safe { Load-ApTab $script:ApTab $true } 'Yenile' })
    $ui.ap_Clear.Add_Click({ Invoke-Safe { Set-RowChecks $ui.ap_List { param($d) $false } } 'Temizle' })
    $ui.ap_Rec.Add_Click({
        Invoke-Safe {
            if ($script:ApTab -eq 'store') { Set-RowChecks $ui.ap_List { param($d) $d.Rec -eq $true } }
            elseif ($script:ApTab -eq 'startup') { Set-RowChecks $ui.ap_List { param($d) $d.Heavy -eq $true -and $d.Item.Enabled -eq $true } }
            $n = (Get-CheckedData $ui.ap_List).Count
            Show-Toast ([string]$n + (' ' + [char]0x00F6 + [char]0x011F + 'e se' + [char]0x00E7 + 'ildi.')) 'info'
        } ([string][char]0x00D6 + 'ner')
    })
    $ui.ap_Alt.Add_Click({
        Invoke-Safe {
            if ($script:ApTab -eq 'store') { Start-ApStore $true }
            elseif ($script:ApTab -eq 'startup') { Start-ApStartup $true }
        } 'Alt'
    })
    $ui.ap_Main.Add_Click({
        Invoke-Safe {
            switch ($script:ApTab) {
                'store' { Start-ApStore $false }
                'startup' { Start-ApStartup $false }
                'foss' { Start-ApFoss }
            }
        } 'Ana'
    })
}

function Select-Sub_apps([string]$Sub) {
    if (-not (Select-TabChip 'ap' $Sub)) { Load-ApTab $Sub $false }
}

function Show-Page_apps {
    $t = Get-TabKey 'ap' $script:ApTabs 'store'
    Load-ApTab $t $false
}

# ==================================================================
#  SAYFA: Temizlik ve Disk  (once tara, sonra secilenleri temizle; disk analizi)
# ==================================================================
$script:ClTabs = @('clean', 'disk', 'big', 'dup', 'compress')
$script:ClTab = 'clean'
$script:ClScan = $null
$script:ClPath = ''
$script:ClStack = New-Object System.Collections.ArrayList

# Tarama kimligi -> katalog kimligi (temizlik adimi)
$script:ClMap = @{ Temp = 'Temp'; Browsers = 'Browsers'; WerFiles = 'WerFiles'; Logs = 'Logs'; UpdCache = 'UpdCache'; Dumps = 'Dumps'; Recycle = 'Recycle'; WinOld = 'WinOld' }
$script:ClInfo = @{
    Temp      = ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' ve Windows ge' + [char]0x00E7 + 'ici klas' + [char]0x00F6 + 'rlerindeki 2 g' + [char]0x00FC + 'nden eski dosyalar.')
    Browsers  = ('Chrome, Edge, Firefox, Brave ' + [char]0x00F6 + 'nbellekleri (parolalar, ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' ve oturumlar silinmez).')
    WerFiles  = ('Windows hata raporlama ar' + [char]0x015F + 'ivleri.')
    Logs      = ('Eski CBS/DISM ve benzeri sistem g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kleri.')
    UpdCache  = ([string][char]0x0130 + 'ndirilmi' + [char]0x015F + ' g' + [char]0x00FC + 'ncelleme dosyalar' + [char]0x0131 + ' (Windows gerekirse yeniden indirir).')
    Dumps     = ('Mavi ekran ve uygulama ' + [char]0x00E7 + [char]0x00F6 + 'kme d' + [char]0x00F6 + 'k' + [char]0x00FC + 'mleri.')
    Recycle   = ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu i' + [char]0x00E7 + 'indekiler kal' + [char]0x0131 + 'c' + [char]0x0131 + ' olarak silinir.')
    WinOld    = ([string][char]0x00D6 + 'nceki Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'n' + [char]0x00FC + 'n yede' + [char]0x011F + 'i; kald' + [char]0x0131 + 'r' + [char]0x0131 + 'nca eski s' + [char]0x00FC + 'r' + [char]0x00FC + 'me d' + [char]0x00F6 + 'n' + [char]0x00FC + 'lemez.')
}

function Render-ClScan {
    $ui.cl_List.Children.Clear()
    $s = $script:ClScan
    if ($null -eq $s) { Add-Note $ui.cl_List ('Hen' + [char]0x00FC + 'z taranmad' + [char]0x0131 + '. ' + [char]0x201C + 'Tara' + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n; tarama hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silmez.'); $ui.cl_Total.Text = (Tr $('')); return }
    $ui.cl_Total.Text = (Tr $((('Temizlenebilir alan: yakla' + [char]0x015F + [char]0x0131 + 'k ') + (Format-Size ([double]$s.Total)))))
    foreach ($r in @($s.Rows)) {
        $id = [string]$r.Id
        $b = [double]$r.Bytes
        $info = [string]$script:ClInfo[$id]
        $tag = (Format-Size $b)
        $br = 'BrAccent'
        $safe = ($id -ne 'Recycle' -and $id -ne 'WinOld')
        if (-not $safe) { $br = 'BrWarn' }
        $d = @{ Id = $id; Cat = [string]$script:ClMap[$id]; Bytes = $b; Name = [string]$r.Name }
        $chkOn = ($safe -and $b -gt 0 -and @('Dumps', 'Shader', 'Thumbs', 'AppCaches') -notcontains $id)
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = $info; Tag = $tag; BrCol = $br } $d ($b -gt 0) $chkOn
        [void]$ui.cl_List.Children.Add($row)
    }
    $ui.cl_Foot.Text = (Tr $(('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z (Belgeler, Resimler, Masa' + [char]0x00FC + 'st' + [char]0x00FC + ') bu listede yoktur ve asla silinmez. Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu ve Windows.old varsay' + [char]0x0131 + 'lan olarak i' + [char]0x015F + 'aretli gelmez.')))
}

function Start-ClScan {
    $script:ClScan = $null
    Set-ListNote $ui.cl_List ('Taran' + [char]0x0131 + 'yor... (hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silinmez)')
    [void](Start-Async 'CleanScan' 'Job_CleanScan' @{} {
        param($r)
        if ($null -eq $r) { Set-ListNote $ui.cl_List ('Tarama tamamlanamad' + [char]0x0131 + '.') 'bad'; return }
        $script:ClScan = $r
        Set-Loaded 'clean'
        if ($script:ClTab -eq 'clean') { Render-ClScan }
    } ('Temizlik taramas' + [char]0x0131) $false $true)
}

function Start-ClClean {
    $sel = (Get-CheckedData $ui.cl_List)
    if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce temizlenecek ' + [char]0x00F6 + [char]0x011F + 'eleri i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $ids = @($sel | ForEach-Object { [string]$_.Cat } | Where-Object { $_ -ne '' })
    $steps = New-StepsFromIds $ids
    $total = 0.0
    foreach ($x in $sel) { $total += [double]$x.Bytes }
    $names = @($sel | ForEach-Object { [string]$_.Name + '  (' + (Format-Size ([double]$_.Bytes)) + ')' })
    $script:PendingSteps = $steps
    $danger = (@($sel | Where-Object { $_.Id -eq 'WinOld' -or $_.Id -eq 'Recycle' }).Count -gt 0)
    Show-Confirm ('Temizli' + [char]0x011F + 'i ba' + [char]0x015F + 'lat') (([string][char]0x015E + "unlar kal" + [char]0x0131 + "c" + [char]0x0131 + " olarak silinecek (yakla" + [char]0x015F + [char]0x0131 + "k ") + (Format-Size $total) + "):`r`n`r`n" + (Format-NameList $names 10) + "`r`n`r`nSilinen dosyalar geri getirilemez.") 'Temizle' {
        Start-PlanJob $script:PendingSteps ('Temizlik yap' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { $script:ClScan = $null; Render-ClScan; Start-ClScan }
    } $danger
}

# ---------------- disk analizi ----------------
function Render-ClDisk($Rows) {
    $ui.cl_List.Children.Clear()
    $arr = @($Rows)
    $max = 1.0
    foreach ($r in $arr) { if ([double]$r.Bytes -gt $max) { $max = [double]$r.Bytes } }
    $total = 0.0
    foreach ($r in $arr) { $total += [double]$r.Bytes }
    $ui.cl_Total.Text = (Tr $(($script:ClPath + ('   ' + [char]0x00B7 + '   ') + (Format-Size $total))))
    foreach ($r in $arr) {
        $b = [double]$r.Bytes
        $det = ('%' + [string][int][math]::Round(100.0 * $b / [math]::Max($total, 1.0)) + (' ' + [char]0x00B7 + ' ') + [string][int]$r.Files + ' dosya')
        $isDir = ([string]$r.Name -notlike '(*')
        $b1 = ''; if ($isDir) { $b1 = ([string][char]0x0130 + [char]0x00E7 + 'ine gir') }
        $d = @{ Path = [string]$r.Path; Name = [string]$r.Name }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = $det; Tag = (Format-Size $b); BrCol = 'BrAccent2'; Btn1 = $b1; Btn2 = 'Gezgin' } $d $false $false
        $row.Tag = $d
        if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_ClEnter) }
        $row.FindName('Act2').Add_Click($script:H_ClExplorer)
        [void]$ui.cl_List.Children.Add($row)
    }
    $ui.cl_Foot.Text = (Tr $(('Bu g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm yaln' + [char]0x0131 + 'zca boyutlar' + [char]0x0131 + ' g' + [char]0x00F6 + 'sterir; hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silmez. B' + [char]0x00FC + 'y' + [char]0x00FC + 'k klas' + [char]0x00F6 + 'rleri Gezgin' + [char]0x2019 + 'de a' + [char]0x00E7 + [char]0x0131 + 'p kendiniz inceleyin.')))
}

$script:H_ClEnter = { param($s, $e) Invoke-Safe { Start-ClDisk ([string]$s.Tag.Path) $true } 'Disk' }
$script:H_ClExplorer = { param($s, $e) Invoke-Safe { Open-Folder ([string]$s.Tag.Path) } 'Gezgin' }

function Start-ClDisk([string]$Path, [bool]$Push) {
    if ($Path -eq '') { return }
    if ($Push -and $script:ClPath -ne '') { [void]$script:ClStack.Add($script:ClPath) }
    $script:ClPath = $Path
    Set-ListNote $ui.cl_List (('Boyutlar hesaplan' + [char]0x0131 + 'yor: ') + $Path)
    [void](Start-Async 'DiskUse' 'Job_DiskUsage' @{ Path = $Path } {
        param($r)
        if ($null -eq $r) { Set-ListNote $ui.cl_List ('Hesaplanamad' + [char]0x0131 + '.') 'bad'; return }
        if ($script:ClTab -eq 'disk') { Render-ClDisk (Get-ResultRows $r) }
    } 'Disk analizi' $false $true)
}

function Init-Page_clean {
    Register-Tabs 'cl' $script:ClTabs { param($s, $e) Invoke-Safe { Set-ClTab ([string]$s.Tag) } 'Sekme' }
    $ui.cl_Scan.Add_Click({ Invoke-Safe { Start-ClScan } 'Tara' })
    $ui.cl_Clean.Add_Click({ Invoke-Safe { Start-ClClean } 'Temizle' })
    $ui.cl_Pick.Add_Click({
        Invoke-Safe {
            $f = Select-Folder ('Analiz edilecek klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in')
            if ($f -ne '') { $script:ClStack.Clear(); $script:ClPath = ''; Start-ClDisk $f $false }
        } ('Klas' + [char]0x00F6 + 'r')
    })
    $ui.cl_Up.Add_Click({
        Invoke-Safe {
            if ($script:ClStack.Count -gt 0) {
                $p = [string]$script:ClStack[$script:ClStack.Count - 1]
                $script:ClStack.RemoveAt($script:ClStack.Count - 1)
                Start-ClDisk $p $false
            } else {
                $par = ''
                try { $par = [string][System.IO.Directory]::GetParent($script:ClPath).FullName } catch { }
                if ($par -ne '') { Start-ClDisk $par $false } else { Show-Toast ([string][char]0x00DC + 'st klas' + [char]0x00F6 + 'r yok.') 'info' }
            }
        } ('Yukar' + [char]0x0131)
    })
    $ui.cl_Open.Add_Click({ Invoke-Safe { Open-Folder $script:ClPath } ('A' + [char]0x00E7) })
    Init-ClFiles
    Init-ClCompress
}

function Select-Sub_clean([string]$Sub) {
    if (-not (Select-TabChip 'cl' $Sub)) { Set-ClTab $Sub }
}

function Show-Page_clean {
    $t = Get-TabKey 'cl' $script:ClTabs 'clean'
    Set-ClTab $t
}

# ==================================================================
#  SAYFA: Guvenlik  (denetim sonuclari, sertlestirme ayarlari, hizli islemler)
# ==================================================================
$script:ScTabs = @('audit', 'fix', 'harden', 'quick')
$script:ScTab = 'audit'
$script:ScItems = @()
$script:ScSel = @{}

$script:H_ScAct = { param($s, $e) Invoke-Safe { Invoke-FindingAction $s.Tag.Action } 'Bulgu eylemi' }
$script:H_ScChk = { param($s, $e) $script:ScSel[[string]$s.Tag] = ($s.IsChecked -eq $true); Update-ScFoot }

function Get-CatLabel([string]$C) {
    switch ($C) { 'sec' { return ('G' + [char]0x00FC + 'venlik') } 'perf' { return 'Performans' } 'maint' { return ('Bak' + [char]0x0131 + 'm') } default { return $C } }
}

function Render-ScAudit {
    $ui.sc_List.Children.Clear()
    $h = $script:Health
    if ($null -eq $h) {
        Add-Note $ui.sc_List ('Hen' + [char]0x00FC + 'z denetim yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '. ' + [char]0x201C + 'Tam denetimi ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n (salt okunur, sistemde de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yapmaz).')
        $ui.sc_Foot.Text = (Tr $(''))
        return
    }
    $sc = $h.Score
    $all = [double]$sc.All
    $key = 'BrGood'
    if ($all -lt 60) { $key = 'BrBad' } elseif ($all -lt 80) { $key = 'BrWarn' }
    $ui.sc_GScore.Stroke = (Get-Br $key)
    Set-Ring $ui.sc_GScore $all 26.48
    $ui.sc_VScore.Text = (Tr $([string][int]$all))
    $ui.sc_Sum.Text = (Tr $((('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ' ') + [string][int]$all + ('  ' + [char]0x00B7 + '  g' + [char]0x00FC + 'venlik ') + [string]$sc.Sec + ('  ' + [char]0x00B7 + '  performans ') + [string]$sc.Perf + ('  ' + [char]0x00B7 + '  bak' + [char]0x0131 + 'm ') + [string]$sc.Maint)))
    $ui.sc_Sub.Text = (Tr $(('Son denetim: ' + (Format-HealthTime 'dd.MM.yyyy HH:mm') + ('. K' + [char]0x0131 + 'rm' + [char]0x0131 + 'z' + [char]0x0131 + ' ve sar' + [char]0x0131 + ' ' + [char]0x00F6 + [char]0x011F + 'eler dikkat ister; mavi ' + [char]0x00F6 + [char]0x011F + 'eler bilgidir; ye' + [char]0x015F + 'il ' + [char]0x00F6 + [char]0x011F + 'eler sorunsuzdur.'))))
    $order = @('bad', 'warn', 'info', 'ok')
    $names = @{ bad = 'Acil ilgi gerektirenler'; warn = ([string][char]0x00D6 + 'nerilenler'); info = 'Bilgi'; ok = 'Sorunsuz' }
    foreach ($st in $order) {
        $grp = @($h.Findings | Where-Object { [string]$_.Status -eq $st })
        if ($grp.Count -eq 0) { continue }
        Add-HeadRow $ui.sc_List ($names[$st] + ' (' + [string]$grp.Count + ')')
        foreach ($f in $grp) {
            $br = 'BrInfo'
            if ($st -eq 'bad') { $br = 'BrBad' } elseif ($st -eq 'warn') { $br = 'BrWarn' } elseif ($st -eq 'ok') { $br = 'BrGood' }
            $btn = ''
            if ($null -ne $f.Action -and $f.Action.ContainsKey('Label')) { $btn = [string]$f.Action.Label }
            $fx = $null
            if ($null -ne $f.Fix -and ([string]$f.Fix.Mode -eq 'Auto' -or [string]$f.Fix.Mode -eq 'Click')) { $fx = $f.Fix }
            $ak = ''
            if ($null -ne $f.Action) { $ak = [string]$f.Action.Kind }
            $d = @{ Action = $f.Action; Id = [string]$f.Id; Title = [string]$f.Title; Fix = $fx; Mode = '' }
            if ($null -ne $fx) { $d.Mode = [string]$fx.Mode }
            if ($null -ne $fx -and ($ak -eq 'Tweak' -or $ak -eq 'Run' -or $btn -eq '')) {
                $row = New-ItemRow @{ Title = [string]$f.Title; Detail = [string]$f.Detail; Tag = (Get-CatLabel ([string]$f.Cat)); BrCol = $br; Btn1 = ('D' + [char]0x00FC + 'zelt') } $d $false $false
                $row.FindName('Act').Add_Click($script:H_ScFix)
            } elseif ($null -ne $fx) {
                $row = New-ItemRow @{ Title = [string]$f.Title; Detail = [string]$f.Detail; Tag = (Get-CatLabel ([string]$f.Cat)); BrCol = $br; Btn1 = ('D' + [char]0x00FC + 'zelt'); Btn2 = $btn } $d $false $false
                $row.FindName('Act').Add_Click($script:H_ScFix)
                $row.FindName('Act2').Add_Click($script:H_ScAct)
            } else {
                $row = New-ItemRow @{ Title = [string]$f.Title; Detail = [string]$f.Detail; Tag = (Get-CatLabel ([string]$f.Cat)); BrCol = $br; Btn1 = $btn } $d $false $false
                if ($btn -ne '') { $row.FindName('Act').Add_Click($script:H_ScAct) }
            }
            [void]$ui.sc_List.Children.Add($row)
        }
    }
    $ui.sc_Foot.Text = (Tr $(('Denetim yaln' + [char]0x0131 + 'zca okur. D' + [char]0x00FC + 'zeltme d' + [char]0x00FC + [char]0x011F + 'meleri her de' + [char]0x011F + 'i' + [char]0x015F + 'iklik i' + [char]0x00E7 + 'in onay ister ve geri al' + [char]0x0131 + 'nabilir.')))
}

# Pano saglik verisini yenileyince cagrilir
function Update-SecurityFromHealth {
    if (-not $script:Pages.ContainsKey('security')) { return }
    if ($script:ScTab -eq 'audit') { Render-ScAudit; Update-FixButtons }
    elseif ($script:ScTab -eq 'fix') { Render-ScFix }
}

function Update-ScFoot {
    $n = 0
    foreach ($k in @($script:ScSel.Keys)) { if ($script:ScSel[$k] -eq $true) { $n++ } }
    $ui.sc_Foot.Text = (Tr $(([string]$n + (' sertle' + [char]0x015F + 'tirme ayar' + [char]0x0131 + ' se' + [char]0x00E7 + 'ili. ' + [char]0x00D6 + 'nizle ile ne de' + [char]0x011F + 'i' + [char]0x015F + 'ece' + [char]0x011F + 'ini ' + [char]0x00F6 + 'nce g' + [char]0x00F6 + 'rebilirsiniz.'))))
}

function Render-ScHarden {
    $ui.sc_List.Children.Clear()
    foreach ($c in $script:ScItems) {
        $lv = Get-OpLevelInfo ([int]$c.Level)
        $det = [string]$c.Desc
        if ($det.Length -gt 230) { $det = $det.Substring(0, 227) + '...' }
        $flags = @()
        if ($c.Reboot -eq $true) { $flags += ('yeniden ba' + [char]0x015F + 'latma gerekir') }
        if ($c.Irrev -eq $true) { $flags += ('geri al' + [char]0x0131 + 'namaz') }
        if ($flags.Count -gt 0) { $det += ('  [' + ($flags -join ', ') + ']') }
        $row = New-ItemRow @{ Title = [string]$c.Title; Detail = $det; Tag = $lv.Text; BrCol = $lv.Br } @{ Id = [string]$c.Id } $true ($script:ScSel[[string]$c.Id] -eq $true)
        $chk = $row.FindName('Chk')
        $chk.Tag = [string]$c.Id
        $chk.Add_Click($script:H_ScChk)
        [void]$ui.sc_List.Children.Add($row)
    }
    Update-ScFoot
}

function Get-ScSelectedIds {
    $ids = New-Object System.Collections.ArrayList
    foreach ($c in $script:ScItems) { if ($script:ScSel[[string]$c.Id] -eq $true) { [void]$ids.Add([string]$c.Id) } }
    return , $ids.ToArray()
}

function Start-ScApply([bool]$Preview) {
    $ids = Get-ScSelectedIds
    if ($ids.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce ayar se' + [char]0x00E7 + 'in.') 'warn'; return }
    $steps = New-StepsFromIds $ids
    if ($Preview) { Start-PlanJob $steps ([string][char]0x00D6 + 'nizleme: sertle' + [char]0x015F + 'tirme') $true $false; return }
    $script:PendingSteps = $steps
    $names = @($ids | ForEach-Object { $c = Get-CatalogItem $_; if ($null -ne $c) { [string]$c.Title } })
    Show-Confirm ('Sertle' + [char]0x015F + 'tirmeyi uygula') ([string]$ids.Count + " ayar uygulanacak:`r`n`r`n" + (Format-NameList $names 10) + ("`r`n`r`nEski de" + [char]0x011F + "erler kaydedilir; Ge" + [char]0x00E7 + "mi" + [char]0x015F + " sayfas" + [char]0x0131 + "ndan geri al" + [char]0x0131 + "nabilir. " + [char]0x00D6 + "nce geri y" + [char]0x00FC + "kleme noktas" + [char]0x0131 + " olu" + [char]0x015F + "turulur.")) 'Uygula' {
        Start-PlanJob $script:PendingSteps ('Sertle' + [char]0x015F + 'tirme uygulan' + [char]0x0131 + 'yor') $false ($script:Settings.RestorePoint -eq $true) { $script:HealthAt = [datetime]::MinValue }
    }
}

# ---------------- hizli islemler ----------------
$script:H_ScQuick = {
    param($s, $e)
    Invoke-Safe {
        $k = [string]$s.Tag.Key
        switch ($k) {
            'DefUpdate' { [void](Start-Async 'Action' 'Job_Action' @{ Key = 'DefUpdate' } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncellendi.') 'good' } else { Show-Toast ('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncellenemedi; internet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + 'n' + [char]0x0131 + ' ve g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ' kontrol edin.') 'warn' } } ('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'ncelleniyor')) }
            'DefScan' { [void](Start-Async 'Action' 'Job_Action' @{ Key = 'DefScan' } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' vir' + [char]0x00FC + 's taramas' + [char]0x0131 + ' tamamland' + [char]0x0131 + '.') 'good'; Show-Notify ('Vir' + [char]0x00FC + 's taramas' + [char]0x0131) ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama tamamland' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Vir' + [char]0x00FC + 's taramas' + [char]0x0131 + ' tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' } } ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' vir' + [char]0x00FC + 's taramas' + [char]0x0131)) }
            'FwOn' { [void](Start-Async 'Action' 'Job_Action' @{ Key = 'FwOn' } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' etkinle' + [char]0x015F + 'tirildi.') 'good' } else { Show-Toast ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' a' + [char]0x00E7 + [char]0x0131 + 'lamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }; $script:HealthAt = [datetime]::MinValue } ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131)) }
            'RpCreate' { [void](Start-Async 'Action' 'Job_Action' @{ Key = 'RpCreate' } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turuldu.') 'good' } else { Show-Toast ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' } } ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131)) }
            'Defender' { Open-Url 'windowsdefender:' }
            'BitLocker' { Start-Process -FilePath 'control.exe' -ArgumentList '/name Microsoft.BitLockerDriveEncryption' | Out-Null }
            'EventVwr' { Start-Process -FilePath 'eventvwr.msc' | Out-Null }
            'HostsOn' { $script:PendingSteps = @(@{ Id = 'Hosts'; Title = ([string][char]0x0130 + 'zleme alan adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' engelle'); Ops = @((FuncOp 'HostsBlock')); Reboot = $false }); Show-Confirm ([string][char]0x0130 + 'zleme engeli') ('hosts dosyas' + [char]0x0131 + 'na bilinen reklam ve izleme alan adlar' + [char]0x0131 + ' (0.0.0.0) eklenir. ' + [char]0x00D6 + 'nceki dosya yedeklenir; Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'nabilir.') 'Uygula' { Start-PlanJob $script:PendingSteps 'hosts engeli' $false $false { if ($script:ScTab -eq 'quick' -and $script:UiState.Page -eq 'security') { Render-ScQuick } } } }
            'HostsOff' { $script:PendingSteps = @(@{ Id = 'Hosts'; Title = ([string][char]0x0130 + 'zleme engelini kald' + [char]0x0131 + 'r'); Ops = @((FuncOp 'HostsUnblock')); Reboot = $false }); Start-PlanJob $script:PendingSteps ('hosts engeli kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { if ($script:ScTab -eq 'quick' -and $script:UiState.Page -eq 'security') { Render-ScQuick } } }
        }
    } ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' i' + [char]0x015F + 'lem')
}

function Render-ScQuick {
    $ui.sc_List.Children.Clear()
    $hs = $false
    try { $hs = ((Get-HostsBlockState).Installed -eq $true) } catch { }
    $items = @(
        @{ Key = 'DefUpdate'; T = ('Vir' + [char]0x00FC + 's tan' + [char]0x0131 + 'mlar' + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00FC + 'ncelle'); D = ('Microsoft Defender imzalar' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x015F + 'imdi indirir.'); B = ('G' + [char]0x00FC + 'ncelle') },
        @{ Key = 'DefScan'; T = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' vir' + [char]0x00FC + 's taramas' + [char]0x0131); D = ('Microsoft Defender h' + [char]0x0131 + 'zl' + [char]0x0131 + ' taramas' + [char]0x0131 + 'n' + [char]0x0131 + ' ba' + [char]0x015F + 'lat' + [char]0x0131 + 'r (birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer).'); B = 'Tara' },
        @{ Key = 'Defender'; T = ('Windows G' + [char]0x00FC + 'venli' + [char]0x011F + 'i' + [char]0x2019 + 'ni a' + [char]0x00E7); D = ('Vir' + [char]0x00FC + 's ve tehdit korumas' + [char]0x0131 + ', hesap korumas' + [char]0x0131 + ', cihaz g' + [char]0x00FC + 'venli' + [char]0x011F + 'i.'); B = ('A' + [char]0x00E7) },
        @{ Key = 'FwOn'; T = ('G' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + 'n' + [char]0x0131 + ' t' + [char]0x00FC + 'm profillerde a' + [char]0x00E7); D = ('Etki alan' + [char]0x0131 + ', ' + [char]0x00F6 + 'zel ve genel a' + [char]0x011F + ' profillerinde Windows G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + [char]0x2019 + 'n' + [char]0x0131 + ' etkinle' + [char]0x015F + 'tirir.'); B = ('A' + [char]0x00E7) },
        @{ Key = 'RpCreate'; T = ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'tur'); D = ('B' + [char]0x00FC + 'y' + [char]0x00FC + 'k bir de' + [char]0x011F + 'i' + [char]0x015F + 'iklikten ' + [char]0x00F6 + 'nce g' + [char]0x00FC + 'venli d' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + ' noktas' + [char]0x0131 + '.'); B = ('Olu' + [char]0x015F + 'tur') },
        @{ Key = 'BitLocker'; T = ('BitLocker disk ' + [char]0x015F + 'ifreleme'); D = ('Diskin ' + [char]0x015F + 'ifreli olup olmad' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n ve y' + [char]0x00F6 + 'netin (Pro/Enterprise).'); B = ('A' + [char]0x00E7) },
        @{ Key = 'EventVwr'; T = ('Olay G' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 'leyici'); D = ('G' + [char]0x00FC + 'venlik ve uygulama olay g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kleri.'); B = ('A' + [char]0x00E7) }
    )
    if ($hs) { $items += @{ Key = 'HostsOff'; T = ([string][char]0x0130 + 'zleme/reklam alan ad' + [char]0x0131 + ' engelini kald' + [char]0x0131 + 'r'); D = ('hosts dosyas' + [char]0x0131 + 'ndaki bu arac' + [char]0x0131 + 'n ekledi' + [char]0x011F + 'i engel listesi ' + [char]0x015F + 'u an A' + [char]0x00C7 + 'IK.'); B = ('Kald' + [char]0x0131 + 'r') } }
    else { $items += @{ Key = 'HostsOn'; T = ([string][char]0x0130 + 'zleme ve reklam alan adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' engelle'); D = ('hosts dosyas' + [char]0x0131 + 'na bilinen reklam/izleme alan adlar' + [char]0x0131 + ' eklenir (taray' + [char]0x0131 + 'c' + [char]0x0131 + 'dan ba' + [char]0x011F + [char]0x0131 + 'ms' + [char]0x0131 + 'z, t' + [char]0x00FC + 'm programlar i' + [char]0x00E7 + 'in).'); B = 'Engelle' } }
    foreach ($i in $items) {
        $row = New-ItemRow @{ Title = $i.T; Detail = $i.D; BrCol = 'BrAccent'; Btn1 = $i.B } @{ Key = $i.Key } $false $false
        $row.FindName('Act').Add_Click($script:H_ScQuick)
        [void]$ui.sc_List.Children.Add($row)
    }
    $ui.sc_Foot.Text = (Tr $(('Defender, G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + ' ve UAC bu ara' + [char]0x00E7 + 'la kapat' + [char]0x0131 + 'lamaz; yaln' + [char]0x0131 + 'zca a' + [char]0x00E7 + [char]0x0131 + 'labilir.')))
}

function Set-ScTab([string]$Tab) {
    $script:ScTab = $Tab
    switch ($Tab) {
        'audit' { Show-OnlyBar 'sc' @('sc_Scan', 'sc_FixAll'); Set-Visible $ui.sc_Card $true; Render-ScAudit; Update-FixButtons }
        'fix' { Show-OnlyBar 'sc' @('sc_Scan', 'sc_FixPick', 'sc_FixNone', 'sc_FixPrev', 'sc_FixRun'); Set-Visible $ui.sc_Card $false; Render-ScFix }
        'harden' {
            Show-OnlyBar 'sc' @('sc_P1', 'sc_P0', 'sc_Preview', 'sc_Apply'); Set-Visible $ui.sc_Card $false
            if ($script:ScItems.Count -eq 0) { $script:ScItems = (Get-CatalogFor 'sec' '' $sync.Profile) }
            Render-ScHarden
        }
        'quick' { Show-OnlyBar 'sc' @(); Set-Visible $ui.sc_Card $false; Render-ScQuick }
    }
}

function Init-Page_security {
    $script:ScItems = (Get-CatalogFor 'sec' '' $sync.Profile)
    foreach ($id in (Get-PresetIds 2 'sec' $sync.Profile)) { $script:ScSel[[string]$id] = $true }
    Register-Tabs 'sc' $script:ScTabs { param($s, $e) Invoke-Safe { Set-ScTab ([string]$s.Tag) } 'Sekme' }
    $ui.sc_Scan.Add_Click({ Invoke-Safe { Start-HealthScan 'Full' $false } 'Denetim' })
    $ui.sc_P1.Add_Click({
        Invoke-Safe {
            $script:ScSel = @{}
            foreach ($id in (Get-PresetIds 2 'sec' $sync.Profile)) { $script:ScSel[[string]$id] = $true }
            Render-ScHarden
        } ('Se' + [char]0x00E7)
    })
    $ui.sc_P0.Add_Click({ Invoke-Safe { $script:ScSel = @{}; Render-ScHarden } 'Temizle' })
    $ui.sc_Preview.Add_Click({ Invoke-Safe { Start-ScApply $true } ([string][char]0x00D6 + 'nizle') })
    $ui.sc_Apply.Add_Click({ Invoke-Safe { Start-ScApply $false } 'Uygula' })
    $ui.sc_FixAll.Add_Click({ Invoke-Safe { Start-FixAll } ('D' + [char]0x00FC + 'zelt') })
    $ui.sc_FixPick.Add_Click({ Invoke-Safe { $script:FxSel = @{}; foreach ($it in (Get-FixItems)) { if ($it.Mode -eq 'Auto') { $script:FxSel[[string]$it.Id] = $true } }; Render-ScFix } ('Se' + [char]0x00E7 + '') })
    $ui.sc_FixNone.Add_Click({ Invoke-Safe { $script:FxSel = @{}; foreach ($it in (Get-FixItems)) { $script:FxSel[[string]$it.Id] = $false }; Render-ScFix } 'Temizle' })
    $ui.sc_FixPrev.Add_Click({ Invoke-Safe { $sel = Get-FxSelectedItems; if ($sel.Count -eq 0) { Show-Toast (('' + [char]0x00D6 + 'nce d' + [char]0x00FC + 'zeltme se' + [char]0x00E7 + 'in.')) 'warn' } else { Invoke-FixRun $sel $true } } (('' + [char]0x00D6 + 'nizle')) })
    $ui.sc_FixRun.Add_Click({ Invoke-Safe { $sel = Get-FxSelectedItems; if ($sel.Count -eq 0) { Show-Toast (('' + [char]0x00D6 + 'nce d' + [char]0x00FC + 'zeltme se' + [char]0x00E7 + 'in.')) 'warn' } else { Start-FixFlow $sel (('Se' + [char]0x00E7 + 'ilen d' + [char]0x00FC + 'zeltmeleri uygula')) } } 'Uygula' })
}

function Select-Sub_security([string]$Sub) {
    if (-not (Select-TabChip 'sc' $Sub)) { Set-ScTab $Sub }
}

function Show-Page_security {
    $t = Get-TabKey 'sc' $script:ScTabs 'audit'
    Set-ScTab $t
    if (($null -eq $script:Health -or $script:HealthAt -eq [datetime]::MinValue) -and $null -ne $sync.Profile) { Start-HealthScan 'Quick' $true }
}

# ==================================================================
#  SAYFA: Guncellemeler  (Windows Update, winget programlari, gecmis)
#  Windows Update bu aracla ASLA kapatilmaz.
# ==================================================================
$script:UpTabs = @('wu', 'winget', 'ctl', 'inst', 'hist')
$script:UpTab = 'wu'
$script:UpData = @{ wu = $null; winget = $null; hist = $null }
$script:UpPending = @()

function Update-UpBanner {
    $p = @($script:UpPending)
    if ($p.Count -gt 0) {
        $ui.up_BannerText.Text = (Tr $((('Yeniden ba' + [char]0x015F + 'latma bekleniyor: ') + ($p -join ', ') + ('. G' + [char]0x00FC + 'ncellemelerin tamamlanmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.'))))
        Set-Visible $ui.up_Banner $true
    } else { Set-Visible $ui.up_Banner $false }
}

function Render-UpWu {
    $ui.up_List.Children.Clear()
    $rows = $script:UpData.wu
    if ($null -eq $rows) { Add-Note $ui.up_List ([string][char]0x201C + 'G' + [char]0x00FC + 'ncellemeleri ara' + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n. Arama 1-3 dakika s' + [char]0x00FC + 'rebilir; internet gerekir.'); $ui.up_Foot.Text = (Tr $('')); return }
    $rows = @($rows)
    if ($rows.Count -eq 0) { Add-Note $ui.up_List ('Bekleyen g' + [char]0x00FC + 'ncelleme yok. Windows g' + [char]0x00FC + 'ncel g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor.') 'good'; $ui.up_Foot.Text = (Tr $('')); return }
    $tot = 0.0
    foreach ($r in $rows) {
        $bits = @()
        if ([string]$r.KB -ne '') { $bits += [string]$r.KB }
        if ([double]$r.Size -gt 0) { $bits += (Format-Size ([double]$r.Size)); $tot += [double]$r.Size }
        if ([string]$r.Cats -ne '') { $bits += [string]$r.Cats }
        if ($r.Reboot -eq $true) { $bits += ('yeniden ba' + [char]0x015F + 'latma gerekir') }
        $tag = [string]$r.Severity
        $br = 'BrInfo'
        if ($r.IsDriver -eq $true) { $tag = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC); $br = 'BrWarn' }
        elseif ($tag -match 'Critical') { $br = 'BrBad'; $tag = 'Kritik' }
        elseif ($tag -match 'Important') { $br = 'BrWarn'; $tag = ([string][char]0x00D6 + 'nemli') }
        elseif ($tag -eq '') { $tag = '' }
        $d = @{ Id = [string]$r.Id; Title = [string]$r.Title; Driver = ($r.IsDriver -eq $true) }
        $row = New-ItemRow @{ Title = [string]$r.Title; Detail = ($bits -join (' ' + [char]0x00B7 + ' ')); Tag = $tag; BrCol = $br } $d $true ($r.IsDriver -ne $true)
        [void]$ui.up_List.Children.Add($row)
    }
    $ui.up_Foot.Text = (Tr $(([string]$rows.Count + (' g' + [char]0x00FC + 'ncelleme ' + [char]0x00B7 + ' toplam yakla' + [char]0x015F + [char]0x0131 + 'k ') + (Format-Size $tot) + ('. S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' g' + [char]0x00FC + 'ncellemeleri varsay' + [char]0x0131 + 'lan olarak i' + [char]0x015F + 'aretli gelmez; ' + [char]0x00FC + 'reticinin sitesinden de alabilirsiniz.'))))
}

function Render-UpWinget {
    if ($script:UpWgPins) { Render-UpPins; return }
    $ui.up_List.Children.Clear()
    $rows = $script:UpData.winget
    if ($null -eq $rows) { Add-Note $ui.up_List ([string][char]0x201C + 'Program g' + [char]0x00FC + 'ncellemelerini ara' + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n. Microsoft' + [char]0x2019 + 'un winget arac' + [char]0x0131 + ' kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'r; internet gerekir.'); $ui.up_Foot.Text = (Tr $('')); return }
    $rows = @($rows)
    if ($rows.Count -eq 0) { Add-Note $ui.up_List ('G' + [char]0x00FC + 'ncellenecek program yok (ya da winget bu bilgisayarda yok).') 'good'; $ui.up_Foot.Text = (Tr $('')); return }
    foreach ($r in $rows) {
        $det = ([string]$r.Version + ('  ' + [char]0x2192 + '  ') + [string]$r.Available + ('  ' + [char]0x00B7 + '  ') + [string]$r.Id)
        $d = @{ Id = [string]$r.Id; Name = [string]$r.Name }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = $det; Tag = [string]$r.Source; BrCol = 'BrAccent' } $d $true $true
        [void]$ui.up_List.Children.Add($row)
    }
    $ui.up_Foot.Text = (Tr $(([string]$rows.Count + (' program' + [char]0x0131 + 'n yeni s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' var. G' + [char]0x00FC + 'ncelleme sessiz yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r; a' + [char]0x00E7 + [char]0x0131 + 'k programlar' + [char]0x0131 + ' ' + [char]0x00F6 + 'nce kapat' + [char]0x0131 + 'n.'))))
}

function Render-UpHist {
    $ui.up_List.Children.Clear()
    $rows = $script:UpData.hist
    if ($null -eq $rows) { Add-Note $ui.up_List 'Okunuyor...'; return }
    $rows = @($rows)
    if ($rows.Count -eq 0) { Add-Note $ui.up_List ('G' + [char]0x00FC + 'ncelleme ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i bo' + [char]0x015F + '.'); return }
    foreach ($r in $rows) {
        $br = 'BrFaint'
        switch ([string]$r.Result) { ('Ba' + [char]0x015F + 'ar' + [char]0x0131 + 'l' + [char]0x0131) { $br = 'BrGood' } ('Uyar' + [char]0x0131 + 'yla ba' + [char]0x015F + 'ar' + [char]0x0131 + 'l' + [char]0x0131) { $br = 'BrWarn' } ('Ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z') { $br = 'BrBad' } }
        $row = New-ItemRow @{ Title = [string]$r.Title; Detail = [string]$r.Date; Tag = [string]$r.Result; BrCol = $br } @{} $false $false
        [void]$ui.up_List.Children.Add($row)
    }
    $ui.up_Foot.Text = (Tr $(('Son ' + [string]$rows.Count + (' kay' + [char]0x0131 + 't.'))))
}

function Start-UpCheck {
    $t = $script:UpTab
    $script:UpLoadTab = $t
    switch ($t) {
        'ctl' { Render-UpCtl }
        'inst' {
            Set-ListNote $ui.up_List ('Kurulu g' + [char]0x00FC + 'ncellemeler okunuyor...')
            [void](Start-Async 'InstUpd' 'Job_InstalledUpdates' @{} {
                param($r)
                if ($null -eq $r) { $script:UpData['inst'] = @() } else { $script:UpData['inst'] = @($r.Rows) }
                if ($script:UpTab -eq 'inst') { Render-UpInst }
            } ('Kurulu g' + [char]0x00FC + 'ncellemeler') $false $true)
        }
        'wu' {
            Set-ListNote $ui.up_List ('Windows Update taran' + [char]0x0131 + 'yor... (1-3 dakika s' + [char]0x00FC + 'rebilir)')
            [void](Start-Async 'WuSearch' 'Job_WuSearch' @{} {
                param($r)
                if ($null -eq $r) { $script:UpData.wu = $null; Set-ListNote $ui.up_List ('Arama ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
                $script:UpData.wu = @($r.Rows)
                $script:UpPending = @($r.PendingReboot)
                Update-UpBanner
                if ($script:UpTab -eq 'wu') { Render-UpWu }
            } ('Windows Update taran' + [char]0x0131 + 'yor') $false $true)
        }
        'winget' {
            Set-ListNote $ui.up_List ('Program g' + [char]0x00FC + 'ncellemeleri denetleniyor...')
            [void](Start-Async 'WgCheck' 'Job_WingetCheck' @{} {
                param($r)
                if ($null -eq $r) { $script:UpData.winget = $null; Set-ListNote $ui.up_List ('Denetim ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
                if ($r.Offline -eq $true) { Set-ListNote $ui.up_List ([string][char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' yok.') 'warn'; return }
                $script:UpData.winget = @($r.Rows)
                if ($script:UpTab -eq 'winget') { Render-UpWinget }
            } ('Program g' + [char]0x00FC + 'ncellemeleri') $false $true)
        }
        'hist' {
            Set-ListNote $ui.up_List ('G' + [char]0x00FC + 'ncelleme ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i okunuyor...')
            [void](Start-Async 'WuHist' 'Job_WuHistory' @{} {
                param($r)
                if ($null -eq $r) { $script:UpData.hist = @(); } else { $script:UpData.hist = @($r.Rows) }
                if ($script:UpTab -eq 'hist') { Render-UpHist }
            } ('G' + [char]0x00FC + 'ncelleme ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i') $false $true)
        }
    }
}

function Start-UpInstall {
    $sel = (Get-CheckedData $ui.up_List)
    if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce g' + [char]0x00FC + 'ncelleme se' + [char]0x00E7 + 'in.') 'warn'; return }
    $ids = @($sel | ForEach-Object { [string]$_.Id })
    $names = @($sel | ForEach-Object { if ($null -ne $_.Title) { [string]$_.Title } else { [string]$_.Name } })
    $script:PendingIds = $ids
    $script:PendingTab = $script:UpTab
    Show-Confirm ('G' + [char]0x00FC + 'ncellemeleri kur') ([string]$ids.Count + (" g" + [char]0x00FC + "ncelleme kurulacak:`r`n`r`n") + (Format-NameList $names 8) + ("`r`n`r`nKurulum s" + [char]0x00FC + "rerken bilgisayar" + [char]0x0131 + " kapatmay" + [char]0x0131 + "n.")) 'Kur' {
        if ($script:PendingTab -eq 'wu') {
            [void](Start-Async 'WuInstall' 'Job_WuInstall' @{ Ids = $script:PendingIds } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) {
                    Show-Toast ([string]$r.Installed + (' g' + [char]0x00FC + 'ncelleme kuruldu.')) 'good'
                    Show-Notify ('G' + [char]0x00FC + 'ncellemeler kuruldu') ([string]$r.Installed + (' g' + [char]0x00FC + 'ncelleme kuruldu.')) 'good'
                    $script:UpData.wu = $null
                    if ($r.Reboot -eq $true) { $script:UpPending = @('Windows Update'); Update-UpBanner; Request-Reboot }
                    if ($script:UpTab -eq 'wu') { Render-UpWu }
                } else { Show-Toast ('Kurulum ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
            } ('G' + [char]0x00FC + 'ncellemeler kuruluyor'))
        } else {
            [void](Start-Async 'WgUpgrade' 'Job_WingetUpgrade' @{ Ids = $script:PendingIds } {
                param($r)
                if ($null -ne $r) { Show-Toast ([string]$r.Ok + ' / ' + [string]$r.Total + (' program g' + [char]0x00FC + 'ncellendi.')) 'good'; Show-Notify ('Programlar g' + [char]0x00FC + 'ncellendi') ([string]$r.Ok + ' / ' + [string]$r.Total) 'good' }
                $script:UpData.winget = $null
                if ($script:UpTab -eq 'winget') { Render-UpWinget }
            } ('Programlar g' + [char]0x00FC + 'ncelleniyor'))
        }
    }
}

function Set-UpTab([string]$Tab) {
    $script:UpTab = $Tab
    Set-UpBar $Tab
    if (($Tab -eq 'hist' -and $null -eq $script:UpData.hist) -or ($Tab -eq 'inst' -and $null -eq $script:UpData['inst'])) { Start-UpCheck }
    else { Render-UpCurrent }
}

function Init-Page_updates {
    Register-Tabs 'up' $script:UpTabs { param($s, $e) Invoke-Safe { Set-UpTab ([string]$s.Tag) } 'Sekme' }
    $ui.up_Check.Add_Click({ Invoke-Safe { Start-UpCheck } 'Denetle' })
    $ui.up_SelAll.Add_Click({ Invoke-Safe { Set-RowChecks $ui.up_List { param($d) $true } } ('Se' + [char]0x00E7) })
    $ui.up_SelNone.Add_Click({ Invoke-Safe { Set-RowChecks $ui.up_List { param($d) $false } } 'Temizle' })
    $ui.up_Install.Add_Click({ Invoke-Safe { Start-UpInstall } 'Kur' })
    $ui.up_Reboot.Add_Click({ Invoke-Safe { Request-Reboot } 'Yeniden' })
    Init-UpFiles
}

function Select-Sub_updates([string]$Sub) {
    if (-not (Select-TabChip 'up' $Sub)) { Set-UpTab $Sub }
}

function Show-Page_updates {
    $p = @()
    try { $p = (Get-PendingReboot) } catch { }
    if ($p.Count -gt 0) { $script:UpPending = $p }
    Update-UpBanner
    $t = Get-TabKey 'up' $script:UpTabs 'wu'
    Set-UpTab $t
}

# ==================================================================
#  SAYFA: Ag Araclari  (genel bakis, DNS, ping/izleme, hiz testi, onarim)
# ==================================================================
$script:NwTabs = @('over', 'dev', 'prot', 'vpn', 'dns', 'ping', 'speed', 'fix')
$script:NwTab = 'over'
$script:NwSnap = $null
$script:NwDns = $null
$script:NwSpeed = $null

function Set-NwTab([string]$Tab) {
    $script:NwTab = $Tab
    Set-Visible $ui.nw_PingBox ($Tab -eq 'ping')
    Set-Visible $ui.nw_DevBox ($Tab -eq 'dev')
    Set-Visible $ui.nw_ProtBox ($Tab -eq 'prot')
    Set-Visible $ui.nw_VpnBox ($Tab -eq 'vpn')
    switch ($Tab) {
        'over' { Show-OnlyBar 'nw' @('nw_Refresh'); Render-NwOver }
        'dev' { Show-OnlyBar 'nw' @('nw_ScanQuick', 'nw_ScanDeep', 'nw_DevTrust', 'nw_DevTrustAll', 'nw_DevName', 'nw_DevBlock', 'nw_DevUnblock', 'nw_DevKick', 'nw_DevPorts'); Render-NwDev }
        'prot' { Show-OnlyBar 'nw' @('nw_ProtScan', 'nw_ProtAll', 'nw_ProtPick', 'nw_PubWifi', 'nw_PubPrev'); Render-NwProt }
        'vpn' { Show-OnlyBar 'nw' @('nw_VpnRefresh', 'nw_VpnWgImport', 'nw_VpnIke', 'nw_KsOn', 'nw_KsOff', 'nw_VpnLeak'); Render-NwVpn }
        'dns' { Show-OnlyBar 'nw' @('nw_DnsBench', 'nw_DnsApply', 'nw_DnsAuto'); Render-NwDns }
        'ping' {
            Show-OnlyBar 'nw' @()
            $ui.nw_List.Children.Clear()
            Add-Note $ui.nw_List ('Bir adres yaz' + [char]0x0131 + 'p ' + [char]0x201C + 'Ping' + [char]0x201D + ' ya da ' + [char]0x201C + 'Yol izle' + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n. ' + [char]0x00C7 + [char]0x0131 + 'kt' + [char]0x0131 + ' soldaki g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte akar.')
            $ui.nw_Foot.Text = (Tr $(''))
        }
        'speed' { Show-OnlyBar 'nw' @('nw_SpeedGo'); Render-NwSpeed }
        'fix' { Show-OnlyBar 'nw' @('nw_FlushDns', 'nw_NetReset'); Render-NwFix }
    }
}

# ---------------- genel bakis ----------------
$script:H_NwKill = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        $script:PendingPid = [int]$d.Pid
        Show-Confirm ('Program' + [char]0x0131 + ' sonland' + [char]0x0131 + 'r') ([string]$d.Name + ' (PID ' + [string]$d.Pid + (") sonland" + [char]0x0131 + "r" + [char]0x0131 + "lacak. Kaydedilmemi" + [char]0x015F + " i" + [char]0x015F + "ler kaybolabilir. Sistem i" + [char]0x015F + "lemleri korunur.")) ('Sonland' + [char]0x0131 + 'r') {
            [void](Start-Async 'Kill' 'Job_Kill' @{ Pid = $script:PendingPid } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ([string][char]0x0130 + [char]0x015F + 'lem sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'good'; Start-NwScan } else { Show-Toast ('Sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (korumal' + [char]0x0131 + ' olabilir).') 'warn' }
            } ([string][char]0x0130 + [char]0x015F + 'lem sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
        } $true
    } ('Sonland' + [char]0x0131 + 'r')
}

function Render-NwOver {
    $ui.nw_List.Children.Clear()
    $s = $script:NwSnap
    if ($null -eq $s) { Set-ListNote $ui.nw_List ('A' + [char]0x011F + ' bilgileri okunuyor...'); Start-NwScan; return }
    Add-HeadRow $ui.nw_List ('Etkin ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'lar')
    $ad = @($s.Adapters)
    if ($ad.Count -eq 0) { Add-Note $ui.nw_List ('Etkin a' + [char]0x011F + ' ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + ' bulunamad' + [char]0x0131 + '.') 'warn' }
    foreach ($a in $ad) {
        $det = ('IP ' + [string]$a.Ip + (' ' + [char]0x00B7 + ' a' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi ') + [string]$a.Gateway + (' ' + [char]0x00B7 + ' MAC ') + [string]$a.Mac)
        $row = New-ItemRow @{ Title = [string]$a.Name; Detail = $det; Tag = [string]$a.Speed; BrCol = 'BrGood' } @{} $false $false
        [void]$ui.nw_List.Children.Add($row)
    }
    Add-KvRow $ui.nw_List ('DNS sunucular' + [char]0x0131) ((@($s.Dns) -join ', '))
    Add-HeadRow $ui.nw_List ([string][char]0x0130 + 'nternete ba' + [char]0x011F + 'lanan programlar')
    $pr = @($s.Procs)
    if ($pr.Count -eq 0) { Add-Note $ui.nw_List ([string][char]0x015E + 'u an d' + [char]0x0131 + [char]0x015F + ' ba' + [char]0x011F + 'lant' + [char]0x0131 + ' yok.') }
    foreach ($p in $pr) {
        $row = New-ItemRow @{ Title = [string]$p.Name; Detail = ('Uzak: ' + (@($p.Remotes) -join ', ')); Tag = ([string]$p.Count + (' ba' + [char]0x011F + 'lant' + [char]0x0131)); BrCol = 'BrBlue' } @{} $false $false
        [void]$ui.nw_List.Children.Add($row)
    }
    Add-HeadRow $ui.nw_List ('D' + [char]0x0131 + [char]0x015F + 'ar' + [char]0x0131 + 'dan eri' + [char]0x015F + 'ilebilen (dinleyen) portlar')
    $lis = @($s.Listen)
    if ($lis.Count -eq 0) { Add-Note $ui.nw_List 'Dinleyen port yok.' 'good' }
    foreach ($l in $lis) {
        $risky = ($script:TopoRisky -contains [int]$l.Port)
        $br = 'BrFaint'; if ($risky) { $br = 'BrBad' }
        $pn = [string]$l.Proc; if ($pn -eq '') { $pn = 'bilinmiyor' }
        $note = ''
        if ($risky) { $note = ('Hassas port: kullanm' + [char]0x0131 + 'yorsan' + [char]0x0131 + 'z bu program' + [char]0x0131 + ' kapat' + [char]0x0131 + 'n veya g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + 'yla s' + [char]0x0131 + 'n' + [char]0x0131 + 'rlay' + [char]0x0131 + 'n.') }
        $b1 = ''; if ([int]$l.Pid -gt 4) { $b1 = ('Program' + [char]0x0131 + ' kapat') }
        $d = @{ Pid = [int]$l.Pid; Name = $pn }
        $row = New-ItemRow @{ Title = ('Port ' + [string]$l.Port + ('  ' + [char]0x2014 + '  ') + $pn); Detail = $note; Tag = [string]$l.Addr; BrCol = $br; Btn1 = $b1 } $d $false $false
        if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_NwKill) }
        [void]$ui.nw_List.Children.Add($row)
    }
    $ui.nw_Foot.Text = (Tr $(('Son okuma: ' + $script:TopoAt.ToString('HH:mm:ss') + ('. 135/139/445 (SMB), 3389 (RDP) gibi portlar internete a' + [char]0x00E7 + [char]0x0131 + 'ksa sald' + [char]0x0131 + 'r' + [char]0x0131 + ' hedefidir.'))))
}

function Start-NwScan {
    [void](Start-Async 'NetScan' 'Job_Net' @{} {
        param($r)
        if ($null -eq $r) { return }
        $script:NwSnap = $r
        $script:TopoSnap = $r
        $script:TopoAt = Get-Date
        if ($script:UiState.Page -eq 'network') {
            if ($script:NwTab -eq 'over') { Render-NwOver } elseif ($script:NwTab -eq 'dns') { Render-NwDns }
        }
    } ('A' + [char]0x011F + ' bilgileri') $false $true)
}

# ---------------- DNS ----------------
$script:H_NwDnsChk = {
    param($s, $e)
    foreach ($row in $ui.nw_List.Children) {
        $c = Get-RowCheck $row
        if ($null -ne $c -and -not [object]::ReferenceEquals($c, $s)) { $c.IsChecked = $false }
    }
}

function Render-NwDns {
    $ui.nw_List.Children.Clear()
    $cur = ''
    if ($null -ne $script:NwSnap) { $cur = (@($script:NwSnap.Dns) -join ', ') }
    if ($cur -ne '') { Add-KvRow $ui.nw_List ([string][char]0x015E + 'u anki DNS') $cur }
    $rows = $script:NwDns
    if ($null -eq $rows) {
        Add-Note $ui.nw_List ([string][char]0x201C + 'DNS h' + [char]0x0131 + 'zlar' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x201D + ' ile Cloudflare, Google, Quad9 ve di' + [char]0x011F + 'erlerinin bu ba' + [char]0x011F + 'lant' + [char]0x0131 + 'da ne kadar h' + [char]0x0131 + 'zl' + [char]0x0131 + ' oldu' + [char]0x011F + 'unu g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n. ' + [char]0x00D6 + 'l' + [char]0x00E7 + [char]0x00FC + 'm 1-2 dakika s' + [char]0x00FC + 'rer.')
        $ui.nw_Foot.Text = (Tr $(('DNS, alan adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' (' + [char]0x00F6 + 'r. google.com) IP adresine ' + [char]0x00E7 + 'evirir. H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bir DNS sayfa a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + 'lar' + [char]0x0131 + 'n' + [char]0x0131 + ' h' + [char]0x0131 + 'zland' + [char]0x0131 + 'r' + [char]0x0131 + 'r; baz' + [char]0x0131 + 'lar' + [char]0x0131 + ' ayr' + [char]0x0131 + 'ca k' + [char]0x00F6 + 't' + [char]0x00FC + ' ama' + [char]0x00E7 + 'l' + [char]0x0131 + ' siteleri engeller.')))
        return
    }
    $best = $null
    foreach ($r in @($rows)) { if ($null -eq $best -and [double]$r.Ms -lt 9000) { $best = $r } }
    $i = 0
    foreach ($r in @($rows)) {
        $ms = [double]$r.Ms
        $tag = '--'; $br = 'BrBad'
        if ($ms -lt 9000) {
            $tag = ($ms.ToString('0.0') + ' ms')
            if ($ms -le 30) { $br = 'BrGood' } elseif ($ms -le 80) { $br = 'BrAccent' } else { $br = 'BrWarn' }
        }
        $det = ([string]$r.Ip + (' ' + [char]0x00B7 + ' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z ') + [string]$r.Fail)
        if ($i -eq 0 -and $ms -lt 9000) { $det += ('  ' + [char]0x00B7 + '  en h' + [char]0x0131 + 'zl' + [char]0x0131 + 's' + [char]0x0131) }
        $d = @{ Ips = @($r.Ips); Name = [string]$r.Name }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = $det; Tag = $tag; BrCol = $br } $d $true ($i -eq 0 -and $ms -lt 9000)
        $row.FindName('Chk').Add_Click($script:H_NwDnsChk)
        [void]$ui.nw_List.Children.Add($row)
        $i++
    }
    $ui.nw_Foot.Text = (Tr $(([string][char]0x0130 + [char]0x015F + 'aretli DNS, etkin t' + [char]0x00FC + 'm a' + [char]0x011F + ' ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'lar' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r; eski ayar kaydedilir ve geri al' + [char]0x0131 + 'nabilir.')))
}

function Start-NwDnsApply([bool]$Auto) {
    if ($null -eq $script:NwSnap -or @($script:NwSnap.Adapters).Count -eq 0) {
        Show-Toast ('Etkin a' + [char]0x011F + ' ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + ' bulunamad' + [char]0x0131 + '; ' + [char]0x00F6 + 'nce Genel bak' + [char]0x0131 + [char]0x015F + ' sekmesinden a' + [char]0x011F + [char]0x0131 + ' okuyun.') 'warn'
        Select-TabChip 'nw' 'over' | Out-Null
        return
    }
    $ad = @($script:NwSnap.Adapters)
    $servers = 'Auto'
    $name = 'Otomatik (DHCP)'
    if (-not $Auto) {
        $sel = (Get-CheckedData $ui.nw_List)
        if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce bir DNS se' + [char]0x00E7 + 'in.') 'warn'; return }
        $servers = @($sel[0].Ips)
        $name = [string]$sel[0].Name + ' (' + ($servers -join ', ') + ')'
    }
    $script:PendingSteps = New-DnsSteps $servers $ad
    Show-Confirm ('DNS de' + [char]0x011F + 'i' + [char]0x015F + 'tir') ($name + " DNS olarak ayarlanacak (" + [string]$ad.Count + (' ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + '). Geri al' + [char]0x0131 + 'nabilir.')) 'Uygula' {
        Start-PlanJob $script:PendingSteps ('DNS de' + [char]0x011F + 'i' + [char]0x015F + 'tiriliyor') $false $false { $script:NwSnap = $null; Start-NwScan }
    }
}

# ---------------- hiz testi ----------------
function Render-NwSpeed {
    $ui.nw_List.Children.Clear()
    $r = $script:NwSpeed
    if ($null -eq $r) {
        Add-Note $ui.nw_List ('H' + [char]0x0131 + 'z testi yaln' + [char]0x0131 + 'zca speed.cloudflare.com ile konu' + [char]0x015F + 'ur; yakla' + [char]0x015F + [char]0x0131 + 'k 33 MB veri kullan' + [char]0x0131 + 'r, ki' + [char]0x015F + 'isel veri g' + [char]0x00F6 + 'ndermez.')
        $ui.nw_Foot.Text = (Tr $(''))
        return
    }
    $row = New-ItemRow @{ Title = ([string][char]0x0130 + 'ndirme h' + [char]0x0131 + 'z' + [char]0x0131); Detail = ''; Tag = (([double]$r.Down).ToString('0.0') + ' Mb/sn'); BrCol = 'BrAccent' } @{} $false $false
    [void]$ui.nw_List.Children.Add($row)
    $row = New-ItemRow @{ Title = ('Y' + [char]0x00FC + 'kleme h' + [char]0x0131 + 'z' + [char]0x0131); Detail = ''; Tag = (([double]$r.Up).ToString('0.0') + ' Mb/sn'); BrCol = 'BrAccent2' } @{} $false $false
    [void]$ui.nw_List.Children.Add($row)
    $row = New-ItemRow @{ Title = 'Gecikme'; Detail = ''; Tag = ([string][int][double]$r.Latency + ' ms'); BrCol = 'BrBlue' } @{} $false $false
    [void]$ui.nw_List.Children.Add($row)
    $ui.nw_Foot.Text = (Tr $((([string][char]0x00D6 + 'l' + [char]0x00E7 + [char]0x00FC + 'm: ') + $script:NwSpeedAt.ToString('HH:mm:ss') + ('. Sonu' + [char]0x00E7 + ', bilgisayar' + [char]0x0131 + 'n' + [char]0x0131 + 'z ile Cloudflare aras' + [char]0x0131 + 'ndad' + [char]0x0131 + 'r; Wi-Fi sinyali ve di' + [char]0x011F + 'er cihazlar etkiler.'))))
}

# ---------------- onarim ----------------
$script:H_NwFixRow = {
    param($s, $e)
    Invoke-Safe {
        switch ([string]$s.Tag.Key) {
            'ncpa' { Start-Process -FilePath 'ncpa.cpl' | Out-Null }
            'wf' { Start-Process -FilePath 'wf.msc' | Out-Null }
            'hosts' { try { Start-Process -FilePath 'notepad.exe' -ArgumentList ('"' + [string](Get-HostsPath) + '"') | Out-Null } catch { Show-Toast ('hosts dosyas' + [char]0x0131 + ' a' + [char]0x00E7 + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'warn' } }
            'settings' { Open-Url 'ms-settings:network' }
        }
    } ('Onar' + [char]0x0131 + 'm')
}

function Render-NwFix {
    $ui.nw_List.Children.Clear()
    $items = @(
        @{ K = 'ncpa'; T = ('A' + [char]0x011F + ' ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar' + [char]0x0131 + ' penceresi'); D = ('Ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'lar' + [char]0x0131 + ' etkinle' + [char]0x015F + 'tirin/devre d' + [char]0x0131 + [char]0x015F + [char]0x0131 + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'n, IP ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + ' elle girin.'); B = ('A' + [char]0x00E7) },
        @{ K = 'settings'; T = ('Windows a' + [char]0x011F + ' ayarlar' + [char]0x0131); D = ('Wi-Fi, VPN, vekil sunucu, veri kullan' + [char]0x0131 + 'm' + [char]0x0131 + '.'); B = ('A' + [char]0x00E7) },
        @{ K = 'wf'; T = ('Geli' + [char]0x015F + 'mi' + [char]0x015F + ' G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131); D = ('Gelen/giden kurallar' + [char]0x0131 + ' inceleyin.'); B = ('A' + [char]0x00E7) },
        @{ K = 'hosts'; T = ('hosts dosyas' + [char]0x0131 + 'n' + [char]0x0131 + ' incele'); D = ('Zararl' + [char]0x0131 + 'lar' + [char]0x0131 + 'n s' + [char]0x0131 + 'k de' + [char]0x011F + 'i' + [char]0x015F + 'tirdi' + [char]0x011F + 'i dosya; tan' + [char]0x0131 + 'mad' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + 'z sat' + [char]0x0131 + 'rlara dikkat edin.'); B = ('A' + [char]0x00E7) }
    )
    foreach ($i in $items) {
        $row = New-ItemRow @{ Title = $i.T; Detail = $i.D; BrCol = 'BrAccent'; Btn1 = $i.B } @{ Key = $i.K } $false $false
        $row.FindName('Act').Add_Click($script:H_NwFixRow)
        [void]$ui.nw_List.Children.Add($row)
    }
    Add-Note $ui.nw_List ([string][char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' sorunluysa ' + [char]0x00F6 + 'nce ' + [char]0x201C + 'DNS ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'ini temizle' + [char]0x201D + 'yi, olmazsa ' + [char]0x201C + 'A' + [char]0x011F + ' y' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + 'n' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rla' + [char]0x201D + 'y' + [char]0x0131 + ' deneyin (s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'latma gerekir).') 'warn'
    $ui.nw_Foot.Text = (Tr $(''))
}

function Init-Page_network {
    Register-Tabs 'nw' $script:NwTabs { param($s, $e) Invoke-Safe { Set-NwTab ([string]$s.Tag) } 'Sekme' }
    $ui.nw_Refresh.Add_Click({ Invoke-Safe { Start-NwScan } 'Yenile' })
    Init-LanUi
    Init-VpnUi
    $ui.nw_DnsBench.Add_Click({
        Invoke-Safe {
            Set-ListNote $ui.nw_List ('DNS sunucular' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x00FC + 'l' + [char]0x00FC + 'yor...')
            [void](Start-Async 'DnsBench' 'Job_DnsBench' @{} {
                param($r)
                if ($null -eq $r) { Set-ListNote $ui.nw_List ([string][char]0x00D6 + 'l' + [char]0x00E7 + [char]0x00FC + 'm tamamlanamad' + [char]0x0131 + '.') 'bad'; return }
                $script:NwDns = @($r.Rows)
                if ($script:NwTab -eq 'dns') { Render-NwDns }
            } ('DNS h' + [char]0x0131 + 'z' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x00FC + 'l' + [char]0x00FC + 'yor'))
        } 'DNS'
    })
    $ui.nw_DnsApply.Add_Click({ Invoke-Safe { Start-NwDnsApply $false } 'DNS' })
    $ui.nw_DnsAuto.Add_Click({ Invoke-Safe { Start-NwDnsApply $true } 'DNS' })
    $ui.nw_PingGo.Add_Click({ Invoke-Safe { [void](Start-Async 'Ping' 'Job_Ping' @{ Host = [string]$ui.nw_Host.Text; Trace = $false } { param($r) } 'Ping') } 'Ping' })
    $ui.nw_TraceGo.Add_Click({ Invoke-Safe { [void](Start-Async 'Ping' 'Job_Ping' @{ Host = [string]$ui.nw_Host.Text; Trace = $true } { param($r) } 'Ping ve yol izleme') } 'Yol' })
    $ui.nw_SpeedGo.Add_Click({
        Invoke-Safe {
            [void](Start-Async 'Speed' 'Job_SpeedTest' @{} {
                param($r)
                if ($null -eq $r) { Show-Toast ('H' + [char]0x0131 + 'z testi tamamlanamad' + [char]0x0131 + '.') 'warn'; return }
                $script:NwSpeed = $r
                $script:NwSpeedAt = Get-Date
                if ($script:NwTab -eq 'speed') { Render-NwSpeed }
            } ([string][char]0x0130 + 'nternet h' + [char]0x0131 + 'z testi'))
        } ('H' + [char]0x0131 + 'z')
    })
    $ui.nw_FlushDns.Add_Click({ Invoke-Safe { Start-PlanJob @(@{ Id = 'FlushDns'; Title = ('DNS ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'ini temizle'); Ops = @((FuncOp 'FlushDns')); Reboot = $false }) ('DNS ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i temizleniyor') $false $false } 'Temizle' })
    $ui.nw_NetReset.Add_Click({
        Invoke-Safe {
            Show-Confirm ('A' + [char]0x011F + ' y' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + 'n' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rla') ('Winsock, TCP/IP ve DNS ayarlar' + [char]0x0131 + ' fabrika de' + [char]0x011F + 'erine d' + [char]0x00F6 + 'ner. Kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' Wi-Fi a' + [char]0x011F + 'lar' + [char]0x0131 + ' silinmez ama VPN/vekil ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + 'z etkilenebilir. ' + [char]0x0130 + [char]0x015F + 'lem sonunda yeniden ba' + [char]0x015F + 'latma gerekir.') ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rla') {
                [void](Start-Async 'NetReset' 'Job_NetReset' @{} { param($r) if ($null -ne $r -and $r.Reboot -eq $true) { Request-Reboot } } ('A' + [char]0x011F + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor'))
            } $true
        } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rla')
    })
}

function Select-Sub_network([string]$Sub) {
    if (-not (Select-TabChip 'nw' $Sub)) { Set-NwTab $Sub }
}

function Show-Page_network {
    $t = Get-TabKey 'nw' $script:NwTabs 'over'
    Set-NwTab $t
}

# ==================================================================
#  SAYFA: Yedek ve Kurtarma  (dosya yedegi, Geri Donusum Kutusu, onceki surumler, geri yukleme noktalari, silinmis dosya kurtarma)
# ==================================================================
$script:BkTabs = @('files', 'recycle', 'shadow', 'points', 'recover', 'bl', 'kit')
$script:BkPhoto = $null
$script:BkKit = $null
$script:BkTab = 'files'
$script:BkRecycle = $null
$script:BkShadow = $null

# ---------------- dosya yedegi ----------------
$script:H_BkRemoveSrc = {
    param($s, $e)
    Invoke-Safe {
        $p = [string]$s.Tag.Path
        $script:Settings.BackupSources = @(@($script:Settings.BackupSources) | Where-Object { [string]$_ -ne $p })
        Save-Settings $script:Settings
        Render-BkFiles
    } ('Kald' + [char]0x0131 + 'r')
}

function Add-BkSource {
    $f = Select-Folder ('Yedeklenecek klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in')
    if ($f -eq '') { return }
    $cur = @($script:Settings.BackupSources)
    if ($cur -contains $f) { Show-Toast ('Bu klas' + [char]0x00F6 + 'r zaten listede.') 'info'; return }
    $script:Settings.BackupSources = @($cur + @($f))
    Save-Settings $script:Settings
    Render-BkFiles
}

function Set-BkDest {
    $f = Select-Folder ('Yedeklerin yaz' + [char]0x0131 + 'laca' + [char]0x011F + [char]0x0131 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (harici disk ' + [char]0x00F6 + 'nerilir)')
    if ($f -eq '') { return }
    $sysd = [string]$env:SystemDrive
    if ($f.StartsWith($sysd, [StringComparison]::OrdinalIgnoreCase)) {
        Show-Toast ('Uyar' + [char]0x0131 + ': Hedef Windows' + [char]0x2019 + 'un kurulu oldu' + [char]0x011F + 'u disk. Disk bozulursa yedek de gider; harici disk ' + [char]0x00F6 + 'nerilir.') 'warn'
    }
    $script:Settings.BackupDest = $f
    Save-Settings $script:Settings
    Render-BkFiles
}

function Start-BkRestore {
    $src = Select-Folder ('Geri y' + [char]0x00FC + 'klenecek yedek klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (' + [char]0x00F6 + 'r. Yedek\BilgisayarAd' + [char]0x0131 + '\Belgeler)')
    if ($src -eq '') { return }
    $dst = Select-Folder ('Dosyalar' + [char]0x0131 + 'n geri y' + [char]0x00FC + 'klenece' + [char]0x011F + 'i hedef klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in')
    if ($dst -eq '') { return }
    $script:PendingRestore = @{ Source = $src; Target = $dst }
    Show-Confirm ('Yedekten geri y' + [char]0x00FC + 'kle') ($src + ("`r`n  " + [char]0x2192 + "  ") + $dst + ("`r`n`r`nDosyalar hedefe kopyalan" + [char]0x0131 + "r; hedefte ayn" + [char]0x0131 + " adl" + [char]0x0131 + " daha yeni dosya varsa " + [char]0x00FC + "zerine yaz" + [char]0x0131 + "lmaz.")) ('Geri y' + [char]0x00FC + 'kle') {
        [void](Start-Async 'Restore' 'Job_Restore' $script:PendingRestore {
            param($r)
            if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Geri y' + [char]0x00FC + 'kleme tamamland' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Geri y' + [char]0x00FC + 'kleme tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
        } ('Yedekten geri y' + [char]0x00FC + 'kleniyor'))
    }
}

# ---------------- Geri Donusum Kutusu ----------------
function Render-BkRecycle {
    $ui.bk_List.Children.Clear()
    $rows = $script:BkRecycle
    if ($null -eq $rows) { Set-ListNote $ui.bk_List 'Okunuyor...'; Load-BkRecycle; return }
    $rows = @($rows)
    if ($rows.Count -eq 0) { Add-Note $ui.bk_List ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu bo' + [char]0x015F + '.'); $ui.bk_Foot.Text = (Tr $('')); return }
    $tot = 0.0
    foreach ($r in $rows) {
        $tot += [double]$r.Size
        $det = ([string]$r.Orig + (' ' + [char]0x00B7 + ' silinme: ') + [string]$r.Deleted)
        $d = @{ Path = [string]$r.Path; Name = [string]$r.Name }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = $det; Tag = (Format-Size ([double]$r.Size)); BrCol = 'BrAccent' } $d $true $false
        [void]$ui.bk_List.Children.Add($row)
    }
    $ui.bk_Foot.Text = (Tr $(([string]$rows.Count + (' ' + [char]0x00F6 + [char]0x011F + 'e ' + [char]0x00B7 + ' ') + (Format-Size $tot) + ('. ' + [char]0x0130 + [char]0x015F + 'aretleyip ' + [char]0x201C + 'Se' + [char]0x00E7 + 'ilenleri geri y' + [char]0x00FC + 'kle' + [char]0x201D + ' ile as' + [char]0x0131 + 'l yerlerine d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'n.'))))
}

function Load-BkRecycle {
    [void](Start-Async 'RbList' 'Job_RecycleList' @{} {
        param($r)
        $script:BkRecycle = @(Get-ResultRows $r)
        if ($script:BkTab -eq 'recycle') { Render-BkRecycle }
    } ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu okunuyor') $false $true)
}

# ---------------- onceki surumler + geri yukleme noktalari ----------------
function Load-BkShadow {
    [void](Start-Async 'ShList' 'Job_ShadowList' @{} {
        param($r)
        if ($null -eq $r) { $script:BkShadow = @{ Shadows = @(); RestorePoints = @(); Trim = '' } } else { $script:BkShadow = $r }
        if ($script:BkTab -eq 'shadow') { Render-BkShadow }
        if ($script:BkTab -eq 'points') { Render-BkPoints }
        if ($script:BkTab -eq 'recover') { Render-BkRecover }
    } ([string][char]0x00D6 + 'nceki s' + [char]0x00FC + 'r' + [char]0x00FC + 'mler okunuyor') $false $true)
}

$script:H_BkMount = {
    param($s, $e)
    Invoke-Safe {
        $dev = [string]$s.Tag.Device
        try {
            $link = Mount-ShadowCopy $dev
            Show-Toast ([string][char]0x00D6 + 'nceki s' + [char]0x00FC + 'r' + [char]0x00FC + 'm ba' + [char]0x011F + 'land' + [char]0x0131 + '. A' + [char]0x00E7 + [char]0x0131 + 'lan klas' + [char]0x00F6 + 'rden dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' kopyalay' + [char]0x0131 + 'n; uygulama kapan' + [char]0x0131 + 'rken ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') 'good'
            Open-Folder $link
        } catch { Show-Toast (('Ba' + [char]0x011F + 'lanamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'bad' }
    } ('Ba' + [char]0x011F + 'la')
}

function Render-BkShadow {
    $ui.bk_List.Children.Clear()
    $r = $script:BkShadow
    if ($null -eq $r) { Set-ListNote $ui.bk_List 'Okunuyor...'; Load-BkShadow; return }
    $rows = @($r.Shadows)
    if ($rows.Count -eq 0) {
        Add-Note $ui.bk_List ('Hi' + [char]0x00E7 + ' ' + [char]0x00F6 + 'nceki s' + [char]0x00FC + 'r' + [char]0x00FC + 'm (g' + [char]0x00F6 + 'lge kopya) yok. Sistem Korumas' + [char]0x0131 + ' kapal' + [char]0x0131 + ' olabilir; a' + [char]0x00E7 + 'arsan' + [char]0x0131 + 'z Windows d' + [char]0x00FC + 'zenli aral' + [char]0x0131 + 'klarla dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n ' + [char]0x00F6 + 'nceki h' + [char]0x00E2 + 'llerini saklar.') 'warn'
        $row = New-ItemRow @{ Title = ('Sistem Korumas' + [char]0x0131 + ' ayarlar' + [char]0x0131); Detail = ('C: s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' i' + [char]0x00E7 + 'in korumay' + [char]0x0131 + ' a' + [char]0x00E7 + [char]0x0131 + 'n ve disk alan' + [char]0x0131 + ' ay' + [char]0x0131 + 'r' + [char]0x0131 + 'n.'); BrCol = 'BrAccent'; Btn1 = ('A' + [char]0x00E7) } @{} $false $false
        $row.FindName('Act').Add_Click({ Invoke-Safe { Start-Process -FilePath 'SystemPropertiesProtection.exe' | Out-Null } 'Koruma' })
        [void]$ui.bk_List.Children.Add($row)
        $ui.bk_Foot.Text = (Tr $(''))
        return
    }
    foreach ($x in $rows) {
        $row = New-ItemRow @{ Title = (([string][char]0x00D6 + 'nceki s' + [char]0x00FC + 'r' + [char]0x00FC + 'm: ') + [string]$x.Date); Detail = ([string]$x.Volume); BrCol = 'BrAccent2'; Btn1 = ('A' + [char]0x00E7 + ' ve g' + [char]0x00F6 + 'zat') } @{ Device = [string]$x.Device } $false $false
        $row.FindName('Act').Add_Click($script:H_BkMount)
        [void]$ui.bk_List.Children.Add($row)
    }
    $ui.bk_Foot.Text = (Tr $(('Bir ' + [char]0x00F6 + 'nceki s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' ba' + [char]0x011F + 'lay' + [char]0x0131 + 'p i' + [char]0x00E7 + 'inden silinen ya da de' + [char]0x011F + 'i' + [char]0x015F + 'tirilen dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' kopyalayabilirsiniz (salt okunur).')))
}

function Render-BkPoints {
    $ui.bk_List.Children.Clear()
    $r = $script:BkShadow
    if ($null -eq $r) { Set-ListNote $ui.bk_List 'Okunuyor...'; Load-BkShadow; return }
    $rows = @($r.RestorePoints)
    if ($rows.Count -eq 0) { Add-Note $ui.bk_List ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' yok. ' + [char]0x201C + 'Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'tur' + [char]0x201D + ' ile ilkini olu' + [char]0x015F + 'turun.') 'warn' }
    foreach ($x in @($rows | Sort-Object { [int]$_.Seq } -Descending)) {
        $row = New-ItemRow @{ Title = [string]$x.Desc; Detail = ('#' + [string]$x.Seq); Tag = [string]$x.Date; BrCol = 'BrGood' } @{} $false $false
        [void]$ui.bk_List.Children.Add($row)
    }
    $ui.bk_Foot.Text = (Tr $(('Bir noktaya d' + [char]0x00F6 + 'nmek i' + [char]0x00E7 + 'in ' + [char]0x201C + 'Sistem Geri Y' + [char]0x00FC + 'kleme' + [char]0x2019 + 'yi a' + [char]0x00E7 + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesini kullan' + [char]0x0131 + 'n. Ki' + [char]0x015F + 'isel dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z etkilenmez; yaln' + [char]0x0131 + 'zca sistem ayarlar' + [char]0x0131 + ' ve programlar geri d' + [char]0x00F6 + 'ner.')))
}

function Render-BkRecover {
    $ui.bk_List.Children.Clear()
    if ($null -eq $script:BkShadow) { Load-BkShadow }
    $trim = ''
    if ($null -ne $script:BkShadow) { $trim = [string]$script:BkShadow.Trim }
    $pr = ''
    $prKnown = ($null -ne $script:BkPhoto)
    if ($prKnown) { $pr = [string]$script:BkPhoto } else { Load-BkPhoto }
    if (-not $prKnown) { Add-KvRow $ui.bk_List 'PhotoRec' ('Aran' + [char]0x0131 + 'yor...') }
    elseif ($pr -ne '') { Add-KvRow $ui.bk_List 'PhotoRec' ('Bulundu: ' + $pr) }
    else { Add-KvRow $ui.bk_List 'PhotoRec' ('Kurulu de' + [char]0x011F + 'il. ' + [char]0x201C + 'PhotoRec' + [char]0x2019 + 'i kur (winget)' + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesiyle indirin (a' + [char]0x00E7 + [char]0x0131 + 'k kaynak, ' + [char]0x00FC + 'cretsiz).') }
    if ($trim -eq 'On') { Add-Note $ui.bk_List ('Uyar' + [char]0x0131 + ': Bu bilgisayarda SSD TRIM a' + [char]0x00E7 + [char]0x0131 + 'k. SSD' + [char]0x2019 + 'lerde silinen dosyalar ' + [char]0x00E7 + 'o' + [char]0x011F + 'u zaman k' + [char]0x0131 + 'sa s' + [char]0x00FC + 'rede kal' + [char]0x0131 + 'c' + [char]0x0131 + ' olarak yok olur; kurtarma ' + [char]0x015F + 'ans' + [char]0x0131 + ' d' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'kt' + [char]0x00FC + 'r.') 'warn' }
    Add-HeadRow $ui.bk_List ('Silinen dosyay' + [char]0x0131 + ' kurtarmak i' + [char]0x00E7 + 'in')
    $tips = @(
        ('1. ' + [char]0x00D6 + 'nce Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm Kutusu sekmesine bak' + [char]0x0131 + 'n; ' + [char]0x00E7 + 'o' + [char]0x011F + 'u silinen dosya oradad' + [char]0x0131 + 'r.'),
        ('2. Sonra ' + [char]0x00D6 + 'nceki s' + [char]0x00FC + 'r' + [char]0x00FC + 'mler sekmesine bak' + [char]0x0131 + 'n; Windows' + [char]0x2019 + 'un saklad' + [char]0x0131 + [char]0x011F + [char]0x0131 + ' eski h' + [char]0x00E2 + 'l olabilir.'),
        ('3. Hi' + [char]0x00E7 + 'biri yoksa PhotoRec ile diski taray' + [char]0x0131 + 'n: silinen dosyan' + [char]0x0131 + 'n bulundu' + [char]0x011F + 'u diske YEN' + [char]0x0130 + ' DOSYA YAZMAYIN, program kurmay' + [char]0x0131 + 'n.'),
        ('4. Kurtar' + [char]0x0131 + 'lan dosyalar' + [char]0x0131 + ' MUTLAKA ba' + [char]0x015F + 'ka bir diske (harici disk) kaydedin.'),
        ('5. PhotoRec dosya adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' kurtaramaz; dosyalar t' + [char]0x00FC + 'rlerine g' + [char]0x00F6 + 're numaral' + [char]0x0131 + ' klas' + [char]0x00F6 + 'rlere yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r.')
    )
    foreach ($t in $tips) { Add-Note $ui.bk_List $t }
    $ui.bk_Foot.Text = (Tr $(('PhotoRec yaln' + [char]0x0131 + 'zca okur; taranan diskte de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yapmaz. Uygulama kendisi dosya silmez.')))
}


# ---------------- Arayuz: dosyalar ve guncellemeler ----------------
# ==================================================================
#  ARAYUZ (dosyalar ve guncellemeler)
#   Temizlik   : "Buyuk dosyalar" ve "Kopya dosyalar" sekmeleri (Geri Donusum Kutusu'na gonderme)
#   Guncelleme : "Denetim" (duraklat / ertele / suruculer) ve "Kurulu guncellemeler" (kaldir), winget sabitleme
#   Yedek      : "BitLocker" sekmesi (kurtarma anahtari), sifreli ve surumlu yedek (restic)
#   Ilk acilis : "Bu bilgisayari nasil kullaniyorsun?" sorusu, Ayarlar > Kullanim turu
#  Cekirdek isleri "Cekirdek ekleri (2)" bolumundedir; burada yalnizca ekran vardir.
# ==================================================================

# ------------------------------------------------------------------
#  Temizlik: buyuk ve kopya dosyalar
# ------------------------------------------------------------------
$script:ClFRoot = ''
$script:ClBig = $null
$script:ClDup = $null
$script:ClDupSeen = @{}

function Get-ClFRoot {
    if ($script:ClFRoot -ne '') { return $script:ClFRoot }
    $r = [string]$env:USERPROFILE
    if ($r -eq '') { $r = [string]$env:SystemDrive + '\' }
    return $r
}

# Kopya gruplarinda TUM kopyalari isaretlenmis olanlar (her grupta en az biri kalmali).
# Checked: isaretli satirlarin verisi (Group alani), GroupSizes: grup -> o gruptaki dosya sayisi
function Get-DupFullGroups($Checked, $GroupSizes) {
    $cnt = @{}
    foreach ($x in @($Checked)) {
        $k = [string]$x.Group
        if ($cnt.ContainsKey($k)) { $cnt[$k] = [int]$cnt[$k] + 1 } else { $cnt[$k] = 1 }
    }
    $bad = New-Object System.Collections.ArrayList
    foreach ($k in @($cnt.Keys)) {
        if ($GroupSizes.ContainsKey($k) -and [int]$cnt[$k] -ge [int]$GroupSizes[$k]) { [void]$bad.Add([string]$k) }
    }
    return $bad.ToArray()
}

$script:H_ClFOpen = { param($s, $e) Invoke-Safe { Open-Folder ([string]$s.Tag.Dir) } ('Klas' + [char]0x00F6 + 'r') }

function Render-ClBig {
    $ui.cl_List.Children.Clear()
    $s = $script:ClBig
    if ($null -eq $s) {
        $ui.cl_Total.Text = (Tr $((('Klas' + [char]0x00F6 + 'r: ') + (Get-ClFRoot))))
        Add-Note $ui.cl_List ('' + [char]0x201C + 'Tara' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n. Se' + [char]0x00E7 + 'ili klas' + [char]0x00F6 + 'rde (varsay' + [char]0x0131 + 'lan: kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'z) 50 MB ' + [char]0x00FC + 'zerindeki en b' + [char]0x00FC + 'y' + [char]0x00FC + 'k 100 dosya listelenir. Tarama hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silmez. Ba' + [char]0x015F + 'ka bir klas' + [char]0x00F6 + 'r i' + [char]0x00E7 + 'in ' + [char]0x201C + 'Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + '...' + [char]0x201D + ' kullan' + [char]0x0131 + 'n.')
        $ui.cl_Foot.Text = (Tr $(('Sistem klas' + [char]0x00F6 + 'rleri (Windows, Program Files) taranmaz ve silinemez.')))
        return
    }
    $rows = @($s.Rows | Where-Object { Test-Path -LiteralPath ([string]$_.Path) -PathType Leaf })
    $total = 0.0
    foreach ($r in $rows) { $total += [double]$r.Size }
    $ui.cl_Total.Text = (Tr $(([string]$s.Root + ('   ' + [char]0x00B7 + '   ') + [string]$rows.Count + (' dosya   ' + [char]0x00B7 + '   ') + (Format-Size $total))))
    if ($rows.Count -eq 0) {
        Add-Note $ui.cl_List ('Bu klas' + [char]0x00F6 + 'rde 50 MB ' + [char]0x00FC + 'zerinde dosya yok.') 'good'
        $ui.cl_Foot.Text = (Tr $(''))
        return
    }
    foreach ($r in $rows) {
        $d = @{ Path = [string]$r.Path; Dir = [string]$r.Dir; Name = [string]$r.Name; Size = [double]$r.Size }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = ([string]$r.Dir + ('   ' + [char]0x00B7 + '   ') + [string]$r.Date); Tag = (Format-Size ([double]$r.Size)); BrCol = 'BrAccent2'; Btn1 = ('Klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' a' + [char]0x00E7 + '') } $d $true $false
        $row.FindName('Act').Add_Click($script:H_ClFOpen)
        [void]$ui.cl_List.Children.Add($row)
    }
    $ui.cl_Foot.Text = (Tr $(('' + [char]0x0130 + '' + [char]0x015F + 'aretledi' + [char]0x011F + 'iniz dosyalar kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silinmez: Windows' + [char]0x2019 + 'un Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na g' + [char]0x00F6 + 'nderilir, oradan geri al' + [char]0x0131 + 'nabilir. Hangi dosyan' + [char]0x0131 + 'n ne oldu' + [char]0x011F + 'unu bilmiyorsan' + [char]0x0131 + 'z dokunmay' + [char]0x0131 + 'n.')))
}

function Render-ClDup {
    $ui.cl_List.Children.Clear()
    $s = $script:ClDup
    if ($null -eq $s) {
        $ui.cl_Total.Text = (Tr $((('Klas' + [char]0x00F6 + 'r: ') + (Get-ClFRoot))))
        Add-Note $ui.cl_List ('' + [char]0x201C + 'Tara' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n. 5 MB ' + [char]0x00FC + 'zerindeki dosyalar ' + [char]0x00F6 + 'nce boyutuna, sonra i' + [char]0x00E7 + 'eri' + [char]0x011F + 'ine g' + [char]0x00F6 + 're kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r; ger' + [char]0x00E7 + 'ekten ayn' + [char]0x0131 + ' olanlar gruplan' + [char]0x0131 + 'r. Tarama hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silmez ve b' + [char]0x00FC + 'y' + [char]0x00FC + 'k klas' + [char]0x00F6 + 'rlerde birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rebilir.')
        $ui.cl_Foot.Text = (Tr $(('Kopyalardan hangisinin kalaca' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' siz se' + [char]0x00E7 + 'ersiniz; her grupta en az bir dosya kalmak zorundad' + [char]0x0131 + 'r.')))
        return
    }
    $gi = 0
    $waste = 0.0
    $shown = 0
    foreach ($g in @($s.Rows)) {
        $files = @(@($g.Files) | Where-Object { Test-Path -LiteralPath ([string]$_) -PathType Leaf })
        if ($files.Count -lt 2) { continue }
        $gi++
        $w = [double]$g.Size * ($files.Count - 1)
        $waste += $w
        Add-HeadRow $ui.cl_List ([string]$g.Name + ('   ' + [char]0x00B7 + '   ') + [string]$files.Count + (' kopya   ' + [char]0x00B7 + '   dosya ba' + [char]0x015F + '' + [char]0x0131 + 'na ') + (Format-Size ([double]$g.Size)) + ('   ' + [char]0x00B7 + '   kazan' + [char]0x0131 + 'labilir ') + (Format-Size $w))
        foreach ($f in $files) {
            $dir = ''
            try { $dir = [string][System.IO.Path]::GetDirectoryName([string]$f) } catch { }
            $d = @{ Path = [string]$f; Dir = $dir; Name = [string]$g.Name; Group = [string]$gi; Size = [double]$g.Size }
            $row = New-ItemRow @{ Title = [string]$f; BrCol = 'BrAccent2'; Btn1 = ('Klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' a' + [char]0x00E7 + '') } $d $true $false
            $row.FindName('Act').Add_Click($script:H_ClFOpen)
            [void]$ui.cl_List.Children.Add($row)
            $shown++
        }
    }
    $ui.cl_Total.Text = (Tr $(([string]$s.Root + ('   ' + [char]0x00B7 + '   ') + [string]$gi + (' kopya grubu   ' + [char]0x00B7 + '   kazan' + [char]0x0131 + 'labilir ') + (Format-Size $waste))))
    if ($gi -eq 0) {
        Add-Note $ui.cl_List ('Bu klas' + [char]0x00F6 + 'rde 5 MB ' + [char]0x00FC + 'zerinde ayn' + [char]0x0131 + ' i' + [char]0x00E7 + 'erikli dosya bulunamad' + [char]0x0131 + '.') 'good'
        $ui.cl_Foot.Text = (Tr $(''))
        return
    }
    $ui.cl_Foot.Text = (Tr $(('Hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey kendili' + [char]0x011F + 'inden i' + [char]0x015F + 'aretlenmez. ' + [char]0x201C + 'Her gruptan birini koru' + [char]0x201D + ' her grubun ilk dosyas' + [char]0x0131 + 'n' + [char]0x0131 + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'r, kalan' + [char]0x0131 + 'n' + [char]0x0131 + ' i' + [char]0x015F + 'aretler. Dosyalar Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na gider.')))
}

function Start-ClFScan {
    $root = Get-ClFRoot
    if (-not (Test-Path -LiteralPath $root -PathType Container)) { Show-Toast ('Klas' + [char]0x00F6 + 'r bulunamad' + [char]0x0131 + '. ' + [char]0x201C + 'Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + '...' + [char]0x201D + ' ile ba' + [char]0x015F + 'ka bir klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in.') 'warn'; return }
    if ($script:ClTab -eq 'dup') {
        Set-ListNote $ui.cl_List (('Kopya dosyalar aran' + [char]0x0131 + 'yor: ') + $root)
        [void](Start-Async 'DupScan' 'Job_Duplicates' @{ Path = $root; MinMB = 5 } {
            param($r)
            if ($null -eq $r) { Set-ListNote $ui.cl_List ('Tarama tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
            $script:ClDup = $r
            if ($script:ClTab -eq 'dup') { Render-ClDup }
        } ('Kopya dosya taramas' + [char]0x0131 + '') $false $true)
    } else {
        Set-ListNote $ui.cl_List (('En b' + [char]0x00FC + 'y' + [char]0x00FC + 'k dosyalar aran' + [char]0x0131 + 'yor: ') + $root)
        [void](Start-Async 'BigScan' 'Job_LargeFiles' @{ Path = $root; Top = 100; MinMB = 50 } {
            param($r)
            if ($null -eq $r) { Set-ListNote $ui.cl_List ('Tarama tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
            $script:ClBig = $r
            if ($script:ClTab -eq 'big') { Render-ClBig }
        } ('B' + [char]0x00FC + 'y' + [char]0x00FC + 'k dosya taramas' + [char]0x0131 + '') $false $true)
    }
}

function Start-ClRecycle {
    $sel = (Get-CheckedData $ui.cl_List)
    if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na g' + [char]0x00F6 + 'nderilecek dosyalar' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    if ($script:ClTab -eq 'dup') {
        $sizes = @{}
        foreach ($row in $ui.cl_List.Children) {
            $d = $row.Tag
            if ($d -is [hashtable] -and $d.ContainsKey('Group')) {
                $k = [string]$d.Group
                if ($sizes.ContainsKey($k)) { $sizes[$k] = [int]$sizes[$k] + 1 } else { $sizes[$k] = 1 }
            }
        }
        $full = @(Get-DupFullGroups $sel $sizes)
        if ($full.Count -gt 0) {
            Show-Message ('Her gruptan en az bir kopya kalmal' + [char]0x0131 + '') ([string]$full.Count + (' grupta t' + [char]0x00FC + 'm kopyalar' + [char]0x0131 + ' i' + [char]0x015F + 'aretlediniz. Ayn' + [char]0x0131 + ' dosyan' + [char]0x0131 + 'n en az bir ' + [char]0x00F6 + 'rne' + [char]0x011F + 'i kalmal' + [char]0x0131 + '; yoksa dosya tamamen kaybolur. ' + [char]0x0130 + '' + [char]0x015F + 'aretlerden birini kald' + [char]0x0131 + 'r' + [char]0x0131 + 'n ya da ' + [char]0x201C + 'Her gruptan birini koru' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesini kullan' + [char]0x0131 + 'n.'))
            return
        }
    }
    $paths = @($sel | ForEach-Object { [string]$_.Path })
    $total = 0.0
    foreach ($x in $sel) { $total += [double]$x.Size }
    $script:PendingPaths = $paths
    Show-Confirm ('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na g' + [char]0x00F6 + 'nder') ([string]$paths.Count + " dosya g$([char]0x00F6)nderilecek (yakla$([char]0x015F)$([char]0x0131)k " + (Format-Size $total) + "):`r`n`r`n" + (Format-NameList $paths 10) + "`r`n`r`nDosyalar kal$([char]0x0131)c$([char]0x0131) silinmez; Windows$([char]0x2019)un Geri D$([char]0x00F6)n$([char]0x00FC)$([char]0x015F)$([char]0x00FC)m Kutusu$([char]0x2019)na gider ve oradan geri al$([char]0x0131)nabilir. Kutuya s$([char]0x0131)$([char]0x011F)mayacak kadar b$([char]0x00FC)y$([char]0x00FC)k dosyalar ve $([char]0x00E7)$([char]0x0131)kar$([char]0x0131)labilir s$([char]0x00FC)r$([char]0x00FC)c$([char]0x00FC)lerdeki dosyalar atlan$([char]0x0131)r (Windows bunlar$([char]0x0131) do$([char]0x011F)rudan silerdi); onlar$([char]0x0131) Gezgin$([char]0x2019)de elle silebilirsiniz.") ('G' + [char]0x00F6 + 'nder') {
        [void](Start-Async 'Recycle' 'Job_RecycleFiles' @{ Paths = $script:PendingPaths } {
            param($r)
            if ($null -eq $r) { Show-Toast ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
            $kind = 'good'
            $msg = [string]$r.Moved + (' dosya Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na g' + [char]0x00F6 + 'nderildi (') + (Format-Size ([double]$r.Bytes)) + ').'
            if ([int]$r.Skipped -gt 0) { $msg += ' ' + [string]$r.Skipped + (' dosya atland' + [char]0x0131 + ' (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte).'); $kind = 'warn' }
            if ([int]$r.Failed -gt 0) { $msg += ' ' + [string]$r.Failed + (' dosya g' + [char]0x00F6 + 'nderilemedi.'); $kind = 'warn' }
            Show-Toast $msg $kind
            if ($script:ClTab -eq 'big') { Render-ClBig } elseif ($script:ClTab -eq 'dup') { Render-ClDup }
        } ('Dosyalar Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na g' + [char]0x00F6 + 'nderiliyor'))
    }
}

function Set-ClTab([string]$Tab) {
    $script:ClTab = $Tab
    switch ($Tab) {
        'clean' {
            Show-OnlyBar 'cl' @('cl_Scan', 'cl_Clean')
            Render-ClScan
            if ($null -eq $script:ClScan) { Start-ClScan }
        }
        'disk' {
            Show-OnlyBar 'cl' @('cl_Pick', 'cl_Up', 'cl_Open')
            if ($script:ClPath -eq '') { $script:ClPath = [string]$env:SystemDrive + '\Users' }
            Start-ClDisk $script:ClPath $false
        }
        'big' {
            Show-OnlyBar 'cl' @('cl_FScan', 'cl_FPick', 'cl_FRecycle')
            Render-ClBig
        }
        'dup' {
            Show-OnlyBar 'cl' @('cl_FScan', 'cl_FPick', 'cl_FAuto', 'cl_FRecycle')
            Render-ClDup
        }
        'compress' {
            Show-OnlyBar 'cl' @('cl_CpScan', 'cl_CpPrev', 'cl_CpRun')
            Render-ClCompress
        }
    }
}

function Init-ClFiles {
    $ui.cl_FScan.Add_Click({ Invoke-Safe { Start-ClFScan } 'Tara' })
    $ui.cl_FPick.Add_Click({
        Invoke-Safe {
            $f = Select-Folder ('Taranacak klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in')
            if ($f -ne '') {
                $script:ClFRoot = $f
                $script:ClBig = $null
                $script:ClDup = $null
                if ($script:ClTab -eq 'big') { Render-ClBig } elseif ($script:ClTab -eq 'dup') { Render-ClDup }
            }
        } ('Klas' + [char]0x00F6 + 'r')
    })
    $ui.cl_FAuto.Add_Click({
        Invoke-Safe {
            $script:ClDupSeen = @{}
            Set-RowChecks $ui.cl_List {
                param($d)
                $g = [string]$d.Group
                if (-not $script:ClDupSeen.ContainsKey($g)) { $script:ClDupSeen[$g] = $true; return $false }
                return $true
            }
        } ('' + [char]0x0130 + '' + [char]0x015F + 'aretle')
    })
    $ui.cl_FRecycle.Add_Click({ Invoke-Safe { Start-ClRecycle } ('G' + [char]0x00F6 + 'nder') })
}

# ------------------------------------------------------------------
#  Guncellemeler: denetim, kurulu guncellemeler, winget sabitleme
# ------------------------------------------------------------------
$script:UpWgPins = $false
$script:UpPins = $null

function Set-UpBar([string]$Tab) {
    switch ($Tab) {
        'wu' {
            Show-OnlyBar 'up' @('up_Check', 'up_SelAll', 'up_SelNone', 'up_Install')
            $ui.up_Check.Content = (Tr $(('G' + [char]0x00FC + 'ncellemeleri ara')))
            $ui.up_Install.Content = (Tr $(('Se' + [char]0x00E7 + 'ilenleri kur')))
        }
        'winget' {
            if ($script:UpWgPins) {
                Show-OnlyBar 'up' @('up_PinList', 'up_SelAll', 'up_SelNone', 'up_Unpin')
                $ui.up_PinList.Content = (Tr $(('G' + [char]0x00FC + 'ncellemelere d' + [char]0x00F6 + 'n')))
            } else {
                Show-OnlyBar 'up' @('up_Check', 'up_SelAll', 'up_SelNone', 'up_Install', 'up_Pin', 'up_PinList')
                $ui.up_Check.Content = (Tr $(('Program g' + [char]0x00FC + 'ncellemelerini ara')))
                $ui.up_Install.Content = (Tr $(('Se' + [char]0x00E7 + 'ilenleri g' + [char]0x00FC + 'ncelle')))
                $ui.up_PinList.Content = (Tr $('Sabitlenenler'))
            }
        }
        'ctl' { Show-OnlyBar 'up' @('up_Pause', 'up_Resume', 'up_Defer', 'up_DeferOff', 'up_DrvToggle') }
        'inst' {
            Show-OnlyBar 'up' @('up_Check', 'up_SelNone', 'up_Uninstall')
            $ui.up_Check.Content = (Tr $('Yenile'))
        }
        'hist' {
            Show-OnlyBar 'up' @('up_Check')
            $ui.up_Check.Content = (Tr $('Yenile'))
        }
    }
}

function Render-UpCurrent {
    switch ($script:UpTab) {
        'wu' { Render-UpWu }
        'winget' { Render-UpWinget }
        'ctl' { Render-UpCtl }
        'inst' { Render-UpInst }
        'hist' { Render-UpHist }
    }
}

# ---------------- Denetim: duraklat / ertele / suruculer ----------------
function Render-UpCtl {
    $ui.up_List.Children.Clear()
    $st = Get-WuControlState
    Add-HeadRow $ui.up_List ('' + [char]0x015E + 'u anki durum')
    if ($st.Paused -eq $true) {
        Add-KvRow $ui.up_List ('G' + [char]0x00FC + 'ncellemeler') (('Duraklat' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ': ') + ([datetime]$st.Until).ToLocalTime().ToString('dd.MM.yyyy HH:mm') + ' tarihine kadar')
    } else {
        Add-KvRow $ui.up_List ('G' + [char]0x00FC + 'ncellemeler') ('Duraklat' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' (Windows normal ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor)')
    }
    if ($st.DeferOn -eq $true) { Add-KvRow $ui.up_List ('' + [char]0x00D6 + 'zellik g' + [char]0x00FC + 'ncellemeleri') ([string]$st.DeferDays + (' g' + [char]0x00FC + 'n ertelenmi' + [char]0x015F + '')) }
    else { Add-KvRow $ui.up_List ('' + [char]0x00D6 + 'zellik g' + [char]0x00FC + 'ncellemeleri') ('Ertelenmemi' + [char]0x015F + '') }
    if ($st.NoDrivers -eq $true) { Add-KvRow $ui.up_List ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler') ('Windows Update ile al' + [char]0x0131 + 'nm' + [char]0x0131 + 'yor (' + [char]0x00FC + 'reticinin sitesinden al' + [char]0x0131 + 'rs' + [char]0x0131 + 'n' + [char]0x0131 + 'z)') }
    else { Add-KvRow $ui.up_List ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler') ('Windows Update ile al' + [char]0x0131 + 'n' + [char]0x0131 + 'yor') }
    Add-HeadRow $ui.up_List ('Ne i' + [char]0x015F + 'e yarar')
    Add-Note $ui.up_List ('Windows Update bu ara' + [char]0x00E7 + 'la kapat' + [char]0x0131 + 'lmaz. Burada yaln' + [char]0x0131 + 'zca zaman' + [char]0x0131 + ' siz belirlersiniz; her de' + [char]0x011F + 'i' + [char]0x015F + 'iklik Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve oradan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.')
    Add-Note $ui.up_List ('Duraklat (en ' + [char]0x00E7 + 'ok 35 g' + [char]0x00FC + 'n): ' + [char]0x00F6 + 'nemli bir i' + [char]0x015F + 'in ya da sunumun ortas' + [char]0x0131 + 'nda beklenmedik yeniden ba' + [char]0x015F + 'latmay' + [char]0x0131 + ' ' + [char]0x00F6 + 'nler. Bu s' + [char]0x00FC + 'rede g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemeleri de gelmez; s' + [char]0x00FC + 're dolunca Windows kendili' + [char]0x011F + 'inden s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'r.')
    Add-Note $ui.up_List ('' + [char]0x00D6 + 'zellik g' + [char]0x00FC + 'ncellemelerini ertele (en ' + [char]0x00E7 + 'ok 365 g' + [char]0x00FC + 'n): y' + [char]0x0131 + 'lda bir gelen b' + [char]0x00FC + 'y' + [char]0x00FC + 'k s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' bekletir; ayl' + [char]0x0131 + 'k g' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemeleri etkilenmez.')
    Add-Note $ui.up_List ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri Windows Update' + [char]0x2019 + 'ten alma: Windows' + [char]0x2019 + 'un yanl' + [char]0x0131 + '' + [char]0x015F + ' ya da eski bir ekran kart' + [char]0x0131 + '/a' + [char]0x011F + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + ' kendili' + [char]0x011F + 'inden kurmas' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x00F6 + 'nler. S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri ' + [char]0x00FC + 'reticiden siz g' + [char]0x00FC + 'ncellersiniz.')
    if ($st.NoDrivers -eq $true) { $ui.up_DrvToggle.Content = (Tr $(('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri yeniden Windows Update' + [char]0x2019 + 'ten al'))) } else { $ui.up_DrvToggle.Content = (Tr $(('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri Windows Update' + [char]0x2019 + 'ten alma'))) }
    $ui.up_Foot.Text = (Tr $(('Not: Windows Home s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde baz' + [char]0x0131 + ' ilkeler (ertelemeler) yok say' + [char]0x0131 + 'labilir; Pro ve Enterprise s' + [char]0x00FC + 'r' + [char]0x00FC + 'mlerinde tam ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.')))
}

function Start-UpPause {
    Show-Input ('G' + [char]0x00FC + 'ncellemeleri duraklat') ("Windows g$([char]0x00FC)ncellemeleri ka$([char]0x00E7) g$([char]0x00FC)n duraklat$([char]0x0131)ls$([char]0x0131)n? (1-35)`r`n`r`nBu s$([char]0x00FC)rede g$([char]0x00FC)venlik g$([char]0x00FC)ncellemeleri de gelmez. S$([char]0x00FC)re dolunca Windows kendili$([char]0x011F)inden s$([char]0x00FC)rd$([char]0x00FC)r$([char]0x00FC)r; istedi$([char]0x011F)iniz zaman $([char]0x201C)Duraklatmay$([char]0x0131) kald$([char]0x0131)r$([char]0x201D) ile geri al$([char]0x0131)rs$([char]0x0131)n$([char]0x0131)z.") '14' {
        param($txt)
        $n = 0
        if (-not [int]::TryParse(([string]$txt).Trim(), [ref]$n) -or $n -lt 1 -or $n -gt 35) { Show-Toast ('G' + [char]0x00FC + 'n say' + [char]0x0131 + 's' + [char]0x0131 + ' 1 ile 35 aras' + [char]0x0131 + 'nda olmal' + [char]0x0131 + '.') 'warn'; return }
        Start-PlanJob (New-WuPauseSteps $n) ('Windows g' + [char]0x00FC + 'ncellemeleri duraklat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { Render-UpCtl }
    }
}

function Start-UpDefer {
    Show-Input ('' + [char]0x00D6 + 'zellik g' + [char]0x00FC + 'ncellemelerini ertele') ("Y$([char]0x0131)lda bir gelen b$([char]0x00FC)y$([char]0x00FC)k Windows s$([char]0x00FC)r$([char]0x00FC)m$([char]0x00FC) ka$([char]0x00E7) g$([char]0x00FC)n ertelensin? (1-365)`r`n`r`nAyl$([char]0x0131)k g$([char]0x00FC)venlik g$([char]0x00FC)ncellemeleri etkilenmez.") '180' {
        param($txt)
        $n = 0
        if (-not [int]::TryParse(([string]$txt).Trim(), [ref]$n) -or $n -lt 1 -or $n -gt 365) { Show-Toast ('G' + [char]0x00FC + 'n say' + [char]0x0131 + 's' + [char]0x0131 + ' 1 ile 365 aras' + [char]0x0131 + 'nda olmal' + [char]0x0131 + '.') 'warn'; return }
        Start-PlanJob (New-WuDeferSteps $n) ('' + [char]0x00D6 + 'zellik g' + [char]0x00FC + 'ncellemeleri erteleniyor') $false $false { Render-UpCtl }
    }
}

function Start-UpDriverToggle {
    $st = Get-WuControlState
    if ($st.NoDrivers -eq $true) {
        Start-PlanJob (New-WuDriverSteps $false) ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler yeniden Windows Update ile al' + [char]0x0131 + 'nacak') $false $false { Render-UpCtl }
        return
    }
    Show-Confirm ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'leri Windows Update' + [char]0x2019 + 'ten alma') "Windows Update art$([char]0x0131)k s$([char]0x00FC)r$([char]0x00FC)c$([char]0x00FC) g$([char]0x00F6)ndermeyecek. Ekran kart$([char]0x0131), a$([char]0x011F) ve ses s$([char]0x00FC)r$([char]0x00FC)c$([char]0x00FC)lerini $([char]0x00FC)reticinin sitesinden (ya da H$([char]0x0131)zland$([char]0x0131)r sayfas$([char]0x0131)ndaki s$([char]0x00FC)r$([char]0x00FC)c$([char]0x00FC) yede$([char]0x011F)inden) siz g$([char]0x00FC)ncellersiniz.`r`n`r`n$([char]0x0130)stedi$([char]0x011F)iniz zaman geri alabilirsiniz." 'Uygula' {
        Start-PlanJob (New-WuDriverSteps $true) ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler Windows Update' + [char]0x2019 + 'ten ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { Render-UpCtl }
    }
}

# ---------------- Kurulu guncellemeler ----------------
function Render-UpInst {
    $ui.up_List.Children.Clear()
    $rows = $script:UpData['inst']
    if ($null -eq $rows) { Set-ListNote $ui.up_List ('Kurulu g' + [char]0x00FC + 'ncellemeler okunuyor...'); return }
    $all = @($rows)
    if ($all.Count -eq 0) { Add-Note $ui.up_List ('Kurulu g' + [char]0x00FC + 'ncelleme listesi bo' + [char]0x015F + ' ya da okunamad' + [char]0x0131 + '.'); $ui.up_Foot.Text = (Tr $('')); return }
    $show = @($all | Select-Object -First 300)
    foreach ($r in $show) {
        $d = @{ Id = [string]$r.Id; Title = [string]$r.Id }
        $det = [string]$r.Desc
        if ([string]$r.By -ne '') { $det += ('   ' + [char]0x00B7 + '   ') + [string]$r.By }
        $row = New-ItemRow @{ Title = [string]$r.Id; Detail = $det; Tag = [string]$r.DateText; BrCol = 'BrInfo' } $d $true $false
        [void]$ui.up_List.Children.Add($row)
    }
    $ui.up_Foot.Text = (Tr $(([string]$all.Count + (' g' + [char]0x00FC + 'ncelleme kurulu. Sorun ' + [char]0x00E7 + '' + [char]0x0131 + 'karan g' + [char]0x00FC + 'ncellemeyi i' + [char]0x015F + 'aretleyip kald' + [char]0x0131 + 'rabilirsiniz; kald' + [char]0x0131 + 'rma geri al' + [char]0x0131 + 'namaz ve Windows Update ayn' + [char]0x0131 + ' g' + [char]0x00FC + 'ncellemeyi yeniden sunabilir (' + [char]0x00F6 + 'nce Denetim sekmesinden duraklat' + [char]0x0131 + 'n). Birikimli g' + [char]0x00FC + 'ncellemeler bu y' + [char]0x00F6 + 'ntemle kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lamayabilir.'))))
}

function Start-UpUninstall {
    $sel = (Get-CheckedData $ui.up_List)
    if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak g' + [char]0x00FC + 'ncellemeyi i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $script:PendingIds = @($sel | ForEach-Object { [string]$_.Id })
    Show-Confirm ('G' + [char]0x00FC + 'ncellemeleri kald' + [char]0x0131 + 'r') ([string]$script:PendingIds.Count + " g$([char]0x00FC)ncelleme kald$([char]0x0131)r$([char]0x0131)lacak:`r`n`r`n" + (Format-NameList $script:PendingIds 10) + "`r`n`r`nBu i$([char]0x015F)lem geri al$([char]0x0131)namaz. Windows Update ayn$([char]0x0131) g$([char]0x00FC)ncellemeyi yeniden sunabilir. Birikimli g$([char]0x00FC)ncellemeler bu y$([char]0x00F6)ntemle kald$([char]0x0131)r$([char]0x0131)lamayabilir; o durumda Ayarlar > Windows Update > G$([char]0x00FC)ncelleme ge$([char]0x00E7)mi$([char]0x015F)i > G$([char]0x00FC)ncellemeleri kald$([char]0x0131)r yolunu kullan$([char]0x0131)n.") ('Kald' + [char]0x0131 + 'r') {
        [void](Start-Async 'WuUninstall' 'Job_WuUninstall' @{ Ids = $script:PendingIds } {
            param($r)
            if ($null -eq $r) { Show-Toast ('Kald' + [char]0x0131 + 'rma tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
            $kind = 'good'
            $msg = [string]$r.Removed + (' g' + [char]0x00FC + 'ncelleme kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '.')
            if ([int]$r.Failed -gt 0) { $msg = [string]$r.Removed + (' g' + [char]0x00FC + 'ncelleme kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ', ') + [string]$r.Failed + (' hata (g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n).'); $kind = 'warn' }
            Show-Toast $msg $kind
            $script:UpData['inst'] = $null
            if ($script:UpTab -eq 'inst') { Start-UpCheck }
            if ($r.Reboot -eq $true) { Request-Reboot }
        } ('G' + [char]0x00FC + 'ncellemeler kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
    } $true
}

# ---------------- winget: sabitle / sabitlemeyi kaldir ----------------
function Render-UpPins {
    $ui.up_List.Children.Clear()
    $ids = $script:UpPins
    if ($null -eq $ids) { Set-ListNote $ui.up_List 'Sabitli programlar okunuyor...'; return }
    $arr = @($ids | Where-Object { $_ })
    if ($arr.Count -eq 0) {
        Add-Note $ui.up_List ('Sabitlenmi' + [char]0x015F + ' program yok. ' + [char]0x201C + 'G' + [char]0x00FC + 'ncellemelere d' + [char]0x00F6 + 'n' + [char]0x201D + ' ile listeye d' + [char]0x00F6 + 'n' + [char]0x00FC + 'p g' + [char]0x00FC + 'ncellenmesini istemedi' + [char]0x011F + 'iniz program' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin ve ' + [char]0x201C + 'Se' + [char]0x00E7 + 'ilenleri sabitle' + [char]0x201D + 'ye bas' + [char]0x0131 + 'n.')
        $ui.up_Foot.Text = (Tr $(''))
        return
    }
    foreach ($id in $arr) {
        $row = New-ItemRow @{ Title = [string]$id; Detail = ('Sabitli: toplu g' + [char]0x00FC + 'ncellemede ve ' + [char]0x201C + 'winget upgrade --all' + [char]0x201D + ' komutunda atlan' + [char]0x0131 + 'r'); Tag = 'sabit'; BrCol = 'BrGold' } @{ Id = [string]$id } $true $false
        [void]$ui.up_List.Children.Add($row)
    }
    $ui.up_Foot.Text = (Tr $(([string]$arr.Count + (' program sabitli. ' + [char]0x0130 + '' + [char]0x015F + 'aretleyip ' + [char]0x201C + 'Sabitlemeyi kald' + [char]0x0131 + 'r' + [char]0x201D + ' ile yeniden g' + [char]0x00FC + 'ncellenebilir yapabilirsiniz.'))))
}

function Load-UpPins {
    Set-ListNote $ui.up_List 'Sabitli programlar okunuyor...'
    [void](Start-Async 'WgPins' 'Job_WingetPinList' @{} {
        param($r)
        if ($null -eq $r) { $script:UpPins = @() } else { $script:UpPins = @($r.Ids) }
        if ($script:UpTab -eq 'winget' -and $script:UpWgPins) { Render-UpPins }
    } 'Sabitli programlar' $false $true)
}

function Start-UpPin {
    $sel = (Get-CheckedData $ui.up_List)
    if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce g' + [char]0x00FC + 'ncellenmesini istemedi' + [char]0x011F + 'iniz program' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $script:PendingIds = @($sel | ForEach-Object { [string]$_.Id })
    $names = @($sel | ForEach-Object { [string]$_.Name })
    Show-Confirm ('Programlar' + [char]0x0131 + ' sabitle') ([string]$script:PendingIds.Count + " program sabitlenecek:`r`n`r`n" + (Format-NameList $names 10) + "`r`n`r`nSabitli program toplu g$([char]0x00FC)ncellemede ve $([char]0x201C)winget upgrade --all$([char]0x201D) komutunda atlan$([char]0x0131)r. $([char]0x201C)Sabitlenenler$([char]0x201D) b$([char]0x00F6)l$([char]0x00FC)m$([char]0x00FC)nden istedi$([char]0x011F)iniz zaman kald$([char]0x0131)r$([char]0x0131)rs$([char]0x0131)n$([char]0x0131)z.") 'Sabitle' {
        [void](Start-Async 'WgPin' 'Job_WingetPin' @{ Action = 'add'; Ids = $script:PendingIds } {
            param($r)
            if ($null -ne $r -and $r.Ok -eq $true) {
                Show-Toast ([string]$r.Done + ' program sabitlendi.') 'good'
                $script:UpData.winget = @($script:UpData.winget | Where-Object { $script:PendingIds -notcontains [string]$_.Id })
                $script:UpPins = $null
                if ($script:UpTab -eq 'winget' -and -not $script:UpWgPins) { Render-UpWinget }
            } else {
                Show-Toast ('Sabitleme tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn'
            }
        } 'Programlar sabitleniyor')
    }
}

function Start-UpUnpin {
    $sel = (Get-CheckedData $ui.up_List)
    if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce sabitlemesi kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak program' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $script:PendingIds = @($sel | ForEach-Object { [string]$_.Id })
    [void](Start-Async 'WgUnpin' 'Job_WingetPin' @{ Action = 'remove'; Ids = $script:PendingIds } {
        param($r)
        if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ([string]$r.Done + (' program' + [char]0x0131 + 'n sabitlemesi kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '.')) 'good' } else { Show-Toast ('Sabitleme kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
        $script:UpData.winget = $null
        $script:UpPins = $null
        if ($script:UpTab -eq 'winget' -and $script:UpWgPins) { Load-UpPins }
    } ('Sabitlemeler kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
}

function Init-UpFiles {
    $ui.up_Pause.Add_Click({ Invoke-Safe { Start-UpPause } 'Duraklat' })
    $ui.up_Resume.Add_Click({ Invoke-Safe { Start-PlanJob (New-WuPauseSteps 0) ('Duraklatma kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { Render-UpCtl } } ('S' + [char]0x00FC + 'rd' + [char]0x00FC + 'r') })
    $ui.up_Defer.Add_Click({ Invoke-Safe { Start-UpDefer } 'Ertele' })
    $ui.up_DeferOff.Add_Click({ Invoke-Safe { Start-PlanJob (New-WuDeferSteps 0) ('Erteleme kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { Render-UpCtl } } 'Erteleme' })
    $ui.up_DrvToggle.Add_Click({ Invoke-Safe { Start-UpDriverToggle } ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + '') })
    $ui.up_Uninstall.Add_Click({ Invoke-Safe { Start-UpUninstall } ('Kald' + [char]0x0131 + 'r') })
    $ui.up_Pin.Add_Click({ Invoke-Safe { Start-UpPin } 'Sabitle' })
    $ui.up_Unpin.Add_Click({ Invoke-Safe { Start-UpUnpin } 'Sabitleme' })
    $ui.up_PinList.Add_Click({
        Invoke-Safe {
            $script:UpWgPins = -not $script:UpWgPins
            Set-UpBar 'winget'
            if ($script:UpWgPins) { $script:UpPins = $null; Load-UpPins } else { Render-UpWinget }
        } 'Sabitlenenler'
    })
}

# ------------------------------------------------------------------
#  Yedek: BitLocker kurtarma anahtari
# ------------------------------------------------------------------
$script:BkBl = $null

function Load-BkBl {
    Set-ListNote $ui.bk_List 'BitLocker durumu okunuyor...'
    [void](Start-Async 'BlInfo' 'Job_BitLockerInfo' @{} {
        param($r)
        if ($null -eq $r) { $script:BkBl = @() } else { $script:BkBl = @($r.Rows) }
        if ($script:BkTab -eq 'bl') { Render-BkBl }
    } 'BitLocker durumu okunuyor' $false $true)
}

$script:H_BkBlKey = {
    param($s, $e)
    Invoke-Safe {
        [void](Start-Async 'BlKey' 'Job_BitLockerKey' @{ Drive = [string]$s.Tag.Drive } {
            param($r)
            if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Kurtarma anahtar' + [char]0x0131 + ' okunamad' + [char]0x0131 + '. Uygulaman' + [char]0x0131 + 'n y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' ve s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de kurtarma anahtar' + [char]0x0131 + ' tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' olmas' + [char]0x0131 + ' gerekir.') 'warn'; return }
            $lines = New-Object System.Collections.ArrayList
            foreach ($k in @($r.Keys)) { [void]$lines.Add(('Anahtar kimli' + [char]0x011F + 'i: ') + [string]$k.Id + "`r`nKurtarma anahtar$([char]0x0131): " + [string]$k.Password) }
            Show-Message ([string]$r.Drive + (' kurtarma anahtar' + [char]0x0131 + '')) (($lines.ToArray() -join "`r`n`r`n") + "`r`n`r`nBu anahtar$([char]0x0131) bilen herkes s$([char]0x00FC)r$([char]0x00FC)c$([char]0x00FC)n$([char]0x00FC)zdeki verilere eri$([char]0x015F)ebilir. Bir kopyas$([char]0x0131)n$([char]0x0131) bilgisayar$([char]0x0131)n DI$([char]0x015E)INDA saklay$([char]0x0131)n (USB bellek, Microsoft hesab$([char]0x0131)n$([char]0x0131)z ya da ka$([char]0x011F)$([char]0x0131)da yazd$([char]0x0131)r$([char]0x0131)lm$([char]0x0131)$([char]0x015F)). Anahtar g$([char]0x00FC)nl$([char]0x00FC)$([char]0x011F)e yaz$([char]0x0131)lmaz.")
        } ('Kurtarma anahtar' + [char]0x0131 + ' okunuyor') $false $true)
    } 'Anahtar'
}

$script:H_BkBlSave = {
    param($s, $e)
    Invoke-Safe {
        [void](Start-Async 'BlKey' 'Job_BitLockerKey' @{ Drive = [string]$s.Tag.Drive } {
            param($r)
            if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Kurtarma anahtar' + [char]0x0131 + ' okunamad' + [char]0x0131 + '. Uygulaman' + [char]0x0131 + 'n y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' ve s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de kurtarma anahtar' + [char]0x0131 + ' tan' + [char]0x0131 + 'ml' + [char]0x0131 + ' olmas' + [char]0x0131 + ' gerekir.') 'warn'; return }
            $text = Format-BlKeyFile ([string]$r.Drive) $r.Keys
            $name = 'BitLocker-kurtarma-' + ([string]$r.Drive).TrimEnd(':') + '-' + [string]$env:COMPUTERNAME + '.txt'
            $f = Select-SaveFile ('Metin dosyas' + [char]0x0131 + ' (*.txt)|*.txt') $name
            if ($f -eq '') { return }
            if ($f.StartsWith([string]$r.Drive, [StringComparison]::OrdinalIgnoreCase)) {
                Show-Toast ('Anahtar, ' + [char]0x015F + 'ifrelenen s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'n kendisine kaydedilmez; s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye eri' + [char]0x015F + 'emezseniz dosyaya da eri' + [char]0x015F + 'emezsiniz. USB bellek ya da ba' + [char]0x015F + 'ka bir disk se' + [char]0x00E7 + 'in.') 'warn'
                return
            }
            try {
                [System.IO.File]::WriteAllText($f, $text, (New-Object System.Text.UTF8Encoding($true)))
                Show-Toast ('Anahtar kaydedildi: ' + $f + ('. Dosyay' + [char]0x0131 + ' g' + [char]0x00FC + 'venli bir yerde saklay' + [char]0x0131 + 'n.')) 'good'
            } catch { Show-Toast ('Kaydedilemedi: ' + $_.Exception.Message) 'bad' }
        } ('Kurtarma anahtar' + [char]0x0131 + ' okunuyor') $false $true)
    } 'Kaydet'
}

$script:H_BkBlAdd = {
    param($s, $e)
    Invoke-Safe {
        $script:PendingDrive = [string]$s.Tag.Drive
        Show-Confirm ('Kurtarma anahtar' + [char]0x0131 + ' ekle') ($script:PendingDrive + " s$([char]0x00FC)r$([char]0x00FC)c$([char]0x00FC)s$([char]0x00FC)ne bir BitLocker kurtarma anahtar$([char]0x0131) (48 haneli say$([char]0x0131)) eklenecek.`r`n`r`nDiskiniz zaten $([char]0x015F)ifreli; bu i$([char]0x015F)lem veriyi de$([char]0x011F)i$([char]0x015F)tirmez, yaln$([char]0x0131)zca BIOS ya da donan$([char]0x0131)m de$([char]0x011F)i$([char]0x015F)ikli$([char]0x011F)inden sonra Windows anahtar sorarsa kullan$([char]0x0131)lacak yedek anahtar$([char]0x0131) olu$([char]0x015F)turur. Eklendikten sonra $([char]0x201C)Anahtar$([char]0x0131) g$([char]0x00F6)ster$([char]0x201D) ya da $([char]0x201C)Dosyaya kaydet$([char]0x201D) ile saklay$([char]0x0131)n.") 'Ekle' {
            [void](Start-Async 'BlAdd' 'Job_BitLockerAddKey' @{ Drive = $script:PendingDrive } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Kurtarma anahtar' + [char]0x0131 + ' eklendi. ' + [char]0x015E + 'imdi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 'leyip bilgisayar' + [char]0x0131 + 'n d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda saklay' + [char]0x0131 + 'n.') 'good' } else { Show-Toast ('Kurtarma anahtar' + [char]0x0131 + ' eklenemedi (y' + [char]0x00F6 + 'netici gerekir); g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
                $script:BkBl = $null
                if ($script:BkTab -eq 'bl') { Render-BkBl }
            } ('Kurtarma anahtar' + [char]0x0131 + ' ekleniyor'))
        }
    } 'Ekle'
}

function Render-BkBl {
    $ui.bk_List.Children.Clear()
    $rows = $script:BkBl
    if ($null -eq $rows) { Load-BkBl; return }
    Add-Note $ui.bk_List ('BitLocker diskinizi ' + [char]0x015F + 'ifreler: bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'rsa dosyalara eri' + [char]0x015F + 'ilemez. Ama BIOS g' + [char]0x00FC + 'ncellemesi ya da donan' + [char]0x0131 + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'inden sonra Windows 48 haneli bir kurtarma anahtar' + [char]0x0131 + ' sorabilir; anahtar' + [char]0x0131 + ' bilmiyorsan' + [char]0x0131 + 'z verilerinize bir daha eri' + [char]0x015F + 'emezsiniz. Anahtar' + [char]0x0131 + 'n bir kopyas' + [char]0x0131 + ' bilgisayar' + [char]0x0131 + 'n d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda olmal' + [char]0x0131 + '.')
    $arr = @($rows)
    if ($arr.Count -eq 0) {
        Add-Note $ui.bk_List ('BitLocker bilgisi okunamad' + [char]0x0131 + '. Bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde (' + [char]0x00F6 + 'r. Home) BitLocker yerine ' + [char]0x201C + 'Cihaz ' + [char]0x015F + 'ifrelemesi' + [char]0x201D + ' bulunur ya da uygulama y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'm' + [char]0x0131 + 'yor.') 'warn'
        Add-BlHomeRows
        $ui.bk_Foot.Text = (Tr $(''))
        return
    }
    foreach ($r in $arr) {
        $br = 'BrWarn'
        if ($r.Protected -eq $true) { $br = 'BrGood' }
        $det = [string]$r.Status
        if ([string]$r.Protectors -ne '') { $det += ('   ' + [char]0x00B7 + '   Koruyucular: ') + [string]$r.Protectors }
        $b1 = ''; $b2 = ''
        if ($r.Encrypted -eq $true) {
            if ($r.HasRecovery -eq $true) { $det += ('   ' + [char]0x00B7 + '   kurtarma anahtar' + [char]0x0131 + ' tan' + [char]0x0131 + 'ml' + [char]0x0131 + ''); $b1 = ('Anahtar' + [char]0x0131 + ' g' + [char]0x00F6 + 'ster'); $b2 = 'Dosyaya kaydet...' }
            else { $det += ('   ' + [char]0x00B7 + '   KURTARMA ANAHTARI YOK'); $br = 'BrBad'; $b1 = 'Anahtar ekle' }
        }
        if ($r.Encrypted -ne $true) { $b1 = (Get-BlOnLabel) }
        $d = @{ Drive = [string]$r.Drive }
        $row = New-ItemRow @{ Title = ([string]$r.Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + '')); Detail = $det; BrCol = $br; Btn1 = $b1; Btn2 = $b2 } $d $false $false
        if ($b1 -eq ('Anahtar' + [char]0x0131 + ' g' + [char]0x00F6 + 'ster')) { $row.FindName('Act').Add_Click($script:H_BkBlKey); $row.FindName('Act2').Add_Click($script:H_BkBlSave) }
        elseif ($b1 -eq 'Anahtar ekle') { $row.FindName('Act').Add_Click($script:H_BkBlAdd) }
        elseif ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_BkBlOn) }
        [void]$ui.bk_List.Children.Add($row)
    }
    $ui.bk_Foot.Text = (Tr $(('Anahtar yaln' + [char]0x0131 + 'zca siz istedi' + [char]0x011F + 'inizde okunur ve g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'lmaz. Microsoft hesab' + [char]0x0131 + 'n' + [char]0x0131 + 'zla oturum a' + [char]0x00E7 + 't' + [char]0x0131 + 'ysan' + [char]0x0131 + 'z anahtar ' + [char]0x00E7 + 'o' + [char]0x011F + 'u zaman hesab' + [char]0x0131 + 'n' + [char]0x0131 + 'zda da vard' + [char]0x0131 + 'r (a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'daki d' + [char]0x00FC + '' + [char]0x011F + 'me).')))
}

# ------------------------------------------------------------------
#  Yedek: sifreli ve surumlu dosya yedegi (restic)
# ------------------------------------------------------------------
$script:BkRestic = $null
$script:BkSnaps = $null
$script:ResticPw = ''
$script:ResticPreview = $false

function Get-BkRestic {
    if ($null -eq $script:BkRestic) { $script:BkRestic = [string](Find-Restic) }
    return [string]$script:BkRestic
}

function Get-BkFilesBar {
    $names = New-Object System.Collections.ArrayList
    foreach ($n in @('bk_AddSrc', 'bk_Dest', 'bk_Preview', 'bk_Run')) { [void]$names.Add($n) }
    if ([string]$script:Settings.BackupMode -eq 'Restic') {
        [void]$names.Add('bk_ResticSnaps')
        if ((Get-BkRestic) -eq '') { [void]$names.Add('bk_ResticGet') }
    } else {
        [void]$names.Add('bk_Restore')
    }
    return , $names.ToArray()
}

function Set-BkTab([string]$Tab) {
    $script:BkTab = $Tab
    if ($Tab -ne 'files') { $script:ResticPw = ''; $script:BkSnaps = $null }
    Set-Visible $ui.bk_Files ($Tab -eq 'files')
    switch ($Tab) {
        'files' { Show-OnlyBar 'bk' (Get-BkFilesBar); Render-BkFiles }
        'recycle' { Show-OnlyBar 'bk' @('bk_RbRefresh', 'bk_RbRestore'); Render-BkRecycle }
        'shadow' { Show-OnlyBar 'bk' @('bk_RbRefresh'); Render-BkShadow }
        'points' { Show-OnlyBar 'bk' @('bk_RbRefresh', 'bk_RpNew', 'bk_RpOpen'); Render-BkPoints }
        'recover' { Show-OnlyBar 'bk' @('bk_PhotoGet', 'bk_PhotoRun'); Render-BkRecover }
        'bl' { Show-OnlyBar 'bk' @('bk_BlRefresh', 'bk_BlWeb'); Render-BkBl }
        'kit' { Show-OnlyBar 'bk' @('bk_KitDrv', 'bk_KitWifi', 'bk_KitRun'); Render-BkKit }
    }
}

function Render-BkFiles {
    $script:ResticPw = ''
    $script:BkSnaps = $null
    $st = $script:Settings
    $dst = [string]$st.BackupDest
    $mode = [string]$st.BackupMode
    if ($mode -eq 'Restic') { $ui.bk_ModeRestic.IsChecked = $true }
    elseif ($mode -eq 'Tarihli') { $ui.bk_ModeDate.IsChecked = $true }
    else { $ui.bk_ModeCopy.IsChecked = $true }
    if ($dst -eq '') { $ui.bk_Dst.Text = (Tr $(('Hedef: se' + [char]0x00E7 + 'ilmedi. ' + [char]0x201C + 'Hedef se' + [char]0x00E7 + '...' + [char]0x201D + ' ile harici disk ya da a' + [char]0x011F + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (kaynak klas' + [char]0x00F6 + 'rlerin d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda olmal' + [char]0x0131 + ').'))) }
    elseif ($mode -eq 'Restic') { $ui.bk_Dst.Text = (Tr $(('Hedef: ' + (Get-ResticRepoPath $dst) + ('   (' + [char]0x015F + 'ifreli depo)')))) }
    else { $ui.bk_Dst.Text = (Tr $(('Hedef: ' + $dst + ('   (bilgisayar ad' + [char]0x0131 + 'yla alt klas' + [char]0x00F6 + 'r a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r)')))) }
    if ($mode -eq 'Restic') {
        $ex = Get-BkRestic
        if ($ex -eq '') { $ui.bk_ResticInfo.Text = (Tr $(('restic bu bilgisayarda yok. ' + [char]0x201C + 'restic' + [char]0x2019 + 'i kur (winget)' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesiyle kurun (a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak; paketin imzas' + [char]0x0131 + ' winget taraf' + [char]0x0131 + 'ndan do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r).'))) }
        else { $ui.bk_ResticInfo.Text = (Tr $(('restic bulundu: ' + $ex + "`r`nDosyalar $([char]0x015F)ifrelenir ve s$([char]0x00FC)r$([char]0x00FC)m s$([char]0x00FC)r$([char]0x00FC)m saklan$([char]0x0131)r (son 7 + haftal$([char]0x0131)k 4 + ayl$([char]0x0131)k 6). Parolay$([char]0x0131) yaln$([char]0x0131)zca siz bilirsiniz; unutursan$([char]0x0131)z yede$([char]0x011F)e eri$([char]0x015F)menin yolu yoktur."))) }
        Set-Visible $ui.bk_ResticInfo $true
    } else {
        Set-Visible $ui.bk_ResticInfo $false
    }
    $ui.bk_List.Children.Clear()
    $src = @($st.BackupSources)
    if ($src.Count -eq 0) {
        Add-Note $ui.bk_List ('Yedeklenecek klas' + [char]0x00F6 + 'r eklenmedi. ' + [char]0x201C + 'Klas' + [char]0x00F6 + 'r ekle...' + [char]0x201D + ' ile Belgeler, Masa' + [char]0x00FC + 'st' + [char]0x00FC + ', Resimler gibi klas' + [char]0x00F6 + 'rleri ekleyin.')
    }
    foreach ($p in $src) {
        $exists = Test-Path -LiteralPath ([string]$p)
        $br = 'BrGood'; $tag = ''
        if (-not $exists) { $br = 'BrBad'; $tag = ('klas' + [char]0x00F6 + 'r yok') }
        $row = New-ItemRow @{ Title = [string]$p; Tag = $tag; BrCol = $br; Btn1 = ('Listeden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar') } @{ Path = [string]$p } $false $false
        $row.FindName('Act').Add_Click($script:H_BkRemoveSrc)
        [void]$ui.bk_List.Children.Add($row)
    }
    $lb = [string]$st.LastBackup
    $how = ('Yedekleme yaln' + [char]0x0131 + 'zca yeni ve de' + [char]0x011F + 'i' + [char]0x015F + 'en dosyalar' + [char]0x0131 + ' kopyalar; kayna' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zdan hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silmez.')
    if ($mode -eq 'Restic') { $how = ('' + [char]0x015E + 'ifreli yedek yaln' + [char]0x0131 + 'zca yeni ve de' + [char]0x011F + 'i' + [char]0x015F + 'en veriyi ekler; kayna' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zdan hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silmez. Zamanlanm' + [char]0x0131 + '' + [char]0x015F + ' ve komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' yede' + [char]0x011F + 'i parola gerektirdi' + [char]0x011F + 'i i' + [char]0x00E7 + 'in ' + [char]0x015F + 'ifreli modda elle ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') }
    if ($lb -eq '') { $ui.bk_Foot.Text = (Tr $((('Hen' + [char]0x00FC + 'z yedek al' + [char]0x0131 + 'nmad' + [char]0x0131 + '. ') + $how))) }
    else { $ui.bk_Foot.Text = (Tr $(('Son yedek: ' + $lb + '. ' + $how))) }
}

function Update-BkMode([string]$Mode) {
    $script:Settings.BackupMode = $Mode
    Save-Settings $script:Settings
    if ($script:BkTab -eq 'files') { Show-OnlyBar 'bk' (Get-BkFilesBar); Render-BkFiles }
}

function Render-BkSnaps {
    $ui.bk_List.Children.Clear()
    $rows = @($script:BkSnaps)
    if ($rows.Count -eq 0) {
        Add-Note $ui.bk_List ('Bu depoda hen' + [char]0x00FC + 'z yedek s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' yok.') 'warn'
        $ui.bk_Foot.Text = (Tr $(''))
        return
    }
    Add-HeadRow $ui.bk_List ('Yedek s' + [char]0x00FC + 'r' + [char]0x00FC + 'mleri (en yeni ' + [char]0x00FC + 'stte)')
    foreach ($x in $rows) {
        $d = @{ Id = [string]$x.Id; Text = ([string]$x.TimeText + '  (' + [string]$x.Short + ')') }
        $row = New-ItemRow @{ Title = [string]$x.TimeText; Detail = ([string]$x.Host + ('   ' + [char]0x00B7 + '   ') + [string]$x.Paths); Tag = [string]$x.Short; BrCol = 'BrGood'; Btn1 = ('Geri y' + [char]0x00FC + 'kle...') } $d $false $false
        $row.FindName('Act').Add_Click($script:H_BkSnapRestore)
        [void]$ui.bk_List.Children.Add($row)
    }
    $ui.bk_Foot.Text = (Tr $(([string]$rows.Count + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'm. Geri y' + [char]0x00FC + 'kleme BO' + [char]0x015E + ' bir klas' + [char]0x00F6 + 're yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r; mevcut dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lmaz. Parola bu g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mden ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'nca bellekten silinir.'))))
}

$script:H_BkSnapRestore = {
    param($s, $e)
    Invoke-Safe {
        if ($script:ResticPw -eq '') { Show-Toast ('Parola oturumu kapand' + [char]0x0131 + '; ' + [char]0x201C + 'Yedek s' + [char]0x00FC + 'r' + [char]0x00FC + 'mleri' + [char]0x201D + ' ile yeniden listeleyin.') 'warn'; return }
        $script:PendingSnap = [string]$s.Tag.Id
        $script:PendingSnapName = [string]$s.Tag.Text
        $t = Select-Folder ('Geri y' + [char]0x00FC + 'klenecek BO' + [char]0x015E + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (' + [char]0x00F6 + 'zg' + [char]0x00FC + 'n dosyalar' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lmaz)')
        if ($t -eq '') { return }
        if (@(Get-ChildItem -LiteralPath $t -Force -ErrorAction SilentlyContinue).Count -gt 0) { Show-Toast ('Se' + [char]0x00E7 + 'ilen klas' + [char]0x00F6 + 'r bo' + [char]0x015F + ' de' + [char]0x011F + 'il. Bo' + [char]0x015F + ' bir klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in ya da yeni klas' + [char]0x00F6 + 'r olu' + [char]0x015F + 'turun.') 'warn'; return }
        $script:PendingTarget = $t
        Show-Confirm ('Yedekten geri y' + [char]0x00FC + 'kle') (('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm: ') + $script:PendingSnapName + "`r`nHedef: " + $t + "`r`n`r`nDosyalar bu bo$([char]0x015F) klas$([char]0x00F6)re a$([char]0x00E7)$([char]0x0131)l$([char]0x0131)r; mevcut dosyalar$([char]0x0131)n$([char]0x0131)z$([char]0x0131)n $([char]0x00FC)zerine yaz$([char]0x0131)lmaz.") ('Geri y' + [char]0x00FC + 'kle') {
            [void](Start-Async 'ResticRestore' 'Job_ResticRestore' @{ Dest = ''; Password = $script:ResticPw; Snapshot = $script:PendingSnap; Target = $script:PendingTarget } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Geri y' + [char]0x00FC + 'kleme tamamland' + [char]0x0131 + '.') 'good'; Open-Folder ([string]$r.Target) } else { Show-Toast ('Geri y' + [char]0x00FC + 'kleme tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
            } ('' + [char]0x015E + 'ifreli yedekten geri y' + [char]0x00FC + 'kleniyor'))
        }
    } ('Geri y' + [char]0x00FC + 'kle')
}

# Ortak on kosullar: kaynak, hedef ve restic var mi
function Test-ResticReady {
    $st = $script:Settings
    if ([string]$st.BackupDest -eq '') { Show-Toast ('' + [char]0x00D6 + 'nce Yedek sayfas' + [char]0x0131 + 'nda hedefi se' + [char]0x00E7 + 'in.') 'warn'; Open-Page 'backup'; return $false }
    $script:BkRestic = $null
    if ((Get-BkRestic) -eq '') { Show-Toast ('' + [char]0x015E + 'ifreli yedek i' + [char]0x00E7 + 'in restic gerekli. Yedek sayfas' + [char]0x0131 + 'nda ' + [char]0x201C + 'restic' + [char]0x2019 + 'i kur (winget)' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n.') 'warn'; Open-Page 'backup'; return $false }
    return $true
}

function Start-ResticBackup([bool]$Preview) {
    $st = $script:Settings
    if (@($st.BackupSources).Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce Yedek sayfas' + [char]0x0131 + 'nda yedeklenecek klas' + [char]0x00F6 + 'rleri se' + [char]0x00E7 + 'in.') 'warn'; Open-Page 'backup'; return }
    if (-not (Test-ResticReady)) { return }
    $script:ResticPreview = $Preview
    $isNew = -not (Test-ResticRepo (Get-ResticRepoPath ([string]$st.BackupDest)))
    if ($isNew) {
        $txt = "Bu hedefte hen$([char]0x00FC)z $([char]0x015F)ifreli yedek deposu yok; ilk yedekte olu$([char]0x015F)turulur. Bir parola belirleyin (en az 8 karakter).`r`n`r`nPAROLAYI UNUTURSANIZ yede$([char]0x011F)e eri$([char]0x015F)menin hi$([char]0x00E7)bir yolu yoktur; parolay$([char]0x0131) ayr$([char]0x0131)ca g$([char]0x00FC)venli bir yere yaz$([char]0x0131)n."
        $conf = $true
    } else {
        $txt = ('' + [char]0x015E + 'ifreli yede' + [char]0x011F + 'in parolas' + [char]0x0131 + 'n' + [char]0x0131 + ' girin.')
        $conf = $false
    }
    Show-Password ('' + [char]0x015E + 'ifreli yedek') $txt $conf {
        param($pw)
        $pwv = [string]$pw
        $lbl = ('' + [char]0x015E + 'ifreli yedek')
        if ($script:ResticPreview) { $lbl = ('' + [char]0x015E + 'ifreli yedek ' + [char]0x00F6 + 'nizlemesi') }
        [void](Start-Async 'ResticBackup' 'Job_ResticBackup' @{ Preview = $script:ResticPreview; Sources = @(); Dest = ''; Password = $pwv } {
            param($r)
            $script:Settings = Get-Settings
            if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('' + [char]0x015E + 'ifreli yedekleme tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n (parola yanl' + [char]0x0131 + '' + [char]0x015F + ' olabilir).') 'bad'; return }
            if ($script:ResticPreview -eq $true) {
                Show-Toast (('' + [char]0x00D6 + 'nizleme: yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + [string][int]$r.Files + ' dosya (' + (Format-Size ([double]$r.Bytes)) + (') yedeklenecek. Hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '.')) 'info'
                return
            }
            $msg = ('' + [char]0x015E + 'ifreli yedek tamamland' + [char]0x0131 + ': ') + [string][int]$r.Files + ' dosya, ' + (Format-Size ([double]$r.Bytes)) + ', depoya ' + (Format-Size ([double]$r.Added)) + ' eklendi'
            Show-Toast $msg 'good'
            Show-Notify ('Yedekleme tamamland' + [char]0x0131 + '') $msg 'good'
            if ($script:UiState.Page -eq 'panel') { Update-QuickStatus }
            if ($script:UiState.Page -eq 'backup' -and $script:BkTab -eq 'files') { Render-BkFiles }
        } $lbl)
    }
}

function Start-ResticSnaps {
    if (-not (Test-ResticReady)) { return }
    if (-not (Test-ResticRepo (Get-ResticRepoPath ([string]$script:Settings.BackupDest)))) { Show-Toast ('Bu hedefte hen' + [char]0x00FC + 'z ' + [char]0x015F + 'ifreli yedek yok. ' + [char]0x00D6 + 'nce bir yedek al' + [char]0x0131 + 'n.') 'info'; return }
    Show-Password ('Yedek s' + [char]0x00FC + 'r' + [char]0x00FC + 'mleri') ('' + [char]0x015E + 'ifreli yede' + [char]0x011F + 'in parolas' + [char]0x0131 + 'n' + [char]0x0131 + ' girin.') $false {
        param($pw)
        $script:ResticPw = [string]$pw
        [void](Start-Async 'ResticSnaps' 'Job_ResticSnapshots' @{ Dest = ''; Password = $script:ResticPw } {
            param($r)
            if ($null -eq $r -or $r.Ok -ne $true) { $script:ResticPw = ''; $script:BkSnaps = $null; Show-Toast ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'mler okunamad' + [char]0x0131 + ' (parola yanl' + [char]0x0131 + '' + [char]0x015F + ' olabilir); g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
            $script:BkSnaps = @($r.Rows)
            if ($script:BkTab -eq 'files') { Render-BkSnaps }
        } ('Yedek s' + [char]0x00FC + 'r' + [char]0x00FC + 'mleri okunuyor'))
    }
}

function Init-BkFiles {
    $ui.bk_ResticGet.Add_Click({
        Invoke-Safe {
            [void](Start-Async 'Foss' 'Job_WingetInstall' @{ Id = 'restic.restic' } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast 'restic kuruldu.' 'good' } else { Show-Toast ('restic kurulamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
                $script:BkRestic = $null
                if ($script:BkTab -eq 'files') { Show-OnlyBar 'bk' (Get-BkFilesBar); Render-BkFiles }
            } 'restic kuruluyor')
        } 'Kur'
    })
    $ui.bk_ResticSnaps.Add_Click({ Invoke-Safe { Start-ResticSnaps } ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'mler') })
    $ui.bk_ModeRestic.Add_Click({ Invoke-Safe { Update-BkMode 'Restic' } ('Y' + [char]0x00F6 + 'ntem') })
    $ui.bk_BlRefresh.Add_Click({ Invoke-Safe { $script:BkBl = $null; Render-BkBl } 'Yenile' })
    $ui.bk_BlWeb.Add_Click({ Invoke-Safe { Open-Url 'https://account.microsoft.com/devices/recoverykey' } ('A' + [char]0x00E7 + '') })
}

# ------------------------------------------------------------------
#  Ilk acilis: "Bu bilgisayari nasil kullaniyorsun?" ve Ayarlar > Kullanim turu
#  Secim hicbir ayari kendiliginden uygulamaz; yalnizca ilgili sayfayi acar (uygulamadan once onizleme ve onay vardir).
# ------------------------------------------------------------------
$script:UseCases = [ordered]@{
    home    = @{ T = ('Ev kullan' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + ' / eski bilgisayar'); D = ('' + [char]0x201C + 'Bilgisayar ' + [char]0x00E7 + 'ok yava' + [char]0x015F + ', disk %100.' + [char]0x201D + ' ' + [char]0x00D6 + 'nerilen profil, ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' temizli' + [char]0x011F + 'i, ' + [char]0x00F6 + 'ncesi/sonras' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm.'); Page = 'optimize'; Sub = ''; Hint = ('Optimizasyon sayfas' + [char]0x0131 + 'nda ' + [char]0x00F6 + 'nerilen ayarlar i' + [char]0x015F + 'aretli geliyor; ' + [char]0x00F6 + 'nizleyip uygulayabilirsiniz.') }
    gamer   = @{ T = 'Oyuncu'; D = ('Tak' + [char]0x0131 + 'lma, arka plan kayd' + [char]0x0131 + ', s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler. Oyun Modu, Game DVR kapatma, s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' yede' + [char]0x011F + 'i.'); Page = 'gaming'; Sub = 'tweaks'; Hint = ('Oyun ayarlar' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '. G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' bir bilgisayarda gereksiz bir ' + [char]0x015F + 'eyi kapatman' + [char]0x0131 + 'z gerekmez; yaln' + [char]0x0131 + 'zca i' + [char]0x015F + 'e yarayanlar' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') }
    privacy = @{ T = ('Gizlilik merakl' + [char]0x0131 + 's' + [char]0x0131 + ''); D = ('Telemetri, reklam, kim neyi dinliyor. Gizlilik denetimi, kamera/mikrofon ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i, a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak alternatifler.'); Page = 'optimize'; Sub = 'Gizlilik'; Hint = ('Gizlilik ayarlar' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '. Kamera/mikrofon ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i i' + [char]0x00E7 + 'in G' + [char]0x00FC + 'venlik sayfas' + [char]0x0131 + 'ndaki gizlilik izine de bak' + [char]0x0131 + 'n.') }
    helper  = @{ T = ('Ailenin ' + [char]0x201C + 'bilgisayarc' + [char]0x0131 + 's' + [char]0x0131 + '' + [char]0x201D + ''); D = ('Ba' + [char]0x015F + 'kas' + [char]0x0131 + 'n' + [char]0x0131 + 'n bilgisayar' + [char]0x0131 + 'n' + [char]0x0131 + ' h' + [char]0x0131 + 'zl' + [char]0x0131 + 'ca toparlamak. D' + [char]0x0131 + '' + [char]0x015F + 'a aktar' + [char]0x0131 + 'labilir rapor, profil dosyas' + [char]0x0131 + '.'); Page = 'company'; Sub = 'report'; Hint = ('Rapor ve envanter a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '. Bir bilgisayarda uygulad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z ayarlar' + [char]0x0131 + ' Profil sekmesinden dosyaya al' + [char]0x0131 + 'p di' + [char]0x011F + 'erine aktarabilirsiniz.') }
    office  = @{ T = ('' + [char]0x015E + 'irket / ofis bilgisayar' + [char]0x0131 + ''); D = ('Envanter, ' + [char]0x015F + 'irket ilkeleri, zamanlanm' + [char]0x0131 + '' + [char]0x015F + ' bak' + [char]0x0131 + 'm, ayar profili.'); Page = 'company'; Sub = 'policy'; Hint = ('' + [char]0x015E + 'irket ilkeleri a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '. ' + [char]0x00D6 + 'nce ' + [char]0x00F6 + 'nizleyin; hi' + [char]0x00E7 + 'bir ilke Windows Update, Defender, g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' ya da UAC' + [char]0x2019 + 'yi kapatmaz.') }
}

function Get-UseCaseTitle([string]$Key) {
    if ($script:UseCases.Contains($Key)) { return [string]$script:UseCases[$Key].T }
    return ('Se' + [char]0x00E7 + 'ilmedi')
}

function Apply-UseCase([string]$Key, [bool]$Navigate) {
    if (-not $script:UseCases.Contains($Key)) { return }
    $script:Settings.UseCase = $Key
    $script:Settings.FirstRunDone = $true
    Save-Settings $script:Settings
    if ($Navigate) {
        $u = $script:UseCases[$Key]
        Open-Page ([string]$u.Page) ([string]$u.Sub)
        Show-Toast ([string]$u.Hint) 'info'
    }
    if ($null -ne $ui.st_UseCaseText) { $ui.st_UseCaseText.Text = (Tr $((Get-UseCaseTitle $Key))) }
}

function Show-UseCaseChoice([bool]$Navigate) {
    $opts = New-Object System.Collections.ArrayList
    foreach ($k in @($script:UseCases.Keys)) { [void]$opts.Add(@{ Key = [string]$k; Title = [string]$script:UseCases[$k].T; Detail = [string]$script:UseCases[$k].D }) }
    $script:ChoiceNavigate = $Navigate
    Show-Choice ('Bu bilgisayar' + [char]0x0131 + ' nas' + [char]0x0131 + 'l kullan' + [char]0x0131 + 'yorsun?') ('Se' + [char]0x00E7 + 'iminize g' + [char]0x00F6 + 're size uygun sayfay' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar' + [char]0x0131 + 'm. Hi' + [char]0x00E7 + 'bir ayar kendili' + [char]0x011F + 'inden de' + [char]0x011F + 'i' + [char]0x015F + 'mez; uygulamadan ' + [char]0x00F6 + 'nce her zaman ' + [char]0x00F6 + 'nizleme ve onay vard' + [char]0x0131 + 'r. Bunu Ayarlar sayfas' + [char]0x0131 + 'ndan de' + [char]0x011F + 'i' + [char]0x015F + 'tirebilirsiniz.') $opts.ToArray() ('' + [char]0x015E + 'imdi de' + [char]0x011F + 'il') {
        param($key)
        Apply-UseCase ([string]$key) $script:ChoiceNavigate
    }
}

# Secenek dugmeleri gosteren kutu. Options: @{ Key; Title; Detail }. OnPick secilen anahtari alir.
function Show-Choice([string]$Title, [string]$Text, $Options, [string]$CancelText, [scriptblock]$OnPick) {
    Show-Overlay $Title $Text 'Tamam' $true $false $false '' $null
    $ui.OvCancel.Content = (Tr $($CancelText))
    $ui.OvOk.Visibility = $script:VisOff
    $ui.OvChoices.Children.Clear()
    $script:ChoiceAction = $OnPick
    foreach ($o in @($Options)) {
        $b = New-Object System.Windows.Controls.Button
        $b.Style = $script:Win.FindResource('BtnChoice')
        $b.Tag = [string]$o.Key
        $b.Margin = New-Object System.Windows.Thickness(0, 0, 0, 8)
        $sp = New-Object System.Windows.Controls.StackPanel
        $t1 = New-Object System.Windows.Controls.TextBlock
        $t1.Text = (Tr $([string]$o.Title))
        $t1.FontWeight = [System.Windows.FontWeights]::SemiBold
        $t1.Foreground = (Get-Br 'BrText')
        $t2 = New-Object System.Windows.Controls.TextBlock
        $t2.Text = (Tr $([string]$o.Detail))
        $t2.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $t2.FontSize = 11.5
        $t2.Margin = New-Object System.Windows.Thickness(0, 2, 0, 0)
        $t2.Foreground = (Get-Br 'BrDim')
        [void]$sp.Children.Add($t1)
        [void]$sp.Children.Add($t2)
        $b.Content = (Tr $($sp))
        [System.Windows.Automation.AutomationProperties]::SetName($b, (Tr ([string]$o.Title)))
        [System.Windows.Automation.AutomationProperties]::SetHelpText($b, (Tr ([string]$o.Detail)))
        $b.Add_Click({ param($s, $e) Invoke-Safe { Complete-Choice ([string]$s.Tag) } ('Se' + [char]0x00E7 + 'im') })
        [void]$ui.OvChoices.Children.Add($b)
    }
    $ui.OvChoices.Visibility = $script:VisOn
}

function Complete-Choice([string]$Key) {
    $act = $script:ChoiceAction
    $script:ChoiceAction = $null
    Close-Overlay
    if ($null -ne $act) {
        try { & $act $Key } catch { Show-Crash $_ ('Se' + [char]0x00E7 + 'im') }
    }
}

# Pencere gorununce bir kez sorar; soruldu diye isaretlenir (her acilista rahatsiz etmez).
function Initialize-FirstRun {
    if ($script:Settings.FirstRunDone -eq $true) { return }
    $script:FirstRunTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:FirstRunTimer.Interval = [TimeSpan]::FromSeconds(3)
    $script:FirstRunTimer.Add_Tick({
        try {
            if ($script:Settings.FirstRunDone -eq $true) { $script:FirstRunTimer.Stop(); return }
            if (-not $script:Win.IsVisible) { return }
            if ($ui.Overlay.Visibility -eq $script:VisOn -or $null -ne $script:Cur) { return }
            $script:FirstRunTimer.Stop()
            $script:Settings.FirstRunDone = $true
            Save-Settings $script:Settings
            Show-UseCaseChoice $true
        } catch { Write-CrashLog ('FirstRunTimer: ' + $_.Exception.Message) }
    })
    $script:FirstRunTimer.Start()
}


# ---------------- Sayfa XAML: guc, oyun, akilli bakim ----------------
# ==================================================================
#  SAYFA XAML: Guc, Oyun, Akilli bakim; adim secici satirlari; mini izleyici penceresi
# ==================================================================

# Bir degerli adim secici satiri:  baslik/aciklama  < deger >
$script:Row_Step1 = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Style="{DynamicResource Row}" Margin="0,0,0,5" Padding="10,6">
  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="Auto"/>
    </Grid.ColumnDefinitions>
    <StackPanel Grid.Column="0" VerticalAlignment="Center">
      <TextBlock Text="@@Title@@" Style="{DynamicResource TxtBody}" FontWeight="SemiBold" TextWrapping="Wrap"/>
      <TextBlock x:Name="Det" Text="@@Detail@@" Style="{DynamicResource TxtDim}" FontSize="11.5" TextWrapping="Wrap" Margin="0,2,0,0"/>
    </StackPanel>
    <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center" Margin="12,0,0,0">
      <Button x:Name="Dn" Content="&#x2039;" Style="{DynamicResource BtnMini}" Width="28"/>
      <TextBlock x:Name="Val" Text="@@Value@@" MinWidth="170" TextAlignment="Center" VerticalAlignment="Center" Style="{DynamicResource TxtBody}" Foreground="{DynamicResource BrAccent}" Margin="6,0"/>
      <Button x:Name="Up" Content="&#x203A;" Style="{DynamicResource BtnMini}" Width="28"/>
    </StackPanel>
  </Grid>
</Border>
'@

# Iki degerli adim secici (guc plani: fiste / pilde)
$script:Row_Step2 = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Style="{DynamicResource Row}" Margin="0,0,0,5" Padding="10,6">
  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="Auto"/>
    </Grid.ColumnDefinitions>
    <StackPanel Grid.Column="0" VerticalAlignment="Center">
      <TextBlock Text="@@Title@@" Style="{DynamicResource TxtBody}" FontWeight="SemiBold" TextWrapping="Wrap"/>
      <TextBlock x:Name="Det" Text="@@Detail@@" Style="{DynamicResource TxtDim}" FontSize="11" TextWrapping="Wrap" Margin="0,2,0,0"/>
    </StackPanel>
    <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center" Margin="10,0,0,0">
      <TextBlock Text="Fi&#x015F;te" Style="{DynamicResource TxtDim}" FontSize="11" VerticalAlignment="Center" Margin="0,0,6,0"/>
      <Button x:Name="AcDn" Content="&#x2039;" Style="{DynamicResource BtnMini}" Width="26"/>
      <TextBlock x:Name="AcVal" Text="" MinWidth="112" TextAlignment="Center" VerticalAlignment="Center" Style="{DynamicResource TxtBody}" Foreground="{DynamicResource BrAccent}" Margin="4,0"/>
      <Button x:Name="AcUp" Content="&#x203A;" Style="{DynamicResource BtnMini}" Width="26"/>
    </StackPanel>
    <StackPanel x:Name="DcBox" Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center" Margin="14,0,0,0">
      <TextBlock Text="Pilde" Style="{DynamicResource TxtDim}" FontSize="11" VerticalAlignment="Center" Margin="0,0,6,0"/>
      <Button x:Name="DcDn" Content="&#x2039;" Style="{DynamicResource BtnMini}" Width="26"/>
      <TextBlock x:Name="DcVal" Text="" MinWidth="112" TextAlignment="Center" VerticalAlignment="Center" Style="{DynamicResource TxtBody}" Foreground="{DynamicResource BrAccent2}" Margin="4,0"/>
      <Button x:Name="DcUp" Content="&#x203A;" Style="{DynamicResource BtnMini}" Width="26"/>
    </StackPanel>
  </Grid>
</Border>
'@

# Dugme dizisi satiri (sablonlar vb.)
$script:Row_Buttons = @'
<WrapPanel xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="2,2,0,8"/>
'@

# Metin girisli satir
$script:Row_Input = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Style="{DynamicResource Row}" Margin="0,0,0,5" Padding="10,6">
  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="Auto"/>
    </Grid.ColumnDefinitions>
    <StackPanel Grid.Column="0" VerticalAlignment="Center">
      <TextBlock Text="@@Title@@" Style="{DynamicResource TxtBody}" FontWeight="SemiBold"/>
      <TextBlock Text="@@Detail@@" Style="{DynamicResource TxtDim}" FontSize="11.5" TextWrapping="Wrap" Margin="0,2,0,0"/>
    </StackPanel>
    <TextBox x:Name="Inp" Grid.Column="1" Width="250" Text="@@Value@@" VerticalAlignment="Center" Margin="12,0,0,0"/>
  </Grid>
</Border>
'@

# ---------------- Guc ----------------
$script:Page_power = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="pw_Title" Text="G&#x00FC;&#x00E7;" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="pw_Desc" Text="G&#x00FC;&#x00E7; plan&#x0131;n&#x0131; se&#x00E7;in, ge&#x00E7;meden &#x00F6;nce neyin de&#x011F;i&#x015F;ece&#x011F;ini g&#x00F6;r&#x00FC;n, kendi plan&#x0131;n&#x0131;z&#x0131; olu&#x015F;turun. &#x00D6;nceki plan kaydedilir; her de&#x011F;i&#x015F;iklik Ge&#x00E7;mi&#x015F; sayfas&#x0131;ndan geri al&#x0131;n&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,4,0,0"/>
  </StackPanel>
  <Border Grid.Row="1" Style="{DynamicResource Card}" Padding="14,10" Margin="0,0,0,10">
    <Grid>
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>
      <ContentControl Grid.Column="0" Style="{DynamicResource Icon}" Tag="{DynamicResource IcoPower}" Width="26" Height="26" Foreground="{DynamicResource BrAccent}" Margin="0,0,14,0" VerticalAlignment="Center"/>
      <StackPanel Grid.Column="1" VerticalAlignment="Center">
        <TextBlock x:Name="pw_LivePlan" Text="G&#x00FC;&#x00E7; durumu okunuyor..." Style="{DynamicResource TxtBody}" FontWeight="SemiBold"/>
        <TextBlock x:Name="pw_LiveText" Text="" Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,2,0,0"/>
        <ProgressBar x:Name="pw_Bat" Height="5" Margin="0,6,0,0" Maximum="100" Value="0" Visibility="Collapsed"/>
      </StackPanel>
      <Button x:Name="pw_Refresh" Grid.Column="2" Content="Yenile" Style="{DynamicResource BtnGhost}" VerticalAlignment="Center" Margin="10,0,0,0"/>
    </Grid>
  </Border>
  <WrapPanel x:Name="pw_Tabs" Grid.Row="2" Margin="0,0,0,8">
    <RadioButton x:Name="pw_Tab_plans" Content="G&#x00FC;&#x00E7; planlar&#x0131;" Tag="plans" GroupName="pw_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="pw_Tab_custom" Content="&#x00D6;zel plan olu&#x015F;tur" Tag="custom" GroupName="pw_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="pw_Tab_more" Content="Ek ayarlar ve raporlar" Tag="more" GroupName="pw_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="pw_Bar" Grid.Row="3" Margin="0,0,0,4">
    <Button x:Name="pw_CPrev" Content="&#x00D6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="pw_CMake" Content="Olu&#x015F;tur ve etkinle&#x015F;tir" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="pw_CSave" Content="Yaln&#x0131;zca olu&#x015F;tur" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="pw_TPrev" Content="Se&#x00E7;ilenleri &#x00F6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="pw_TApply" Content="Se&#x00E7;ilenleri uygula" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed"/>
  </WrapPanel>
  <Grid Grid.Row="4">
    <Border x:Name="pw_ListCard" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="pw_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="pw_List"/>
      </ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="pw_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

# ---------------- Oyun ----------------
$script:Page_gaming = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="gm_Title" Text="Oyun" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="gm_Desc" Text="Canl&#x0131; donan&#x0131;m g&#x00F6;stergeleri, y&#x00FC;kl&#x00FC; oyunlar&#x0131;n&#x0131;z ve oyun ayarlar&#x0131;. Daha d&#x00FC;&#x015F;&#x00FC;k gecikme, daha y&#x00FC;ksek ve kararl&#x0131; FPS i&#x00E7;in yaln&#x0131;zca Windows&#x2019;un kendi ayarlar&#x0131; kullan&#x0131;l&#x0131;r; hepsi geri al&#x0131;nabilir." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,4,0,0"/>
  </StackPanel>
  <Border Grid.Row="1" Style="{DynamicResource Card}" Padding="12,10" Margin="0,0,0,10">
    <Grid>
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="*"/>
      </Grid.ColumnDefinitions>
      <StackPanel Grid.Column="0" HorizontalAlignment="Center" Margin="0,0,10,0">
        <Grid Width="84" Height="80">
          <Ellipse Width="76" Height="76" Stroke="{DynamicResource BrLine}" StrokeThickness="7" StrokeDashArray="23.23,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <Ellipse x:Name="gm_GCpu" Width="76" Height="76" Stroke="{DynamicResource BrCpu}" StrokeThickness="7" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5" Opacity="0">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
            <TextBlock x:Name="gm_VCpu" Text="--" FontSize="18" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
            <TextBlock Text="CPU" FontSize="10" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
          </StackPanel>
        </Grid>
        <TextBlock x:Name="gm_DCpu" Text="" FontSize="10.5" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="96"/>
      </StackPanel>
      <StackPanel Grid.Column="1" HorizontalAlignment="Center" Margin="0,0,10,0">
        <Grid Width="84" Height="80">
          <Ellipse Width="76" Height="76" Stroke="{DynamicResource BrLine}" StrokeThickness="7" StrokeDashArray="23.23,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <Ellipse x:Name="gm_GRam" Width="76" Height="76" Stroke="{DynamicResource BrRam}" StrokeThickness="7" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5" Opacity="0">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
            <TextBlock x:Name="gm_VRam" Text="--" FontSize="18" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
            <TextBlock Text="RAM" FontSize="10" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
          </StackPanel>
        </Grid>
        <TextBlock x:Name="gm_DRam" Text="" FontSize="10.5" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="96"/>
      </StackPanel>
      <StackPanel Grid.Column="2" HorizontalAlignment="Center" Margin="0,0,10,0">
        <Grid Width="84" Height="80">
          <Ellipse Width="76" Height="76" Stroke="{DynamicResource BrLine}" StrokeThickness="7" StrokeDashArray="23.23,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <Ellipse x:Name="gm_GGpu" Width="76" Height="76" Stroke="{DynamicResource BrGpu}" StrokeThickness="7" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5" Opacity="0">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
            <TextBlock x:Name="gm_VGpu" Text="--" FontSize="18" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
            <TextBlock Text="GPU" FontSize="10" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
          </StackPanel>
        </Grid>
        <TextBlock x:Name="gm_DGpu" Text="" FontSize="10.5" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="96"/>
      </StackPanel>
      <StackPanel Grid.Column="3" HorizontalAlignment="Center" Margin="0,0,10,0">
        <Grid Width="84" Height="80">
          <Ellipse Width="76" Height="76" Stroke="{DynamicResource BrLine}" StrokeThickness="7" StrokeDashArray="23.23,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <Ellipse x:Name="gm_GDisk" Width="76" Height="76" Stroke="{DynamicResource BrDisk}" StrokeThickness="7" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5" Opacity="0">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
            <TextBlock x:Name="gm_VDisk" Text="--" FontSize="18" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
            <TextBlock Text="D&#x0130;SK" FontSize="10" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
          </StackPanel>
        </Grid>
        <TextBlock x:Name="gm_DDisk" Text="" FontSize="10.5" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="96"/>
      </StackPanel>
      <StackPanel Grid.Column="4" HorizontalAlignment="Center" Margin="0,0,10,0">
        <Grid Width="84" Height="80">
          <Ellipse Width="76" Height="76" Stroke="{DynamicResource BrLine}" StrokeThickness="7" StrokeDashArray="23.23,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <Ellipse x:Name="gm_GTemp" Width="76" Height="76" Stroke="{DynamicResource BrWarn}" StrokeThickness="7" StrokeDashArray="0.001,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5" Opacity="0">
            <Ellipse.RenderTransform><RotateTransform Angle="135"/></Ellipse.RenderTransform>
          </Ellipse>
          <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
            <TextBlock x:Name="gm_VTemp" Text="--" FontSize="18" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" HorizontalAlignment="Center"/>
            <TextBlock Text="ISI" FontSize="10" Foreground="{DynamicResource BrDim}" HorizontalAlignment="Center"/>
          </StackPanel>
        </Grid>
        <TextBlock x:Name="gm_DTemp" Text="" FontSize="10.5" Foreground="{DynamicResource BrFaint}" HorizontalAlignment="Center" TextAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="96"/>
      </StackPanel>
      <StackPanel Grid.Column="5" VerticalAlignment="Center" Margin="16,0,0,0">
        <TextBlock x:Name="gm_Running" Text="&#x015E;u an &#x00E7;al&#x0131;&#x015F;an oyun yok" Style="{DynamicResource TxtBody}" FontWeight="SemiBold" TextWrapping="Wrap"/>
        <TextBlock x:Name="gm_RunInfo" Text="Oyun kipi: g&#x00FC;&#x00E7; plan&#x0131;n&#x0131; en y&#x00FC;ksek performansa al&#x0131;r, a&#x00E7;&#x0131;ksa odak kipini ba&#x015F;lat&#x0131;r ve &#x00E7;al&#x0131;&#x015F;an oyunun &#x00F6;nceli&#x011F;ini y&#x00FC;kseltir." Style="{DynamicResource TxtDim}" FontSize="11.5" TextWrapping="Wrap" Margin="0,3,0,8"/>
        <WrapPanel>
          <Button x:Name="gm_Boost" Content="Oyun kipini a&#x00E7;" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,4"/>
          <Button x:Name="gm_Normal" Content="Normale d&#x00F6;n" Style="{DynamicResource BtnGhost}" Margin="0,0,8,4"/>
        </WrapPanel>
      </StackPanel>
    </Grid>
  </Border>
  <WrapPanel x:Name="gm_Tabs" Grid.Row="2" Margin="0,0,0,8">
    <RadioButton x:Name="gm_Tab_games" Content="Oyunlar&#x0131;m" Tag="games" GroupName="gm_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="gm_Tab_tweaks" Content="Oyun ayarlar&#x0131;" Tag="tweaks" GroupName="gm_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="gm_Bar" Grid.Row="3" Margin="0,0,0,4">
    <Button x:Name="gm_Scan" Content="Yeniden tara" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6"/>
    <Button x:Name="gm_Add" Content="Oyun ekle..." Style="{DynamicResource BtnGhost}" Margin="0,0,8,6"/>
    <Button x:Name="gm_ClearCustom" Content="Elle eklenenleri listeden &#x00E7;&#x0131;kar" Style="{DynamicResource BtnMini}" Margin="0,0,8,6"/>
    <Button x:Name="gm_TPrev" Content="Se&#x00E7;ilenleri &#x00F6;nizle" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="gm_TApply" Content="Se&#x00E7;ilenleri uygula" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed"/>
  </WrapPanel>
  <Grid Grid.Row="4">
    <Border x:Name="gm_ListCard" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="gm_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="gm_List"/>
      </ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="gm_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

# ---------------- Akilli bakim ----------------
$script:Page_smart = @'
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,6,0">
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="Auto"/>
    <RowDefinition Height="*"/>
    <RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <StackPanel Grid.Row="0" Margin="0,0,0,10">
    <TextBlock x:Name="sm_Title" Text="Ak&#x0131;ll&#x0131; bak&#x0131;m" Style="{DynamicResource TxtH1}"/>
    <TextBlock x:Name="sm_Desc" Text="Bu bilgisayar&#x0131;n kendi &#x00F6;l&#x00E7;&#x00FC;mleriyle karar veren yerel bak&#x0131;m: performans art&#x0131;r&#x0131;c&#x0131;, &#x0131;s&#x0131; y&#x00F6;netimi, gizlilik kalkan&#x0131;, s&#x0131;f&#x0131;r dokunu&#x015F;, otomasyon kurallar&#x0131; ve donan&#x0131;m &#x00F6;mr&#x00FC;. Hi&#x00E7;bir veri d&#x0131;&#x015F;ar&#x0131; g&#x00F6;nderilmez, bulut kullan&#x0131;lmaz; hepsi kapal&#x0131; gelir." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,4,0,0"/>
  </StackPanel>
  <Border Grid.Row="1" Style="{DynamicResource Card}" Padding="14,10" Margin="0,0,0,10">
    <Grid>
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>
      <Ellipse x:Name="sm_Dot" Grid.Column="0" Width="12" Height="12" Fill="{DynamicResource BrFaint}" VerticalAlignment="Center" Margin="0,0,12,0"/>
      <StackPanel Grid.Column="1" VerticalAlignment="Center">
        <TextBlock x:Name="sm_State" Text="Ak&#x0131;ll&#x0131; bak&#x0131;m kapal&#x0131;" Style="{DynamicResource TxtBody}" FontWeight="SemiBold"/>
        <TextBlock x:Name="sm_StateText" Text="A&#x00E7;&#x0131;nca izleyiciler ve kurallar uygulama a&#x00E7;&#x0131;kken (tepsiye k&#x00FC;&#x00E7;&#x00FC;lt&#x00FC;lm&#x00FC;&#x015F;ken de) &#x00E7;al&#x0131;&#x015F;&#x0131;r." Style="{DynamicResource TxtDim}" TextWrapping="Wrap" Margin="0,2,0,0"/>
      </StackPanel>
      <Button x:Name="sm_Master" Grid.Column="2" Content="A&#x00E7;" Style="{DynamicResource BtnPrimary}" VerticalAlignment="Center" Margin="10,0,0,0"/>
    </Grid>
  </Border>
  <WrapPanel x:Name="sm_Tabs" Grid.Row="2" Margin="0,0,0,8">
    <RadioButton x:Name="sm_Tab_care" Content="Ak&#x0131;ll&#x0131; bak&#x0131;m" Tag="care" GroupName="sm_tabs" Style="{DynamicResource Chip}" IsChecked="True"/>
    <RadioButton x:Name="sm_Tab_rules" Content="Otomasyon kurallar&#x0131;" Tag="rules" GroupName="sm_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sm_Tab_life" Content="Donan&#x0131;m sa&#x011F;l&#x0131;&#x011F;&#x0131; ve &#x00F6;mr&#x00FC;" Tag="life" GroupName="sm_tabs" Style="{DynamicResource Chip}"/>
    <RadioButton x:Name="sm_Tab_widget" Content="Mini izleyici" Tag="widget" GroupName="sm_tabs" Style="{DynamicResource Chip}"/>
  </WrapPanel>
  <WrapPanel x:Name="sm_Bar" Grid.Row="3" Margin="0,0,0,4">
    <Button x:Name="sm_RuleNew" Content="Yeni kural" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="sm_RuleSave" Content="Kural&#x0131; kaydet" Style="{DynamicResource BtnPrimary}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="sm_RuleCancel" Content="Vazge&#x00E7;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="sm_LifeRun" Content="Yeniden &#x00F6;l&#x00E7;" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
    <Button x:Name="sm_BatRep" Content="Pil raporu" Style="{DynamicResource BtnGhost}" Margin="0,0,8,6" Visibility="Collapsed"/>
  </WrapPanel>
  <Grid Grid.Row="4">
    <Border x:Name="sm_ListCard" Style="{DynamicResource Card}" Padding="8">
      <ScrollViewer x:Name="sm_Scroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel x:Name="sm_List"/>
      </ScrollViewer>
    </Border>
  </Grid>
  <DockPanel Grid.Row="5" Margin="0,8,0,0" LastChildFill="True">
    <TextBlock x:Name="sm_Foot" Text="" Style="{DynamicResource TxtDim}" VerticalAlignment="Center" TextWrapping="Wrap" Margin="2,0,10,6"/>
  </DockPanel>
</Grid>
'@

# ---------------- mini izleyici (ayri, her zaman ustte, suruklenebilir pencere) ----------------
$script:XamlWidget = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Multimizer mini izleyici" WindowStyle="None" AllowsTransparency="True" Background="Transparent" Topmost="True"
        ShowInTaskbar="False" ResizeMode="NoResize" SizeToContent="WidthAndHeight" ShowActivated="False" FontFamily="Segoe UI">
  <Border x:Name="wd_Root" CornerRadius="12" Padding="12,9,12,10" Background="#E60E1427" BorderBrush="#2FE0B5" BorderThickness="1">
    <StackPanel MinWidth="196">
      <DockPanel Margin="0,0,0,6">
        <Button x:Name="wd_Close" DockPanel.Dock="Right" Cursor="Hand" ToolTip="Kapat" Focusable="False">
          <Button.Template>
            <ControlTemplate TargetType="Button">
              <TextBlock Text="&#x00D7;" FontSize="15" Foreground="#8591B8" Padding="6,0,0,0"/>
            </ControlTemplate>
          </Button.Template>
        </Button>
        <TextBlock x:Name="wd_Head" Text="MULTIMIZER" FontSize="10.5" FontWeight="SemiBold" Foreground="#2FE0B5" VerticalAlignment="Center"/>
      </DockPanel>
      <Grid Margin="0,2,0,2">
        <Grid.ColumnDefinitions><ColumnDefinition Width="62"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <TextBlock Grid.Column="0" Text="&#x0130;&#x015F;lemci" FontSize="11" Foreground="#8591B8" VerticalAlignment="Center"/>
        <Grid Grid.Column="1" Height="5" Width="84" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="0,0,8,0">
          <Border Background="#222C52" CornerRadius="2.5"/>
          <Border x:Name="wd_BCpu" Background="#4FA3FF" CornerRadius="2.5" HorizontalAlignment="Left" Width="0"/>
        </Grid>
        <TextBlock x:Name="wd_VCpu" Grid.Column="2" Text="--" FontSize="11.5" FontWeight="SemiBold" Foreground="#E2E8F8" MinWidth="54" TextAlignment="Right" VerticalAlignment="Center"/>
      </Grid>
      <Grid Margin="0,2,0,2">
        <Grid.ColumnDefinitions><ColumnDefinition Width="62"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <TextBlock Grid.Column="0" Text="Bellek" FontSize="11" Foreground="#8591B8" VerticalAlignment="Center"/>
        <Grid Grid.Column="1" Height="5" Width="84" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="0,0,8,0">
          <Border Background="#222C52" CornerRadius="2.5"/>
          <Border x:Name="wd_BRam" Background="#8C6BFF" CornerRadius="2.5" HorizontalAlignment="Left" Width="0"/>
        </Grid>
        <TextBlock x:Name="wd_VRam" Grid.Column="2" Text="--" FontSize="11.5" FontWeight="SemiBold" Foreground="#E2E8F8" MinWidth="54" TextAlignment="Right" VerticalAlignment="Center"/>
      </Grid>
      <Grid Margin="0,2,0,2">
        <Grid.ColumnDefinitions><ColumnDefinition Width="62"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <TextBlock Grid.Column="0" Text="Ekran k." FontSize="11" Foreground="#8591B8" VerticalAlignment="Center"/>
        <Grid Grid.Column="1" Height="5" Width="84" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="0,0,8,0">
          <Border Background="#222C52" CornerRadius="2.5"/>
          <Border x:Name="wd_BGpu" Background="#2FE0B5" CornerRadius="2.5" HorizontalAlignment="Left" Width="0"/>
        </Grid>
        <TextBlock x:Name="wd_VGpu" Grid.Column="2" Text="--" FontSize="11.5" FontWeight="SemiBold" Foreground="#E2E8F8" MinWidth="54" TextAlignment="Right" VerticalAlignment="Center"/>
      </Grid>
      <Grid Margin="0,2,0,2">
        <Grid.ColumnDefinitions><ColumnDefinition Width="62"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <TextBlock Grid.Column="0" Text="Disk" FontSize="11" Foreground="#8591B8" VerticalAlignment="Center"/>
        <Grid Grid.Column="1" Height="5" Width="84" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="0,0,8,0">
          <Border Background="#222C52" CornerRadius="2.5"/>
          <Border x:Name="wd_BDisk" Background="#E2A93F" CornerRadius="2.5" HorizontalAlignment="Left" Width="0"/>
        </Grid>
        <TextBlock x:Name="wd_VDisk" Grid.Column="2" Text="--" FontSize="11.5" FontWeight="SemiBold" Foreground="#E2E8F8" MinWidth="54" TextAlignment="Right" VerticalAlignment="Center"/>
      </Grid>
      <Grid Margin="0,2,0,2">
        <Grid.ColumnDefinitions><ColumnDefinition Width="62"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <TextBlock Grid.Column="0" Text="A&#x011F; &#x2193;/&#x2191;" FontSize="11" Foreground="#8591B8" VerticalAlignment="Center"/>
        <TextBlock x:Name="wd_VNet" Grid.Column="2" Text="--" FontSize="11.5" FontWeight="SemiBold" Foreground="#E2E8F8" MinWidth="54" TextAlignment="Right" VerticalAlignment="Center"/>
      </Grid>
      <Grid Margin="0,2,0,2">
        <Grid.ColumnDefinitions><ColumnDefinition Width="62"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <TextBlock Grid.Column="0" Text="S&#x0131;cakl&#x0131;k" FontSize="11" Foreground="#8591B8" VerticalAlignment="Center"/>
        <Grid Grid.Column="1" Height="5" Width="84" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="0,0,8,0">
          <Border Background="#222C52" CornerRadius="2.5"/>
          <Border x:Name="wd_BTemp" Background="#FF5C7C" CornerRadius="2.5" HorizontalAlignment="Left" Width="0"/>
        </Grid>
        <TextBlock x:Name="wd_VTemp" Grid.Column="2" Text="--" FontSize="11.5" FontWeight="SemiBold" Foreground="#E2E8F8" MinWidth="54" TextAlignment="Right" VerticalAlignment="Center"/>
      </Grid>
    </StackPanel>
  </Border>
</Window>
'@


# ---------------- Ekranlar: guc, oyun, akilli bakim, sikistirma ----------------
# ==================================================================
#  EKRANLAR: Guc, Oyun, Akilli bakim, Temizlik > Sikistir, mini izleyici; ortak adim secici ve katalog satirlari
# ==================================================================

# ---------------- ortak: adim secici ----------------
$script:StepState = @{}

$script:H_Step = { param($s, $e) Invoke-Safe { Move-Step ([string]$s.Tag.Key) ([int]$s.Tag.Dir) } ('Se' + [char]0x00E7 + 'im') }

function Update-StepText([string]$Key) {
    $st = $script:StepState[$Key]
    if ($null -eq $st -or $null -eq $st.Text) { return }
    $ch = @($st.Choices)
    if ($ch.Count -eq 0) { $st.Text.Text = (Tr $('')); return }
    $st.Text.Text = (Tr $([string]$ch[[int]$st.Index].L))
}

function Move-Step([string]$Key, [int]$Dir) {
    $st = $script:StepState[$Key]
    if ($null -eq $st) { return }
    $n = @($st.Choices).Count
    if ($n -eq 0) { return }
    $st.Index = (([int]$st.Index + $Dir) % $n + $n) % $n
    Update-StepText $Key
    if ($null -ne $st.OnChange) { & $st.OnChange $Key (@($st.Choices)[[int]$st.Index]) }
}

function Get-StepChoice([string]$Key) {
    $st = $script:StepState[$Key]
    if ($null -eq $st) { return $null }
    return @($st.Choices)[[int]$st.Index]
}

function Find-ChoiceIndex($Choices, $Value) {
    $arr = @($Choices)
    for ($i = 0; $i -lt $arr.Count; $i++) {
        $v = $arr[$i].V
        if ($null -eq $v -and $null -eq $Value) { return $i }
        if ($null -ne $v -and $null -ne $Value -and [string]$v -eq [string]$Value) { return $i }
    }
    return 0
}

function Add-Step1Row($Panel, [string]$Key, [string]$Title, [string]$Detail, $Choices, [int]$Index, [scriptblock]$OnChange) {
    $row = New-RowElement 'Step1' @{ Title = $Title; Detail = $Detail; Value = '' }
    $det = $row.FindName('Det')
    $script:StepState[$Key] = @{ Choices = @($Choices); Index = $Index; OnChange = $OnChange; Text = $row.FindName('Val'); Det = $det }
    Update-StepText $Key
    $dn = $row.FindName('Dn'); $up = $row.FindName('Up')
    $dn.Tag = @{ Key = $Key; Dir = -1 }
    $up.Tag = @{ Key = $Key; Dir = 1 }
    $dn.Add_Click($script:H_Step)
    $up.Add_Click($script:H_Step)
    if ($Detail -eq '') { $det.Visibility = $script:VisOff }
    [void]$Panel.Children.Add($row)
    return $row
}

function New-UiButton([string]$Text, [string]$Style, $Tag, [scriptblock]$OnClick, [string]$Tip = '') {
    $b = New-Object System.Windows.Controls.Button
    $b.Content = (Tr $($Text))
    $b.Style = $script:Win.FindResource($Style)
    $b.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 0, 8, 6
    $b.Tag = $Tag
    if ($Tip -ne '') { $b.ToolTip = (Tr $($Tip)) }
    $b.Add_Click($OnClick)
    return $b
}

# ---------------- ortak: katalog satirlari (Guc > Ek ayarlar, Oyun ayarlari, Gizlilik kalkani) ----------------
$script:CatStates = @{}

function Add-CatRows($Panel, $Ids) {
    $n = 0
    foreach ($id in @($Ids)) {
        $c = Get-CatalogItem ([string]$id)
        if ($null -eq $c) { continue }
        if (-not (Test-OsOk ([string]$c.OS) $sync.Profile)) { continue }
        $lv = Get-OpLevelInfo ([int]$c.Level)
        $det = [string]$c.Desc
        $flags = @()
        if ($c.Irrev -eq $true) { $flags += ('geri al' + [char]0x0131 + 'namaz') }
        if ($c.Reboot -eq $true) { $flags += ('yeniden ba' + [char]0x015F + 'latma gerekir') }
        if (-not (Test-WhenOk ([string]$c.When) $sync.Profile)) { $flags += ('bu bilgisayar i' + [char]0x00E7 + 'in gereksiz') }
        if ($flags.Count -gt 0) { $det += ('  [' + ($flags -join ', ') + ']') }
        $tag = [string]$lv.Text
        $br = [string]$lv.Br
        if ($script:CatStates.ContainsKey([string]$id) -and [int]$script:CatStates[[string]$id] -eq -3) { $tag = ('Windows engelliyor  ' + [char]0x00B7 + '  ') + $tag; $br = 'BrFaint' }
        elseif ($script:CatStates.ContainsKey([string]$id) -and [int]$script:CatStates[[string]$id] -eq 0) { $tag = ('uygulanm' + [char]0x0131 + '' + [char]0x015F + '  ' + [char]0x00B7 + '  ') + $tag; $br = 'BrFaint' }
        $row = New-ItemRow @{ Title = [string]$c.Title; Detail = $det; Tag = $tag; BrCol = $br } @{ Id = [string]$id } $true $false
        [void]$Panel.Children.Add($row)
        $n++
    }
    return $n
}

function Start-CatStates($Ids) {
    [void](Start-Async 'CatStates' 'Job_TweakStateIds' @{ Ids = @($Ids) } {
        param($r)
        if ($null -eq $r) { return }
        foreach ($k in @($r.States.Keys)) { $script:CatStates[[string]$k] = [int]$r.States[$k] }
        Update-CatViews
    } ('Ayarlar' + [char]0x0131 + 'n durumu okunuyor') $true $true)
}

# Durum olcumu bitince acik olan ilgili ekrani yeniler
function Update-CatViews {
    switch ([string]$script:UiState.Page) {
        'power' { if ($script:PwTab -eq 'more') { Render-PwMore } }
        'gaming' { if ($script:GmTab -eq 'tweaks') { Render-GmTweaks } }
    }
}

function Invoke-CatAfter {
    $script:CatStates = @{}
    $script:SmPriv = $null
    switch ([string]$script:UiState.Page) {
        'power' { if ($script:PwTab -eq 'more') { Start-CatStates $script:PwMoreIds } }
        'gaming' { if ($script:GmTab -eq 'tweaks') { Start-CatStates (Get-GmTweakIds) } }
        'smart' { Render-SmTab }
    }
}

function Start-CatApply($Ids, [bool]$Preview, [string]$What) {
    $sel = @($Ids | Where-Object { [string]$_ -ne '' })
    if ($sel.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce uygulanacak ayarlar' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $steps = New-StepsFromIds ([string[]]$sel)
    if ($Preview) { Start-PlanJob $steps (('' + [char]0x00D6 + 'nizleme: ') + $What) $true $false; return }
    $items = @($sel | ForEach-Object { Get-CatalogItem $_ } | Where-Object { $null -ne $_ })
    $reboot = @($items | Where-Object { $_.Reboot -eq $true }).Count
    $irrev = @($items | Where-Object { $_.Irrev -eq $true } | ForEach-Object { [string]$_.Title })
    $txt = ([string]$sel.Count + (' ayar uygulanacak. Eski de' + [char]0x011F + 'erler kaydedilir; Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri alabilirsiniz.'))
    if ($reboot -gt 0) { $txt += ("`r`n" + [string]$reboot + (' ayar yeniden ba' + [char]0x015F + 'latmadan sonra etkinle' + [char]0x015F + 'ir.')) }
    if ($irrev.Count -gt 0) { $txt += ("`r`n`r`nGeri al$([char]0x0131)namayanlar (yaln$([char]0x0131)zca silme i$([char]0x015F)lemleri):`r`n" + (Format-NameList $irrev 8)) }
    $script:PendingSteps = $steps
    $script:PendingRp = ($script:Settings.RestorePoint -eq $true)
    Show-Confirm $What $txt 'Uygula' {
        Start-PlanJob $script:PendingSteps ('Ayarlar uygulan' + [char]0x0131 + 'yor') $false $script:PendingRp { Invoke-CatAfter }
    }
}

function Get-CheckedIds($Panel) {
    $sel = Get-CheckedData $Panel
    return @(@($sel) | ForEach-Object { [string]$_.Id } | Where-Object { $_ -ne '' })
}

# ==================================================================
#  GUC
# ==================================================================
$script:PwTabs = @('plans', 'custom', 'more')
$script:PwTab = 'plans'
$script:PwInfo = $null
$script:PwPrev = $null
$script:PwPrevName = ''
$script:PwBName = ('Benim plan' + [char]0x0131 + 'm')
$script:PwBBase = 'Balanced'
$script:PwBIdx = @{}
$script:PwBPrev = $null
$script:PwBInput = $null
$script:PwLiveTick = 0
$script:PwMoreIds = @('HibernateOff', 'SysFastStartup', 'SysMaintWake', 'PowerThrottle')
$script:PwHints = @{
    CpuMin = ('D' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'k tutmak bo' + [char]0x015F + 'ta tasarruf eder; %100 i' + [char]0x015F + 'lemciyi hep tam h' + [char]0x0131 + 'zda tutar.')
    CpuMax = ('D' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'rmek ' + [char]0x0131 + 's' + [char]0x0131 + 'y' + [char]0x0131 + ' ve fan sesini belirgin azalt' + [char]0x0131 + 'r; a' + [char]0x011F + '' + [char]0x0131 + 'r i' + [char]0x015F + 'lerde biraz yava' + [char]0x015F + 'lat' + [char]0x0131 + 'r.')
    Boost = ('Turbo frekans davran' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + '. Kapal' + [char]0x0131 + ': serin ve sessiz; agresif: en y' + [char]0x00FC + 'ksek tepki.')
    Cooling = ('Etkin: ' + [char]0x00F6 + 'nce fan h' + [char]0x0131 + 'zlan' + [char]0x0131 + 'r. Pasif: ' + [char]0x00F6 + 'nce i' + [char]0x015F + 'lemci yava' + [char]0x015F + 'lar (sessiz).')
    Cores = ('Bo' + [char]0x015F + 'taki ' + [char]0x00E7 + 'ekirdeklerin uykuya ge' + [char]0x00E7 + 'mesini s' + [char]0x0131 + 'n' + [char]0x0131 + 'rlar; %100 hepsini uyan' + [char]0x0131 + 'k tutar (oyunlarda tak' + [char]0x0131 + 'lmay' + [char]0x0131 + ' azaltabilir).')
    Display = ''
    Bright = ('Yaln' + [char]0x0131 + 'zca diz' + [char]0x00FC + 'st' + [char]0x00FC + ' ve dahili ekranlarda ge' + [char]0x00E7 + 'erlidir.')
    Sleep = ''
    Hiber = ('Haz' + [char]0x0131 + 'rda bekletme kapal' + [char]0x0131 + 'ysa etkisi yoktur.')
    Disk = ('Yaln' + [char]0x0131 + 'zca mekanik diskleri etkiler.')
    Usb = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'kken kullan' + [char]0x0131 + 'lmayan USB ayg' + [char]0x0131 + 'tlar' + [char]0x0131 + ' g' + [char]0x00FC + '' + [char]0x00E7 + ' tasarrufuna ge' + [char]0x00E7 + 'er; baz' + [char]0x0131 + ' fare/kulakl' + [char]0x0131 + 'klarda kopma yapabilir.')
    Pcie = ('Ekran kart' + [char]0x0131 + ' ve NVMe ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + 'n' + [char]0x0131 + 'n g' + [char]0x00FC + '' + [char]0x00E7 + ' tasarrufu. Kapal' + [char]0x0131 + ': en d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'k gecikme.')
    Wifi = ('Kablosuz ba' + [char]0x011F + 'da' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'n g' + [char]0x00FC + '' + [char]0x00E7 + ' tasarrufu. En y' + [char]0x00FC + 'ksek performans: daha kararl' + [char]0x0131 + ' ping.')
    Lid = ('Diz' + [char]0x00FC + 'st' + [char]0x00FC + 'nde kapak kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'nda ne olaca' + [char]0x011F + '' + [char]0x0131 + '.')
}

function Format-PwMinutes([int]$M) {
    if ($M -lt 60) { return ([string]$M + ' dk') }
    return ([string][math]::Floor($M / 60) + ' sa ' + [string]($M % 60) + ' dk')
}

function Format-PwLive($L) {
    if ($null -eq $L) { return '' }
    if (-not [bool]$L.HasBattery) { return ('G' + [char]0x00FC + '' + [char]0x00E7 + ' kayna' + [char]0x011F + '' + [char]0x0131 + ': fi' + [char]0x015F + 'te (bu bilgisayarda pil yok)') }
    $t = 'Pil'
    if ([int]$L.Percent -ge 0) { $t += (' %' + [string]$L.Percent) }
    if ([bool]$L.Charging) { $t += (' ' + [char]0x00B7 + ' ' + [char]0x015F + 'arj oluyor') } elseif ([bool]$L.Online) { $t += (' ' + [char]0x00B7 + ' fi' + [char]0x015F + 'te') } else { $t += (' ' + [char]0x00B7 + ' pilde') }
    if ([int]$L.Minutes -gt 0 -and -not [bool]$L.Online) { $t += ((' ' + [char]0x00B7 + ' kalan yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + (Format-PwMinutes ([int]$L.Minutes))) }
    return $t
}

function Update-PwLive {
    $i = $script:PwInfo
    if ($null -eq $i -or $null -eq $ui.pw_LivePlan) { return }
    $nm = [string]$i.Active.Name
    if ($nm -eq '') { $nm = ('okunamad' + [char]0x0131 + '') }
    $ui.pw_LivePlan.Text = (Tr $((('Etkin g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ': ') + $nm)))
    Update-PwModeLine $i
    $t = Format-PwLive $i.Live
    if ($null -ne $i.Wear) { $t += (('  ' + [char]0x00B7 + '  pil a' + [char]0x015F + '' + [char]0x0131 + 'nmas' + [char]0x0131 + ' %') + [string]$i.Wear.Wear) }
    $ui.pw_LiveText.Text = (Tr $($t))
    $hasB = ($null -ne $i.Live -and [bool]$i.Live.HasBattery -and [int]$i.Live.Percent -ge 0)
    Set-Visible $ui.pw_Bat $hasB
    if ($hasB) { $ui.pw_Bat.Value = [int]$i.Live.Percent }
}

function Load-PwInfo {
    [void](Start-Async 'PowerInfo' 'Job_PowerInfo' @{} {
        param($r)
        if ($null -eq $r) { return }
        $script:PwInfo = $r
        Update-PwLive
        if ($script:UiState.Page -eq 'power' -and $script:PwTab -eq 'plans') { Render-PwPlans }
    } ('G' + [char]0x00FC + '' + [char]0x00E7 + ' durumu okunuyor') $true $true)
}

$script:H_PwPrev = { param($s, $e) Invoke-Safe { Start-PwPreview ([string]$s.Tag.Key) ([string]$s.Tag.Name) } ('' + [char]0x00D6 + 'nizle') }
$script:H_PwSet = { param($s, $e) Invoke-Safe { Start-PwSet ([string]$s.Tag.Key) ([string]$s.Tag.Name) } ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + '') }
$script:H_PwDel = { param($s, $e) Invoke-Safe { Start-PwDelete ([string]$s.Tag.Key) ([string]$s.Tag.Name) } ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + '') }

function Start-PwPreview([string]$Key, [string]$Name) {
    $script:PwPrevName = $Name
    [void](Start-Async 'PowerPreview' 'Job_PowerPreview' @{ Key = $Key } {
        param($r)
        if ($null -eq $r) { Show-Toast ('' + [char]0x00D6 + 'nizleme yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'warn'; return }
        $script:PwPrev = @{ Name = $script:PwPrevName; Diff = @($r.Diff); Note = [string]$r.Note }
        if ($script:PwTab -eq 'plans') { Render-PwPlans; try { $ui.pw_Scroll.ScrollToEnd() } catch { } }
    } ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' ' + [char]0x00F6 + 'nizleniyor'))
}

function Start-PwSet([string]$Key, [string]$Name) {
    $script:PendingSteps = New-PowerSetSteps $Key $Name
    $txt = (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' ' + [char]0x201C + '') + $Name + ('' + [char]0x201D + ' olarak de' + [char]0x011F + 'i' + [char]0x015F + 'tirilecek. ' + [char]0x00D6 + 'nceki plan kaydedilir; Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri d' + [char]0x00F6 + 'nebilirsiniz.'))
    if (($Key -eq 'Ultimate' -or $Key -eq 'High') -and [bool]$sync.Profile.IsLaptop) { $txt += "`r`n`r`nBu bir diz$([char]0x00FC)st$([char]0x00FC) bilgisayar: bu plan pil s$([char]0x00FC)resini belirgin k$([char]0x0131)salt$([char]0x0131)r ve $([char]0x0131)s$([char]0x0131)y$([char]0x0131) art$([char]0x0131)r$([char]0x0131)r. Fi$([char]0x015F)teyken kullanman$([char]0x0131)z $([char]0x00F6)nerilir." }
    Show-Confirm ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + 'n' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tir') $txt ('Etkinle' + [char]0x015F + 'tir') {
        Start-PlanJob $script:PendingSteps ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tiriliyor') $false $false { $script:PwPrev = $null; Load-PwInfo }
    }
}

function Start-PwDelete([string]$Guid, [string]$Name) {
    $script:PendingSteps = @(@{ Id = 'power.delete'; Title = (('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + 'n' + [char]0x0131 + ' sil: ') + $Name); Ops = @(@{ T = 'PowerDelete'; Guid = $Guid }); Reboot = $false })
    Show-Confirm ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + 'n' + [char]0x0131 + ' sil') (('' + [char]0x201C + '') + $Name + ('' + [char]0x201D + ' plan' + [char]0x0131 + ' silinecek. ' + [char]0x00D6 + 'nce d' + [char]0x0131 + '' + [char]0x015F + 'a aktar' + [char]0x0131 + 'l' + [char]0x0131 + 'p yedeklenir; Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri getirebilirsiniz. Etkinse Dengeli plana ge' + [char]0x00E7 + 'ilir.')) 'Sil' {
        Start-PlanJob $script:PendingSteps ('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' siliniyor') $false $false { Load-PwInfo }
    } $true
}

function Add-PwDiff($Panel, $Diff, [string]$Note) {
    if ($Note -ne '') { Add-Note $Panel $Note 'warn' }
    $d = @($Diff)
    if ($d.Count -eq 0 -and $Note -eq '') { Add-Note $Panel ('D' + [char]0x00FC + 'zenlenebilir ayarlarda fark yok; iki plan bu ayarlarda ayn' + [char]0x0131 + '.') }
    foreach ($x in $d) { Add-KvRow $Panel ([string]$x.Label) ([string]$x.Parts) }
}

function Render-PwPlans {
    $ui.pw_List.Children.Clear()
    $i = $script:PwInfo
    if ($null -eq $i) { Set-ListNote $ui.pw_List ('G' + [char]0x00FC + '' + [char]0x00E7 + ' planlar' + [char]0x0131 + ' okunuyor...'); return }
    Add-HeadRow $ui.pw_List ('Windows g' + [char]0x00FC + '' + [char]0x00E7 + ' planlar' + [char]0x0131 + '')
    $knownG = @{}
    foreach ($k in $script:PwKnown.Keys) {
        $kn = $script:PwKnown[$k]
        $p = Find-PwScheme ([string]$k) $i.Plans
        if ($null -ne $p) { $knownG[[string]$p.Guid] = $true }
        $active = ($null -ne $p -and [string]$p.Guid -eq [string]$i.Active.Guid)
        $name = [string]$kn.Name
        if ($null -ne $p) { $name = [string]$p.Name }
        $det = [string]$kn.Info
        if ($null -eq $p) { $det += (' (Bu bilgisayarda hen' + [char]0x00FC + 'z yok; se' + [char]0x00E7 + 'ince Windows' + [char]0x2019 + 'un yerle' + [char]0x015F + 'ik ' + [char]0x015F + 'ablonundan olu' + [char]0x015F + 'turulur.)') }
        $tag = ''; $br = 'BrAccent'; $b2 = ('Etkinle' + [char]0x015F + 'tir')
        if ($active) { $tag = ('ETK' + [char]0x0130 + 'N'); $br = 'BrGood'; $b2 = '' }
        $row = New-ItemRow @{ Title = $name; Detail = $det; Tag = $tag; BrCol = $br; Btn1 = ('' + [char]0x00D6 + 'nizle'); Btn2 = $b2 } @{ Key = [string]$k; Name = $name } $false $false
        $row.FindName('Act').Add_Click($script:H_PwPrev)
        if ($b2 -ne '') { $row.FindName('Act2').Add_Click($script:H_PwSet) }
        [void]$ui.pw_List.Children.Add($row)
    }
    $cust = @(@($i.Plans) | Where-Object { -not $knownG.ContainsKey([string]$_.Guid) })
    if ($cust.Count -gt 0) {
        Add-HeadRow $ui.pw_List ('' + [char]0x00D6 + 'zel planlar')
        foreach ($p in $cust) {
            $active = ([string]$p.Guid -eq [string]$i.Active.Guid)
            $tag = ''; $br = 'BrAccent2'; $b1 = ('Etkinle' + [char]0x015F + 'tir')
            if ($active) { $tag = ('ETK' + [char]0x0130 + 'N'); $br = 'BrGood'; $b1 = '' }
            $row = New-ItemRow @{ Title = [string]$p.Name; Detail = ('GUID ' + [string]$p.Guid); Tag = $tag; BrCol = $br; Btn1 = $b1; Btn2 = 'Sil' } @{ Key = [string]$p.Guid; Name = [string]$p.Name } $false $false
            if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_PwSet) }
            $row.FindName('Act2').Add_Click($script:H_PwDel)
            [void]$ui.pw_List.Children.Add($row)
        }
    }
    if ($null -ne $script:PwPrev) {
        Add-HeadRow $ui.pw_List (('' + [char]0x00D6 + 'nizleme: ') + [string]$script:PwPrev.Name + (' (etkin plana g' + [char]0x00F6 + 're de' + [char]0x011F + 'i' + [char]0x015F + 'ecek ayarlar)'))
        Add-PwDiff $ui.pw_List $script:PwPrev.Diff ([string]$script:PwPrev.Note)
    }
    $ui.pw_Foot.Text = (Tr $(('' + [char]0x00D6 + 'nizleme hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'eyi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez. Plan de' + [char]0x011F + 'i' + [char]0x015F + 'ince ' + [char]0x00F6 + 'nceki plan kaydedilir ve Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri d' + [char]0x00F6 + 'n' + [char]0x00FC + 'l' + [char]0x00FC + 'r. Kendi plan' + [char]0x0131 + 'n' + [char]0x0131 + 'z i' + [char]0x00E7 + 'in ' + [char]0x201C + '' + [char]0x00D6 + 'zel plan olu' + [char]0x015F + 'tur' + [char]0x201D + ' sekmesine ge' + [char]0x00E7 + 'in.')))
}

# ---------------- ozel plan olusturucu ----------------
function Get-PwChoices($Def) {
    $c = New-Object System.Collections.ArrayList
    [void]$c.Add(@{ V = $null; L = ('de' + [char]0x011F + 'i' + [char]0x015F + 'tirme') })
    switch ([string]$Def.U) {
        'sec' { foreach ($v in @(60, 120, 180, 300, 600, 900, 1200, 1800, 2700, 3600, 7200, 18000, 0)) { [void]$c.Add(@{ V = $v; L = (Format-PwValue $Def $v) }) } }
        'pct' {
            $step = 10; $from = 0
            if ([string]$Def.K -match '^Cpu') { $step = 5 }
            if ([string]$Def.K -eq 'CpuMax') { $from = 30 }
            for ($v = $from; $v -le 100; $v += $step) { [void]$c.Add(@{ V = $v; L = (Format-Percent $v) }) }
        }
        default { foreach ($k in @($Def.O.Keys | Sort-Object)) { [void]$c.Add(@{ V = [int]$k; L = [string]$Def.O[$k] }) } }
    }
    return $c.ToArray()
}

$script:PwBChanged = { param($key, $ch) $script:PwBIdx[$key] = [int]$script:StepState[$key].Index; $script:PwBPrev = $null }

function Add-PwStep2Row($Panel, $Def, [bool]$HasBattery) {
    $k = [string]$Def.K
    $row = New-RowElement 'Step2' @{ Title = [string]$Def.L; Detail = [string]$script:PwHints[$k] }
    if ([string]$script:PwHints[$k] -eq '') { $row.FindName('Det').Visibility = $script:VisOff }
    $ch = @(Get-PwChoices $Def)
    foreach ($side in @('Ac', 'Dc')) {
        $key = 'pw.' + $k + '.' + $side
        $idx = 0
        if ($script:PwBIdx.ContainsKey($key)) { $idx = [int]$script:PwBIdx[$key] }
        $script:StepState[$key] = @{ Choices = $ch; Index = $idx; OnChange = $script:PwBChanged; Text = $row.FindName($side + 'Val') }
        Update-StepText $key
        $dn = $row.FindName($side + 'Dn'); $up = $row.FindName($side + 'Up')
        $dn.Tag = @{ Key = $key; Dir = -1 }
        $up.Tag = @{ Key = $key; Dir = 1 }
        $dn.Add_Click($script:H_Step)
        $up.Add_Click($script:H_Step)
    }
    if (-not $HasBattery) { $row.FindName('DcBox').Visibility = $script:VisOff }
    [void]$Panel.Children.Add($row)
}

function Get-PwBValues {
    $vals = @{}
    foreach ($d in $script:PwSet) {
        $k = [string]$d.K
        $ch = $null
        $ac = $null; $dc = $null
        foreach ($side in @('Ac', 'Dc')) {
            $key = 'pw.' + $k + '.' + $side
            if (-not $script:PwBIdx.ContainsKey($key)) { continue }
            if ($null -eq $ch) { $ch = @(Get-PwChoices $d) }
            $v = $ch[[int]$script:PwBIdx[$key]].V
            if ($side -eq 'Ac') { $ac = $v } else { $dc = $v }
        }
        if ($null -ne $ac -or $null -ne $dc) { $vals[$k] = @{ Ac = $ac; Dc = $dc } }
    }
    return $vals
}

function Set-PwTemplate([string]$Key) {
    $t = $script:PwTemplates[$Key]
    if ($null -eq $t) { return }
    $script:PwBIdx = @{}
    $script:PwBName = [string]$t.Name
    $script:PwBBase = [string]$t.Base
    $tv = $t['Values']
    foreach ($k in @($tv.Keys)) {
        $d = Get-PwDef ([string]$k)
        if ($null -eq $d) { continue }
        $ch = @(Get-PwChoices $d)
        foreach ($side in @('Ac', 'Dc')) {
            $want = $tv[$k][$side]
            if ($null -eq $want) { continue }
            for ($i = 1; $i -lt $ch.Count; $i++) {
                if ($null -ne $ch[$i].V -and [int64]$ch[$i].V -eq [int64]$want) { $script:PwBIdx['pw.' + [string]$k + '.' + $side] = $i; break }
            }
        }
    }
    $script:PwBPrev = $null
    Render-PwCustom
    Show-Toast (('' + [char]0x015E + 'ablon y' + [char]0x00FC + 'klendi: ') + [string]$t.Name + ('. ' + [char]0x0130 + 'sterseniz de' + [char]0x011F + 'erleri de' + [char]0x011F + 'i' + [char]0x015F + 'tirip ' + [char]0x00F6 + 'nizleyin.')) 'info'
}

$script:H_PwTpl = { param($s, $e) Invoke-Safe { if ([string]$s.Tag -eq '') { $script:PwBIdx = @{}; $script:PwBPrev = $null; Render-PwCustom } else { Set-PwTemplate ([string]$s.Tag) } } ('' + [char]0x015E + 'ablon') }

function Render-PwCustom {
    $ui.pw_List.Children.Clear()
    $hasB = $true
    if ($null -ne $script:PwInfo -and $null -ne $script:PwInfo.Live) { $hasB = [bool]$script:PwInfo.Live.HasBattery }
    $lap = [bool]$sync.Profile.IsLaptop
    Add-HeadRow $ui.pw_List ('Haz' + [char]0x0131 + 'r ' + [char]0x015F + 'ablonlar')
    $wrap = New-RowElement 'Buttons' @{}
    foreach ($k in $script:PwTemplates.Keys) {
        $t = $script:PwTemplates[$k]
        [void]$wrap.Children.Add((New-UiButton ([string]$t.Name) 'BtnGhost' ([string]$k) $script:H_PwTpl ([string]$t.Info)))
    }
    [void]$wrap.Children.Add((New-UiButton ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rla') 'BtnMini' '' $script:H_PwTpl ('T' + [char]0x00FC + 'm de' + [char]0x011F + 'erleri ' + [char]0x201C + 'de' + [char]0x011F + 'i' + [char]0x015F + 'tirme' + [char]0x201D + 'ye d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'r.')))
    [void]$ui.pw_List.Children.Add($wrap)
    $inp = New-RowElement 'Input' @{ Title = ('Plan ad' + [char]0x0131 + ''); Detail = ('Windows G' + [char]0x00FC + '' + [char]0x00E7 + ' Se' + [char]0x00E7 + 'enekleri' + [char]0x2019 + 'nde bu adla g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.'); Value = $script:PwBName }
    $script:PwBInput = $inp.FindName('Inp')
    [void]$ui.pw_List.Children.Add($inp)
    $bc = New-Object System.Collections.ArrayList
    foreach ($k in $script:PwKnown.Keys) { [void]$bc.Add(@{ V = [string]$k; L = [string]$script:PwKnown[$k].Name }) }
    [void](Add-Step1Row $ui.pw_List 'pw.base' 'Taban plan' ('' + [char]0x201C + 'de' + [char]0x011F + 'i' + [char]0x015F + 'tirme' + [char]0x201D + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'lan ayarlar bu plandan al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.') $bc.ToArray() (Find-ChoiceIndex $bc.ToArray() $script:PwBBase) { param($key, $ch) $script:PwBBase = [string]$ch.V; $script:PwBPrev = $null })
    $head = ('Ayarlar (fi' + [char]0x015F + 'te / pilde)')
    if (-not $hasB) { $head = ('Ayarlar (bu bilgisayarda pil yok; yaln' + [char]0x0131 + 'zca fi' + [char]0x015F + 'teki de' + [char]0x011F + 'erler)') }
    Add-HeadRow $ui.pw_List $head
    foreach ($d in $script:PwSet) {
        if (-not $lap -and @('Lid', 'Bright') -contains [string]$d.K) { continue }
        Add-PwStep2Row $ui.pw_List $d $hasB
    }
    if ($null -ne $script:PwBPrev) {
        Add-HeadRow $ui.pw_List ('' + [char]0x00D6 + 'nizleme: etkin plana g' + [char]0x00F6 + 're de' + [char]0x011F + 'i' + [char]0x015F + 'ecek ayarlar')
        Add-PwDiff $ui.pw_List $script:PwBPrev.Diff ([string]$script:PwBPrev.Note)
    }
    $ui.pw_Foot.Text = (Tr $(('' + [char]0x201C + 'de' + [char]0x011F + 'i' + [char]0x015F + 'tirme' + [char]0x201D + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'lan ayarlar taban plandaki de' + [char]0x011F + 'eriyle kal' + [char]0x0131 + 'r. Olu' + [char]0x015F + 'turulan plan Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan silinir; Windows' + [char]0x2019 + 'un yerle' + [char]0x015F + 'ik planlar' + [char]0x0131 + 'na dokunulmaz.')))
}

function Get-PwBName {
    $n = $script:PwBName
    if ($null -ne $script:PwBInput) { $n = [string]$script:PwBInput.Text }
    $script:PwBName = $n
    return (Get-PwSafeName $n)
}

function Start-PwCustomPreview {
    $vals = Get-PwBValues
    if ($vals.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce en az bir ayar' + [char]0x0131 + ' ' + [char]0x201C + 'de' + [char]0x011F + 'i' + [char]0x015F + 'tirme' + [char]0x201D + ' d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda bir de' + [char]0x011F + 'ere getirin ya da bir ' + [char]0x015F + 'ablon se' + [char]0x00E7 + 'in.') 'warn'; return }
    [void](Get-PwBName)
    [void](Start-Async 'PowerPreview' 'Job_PowerPreview' @{ Base = $script:PwBBase; Values = $vals } {
        param($r)
        if ($null -eq $r) { Show-Toast ('' + [char]0x00D6 + 'nizleme yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'warn'; return }
        $script:PwBPrev = @{ Diff = @($r.Diff); Note = [string]$r.Note }
        if ($script:PwTab -eq 'custom') { Render-PwCustom; try { $ui.pw_Scroll.ScrollToEnd() } catch { } }
    } ('' + [char]0x00D6 + 'zel plan ' + [char]0x00F6 + 'nizleniyor'))
}

function Start-PwCustomMake([bool]$Activate) {
    $vals = Get-PwBValues
    if ($vals.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce en az bir ayar' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tirin ya da bir ' + [char]0x015F + 'ablon se' + [char]0x00E7 + 'in.') 'warn'; return }
    $name = Get-PwBName
    $script:PendingSteps = New-PowerCustomSteps $name $script:PwBBase $vals $Activate
    $txt = (('' + [char]0x201C + '') + $name + ('' + [char]0x201D + ' adl' + [char]0x0131 + ' yeni g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' ') + [string]$script:PwKnown[$script:PwBBase].Name + (' plan' + [char]0x0131 + 'n' + [char]0x0131 + 'n kopyas' + [char]0x0131 + ' olarak olu' + [char]0x015F + 'turulacak ve ') + [string]$vals.Count + (' ayar' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tirilecek.'))
    if ($Activate) { $txt += (' Olu' + [char]0x015F + 'turulunca etkinle' + [char]0x015F + 'tirilir; ' + [char]0x00F6 + 'nceki plan kaydedilir.') }
    $txt += "`r`n`r`nGe$([char]0x00E7)mi$([char]0x015F) sayfas$([char]0x0131)ndan geri al$([char]0x0131)nca bu plan silinir ve $([char]0x00F6)nceki plana d$([char]0x00F6)n$([char]0x00FC)l$([char]0x00FC)r."
    Show-Confirm ('' + [char]0x00D6 + 'zel g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + '') $txt ('Olu' + [char]0x015F + 'tur') {
        Start-PlanJob $script:PendingSteps ('' + [char]0x00D6 + 'zel g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' olu' + [char]0x015F + 'turuluyor') $false $false { $script:PwBPrev = $null; Load-PwInfo; [void](Select-TabChip 'pw' 'plans') }
    }
}

# ---------------- ek ayarlar ve raporlar ----------------
$script:H_PwAct = {
    param($s, $e)
    Invoke-Safe {
        switch ([string]$s.Tag.Key) {
            'bat' { [void](Start-Async 'Action' 'Job_Action' @{ Key = 'BatteryReport' } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Pil raporu haz' + [char]0x0131 + 'r; taray' + [char]0x0131 + 'c' + [char]0x0131 + 'da a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Pil raporu olu' + [char]0x015F + 'turulamad' + [char]0x0131 + '.') 'warn' } } ('Pil raporu haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor')) }
            'energy' { [void](Start-Async 'Action' 'Job_Action' @{ Key = 'EnergyReport' } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Enerji raporu haz' + [char]0x0131 + 'r; taray' + [char]0x0131 + 'c' + [char]0x0131 + 'da a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Enerji raporu olu' + [char]0x015F + 'turulamad' + [char]0x0131 + '.') 'warn' } } ('Enerji raporu haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor (15 sn)')) }
            'states' { [void](Start-Async 'PowerStates' 'Job_PowerStates' @{} { param($r) if ($null -ne $r) { Show-Message ('Bu bilgisayar' + [char]0x0131 + 'n uyku durumlar' + [char]0x0131 + '') ([string]$r.Text) } } ('Uyku durumlar' + [char]0x0131 + ' okunuyor')) }
            'cpl' { try { Start-Process -FilePath 'control.exe' -ArgumentList 'powercfg.cpl' -ErrorAction Stop | Out-Null } catch { Show-Toast ('G' + [char]0x00FC + '' + [char]0x00E7 + ' Se' + [char]0x00E7 + 'enekleri a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'warn' } }
        }
    } ('G' + [char]0x00FC + '' + [char]0x00E7 + '')
}

function Render-PwMore {
    $ui.pw_List.Children.Clear()
    Add-HeadRow $ui.pw_List ('Haz' + [char]0x0131 + 'rda bekletme, h' + [char]0x0131 + 'zl' + [char]0x0131 + ' ba' + [char]0x015F + 'latma ve g' + [char]0x00FC + '' + [char]0x00E7 + ' k' + [char]0x0131 + 'sma')
    [void](Add-CatRows $ui.pw_List $script:PwMoreIds)
    Add-HeadRow $ui.pw_List ('Raporlar ve ara' + [char]0x00E7 + 'lar')
    $hasB = $true
    if ($null -ne $script:PwInfo -and $null -ne $script:PwInfo.Live) { $hasB = [bool]$script:PwInfo.Live.HasBattery }
    $acts = @()
    if ($hasB) { $acts += , @('bat', 'Pil raporu', ('Pilin tasar' + [char]0x0131 + 'm kapasitesi, ' + [char]0x015F + 'u anki kapasitesi, ' + [char]0x015F + 'arj d' + [char]0x00F6 + 'ng' + [char]0x00FC + 'leri ve son g' + [char]0x00FC + 'nlerin kullan' + [char]0x0131 + 'm' + [char]0x0131 + ' (Windows' + [char]0x2019 + 'un kendi raporu).'), ('Olu' + [char]0x015F + 'tur')) }
    $acts += , @('energy', ('Enerji verimlili' + [char]0x011F + 'i raporu'), ('Windows 15 saniye boyunca g' + [char]0x00F6 + 'zlem yapar; uykuyu engelleyen ayg' + [char]0x0131 + 'tlar' + [char]0x0131 + ', y' + [char]0x00FC + 'ksek i' + [char]0x015F + 'lemci kullan' + [char]0x0131 + 'm' + [char]0x0131 + 'n' + [char]0x0131 + ' ve g' + [char]0x00FC + '' + [char]0x00E7 + ' ayar' + [char]0x0131 + ' sorunlar' + [char]0x0131 + 'n' + [char]0x0131 + ' listeler.'), ('Olu' + [char]0x015F + 'tur'))
    $acts += , @('states', ('Uyku durumlar' + [char]0x0131 + ''), ('Bu bilgisayar' + [char]0x0131 + 'n destekledi' + [char]0x011F + 'i uyku t' + [char]0x00FC + 'rlerini (S3, Modern Bekleme, haz' + [char]0x0131 + 'rda bekletme) g' + [char]0x00F6 + 'sterir.'), ('G' + [char]0x00F6 + 'ster'))
    $acts += , @('cpl', ('Windows G' + [char]0x00FC + '' + [char]0x00E7 + ' Se' + [char]0x00E7 + 'enekleri'), ('Windows' + [char]0x2019 + 'un kendi g' + [char]0x00FC + '' + [char]0x00E7 + ' se' + [char]0x00E7 + 'enekleri penceresini a' + [char]0x00E7 + 'ar.'), ('A' + [char]0x00E7 + ''))
    foreach ($a in $acts) {
        $row = New-ItemRow @{ Title = [string]$a[1]; Detail = [string]$a[2]; BrCol = 'BrBlue'; Btn1 = [string]$a[3] } @{ Key = [string]$a[0] } $false $false
        $row.FindName('Act').Add_Click($script:H_PwAct)
        [void]$ui.pw_List.Children.Add($row)
    }
    $ui.pw_Foot.Text = (Tr $(('' + [char]0x0130 + '' + [char]0x015F + 'aretledi' + [char]0x011F + 'iniz ayarlar' + [char]0x0131 + ' ' + [char]0x00F6 + 'nizleyip uygulayabilirsiniz; hepsi Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.')))
}

function Set-PwTab([string]$Tab) {
    $script:PwTab = $Tab
    switch ($Tab) {
        'plans' { Show-OnlyBar 'pw' @(); Render-PwPlans }
        'custom' { Show-OnlyBar 'pw' @('pw_CPrev', 'pw_CMake', 'pw_CSave'); Render-PwCustom }
        'more' {
            Show-OnlyBar 'pw' @('pw_TPrev', 'pw_TApply')
            Render-PwMore
            $miss = @($script:PwMoreIds | Where-Object { -not $script:CatStates.ContainsKey([string]$_) })
            if ($miss.Count -gt 0) { Start-CatStates $script:PwMoreIds }
        }
    }
}

function Init-Page_power {
    Register-Tabs 'pw' $script:PwTabs { param($s, $e) Invoke-Safe { Set-PwTab ([string]$s.Tag) } 'Sekme' }
    $ui.pw_Refresh.Add_Click({ Invoke-Safe { $script:PwPrev = $null; Load-PwInfo } 'Yenile' })
    $ui.pw_CPrev.Add_Click({ Invoke-Safe { Start-PwCustomPreview } ('' + [char]0x00D6 + 'nizle') })
    $ui.pw_CMake.Add_Click({ Invoke-Safe { Start-PwCustomMake $true } ('Olu' + [char]0x015F + 'tur') })
    $ui.pw_CSave.Add_Click({ Invoke-Safe { Start-PwCustomMake $false } ('Olu' + [char]0x015F + 'tur') })
    $ui.pw_TPrev.Add_Click({ Invoke-Safe { Start-CatApply (Get-CheckedIds $ui.pw_List) $true ('G' + [char]0x00FC + '' + [char]0x00E7 + ' ayarlar' + [char]0x0131 + '') } ('' + [char]0x00D6 + 'nizle') })
    $ui.pw_TApply.Add_Click({ Invoke-Safe { Start-CatApply (Get-CheckedIds $ui.pw_List) $false ('G' + [char]0x00FC + '' + [char]0x00E7 + ' ayarlar' + [char]0x0131 + '') } 'Uygula' })
}

function Select-Sub_power([string]$Sub) {
    if (-not (Select-TabChip 'pw' $Sub)) { Set-PwTab $Sub }
}

function Show-Page_power {
    Set-PwTab (Get-TabKey 'pw' $script:PwTabs 'plans')
    Load-PwInfo
}

# ==================================================================
#  OYUN
# ==================================================================
$script:GmTabs = @('games', 'tweaks')
$script:GmTab = 'games'
$script:GmGames = $null
$script:GmRun = @()
$script:GmTick = 0
$script:GmPrevPlan = ''
$script:GmBoosted = $false
$script:GmBoostPids = @()
$script:GmPendingGame = $null
$script:GmLoading = $false

function Get-GmTweakIds {
    return @($script:Catalog | Where-Object { [string]$_.Cat -eq 'Oyun' -and (Test-OsOk ([string]$_.OS) $sync.Profile) } | ForEach-Object { [string]$_.Id })
}

function Get-GmCustom {
    $out = New-Object System.Collections.ArrayList
    if ($script:Settings.ContainsKey('Games')) { foreach ($g in @($script:Settings.Games)) { if ($null -ne $g -and [string]$g.Exe -ne '') { [void]$out.Add(@{ Name = [string]$g.Name; Exe = [string]$g.Exe }) } } }
    return $out.ToArray()
}

function Load-GmGames {
    if ($script:GmLoading -eq $true) { return }
    $script:GmLoading = $true
    [void](Start-Async 'GameScan' 'Job_GameScan' @{ Custom = (Get-GmCustom) } {
        param($r)
        $script:GmLoading = $false
        if ($null -eq $r) { $script:GmGames = @() } else { $script:GmGames = @($r.Games) }
        # canli izleyici calisan oyunu kendi is parcaciginda arar (arayuz donmaz)
        $sync.GameDirs = @($script:GmGames | ForEach-Object { @{ Name = [string]$_.Name; Dir = [string]$_.Dir } })
        $script:GmRun = @(Get-GmRunning $script:GmGames)
        Update-GmRunText
        if ($script:UiState.Page -eq 'gaming' -and $script:GmTab -eq 'games') { Render-GmGames }
    } ('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' oyunlar aran' + [char]0x0131 + 'yor') $true $true)
}

function Update-GmRunText {
    if ($null -eq $ui.gm_Running) { return }
    $names = @(@($script:GmRun) | ForEach-Object { [string]$_.Name } | Select-Object -Unique)
    if ($names.Count -gt 0) { $t = (('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oyun: ') + ($names -join ', ')) } else { $t = ('' + [char]0x015E + 'u an ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oyun yok') }
    if ($script:GmBoosted) { $t += ('  ' + [char]0x00B7 + '  OYUN K' + [char]0x0130 + 'P' + [char]0x0130 + ' A' + [char]0x00C7 + 'IK') }
    $ui.gm_Running.Text = (Tr $($t))
}

function Update-GmLive($M) {
    $u = 23.23
    $cpu = [double]$M.Cpu
    Set-Ring $ui.gm_GCpu $cpu $u
    $ui.gm_VCpu.Text = (Tr $((Format-Percent ([int]$cpu))))
    $top = ''
    try { if ($M.ContainsKey('Top') -and @($M.Top).Count -gt 0) { $top = [string]@($M.Top)[0].Name } } catch { }
    $ui.gm_DCpu.Text = (Tr $($top))
    $ram = [double]$M.Ram
    Set-Ring $ui.gm_GRam $ram $u
    $ui.gm_VRam.Text = (Tr $((Format-Percent ([int]$ram))))
    $ui.gm_DRam.Text = (Tr $(([string]$M.RamUsedGB + ' / ' + [string]$M.RamTotalGB + ' GB')))
    $gpu = [double]$M.Gpu
    if ($gpu -ge 0) { Set-Ring $ui.gm_GGpu $gpu $u; $ui.gm_VGpu.Text = (Tr $((Format-Percent ([int]$gpu)))); $ui.gm_DGpu.Text = (Tr $(('3B y' + [char]0x00FC + 'k'))) }
    else { Set-Ring $ui.gm_GGpu 0 $u; $ui.gm_VGpu.Text = (Tr $('--')); $ui.gm_DGpu.Text = (Tr $((Get-GpuOffText))) }
    $disk = [double]$M.Disk
    Set-Ring $ui.gm_GDisk $disk $u
    $ui.gm_VDisk.Text = (Tr $((Format-Percent ([int]$disk))))
    $ui.gm_DDisk.Text = (Tr $('etkinlik'))
    $tmp = -1.0
    if ($M.ContainsKey('Temp')) { $tmp = [double]$M.Temp }
    if ($tmp -gt 0) {
        Set-Ring $ui.gm_GTemp $tmp $u
        $ui.gm_VTemp.Text = (Tr $(([string][int]$tmp + [string][char]0x00B0)))
        $ui.gm_DTemp.Text = (Tr $((Get-TempSubText $M 'sistem')))
    } else { Set-Ring $ui.gm_GTemp 0 $u; $ui.gm_VTemp.Text = (Tr $('--')); $ui.gm_DTemp.Text = (Tr $((Get-TempOffText))) }
    $script:GmTick++
    if ($M.ContainsKey('Games') -and $null -ne $script:GmGames) {
        $script:GmRun = @($M.Games)
        Update-GmRunText
    }
}

$script:H_GmGpu = { param($s, $e) Invoke-Safe { $g = $s.Tag; Start-GmFlag $g (-not [bool]$g.Flags.Gpu) $null } 'GPU tercihi' }
$script:H_GmFso = { param($s, $e) Invoke-Safe { $g = $s.Tag; Start-GmFlag $g $null (-not [bool]$g.Flags.Fso) } 'Tam ekran' }

function Start-GmFlag($Game, $Gpu, $Fso) {
    if ($null -eq $Game.Flags) { $Game.Flags = @{ Gpu = $false; Fso = $false } }
    $script:GmPendingGame = $Game
    Start-PlanJob (New-GameFlagSteps $Game $Gpu $Fso) (('Oyun ayar' + [char]0x0131 + ': ') + [string]$Game.Name) $false $false {
        if ($null -ne $script:GmPendingGame) { $script:GmPendingGame.Flags = Get-GmFlags ([string]$script:GmPendingGame.Exe) }
        if ($script:GmTab -eq 'games') { Render-GmGames }
    }
}

function Render-GmGames {
    $ui.gm_List.Children.Clear()
    if ($null -eq $script:GmGames) { Set-ListNote $ui.gm_List ('Y' + [char]0x00FC + 'kl' + [char]0x00FC + ' oyunlar aran' + [char]0x0131 + 'yor (Steam, Epic Games, GOG ve elle eklenenler)...'); Load-GmGames; return }
    $games = @($script:GmGames)
    if ($games.Count -eq 0) {
        Add-Note $ui.gm_List ('Steam, Epic Games ya da GOG' + [char]0x2019 + 'dan y' + [char]0x00FC + 'klenmi' + [char]0x015F + ' oyun bulunamad' + [char]0x0131 + '. Ba' + [char]0x015F + 'ka bir yerden y' + [char]0x00FC + 'kledi' + [char]0x011F + 'iniz oyunu ' + [char]0x201C + 'Oyun ekle...' + [char]0x201D + ' ile ekleyebilirsiniz.')
    }
    $run = @(@($script:GmRun) | ForEach-Object { [string]$_.Name })
    foreach ($g in $games) {
        if ($null -eq $g.Flags) { $g.Flags = @{ Gpu = $false; Fso = $false } }
        $det = [string]$g.Store
        if ([double]$g.Size -gt 0) { $det += ((' ' + [char]0x00B7 + ' ') + (Format-Size ([double]$g.Size))) }
        $det += ((' ' + [char]0x00B7 + ' ') + (Limit-Text ([string]$g.Dir) 90))
        if ([string]$g.Exe -eq '') { $det += (' ' + [char]0x00B7 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir dosya bulunamad' + [char]0x0131 + ' (oyun ba' + [char]0x015F + '' + [char]0x0131 + 'na ayar yap' + [char]0x0131 + 'lamaz)') }
        $tags = @()
        if ($run -contains [string]$g.Name) { $tags += ('' + [char]0x00C7 + 'ALI' + [char]0x015E + 'IYOR') }
        if ([bool]$g.Flags.Gpu) { $tags += ('GPU: y' + [char]0x00FC + 'ksek') }
        if ([bool]$g.Flags.Fso) { $tags += ('FSO kapal' + [char]0x0131 + '') }
        $b1 = ''; $b2 = ''
        if ([string]$g.Exe -ne '') {
            $b1 = ('G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' GPU' + [char]0x2019 + 'da ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r'); if ([bool]$g.Flags.Gpu) { $b1 = ('GPU tercihini kald' + [char]0x0131 + 'r') }
            $b2 = ('Tam ekran iyile' + [char]0x015F + 'tirmesini kapat'); if ([bool]$g.Flags.Fso) { $b2 = ('Tam ekran iyile' + [char]0x015F + 'tirmesini a' + [char]0x00E7 + '') }
        }
        $br = 'BrAccent'
        if ($run -contains [string]$g.Name) { $br = 'BrGood' }
        $row = New-ItemRow @{ Title = [string]$g.Name; Detail = $det; Tag = ($tags -join (' ' + [char]0x00B7 + ' ')); BrCol = $br; Btn1 = $b1; Btn2 = $b2 } $g $false $false
        if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_GmGpu); $row.FindName('Act2').Add_Click($script:H_GmFso) }
        [void]$ui.gm_List.Children.Add($row)
    }
    $ui.gm_Foot.Text = (Tr $(([string]$games.Count + (' oyun. ' + [char]0x201C + 'G' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' GPU' + [char]0x2019 + 'da ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x201D + ' iki ekran kartl' + [char]0x0131 + ' diz' + [char]0x00FC + 'st' + [char]0x00FC + 'lerde oyunun g' + [char]0x00FC + '' + [char]0x00E7 + 'l' + [char]0x00FC + ' kartta ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + 'n' + [char]0x0131 + ' sa' + [char]0x011F + 'lar (Ayarlar > Ekran > Grafik ile ayn' + [char]0x0131 + '). Tam ekran iyile' + [char]0x015F + 'tirmesini kapatmak baz' + [char]0x0131 + ' eski oyunlarda gecikmeyi azalt' + [char]0x0131 + 'r. Hepsi Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.'))))
}

function Render-GmTweaks {
    $ui.gm_List.Children.Clear()
    Add-HeadRow $ui.gm_List ('Oyun ayarlar' + [char]0x0131 + ' (daha d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'k gecikme, daha y' + [char]0x00FC + 'ksek ve kararl' + [char]0x0131 + ' FPS)')
    $n = Add-CatRows $ui.gm_List (Get-GmTweakIds)
    if ($n -eq 0) { Add-Note $ui.gm_List ('Bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' i' + [char]0x00E7 + 'in oyun ayar' + [char]0x0131 + ' yok.') }
    Add-Note $ui.gm_List ('Bellek b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' (HVCI) gibi g' + [char]0x00FC + 'venlik ' + [char]0x00F6 + 'zelliklerini kapatan ayarlar yaln' + [char]0x0131 + 'zca elle se' + [char]0x00E7 + 'ilebilir ve ' + [char]0x00F6 + 'nerilmez.')
    $ui.gm_Foot.Text = (Tr $(('' + [char]0x0130 + '' + [char]0x015F + 'aretleyip ' + [char]0x00F6 + 'nce ' + [char]0x00F6 + 'nizleyin. ' + [char]0x201C + 'uygulanm' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x201D + ' yazanlar zaten etkin. G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' i' + [char]0x00E7 + 'in G' + [char]0x00FC + '' + [char]0x00E7 + ' sayfas' + [char]0x0131 + 'ndaki ' + [char]0x201C + 'Oyun' + [char]0x201D + ' ' + [char]0x015F + 'ablonunu da kullanabilirsiniz.')))
}

function Start-GmBoost {
    $script:GmPrevPlan = ''
    try { $script:GmPrevPlan = [string](Get-PwActive).Guid } catch { }
    $script:GmBoostPids = @(@($script:GmRun) | ForEach-Object { [int]$_.Pid })
    $lines = @(('G' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ': Nihai performans (yoksa olu' + [char]0x015F + 'turulur; desteklenmiyorsa Y' + [char]0x00FC + 'ksek performans). ' + [char]0x00D6 + 'nceki plan kaydedilir.'))
    if ($script:Settings.OptFocus -eq $true) { $lines += ('Odak kipi: arama dizini, SysMain gibi arka plan hizmetleri ge' + [char]0x00E7 + 'ici durdurulur.') }
    else { $lines += ('Odak kipi iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + 'd' + [char]0x0131 + 'r ve kapal' + [char]0x0131 + ' (Ayarlar > ' + [char]0x0130 + 'ste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellikler); bu ad' + [char]0x0131 + 'm atlan' + [char]0x0131 + 'r.') }
    if ($script:GmBoostPids.Count -gt 0) { $lines += (('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oyunun ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'i y' + [char]0x00FC + 'kseltilir (oyun kapan' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r).')) }
    else { $lines += ('' + [char]0x015E + 'u an ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oyun yok; ' + [char]0x00F6 + 'ncelik de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmez. Oyunu a' + [char]0x00E7 + 't' + [char]0x0131 + 'ktan sonra yeniden basabilirsiniz.') }
    $txt = (($lines | ForEach-Object { ('' + [char]0x2022 + ' ') + $_ }) -join "`r`n") + "`r`n`r`n$([char]0x201C)Normale d$([char]0x00F6)n$([char]0x201D) her $([char]0x015F)eyi eski haline getirir."
    Show-Confirm 'Oyun kipi' $txt ('A' + [char]0x00E7 + '') {
        Start-PlanJob (New-PowerSetSteps 'Best' 'Nihai performans') ('Oyun kipi a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { Complete-GmBoost }
    }
}

function Complete-GmBoost {
    if (@($script:GmBoostPids).Count -gt 0) {
        [void](Start-Async 'GameBoost' 'Job_GameBoost' @{ Pids = @($script:GmBoostPids) } { param($r) } ('Oyun ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'i y' + [char]0x00FC + 'kseltiliyor') $true $true)
    }
    if ($script:Settings.OptFocus -eq $true) {
        [void](Start-Async 'Focus' 'Job_Focus' @{ On = $true } { param($r) $script:TlFocus = ($null -ne $r -and $r.On -eq $true); Update-TrayMenuState } ('Odak kipi a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $true $true)
    }
    $script:GmBoosted = $true
    Update-GmRunText
    Add-SmLog ('Oyun kipi a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '.')
}

function Start-GmNormal {
    $to = [string]$script:GmPrevPlan
    $steps = $null
    if ($to -ne '') { $steps = New-PowerSetSteps $to ('' + [char]0x00F6 + 'nceki plan') } else { $steps = New-PowerSetSteps 'Balanced' }
    Start-PlanJob $steps ('Normale d' + [char]0x00F6 + 'n' + [char]0x00FC + 'l' + [char]0x00FC + 'yor') $false $false {
        foreach ($id in @($script:GmBoostPids)) { [void](Start-Async ('Prio' + [string]$id) 'Job_Priority' @{ Pid = [int]$id; Level = 'Normal' } { param($r) } ('' + [char]0x00D6 + 'ncelik s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor') $true $true) }
        if ($script:Settings.OptFocus -eq $true) {
            [void](Start-Async 'Focus' 'Job_Focus' @{ On = $false } { param($r) $script:TlFocus = $false; Update-TrayMenuState } ('Odak kipi kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $true $true)
        }
        $script:GmBoosted = $false
        $script:GmBoostPids = @()
        Update-GmRunText
        Add-SmLog ('Oyun kipi kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '.')
    }
}

function Add-GmCustom {
    $f = Select-OpenFile 'Oyun (*.exe)|*.exe'
    if ($f -eq '') { return }
    if (-not (Test-GmExePath $f)) { Show-Toast ('Ge' + [char]0x00E7 + 'erli bir .exe dosyas' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') 'warn'; return }
    $list = New-Object System.Collections.ArrayList
    foreach ($g in (Get-GmCustom)) { if ([string]$g.Exe -ne $f) { [void]$list.Add($g) } }
    [void]$list.Add(@{ Name = [System.IO.Path]::GetFileNameWithoutExtension($f); Exe = $f })
    Set-OptValue 'Games' @($list.ToArray())
    $script:GmGames = $null
    Render-GmGames
}

function Set-GmTab([string]$Tab) {
    $script:GmTab = $Tab
    switch ($Tab) {
        'games' { Show-OnlyBar 'gm' @('gm_Scan', 'gm_Add', 'gm_ClearCustom'); Render-GmGames }
        'tweaks' {
            Show-OnlyBar 'gm' @('gm_TPrev', 'gm_TApply')
            Render-GmTweaks
            $ids = Get-GmTweakIds
            $miss = @($ids | Where-Object { -not $script:CatStates.ContainsKey([string]$_) })
            if ($miss.Count -gt 0) { Start-CatStates $ids }
        }
    }
}

function Init-Page_gaming {
    Register-Tabs 'gm' $script:GmTabs { param($s, $e) Invoke-Safe { Set-GmTab ([string]$s.Tag) } 'Sekme' }
    $ui.gm_Scan.Add_Click({ Invoke-Safe { $script:GmGames = $null; Render-GmGames } 'Tara' })
    $ui.gm_Add.Add_Click({ Invoke-Safe { Add-GmCustom } 'Oyun ekle' })
    $ui.gm_ClearCustom.Add_Click({ Invoke-Safe { Set-OptValue 'Games' @(); $script:GmGames = $null; Render-GmGames } 'Oyun listesi' })
    $ui.gm_TPrev.Add_Click({ Invoke-Safe { Start-CatApply (Get-CheckedIds $ui.gm_List) $true ('Oyun ayarlar' + [char]0x0131 + '') } ('' + [char]0x00D6 + 'nizle') })
    $ui.gm_TApply.Add_Click({ Invoke-Safe { Start-CatApply (Get-CheckedIds $ui.gm_List) $false ('Oyun ayarlar' + [char]0x0131 + '') } 'Uygula' })
    $ui.gm_Boost.Add_Click({ Invoke-Safe { Start-GmBoost } 'Oyun kipi' })
    $ui.gm_Normal.Add_Click({ Invoke-Safe { Start-GmNormal } ('Normale d' + [char]0x00F6 + 'n') })
}

function Select-Sub_gaming([string]$Sub) {
    if (-not (Select-TabChip 'gm' $Sub)) { Set-GmTab $Sub }
}

function Show-Page_gaming {
    Set-GmTab (Get-TabKey 'gm' $script:GmTabs 'games')
    Update-GmRunText
    $m = $sync.Mon
    if ($null -ne $m -and $m.ContainsKey('Cpu')) { Update-GmLive $m }
}

# ==================================================================
#  AKILLI BAKIM
# ==================================================================
$script:SmTabs = @('care', 'rules', 'life', 'widget')
$script:SmTab = 'care'
$script:SmLog = New-Object System.Collections.ArrayList
$script:SmPriv = $null
$script:SmLife = $null
$script:SmEdit = $null
$script:SmN = 0
$script:SmSlow = @{ Battery = -1.0; HasBattery = $false; Online = $true; FreeGB = -1.0; GameOn = $false }
$script:SmCnt = @{ CpuHigh = 0; TempHigh = 0; TempLow = 0; RamHigh = 0 }
$script:SmLast = @{ Boost = [datetime]::MinValue; Thermal = [datetime]::MinValue; Ram = [datetime]::MinValue }
$script:SmCapped = $false
$script:SmCapPrev = @{ Ac = 100; Dc = 100 }
$script:AuRt = @{}

function Add-SmLog([string]$Text) {
    [void]$script:SmLog.Add(@{ Time = (Get-Date).ToString('HH:mm:ss'); Text = $Text })
    while ($script:SmLog.Count -gt 100) { $script:SmLog.RemoveAt(0) }
    try { Write-LogFile ((Get-Date).ToString('yyyy-MM-dd HH:mm:ss') + ' [AKILLI] ' + $Text) } catch { }
    if ($script:UiState.Page -eq 'smart' -and $script:SmTab -eq 'care' -and $null -ne $ui.sm_List) { try { Render-SmCare } catch { } }
}

function Start-SmPlan($Steps, [string]$Label) {
    $st = @($Steps)
    if ($st.Count -eq 0) { return }
    [void](Start-Async 'SmPlan' 'Job_Plan' @{ Steps = $st; Preview = $false; RestorePoint = $false } {
        param($r)
        if ($null -ne $r) { Add-SmLog ('  ' + [string]$r.Summary); $script:Settings = Get-Settings }
    } $Label $true $true)
}

function Update-SmHeader {
    if ($null -eq $ui.sm_State) { return }
    $on = ($script:Settings.OptSmart -eq $true)
    if ($on) {
        $ui.sm_State.Text = (Tr $(('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm a' + [char]0x00E7 + '' + [char]0x0131 + 'k')))
        $parts = @()
        if ($script:Settings.SmartBoost -eq $true) { $parts += ('performans art' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + '') }
        if ($script:Settings.SmartThermal -eq $true) { $parts += ('' + [char]0x0131 + 's' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi') }
        if ($script:Settings.SmartRamAuto -eq $true) { $parts += 'bellek rahatlatma' }
        if ($script:Settings.AutoOn -eq $true) { $parts += ([string]@(Get-AuRules | Where-Object { $_.On -eq $true }).Count + (' otomasyon kural' + [char]0x0131 + '')) }
        if ($parts.Count -eq 0) { $ui.sm_StateText.Text = (Tr $(('Motor a' + [char]0x00E7 + '' + [char]0x0131 + 'k ama hi' + [char]0x00E7 + 'bir izleyici se' + [char]0x00E7 + 'ilmedi. A' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'dan se' + [char]0x00E7 + 'in.'))) }
        else { $ui.sm_StateText.Text = (Tr $((('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'anlar: ') + ($parts -join ', ') + ('. Uygulama a' + [char]0x00E7 + '' + [char]0x0131 + 'kken (tepsideyken de) ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.')))) }
        $ui.sm_Dot.Fill = (Get-Br 'BrGood')
        $ui.sm_Master.Content = (Tr $('Kapat'))
    } else {
        $ui.sm_State.Text = (Tr $(('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm kapal' + [char]0x0131 + '')))
        $ui.sm_StateText.Text = (Tr $(('A' + [char]0x00E7 + '' + [char]0x0131 + 'nca se' + [char]0x00E7 + 'ti' + [char]0x011F + 'iniz izleyiciler ve kurallar uygulama a' + [char]0x00E7 + '' + [char]0x0131 + 'kken (tepsiye k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'lt' + [char]0x00FC + 'lm' + [char]0x00FC + '' + [char]0x015F + 'ken de) ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r. Kapal' + [char]0x0131 + 'yken hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey kendili' + [char]0x011F + 'inden yap' + [char]0x0131 + 'lmaz.')))
        $ui.sm_Dot.Fill = (Get-Br 'BrFaint')
        $ui.sm_Master.Content = (Tr $(('A' + [char]0x00E7 + '')))
    }
}

function Get-SmModeText([string]$On, [string]$Auto) {
    $o = ($script:Settings[$On] -eq $true)
    $a = ($script:Settings[$Auto] -eq $true)
    if (-not $o) { return @{ Tag = ('kapal' + [char]0x0131 + ''); Br = 'BrFaint'; B1 = ('A' + [char]0x00E7 + ''); B2 = '' } }
    if ($a) { return @{ Tag = ('OTOMAT' + [char]0x0130 + 'K'); Br = 'BrGood'; B1 = 'Kapat'; B2 = ('Yaln' + [char]0x0131 + 'zca bildir') } }
    return @{ Tag = 'bildirir'; Br = 'BrInfo'; B1 = 'Kapat'; B2 = 'Otomatik yap' }
}

$script:H_SmAct = {
    param($s, $e)
    Invoke-Safe { Invoke-SmAct ([string]$s.Tag.Key) $s.Tag } ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm')
}

function Add-SmRow([string]$Title, [string]$Detail, [string]$Tag, [string]$Br, [string]$K1, [string]$B1, [string]$K2 = '', [string]$B2 = '', $Data = $null) {
    $d1 = @{ Key = $K1 }
    if ($null -ne $Data) { foreach ($k in @($Data.Keys)) { $d1[$k] = $Data[$k] } }
    $row = New-ItemRow @{ Title = $Title; Detail = $Detail; Tag = $Tag; BrCol = $Br; Btn1 = $B1; Btn2 = $B2 } $d1 $false $false
    if ($B1 -ne '') { $row.FindName('Act').Add_Click($script:H_SmAct) }
    if ($B2 -ne '') {
        $d2 = @{ Key = $K2 }
        if ($null -ne $Data) { foreach ($k in @($Data.Keys)) { $d2[$k] = $Data[$k] } }
        $a2 = $row.FindName('Act2'); $a2.Tag = $d2; $a2.Add_Click($script:H_SmAct)
    }
    [void]$ui.sm_List.Children.Add($row)
}

function Set-SmFlag([string]$Name, [bool]$Value) {
    Set-OptValue $Name $Value
    $script:SmCnt = @{ CpuHigh = 0; TempHigh = 0; TempLow = 0; RamHigh = 0 }
    Update-SmHeader
    Render-SmTab
}

function Invoke-SmAct([string]$Key, $Data) {
    switch ($Key) {
        'boost' { Set-SmFlag 'SmartBoost' (-not ($script:Settings.SmartBoost -eq $true)) }
        'boostAuto' { Set-SmFlag 'SmartBoostAuto' (-not ($script:Settings.SmartBoostAuto -eq $true)) }
        'thermal' { Set-SmFlag 'SmartThermal' (-not ($script:Settings.SmartThermal -eq $true)) }
        'thermalAuto' { Set-SmFlag 'SmartThermalAuto' (-not ($script:Settings.SmartThermalAuto -eq $true)) }
        'ramAuto' { Set-SmFlag 'SmartRamAuto' (-not ($script:Settings.SmartRamAuto -eq $true)) }
        'settings' { Show-Page 'settings' }
        'zeroPrev' {
            [void](Start-Async 'SmartZero' 'Job_SmartZero' @{ Preview = $true; RestorePoint = $false } { param($r) Complete-PlanJob $r } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'r dokunu' + [char]0x015F + ' ' + [char]0x00F6 + 'nizleniyor'))
        }
        'zeroRun' {
            Show-Confirm ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'r dokunu' + [char]0x015F + '') (('Bu bilgisayara uygun g' + [char]0x00FC + 'venli (d' + [char]0x00FC + 'zey 1) ayarlar uygulanacak ve ge' + [char]0x00E7 + 'ici dosyalar temizlenecek. Zaten uygulanm' + [char]0x0131 + '' + [char]0x015F + ' ayarlar atlan' + [char]0x0131 + 'r. ' + [char]0x00D6 + 'nce bir geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulur (Ayarlar' + [char]0x2019 + 'da kapal' + [char]0x0131 + ' de' + [char]0x011F + 'ilse). Her de' + [char]0x011F + 'i' + [char]0x015F + 'iklik Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.')) 'Uygula' {
                $rp = ($script:Settings.RestorePoint -eq $true)
                [void](Start-Async 'SmartZero' 'Job_SmartZero' @{ Preview = $false; RestorePoint = $rp } {
                    param($r)
                    Complete-PlanJob $r
                    if ($null -ne $r) { Add-SmLog (('S' + [char]0x0131 + 'f' + [char]0x0131 + 'r dokunu' + [char]0x015F + ': ') + [string]$r.Summary); Set-OptValue 'LastZero' ((Get-Date).ToString('dd.MM.yyyy HH:mm')) }
                    Render-SmTab
                } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'r dokunu' + [char]0x015F + ' uygulan' + [char]0x0131 + 'yor'))
            }
        }
        'privCheck' { Start-SmPrivCheck }
        'privRun' {
            if ($null -eq $script:SmPriv) { Start-SmPrivCheck; Show-Toast ('' + [char]0x00D6 + 'nce denetleniyor; bitince yeniden ' + [char]0x201C + 'Eksikleri uygula' + [char]0x201D + 'ya bas' + [char]0x0131 + 'n.') 'info'; return }
            $p = @($script:SmPriv.Pending)
            if ($p.Count -eq 0) { Show-Toast ('Gizlilik kalkan' + [char]0x0131 + 'ndaki t' + [char]0x00FC + 'm ayarlar zaten uygulanm' + [char]0x0131 + '' + [char]0x015F + '.') 'good'; return }
            Start-CatApply $p $false ('Gizlilik kalkan' + [char]0x0131 + '')
        }
        'cleanPage' { Open-Page 'clean' 'clean' }
        'cleanRun' { Start-SmClean }
        'master' { Set-SmFlag 'OptSmart' (-not ($script:Settings.OptSmart -eq $true)); if ($script:Settings.OptSmart -eq $true) { Show-Toast ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm a' + [char]0x00E7 + '' + [char]0x0131 + 'k. Hangi izleyicilerin ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'aca' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'dan se' + [char]0x00E7 + 'in.') 'info' } else { Show-Toast ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '; hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey kendili' + [char]0x011F + 'inden yap' + [char]0x0131 + 'lmaz.') 'info' } }
        'autoToggle' { Set-SmFlag 'AutoOn' (-not ($script:Settings.AutoOn -eq $true)) }
        'ruleToggle' { Set-AuRuleOn ([string]$Data.Id) }
        'ruleDel' { Remove-AuRuleUi ([string]$Data.Id) }
        'tplAdd' { Add-AuTemplate ([int]$Data.Index) }
        'widget' { Set-SmFlag 'OptWidget' (-not ($script:Settings.OptWidget -eq $true)); Sync-Widget }
        'batrep' { [void](Start-Async 'Action' 'Job_Action' @{ Key = 'BatteryReport' } { param($r) } ('Pil raporu haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor')) }
    }
}

function Start-SmPrivCheck {
    [void](Start-Async 'PrivStatus' 'Job_PrivacyStatus' @{} {
        param($r)
        $script:SmPriv = $r
        if ($script:UiState.Page -eq 'smart' -and $script:SmTab -eq 'care') { Render-SmCare }
    } ('Gizlilik ayarlar' + [char]0x0131 + ' denetleniyor'))
}

function Start-SmClean {
    $ids = @($script:SmSafeClean | Where-Object { $null -ne (Get-CatalogItem $_) })
    $names = @($ids | ForEach-Object { [string](Get-CatalogItem $_).Title })
    $script:PendingSteps = New-StepsFromIds ([string[]]$ids)
    Show-Confirm ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' temizlik') ("$([char]0x015E)u g$([char]0x00FC)venli kategoriler temizlenecek:`r`n" + (Format-NameList $names 10) + "`r`n`r`nYaln$([char]0x0131)zca yeniden olu$([char]0x015F)turulabilen dosyalar silinir; belgeleriniz, parolalar$([char]0x0131)n$([char]0x0131)z ve oturumlar$([char]0x0131)n$([char]0x0131)z etkilenmez. Silinen dosyalar geri getirilemez.") 'Temizle' {
        Start-PlanJob $script:PendingSteps ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' temizlik') $false $false { Add-SmLog ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' temizlik tamamland' + [char]0x0131 + '.') }
    }
}

function Render-SmCare {
    $ui.sm_List.Children.Clear()
    $on = ($script:Settings.OptSmart -eq $true)
    if (-not $on) { Add-Note $ui.sm_List ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm kapal' + [char]0x0131 + '. ' + [char]0x0130 + 'zleyicileri buradan se' + [char]0x00E7 + 'ebilirsiniz; ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'malar' + [char]0x0131 + ' i' + [char]0x00E7 + 'in ' + [char]0x00FC + 'stteki ' + [char]0x201C + 'A' + [char]0x00E7 + '' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesiyle motoru a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') 'warn' }
    Add-HeadRow $ui.sm_List ('' + [char]0x0130 + 'zleyiciler')
    $m = Get-SmModeText 'SmartBoost' 'SmartBoostAuto'
    Add-SmRow ('Performans art' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + '') ('' + [char]0x0130 + '' + [char]0x015F + 'lemci 40 saniyeden uzun s' + [char]0x00FC + 're %90' + [char]0x2019 + '' + [char]0x0131 + 'n ' + [char]0x00FC + 'st' + [char]0x00FC + 'ndeyse y' + [char]0x00FC + 'k' + [char]0x00FC + ' olu' + [char]0x015F + 'turan arka plan program' + [char]0x0131 + 'n' + [char]0x0131 + ' bulur ve haber verir. ' + [char]0x201C + 'Otomatik' + [char]0x201D + ' se' + [char]0x00E7 + 'ilirse penceresi olmayan o arka plan i' + [char]0x015F + 'leminin ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'ini d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'r (program kapan' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r). Sistem i' + [char]0x015F + 'lemlerine ve a' + [char]0x00E7 + '' + [char]0x0131 + 'k pencerelere dokunmaz.') $m.Tag $m.Br 'boost' $m.B1 'boostAuto' $m.B2
    $m = Get-SmModeText 'SmartThermal' 'SmartThermalAuto'
    $tnow = ('sens' + [char]0x00F6 + 'r okunam' + [char]0x0131 + 'yor')
    try { if ($sync.Mon.ContainsKey('Temp') -and [double]$sync.Mon.Temp -gt 0) { $tnow = ([string][int][double]$sync.Mon.Temp + (' ' + [char]0x00B0 + 'C')) } } catch { }
    if ($script:SmCapped) { $m.Tag = 'SINIRLI (%80)' ; $m.Br = 'BrWarn' }
    Add-SmRow ('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi') (('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k 30 saniye boyunca 88 ' + [char]0x00B0 + 'C' + [char]0x2019 + 'yi a' + [char]0x015F + 'arsa haber verir. ' + [char]0x201C + 'Otomatik' + [char]0x201D + ' se' + [char]0x00E7 + 'ilirse i' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' ge' + [char]0x00E7 + 'ici olarak %80' + [char]0x2019 + 'e ' + [char]0x00E7 + 'eker; 2 dakika 70 ' + [char]0x00B0 + 'C' + [char]0x2019 + 'nin alt' + [char]0x0131 + 'nda kal' + [char]0x0131 + 'nca eski de' + [char]0x011F + 'erine d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'r. ' + [char]0x015E + 'u an: ') + $tnow) $m.Tag $m.Br 'thermal' $m.B1 'thermalAuto' $m.B2
    if ($script:Settings.OptRam -eq $true) {
        $ro = ($script:Settings.SmartRamAuto -eq $true)
        $tg = ('kapal' + [char]0x0131 + ''); $br = 'BrFaint'; $b = ('A' + [char]0x00E7 + '')
        if ($ro) { $tg = ('OTOMAT' + [char]0x0130 + 'K'); $br = 'BrGood'; $b = 'Kapat' }
        Add-SmRow 'Bellek rahatlatma' ('Bellek 2 dakika boyunca %92' + [char]0x2019 + 'nin ' + [char]0x00FC + 'st' + [char]0x00FC + 'nde kal' + [char]0x0131 + 'rsa belle' + [char]0x011F + 'i bo' + [char]0x015F + 'alt' + [char]0x0131 + 'r (20 dakikada en fazla bir kez). Etkisi ge' + [char]0x00E7 + 'icidir.') $tg $br 'ramAuto' $b
    } else {
        Add-SmRow 'Bellek rahatlatma' ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ' iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' bir ' + [char]0x00F6 + 'zelliktir ve kapal' + [char]0x0131 + '. Kullanmak i' + [char]0x00E7 + 'in ' + [char]0x00F6 + 'nce Ayarlar > ' + [char]0x0130 + 'ste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellikler' + [char]0x2019 + 'den a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') ('kapal' + [char]0x0131 + '') 'BrFaint' 'settings' ('Ayarlar' + [char]0x0131 + ' a' + [char]0x00E7 + '')
    }
    Add-HeadRow $ui.sm_List ('Tek t' + [char]0x0131 + 'kla bak' + [char]0x0131 + 'm')
    $lz = [string]$script:Settings.LastZero
    $zt = ''; if ($lz -ne '') { $zt = ('son: ' + $lz) }
    Add-SmRow ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'r dokunu' + [char]0x015F + '') ('Bu bilgisayar' + [char]0x0131 + 'n donan' + [char]0x0131 + 'm' + [char]0x0131 + 'na g' + [char]0x00F6 + 're yaln' + [char]0x0131 + 'zca g' + [char]0x00FC + 'venli (d' + [char]0x00FC + 'zey 1) ayarlar' + [char]0x0131 + ' se' + [char]0x00E7 + 'er, zaten uygulanm' + [char]0x0131 + '' + [char]0x015F + ' olanlar' + [char]0x0131 + ' atlar ve ge' + [char]0x00E7 + 'ici dosyalar' + [char]0x0131 + ' temizler. ' + [char]0x00D6 + 'nce ' + [char]0x00F6 + 'nizleyin; uygulanan her ' + [char]0x015F + 'ey Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.') $zt 'BrAccent' 'zeroPrev' ('' + [char]0x00D6 + 'nizle') 'zeroRun' 'Uygula'
    $pt = 'denetlenmedi'; $pb = 'BrInfo'
    if ($null -ne $script:SmPriv) {
        $pt = ([string]$script:SmPriv.Applied + ' / ' + [string]$script:SmPriv.Total + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'k'))
        if (@($script:SmPriv.Pending).Count -eq 0) { $pb = 'BrGood' } else { $pb = 'BrWarn' }
    }
    Add-SmRow ('Gizlilik kalkan' + [char]0x0131 + '') ('Telemetri, reklam kimli' + [char]0x011F + 'i, ' + [char]0x00F6 + 'neriler, etkinlik ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i, Edge ve Office tan' + [char]0x0131 + 'lama verisi gibi g' + [char]0x00FC + 'venli (d' + [char]0x00FC + 'zey 1-2) gizlilik ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + 'n hepsini denetler; eksik olanlar' + [char]0x0131 + ' tek seferde uygular. Windows g' + [char]0x00FC + 'ncellemesi bir ayar' + [char]0x0131 + ' geri al' + [char]0x0131 + 'rsa yeniden denetleyin ya da Ayar bek' + [char]0x00E7 + 'isini a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') $pt $pb 'privCheck' 'Denetle' 'privRun' 'Eksikleri uygula'
    Add-SmRow ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' temizlik') ('Ge' + [char]0x00E7 + 'ici dosyalar, hata raporlar' + [char]0x0131 + ', eski g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kler, g' + [char]0x00FC + 'ncelleme ve Teslim ' + [char]0x0130 + 'yile' + [char]0x015F + 'tirme ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'i gibi g' + [char]0x00FC + 'venle silinebilen kategorileri temizler. Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' dosyalar' + [char]0x0131 + 'na dokunmaz. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' se' + [char]0x00E7 + 'im i' + [char]0x00E7 + 'in Temizlik sayfas' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') '' 'BrAccent' 'cleanPage' ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' tara') 'cleanRun' ('G' + [char]0x00FC + 'venli temizle')
    Add-HeadRow $ui.sm_List ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' (bu oturum)')
    if ($script:SmLog.Count -eq 0) { Add-Note $ui.sm_List ('Hen' + [char]0x00FC + 'z bir ' + [char]0x015F + 'ey yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '.') }
    else {
        $arr = @($script:SmLog.ToArray())
        $from = [math]::Max(0, $arr.Count - 15)
        for ($i = $arr.Count - 1; $i -ge $from; $i--) { Add-KvRow $ui.sm_List ([string]$arr[$i].Time) ([string]$arr[$i].Text) }
    }
    $ui.sm_Foot.Text = (Tr $(('Kararlar bu bilgisayar' + [char]0x0131 + 'n kendi ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'mleriyle verilir; hi' + [char]0x00E7 + 'bir veri d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + ' g' + [char]0x00F6 + 'nderilmez. Otomatik yap' + [char]0x0131 + 'lan her de' + [char]0x011F + 'i' + [char]0x015F + 'iklik Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r.')))
}

# ---------------- otomasyon kurallari ----------------
function ConvertTo-AuRule($R) {
    $h = ConvertTo-Hashtable $R
    if ($h -isnot [hashtable]) { return $null }
    if ($h.When -isnot [hashtable] -or $h.Do -isnot [hashtable]) { return $null }
    if ($h.When.ContainsKey('Days')) { $h.When.Days = @($h.When.Days) }
    if (-not $h.ContainsKey('Cool')) { $h.Cool = 30 }
    if (-not $h.ContainsKey('Last')) { $h.Last = '' }
    return $h
}

function Get-AuRules {
    $l = New-Object System.Collections.ArrayList
    if ($script:Settings.ContainsKey('AutoRules')) {
        foreach ($r in @($script:Settings.AutoRules)) {
            if ($null -eq $r) { continue }
            $x = ConvertTo-AuRule $r
            if ($null -ne $x -and [string]$x.Id -ne '') { [void]$l.Add($x) }
        }
    }
    return $l.ToArray()
}

function Save-AuRules($Rules) {
    Set-OptValue 'AutoRules' @($Rules)
}

function Set-AuRuleOn([string]$Id) {
    $rs = @(Get-AuRules)
    foreach ($r in $rs) { if ([string]$r.Id -eq $Id) { $r.On = -not ($r.On -eq $true) } }
    Save-AuRules $rs
    if ($script:AuRt.ContainsKey($Id)) { $script:AuRt.Remove($Id) }
    Update-SmHeader
    Render-SmRules
}

function Remove-AuRuleUi([string]$Id) {
    $script:PendingRuleId = $Id
    Show-Confirm ('Kural' + [char]0x0131 + ' sil') ('Bu otomasyon kural' + [char]0x0131 + ' silinecek. Daha ' + [char]0x00F6 + 'nce yapt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'iklikler Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'nda kal' + [char]0x0131 + 'r.') 'Sil' {
        $rs = @(Get-AuRules | Where-Object { [string]$_.Id -ne [string]$script:PendingRuleId })
        Save-AuRules $rs
        Update-SmHeader
        Render-SmRules
    } $true
}

function Add-AuTemplate([int]$Index) {
    $t = @($script:AuTemplates)[$Index]
    if ($null -eq $t) { return }
    $rs = New-Object System.Collections.ArrayList
    foreach ($r in (Get-AuRules)) { [void]$rs.Add($r) }
    [void]$rs.Add((New-AuRule $t))
    Save-AuRules $rs.ToArray()
    Show-Toast ('Kural eklendi (kapal' + [char]0x0131 + '). A' + [char]0x00E7 + 'mak i' + [char]0x00E7 + 'in kural' + [char]0x0131 + 'n ' + [char]0x201C + 'A' + [char]0x00E7 + '' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n.') 'good'
    Render-SmRules
}

function Get-AuRuleRunText($Rule) {
    $t = Get-AuRuleText $Rule
    if ([string]$Rule.Last -ne '') { $t += (('  ' + [char]0x00B7 + '  son ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma: ') + [string]$Rule.Last) }
    $k = [string]$Rule.Do.Kind
    if ($k -eq 'Mem' -and $script:Settings.OptRam -ne $true) { $t += ('  ' + [char]0x00B7 + '  (bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ' Ayarlar' + [char]0x2019 + 'da kapal' + [char]0x0131 + '; bu eylem atlan' + [char]0x0131 + 'r)') }
    if ($k -eq 'Focus' -and $script:Settings.OptFocus -ne $true) { $t += ('  ' + [char]0x00B7 + '  (odak kipi Ayarlar' + [char]0x2019 + 'da kapal' + [char]0x0131 + '; bu eylem atlan' + [char]0x0131 + 'r)') }
    if ([string]$Rule.When.Kind -eq 'Temp' -and -not ($sync.Mon.ContainsKey('Temp') -and [double]$sync.Mon.Temp -gt 0)) { $t += ('  ' + [char]0x00B7 + '  (bu bilgisayarda s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k okunam' + [char]0x0131 + 'yor)') }
    return $t
}

function Render-SmRules {
    $ui.sm_List.Children.Clear()
    if ($null -ne $script:SmEdit) { Render-SmEditor; return }
    Show-OnlyBar 'sm' @('sm_RuleNew')
    $ao = ($script:Settings.AutoOn -eq $true)
    $tg = ('kapal' + [char]0x0131 + ''); $br = 'BrFaint'; $b = ('A' + [char]0x00E7 + '')
    if ($ao) { $tg = ('A' + [char]0x00C7 + 'IK'); $br = 'BrGood'; $b = 'Kapat' }
    $det = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'k kurallar, ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm motoru da a' + [char]0x00E7 + '' + [char]0x0131 + 'kken ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r. Zamanl' + [char]0x0131 + ' kurallar uygulama a' + [char]0x00E7 + '' + [char]0x0131 + 'kken (tepsideyken de) ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r; bilgisayar kapal' + [char]0x0131 + 'yken ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'maz.')
    if ($script:Settings.OptSmart -ne $true) { $det += (' ' + [char]0x015E + 'u an ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm motoru kapal' + [char]0x0131 + '.') }
    Add-SmRow ('Otomasyon kurallar' + [char]0x0131 + '') $det $tg $br 'autoToggle' $b
    $rules = @(Get-AuRules)
    Add-HeadRow $ui.sm_List (('Kurallar' + [char]0x0131 + 'm (') + [string]$rules.Count + ')')
    if ($rules.Count -eq 0) { Add-Note $ui.sm_List ('Hen' + [char]0x00FC + 'z kural yok. A' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'daki haz' + [char]0x0131 + 'r ' + [char]0x015F + 'ablonlardan ekleyin ya da ' + [char]0x201C + 'Yeni kural' + [char]0x201D + ' ile kendiniz olu' + [char]0x015F + 'turun.') }
    foreach ($r in $rules) {
        $on = ($r.On -eq $true)
        $t2 = ('kapal' + [char]0x0131 + ''); $b2 = 'BrFaint'; $bb = ('A' + [char]0x00E7 + '')
        if ($on) { $t2 = ('A' + [char]0x00C7 + 'IK'); $b2 = 'BrAccent'; $bb = 'Kapat' }
        Add-SmRow ([string]$r.Name) (Get-AuRuleRunText $r) $t2 $b2 'ruleToggle' $bb 'ruleDel' 'Sil' @{ Id = [string]$r.Id }
    }
    Add-HeadRow $ui.sm_List ('Haz' + [char]0x0131 + 'r ' + [char]0x015F + 'ablonlar')
    $i = 0
    foreach ($t in $script:AuTemplates) {
        Add-SmRow ([string]$t.Name) (Get-AuRuleText (New-AuRule $t)) '' 'BrBlue' 'tplAdd' 'Ekle' '' '' @{ Index = $i }
        $i++
    }
    $ui.sm_Foot.Text = (Tr $(('Kurallar yaln' + [char]0x0131 + 'zca bu bilgisayarda, uygulaman' + [char]0x0131 + 'n kendi ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'mleriyle ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r. Her kural' + [char]0x0131 + 'n yapt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r.')))
}

# ---------------- yeni kural duzenleyicisi ----------------
function New-SmEdit {
    return @{ When = 'Ram'; Op = 'gt'; Val = 90; For = 120; Arg = ''; At = '03:00'; Days = @(); Do = 'Notify'; DoArg = ''; Cool = 30 }
}

function Get-SmValChoices([string]$Kind) {
    $c = New-Object System.Collections.ArrayList
    $vals = @()
    switch ($Kind) {
        'Ram' { $vals = @(50, 60, 70, 75, 80, 85, 90, 92, 95, 98) }
        'Cpu' { $vals = @(50, 60, 70, 80, 85, 90, 95, 98) }
        'Temp' { $vals = @(60, 65, 70, 75, 80, 85, 88, 90, 95) }
        'Battery' { $vals = @(5, 10, 15, 20, 25, 30, 40, 50, 80, 90) }
        'Disk' { $vals = @(1, 2, 5, 10, 15, 20, 30, 50, 100) }
    }
    $u = [string]$script:AuWhen[$Kind].Unit
    foreach ($v in $vals) { [void]$c.Add(@{ V = $v; L = ([string]$v + ' ' + $u) }) }
    return $c.ToArray()
}

$script:H_SmEdit = { param($key, $ch) Set-SmEditField $key $ch }

function Set-SmEditField([string]$Key, $Ch) {
    $e = $script:SmEdit
    if ($null -eq $e) { return }
    switch ($Key) {
        'au.when' {
            $e.When = [string]$Ch.V
            $wd = $script:AuWhen[$e.When]
            if ([string]$wd.K -eq 'Num') { $e.Op = [string]$wd.Op; $e.Val = [int]$wd.Def; $e.For = [int]$wd.For }
            if ($null -ne $wd.Args) { $e.Arg = [string]@($wd.Args.Keys | Sort-Object)[0] } else { $e.Arg = '' }
            Render-SmEditor; return
        }
        'au.op' { $e.Op = [string]$Ch.V }
        'au.val' { $e.Val = [int]$Ch.V }
        'au.for' { $e.For = [int]$Ch.V }
        'au.arg' { $e.Arg = [string]$Ch.V }
        'au.at' { $e.At = [string]$Ch.V }
        'au.days' { $e.Days = @($Ch.V) }
        'au.do' {
            $e.Do = [string]$Ch.V
            $dd = $script:AuDo[$e.Do]
            if ($null -ne $dd.Args) { $e.DoArg = [string]@($dd.Args.Keys | Sort-Object)[0] } else { $e.DoArg = '' }
            Render-SmEditor; return
        }
        'au.doarg' { $e.DoArg = [string]$Ch.V }
        'au.cool' { $e.Cool = [int]$Ch.V }
    }
    Update-SmEditSummary
}

function New-SmRuleFromEdit {
    $e = $script:SmEdit
    $w = @{ Kind = [string]$e.When }
    $wd = $script:AuWhen[$e.When]
    switch ([string]$wd.K) {
        'Num' { $w.Op = [string]$e.Op; $w.Val = [int]$e.Val; $w.For = [int]$e.For }
        'Time' { $w.At = [string]$e.At; $w.Days = @($e.Days) }
        default { $w.Arg = [string]$e.Arg }
    }
    $d = @{ Kind = [string]$e.Do }
    if ([string]$e.DoArg -ne '') { $d.Arg = [string]$e.DoArg }
    $r = @{ Id = [guid]::NewGuid().ToString('N').Substring(0, 8); On = $true; Name = ''; When = $w; Do = $d; Cool = [int]$e.Cool; Last = '' }
    $r.Name = Get-AuRuleText $r
    return $r
}

function Update-SmEditSummary {
    if ($null -eq $script:SmEditSum) { return }
    $script:SmEditSum.Text = (Tr $(('Kural: ' + (Get-AuRuleText (New-SmRuleFromEdit)))))
}

function Render-SmEditor {
    $ui.sm_List.Children.Clear()
    Show-OnlyBar 'sm' @('sm_RuleSave', 'sm_RuleCancel')
    $e = $script:SmEdit
    Add-HeadRow $ui.sm_List ('Yeni otomasyon kural' + [char]0x0131 + ': ' + [char]0x00F6 + 'nce ko' + [char]0x015F + 'ul, sonra eylem')
    $wc = New-Object System.Collections.ArrayList
    foreach ($k in $script:AuWhen.Keys) { [void]$wc.Add(@{ V = [string]$k; L = [string]$script:AuWhen[$k].L }) }
    [void](Add-Step1Row $ui.sm_List 'au.when' 'Ne olunca?' '' $wc.ToArray() (Find-ChoiceIndex $wc.ToArray() $e.When) $script:H_SmEdit)
    $wd = $script:AuWhen[$e.When]
    switch ([string]$wd.K) {
        'Num' {
            $oc = @(@{ V = 'gt'; L = ('' + [char]0x00FC + 'st' + [char]0x00FC + 'ne ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'nca') }, @{ V = 'lt'; L = ('alt' + [char]0x0131 + 'na inince') })
            [void](Add-Step1Row $ui.sm_List 'au.op' ('Y' + [char]0x00F6 + 'n') '' $oc (Find-ChoiceIndex $oc $e.Op) $script:H_SmEdit)
            $vc = Get-SmValChoices ([string]$e.When)
            [void](Add-Step1Row $ui.sm_List 'au.val' ('E' + [char]0x015F + 'ik') '' $vc (Find-ChoiceIndex $vc $e.Val) $script:H_SmEdit)
            $fc = @(@{ V = 0; L = 'hemen' }, @{ V = 10; L = ('10 saniye s' + [char]0x00FC + 'rerse') }, @{ V = 30; L = ('30 saniye s' + [char]0x00FC + 'rerse') }, @{ V = 60; L = ('1 dakika s' + [char]0x00FC + 'rerse') }, @{ V = 120; L = ('2 dakika s' + [char]0x00FC + 'rerse') }, @{ V = 300; L = ('5 dakika s' + [char]0x00FC + 'rerse') }, @{ V = 600; L = ('10 dakika s' + [char]0x00FC + 'rerse') })
            [void](Add-Step1Row $ui.sm_List 'au.for' ('S' + [char]0x00FC + 're') ('K' + [char]0x0131 + 'sa s' + [char]0x0131 + '' + [char]0x00E7 + 'ramalarda tetiklenmemesi i' + [char]0x00E7 + 'in ko' + [char]0x015F + 'ulun ne kadar s' + [char]0x00FC + 'rmesi gerekti' + [char]0x011F + 'i.') $fc (Find-ChoiceIndex $fc $e.For) $script:H_SmEdit)
        }
        'Time' {
            $tc = New-Object System.Collections.ArrayList
            for ($h = 0; $h -lt 24; $h++) { foreach ($mm in @('00', '30')) { $s = ('{0:00}:{1}' -f $h, $mm); [void]$tc.Add(@{ V = $s; L = $s }) } }
            [void](Add-Step1Row $ui.sm_List 'au.at' 'Saat' ('Bilgisayar ve uygulama o saatte a' + [char]0x00E7 + '' + [char]0x0131 + 'k olmal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') $tc.ToArray() (Find-ChoiceIndex $tc.ToArray() $e.At) $script:H_SmEdit)
            $dc = @(@{ V = @(); L = ('Her g' + [char]0x00FC + 'n') }, @{ V = @(1, 2, 3, 4, 5); L = ('Hafta i' + [char]0x00E7 + 'i') }, @{ V = @(0, 6); L = 'Hafta sonu' }, @{ V = @(1); L = 'Pazartesi' }, @{ V = @(2); L = ('Sal' + [char]0x0131 + '') }, @{ V = @(3); L = ('' + [char]0x00C7 + 'ar' + [char]0x015F + 'amba') }, @{ V = @(4); L = ('Per' + [char]0x015F + 'embe') }, @{ V = @(5); L = 'Cuma' }, @{ V = @(6); L = 'Cumartesi' }, @{ V = @(0); L = 'Pazar' })
            $di = 0
            for ($i = 0; $i -lt $dc.Count; $i++) { if ((@($dc[$i].V) -join ',') -eq (@($e.Days) -join ',')) { $di = $i } }
            [void](Add-Step1Row $ui.sm_List 'au.days' ('G' + [char]0x00FC + 'n') '' $dc $di $script:H_SmEdit)
        }
        default {
            if ($null -ne $wd.Args) {
                $ac = New-Object System.Collections.ArrayList
                foreach ($k in @($wd.Args.Keys | Sort-Object)) { [void]$ac.Add(@{ V = [string]$k; L = [string]$wd.Args[$k] }) }
                [void](Add-Step1Row $ui.sm_List 'au.arg' 'Olay' '' $ac.ToArray() (Find-ChoiceIndex $ac.ToArray() $e.Arg) $script:H_SmEdit)
            }
        }
    }
    $dc2 = New-Object System.Collections.ArrayList
    foreach ($k in $script:AuDo.Keys) { [void]$dc2.Add(@{ V = [string]$k; L = [string]$script:AuDo[$k].L }) }
    [void](Add-Step1Row $ui.sm_List 'au.do' ('Ne yap' + [char]0x0131 + 'ls' + [char]0x0131 + 'n?') '' $dc2.ToArray() (Find-ChoiceIndex $dc2.ToArray() $e.Do) $script:H_SmEdit)
    $dd = $script:AuDo[$e.Do]
    if ($null -ne $dd.Args) {
        $xc = New-Object System.Collections.ArrayList
        foreach ($k in @($dd.Args.Keys | Sort-Object)) { [void]$xc.Add(@{ V = [string]$k; L = [string]$dd.Args[$k] }) }
        [void](Add-Step1Row $ui.sm_List 'au.doarg' ('Se' + [char]0x00E7 + 'enek') '' $xc.ToArray() (Find-ChoiceIndex $xc.ToArray() $e.DoArg) $script:H_SmEdit)
    }
    $cc = @()
    foreach ($v in @(1, 5, 10, 15, 30, 60, 120, 240, 720, 1440)) { $l = ([string]$v + ' dakika'); if ($v -ge 60) { $l = ([string]($v / 60) + ' saat') }; $cc += @{ V = $v; L = $l } }
    [void](Add-Step1Row $ui.sm_List 'au.cool' ('Tekrar i' + [char]0x00E7 + 'in bekle') ('Kural ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'ktan sonra bu s' + [char]0x00FC + 're i' + [char]0x00E7 + 'inde yeniden ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'maz.') $cc (Find-ChoiceIndex $cc $e.Cool) $script:H_SmEdit)
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $tb.Margin = New-Object System.Windows.Thickness -ArgumentList 4, 10, 4, 4
    $tb.FontSize = 13
    $tb.Foreground = (Get-Br 'BrAccent')
    [void]$ui.sm_List.Children.Add($tb)
    $script:SmEditSum = $tb
    Update-SmEditSummary
    $ui.sm_Foot.Text = (Tr $(('Kaydedilen kural a' + [char]0x00E7 + '' + [char]0x0131 + 'k olarak eklenir; ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in otomasyon kurallar' + [char]0x0131 + ' ve ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm motorunun da a' + [char]0x00E7 + '' + [char]0x0131 + 'k olmas' + [char]0x0131 + ' gerekir.')))
}

function Save-SmEdit {
    if ($null -eq $script:SmEdit) { return }
    $r = New-SmRuleFromEdit
    $rs = New-Object System.Collections.ArrayList
    foreach ($x in (Get-AuRules)) { [void]$rs.Add($x) }
    [void]$rs.Add($r)
    Save-AuRules $rs.ToArray()
    $script:SmEdit = $null
    $script:SmEditSum = $null
    Show-Toast ('Kural kaydedildi: ' + [string]$r.Name) 'good'
    Update-SmHeader
    Render-SmRules
}

# ---------------- donanim omru ----------------
function Load-SmLife {
    [void](Start-Async 'Lifespan' 'Job_Lifespan' @{} {
        param($r)
        $script:SmLife = $r
        if ($script:UiState.Page -eq 'smart' -and $script:SmTab -eq 'life') { Render-SmLife }
    } ('Donan' + [char]0x0131 + 'm sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor'))
}

function Render-SmLife {
    $ui.sm_List.Children.Clear()
    if ($null -eq $script:SmLife) { Set-ListNote $ui.sm_List ('Diskler, pil, s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k ve a' + [char]0x00E7 + '' + [char]0x0131 + 'k kalma s' + [char]0x00FC + 'resi ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor...'); Load-SmLife; return }
    foreach ($x in @($script:SmLife.Rows)) {
        $br = 'BrGood'; $tg = 'iyi'
        switch ([string]$x.Status) { 'warn' { $br = 'BrWarn'; $tg = 'dikkat' } 'bad' { $br = 'BrBad'; $tg = ('k' + [char]0x00F6 + 't' + [char]0x00FC + '') } 'info' { $br = 'BrInfo'; $tg = 'bilgi' } }
        $row = New-ItemRow @{ Title = [string]$x.Title; Detail = ([string]$x.Value + ('  ' + [char]0x2014 + '  ') + [string]$x.Hint); Tag = $tg; BrCol = $br } @{ } $false $false
        [void]$ui.sm_List.Children.Add($row)
    }
    $ui.sm_Foot.Text = (Tr $(('Bu ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'mler yaln' + [char]0x0131 + 'zca okunur. Disk ' + [char]0x00F6 + 'mr' + [char]0x00FC + ' ve s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k bilgisi diskin ve anakart' + [char]0x0131 + 'n Windows' + [char]0x2019 + 'a verdi' + [char]0x011F + 'i kadar' + [char]0x0131 + 'yla g' + [char]0x00F6 + 'sterilir.')))
}

# ---------------- mini izleyici ----------------
$script:Widget = $null
$script:WdCorners = @(@{ V = 'TR'; L = ('Sa' + [char]0x011F + ' ' + [char]0x00FC + 'st') }, @{ V = 'BR'; L = ('Sa' + [char]0x011F + ' alt') }, @{ V = 'TL'; L = ('Sol ' + [char]0x00FC + 'st') }, @{ V = 'BL'; L = 'Sol alt' }, @{ V = 'Free'; L = ('Serbest (s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleyerek)') })
$script:WdOpac = @(@{ V = 100; L = '%100' }, @{ V = 90; L = '%90' }, @{ V = 80; L = '%80' }, @{ V = 70; L = '%70' }, @{ V = 60; L = '%60' })

function Set-WidgetPos {
    $w = $script:Widget
    if ($null -eq $w) { return }
    $wa = [System.Windows.SystemParameters]::WorkArea
    $m = 12.0
    $ww = [double]$w.ActualWidth; $wh = [double]$w.ActualHeight
    if ($ww -le 0) { $ww = 220 }; if ($wh -le 0) { $wh = 170 }
    $c = [string]$script:Settings.WidgetCorner
    switch ($c) {
        'TL' { $w.Left = $wa.Left + $m; $w.Top = $wa.Top + $m }
        'BL' { $w.Left = $wa.Left + $m; $w.Top = $wa.Bottom - $wh - $m }
        'BR' { $w.Left = $wa.Right - $ww - $m; $w.Top = $wa.Bottom - $wh - $m }
        'Free' {
            $x = $wa.Right - $ww - $m; $y = $wa.Top + $m
            try { $x = [double]$script:Settings.WidgetX; $y = [double]$script:Settings.WidgetY } catch { }
            $x = [math]::Max($wa.Left, [math]::Min($x, $wa.Right - $ww))
            $y = [math]::Max($wa.Top, [math]::Min($y, $wa.Bottom - $wh))
            $w.Left = $x; $w.Top = $y
        }
        default { $w.Left = $wa.Right - $ww - $m; $w.Top = $wa.Top + $m }
    }
}

function Open-Widget {
    if ($null -ne $script:Widget) { return }
    $w = Read-LocalXaml ($script:XamlWidget)
    Register-XamlNames $script:XamlWidget $w
    $op = 100
    try { $op = [int]$script:Settings.WidgetOpacity } catch { }
    if ($op -lt 40 -or $op -gt 100) { $op = 100 }
    $w.Opacity = $op / 100.0
    $ui.wd_Close.Add_Click({ Invoke-Safe { Set-OptValue 'OptWidget' $false; Close-Widget; if ($script:UiState.Page -eq 'smart') { Render-SmTab } } 'Mini izleyici' })
    $ui.wd_Root.Add_MouseLeftButtonDown({
        param($s, $e)
        try {
            $script:Widget.DragMove()
            $script:Settings.WidgetCorner = 'Free'
            Set-OptValue 'WidgetX' ([int]$script:Widget.Left)
            Set-OptValue 'WidgetY' ([int]$script:Widget.Top)
            Set-OptValue 'WidgetCorner' 'Free'
        } catch { }
    })
    $w.Add_ContentRendered({ try { Set-WidgetPos } catch { } })
    # Alt+F4 ile kapatilirsa her turda yeniden acilmasin: kapali sayilir (uygulama kapanirken ayar korunur)
    $w.Add_Closed({
        $script:Widget = $null
        if ($script:Quitting -ne $true -and $script:Settings.OptWidget -eq $true) { try { Set-OptValue 'OptWidget' $false } catch { } }
    })
    $script:Widget = $w
    $w.Show()
    $m = $sync.Mon
    if ($null -ne $m -and $m.ContainsKey('Cpu')) { Update-Widget $m }
}

function Close-Widget {
    if ($null -eq $script:Widget) { return }
    try { $script:Widget.Close() } catch { }
    $script:Widget = $null
}

function Sync-Widget {
    $want = ($script:Settings.OptWidget -eq $true)
    if ($want -and $null -eq $script:Widget) { try { Open-Widget } catch { $script:Widget = $null; Write-CrashLog ('Mini izleyici: ' + $_.Exception.Message) } }
    elseif (-not $want -and $null -ne $script:Widget) { Close-Widget }
}

function Set-WdBar([string]$K, [double]$Pct) {
    $b = $ui['wd_B' + $K]
    if ($null -eq $b) { return }
    $p = [math]::Max(0.0, [math]::Min(100.0, $Pct))
    $b.Width = 84.0 * $p / 100.0
}

function Update-Widget($M) {
    if ($null -eq $script:Widget) { return }
    $ui.wd_VCpu.Text = (Tr $((Format-Percent ([int][double]$M.Cpu)))); Set-WdBar 'Cpu' ([double]$M.Cpu)
    $ui.wd_VRam.Text = (Tr $((Format-Percent ([int][double]$M.Ram)))); Set-WdBar 'Ram' ([double]$M.Ram)
    $g = [double]$M.Gpu
    if ($g -ge 0) { $ui.wd_VGpu.Text = (Tr $((Format-Percent ([int]$g)))); Set-WdBar 'Gpu' $g } else { $ui.wd_VGpu.Text = (Tr $('--')); Set-WdBar 'Gpu' 0 }
    $ui.wd_VDisk.Text = (Tr $((Format-Percent ([int][double]$M.Disk)))); Set-WdBar 'Disk' ([double]$M.Disk)
    $ui.wd_VNet.Text = (Tr $(((Format-Mbps ([double]$M.NetDown)) -replace ' Mb/sn', '') + ' / ' + (Format-Mbps ([double]$M.NetUp))))
    $t = -1.0
    if ($M.ContainsKey('Temp')) { $t = [double]$M.Temp }
    if ($t -gt 0) { $ui.wd_VTemp.Text = (Tr $(([string][int]$t + (' ' + [char]0x00B0 + 'C')))); Set-WdBar 'Temp' $t } else { $ui.wd_VTemp.Text = (Tr $('--')); Set-WdBar 'Temp' 0 }
}

function Render-SmWidget {
    $ui.sm_List.Children.Clear()
    $on = ($script:Settings.OptWidget -eq $true)
    $tg = ('kapal' + [char]0x0131 + ''); $br = 'BrFaint'; $b = ('A' + [char]0x00E7 + '')
    if ($on) { $tg = ('A' + [char]0x00C7 + 'IK'); $br = 'BrGood'; $b = 'Kapat' }
    Add-SmRow 'Mini izleyici' ('Ekran' + [char]0x0131 + 'n k' + [char]0x00F6 + '' + [char]0x015F + 'esinde her zaman ' + [char]0x00FC + 'stte duran k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k bir pencere: i' + [char]0x015F + 'lemci, bellek, ekran kart' + [char]0x0131 + ', disk, a' + [char]0x011F + ' ve s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k. S' + [char]0x00FC + 'r' + [char]0x00FC + 'kleyerek ta' + [char]0x015F + '' + [char]0x0131 + 'yabilir, ' + [char]0x00D7 + ' ile kapatabilirsiniz. Ana pencere tepsideyken de ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.') $tg $br 'widget' $b
    $ci = Find-ChoiceIndex $script:WdCorners ([string]$script:Settings.WidgetCorner)
    [void](Add-Step1Row $ui.sm_List 'wd.corner' 'Konum' '' $script:WdCorners $ci { param($key, $ch) Set-OptValue 'WidgetCorner' ([string]$ch.V); Set-WidgetPos })
    $oi = Find-ChoiceIndex $script:WdOpac $script:Settings.WidgetOpacity
    [void](Add-Step1Row $ui.sm_List 'wd.opac' ('Saydaml' + [char]0x0131 + 'k') '' $script:WdOpac $oi { param($key, $ch) Set-OptValue 'WidgetOpacity' ([int]$ch.V); if ($null -ne $script:Widget) { $script:Widget.Opacity = [int]$ch.V / 100.0 } })
    if (-not ($sync.Mon.ContainsKey('Temp') -and [double]$sync.Mon.Temp -gt 0)) { Add-Note $ui.sm_List ('Bu bilgisayar ' + [char]0x0131 + 's' + [char]0x0131 + ' sens' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' Windows' + [char]0x2019 + 'a a' + [char]0x00E7 + 'm' + [char]0x0131 + 'yor; s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ' + [char]0x201C + '--' + [char]0x201D + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.') }
    $ui.sm_Foot.Text = (Tr $(('Mini izleyici Ayarlar > ' + [char]0x0130 + 'ste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellikler' + [char]0x2019 + 'den de a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'p kapat' + [char]0x0131 + 'labilir.')))
}

function Render-SmTab {
    if ($null -eq $ui.sm_List) { return }
    Update-SmHeader
    switch ($script:SmTab) {
        'care' { Show-OnlyBar 'sm' @(); Render-SmCare }
        'rules' { Render-SmRules }
        'life' { Show-OnlyBar 'sm' @('sm_LifeRun', 'sm_BatRep'); Render-SmLife }
        'widget' { Show-OnlyBar 'sm' @(); Render-SmWidget }
    }
}

function Set-SmTab([string]$Tab) {
    $script:SmTab = $Tab
    if ($Tab -ne 'rules') { $script:SmEdit = $null }
    Render-SmTab
}

function Init-Page_smart {
    Register-Tabs 'sm' $script:SmTabs { param($s, $e) Invoke-Safe { Set-SmTab ([string]$s.Tag) } 'Sekme' }
    $ui.sm_Master.Add_Click({ Invoke-Safe { Invoke-SmAct 'master' $null } ('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm') })
    $ui.sm_RuleNew.Add_Click({ Invoke-Safe { $script:SmEdit = New-SmEdit; Render-SmRules } 'Yeni kural' })
    $ui.sm_RuleSave.Add_Click({ Invoke-Safe { Save-SmEdit } 'Kural' })
    $ui.sm_RuleCancel.Add_Click({ Invoke-Safe { $script:SmEdit = $null; Render-SmRules } 'Kural' })
    $ui.sm_LifeRun.Add_Click({ Invoke-Safe { $script:SmLife = $null; Render-SmLife } ('' + [char]0x00D6 + 'l' + [char]0x00E7 + '') })
    $ui.sm_BatRep.Add_Click({ Invoke-Safe { Invoke-SmAct 'batrep' $null } 'Pil raporu' })
}

function Select-Sub_smart([string]$Sub) {
    if (-not (Select-TabChip 'sm' $Sub)) { Set-SmTab $Sub }
}

function Show-Page_smart {
    $script:SmTab = Get-TabKey 'sm' $script:SmTabs 'care'
    Render-SmTab
}

# ---------------- akilli bakim motoru (izleyici zamanlayicisindan, 2 saniyede bir) ----------------
function Update-SmSlow {
    $l = Get-PwLive
    $script:SmSlow.HasBattery = [bool]$l.HasBattery
    $script:SmSlow.Battery = [double]$l.Percent
    $script:SmSlow.Online = [bool]$l.Online
    try {
        $di = New-Object System.IO.DriveInfo(([string]$env:SystemDrive).Substring(0, 1))
        $script:SmSlow.FreeGB = [math]::Round([double]$di.AvailableFreeSpace / 1GB, 1)
    } catch { }
    $needGame = $false
    if ($script:Settings.AutoOn -eq $true) { foreach ($r in (Get-AuRules)) { if ($r.On -eq $true -and [string]$r.When.Kind -eq 'Game') { $needGame = $true } } }
    if ($needGame) {
        if ($null -eq $script:GmGames) { Load-GmGames }
        else { $script:SmSlow.GameOn = ($sync.Mon.ContainsKey('Games') -and @($sync.Mon.Games).Count -gt 0) }
    }
}

function Test-SmBoost($S, $M, [datetime]$Now) {
    if ($script:Settings.SmartBoost -ne $true) { return }
    if ([double]$S.Cpu -ge 90) { $script:SmCnt.CpuHigh++ } else { $script:SmCnt.CpuHigh = 0 }
    if ($script:SmCnt.CpuHigh -lt 20) { return }
    if (($Now - $script:SmLast.Boost).TotalMinutes -lt 15) { return }
    $script:SmLast.Boost = $Now
    $script:SmCnt.CpuHigh = 0
    $t = @(Get-BoostTargets $M.Top)
    if ($t.Count -eq 0) { Add-SmLog ('' + [char]0x0130 + '' + [char]0x015F + 'lemci uzun s' + [char]0x00FC + 'redir yo' + [char]0x011F + 'un; ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'i d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'lebilecek bir arka plan i' + [char]0x015F + 'lemi yok (y' + [char]0x00FC + 'k a' + [char]0x00E7 + '' + [char]0x0131 + 'k bir programdan ya da sistemden geliyor).'); return }
    $x = $t[0]
    $nm = [string]$x.Name; $pct = [string][int][double]$x.Cpu
    if ($script:Settings.SmartBoostAuto -eq $true) {
        [void](Start-Async 'Priority' 'Job_Priority' @{ Pid = [int]$x.Pid; Level = 'BelowNormal' } { param($r) } (('' + [char]0x00D6 + 'ncelik d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'l' + [char]0x00FC + 'yor: ') + $nm) $true $true)
        Add-SmLog (('Performans art' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + ': ') + $nm + ' (%' + $pct + (' i' + [char]0x015F + 'lemci) ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'i d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '; program kapan' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r.'))
        Show-Notify ('Performans art' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + '') ($nm + (' arka planda i' + [char]0x015F + 'lemciyi %') + $pct + (' kullan' + [char]0x0131 + 'yordu; ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'i d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '.')) 'info'
    } else {
        Add-SmLog (('Performans art' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + ': ') + $nm + (' arka planda i' + [char]0x015F + 'lemciyi %') + $pct + (' kullan' + [char]0x0131 + 'yor.'))
        Show-Notify ('' + [char]0x0130 + '' + [char]0x015F + 'lemci yo' + [char]0x011F + 'un') ($nm + (' arka planda i' + [char]0x015F + 'lemciyi %') + $pct + (' kullan' + [char]0x0131 + 'yor. Ara' + [char]0x00E7 + 'lar > ' + [char]0x0130 + '' + [char]0x015F + 'lemler' + [char]0x2019 + 'den ' + [char]0x00F6 + 'nceli' + [char]0x011F + 'ini d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'rebilir ya da kapatabilirsiniz.')) 'warn'
    }
}

function Test-SmThermal($S, [datetime]$Now) {
    if ($script:Settings.SmartThermal -ne $true) { return }
    $t = [double]$S.Temp
    if ($t -le 0) { return }
    $thr = 88
    if ($t -ge $thr) { $script:SmCnt.TempHigh++ } else { $script:SmCnt.TempHigh = 0 }
    if ($t -lt 70) { $script:SmCnt.TempLow++ } else { $script:SmCnt.TempLow = 0 }
    if ($script:SmCapped -and $script:SmCnt.TempLow -ge 60) {
        $script:SmCapped = $false
        $script:SmCnt.TempLow = 0
        Start-SmPlan @(@{ Id = 'smart.thermal'; Title = ('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi: i' + [char]0x015F + 'lemci s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'); Ops = @(@{ T = 'PowerCpuMax'; Ac = [int]$script:SmCapPrev.Ac; Dc = [int]$script:SmCapPrev.Dc }); Reboot = $false }) ('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi')
        Add-SmLog ('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi: s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k d' + [char]0x00FC + '' + [char]0x015F + 't' + [char]0x00FC + '; i' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' eski de' + [char]0x011F + 'erine d' + [char]0x00F6 + 'nd' + [char]0x00FC + '.')
        return
    }
    if ($script:SmCnt.TempHigh -lt 15) { return }
    if (($Now - $script:SmLast.Thermal).TotalMinutes -lt 30) { return }
    $script:SmLast.Thermal = $Now
    $script:SmCnt.TempHigh = 0
    if ($script:Settings.SmartThermalAuto -eq $true -and -not $script:SmCapped) {
        $prev = $null
        try { $a = Get-PwActive; $prev = Get-PwValue ([string]$a.Guid) (Get-PwDef 'CpuMax') } catch { }
        if ($null -eq $prev) { $prev = @{ Ac = 100; Dc = 100 } }
        $script:SmCapPrev = @{ Ac = [int]$prev.Ac; Dc = [int]$prev.Dc }
        $script:SmCapped = $true
        Start-SmPlan @(@{ Id = 'smart.thermal'; Title = ('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi: i' + [char]0x015F + 'lemci %80 ile s' + [char]0x0131 + 'n' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor'); Ops = @(@{ T = 'PowerCpuMax'; Value = 80 }); Reboot = $false }) ('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi')
        Add-SmLog (('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi: s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k ') + [string][int]$t + (' ' + [char]0x00B0 + 'C; i' + [char]0x015F + 'lemci ge' + [char]0x00E7 + 'ici olarak %80 ile s' + [char]0x0131 + 'n' + [char]0x0131 + 'rland' + [char]0x0131 + '.'))
        Show-Notify ('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi') (('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k ') + [string][int]$t + (' ' + [char]0x00B0 + 'C. ' + [char]0x0130 + '' + [char]0x015F + 'lemci ge' + [char]0x00E7 + 'ici olarak %80 ile s' + [char]0x0131 + 'n' + [char]0x0131 + 'rland' + [char]0x0131 + '; so' + [char]0x011F + 'uyunca eski haline d' + [char]0x00F6 + 'ner.')) 'warn'
    } else {
        Add-SmLog (('Is' + [char]0x0131 + ' y' + [char]0x00F6 + 'netimi: s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k ') + [string][int]$t + (' ' + [char]0x00B0 + 'C.'))
        Show-Notify ('Y' + [char]0x00FC + 'ksek s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k') (('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k ') + [string][int]$t + (' ' + [char]0x00B0 + 'C. Havaland' + [char]0x0131 + 'rmay' + [char]0x0131 + ' ve tozu kontrol edin; G' + [char]0x00FC + '' + [char]0x00E7 + ' sayfas' + [char]0x0131 + 'ndaki ' + [char]0x201C + 'Sessiz ve serin' + [char]0x201D + ' ' + [char]0x015F + 'ablonu ' + [char]0x0131 + 's' + [char]0x0131 + 'y' + [char]0x0131 + ' d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'r.')) 'warn'
    }
}

function Test-SmRam($S, [datetime]$Now) {
    if ($script:Settings.SmartRamAuto -ne $true -or $script:Settings.OptRam -ne $true) { return }
    if ([double]$S.Ram -ge 92) { $script:SmCnt.RamHigh++ } else { $script:SmCnt.RamHigh = 0 }
    if ($script:SmCnt.RamHigh -lt 60) { return }
    if (($Now - $script:SmLast.Ram).TotalMinutes -lt 20) { return }
    $script:SmLast.Ram = $Now
    $script:SmCnt.RamHigh = 0
    if ((Get-ExtProblem 'Bellek') -ne '') { Add-SmLog ('Bellek rahatlatma atland' + [char]0x0131 + ': bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ' eklentisi kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor.'); return }
    [void](Start-Async 'MemTrim' 'Job_MemTrim' @{ Standby = $true } {
        param($r)
        if ($null -ne $r -and $r.Ok -eq $true) { Add-SmLog (('Bellek rahatlatma: bo' + [char]0x015F + ' bellek ') + [string][int]$r.Before + (' MB ' + [char]0x2192 + ' ') + [string][int]$r.After + ' MB') }
    } ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $true $true)
}

function Invoke-AuAction($Rule) {
    $d = $Rule.Do
    $arg = [string]$d.Arg
    $nm = [string]$Rule.Name
    Add-SmLog (('Kural ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + ': ') + $nm)
    switch ([string]$d.Kind) {
        'Power' { Start-SmPlan (New-PowerSetSteps $arg) ('Otomasyon: ' + $nm) }
        'Clean' { Start-SmPlan (New-StepsFromIds ([string[]]@($script:SmSafeClean))) ('Otomasyon: ' + $nm) }
        'Mem' {
            if ($script:Settings.OptRam -eq $true -and (Get-ExtProblem 'Bellek') -eq '') {
                [void](Start-Async 'MemTrim' 'Job_MemTrim' @{ Standby = $true } { param($r) } ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $true $true)
            } else { Add-SmLog ('  atland' + [char]0x0131 + ': bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ' Ayarlar' + [char]0x2019 + 'da kapal' + [char]0x0131 + '') }
        }
        'Focus' {
            if ($script:Settings.OptFocus -eq $true) {
                [void](Start-Async 'Focus' 'Job_Focus' @{ On = ($arg -eq 'on') } { param($r) $script:TlFocus = ($null -ne $r -and $r.On -eq $true); Update-TrayMenuState } 'Odak kipi' $true $true)
            } else { Add-SmLog ('  atland' + [char]0x0131 + ': odak kipi Ayarlar' + [char]0x2019 + 'da kapal' + [char]0x0131 + '') }
        }
        'Cap' {
            $v = 100
            if ($arg -eq '80') { $v = 80 }
            Start-SmPlan @(@{ Id = 'auto.cap'; Title = (('' + [char]0x0130 + '' + [char]0x015F + 'lemci ' + [char]0x00FC + 'st s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' %') + [string]$v); Ops = @(@{ T = 'PowerCpuMax'; Value = $v }); Reboot = $false }) ('Otomasyon: ' + $nm)
        }
        'Notify' {
            $txt = $arg
            if ($txt -eq '') { $txt = Get-AuRuleText $Rule }
            Show-Notify 'Multimizer otomasyon' $txt 'info'
        }
        'Health' { Start-HealthScan 'Quick' $true }
        'Privacy' { Start-SmPlan (New-StepsFromIds (Get-PrivacyShieldIds)) ('Otomasyon: ' + $nm) }
    }
    try {
        $rs = @(Get-AuRules)
        foreach ($r in $rs) { if ([string]$r.Id -eq [string]$Rule.Id) { $r.Last = (Get-Date).ToString('dd.MM HH:mm') } }
        Save-AuRules $rs
    } catch { }
}

function Invoke-SmartTick($M) {
    Sync-Widget
    if ($script:Settings.OptSmart -ne $true) { return }
    $now = Get-Date
    $script:SmN++
    if (($script:SmN % 5) -eq 1) { Update-SmSlow }
    $s = @{
        Ram = [double]$M.Ram; Cpu = [double]$M.Cpu; Temp = -1.0
        Battery = [double]$script:SmSlow.Battery; HasBattery = [bool]$script:SmSlow.HasBattery; Online = [bool]$script:SmSlow.Online
        FreeGB = [double]$script:SmSlow.FreeGB; GameOn = [bool]$script:SmSlow.GameOn; Started = ($script:SmN -le 1)
    }
    if ($M.ContainsKey('Temp')) { $s.Temp = [double]$M.Temp }
    Test-SmBoost $s $M $now
    Test-SmThermal $s $now
    Test-SmRam $s $now
    if ($script:Settings.AutoOn -eq $true) {
        foreach ($r in (Get-AuRules)) {
            if ($r.On -ne $true) { continue }
            $id = [string]$r.Id
            if (-not $script:AuRt.ContainsKey($id)) { $script:AuRt[$id] = @{ Since = $null; Fired = $false; Prev = $null; LastFire = $null; Day = '' } }
            if (Test-AuRule $r $s $script:AuRt[$id] $now) { Invoke-AuAction $r }
        }
    }
}

# Izleyici zamanlayicisinin ek isleri (Update-MonitorUi cagirir)
function Update-MonitorExtras($M) {
    try {
        if ($script:UiState.Page -eq 'gaming' -and $script:Win.IsVisible -and $script:Pages.ContainsKey('gaming')) { Update-GmLive $M }
    } catch { Write-CrashLog (('Oyun g' + [char]0x00F6 + 'stergeleri: ') + $_.Exception.Message) }
    try {
        if ($script:UiState.Page -eq 'power' -and $script:Win.IsVisible -and $null -ne $script:PwInfo) {
            $script:PwLiveTick++
            if (($script:PwLiveTick % 15) -eq 0) { $script:PwInfo.Live = Get-PwLive; Update-PwLive }
        }
    } catch { Write-CrashLog (('G' + [char]0x00FC + '' + [char]0x00E7 + ' durumu: ') + $_.Exception.Message) }
    try { if ($null -ne $script:Widget) { Update-Widget $M } } catch { Write-CrashLog ('Mini izleyici: ' + $_.Exception.Message) }
    try { Invoke-SmartTick $M } catch { Write-CrashLog (('Ak' + [char]0x0131 + 'll' + [char]0x0131 + ' bak' + [char]0x0131 + 'm: ') + $_.Exception.Message) }
}

