$script:ClInfo['SetupLogs'] = ('Windows kurulum (Panther) ve bak' + [char]0x0131 + 'm bile' + [char]0x015F + 'enlerinin 14 g' + [char]0x00FC + 'nden eski g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kleri.')
$script:ClInfo['Delivery'] = ('G' + [char]0x00FC + 'ncellemeleri ba' + [char]0x015F + 'ka bilgisayarlarla payla' + [char]0x015F + 'mak i' + [char]0x00E7 + 'in tutulan ' + [char]0x00F6 + 'nbellek.')
