        $d = $s.Tag
        switch ([string]$d.Key) {
            'cosPrev' { Start-PlanJob @(@{ Id = 'compactos'; Title = 'CompactOS'; Ops = @(@{ T = 'CompactOs'; State = [string]$d.Want }); Reboot = $false }) ('' + [char]0x00D6 + 'nizleme: CompactOS') $true $false }
            'cosRun' { Start-CpCompactOs ([string]$d.Want) }
            'pick' { Start-CpPick }
            'pickRun' { Start-CpRun @([string]$d.Path) 'compress' }
            'pickUndo' { Start-CpRun @([string]$d.Path) 'decompress' }
            'cosCheck' { Start-CpScan }
        }
    } ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r')
}

function Add-CpRow([string]$Title, [string]$Detail, [string]$Tag, [string]$Br, $D1, [string]$B1, $D2 = $null, [string]$B2 = '') {
    $row = New-ItemRow @{ Title = $Title; Detail = $Detail; Tag = $Tag; BrCol = $Br; Btn1 = $B1; Btn2 = $B2 } $D1 $false $false
    if ($B1 -ne '') { $row.FindName('Act').Add_Click($script:H_CpAct) }
    if ($B2 -ne '') { $a2 = $row.FindName('Act2'); $a2.Tag = $D2; $a2.Add_Click($script:H_CpAct) }
    [void]$ui.cl_List.Children.Add($row)
}

function Render-ClCompress {
    $ui.cl_List.Children.Clear()
    $ui.cl_Total.Text = (Tr $(''))
    Add-HeadRow $ui.cl_List ('Windows sistem dosyalar' + [char]0x0131 + ' (CompactOS)')
    $cos = [string]$script:CpCos
    $tag = ('durum ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lmedi'); $want = 'always'; $b2 = ('A' + [char]0x00E7 + ''); $br = 'BrAccent'
    if ($cos -eq 'on') { $tag = ('A' + [char]0x00C7 + 'IK'); $want = 'never'; $b2 = 'Kapat'; $br = 'BrGood' }
    elseif ($cos -eq 'off') { $tag = ('kapal' + [char]0x0131 + '') }
    $det = ('Windows' + [char]0x2019 + 'un kendi sistem dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'r; genelde 2-4 GB yer a' + [char]0x00E7 + 'ar. Dosyalar silinmez, Windows normal ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r. K' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k SSD' + [char]0x2019 + 'si dolmak ' + [char]0x00FC + 'zere olan bilgisayarlar i' + [char]0x00E7 + 'in ' + [char]0x00F6 + 'nerilir; i' + [char]0x015F + 'lem birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer ve Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.')
    if ([string]$sync.Profile.DiskType -eq 'HDD') { $det += (' Bu bilgisayar' + [char]0x0131 + 'n sistem diski mekanik (HDD): a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' biraz yava' + [char]0x015F + 'layabilir.') }
    Add-CpRow 'CompactOS' $det $tag $br @{ Key = 'cosPrev'; Want = $want } ('' + [char]0x00D6 + 'nizle') @{ Key = 'cosRun'; Want = $want } $b2
    Add-HeadRow $ui.cl_List ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma y' + [char]0x00F6 + 'ntemi (klas' + [char]0x00F6 + 'rler i' + [char]0x00E7 + 'in)')
    $ac = New-Object System.Collections.ArrayList
    foreach ($k in $script:CpAlgos.Keys) { [void]$ac.Add(@{ V = [string]$k; L = [string]$script:CpAlgos[$k].Name }) }
    [void](Add-Step1Row $ui.cl_List 'cp.algo' ('Y' + [char]0x00F6 + 'ntem') ([string]$script:CpAlgos[$script:CpAlgo].Info) $ac.ToArray() (Find-ChoiceIndex $ac.ToArray() $script:CpAlgo) {
        param($key, $ch)
        $script:CpAlgo = [string]$ch.V
        $st = $script:StepState[$key]
        if ($null -ne $st.Det) { $st.Det.Text = (Tr $([string]$script:CpAlgos[$script:CpAlgo].Info)); $st.Det.Visibility = $script:VisOn }
    })
    Add-HeadRow $ui.cl_List ('Bir klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r')
    Add-CpRow ('Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + '') ('Bir oyun ya da program klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in; ' + [char]0x00F6 + 'nce boyutu ve tahmini kazan' + [char]0x00E7 + ' g' + [char]0x00F6 + 'sterilir, onaylamadan hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'mez.') '' 'BrAccent2' @{ Key = 'pick' } ('Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + '...')
    $p = $script:CpPick
    if ($null -ne $p) {
        if ($p.Ok -eq $true) {
            $d = ((Format-Size ([double]$p.Bytes)) + ', ' + [string]$p.Files + (' dosya ' + [char]0x00B7 + ' tahmini kazan' + [char]0x00E7 + ' ') + (Format-Size ([double]$p.Save)))
            if ([double]$p.Skip -gt 0) { $d += ((' ' + [char]0x00B7 + ' ') + (Format-Size ([double]$p.Skip)) + (' zaten s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'k (resim, video, ar' + [char]0x015F + 'iv)')) }
            if ($p.Cut -eq $true) { $d += (' ' + [char]0x00B7 + ' tahmin ilk 60 bin dosyaya g' + [char]0x00F6 + 're') }
            Add-CpRow ([string]$p.Path) $d 'tahmin' 'BrAccent' @{ Key = 'pickRun'; Path = [string]$p.Path } ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r') @{ Key = 'pickUndo'; Path = [string]$p.Path } ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rmay' + [char]0x0131 + ' kald' + [char]0x0131 + 'r')
        } else {
            Add-CpRow ([string]$p.Path) ([string]$p.Why) ('uygun de' + [char]0x011F + 'il') 'BrWarn' @{ Key = '' } ''
        }
    }
    Add-HeadRow $ui.cl_List ('' + [char]0x00D6 + 'nerilen klas' + [char]0x00F6 + 'rler')
    if ($null -eq $script:CpScan) {
        Add-Note $ui.cl_List ('' + [char]0x201C + '' + [char]0x00D6 + 'nerilenleri bul' + [char]0x201D + 'a bas' + [char]0x0131 + 'n: oyun kitapl' + [char]0x0131 + 'klar' + [char]0x0131 + ' ve Program Files alt' + [char]0x0131 + 'ndaki b' + [char]0x00FC + 'y' + [char]0x00FC + 'k program klas' + [char]0x00F6 + 'rleri ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'r (hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'mez).')
    } else {
        $rows = @($script:CpScan.Rows)
        if ($rows.Count -eq 0) { Add-Note $ui.cl_List ('250 MB' + [char]0x2019 + 'tan b' + [char]0x00FC + 'y' + [char]0x00FC + 'k uygun klas' + [char]0x00F6 + 'r bulunamad' + [char]0x0131 + '.') }
        foreach ($r in $rows) {
            $row = New-ItemRow @{ Title = ([string]$r.Name + '  (' + [string]$r.Kind + ')'); Detail = [string]$r.Path; Tag = (Format-Size ([double]$r.Bytes)); BrCol = 'BrAccent' } @{ Path = [string]$r.Path; Bytes = [double]$r.Bytes } $true $false
            [void]$ui.cl_List.Children.Add($row)
        }
    }
    $ui.cl_Foot.Text = (Tr $(('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' dosyalar normal a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r; programlar fark' + [char]0x0131 + ' g' + [char]0x00F6 + 'rmez. S' + [char]0x0131 + 'k de' + [char]0x011F + 'i' + [char]0x015F + 'en dosyalar (veritaban' + [char]0x0131 + ', sanal makine) s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz. Windows ve g' + [char]0x00FC + 'venlik klas' + [char]0x00F6 + 'rleri listede yoktur. Her i' + [char]0x015F + 'lem Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.')))
}

function Start-CpScan {
    $script:CpScan = $null
    Set-ListNote $ui.cl_List ('' + [char]0x00D6 + 'nerilen klas' + [char]0x00F6 + 'rler ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor (hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'mez)...')
    $games = @()
    if ($null -ne $script:GmGames) { $games = @($script:GmGames) }
    [void](Start-Async 'CpScan' 'Job_CompressScan' @{ Games = $games } {
        param($r)
        if ($null -eq $r) { $script:CpScan = @{ Rows = @() } } else { $script:CpScan = $r; $script:CpCos = [string]$r.CompactOs }
        if ($script:ClTab -eq 'compress') { Render-ClCompress }
    } ('' + [char]0x00D6 + 'nerilen klas' + [char]0x00F6 + 'rler ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor') $false $true)
}

function Start-CpPick {
    $f = Select-Folder ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (' + [char]0x00F6 + 'r. bir oyunun klas' + [char]0x00F6 + 'r' + [char]0x00FC + ')')
    if ($f -eq '') { return }
    $script:CpPick = $null
    [void](Start-Async 'CpEst' 'Job_CompressEstimate' @{ Path = $f } {
        param($r)
        $script:CpPick = $r
        if ($script:ClTab -eq 'compress') { Render-ClCompress }
    } ('Klas' + [char]0x00F6 + 'r ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor'))
}

function Start-CpRun($Paths, [string]$Mode) {
    $ps = @($Paths | Where-Object { [string]$_ -ne '' })
    if ($ps.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in ya da i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $script:PendingSteps = New-CompressSteps $ps $script:CpAlgo $Mode
    if ($Mode -eq 'decompress') {
        Show-Confirm ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rmay' + [char]0x0131 + ' kald' + [char]0x0131 + 'r') ([string]$ps.Count + (' klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'n s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rmas' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak; dosyalar eski boyutuna d' + [char]0x00F6 + 'ner. Diskte yeterli bo' + [char]0x015F + ' yer olmal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.')) ('Kald' + [char]0x0131 + 'r') {
            Start-PlanJob $script:PendingSteps ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { if ($script:ClTab -eq 'compress') { Render-ClCompress } }
        }
        return
    }
    $txt = ([string]$ps.Count + (' klas' + [char]0x00F6 + 'r ' + [char]0x201C + '') + [string]$script:CpAlgos[$script:CpAlgo].Name + ('' + [char]0x201D + ' y' + [char]0x00F6 + 'ntemiyle s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak:') + "`r`n" + (Format-NameList $ps 8) + "`r`n`r`nDosyalar silinmez; i$([char]0x015F)lem klas$([char]0x00F6)r$([char]0x00FC)n boyutuna g$([char]0x00F6)re birka$([char]0x00E7) dakika ile bir saat aras$([char]0x0131) s$([char]0x00FC)rebilir. Bu s$([char]0x0131)rada o oyun ya da program$([char]0x0131) $([char]0x00E7)al$([char]0x0131)$([char]0x015F)t$([char]0x0131)rmay$([char]0x0131)n. $([char]0x0130)ptal edilebilir; yar$([char]0x0131)da kalan klas$([char]0x00F6)r de sorunsuz $([char]0x00E7)al$([char]0x0131)$([char]0x015F)$([char]0x0131)r.")
    if ([string]$sync.Profile.DiskType -eq 'HDD') { $txt += "`r`n`r`nMekanik diskte y$([char]0x00FC)kleme s$([char]0x00FC)releri biraz uzayabilir." }
    Show-Confirm ('Klas' + [char]0x00F6 + 'rleri s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r') $txt ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r') {
        Start-PlanJob $script:PendingSteps ('Klas' + [char]0x00F6 + 'rler s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { $script:CpPick = $null; if ($script:ClTab -eq 'compress') { Render-ClCompress } }
    }
}

function Start-CpCompactOs([string]$Want) {
    $script:PendingSteps = @(@{ Id = 'compactos'; Title = 'CompactOS'; Ops = @(@{ T = 'CompactOs'; State = $Want }); Reboot = $false })
    $script:CpPendingWant = $Want
    $txt = ('Windows sistem dosyalar' + [char]0x0131 + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak (CompactOS). Birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer; bu s' + [char]0x0131 + 'rada bilgisayar' + [char]0x0131 + ' kapatmay' + [char]0x0131 + 'n. Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'nabilir.')
    if ($Want -eq 'never') { $txt = ('CompactOS kapat' + [char]0x0131 + 'lacak: sistem dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'n s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rmas' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve diskte 2-4 GB daha fazla yer kaplar. Birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rer.') }
    Show-Confirm 'CompactOS' $txt 'Devam' {
        Start-PlanJob $script:PendingSteps ('CompactOS uygulan' + [char]0x0131 + 'yor') $false $false {
            if ([string]$script:CpPendingWant -eq 'always') { $script:CpCos = 'on' } else { $script:CpCos = 'off' }
            if ($script:ClTab -eq 'compress') { Render-ClCompress }
        }
    }
}

function Init-ClCompress {
    $ui.cl_CpScan.Add_Click({ Invoke-Safe { Start-CpScan } ('' + [char]0x00D6 + 'nerilenler') })
    $ui.cl_CpPrev.Add_Click({
        Invoke-Safe {
            $sel = Get-CheckedData $ui.cl_List
            $ps = @(@($sel) | ForEach-Object { [string]$_.Path } | Where-Object { $_ -ne '' })
            if ($ps.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce ' + [char]0x00F6 + 'nerilen klas' + [char]0x00F6 + 'rlerden i' + [char]0x015F + 'aretleyin.') 'warn'; return }
            Start-PlanJob (New-CompressSteps $ps $script:CpAlgo 'compress') ('' + [char]0x00D6 + 'nizleme: s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma') $true $false
        } ('' + [char]0x00D6 + 'nizle')
    })
    $ui.cl_CpRun.Add_Click({ Invoke-Safe { $sel = Get-CheckedData $ui.cl_List; Start-CpRun @(@($sel) | ForEach-Object { [string]$_.Path }) 'compress' } ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r') })
}


# ---------------- Kararlilik ----------------
# ==================================================================
#  KARARLILIK: hata gunlugu siniri, hata firtinasi algilama, guvenli baslangic, gorunumu sifirlama
#  Amac: bir cizim / gorunum hatasi uygulamayi kapatsa ya da hata gunlugunu doldursa bile kullanici kilitli kalmasin;
#        sonraki acilis kendiliginden guvenli (varsayilan gorunumlu) olsun.
# ==================================================================

# ---------------- hata gunlugu (sinirli) ----------------
# Ayni ileti 60 sn icinde yeniden yazilmaz (sayilir, sonraki yazimda belirtilir); gunluk dosyasi bir gunde ~1 MB'ta kesilir.
$script:CrashSeen = @{}
$script:CrashBytes = -1
$script:CrashDay = ''
$script:CrashMaxBytes = 1048576
$script:CrashLineMax = 6000

function Write-CrashLog([string]$Text) {
    try { if ($script:SmokeMode) { Add-SmokeError ('hata g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + '') $Text } } catch { }
    try { $tr = $Text; if ($tr.Length -gt 140) { $tr = $tr.Substring(0, 140) }; Add-Trace (('hata kayd' + [char]0x0131 + ': ') + ($tr -replace '\s+', ' ')) } catch { }
    try {
        $day = Get-Date -Format 'yyyyMMdd'
        $f = Join-Path $script:LogDir ('hata-' + $day + '.txt')
        if ($script:CrashDay -ne $day -or $script:CrashBytes -lt 0) {
            $script:CrashDay = $day
            $script:CrashBytes = 0
            $script:CrashSeen = @{}
            if (Test-Path -LiteralPath $f) { $script:CrashBytes = [long](Get-Item -LiteralPath $f).Length }
        }
        if ($script:CrashBytes -ge $script:CrashMaxBytes) { return }
        $key = $Text
        if ($key.Length -gt 160) { $key = $key.Substring(0, 160) }
        $now = [DateTime]::UtcNow
        $note = ''
        if ($script:CrashSeen.ContainsKey($key)) {
            $e = $script:CrashSeen[$key]
            if (($now - $e.T).TotalSeconds -lt 60) { $e.N = [int]$e.N + 1; return }
            if ([int]$e.N -gt 0) { $note = '  (bu ileti son bir dakikada ' + [string]$e.N + (' kez daha tekrarland' + [char]0x0131 + ')') }
        }
        if ($script:CrashSeen.Count -gt 300) { $script:CrashSeen = @{} }
        $script:CrashSeen[$key] = @{ T = $now; N = 0 }
        $body = $Text
        if ($body.Length -gt $script:CrashLineMax) { $body = $body.Substring(0, $script:CrashLineMax) + '...' }
        $line = (Get-Date -Format 'HH:mm:ss') + '  ' + $body + $note + "`r`n"
        $enc = New-Object System.Text.UTF8Encoding($true)
        [System.IO.File]::AppendAllText($f, $line, $enc)
        $script:CrashBytes = $script:CrashBytes + $line.Length
        if ($script:CrashBytes -ge $script:CrashMaxBytes) {
            [System.IO.File]::AppendAllText($f, ((Get-Date -Format 'HH:mm:ss') + ('  (g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k hata dosyas' + [char]0x0131 + ' s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'na ula' + [char]0x015F + 't' + [char]0x0131 + '; bu g' + [char]0x00FC + 'n i' + [char]0x00E7 + 'in yeni sat' + [char]0x0131 + 'r yaz' + [char]0x0131 + 'lmayacak)') + "`r`n"), $enc)
        }
    } catch { }
}

# Ayni hata kisa surede cok yineleniyorsa $true doner (ekran bildirimi ve oturum gunlugu sismesin): ilk 3 yineleme gecer.
$script:BurstSeen = @{}
function Test-ErrorBurst([string]$Key) {
    $k = $Key
    if ($k.Length -gt 200) { $k = $k.Substring(0, 200) }
    $now = [DateTime]::UtcNow
    if ($script:BurstSeen.Count -gt 300) { $script:BurstSeen = @{} }
    if (-not $script:BurstSeen.ContainsKey($k)) { $script:BurstSeen[$k] = @{ T = $now; N = 1 }; return $false }
    $e = $script:BurstSeen[$k]
    if (($now - $e.T).TotalSeconds -gt 10) { $e.T = $now; $e.N = 1; return $false }
    $e.N = [int]$e.N + 1
    return ([int]$e.N -gt 3)
}

# ---------------- ayarlara guvenli yazim ----------------
# Bellekteki $script:Settings eski kalmis olabilir (arka plan isleri ayar dosyasini kendi okuyup yazar). Bu yuzden degisiklik,
# dosyadan taze okunan nesneye uygulanip kaydedilir; bellekteki nesneye de ayni anahtarlar yansitilir.
function Set-SettingsKeys($Keys) {
    try {
        $st = Get-Settings
        foreach ($k in @($Keys.Keys)) { $st[[string]$k] = $Keys[$k] }
        Save-Settings $st
    } catch { }
    foreach ($k in @($Keys.Keys)) {
        try { $script:Settings[[string]$k] = $Keys[$k] } catch { }
    }
}

# ---------------- guvenli gorunum ----------------
# Hata firtinasinda, guvenli baslangicta ve "GorunumSifirla" komutunda ayni degerler yazilir: arayuzde gomulu en sinanmis tema (Neon), yerlesim (Ayrintili) ve tasarim;
# tasarim ayrintilari tasarimin kendi degerinde; ana ekran en sinanmis bicimde (klasik durum panosu); saydamlik kapali.
function Get-SafeLookKeys([int]$BootTries = 0) {
    return @{
        Theme = 'Neon'; Layout = 'Ayrintili'; Zoom = 100; OptWidget = $false; BootTries = $BootTries
        Design = 'Klasik'; HomeMode = 'Klasik'; DsNav = 'Auto'; DsRadius = 'Auto'; DsFont = 'Auto'; DsGraph = 'Auto'; DsSkin = 'Auto'
        Backdrop = 'Yok'; WinOpacity = 100; TouchTargets = 'Normal'
    }
}

# ---------------- hata firtinasi ----------------
# Cizim sirasinda olusan bir hata her karede yinelenir (gunluk on binlerce satira siser). 5 sn icinde 25 yakalanmamis hata olursa
# uygulama kendini guvenle kapatir ve bir sonraki acilis guvenli gorunumle (Neon, Ayrintili) olur.
$script:UiErrTimes = New-Object System.Collections.ArrayList
$script:UiErrTotal = 0
$script:StormDone = $false
$script:StormLimit = 25
$script:RunFailed = $false

function Register-UiError {
    $script:UiErrTotal = [int]$script:UiErrTotal + 1
    $now = [DateTime]::UtcNow.Ticks
    [void]$script:UiErrTimes.Add($now)
    while ($script:UiErrTimes.Count -gt 0 -and ($now - [long]$script:UiErrTimes[0]) -gt 50000000) { $script:UiErrTimes.RemoveAt(0) }
    return ($script:UiErrTimes.Count -ge [int]$script:StormLimit)
}

function Stop-ErrorStorm {
    if ($script:StormDone) { return }
    $script:StormDone = $true
    Write-CrashLog ('Hata d' + [char]0x00F6 + 'ng' + [char]0x00FC + 's' + [char]0x00FC + ' alg' + [char]0x0131 + 'land' + [char]0x0131 + ': 5 saniyede 25 ya da daha fazla yakalanmam' + [char]0x0131 + '' + [char]0x015F + ' hata. Uygulama kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor; sonraki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' g' + [char]0x00FC + 'venli g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mle olacak.')
    if (-not $script:SmokeMode) { Set-SettingsKeys (Get-SafeLookKeys 2) }
    try { $script:PumpTimer.Stop(); $script:MonTimer.Stop() } catch { }
    try { $script:Win.Hide() } catch { }
    if (-not $script:SmokeMode) {
        try {
            $txt = ('Multimizer, g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mle ilgili tekrarlayan bir hata nedeniyle kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '.') + "`r`n`r`n" + ('Yeniden a' + [char]0x00E7 + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda g' + [char]0x00FC + 'venli g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mle ba' + [char]0x015F + 'layacak.') + "`r`n" + ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ': ') + [string]$script:LogDir
            [void][System.Windows.MessageBox]::Show($txt, 'Multimizer', 'OK', 'Warning')
        } catch { }
    }
    $script:Quitting = $true
    try { $script:App.Shutdown() } catch { try { $script:Win.Close() } catch { } }
}

# ---------------- guvenli baslangic ----------------
# Ust uste iki acilis "ana pencere hatasiz acildi" noktasina varamadiysa gorunum ve mini izleyici varsayilana doner.
$script:SafeBoot = $false
$script:BootOkTimer = $null

function Invoke-BootGuard {
    if ($script:SmokeMode) { return }
    $n = 0
    try { $n = [int]$script:Settings.BootTries } catch { $n = 0 }
    if ($n -ge 2) {
        $script:SafeBoot = $true
        $n = 0
        Write-CrashLog ('G' + [char]0x00FC + 'venli ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ': ' + [char]0x00F6 + 'nceki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'lar tamamlanamad' + [char]0x0131 + '; g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm g' + [char]0x00FC + 'venli de' + [char]0x011F + 'erlere d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '.')
        Set-SettingsKeys (Get-SafeLookKeys 1)
    } else {
        Set-SettingsKeys @{ BootTries = ($n + 1) }
    }
}

function Confirm-BootOk {
    if ($script:SmokeMode) { return }
    if ([int]$script:UiErrTotal -gt 0) { return }
    $n = 0
    try { $n = [int]$script:Settings.BootTries } catch { $n = 0 }
    if ($n -eq 0) { return }
    Set-SettingsKeys @{ BootTries = 0 }
}

function Start-BootOkTimer {
    $script:BootOkTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:BootOkTimer.Interval = [TimeSpan]::FromSeconds(6)
    $script:BootOkTimer.Add_Tick({
        try { $script:BootOkTimer.Stop(); Confirm-BootOk } catch { }
    })
    $script:BootOkTimer.Start()
}

# Pencere hic acilamadiysa: kullaniciya acik bir ileti gosterilir ve bir sonraki acilis guvenli (varsayilan gorunumlu) yapilir.
function Show-StartFailure([string]$Msg) {
    if ($script:SmokeMode) { return }
    # konsol acilis ekrani ileti kutusunun altinda yarim kalmasin
    try { Stop-Splash } catch { }
    Set-SettingsKeys @{ BootTries = 2 }
    $txt = ('Multimizer a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') + "`r`n`r`n" + $Msg + "`r`n`r`n" + ('Uygulamay' + [char]0x0131 + ' yeniden a' + [char]0x00E7 + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda g' + [char]0x00FC + 'venli g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mle ba' + [char]0x015F + 'layacak.') + "`r`n" + ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ': ') + [string]$script:LogDir
    try { [void][System.Windows.MessageBox]::Show($txt, 'Multimizer', 'OK', 'Error') } catch { }
}

# ---------------- gorunumu sifirla (pencere acilmasa da calisir: Baslat.bat -Cli -Gorev GorunumSifirla) ----------------
function Reset-UiSettings {
    $st = Get-Settings
    $safe = Get-SafeLookKeys 0
    foreach ($k in @($safe.Keys)) { $st[[string]$k] = $safe[$k] }
    $st.ReduceMotion = $false
    $st.SmoothScroll = $true
    $st.ToTopButton = $true
    $st.FocusRing = $true
    $st.TouchTargets = 'Auto'
    $st.WidgetX = -1
    $st.WidgetY = -1
    Save-Settings $st
    return $st
}

function Invoke-CliResetUi {
    [void](Reset-UiSettings)
    Write-WhLog ('G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm g' + [char]0x00FC + 'venli de' + [char]0x011F + 'erlere d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + ' (tema: Neon, yerle' + [char]0x015F + 'im: Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ', tasar' + [char]0x0131 + 'm: Klasik ve ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' kendi de' + [char]0x011F + 'erinde, ana ekran: klasik durum panosu, saydaml' + [char]0x0131 + 'k: kapal' + [char]0x0131 + ', yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma: %100, mini izleyici kapal' + [char]0x0131 + ', a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' sayac' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'r). Hi' + [char]0x00E7 + 'bir sistem ayar' + [char]0x0131 + 'na dokunulmad' + [char]0x0131 + '.') 'OK'
    return 0
}


# ---------------- Duman testi ----------------
# ==================================================================
#  DUMAN TESTI (-Duman): arayuzu gercekten acar; her temada her sayfayi olusturup yerlestirir, sekmeleri gezer,
#  satir sablonlarini, bildirim / onay kutusunu, kip degisimini ve mini izleyiciyi dener, Ayarlar sayfasindaki tema
#  dugmelerine gercekten tiklar, salt-okunur tarama ve onizleme dugmelerine basip islerin bitmesini bekler,
#  pencere boyutlarini dener ve her sayfanin ekran goruntusunu alir. Bes temanin hepsini, dort yerlesimi, yakinlastirmayi,
#  fare tekerlegi / klavye kaydirmasini, basa don dugmesini ve tepsiye inmeyi (simge durumu ve X, islem surerken de) gercekten dener.
#  Tasarimlari (Atolye, Sifir Noktasi, Morpheus Agi, Komuta Merkezi), ana ekran panosunu (duzenleme kipi, parca ekleme, kaldirma, gercek fare ile
#  tasima ve boyutlandirma) ve saydamligi (Mica, Akrilik, opaklik adimlari, pencerenin ekrandaki gercek goruntusu) "Duman testi: tasarim ve saydamlik" bolumu sinar.
#  Kapsam: ortam degiskeni MM_DUMAN_KAPSAM = tam (varsayilan) | tepsi | gorunum | tasarim | saydam | dil (araclar klasorundeki Duman-*.cmd dosyalari).
#  Sonuc: %TEMP%\Multimizer-duman.txt  ve  %TEMP%\Multimizer-duman\ekran\*.png
#  Yonetici izni gerekmez: ayarlar ve gunlukler %TEMP%\Multimizer-duman\veri altinda (gercek ayar dosyasinin kopyasiyla) calisir.
#  Hicbir sistem ayarini degistirmez: yalnizca asagidaki "guvenli dugme" listesindeki (tarama, onizleme, yenile, tema) dugmelere basar;
#  "Uygula", "Kaldir", "Temizle", "Kur" gibi eylem dugmelerine basilmaz. Agda cihaz taramasi, hiz testi ve DNS olcumu yapilmaz.
#  Cikis kodu: 0 = hatasiz, 2 = hata var, 3 = zaman asimi.
#  Amac: Linux'ta calismayan butun WPF yollarini gercek Windows'ta bir kez uctan uca yurutmek.
# ==================================================================
$script:SmokeMode = $false
$script:SmokeErrs = New-Object System.Collections.ArrayList
$script:SmokeSteps = New-Object System.Collections.Queue
$script:SmokeCurStep = $null
$script:SmokeTimer = $null
$script:SmokeWaitUntil = [DateTime]::MinValue
$script:SmokeLog = ''
$script:SmokeDir = ''
$script:SmokeExit = 2
$script:SmokeTheme = 'Neon'
$script:SmokeMode0 = 'User'
$script:SmokeStart = $null
$script:SmokeCur = ''
$script:SmokeShots = 0
$script:SmokeDone = $false
$script:SmokeLimitSec = 4800
$script:SmokeDrainSec = 240
$script:SmokeLogPos = 0
$script:SmokeClickAt = $null
$script:SmokeWarns = 0
$script:SmokeClicks = 0
$script:SmokeTrayMin0 = $null
$script:SmokeTraySaved = $false
$script:SmokeTrayOn0 = $null
$script:SmokeLayout = 'Ayrintili'
$script:SmokeScrollPrev = 0.0

# Basilmasina izin verilen dugmeler (hepsi salt okunur: tarama, onizleme, yenileme, tema)
$script:SmokeSafe = @(
    'op_Preview', 'sv_PRec', 'sv_Preview', 'ap_Refresh', 'cl_Scan', 'cl_CpScan', 'pw_Refresh', 'gm_Scan', 'sc_Scan', 'sc_Preview',
    'nw_Refresh', 'nw_ProtScan', 'nw_VpnRefresh', 'bk_RbRefresh', 'bk_BlRefresh', 'co_Report', 'co_TaskRefresh', 'tl_Refresh', 'hi_Refresh',
    'up_Check', 'bd_BtnEdit', 'BtnLogToggle', 'BtnCmdToggle', 'st_DsReset', 'st_BoardEdit', 'st_BoardReset',
    'sl_Scan', 'sl_DiskRefresh', 'sl_ErRefresh', 'sl_PcRefresh', 'sl_PrCheck', 'st_IntCheck', 'BtnHome'
)

# Secim yapilmasina izin verilen acilir listeler (Ayarlar > Gorunum): yalnizca bu pencerenin gorunumunu degistirirler
$script:SmokeSafeSelect = @(
    'st_LookSel', 'st_ThemeSel', 'st_LayoutSel', 'st_ZoomSel', 'st_TouchSel', 'st_DesignSel', 'st_HomeSel', 'st_BackdropSel', 'st_OpacitySel',
    'st_DsNavSel', 'st_DsRadiusSel', 'st_DsFontSel', 'st_DsGraphSel', 'st_DsSkinSel'
)

# Duman testinin denedigi temalar ve yerlesimler (Themes / LayoutInfo tablolariyla ayni olmali; testler karsilastirir)
$script:SmokeThemes = @('Neon', 'Koyu', 'Acik', 'Kum', 'Yuksek', 'Hacker', 'Cam', 'Holo', 'Akis', 'Uzay')
$script:SmokeLayouts = @('Ayrintili', 'Kompakt', 'Sade', 'Hacker')

# Program hatasi sayilan hata kimlikleri (dil bagimsiz); diger hata akisi kayitlari (erisim engellendi, yol yok...) yalnizca uyaridir
$script:SmokeBadIds = 'InvokeMethodOnNull|PropertyNotFound|CommandNotFound|ParameterBinding|NullReference|InvalidCast|IndexOutOfRange|MethodNotFound|ArgumentNull|VariableIsUndefined|ParseException|RuntimeException'

function Add-SmokeLine([string]$Text) {
    $line = (Get-Date -Format 'HH:mm:ss') + '  ' + $Text
    try {
        if ($script:SmokeLog -ne '') { [System.IO.File]::AppendAllText($script:SmokeLog, $line + "`r`n", (New-Object System.Text.UTF8Encoding($true))) }
    } catch { }
}

function Add-SmokeError([string]$Where, [string]$Msg) {
    $m = $Msg
    if ($m.Length -gt 700) { $m = $m.Substring(0, 700) + '...' }
    [void]$script:SmokeErrs.Add(@{ Step = $script:SmokeCur; Where = $Where; Msg = $m })
    Add-SmokeLine ('HATA  [' + $script:SmokeCur + '] ' + $Where + ': ' + $m)
}

function Add-SmokeWarn([string]$Text) {
    $script:SmokeWarns = [int]$script:SmokeWarns + 1
    Add-SmokeLine ('UYARI [' + $script:SmokeCur + '] ' + $Text)
}

function Initialize-Smoke {
    $script:SmokeMode = $true
    # yutulan hatalar da toplanir ve rapor sonunda ozetlenir (gunluk dosyasina da yazilir)
    try { Set-DebugLogState $true } catch { }
    $tmp = [System.IO.Path]::GetTempPath()
    $script:SmokeLog = Join-Path $tmp 'Multimizer-duman.txt'
    try { [void](Initialize-CrashHooks $script:SmokeLog) } catch { }
    $script:SmokeDir = Join-Path (Join-Path $tmp 'Multimizer-duman') 'ekran'
    try { if (Test-Path -LiteralPath $script:SmokeDir) { Remove-Item -LiteralPath $script:SmokeDir -Recurse -Force -ErrorAction SilentlyContinue } } catch { }
    try { [void](New-Item -ItemType Directory -Path $script:SmokeDir -Force) } catch { }
    try { [System.IO.File]::WriteAllText($script:SmokeLog, '', (New-Object System.Text.UTF8Encoding($true))) } catch { }
    # Ikinci acilis sinyali denemesi icin bu surece ozel yerel olay (gercek uygulamanin Global\Multimizer-Goster olayina dokunulmaz)
    try { $script:ShowEvent = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::AutoReset, ('Local\Multimizer-Duman-Goster-' + [string]$PID)) } catch { }
    # Zaman asimi bekcisi: ayri bir is parcaciginda calisir; arayuz kilitlense bile sureci sonlandirir (cikis kodu 3)
    try {
        $wd = [powershell]::Create()
        [void]$wd.AddScript('param($Log, $Sec) Start-Sleep -Seconds $Sec; try { [System.IO.File]::AppendAllText($Log, ((Get-Date -Format "HH:mm:ss") + "  HATA  zaman asimi: duman testi " + $Sec + " sn icinde bitmedi" + [char]13 + [char]10)) } catch { }; [Environment]::Exit(3)')
        [void]$wd.AddArgument($script:SmokeLog)
        if ((Get-SmokeScope) -eq 'ozellik') { $script:SmokeLimitSec = 10800 }
        [void]$wd.AddArgument([int]$script:SmokeLimitSec)
        [void]$wd.BeginInvoke()
    } catch { }
}

# Pencerenin goruntusunu PNG olarak kaydeder (gorsel inceleme icin)
function Save-SmokeShot([string]$Name) {
    try {
        $w = $script:Win
        $pw = [int][math]::Ceiling([double]$w.ActualWidth)
        $ph = [int][math]::Ceiling([double]$w.ActualHeight)
        if ($pw -lt 50 -or $ph -lt 50) { return }
        $fmt = [System.Windows.Media.PixelFormats]::Pbgra32
        $bmp = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($pw, $ph, 96, 96, $fmt)
        $bmp.Render($w)
        $enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
        $enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($bmp))
        $fs = [System.IO.File]::Create((Join-Path $script:SmokeDir ($Name + '.png')))
        try { $enc.Save($fs) } finally { $fs.Dispose() }
        $script:SmokeShots = $script:SmokeShots + 1
        try { Measure-SmokeA11y $Name } catch { Add-SmokeA11yFail $_.Exception.Message }
    } catch { Add-SmokeError ('ekran g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + '') $_.Exception.Message }
}

function New-SmokeStep([string]$Kind, [string]$Arg, [int]$Wait, [string]$Label) {
    $lbl = $Label
    if ($lbl -eq '') { $lbl = $Kind + ' ' + $Arg }
    return @{ Kind = $Kind; Arg = $Arg; Wait = $Wait; Label = $lbl; Until = $null }
}

# Sayfanin sekme dugmelerinin adlari (sayfa tanimindan)
function Get-SmokeTabs([string]$Page) {
    $out = New-Object System.Collections.ArrayList
    $v = Get-Variable -Scope Script -Name ('Page_' + $Page) -ValueOnly -ErrorAction SilentlyContinue
    if ($null -ne $v) {
        foreach ($m in [regex]::Matches([string]$v, 'x:Name="([a-z]{2,3}_Tab_[A-Za-z0-9]+)"')) { [void]$out.Add($m.Groups[1].Value) }
    }
    return $out.ToArray()
}

