# Duman testinin kapsami. "tam" varsayilandir; kisa kapsamlar gelistirme sirasinda hizli yineleme icindir (Duman-Tepsi.cmd, Duman-Gorunum.cmd,
# Duman-Tasarim.cmd, Duman-Saydam.cmd, Duman-Dil.cmd, Duman-Ust.cmd). Kapsam ortam degiskeninden okunur: MM_DUMAN_KAPSAM = tam | tepsi | gorunum | tasarim | saydam | dil | ust | kullanim | ozellik
# "ozellik" kapsami her ozelligi gercek Windows'ta dener (mods/155_live_audit.ps1, 156): Duman-Ozellik.cmd (yonetici) ya da Duman-OzellikOku.cmd (yalnizca okuma).
# "kullanim" kapsami Asistan'i, sol cubuk alt sekme menusunu, Yardimcilar sekmesini ve kisa aciklamalari dener; fareyi oynatmaz, panoya ve ayarlara dokunmaz.
# "ust" kapsami baslik cubugunu dener: ana sayfa emblemi baska sayfadan ana sayfaya doner, dil listesi acilir (dil secilmez), goruntusu alinip ceviri sizintisi taranir.
# "dil" kapsami her sayfayi ve sekmeyi secili arayuz dilinde gezer; ceviri sizintisi ve kutuya sigmayan metin raporu yazar (Multimizer-duman-dil.txt).
$script:SmokeScopes = @{
    tam     = @('sayfa', 'sekme', 'ornek', 'ust', 'kullanim', 'tepsi', 'boyut', 'tema', 'yerlesim', 'dokunma', 'hazir', 'esle', 'tasarim', 'saydam', 'zoom', 'kaydirma', 'kisayol', 'saglik', 'eylem')
    tepsi   = @('tepsi', 'saglik')
    dokunma = @('dokunma')
    gorunum = @('sayfa', 'tema', 'hazir', 'esle')
    tasarim = @('tasarim')
    saydam  = @('saydam')
    dil     = @('sayfa', 'sekme', 'tektema', 'dildenetim', 'ust')
    ust     = @('ust')
    kullanim = @('kullanim')
    ozellik = @('ozellik')
}

function Get-SmokeScope {
    $s = ''
    try { $s = ([string]$env:MM_DUMAN_KAPSAM).Trim().ToLowerInvariant() } catch { $s = '' }
    if ($s -ne '' -and $script:SmokeScopes.ContainsKey($s)) { return $s }
    return 'tam'
}

# Adim kuyrugunu kurar (saf: ekrana dokunmaz; testlerde de kullanilir)
function New-SmokeQueue([string]$Start, [string[]]$Keys, [scriptblock]$TabsOf, [string]$StartLayout = 'Ayrintili', [string]$Scope = 'tam', [string]$StartDesign = 'Klasik', [string]$StartGlass = 'Yok|100', [string]$StartHome = 'Pano|Auto|Auto|Auto|Auto|Auto', [string]$StartTouch = 'Normal') {
    $q = New-Object System.Collections.Queue
    if (-not $script:SmokeScopes.ContainsKey($Scope)) { $Scope = 'tam' }
    $parts = @($script:SmokeScopes[$Scope])
    # denetimler kullanicinin tasarimi ve saydamligi ne olursa olsun Klasik tasarim ve duz pencereyle baslar (kopya ayar dosyasinda); sonda geri yuklenir
    if ($StartDesign -ne 'Klasik') { $q.Enqueue((New-SmokeStep 'Design' 'Klasik' 900 ('tasar' + [char]0x0131 + 'm: Klasik (ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ')'))) }
    if ($StartGlass -ne 'Yok|100') { $q.Enqueue((New-SmokeStep 'Glass' 'Yok|100' 900 ('saydaml' + [char]0x0131 + 'k: kapal' + [char]0x0131 + ' (ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ')'))) }
    # ana ekran bicimi ve tasarim ayrintilari da bilinen degerle baslar (Pano; hepsi tasarimin kendi degerinde)
    if ($StartHome -ne 'Pano|Auto|Auto|Auto|Auto|Auto') { $q.Enqueue((New-SmokeStep 'HomeSet' 'Pano|Auto|Auto|Auto|Auto|Auto' 900 ('ana ekran: pano, ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n de' + [char]0x011F + 'erinde (ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ')'))) }
    # dokunma hedefleri her zaman Normal kipte baslar (Otomatik, dokunmatik ekranda Buyuk olurdu); sonda kullanicinin ayarina doner
    if ($StartTouch -ne 'Normal') { $q.Enqueue((New-SmokeStep 'Touch' 'Normal' 600 ('dokunma hedefleri: Normal (ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ')'))) }
    $themes = @($Start)
    foreach ($t in $script:SmokeThemes) { if ($themes -notcontains $t) { $themes += $t } }
    $themeList = $themes
    if ($parts -notcontains 'sayfa') {
        $themeList = @($themes[0])
        $q.Enqueue((New-SmokeStep 'Page' 'panel' 900 ('sayfa panel (ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ')')))
    } elseif ($parts -contains 'tektema') {
        # dil denetimi: yalnizca gecerli temada gezilir (temalar arasi tekrar gerekmez)
        $themeList = @($themes[0])
    }
    $first = $true
    foreach ($t in $themeList) {
        if (-not $first) { $q.Enqueue((New-SmokeStep 'Theme' $t 250 ('tema ' + $t))) }
        if ($parts -contains 'sayfa') {
          foreach ($k in $Keys) {
            $q.Enqueue((New-SmokeStep 'Page' $k 900 ('sayfa ' + $k + ' / ' + $t)))
            $q.Enqueue((New-SmokeStep 'Shot' ($t + '-' + $k) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' ') + $t + '-' + $k)))
            if ($parts -contains 'dildenetim') { $q.Enqueue((New-SmokeStep 'LangScan' ($k) 0 ('dil denetimi: ' + $k))) }
            if ($first -and ($parts -contains 'sekme')) {
                foreach ($tab in @(& $TabsOf $k)) {
                    $q.Enqueue((New-SmokeStep 'Tab' $tab 500 ('sekme ' + $tab)))
                    $q.Enqueue((New-SmokeStep 'Shot' ($t + '-' + $k + '-' + $tab) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' ') + $tab)))
                    if ($parts -contains 'dildenetim') { $q.Enqueue((New-SmokeStep 'LangScan' ($k + '/' + $tab) 0 ('dil denetimi: ' + $tab))) }
                }
            }
          }
        }
        if ($first) {
          if ($parts -contains 'ornek') {
            # gunluk ve komut satirina ornek satirlar: tema degisince bu satirlarin rengi de degismeli (koddan uretilen ogeler)
            $q.Enqueue((New-SmokeStep 'BrushSeed' '' 300 ('' + [char]0x00F6 + 'rnek g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k sat' + [char]0x0131 + 'rlar' + [char]0x0131 + ' (renk denetimi i' + [char]0x00E7 + 'in)')))
            foreach ($k in @('Templates', 'Toasts', 'Overlay', 'Widget', 'Mode')) { $q.Enqueue((New-SmokeStep $k '' 600 ('deneme ' + $k))) }
            # konsol: hizli duzenleme ("Sec" kipi) kapali mi (yanlislikla tiklamak konsola yazan islemi dondurur)
            $q.Enqueue((New-SmokeStep 'Console' '' 100 ('konsol: h' + [char]0x0131 + 'zl' + [char]0x0131 + ' d' + [char]0x00FC + 'zenleme kapal' + [char]0x0131 + ' m' + [char]0x0131 + '')))
          }
          if ($parts -contains 'ust') {
            # ust cubuk: baska sayfadayken ana sayfa emblemine tiklanir; dil listesi acilir, goruntusu alinir ve kapanir (dil secilmez: secim uygulamayi yeniden baslatirdi)
            $q.Enqueue((New-SmokeStep 'Page' 'settings' 700 ('sayfa settings (ana sayfa emblemi i' + [char]0x00E7 + 'in)')))
            $q.Enqueue((New-SmokeStep 'Click' 'BtnHome' 700 ('d' + [char]0x00FC + '' + [char]0x011F + 'me: ana sayfa emblemi')))
            $q.Enqueue((New-SmokeStep 'UstCheck' 'home' 100 ('ana sayfa: emblem durum panosunu a' + [char]0x00E7 + 't' + [char]0x0131 + ' m' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'Shot' 'ust-ana-sayfa' 200 ('' + [char]0x00FC + 'st ' + [char]0x00E7 + 'ubuk: pencere g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'Screen' 'ust-ana-sayfa' 200 ('' + [char]0x00FC + 'st ' + [char]0x00E7 + 'ubuk: ger' + [char]0x00E7 + 'ek ekran g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'LangPop' 'all' 300 ('dil listesi: a' + [char]0x00E7 + ', g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' al, ' + [char]0x00E7 + 'eviri tara, kapat')))
            $q.Enqueue((New-SmokeStep 'UstCheck' 'lang' 100 ('dil d' + [char]0x00FC + '' + [char]0x011F + 'mesi: kod ve ara' + [char]0x00E7 + ' ipucu')))
          }
          if ($parts -contains 'kullanim') {
            $q.Enqueue((New-SmokeStep 'UxCheck' 'ask' 400 ('Asistan: a' + [char]0x00E7 + ' ve ' + [char]0x00F6 + 'rnek soru sor')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kullanim-asistan' 300 ('Asistan: pencere g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'askclose' 200 'Asistan: kapat'))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'group' 200 ('sol ' + [char]0x00E7 + 'ubuk: grup ge' + [char]0x00E7 + 'ici a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve kapan' + [char]0x0131 + 'r')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'hover' 300 ('sol ' + [char]0x00E7 + 'ubuk: alt sekme men' + [char]0x00FC + 's' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'kit' 600 ('Ara' + [char]0x00E7 + 'lar > Yard' + [char]0x0131 + 'mc' + [char]0x0131 + 'lar: liste, k' + [char]0x0131 + 'sa a' + [char]0x00E7 + '' + [char]0x0131 + 'klamalar, parola ' + [char]0x00FC + 'reteci')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kullanim-yardimcilar' 300 ('Yard' + [char]0x0131 + 'mc' + [char]0x0131 + 'lar: pencere g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'desc' 500 ('Ayarlar: k' + [char]0x0131 + 'sa a' + [char]0x00E7 + '' + [char]0x0131 + 'klamalar')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kullanim-ayarlar' 300 ('Ayarlar: pencere g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'drift' 300 ('geri d' + [char]0x00F6 + 'nen ayarlar: eski ve yeni kural (yaln' + [char]0x0131 + 'zca okuma)')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'pano' 300 ('ana ekran: ekran kart' + [char]0x0131 + ' ve s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k kartlar' + [char]0x0131 + ' (ilk ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm beklenir)')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kullanim-pano' 300 ('ana ekran: pencere g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'Health' '' 1500 ('sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ' (yaln' + [char]0x0131 + 'zca okur)')))
            $q.Enqueue((New-SmokeStep 'Drain' '' 1500 ('i' + [char]0x015F + ' bitsin: sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'sorunlar' 300 ('sorunlar: bulgular ve eylemleri (yaln' + [char]0x0131 + 'zca okuma)')))
            $q.Enqueue((New-SmokeStep 'UxCheck' 'kurulum' 400 ('kurulum teklifi: kutu a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r, se' + [char]0x00E7 + 'im yap' + [char]0x0131 + 'lmadan kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'r')))
          }
          if ($parts -contains 'ozellik') {
            foreach ($lv in @('ortam', 'olcum', 'etki', 'sapma', 'tur:hkcu', 'tur:hklm', 'tur:hizmet', 'tur:ozel', 'tur:tekyon', 'tur:onizleme', 'bilesen', 'arac', 'is:sistem', 'is:depolama', 'is:guncelleme', 'is:ag', 'is:oyun', 'is:saglik', 'sensor', 'bulgu', 'ozet')) {
              $q.Enqueue((New-SmokeStep 'LiveCheck' $lv 300 ('canl' + [char]0x0131 + ' denetim: ' + $lv)))
            }
          }
          if ($parts -contains 'tepsi') {
            # tepsi: simge durumuna kucultunce ve X'e basinca pencere sag alttaki tepsiye iner; ikinci acilis sinyaliyle ve simgeyle geri gelir
            $q.Enqueue((New-SmokeStep 'TrayHide' '' 900 ('tepsiye indir (simge durumuna k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'lt)')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'hidden' 100 'tepsi: pencere gizlendi mi'))
            $q.Enqueue((New-SmokeStep 'TraySignal' '' 400 ('tepsi: ikinci a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' sinyali')))
            $q.Enqueue((New-SmokeStep 'TrayWait' 'shown' 200 ('tepsi: sinyal pencereyi geri getirdi mi (en ' + [char]0x00E7 + 'ok 5 sn beklenir)')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'shown' 100 'tepsi: sinyalle geri geldi mi'))
            $q.Enqueue((New-SmokeStep 'TrayHide' '' 900 'tepsiye indir (yeniden)'))
            $q.Enqueue((New-SmokeStep 'TrayShow' '' 900 'tepsi: simgeyle geri getir'))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'shown' 100 'tepsi: geri geldi mi'))
            $q.Enqueue((New-SmokeStep 'TrayClose' 'btn' 900 ('tepsiye indir (X d' + [char]0x00FC + '' + [char]0x011F + 'mesi)')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'hidden' 100 'tepsi: X pencereyi gizledi mi'))
            $q.Enqueue((New-SmokeStep 'TrayShow' '' 900 ('tepsi: simgeyle geri getir (X sonras' + [char]0x0131 + ')')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'shown' 100 ('tepsi: X sonras' + [char]0x0131 + ' geri geldi mi')))
            $q.Enqueue((New-SmokeStep 'TrayClose' 'alt' 900 ('tepsiye indir (Alt+F4 / pencere kapatma iste' + [char]0x011F + 'i)')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'hidden' 100 'tepsi: Alt+F4 pencereyi gizledi mi'))
            $q.Enqueue((New-SmokeStep 'TrayShow' '' 900 ('tepsi: simgeyle geri getir (Alt+F4 sonras' + [char]0x0131 + ')')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'shown' 100 ('tepsi: Alt+F4 sonras' + [char]0x0131 + ' geri geldi mi')))
            $q.Enqueue((New-SmokeStep 'TrayMinOff' '' 900 ('simge durumu: tepsi kapal' + [char]0x0131 + 'yken g' + [char]0x00F6 + 'rev ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'una insin')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'minimized' 100 'simge durumu: pencere gizlenmedi mi'))
            $q.Enqueue((New-SmokeStep 'TrayShow' '' 900 'simge durumundan geri getir'))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'shown' 100 'simge durumundan geri geldi mi'))
            $q.Enqueue((New-SmokeStep 'TrayDone' '' 100 'tepsi denemesi bitti'))
          }
          if ($parts -contains 'boyut') {
            # sol menu: butun sayfa dugmeleri pencerede gorunuyor mu
            $q.Enqueue((New-SmokeStep 'Rail' 'fit' 300 ('sol men' + [char]0x00FC + ' s' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'yor mu')))
            # pencere boyutlari (en kucuk boyutta yalnizca uyari verilir)
            # duyarli yerlesim: dar ve kisa pencerede gunluk ile komut satiri kendiliginden kapanir, baslik cubugu cakismaz, durum panosu sigar
            $q.Enqueue((New-SmokeStep 'Layout' 'Ayrintili' 600 ('yerle' + [char]0x015F + 'im: ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' (duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im denemesi)')))
            $q.Enqueue((New-SmokeStep 'Resp' 'log:on,cmd:on,title,panel' 300 ('duyarl' + [char]0x0131 + ': varsay' + [char]0x0131 + 'lan boyutta g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k ve komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'k')))
            $q.Enqueue((New-SmokeStep 'Size' '1060x660' 600 ('pencere en k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k boyut')))
            $q.Enqueue((New-SmokeStep 'Page' 'panel' 600 ('sayfa panel (k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere)')))
            $q.Enqueue((New-SmokeStep 'Resp' 'log:off,cmd:off,title,panel,panelfit' 400 ('duyarl' + [char]0x0131 + ': k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencerede g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k ve komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' kendili' + [char]0x011F + 'inden kapand' + [char]0x0131 + ' m' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kucuk-panel' 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere')))
            $q.Enqueue((New-SmokeStep 'Rail' 'warn' 100 ('sol men' + [char]0x00FC + ' (k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere)')))
            $q.Enqueue((New-SmokeStep 'Page' 'optimize' 700 ('sayfa optimize (k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere)')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kucuk-optimize' 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere optimize')))
            # kullanici paneli elle acarsa secimi gecerlidir (kendiliginden yeniden kapanmaz)
            $q.Enqueue((New-SmokeStep 'Click' 'BtnLogToggle' 500 ('d' + [char]0x00FC + '' + [char]0x011F + 'me: g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' elle a' + [char]0x00E7 + ' (k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere)')))
            $q.Enqueue((New-SmokeStep 'Click' 'BtnCmdToggle' 500 ('d' + [char]0x00FC + '' + [char]0x011F + 'me: komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' elle a' + [char]0x00E7 + ' (k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere)')))
            $q.Enqueue((New-SmokeStep 'Page' 'panel' 600 ('sayfa panel (elle a' + [char]0x00E7 + '' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' paneller)')))
            $q.Enqueue((New-SmokeStep 'Resp' 'log:on,cmd:on,panel' 500 ('duyarl' + [char]0x0131 + ': elle a' + [char]0x00E7 + '' + [char]0x0131 + 'lan paneller a' + [char]0x00E7 + '' + [char]0x0131 + 'k kald' + [char]0x0131 + ' m' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kucuk-panel-elle' 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere (paneller elle a' + [char]0x00E7 + '' + [char]0x0131 + 'k)')))
            $q.Enqueue((New-SmokeStep 'Size' '1380x840' 600 ('pencere varsay' + [char]0x0131 + 'lan boyut')))
            $q.Enqueue((New-SmokeStep 'Resp' 'log:on,cmd:on,title,panel' 400 ('duyarl' + [char]0x0131 + ': varsay' + [char]0x0131 + 'lan boyuta d' + [char]0x00F6 + 'n' + [char]0x00FC + 'nce')))
            $q.Enqueue((New-SmokeStep 'Rail' 'fit' 300 ('sol men' + [char]0x00FC + ' s' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'yor mu (varsay' + [char]0x0131 + 'lan)')))
          }
          if ($parts -contains 'tema') {
            # Ayarlar sayfasindaki tema listesinden gercek secim (kullanicinin coken yolu): baslangic temasina en son donulur
            $q.Enqueue((New-SmokeStep 'Page' 'settings' 800 ('sayfa settings (tema t' + [char]0x0131 + 'klamalar' + [char]0x0131 + ')')))
            $order = @()
            foreach ($x in $script:SmokeThemes) { if ($x -ne $Start) { $order += $x } }
            $order += $Start
            $q.Enqueue((New-SmokeStep 'Select' 'st_ThemeSel|Sistem' 700 ('se' + [char]0x00E7 + ' tema Sistem')))
            $q.Enqueue((New-SmokeStep 'SystemThemeCheck' 'Sistem' 200 ('tema do' + [char]0x011F + 'rula Sistem')))
            foreach ($x in $order) {
                $q.Enqueue((New-SmokeStep 'Select' ('st_ThemeSel|' + $x) 700 (('se' + [char]0x00E7 + ' tema ') + $x)))
                $q.Enqueue((New-SmokeStep 'ThemeCheck' $x 200 (('tema do' + [char]0x011F + 'rula ') + $x)))
                $q.Enqueue((New-SmokeStep 'Shot' ('tikla-' + $x) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' t' + [char]0x0131 + 'klama ') + $x)))
            }
          }
          if ($parts -contains 'yerlesim') {
            # yerlesimler: Ayarlar'daki listeden gercek secim; geometri dogrulanir, sayfalar goruntulenir
            foreach ($x in @('Kompakt', 'Sade', 'Hacker', 'Ayrintili')) {
                $q.Enqueue((New-SmokeStep 'Select' ('st_LayoutSel|' + $x) 800 (('se' + [char]0x00E7 + ' yerle' + [char]0x015F + 'im ') + $x)))
                $q.Enqueue((New-SmokeStep 'LayoutCheck' $x 300 (('yerle' + [char]0x015F + 'im do' + [char]0x011F + 'rula ') + $x)))
                $q.Enqueue((New-SmokeStep 'Resp' 'log:def,cmd:def,title,panel' 300 (('duyarl' + [char]0x0131 + ': yerle' + [char]0x015F + 'im ') + $x)))
                $q.Enqueue((New-SmokeStep 'Drain' '' 300 (('' + [char]0x00F6 + 'nce bo' + [char]0x015F + 'ta bekle (g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k denemesi, ') + $x + ')')))
                $q.Enqueue((New-SmokeStep 'BusyLog' '' 300 (('i' + [char]0x015F + 'lem ba' + [char]0x015F + 'lay' + [char]0x0131 + 'nca g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k (') + $x + ')')))
                $q.Enqueue((New-SmokeStep 'Rail' 'fit' 300 (('sol men' + [char]0x00FC + ' s' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'yor mu (') + $x + ')')))
                foreach ($pg in @('panel', 'optimize', 'network', 'settings')) {
