                    $q.Enqueue((New-SmokeStep 'Shot' ('yerlesim-' + $x + '-' + $pg) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' yerle' + [char]0x015F + 'im ') + $x + ' ' + $pg)))
                }
                $q.Enqueue((New-SmokeStep 'Page' 'settings' 600 'sayfa settings'))
            }
          }
          if ($parts -contains 'dokunma') {
            # dokunma hedefleri Buyuk: her sayfa ve alt sekme, sonra Kompakt yerlesim (32 px); olcum 'dokunma-' onekiyle ayri raporlanir
            $q.Enqueue((New-SmokeStep 'Touch' 'Large' 900 ('dokunma hedefleri: B' + [char]0x00FC + 'y' + [char]0x00FC + 'k')))
            foreach ($k in $Keys) {
                $q.Enqueue((New-SmokeStep 'Page' $k 900 ('sayfa ' + $k + ' / dokunma')))
                $q.Enqueue((New-SmokeStep 'Shot' ('dokunma-' + $k) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' dokunma ') + $k)))
                foreach ($tab in @(& $TabsOf $k)) {
                    $q.Enqueue((New-SmokeStep 'Tab' $tab 500 ('sekme ' + $tab + ' / dokunma')))
                    $q.Enqueue((New-SmokeStep 'Shot' ('dokunma-' + $k + '-' + $tab) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' dokunma ') + $tab)))
