                $q.Enqueue((New-SmokeStep 'Shot' ('dokunma-Kompakt-' + $pg) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' dokunma Kompakt ') + $pg)))
            }
