            $q.Enqueue((New-SmokeStep 'Touch' 'Normal' 600 'dokunma hedefleri: Normal'))
          }
          if ($parts -contains 'hazir') {
            # hazir gorunumler (tema + yerlesim birlikte)
            foreach ($pr in @(@('Varsayilan', 'Sade', 'Acik'), @('KoyuNeon', 'Ayrintili', 'Neon'), @('KompaktKoyu', 'Kompakt', 'Koyu'), @('Hacker', 'Hacker', 'Hacker'))) {
                $q.Enqueue((New-SmokeStep 'Select' ('st_LookSel|' + $pr[0]) 1000 (('se' + [char]0x00E7 + ' haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm ') + $pr[0])))
                $q.Enqueue((New-SmokeStep 'LayoutCheck' $pr[1] 300 (('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm yerle' + [char]0x015F + 'imi ') + $pr[1])))
                $q.Enqueue((New-SmokeStep 'ThemeCheck' $pr[2] 200 (('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm temas' + [char]0x0131 + ' ') + $pr[2])))
                $q.Enqueue((New-SmokeStep 'Page' 'panel' 800 (('sayfa panel / haz' + [char]0x0131 + 'r ') + $pr[0])))
                $q.Enqueue((New-SmokeStep 'Shot' ('hazir-' + $pr[0] + '-panel') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' haz' + [char]0x0131 + 'r ') + $pr[0])))
