                $q.Enqueue((New-SmokeStep 'Theme' $cb[0] 250 (('e' + [char]0x015F + 'le' + [char]0x015F + 'me tema ') + $cb[0])))
                $q.Enqueue((New-SmokeStep 'Layout' $cb[1] 600 (('e' + [char]0x015F + 'le' + [char]0x015F + 'me yerle' + [char]0x015F + 'im ') + $cb[1])))
                $q.Enqueue((New-SmokeStep 'LayoutGeo' $cb[1] 100 (('e' + [char]0x015F + 'le' + [char]0x015F + 'me do' + [char]0x011F + 'rula ') + $cb[1])))
