                    $q.Enqueue((New-SmokeStep 'Shot' ('esle-' + $cb[0] + '-' + $cb[1] + '-' + $pg) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' e' + [char]0x015F + 'le' + [char]0x015F + 'me ') + $cb[0] + ' ' + $cb[1] + ' ' + $pg)))
                }
            }
          }
            $q.Enqueue((New-SmokeStep 'Theme' $Start 250 ('tema geri: ' + $Start)))
            $q.Enqueue((New-SmokeStep 'Layout' 'Ayrintili' 600 ('yerle' + [char]0x015F + 'im: ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + '')))
          if (($parts -contains 'tasarim') -or ($parts -contains 'saydam')) { Add-SmokeLookParts $q $parts $Start }
          if ($parts -contains 'zoom') {
            # yakinlastirma: Ayarlar'daki liste; govde olcegi ve ayar dogrulanir
            $q.Enqueue((New-SmokeStep 'Page' 'settings' 800 ('sayfa settings (yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma)')))
            foreach ($z in @(130, 80)) {
                $q.Enqueue((New-SmokeStep 'Select' ('st_ZoomSel|' + [string]$z) 800 (('se' + [char]0x00E7 + ' yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$z)))
                $q.Enqueue((New-SmokeStep 'ZoomCheck' ([string]$z) 300 (('yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma do' + [char]0x011F + 'rula %') + [string]$z)))
                # yakinlastirma menu alaninin yuksekligini degistirir: dugme yukseklikleri buna gore yeniden hesaplanmis olmali (%130'da yer yetmeyebilir: uyari)
