                $q.Enqueue((New-SmokeStep 'Rail' $rr 300 (('sol men' + [char]0x00FC + ' (yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$z + ')')))
                if ($z -ge 120) { $rs = 'log:off,cmd:off,title,panel,panelfit' } else { $rs = 'log:def,cmd:def,title,panel' }
                $q.Enqueue((New-SmokeStep 'Page' 'panel' 800 (('sayfa panel / yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$z)))
                $q.Enqueue((New-SmokeStep 'Resp' $rs 300 (('duyarl' + [char]0x0131 + ': yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$z)))
                $q.Enqueue((New-SmokeStep 'Shot' ('zoom-' + [string]$z + '-panel') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$z + ' panel')))
                $q.Enqueue((New-SmokeStep 'Page' 'optimize' 800 (('sayfa optimize / yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$z)))
                $q.Enqueue((New-SmokeStep 'Shot' ('zoom-' + [string]$z + '-optimize') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$z + ' optimize')))
                $q.Enqueue((New-SmokeStep 'Page' 'settings' 700 'sayfa settings'))
            }
            $q.Enqueue((New-SmokeStep 'Select' 'st_ZoomSel|100' 800 ('se' + [char]0x00E7 + ' yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %100')))
            $q.Enqueue((New-SmokeStep 'ZoomCheck' '100' 300 ('yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma do' + [char]0x011F + 'rula %100')))
            $q.Enqueue((New-SmokeStep 'Rail' 'fit' 300 ('sol men' + [char]0x00FC + ' s' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'yor mu (yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %100 geri)')))
            $q.Enqueue((New-SmokeStep 'Resp' 'log:def,cmd:def,title,panel' 300 ('duyarl' + [char]0x0131 + ': yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %100 (kendili' + [char]0x011F + 'inden kapanan paneller geri a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ' m' + [char]0x0131 + ')')))
          }
          if ($parts -contains 'kaydirma') {
            # kaydirma: sagdaki cubuk kullanilmadan (tekerlek olayi, klavye eylemleri, basa don dugmesi)
