            $q.Enqueue((New-SmokeStep 'Keys' 'Top' 700 ('kayd' + [char]0x0131 + 'rma: en ba' + [char]0x015F + 'a')))
            $q.Enqueue((New-SmokeStep 'ScrollMark' '' 100 ('kayd' + [char]0x0131 + 'rma: konum i' + [char]0x015F + 'aretle')))
            $q.Enqueue((New-SmokeStep 'Wheel' 'down' 1100 ('kayd' + [char]0x0131 + 'rma: tekerlek a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + ' (yumu' + [char]0x015F + 'ak)')))
            $q.Enqueue((New-SmokeStep 'ScrollCheck' 'moved' 100 ('kayd' + [char]0x0131 + 'rma: tekerlek sayfay' + [char]0x0131 + ' kayd' + [char]0x0131 + 'rd' + [char]0x0131 + ' m' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'Wheel' 'down' 1100 ('kayd' + [char]0x0131 + 'rma: tekerlek daha a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'ScrollCheck' 'moved' 100 ('kayd' + [char]0x0131 + 'rma: ikinci tekerlek ' + [char]0x00E7 + 'enti' + [char]0x011F + 'i')))
            $q.Enqueue((New-SmokeStep 'ToTop' 'visible' 400 ('ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n d' + [char]0x00FC + '' + [char]0x011F + 'mesi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nd' + [char]0x00FC + ' m' + [char]0x00FC + '')))
            $q.Enqueue((New-SmokeStep 'Shot' 'kaydirma-asagi' 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' kayd' + [char]0x0131 + 'rma (a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'da)')))
            $q.Enqueue((New-SmokeStep 'Wheel' 'up' 1100 ('kayd' + [char]0x0131 + 'rma: tekerlek yukar' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'ScrollCheck' 'moved' 100 ('kayd' + [char]0x0131 + 'rma: yukar' + [char]0x0131 + ' tekerlek')))
            $q.Enqueue((New-SmokeStep 'Keys' 'PageDown' 1100 ('kayd' + [char]0x0131 + 'rma: PageDown')))
            $q.Enqueue((New-SmokeStep 'ScrollCheck' 'moved' 100 ('kayd' + [char]0x0131 + 'rma: PageDown kayd' + [char]0x0131 + 'rd' + [char]0x0131 + ' m' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'Keys' 'PageUp' 1100 ('kayd' + [char]0x0131 + 'rma: PageUp')))
            $q.Enqueue((New-SmokeStep 'ScrollCheck' 'moved' 100 ('kayd' + [char]0x0131 + 'rma: PageUp kayd' + [char]0x0131 + 'rd' + [char]0x0131 + ' m' + [char]0x0131 + '')))
