            $q.Enqueue((New-SmokeStep 'Shot' 'kaydirma-sonda' 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' kayd' + [char]0x0131 + 'rma (en sonda)')))
            $q.Enqueue((New-SmokeStep 'Keys' 'Top' 1200 ('kayd' + [char]0x0131 + 'rma: Home / ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n')))
            $q.Enqueue((New-SmokeStep 'ScrollCheck' 'top' 100 ('kayd' + [char]0x0131 + 'rma: en ba' + [char]0x015F + 'ta m' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'ToTop' 'hidden' 400 ('ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n d' + [char]0x00FC + '' + [char]0x011F + 'mesi gizlendi mi')))
