            $q.Enqueue((New-SmokeStep 'Wheel' 'down' 400 ('kayd' + [char]0x0131 + 'rma: tekerlek a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + ' (an' + [char]0x0131 + 'nda)')))
            $q.Enqueue((New-SmokeStep 'ScrollCheck' 'moved' 100 ('kayd' + [char]0x0131 + 'rma: an' + [char]0x0131 + 'nda kayd' + [char]0x0131 + 'rd' + [char]0x0131 + ' m' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'SmoothOn' '' 100 ('kayd' + [char]0x0131 + 'rma: yumu' + [char]0x015F + 'ak kayd' + [char]0x0131 + 'rma geri a' + [char]0x00E7 + '' + [char]0x0131 + 'k')))
            $q.Enqueue((New-SmokeStep 'Keys' 'Top' 900 ('kayd' + [char]0x0131 + 'rma: ba' + [char]0x015F + 'a')))
          }
          if ($parts -contains 'kisayol') {
            # kisayollar: Ctrl+Tab sayfa degistirir, Ctrl+, Ayarlar'i acar
            $q.Enqueue((New-SmokeStep 'HotKey' 'NextPage' 700 ('k' + [char]0x0131 + 'sayol: sonraki sayfa')))
            $q.Enqueue((New-SmokeStep 'HotKey' 'PrevPage' 700 ('k' + [char]0x0131 + 'sayol: ' + [char]0x00F6 + 'nceki sayfa')))
            $q.Enqueue((New-SmokeStep 'HotKey' 'Settings' 700 ('k' + [char]0x0131 + 'sayol: Ayarlar')))
          }
          if ($parts -contains 'saglik') {
            # saglik taramasi (yalnizca okur)
            $q.Enqueue((New-SmokeStep 'Page' 'panel' 600 'sayfa panel (tarama)'))
            $q.Enqueue((New-SmokeStep 'Health' '' 1500 ('sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ' (yaln' + [char]0x0131 + 'zca okur)')))
            # islem surerken X: pencere tepsiye iner, onay kutusu cikmaz, is arka planda surer
            $q.Enqueue((New-SmokeStep 'TrayCloseBusy' '' 900 ('tepsiye indir (X, i' + [char]0x015F + 'lem s' + [char]0x00FC + 'rerken)')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'hidden' 100 ('tepsi: i' + [char]0x015F + 'lem s' + [char]0x00FC + 'rerken X pencereyi gizledi mi')))
            $q.Enqueue((New-SmokeStep 'TrayShow' '' 900 ('tepsi: simgeyle geri getir (i' + [char]0x015F + 'lem s' + [char]0x00FC + 'rerken)')))
            $q.Enqueue((New-SmokeStep 'TrayCheck' 'shown' 100 ('tepsi: i' + [char]0x015F + 'lem s' + [char]0x00FC + 'rerken geri geldi mi')))
            $q.Enqueue((New-SmokeStep 'TrayDone' '' 100 ('tepsi denemesi bitti (i' + [char]0x015F + 'lem)')))
            $q.Enqueue((New-SmokeStep 'Drain' '' 1500 ('i' + [char]0x015F + ' bitsin: sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + '')))
            $q.Enqueue((New-SmokeStep 'Shot' ($t + '-panel-tarama') 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' panel (tarama sonras' + [char]0x0131 + ')')))
          }
          if ($parts -contains 'eylem') {
            # salt okunur tarama / onizleme dugmeleri
            foreach ($a in @(Get-SmokeActions)) {
                $q.Enqueue((New-SmokeStep 'Page' $a[0] 700 ('sayfa ' + $a[0] + ' (eylem)')))
                if ($a[1] -ne '') { $q.Enqueue((New-SmokeStep 'Tab' $a[1] 400 ('sekme ' + $a[1]))) }
                # sayfanin kendi acilis isi bitmeden basilirsa uygulama "baska bir islem suruyor" der; once bosta beklenir
                $q.Enqueue((New-SmokeStep 'Drain' '' 300 (('' + [char]0x00F6 + 'nce bo' + [char]0x015F + 'ta bekle: ') + $a[2])))
                $q.Enqueue((New-SmokeStep 'Click' $a[2] 800 (('d' + [char]0x00FC + '' + [char]0x011F + 'me ') + $a[2])))
                $q.Enqueue((New-SmokeStep 'Drain' '' 800 (('i' + [char]0x015F + ' bitsin: ') + $a[2])))
                $q.Enqueue((New-SmokeStep 'Shot' ('eylem-' + $(if ($a[1] -ne '') { [string]$a[1] + '-' } else { '' }) + $a[2]) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' eylem ') + $a[2])))
            }
          }
        }
        $first = $false
    }
    if ($StartDesign -ne 'Klasik') { $q.Enqueue((New-SmokeStep 'Design' $StartDesign 900 (('tasar' + [char]0x0131 + 'm geri: ') + $StartDesign))) }
    if ($StartGlass -ne 'Yok|100') { $q.Enqueue((New-SmokeStep 'Glass' $StartGlass 900 (('saydaml' + [char]0x0131 + 'k geri: ') + $StartGlass))) }
    if ($StartHome -ne 'Pano|Auto|Auto|Auto|Auto|Auto') { $q.Enqueue((New-SmokeStep 'HomeSet' $StartHome 900 (('ana ekran ve ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar geri: ') + $StartHome))) }
    $q.Enqueue((New-SmokeStep 'Theme' $Start 250 ('tema geri: ' + $Start)))
    if ($StartTouch -ne 'Normal') { $q.Enqueue((New-SmokeStep 'Touch' $StartTouch 600 ('dokunma hedefleri geri: ' + $StartTouch))) }
    $q.Enqueue((New-SmokeStep 'Layout' $StartLayout 600 (('yerle' + [char]0x015F + 'im geri: ') + $StartLayout)))
    $q.Enqueue((New-SmokeStep 'Page' 'panel' 600 'sayfa panel (son)'))
    $q.Enqueue((New-SmokeStep 'Drain' '' 1500 ('i' + [char]0x015F + ' bitsin (son)')))
    $q.Enqueue((New-SmokeStep 'Finish' '' 0 'bitir'))
    return , $q
}

function Start-SmokeRun {
    $script:SmokeStart = Get-Date
    $script:SmokeTheme = [string]$script:ThemeName
    $script:SmokeLayout = [string]$script:LayoutName
    $script:SmokeMode0 = [string]$script:UiState.Mode
    $scope = Get-SmokeScope
    Add-SmokeLine ('=== DUMAN TESTI basladi   surum ' + [string]$script:AppVersion + '   PowerShell ' + $PSVersionTable.PSVersion.ToString() + '   yonetici=' + [string]$script:IsAdmin + '   kapsam=' + $scope + '   baslangic temasi=' + $script:SmokeTheme + '   yerlesim=' + $script:SmokeLayout + '   yakinlastirma=' + [string]$script:Settings.Zoom + '   guvenli=' + [string]$script:SafeBoot)
    $keys = @($script:PageTitles.Keys)
    $d0 = ConvertTo-DesignKey ([string]$script:DesignKey)
    $gk0 = ConvertTo-GlassKey ([string]$script:Settings.Backdrop)
    $g0 = 'Yok|100'
    if ($gk0 -ne 'Yok') { $g0 = $gk0 + '|' + [string](ConvertTo-GlassOpacity $script:Settings.WinOpacity) }
    $h0 = ConvertTo-HomeKey (Get-BoardField $script:Settings 'HomeMode')
    foreach ($dp in @($script:DsOptions.Keys)) { $h0 = $h0 + '|' + (ConvertTo-DsValue ([string]$dp) (Get-BoardField $script:Settings ('Ds' + [string]$dp))) }
    Add-SmokeLine ('baslangic tasarimi=' + $d0 + '   saydamlik=' + $g0 + '   ana ekran/ayrintilar=' + $h0)
    $t0 = ConvertTo-TouchKey ([string]$script:Settings.TouchTargets)
    Add-SmokeLine ('baslangic dokunma hedefleri=' + $t0 + '   dokunmatik ekran=' + [string](Test-TouchScreen))
    $script:SmokeSteps = New-SmokeQueue $script:SmokeTheme $keys { param($k) Get-SmokeTabs $k } $script:SmokeLayout $scope $d0 $g0 $h0 $t0
    Add-SmokeLine ('adim sayisi: ' + [string]$script:SmokeSteps.Count)
    try { Add-SmokeLine (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' ekran' + [char]0x0131 + ': kip=') + [string]$script:SplashMode + ('   a' + [char]0x015F + 'ama ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + 'lar' + [char]0x0131 + ' (ms): ') + (Get-SplashSummary)) } catch { }
    $script:SmokeTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:SmokeTimer.Interval = [TimeSpan]::FromMilliseconds(200)
    $script:SmokeTimer.Add_Tick({ try { Invoke-SmokeTick } catch { Add-SmokeError 'duman zamanlayicisi' $_.Exception.Message } })
    $script:SmokeTimer.Start()
}

function Invoke-SmokeTick {
    if ($script:SmokeDone) { return }
    if ((Get-Date) -lt $script:SmokeWaitUntil) { return }
    $st = $script:SmokeCurStep
    if ($null -eq $st) {
        if ($script:SmokeSteps.Count -eq 0) { Complete-SmokeRun; return }
        $st = $script:SmokeSteps.Dequeue()
    }
    $script:SmokeCurStep = $null
    $script:SmokeCur = [string]$st.Label
    $before = $script:SmokeErrs.Count
    $t0 = Get-Date
    $again = $false
    try {
        $res = @(Invoke-SmokeStep $st)
        if ($res.Count -gt 0 -and $res[$res.Count - 1] -eq $true) { $again = $true }
    } catch { Add-SmokeError ('ad' + [char]0x0131 + 'm') $_.Exception.Message }
    try { $script:Win.UpdateLayout() } catch { Add-SmokeError ('yerle' + [char]0x015F + 'im') $_.Exception.Message }
    $ms = [int]((Get-Date) - $t0).TotalMilliseconds
    if ($again) { $script:SmokeCurStep = $st }
    elseif ($script:SmokeErrs.Count -eq $before -and [string]$st.Kind -ne 'Shot') { Add-SmokeLine ('ok    ' + [string]$st.Label + '   ' + [string]$ms + ' ms') }
    $script:SmokeWaitUntil = (Get-Date).AddMilliseconds([int]$st.Wait)
}

# Tepsi sinyali denemesinde hata ayiklama bilgisi: zamanlayici calisti mi, olay tuketildi mi, pencere hangi durumda
function Get-SmokeSignalInfo {
    try {
        $t0 = 0
        $f0 = 0
        if ($null -ne $script:SmokeSig0) { $t0 = [int]$script:SmokeSig0[0]; $f0 = [int]$script:SmokeSig0[1] }
        $en = 'yok'
        if ($null -ne $script:SigTimer) { $en = [string]$script:SigTimer.IsEnabled }
        $ev = 'yok'
        if ($null -ne $script:ShowEvent) {
            # otomatik sifirlanan olay okununca tuketilir; bilgi icin okunduysa geri konur
            $on = [bool]$script:ShowEvent.WaitOne(0)
            if ($on) { [void]$script:ShowEvent.Set() }
            $ev = [string]$on
        }
        return ((' [sinyal zamanlay' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131 + ': ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor=') + $en + ', tik=' + [string]([int]$script:SigTicks - $t0) + ', tetiklenme=' + [string]([int]$script:SigFired - $f0) + (', olay h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' sinyalde=') + $ev + ', pencere=' + [string]$script:Win.WindowState + (', g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r=') + [string]$script:Win.IsVisible + ']')
    } catch { return '' }
}

# Tepsi denemesi icin ayarlari bir kez saklar ve X / simge durumu davranisini acar
function Save-SmokeTray {
    if (-not $script:SmokeTraySaved) {
        $script:SmokeTraySaved = $true
        $script:SmokeTrayMin0 = ($script:Settings.TrayMinimize -eq $true)
        $script:SmokeTrayOn0 = $script:Settings.TrayOnMinimize
    }
    $script:TrayHintShown = $true
}

# Yerlesimin gercekten oturdugunu olcer: ayar, geometri, paneller, yazi tipi, gruplar ve kartlar. WithDisk: dosyadaki ayar da denetlenir.
function Test-SmokeLayout([string]$Name, [bool]$WithDisk) {
    $d = Get-LayoutDefaults $Name
    $script:Win.UpdateLayout()
    if ([string]$script:LayoutName -ne $Name) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('etkin yerle' + [char]0x015F + 'im ') + [string]$script:LayoutName + ', beklenen ' + $Name) }
    if ([int]$script:LayoutFail -gt 0) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('uygulanamayan ad' + [char]0x0131 + 'm say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + [string]$script:LayoutFail) }
    if ([string]$script:Settings.Layout -ne $Name) { Add-SmokeError ('yerle' + [char]0x015F + 'im') ('bellekteki ayar ' + [string]$script:Settings.Layout + ', beklenen ' + $Name) }
    if ($WithDisk) {
        $cfg = ''
        try { $cfg = [string](Get-Settings).Layout } catch { }
        if ($cfg -ne $Name) { Add-SmokeError ('yerle' + [char]0x015F + 'im') ('dosyadaki ayar ' + $cfg + ', beklenen ' + $Name) }
    }
    $rw = [double]$ui.RailHost.ActualWidth
    $want = [double](Get-RailWidth ([string]$d.Rail))
    if ([math]::Abs($rw - $want) -gt 2) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('sol men' + [char]0x00FC + ' geni' + [char]0x015F + 'li' + [char]0x011F + 'i ') + [string]$rw + ', beklenen ' + [string]$want) }
    $lw = [double]$ui.ColLog.ActualWidth
    if ([math]::Abs($lw - [double]$d.Log) -gt 2) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k paneli geni' + [char]0x015F + 'li' + [char]0x011F + 'i ') + [string]$lw + ', beklenen ' + [string]$d.Log) }
    $cmd = ($ui.CmdPanel.Visibility -eq $script:VisOn)
    if ($cmd -ne [bool]$d.Cmd) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' ') + [string]$cmd + ', beklenen ' + [string]$d.Cmd) }
    $mono = ([string]$script:Win.FontFamily.Source -like 'Cascadia*')
    if ($mono -ne [bool]$d.Mono) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('tek aral' + [char]0x0131 + 'kl' + [char]0x0131 + ' yaz' + [char]0x0131 + ' tipi ') + [string]$mono + ', beklenen ' + [string]$d.Mono) }
    $tag = [string]$ui.TxtTagline.Text
    if ($Name -eq 'Hacker' -and $tag -notlike 'multimizer@*') { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('Terminal ba' + [char]0x015F + 'l' + [char]0x0131 + 'k yaz' + [char]0x0131 + 's' + [char]0x0131 + ' uygulanmad' + [char]0x0131 + ': ') + $tag) }
    if ($Name -ne 'Hacker' -and $tag -like 'multimizer@*') { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('Terminal ba' + [char]0x015F + 'l' + [char]0x0131 + 'k yaz' + [char]0x0131 + 's' + [char]0x0131 + ' geri al' + [char]0x0131 + 'nmad' + [char]0x0131 + ': ') + $tag) }
    $hv = 0
    foreach ($g in @($script:RailGroups)) { if ($g.Header.Visibility -eq $script:VisOn) { $hv++ } }
    if ([bool]$d.Groups) { if ($hv -lt 2) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r men' + [char]0x00FC + ' grup ba' + [char]0x015F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' say' + [char]0x0131 + 's' + [char]0x0131 + ' ') + [string]$hv + ', beklenen en az 2') } }
    elseif ($hv -gt 0) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r men' + [char]0x00FC + ' ba' + [char]0x015F + 'l' + [char]0x0131 + 'klar' + [char]0x0131 + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' / kompakt yerle' + [char]0x015F + 'imde g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor (') + [string]$hv + ')') }
    $conv = 0
    $closed = 0
    $root = $script:Pages['settings']
    if ($null -ne $root) {
        $cards = New-Object System.Collections.ArrayList
        Find-CardBorders $root $cards 0
        foreach ($c in $cards) {
            $sp = $c.Child
            $h = $sp.Children[0]
            if (($h -is [System.Windows.Controls.Grid]) -and ([string]$h.Tag -eq 'cardhdr')) {
                $conv++
                if ($sp.Children[1].Visibility -ne $script:VisOn) { $closed++ }
            }
        }
        if ([bool]$d.Cards) {
            if ($conv -lt 3) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r kart say' + [char]0x0131 + 's' + [char]0x0131 + ' ') + [string]$conv + ', beklenen en az 3') }
            if ($closed -lt 1) { Add-SmokeError ('yerle' + [char]0x015F + 'im') ('Sade yerle' + [char]0x015F + 'imde kapal' + [char]0x0131 + ' kart yok') }
        } elseif ($closed -gt 0) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('d' + [char]0x00FC + 'z yerle' + [char]0x015F + 'imde kapal' + [char]0x0131 + ' kart kald' + [char]0x0131 + ': ') + [string]$closed) }
    }
    Add-SmokeLine (('      yerle' + [char]0x015F + 'im ') + $Name + (': men' + [char]0x00FC + ' ') + [string][int]$rw + (' px, g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k ') + [string][int]$lw + (' px, komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ') + [string]$cmd + (', grup ba' + [char]0x015F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ') + [string]$hv + (', a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r kart ') + [string]$conv + (' (kapal' + [char]0x0131 + ' ') + [string]$closed + ')')
}

# Duyarli yerlesim denetimi (Duyarli yerlesim bolumu). Spec: virgulle ayrilmis kosullar:
#   log:off | log:on | log:def   islem gunlugu kapali / acik / yerlesimin varsayilani (pencere yeterince genisse)
#   cmd:off | cmd:on | cmd:def   komut satiri kapali / acik / yerlesimin varsayilani
#   title                        baslik cubugunda orta blok sol ve sag blokla cakismiyor
#   panel                        durum panosunun sutun sayisi pencere olcusuyle uyumlu (dar sayfada tek sutun)
#   panelfit                     durum panosunun sol sutunu gosterge cemberleri icin yeterince genis
function Test-SmokeResp([string]$Spec) {
    $script:Win.UpdateLayout()
    Update-Responsive
    $script:Win.UpdateLayout()
    $d = Get-LayoutDefaults ([string]$script:LayoutName)
    $lw = [double]$ui.ColLog.ActualWidth
    $cmdOn = ($ui.CmdPanel.Visibility -eq $script:VisOn)
    $pw = [double](Get-CurrentPageWidth)
    $sz = Get-WinSize
    $ph = [double](Get-PageHeight ([double]$sz[1]) ([double]$script:UiZoom) $(if ($cmdOn) { [double]$ui.CmdPanel.ActualHeight + 16 } else { 0.0 }))
    Add-SmokeLine (('      duyarl' + [char]0x0131 + ': pencere ') + [string][int]$sz[0] + 'x' + [string][int]$sz[1] + (', yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string][int]([double]$script:UiZoom * 100) + (', sayfa alan' + [char]0x0131 + ' ') + [string][int]$pw + 'x' + [string][int]$ph + (' px, g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k ') + [string][int]$lw + (' px (kendili' + [char]0x011F + 'inden kapal' + [char]0x0131 + ' ') + [string]$script:LogAutoOff + ('), komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ') + [string]$cmdOn + (' (kendili' + [char]0x011F + 'inden kapal' + [char]0x0131 + ' ') + [string]$script:CmdAutoOff + ('), ba' + [char]0x015F + 'l' + [char]0x0131 + 'k seviyesi ') + [string]$script:TitleLevel)
    foreach ($tok in @($Spec -split ',')) {
        $t = $tok.Trim()
        if ($t -eq '') { continue }
        if ($t -like 'log:*') {
            $want = $t.Substring(4)
            if ($want -eq 'def') { if (([double]$d.Log -gt 0) -and ($script:RespLogFits -eq $true)) { $want = 'on' } else { $want = 'off' } }
            if ($want -eq 'off' -and $lw -gt 2) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') (('g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k kapal' + [char]0x0131 + ' olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ', geni' + [char]0x015F + 'lik ') + [string][int]$lw + ' px (sayfa ' + [string][int]$pw + ' px)') }
            if ($want -eq 'on' -and $lw -lt 100) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') (('g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k a' + [char]0x00E7 + '' + [char]0x0131 + 'k olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ', geni' + [char]0x015F + 'lik ') + [string][int]$lw + ' px (sayfa ' + [string][int]$pw + ' px)') }
        } elseif ($t -like 'cmd:*') {
            $want = $t.Substring(4)
            if ($want -eq 'def') { if (([bool]$d.Cmd) -and ($script:RespCmdFits -eq $true)) { $want = 'on' } else { $want = 'off' } }
            if ($want -eq 'off' -and $cmdOn) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') (('komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' kapal' + [char]0x0131 + ' olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ' (sayfa y' + [char]0x00FC + 'ksekli' + [char]0x011F + 'i ') + [string][int]$ph + ' px)') }
            if ($want -eq 'on' -and -not $cmdOn) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') (('komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'k olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ' (sayfa y' + [char]0x00FC + 'ksekli' + [char]0x011F + 'i ') + [string][int]$ph + ' px)') }
        } elseif ($t -eq 'title') {
            $par = $ui.TitleCenter.Parent
            $col1 = [double]$par.ColumnDefinitions[1].ActualWidth
            $need = [double]$ui.TitleCenter.DesiredSize.Width
            if ($need -gt $col1 + 1) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') (('ba' + [char]0x015F + 'l' + [char]0x0131 + 'k ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'unda orta blok s' + [char]0x0131 + '' + [char]0x011F + 'm' + [char]0x0131 + 'yor: ') + [string][int]$need + ' px > ' + [string][int]$col1 + ' px (seviye ' + [string]$script:TitleLevel + ')') }
            else { Add-SmokeLine (('      ba' + [char]0x015F + 'l' + [char]0x0131 + 'k ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'u: orta blok ') + [string][int]$need + (' px, bo' + [char]0x015F + ' s' + [char]0x00FC + 'tun ') + [string][int]$col1 + ' px, seviye ' + [string]$script:TitleLevel) }
        } elseif ($t -eq 'panel' -or $t -eq 'panelfit') {
            $root = $null
            if ($script:Pages.ContainsKey('panel')) { $root = $script:Pages['panel'] }
            if ($null -eq $root) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') ('durum panosu sayfas' + [char]0x0131 + ' yok'); continue }
            $g = $root.Content
            $right = $g.Children[1]
            $isNarrow = ([System.Windows.Controls.Grid]::GetRow($right) -eq 1)
            $wantNarrow = [bool](Test-PanelNarrow $pw)
            if ($t -eq 'panel') {
                if ($isNarrow -ne $wantNarrow) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') ('durum panosu ' + $(if ($isNarrow) { 'tek' } else { 'iki' }) + (' s' + [char]0x00FC + 'tunlu, sayfa ') + [string][int]$pw + (' px i' + [char]0x00E7 + 'in beklenen ') + $(if ($wantNarrow) { 'tek' } else { 'iki' }) + (' s' + [char]0x00FC + 'tun')) }
                else { Add-SmokeLine ('      durum panosu: ' + $(if ($isNarrow) { 'tek' } else { 'iki' }) + (' s' + [char]0x00FC + 'tun (sayfa ') + [string][int]$pw + ' px)') }
            } else {
                $leftW = [double]$g.Children[0].ActualWidth
                if ($leftW -gt 0 -and $leftW -lt 600) { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') (('durum panosunun sol s' + [char]0x00FC + 'tunu ' + [char]0x00E7 + 'ok dar: ') + [string][int]$leftW + ' px (sayfa ' + [string][int]$pw + ' px)') }
                elseif ($leftW -gt 0) { Add-SmokeLine (('      durum panosu sol s' + [char]0x00FC + 'tun: ') + [string][int]$leftW + ' px') }
            }
        } else { Add-SmokeError ('duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im') (('bilinmeyen ko' + [char]0x015F + 'ul: ') + $t) }
    }
}

# Donus: $true = bu adim yeniden denensin (bekleme adimlari); aksi halde $false
function Invoke-SmokeStep($St) {
    $arg = [string]$St.Arg
    switch ([string]$St.Kind) {
        'Theme' {
            Set-AppTheme $arg
            if ([int]$script:ThemeFail -gt 0) { Add-SmokeError 'tema' (('uygulanamayan renk say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + [string]$script:ThemeFail) }
            $bad = @(Get-ThemeProblems $arg)
            if ($bad.Count -gt 0) { Add-SmokeError 'tema' (('uyu' + [char]0x015F + 'mayan renk: ') + ($bad -join ', ')) }
            $bad2 = @(Get-CodeBrushProblems)
            if ($bad2.Count -gt 0) { Add-SmokeError 'tema' (('koddan ' + [char]0x00FC + 'retilen ' + [char]0x00F6 + '' + [char]0x011F + 'elerin rengi temaya uymuyor: ') + ($bad2 -join ', ')) }
        }
        'Page' {
            Show-Page $arg
            $want = $arg
            if ($arg -eq 'panel' -and (Test-BoardHome)) { $want = 'board' }
            if (-not $script:Pages.ContainsKey($want)) { Add-SmokeError 'sayfa' (('sayfa olu' + [char]0x015F + 'turulamad' + [char]0x0131 + ': ') + $arg) }
            elseif ([string]$script:UiState.Page -ne $want) { Add-SmokeError 'sayfa' (('sayfa a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + ': ') + $arg) }
        }
        'Shot' { Save-SmokeShot $arg }
        'LangScan' { Invoke-SmokeLangScan $arg }
        'Tab' {
            $c = $ui[$arg]
            if ($null -eq $c) { Add-SmokeError 'sekme' (('sekme d' + [char]0x00FC + '' + [char]0x011F + 'mesi yok: ') + $arg) }
            elseif ($c.IsChecked -ne $true) { $c.IsChecked = $true }
        }
        'Click' {
            $c = $ui[$arg]
            if ($script:SmokeSafe -notcontains $arg) { Add-SmokeError ('d' + [char]0x00FC + '' + [char]0x011F + 'me') (('g' + [char]0x00FC + 'venli d' + [char]0x00FC + '' + [char]0x011F + 'me listesinde de' + [char]0x011F + 'il, bas' + [char]0x0131 + 'lmad' + [char]0x0131 + ': ') + $arg) }
            elseif ($null -eq $c) { Add-SmokeError ('d' + [char]0x00FC + '' + [char]0x011F + 'me') (('d' + [char]0x00FC + '' + [char]0x011F + 'me yok: ') + $arg) }
            elseif ($c.IsEnabled -ne $true) { Add-SmokeWarn (('d' + [char]0x00FC + '' + [char]0x011F + 'me kapal' + [char]0x0131 + ', atland' + [char]0x0131 + ': ') + $arg) }
            else {
                $script:SmokeClickAt = Get-Date
                $script:SmokeClicks = [int]$script:SmokeClicks + 1
                if ($c -is [System.Windows.Controls.RadioButton]) { $c.IsChecked = $true }
                $ev = New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, $c)
                $c.RaiseEvent($ev)
            }
        }
        'Select' {
            $p = $arg.Split('|')
            $cn = [string]$p[0]
            $c = $ui[$cn]
            if ($script:SmokeSafeSelect -notcontains $cn) { Add-SmokeError 'liste' (('g' + [char]0x00FC + 'venli liste k' + [char]0x00FC + 'mesinde de' + [char]0x011F + 'il, se' + [char]0x00E7 + 'ilmedi: ') + $cn) }
            elseif ($null -eq $c) { Add-SmokeError 'liste' (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r liste yok: ') + $cn) }
            elseif ($c.IsEnabled -ne $true) { Add-SmokeWarn (('liste kapal' + [char]0x0131 + ', atland' + [char]0x0131 + ': ') + $cn) }
            else {
                $hit = $null
                foreach ($it in $c.Items) { if ([string]$it['Key'] -eq [string]$p[1]) { $hit = $it; break } }
                if ($null -eq $hit) { Add-SmokeError 'liste' (('se' + [char]0x00E7 + 'enek yok: ') + $cn + ' / ' + [string]$p[1]) }
                else {
                    $script:SmokeClickAt = Get-Date
                    $script:SmokeClicks = [int]$script:SmokeClicks + 1
                    $c.SelectedItem = $hit
                    if ((Get-ComboKey $c) -ne [string]$p[1]) { Add-SmokeError 'liste' (('se' + [char]0x00E7 + 'im oturmad' + [char]0x0131 + ': ') + $cn + ' / ' + [string]$p[1]) }
                }
            }
        }
        'DropDown' {
            # acilir listeyi ac ya da kapat (gercek ekran goruntusunde acilan pencerenin gorunmesi icin)
            $p = $arg.Split('|')
            $c = $ui[[string]$p[0]]
            if ($null -eq $c) { Add-SmokeError 'liste' (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r liste yok: ') + [string]$p[0]) }
            else { $c.IsDropDownOpen = ([string]$p[1] -ne 'close') }
        }
        'SystemThemeCheck' {
            $cfg = ''
            try { $cfg = [string](Get-Settings).Theme } catch { }
            $want = Get-SystemThemeKey
            if ([string]$script:Settings.Theme -ne 'Sistem') { Add-SmokeError 'tema' ('bellekteki ayar ' + [string]$script:Settings.Theme + ', beklenen Sistem') }
            if ($cfg -ne 'Sistem') { Add-SmokeError 'tema' ('dosyadaki ayar ' + $cfg + ', beklenen Sistem') }
            if ([string]$script:ThemeName -ne $want) { Add-SmokeError 'tema' (('Sistem se' + [char]0x00E7 + 'iliyken etkin tema ') + [string]$script:ThemeName + (', Windows kipine g' + [char]0x00F6 + 're beklenen ') + $want) }
            elseif ([bool](Update-SystemTheme)) { Add-SmokeError 'tema' ('Windows kipi de' + [char]0x011F + 'i' + [char]0x015F + 'medi' + [char]0x011F + 'i h' + [char]0x00E2 + 'lde tema yeniden uyguland' + [char]0x0131 + '') }
            if ((Get-ComboKey $ui.st_ThemeSel) -ne 'Sistem') { Add-SmokeError 'tema' (('listede se' + [char]0x00E7 + 'ili ') + (Get-ComboKey $ui.st_ThemeSel) + ', beklenen Sistem') }
            if ([int]$script:ThemeFail -gt 0) { Add-SmokeError 'tema' (('uygulanamayan renk say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + [string]$script:ThemeFail) }
        }
        'ThemeCheck' {
            $cfg = ''
            try { $cfg = [string](Get-Settings).Theme } catch { }
            if ([string]$script:ThemeName -ne $arg) { Add-SmokeError 'tema' ('etkin tema ' + [string]$script:ThemeName + ', beklenen ' + $arg) }
            if ([string]$script:Settings.Theme -ne $arg) { Add-SmokeError 'tema' ('bellekteki ayar ' + [string]$script:Settings.Theme + ', beklenen ' + $arg) }
            if ($cfg -ne $arg) { Add-SmokeError 'tema' ('dosyadaki ayar ' + $cfg + ', beklenen ' + $arg) }
            if ([int]$script:ThemeFail -gt 0) { Add-SmokeError 'tema' (('uygulanamayan renk say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + [string]$script:ThemeFail) }
            $bad = @(Get-ThemeProblems $arg)
            if ($bad.Count -gt 0) { Add-SmokeError 'tema' (('uyu' + [char]0x015F + 'mayan renk: ') + ($bad -join ', ')) }
            $bad2 = @(Get-CodeBrushProblems)
            if ($bad2.Count -gt 0) { Add-SmokeError 'tema' (('koddan ' + [char]0x00FC + 'retilen ' + [char]0x00F6 + '' + [char]0x011F + 'elerin rengi temaya uymuyor: ') + ($bad2 -join ', ')) }
        }
        'BrushSeed' {
            # Her gunluk duzeyinden ve komut satiri renginden bir ornek satir eklenir; sonraki tema degisimlerinde bu satirlarin rengi denetlenir
            foreach ($lv in @('STEP', 'OK', 'WARN', 'ERR', 'PLAN', 'SKIP', 'INFO')) {
                Add-LogLine ((Get-Date -Format 'HH:mm:ss') + '  ' + $lv + ('  Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + ' ' + [char]0x00F6 + 'rnek sat' + [char]0x0131 + 'r' + [char]0x0131 + ' (') + $lv + ')')
            }
            Add-CmdLine ('Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + ': komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ' + [char]0x00F6 + 'rnek sat' + [char]0x0131 + 'r' + [char]0x0131 + '') 'BrText'
            Add-CmdLine ('Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + ': soluk ' + [char]0x00F6 + 'rnek sat' + [char]0x0131 + 'r') 'BrDim'
            $bad2 = @(Get-CodeBrushProblems)
            if ($bad2.Count -gt 0) { Add-SmokeError 'tema' (('koddan ' + [char]0x00FC + 'retilen ' + [char]0x00F6 + '' + [char]0x011F + 'elerin rengi ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + 'tan uymuyor: ') + ($bad2 -join ', ')) }
            Add-SmokeLine (('      ' + [char]0x00F6 + 'rnek sat' + [char]0x0131 + 'rlar eklendi: g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k ') + [string]$ui.LogStack.Children.Count + (', komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ') + [string]$ui.CmdOut.Children.Count)
        }
        'Resp' { Test-SmokeResp $arg }
        'UstCheck' { Test-SmokeHeader $arg }
        'UxCheck' { Test-SmokeUx $arg }
        'LiveCheck' { Test-SmokeLive $arg }
        'LangPop' { Test-SmokeLangPop $arg }
        'BusyLog' {
            if ([bool](Test-AsyncBusy)) { Add-SmokeWarn ('ba' + [char]0x015F + 'ka bir i' + [char]0x015F + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor; i' + [char]0x015F + 'lem ba' + [char]0x015F + 'lay' + [char]0x0131 + 'nca g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k denemesi atland' + [char]0x0131 + ''); return $false }
            $d = Get-LayoutDefaults ([string]$script:LayoutName)
            $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList 0
            $script:LogAutoOff = $false
            Set-BusyUi $true ('Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + '')
            $script:Win.UpdateLayout()
            $lw = [double]$ui.ColLog.ActualWidth
            $want = (([double]$d.Log -gt 0) -and ($script:RespLogFits -eq $true))
            if ($want -and $lw -lt 100) { Add-SmokeError ('g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k') (('i' + [char]0x015F + 'lem ba' + [char]0x015F + 'lay' + [char]0x0131 + 'nca g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + ' (') + [string][int]$lw + (' px); yerle' + [char]0x015F + 'im ') + [string]$script:LayoutName) }
            if ((-not $want) -and $lw -gt 2) { Add-SmokeError ('g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k') (('i' + [char]0x015F + 'lem ba' + [char]0x015F + 'lay' + [char]0x0131 + 'nca g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k kendili' + [char]0x011F + 'inden a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ' (') + [string][int]$lw + (' px); yerle' + [char]0x015F + 'im ') + [string]$script:LayoutName) }
            Add-SmokeLine (('      i' + [char]0x015F + 'lem ba' + [char]0x015F + 'lay' + [char]0x0131 + 'nca g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k (') + [string]$script:LayoutName + '): ' + [string][int]$lw + ' px, beklenen ' + $(if ($want) { ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k') } else { ('kapal' + [char]0x0131 + '') }))
            Set-BusyUi $false ''
            $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList ([double]$d.Log)
            $script:Win.UpdateLayout()
        }
        'Size' {
            $p = $arg.Split('x')
            $script:Win.Width = [double]$p[0]
            $script:Win.Height = [double]$p[1]
            $script:Win.UpdateLayout()
        }
        'Rail' {
            $sv = $ui['RailScroll']
            if ($null -eq $sv) { Add-SmokeError ('sol men' + [char]0x00FC + '') ('kayd' + [char]0x0131 + 'rma alan' + [char]0x0131 + ' (RailScroll) bulunamad' + [char]0x0131 + '') }
            else {
                # menu alani boyut degisince dugme yukseklikleri olay isleyicisinde yeniden hesaplanir; ikinci gecis sonucu olcume katar
                $script:Win.UpdateLayout()
                $script:Win.UpdateLayout()
                $ext = [int][math]::Ceiling([double]$sv.ExtentHeight)
                $vp = [int][math]::Floor([double]$sv.ViewportHeight)
                Add-SmokeLine (('      sol men' + [char]0x00FC + ': i' + [char]0x00E7 + 'erik ') + [string]$ext + (' px, g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r alan ') + [string]$vp + (' px, d' + [char]0x00FC + '' + [char]0x011F + 'me y' + [char]0x00FC + 'ksekli' + [char]0x011F + 'i ') + [string]$script:RailH + ' px, pencere ' + [string][int]$script:Win.ActualHeight + ' px')
                if ($ext -gt $vp + 1) {
                    if ($arg -eq 'warn') { Add-SmokeWarn (('sol men' + [char]0x00FC + ' bu pencerede kayd' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r (') + [string]$ext + ' > ' + [string]$vp + ' px)') }
                    else { Add-SmokeError ('sol men' + [char]0x00FC + '') (('d' + [char]0x00FC + '' + [char]0x011F + 'meler s' + [char]0x0131 + '' + [char]0x011F + 'm' + [char]0x0131 + 'yor: ') + [string]$ext + ' px > ' + [string]$vp + ' px') }
                }
            }
        }
        'Templates' {
            $panel = New-Object System.Windows.Controls.StackPanel
            $n = 0
            foreach ($v in @(Get-Variable -Scope Script -Name 'Row_*')) {
                $tn = ([string]$v.Name).Substring(4)
                $vars = @{}
                foreach ($m in [regex]::Matches([string]$v.Value, '@@(\w+)@@')) {
                    $k = $m.Groups[1].Value
                    if ($k -like 'Br*') { $vars[$k] = 'BrText' } elseif ($k -like 'Ico*') { $vars[$k] = 'IcoInfo' } else { $vars[$k] = (('' + [char]0x00D6 + 'rnek ') + $k) }
                }
                try {
                    $el = New-RowElement $tn $vars
                    [void]$panel.Children.Add($el)
                    $n++
                } catch { Add-SmokeError ('sat' + [char]0x0131 + 'r ' + [char]0x015F + 'ablonu') ($tn + ': ' + $_.Exception.Message) }
            }
            [void]$ui.PageHost.Children.Add($panel)
            try { $panel.Measure((New-Object System.Windows.Size(900, 900))); $panel.Arrange((New-Object System.Windows.Rect(0, 0, 900, 900))) }
            catch { Add-SmokeError ('sat' + [char]0x0131 + 'r ' + [char]0x015F + 'ablonu yerle' + [char]0x015F + 'imi') $_.Exception.Message }
            [void]$ui.PageHost.Children.Remove($panel)
            Add-SmokeLine ('      ' + [string]$n + ' satir sablonu olusturuldu ve yerlestirildi')
        }
        'Toasts' {
            foreach ($k in @('info', 'good', 'warn', 'bad')) { Show-Toast (('Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + ': ') + $k) $k }
            if ($ui.ToastHost.Children.Count -lt 1) { Add-SmokeError 'bildirim' ('bildirim kart' + [char]0x0131 + ' eklenmedi') }
            $script:Win.UpdateLayout()
            Save-SmokeShot 'bildirimler'
        }
        'Overlay' {
            Show-Message ('Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + '') 'Bu bir deneme iletisidir.'
            $script:Win.UpdateLayout()
            Save-SmokeShot 'kutu-mesaj'
            Close-Overlay
            Show-Confirm ('Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + '') 'Onay kutusu denemesi.' 'Tamam' { } $true
            $script:Win.UpdateLayout()
            Save-SmokeShot 'kutu-onay'
            Close-Overlay
            Show-Input ('Aray' + [char]0x00FC + 'z do' + [char]0x011F + 'rulamas' + [char]0x0131 + '') ('Giri' + [char]0x015F + ' kutusu denemesi.') ('varsay' + [char]0x0131 + 'lan') { param($t) }
            $script:Win.UpdateLayout()
            Close-Overlay
            Show-UseCaseChoice $false
            $script:Win.UpdateLayout()
            Save-SmokeShot 'kutu-kullanim-secimi'
            Close-Overlay
        }
        'Widget' {
            if ($null -eq (Get-Command -Name 'Open-Widget' -CommandType Function -ErrorAction Ignore)) { Add-SmokeError 'mini izleyici' 'Open-Widget yok' }
            else {
                $wasOpen = ($null -ne $script:Widget)
                if (-not $wasOpen) { Open-Widget }
                if ($null -eq $script:Widget) { Add-SmokeError 'mini izleyici' ('pencere a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + '') }
                else {
                    try { Update-Widget $sync.Mon } catch { Add-SmokeError 'mini izleyici' (('g' + [char]0x00FC + 'ncelleme: ') + $_.Exception.Message) }
                    try { $script:Widget.UpdateLayout() } catch { Add-SmokeError 'mini izleyici' (('yerle' + [char]0x015F + 'im: ') + $_.Exception.Message) }
                    if (-not $wasOpen) { Close-Widget }
                }
            }
        }
        'Mode' {
            $m0 = [string]$script:UiState.Mode
            Set-UiMode 'User' $true
            Set-UiMode 'Expert' $true
            Set-UiMode $m0 $true
        }
        'Console' {
            $cm = [uint32]0
            $cok = $false
            try {
                if ('WH.ConsoleWin' -as [type]) { $cok = [bool][WH.ConsoleWin]::GetConsoleMode([WH.ConsoleWin]::GetStdHandle(-10), [ref]$cm) }
            } catch { $cok = $false }
            if (-not $cok) { Add-SmokeLine ('      konsol girdi kipi okunamad' + [char]0x0131 + ' (konsol yok ya da y' + [char]0x00F6 + 'nlendirilmi' + [char]0x015F + '); h' + [char]0x0131 + 'zl' + [char]0x0131 + ' d' + [char]0x00FC + 'zenleme denetimi atland' + [char]0x0131 + '') }
            elseif (($cm -band 0x40) -ne 0) { Add-SmokeError 'konsol' (('h' + [char]0x0131 + 'zl' + [char]0x0131 + ' d' + [char]0x00FC + 'zenleme (Se' + [char]0x00E7 + ' kipi) h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'k; kip=0x') + $cm.ToString('X')) }
            else { Add-SmokeLine (('      konsol: h' + [char]0x0131 + 'zl' + [char]0x0131 + ' d' + [char]0x00FC + 'zenleme kapal' + [char]0x0131 + ' (kip=0x') + $cm.ToString('X') + ')') }
        }
        'Layout' {
            if (-not (Select-Layout $arg)) { Add-SmokeError ('yerle' + [char]0x015F + 'im') (('yerle' + [char]0x015F + 'im uygulanamad' + [char]0x0131 + ': ') + $arg) }
            # Select-* yalnizca uygular; gercek akislarda secimi Ayarlar sayfasi kaydeder. Arka plan isi bitince ayarlar dosyadan yeniden
            # okunur (Complete-Async): kaydedilmemis yerlesim eski degere donerdi. Duman testi gecici kopyada calisir.
            try { Save-Settings $script:Settings } catch { }
        }
        'LayoutCheck' { Test-SmokeLayout $arg $true }
        'LayoutGeo' { Test-SmokeLayout $arg $false }
        'ZoomCheck' {
            $z = [int]$arg
            $mem = ConvertTo-ZoomPct $script:Settings.Zoom
            if ($mem -ne $z) { Add-SmokeError ('yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma') ('bellekteki ayar %' + [string]$mem + ', beklenen %' + $arg) }
            $cfg = 0
            try { $cfg = [int](Get-Settings).Zoom } catch { }
            if ($cfg -ne $z) { Add-SmokeError ('yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma') ('dosyadaki ayar %' + [string]$cfg + ', beklenen %' + $arg) }
            $script:Win.UpdateLayout()
            $tr = $ui.BodyGrid.LayoutTransform
            $sx = 1.0
            if ($tr -is [System.Windows.Media.ScaleTransform]) { $sx = [double]$tr.ScaleX }
            if ([math]::Abs($sx - ([double]$z / 100.0)) -gt 0.001) { Add-SmokeError ('yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma') (('g' + [char]0x00F6 + 'vde ' + [char]0x00F6 + 'l' + [char]0x00E7 + 'e' + [char]0x011F + 'i ') + [string]$sx + ', beklenen ' + [string]([double]$z / 100.0)) }
            $inner = [double]$ui.Root.ActualWidth - 2
            $seen = [double]$ui.BodyGrid.ActualWidth * $sx
            Add-SmokeLine (('      yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + $arg + (': g' + [char]0x00F6 + 'vde ') + [string][int]$seen + (' px (pencere i' + [char]0x00E7 + 'i ') + [string][int]$inner + (' px), sol men' + [char]0x00FC + ' d' + [char]0x00FC + '' + [char]0x011F + 'me y' + [char]0x00FC + 'ksekli' + [char]0x011F + 'i ') + [string]$script:RailH + ' px')
            if ([math]::Abs($inner - $seen) -gt 6) { Add-SmokeError ('yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma') (('g' + [char]0x00F6 + 'vde pencereyi doldurmuyor: ') + [string][int]$seen + ' px, beklenen ' + [string][int]$inner + ' px') }
        }
        'ScrollMark' {
            $sv = Get-PageScroller 0
            if ($null -eq $sv) { Add-SmokeError ('kayd' + [char]0x0131 + 'rma') ('Ayarlar sayfas' + [char]0x0131 + 'nda kayd' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir alan bulunamad' + [char]0x0131 + ''); $script:SmokeScrollPrev = -1.0 }
            else {
                $script:SmokeScrollPrev = [double]$sv.VerticalOffset
                Add-SmokeLine (('      kayd' + [char]0x0131 + 'rma alan' + [char]0x0131 + ': i' + [char]0x00E7 + 'erik ') + [string][int]$sv.ExtentHeight + (' px, g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r ') + [string][int]$sv.ViewportHeight + (' px, kayd' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir ') + [string][int]$sv.ScrollableHeight + ' px, konum ' + [string][int]$sv.VerticalOffset)
            }
        }
        'Wheel' {
            if ([double]$script:SmokeScrollPrev -lt 0) { return $false }
            $el = $ui['st_Notify']
            $delta = -360
            if ($arg -eq 'up') { $delta = 360 }
            $ev = New-Object System.Windows.Input.MouseWheelEventArgs -ArgumentList ([System.Windows.Input.Mouse]::PrimaryDevice), ([Environment]::TickCount), $delta
            $ev.RoutedEvent = [System.Windows.UIElement]::PreviewMouseWheelEvent
            $el.RaiseEvent($ev)
            if (-not $ev.Handled) { Add-SmokeError ('kayd' + [char]0x0131 + 'rma') ('tekerlek olay' + [char]0x0131 + ' i' + [char]0x015F + 'lenmedi (sayfa kayd' + [char]0x0131 + 'r' + [char]0x0131 + 'lmad' + [char]0x0131 + ')') }
        }
        'Keys' {
            if ([double]$script:SmokeScrollPrev -lt 0) { return $false }
            $sv = Get-PageScroller 0
            $off = 0.0
            if ($null -ne $sv) { $off = [double]$sv.VerticalOffset }
            $okk = Invoke-ScrollAction $arg
            if (-not $okk -and -not ($arg -eq 'Top' -and $off -lt 1)) { Add-SmokeError ('kayd' + [char]0x0131 + 'rma') (('klavye eylemi kayd' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 'y' + [char]0x0131 + ' bulamad' + [char]0x0131 + ': ') + $arg) }
        }
        'ScrollCheck' {
            if ([double]$script:SmokeScrollPrev -lt 0) { return $false }
            $sv = Get-PageScroller 0
            if ($null -eq $sv) { Add-SmokeError ('kayd' + [char]0x0131 + 'rma') ('kayd' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + ' bulunamad' + [char]0x0131 + ''); return $false }
            $off = [double]$sv.VerticalOffset
            $mx = [double]$sv.ScrollableHeight
            if ($arg -eq 'moved') {
                if ([math]::Abs($off - [double]$script:SmokeScrollPrev) -lt 5) { Add-SmokeError ('kayd' + [char]0x0131 + 'rma') (('konum de' + [char]0x011F + 'i' + [char]0x015F + 'medi (') + [string][int]$off + ' px)') }
                else { Add-SmokeLine (('      kayd' + [char]0x0131 + 'rma: ') + [string][int]$script:SmokeScrollPrev + ' -> ' + [string][int]$off + ' px (en fazla ' + [string][int]$mx + ')') }
            } elseif ($arg -eq 'bottom') {
                if ($off -lt $mx - 2) { Add-SmokeError ('kayd' + [char]0x0131 + 'rma') ('en sona inilmedi: ' + [string][int]$off + ' / ' + [string][int]$mx) }
            } elseif ($arg -eq 'top') {
                if ($off -gt 1) { Add-SmokeError ('kayd' + [char]0x0131 + 'rma') (('en ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n' + [char]0x00FC + 'lmedi: ') + [string][int]$off) }
            }
            $script:SmokeScrollPrev = $off
        }
        'ToTop' {
            if ([double]$script:SmokeScrollPrev -lt 0) { return $false }
            $b = $script:ToTopBtn
            if ($null -eq $b) { Add-SmokeError ('ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n') ('d' + [char]0x00FC + '' + [char]0x011F + 'me kurulmam' + [char]0x0131 + '' + [char]0x015F + ''); return $false }
            $on = ($b.Visibility -eq $script:VisOn)
            if ($arg -eq 'visible' -and -not $on) { Add-SmokeError ('ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n') ('a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + ' inilince d' + [char]0x00FC + '' + [char]0x011F + 'me g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nmedi') }
            if ($arg -eq 'hidden' -and $on) { Add-SmokeError ('ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n') ('en ba' + [char]0x015F + 'ta d' + [char]0x00FC + '' + [char]0x011F + 'me h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor') }
        }
        'SmoothOff' { $script:Settings.SmoothScroll = $false }
        'SmoothOn' { $script:Settings.SmoothScroll = $true }
        'HotKey' {
            $p0 = [string]$script:UiState.Page
            Invoke-HotAction $arg
            $p1 = [string]$script:UiState.Page
            if (($arg -eq 'NextPage' -or $arg -eq 'PrevPage') -and $p1 -eq $p0) { Add-SmokeError ('k' + [char]0x0131 + 'sayol') (('sayfa de' + [char]0x011F + 'i' + [char]0x015F + 'medi: ') + $arg + ' (' + $p0 + ')') }
            if ($arg -eq 'Settings' -and $p1 -ne 'settings') { Add-SmokeError ('k' + [char]0x0131 + 'sayol') (('Ayarlar a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + ': ') + $p1) }
        }
        'TrayHide' {
            if ($null -eq $script:Tray) { Add-SmokeWarn ('tepsi simgesi kurulu de' + [char]0x011F + 'il; tepsi denemesi atland' + [char]0x0131 + ''); return $false }
            Save-SmokeTray
            $script:Settings.TrayMinimize = $true
            $script:Settings.TrayOnMinimize = $true
            $script:Win.WindowState = [System.Windows.WindowState]::Minimized
        }
        'TrayClose' {
            if ($null -eq $script:Tray) { return $false }
            Save-SmokeTray
            $script:Settings.TrayMinimize = $true
            if ($arg -eq 'alt') { $script:Win.Close() }
            else { $ui.BtnClose.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, $ui.BtnClose))) }
            if ($ui.Overlay.Visibility -eq $script:VisOn) { Add-SmokeError 'tepsi' ('X, tepsiye inmek yerine onay kutusu a' + [char]0x00E7 + 't' + [char]0x0131 + ''); Close-Overlay }
        }
        'TrayCloseBusy' {
            if ($null -eq $script:Tray) { return $false }
            Save-SmokeTray
            $script:TrayBusyHintAt = Get-Date
            $script:Settings.TrayMinimize = $true
            $busy = $false
            try { $busy = [bool](Test-AsyncBusy) } catch { $busy = $false }
            if (-not $busy) { Add-SmokeWarn ('sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ' bu anda bitmi' + [char]0x015F + 'ti; i' + [char]0x015F + 'lem s' + [char]0x00FC + 'rerken X yolu denenemedi (d' + [char]0x00FC + 'z X yolu denendi)') }
            $ui.BtnClose.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, $ui.BtnClose)))
            if ($ui.Overlay.Visibility -eq $script:VisOn) { Add-SmokeError 'tepsi' ('i' + [char]0x015F + 'lem s' + [char]0x00FC + 'rerken X, tepsiye inmek yerine onay kutusu a' + [char]0x00E7 + 't' + [char]0x0131 + ''); Close-Overlay }
        }
        'TrayMinOff' {
            if ($null -eq $script:Tray) { return $false }
            Save-SmokeTray
            $script:Settings.TrayMinimize = $true
            $script:Settings.TrayOnMinimize = $false
            $script:Win.WindowState = [System.Windows.WindowState]::Minimized
        }
        'TrayCheck' {
            if ($null -eq $script:Tray) { return $false }
            $vis = [bool]$script:Win.IsVisible
            $min = ([string]$script:Win.WindowState -eq 'Minimized')
            if ($arg -eq 'hidden') {
                if ($vis) { Add-SmokeError 'tepsi' ('pencere tepsiye inmedi (h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r)') }
            } elseif ($arg -eq 'minimized') {
                if (-not $vis) { Add-SmokeError 'tepsi' ('tepsi kapal' + [char]0x0131 + 'yken simge durumuna k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'ltme pencereyi gizledi') }
                elseif (-not $min) { Add-SmokeError 'tepsi' ('pencere simge durumuna k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'lmedi') }
            } else {
                if (-not $vis) { Add-SmokeError 'tepsi' (('pencere tepsiden geri getirilemedi (gizli kald' + [char]0x0131 + ')') + (Get-SmokeSignalInfo)) }
                elseif ($min) { Add-SmokeError 'tepsi' ('pencere geri geldi ama simge durumunda kald' + [char]0x0131 + '') }
                elseif ([double]$script:Win.ActualWidth -lt 300) { Add-SmokeError 'tepsi' ('pencere boyutu bozuk: ' + [string]$script:Win.ActualWidth) }
            }
        }
        'TraySignal' {
            if ($null -eq $script:Tray) { return $false }
            $script:SmokeSig0 = @([int]$script:SigTicks, [int]$script:SigFired)
            if ($null -eq $script:ShowEvent) { Add-SmokeWarn ('ikinci a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' olay' + [char]0x0131 + ' kurulu de' + [char]0x011F + 'il; do' + [char]0x011F + 'rudan geri getirildi'); Restore-FromTray }
            else { [void]$script:ShowEvent.Set() }
        }
        'TrayWait' {
            # ikinci acilis sinyali pencereyi geri getirene kadar (en cok 5 sn) bekler; gecikme ile hic gelmemeyi ayirt etmek icin sure yazilir
            if ($null -eq $script:Tray) { return $false }
            if ($null -eq $St.Until) { $St.Until = (Get-Date).AddSeconds(5); $St.T0 = Get-Date }
            if ([bool]$script:Win.IsVisible) {
                Add-SmokeLine ('      sinyal pencereyi ' + [string][int]((Get-Date) - $St.T0).TotalMilliseconds + (' ms i' + [char]0x00E7 + 'inde geri getirdi') + (Get-SmokeSignalInfo))
                return $false
            }
            if ((Get-Date) -lt $St.Until) { return $true }
            Add-SmokeError 'tepsi' (('ikinci a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' sinyali 5 sn i' + [char]0x00E7 + 'inde pencereyi geri getirmedi') + (Get-SmokeSignalInfo))
        }
        'TrayShow' { if ($null -ne $script:Tray) { Restore-FromTray } }
        'TrayDone' {
            if ($script:SmokeTraySaved) {
                $script:Settings.TrayMinimize = [bool]$script:SmokeTrayMin0
                $script:Settings.TrayOnMinimize = $script:SmokeTrayOn0
            }
            $script:SmokeTraySaved = $false
            $script:SmokeTrayMin0 = $null
            $script:SmokeTrayOn0 = $null
        }
        'Health' { Start-HealthScan 'Quick' $true }
        'Drain' {
            if ($null -eq $St.Until) { $St.Until = (Get-Date).AddSeconds([int]$script:SmokeDrainSec) }
            $busy = $false
            try { $busy = [bool](Test-AsyncBusy) } catch { $busy = $false }
            if ($busy -and (Get-Date) -lt $St.Until) { return $true }
            if ($busy) { Add-SmokeError ('i' + [char]0x015F + '') (('arka plan i' + [char]0x015F + 'i ') + [string]$script:SmokeDrainSec + (' sn i' + [char]0x00E7 + 'inde bitmedi')) }
            elseif ($null -ne $script:SmokeClickAt) {
                $jm = [int]((Get-Date) - $script:SmokeClickAt).TotalMilliseconds
                Add-SmokeLine (('      i' + [char]0x015F + ' s' + [char]0x00FC + 'resi ') + [string]$jm + ' ms')
                $script:SmokeClickAt = $null
            }
            [void](Read-SmokeLogDelta)
            try { Close-Overlay } catch { }
        }
        'Finish' { Complete-SmokeRun }
        default { [void](Invoke-SmokeStepLook $St) }
    }
    return $false
}

# Oturum gunlugunun yeni girdilerini okur: ERR = hata, WARN / hata akisi = uyari (program hatasi kimlikleri hata sayilir).
# Cok satirli girdiler (satir basi saat damgasi olmayanlar) onceki girdiye eklenir. Donus: bu cagrida bulunan hata sayisi.
# Beklenen gunluk satirlari: bilerek yapilan olumsuz denemeler (yanlis parola, kisa parola, bozuk dosya ...) uygulamanin gunlugune ERR ya da WARN yazar.
# Bunlar hata sayilmaz; ama gercekten yazildiklari dogrulanir (yazilmadiysa olumsuz yol hic calismamis demektir). Her beklenti en cok N satir tuketir.
$script:SmokeExpect = New-Object System.Collections.ArrayList

function Add-SmokeExpect([string]$Pattern, [int]$Count = 1, [string]$Why = '') {
    [void]$script:SmokeExpect.Add(@{ Pat = $Pattern; N = [int]$Count; Seen = 0; Why = $Why })
}

function Test-SmokeExpected([string]$Text) {
    foreach ($e in @($script:SmokeExpect)) {
        if ([int]$e.Seen -lt [int]$e.N -and $Text -match [string]$e.Pat) { $e.Seen = [int]$e.Seen + 1; return $true }
    }
    return $false
}

function Get-SmokeExpectMissing {
    $o = New-Object System.Collections.ArrayList
    foreach ($e in @($script:SmokeExpect)) {
        if ([int]$e.Seen -lt [int]$e.N) { [void]$o.Add([string]$e.Why + ' (beklenen ' + [string]$e.N + (', g' + [char]0x00F6 + 'r' + [char]0x00FC + 'len ') + [string]$e.Seen + ')') }
    }
    return $o.ToArray()
}

function Read-SmokeLogDelta {
    $errN = 0
    try {
        $lf = [string]$script:LogFile
        if ($lf -eq '' -or -not (Test-Path -LiteralPath $lf)) { return 0 }
        $text = ''
        $fs = [System.IO.File]::Open($lf, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try {
            $sr = New-Object System.IO.StreamReader($fs, (New-Object System.Text.UTF8Encoding($true)))
            $text = $sr.ReadToEnd()
        } finally { $fs.Dispose() }
        $entries = New-Object System.Collections.ArrayList
        $cur = $null
        foreach ($ln in ($text -split "`r?`n")) {
            if ($ln -match '^\d\d:\d\d:\d\d\s+(\w+)\s') { $cur = @{ Lv = $Matches[1]; Tx = $ln }; [void]$entries.Add($cur) }
            elseif ($ln -match '^HATA-AKISI:') { $cur = @{ Lv = 'AKIS'; Tx = $ln }; [void]$entries.Add($cur) }
            elseif ($null -ne $cur -and $ln.Trim() -ne '') { $cur.Tx = [string]$cur.Tx + ' | ' + $ln.Trim() }
        }
        for ($i = [int]$script:SmokeLogPos; $i -lt $entries.Count; $i++) {
            $en = $entries[$i]
            $tx = [string]$en.Tx
            if ($tx.Length -gt 700) { $tx = $tx.Substring(0, 700) + '...' }
            if (([string]$en.Lv -eq 'ERR' -or [string]$en.Lv -eq 'WARN') -and (Test-SmokeExpected $tx)) { Add-SmokeLine (('beklenen olumsuz deneme [g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k] ') + $tx); continue }
            switch ([string]$en.Lv) {
                'ERR' { $errN++; [void]$script:SmokeErrs.Add(@{ Step = $script:SmokeCur; Where = ('oturum g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ''); Msg = $tx }); Add-SmokeLine ('HATA  [' + $script:SmokeCur + ('] [g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k] ') + $tx) }
                'WARN' { Add-SmokeWarn (('[g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k] ') + $tx) }
                'AKIS' {
                    if ($tx -match $script:SmokeBadIds) { $errN++; [void]$script:SmokeErrs.Add(@{ Step = $script:SmokeCur; Where = ('hata ak' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ''); Msg = $tx }); Add-SmokeLine ('HATA  [' + $script:SmokeCur + ('] [ak' + [char]0x0131 + '' + [char]0x015F + '] ') + $tx) }
                    else { Add-SmokeWarn (('[ak' + [char]0x0131 + '' + [char]0x015F + '] ') + $tx) }
                }
            }
        }
        $script:SmokeLogPos = $entries.Count
    } catch { Add-SmokeLine (('UYARI g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    return $errN
}

# Canli izleme gercekten olcum uretiyor mu, nabiz taze mi, oturum izi yaziliyor mu
function Test-SmokeMonitor {
    $m = $sync.Mon
    if ($null -eq $m -or -not $m.ContainsKey('Cpu')) { Add-SmokeError 'izleme' ('ilk ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm hi' + [char]0x00E7 + ' gelmedi'); return }
    $d = $sync.MonDiag
    $age = -1
    try { $age = [int]([DateTime]::UtcNow - [DateTime]$sync.MonBeat).TotalSeconds } catch { }
    $tick = -1; $ms = -1; $gf = -1; $tf = -1; $nf = -1
    if ($d -is [hashtable]) { $tick = [int]$d.Tick; $ms = [int]$d.Ms; $gf = [int]$d.GpuFail; $tf = [int]$d.TempFail; $nf = [int]$d.NetFail }
    Add-SmokeLine (('izleme: i' + [char]0x015F + 'lemci=%') + [string]$m.Cpu + ' bellek=%' + [string]$m.Ram + ' (' + [string]$m.RamUsedGB + '/' + [string]$m.RamTotalGB + ' GB) disk=%' + [string]$m.Disk + (' a' + [char]0x011F + '=') + [string][int]$m.NetDown + '/' + [string][int]$m.NetUp + ' B/sn GPU=' + [string]$m.Gpu + (' s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k=') + [string]$m.Temp + (' i' + [char]0x015F + 'lem=') + [string]@($m.Top).Count + (' nab' + [char]0x0131 + 'z=') + [string]$age + ' sn tur=' + [string]$tick + ' son-tur=' + [string]$ms + ' ms gpuHata=' + [string]$gf + (' ' + [char]0x0131 + 's' + [char]0x0131 + 'Hata=') + [string]$tf + (' a' + [char]0x011F + 'Hata=') + [string]$nf + (' g' + [char]0x00FC + 'venli=') + [string]$script:SafeMode)
    if ($age -lt 0 -or $age -gt 30) { Add-SmokeError 'izleme' (('nab' + [char]0x0131 + 'z bayat ya da yok: ') + [string]$age + ' sn') }
    if ([double]$m.RamTotalGB -le 0) { Add-SmokeError 'izleme' ('bellek ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemedi') }
    if ($tick -lt 1) { Add-SmokeWarn ('izleme: bir turdan az ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm') }
    if (-not [string]::IsNullOrEmpty($script:TraceFile) -and (Test-Path -LiteralPath $script:TraceFile)) {
        $tl = @(Get-SessionTail $script:TraceFile 400)
        $joined = ($tl -join "`n")
        # "pencere acildi" iz dosyasinin basindadir; uzun kosuda son 400 satirin disinda kalir: bu satir icin dosyanin tamamina bakilir
        $whole = $joined
        try { $whole = [System.IO.File]::ReadAllText($script:TraceFile, [System.Text.Encoding]::UTF8) } catch { }
        Add-SmokeLine ('oturum izi: ' + [string]$tl.Count + (' sat' + [char]0x0131 + 'r; sayfa ge' + [char]0x00E7 + 'i' + [char]0x015F + 'i=') + [string]@($tl | Where-Object { $_ -like '*sayfa: *' }).Count + (' i' + [char]0x015F + '=') + [string]@($tl | Where-Object { $_ -like ('*i' + [char]0x015F + ' bitti:*') -or $_ -like '*is bitti:*' }).Count)
        if ($whole -notlike ('*pencere a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '*')) { Add-SmokeError 'oturum izi' ('pencere a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ' sat' + [char]0x0131 + 'r' + [char]0x0131 + ' yok') }
        if ($joined -notlike '*sayfa: *') { Add-SmokeError 'oturum izi' ('sayfa ge' + [char]0x00E7 + 'i' + [char]0x015F + 'i izlenmiyor') }
    } else { Add-SmokeError 'oturum izi' ('iz dosyas' + [char]0x0131 + ' yok') }
    $sj = $null
    try { $sj = ConvertTo-Hashtable (Read-JsonFile $script:SessFile) } catch { }
    if ($sj -is [hashtable] -and [string]$sj.Durum -eq 'acik' -and [int]$sj.Pid -eq $PID) { Add-SmokeLine ('oturum kayd' + [char]0x0131 + ': a' + [char]0x00E7 + '' + [char]0x0131 + 'k (bu s' + [char]0x00FC + 're' + [char]0x00E7 + ')') } else { Add-SmokeError ('oturum kayd' + [char]0x0131 + '') ('oturum.json a' + [char]0x00E7 + '' + [char]0x0131 + 'k g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor') }
}

# Baslik cubugu dugmeleri: pencere kromunda tiklanabilir olmali (WindowChrome altinda olmazsa tiklamalar suruklemeye gider)
function Test-SmokeChrome {
    foreach ($nm in @('BtnMin', 'BtnMax', 'BtnClose', 'BtnLogToggle', 'SegUser', 'SegExpert')) {
        $el = $ui[$nm]
        if ($null -eq $el) { Add-SmokeError ('ba' + [char]0x015F + 'l' + [char]0x0131 + 'k ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'u') ($nm + (' bulunamad' + [char]0x0131 + '')); continue }
        $ok = $false
        $cur = $el
        for ($i = 0; $i -lt 8 -and $null -ne $cur; $i++) {
            try { if ([System.Windows.Shell.WindowChrome]::GetIsHitTestVisibleInChrome($cur)) { $ok = $true; break } } catch { }
            try { $cur = [System.Windows.Media.VisualTreeHelper]::GetParent($cur) } catch { $cur = $null }
        }
        if (-not $ok) { Add-SmokeError ('ba' + [char]0x015F + 'l' + [char]0x0131 + 'k ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'u') ($nm + (' pencere kromunda t' + [char]0x0131 + 'klanabilir de' + [char]0x011F + 'il')) }
    }
}

# ---------------- duman: erisilebilirlik olcumu (yalnizca okur) ----------------
# ---------------- Duman testi: erisilebilirlik olcumu (yalnizca okur) ----------------
# Her ekran goruntusunde pencerede gorunen denetim ogelerini (dugme, onay kutusu, secenek dugmesi, secim kutusu, metin kutusu,
# kaydirici) gezer ve iki seyi olcer:
#  1) Ekran okuyucunun okuyacagi ad (UI Automation Name) bos mu ya da yalnizca simge yazi tipi karakteri mi (Ekran Okuyucu bunu
#     "dugme" diye adsiz okur). Ad, ogenin otomasyon esinden (AutomationPeer) alinir; Windows'un ekran okuyucuya verdigi addir.
#  2) Dokunma hedefi: kisa kenari 24 px'ten kucuk mu (WCAG 2.2 AA alt siniri) ya da 24-32 px arasinda mi (Windows sik yerlesim
#     olcusu 32 px; dokunmatik ekran icin onerilen yaklasik 40 px). Olculer etkin pikseldir (96 DPI'a gore).
# Ayni sayfa ve sekme her temada yeniden olculmez (adlar temaya bagli degil); yerlesimler ayri olculur (boyutlar degisir).
# Baska bir denetimin parcasi olan ogeler (kaydirma cubugu oklari, secim kutusunun acma dugmesi gibi) sayilmaz.
# Hicbir seyi degistirmez; ozet duman sonucuna, ayrinti %TEMP%\Multimizer-duman-erisim.txt dosyasina yazilir.
$script:SmokeA11y = $null
$script:SmokeA11yMax = 200
$script:SmokeA11yMaxLarge = 160
$script:SmokeA11yFails = 0

# Ad bos ya da yalnizca simge/noktalama mi (harf ya da rakam yoksa ekran okuyucu anlamli bir sey okuyamaz)
function Test-A11yNameBad([string]$Name) {
    $t = ([string]$Name).Trim()
    if ($t.Length -eq 0) { return $true }
    foreach ($ch in $t.ToCharArray()) {
        $c = [int]$ch
        if ($c -ge 0xE000 -and $c -le 0xF8FF) { continue }
        if ([char]::IsLetterOrDigit($ch)) { return $false }
    }
    return $true
}

# Ekran goruntusu adindan tema onekini atar: "Neon-home" ve "Koyu-home" ayni gorunumdur
function Get-A11yContextKey([string]$Shot) {
    $s = [string]$Shot
    $i = $s.IndexOf('-')
    if ($i -gt 0) {
        $first = $s.Substring(0, $i)
        foreach ($t in @($script:SmokeThemes)) { if ([string]$t -eq $first) { return $s.Substring($i + 1) } }
    }
    return $s
}

# Turlere gore sayim: anahtarin ilk sozcugu tur adidir ("Button Kok \"Uygula\"")
function Get-A11yKindCounts($Map) {
    $c = @{}
    foreach ($k in @($Map.Keys)) {
        $kind = ([string]$k).Split(' ')[0]
        if (-not $c.ContainsKey($kind)) { $c[$kind] = 0 }
        $c[$kind] = [int]$c[$kind] + 1
    }
    if ($c.Count -eq 0) { return '' }
    return (' (' + ((@($c.Keys | Sort-Object) | ForEach-Object { [string]$_ + ' ' + [string]$c[$_] }) -join ', ') + ')')
}

# Rapora yazilan gorunen yazi ve adlarda kisisel veri olmasin (IP, e-posta, kullanici klasoru yolu)
function Protect-A11yText([string]$Text) {
    $t = [string]$Text
    $t = [regex]::Replace($t, '\b\d{1,3}(\.\d{1,3}){3}\b', '<gizli>')
    $t = [regex]::Replace($t, '[0-9A-Fa-f]{0,4}(:[0-9A-Fa-f]{0,4}){3,}', '<gizli>')
    $t = [regex]::Replace($t, '[^\s"@]+@[^\s"@]+\.[^\s"@]+', '<gizli>')
    $t = [regex]::Replace($t, '(?i)\\Users\\[^\\\s"]+', '\Users\<gizli>')
    return $t
}

# Ad, denetimin gorunen yazisi ya da ipucuyla ortusuyor mu? (biri digerini iceriyorsa ortusur; yazi yoksa sorun sayilmaz)
function Test-A11yNameMismatch([string]$Label, [string]$Name) {
    $l = ([string]$Label).Trim()
    if ($l.StartsWith('ipucu: ')) { $l = $l.Substring(7) }
    if ($l.EndsWith('...')) { $l = $l.Substring(0, $l.Length - 3) }
    $l = $l.Trim()
    if ($l -eq '' -or (Test-A11yNameBad $Name)) { return $false }
    $n = ([string]$Name).Trim()
    if ($n.StartsWith($l + ',', [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
    if ($n.Length -lt 3 -or $l.Length -lt 3) { return ($n -ne $l) }
    if ($n.IndexOf($l, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return $false }
    if ($l.IndexOf($n, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return $false }
    return $true
}

function Get-A11yKind($El) {
    if ($El -is [System.Windows.Controls.ComboBox]) { return 'ComboBox' }
    if ($El -is [System.Windows.Controls.Slider]) { return 'Slider' }
    if ($El -is [System.Windows.Controls.PasswordBox]) { return 'PasswordBox' }
    if ($El -is [System.Windows.Controls.Primitives.TextBoxBase]) { return 'TextBox' }
    if ($El -is [System.Windows.Controls.Primitives.ButtonBase]) { return [string]$El.GetType().Name }
    return ''
}

# Ogenin ekranda gorunen yazisi (yoksa ipucu): ayrinti listesinde hangi oge oldugunu bulmak icin
function Get-A11yLabel($El) {
    try {
        if ($El -is [System.Windows.Controls.ContentControl]) {
            $cn = $El.Content
            if ($cn -is [string] -and -not (Test-A11yNameBad ([string]$cn))) { return [string]$cn }
        }
        $stack = New-Object System.Collections.Stack
        $stack.Push($El)
        $n = 0
        while ($stack.Count -gt 0 -and $n -lt 60) {
            $o = $stack.Pop()
            $n++
            if ($o -is [System.Windows.Controls.TextBlock]) {
                $tx = [string]$o.Text
                if (-not (Test-A11yNameBad $tx)) { if ($tx.Length -gt 40) { $tx = $tx.Substring(0, 40) + '...' }; return $tx }
            }
            $k = 0
            try { $k = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o) } catch { $k = 0 }
            for ($i = $k - 1; $i -ge 0; $i--) { try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $i)) } catch { } }
        }
    } catch { }
    try {
        $tt = $El.ToolTip
        if ($tt -is [string] -and [string]$tt -ne '') { $s = [string]$tt; if ($s.Length -gt 40) { $s = $s.Substring(0, 40) + '...' }; return ('ipucu: ' + $s) }
    } catch { }
    return ''
}

# Ogenin kendisinin ya da en yakin ust ogesinin adi (x:Name): ayrinti listesinde yer bulmak icin
function Get-A11yAnchor($El) {
    $cur = $El
    $n = 0
    while ($null -ne $cur -and $n -lt 40) {
        $nm = ''
        try { $nm = [string]$cur.Name } catch { $nm = '' }
        if ($nm -ne '') { return $nm }
        try { $cur = [System.Windows.Media.VisualTreeHelper]::GetParent($cur) } catch { $cur = $null }
        $n++
    }
    return '?'
}

function Add-SmokeA11yFail([string]$Msg) {
    $script:SmokeA11yFails = [int]$script:SmokeA11yFails + 1
    if ([int]$script:SmokeA11yFails -eq 1) { Add-SmokeLine (('eri' + [char]0x015F + 'ilebilirlik ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm' + [char]0x00FC + ' yap' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (bilgi): ') + $Msg) }
}

function Measure-SmokeA11y([string]$Shot) {
    if ($null -eq $script:SmokeA11y) {
        $script:SmokeA11y = @{ Runs = 0; Seen = @{}; NoName = @{}; Small24 = @{}; Small32 = @{}; Ctx = @{}; Kinds = @{}; Named = @{}; Mis = @{}; Dup = @{}; L24 = @{}; L32 = @{}; L40 = @{}; LRuns = 0; Capped = $false; Ms = 0 }
    }
    $A = $script:SmokeA11y
    $ctx = Get-A11yContextKey $Shot
    if ($A.Ctx.ContainsKey($ctx)) { return }
    if ($ctx.StartsWith('dokunma-')) {
        if ([int]$A.LRuns -ge [int]$script:SmokeA11yMaxLarge) { $A.Capped = $true; return }
    } elseif (([int]$A.Runs - [int]$A.LRuns) -ge [int]$script:SmokeA11yMax) { $A.Capped = $true; return }
    $root = $script:Win
    if ($null -eq $root) { return }
    $A.Ctx[$ctx] = $true
    $A.Runs = [int]$A.Runs + 1
    if ($ctx.StartsWith('dokunma-')) { $A.LRuns = [int]$A.LRuns + 1 }
    # bekleyen ekran okuyucu adlari once verilir (olcum, adlarin verilme anina bagli kalmasin)
    try { if ($null -ne $script:A11yQueue -and $script:A11yQueue.Count -gt 0) { Invoke-A11yQueue $true } } catch { }
    $t0 = Get-Date
    $stack = New-Object System.Collections.Stack
    $stack.Push($root)
    $n = 0
    while ($stack.Count -gt 0 -and $n -lt 30000) {
        $o = $stack.Pop()
        $n++
        if ($o -is [System.Windows.UIElement]) { if (-not $o.IsVisible) { continue } }
        $kind = Get-A11yKind $o
        if ($kind -ne '') {
            $part = $false
            try { $part = ($o.TemplatedParent -is [System.Windows.Controls.Control]) } catch { $part = $false }
            $w = 0.0
            $h = 0.0
            try { $w = [double]$o.ActualWidth; $h = [double]$o.ActualHeight } catch { }
            if (-not $part -and $w -gt 0 -and $h -gt 0) {
                $lab = Get-A11yLabel $o
                $anc = Get-A11yAnchor $o
                $key = $kind + ' ' + $anc + ' "' + $lab + '"'
                if (-not $A.Seen.ContainsKey($key)) {
                    $A.Seen[$key] = $ctx
                    if (-not $A.Kinds.ContainsKey($kind)) { $A.Kinds[$kind] = 0 }
                    $A.Kinds[$kind] = [int]$A.Kinds[$kind] + 1
                }
                $name = ''
                try {
                    $peer = [System.Windows.Automation.Peers.UIElementAutomationPeer]::CreatePeerForElement($o)
                    if ($null -ne $peer) { $name = [string]$peer.GetName() }
                } catch { $name = '' }
                if (Test-A11yNameBad $name) {
                    if (-not $A.NoName.ContainsKey($key)) { $A.NoName[$key] = $ctx }
                } else {
                    $nm1 = $name.Trim()
                    if (-not $A.Named.ContainsKey($key)) {
                        $A.Named[$key] = '-> "' + $nm1 + '" [' + $ctx + ']'
                        if (Test-A11yNameMismatch $lab $nm1) { $A.Mis[$key] = '-> "' + $nm1 + '" [' + $ctx + ']' }
                    }
                    $dk = $ctx + ' ' + $kind + ' "' + $nm1 + '"'
                    if (-not $A.Dup.ContainsKey($dk)) { $A.Dup[$dk] = @{ N = 0; Anchors = @{} } }
                    $A.Dup[$dk].N = [int]$A.Dup[$dk].N + 1
                    $A.Dup[$dk].Anchors[$anc] = $true
                }
                $mn = [Math]::Min($w, $h)
                $sz = [string][int][Math]::Round($w) + 'x' + [string][int][Math]::Round($h)
                if ($ctx.StartsWith('dokunma-')) {
                    if ($mn -lt 24) { if (-not $A.L24.ContainsKey($key)) { $A.L24[$key] = $ctx + ' ' + $sz } }
                    elseif ($mn -lt 32) { if (-not $A.L32.ContainsKey($key)) { $A.L32[$key] = $ctx + ' ' + $sz } }
                    elseif ($mn -lt 40 -and $ctx.IndexOf('Kompakt') -lt 0 -and @('Button', 'CheckBox', 'RadioButton') -contains $kind) { if (-not $A.L40.ContainsKey($key)) { $A.L40[$key] = $ctx + ' ' + $sz } }
                }
                elseif ($mn -lt 24) { if (-not $A.Small24.ContainsKey($key)) { $A.Small24[$key] = $ctx + ' ' + $sz } }
                elseif ($mn -lt 32) { if (-not $A.Small32.ContainsKey($key)) { $A.Small32[$key] = $ctx + ' ' + $sz } }
            }
        }
        $k = 0
        try { $k = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o) } catch { $k = 0 }
        for ($i = $k - 1; $i -ge 0; $i--) { try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $i)) } catch { } }
    }
    $A.Ms = [int]$A.Ms + [int]((Get-Date) - $t0).TotalMilliseconds
}

function Write-SmokeA11yReport {
    $A = $script:SmokeA11y
    if ($null -eq $A -or [int]$A.Runs -le 0) { return }
    $kinds = (@($A.Kinds.Keys | Sort-Object) | ForEach-Object { [string]$_ + ' ' + [string]$A.Kinds[$_] }) -join ', '
    Add-SmokeLine (('--- eri' + [char]0x015F + 'ilebilirlik (bilgi; hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmedi): ') + [string]$A.Runs + (' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mde ') + [string]$A.Seen.Count + (' denetim ' + [char]0x00F6 + '' + [char]0x011F + 'esi (') + $kinds + '), ' + [string]$A.Ms + ' ms')
    Add-SmokeLine (('  ekran okuyucu ad' + [char]0x0131 + ' bo' + [char]0x015F + ' ya da yaln' + [char]0x0131 + 'zca simge: ') + [string]$A.NoName.Count + (Get-A11yKindCounts $A.NoName))
    Add-SmokeLine (('  dokunma hedefi 24 px alt' + [char]0x0131 + ': ') + [string]$A.Small24.Count + (Get-A11yKindCounts $A.Small24) + ('; 24-32 px aras' + [char]0x0131 + ': ') + [string]$A.Small32.Count + (Get-A11yKindCounts $A.Small32))
    $dupShow = @{}
    if ($null -ne $A.Dup) {
        foreach ($dk in @($A.Dup.Keys)) {
            $dv = $A.Dup[$dk]
            if ([int]$dv.N -ge 2) { $dupShow[$dk] = [string]$dv.N + ' denetim, ' + [string]$dv.Anchors.Count + (' ayr' + [char]0x0131 + ' ' + [char]0x00E7 + 'apa: ') + ((@($dv.Anchors.Keys | Sort-Object | Select-Object -First 4)) -join ', ') }
        }
    }
    if ($null -ne $A.Named) {
        Add-SmokeLine ('  verilen ad listesi: ' + [string]$A.Named.Count + (' denetim; ad yaz' + [char]0x0131 + 'yla ' + [char]0x00F6 + 'rt' + [char]0x00FC + '' + [char]0x015F + 'meyen: ') + [string]$A.Mis.Count + ('; ayn' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mde ayn' + [char]0x0131 + ' ad: ') + [string]$dupShow.Count)
    }
    if ($A.Capped -eq $true) { Add-SmokeLine (('  UYARI: ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + ' doldu; kalan g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mler ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lmedi (Normal ') + [string]$script:SmokeA11yMax + (', B' + [char]0x00FC + 'y' + [char]0x00FC + 'k ') + [string]$script:SmokeA11yMaxLarge + ')') }
    if ([int]$A.LRuns -gt 0) {
        Add-SmokeLine (('  dokunma hedefleri B' + [char]0x00FC + 'y' + [char]0x00FC + 'k (') + [string]$A.LRuns + (' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm): 24 px alt' + [char]0x0131 + ': ') + [string]$A.L24.Count + ('; 24-32 px aras' + [char]0x0131 + ': ') + [string]$A.L32.Count + ('; 32-40 px aras' + [char]0x0131 + ' (Kompakt d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + '): ') + [string]$A.L40.Count)
    }
    if ($null -ne $script:A11yCalls) { Add-SmokeLine (('  ekran okuyucu ad' + [char]0x0131 + ' verilen: ') + [string][int]$script:A11yDone + ' denetim (incelenen ' + [string][int]$script:A11yCalls + ')') }
    if ([int]$script:SmokeA11yFails -gt 0) { Add-SmokeLine (('  ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ') + [string]$script:SmokeA11yFails + (' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mde yar' + [char]0x0131 + 'da kald' + [char]0x0131 + '; say' + [char]0x0131 + 'lar eksik olabilir')) }
    $nl = "`r`n"
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append(('MULTIMIZER ER' + [char]0x0130 + '' + [char]0x015E + '' + [char]0x0130 + 'LEB' + [char]0x0130 + 'L' + [char]0x0130 + 'RL' + [char]0x0130 + 'K ' + [char]0x00D6 + 'L' + [char]0x00C7 + '' + [char]0x00DC + 'M' + [char]0x00DC + ' (yaln' + [char]0x0131 + 'zca okuma; hi' + [char]0x00E7 + 'bir ayar de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmedi)') + $nl)
    [void]$sb.Append('tarih=' + (Get-Date).ToString('yyyy-MM-dd HH:mm:ss') + ('  g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm=') + [string]$A.Runs + ('  ' + [char]0x00F6 + '' + [char]0x011F + 'e=') + [string]$A.Seen.Count + ('  s' + [char]0x00FC + 're=') + [string]$A.Ms + ' ms' + $nl)
    [void]$sb.Append(('' + [char]0x00D6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 't: ekran okuyucunun okuyaca' + [char]0x011F + '' + [char]0x0131 + ' ad (UI Automation Name) bo' + [char]0x015F + ' ya da yaln' + [char]0x0131 + 'zca simge; dokunma hedefinin k' + [char]0x0131 + 'sa kenar' + [char]0x0131 + ' 24 px (WCAG 2.2 AA) ve 32 px (Windows s' + [char]0x0131 + 'k yerle' + [char]0x015F + 'im) alt' + [char]0x0131 + 'nda. ' + [char]0x00D6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'ler etkin pikseldir.') + $nl)
    [void]$sb.Append(('Sat' + [char]0x0131 + 'r bi' + [char]0x00E7 + 'imi: t' + [char]0x00FC + 'r  ' + [char]0x00E7 + 'apa (' + [char]0x00F6 + '' + [char]0x011F + 'enin ya da en yak' + [char]0x0131 + 'n ' + [char]0x00FC + 'st ' + [char]0x00F6 + '' + [char]0x011F + 'enin ad' + [char]0x0131 + ')  "g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen yaz' + [char]0x0131 + ' ya da ipucu"  |  ilk g' + [char]0x00F6 + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm [' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + ']') + $nl)
    $sections = @(
        @{ T = ('ADSIZ (ekran okuyucu ad' + [char]0x0131 + ' bo' + [char]0x015F + ' ya da yaln' + [char]0x0131 + 'zca simge)'); M = $A.NoName },
        @{ T = '24 PX ALTI'; M = $A.Small24 },
        @{ T = '24-32 PX ARASI'; M = $A.Small32 },
        @{ T = ('AD G' + [char]0x00D6 + 'R' + [char]0x00DC + 'NEN YAZIYLA ' + [char]0x00D6 + 'RT' + [char]0x00DC + '' + [char]0x015E + 'M' + [char]0x00DC + 'YOR (sat' + [char]0x0131 + 'r: t' + [char]0x00FC + 'r ' + [char]0x00E7 + 'apa "g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen yaz' + [char]0x0131 + '" -> verilen ad)'); M = $A.Mis },
        @{ T = ('AYNI G' + [char]0x00D6 + 'R' + [char]0x00DC + 'N' + [char]0x00DC + 'MDE AYNI T' + [char]0x00DC + 'RDE AYNI AD (g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm t' + [char]0x00FC + 'r "ad")'); M = $dupShow },
        @{ T = ('VER' + [char]0x0130 + 'LEN ADLAR (t' + [char]0x00FC + 'r ' + [char]0x00E7 + 'apa "g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen yaz' + [char]0x0131 + '" -> verilen ad)'); M = $A.Named }
    )
    if ([int]$A.LRuns -gt 0) {
        $sections = @($sections) + @(
            @{ T = ('DOKUNMA B' + [char]0x00DC + 'Y' + [char]0x00DC + 'K: 24 PX ALTI'); M = $A.L24 },
            @{ T = ('DOKUNMA B' + [char]0x00DC + 'Y' + [char]0x00DC + 'K: 24-32 PX ARASI'); M = $A.L32 },
            @{ T = ('DOKUNMA B' + [char]0x00DC + 'Y' + [char]0x00DC + 'K: 32-40 PX ARASI (Kompakt d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ')'); M = $A.L40 }
        )
    }
    foreach ($sec in $sections) {
        $m = $sec.M
        if ($null -eq $m) { $m = @{} }
        [void]$sb.Append($nl + '[' + [string]$sec.T + '] ' + [string]$m.Count + $nl)
        $i = 0
        foreach ($k in @($m.Keys | Sort-Object)) {
            $i++
            if ($i -gt 400) { [void]$sb.Append(('  ... (ilk 400 sat' + [char]0x0131 + 'r)') + $nl); break }
            [void]$sb.Append('  ' + (Protect-A11yText ([string]$k)) + '  |  ' + (Protect-A11yText ([string]$m[$k])) + $nl)
        }
    }
    $path = Join-Path ([System.IO.Path]::GetTempPath()) 'Multimizer-duman-erisim.txt'
    try {
        [System.IO.File]::WriteAllText($path, $sb.ToString(), (New-Object System.Text.UTF8Encoding($true)))
        Add-SmokeLine (('  ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ': ') + $path)
    } catch { Add-SmokeLine (('  ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' dosyas' + [char]0x0131 + ' yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
}

function Complete-SmokeRun {
    if ($script:SmokeDone) { return }
    $script:SmokeDone = $true
    try { if ($null -ne $script:SmokeTimer) { $script:SmokeTimer.Stop() } } catch { }
    try { Stop-SmokeLook } catch { }
    try { Set-AppTheme $script:SmokeTheme } catch { }
    try { if ([string]$script:LayoutName -ne [string]$script:SmokeLayout) { [void](Select-Layout $script:SmokeLayout) } } catch { }
    [void](Read-SmokeLogDelta)
    try { Test-SmokeMonitor } catch { Add-SmokeError 'izleme denetimi' $_.Exception.Message }
    try { Test-SmokeChrome } catch { Add-SmokeError ('ba' + [char]0x015F + 'l' + [char]0x0131 + 'k ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'u denetimi') $_.Exception.Message }
    # yutulan (try / catch ile gecistirilen) hatalarin ozeti: bilgi amaclidir, sonucu etkilemez; [kod?] program hatasi olasiligi yuksek olanlardir
    try {
        [void](Save-DebugErrors 'ana')
        $dc = Get-DebugCounts
        Add-SmokeLine ('--- yutulan hatalar (bilgi): ' + [string]$dc.Kinds + (' t' + [char]0x00FC + 'r, ') + [string]$dc.Total + (' kay' + [char]0x0131 + 't, program hatas' + [char]0x0131 + ' olas' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ': ') + [string]$dc.Code + (' t' + [char]0x00FC + 'r ---'))
        foreach ($dl in @(Get-DebugSummary 40)) { Add-SmokeLine ('  ' + [string]$dl) }
    } catch { Add-SmokeLine (('yutulan hata ' + [char]0x00F6 + 'zeti yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    try { Write-SmokeA11yReport } catch { Add-SmokeA11yFail $_.Exception.Message }
    try { Write-SmokeLangReport } catch { Add-SmokeLine ('dil raporu yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ' + $_.Exception.Message) }
    $n = $script:SmokeErrs.Count
    $secs = 0
    try { $secs = [int]((Get-Date) - $script:SmokeStart).TotalSeconds } catch { }
    $script:SmokeExit = 0
    if ($n -gt 0 -or [int]$script:UiErrTotal -gt 0) { $script:SmokeExit = 2 }
    Add-SmokeLine ('=== DUMAN TESTI bitti: hata=' + [string]$n + '   uyari=' + [string]$script:SmokeWarns + '   yakalanmamis=' + [string]$script:UiErrTotal + '   tiklanan=' + [string]$script:SmokeClicks + '   goruntu=' + [string]$script:SmokeShots + '   sure=' + [string]$secs + ' sn')
    if ($script:SmokeExit -eq 0) { Add-SmokeLine 'SONUC TEMIZ' } else { Add-SmokeLine 'SONUC HATALI' }
    $script:SmokeFinishing = $true
    Exit-App
}


# ---------------- Sol menu yogunlugu ----------------
# ==================================================================
#  SOL MENU YOGUNLUGU
#  16 sayfa x 56 px = 896 px; 840 px'lik pencerede Yedek / Sirket / Araclar kesiliyor ve fare tekerlegi olmadan gorunmuyordu.
#  Dugme yuksekligi, gorunen dugme sayisina ve pencere yuksekligine gore 40-56 px arasinda secilir (cok kucuk ekranda menu kaydirilir).
# ==================================================================
$script:RailH = 0
$script:RailMax = 56
$script:RailMin = 40

# Verilen yukseklik ve dugme sayisi icin dugme yuksekligi (saf hesap; ekrana dokunmaz)
function Get-RailHeight([double]$Avail, [int]$Count) {
    if ($Count -lt 1) { return [int]$script:RailMax }
    $h = [int][math]::Floor($Avail / $Count)
    if ($h -gt [int]$script:RailMax) { $h = [int]$script:RailMax }
    if ($h -lt [int]$script:RailMin) { $h = [int]$script:RailMin }
    if ($script:TouchMode -eq 'Large' -and $h -lt [int]$script:TouchMinNow) { $h = [int]$script:TouchMinNow }
    return $h
}

function Update-RailDensity {
    $host_ = $ui['RailHost']
    if ($null -eq $host_) { return }
    # Acilir menu gruplari (Sade yerlesim): basliklarin gorunurlugu her cagrida guncellenir
    try { if ($null -ne (Get-Command -Name 'Refresh-RailGroups' -CommandType Function -ErrorAction Ignore)) { Refresh-RailGroups } } catch { }
    # Kaydirma alaninin ust boslugu (6) + alt bolumun alt boslugu (6) + yerlesim payi (8): dugmeler kaydirma gerektirmeden sigsin
    $avail = [double]$host_.ActualHeight - 20
    if ($avail -le 0) { return }
    $all = New-Object System.Collections.ArrayList
    $vis = 0
    foreach ($k in @($script:PageTitles.Keys)) {
        $rb = $ui['Rail_' + $k]
        if ($null -eq $rb) { continue }
        [void]$all.Add($rb)
        if (Test-RailShown $rb) { $vis++ }
    }
    # grup basliklari yer kaplar (her biri ~32 px)
    $hdr = 0
    foreach ($g in @($script:RailGroups)) { if ($g.Header.Visibility -eq $script:VisOn) { $hdr++ } }
    $avail = $avail - 32.0 * $hdr
    $h = Get-RailHeight $avail $vis
    if ($h -eq [int]$script:RailH) { return }
    $script:RailH = $h
    foreach ($rb in $all) { $rb.Height = [double]$h }
}


# ---------------- Gorunum ----------------
