    Acik   = @{ T = 'Beyaz';     D = ('Beyaz y' + [char]0x00FC + 'zeyler, koyu lacivert d' + [char]0x00FC + '' + [char]0x011F + 'meler ve eflatun ikinci vurgu; sade ve rahat okunur. Varsay' + [char]0x0131 + 'lan tema.') }
    Kum    = @{ T = ('Krem (s' + [char]0x0131 + 'cak a' + [char]0x00E7 + '' + [char]0x0131 + 'k)'); D = ('Krem k' + [char]0x00E2 + '' + [char]0x011F + '' + [char]0x0131 + 't zemin, kiremit ve erik moru vurgu; g' + [char]0x00F6 + 'z yormayan s' + [char]0x0131 + 'cak a' + [char]0x00E7 + '' + [char]0x0131 + 'k tema.') }
    Yuksek = @{ T = ('Y' + [char]0x00FC + 'ksek kar' + [char]0x015F + '' + [char]0x0131 + 'tl' + [char]0x0131 + 'k'); D = ('Siyah zemin, beyaz yaz' + [char]0x0131 + ' ve belirgin ' + [char]0x00E7 + 'izgiler; g' + [char]0x00F6 + 'rmesi zor olanlar i' + [char]0x00E7 + 'in.') }
    Hacker = @{ T = ('Terminal (ye' + [char]0x015F + 'il)');           D = ('Siyah zemin, fosfor ye' + [char]0x015F + 'ili terminal renkleri.') }
    Cam    = @{ T = ('Buzlu cam (a' + [char]0x00E7 + '' + [char]0x0131 + 'k)');        D = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'k, pastel zemin ve yar' + [char]0x0131 + ' saydam cam y' + [char]0x00FC + 'zeyler; mavi' + [char]0x2013 + 'eflatun ge' + [char]0x00E7 + 'i' + [char]0x015F + '.') }
    Holo   = @{ T = 'Koyu cam';       D = ('Koyu cam y' + [char]0x00FC + 'zeyler, parlayan mavi ve mor ' + [char]0x00E7 + 'er' + [char]0x00E7 + 'eveler; turkuaz ile pembe vurgu.') }
    Akis   = @{ T = ('Renk ge' + [char]0x00E7 + 'i' + [char]0x015F + 'i');       D = ('Mavi, mor ve macenta renklerin akt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' canl' + [char]0x0131 + ' zemin; koyu, yar' + [char]0x0131 + ' saydam kartlar.') }
    Uzay   = @{ T = 'Koyu mor';       D = ('' + [char]0x00C7 + 'ok koyu mor zemin, k' + [char]0x0131 + 'z' + [char]0x0131 + 'l' + [char]0x2013 + 'mor tonlar ve g' + [char]0x00FC + 'l rengi vurgu.') }
}

$script:LayoutInfo = [ordered]@{
    Ayrintili = @{ T = ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ''); D = ('Bug' + [char]0x00FC + 'nk' + [char]0x00FC + ' d' + [char]0x00FC + 'zen: simge ve yaz' + [char]0x0131 + 'l' + [char]0x0131 + ' sol men' + [char]0x00FC + ', i' + [char]0x015F + 'lem g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' ile komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'k. Her ' + [char]0x015F + 'ey bir arada.') }
    Kompakt   = @{ T = 'Kompakt';   D = ('Dar simge men' + [char]0x00FC + 's' + [char]0x00FC + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k ve komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' kapal' + [char]0x0131 + ', sayfaya en geni' + [char]0x015F + ' alan.') }
    Sade      = @{ T = 'Sade';      D = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r men' + [char]0x00FC + ' gruplar' + [char]0x0131 + ' ve a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r kartlar; g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k, komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ve animasyonlar kapal' + [char]0x0131 + '. Az kalabal' + [char]0x0131 + 'k.') }
    Hacker    = @{ T = 'Terminal';    D = ('Terminal d' + [char]0x00FC + 'zeni: yaz' + [char]0x0131 + 'l' + [char]0x0131 + ' men' + [char]0x00FC + ', hep a' + [char]0x00E7 + '' + [char]0x0131 + 'k komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ve g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k, tek aral' + [char]0x0131 + 'kl' + [char]0x0131 + ' yaz' + [char]0x0131 + '.') }
}

$script:ZoomSteps = @(80, 90, 100, 110, 120, 130)

$script:LayoutName = 'Ayrintili'
$script:LayoutFail = 0
$script:RailMode = 'Icon'
$script:RailGroups = New-Object System.Collections.ArrayList
$script:RailGroupsOn = $false
$script:CardsOn = $false
$script:UiZoom = 1.0
$script:LogOpenWidth = 330
$script:TaglineOrig = ''

# ---------------- saf yardimcilar (ekrana dokunmaz; testlerde de kullanilir) ----------------

# Eski "Sade" tema Koyu'ya tasinir; bilinmeyen ad varsayilan tema (Acik) olur
# ---------------- tema: Sistem ayarini kullan ----------------
# ---------------- Tema: "Sistem ayarini kullan" (Windows'un acik/koyu uygulama ayarini izler) ----------------
# Ayarlarda Theme = 'Sistem' saklanir; etkin tema her an Windows'tan cozulur: yuksek karsitlik aciksa Yuksek, uygulamalar
# icin koyu kip seciliyse Koyu, acik kip ya da ayar yoksa Acik. Windows'ta kip degisince 3 sn icinde tema da degisir.
$script:SystemThemeInfo = @{
    T = ('Sistem ayar' + [char]0x0131 + 'n' + [char]0x0131 + ' kullan')
    D = ('Windows' + [char]0x2019 + 'un a' + [char]0x00E7 + '' + [char]0x0131 + 'k ya da koyu uygulama ayar' + [char]0x0131 + 'n' + [char]0x0131 + ' izler; Windows' + [char]0x2019 + 'ta de' + [char]0x011F + 'i' + [char]0x015F + 'tirdi' + [char]0x011F + 'inizde Multimizer da de' + [char]0x011F + 'i' + [char]0x015F + 'ir. Y' + [char]0x00FC + 'ksek kar' + [char]0x015F + '' + [char]0x0131 + 'tl' + [char]0x0131 + 'k a' + [char]0x00E7 + '' + [char]0x0131 + 'ksa y' + [char]0x00FC + 'ksek kar' + [char]0x015F + '' + [char]0x0131 + 'tl' + [char]0x0131 + 'k temas' + [char]0x0131 + ' kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'r.')
}
$script:SysThemeTimer = $null
$script:SysThemeErr = $false

function Get-SystemThemeKey {
    try { if (-not $script:SafeBoot -and [System.Windows.SystemParameters]::HighContrast) { return 'Yuksek' } } catch { }
    $v = 1
    try { $v = [int](Get-RegValue 'HKCU\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' 'AppsUseLightTheme' 1) } catch { $v = 1 }
    if ($v -eq 0) { return 'Koyu' }
    return 'Acik'
}

# Ayarlar listesinde secili gosterilecek deger: "Sistem" korunur, diger adlar tema anahtarina cevrilir
function ConvertTo-ThemeChoice([string]$Name) {
    if ([string]$Name -eq 'Sistem') { return 'Sistem' }
    return (ConvertTo-ThemeKey $Name)
}

# "Sistem ayarini kullan" seciliyken Windows'un kipi degistiyse temayi yeniden uygular
function Update-SystemTheme {
    if ([string]$script:Settings.Theme -ne 'Sistem') { return $false }
    $k = Get-SystemThemeKey
    if ($k -eq [string]$script:ThemeName) { return $false }
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: Windows kipi de' + [char]0x011F + 'i' + [char]0x015F + 'ti, tema ') + $k) } catch { }
    Set-AppTheme $k
    try { Update-StAppearanceText } catch { }
    return $true
}

function Start-SystemThemeWatch {
    if ($null -ne $script:SysThemeTimer) { return }
    $script:SysThemeTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:SysThemeTimer.Interval = [TimeSpan]::FromSeconds(3)
    $script:SysThemeTimer.Add_Tick({
        try { [void](Update-SystemTheme) }
        catch {
            if (-not $script:SysThemeErr) { $script:SysThemeErr = $true; Write-CrashLog (('Sistem temas' + [char]0x0131 + ': ') + $_.Exception.Message) }
        }
    })
    $script:SysThemeTimer.Start()
}

function ConvertTo-ThemeKey([string]$Name) {
    $t = [string]$Name
    if ($t -eq 'Sade') { return 'Koyu' }
    if ($t -eq 'Sistem') { return (Get-SystemThemeKey) }
    foreach ($k in @($script:Themes.Keys)) { if ([string]$k -eq $t) { return [string]$k } }
    return 'Acik'
}

function ConvertTo-LayoutKey([string]$Name) {
    $l = [string]$Name
    foreach ($k in @($script:LayoutInfo.Keys)) { if ([string]$k -eq $l) { return [string]$k } }
    return 'Sade'
}

function ConvertTo-ZoomPct($Value) {
    if ($null -eq $Value -or [string]$Value -eq '') { return 100 }
    $n = 100
    try { $n = [int]$Value } catch { return 100 }
    if ($n -le 0) { return 100 }
    if ($n -lt 70) { $n = 70 }
    if ($n -gt 150) { $n = 150 }
    return $n
}

function Get-NearestZoomStep([int]$Pct) {
    $best = 100
    $bd = 100000
    foreach ($z in $script:ZoomSteps) {
        $dd = [math]::Abs([int]$z - $Pct)
        if ($dd -lt $bd) { $bd = $dd; $best = [int]$z }
    }
    return $best
}

function Get-NextZoom([int]$Cur, [int]$Dir) {
    $steps = @($script:ZoomSteps)
    $i = [array]::IndexOf($steps, (Get-NearestZoomStep $Cur))
    if ($i -lt 0) { $i = 2 }
    $j = $i + $Dir
    if ($j -lt 0) { $j = 0 }
    if ($j -ge $steps.Count) { $j = $steps.Count - 1 }
    return [int]$steps[$j]
}

# WCAG goreli parlaklik ve karsitlik orani ("#RRGGBB" ya da "#AARRGGBB")
function Get-RelLuminance([string]$Hex) {
    $h = $Hex.TrimStart('#')
    if ($h.Length -eq 8) { $h = $h.Substring(2) }
    $ch = New-Object System.Collections.ArrayList
    foreach ($i in 0, 2, 4) {
        $v = [Convert]::ToInt32($h.Substring($i, 2), 16) / 255.0
        if ($v -le 0.03928) { [void]$ch.Add($v / 12.92) } else { [void]$ch.Add([math]::Pow((($v + 0.055) / 1.055), 2.4)) }
    }
    return (0.2126 * [double]$ch[0] + 0.7152 * [double]$ch[1] + 0.0722 * [double]$ch[2])
}

function Get-ContrastRatio([string]$A, [string]$B) {
    $la = Get-RelLuminance $A
    $lb = Get-RelLuminance $B
    if ($la -lt $lb) { $t = $la; $la = $lb; $lb = $t }
    return (($la + 0.05) / ($lb + 0.05))
}

# Yerlesimin baslangic ayarlari. Rail: Icon (simge + alt yazi) | Compact (yalniz simge) | Text (yan yana simge ve yazi)
function Get-LayoutDefaults([string]$Name) {
    $d = @{ Rail = 'Icon'; Groups = $false; Log = 330; Cmd = $true; CmdH = 160; Cards = $false; Mono = $false; Calm = $false; Sys = $true; Open = 330 }
    if ($Name -eq 'Kompakt') {
        $d.Rail = 'Compact'; $d.Log = 0; $d.Cmd = $false
    } elseif ($Name -eq 'Sade') {
        $d.Rail = 'Text'; $d.Groups = $true; $d.Log = 0; $d.Cmd = $false; $d.Cards = $true; $d.Calm = $true; $d.Sys = $false
    } elseif ($Name -eq 'Hacker') {
        $d.Rail = 'Text'; $d.Log = 360; $d.Open = 360; $d.CmdH = 200; $d.Mono = $true
    }
    return $d
}

function Get-RailWidth([string]$Mode) {
    if ($Mode -eq 'None') { return 0 }
    if ($Mode -eq 'Fly') { return 84 }
    if ($Mode -eq 'Compact') { return 54 }
    if ($Mode -eq 'Text') { return 200 }
    return 72
}

# ---------------- agac yardimcilari ----------------
function Test-StyleIs($El, [string]$Key) {
    try { return [object]::ReferenceEquals($El.Style, $script:Win.FindResource($Key)) } catch { return $false }
}

# ---------------- sol menu: bicim (simge / kompakt / yazili) ----------------
function Set-RailMode([string]$Mode) {
    $w = [double](Get-RailWidth $Mode)
    $grid = $ui.RailHost.Parent
    if (($grid -is [System.Windows.Controls.Grid]) -and $grid.ColumnDefinitions.Count -ge 1) {
        $grid.ColumnDefinitions[0].Width = New-Object System.Windows.GridLength -ArgumentList $w
    }
    if ($Mode -eq 'Compact') { $script:RailMax = 46; $script:RailMin = 38 }
    elseif ($Mode -eq 'Text') { $script:RailMax = 40; $script:RailMin = 34 }
    else { $script:RailMax = 56; $script:RailMin = 40 }
    $zero = New-Object System.Windows.Thickness -ArgumentList 0
    foreach ($k in @($script:PageTitles.Keys)) {
        $rb = $ui['Rail_' + $k]
        if ($null -eq $rb) { continue }
        $sp = $rb.Content
        if (($sp -isnot [System.Windows.Controls.StackPanel]) -or $sp.Children.Count -lt 2) { continue }
        $ico = $sp.Children[0]
        $lbl = $sp.Children[1]
        if ($Mode -eq 'Text') {
            $sp.Orientation = [System.Windows.Controls.Orientation]::Horizontal
            $sp.Width = $w - 28
            $ico.Margin = New-Object System.Windows.Thickness -ArgumentList 10, 0, 12, 0
            $ico.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
            $lbl.Visibility = $script:VisOn
            $lbl.FontSize = 12.5
            $lbl.Margin = $zero
            $lbl.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
            $lbl.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        } elseif ($Mode -eq 'Compact') {
            $sp.Orientation = [System.Windows.Controls.Orientation]::Vertical
            $sp.Width = [double]::NaN
            $ico.Margin = $zero
            $lbl.Visibility = $script:VisOff
        } else {
            $sp.Orientation = [System.Windows.Controls.Orientation]::Vertical
            $sp.Width = [double]::NaN
            $ico.Margin = $zero
            $lbl.Visibility = $script:VisOn
            $lbl.FontSize = 9.5
            $lbl.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 3, 0, 0
            $lbl.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        }
    }
    $script:RailMode = $Mode
    $script:RailH = 0
}

# ---------------- sol menu: acilir gruplar (Sade yerlesim) ----------------
function Set-GroupOpen($G, [bool]$Open) {
    $G.Open = $Open
    Set-Visible $G.Panel $Open
    $mark = [string][char]0x25B8
    if ($Open) { $mark = [string][char]0x25BE }
    $G.Label.Text = (Tr $(($mark + ' ' + [string]$G.Title)))
}

function Switch-RailGroup([string]$Key) {
    foreach ($g in @($script:RailGroups)) {
        if ([string]$g.Key -eq $Key) { if ($g.Peek -eq $true -and [bool]$g.Open) { $g.Peek = $false } else { Set-GroupOpen $g (-not [bool]$g.Open) } }
    }
    $script:RailH = 0
    try { Update-RailDensity } catch { }
}

function Initialize-RailGroups {
    if ($script:RailGroups.Count -gt 0) { return }
    $host_ = $ui.RailScroll.Content
    if ($host_ -isnot [System.Windows.Controls.StackPanel]) { return }
    $defs = @(
        @{ K = 'ana'; T = 'ANA'; P = @('panel', 'solve') },
        @{ K = 'hiz'; T = ('HIZ VE TEM' + [char]0x0130 + 'ZL' + [char]0x0130 + 'K'); P = @('optimize', 'services', 'apps', 'clean', 'power', 'gaming', 'smart') },
        @{ K = 'guv'; T = ('G' + [char]0x00DC + 'VENL' + [char]0x0130 + 'K VE A' + [char]0x011E + ''); P = @('security', 'updates', 'network', 'backup') },
        @{ K = 'yon'; T = ('Y' + [char]0x00D6 + 'NET' + [char]0x0130 + 'M'); P = @('company', 'tools') }
    )
    $made = New-Object System.Collections.ArrayList
    foreach ($d in $defs) {
        $items = New-Object System.Collections.ArrayList
        foreach ($pk in $d.P) {
            $rb = $ui['Rail_' + $pk]
            if ($null -ne $rb -and [object]::ReferenceEquals($rb.Parent, $host_)) { [void]$items.Add($rb) }
        }
        if ($items.Count -gt 0) { [void]$made.Add(@{ Def = $d; Items = $items }) }
    }
    if ($made.Count -eq 0) { return }
    $host_.Children.Clear()
    foreach ($m in $made) {
        $d = $m.Def
        $panel = New-Object System.Windows.Controls.StackPanel
        $panel.Tag = ('rg:' + [string]$d.K)
        $hdr = New-Object System.Windows.Controls.Border
        $hdr.Background = [System.Windows.Media.Brushes]::Transparent
        $hdr.Cursor = [System.Windows.Input.Cursors]::Hand
        $hdr.Padding = New-Object System.Windows.Thickness -ArgumentList 16, 10, 8, 4
        $hdr.Tag = [string]$d.K
        $hdr.Visibility = $script:VisOff
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.FontSize = 10.5
        $tb.FontWeight = [System.Windows.FontWeights]::SemiBold
        $tb.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'BrFaint')
        $hdr.Child = $tb
        $hdr.Add_MouseLeftButtonUp({ param($s, $e) Invoke-Safe { Switch-RailGroup ([string]$s.Tag) } ('Men' + [char]0x00FC + '') })
        $hdr.Add_MouseEnter($script:H_RailHdrEnter)
        [void]$host_.Children.Add($hdr)
        [void]$host_.Children.Add($panel)
        foreach ($rb in $m.Items) { [void]$panel.Children.Add($rb) }
        $g = @{ Key = [string]$d.K; Title = [string]$d.T; Pages = @($d.P); Header = $hdr; Label = $tb; Panel = $panel; Open = $true; Shown = 0 }
        Set-GroupOpen $g $true
        [void]$script:RailGroups.Add($g)
    }
}

# Basliklar yalnizca acilir grup kipinde ve grupta gorunen dugme varken gorunur
function Refresh-RailGroups {
    foreach ($g in @($script:RailGroups)) {
        $n = 0
        foreach ($pk in $g.Pages) {
            $rb = $ui['Rail_' + $pk]
            if ($null -ne $rb -and $rb.Visibility -eq $script:VisOn) { $n++ }
        }
        $g.Shown = $n
        Set-Visible $g.Header (($script:RailGroupsOn -eq $true) -and ($g.Pages.Count -gt 1) -and ($n -gt 0))
    }
}

# Sayfaya gidilince sayfanin grubu acilir (digerleri oldugu gibi kalir)
function Sync-RailGroups([string]$Page) {
    if ($script:RailGroupsOn -ne $true) { return }
    foreach ($g in @($script:RailGroups)) {
        if (($g.Pages -contains $Page) -and (-not [bool]$g.Open)) { Set-GroupOpen $g $true }
    }
    $script:RailH = 0
    try { Update-RailDensity } catch { }
}

function Set-RailGroupsMode([bool]$On) {
    if ($On -and $script:RailGroups.Count -eq 0) { Initialize-RailGroups }
    if ($script:RailGroups.Count -eq 0) { $script:RailGroupsOn = $false; return }
    $script:RailGroupsOn = $On
    foreach ($g in @($script:RailGroups)) {
        if ($On) { Set-GroupOpen $g ($g.Pages -contains [string]$script:UiState.Page) } else { Set-GroupOpen $g $true }
    }
    Refresh-RailGroups
}

# Dugme, gorunur ve (varsa) acik bir grubun icinde mi?
function Test-RailShown($Rb) {
    if ($null -eq $Rb) { return $false }
    if ($Rb.Visibility -ne $script:VisOn) { return $false }
    $p = $Rb.Parent
    if ($null -ne $p -and $null -ne $p.Tag -and ([string]$p.Tag).StartsWith('rg:') -and $p.Visibility -ne $script:VisOn) { return $false }
    return $true
}

# ---------------- acilir kartlar (Sade yerlesim) ----------------
# Kart = Style "Card" olan Border; icinde adsiz bir StackPanel ve ilk cocugu baslik olanlar. Baslik: TxtCardTitle yazisi ya da ilk cocugu
# TxtCardTitle olan bir Grid (baslik satirinda dugmeler olabilir). Baslik satirina tiklaninca kartin govdesi acilip kapanir.
# Cocuklarin kendi Visibility degerlerine dokunulmaz: govde tek bir kapta toplanir ve o kap acilip kapatilir.
# Adli StackPanel (sayfanin kendi liste kabi) ve satir sablonlari donusturulmez.
function Test-CardTitleEl($El) {
    if ($El -is [System.Windows.Controls.TextBlock]) { return (Test-StyleIs $El 'TxtCardTitle') }
    if (($El -is [System.Windows.Controls.Grid]) -and [string]$El.Tag -ne 'cardhdr' -and $El.Children.Count -ge 1) {
        $f = $El.Children[0]
        return (($f -is [System.Windows.Controls.TextBlock]) -and (Test-StyleIs $f 'TxtCardTitle'))
    }
    return $false
}

function Find-CardBorders($El, $List, [int]$Depth) {
    if ($null -eq $El -or $Depth -gt 14) { return }
    if (($El -is [System.Windows.Controls.Border]) -and (Test-StyleIs $El 'Card')) {
        $sp = $El.Child
        if (($sp -is [System.Windows.Controls.StackPanel]) -and [string]::IsNullOrEmpty([string]$sp.Name) -and $sp.Children.Count -ge 2) {
            $f = $sp.Children[0]
            $isHdr = (($f -is [System.Windows.Controls.Grid]) -and ([string]$f.Tag -eq 'cardhdr'))
            if ($isHdr -or (Test-CardTitleEl $f)) { [void]$List.Add($El) }
        }
    }
    foreach ($c in [System.Windows.LogicalTreeHelper]::GetChildren($El)) {
        if ($c -is [System.Windows.FrameworkElement]) { Find-CardBorders $c $List ($Depth + 1) }
    }
}

function Set-CardOpen($Card, [bool]$Open) {
    $sp = $Card.Child
    $hdr = $sp.Children[0]
    $body = $sp.Children[1]
    Set-Visible $body $Open
    $mark = [string][char]0x25B8
    if ($Open) { $mark = [string][char]0x25BE }
    $hdr.Children[1].Text = (Tr $($mark))
}

function Invoke-CardHeaderClick($Hdr, $E) {
    try {
        if ($script:CardsOn -ne $true) { return }
        $sp = $Hdr.Parent
        $card = $sp.Parent
        $body = $sp.Children[1]
        Set-CardOpen $card ($body.Visibility -ne $script:VisOn)
        $E.Handled = $true
    } catch { }
}

function Convert-CardToExpander($Card) {
    $sp = $Card.Child
    $kids = New-Object System.Collections.ArrayList
    foreach ($k in $sp.Children) { [void]$kids.Add($k) }
    $title = $kids[0]
    $sp.Children.Clear()
    $hdr = New-Object System.Windows.Controls.Grid
    $hdr.Tag = 'cardhdr'
    $hdr.Background = [System.Windows.Media.Brushes]::Transparent
    $c0 = New-Object System.Windows.Controls.ColumnDefinition
    $c0.Width = New-Object System.Windows.GridLength -ArgumentList 1, ([System.Windows.GridUnitType]::Star)
    $c1 = New-Object System.Windows.Controls.ColumnDefinition
    $c1.Width = [System.Windows.GridLength]::Auto
    [void]$hdr.ColumnDefinitions.Add($c0)
    [void]$hdr.ColumnDefinitions.Add($c1)
    [System.Windows.Controls.Grid]::SetColumn($title, 0)
    [void]$hdr.Children.Add($title)
    $chev = New-Object System.Windows.Controls.TextBlock
    $chev.Text = (Tr $([string][char]0x25BE))
    $chev.FontSize = 13
    $chev.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $chev.Margin = New-Object System.Windows.Thickness -ArgumentList 8, 0, 2, 0
    $chev.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'BrDim')
    [System.Windows.Controls.Grid]::SetColumn($chev, 1)
    [void]$hdr.Children.Add($chev)
    $body = New-Object System.Windows.Controls.StackPanel
    $body.Tag = 'cardbody'
    for ($i = 1; $i -lt $kids.Count; $i++) { [void]$body.Children.Add($kids[$i]) }
    [void]$sp.Children.Add($hdr)
    [void]$sp.Children.Add($body)
    $hdr.Add_MouseLeftButtonUp({ param($s, $e) Invoke-CardHeaderClick $s $e })
}

# Kac kart acik baslasin (Sade yerlesim): Durum panosunda ve Ayarlar'da ilk ikisi, diger sayfalarda ilki
function Get-CardOpenCount([string]$PageKey) {
    if ($PageKey -eq 'panel' -or $PageKey -eq 'settings') { return 2 }
    return 1
}

# Sayfadaki kartlari acilir yapar (On) ya da duz haline getirir. Acik baslayan kart sayisi OpenN.
function Update-PageCards($Root, [bool]$On, [int]$OpenN = 1) {
    if ($null -eq $Root) { return }
    $list = New-Object System.Collections.ArrayList
    Find-CardBorders $Root $list 0
    $idx = 0
    foreach ($c in $list) {
        $sp = $c.Child
        $f = $sp.Children[0]
        $done = (($f -is [System.Windows.Controls.Grid]) -and ([string]$f.Tag -eq 'cardhdr'))
        if (-not $done) {
            if (-not $On) { continue }
            Convert-CardToExpander $c
        }
        $hdr = $sp.Children[0]
        if ($On) {
            Set-Visible $hdr.Children[1] $true
            $hdr.Cursor = [System.Windows.Input.Cursors]::Hand
            Set-CardOpen $c ($idx -lt $OpenN)
        } else {
            Set-Visible $hdr.Children[1] $false
            $hdr.Cursor = [System.Windows.Input.Cursors]::Arrow
            Set-Visible $sp.Children[1] $true
        }
        $idx++
    }
}

function Update-AllPageCards([bool]$On) {
    $script:CardsOn = $On
    foreach ($k in @($script:Pages.Keys)) {
        try { Update-PageCards $script:Pages[$k] $On (Get-CardOpenCount ([string]$k)) } catch { Write-CrashLog ('Kart: ' + $k + ' ' + $_.Exception.Message) }
    }
}

# ---------------- yerlesim uygulama ----------------
function Set-LayoutTexts([string]$Name) {
    if ($null -ne $ui.TxtTagline) {
        if ($script:TaglineOrig -eq '') { $script:TaglineOrig = [string]$ui.TxtTagline.Text }
        if ($Name -eq 'Hacker') { $ui.TxtTagline.Text = (Tr $('multimizer@pc:~$ _')) } else { $ui.TxtTagline.Text = (Tr $($script:TaglineOrig)) }
    }
}

function Set-AppLayout([string]$Name) {
    $Name = ConvertTo-LayoutKey $Name
    $d = Get-LayoutDefaults $Name
    $fail = 0
    try { Set-RailMode ([string]$d.Rail) } catch { $fail++; Write-WhLog (('Yerle' + [char]0x015F + 'im (men' + [char]0x00FC + '): ') + $_.Exception.Message) 'WARN' }
    try { Set-RailGroupsMode ([bool]$d.Groups) } catch { $fail++; Write-WhLog (('Yerle' + [char]0x015F + 'im (gruplar): ') + $_.Exception.Message) 'WARN' }
    try {
        $script:LogOpenWidth = [double]$d.Open
        $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList ([double]$d.Log)
        Set-Visible $ui.CmdPanel ([bool]$d.Cmd)
        $ui.CmdPanel.Height = [double]$d.CmdH
        if (-not [bool]$d.Cmd) { $ui.CmdPop.IsOpen = $false }
    } catch { $fail++; Write-WhLog (('Yerle' + [char]0x015F + 'im (paneller): ') + $_.Exception.Message) 'WARN' }
    try {
        if ([bool]$d.Mono) { $script:Win.FontFamily = New-Object System.Windows.Media.FontFamily -ArgumentList 'Cascadia Mono, Consolas, Courier New' }
        else { $script:Win.FontFamily = New-Object System.Windows.Media.FontFamily -ArgumentList 'Segoe UI' }
    } catch { $fail++; Write-WhLog (('Yerle' + [char]0x015F + 'im (yaz' + [char]0x0131 + ' tipi): ') + $_.Exception.Message) 'WARN' }
    try { Set-LayoutTexts $Name; Set-Visible $ui.TxtSys ([bool]$d.Sys) } catch { $fail++; Write-WhLog (('Yerle' + [char]0x015F + 'im (metinler): ') + $_.Exception.Message) 'WARN' }
    try { Update-AllPageCards ([bool]$d.Cards) } catch { $fail++; Write-WhLog (('Yerle' + [char]0x015F + 'im (kartlar): ') + $_.Exception.Message) 'WARN' }
    $script:LayoutName = $Name
    $script:LayoutFail = $fail
    try { Update-ReduceMotion } catch { }
    try { if ([string]$script:DesignKey -ne 'Klasik') { Apply-DesignShell } } catch { Write-CrashLog ('Yerlesim (tasarim): ' + $_.Exception.Message) }
    try { $script:RailH = 0; Update-RailDensity } catch { }
    try { Set-TouchTargets $Name } catch { Write-CrashLog ('Dokunma hedefleri: ' + $_.Exception.Message) }
    # Pencere dar ya da kisaysa gunluk ve komut satiri kendiliginden kapanir (Duyarli yerlesim bolumu); varsayilanlar yeni yerlesime gore yeniden degerlendirilir
    try { Reset-Responsive } catch { Write-CrashLog (('Duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im (yerle' + [char]0x015F + 'im): ') + $_.Exception.Message) }
}

# Acilista kayitli yerlesim ve yakinlastirma uygulanir; bir sey olursa varsayilana donulur
function Initialize-Layout {
    $l = ConvertTo-LayoutKey ([string]$script:Settings.Layout)
    $z = ConvertTo-ZoomPct $script:Settings.Zoom
    $ok = $true
    try { Set-AppLayout $l; if ([int]$script:LayoutFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Yerle' + [char]0x015F + 'im uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok) {
        try { Set-AppLayout 'Ayrintili' } catch { }
        Set-SettingsKeys @{ Layout = 'Ayrintili' }
    }
    try { Set-UiZoom $z $false } catch { Write-CrashLog (('Yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message); try { Set-UiZoom 100 $false } catch { } }
}

# ---------------- yakinlastirma (sayfa govdesi olceklenir; baslik ve durum cubugu sabit kalir) ----------------
function Set-UiZoom([int]$Pct, [bool]$Save = $true) {
    $Pct = ConvertTo-ZoomPct $Pct
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + $Pct) } catch { }
    $script:UiZoom = [double]$Pct / 100.0
    if ($Pct -eq 100) { $ui.BodyGrid.LayoutTransform = [System.Windows.Media.Transform]::Identity }
    else { $ui.BodyGrid.LayoutTransform = New-Object System.Windows.Media.ScaleTransform -ArgumentList $script:UiZoom, $script:UiZoom }
    if ($Save) { Set-SettingsKeys @{ Zoom = $Pct } }
    try { $script:RailH = 0; Update-RailDensity } catch { }
    try { Update-Responsive } catch { Write-CrashLog (('Duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im (yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma): ') + $_.Exception.Message) }
}

function Step-UiZoom([int]$Dir) {
    $cur = ConvertTo-ZoomPct $script:Settings.Zoom
    $n = Get-NextZoom $cur $Dir
    if ($n -eq (Get-NearestZoomStep $cur) -and $n -eq $cur) { return }
    Set-UiZoom $n $true
    try { if ($script:Pages.ContainsKey('settings')) { Load-StLook } } catch { }
    Show-Toast (('Yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma: %') + [string]$n) 'info'
}

# ---------------- Ayarlar sayfasi: secimler ----------------
function Select-Theme([string]$Name) {
    $choice = ConvertTo-ThemeChoice $Name
    $Name = ConvertTo-ThemeKey $choice
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: tema ') + $Name) } catch { }
    $script:Settings.Theme = $choice
    $ok = $true
    try { Set-AppTheme $Name; if ([int]$script:ThemeFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Tema uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok) {
        try { Set-AppTheme 'Neon' } catch { }
        $script:Settings.Theme = 'Neon'
        try { Load-StLook } catch { }
        Show-Toast ('Tema tam uygulanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'venli g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'me d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn'
    }
    return $ok
}

function Select-Layout([string]$Name) {
    $Name = ConvertTo-LayoutKey $Name
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: yerle' + [char]0x015F + 'im ') + $Name) } catch { }
    $script:Settings.Layout = $Name
    $ok = $true
    try { Set-AppLayout $Name; if ([int]$script:LayoutFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Yerle' + [char]0x015F + 'im uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok) {
        try { Set-AppLayout 'Ayrintili' } catch { }
        $script:Settings.Layout = 'Ayrintili'
        try { Load-StLook } catch { }
        Show-Toast ('Yerle' + [char]0x015F + 'im tam uygulanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'venli yerle' + [char]0x015F + 'ime d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn'
    }
    return $ok
}

# ---------------- acilir liste yardimcilari ----------------
# Her acilir listenin ogesi bir hashtable'dir: Key (ayarda saklanan ad), Name (ekranda gorunen ad), C1..C4 (tema onizleme renkleri).
# Oge sablonu bu alanlara {Binding [Name]} gibi baglanir (bkz. ComboChoice / ComboTheme stilleri).
function New-Choice([string]$Key, [string]$Name, $Colors = $null) {
    $c = @{ Key = $Key; Name = (Tr $Name); C1 = '#00000000'; C2 = '#00000000'; C3 = '#00000000'; C4 = '#00000000' }
    $i = 1
    foreach ($h in @($Colors)) {
        if ($i -le 4 -and $null -ne $h) { $c[('C' + [string]$i)] = [string]$h }
        $i++
    }
    return $c
}

# Programla yapilan secimler Ayarlar kaydini tetiklemesin diye StLoading bayragi gecici olarak kaldirilir
function Set-ComboChoices($Combo, $Choices) {
    if ($null -eq $Combo) { return }
    $prev = $script:StLoading
    $script:StLoading = $true
    try {
        $Combo.Items.Clear()
        foreach ($c in @($Choices)) { [void]$Combo.Items.Add($c) }
        if ($script:LangOn) { Fit-ComboWidth $Combo }
    } finally { $script:StLoading = $prev }
}

function Select-ComboKey($Combo, [string]$Key) {
    if ($null -eq $Combo) { return $false }
    $prev = $script:StLoading
    $script:StLoading = $true
    $found = $false
    try {
        $i = 0
        foreach ($it in $Combo.Items) {
            if ([string]$it['Key'] -eq $Key) { $Combo.SelectedIndex = $i; $found = $true; break }
            $i++
        }
        if (-not $found) { $Combo.SelectedIndex = -1 }
    } finally { $script:StLoading = $prev }
    return $found
}

function Get-ComboKey($Combo) {
    if ($null -eq $Combo) { return '' }
    $it = $Combo.SelectedItem
    if ($null -eq $it) { return '' }
    try { return [string]$it['Key'] } catch { return '' }
}

# Ustteki rengin (#RRGGBB ya da #AARRGGBB) alt rengin (#RRGGBB) uzerine karistirilmis opak karsiligi (#RRGGBB)
function Merge-HexOver([string]$Top, [string]$Base) {
    $t = $Top.TrimStart('#')
    $b = $Base.TrimStart('#')
    if ($b.Length -eq 8) { $b = $b.Substring(2) }
    $a = 255
    if ($t.Length -eq 8) { $a = [Convert]::ToInt32($t.Substring(0, 2), 16); $t = $t.Substring(2) }
    if ($t.Length -ne 6 -or $b.Length -ne 6) { return ('#' + $t) }
    $out = '#'
    foreach ($k in 0, 2, 4) {
        $f = [Convert]::ToInt32($t.Substring($k, 2), 16)
        $g = [Convert]::ToInt32($b.Substring($k, 2), 16)
        $v = [int][math]::Floor(($f * $a + $g * (255 - $a)) / 255.0 + 0.5)
        $out = $out + $v.ToString('X2')
    }
    return $out
}

# Tema onizlemesi: zemin, yuzey, vurgu ve ikinci vurgu rengi (#RRGGBB). Zemin, arka plan gecisinin orta rengidir.
function Get-ThemeSwatch([string]$Key) {
    $k = ConvertTo-ThemeKey $Key
    $tbl = $script:Themes[$k]
    $bg = [string]$tbl.BrBg
    if ($script:ThemeGrads.ContainsKey($k)) {
        $g = @($script:ThemeGrads[$k])
        if ($g.Count -ge 2) { $bg = [string]$g[1] }
    }
    $bg = Merge-HexOver $bg '#000000'
    return @($bg, (Merge-HexOver ([string]$tbl.BrCard) $bg), (Merge-HexOver ([string]$tbl.BrAccent) $bg), (Merge-HexOver ([string]$tbl.BrAccent2) $bg))
}

# ---------------- hazir gorunumler: tema + yerlesim + tasarim + saydamlik + yakinlastirma birlikte ----------------
$script:LookPresetNames = [ordered]@{
    Varsayilan = ('Varsay' + [char]0x0131 + 'lan (beyaz ve sade)'); KoyuNeon = 'Koyu neon'; KompaktKoyu = 'Kompakt koyu'; Hacker = 'Terminal'
    Atolye = ('Kartl' + [char]0x0131 + ''); Sifir = 'Minimal'; Morpheus = ('A' + [char]0x011F + ' konsolu'); Komuta = ('G' + [char]0x00F6 + 'sterge paneli')
}

function Get-LookPreset([string]$Key) {
    $p = @{ Theme = 'Acik'; Layout = 'Sade'; Zoom = 100; Design = 'Klasik'; Backdrop = 'Yok'; Opacity = 100; HomeMode = '' }
    if ($Key -eq 'KoyuNeon') { $p.Theme = 'Neon'; $p.Layout = 'Ayrintili' }
    elseif ($Key -eq 'KompaktKoyu') { $p.Theme = 'Koyu'; $p.Layout = 'Kompakt' }
    elseif ($Key -eq 'Hacker') { $p.Theme = 'Hacker'; $p.Layout = 'Hacker' }
    elseif (@('Atolye', 'Sifir', 'Morpheus', 'Komuta') -contains $Key) {
        $d = Get-DesignSpec $Key
        $p.Theme = [string]$d.Theme; $p.Layout = [string]$d.Layout; $p.Design = [string]$d.Key
        $g = Get-PresetGlass $Key
        $p.Backdrop = [string]$g.Backdrop; $p.Opacity = [int]$g.Opacity
        $p.HomeMode = 'Pano'
    }
    return $p
}

# Gecerli ayarlar hazir gorunumlerden biriyle ayniysa onun anahtari, degilse 'Ozel' doner
function Get-MatchingLookPreset($St) {
    if (Test-DesignOverridden $St) { return 'Ozel' }
    $t = ConvertTo-ThemeChoice ([string](Get-BoardField $St 'Theme'))
    $l = ConvertTo-LayoutKey ([string](Get-BoardField $St 'Layout'))
    $d = ConvertTo-DesignKey ([string](Get-BoardField $St 'Design'))
    $z = ConvertTo-ZoomPct (Get-BoardField $St 'Zoom')
    $b = ConvertTo-GlassKey ([string](Get-BoardField $St 'Backdrop'))
    $o = ConvertTo-GlassOpacity (Get-BoardField $St 'WinOpacity')
    $h = ConvertTo-HomeKey (Get-BoardField $St 'HomeMode')
    foreach ($k in @($script:LookPresetNames.Keys)) {
        $p = Get-LookPreset ([string]$k)
        if ([string]$p.Theme -ne $t -or [string]$p.Layout -ne $l -or [string]$p.Design -ne $d -or [int]$p.Zoom -ne $z) { continue }
        if ([string]$p.HomeMode -ne '' -and [string]$p.HomeMode -ne $h) { continue }
        if ([string]$p.Backdrop -ne $b) { continue }
        if ($b -ne 'Yok' -and [int]$p.Opacity -ne $o) { continue }
        return [string]$k
    }
    return 'Ozel'
}

function Apply-LookPreset([string]$Key) {
    $p = Get-LookPreset $Key
    [void](Select-Theme ([string]$p.Theme))
    [void](Select-Layout ([string]$p.Layout))
    [void](Select-Design ([string]$p.Design))
    if ([string]$p.HomeMode -ne '') { [void](Select-HomeMode ([string]$p.HomeMode)) }
    [void](Select-Glass ([string]$p.Backdrop) $p.Opacity)
    try { Set-UiZoom ([int]$p.Zoom) $false } catch { }
    $s = $script:Settings
    $s.Zoom = [int]$p.Zoom
    Save-Settings $s
    Update-ReduceMotion
    Sync-StLookControls
}

function Update-StAppearanceText {
    try {
        $t = ConvertTo-ThemeKey ([string]$script:Settings.Theme)
        $l = ConvertTo-LayoutKey ([string]$script:Settings.Layout)
        if ([string]$script:Settings.Theme -eq 'Sistem') { $ui.st_ThDesc.Text = (Tr $(([string]$script:SystemThemeInfo.T + ': ' + [string]$script:SystemThemeInfo.D))) + ' ' + (Format-Tr ('' + [char]0x015E + 'u an: {0}.') (Tr ([string]$script:ThemeInfo[$t].T))) }
        else { $ui.st_ThDesc.Text = (Tr $(([string]$script:ThemeInfo[$t].T + ': ' + [string]$script:ThemeInfo[$t].D))) }
        $ui.st_LyDesc.Text = (Tr $(([string]$script:LayoutInfo[$l].T + ': ' + [string]$script:LayoutInfo[$l].D)))
    } catch { }
}

# Ayarlar sayfasindaki acilir listelerin icerigi (bir kez, sayfa kurulurken)
function Initialize-StLookChoices {
    $th = New-Object System.Collections.ArrayList
    [void]$th.Add((New-Choice 'Sistem' ([string]$script:SystemThemeInfo.T) (Get-ThemeSwatch (Get-SystemThemeKey))))
    foreach ($k in @($script:Themes.Keys)) { [void]$th.Add((New-Choice ([string]$k) ([string]$script:ThemeInfo[$k].T) (Get-ThemeSwatch ([string]$k)))) }
    Set-ComboChoices $ui.st_ThemeSel $th.ToArray()
    $ly = New-Object System.Collections.ArrayList
    foreach ($k in @($script:LayoutInfo.Keys)) { [void]$ly.Add((New-Choice ([string]$k) ([string]$script:LayoutInfo[$k].T))) }
    Set-ComboChoices $ui.st_LayoutSel $ly.ToArray()
    $zm = New-Object System.Collections.ArrayList
    foreach ($z in $script:ZoomSteps) { [void]$zm.Add((New-Choice ([string]$z) (Format-Percent $z))) }
    Set-ComboChoices $ui.st_ZoomSel $zm.ToArray()
    $tc = New-Object System.Collections.ArrayList
    [void]$tc.Add((New-Choice 'Auto' 'Otomatik'))
    [void]$tc.Add((New-Choice 'Normal' 'Normal'))
    [void]$tc.Add((New-Choice 'Large' ('B' + [char]0x00FC + 'y' + [char]0x00FC + 'k')))
    Set-ComboChoices $ui.st_TouchSel $tc.ToArray()
    $pr = New-Object System.Collections.ArrayList
    [void]$pr.Add((New-Choice 'Ozel' ('' + [char]0x00D6 + 'zel (kendi birle' + [char]0x015F + 'iminiz)')))
    foreach ($k in @($script:LookPresetNames.Keys)) { [void]$pr.Add((New-Choice ([string]$k) ([string]$script:LookPresetNames[$k]))) }
    Set-ComboChoices $ui.st_LookSel $pr.ToArray()
}

# Ayarlar sayfasindaki gorunum denetimlerini kayitli ayara gore isaretler (secim olayi kayit yapmaz)
function Load-StLook {
    $t = ConvertTo-ThemeChoice ([string]$script:Settings.Theme)
    $l = ConvertTo-LayoutKey ([string]$script:Settings.Layout)
    $z = Get-NearestZoomStep (ConvertTo-ZoomPct $script:Settings.Zoom)
    [void](Select-ComboKey $ui.st_ThemeSel $t)
    [void](Select-ComboKey $ui.st_LayoutSel $l)
    [void](Select-ComboKey $ui.st_ZoomSel ([string]$z))
    [void](Select-ComboKey $ui.st_TouchSel (ConvertTo-TouchKey ([string]$script:Settings.TouchTargets)))
    Sync-StPresetBox
    $ui.st_ReduceMotion.IsChecked = ($script:Settings.ReduceMotion -eq $true)
    $ui.st_Smooth.IsChecked = ($script:Settings.SmoothScroll -ne $false)
    $ui.st_ToTop.IsChecked = ($script:Settings.ToTopButton -ne $false)
    $ui.st_FullDesc.IsChecked = ($script:Settings.FullDesc -eq $true)
    $ui.st_FocusRing.IsChecked = ($script:Settings.FocusRing -ne $false)
    Update-StAppearanceText
}

# Hazir gorunum listesi gecerli birlesimi gosterir (hicbiriyle eslesmiyorsa "Ozel")
function Sync-StPresetBox {
    [void](Select-ComboKey $ui.st_LookSel (Get-MatchingLookPreset $script:Settings))
}

# Gorunumle ilgili tum denetimleri (tema, tasarim, saydamlik...) ayarlara gore yeniler
function Sync-StLookControls {
    foreach ($fn in @('Load-StLook', 'Load-StDesign', 'Load-StGlass')) {
        try { & $fn } catch { Write-CrashLog ('Ayar (' + $fn + '): ' + $_.Exception.Message) }
    }
    try { Sync-StPresetBox } catch { }
}

# Denetimlerdeki secimi uygular ve ayara yazar (kaydetmeyi cagiran yapar)
function Save-StLook {
    $s = $script:Settings
    $t = Get-ComboKey $ui.st_ThemeSel
    if ($t -ne '' -and (ConvertTo-ThemeChoice $t) -ne (ConvertTo-ThemeChoice ([string]$s.Theme))) { [void](Select-Theme $t) }
    $l = Get-ComboKey $ui.st_LayoutSel
    if ($l -ne '' -and (ConvertTo-LayoutKey $l) -ne (ConvertTo-LayoutKey ([string]$s.Layout))) { [void](Select-Layout $l) }
    $z = Get-ComboKey $ui.st_ZoomSel
    if ($z -ne '' -and (ConvertTo-ZoomPct $z) -ne (ConvertTo-ZoomPct $s.Zoom)) {
        Set-UiZoom ([int]$z) $false
        $s.Zoom = [int]$z
    }
    $tk = Get-ComboKey $ui.st_TouchSel
    if ($tk -ne '' -and (ConvertTo-TouchKey $tk) -ne (ConvertTo-TouchKey ([string]$s.TouchTargets))) {
        $s.TouchTargets = ConvertTo-TouchKey $tk
        Set-TouchTargets
    }
    $s.ReduceMotion = ($ui.st_ReduceMotion.IsChecked -eq $true)
    $s.SmoothScroll = ($ui.st_Smooth.IsChecked -eq $true)
    $s.ToTopButton = ($ui.st_ToTop.IsChecked -eq $true)
    $s.FullDesc = ($ui.st_FullDesc.IsChecked -eq $true)
    $s.FocusRing = ($ui.st_FocusRing.IsChecked -eq $true)
    Update-StAppearanceText
}


# ---------------- Kaydirma, klavye ve kisayollar ----------------
# ==================================================================
#  KAYDIRMA, KLAVYE VE KISAYOLLAR
#  - Fare tekerlegi (dokunmatik yuzey dahil) her yerde kaydirir; ic ice listeler sinira gelince sayfa kaydirilir
#  - Klavye: PageUp / PageDown, Home / End, bosluk, ^ / v (sayfaya tikladiktan sonra), Ctrl+Home basa
#  - Dokunmatik ekran: parmakla surukleme (PanningMode)
#  - Basa don dugmesi, Ctrl+tekerlek ve Ctrl+(+ / - / 0) yakinlastirma, Ctrl+Tab sayfa degistirme
#  - Klavye odak cercevesi: Tab ile gezerken hangi dugmede oldugunuz gorunur
#  Hicbiri sistem ayarina dokunmaz. Her isleyici hata yakalar; hata olursa varsayilan WPF davranisi surer.
# ==================================================================

$script:ScrollReady = $false
$script:SmoothMap = @{}
$script:SmoothTimer = $null
$script:ToTopBtn = $null
$script:PageSv = @{}
$script:KbNav = $false
$script:FocusRingBox = $null
$script:FocusRingHost = $null
$script:ZoomStepAt = [datetime]::MinValue
$script:ScrollErrAt = [datetime]::MinValue

# ---------------- saf yardimcilar (ekrana dokunmaz; testlerde de kullanilir) ----------------

# Fare tekerlegi centigi (120) basina kaydirilacak piksel. Lines <= 0: Windows "bir ekran" ayari
function Get-WheelPixels([int]$Delta, [int]$Lines, [double]$Viewport) {
    $notches = [double]$Delta / 120.0
    if ($Lines -le 0) { return ($notches * $Viewport * 0.9) }
    return ($notches * [double]$Lines * 33.0)
}

# Odaktaki ogenin turu: Text (yazi kutusu) | List (liste, acilir kutu, cubuk) | Button (dugme, isaret kutusu) | Neutral (sayfa ya da bos)
function Get-FocusKind($Fe) {
    if ($null -eq $Fe) { return 'Neutral' }
    if (($Fe -is [System.Windows.Controls.Primitives.TextBoxBase]) -or ($Fe -is [System.Windows.Controls.PasswordBox])) { return 'Text' }
    if (($Fe -is [System.Windows.Controls.Primitives.Selector]) -or ($Fe -is [System.Windows.Controls.Slider]) -or ($Fe -is [System.Windows.Controls.ListBoxItem]) -or ($Fe -is [System.Windows.Controls.ComboBoxItem])) { return 'List' }
    if ($Fe -is [System.Windows.Controls.Primitives.ButtonBase]) { return 'Button' }
    return 'Neutral'
}

# WPF'te PageDown = Next, PageUp = Prior (ayni sayi); ad tek bicime cevrilir
function Get-KeyName($Key) {
    if ($Key -eq [System.Windows.Input.Key]::Next) { return 'PageDown' }
    if ($Key -eq [System.Windows.Input.Key]::Prior) { return 'PageUp' }
    return [string]$Key
}

# Tus -> kaydirma eylemi. Yazi kutusunda ve listelerde tuslara dokunulmaz; dugmede yalnizca sayfa tuslari calisir.
function Get-ScrollKeyAction([string]$Key, [bool]$Ctrl, [bool]$Alt, [bool]$Shift, [string]$Kind) {
    if ($Alt) { return '' }
    if ($Kind -eq 'Text' -or $Kind -eq 'List') { return '' }
    if ($Key -eq 'PageDown' -and -not $Ctrl) { return 'PageDown' }
    if ($Key -eq 'PageUp' -and -not $Ctrl) { return 'PageUp' }
    if ($Key -eq 'Home' -and ($Ctrl -or $Kind -eq 'Neutral')) { return 'Top' }
    if ($Key -eq 'End' -and ($Ctrl -or $Kind -eq 'Neutral')) { return 'Bottom' }
    if ($Kind -eq 'Neutral' -and -not $Ctrl) {
        if ($Key -eq 'Space') { if ($Shift) { return 'PageUp' } else { return 'PageDown' } }
        if ($Key -eq 'Down') { return 'LineDown' }
        if ($Key -eq 'Up') { return 'LineUp' }
    }
    return ''
}

# Ctrl kisayollari -> eylem
function Get-HotKeyAction([string]$Key, [bool]$Ctrl, [bool]$Alt, [bool]$Shift) {
    if ((-not $Ctrl) -or $Alt) { return '' }
    if ($Key -eq 'Tab') { if ($Shift) { return 'PrevPage' } else { return 'NextPage' } }
    if ($Key -eq 'OemComma') { return 'Settings' }
    if ($Key -eq 'Q') { return 'Quit' }
    if ($Key -eq 'W') { return 'HideToTray' }
    if ($Key -eq 'OemPlus' -or $Key -eq 'Add') { return 'ZoomIn' }
    if ($Key -eq 'OemMinus' -or $Key -eq 'Subtract') { return 'ZoomOut' }
    if ($Key -eq 'D0' -or $Key -eq 'NumPad0') { return 'ZoomReset' }
    return ''
}

# Klavyeyle gezmeyi baslatan tuslar (odak cercevesi bunlardan sonra gorunur)
function Test-NavKeyName([string]$Name) {
    return (@('Tab', 'Left', 'Right', 'Up', 'Down', 'Space', 'Return', 'Enter') -contains $Name)
}

# ---------------- agac yardimcilari ----------------
function Get-ParentObj($O) {
    if ($null -eq $O) { return $null }
    try {
        if (($O -is [System.Windows.Media.Visual]) -or ($O -is [System.Windows.Media.Media3D.Visual3D])) { return [System.Windows.Media.VisualTreeHelper]::GetParent($O) }
        if ($O -is [System.Windows.DependencyObject]) { return [System.Windows.LogicalTreeHelper]::GetParent($O) }
    } catch { }
    return $null
}

function Test-IsDescendant($Child, $Ancestor) {
    $o = $Child
    $n = 0
    while ($null -ne $o -and $n -lt 160) {
        if ([object]::ReferenceEquals($o, $Ancestor)) { return $true }
        $o = Get-ParentObj $o
        $n++
    }
    return $false
}

# Tekerlek / tus icin en yakin kaydirici. Dir: 1 asagi, -1 yukari, 0 herhangi. Sinirda olan kaydirici atlanir (ustteki denenir).
# Donus: ScrollViewer, $null ya da 'native' (oge satir bazli kaydirir, orn. sanallastirilmis liste: WPF'e birakilir).
function Find-ScrollerFrom($Start, [int]$Dir) {
    $o = $Start
    $n = 0
    while ($null -ne $o -and $n -lt 100) {
        $n++
        if ($o -is [System.Windows.Controls.ScrollViewer]) {
            $sv = $o
            if (($sv.VerticalScrollBarVisibility -ne [System.Windows.Controls.ScrollBarVisibility]::Disabled) -and ([double]$sv.ScrollableHeight -gt 0.5)) {
                $off = [double]$sv.VerticalOffset
                if ($sv.CanContentScroll -eq $true) {
                    # Satir bazli (sanallastirilmis) liste: sinirinda degilse WPF kendi kaydirir; sinirdaysa tekerlek ustteki kaydiriciya gecer
                    if ($Dir -eq 0) { return 'native' }
                    if ($Dir -lt 0 -and $off -gt 0.01) { return 'native' }
                    if ($Dir -gt 0 -and $off -lt ([double]$sv.ScrollableHeight - 0.01)) { return 'native' }
                } else {
                    if ($Dir -eq 0) { return $sv }
                    if ($Dir -lt 0 -and $off -gt 0.5) { return $sv }
                    if ($Dir -gt 0 -and $off -lt ([double]$sv.ScrollableHeight - 0.5)) { return $sv }
                }
            }
        }
        $o = Get-ParentObj $o
    }
    return $null
}

# Kaynak, acik bir acilir listenin (ComboBox) acilan penceresinin icindeyse o ComboBox doner. Acilan pencere ayri bir gorsel agactir;
# kaynak agacta yukari cikilirken penceresinin (Popup) cocuguna varilinca ComboBox, Popup'in sablon sahibidir.
function Get-ComboOfPopupSource($Src) {
    $o = $Src
    $n = 0
    while ($null -ne $o -and $n -lt 100) {
        $n++
        if ($o -is [System.Windows.FrameworkElement]) {
            $par = $o.Parent
            if ($par -is [System.Windows.Controls.Primitives.Popup]) {
                $cb = $par.TemplatedParent
                if ($cb -is [System.Windows.Controls.ComboBox]) { return $cb }
                return $null
            }
        }
        $o = Get-ParentObj $o
    }
    return $null
}

# Gecerli sayfanin ana kaydiricisi (belge sirasindaki ilk kaydirilabilir olan); sonuc sayfa basina saklanir
function Get-PageScroller([int]$Dir) {
    $page = [string]$script:UiState.Page
    $root = $null
    try { $root = $script:Pages[$page] } catch { $root = $null }
    if ($null -eq $root) { return $null }
    $cand = $null
    $c0 = $script:PageSv[$page]
    if ($null -ne $c0 -and $c0.IsVisible -and ([double]$c0.ScrollableHeight -gt 0.5)) { $cand = $c0 }
    if ($null -eq $cand) {
        $stack = New-Object System.Collections.Stack
        $stack.Push($root)
        $n = 0
        while ($stack.Count -gt 0 -and $n -lt 4000) {
            $o = $stack.Pop()
            $n++
            if (($o -is [System.Windows.Controls.ScrollViewer]) -and $o.IsVisible -and ($o.CanContentScroll -ne $true) -and ($o.VerticalScrollBarVisibility -ne [System.Windows.Controls.ScrollBarVisibility]::Disabled) -and ([double]$o.ScrollableHeight -gt 0.5)) {
                $cand = $o
                break
            }
            $kids = New-Object System.Collections.ArrayList
            foreach ($c in [System.Windows.LogicalTreeHelper]::GetChildren($o)) {
                if ($c -is [System.Windows.FrameworkElement]) { [void]$kids.Add($c) }
            }
            for ($i = $kids.Count - 1; $i -ge 0; $i--) { $stack.Push($kids[$i]) }
        }
        if ($null -ne $cand) { $script:PageSv[$page] = $cand }
    }
    if ($null -eq $cand) { return $null }
    $off = [double]$cand.VerticalOffset
    if ($Dir -lt 0 -and $off -le 0.5) { return $null }
    if ($Dir -gt 0 -and $off -ge ([double]$cand.ScrollableHeight - 0.5)) { return $null }
    return $cand
}

# Tuslar icin hedef: fare sayfa alanindaki bir kaydiricinin ustundeyse o, degilse sayfanin ana kaydiricisi
function Get-KeyScroller([int]$Dir) {
    $sv = $null
    try {
        $over = [System.Windows.Input.Mouse]::DirectlyOver
        if ($null -ne $over -and (Test-IsDescendant $over $ui.PageHost)) {
            $sv = Find-ScrollerFrom $over $Dir
            if ($sv -is [string]) { $sv = $null }
        }
    } catch { $sv = $null }
    if ($null -eq $sv) { $sv = Get-PageScroller $Dir }
    return $sv
}

# ---------------- yumusak kaydirma ----------------
function Get-SmoothKey($Sv) { return [string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($Sv) }

function Get-SmoothBase($Sv) {
    $key = Get-SmoothKey $Sv
    if ($script:SmoothMap.ContainsKey($key)) { return [double]$script:SmoothMap[$key].Target }
    return [double]$Sv.VerticalOffset
}

function Stop-SmoothScroll {
    try { if ($null -ne $script:SmoothTimer) { $script:SmoothTimer.Stop() } } catch { }
    $script:SmoothMap.Clear()
}

function Step-SmoothScroll {
    $done = New-Object System.Collections.ArrayList
    foreach ($key in @($script:SmoothMap.Keys)) {
        $en = $script:SmoothMap[$key]
        $sv = $en.Sv
        $cur = [double]$sv.VerticalOffset
        $d = [double]$en.Target - $cur
        if ([math]::Abs($d) -lt 0.6) {
            $sv.ScrollToVerticalOffset([double]$en.Target)
            [void]$done.Add($key)
        } else {
            $sv.ScrollToVerticalOffset($cur + $d * 0.30)
        }
    }
    foreach ($k in $done) { $script:SmoothMap.Remove($k) }
    if ($script:SmoothMap.Count -eq 0) { $script:SmoothTimer.Stop() }
}

function Start-SmoothScroll($Sv, [double]$Target) {
    $max = [double]$Sv.ScrollableHeight
    if ($Target -lt 0) { $Target = 0 }
    if ($Target -gt $max) { $Target = $max }
    if (($script:ReduceMotion -eq $true) -or ($script:Settings.SmoothScroll -eq $false)) {
        $Sv.ScrollToVerticalOffset($Target)
        return
    }
    $script:SmoothMap[(Get-SmoothKey $Sv)] = @{ Sv = $Sv; Target = $Target }
    if ($null -eq $script:SmoothTimer) {
        $t = New-Object System.Windows.Threading.DispatcherTimer -ArgumentList ([System.Windows.Threading.DispatcherPriority]::Render)
        $t.Interval = [TimeSpan]::FromMilliseconds(15)
        $t.Add_Tick({ try { Step-SmoothScroll } catch { Stop-SmoothScroll } })
        $script:SmoothTimer = $t
    }
    if (-not $script:SmoothTimer.IsEnabled) { $script:SmoothTimer.Start() }
}

# ---------------- fare tekerlegi ----------------
function Invoke-WheelRoute($E) {
    $mods = [System.Windows.Input.Keyboard]::Modifiers
    if (($mods -band [System.Windows.Input.ModifierKeys]::Control) -ne 0) {
        $now = Get-Date
        if (($now - $script:ZoomStepAt).TotalMilliseconds -ge 140) {
            $script:ZoomStepAt = $now
            if ($E.Delta -gt 0) { Step-UiZoom 1 } elseif ($E.Delta -lt 0) { Step-UiZoom -1 }
        }
        $E.Handled = $true
        return
    }
    if ($mods -ne [System.Windows.Input.ModifierKeys]::None) { return }
    $src = $E.OriginalSource
    $modal = ($ui.Overlay.Visibility -eq $script:VisOn)
    if ($modal -and (-not (Test-IsDescendant $src $ui.Overlay))) { $E.Handled = $true; return }
    $dir = 1
    if ($E.Delta -gt 0) { $dir = -1 }
    # Acik bir acilir listenin ustundeyken tekerlek yalnizca o listeyi kaydirir; liste kisaysa ya da sinira gelmisse arkadaki sayfa kipirdamaz
    if ($null -ne (Get-ComboOfPopupSource $src)) {
        $lv = Find-ScrollerFrom $src $dir
        if ($lv -is [string]) { return }
        $E.Handled = $true
        return
    }
    $sv = Find-ScrollerFrom $src $dir
    if ($sv -is [string]) { return }
    if ($null -eq $sv -and (-not $modal) -and (Test-IsDescendant $src $ui.PageHost)) { $sv = Get-PageScroller $dir }
    if ($null -eq $sv) { return }
    $lines = 3
    try { $lines = [int][System.Windows.SystemParameters]::WheelScrollLines } catch { $lines = 3 }
    $px = Get-WheelPixels ([int]$E.Delta) $lines ([double]$sv.ViewportHeight)
    Start-SmoothScroll $sv ((Get-SmoothBase $sv) - $px)
    $E.Handled = $true
}

# ---------------- klavye ----------------
function Invoke-ScrollAction([string]$Action) {
    $dir = 0
    if ($Action -eq 'PageDown' -or $Action -eq 'LineDown' -or $Action -eq 'Bottom') { $dir = 1 }
    elseif ($Action -eq 'PageUp' -or $Action -eq 'LineUp' -or $Action -eq 'Top') { $dir = -1 }
    $sv = Get-KeyScroller $dir
    if ($null -eq $sv) { return $false }
    $vp = [double]$sv.ViewportHeight
    $base = Get-SmoothBase $sv
    $t = $base
    if ($Action -eq 'PageDown') { $t = $base + [math]::Max(40.0, $vp - 60.0) }
    elseif ($Action -eq 'PageUp') { $t = $base - [math]::Max(40.0, $vp - 60.0) }
    elseif ($Action -eq 'LineDown') { $t = $base + 60.0 }
    elseif ($Action -eq 'LineUp') { $t = $base - 60.0 }
    elseif ($Action -eq 'Top') { $t = 0.0 }
    elseif ($Action -eq 'Bottom') { $t = [double]$sv.ScrollableHeight }
    Start-SmoothScroll $sv $t
    return $true
}

function Step-Page([int]$Delta) {
    $keys = New-Object System.Collections.ArrayList
    foreach ($k in @($script:PageTitles.Keys)) {
        $rb = $ui['Rail_' + [string]$k]
        if ($null -ne $rb -and $rb.Visibility -eq $script:VisOn) { [void]$keys.Add([string]$k) }
    }
    if ($keys.Count -lt 2) { return }
    $cur = [string]$script:UiState.Page
    if ($cur -eq 'board') { $cur = 'panel' }
    $i = $keys.IndexOf($cur)
    if ($i -lt 0) { $i = 0 }
    $j = ($i + $Delta) % $keys.Count
    if ($j -lt 0) { $j += $keys.Count }
    Show-Page ([string]$keys[$j])
}

# Uygulamayi tamamen kapatma istegi (guc dugmesi ve Ctrl+Q): islem suruyorsa once sorulur
function Request-FullExit {
    if (Test-AsyncBusy) {
        Show-Confirm ('' + [char]0x0130 + '' + [char]0x015F + 'lem s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor') ('Devam eden i' + [char]0x015F + 'lem iptal edilip uygulama tamamen kapat' + [char]0x0131 + 'ls' + [char]0x0131 + 'n m' + [char]0x0131 + '?') 'Kapat' { Exit-App } $true
    } else {
        Show-Confirm ('Uygulamay' + [char]0x0131 + ' kapat') ('Uygulama tamamen kapat' + [char]0x0131 + 'ls' + [char]0x0131 + 'n m' + [char]0x0131 + '? (Tepsiye k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'ltmek i' + [char]0x00E7 + 'in pencerenin X d' + [char]0x00FC + '' + [char]0x011F + 'mesini ya da Ctrl+W tu' + [char]0x015F + 'unu kullan' + [char]0x0131 + 'n.)') 'Kapat' { Exit-App } $false
    }
}

function Reset-UiZoom {
    Set-UiZoom 100 $true
    try { if ($script:Pages.ContainsKey('settings')) { Load-StLook } } catch { }
    Show-Toast ('Yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma: %100') 'info'
}

function Invoke-HotAction([string]$Act) {
    if ($Act -eq 'NextPage') { Step-Page 1 }
    elseif ($Act -eq 'PrevPage') { Step-Page -1 }
    elseif ($Act -eq 'Settings') { Show-Page 'settings' }
    elseif ($Act -eq 'Quit') { Request-FullExit }
    elseif ($Act -eq 'HideToTray') { if ($null -ne $script:Tray) { Hide-ToTray } else { $script:Win.WindowState = [System.Windows.WindowState]::Minimized } }
    elseif ($Act -eq 'ZoomIn') { Step-UiZoom 1 }
    elseif ($Act -eq 'ZoomOut') { Step-UiZoom -1 }
    elseif ($Act -eq 'ZoomReset') { Reset-UiZoom }
}

function Invoke-KeyRoute($E) {
    if ($E.Handled) { return }
    $mods = [System.Windows.Input.Keyboard]::Modifiers
    $ctrl = (($mods -band [System.Windows.Input.ModifierKeys]::Control) -ne 0)
    $alt = (($mods -band [System.Windows.Input.ModifierKeys]::Alt) -ne 0)
    $shift = (($mods -band [System.Windows.Input.ModifierKeys]::Shift) -ne 0)
    $key = $E.Key
    if ($key -eq [System.Windows.Input.Key]::System) { $key = $E.SystemKey }
    $name = Get-KeyName $key
    if (Test-NavKeyName $name) { $script:KbNav = $true }
    $modal = ($ui.Overlay.Visibility -eq $script:VisOn)
    if ($modal) { return }
    $hk = Get-HotKeyAction $name $ctrl $alt $shift
    if ($hk -ne '') {
        Invoke-Safe { Invoke-HotAction $hk } ('K' + [char]0x0131 + 'sayol')
        $E.Handled = $true
        return
    }
    if ($ui.CmdPop.IsOpen -eq $true) { return }
    $kind = Get-FocusKind ([System.Windows.Input.Keyboard]::FocusedElement)
    $act = Get-ScrollKeyAction $name $ctrl $alt $shift $kind
    if ($act -ne '') {
        if (Invoke-ScrollAction $act) { $E.Handled = $true }
    }
}

# ---------------- basa don dugmesi ----------------
function Initialize-ToTop {
    $host_ = $ui.PageHost.Parent
    if ($host_ -isnot [System.Windows.Controls.Grid]) { return }
    $b = New-Object System.Windows.Controls.Button
    $b.Style = $script:Win.FindResource('BtnPrimary')
    $b.Content = (Tr $([string][char]0x2191))
    $b.Width = 38
    $b.Height = 38
    $b.Padding = New-Object System.Windows.Thickness -ArgumentList 0
    $b.FontSize = 18
    $b.FontWeight = [System.Windows.FontWeights]::Bold
    $b.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
    $b.VerticalAlignment = [System.Windows.VerticalAlignment]::Bottom
    $b.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 0, 28, 70
    $b.ToolTip = (Tr $(('Ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n (Ctrl+Home)')))
    $b.Visibility = $script:VisOff
    $b.Add_Click({ Invoke-Safe { [void](Invoke-ScrollAction 'Top') } ('Ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n') })
    [void]$host_.Children.Add($b)
    $script:ToTopBtn = $b
}

# Src: degisen kaydirici (sayfa degisiminde $null). Dugme, sayfanin ana kaydiricisi belirgin bicimde asagidayken gorunur.
function Update-ToTop($Src) {
    $b = $script:ToTopBtn
    if ($null -eq $b) { return }
    if ($script:Settings.ToTopButton -eq $false) { Set-Visible $b $false; return }
    if ($null -ne $Src) {
        if ($Src -isnot [System.Windows.Controls.ScrollViewer]) { return }
        if (-not (Test-IsDescendant $Src $ui.PageHost)) { return }
    }
    $sv = Get-PageScroller 0
    Set-Visible $b (($null -ne $sv) -and ([double]$sv.VerticalOffset -gt 240))
}

# ---------------- klavye odak cercevesi ----------------
function Initialize-FocusRing {
    $rootGrid = $ui.Root.Child
    if ($rootGrid -isnot [System.Windows.Controls.Grid]) { return }
    $r = New-Object System.Windows.Controls.Border
    $r.IsHitTestVisible = $false
    $r.BorderThickness = New-Object System.Windows.Thickness -ArgumentList 2
    $r.CornerRadius = New-Object System.Windows.CornerRadius -ArgumentList 6
    $r.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BrAccent')
    $r.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
    $r.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
    $r.Visibility = $script:VisOff
    [System.Windows.Controls.Grid]::SetRowSpan($r, 3)
    [System.Windows.Controls.Panel]::SetZIndex($r, 50)
    [void]$rootGrid.Children.Add($r)
    $script:FocusRingBox = $r
    $script:FocusRingHost = $rootGrid
}

function Update-FocusRing {
    $r = $script:FocusRingBox
    if ($null -eq $r) { return }
    $show = $false
    try {
        if (($script:KbNav -eq $true) -and ($script:Settings.FocusRing -ne $false)) {
            $fe = [System.Windows.Input.Keyboard]::FocusedElement
            $skip = ($fe -is [System.Windows.Window]) -or ($fe -is [System.Windows.Controls.ScrollViewer]) -or ([object]::ReferenceEquals($fe, $ui.PageHost)) -or ((Get-FocusKind $fe) -eq 'Text')
            if (($fe -is [System.Windows.FrameworkElement]) -and (-not $skip) -and $fe.IsVisible -and ([double]$fe.ActualWidth -gt 4) -and ([double]$fe.ActualHeight -gt 4)) {
                $t = $fe.TransformToAncestor($script:FocusRingHost)
                $b = $t.TransformBounds((New-Object System.Windows.Rect -ArgumentList 0, 0, ([double]$fe.ActualWidth), ([double]$fe.ActualHeight)))
                if ($b.Width -gt 1 -and $b.Height -gt 1) {
                    $r.Margin = New-Object System.Windows.Thickness -ArgumentList ($b.Left - 2), ($b.Top - 2), 0, 0
                    $r.Width = $b.Width + 4
                    $r.Height = $b.Height + 4
                    $show = $true
                }
            }
        }
    } catch { $show = $false }
    Set-Visible $r $show
}

# Sayfa alaninda etkilesimsiz bir yere tiklaninca odak sayfaya gecer (ok tuslari ve PageDown sayfayi kaydirsin; menu dugmesinde kalmasin)
function Test-InteractiveSource($Src) {
    $o = $Src
    $n = 0
    while ($null -ne $o -and $n -lt 100) {
        if (($o -is [System.Windows.Controls.Primitives.ButtonBase]) -or ($o -is [System.Windows.Controls.Primitives.TextBoxBase]) -or ($o -is [System.Windows.Controls.PasswordBox]) -or ($o -is [System.Windows.Controls.Primitives.Selector]) -or ($o -is [System.Windows.Controls.Primitives.ScrollBar]) -or ($o -is [System.Windows.Controls.Slider]) -or ($o -is [System.Windows.Controls.ListBoxItem])) { return $true }
        if ([object]::ReferenceEquals($o, $ui.PageHost)) { return $false }
        $o = Get-ParentObj $o
        $n++
    }
    return $false
}

function Focus-PageHost {
    try { [void]$ui.PageHost.Focus() } catch { }
}

# ---------------- kurulum ----------------
function Write-ScrollErr([string]$Where, $Err) {
    if (((Get-Date) - $script:ScrollErrAt).TotalSeconds -lt 5) { return }
    $script:ScrollErrAt = Get-Date
    Write-CrashLog ($Where + ': ' + $Err.Exception.Message)
}

# ---------------- erisilebilirlik: ekran okuyucu adlari ----------------
# ---------------- Erisilebilirlik: ekran okuyucu adlari ----------------
# Ekran Okuyucu bir denetimi UI Automation adiyla okur. WPF bu adi yalnizca icerigi duz yazi olan dugmelerde kendisi bulur;
# simge + yazidan olusan dugmeler, secim ve metin kutulari adsiz kalir ("dugme", "birlesik giris kutusu" diye okunur).
# Bir denetim ilk kez boyut aldiginda (SizeChanged sinif isleyicisi; sonradan olusan satirlar, acilan sekmeler dahil) adi bossa:
#  - dugme ve onay/secenek kutusu: icindeki ilk anlamli yaziya (TextBlock.Text) baglanir; yazi yoksa ipucuna (ToolTip)
#  - secim kutusu, metin kutusu, parola kutusu, kaydirici: ayni satirdaki onceki etikete (LabeledBy) baglanir; yoksa ipucuna
# Baglama (Binding) kullanildigi icin dil degisince ad da degisir. Adi zaten verilmis ogelere ve baska bir denetimin
# sablon parcalarina (kaydirma cubugu oklari gibi) dokunulmaz. Is, yerlesim bittikten sonra (Background onceligi) yapilir.
# Neden Loaded degil: WPF, Loaded olayini yalnizca kendisinde ya da stilinde Loaded isleyicisi olan ogelere yayinlar; sinif
# isleyicisi bu yuzden cogu dugmede hic cagrilmaz (gercek bilgisayarda 25.11.2026: yama oncesi ve sonrasi 46 adsiz denetim).
# SizeChanged ise her ogede yerlesim sirasinda RaiseEvent ile tetiklenir; yalnizca ilk boyutta (onceki boyut 0) is yapilir.
$script:A11yQueue = New-Object System.Collections.ArrayList
$script:A11yPending = $false
$script:A11yRegistered = $false
$script:A11yDone = 0
$script:A11yCalls = 0
$script:A11yErr = $false
# Yazisi ya da ipucu olmayan, adiyla taninan denetimler (deger secici oklari, komut satiri). Satir basligi varsa one eklenir.
$script:A11yNameMap = @{
    Dn = 'Azalt'; Up = ('Art' + [char]0x0131 + 'r')
    AcDn = ('Fi' + [char]0x015F + 'te: azalt'); AcUp = ('Fi' + [char]0x015F + 'te: art' + [char]0x0131 + 'r'); DcDn = 'Pilde: azalt'; DcUp = ('Pilde: art' + [char]0x0131 + 'r')
    CmdInput = ('Komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ''); AskInput = 'Asistan'
}
$script:A11yRowTitled = @('Dn', 'Up', 'AcDn', 'AcUp', 'DcDn', 'DcUp')

function Test-A11yTarget($El) {
    return (($El -is [System.Windows.Controls.Primitives.ButtonBase]) -or ($El -is [System.Windows.Controls.ComboBox]) -or
        ($El -is [System.Windows.Controls.Primitives.TextBoxBase]) -or ($El -is [System.Windows.Controls.PasswordBox]) -or
        ($El -is [System.Windows.Controls.Slider]))
}

# Yuklenen oge: hizli elemeden gecerse kuyruga alinir (asil is bosta yapilir)
function Add-A11yCandidate($El) {
    if ($null -eq $El) { return }
    if (-not [string]::IsNullOrEmpty([System.Windows.Automation.AutomationProperties]::GetName($El))) { return }
    if ($null -ne [System.Windows.Automation.AutomationProperties]::GetLabeledBy($El)) { return }
    if ($El -is [System.Windows.Controls.ContentControl]) {
        $cn = $El.Content
        if ($cn -is [string] -and -not (Test-A11yNameBad ([string]$cn)) -and -not (Test-A11yContextTarget $El)) { return }
    }
    if ($El.TemplatedParent -is [System.Windows.Controls.Control]) { return }
    [void]$script:A11yQueue.Add($El)
    if (-not $script:A11yPending) {
        $script:A11yPending = $true
        [void]$El.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Background, [Action]{ Invoke-A11yQueue })
    }
}

# Adi baglama gore uzatilan denetimler: ad tek basina ayirt edici degildir (her satirda ayni dugme, ayni basliklar)
function Test-A11yContextTarget($El) {
    $nm = [string]$El.Name
    if ($El -is [System.Windows.Controls.Primitives.ButtonBase] -and ($nm -eq 'Act' -or $nm -eq 'Act2' -or $nm -eq 'Fx' -or $nm -eq 'BtnCancel')) { return $true }
    if ($El -is [System.Windows.Controls.RadioButton] -and $nm -cmatch '^[a-z]+_Tab_') { return $true }
    if ($El -is [System.Windows.Controls.CheckBox] -and $nm -eq 'Chk') { return $true }
    return $false
}

# Denetimin bulundugu satirdaki (en yakin ust paneller, en cok 2 basamak) adi verilen TextBlock; belirsizse ($null) bulunmaz
function Find-A11yRowText($El, [string]$TbName) {
    $p = $El
    for ($lvl = 0; $lvl -lt 2 -and $null -ne $p; $lvl++) {
        $p = [System.Windows.Media.VisualTreeHelper]::GetParent($p)
        if ($null -eq $p) { break }
        $hits = New-Object System.Collections.ArrayList
        $stack = New-Object System.Collections.Stack
        $stack.Push($p)
        $n = 0
        while ($stack.Count -gt 0 -and $n -lt 100) {
            $o = $stack.Pop()
            $n++
            if ($o -is [System.Windows.Controls.TextBlock] -and [string]$o.Name -eq $TbName) { [void]$hits.Add($o); continue }
            $k = 0
            try { $k = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o) } catch { $k = 0 }
            for ($i = $k - 1; $i -ge 0; $i--) { try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $i)) } catch { } }
        }
        if ($stack.Count -gt 0) { return $null }
        if ($hits.Count -eq 1) { return $hits[0] }
        if ($hits.Count -gt 1) { return $null }
    }
    return $null
}

function Set-A11yJoinBinding($El, $Parts, [string]$Fmt) {
    $mb = New-Object System.Windows.Data.MultiBinding
    $mb.StringFormat = $Fmt
    $mb.Mode = [System.Windows.Data.BindingMode]::OneWay
    foreach ($pt in $Parts) {
        $bp = New-Object System.Windows.Data.Binding([string]$pt.P)
        $bp.Source = $pt.S
        $bp.Mode = [System.Windows.Data.BindingMode]::OneWay
        $mb.Bindings.Add($bp)
    }
    [void][System.Windows.Data.BindingOperations]::SetBinding($El, [System.Windows.Automation.AutomationProperties]::NameProperty, $mb)
}

# Satir kabindan (kok) ilk adli TextBlock
function Find-A11yNamedText($Root, [string]$TbName) {
    $stack = New-Object System.Collections.Stack
    $stack.Push($Root)
    $n = 0
    while ($stack.Count -gt 0 -and $n -lt 100) {
        $o = $stack.Pop()
        $n++
        if ($o -is [System.Windows.Controls.TextBlock] -and [string]$o.Name -eq $TbName) { return $o }
        $k = 0
        try { $k = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o) } catch { $k = 0 }
        for ($i = $k - 1; $i -ge 0; $i--) { try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $i)) } catch { } }
    }
    return $null
}

# Ayni satir listesinde (satir kabinin ust paneli) bu basligi tasiyan satir sayisi; kuyruk bosalinca onbellek silinir
$script:A11yTitleCache = @{}
function Get-A11yTitleCount($El, $Tt) {
    $row = $null
    $cur = [System.Windows.Media.VisualTreeHelper]::GetParent($El)
    $n = 0
    while ($null -ne $cur -and $n -lt 8) {
        if ($cur -is [System.Windows.Controls.Border]) { $row = $cur; break }
        $cur = [System.Windows.Media.VisualTreeHelper]::GetParent($cur)
        $n++
    }
    if ($null -eq $row) { return 1 }
    $panel = [System.Windows.Media.VisualTreeHelper]::GetParent($row)
    if (-not ($panel -is [System.Windows.Controls.Panel])) { return 1 }
    $key = [string][System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($panel) + ':' + [string]$panel.Children.Count
    if (-not $script:A11yTitleCache.ContainsKey($key)) {
        $cnt = @{}
        foreach ($c in @($panel.Children)) {
            $t = Find-A11yNamedText $c 'Ttl'
            if ($null -ne $t) { $k = ([string]$t.Text).ToLowerInvariant(); $cnt[$k] = [int]$cnt[$k] + 1 }
        }
        $script:A11yTitleCache[$key] = $cnt
    }
    $c2 = $script:A11yTitleCache[$key][([string]$Tt.Text).ToLowerInvariant()]
    if ($null -eq $c2) { return 1 }
    return [int]$c2
}

function Set-A11yContextName($El) {
    $nm = [string]$El.Name
    if ($nm -eq 'BtnCancel') {
        [System.Windows.Automation.AutomationProperties]::SetName($El, (Tr ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an i' + [char]0x015F + 'i durdur')))
        return $true
    }
    if ($El -is [System.Windows.Controls.RadioButton]) {
        if (-not ($El.Content -is [string]) -or (Test-A11yNameBad ([string]$El.Content))) { return $false }
        $b = New-Object System.Windows.Data.Binding('Content')
        $b.Source = $El
        $b.Mode = [System.Windows.Data.BindingMode]::OneWay
        $b.StringFormat = '{0}, ' + ((Tr 'sekme') -replace '([{}])', '$1$1')
        [void][System.Windows.Data.BindingOperations]::SetBinding($El, [System.Windows.Automation.AutomationProperties]::NameProperty, $b)
        return $true
    }
    $tt = Find-A11yRowText $El 'Ttl'
    if ($null -eq $tt -or [string]::IsNullOrEmpty([string]$tt.Text)) { return $false }
    if ($El -is [System.Windows.Controls.CheckBox]) {
        $dt = Find-A11yRowText $El 'Det'
        if ($null -ne $dt -and $dt.Visibility -eq [System.Windows.Visibility]::Visible -and -not [string]::IsNullOrEmpty([string]$dt.Text)) {
            Set-A11yJoinBinding $El @(@{ S = $tt; P = 'Text' }, @{ S = $dt; P = 'Text' }) '{0}, {1}'
        } else { Set-A11yNameBinding $El $tt 'Text' }
        return $true
    }
    if ($El.Content -is [string] -and -not (Test-A11yNameBad ([string]$El.Content))) {
        $dt = $null
        if ((Get-A11yTitleCount $El $tt) -gt 1) { $dt = Find-A11yRowText $El 'Det' }
        if ($null -ne $dt -and -not [string]::IsNullOrEmpty([string]$dt.Text)) { Set-A11yJoinBinding $El @(@{ S = $El; P = 'Content' }, @{ S = $tt; P = 'Text' }, @{ S = $dt; P = 'Text' }) '{0}, {1}, {2}' }
        else { Set-A11yJoinBinding $El @(@{ S = $El; P = 'Content' }, @{ S = $tt; P = 'Text' }) '{0}, {1}' }
        return $true
    }
    return $false
}

function Set-A11yNameBinding($El, $Source, [string]$Path) {
    $b = New-Object System.Windows.Data.Binding($Path)
    $b.Source = $Source
    $b.Mode = [System.Windows.Data.BindingMode]::OneWay
    [void][System.Windows.Data.BindingOperations]::SetBinding($El, [System.Windows.Automation.AutomationProperties]::NameProperty, $b)
}

# Dugmenin icindeki ilk anlamli yazi (yalnizca simge karakteri olan yazilar atlanir)
function Find-A11yInnerText($El) {
    $hidden = $null
    $stack = New-Object System.Collections.Stack
    $stack.Push($El)
    $n = 0
    while ($stack.Count -gt 0 -and $n -lt 80) {
        $o = $stack.Pop()
        $n++
        if ($o -is [System.Windows.Controls.TextBlock] -and $o -ne $El -and -not (Test-A11yNameBad ([string]$o.Text))) {
            if ($o.IsVisible) { return $o }
            if ($null -eq $hidden) { $hidden = $o }
        }
        $k = 0
        try { $k = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o) } catch { $k = 0 }
        for ($i = $k - 1; $i -ge 0; $i--) { try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $i)) } catch { } }
    }
    return $hidden
}

# Panelin dogrudan cocuklarindan ilk anlamli yazi (satir basligi: StackPanel icindeki baslik TextBlock'u)
function Get-A11yFirstText($El) {
    if ($El -is [System.Windows.Controls.TextBlock]) { if (-not (Test-A11yNameBad ([string]$El.Text))) { return $El }; return $null }
    if ($El -is [System.Windows.Controls.Panel]) {
        foreach ($c in @($El.Children)) { if ($c -is [System.Windows.Controls.TextBlock] -and -not (Test-A11yNameBad ([string]$c.Text))) { return $c } }
    }
    return $null
}

# Icerigi olmayan dugme (kart ustundeki tiklama alani, satirdaki onay kutusu): kardes ogelerdeki ilk anlamli yazi
function Find-A11ySiblingText($El) {
    $p = [System.Windows.Media.VisualTreeHelper]::GetParent($El)
    if (-not ($p -is [System.Windows.Controls.Panel])) { return $null }
    foreach ($c in @($p.Children)) {
        if ($c -eq $El) { continue }
        $t = Find-A11yInnerText $c
        if ($null -ne $t) { return $t }
    }
    return $null
}

# Satir basligi: ustteki Grid'in ilk sutunundaki baslik yazisi (deger secici satirlari)
function Get-A11yRowTitle($El) {
    $p = $El
    for ($i = 0; $i -lt 3 -and $null -ne $p; $i++) {
        $p = [System.Windows.Media.VisualTreeHelper]::GetParent($p)
        if ($p -is [System.Windows.Controls.Grid]) {
            foreach ($c in @($p.Children)) {
                if ([System.Windows.Controls.Grid]::GetColumn($c) -ne 0) { continue }
                $t = Get-A11yFirstText $c
                if ($null -ne $t) { return [string]$t.Text }
            }
            return ''
        }
    }
    return ''
}

# Giris denetiminin etiketi: ayni panelde ondan once gelen, anlamli yazisi olan TextBlock (Grid'de ayni satir, soldaki sutun)
function Find-A11yLabel($El) {
    $p = [System.Windows.Media.VisualTreeHelper]::GetParent($El)
    $hop = 0
    while ($null -ne $p -and $hop -lt 3) {
        if ($p -is [System.Windows.Controls.Grid]) {
            $row = [System.Windows.Controls.Grid]::GetRow($El)
            $col = [System.Windows.Controls.Grid]::GetColumn($El)
            $best = $null
            $bestCol = -1
            foreach ($c in @($p.Children)) {
                if ($c -eq $El -or -not $c.IsVisible) { continue }
                $cc = [System.Windows.Controls.Grid]::GetColumn($c)
                if ([System.Windows.Controls.Grid]::GetRow($c) -ne $row -or $cc -ge $col -or $cc -le $bestCol) { continue }
                $t = Get-A11yFirstText $c
                if ($null -ne $t) { $best = $t; $bestCol = $cc }
            }
            return $best
        }
        if ($p -is [System.Windows.Controls.Panel]) {
            $prev = $null
            foreach ($c in @($p.Children)) {
                if ($c -eq $El) { break }
                if ($c.IsVisible) { $prev = $c }
            }
            if ($prev -is [System.Windows.Controls.TextBlock] -and -not (Test-A11yNameBad ([string]$prev.Text))) { return $prev }
            $vis = @(@($p.Children) | Where-Object { $_.IsVisible })
            if ($vis.Count -gt 1) { return $null }
        }
        $El = $p
        $p = [System.Windows.Media.VisualTreeHelper]::GetParent($p)
        $hop++
    }
    return $null
}

function Set-A11yName($El) {
    if (-not [string]::IsNullOrEmpty([System.Windows.Automation.AutomationProperties]::GetName($El))) { return $false }
    if (Test-A11yContextTarget $El) { if (Set-A11yContextName $El) { return $true } }
    $nm = [string]$El.Name
    if ($nm -ne '' -and $script:A11yNameMap.ContainsKey($nm)) {
        $txt = Tr ([string]$script:A11yNameMap[$nm])
        if ($script:A11yRowTitled -contains $nm) { $rt = Get-A11yRowTitle $El; if ($rt -ne '') { $txt = $rt + ', ' + $txt } }
        [System.Windows.Automation.AutomationProperties]::SetName($El, $txt)
        return $true
    }
    if ($El -is [System.Windows.Controls.Primitives.ButtonBase]) {
        $tb = Find-A11yInnerText $El
        if ($null -ne $tb) { Set-A11yNameBinding $El $tb 'Text'; return $true }
    } else {
        if ($null -ne [System.Windows.Automation.AutomationProperties]::GetLabeledBy($El)) { return $false }
        $lb = Find-A11yLabel $El
        if ($null -ne $lb) { [System.Windows.Automation.AutomationProperties]::SetLabeledBy($El, $lb); return $true }
    }
    if ($El.ToolTip -is [string] -and -not (Test-A11yNameBad ([string]$El.ToolTip))) { Set-A11yNameBinding $El $El 'ToolTip'; return $true }
    if ($El -is [System.Windows.Controls.Primitives.ButtonBase] -and ($null -eq $El.Content -or [string]$El.Content -eq '')) {
        $st = Find-A11ySiblingText $El
        if ($null -ne $st) { Set-A11yNameBinding $El $st 'Text'; return $true }
    }
    return $false
}

function Invoke-A11yQueue([bool]$All = $false) {
    $script:A11yPending = $false
    $items = $script:A11yQueue.ToArray()
    $script:A11yQueue.Clear()
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    for ($qi = 0; $qi -lt $items.Count; $qi++) {
        if (-not $All -and $qi -gt 0 -and $sw.ElapsedMilliseconds -gt 40) {
            for ($qj = $qi; $qj -lt $items.Count; $qj++) { [void]$script:A11yQueue.Add($items[$qj]) }
            if (-not $script:A11yPending) {
                $script:A11yPending = $true
                [void]$items[$qi].Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Background, [Action]{ Invoke-A11yQueue })
            }
            break
        }
        $el = $items[$qi]
        try { if ($el.IsLoaded -and (Set-A11yName $el)) { $script:A11yDone = [int]$script:A11yDone + 1 } }
        catch {
            if (-not $script:A11yErr) { $script:A11yErr = $true; Write-CrashLog (('Eri' + [char]0x015F + 'ilebilirlik ad' + [char]0x0131 + ' verilemedi: ') + $_.Exception.Message) }
        }
    }
    if ($script:A11yQueue.Count -eq 0) { $script:A11yTitleCache.Clear() }
}

# Uygulama baslarken bir kez: denetim turleri icin ilk boyut (SizeChanged) ve Loaded sinif isleyicileri
function Register-A11yNames {
    if ($script:A11yRegistered) { return }
    $script:A11yRegistered = $true
    $h = [System.Windows.RoutedEventHandler]{
        param($s, $e)
        try {
            # yeniden boyutlanma (pencere buyutme, yakinlastirma) issizdir; yalnizca ilk boyut ve gizliyken acilma
            if ($e -is [System.Windows.SizeChangedEventArgs]) { $p = $e.PreviousSize; if ($p.Width -gt 0 -and $p.Height -gt 0) { return } }
            $script:A11yCalls = [int]$script:A11yCalls + 1
            if (Test-A11yTarget $s) { Add-A11yCandidate $s }
        }
        catch {
            if (-not $script:A11yErr) { $script:A11yErr = $true; Write-CrashLog (('Eri' + [char]0x015F + 'ilebilirlik ad' + [char]0x0131 + ' verilemedi: ') + $_.Exception.Message) }
        }
    }
    foreach ($t in @([System.Windows.Controls.Primitives.ButtonBase], [System.Windows.Controls.ComboBox], [System.Windows.Controls.Primitives.TextBoxBase],
            [System.Windows.Controls.PasswordBox], [System.Windows.Controls.Slider])) {
        [System.Windows.EventManager]::RegisterClassHandler($t, [System.Windows.FrameworkElement]::SizeChangedEvent, $h)
        [System.Windows.EventManager]::RegisterClassHandler($t, [System.Windows.FrameworkElement]::LoadedEvent, $h)
    }
}

# ---------------- dokunma hedefleri: Otomatik / Normal / Buyuk ----------------
# ---------------- Dokunma hedefleri: Otomatik / Normal / Buyuk ----------------
# Ayarlar > Gorunum'de "Dokunma hedefleri". Buyuk kipte sekme, onay kutusu, secenek ve dugmeler en az 40 px (Kompakt yerlesimde 32 px) olur.
# Otomatik: dokunmatik ekran varsa Buyuk. Normal kipte hicbir olcu degismez.
# Kaynak sozlugunde iki sayi tutulur (stiller DynamicResource ile okur, bu yuzden degisiklik aninda uygulanir):
#  TouchMin    : sekme, onay kutusu ve anahtar icin alt sinir (Normal 24 px: WCAG 2.2 AA 2.5.8; Buyuk 40 ya da 32 px)
#  TouchBtnMin : dugmeler icin alt sinir (Normal 0 = yalnizca kendi olcusu; Buyuk 40 ya da 32 px)
$script:TouchKeys = @('Auto', 'Normal', 'Large')
$script:TouchScreenCache = $null
$script:TouchMode = 'Normal'
$script:TouchMinNow = 24.0

function ConvertTo-TouchKey($Value) {
    $t = [string]$Value
    foreach ($k in $script:TouchKeys) { if ($k -ceq $t) { return $k } }
    return 'Auto'
}

# Bilgisayarda dokunmatik ekran var mi (WPF tablet aygitlari; ilk sonuc saklanir)
function Test-TouchScreen {
    if ($null -ne $script:TouchScreenCache) { return [bool]$script:TouchScreenCache }
    $r = $false
    try {
        foreach ($d in @([System.Windows.Input.Tablet]::TabletDevices)) {
            if ($d.Type -eq [System.Windows.Input.TabletDeviceType]::Touch) { $r = $true; break }
        }
    } catch { $r = $false }
    $script:TouchScreenCache = $r
    return $r
}

# Saf: ayardaki anahtardan etkin kip (Normal | Large); $HasTouch Otomatik icin dokunmatik ekran var mi
function Get-TouchMode([string]$Key, [bool]$HasTouch) {
    $k = ConvertTo-TouchKey $Key
    if ($k -eq 'Auto') { if ($HasTouch) { return 'Large' }; return 'Normal' }
    return $k
}

# Saf: kip ve yerlesime gore alt sinir (px)
function Get-TouchMin([string]$Mode, [string]$Layout) {
    if ($Mode -ne 'Large') { return 24.0 }
    if ($Layout -eq 'Kompakt') { return 32.0 }
    return 40.0
}

function Set-TouchTargets([string]$Layout = '') {
    if ($Layout -eq '') { $Layout = [string]$script:LayoutName }
    $key = ConvertTo-TouchKey ([string]$script:Settings.TouchTargets)
    $hasTouch = $false
    if ($key -eq 'Auto') { $hasTouch = Test-TouchScreen }
    $mode = Get-TouchMode $key $hasTouch
    $min = Get-TouchMin $mode $Layout
    $btn = 0.0
    if ($mode -eq 'Large') { $btn = $min }
    $res = $script:Win.Resources
    $res['TouchMin'] = [double]$min
    $res['TouchBtnMin'] = [double]$btn
    $script:TouchMode = $mode
    $script:TouchMinNow = $min
    # sol menu dugmelerinin yuksekligi de alt siniri izler (Get-RailHeight $script:TouchMinNow'u okur)
    try { $script:RailH = 0; Update-RailDensity } catch { }
}

function Initialize-Scrolling {
    if ($script:ScrollReady) { return }
    $script:ScrollReady = $true
    $w = $script:Win

    # dokunmatik ekran: tum kaydiricilar parmakla suruklenebilir
    try {
        [System.Windows.EventManager]::RegisterClassHandler([System.Windows.Controls.ScrollViewer], [System.Windows.FrameworkElement]::LoadedEvent, [System.Windows.RoutedEventHandler]{
            param($s, $e)
            try { $s.PanningMode = [System.Windows.Controls.PanningMode]::VerticalOnly } catch { }
        })
    } catch { Write-CrashLog (('Dokunmatik kayd' + [char]0x0131 + 'rma kurulamad' + [char]0x0131 + ': ') + $_.Exception.Message) }

    $w.Add_PreviewMouseWheel({ param($s, $e) try { Invoke-WheelRoute $e } catch { Write-ScrollErr 'Tekerlek' $_ } })
    $w.Add_PreviewKeyDown({ param($s, $e) try { Invoke-KeyRoute $e } catch { Write-ScrollErr ('Tu' + [char]0x015F + '') $_ } })
    $w.Add_PreviewMouseDown({ param($s, $e) try { $script:KbNav = $false; Update-FocusRing } catch { } })
    $w.Add_PreviewTouchDown({ param($s, $e) try { $script:KbNav = $false; Update-FocusRing } catch { } })

    try {
        $w.AddHandler([System.Windows.UIElement]::GotKeyboardFocusEvent, [System.Windows.Input.KeyboardFocusChangedEventHandler]{
            param($s, $e)
            try { $script:Win.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Render, [Action]{ try { Update-FocusRing } catch { } }) | Out-Null } catch { }
        })
        $w.AddHandler([System.Windows.Controls.ScrollViewer]::ScrollChangedEvent, [System.Windows.Controls.ScrollChangedEventHandler]{
            param($s, $e)
            try {
                if ([double]$e.VerticalChange -ne 0) {
                    Update-ToTop $e.OriginalSource
                    if ($null -ne $script:FocusRingBox -and $script:FocusRingBox.Visibility -eq $script:VisOn) { Update-FocusRing }
                }
            } catch { }
        })
    } catch { Write-CrashLog (('Kayd' + [char]0x0131 + 'rma olaylar' + [char]0x0131 + ' kurulamad' + [char]0x0131 + ': ') + $_.Exception.Message) }

    # sayfa alani odak alabilir: bos bir yere tiklayinca ok tuslari / PageDown sayfayi kaydirir
    try {
        $ui.PageHost.Focusable = $true
        $ui.PageHost.FocusVisualStyle = $null
        $ui.PageHost.Add_PreviewMouseDown({ param($s, $e) try { if (-not (Test-InteractiveSource $e.OriginalSource)) { Focus-PageHost } } catch { } })
        foreach ($k in @($script:PageTitles.Keys)) {
            $rb = $ui['Rail_' + [string]$k]
            if ($null -ne $rb) {
                $rb.Add_PreviewMouseLeftButtonUp({
                    param($s, $e)
                    try { $script:Win.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Input, [Action]{ Focus-PageHost }) | Out-Null } catch { }
                })
            }
        }
    } catch { Write-CrashLog (('Sayfa oda' + [char]0x011F + '' + [char]0x0131 + ' kurulamad' + [char]0x0131 + ': ') + $_.Exception.Message) }

    try { Initialize-ToTop } catch { Write-CrashLog (('Ba' + [char]0x015F + 'a d' + [char]0x00F6 + 'n d' + [char]0x00FC + '' + [char]0x011F + 'mesi kurulamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    try { Initialize-FocusRing } catch { Write-CrashLog (('Odak ' + [char]0x00E7 + 'er' + [char]0x00E7 + 'evesi kurulamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
}


# ---------------- Tepsi ----------------
# ==================================================================
#  TEPSI (SAG ALT BILDIRIM ALANI): simge durumuna kucultme ve kapatma
#  - Simge durumuna kucultunce ya da X'e basinca / Alt+F4 yapinca pencere tepsiye iner; izleme, suren islem ve zamanlayicilar calismaya devam eder.
#  - Tamamen kapatmak icin: sag ustteki guc dugmesi, Ctrl+Q ya da tepsi simgesinin menusundeki "Tamamen kapat".
#  - Iki davranis Ayarlar'dan ayri ayri kapatilabilir (kapaliyken X uygulamayi kapatir, kucultme gorev cubuguna iner).
#  - Windows oturumu kapanirken (kapatma, oturumu kapatma) tepsi davranisi devreye girmez; uygulama engel olmaz.
#  Bu islevler eski surumdeki ayni adli tanimlarin yerini alir (ana betikteki eski tanimlar kaldirildi).
# ==================================================================

# Pencerenin tepsiye inmeden onceki durumu (Normal / Maximized); geri gelirken ayni boyuta donulur
$script:LastShownState = 'Normal'
$script:TrayBusyHintAt = [datetime]::MinValue
$script:TrayRestoring = $false

# X dugmesi tepsiye mi indirsin?
function Get-TrayOnClose {
    return ($script:Settings.TrayMinimize -eq $true)
}

# Simge durumuna kucultmek tepsiye mi indirsin? Ayar hic secilmediyse (null) X dugmesinin ayarini izler.
function Get-TrayOnMinimize {
    $v = $script:Settings.TrayOnMinimize
    if ($null -eq $v) { return ($script:Settings.TrayMinimize -eq $true) }
    return ($v -eq $true)
}

# X dugmesi / Alt+F4: tepsi aciksa pencere tepsiye iner ve calisma (suren islem dahil) arka planda surer.
# Tepsi kapaliysa: islem suruyorsa once sorulur, yoksa uygulama kapanir.
function Invoke-CloseRequest {
    if ($null -ne $script:Tray -and (Get-TrayOnClose)) { Hide-ToTray; return }
    if (Test-AsyncBusy) {
        Show-Confirm ('' + [char]0x0130 + '' + [char]0x015F + 'lem s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor') ('Devam eden i' + [char]0x015F + 'lem iptal edilip uygulama kapat' + [char]0x0131 + 'ls' + [char]0x0131 + 'n m' + [char]0x0131 + '?') 'Kapat' { Exit-App } $true
        return
    }
    Exit-App
}

# Pencereyi gizler. Ilk iki kez (kalici sayac) ve suren bir islem varken simgenin nasil acilip kapatilacagi bildirimle soylenir.
function Hide-ToTray {
    if ($null -eq $script:Tray) { return }
    try {
        $st = [string]$script:Win.WindowState
        if ($st -ne 'Minimized') { $script:LastShownState = $st }
        $script:Win.Hide()
        $busy = $false
        try { $busy = [bool](Test-AsyncBusy) } catch { $busy = $false }
        $hints = 0
        try { $hints = [int]$script:Settings.TrayHints } catch { $hints = 0 }
        $text = ''
        if ($busy -and ((Get-Date) - $script:TrayBusyHintAt).TotalSeconds -gt 120) {
            $script:TrayBusyHintAt = Get-Date
            $text = ('S' + [char]0x00FC + 'ren i' + [char]0x015F + 'lem arka planda tamamlanacak. A' + [char]0x00E7 + 'mak i' + [char]0x00E7 + 'in simgeye t' + [char]0x0131 + 'klay' + [char]0x0131 + 'n; tamamen kapatmak i' + [char]0x00E7 + 'in sa' + [char]0x011F + ' t' + [char]0x0131 + 'klay' + [char]0x0131 + 'p "Tamamen kapat" deyin.')
        } elseif ((-not $script:TrayHintShown) -and $hints -lt 2) {
            $script:TrayHintShown = $true
            $text = ('Arka planda ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'maya devam ediyor. A' + [char]0x00E7 + 'mak i' + [char]0x00E7 + 'in simgeye t' + [char]0x0131 + 'klay' + [char]0x0131 + 'n; tamamen kapatmak i' + [char]0x00E7 + 'in sa' + [char]0x011F + ' t' + [char]0x0131 + 'klay' + [char]0x0131 + 'p "Tamamen kapat" deyin.')
            Set-SettingsKeys @{ TrayHints = ($hints + 1) }
        }
        if ($text -ne '') { $script:Tray.ShowBalloonTip(4000, 'Multimizer', (Tr $text), [System.Windows.Forms.ToolTipIcon]::Info) }
    } catch { Write-CrashLog ('Hide-ToTray: ' + $_.Exception.Message) }
}

# Geri getirme surerken pencere durumu olaylari (Show cagrisinin tetikleyebilecegi "kucultuldu") pencereyi yeniden gizlemesin
function Restore-FromTray {
    $script:TrayRestoring = $true
    try {
        $w = $script:Win
        $w.ShowInTaskbar = $true
        $w.Show()
        if ($w.WindowState -eq [System.Windows.WindowState]::Minimized) {
            if ($script:LastShownState -eq 'Maximized') { $w.WindowState = [System.Windows.WindowState]::Maximized }
            else { $w.WindowState = [System.Windows.WindowState]::Normal }
        }
        [void]$w.Activate()
        $w.Topmost = $true
        $w.Topmost = $false
        [void]$w.Focus()
    } catch {
        Write-CrashLog ('Restore-FromTray: ' + $_.Exception.Message)
    } finally {
        $script:TrayRestoring = $false
    }
}

# Pencere durumu degisti (Normal / Buyutulmus / Simge durumu): kenar boslugu ve tepsi davranisi
function Invoke-WindowStateChanged {
    $w = $script:Win
    $st = $w.WindowState
    if ($st -eq [System.Windows.WindowState]::Maximized) {
        $script:LastShownState = 'Maximized'
        if (-not $script:ChromeFallback) {
            $t = [System.Windows.SystemParameters]::WindowResizeBorderThickness
            $ui.Root.Margin = New-Object System.Windows.Thickness -ArgumentList $t.Left, $t.Top, $t.Right, $t.Bottom
        }
        return
    }
    $ui.Root.Margin = New-Object System.Windows.Thickness -ArgumentList 0
    if ($st -eq [System.Windows.WindowState]::Normal) { $script:LastShownState = 'Normal'; return }
    if ($st -eq [System.Windows.WindowState]::Minimized -and -not $script:TrayRestoring -and (Get-TrayOnMinimize) -and $null -ne $script:Tray) { Hide-ToTray }
}


# ---------------- Duyarli yerlesim ----------------
# ==================================================================
#  DUYARLI YERLESIM: pencere kuculunce ya da yakinlastirma artinca icerik sikismasin
#  - Baslik cubugu: sigmayan ogeler sirayla gizlenir (slogan, sayfa adi kutusunun alt siniri, etiketler)
#  - Islem gunlugu: sayfaya yeterli genislik kalmiyorsa kendiliginden kapanir; yer acilinca (kendiliginden kapandiysa) geri acilir
#  - Komut satiri: sayfaya yeterli yukseklik kalmiyorsa kendiliginden kapanir; yer acilinca (kendiliginden kapandiysa) geri acilir
#  - Durum panosu: sayfa dar kalinca sagdaki arac sutunu altina iner
#  Yalnizca bu pencerenin gorunumudur; sistem ayarina dokunmaz. Kullanici bir paneli elle acip kapatirsa o secim gecerlidir.
#  Kararlar yalnizca pencere boyutuna, yakinlastirmaya ve yerlesime baglidir (panelin o anki durumuna degil): acilip kapanma titremez.
#  Surekli calisan bir dongu yoktur; hesap yalnizca boyut, yakinlastirma ve yerlesim degisince (kisa bir bekleme sonrasi) yapilir.
# ==================================================================

$script:RespMinPageW = 700       # sayfa alani (yakinlastirma sonrasi, px) bundan darsa islem gunlugu kapanir
$script:RespMinPageH = 450       # sayfa alani bundan kisaysa komut satiri kapanir
$script:RespWidePage = 940       # durum panosu iki sutun icin en az bu genisligi ister (4 gosterge cemberi 108 px sutun ister; daha darsa tek sutun)
$script:RespChromeH = 74         # baslik cubugu 46 + durum cubugu 26 + cerceve 2
$script:RespPageMargin = 16      # sayfa alaninin sag ve sol bosluklari (8 + 8)
$script:RespLogFits = $true
$script:RespCmdFits = $true
$script:LogAutoOff = $false      # gunluk kendiliginden kapandi (yer acilinca geri acilir)
$script:CmdAutoOff = $false      # komut satiri kendiliginden kapandi (yer acilinca geri acilir)
$script:RespBusy = $false
$script:RespTimer = $null
$script:RespHinted = @{}
$script:TitleNat = $null
$script:TitleLevel = 0

# ---------------- saf hesaplar (ekrana dokunmaz; testlerde de kullanilir) ----------------

# Sayfa alaninin genisligi: pencere (kenarlik dusulur) yakinlastirmaya bolunur; sol menu, acik gunluk ve sayfa bosluklari cikarilir
function Get-PageWidth([double]$WinW, [double]$Zoom, [double]$Rail, [double]$Log) {
    if ($Zoom -le 0) { $Zoom = 1.0 }
    return [math]::Round((($WinW - 2) / $Zoom) - $Rail - $Log - [double]$script:RespPageMargin)
}

# Sayfa alaninin yuksekligi: baslik ve durum cubugu dusulur, yakinlastirmaya bolunur; ust bosluk ve (acik) komut satiri cikarilir
function Get-PageHeight([double]$WinH, [double]$Zoom, [double]$Cmd) {
    if ($Zoom -le 0) { $Zoom = 1.0 }
    return [math]::Round((($WinH - [double]$script:RespChromeH) / $Zoom) - 8 - $Cmd)
}

# Gunluk acikken sayfaya yeterli genislik kaliyor mu? LogOpen: gunlugun acilinca alacagi genislik
function Test-LogFits([double]$WinW, [double]$Zoom, [double]$Rail, [double]$LogOpen) {
    return ((Get-PageWidth $WinW $Zoom $Rail $LogOpen) -ge [double]$script:RespMinPageW)
}

# Komut satiri acikken sayfaya yeterli yukseklik kaliyor mu? CmdH: komut satirinin yuksekligi (kenar bosluklari eklenir)
function Test-CmdFits([double]$WinH, [double]$Zoom, [double]$CmdH) {
    return ((Get-PageHeight $WinH $Zoom ($CmdH + 16)) -ge [double]$script:RespMinPageH)
}

# Durum panosu tek sutuna insin mi?
function Test-PanelNarrow([double]$PageW) {
    return ($PageW -lt [double]$script:RespWidePage)
}

# Baslik cubugunda kac basamak sadelestirme gerekir? 0 = hepsi gorunur, 1 = slogan gizli, 2 = sayfa adi kutusu daralir, 3 = etiketler de gizli.
# N: tum ogeler gorunurken olculen dogal genislikler (L sol blok, C orta blok, R sag blok, Tag slogan, Pill kutunun kazanci, Lab etiketler)
function Get-TitleLevel([double]$W, $N) {
    $avail = $W - 2 - 12
    $need = [double]$N.L + [double]$N.C + [double]$N.R
    if ($need -le $avail) { return 0 }
    $need = $need - [double]$N.Tag
    if ($need -le $avail) { return 1 }
    $need = $need - [double]$N.Pill
    if ($need -le $avail) { return 2 }
    return 3
}

# ---------------- pencere olculeri ----------------
function Get-WinSize {
    $w = 0.0
    $h = 0.0
    try { $w = [double]$script:Win.ActualWidth; $h = [double]$script:Win.ActualHeight } catch { }
    if ($w -lt 100) { try { $w = [double]$script:Win.Width } catch { $w = 1380.0 } }
    if ($h -lt 100) { try { $h = [double]$script:Win.Height } catch { $h = 840.0 } }
    if ([double]::IsNaN($w) -or $w -lt 100) { $w = 1380.0 }
    if ([double]::IsNaN($h) -or $h -lt 100) { $h = 840.0 }
    return @($w, $h)
}

function Get-OpenLogWidth {
    $v = 0.0
    try { if ($ui.ColLog.Width.Value -gt 10) { $v = [double]$ui.ColLog.Width.Value } } catch { }
    return $v
}

# Sayfa alaninin su anki genisligi (acik gunluk hesaba katilir)
function Get-CurrentPageWidth {
    $sz = Get-WinSize
    return (Get-PageWidth ([double]$sz[0]) ([double]$script:UiZoom) ([double](Get-RailWidth ([string]$script:RailMode))) (Get-OpenLogWidth))
}

# ---------------- baslik cubugu ----------------
function Set-TitleLevel([int]$Level) {
    $script:TitleLevel = $Level
    $tag = ($Level -lt 1)
    if ($null -ne $ui.TxtTagline) { Set-Visible $ui.TxtTagline $tag }
    if ($null -ne $ui.TxtTitleSep) { Set-Visible $ui.TxtTitleSep $tag }
    if ($null -ne $ui.TitlePill) {
        if ($Level -ge 2) { $ui.TitlePill.MinWidth = 120 } else { $ui.TitlePill.MinWidth = 190 }
    }
    $lab = ($Level -lt 3)
    if ($null -ne $ui.TxtJobLbl) { Set-Visible $ui.TxtJobLbl $lab }
    if ($null -ne $ui.TxtConnLbl) { Set-Visible $ui.TxtConnLbl $lab }
    if ($null -ne $ui.TxtLangCode) { Set-Visible $ui.TxtLangCode ($Level -lt 2) }
    if ($null -ne $ui.TxtAskHint) { Set-Visible $ui.TxtAskHint ($Level -lt 1) }
}

# Tum ogeler gorunurken bloklarin dogal genisligini olcer (yerlesim, yani yazi tipi degisince yeniden olculur)
function Measure-TitleNatural {
    Set-TitleLevel 0
    try { $script:Win.UpdateLayout() } catch { }
    $l = 0.0; $c = 0.0; $r = 0.0
    try {
        $l = [double]$ui.TitleLeft.DesiredSize.Width
        $c = [double]$ui.TitleCenter.DesiredSize.Width
        $r = [double]$ui.TitleRight.DesiredSize.Width
    } catch { return }
    if ($l -lt 20 -or $c -lt 20 -or $r -lt 20) { return }
    $tag = [double]$ui.TxtTagline.DesiredSize.Width + [double]$ui.TxtTitleSep.DesiredSize.Width
    $lab = [double]$ui.TxtJobLbl.DesiredSize.Width + [double]$ui.TxtConnLbl.DesiredSize.Width
    $gain = 40.0
    try { if ($null -ne $ui.TxtLangCode) { $gain = $gain + [double]$ui.TxtLangCode.DesiredSize.Width + [double]$ui.TxtLangCode.Margin.Left } } catch { }
    try { if ($null -ne $ui.TxtAskHint) { $tag = $tag + [double]$ui.TxtAskHint.DesiredSize.Width + [double]$ui.TxtAskHint.Margin.Left + [double]$ui.TxtAskHint.Margin.Right } } catch { }
    $script:TitleNat = @{ L = $l; C = $c; R = $r; Tag = $tag; Pill = $gain; Lab = $lab }
}

function Update-TitleFit {
    if ($null -eq $ui.TitleLeft -or $null -eq $ui.TitleCenter -or $null -eq $ui.TitleRight) { return }
    if ($null -eq $script:TitleNat) { Measure-TitleNatural }
    if ($null -eq $script:TitleNat) { return }
    $sz = Get-WinSize
    $lv = Get-TitleLevel ([double]$sz[0]) $script:TitleNat
    if ($lv -ne [int]$script:TitleLevel) { Set-TitleLevel $lv }
}

# ---------------- islem gunlugu ve komut satiri ----------------
function Show-RespHint([string]$Which) {
    if ($script:RespHinted.ContainsKey($Which)) { return }
    $script:RespHinted[$Which] = $true
    try {
        if ($Which -eq 'log') { Show-Toast ('Pencere dar oldu' + [char]0x011F + 'u i' + [char]0x00E7 + 'in i' + [char]0x015F + 'lem g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' gizlendi. Sa' + [char]0x011F + ' ' + [char]0x00FC + 'stteki liste d' + [char]0x00FC + '' + [char]0x011F + 'mesiyle a' + [char]0x00E7 + 'abilirsiniz.') 'info' }
        else { Show-Toast ('Pencere k' + [char]0x0131 + 'sa oldu' + [char]0x011F + 'u i' + [char]0x00E7 + 'in komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' gizlendi. Sa' + [char]0x011F + ' ' + [char]0x00FC + 'stteki terminal d' + [char]0x00FC + '' + [char]0x011F + 'mesiyle (Ctrl+K) a' + [char]0x00E7 + 'abilirsiniz.') 'info' }
    } catch { }
}

function Update-ResponsivePanels {
    $sz = Get-WinSize
    $zoom = [double]$script:UiZoom
    $rail = [double](Get-RailWidth ([string]$script:RailMode))
    $d = Get-LayoutDefaults ([string]$script:LayoutName)

    $logFits = [bool](Test-LogFits ([double]$sz[0]) $zoom $rail ([double]$script:LogOpenWidth))
    if ($logFits -ne [bool]$script:RespLogFits) {
        $script:RespLogFits = $logFits
        if (-not $logFits) {
            if ($ui.ColLog.Width.Value -gt 10) {
                $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList 0
                $script:LogAutoOff = $true
                Show-RespHint 'log'
            }
        } elseif ($script:LogAutoOff -eq $true) {
            $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList ([double]$script:LogOpenWidth)
            $script:LogAutoOff = $false
        }
    }

    $cmdFits = [bool](Test-CmdFits ([double]$sz[1]) $zoom ([double]$d.CmdH))
    if ($cmdFits -ne [bool]$script:RespCmdFits) {
        $script:RespCmdFits = $cmdFits
        if (-not $cmdFits) {
            if ($ui.CmdPanel.Visibility -eq $script:VisOn) {
                Set-Visible $ui.CmdPanel $false
                try { $ui.CmdPop.IsOpen = $false } catch { }
                $script:CmdAutoOff = $true
                Show-RespHint 'cmd'
            }
        } elseif ($script:CmdAutoOff -eq $true) {
            Set-Visible $ui.CmdPanel $true
            $script:CmdAutoOff = $false
        }
    }
}

# Islem baslayinca gunluk kendiliginden acilsin mi? Yalnizca gunlugun varsayilan olarak acik oldugu yerlesimlerde (ayrintili, hacker)
# ve pencere yeterince genisken. Kompakt ve sade yerlesimde gunluk istenmedikce acilmaz (ilerleme durum cubugunda gorunur).
function Test-LogAutoOpen {
    if ($script:RespLogFits -ne $true) { return $false }
    $d = Get-LayoutDefaults ([string]$script:LayoutName)
    return ([double]$d.Log -gt 0)
}

# Basliktaki dugmeyle gunlugu elle ac / kapat: kullanicinin secimi kendiliginden kapanma durumunu sifirlar
function Switch-LogPanel {
    if ($ui.ColLog.Width.Value -gt 10) { $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList 0 }
    else { $ui.ColLog.Width = New-Object System.Windows.GridLength -ArgumentList ([double]$script:LogOpenWidth) }
    $script:LogAutoOff = $false
    try { Update-PanelReflow } catch { }
}

# ---------------- durum panosu: dar sayfada tek sutun ----------------
function Set-PanelReflow($Root) {
    if ($null -eq $Root) { return }
    $g = $Root.Content
    if (($g -isnot [System.Windows.Controls.Grid]) -or $g.Children.Count -lt 2 -or $g.ColumnDefinitions.Count -lt 2) { return }
    $right = $g.Children[1]
    $narrow = [bool](Test-PanelNarrow (Get-CurrentPageWidth))
    $isNarrow = ([System.Windows.Controls.Grid]::GetRow($right) -eq 1)
    if ($narrow -eq $isNarrow) { return }
    if ($narrow) {
        $g.ColumnDefinitions[1].Width = New-Object System.Windows.GridLength -ArgumentList 0
        $g.RowDefinitions.Clear()
        for ($i = 0; $i -lt 2; $i++) {
            $rd = New-Object System.Windows.Controls.RowDefinition
            $rd.Height = [System.Windows.GridLength]::Auto
            [void]$g.RowDefinitions.Add($rd)
        }
        [System.Windows.Controls.Grid]::SetColumn($right, 0)
        [System.Windows.Controls.Grid]::SetRow($right, 1)
        $right.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 0, 10, 0
    } else {
        $g.RowDefinitions.Clear()
        $g.ColumnDefinitions[1].Width = New-Object System.Windows.GridLength -ArgumentList 316
        [System.Windows.Controls.Grid]::SetRow($right, 0)
        [System.Windows.Controls.Grid]::SetColumn($right, 1)
        $right.Margin = New-Object System.Windows.Thickness -ArgumentList 0
    }
}

function Update-PanelReflow {
    if ($script:Pages.ContainsKey('panel')) { Set-PanelReflow $script:Pages['panel'] }
}

# ---------------- toplu guncelleme ----------------
function Update-Responsive {
    if ($script:RespBusy) { return }
    $script:RespBusy = $true
    try {
        try { Update-ResponsivePanels } catch { Write-CrashLog (('Duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im (paneller): ') + $_.Exception.Message) }
        try { Update-TitleFit } catch { Write-CrashLog (('Duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im (ba' + [char]0x015F + 'l' + [char]0x0131 + 'k): ') + $_.Exception.Message) }
        try { Update-PanelReflow } catch { Write-CrashLog (('Duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im (durum panosu): ') + $_.Exception.Message) }
    } finally { $script:RespBusy = $false }
}

# Yerlesim degisince: varsayilanlar yeniden uygulanmistir; kendiliginden kapanma durumu sifirlanir ve boyuta gore yeniden karar verilir
function Reset-Responsive {
    $script:LogAutoOff = $false
    $script:CmdAutoOff = $false
    $script:RespLogFits = $true
    $script:RespCmdFits = $true
    $script:TitleNat = $null
    Update-Responsive
}

# Boyut degisiklikleri kisa bir beklemeyle birlestirilir (pencere suruklenirken her karede hesap yapilmaz)
function Request-Responsive {
    if ($null -eq $script:RespTimer) { return }
    $script:RespTimer.Stop()
    $script:RespTimer.Start()
}

function Initialize-Responsive {
    $t = New-Object System.Windows.Threading.DispatcherTimer
    $t.Interval = [TimeSpan]::FromMilliseconds(80)
    $t.Add_Tick({
        $script:RespTimer.Stop()
        try { Update-Responsive } catch { Write-CrashLog (('Duyarl' + [char]0x0131 + ' yerle' + [char]0x015F + 'im: ') + $_.Exception.Message) }
    })
    $script:RespTimer = $t
    $script:Win.Add_SizeChanged({ try { Request-Responsive } catch { } })
    # Sol menu dugme yuksekligi, menu alaninin gercek yuksekligi degisince yeniden hesaplanir. Yalnizca pencere boyutuna bagli olsaydi
    # yakinlastirma degisince (pencere ayni kalir, govde olceklenir) eski yukseklikle hesap yapilir ve menu tasardi.
    if ($null -ne $ui['RailHost']) { $ui.RailHost.Add_SizeChanged({ try { Update-RailDensity } catch { } }) }
    Request-Responsive
}


# ---------------- Oturum izi ve guvenli kip ----------------
# ==================================================================
#  OTURUM IZI VE GUVENLI KIP
#  Amac: Windows hata raporlamasi kapaliysa bile (cokme kaydi yazilmaz) "uygulama neden kapandi?" sorusunu kanita dayanarak yanitlamak.
#    oturum.json       calisan oturumun kimligi; duzgun kapanista Durum = 'kapali' yazilir. 'acik' kalmissa onceki oturum beklenmedik bitmistir.
#    oturum-iz.txt     kisa, yalnizca eklenen izler (sayfa gecisi, is, gorunum, pencere durumu, dakikalik nabiz: bellek / tutamac / parcacik)
#    oturum-acik-<k>   Baslat.bat'in "pencere gercekten acilmisti" bilgisini almak icin isaret dosyasi (k = Baslat.bat'in verdigi kod)
#  Beklenmedik bitis bulunursa: iz dosyasi saklanir (oturum-iz-cokme-*.txt), hata kaydina yazilir, bu oturum guvenli kipte acilir
#  (yazilimsal cizim, GPU / sicaklik izleme kapali). Ust uste iki kez olursa guvenli cizim kalici olur (Ayarlar'dan kapatilir).
# ==================================================================

$script:SessFile = ''
$script:TraceFile = ''
$script:TraceBytes = 0
$script:TraceMax = 262144
$script:TraceEnc = New-Object System.Text.UTF8Encoding($true)
$script:SafeMode = $false
$script:PrevCrashed = $false
$script:PrevCrashFile = ''
$script:SafeRenderAuto = $false
$script:SessClosed = $false
$script:OpenMarker = ''
$script:RunToken = ''
$script:SessStart = [DateTime]::UtcNow
$script:SessBeatTimer = $null
$script:MonRestarts = New-Object System.Collections.ArrayList
$script:MonSeenAt = $null
$script:MonGaveUp = $false

# Tek satir iz ekler; hicbir kosulda hata firlatmaz. Oturum basina 256 KB'ta kesilir.
function Add-Trace([string]$Text) {
    try {
        if ([string]::IsNullOrEmpty($script:TraceFile)) { return }
        if ($script:TraceBytes -ge $script:TraceMax) { return }
        $line = (Get-Date -Format 'HH:mm:ss.fff') + '  ' + $Text
        if ($line.Length -gt 600) { $line = $line.Substring(0, 600) }
        $line += "`r`n"
        [System.IO.File]::AppendAllText($script:TraceFile, $line, $script:TraceEnc)
        $script:TraceBytes = $script:TraceBytes + $line.Length
        if ($script:TraceBytes -ge $script:TraceMax) {
            [System.IO.File]::AppendAllText($script:TraceFile, (('(iz dosyas' + [char]0x0131 + ' s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'na ula' + [char]0x015F + 't' + [char]0x0131 + '; yeni sat' + [char]0x0131 + 'r yaz' + [char]0x0131 + 'lmayacak)') + "`r`n"), $script:TraceEnc)
        }
    } catch { }
}

# Baslat.bat'in verdigi kod yalnizca harf / rakam olabilir (dosya adinda kullanilir)
function ConvertTo-RunToken([string]$Text) {
    if ([string]::IsNullOrEmpty($Text)) { return '' }
    if ($Text -cnotmatch '^[A-Za-z0-9]{3,32}$') { return '' }
    return $Text
}

# Onceki oturumun sureci hala calisiyor mu? (surec numarasi yeniden kullanilmis olabilir: baslangic saati de karsilastirilir)
function Test-SessionAlive($Prev) {
    try {
        $id = [int]$Prev.Pid
        if ($id -le 0 -or $id -eq $PID) { return $false }
        $pr = [System.Diagnostics.Process]::GetProcessById($id)
        try {
            $exp = [DateTime]::Parse([string]$Prev.Basladi, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()
            $st = $pr.StartTime.ToUniversalTime()
            return ([math]::Abs(($st - $exp).TotalSeconds) -lt 5)
        } finally { $pr.Dispose() }
    } catch { return $false }
}

function Get-SessionTail([string]$Path, [int]$Count = 12) {
    try {
        if (-not (Test-Path -LiteralPath $Path)) { return @() }
        $all = @([System.IO.File]::ReadAllLines($Path, [System.Text.Encoding]::UTF8))
        if ($all.Count -le $Count) { return $all }
        return @($all[($all.Count - $Count)..($all.Count - 1)])
    } catch { return @() }
}

# Kaydedilen cokme izlerinden yalnizca en yeni 5 tanesi tutulur
function Remove-OldCrashTraces {
    try {
        $fs = @(Get-ChildItem -LiteralPath $script:LogDir -Filter 'oturum-iz-cokme-*.txt' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)
        for ($i = 5; $i -lt $fs.Count; $i++) { try { Remove-Item -LiteralPath $fs[$i].FullName -Force -ErrorAction SilentlyContinue } catch { } }
    } catch { }
}

# Arayuz acilirken bir kez cagrilir: onceki oturumu degerlendirir, yenisini kaydeder, guvenli kip kararini verir.
function Start-SessionTrace {
    $script:SessFile = Join-Path $script:DataDir 'oturum.json'
    $script:TraceFile = Join-Path $script:LogDir 'oturum-iz.txt'
    $script:TraceBytes = 0
    $script:SessClosed = $false
    $script:SessStart = [DateTime]::UtcNow
    $script:PrevCrashed = $false
    $script:PrevCrashFile = ''
    $script:RunToken = ConvertTo-RunToken ([string]$Oturum)
    $prev = $null
    try { if (Test-Path -LiteralPath $script:SessFile) { $prev = ConvertTo-Hashtable (Read-JsonFile $script:SessFile) } } catch { $prev = $null }

    $script:PrevBySystem = $false
    if ($prev -is [hashtable] -and [string]$prev.Durum -eq 'acik' -and -not (Test-SessionAlive $prev) -and (Test-SessionEndedBySystem)) { $script:PrevBySystem = $true; $prev = $null }
    if ($prev -is [hashtable] -and [string]$prev.Durum -eq 'acik' -and -not (Test-SessionAlive $prev)) {
        $script:PrevCrashed = $true
        $when = [DateTime]::Now
        try { if (Test-Path -LiteralPath $script:TraceFile) { $when = (Get-Item -LiteralPath $script:TraceFile).LastWriteTime } } catch { }
        $name = 'oturum-iz-cokme-' + $when.ToString('yyyyMMdd-HHmmss') + '.txt'
        try {
            if (Test-Path -LiteralPath $script:TraceFile) {
                Copy-Item -LiteralPath $script:TraceFile -Destination (Join-Path $script:LogDir $name) -Force -ErrorAction Stop
                $script:PrevCrashFile = $name
            }
        } catch { }
        $tail = @(Get-SessionTail $script:TraceFile 10)
        $msg = ('' + [char]0x00D6 + 'nceki oturum beklenmedik bi' + [char]0x00E7 + 'imde sona erdi (PID ') + [string]$prev.Pid + (', s' + [char]0x00FC + 'r' + [char]0x00FC + 'm ') + [string]$prev.Surum + (', ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' ') + [string]$prev.Basladi + ', son iz ' + $when.ToString('dd.MM.yyyy HH:mm:ss') + ').'
        if ($script:PrevCrashFile -ne '') { $msg += (' ' + [char]0x0130 + 'z dosyas' + [char]0x0131 + ': ') + $script:PrevCrashFile + '.' }
        if ($tail.Count -gt 0) { $msg += ' Son izler: ' + (($tail | ForEach-Object { ([string]$_).Trim() }) -join ' | ') }
        Write-CrashLog $msg
        Remove-OldCrashTraces
    }
    # yeni oturumun izi temiz baslar
    try { if (Test-Path -LiteralPath $script:TraceFile) { Remove-Item -LiteralPath $script:TraceFile -Force -ErrorAction SilentlyContinue } } catch { }

    # guvenli kip karari
    $streak = 0
    try { $streak = [int]$script:Settings.CrashStreak } catch { $streak = 0 }
    if ($script:PrevCrashed) { $streak++ }
    $persist = ($script:Settings.SafeRender -eq $true)
    $keys = @{}
    if ($script:PrevCrashed) {
        $keys['CrashStreak'] = $streak
        if ($streak -ge 2 -and -not $persist) { $persist = $true; $script:SafeRenderAuto = $true; $keys['SafeRender'] = $true }
    }
    if ($keys.Count -gt 0) { Set-SettingsKeys $keys }
    $persist = Update-SafeModeState $persist
    $script:SafeMode = ($persist -or $script:PrevCrashed -or ($Guvenli -eq $true))
    $sync.SafeMon = $script:SafeMode
    if ($script:PrevBySystem) { Add-Trace 'onceki oturum bilgisayar kapanirken sona erdi (cokme sayilmadi)' }
    $sync.NoGpu = ($script:Settings.MonGpu -eq $false)

    # bu oturumun kaydi
    $startIso = ''
    try { $pr = [System.Diagnostics.Process]::GetCurrentProcess(); try { $startIso = $pr.StartTime.ToUniversalTime().ToString('o') } finally { $pr.Dispose() } } catch { $startIso = [DateTime]::UtcNow.ToString('o') }
    $sess = @{ Durum = 'acik'; Pid = $PID; Basladi = $startIso; Surum = [string]$script:AppVersion; Guvenli = $script:SafeMode; Yonetici = [bool]$script:IsAdmin; Kod = $script:RunToken }
    try { Save-JsonFile $sess $script:SessFile 3 } catch { }

    $tier = ''
    try { $tier = [string]([System.Windows.Media.RenderCapability]::Tier -shr 16) } catch { $tier = '?' }
    Add-Trace (('oturum ba' + [char]0x015F + 'lad' + [char]0x0131 + ': s' + [char]0x00FC + 'r' + [char]0x00FC + 'm ') + [string]$script:AppVersion + ' PID ' + $PID + (' y' + [char]0x00F6 + 'netici=') + [string]$script:IsAdmin + (' g' + [char]0x00FC + 'venli=') + [string]$script:SafeMode + (' ' + [char]0x00E7 + 'izim-katman' + [char]0x0131 + '=') + $tier + ' PS ' + $PSVersionTable.PSVersion.ToString() + (' i' + [char]0x015F + 'lemci=') + [string][Environment]::ProcessorCount)
    if ($script:PrevCrashed) { Add-Trace (('' + [char]0x00F6 + 'nceki oturum beklenmedik bitmi' + [char]0x015F + 'ti (art arda ') + $streak + ')') }
}

# Pencere olusturulmadan once cagrilir: guvenli kipte WPF yalnizca yazilimla cizer (ekran karti surucusu kaynakli cokmelere karsi)
function Set-RenderMode {
    if ($script:SafeMode -ne $true) { return }
    try {
        [System.Windows.Media.RenderOptions]::ProcessRenderMode = [System.Windows.Interop.RenderMode]::SoftwareOnly
        Add-Trace ('' + [char]0x00E7 + 'izim: yaln' + [char]0x0131 + 'zca yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'm (SoftwareOnly)')
    } catch { Add-Trace (('' + [char]0x00E7 + 'izim kipi ayarlanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
}

# Pencere acilinca: Baslat.bat'in okuyacagi isaret dosyasi ve dakikalik nabiz
function Set-SessionOpen {
    try {
        if ($script:RunToken -ne '' -and -not $script:SmokeMode) {
            $script:OpenMarker = Join-Path $script:DataDir ('oturum-acik-' + $script:RunToken + '.txt')
            [System.IO.File]::WriteAllText($script:OpenMarker, ([string]$PID + ' ' + [DateTime]::UtcNow.ToString('o')), $script:TraceEnc)
        }
    } catch { }
    Add-Trace ('pencere a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '')
    try { Add-Trace (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + ' s' + [char]0x00FC + 'releri (ms): ') + (Get-StartupTimingText)) } catch { }
    try {
        $script:SessBeatTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:SessBeatTimer.Interval = [TimeSpan]::FromSeconds(60)
        $script:SessBeatTimer.Add_Tick({ Write-SessionBeat })
        $script:SessBeatTimer.Start()
    } catch { }
    try { Start-SystemThemeWatch } catch { }
    Write-SessionBeat
    if ($script:PrevCrashed) {
        try {
            Write-WhLog ('' + [char]0x00D6 + 'nceki oturum beklenmedik bi' + [char]0x00E7 + 'imde kapanm' + [char]0x0131 + '' + [char]0x015F + '. Bu oturum g' + [char]0x00FC + 'venli kipte (yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'msal ' + [char]0x00E7 + 'izim, GPU / s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k izleme kapal' + [char]0x0131 + ') ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor.') 'WARN'
            if ($script:PrevCrashFile -ne '') { Write-WhLog (('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ': Kay' + [char]0x0131 + 'tlar\') + $script:PrevCrashFile) 'WARN' }
            Show-Toast ('' + [char]0x00D6 + 'nceki oturum beklenmedik bi' + [char]0x00E7 + 'imde kapanm' + [char]0x0131 + '' + [char]0x015F + '. Bu oturum g' + [char]0x00FC + 'venli kipte ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn'
            if ($script:SafeRenderAuto) { Write-WhLog ('Art arda ikinci beklenmedik kapanma: g' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim kal' + [char]0x0131 + 'c' + [char]0x0131 + ' yap' + [char]0x0131 + 'ld' + [char]0x0131 + '. Ayarlar > G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nden kapatabilirsiniz.') 'WARN' }
        } catch { }
    }
}

function Write-SessionBeat {
    try {
        $p = [System.Diagnostics.Process]::GetCurrentProcess()
        $ws = 0; $pv = 0; $hc = 0; $th = 0
        try { $ws = [int]($p.WorkingSet64 / 1MB); $pv = [int]($p.PrivateMemorySize64 / 1MB); $hc = [int]$p.HandleCount; $th = [int]$p.Threads.Count } finally { $p.Dispose() }
        $age = -1
        try { if ($null -ne $sync.MonBeat) { $age = [int]([DateTime]::UtcNow - [DateTime]$sync.MonBeat).TotalSeconds } } catch { }
        $gc = [int]([GC]::GetTotalMemory($false) / 1MB)
        $mi = ''
        $d = $sync.MonDiag
        if ($d -is [hashtable]) { $mi = ' tur=' + [string]$d.Tick + ' ' + [string]$d.Ms + 'ms gpuHata=' + [string]$d.GpuFail + (' ' + [char]0x0131 + 's' + [char]0x0131 + 'Hata=') + [string]$d.TempFail + (' a' + [char]0x011F + 'Hata=') + [string]$d.NetFail }
        $pg = ''
        try { $pg = [string]$script:UiState.Page } catch { }
        Add-Trace (('nab' + [char]0x0131 + 'z: bellek=') + $ws + ('MB ' + [char]0x00F6 + 'zel=') + $pv + ('MB tutama' + [char]0x00E7 + '=') + $hc + (' par' + [char]0x00E7 + 'ac' + [char]0x0131 + 'k=') + $th + (' y' + [char]0x00F6 + 'netilen=') + $gc + 'MB izleme=' + $age + 'sn' + $mi + ' sayfa=' + $pg)
    } catch { }
}

# Duzgun kapanis (ya da Windows oturumu kapaniyor): kayit 'kapali' yazilir; Baslat.bat isaret dosyasi silinir
function Stop-SessionTrace([string]$Why = 'normal') {
    if ($script:SessClosed) { return }
    $script:SessClosed = $true
    try { Step-CleanStreak } catch { }
    try { if ($null -ne $script:SessBeatTimer) { $script:SessBeatTimer.Stop() } } catch { }
    Add-Trace (('oturum kapand' + [char]0x0131 + ': ') + $Why)
    try {
        $sess = @{ Durum = 'kapali'; Pid = $PID; Kapandi = [DateTime]::UtcNow.ToString('o'); Neden = $Why; Surum = [string]$script:AppVersion }
        Save-JsonFile $sess $script:SessFile 3
    } catch { }
    try { if ($script:OpenMarker -ne '') { Remove-Item -LiteralPath $script:OpenMarker -Force -ErrorAction SilentlyContinue } } catch { }
    try { if ([int]$script:Settings.CrashStreak -ne 0) { Set-SettingsKeys @{ CrashStreak = 0 } } } catch { }
}

# Izleme is parcacigi kapanmissa ya da 60 sn nabiz vermediyse yeniden baslatir (10 dakikada en cok 3 kez)
function Test-MonitorAlive {
    $w = $script:MonWork
    if ($null -eq $w -or $script:MonStarter -eq $true -or $null -eq $w.RunAr) { return }
    if ($sync.Stop -eq $true -or $script:Quitting -eq $true -or $script:MonGaveUp) { return }
    $now = [DateTime]::UtcNow
    if ($null -eq $script:MonSeenAt) { $script:MonSeenAt = $now }
    $why = ''
    try { if ($w.RunAr.IsCompleted) { $why = ('i' + [char]0x015F + ' sonlanm' + [char]0x0131 + '' + [char]0x015F + '') } } catch { }
    if ($why -eq '') {
        $b = $sync.MonBeat
        if ($null -ne $b) { if (($now - [DateTime]$b).TotalSeconds -gt 60) { $why = ('nab' + [char]0x0131 + 'z yok') } }
        elseif (($now - $script:MonSeenAt).TotalSeconds -gt 90) { $why = ('ilk ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm gelmedi') }
    }
    if ($why -eq '') { return }
    for ($i = $script:MonRestarts.Count - 1; $i -ge 0; $i--) { if (($now - [DateTime]$script:MonRestarts[$i]).TotalMinutes -gt 10) { $script:MonRestarts.RemoveAt($i) } }
    if ($script:MonRestarts.Count -ge 3) {
        $script:MonGaveUp = $true
        Add-Trace (('izleme 10 dakikada 3 kez yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + '; vazge' + [char]0x00E7 + 'ildi (') + $why + ')')
        Write-WhLog ('Canl' + [char]0x0131 + ' izleme tekrar tekrar durdu; yeniden ba' + [char]0x015F + 'latma b' + [char]0x0131 + 'rak' + [char]0x0131 + 'ld' + [char]0x0131 + '. G' + [char]0x00F6 + 'stergeler son de' + [char]0x011F + 'erde kalabilir.') 'WARN'
        return
    }
    [void]$script:MonRestarts.Add($now)
    Add-Trace (('izleme yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor: ') + $why)
    Write-WhLog (('Canl' + [char]0x0131 + ' izleme yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + ' (') + $why + ').') 'WARN'
    try { [void]$w.Run.BeginStop($null, $null) } catch { }
    try { [void]$w.Rs.CloseAsync() } catch { }
    $script:MonWork = $null
    $script:MonSeenAt = $null
    $sync.MonBeat = $null
    Start-Monitor
}

# Pencere olaylari iz birakir (cokme anindan onceki son durumu gormek icin)
function Initialize-SessionHooks {
    try {
        $w = $script:Win
        $w.Add_StateChanged({ Add-Trace ('pencere durumu: ' + [string]$script:Win.WindowState) })
        $w.Add_IsVisibleChanged({ Add-Trace (('pencere g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r=') + [string]$script:Win.IsVisible) })
        $w.Add_Closing({ Add-Trace ('pencere kapan' + [char]0x0131 + 'yor') })
    } catch { Add-Trace (('olay ba' + [char]0x011F + 'lanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
}

# Komut satiri: Baslat.bat -Cli -Gorev GuvenliCizim -Deger Ac | Kapat | Durum
function Invoke-CliSafeRender {
    $v = ([string]$Deger).Trim().ToLowerInvariant()
    $cur = ($script:Settings.SafeRender -eq $true)
    if ($v -eq 'ac' -or $v -eq 'on') {
        Set-SettingsKeys @{ SafeRender = $true }
        Write-WhLog ('G' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ': sonraki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta yaln' + [char]0x0131 + 'zca yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'mla ' + [char]0x00E7 + 'izilir, GPU / s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k izleme kapal' + [char]0x0131 + ' olur.') 'OK'
        return 0
    }
    if ($v -eq 'kapat' -or $v -eq 'off') {
        Set-SettingsKeys @{ SafeRender = $false; CrashStreak = 0 }
        Write-WhLog ('G' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'OK'
        return 0
    }
    $durum = ('kapal' + [char]0x0131 + '')
    if ($cur) { $durum = ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k') }
    Write-WhLog (('G' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim: ') + $durum + ('. De' + [char]0x011F + 'i' + [char]0x015F + 'tirmek i' + [char]0x00E7 + 'in -Deger Ac ya da -Deger Kapat verin.')) 'INFO'
    return 0
}


# ---------------- Duzen motoru ----------------
# ==================================================================
#  DUZEN MOTORU (saf mantik): doseme (tile) panosu
#  Pano 12 sutunlu bir izgaradir. Her doseme X, Y (sol ust hucre) ve W, H (hucre sayisi) ile durur.
#  Bu dosya ekrana dokunmaz; tasima, boyutlandirma, ekleme, cikarma, carpisma cozumu, kayitli duzenin dogrulanmasi
#  ve hazir duzenler burada olur. Ekran tarafi (Ana ekran panosu bolumu) bu islevleri cagirir; testler de ayni islevleri dogrudan sinar.
#
#  Carpisma kurali (react-grid-layout ile ayni mantik): tasinan ya da boyutu degisen doseme oldugu yerde kalir;
#  digerleri (Y, X) sirasiyla ele alinir, cakisan doseme tasinanin altina itilir, bosluk kalan yukari cekilir.
#  Kayitli duzen tasarimdan bagimsizdir: tasarim degisince yalnizca gorunum (kabuk) degisir, dosemelerin yeri korunur.
# ==================================================================
$script:BoardCols = 12
$script:BoardMaxTiles = 24
$script:BoardMaxRows = 200

# Parca (widget) katalogu. T ad, D aciklama, W/H varsayilan boyut, Min*/Max* sinirlar, Ico simge anahtari, Uniq: panoda en cok bir tane
$script:BoardWidgets = [ordered]@{
    hero    = @{ T = ('Kar' + [char]0x015F + '' + [char]0x0131 + 'lama ba' + [char]0x015F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ''); D = ('B' + [char]0x00FC + 'y' + [char]0x00FC + 'k ba' + [char]0x015F + 'l' + [char]0x0131 + 'k ve k' + [char]0x0131 + 'sa a' + [char]0x00E7 + '' + [char]0x0131 + 'klama.'); W = 12; H = 2; MinW = 6; MinH = 2; MaxW = 12; MaxH = 3; Ico = 'IcoSpark'; Uniq = $true }
    search  = @{ T = ('Komut ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'u'); D = ('Yazarak sayfa a' + [char]0x00E7 + ' ya da komut ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r.'); W = 8; H = 1; MinW = 4; MinH = 1; MaxW = 12; MaxH = 1; Ico = 'IcoSearch'; Uniq = $true }
    health  = @{ T = ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ''); D = ('Genel puan ve h' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama d' + [char]0x00FC + '' + [char]0x011F + 'mesi.'); W = 3; H = 3; MinW = 2; MinH = 2; MaxW = 4; MaxH = 4; Ico = 'IcoPulse'; Uniq = $true }
    cpu     = @{ T = ('' + [char]0x0130 + '' + [char]0x015F + 'lemci'); D = ('Canl' + [char]0x0131 + ' i' + [char]0x015F + 'lemci kullan' + [char]0x0131 + 'm' + [char]0x0131 + '.'); W = 3; H = 2; MinW = 2; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoCpu'; Uniq = $true }
    ram     = @{ T = 'Bellek'; D = ('Canl' + [char]0x0131 + ' bellek kullan' + [char]0x0131 + 'm' + [char]0x0131 + '.'); W = 3; H = 2; MinW = 2; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoLayers'; Uniq = $true }
    disk    = @{ T = 'Disk'; D = ('Sistem diskinin dolulu' + [char]0x011F + 'u ve etkinli' + [char]0x011F + 'i.'); W = 3; H = 2; MinW = 2; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoDisk'; Uniq = $true }
    net     = @{ T = ('A' + [char]0x011F + ''); D = ('Anl' + [char]0x0131 + 'k indirme ve y' + [char]0x00FC + 'kleme h' + [char]0x0131 + 'z' + [char]0x0131 + '.'); W = 3; H = 2; MinW = 2; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoWifi'; Uniq = $true }
    gpu     = @{ T = ('Ekran kart' + [char]0x0131 + ''); D = ('Ekran kart' + [char]0x0131 + ' (3B) y' + [char]0x00FC + 'k' + [char]0x00FC + '.'); W = 3; H = 2; MinW = 2; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoMonitor'; Uniq = $true }
    temp    = @{ T = ('S' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k'); D = ('Okunabiliyorsa i' + [char]0x015F + 'lemci s' + [char]0x0131 + 'cakl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + '.'); W = 3; H = 2; MinW = 2; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoAlert'; Uniq = $true }
    action  = @{ T = ('Eylem kart' + [char]0x0131 + ''); D = ('Tek dokunu' + [char]0x015F + 'la bir sayfay' + [char]0x0131 + ' ya da i' + [char]0x015F + 'lemi a' + [char]0x00E7 + 'ar.'); W = 4; H = 3; MinW = 2; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoApps'; Uniq = $false }
    cta     = @{ T = ('B' + [char]0x00FC + 'y' + [char]0x00FC + 'k d' + [char]0x00FC + '' + [char]0x011F + 'me'); D = ('Geni' + [char]0x015F + ' bir eylem d' + [char]0x00FC + '' + [char]0x011F + 'mesi.'); W = 4; H = 1; MinW = 2; MinH = 1; MaxW = 12; MaxH = 2; Ico = 'IcoPlay'; Uniq = $false }
    top     = @{ T = ('En ' + [char]0x00E7 + 'ok kaynak kullananlar'); D = ('' + [char]0x0130 + '' + [char]0x015F + 'lemciyi en ' + [char]0x00E7 + 'ok kullanan i' + [char]0x015F + 'lemler.'); W = 4; H = 3; MinW = 3; MinH = 2; MaxW = 6; MaxH = 6; Ico = 'IcoList'; Uniq = $true }
    log     = @{ T = ('Akan g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k'); D = ('' + [char]0x0130 + '' + [char]0x015F + 'lem g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + 'n' + [char]0x00FC + 'n son sat' + [char]0x0131 + 'rlar' + [char]0x0131 + '.'); W = 6; H = 3; MinW = 3; MinH = 2; MaxW = 12; MaxH = 6; Ico = 'IcoTerminal'; Uniq = $true }
    radar   = @{ T = ('A' + [char]0x011F + ' radar' + [char]0x0131 + ''); D = ('Son taramada bulunan cihazlar (yeni tarama ba' + [char]0x015F + 'latmaz).'); W = 4; H = 4; MinW = 3; MinH = 3; MaxW = 6; MaxH = 6; Ico = 'IcoGlobe'; Uniq = $true }
    hex     = @{ T = ('Disk b' + [char]0x00F6 + 'lgeleri'); D = ('Disk dolulu' + [char]0x011F + 'u alt' + [char]0x0131 + 'gen b' + [char]0x00F6 + 'lgelerle g' + [char]0x00F6 + 'sterilir.'); W = 6; H = 3; MinW = 4; MinH = 2; MaxW = 12; MaxH = 5; Ico = 'IcoDisk'; Uniq = $true }
    sysinfo = @{ T = 'Sistem bilgisi'; D = ('Windows, i' + [char]0x015F + 'lemci, bellek ve a' + [char]0x00E7 + '' + [char]0x0131 + 'k kalma s' + [char]0x00FC + 'resi.'); W = 4; H = 2; MinW = 3; MinH = 2; MaxW = 6; MaxH = 4; Ico = 'IcoInfo'; Uniq = $true }
}

# Eylem katalogu: eylem / cta dosemelerinin yaptigi is. Page doluysa o sayfa acilir; Fn doluysa uygulamanin kendi islevi cagrilir.
# Hepsi uygulamanin bugunku hizli eylemleridir: onay, onizleme ve geri alma kurallari oldugu gibi gecerlidir.
$script:BoardActions = [ordered]@{
    health   = @{ T = ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ''); D = ('Sistemi yaln' + [char]0x0131 + 'zca okuyarak denetler; d' + [char]0x00FC + 'zeltilebilir bulgular' + [char]0x0131 + ' listeler.'); Ico = 'IcoPulse'; Page = ''; Fn = 'health' }
    maint    = @{ T = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm'); D = ('Ge' + [char]0x00E7 + 'ici dosyalar' + [char]0x0131 + ' ve kal' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' ' + [char]0x00F6 + 'nizleyip onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla temizler.'); Ico = 'IcoTrash'; Page = ''; Fn = 'maint' }
    audit    = @{ T = ('G' + [char]0x00FC + 'venlik denetimi'); D = ('Tam g' + [char]0x00FC + 'venlik ve sa' + [char]0x011F + 'l' + [char]0x0131 + 'k denetimini ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'r.'); Ico = 'IcoShieldCheck'; Page = 'security'; Fn = 'audit' }
    speed    = @{ T = 'Optimizasyon'; D = ('Gizlilik, performans ve g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm ayarlar' + [char]0x0131 + '; hepsi geri al' + [char]0x0131 + 'nabilir.'); Ico = 'IcoBolt'; Page = 'optimize'; Fn = '' }
