# ---------------- kucuk yardimcilar ----------------
function ConvertTo-BoardInt($Value, [int]$Default = 0) {
    if ($null -eq $Value) { return $Default }
    $n = 0
    try { $n = [int][math]::Floor([double]$Value) } catch { return $Default }
    return $n
}

function Get-BoardField($Obj, [string]$Name) {
    if ($null -eq $Obj) { return $null }
    if ($Obj -is [System.Collections.IDictionary]) {
        if ($Obj.Contains($Name)) { return $Obj[$Name] }
        return $null
    }
    try { return $Obj.$Name } catch { return $null }
}

# Tur adi katalogdaki anahtara cevrilir (buyuk/kucuk harf onemsiz); bilinmiyorsa bos doner
function Resolve-BoardType([string]$Type) {
    foreach ($k in @($script:BoardWidgets.Keys)) { if ([string]$k -ieq $Type.Trim()) { return [string]$k } }
    return ''
}

function Get-BoardSpec([string]$Type) {
    $k = Resolve-BoardType $Type
    if ($k -eq '') { return $null }
    return $script:BoardWidgets[$k]
}

# Eylem anahtari gecerliyse kucuk harfle doner; degilse varsayilan
function Get-BoardActionKey([string]$Key, [string]$Default = 'health') {
    foreach ($k in @($script:BoardActions.Keys)) { if ([string]$k -ieq $Key.Trim()) { return [string]$k } }
    return $Default
}

# eylem / cta disindaki turlerde Arg bos kalir
function Resolve-BoardArg([string]$Type, [string]$Arg) {
    if ($Type -eq 'action' -or $Type -eq 'cta') {
        $def = 'health'
        if ($Type -eq 'cta') { $def = 'maint' }
        return (Get-BoardActionKey $Arg $def)
    }
    return ''
}

function ConvertTo-BoardTileFit([string]$Type, $W, $H) {
    $spec = Get-BoardSpec $Type
    $cw = ConvertTo-BoardInt $W ([int]$spec.W)
    $ch = ConvertTo-BoardInt $H ([int]$spec.H)
    if ($cw -lt [int]$spec.MinW) { $cw = [int]$spec.MinW }
    if ($cw -gt [int]$spec.MaxW) { $cw = [int]$spec.MaxW }
    if ($cw -gt $script:BoardCols) { $cw = $script:BoardCols }
    if ($ch -lt [int]$spec.MinH) { $ch = [int]$spec.MinH }
    if ($ch -gt [int]$spec.MaxH) { $ch = [int]$spec.MaxH }
    return @{ W = $cw; H = $ch }
}

function Find-BoardTile($L, [string]$Id) {
    foreach ($t in $L) { if ([string]$t.Id -eq $Id) { return $t } }
    return $null
}

# Siradaki serbest kimlik: t1, t2, ...
function Get-BoardNewId($L) {
    $max = 0
    foreach ($t in $L) {
        $m = [regex]::Match([string]$t.Id, '^t(\d+)$')
        if ($m.Success) { $n = [int]$m.Groups[1].Value; if ($n -gt $max) { $max = $n } }
    }
    return ('t' + [string]($max + 1))
}

function New-BoardTile([string]$Id, [string]$Type, $X, $Y, $W, $H, [string]$Arg = '') {
    $k = Resolve-BoardType $Type
    if ($k -eq '') { return $null }
    $fit = ConvertTo-BoardTileFit $k $W $H
    $cx = ConvertTo-BoardInt $X 0
    $cy = ConvertTo-BoardInt $Y 0
    if ($cx -lt 0) { $cx = 0 }
    if ($cx -gt ($script:BoardCols - [int]$fit.W)) { $cx = $script:BoardCols - [int]$fit.W }
    if ($cy -lt 0) { $cy = 0 }
    if ($cy -gt $script:BoardMaxRows) { $cy = $script:BoardMaxRows }
    return @{ Id = $Id; Type = $k; X = $cx; Y = $cy; W = [int]$fit.W; H = [int]$fit.H; Arg = (Resolve-BoardArg $k $Arg) }
}

function Copy-BoardLayout($L) {
    $c = New-Object System.Collections.ArrayList
    foreach ($t in $L) { [void]$c.Add(@{ Id = [string]$t.Id; Type = [string]$t.Type; X = [int]$t.X; Y = [int]$t.Y; W = [int]$t.W; H = [int]$t.H; Arg = [string]$t.Arg }) }
    return , $c
}

# ---------------- carpisma ve sikistirma ----------------
function Test-BoardCollide($A, $B) {
    if ([int]$A.X -ge ([int]$B.X + [int]$B.W)) { return $false }
    if ([int]$B.X -ge ([int]$A.X + [int]$A.W)) { return $false }
    if ([int]$A.Y -ge ([int]$B.Y + [int]$B.H)) { return $false }
    if ([int]$B.Y -ge ([int]$A.Y + [int]$A.H)) { return $false }
    return $true
}

function Test-BoardHit($Tile, $Placed) {
    foreach ($p in $Placed) {
        if ([object]::ReferenceEquals($p, $Tile)) { continue }
        if (Test-BoardCollide $Tile $p) { return $true }
    }
    return $false
}

# (Y, X) sirasina gore doseme dizinleri; esit konumda ozgun sira korunur (kararli)
function Get-BoardOrder($L, [string]$SkipId = '') {
    $idx = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt $L.Count; $i++) { if ([string]$L[$i].Id -ne $SkipId -or $SkipId -eq '') { [void]$idx.Add($i) } }
    $arr = $idx.ToArray()
    for ($a = 1; $a -lt $arr.Length; $a++) {
        $cur = $arr[$a]
        $b = $a - 1
        while ($b -ge 0) {
            $p = $L[$arr[$b]]
            $q = $L[$cur]
            $after = ([int]$p.Y -gt [int]$q.Y) -or (([int]$p.Y -eq [int]$q.Y) -and ([int]$p.X -gt [int]$q.X))
            if (-not $after) { break }
            $arr[$b + 1] = $arr[$b]
            $b--
        }
        $arr[$b + 1] = $cur
    }
    return , $arr
}

# PinId verilirse o doseme oldugu yerde kalir; digerleri onun etrafinda yerlesir. Bossa hepsi yukari sikisir.
function Invoke-BoardCompact($L, [string]$PinId = '') {
    $placed = New-Object System.Collections.ArrayList
    if ($PinId -ne '') {
        $p = Find-BoardTile $L $PinId
        if ($null -ne $p) { [void]$placed.Add($p) }
    }
    $skip = ''
    if ($placed.Count -gt 0) { $skip = $PinId }
    foreach ($i in (Get-BoardOrder $L $skip)) {
        $t = $L[$i]
        if (-not (Test-BoardHit $t $placed)) {
            while ([int]$t.Y -gt 0) {
                $t.Y = [int]$t.Y - 1
                if (Test-BoardHit $t $placed) { $t.Y = [int]$t.Y + 1; break }
            }
        }
        while (Test-BoardHit $t $placed) { $t.Y = [int]$t.Y + 1 }
        [void]$placed.Add($t)
    }
}

# ---------------- islemler ----------------
function Move-BoardTile($L, [string]$Id, $X, $Y) {
    $t = Find-BoardTile $L $Id
    if ($null -eq $t) { return $false }
    $nx = ConvertTo-BoardInt $X 0
    $ny = ConvertTo-BoardInt $Y 0
    if ($nx -gt ($script:BoardCols - [int]$t.W)) { $nx = $script:BoardCols - [int]$t.W }
    if ($nx -lt 0) { $nx = 0 }
    if ($ny -lt 0) { $ny = 0 }
    if ($ny -gt $script:BoardMaxRows) { $ny = $script:BoardMaxRows }
    $t.X = $nx
    $t.Y = $ny
    Invoke-BoardCompact $L $Id
    return $true
}

function Resize-BoardTile($L, [string]$Id, $W, $H) {
    $t = Find-BoardTile $L $Id
    if ($null -eq $t) { return $false }
    $fit = ConvertTo-BoardTileFit ([string]$t.Type) $W $H
    $t.W = [int]$fit.W
    $t.H = [int]$fit.H
    if (([int]$t.X + [int]$t.W) -gt $script:BoardCols) { $t.X = $script:BoardCols - [int]$t.W }
    Invoke-BoardCompact $L $Id
    return $true
}

# Yeni doseme ilk bos yere konur; eklenemezse (sinir ya da tek kopya kurali) $null doner
function Add-BoardTile($L, [string]$Type, [string]$Arg = '') {
    $k = Resolve-BoardType $Type
    if ($k -eq '') { return $null }
    $spec = $script:BoardWidgets[$k]
    if ($L.Count -ge $script:BoardMaxTiles) { return $null }
    if ([bool]$spec.Uniq) { foreach ($t in $L) { if ([string]$t.Type -eq $k) { return $null } } }
    $w = [int]$spec.W
    $h = [int]$spec.H
    $probe = @{ X = 0; Y = 0; W = $w; H = $h }
    $found = $false
    $y = 0
    while (-not $found -and $y -le $script:BoardMaxRows) {
        $x = 0
        while (-not $found -and $x -le ($script:BoardCols - $w)) {
            $probe.X = $x
            $probe.Y = $y
            if (-not (Test-BoardHit $probe $L)) { $found = $true } else { $x++ }
        }
        if (-not $found) { $y++ }
    }
    if (-not $found) { return $null }
    $tile = New-BoardTile (Get-BoardNewId $L) $k $probe.X $probe.Y $w $h $Arg
    [void]$L.Add($tile)
    Invoke-BoardCompact $L ''
    return $tile
}

function Remove-BoardTile($L, [string]$Id) {
    $t = Find-BoardTile $L $Id
    if ($null -eq $t) { return $false }
    $L.Remove($t)
    Invoke-BoardCompact $L ''
    return $true
}

# ---------------- dogrulama ve kayit bicimi ----------------
# Kayitli (ya da elle duzenlenmis) veri guvenli bir duzene cevrilir: bilinmeyen turler atilir, boyutlar sinirlanir,
# kimlikler benzersiz yapilir, cakismalar cozulur. Hicbir doseme kalmazsa bos liste doner (cagiran hazir duzeni kullanir).
function ConvertTo-BoardLayout($Data) {
    $out = New-Object System.Collections.ArrayList
    $seen = @{}
    foreach ($d in @($Data)) {
        if ($null -eq $d) { continue }
        if ($out.Count -ge $script:BoardMaxTiles) { break }
        $k = Resolve-BoardType ([string](Get-BoardField $d 'Type'))
        if ($k -eq '') { continue }
        $spec = $script:BoardWidgets[$k]
        if ([bool]$spec.Uniq -and $seen.ContainsKey($k)) { continue }
        $id = [string](Get-BoardField $d 'Id')
        $idOk = $id -cmatch '^[a-z][a-z0-9]{0,11}$'
        if ($idOk) { foreach ($o in $out) { if ([string]$o.Id -eq $id) { $idOk = $false } } }
        if (-not $idOk) { $id = Get-BoardNewId $out }
        $arg = [string](Get-BoardField $d 'Arg')
        $tile = New-BoardTile $id $k (Get-BoardField $d 'X') (Get-BoardField $d 'Y') (Get-BoardField $d 'W') (Get-BoardField $d 'H') $arg
        if ($null -eq $tile) { continue }
        $seen[$k] = $true
        [void]$out.Add($tile)
    }
    if ($out.Count -gt 0) { Invoke-BoardCompact $out '' }
    return , $out
}

# Kayit icin duz dizi (JSON'a yazilir)
function ConvertTo-BoardData($L) {
    $arr = New-Object System.Collections.ArrayList
    foreach ($t in $L) { [void]$arr.Add([ordered]@{ Id = [string]$t.Id; Type = [string]$t.Type; X = [int]$t.X; Y = [int]$t.Y; W = [int]$t.W; H = [int]$t.H; Arg = [string]$t.Arg }) }
    return , $arr.ToArray()
}

# 'tur:x:y:w:h[:eylem]' satirlarindan duzen
function ConvertFrom-BoardSpecs($Specs) {
    $raw = New-Object System.Collections.ArrayList
    $n = 0
    foreach ($s in @($Specs)) {
        $p = ([string]$s).Split(':')
        if ($p.Count -lt 5) { continue }
        $n++
        $arg = ''
        if ($p.Count -ge 6) { $arg = [string]$p[5] }
        [void]$raw.Add(@{ Id = ('t' + [string]$n); Type = [string]$p[0]; X = $p[1]; Y = $p[2]; W = $p[3]; H = $p[4]; Arg = $arg })
    }
    return , (ConvertTo-BoardLayout $raw.ToArray())
}

function Get-BoardPreset([string]$Design) {
    $key = ''
    foreach ($k in @($script:BoardPresets.Keys)) { if ([string]$k -ieq $Design) { $key = [string]$k } }
    if ($key -eq '') { $key = 'Klasik' }
    return , (ConvertFrom-BoardSpecs $script:BoardPresets[$key])
}

# Duzende sorun var mi? Sorun metinlerinin dizisi doner (bossa duzen saglamdir). Testlerde ve duman denetiminde kullanilir.
function Get-BoardProblems($L) {
    $bad = New-Object System.Collections.ArrayList
    $ids = @{}
    $i = 0
    foreach ($t in $L) {
        $i++
        $spec = Get-BoardSpec ([string]$t.Type)
        if ($null -eq $spec) { [void]$bad.Add(('bilinmeyen t' + [char]0x00FC + 'r: ') + [string]$t.Type); continue }
        if ($ids.ContainsKey([string]$t.Id)) { [void]$bad.Add('yinelenen kimlik: ' + [string]$t.Id) }
        $ids[[string]$t.Id] = $true
        if ([int]$t.X -lt 0 -or ([int]$t.X + [int]$t.W) -gt $script:BoardCols) { [void]$bad.Add(('s' + [char]0x00FC + 'tun d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ': ') + [string]$t.Id) }
        if ([int]$t.Y -lt 0) { [void]$bad.Add(('eksi sat' + [char]0x0131 + 'r: ') + [string]$t.Id) }
        if ([int]$t.W -lt [int]$spec.MinW -or [int]$t.W -gt [int]$spec.MaxW -or [int]$t.H -lt [int]$spec.MinH -or [int]$t.H -gt [int]$spec.MaxH) { [void]$bad.Add(('boyut s' + [char]0x0131 + 'n' + [char]0x0131 + 'r d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ': ') + [string]$t.Id) }
        $j = 0
        foreach ($u in $L) {
            $j++
            if ($j -le $i) { continue }
            if (Test-BoardCollide $t $u) { [void]$bad.Add(('' + [char]0x00E7 + 'ak' + [char]0x0131 + '' + [char]0x015F + 'ma: ') + [string]$t.Id + ' / ' + [string]$u.Id) }
        }
    }
    if ($L.Count -gt $script:BoardMaxTiles) { [void]$bad.Add(('' + [char]0x00E7 + 'ok fazla d' + [char]0x00F6 + '' + [char]0x015F + 'eme')) }
    return $bad.ToArray()
}

# ---------------- piksel hesaplari ----------------
function Get-BoardCellW([double]$AvailW, [double]$Gap) {
    $w = ($AvailW - $Gap * ($script:BoardCols - 1)) / $script:BoardCols
    if ($w -lt 20) { $w = 20 }
    return $w
}

function Get-BoardRows($L) {
    $r = 0
    foreach ($t in $L) { $b = [int]$t.Y + [int]$t.H; if ($b -gt $r) { $r = $b } }
    return $r
}

function Get-BoardRect($T, [double]$CellW, [double]$CellH, [double]$Gap) {
    return @{
        X = [double]$T.X * ($CellW + $Gap)
        Y = [double]$T.Y * ($CellH + $Gap)
        W = [double]$T.W * $CellW + ([double]$T.W - 1) * $Gap
        H = [double]$T.H * $CellH + ([double]$T.H - 1) * $Gap
    }
}

# Piksel konumuna en yakin hucre (sol ust kose)
function Get-BoardCell([double]$Px, [double]$Py, [double]$CellW, [double]$CellH, [double]$Gap) {
    $cx = [int][math]::Floor($Px / ($CellW + $Gap) + 0.5)
    $cy = [int][math]::Floor($Py / ($CellH + $Gap) + 0.5)
    if ($cx -lt 0) { $cx = 0 }
    if ($cy -lt 0) { $cy = 0 }
    return @{ X = $cx; Y = $cy }
}

# Piksel boyutuna en yakin hucre sayisi (koseden boyutlandirirken)
function Get-BoardSpan([double]$Px, [double]$CellW, [double]$Gap) {
    $n = [int][math]::Floor(($Px + $Gap) / ($CellW + $Gap) + 0.5)
    if ($n -lt 1) { $n = 1 }
    return $n
}


# ---------------- Tasarim ----------------
# ==================================================================
#  TASARIM: kabugun yapisi (menu bicimi, kose yuvarlakligi, yazi tipi, ana ekran)
#  Uc bagimsiz secim vardir: renk temasi, yerlesim (yogunluk) ve tasarim. Tasarim yalnizca bu pencerenin gorunumunu
#  degistirir; sistem ayarina dokunmaz. Bir adim basarisiz olursa Klasik tasarima donulur.
#  Klasik   : bugunku gorunum (simgeli sol menu); ana ekran secime gore pano ya da klasik durum panosu
#  Atolye   : buyuk baslik, cam kartlar, buyuk dugme; simge menusu ve acilan alt menu
#  Sifir    : ortada komut cubugu ve birkac buyuk eylem karti; menu gizli
#  Morpheus : siyah zemin, neon cizgiler, tek aralikli yazi, akan gunluk, ag radari
#  Komuta   : ince menu ve yeniden duzenlenebilir parcalardan olusan ana ekran
#  Ana ekran her tasarimda iki bicimde sunulur (Ayarlar > Gorunum > Ana ekran): Duzen Motoru'nun duzenlenebilir
#  panosu ya da klasik durum panosu. Tasarimin menu bicimi, koseleri, yazi tipi, grafik bicimi, parca gorunumu ve pano duzeni
#  ayrica tek tek secilebilir; secilmeyen ozellik tasarimin kendi degerini kullanir (Get-ActiveDesign).
# ==================================================================
$script:DesignInfo = [ordered]@{
    Klasik   = @{ T = 'Klasik';         D = ('Bug' + [char]0x00FC + 'nk' + [char]0x00FC + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: simgeli sol men' + [char]0x00FC + ', ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' durum g' + [char]0x00F6 + 'stergeleri. Pano ya da klasik durum panosu se' + [char]0x00E7 + 'ilebilir.') }
    Atolye   = @{ T = ('Kartl' + [char]0x0131 + '');         D = ('B' + [char]0x00FC + 'y' + [char]0x00FC + 'k ba' + [char]0x015F + 'l' + [char]0x0131 + 'k, yan yana cam kartlar ve tek dokunu' + [char]0x015F + 'luk b' + [char]0x00FC + 'y' + [char]0x00FC + 'k d' + [char]0x00FC + '' + [char]0x011F + 'me. Simge men' + [char]0x00FC + 's' + [char]0x00FC + '; bir simgeye t' + [char]0x0131 + 'klay' + [char]0x0131 + 'nca alt men' + [char]0x00FC + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') }
    Sifir    = @{ T = 'Minimal';  D = ('Ortada komut ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'u ve birka' + [char]0x00E7 + ' b' + [char]0x00FC + 'y' + [char]0x00FC + 'k eylem kart' + [char]0x0131 + '. Men' + [char]0x00FC + ' gizlidir (sol ' + [char]0x00FC + 'stteki d' + [char]0x00FC + '' + [char]0x011F + 'meyle a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r); say' + [char]0x0131 + ' ve grafik kalabal' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' yoktur.') }
    Morpheus = @{ T = ('A' + [char]0x011F + ' konsolu');   D = ('Siyah zemin, ince neon ' + [char]0x00E7 + 'izgiler, tek aral' + [char]0x0131 + 'kl' + [char]0x0131 + ' yaz' + [char]0x0131 + '. Akan g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k, a' + [char]0x011F + ' radar' + [char]0x0131 + ' ve dalga bi' + [char]0x00E7 + 'imli grafikler.') }
    Komuta   = @{ T = ('G' + [char]0x00F6 + 'sterge paneli'); D = ('' + [char]0x0130 + 'nce, daralt' + [char]0x0131 + 'labilir sol men' + [char]0x00FC + ' ve istedi' + [char]0x011F + 'iniz gibi d' + [char]0x00FC + 'zenlenen par' + [char]0x00E7 + 'alardan olu' + [char]0x015F + 'an ana ekran.') }
}

