# ---------------- saf yardimcilar (ekrana dokunmaz; testlerde de kullanilir) ----------------
function ConvertTo-DesignKey([string]$Name) {
    $t = [string]$Name
    foreach ($k in @($script:DesignInfo.Keys)) { if ([string]$k -eq $t) { return [string]$k } }
    return 'Klasik'
}

# Tasarimin ozellikleri. Board: ana ekran pano mu (Get-ActiveDesign bunu Ana ekran seciminden okur) - Preset: hazir pano duzeni - Nav: menu bicimi (Rail | Fly | Hidden | Compact)
# RadCard / RadBtn: kose yuvarlakligi - Mono: tek aralikli yazi - Graph: area | scope | none - Gap, CellH: pano hucre araligi ve yuksekligi
# Skin: Plain | Glass | Calm | Neon | Slate (parca cizim bicimi) - Theme, Layout: "hazir gorunum" olarak onerilen tema ve yerlesim
function Get-DesignSpec([string]$Key) {
    $d = @{ Key = 'Klasik'; Board = $true; Preset = 'Klasik'; Nav = 'Rail'; RadCard = 8; RadBtn = 6; Mono = $false; Graph = 'area'; Gap = 10; CellH = 66
            Skin = 'Plain'; Theme = 'Acik'; Layout = 'Sade'; Tagline = '' }
    $k = ConvertTo-DesignKey $Key
    $d.Key = $k
    if ($k -eq 'Atolye') {
        $d.Preset = 'Atolye'; $d.Nav = 'Fly'; $d.RadCard = 18; $d.RadBtn = 12; $d.Graph = 'area'; $d.Gap = 16; $d.CellH = 62
        $d.Skin = 'Glass'; $d.Theme = 'Holo'; $d.Layout = 'Kompakt'
    } elseif ($k -eq 'Sifir') {
        $d.Preset = 'Sifir'; $d.Nav = 'Hidden'; $d.RadCard = 24; $d.RadBtn = 16; $d.Graph = 'none'; $d.Gap = 18; $d.CellH = 62
        $d.Skin = 'Calm'; $d.Theme = 'Cam'; $d.Layout = 'Sade'
    } elseif ($k -eq 'Morpheus') {
        $d.Preset = 'Morpheus'; $d.Nav = 'Compact'; $d.RadCard = 2; $d.RadBtn = 2; $d.Mono = $true; $d.Graph = 'scope'; $d.Gap = 8; $d.CellH = 64
        $d.Skin = 'Neon'; $d.Theme = 'Hacker'; $d.Layout = 'Kompakt'; $d.Tagline = ('A' + [char]0x011E + ' KONSOLU')
    } elseif ($k -eq 'Komuta') {
        $d.Preset = 'Komuta'; $d.Nav = 'Compact'; $d.RadCard = 6; $d.RadBtn = 5; $d.Graph = 'area'; $d.Gap = 10; $d.CellH = 66
        $d.Skin = 'Slate'; $d.Theme = 'Koyu'; $d.Layout = 'Kompakt'
    }
    return $d
}

