    Klasik = @{ T = 'Klasik durum panosu'; D = ('Sabit durum panosu: kaynak g' + [char]0x00F6 + 'stergeleri, sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ' ve h' + [char]0x0131 + 'zl' + [char]0x0131 + ' eylemler. Par' + [char]0x00E7 + 'alar' + [char]0x0131 + ' d' + [char]0x00FC + 'zenlenmez.') }
