    Font   = [ordered]@{ Auto = ('Tasar' + [char]0x0131 + 'ma g' + [char]0x00F6 + 're'); Sans = 'Segoe UI (normal)'; Mono = ('Tek aral' + [char]0x0131 + 'kl' + [char]0x0131 + ' (terminal)') }
    Graph  = [ordered]@{ Auto = ('Tasar' + [char]0x0131 + 'ma g' + [char]0x00F6 + 're'); area = ('Alan grafi' + [char]0x011F + 'i'); scope = 'Dalga (osiloskop)'; none = ('Grafik yok, yaln' + [char]0x0131 + 'zca say' + [char]0x0131 + '') }
    Skin   = [ordered]@{ Auto = ('Tasar' + [char]0x0131 + 'ma g' + [char]0x00F6 + 're'); Plain = ('D' + [char]0x00FC + 'z'); Glass = 'Cam'; Calm = ('Sakin (' + [char]0x00E7 + 'er' + [char]0x00E7 + 'evesiz)'); Neon = ('Neon ' + [char]0x00E7 + 'izgi'); Slate = ('Antrasit (' + [char]0x00FC + 'st ' + [char]0x00E7 + 'izgili)') }
