$script:DsTitles = [ordered]@{ Nav = ('Men' + [char]0x00FC + ' bi' + [char]0x00E7 + 'imi'); Radius = ('K' + [char]0x00F6 + '' + [char]0x015F + 'eler'); Font = ('Yaz' + [char]0x0131 + ' tipi'); Graph = ('Grafik bi' + [char]0x00E7 + 'imi'); Skin = ('Par' + [char]0x00E7 + 'a g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm' + [char]0x00FC + '') }
# Kose yuvarlakligi secenekleri: kart ve dugme kose yaricapi
$script:DsRadii = @{ Sharp = @(2, 2); Soft = @(8, 6); Round = @(18, 12); Pill = @(24, 16) }

function ConvertTo-HomeKey($Name) {
    $t = [string]$Name
    foreach ($k in @($script:HomeInfo.Keys)) { if ([string]$k -eq $t) { return [string]$k } }
    return 'Pano'
}

# Bilinmeyen ya da bos deger 'Auto' olur
function ConvertTo-DsValue([string]$Prop, $Value) {
    $tbl = $script:DsOptions[$Prop]
    if ($null -eq $tbl) { return 'Auto' }
    $t = [string]$Value
    foreach ($k in @($tbl.Keys)) { if ([string]$k -ieq $t) { return [string]$k } }
    return 'Auto'
}

# Tasarim ozelliklerine kullanici secimlerini uygular (saf islev: ayarlar tablosu disaridan verilir)
function Merge-DesignOverrides($Spec, $St) {
    $d = @{}
    foreach ($k in @($Spec.Keys)) { $d[$k] = $Spec[$k] }
    $nav = ConvertTo-DsValue 'Nav' (Get-BoardField $St 'DsNav')
    if ($nav -ne 'Auto') { $d.Nav = $nav }
    $rad = ConvertTo-DsValue 'Radius' (Get-BoardField $St 'DsRadius')
    if ($rad -ne 'Auto') { $d.RadCard = [int]$script:DsRadii[$rad][0]; $d.RadBtn = [int]$script:DsRadii[$rad][1] }
    $font = ConvertTo-DsValue 'Font' (Get-BoardField $St 'DsFont')
    if ($font -eq 'Mono') { $d.Mono = $true } elseif ($font -eq 'Sans') { $d.Mono = $false }
    $gr = ConvertTo-DsValue 'Graph' (Get-BoardField $St 'DsGraph')
    if ($gr -ne 'Auto') { $d.Graph = $gr }
    $sk = ConvertTo-DsValue 'Skin' (Get-BoardField $St 'DsSkin')
    if ($sk -ne 'Auto') { $d.Skin = $sk }
    $d.Board = ((ConvertTo-HomeKey (Get-BoardField $St 'HomeMode')) -ne 'Klasik')
    return $d
}

# Etkin tasarimin ozellikleri: secili tasarim + kullanicinin tek tek sectikleri + ana ekran bicimi
function Get-ActiveDesign {
    return (Merge-DesignOverrides (Get-DesignSpec $script:DesignKey) $script:Settings)
}

# Tasarim ayrintilarindan biri tasarimin kendi degerinden farkli mi?
function Test-DesignOverridden($St) {
    foreach ($p in @($script:DsOptions.Keys)) {
        if ((ConvertTo-DsValue ([string]$p) (Get-BoardField $St ('Ds' + [string]$p))) -ne 'Auto') { return $true }
    }
    return $false
}

# Ayar tablosundaki tasarim ayrintilarini 'Auto' yapar (kaydetmeyi cagiran yapar)
function Clear-DesignOverrides($St) {
    foreach ($p in @($script:DsOptions.Keys)) { $St[('Ds' + [string]$p)] = 'Auto' }
}

# Ana ekran basligi (Atolye ve Sifir Noktasi'nin karsilama karti)
function Get-DesignHero([string]$Key) {
    $k = ConvertTo-DesignKey $Key
    if ($k -eq 'Atolye') { return @{ T = ('Bilgisayar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' sade ve g' + [char]0x00FC + 'venli bi' + [char]0x00E7 + 'imde optimize edin.'); S = ('Her de' + [char]0x011F + 'i' + [char]0x015F + 'iklik ' + [char]0x00F6 + 'nizlenir, kaydedilir ve geri al' + [char]0x0131 + 'nabilir.') } }
    if ($k -eq 'Sifir') { return @{ T = 'Ne yapmak istersiniz?'; S = ('Bir i' + [char]0x015F + 'lem ya da sayfa ad' + [char]0x0131 + ' yaz' + [char]0x0131 + 'n.') } }
    return @{ T = ('MULT' + [char]0x0130 + 'M' + [char]0x0130 + 'ZER'); S = ('Optimizasyon, g' + [char]0x00FC + 'venlik ve a' + [char]0x011F + ' korumas' + [char]0x0131 + '') }
}

# Menu gruplari. Expert $false ise yalnizca uzman kipine ozel olmayan sayfalar gelir.
function Get-NavGroups([bool]$Expert) {
    $defs = @(
        @{ K = 'ana'; T = 'Ana ekran'; Ico = 'IcoHome'; P = @('panel', 'solve') },
        @{ K = 'hiz'; T = ('H' + [char]0x0131 + 'z ve temizlik'); Ico = 'IcoBolt'; P = @('optimize', 'services', 'apps', 'clean', 'power', 'gaming', 'smart') },
        @{ K = 'guv'; T = ('G' + [char]0x00FC + 'venlik ve a' + [char]0x011F + ''); Ico = 'IcoShieldCheck'; P = @('security', 'updates', 'network', 'backup') },
        @{ K = 'kur'; T = ('' + [char]0x015E + 'irket ve ara' + [char]0x00E7 + 'lar'); Ico = 'IcoBuilding'; P = @('company', 'tools') },
        @{ K = 'son'; T = ('Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' ve ayarlar'); Ico = 'IcoSliders'; P = @('history', 'settings') }
    )
    $expertOnly = @('services', 'company')
    $out = New-Object System.Collections.ArrayList
    foreach ($g in $defs) {
        $pages = New-Object System.Collections.ArrayList
        foreach ($p in $g.P) {
            if (-not $Expert -and ($expertOnly -contains [string]$p)) { continue }
            [void]$pages.Add([string]$p)
        }
        if ($pages.Count -eq 0) { continue }
        [void]$out.Add(@{ K = [string]$g.K; T = [string]$g.T; Ico = [string]$g.Ico; P = $pages.ToArray() })
    }
    return $out.ToArray()
}

# Sayfa anahtari hangi gruba ait? ('board' ana ekrandir)
function Get-NavGroupOf([string]$Page, [bool]$Expert = $true) {
    $p = $Page
    if ($p -eq 'board') { $p = 'panel' }
    foreach ($g in @(Get-NavGroups $Expert)) { if (@($g.P) -contains $p) { return [string]$g.K } }
    return ''
}

function Test-BoardHome {
    $s = Get-ActiveDesign
    return ($s.Board -eq $true)
}

# ---------------- kose yuvarlakligi (kaynak sozlugu; Card, Row ve dugmeler DynamicResource ile okur) ----------------
function Set-DesignRadii([double]$Card, [double]$Btn) {
    $res = $script:Win.Resources
    $pairs = @(@('RadCard', $Card), @('RadBtn', $Btn))
    foreach ($p in $pairs) {
        $name = [string]$p[0]
        $cr = New-Object System.Windows.CornerRadius -ArgumentList ([double]$p[1])
        if ($res.Contains($name)) { $res.Remove($name) }
        $res.Add($name, $cr)
    }
}

# ---------------- acilir menu (alt menu ve gizli menu icin tek bilesen) ----------------
$script:NavPopXaml = @'
<Popup xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
       StaysOpen="False" AllowsTransparency="True" PopupAnimation="Fade" Placement="Right">
  <Border Background="{DynamicResource BrPanel2}" BorderBrush="{DynamicResource BrLine2}" BorderThickness="1" CornerRadius="12" Padding="6" Margin="8" MinWidth="230" MaxHeight="560">
    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
      <StackPanel x:Name="Items"/>
    </ScrollViewer>
  </Border>
</Popup>
'@

$script:NavItemXaml = @'
<Button xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Style="{DynamicResource BtnRow}" Tag="@@Tag@@">
  <StackPanel Orientation="Horizontal">
    <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource @@Ico@@}" Width="18" Height="18" Foreground="{DynamicResource BrAccent}" VerticalAlignment="Center"/>
    <StackPanel Margin="12,0,8,0" VerticalAlignment="Center">
      <TextBlock Text="@@Text@@" FontSize="13" FontWeight="SemiBold" Foreground="{DynamicResource BrText}"/>
      <TextBlock Text="@@Sub@@" FontSize="11" Foreground="{DynamicResource BrDim}" TextWrapping="Wrap" MaxWidth="260"/>
    </StackPanel>
  </StackPanel>
</Button>
'@

$script:NavHeadXaml = @'
<TextBlock xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Text="@@Text@@" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource BrFaint}" Margin="10,10,0,4"/>
'@

function Get-NavPopup {
    if ($null -ne $script:NavPop) { return $script:NavPop }
    $pop = Read-LocalXaml ($script:NavPopXaml)
    # Acilir pencere pencerenin agacina baglanmazsa kaynaklar (renkler) bulunamaz
    [void]$ui.BodyGrid.Children.Add($pop)
    $script:NavPop = $pop
    return $pop
}

function Close-NavMenu {
    if ($null -ne $script:NavPop) { $script:NavPop.IsOpen = $false }
    try { Close-HoverMenu } catch { }
}

# Ogeler: @{ Head = 'baslik' } ya da @{ Text; Sub; Ico; Tag }. Tag bicimi: nav:<sayfa> | act:<eylem> | cmd:<komut> | add:<tur> | addact:<eylem> | addcta:<eylem> | layout:<hazir duzen>
function Show-ItemMenu($Target, $Items, [string]$Placement = 'Right') {
    $pop = Get-NavPopup
    $same = ($pop.IsOpen -and [object]::ReferenceEquals($pop.PlacementTarget, $Target))
    if (-not $same) { $pop.IsOpen = $false }
    $stack = $pop.FindName('Items')
    $stack.Children.Clear()
    foreach ($it in @($Items)) {
        if ($it.ContainsKey('Head')) {
            $h = Read-LocalXaml ((Expand-Template $script:NavHeadXaml @{ Text = [string]$it.Head }))
            [void]$stack.Children.Add($h)
            continue
        }
        $x = Expand-Template $script:NavItemXaml @{ Tag = [string]$it.Tag; Text = [string]$it.Text; Sub = [string]$it.Sub; Ico = [string]$it.Ico }
        $b = Read-LocalXaml ($x)
        $b.Add_Click($script:H_MenuItem)
        [void]$stack.Children.Add($b)
    }
    if ($same) { return }
    $pop.PlacementTarget = $Target
    if ($Placement -eq 'Bottom') { $pop.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom }
    else { $pop.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Right }
    $pop.IsOpen = $true
}

$script:H_MenuItem = {
    param($s, $e)
    Invoke-Safe { Invoke-MenuTag ([string]$s.Tag) } ('Men' + [char]0x00FC + '')
}

function Invoke-MenuTag([string]$Tag) {
    Close-NavMenu
    $i = $Tag.IndexOf(':')
    if ($i -lt 0) { return }
    $kind = $Tag.Substring(0, $i)
    $arg = $Tag.Substring($i + 1)
    if ($kind -eq 'nav') { Show-Page $arg }
    elseif ($kind -eq 'sub') { $sp = $arg.Split(':'); if ($sp.Count -ge 2) { Open-Page ([string]$sp[0]) ([string]$sp[1]) } else { Show-Page $arg } }
    elseif ($kind -eq 'act') { Invoke-BoardAction $arg }
    elseif ($kind -eq 'cmd') { Invoke-BoardCommand $arg }
    elseif ($kind -eq 'add') { [void](Add-BoardWidget $arg '') }
    elseif ($kind -eq 'addact') { [void](Add-BoardWidget 'action' $arg) }
    elseif ($kind -eq 'addcta') { [void](Add-BoardWidget 'cta' $arg) }
    elseif ($kind -eq 'layout') { [void](Select-BoardPreset $arg) }
}

# Turkce buyuk harf (i -> I, i -> I); kultur verisine bagli degildir
function ConvertTo-TrUpper([string]$Text) {
    if ($script:LangOn) { return ([string](Tr $Text)).ToUpperInvariant() }
    return ($Text.Replace('i', [string][char]0x0130).Replace([string][char]0x0131, 'I')).ToUpperInvariant()
}

function Get-NavMenuItems([string]$GroupKey, [bool]$Expert) {
    $items = New-Object System.Collections.ArrayList
    foreach ($g in @(Get-NavGroups $Expert)) {
        if ($GroupKey -ne '' -and [string]$g.K -ne $GroupKey) { continue }
        if ($GroupKey -eq '') { [void]$items.Add(@{ Head = (ConvertTo-TrUpper ([string]$g.T)) }) }
        foreach ($p in @($g.P)) {
            [void]$items.Add(@{ Text = [string]$script:PageNames[$p]; Sub = [string]$script:PageSubs[$p]; Ico = [string]$script:PageIcons[$p]; Tag = ('nav:' + $p) })
        }
    }
    return $items.ToArray()
}

# ---------------- Atolye: simge menusu ----------------
$script:FlyBtnXaml = @'
<Button xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Style="{DynamicResource BtnFly}" Tag="@@Tag@@" ToolTip="@@Tip@@" Margin="0,0,0,12">
  <ContentControl Style="{DynamicResource Icon}" Tag="{DynamicResource @@Ico@@}" Width="22" Height="22" Foreground="{DynamicResource BrAccent}"/>
</Button>
'@

$script:H_FlyClick = {
    param($s, $e)
    Invoke-Safe {
        $key = [string]$s.Tag
        $expert = ([string]$script:UiState.Mode -eq 'Expert')
        $g = $null
        foreach ($x in @(Get-NavGroups $expert)) { if ([string]$x.K -eq $key) { $g = $x } }
        if ($null -eq $g) { return }
        if (@($g.P).Count -eq 1) { Show-Page ([string]$g.P[0]); return }
        Show-ItemMenu $s @(Get-NavMenuItems $key $expert) 'Right'
    } ('Men' + [char]0x00FC + '')
}

function Build-FlyRail {
    $host_ = $ui.FlyRail
    if ($null -eq $host_) { return }
    $expert = ([string]$script:UiState.Mode -eq 'Expert')
    $host_.Children.Clear()
    $script:FlyBtns.Clear()
    foreach ($g in @(Get-NavGroups $expert)) {
        $x = Expand-Template $script:FlyBtnXaml @{ Tag = [string]$g.K; Tip = [string]$g.T; Ico = [string]$g.Ico }
        $b = Read-LocalXaml ($x)
        $b.Add_Click($script:H_FlyClick)
        $b.Add_MouseEnter($script:H_FlyHover)
        [void]$host_.Children.Add($b)
        [void]$script:FlyBtns.Add($b)
    }
    try { Sync-FlyRail ([string]$script:UiState.Page) } catch { }
}

# Gecerli sayfanin grubu vurgulanir
function Sync-FlyRail([string]$Page) {
    if ($script:FlyBtns.Count -eq 0) { return }
    $expert = ([string]$script:UiState.Mode -eq 'Expert')
    $cur = Get-NavGroupOf $Page $expert
    foreach ($b in $script:FlyBtns) {
        if ([string]$b.Tag -eq $cur) { $b.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, 'BrAccent') }
        else { $b.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, 'BrLine2') }
    }
}

# ---------------- kabuk: menu bicimi, yazi tipi, baslik metni ----------------
function Apply-DesignShell {
    $spec = Get-ActiveDesign
    $nav = [string]$spec.Nav
    $grid = $ui.RailHost.Parent
    $hidden = ($nav -eq 'Hidden')
    $fly = ($nav -eq 'Fly')
    Set-Visible $ui.BtnMenu ($hidden -or ($nav -eq 'Compact'))
    Set-Visible $ui.RailHost (-not $hidden)
    Set-Visible $ui.FlyRail $fly
    Set-Visible $ui.RailScroll (-not $fly)
    Set-Visible $ui.RailBottom (-not $fly)
    if ($hidden) {
        $grid.ColumnDefinitions[0].Width = New-Object System.Windows.GridLength -ArgumentList 0.0
        $script:RailMode = 'None'
    } elseif ($fly) {
        $grid.ColumnDefinitions[0].Width = New-Object System.Windows.GridLength -ArgumentList 84.0
        $script:RailMode = 'Fly'
        if ($script:FlyBtns.Count -eq 0) { Build-FlyRail } else { Sync-FlyRail ([string]$script:UiState.Page) }
    } elseif ($nav -eq 'Compact') {
        if ([string]$script:RailMode -ne 'Text') { Set-RailMode 'Compact' } else { Set-RailMode 'Text' }
    } else {
        Set-RailMode ([string](Get-LayoutDefaults ([string]$script:LayoutName)).Rail)
    }
    # yazi tipi: yerlesim tek aralikli istiyorsa ya da tasarim istiyorsa
    $mono = ([bool](Get-LayoutDefaults ([string]$script:LayoutName)).Mono) -or ($spec.Mono -eq $true)
    if ($mono) { $script:Win.FontFamily = New-Object System.Windows.Media.FontFamily -ArgumentList 'Cascadia Mono, Consolas, Courier New' }
    else { $script:Win.FontFamily = New-Object System.Windows.Media.FontFamily -ArgumentList 'Segoe UI' }
    if ($null -ne $ui.TxtTagline) {
        if ($script:TaglineOrig -eq '') { $script:TaglineOrig = [string]$ui.TxtTagline.Text }
        if ([string]$spec.Tagline -ne '') { $ui.TxtTagline.Text = (Tr $([string]$spec.Tagline)) }
        elseif ([string]$script:LayoutName -ne 'Hacker') { $ui.TxtTagline.Text = (Tr $($script:TaglineOrig)) }
    }
    $script:RailH = 0
    try { Update-RailDensity } catch { }
    try { Reset-Responsive } catch { }
}

# Baslik cubugundaki menu dugmesi: gizli menude acilir liste, dar menude genislik degisimi
function Invoke-MenuButton {
    $spec = Get-ActiveDesign
    if ([string]$spec.Nav -eq 'Hidden') {
        $expert = ([string]$script:UiState.Mode -eq 'Expert')
        Show-ItemMenu $ui.BtnMenu @(Get-NavMenuItems '' $expert) 'Bottom'
    } else {
        Switch-RailWidth
    }
}

# Menu seridini dar / yazili arasinda degistirir (Morpheus ve Komuta)
function Switch-RailWidth {
    if ([string]$script:RailMode -eq 'Text') { Set-RailMode 'Compact' } else { Set-RailMode 'Text' }
    try { Update-RailDensity } catch { }
}

# ---------------- tasarim secimi ----------------
function Set-AppDesign([string]$Key, [bool]$Refresh = $true) {
    $Key = ConvertTo-DesignKey $Key
    $script:DesignKey = $Key
    $spec = Get-ActiveDesign
    $fail = 0
    try { Set-DesignRadii ([double]$spec.RadCard) ([double]$spec.RadBtn) } catch { $fail++; Write-WhLog (('Tasar' + [char]0x0131 + 'm (k' + [char]0x00F6 + '' + [char]0x015F + 'eler): ') + $_.Exception.Message) 'WARN' }
    try { Apply-DesignShell } catch { $fail++; Write-WhLog (('Tasar' + [char]0x0131 + 'm (men' + [char]0x00FC + '): ') + $_.Exception.Message) 'WARN' }
    try { Update-BoardSkin } catch { $fail++; Write-WhLog (('Tasar' + [char]0x0131 + 'm (ana ekran): ') + $_.Exception.Message) 'WARN' }
    $script:DesignFail = $fail
    try { Close-NavMenu } catch { }
    # ana ekrandaysak yeni tasarimin ana ekrani gosterilir
    try { if ($Refresh -and @('panel', 'board') -contains [string]$script:UiState.Page) { Show-Page 'panel' } } catch { }
    try { Update-ReduceMotion } catch { }
}

# Acilista kayitli tasarim uygulanir; bir sey olursa Klasik'e donulur
$script:DesignWired = $false

function Initialize-Design {
    if (-not $script:DesignWired -and $null -ne $ui.BtnMenu) {
        $script:DesignWired = $true
        $ui.BtnMenu.Add_Click({ Invoke-Safe { Invoke-MenuButton } ('Men' + [char]0x00FC + '') })
    }
    $k = ConvertTo-DesignKey ([string]$script:Settings.Design)
    $ok = $true
    try { Set-AppDesign $k $false; if ([int]$script:DesignFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Tasar' + [char]0x0131 + 'm uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok) {
        # Once secilen ayrintilar kaldirilir; yine olmazsa Klasik tasarim ve klasik durum panosu kullanilir
        $script:DesignFail = 0
        $saved = @{}
        foreach ($p in @($script:DsOptions.Keys)) { $saved[('Ds' + [string]$p)] = 'Auto' }
        try { Clear-DesignOverrides $script:Settings; Set-AppDesign $k $false } catch { $script:DesignFail = 1 }
        if ([int]$script:DesignFail -gt 0) {
            $saved['Design'] = 'Klasik'
            $saved['HomeMode'] = 'Klasik'
            $script:Settings.HomeMode = 'Klasik'
            try { Set-AppDesign 'Klasik' $false } catch { }
        }
        Set-SettingsKeys $saved
    }
}

function Select-Design([string]$Name) {
    $Name = ConvertTo-DesignKey $Name
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: tasar' + [char]0x0131 + 'm ') + $Name) } catch { }
    $script:Settings.Design = $Name
    # tasarim secilince ayrintilar tasarimin kendi degerlerine doner
    Clear-DesignOverrides $script:Settings
    $ok = $true
    try { Set-AppDesign $Name; if ([int]$script:DesignFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Tasar' + [char]0x0131 + 'm uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok) {
        try { Set-AppDesign 'Klasik' } catch { }
        $script:Settings.Design = 'Klasik'
        try { Load-StDesign } catch { }
        Show-Toast ('Tasar' + [char]0x0131 + 'm tam uygulanamad' + [char]0x0131 + '; Klasik tasar' + [char]0x0131 + 'ma d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn'
    }
    return $ok
}

# Ana ekran bicimi: Pano ya da Klasik durum panosu (her tasarimda)
function Select-HomeMode([string]$Name) {
    $Name = ConvertTo-HomeKey $Name
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: ana ekran ') + $Name) } catch { }
    $script:Settings.HomeMode = $Name
    $ok = $true
    try {
        if (@('panel', 'board') -contains [string]$script:UiState.Page) { Show-Page 'panel' }
    } catch { $ok = $false; Write-CrashLog (('Ana ekran uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok -and $Name -ne 'Klasik') {
        $script:Settings.HomeMode = 'Klasik'
        try { if (@('panel', 'board') -contains [string]$script:UiState.Page) { Show-Page 'panel' } } catch { }
        try { Load-StDesign } catch { }
        Show-Toast ('Pano a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '; klasik durum panosuna d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn'
    }
    return $ok
}

# Tasarimin tek bir ayrintisini (menu bicimi, koseler, yazi tipi, grafik, parca gorunumu) degistirir
function Select-DesignOverride([string]$Prop, [string]$Value) {
    $v = ConvertTo-DsValue $Prop $Value
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: tasar' + [char]0x0131 + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 's' + [char]0x0131 + ' ') + $Prop + ' ' + $v) } catch { }
    $script:Settings[('Ds' + $Prop)] = $v
    $ok = $true
    try { Set-AppDesign $script:DesignKey; if ([int]$script:DesignFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Tasar' + [char]0x0131 + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 's' + [char]0x0131 + ' uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok) {
        Clear-DesignOverrides $script:Settings
        try { Set-AppDesign $script:DesignKey } catch { }
        try { Load-StDesign } catch { }
        Show-Toast ('Bu ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' uygulanamad' + [char]0x0131 + '; tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n kendi de' + [char]0x011F + 'erlerine d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn'
    }
    return $ok
}

# Tum ayrintilari tasarimin kendi degerlerine dondurur
function Reset-DesignOverrides {
    Clear-DesignOverrides $script:Settings
    $ok = $true
    try { Set-AppDesign $script:DesignKey; if ([int]$script:DesignFail -gt 0) { $ok = $false } } catch { $ok = $false; Write-CrashLog (('Tasar' + [char]0x0131 + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    return $ok
}

# ---------------- Ayarlar sayfasindaki tasarim denetimleri (acilir listeler; yardimcilar Gorunum bolumunde) ----------------
function Update-StDesignText {
    try {
        $k = ConvertTo-DesignKey ([string]$script:Settings.Design)
        $txt = ([string]$script:DesignInfo[$k].T + ': ' + [string]$script:DesignInfo[$k].D)
        if (Test-DesignOverridden $script:Settings) { $txt = $txt + (' Baz' + [char]0x0131 + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' kendiniz se' + [char]0x00E7 + 'tiniz (a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'daki Tasar' + [char]0x0131 + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ').') }
        if ($ui.st_DsDesc) { $ui.st_DsDesc.Text = (Tr $($txt)) }
        $h = ConvertTo-HomeKey (Get-BoardField $script:Settings 'HomeMode')
        if ($ui.st_HomeDesc) { $ui.st_HomeDesc.Text = (Tr $([string]$script:HomeInfo[$h].D)) }
    } catch { }
}

function Initialize-StDesignChoices {
    $d = New-Object System.Collections.ArrayList
    foreach ($k in @($script:DesignInfo.Keys)) { [void]$d.Add((New-Choice ([string]$k) ([string]$script:DesignInfo[$k].T))) }
    Set-ComboChoices $ui.st_DesignSel $d.ToArray()
    $h = New-Object System.Collections.ArrayList
    foreach ($k in @($script:HomeInfo.Keys)) { [void]$h.Add((New-Choice ([string]$k) ([string]$script:HomeInfo[$k].T))) }
    Set-ComboChoices $ui.st_HomeSel $h.ToArray()
    foreach ($p in @($script:DsOptions.Keys)) {
        $c = New-Object System.Collections.ArrayList
        foreach ($k in @($script:DsOptions[$p].Keys)) { [void]$c.Add((New-Choice ([string]$k) ([string]$script:DsOptions[$p][$k]))) }
        Set-ComboChoices $ui[('st_Ds' + [string]$p + 'Sel')] $c.ToArray()
    }
}

function Load-StDesign {
    $s = $script:Settings
    Select-ComboKey $ui.st_DesignSel (ConvertTo-DesignKey ([string]$s.Design))
    Select-ComboKey $ui.st_HomeSel (ConvertTo-HomeKey (Get-BoardField $s 'HomeMode'))
    foreach ($p in @($script:DsOptions.Keys)) {
        Select-ComboKey $ui[('st_Ds' + [string]$p + 'Sel')] (ConvertTo-DsValue ([string]$p) (Get-BoardField $s ('Ds' + [string]$p)))
    }
    if ($null -ne $ui.st_DsAdv -and (Test-DesignOverridden $s)) { $ui.st_DsAdv.IsChecked = $true }
    Update-StDesignText
}

function Save-StDesign {
    $s = $script:Settings
    $want = Get-ComboKey $ui.st_DesignSel
    $designChanged = $false
    if ($want -ne '' -and (ConvertTo-DesignKey $want) -ne (ConvertTo-DesignKey ([string]$s.Design))) { [void](Select-Design $want); $designChanged = $true }
    $hm = Get-ComboKey $ui.st_HomeSel
    if ($hm -ne '' -and (ConvertTo-HomeKey $hm) -ne (ConvertTo-HomeKey (Get-BoardField $s 'HomeMode'))) { [void](Select-HomeMode $hm) }
    # Tasarim degisince ayrinti listeleri henuz eski secimleri gosterir; Select-Design ayrintilari sifirladigi icin onlar geri yazilmaz
    if (-not $designChanged) {
        foreach ($p in @($script:DsOptions.Keys)) {
            $v = Get-ComboKey $ui[('st_Ds' + [string]$p + 'Sel')]
            if ($v -ne '' -and (ConvertTo-DsValue ([string]$p) $v) -ne (ConvertTo-DsValue ([string]$p) (Get-BoardField $s ('Ds' + [string]$p)))) { [void](Select-DesignOverride ([string]$p) $v) }
        }
    }
    # tasarim ya da ayrinti degisince diger listeler de guncel degere cekilir
    Load-StDesign
}


