# ---------------- saf yardimcilar (ekrana dokunmaz; testlerde de kullanilir) ----------------
function Format-BoardNum([double]$V) {
    return $V.ToString('0.##', [System.Globalization.CultureInfo]::InvariantCulture)
}

# Son degerlerden cizgi noktalari: en yeni deger sagda. Vals eskiden yeniye; Max ust sinir; Cap kac degerin sigdigi
function Get-SparkPoints($Vals, [double]$W, [double]$H, [double]$Max, [int]$Cap) {
    $arr = @($Vals)
    $n = $arr.Count
    if ($n -lt 2 -or $W -le 1 -or $H -le 1) { return '' }
    if ($Max -lt 0.0001) { $Max = 1.0 }
    if ($Cap -lt 2) { $Cap = 2 }
    $step = $W / [double]($Cap - 1)
    $pts = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt $n; $i++) {
        $v = [double]$arr[$i]
        if ($v -lt 0) { $v = 0 }
        if ($v -gt $Max) { $v = $Max }
        $x = $W - ([double]($n - 1 - $i)) * $step
        if ($x -lt 0) { continue }
        $y = $H - ($v / $Max) * ($H - 3.0) - 1.5
        [void]$pts.Add((Format-BoardNum $x) + ',' + (Format-BoardNum $y))
    }
    return ($pts -join ' ')
}

# Altigen izgara merkezleri (sivri tepeli altigen, yaricap R); satir sirasiyla
function Get-HexCells([double]$W, [double]$H, [double]$R) {
    $cells = New-Object System.Collections.ArrayList
    if ($R -lt 3 -or $W -lt 2 * $R -or $H -lt 2 * $R) { return $cells.ToArray() }
    $dx = [math]::Sqrt(3.0) * $R
    $dy = 1.5 * $R
    $row = 0
    $y = $R
    while (($y + $R) -le ($H + 0.5)) {
        $off = 0.0
        if (($row % 2) -eq 1) { $off = $dx / 2.0 }
        $x = $dx / 2.0 + $off
        while (($x + $dx / 2.0) -le ($W + 0.5)) {
            [void]$cells.Add(@{ X = $x; Y = $y })
            $x += $dx
        }
        $y += $dy
        $row++
    }
    return $cells.ToArray()
}

# Secilen hucrelerin tek bir yol (Path) verisi; Shrink hucreler arasinda bosluk birakir
function Get-HexPath($Cells, [double]$R, [double]$Shrink = 0.9) {
    $sb = New-Object System.Text.StringBuilder
    $rr = $R * $Shrink
    foreach ($c in @($Cells)) {
        for ($k = 0; $k -lt 6; $k++) {
            $a = (60.0 * $k - 30.0) * [math]::PI / 180.0
            $px = [double]$c.X + $rr * [math]::Cos($a)
            $py = [double]$c.Y + $rr * [math]::Sin($a)
            if ($k -eq 0) { [void]$sb.Append('M') } else { [void]$sb.Append(' L') }
            [void]$sb.Append((Format-BoardNum $px) + ',' + (Format-BoardNum $py))
        }
        [void]$sb.Append(' Z ')
    }
    return $sb.ToString().Trim()
}

# Radar yerlesimi: merkez yonlendirici; cihazlar halkalara dizilir. Donus: @{ X; Y } dizisi (Count kadar)
function Get-RadarSlots([int]$Count, [double]$Cx, [double]$Cy, [double]$Rad) {
    $out = New-Object System.Collections.ArrayList
    $rings = @(@{ N = 8; R = 0.42 }, @{ N = 14; R = 0.7 }, @{ N = 24; R = 0.92 })
    $left = $Count
    $ri = 0
    while ($left -gt 0 -and $ri -lt $rings.Count) {
        $cap = [int]$rings[$ri].N
        $take = [math]::Min($left, $cap)
        if ($ri -eq ($rings.Count - 1)) { $take = $left }
        for ($i = 0; $i -lt $take; $i++) {
            $a = (-90.0 + 360.0 * $i / $take + 17.0 * $ri) * [math]::PI / 180.0
            $dist = [double]$rings[$ri].R * $Rad
            [void]$out.Add(@{ X = $Cx + $dist * [math]::Cos($a); Y = $Cy + $dist * [math]::Sin($a) })
        }
        $left -= $take
        $ri++
    }
    return $out.ToArray()
}

# Islemci adi kisa bicim (Update-SysInfo ile ayni kural)
function Get-CpuShortName([string]$Name) {
    $cn = [regex]::Replace($Name, '\(R\)|\(TM\)|CPU|Processor|@.*$', '')
    return (($cn -replace '\s+', ' ').Trim())
}

# Arama kutusu: sayfalar, eylemler ve komutlar. Donus: Show-ItemMenu ogeleri (Text, Sub, Ico, Tag)
function Get-BoardSearchResults([string]$Text) {
    $q = (ConvertTo-AsciiKey $Text).Trim()
    $res = New-Object System.Collections.ArrayList
    if ($q -eq '') { return $res.ToArray() }
    $toks = @($q -split '\s+' | Where-Object { $_ -ne '' })
    $cands = New-Object System.Collections.ArrayList
    foreach ($k in @($script:PageNames.Keys)) {
        $hay = ((ConvertTo-AsciiKey ([string]$script:PageNames[$k])) + ' ' + [string]$k + ' ' + [string]$script:BoardSearchWords[$k]).Trim()
        if ($script:LangOn -eq $true) { $hay = $hay + ' ' + (ConvertTo-AsciiKey (Tr ([string]$script:PageNames[$k]))) }
        [void]$cands.Add(@{ Hay = $hay; Text = [string]$script:PageNames[$k]; Sub = [string]$script:PageSubs[$k]; Ico = [string]$script:PageIcons[$k]; Tag = ('nav:' + $k); Pri = 0 })
    }
    foreach ($k in @($script:BoardActions.Keys)) {
        $a = $script:BoardActions[$k]
        $hay = ((ConvertTo-AsciiKey ([string]$a.T)) + ' ' + (ConvertTo-AsciiKey ([string]$a.D)) + ' ' + [string]$k + ' ' + [string]$a.K).Trim()
        if ($script:LangOn -eq $true) { $hay = $hay + ' ' + (ConvertTo-AsciiKey (Tr ([string]$a.T))) + ' ' + (ConvertTo-AsciiKey (Tr ([string]$a.D))) }
        [void]$cands.Add(@{ Hay = $hay; Text = [string]$a.T; Sub = [string]$a.D; Ico = [string]$a.Ico; Tag = ('act:' + $k); Pri = 1 })
    }
    foreach ($c in $cands) {
        $words = @(([string]$c.Hay) -split '\s+')
        $score = 0
        $all = $true
        foreach ($t in $toks) {
            $best = 0
            foreach ($w in $words) {
                if ($w -eq $t) { $best = [math]::Max($best, 3) }
                elseif ($w.StartsWith($t)) { $best = [math]::Max($best, 2) }
                elseif (($t.Length -ge 3 -or ($t.Length -ge 2 -and $t -cmatch '[^\x00-\x7F]')) -and $w.Contains($t)) { $best = [math]::Max($best, 1) }
            }
            if ($best -eq 0) { $all = $false; break }
            $score += $best
        }
        if ($all) { [void]$res.Add(@{ Score = $score - 0.1 * [int]$c.Pri; Item = $c }) }
    }
    $sorted = @($res | Sort-Object @{ Expression = { -[double]$_.Score } }, @{ Expression = { [string]$_.Item.Text } })
    $out = New-Object System.Collections.ArrayList
    # komut: ilk sozcuk bilinen bir komutsa ve bagimsiz degiskeni varsa en ustte
    $first = [string]$toks[0]
    if ($script:CmdDefs.Contains($first) -and $toks.Count -ge 2) {
        [void]$out.Add(@{ Text = ('Komut: ' + $Text.Trim()); Sub = [string]$script:CmdDefs[$first]; Ico = 'IcoTerminal'; Tag = ('cmd:' + $Text.Trim()) })
    }
    foreach ($s in $sorted) {
        if ($out.Count -ge 7) { break }
        $it = $s.Item
        [void]$out.Add(@{ Text = [string]$it.Text; Sub = [string]$it.Sub; Ico = [string]$it.Ico; Tag = [string]$it.Tag })
    }
    if ($out.Count -eq 0 -and $script:CmdDefs.Contains($first)) {
        [void]$out.Add(@{ Text = ('Komut: ' + $Text.Trim()); Sub = [string]$script:CmdDefs[$first]; Ico = 'IcoTerminal'; Tag = ('cmd:' + $Text.Trim()) })
    }
    return $out.ToArray()
}

