      <StackPanel Orientation="Horizontal" Margin="14,12,14,6" IsHitTestVisible="False">
        <ContentControl x:Name="Ico" Style="{DynamicResource Icon}" Width="15" Height="15" Foreground="{DynamicResource BrAccent}"/>
        <TextBlock x:Name="Ttl" Style="{DynamicResource TxtCardTitle}" Margin="7,0,0,0"/>
      </StackPanel>
      <StackPanel x:Name="Lst" Grid.Row="1" Margin="14,0,14,10" IsHitTestVisible="False"/>
    </Grid>
'@

$script:BoardXaml['radar'] = @'
    <Grid>
      <Canvas x:Name="Cv" ClipToBounds="True" IsHitTestVisible="False"/>
      <StackPanel Orientation="Horizontal" Margin="14,12,14,6" VerticalAlignment="Top" HorizontalAlignment="Left" IsHitTestVisible="False">
        <ContentControl x:Name="Ico" Style="{DynamicResource Icon}" Width="15" Height="15" Foreground="{DynamicResource BrAccent}"/>
        <TextBlock x:Name="Ttl" Style="{DynamicResource TxtCardTitle}" Margin="7,0,0,0"/>
      </StackPanel>
      <TextBlock x:Name="Sub" Text="" FontSize="11" Foreground="{DynamicResource BrDim}" VerticalAlignment="Bottom" HorizontalAlignment="Left" Margin="14,0,14,10" IsHitTestVisible="False" TextTrimming="CharacterEllipsis"/>
    </Grid>
'@

$script:BoardXaml['hex'] = @'
    <Grid>
      <Canvas x:Name="Cv" ClipToBounds="True" IsHitTestVisible="False">
        <Path x:Name="HOff" Fill="{DynamicResource BrLine}" Opacity="0.55"/>
        <Path x:Name="HOn" Fill="{DynamicResource BrAccent}"/>
      </Canvas>
      <StackPanel Orientation="Horizontal" Margin="14,12,14,6" VerticalAlignment="Top" HorizontalAlignment="Left" IsHitTestVisible="False">
        <ContentControl x:Name="Ico" Style="{DynamicResource Icon}" Width="15" Height="15" Foreground="{DynamicResource BrAccent}"/>
        <TextBlock x:Name="Ttl" Style="{DynamicResource TxtCardTitle}" Margin="7,0,0,0"/>
      </StackPanel>
      <TextBlock x:Name="Sub" Text="" FontSize="11" Foreground="{DynamicResource BrDim}" VerticalAlignment="Bottom" HorizontalAlignment="Left" Margin="14,0,14,10" IsHitTestVisible="False" TextTrimming="CharacterEllipsis"/>
    </Grid>
'@

# ---------------- geometri ----------------
function Update-BoardMetrics {
    $spec = Get-ActiveDesign
    $w = 0.0
    try { $w = [double]$ui.bd_Scroll.ActualWidth } catch { $w = 0.0 }
    if ($w -lt 200) { try { $w = [double]$ui.PageHost.ActualWidth - 20 } catch { $w = 0.0 } }
    if ($w -lt 200) { $w = 900.0 }
    $w = $w - 4
    $m = $script:BoardMetrics
    $m.Gap = [double]$spec.Gap
    $m.CellH = [double]$spec.CellH
    $m.W = $w
    $m.CellW = [double](Get-BoardCellW $w $m.Gap)
}

function Get-BoardKind($Tile) {
    $t = [string]$Tile.Type
    if (@('cpu', 'ram', 'disk', 'net', 'gpu', 'temp') -contains $t) { return 'metric' }
    if ($t -eq 'action') { if ([int]$Tile.H -le 2) { return 'actionH' } else { return 'actionV' } }
    if (@('top', 'log', 'sysinfo') -contains $t) { return 'list' }
    return $t
}

function Set-ResRef($El, $Prop, [string]$Key) {
    if ($null -ne $El) { $El.SetResourceReference($Prop, $Key) }
}

# Dosemeyi kendi hucre dikdortgenine yerlestirir; Animate ise 140 ms kayar
function Set-TilePlace($V, $Tile, [bool]$Animate) {
    $m = $script:BoardMetrics
    $r = Get-BoardRect $Tile $m.CellW $m.CellH $m.Gap
    $el = $V.Root
    $oldL = [System.Windows.Controls.Canvas]::GetLeft($el)
    $oldT = [System.Windows.Controls.Canvas]::GetTop($el)
    $el.Width = [double]$r.W
    $el.Height = [double]$r.H
    [System.Windows.Controls.Canvas]::SetLeft($el, [double]$r.X)
    [System.Windows.Controls.Canvas]::SetTop($el, [double]$r.Y)
    if ($Animate -and -not $script:ReduceMotion -and -not [double]::IsNaN($oldL) -and -not [double]::IsNaN($oldT)) {
        if ([math]::Abs($oldL - [double]$r.X) -gt 0.5) { Start-TileSlide $el ([System.Windows.Controls.Canvas]::LeftProperty) $oldL ([double]$r.X) }
        if ([math]::Abs($oldT - [double]$r.Y) -gt 0.5) { Start-TileSlide $el ([System.Windows.Controls.Canvas]::TopProperty) $oldT ([double]$r.Y) }
    }
    Resize-TileContent $V $r
}

function Start-TileSlide($El, $Prop, [double]$From, [double]$To) {
    $a = New-Object System.Windows.Media.Animation.DoubleAnimation
    $a.From = $From
    $a.To = $To
    $a.Duration = New-Object System.Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds(150))
    $a.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
    $ease = New-Object System.Windows.Media.Animation.QuadraticEase
    $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
    $a.EasingFunction = $ease
    $El.BeginAnimation($Prop, $a)
}

# Doseme boyutu degisince ic ogeler (grafik, kirpma) uyarlanir
function Resize-TileContent($V, $R) {
    $w = [double]$R.W
    $h = [double]$R.H
    $n = $V.N
    $key = ([string][int]$w + 'x' + [string][int]$h)
    if ($V.Size -eq $key) { return }
    $V.Size = $key
    try {
        $rad = [double]((Get-ActiveDesign).RadCard)
        $clip = New-Object System.Windows.Media.RectangleGeometry
        $clip.Rect = New-Object System.Windows.Rect -ArgumentList 0.0, 0.0, ([math]::Max(1.0, $w - 2.0)), ([math]::Max(1.0, $h - 2.0))
        $clip.RadiusX = [math]::Max(0.0, $rad - 1.0)
        $clip.RadiusY = [math]::Max(0.0, $rad - 1.0)
        $n.Inner.Clip = $clip
    } catch { }
    if ($V.Kind -eq 'metric') {
        $n.Gr.Width = [math]::Max(10.0, $w - 2.0)
        $n.Gr.Height = [math]::Max(16.0, [math]::Min(60.0, $h * 0.48))
    }
    if ($V.Kind -eq 'radar' -or $V.Kind -eq 'hex') { $V.Dirty = $true }
}

function Update-BoardGeometry([bool]$Animate = $false) {
    if (-not $script:BoardBuilt -or $null -eq $script:BoardLayout) { return }
    Update-BoardMetrics
    $m = $script:BoardMetrics
    $rows = Get-BoardRows $script:BoardLayout
    $ui.bd_Canvas.Width = [double]$m.W
    $ui.bd_Canvas.Height = [math]::Max(120.0, $rows * ($m.CellH + $m.Gap) + 8.0)
    foreach ($t in $script:BoardLayout) {
        $v = $script:BoardViews[[string]$t.Id]
        if ($null -eq $v) { continue }
        if ($null -ne $script:BoardDrag -and [string]$script:BoardDrag.Id -eq [string]$t.Id) { continue }
        Set-TilePlace $v $t $Animate
    }
    $script:BoardLastGeo = [double]$m.W
    try { Update-BoardLive $null } catch { }
}

# ---------------- doseme olusturma ----------------
function Get-BoardTitle([string]$Type, [string]$Arg) {
    if (($Type -eq 'action' -or $Type -eq 'cta') -and $script:BoardActions.Contains($Arg)) { return [string]$script:BoardActions[$Arg].T }
    return [string]$script:BoardWidgets[$Type].T
}

function New-BoardTileView($Tile) {
    $kind = Get-BoardKind $Tile
    $content = [string]$script:BoardXaml[$kind]
    if ($content -eq '') { return $null }
    $xaml = $script:BoardShellHead + $content + $script:BoardShellTail
    $root = Read-LocalXaml ($xaml)
    $n = @{}
    foreach ($m in [regex]::Matches($xaml, 'x:Name="([A-Za-z0-9_]+)"')) {
        $nm = $m.Groups[1].Value
        $c = $root.FindName($nm)
        if ($null -ne $c) { $n[$nm] = $c }
    }
    $id = [string]$Tile.Id
    $v = @{ Id = $id; Type = [string]$Tile.Type; Arg = [string]$Tile.Arg; Kind = $kind; Root = $root; N = $n; Size = ''; Dirty = $true; Rot = $null }
    $root.Tag = $id
    foreach ($nm in @('Veil', 'Del', 'Grip', 'Hit', 'Act')) { if ($n.ContainsKey($nm)) { $n[$nm].Tag = $id } }
    $n.Veil.Add_MouseLeftButtonDown($script:H_BdDown)
    $n.Veil.Add_MouseMove($script:H_BdMove)
    $n.Veil.Add_MouseLeftButtonUp($script:H_BdUp)
    $n.Veil.Add_LostMouseCapture($script:H_BdLost)
    $n.Grip.Add_MouseLeftButtonDown($script:H_BdDown)
    $n.Grip.Add_MouseMove($script:H_BdMove)
    $n.Grip.Add_MouseLeftButtonUp($script:H_BdUp)
    $n.Grip.Add_LostMouseCapture($script:H_BdLost)
    $n.Del.Add_Click($script:H_BdDel)
    if ($n.ContainsKey('Hit')) { $n.Hit.Add_Click($script:H_BdHit) }
    if ($n.ContainsKey('Act')) { $n.Act.Add_Click({ Invoke-Safe { Start-HealthScan 'Quick' $false } ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k') }) }
    if ($n.ContainsKey('Inp')) {
        $n.Inp.Add_TextChanged({ param($s, $e) Invoke-Safe { Update-BoardSearch $s } 'Arama' })
        $n.Inp.Add_PreviewKeyDown({ param($s, $e) Invoke-Safe { Invoke-BoardSearchKey $s $e } 'Arama' })
    }
    $rt = New-Object System.Windows.Media.RotateTransform
    $root.RenderTransform = $rt
    $root.RenderTransformOrigin = New-Object System.Windows.Point -ArgumentList 0.5, 0.5
    $v.Rot = $rt
    Initialize-TileTexts $v $Tile
    Apply-TileSkin $v
    return $v
}

# Dosemenin sabit metin ve simgeleri
function Initialize-TileTexts($V, $Tile) {
    $n = $V.N
    $type = [string]$Tile.Type
    $arg = [string]$Tile.Arg
    $spec = Get-ActiveDesign
    $title = Get-BoardTitle $type $arg
    $icoKey = [string]$script:BoardWidgets[$type].Ico
    if (($type -eq 'action' -or $type -eq 'cta') -and $script:BoardActions.Contains($arg)) { $icoKey = [string]$script:BoardActions[$arg].Ico }
    if ($n.ContainsKey('Ico')) { $n.Ico.SetResourceReference([System.Windows.FrameworkElement]::TagProperty, $icoKey) }
    if ($n.ContainsKey('Ttl')) {
        if (@('Neon', 'Slate') -contains [string]$spec.Skin) { $n.Ttl.Text = (Tr $((ConvertTo-TrUpper $title))) } else { $n.Ttl.Text = (Tr $($title)) }
    }
    if ($type -eq 'action' -and $script:BoardActions.Contains($arg)) { $n.Sub.Text = (Tr $([string]$script:BoardActions[$arg].D)) }
    if ($type -eq 'hero') {
        $h = Get-DesignHero $script:DesignKey
        $n.Ttl.Text = (Tr $([string]$h.T))
        $n.Sub.Text = (Tr $([string]$h.S))
    }
    if ($type -eq 'radar' -or $type -eq 'hex') { $n.Sub.Text = (Tr $('')) }
    if ($n.ContainsKey('Del')) {
        [System.Windows.Automation.AutomationProperties]::SetName($n.Del, (Tr ('Par' + [char]0x00E7 + 'ay' + [char]0x0131 + ' kald' + [char]0x0131 + 'r')) + ': ' + (Tr $title))
    }
}

# Tasarima gore doseme gorunumu
function Apply-TileSkin($V) {
    $spec = Get-ActiveDesign
    $skin = [string]$spec.Skin
    $n = $V.N
    $root = $V.Root
    $B = [System.Windows.Controls.Border]
    $fill = 'BrPanel'; $edge = 'BrLine'; $th = 1.0; $gloss = $false; $bar = $false
    if ($skin -eq 'Glass') { $fill = 'BrCard'; $edge = 'BrLine2'; $gloss = $true }
    elseif ($skin -eq 'Calm') { $fill = 'BrCard'; $edge = 'BrCard'; $th = 0.0 }
    elseif ($skin -eq 'Neon') { $fill = 'BrBg'; $edge = 'BrAccent' }
    elseif ($skin -eq 'Slate') { $bar = $true }
    $type = [string]$V.Type
    if ($type -eq 'cta') { $edge = 'BrAccent'; $fill = 'BrActiveBg'; $th = 1.5 }
    if ($type -eq 'hero') { if ($skin -eq 'Calm') { $fill = 'BrBg'; $edge = 'BrBg' } }
    if ($type -eq 'search') { $edge = 'BrLine2'; $th = 1.0; if ($skin -eq 'Calm') { $fill = 'BrCard' } }
    Set-ResRef $root ($B::BackgroundProperty) $fill
    Set-ResRef $root ($B::BorderBrushProperty) $edge
    $root.BorderThickness = New-Object System.Windows.Thickness -ArgumentList $th
    Set-Visible $n.Gloss $gloss
    Set-Visible $n.Bar $bar
    # parca rengi: Neon tek renk (parlayan cizgi), digerleri anlamina gore
    $acc = Get-TileAccent $type ([string]$V.Arg) $skin
    foreach ($nm in @('Ico')) { if ($n.ContainsKey($nm) -and $type -ne 'search') { Set-ResRef $n[$nm] ([System.Windows.Controls.Control]::ForegroundProperty) $acc } }
    if ($n.ContainsKey('Ln')) {
        Set-ResRef $n.Ln ([System.Windows.Shapes.Shape]::StrokeProperty) $acc
        Set-ResRef $n.Ar ([System.Windows.Shapes.Shape]::FillProperty) $acc
        $n.Ln.StrokeThickness = 1.6
        if ([string]$spec.Graph -eq 'scope') { $n.Ln.StrokeThickness = 1.3; Set-Visible $n.Ar $false; Set-Visible $n.Gd $true }
        else { Set-Visible $n.Ar ([string]$spec.Graph -eq 'area'); Set-Visible $n.Gd $false }
        Set-Visible $n.Gr ([string]$spec.Graph -ne 'none')
    }
    if ($n.ContainsKey('Plate')) {
        if ($skin -eq 'Neon') { Set-ResRef $n.Plate ($B::BackgroundProperty) 'BrBg'; Set-ResRef $n.Plate ($B::BorderBrushProperty) 'BrAccent'; $n.Plate.BorderThickness = New-Object System.Windows.Thickness -ArgumentList 1.0 }
        else { Set-ResRef $n.Plate ($B::BackgroundProperty) (Get-TileSoft $acc); $n.Plate.BorderThickness = New-Object System.Windows.Thickness -ArgumentList 0.0 }
        $n.Plate.CornerRadius = New-Object System.Windows.CornerRadius -ArgumentList ([math]::Max(2.0, [double]$spec.RadBtn + 2.0))
    }
    if ($skin -eq 'Neon') {
        if ($n.ContainsKey('Val')) { Set-ResRef $n.Val ([System.Windows.Controls.TextBlock]::ForegroundProperty) 'BrAccent' }
    } else {
        if ($n.ContainsKey('Val') -and $type -ne 'health') { Set-ResRef $n.Val ([System.Windows.Controls.TextBlock]::ForegroundProperty) 'BrText' }
    }
    if ($type -eq 'hero') {
        $n.Ttl.FontSize = 26
        if ($skin -eq 'Calm') { $n.Ttl.FontSize = 30; $n.Ttl.FontWeight = [System.Windows.FontWeights]::Normal }
        if ($skin -eq 'Neon') { $n.Ttl.FontSize = 22 }
    }
    if ($type -eq 'search') {
        if ($skin -eq 'Calm') { $n.Inp.FontSize = 17 }
        $n.Ph.Visibility = $script:VisOn
    }
    $V.Size = ''
    $V.Dirty = $true
}

function Start-TileWiggle($V, [int]$Index) {
    try {
        if ($script:ReduceMotion) { return }
        $a = New-Object System.Windows.Media.Animation.DoubleAnimation
        $a.From = -0.6
        $a.To = 0.6
        $a.Duration = New-Object System.Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds(120))
        $a.AutoReverse = $true
        $a.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $a.BeginTime = [TimeSpan]::FromMilliseconds(($Index * 37) % 120)
        $V.Rot.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $a)
    } catch { }
}

function Stop-TileWiggle($V) {
    try {
        $V.Rot.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null)
        $V.Rot.Angle = 0.0
    } catch { }
}

# Duzenleme kipi acik/kapali
function Set-BoardEdit([bool]$On) {
    $script:BoardEdit = $On
    if ($null -eq $ui.bd_Canvas) { return }
    $i = 0
    foreach ($t in @($script:BoardLayout)) {
        $v = $script:BoardViews[[string]$t.Id]
        if ($null -eq $v) { continue }
        Set-Visible $v.N.Veil $On
        Set-Visible $v.N.Del $On
        Set-Visible $v.N.Grip $On
        if ($On) { Start-TileWiggle $v $i } else { Stop-TileWiggle $v }
        $i++
    }
    Set-Visible $ui.bd_BtnAdd $On
    Set-Visible $ui.bd_BtnLayout $On
    Set-Visible $ui.bd_BtnReset $On
    if ($On) {
        $ui.bd_BtnEdit.Content = (Tr $(('D' + [char]0x00FC + 'zeni kilitle')))
        $ui.bd_Hint.Text = (Tr $(('Par' + [char]0x00E7 + 'alar' + [char]0x0131 + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleyin; sa' + [char]0x011F + ' alttaki k' + [char]0x00F6 + '' + [char]0x015F + 'eden boyutland' + [char]0x0131 + 'r' + [char]0x0131 + 'n; ' + [char]0x2715 + ' ile kald' + [char]0x0131 + 'r' + [char]0x0131 + 'n. D' + [char]0x00FC + 'zen kendili' + [char]0x011F + 'inden kaydedilir.')))
    } else {
        $ui.bd_BtnEdit.Content = (Tr $(('D' + [char]0x00FC + 'zeni a' + [char]0x00E7 + '')))
        $ui.bd_Hint.Text = (Tr $(''))
    }
    Set-Visible $ui.bd_Hint $On
}

# ---------------- duzenin kaydi ve yuklenmesi ----------------
function Get-BoardActiveLayout {
    $spec = Get-ActiveDesign
    if ($script:Settings.BoardCustom -eq $true) {
        $l = ConvertTo-BoardLayout @($script:Settings.Board)
        if ($l.Count -gt 0) { return , $l }
    }
    return , (Get-BoardPreset ([string]$spec.Preset))
}

function Save-BoardLayout {
    Set-SettingsKeys @{ Board = (ConvertTo-BoardData $script:BoardLayout); BoardCustom = $true }
}

function Reset-BoardLayout {
    Set-SettingsKeys @{ Board = @(); BoardCustom = $false }
    Rebuild-BoardTiles
}

# Secilen hazir duzeni uygular ve kaydeder (kullanici sectigi icin ozel duzen sayilir; tasarim degisse de korunur)
function Select-BoardPreset([string]$Key) {
    if (-not $script:BoardPresetInfo.Contains($Key)) { return $false }
    $script:BoardLayout = Get-BoardPreset $Key
    Save-BoardLayout
    Rebuild-BoardTiles
    return $true
}

# Ana ekrani duzenleme kipinde acar. Klasik durum panosu seciliyse once pano bicimine gecilir (duzenlenebilen yalnizca panodur).
function Open-BoardEditor {
    if (-not (Test-BoardHome)) {
        [void](Select-HomeMode 'Pano')
        Save-Settings $script:Settings
        try { Load-StDesign } catch { }
    }
    Open-Page 'panel'
    Set-BoardEdit $true
}

# ---------------- pano kurulumu ----------------
function Rebuild-BoardTiles {
    if ($null -eq $ui.bd_Canvas) { return }
    $wasEdit = $script:BoardEdit
    $script:BoardDrag = $null
    $script:BoardGhost = $null
    $ui.bd_Canvas.Children.Clear()
    $script:BoardViews = @{}
    $script:BoardLayout = Get-BoardActiveLayout
    $spec = Get-ActiveDesign
    # surukleme golgesi
    $g = New-Object System.Windows.Controls.Border
    $g.IsHitTestVisible = $false
    $g.Visibility = $script:VisOff
    $g.BorderThickness = New-Object System.Windows.Thickness -ArgumentList 1.5
    $g.CornerRadius = New-Object System.Windows.CornerRadius -ArgumentList ([double]$spec.RadCard)
    $g.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BrAccent')
    $g.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'BrActiveBg')
    $g.Opacity = 0.55
    [System.Windows.Controls.Panel]::SetZIndex($g, 0)
    [void]$ui.bd_Canvas.Children.Add($g)
    $script:BoardGhost = $g
    $i = 0
    foreach ($t in $script:BoardLayout) {
        $v = New-BoardTileView $t
        if ($null -eq $v) { continue }
        [System.Windows.Controls.Panel]::SetZIndex($v.Root, 1)
        [void]$ui.bd_Canvas.Children.Add($v.Root)
        $script:BoardViews[[string]$t.Id] = $v
        if ([string]$spec.Skin -eq 'Calm' -and -not $script:ReduceMotion) { Start-TileFade $v.Root $i }
        $i++
    }
    $script:BoardBuilt = $true
    $script:BoardLastGeo = 0.0
    Update-BoardGeometry $false
    Set-BoardEdit $wasEdit
    $ui.bd_Title.Text = (Tr $(([string]$script:DesignInfo[$script:DesignKey].T)))
    if ($script:DesignKey -eq 'Klasik') { $ui.bd_Title.Text = (Tr $('Ana ekran (pano)')) }
}

function Start-TileFade($El, [int]$Index) {
    try {
        $a = New-Object System.Windows.Media.Animation.DoubleAnimation
        $a.From = 0.0
        $a.To = 1.0
        $a.Duration = New-Object System.Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds(520))
        $a.BeginTime = [TimeSpan]::FromMilliseconds($Index * 70)
        $a.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
        $El.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $a)
    } catch { }
}

# Tasarim degisince (Set-AppDesign) cagrilir
function Update-BoardSkin {
    if (-not $script:BoardBuilt) { return }
    Rebuild-BoardTiles
}

function Init-Page_board {
    $ui.bd_BtnEdit.Add_Click({ Invoke-Safe { Set-BoardEdit (-not $script:BoardEdit) } 'Pano' })
    $ui.bd_BtnAdd.Add_Click({ Invoke-Safe { Show-BoardAddMenu } 'Pano' })
    $ui.bd_BtnLayout.Add_Click({ Invoke-Safe { Show-BoardLayoutMenu } 'Pano' })
    $ui.bd_BtnReset.Add_Click({ Invoke-Safe { Reset-BoardLayout; Show-Toast ('Ana ekran bu tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zenine d' + [char]0x00F6 + 'nd' + [char]0x00FC + '.') 'info' } 'Pano' })
    $ui.bd_Scroll.Add_SizeChanged({
        try {
            $w = [double]$ui.bd_Scroll.ActualWidth
            if ([math]::Abs($w - $script:BoardLastGeo - 4.0) -gt 3.0 -and $null -eq $script:BoardDrag) { Update-BoardGeometry $false }
        } catch { Write-CrashLog ('Pano boyutu: ' + $_.Exception.Message) }
    })
    Rebuild-BoardTiles
}

function Show-Page_board {
    Initialize-LanSnap
    if (($null -eq $script:Health -or $script:HealthAt -eq [datetime]::MinValue) -and $null -ne $sync.Profile) { Start-HealthScan 'Quick' $true }
    Update-BoardGeometry $false
}

# ---------------- eylemler ----------------
function Invoke-BoardAction([string]$Key) {
    if (-not $script:BoardActions.Contains($Key)) { return }
    $a = $script:BoardActions[$Key]
    switch ([string]$a.Fn) {
        'health' { Start-HealthScan 'Quick' $false; return }
        'maint' { Start-QuickMaint; return }
        'audit' { Open-Page 'security'; Start-HealthScan 'Full' $false; return }
        'report' { Start-ReportNow; return }
    }
    if ([string]$a.Page -ne '') { Open-Page ([string]$a.Page) ([string](Get-BoardField $a 'Sub')) }
}

function Invoke-BoardCommand([string]$Text) {
    try { Switch-CmdPanel $true } catch { }
    Invoke-CmdLine $Text
}

$script:H_BdHit = {
    param($s, $e)
    Invoke-Safe {
        if ($script:BoardEdit) { return }
        $t = Find-BoardTile $script:BoardLayout ([string]$s.Tag)
        if ($null -eq $t) { return }
        Invoke-BoardAction ([string]$t.Arg)
    } 'Pano'
}

$script:H_BdDel = {
    param($s, $e)
    Invoke-Safe {
        $id = [string]$s.Tag
        if (Remove-BoardTile $script:BoardLayout $id) {
            Remove-BoardTileView $id
            Save-BoardLayout
            Update-BoardGeometry $true
        }
    } 'Pano'
}

function Remove-BoardTileView([string]$Id) {
    $v = $script:BoardViews[$Id]
    if ($null -eq $v) { return }
    $ui.bd_Canvas.Children.Remove($v.Root)
    $script:BoardViews.Remove($Id)
}

function Add-BoardWidget([string]$Type, [string]$Arg) {
    $t = Add-BoardTile $script:BoardLayout $Type $Arg
    if ($null -eq $t) { Show-Toast ('Bu par' + [char]0x00E7 + 'a eklenemedi: panoda zaten var ya da en ' + [char]0x00E7 + 'ok 24 par' + [char]0x00E7 + 'a kullan' + [char]0x0131 + 'labilir.') 'warn'; return $false }
    $v = New-BoardTileView $t
    if ($null -ne $v) {
        [System.Windows.Controls.Panel]::SetZIndex($v.Root, 1)
        [void]$ui.bd_Canvas.Children.Add($v.Root)
        $script:BoardViews[[string]$t.Id] = $v
        if ($script:BoardEdit) { Set-Visible $v.N.Veil $true; Set-Visible $v.N.Del $true; Set-Visible $v.N.Grip $true; Start-TileWiggle $v 0 }
    }
    Save-BoardLayout
    Update-BoardGeometry $true
    return $true
}

function Show-BoardLayoutMenu {
    $items = New-Object System.Collections.ArrayList
    [void]$items.Add(@{ Head = ('HAZIR D' + [char]0x00DC + 'ZENLER') })
    foreach ($k in @($script:BoardPresetInfo.Keys)) {
        $i = $script:BoardPresetInfo[$k]
        [void]$items.Add(@{ Text = [string]$i.T; Sub = [string]$i.D; Ico = 'IcoApps'; Tag = ('layout:' + [string]$k) })
    }
    Show-ItemMenu $ui.bd_BtnLayout $items.ToArray() 'Bottom'
}

function Show-BoardAddMenu {
    $items = New-Object System.Collections.ArrayList
    [void]$items.Add(@{ Head = ('PAR' + [char]0x00C7 + 'ALAR') })
    foreach ($k in @($script:BoardWidgets.Keys)) {
        if ($k -eq 'action' -or $k -eq 'cta') { continue }
        $w = $script:BoardWidgets[$k]
        if ([bool]$w.Uniq) {
            $have = $false
            foreach ($t in $script:BoardLayout) { if ([string]$t.Type -eq [string]$k) { $have = $true } }
            if ($have) { continue }
        }
        [void]$items.Add(@{ Text = [string]$w.T; Sub = [string]$w.D; Ico = [string]$w.Ico; Tag = ('add:' + $k) })
    }
    [void]$items.Add(@{ Head = 'EYLEM KARTLARI' })
    foreach ($k in @($script:BoardActions.Keys)) {
        $a = $script:BoardActions[$k]
        [void]$items.Add(@{ Text = [string]$a.T; Sub = [string]$a.D; Ico = [string]$a.Ico; Tag = ('addact:' + $k) })
    }
    [void]$items.Add(@{ Head = ('B' + [char]0x00DC + 'Y' + [char]0x00DC + 'K D' + [char]0x00DC + '' + [char]0x011E + 'ME') })
    [void]$items.Add(@{ Text = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm d' + [char]0x00FC + '' + [char]0x011F + 'mesi'); Sub = ('Geni' + [char]0x015F + ' bir d' + [char]0x00FC + '' + [char]0x011F + 'me; onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla h' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm' + [char]0x0131 + ' ba' + [char]0x015F + 'lat' + [char]0x0131 + 'r.'); Ico = 'IcoPlay'; Tag = 'addcta:maint' })
    Show-ItemMenu $ui.bd_BtnAdd $items.ToArray() 'Bottom'
}

# ---------------- surukle-birak ----------------
$script:H_BdDown = {
    param($s, $e)
    Invoke-Safe {
        if (-not $script:BoardEdit) { return }
        $mode = 'move'
        if ([string]$s.Name -eq 'Grip') { $mode = 'size' }
        Start-BoardDrag $s $e $mode
    } 'Pano'
}
$script:H_BdMove = {
    param($s, $e)
    if ($null -eq $script:BoardDrag) { return }
    try { Step-BoardDrag $e } catch { Write-CrashLog (('Pano s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme: ') + $_.Exception.Message); try { Stop-BoardDrag $false } catch { } }
}
$script:H_BdUp = {
    param($s, $e)
    Invoke-Safe { if ($null -ne $script:BoardDrag) { Stop-BoardDrag $true; $e.Handled = $true } } 'Pano'
}
$script:H_BdLost = {
    param($s, $e)
    try { if ($null -ne $script:BoardDrag) { Stop-BoardDrag $false } } catch { }
}

function Start-BoardDrag($S, $E, [string]$Mode) {
    $id = [string]$S.Tag
    $v = $script:BoardViews[$id]
    $t = Find-BoardTile $script:BoardLayout $id
    if ($null -eq $v -or $null -eq $t) { return }
    $p = $E.GetPosition($ui.bd_Canvas)
    $m = $script:BoardMetrics
    $rect = Get-BoardRect $t $m.CellW $m.CellH $m.Gap
    $script:BoardDrag = @{ Id = $id; Mode = $Mode; Src = $S; OffX = $p.X - [double]$rect.X; OffY = $p.Y - [double]$rect.Y; Rect = $rect; Key = ''; Work = $null }
    [void]$S.CaptureMouse()
    [System.Windows.Controls.Panel]::SetZIndex($v.Root, 50)
    $v.Root.Opacity = 0.92
    $E.Handled = $true
}

function Step-BoardDrag($E) {
    $d = $script:BoardDrag
    $v = $script:BoardViews[[string]$d.Id]
    if ($null -eq $v) { return }
    $p = $E.GetPosition($ui.bd_Canvas)
    $m = $script:BoardMetrics
    $rect = $d.Rect
    if ($d.Mode -eq 'move') {
        $left = $p.X - [double]$d.OffX
        $top = $p.Y - [double]$d.OffY
        $maxL = [double]$m.W - [double]$rect.W
        if ($left -gt $maxL) { $left = $maxL }
        if ($left -lt 0) { $left = 0 }
        if ($top -lt 0) { $top = 0 }
        [System.Windows.Controls.Canvas]::SetLeft($v.Root, $left)
        [System.Windows.Controls.Canvas]::SetTop($v.Root, $top)
        $c = Get-BoardCell $left $top $m.CellW $m.CellH $m.Gap
        $key = ([string]$c.X + ',' + [string]$c.Y)
        if ($key -ne $d.Key) {
            $d.Key = $key
            $work = Copy-BoardLayout $script:BoardLayout
            [void](Move-BoardTile $work ([string]$d.Id) $c.X $c.Y)
            $d.Work = $work
            Show-BoardPreview $work ([string]$d.Id)
        }
    } else {
        $w = $p.X - [double]$rect.X
        $h = $p.Y - [double]$rect.Y
        if ($w -lt $m.CellW) { $w = $m.CellW }
        if ($h -lt $m.CellH) { $h = $m.CellH }
        $v.Root.Width = $w
        $v.Root.Height = $h
        $sw = Get-BoardSpan $w $m.CellW $m.Gap
        $sh = Get-BoardSpan $h $m.CellH $m.Gap
        $key = ([string]$sw + 'x' + [string]$sh)
        if ($key -ne $d.Key) {
            $d.Key = $key
            $work = Copy-BoardLayout $script:BoardLayout
            [void](Resize-BoardTile $work ([string]$d.Id) $sw $sh)
            $d.Work = $work
            Show-BoardPreview $work ([string]$d.Id)
        }
    }
}

# Onizleme: diger dosemeler yeni yerlerine kayar; golge suruklenenin hedefini gosterir
function Show-BoardPreview($Work, [string]$MovingId) {
    $m = $script:BoardMetrics
    foreach ($t in $Work) {
        $v = $script:BoardViews[[string]$t.Id]
        if ($null -eq $v) { continue }
        if ([string]$t.Id -eq $MovingId) {
            $r = Get-BoardRect $t $m.CellW $m.CellH $m.Gap
            $g = $script:BoardGhost
            $g.Width = [double]$r.W
            $g.Height = [double]$r.H
            [System.Windows.Controls.Canvas]::SetLeft($g, [double]$r.X)
            [System.Windows.Controls.Canvas]::SetTop($g, [double]$r.Y)
            $g.Visibility = $script:VisOn
        } else {
            Set-TilePlace $v $t $true
        }
    }
    $rows = Get-BoardRows $Work
    $ui.bd_Canvas.Height = [math]::Max([double]$ui.bd_Canvas.Height, $rows * ($m.CellH + $m.Gap) + 8.0)
}

function Stop-BoardDrag([bool]$Commit) {
    $d = $script:BoardDrag
    if ($null -eq $d) { return }
    $script:BoardDrag = $null
    $id = [string]$d.Id
    $v = $script:BoardViews[$id]
    try { if ($null -ne $d.Src) { $d.Src.ReleaseMouseCapture() } } catch { }
    if ($null -ne $script:BoardGhost) { $script:BoardGhost.Visibility = $script:VisOff }
    if ($null -ne $v) {
        [System.Windows.Controls.Panel]::SetZIndex($v.Root, 1)
        $v.Root.Opacity = 1.0
    }
    $rebuild = $false
    if ($Commit -and $null -ne $d.Work) {
        $script:BoardLayout = $d.Work
        Invoke-BoardCompact $script:BoardLayout ''
        if ($d.Mode -eq 'size') { $rebuild = $true }
        Save-BoardLayout
    }
    if ($rebuild -and $null -ne $v) {
        # boyut degisince icerik duzeni (dikey / yatay kart, grafik) yeniden kurulur
        $t = Find-BoardTile $script:BoardLayout $id
        if ($null -ne $t) {
            Remove-BoardTileView $id
            $nv = New-BoardTileView $t
            if ($null -ne $nv) {
                [System.Windows.Controls.Panel]::SetZIndex($nv.Root, 1)
                [void]$ui.bd_Canvas.Children.Add($nv.Root)
                $script:BoardViews[$id] = $nv
                if ($script:BoardEdit) { Set-Visible $nv.N.Veil $true; Set-Visible $nv.N.Del $true; Set-Visible $nv.N.Grip $true; Start-TileWiggle $nv 0 }
            }
        }
    }
    Update-BoardGeometry $true
}

# ---------------- arama kutusu ----------------
function Update-BoardSearch($Tb) {
    $text = [string]$Tb.Text
    $ph = $null
    try { $ph = $Tb.Parent.Children | Where-Object { $_.Name -eq 'Ph' } | Select-Object -First 1 } catch { $ph = $null }
    if ($null -ne $ph) { Set-Visible $ph ($text -eq '') }
    if ($text.Trim() -eq '') { $script:BoardSearchTop = ''; Close-NavMenu; return }
    $res = @(Get-BoardSearchResults $text)
    if ($res.Count -eq 0) { $script:BoardSearchTop = ''; Close-NavMenu; return }
    $script:BoardSearchTop = [string]$res[0].Tag
    Show-ItemMenu $Tb $res 'Bottom'
}

function Invoke-BoardSearchKey($Tb, $E) {
    $k = [string]$E.Key
    if ($k -eq 'Escape') { $Tb.Text = (Tr $('')); Close-NavMenu; $E.Handled = $true; return }
    if ($k -ne 'Return') { return }
    $E.Handled = $true
    $tag = $script:BoardSearchTop
    $text = [string]$Tb.Text
    if ($tag -eq '' -and $text.Trim() -ne '') { $tag = 'cmd:' + $text.Trim() }
    if ($tag -eq '') { return }
    $Tb.Text = (Tr $(''))
    Invoke-MenuTag $tag
}

# ---------------- canli veri ----------------
function Add-BoardSample([string]$Key, [double]$V) {
    if (-not $script:BoardHist.ContainsKey($Key)) { $script:BoardHist[$Key] = New-Object System.Collections.ArrayList }
    $l = $script:BoardHist[$Key]
    [void]$l.Add($V)
    while ($l.Count -gt $script:BoardHistLen) { $l.RemoveAt(0) }
}

# Izleme her tur yeni olcum getirir; gecmis her zaman, cizim yalnizca ana ekrandayken guncellenir
function Invoke-BoardTick($M) {
    if ($null -eq $M -or -not $M.ContainsKey('Cpu')) { return }
    Add-BoardSample 'cpu' ([double]$M.Cpu)
    Add-BoardSample 'ram' ([double]$M.Ram)
    Add-BoardSample 'disk' ([double]$M.Disk)
    Add-BoardSample 'net' ([double]$M.NetDown * 8.0 / 1000000.0)
    if ([double]$M.Gpu -ge 0) { Add-BoardSample 'gpu' ([double]$M.Gpu) }
    if ([double]$M.Temp -gt 0) { Add-BoardSample 'temp' ([double]$M.Temp) }
    if ($script:UiState.Page -eq 'board' -and $script:Win.IsVisible -and $script:BoardBuilt) { Update-BoardLive $M }
}

function Set-TileGraph($V, [string]$Key, [double]$Max) {
    $n = $V.N
    if (-not $n.ContainsKey('Ln')) { return }
    $spec = Get-ActiveDesign
    if ([string]$spec.Graph -eq 'none') { return }
    $w = [double]$n.Gr.Width
    $h = [double]$n.Gr.Height
    $vals = @()
    if ($script:BoardHist.ContainsKey($Key)) { $vals = @($script:BoardHist[$Key]) }
    $pts = Get-SparkPoints $vals $w $h $Max $script:BoardHistLen
    if ($pts -eq '') { $n.Ln.Points = New-Object System.Windows.Media.PointCollection; $n.Ar.Points = New-Object System.Windows.Media.PointCollection; return }
    $n.Ln.Points = [System.Windows.Media.PointCollection]::Parse($pts)
    if ([string]$spec.Graph -eq 'area') {
        $first = $pts.Substring(0, $pts.IndexOf(','))
        $last = $pts.Substring($pts.LastIndexOf(' ') + 1)
        $lastX = $last.Substring(0, $last.IndexOf(','))
        $n.Ar.Points = [System.Windows.Media.PointCollection]::Parse(($first + ',' + (Format-BoardNum $h) + ' ' + $pts + ' ' + $lastX + ',' + (Format-BoardNum $h)))
    }
    if ([string]$spec.Graph -eq 'scope' -and $V.Dirty) {
        $gd = ''
        foreach ($f in @(0.25, 0.5, 0.75)) { $y = Format-BoardNum ($h * $f); $gd += ('M0,' + $y + ' L' + (Format-BoardNum $w) + ',' + $y + ' ') }
        $n.Gd.Data = [System.Windows.Media.Geometry]::Parse($gd.Trim())
    }
}

function Update-MetricTile($V, $M) {
    $n = $V.N
    $t = [string]$V.Type
    $val = '--'
    $sub = ''
    $max = 100.0
    $key = $t
    if ($t -eq 'cpu') {
        $val = (Format-Percent ([int][double]$M.Cpu))
        $sub = [string]$script:CpuShort
    } elseif ($t -eq 'ram') {
        $val = (Format-Percent ([int][double]$M.Ram))
        $sub = ([string]$M.RamUsedGB + ' / ' + [string]$M.RamTotalGB + ' GB')
    } elseif ($t -eq 'disk') {
        $p = $sync.Profile
        if ($null -ne $p -and [double]$p.SizeGB -gt 0) {
            $used = 100.0 * ([double]$p.SizeGB - [double]$p.FreeGB) / [double]$p.SizeGB
            $val = (Format-Percent ([int]$used))
            $sub = ([string]$p.SysDrive + ': ' + [string]$p.FreeGB + (' GB bo' + [char]0x015F + ' ' + [char]0x00B7 + ' etkinlik %') + [string][int][double]$M.Disk)
        }
    } elseif ($t -eq 'net') {
        $val = Format-Mbps ([double]$M.NetDown)
        $sub = (('y' + [char]0x00FC + 'kleme ') + (Format-Mbps ([double]$M.NetUp)))
        $script:BoardNetPeak = [math]::Max(10.0, [math]::Max($script:BoardNetPeak * 0.97, [double]$M.NetDown * 8.0 / 1000000.0))
        $max = $script:BoardNetPeak
    } elseif ($t -eq 'gpu') {
        if ([double]$M.Gpu -ge 0) { $val = (Format-Percent ([int][double]$M.Gpu)); $sub = ('ekran kart' + [char]0x0131 + ' (3B)') } else { $val = '--'; $sub = (Get-GpuOffText) }
    } elseif ($t -eq 'temp') {
        if ([double]$M.Temp -gt 0) { $val = ([string][int][double]$M.Temp + (' ' + [char]0x00B0 + 'C')); $sub = (Get-TempSubText $M ('i' + [char]0x015F + 'lemci / sistem')); $max = 110.0 } else { $val = '--'; $sub = (Get-TempOffText) }
    }
    $n.Val.Text = (Tr $($val))
    $n.Sub.Text = (Tr $($sub))
    Set-TileGraph $V $key $max
}

function Update-HealthTile($V) {
    $n = $V.N
    $h = $script:Health
    if ($null -eq $h) {
        $n.Val.Text = (Tr $('--'))
        $n.Sub.Text = (Tr $(('Hen' + [char]0x00FC + 'z taranmad' + [char]0x0131 + '')))
        Set-Ring $n.Rg 0 37.7
        return
    }
    $all = [double]$h.Score.All
    $key = 'BrGood'
    if ($all -lt 60) { $key = 'BrBad' } elseif ($all -lt 80) { $key = 'BrWarn' }
    $n.Rg.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, $key)
    Set-Ring $n.Rg $all 37.7
    $n.Val.Text = (Tr $([string][int]$all))
    $issues = @($h.Findings | Where-Object { $_.Status -ne 'ok' }).Count
    $age = ''
    try { $age = Get-AgeText $script:HealthAt } catch { $age = '' }
    if ($issues -eq 0) { $n.Sub.Text = (Tr $((('Her ' + [char]0x015F + 'ey yolunda ' + [char]0x00B7 + ' ') + $age))) } else { $n.Sub.Text = (Tr $(([string]$issues + (' ' + [char]0x00F6 + 'neri ' + [char]0x00B7 + ' ') + $age))) }
}

# Saglik taramasi bitince (Update-HealthUi) cagrilir
function Update-BoardHealth {
    if (-not $script:BoardBuilt) { return }
    foreach ($t in @($script:BoardLayout)) {
        if ([string]$t.Type -ne 'health') { continue }
        $v = $script:BoardViews[[string]$t.Id]
        if ($null -ne $v) { Update-HealthTile $v }
    }
}

function Update-TopTile($V, $M) {
    $lst = $V.N.Lst
    $lst.Children.Clear()
    $rows = [math]::Max(1, [int][math]::Floor(([double]$V.Root.Height - 44.0) / 20.0))
    $i = 0
    if ($null -ne $M -and $M.ContainsKey('Top')) {
        foreach ($t in @($M.Top)) {
            if ($i -ge $rows) { break }
            $i++
            $g = New-Object System.Windows.Controls.Grid
            $a = New-Object System.Windows.Controls.TextBlock
            $a.Text = (Tr $([string]$t.Name))
            $a.FontSize = 12
            $a.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
            $a.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 0, 52, 0
            $a.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'BrText')
            $b = New-Object System.Windows.Controls.TextBlock
            $b.Text = (Tr $((Format-Percent ([double]$t.Cpu))))
            $b.FontSize = 12
            $b.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
            $b.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'BrDim')
            [void]$g.Children.Add($a)
            [void]$g.Children.Add($b)
            $g.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 2, 0, 2
            [void]$lst.Children.Add($g)
        }
    }
    if ($i -eq 0) { Add-BoardLine $lst ('' + [char]0x00D6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm bekleniyor' + [char]0x2026 + '') 'BrFaint' }
}

function Add-BoardLine($Panel, [string]$Text, [string]$Key, [bool]$Mono = $false) {
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.Text = (Tr $($Text))
    $tb.FontSize = 11.5
    $tb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
    $tb.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 1, 0, 1
    if ($Mono) { $tb.SetResourceReference([System.Windows.Controls.TextBlock]::FontFamilyProperty, 'FontMono') }
    $tb.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $Key)
    [void]$Panel.Children.Add($tb)
}

function Update-SysInfoTile($V, $M) {
    $lst = $V.N.Lst
    $lst.Children.Clear()
    $p = $sync.Profile
    if ($null -eq $p) { Add-BoardLine $lst ('Bilgi okunuyor' + [char]0x2026 + '') 'BrFaint'; return }
    Add-BoardLine $lst ([string]$p.OsName + ' ' + [string]$p.Version) 'BrText'
    Add-BoardLine $lst (Get-CpuShortName ([string]$p.CpuName)) 'BrDim'
    Add-BoardLine $lst ([string]$p.RamGB + (' GB bellek ' + [char]0x00B7 + ' ') + [string]$p.Cores + (' ' + [char]0x00E7 + 'ekirdek')) 'BrDim'
    if ($null -ne $M -and $M.ContainsKey('Boot') -and $null -ne $M.Boot) {
        try { Add-BoardLine $lst (('A' + [char]0x00E7 + '' + [char]0x0131 + 'k kalma: ') + (Format-Duration (((Get-Date) - [datetime]$M.Boot).TotalSeconds))) 'BrDim' } catch { }
    }
}

# Gunluge dusen her satir pano icin de tutulur (Add-LogLine cagirir)
function Push-BoardLog([string]$Line, [string]$Key) {
    [void]$script:BoardLogs.Add(@{ Text = $Line; Key = $Key })
    while ($script:BoardLogs.Count -gt 40) { $script:BoardLogs.RemoveAt(0) }
}

function Update-LogTile($V) {
    $lst = $V.N.Lst
    $rows = [math]::Max(1, [int][math]::Floor(([double]$V.Root.Height - 44.0) / 17.0))
    $total = $script:BoardLogs.Count
    $sig = ([string]$total + '|' + [string]$rows + '|' + [string]$V.Root.Height)
    if ($V.Sig -eq $sig -and -not $V.Dirty) { return }
    $V.Sig = $sig
    $lst.Children.Clear()
    $from = [math]::Max(0, $total - $rows)
    for ($i = $from; $i -lt $total; $i++) {
        $it = $script:BoardLogs[$i]
        Add-BoardLine $lst ([string]$it.Text) ([string]$it.Key) $true
    }
    if ($total -eq 0) { Add-BoardLine $lst ('Hen' + [char]0x00FC + 'z i' + [char]0x015F + 'lem g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yok.') 'BrFaint' $true }
}

function Update-RadarTile($V) {
    $n = $V.N
    $snap = $script:LanSnap
    $devs = @()
    if ($null -ne $snap) { $devs = @($snap.Devices) }
    $w = [double]$V.Root.Width - 2.0
    $h = [double]$V.Root.Height - 2.0
    $sig = ([string]$devs.Count + '|' + [string][int]$w + 'x' + [string][int]$h + '|' + [string]$script:DesignKey)
    if ($script:BoardRadarSig -eq $sig -and -not $V.Dirty) { return }
    $script:BoardRadarSig = $sig
    $cv = $n.Cv
    $cv.Children.Clear()
    $cx = $w / 2.0
    $cy = $h / 2.0 + 6.0
    $rad = [math]::Min($w / 2.0 - 8.0, ($h - 40.0) / 2.0)
    if ($rad -lt 20) { return }
    foreach ($f in @(0.42, 0.7, 0.92)) {
        $e = New-Object System.Windows.Shapes.Ellipse
        $e.Width = 2.0 * $rad * $f
        $e.Height = 2.0 * $rad * $f
        $e.StrokeThickness = 1.0
        $e.StrokeDashArray = [System.Windows.Media.DoubleCollection]::Parse('2,3')
        $e.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, 'BrLine2')
        [System.Windows.Controls.Canvas]::SetLeft($e, $cx - $rad * $f)
        [System.Windows.Controls.Canvas]::SetTop($e, $cy - $rad * $f)
        [void]$cv.Children.Add($e)
    }
    foreach ($ln in @(@(($cx - $rad), $cy, ($cx + $rad), $cy), @($cx, ($cy - $rad), $cx, ($cy + $rad)))) {
        $l = New-Object System.Windows.Shapes.Line
        $l.X1 = $ln[0]; $l.Y1 = $ln[1]; $l.X2 = $ln[2]; $l.Y2 = $ln[3]
        $l.StrokeThickness = 1.0
        $l.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, 'BrLine')
        [void]$cv.Children.Add($l)
    }
    # tarama cizgisi (hareket azaltilmissa duragan)
    $sw = New-Object System.Windows.Shapes.Line
    $sw.X1 = $cx; $sw.Y1 = $cy; $sw.X2 = $cx; $sw.Y2 = $cy - $rad
    $sw.StrokeThickness = 1.6
    $sw.Opacity = 0.7
    $sw.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, 'BrAccent')
    $rot = New-Object System.Windows.Media.RotateTransform
    $rot.CenterX = $cx; $rot.CenterY = $cy
    $sw.RenderTransform = $rot
    [void]$cv.Children.Add($sw)
    if (-not $script:ReduceMotion) {
        $a = New-Object System.Windows.Media.Animation.DoubleAnimation
        $a.From = 0.0; $a.To = 360.0
        $a.Duration = New-Object System.Windows.Duration -ArgumentList ([TimeSpan]::FromSeconds(5))
        $a.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $rot.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $a)
    }
    # merkez: yonlendirici; cevre: cihazlar
    $gw = $null
    $others = New-Object System.Collections.ArrayList
    foreach ($d in $devs) { if ($d.IsGateway -eq $true -and $null -eq $gw) { $gw = $d } else { [void]$others.Add($d) } }
    $slots = @(Get-RadarSlots $others.Count $cx $cy $rad)
    for ($i = 0; $i -lt $others.Count; $i++) {
        $d = $others[$i]
        $key = 'BrWarn'
        if ($d.IsSelf -eq $true) { $key = 'BrAccent' } elseif ($d.Blocked -eq $true) { $key = 'BrBad' } elseif ($d.Known -eq $true) { $key = 'BrGood' }
        $dot = New-Object System.Windows.Shapes.Ellipse
        $dot.Width = 9; $dot.Height = 9
        if ($d.IsSelf -eq $true) { $dot.Width = 12; $dot.Height = 12 }
        $dot.SetResourceReference([System.Windows.Shapes.Shape]::FillProperty, $key)
        $tip = ''
        try { $tip = (Get-DeviceTitle $d) + (' ' + [char]0x00B7 + ' ') + [string]$d.Ip } catch { $tip = [string]$d.Ip }
        $dot.ToolTip = (Tr $($tip))
        [System.Windows.Controls.Canvas]::SetLeft($dot, [double]$slots[$i].X - $dot.Width / 2.0)
        [System.Windows.Controls.Canvas]::SetTop($dot, [double]$slots[$i].Y - $dot.Height / 2.0)
        [void]$cv.Children.Add($dot)
    }
    $c0 = New-Object System.Windows.Shapes.Ellipse
    $c0.Width = 14; $c0.Height = 14
    $c0.SetResourceReference([System.Windows.Shapes.Shape]::FillProperty, 'BrBlue')
    [System.Windows.Controls.Canvas]::SetLeft($c0, $cx - 7.0)
    [System.Windows.Controls.Canvas]::SetTop($c0, $cy - 7.0)
    [void]$cv.Children.Add($c0)
    if ($devs.Count -eq 0) { $n.Sub.Text = (Tr $(('A' + [char]0x011F + ' hen' + [char]0x00FC + 'z taranmad' + [char]0x0131 + ' (A' + [char]0x011F + ' ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ' > A' + [char]0x011F + '' + [char]0x0131 + ' tara)'))) }
    else {
        $age = ''
        try { $age = Get-AgeText $script:LanAt } catch { $age = '' }
        $n.Sub.Text = (Tr $(([string]$devs.Count + (' cihaz ' + [char]0x00B7 + ' ') + $age)))
    }
}

function Update-HexTile($V) {
    $n = $V.N
    $p = $sync.Profile
    $w = [double]$V.Root.Width - 2.0
    $h = [double]$V.Root.Height - 2.0
    $used = -1.0
    $free = 0.0
    $drv = 'C'
    if ($null -ne $p -and [double]$p.SizeGB -gt 0) {
        $used = 100.0 * ([double]$p.SizeGB - [double]$p.FreeGB) / [double]$p.SizeGB
        $free = [double]$p.FreeGB
        $drv = [string]$p.SysDrive
    }
    $sig = ([string][int]$used + '|' + [string][int]$w + 'x' + [string][int]$h)
    if ($script:BoardHexSig -eq $sig -and -not $V.Dirty) { return }
    $script:BoardHexSig = $sig
    $r = 11.0
    if ($w -lt 330) { $r = 9.0 }
    $top = 34.0
    $cells = @(Get-HexCells $w ($h - $top - 24.0) $r)
    foreach ($c in $cells) { $c.Y = [double]$c.Y + $top }
    $on = [int][math]::Round(([math]::Max(0.0, $used) / 100.0) * $cells.Count)
    $keyOn = 'BrAccent'
    if ($used -ge 90) { $keyOn = 'BrBad' } elseif ($used -ge 75) { $keyOn = 'BrWarn' }
    $n.HOn.SetResourceReference([System.Windows.Shapes.Shape]::FillProperty, $keyOn)
    $onCells = @(); $offCells = @()
    if ($cells.Count -gt 0) {
        if ($on -gt 0) { $onCells = @($cells[0..($on - 1)]) }
        if ($on -lt $cells.Count) { $offCells = @($cells[$on..($cells.Count - 1)]) }
    }
    $n.HOn.Data = $null
    $n.HOff.Data = $null
    if ($onCells.Count -gt 0) { $n.HOn.Data = [System.Windows.Media.Geometry]::Parse((Get-HexPath $onCells $r)) }
    if ($offCells.Count -gt 0) { $n.HOff.Data = [System.Windows.Media.Geometry]::Parse((Get-HexPath $offCells $r)) }
    if ($used -ge 0) { $n.Sub.Text = (Tr $(($drv + ': %' + [string][int]$used + (' dolu ' + [char]0x00B7 + ' ') + [string]$free + (' GB bo' + [char]0x015F + '')))) } else { $n.Sub.Text = (Tr $(('Disk bilgisi okunuyor' + [char]0x2026 + ''))) }
}

# Tum dosemeleri gunceller; M $null ise son olcum kullanilir
function Update-BoardLive($M) {
    if (-not $script:BoardBuilt -or $null -eq $script:BoardLayout) { return }
    if ($null -eq $M) { $M = $sync.Mon }
    if ($null -eq $M -or -not $M.ContainsKey('Cpu')) { $M = @{ Cpu = 0.0; Ram = 0.0; Disk = 0.0; NetDown = 0.0; NetUp = 0.0; Gpu = -1.0; Temp = -1.0; RamUsedGB = 0.0; RamTotalGB = 0.0; Top = @() } }
    if ($script:CpuShort -eq '' -and $null -ne $sync.Profile) { $script:CpuShort = Get-CpuShortName ([string]$sync.Profile.CpuName) }
    foreach ($t in $script:BoardLayout) {
        $v = $script:BoardViews[[string]$t.Id]
        if ($null -eq $v) { continue }
        $k = [string]$v.Kind
        if ($k -eq 'metric') { Update-MetricTile $v $M }
        elseif ($k -eq 'health') { Update-HealthTile $v }
        elseif ($k -eq 'radar') { Update-RadarTile $v }
        elseif ($k -eq 'hex') { Update-HexTile $v }
        elseif ($k -eq 'list') {
            $ty = [string]$v.Type
            if ($ty -eq 'top') { Update-TopTile $v $M } elseif ($ty -eq 'sysinfo') { Update-SysInfoTile $v $M } elseif ($ty -eq 'log') { Update-LogTile $v }
        }
        $v.Dirty = $false
    }
}


# ---------------- Saydamlik ----------------
# ==================================================================
#  SAYDAMLIK: pencere arka plan efekti (Mica, Akrilik) ve yuzey saydamligi
#  Iki ayri ayar vardir: Backdrop (efekt) ve WinOpacity (yuzeylerin opakligi, %100 ... %50).
#  Efekt Windows'un kendi pencere yoneticisi (DWM) tarafindan cizilir; uygulama yalnizca yuzeyleri yari saydam boyar.
#  Efektsiz duz seffaflik sunulmaz: Windows 11 de normal pencerede pencere bilesimi bunu cizmez, katmanli pencere ise
#  calisirken acilip kapanamaz. Mica ve Akrilik her iki durumda da calisir ve aninda degisir.
#  Saf kisim (plan, renk hesabi) ekrana dokunmaz ve her yerde test edilir. Windows kismi uc sistem cagrisini tek bir kucuk
#  Add-Type tanimiyla yukler. Herhangi bir adim basarisiz olursa efekt kapatilir, pencere duz renkle cizilir.
#  Guvenli baslangicta, guvenli cizim kipinde, yuksek karsitlikta ve uzak masaustunde saydamlik hic acilmaz.
# ==================================================================
$script:GlassInfo = [ordered]@{
    Yok     = @{ T = ('Kapal' + [char]0x0131 + '');  D = ('Pencere d' + [char]0x00FC + 'z renkli ' + [char]0x00E7 + 'izilir. Varsay' + [char]0x0131 + 'lan.') }
    Mica    = @{ T = 'Mica';    D = ('Windows 11 malzemesi: duvar k' + [char]0x00E2 + '' + [char]0x011F + '' + [char]0x0131 + 'd' + [char]0x0131 + 'n' + [char]0x0131 + 'n sakin, hafif bir yans' + [char]0x0131 + 'mas' + [char]0x0131 + '. Windows 10 da Akrilik kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') }
    Akrilik = @{ T = 'Akrilik'; D = ('Pencerenin arkas' + [char]0x0131 + 'ndaki pencereler ve masa' + [char]0x00FC + 'st' + [char]0x00FC + ' bulan' + [char]0x0131 + 'k g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.') }
}
$script:GlassSteps = @(100, 90, 80, 70, 60, 50)
# Efekt ilk kez acilirken onerilen yuzey opakligi (%100'de efekt gorunmez)
$script:GlassDefaultOp = @{ Mica = 80; Akrilik = 70 }
# Yari saydam boyanan fircalar: kabuk (pencere zemini, baslik, menu) ve yuzeyler (kartlar). Acilir menu ve bildirimler opak kalir.
$script:GlassShellKeys = @('BrBg', 'BrTitle', 'BrRail')
$script:GlassSurfaceKeys = @('BrPanel', 'BrCard')

$script:GlassAlpha = 1.0
$script:GlassPlan = @{ Req = 'Yok'; Mode = 'Yok'; Api = ''; Note = '' }
$script:GlassApplied = $null
$script:GlassApi = $null
$script:GlassFail = 0
$script:GlassState = @{ Ok = $true; Detail = '' }
$script:GlassPrevBg = $null
$script:GlassWired = $false

# ---------------- saf yardimcilar (ekrana dokunmaz; testlerde de kullanilir) ----------------
function ConvertTo-GlassKey([string]$Name) {
    foreach ($k in @($script:GlassInfo.Keys)) { if ([string]$k -eq $Name) { return [string]$k } }
    return 'Yok'
}

# En yakin opaklik adimi (kayit bozuk ya da bossa %100)
function ConvertTo-GlassOpacity($Value) {
    if ($null -eq $Value -or [string]$Value -eq '') { return 100 }
    $v = 100
    try { $v = [int]$Value } catch { return 100 }
    if ($v -le 0) { return 100 }
    $best = 100
    $bd = 1000
    foreach ($s in $script:GlassSteps) {
        $d = [math]::Abs([int]$s - $v)
        if ($d -lt $bd) { $bd = $d; $best = [int]$s }
    }
    return $best
}

# Istenen efekt bu sistemde nasil uygulanir? Build: Windows derleme numarasi; BlockWhy doluysa saydamlik kapali kalir.
# Api: Backdrop (Windows 11 22621+: DWM sistem arka plani) | MicaOld (Windows 11 ilk surum) | Accent (Windows 10: pencere bilesimi)
function Get-GlassPlan([string]$Backdrop, [int]$Build, [string]$BlockWhy) {
    $req = ConvertTo-GlassKey $Backdrop
    $p = @{ Req = $req; Mode = 'Yok'; Api = ''; Note = '' }
    if ($req -eq 'Yok') { return $p }
    if ($BlockWhy -ne '') { $p.Note = $BlockWhy; return $p }
    if ($Build -lt 17134) { $p.Note = ('Saydaml' + [char]0x0131 + 'k i' + [char]0x00E7 + 'in Windows 10 s' + [char]0x00FC + 'r' + [char]0x00FC + 'm 1803 ya da ' + [char]0x00FC + 'st' + [char]0x00FC + ' gerekir.'); return $p }
    if ($req -eq 'Mica') {
        if ($Build -ge 22621) { $p.Mode = 'Mica'; $p.Api = 'Backdrop' }
        elseif ($Build -ge 22000) { $p.Mode = 'Mica'; $p.Api = 'MicaOld' }
        else { $p.Mode = 'Akrilik'; $p.Api = 'Accent'; $p.Note = ('Mica yaln' + [char]0x0131 + 'zca Windows 11 de vard' + [char]0x0131 + 'r; Akrilik uyguland' + [char]0x0131 + '.') }
        return $p
    }
    $p.Mode = 'Akrilik'
    if ($Build -ge 22621) { $p.Api = 'Backdrop' } else { $p.Api = 'Accent' }
    return $p
}

# Firca anahtarina gore alfa: kabuk katmanlari Alpha, kartlar daha opak (yari yolda), digerleri opak
function Get-GlassAlphaFor([string]$Key, [double]$Alpha) {
    if ($Alpha -ge 0.999) { return 1.0 }
    if ($script:GlassShellKeys -contains $Key) { return $Alpha }
    if ($script:GlassSurfaceKeys -contains $Key) { return ($Alpha + (1.0 - $Alpha) * 0.5) }
    return 1.0
}

# Tema renginin (orn. #0E1427) o anki saydamliga gore #AARRGGBB karsiligi; saydamlik yoksa renk aynen doner.
# Set-AppTheme ve Get-ThemeProblems ayni islevi kullanir; tema dogrulamasi bu yuzden saydam renklerle de tutarlidir.
function Get-GlassHex([string]$Key, [string]$Hex) {
    $a = Get-GlassAlphaFor $Key ([double]$script:GlassAlpha)
    if ($a -ge 0.999) { return $Hex }
    $h = $Hex.TrimStart('#')
    $base = 1.0
    $rgb = $h
    if ($h.Length -eq 8) { $base = [Convert]::ToInt32($h.Substring(0, 2), 16) / 255.0; $rgb = $h.Substring(2) }
    if ($rgb.Length -ne 6) { return $Hex }
    $v = [int][math]::Round(255.0 * $base * $a)
    if ($v -gt 255) { $v = 255 }
    if ($v -lt 0) { $v = 0 }
    return ('#' + $v.ToString('X2') + $rgb.ToUpperInvariant())
}

# Hazir gorunumun saydamligi: Atolye ve Sifir Noktasi Mica ile gelir; digerleri duz renkli kalir
function Get-PresetGlass([string]$Key) {
    if ($Key -eq 'Atolye') { return @{ Backdrop = 'Mica'; Opacity = 80 } }
    if ($Key -eq 'Sifir') { return @{ Backdrop = 'Mica'; Opacity = 90 } }
    return @{ Backdrop = 'Yok'; Opacity = 100 }
}

# Koyu renk mi? (Windows'a koyu ya da acik malzeme istenecegi buradan cikar)
function Test-HexDark([string]$Hex) {
    $h = $Hex.TrimStart('#')
    if ($h.Length -eq 8) { $h = $h.Substring(2) }
    if ($h.Length -ne 6) { return $true }
    $r = [Convert]::ToInt32($h.Substring(0, 2), 16)
    $g = [Convert]::ToInt32($h.Substring(2, 2), 16)
    $b = [Convert]::ToInt32($h.Substring(4, 2), 16)
    return (((0.2126 * $r + 0.7152 * $g + 0.0722 * $b) / 255.0) -lt 0.5)
}

# Pencere bilesimi icin ABGR renk (alfa en yuksek bayt)
function Get-AccentColor([string]$Hex, [int]$Alpha) {
    $h = $Hex.TrimStart('#')
    if ($h.Length -eq 8) { $h = $h.Substring(2) }
    if ($h.Length -ne 6) { $h = '000000' }
    $r = [Convert]::ToInt64($h.Substring(0, 2), 16)
    $g = [Convert]::ToInt64($h.Substring(2, 2), 16)
    $b = [Convert]::ToInt64($h.Substring(4, 2), 16)
    $a = [int64][math]::Max(0, [math]::Min(255, $Alpha))
    return [uint32](($a * 16777216) + ($b * 65536) + ($g * 256) + $r)
}

# Temanin koyu mu acik mi oldugu (pencere zemin renginden)
function Get-GlassThemeDark([string]$ThemeName) {
    if ($script:Themes.Contains($ThemeName)) { return (Test-HexDark ([string]$script:Themes[$ThemeName].BrBg)) }
    return $true
}

# Saydamligin kapali kalacagi durumlar (bos dize: engel yok). ThemeKey: uygulanacak ya da uygulanmis tema.
function Get-GlassBlockWhy([string]$ThemeKey) {
    if ($script:SafeBoot -eq $true) { return ('G' + [char]0x00FC + 'venli ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + 'ta saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') }
    if ($script:SafeMode -eq $true) { return ('G' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim kipinde saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') }
    if ($script:ChromeFallback -eq $true) { return ('Sistem ' + [char]0x00E7 + 'er' + [char]0x00E7 + 'evesi kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'rken saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') }
    try { if ([System.Windows.SystemParameters]::HighContrast) { return ('Windows y' + [char]0x00FC + 'ksek kar' + [char]0x015F + '' + [char]0x0131 + 'tl' + [char]0x0131 + 'k kipinde saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') } } catch { }
    if ($ThemeKey -eq 'Yuksek') { return ('Y' + [char]0x00FC + 'ksek kar' + [char]0x015F + '' + [char]0x0131 + 'tl' + [char]0x0131 + 'k temas' + [char]0x0131 + 'nda saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') }
    if ([string]$env:SESSIONNAME -like 'RDP-*') { return ('Uzak masa' + [char]0x00FC + 'st' + [char]0x00FC + ' oturumunda saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.') }
    return ''
}

# ---------------- plan ve fircalar ----------------
# Ayarlardan plani ve yuzey alfasini hesaplar; pencereye dokunmaz (acilista tema uygulanmadan once cagrilir)
function Initialize-GlassState([string]$ThemeKey) {
    $req = ConvertTo-GlassKey ([string]$script:Settings.Backdrop)
    $op = ConvertTo-GlassOpacity $script:Settings.WinOpacity
    $why = ''
    try { $why = Get-GlassBlockWhy $ThemeKey } catch { $why = '' }
    $plan = Get-GlassPlan $req (Get-OsBuildNumber) $why
    $script:GlassPlan = $plan
    if ([string]$plan.Mode -eq 'Yok') { $script:GlassAlpha = 1.0 } else { $script:GlassAlpha = [double]$op / 100.0 }
}

# Saydamligi ayarda ve bellekte kapatir (tema ya da pencere uygulanamazsa varsayilan gorunume donmek icin)
function Disable-GlassState {
    $script:GlassAlpha = 1.0
    $script:GlassPlan = @{ Req = 'Yok'; Mode = 'Yok'; Api = ''; Note = '' }
    try { Set-SettingsKeys @{ Backdrop = 'Yok'; WinOpacity = 100 } } catch { }
}

# ---------------- Windows: sistem cagrilari ----------------
function Get-GlassApi {
    if ($null -ne $script:GlassApi) { return $script:GlassApi }
    try {
        # Uygulamanin baska yerlerindeki kucuk sistem cagrisi tanimlariyla ayni yontem; yalnizca saydamlik ilk kez gerektiginde derlenir
        if ($null -eq ('WH.GlassWin' -as [type])) {
            Add-Type -Namespace WH -Name GlassWin -ErrorAction Stop -MemberDefinition '[DllImport("dwmapi.dll")] public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, IntPtr value, int size); [DllImport("dwmapi.dll")] public static extern int DwmExtendFrameIntoClientArea(IntPtr hwnd, IntPtr margins); [DllImport("user32.dll")] public static extern int SetWindowCompositionAttribute(IntPtr hwnd, IntPtr data);'
        }
        $script:GlassApi = ('WH.GlassWin' -as [type])
    } catch {
        $script:GlassApi = $null
        Write-WhLog (('Saydaml' + [char]0x0131 + 'k sistem ' + [char]0x00E7 + 'a' + [char]0x011F + 'r' + [char]0x0131 + 'lar' + [char]0x0131 + ' tan' + [char]0x0131 + 'mlanamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN'
    }
    return $script:GlassApi
}

function Invoke-GlassNative([string]$Name, [object[]]$CallArgs) {
    $api = Get-GlassApi
    if ($null -eq $api) { return -1 }
    $mi = $api.GetMethod($Name)
    if ($null -eq $mi) { return -1 }
    return [int]$mi.Invoke($null, $CallArgs)
}

function Set-DwmInt([IntPtr]$Hwnd, [int]$Attr, [int]$Value) {
    $p = [System.Runtime.InteropServices.Marshal]::AllocHGlobal(4)
    try {
        [System.Runtime.InteropServices.Marshal]::WriteInt32($p, $Value)
        return (Invoke-GlassNative 'DwmSetWindowAttribute' @($Hwnd, $Attr, $p, 4))
    } finally { [System.Runtime.InteropServices.Marshal]::FreeHGlobal($p) }
}

function Set-DwmMargins([IntPtr]$Hwnd, [int]$M) {
    $p = [System.Runtime.InteropServices.Marshal]::AllocHGlobal(16)
    try {
        for ($i = 0; $i -lt 4; $i++) { [System.Runtime.InteropServices.Marshal]::WriteInt32($p, 4 * $i, $M) }
        return (Invoke-GlassNative 'DwmExtendFrameIntoClientArea' @($Hwnd, $p))
    } finally { [System.Runtime.InteropServices.Marshal]::FreeHGlobal($p) }
}

# Pencere bilesimi vurgusu (ACCENT_POLICY): State 0 kapali, 2 seffaf, 4 akrilik. Donus: 0 = basarisiz, diger = basarili
function Set-WindowAccent([IntPtr]$Hwnd, [int]$State, [int]$Flags, [uint32]$Color) {
    $ps = [IntPtr]::Size
    $acc = [System.Runtime.InteropServices.Marshal]::AllocHGlobal(16)
    $size = 3 * $ps + 4
    if ($ps -eq 8) { $size = 24 }
    $data = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($size)
    try {
        for ($i = 0; $i -lt $size; $i += 4) { [System.Runtime.InteropServices.Marshal]::WriteInt32($data, $i, 0) }
        [System.Runtime.InteropServices.Marshal]::WriteInt32($acc, 0, $State)
        [System.Runtime.InteropServices.Marshal]::WriteInt32($acc, 4, $Flags)
        [System.Runtime.InteropServices.Marshal]::WriteInt32($acc, 8, [BitConverter]::ToInt32([BitConverter]::GetBytes($Color), 0))
        [System.Runtime.InteropServices.Marshal]::WriteInt32($acc, 12, 0)
        [System.Runtime.InteropServices.Marshal]::WriteInt32($data, 0, 19)
        [System.Runtime.InteropServices.Marshal]::WriteIntPtr($data, $ps, $acc)
        [System.Runtime.InteropServices.Marshal]::WriteInt32($data, 2 * $ps, 16)
        return (Invoke-GlassNative 'SetWindowCompositionAttribute' @($Hwnd, $data))
    } finally {
        [System.Runtime.InteropServices.Marshal]::FreeHGlobal($data)
        [System.Runtime.InteropServices.Marshal]::FreeHGlobal($acc)
    }
}

function Get-GlassHwnd {
    $h = [IntPtr]::Zero
    try { $h = (New-Object System.Windows.Interop.WindowInteropHelper -ArgumentList $script:Win).Handle } catch { $h = [IntPtr]::Zero }
    return $h
}

# Ozel pencere cercevesi: cam cerceve tum istemci alanina yayilir ( -1 ) ya da kapatilir ( 0 )
function Set-GlassChrome([bool]$On) {
    $wc = $null
    try { $wc = [System.Windows.Shell.WindowChrome]::GetWindowChrome($script:Win) } catch { $wc = $null }
    if ($null -eq $wc) { return }
    $t = 0.0
    if ($On) { $t = -1.0 }
    $wc.GlassFrameThickness = New-Object System.Windows.Thickness -ArgumentList $t
}

function Set-GlassSurface([bool]$On) {
    $hwnd = Get-GlassHwnd
    $src = $null
    try { if ($hwnd -ne [IntPtr]::Zero) { $src = [System.Windows.Interop.HwndSource]::FromHwnd($hwnd) } } catch { $src = $null }
    if ($On) {
        if ($null -ne $src -and $null -ne $src.CompositionTarget) {
            if ($null -eq $script:GlassPrevBg) { $script:GlassPrevBg = $src.CompositionTarget.BackgroundColor }
            $src.CompositionTarget.BackgroundColor = [System.Windows.Media.Colors]::Transparent
        }
        $script:Win.Background = [System.Windows.Media.Brushes]::Transparent
    } else {
        if ($null -ne $src -and $null -ne $src.CompositionTarget -and $null -ne $script:GlassPrevBg) { $src.CompositionTarget.BackgroundColor = [System.Windows.Media.Color]$script:GlassPrevBg }
        $script:Win.SetResourceReference([System.Windows.Window]::BackgroundProperty, 'BrBg')
    }
}

# Onceki efekti kaldirir (planin Api degerine gore); cerceve ve zemin eski haline doner
function Clear-GlassWindow([IntPtr]$Hwnd) {
    $ap = $script:GlassApplied
    if ($null -eq $ap) { return }
    $api = [string]$ap.Api
    # her adim ayri korunur: biri basarisiz olsa da kalanlar yapilir (pencere yari saydam kalmasin)
    try { if ($api -eq 'Accent') { [void](Set-WindowAccent $Hwnd 0 0 ([uint32]0)) } } catch { }
    try { if ($api -eq 'Backdrop') { [void](Set-DwmInt $Hwnd 38 1) } } catch { }
    try { if ($api -eq 'MicaOld') { [void](Set-DwmInt $Hwnd 1029 0) } } catch { }
    try { [void](Set-DwmMargins $Hwnd 0) } catch { }
    try { Set-GlassChrome $false } catch { }
    try { Set-GlassSurface $false } catch { }
    $script:GlassApplied = $null
}

# Plani pencereye uygular. Pencere taniticisi yoksa (henuz gosterilmediyse) hicbir sey yapmaz; SourceInitialized'da yeniden cagrilir.
function Update-GlassWindow {
    $hwnd = Get-GlassHwnd
    if ($hwnd -eq [IntPtr]::Zero) { return }
    $plan = $script:GlassPlan
    $mode = [string]$plan.Mode
    $api = [string]$plan.Api
    $themeName = [string]$script:ThemeName
    $dark = Get-GlassThemeDark $themeName
    # yalnizca bir sey degistiyse yeniden uygula (tema degisince koyu/acik malzeme ve renk de degisir)
    $sig = ($mode + '|' + $api + '|' + [string]$dark + '|' + $themeName)
    if ($null -ne $script:GlassApplied -and [string]$script:GlassApplied.Sig -eq $sig) { return }
    if ($null -ne $script:GlassApplied) { try { Clear-GlassWindow $hwnd } catch { } }
    if ($mode -eq 'Yok') {
        $script:GlassState = @{ Ok = $true; Detail = ('kapal' + [char]0x0131 + '') }
        return
    }
    $ok = $true
    $detail = ''
    try {
        $darkV = 0
        if ($dark) { $darkV = 1 }
        $mid = ''
        try { $mid = [string]@($script:ThemeGrads[$themeName])[1] } catch { $mid = '' }
        if ($mid -eq '') { $mid = [string]$script:Themes[$themeName].BrBg }
        # zemin saydam olur, cerceve cam olarak istemci alanina yayilir; sonra efekt secilir
        Set-GlassSurface $true
        Set-GlassChrome $true
        [void](Set-DwmInt $hwnd 20 $darkV)
        if ($api -eq 'Backdrop') {
            $type = 1
            if ($mode -eq 'Mica') { $type = 2 } elseif ($mode -eq 'Akrilik') { $type = 3 }
            $hr = Set-DwmInt $hwnd 38 $type
            if ($hr -ne 0) { $ok = $false; $detail = (('DWM arka plan t' + [char]0x00FC + 'r' + [char]0x00FC + ': 0x') + $hr.ToString('X8')) }
        } elseif ($api -eq 'MicaOld') {
            $hr = Set-DwmInt $hwnd 1029 1
            if ($hr -ne 0) { $ok = $false; $detail = ('DWM Mica: 0x' + $hr.ToString('X8')) }
        } else {
            $r = Set-WindowAccent $hwnd 4 2 (Get-AccentColor $mid 96)
            if ($r -eq 0) { $ok = $false; $detail = ('pencere bile' + [char]0x015F + 'imi ' + [char]0x00E7 + 'a' + [char]0x011F + 'r' + [char]0x0131 + 's' + [char]0x0131 + ' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z') }
        }
        if ($ok) {
            $hr2 = Set-DwmMargins $hwnd (-1)
            if ($hr2 -ne 0) { $ok = $false; $detail = (('' + [char]0x00E7 + 'er' + [char]0x00E7 + 'eve: 0x') + $hr2.ToString('X8')) }
        }
    } catch {
        $ok = $false
        $detail = [string]$_.Exception.Message
        Write-CrashLog (('Saydaml' + [char]0x0131 + 'k uygulanamad' + [char]0x0131 + ': ') + $detail)
    }
    if ($ok) {
        $script:GlassApplied = @{ Api = $api; Mode = $mode; Sig = $sig }
    } else {
        $script:GlassFail = [int]$script:GlassFail + 1
        try { $script:GlassApplied = @{ Api = $api; Mode = $mode; Sig = '' }; Clear-GlassWindow $hwnd } catch { $script:GlassApplied = $null }
    }
    $script:GlassState = @{ Ok = $ok; Detail = $detail }
    $res = 'tamam'
    if (-not $ok) { $res = ('ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $detail }
    try { Add-Trace (('saydaml' + [char]0x0131 + 'k: ') + $mode + ' (' + $api + ') ' + $res) } catch { }
}

# Tema uygulaninca cagrilir (Set-AppTheme): plan temaya gore yeniden kurulmustur; efekt ve koyu/acik malzeme buna uydurulur
function Update-GlassTheme {
    if ($null -eq $script:GlassApplied -and [string]$script:GlassPlan.Mode -eq 'Yok') { return }
    Update-GlassWindow
}

# Ayar degisince: fircalar yeni alfa ile boyanir (Set-AppTheme plani da kurar) ve efekt pencereye uygulanir
function Update-Glass {
    try { Set-AppTheme ([string]$script:ThemeName) } catch { Write-CrashLog (('Saydaml' + [char]0x0131 + 'k (tema): ') + $_.Exception.Message) }
    Update-GlassWindow
    Update-StGlassText
}

# Acilista: plan Initialize-Appearance'ta kuruldu; pencere gosterilince (SourceInitialized) efekt uygulanir
function Initialize-Glass {
    if (-not $script:GlassWired) {
        $script:GlassWired = $true
        $script:Win.Add_SourceInitialized({ try { Update-GlassWindow } catch { Write-CrashLog (('Saydaml' + [char]0x0131 + 'k: ') + $_.Exception.Message) } })
    }
    try { Update-GlassWindow } catch { Write-CrashLog (('Saydaml' + [char]0x0131 + 'k: ') + $_.Exception.Message) }
}

# Ayarlardan bir secim: donus $false ise saydamlik kapatilmistir
function Select-Glass([string]$Name, $Opacity) {
    $Name = ConvertTo-GlassKey $Name
    $op = ConvertTo-GlassOpacity $Opacity
    try { Add-Trace (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm: saydaml' + [char]0x0131 + 'k ') + $Name + ' %' + [string]$op) } catch { }
    $script:Settings.Backdrop = $Name
    $script:Settings.WinOpacity = $op
    $ok = $true
    try {
        Update-Glass
        if (-not $script:GlassState.Ok) { $ok = $false }
        if ([int]$script:ThemeFail -gt 0) { $ok = $false }
    } catch { $ok = $false; Write-CrashLog (('Saydaml' + [char]0x0131 + 'k uygulanamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if (-not $ok) {
        $script:Settings.Backdrop = 'Yok'
        $script:Settings.WinOpacity = 100
        try { Update-Glass } catch { }
        try { Load-StGlass } catch { }
        Show-Toast ('Saydaml' + [char]0x0131 + 'k bu sistemde uygulanamad' + [char]0x0131 + '; kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn'
    }
    return $ok
}

# ---------------- Ayarlar sayfasi ----------------
# Ayarlar sayfasi ilk gezintide kurulur; kurulmadan once aciklama kutusu yoktur (sayfa kurulunca Load-StGlass yazar)
function Update-StGlassText {
    try {
        if ($null -eq $ui.st_BdDesc) { return }
        $k = ConvertTo-GlassKey ([string]$script:Settings.Backdrop)
        $txt = ([string]$script:GlassInfo[$k].T + ': ' + [string]$script:GlassInfo[$k].D)
        $plan = $script:GlassPlan
        if ([string]$plan.Note -ne '') { $txt = $txt + ' ' + [string]$plan.Note }
        if ($k -ne 'Yok' -and [string]$plan.Mode -ne 'Yok') {
            $txt = $txt + ' Etkin: ' + [string]$script:GlassInfo[[string]$plan.Mode].T + (', y' + [char]0x00FC + 'zey opakl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' %') + [string](ConvertTo-GlassOpacity $script:Settings.WinOpacity) + '.'
        }
        $ui.st_BdDesc.Text = (Tr $($txt))
    } catch { }
}

function Initialize-StGlassChoices {
    $b = New-Object System.Collections.ArrayList
    foreach ($k in @($script:GlassInfo.Keys)) { [void]$b.Add((New-Choice ([string]$k) ([string]$script:GlassInfo[$k].T))) }
    Set-ComboChoices $ui.st_BackdropSel $b.ToArray()
    $o = New-Object System.Collections.ArrayList
    foreach ($z in $script:GlassSteps) { [void]$o.Add((New-Choice ([string]$z) (Format-Percent $z))) }
    Set-ComboChoices $ui.st_OpacitySel $o.ToArray()
}

function Load-StGlass {
    $k = ConvertTo-GlassKey ([string]$script:Settings.Backdrop)
    $op = ConvertTo-GlassOpacity $script:Settings.WinOpacity
    [void](Select-ComboKey $ui.st_BackdropSel $k)
    [void](Select-ComboKey $ui.st_OpacitySel ([string]$op))
    $ui.st_OpacitySel.IsEnabled = ($k -ne 'Yok')
    Update-StGlassText
}

function Save-StGlass {
    $s = $script:Settings
    $want = Get-ComboKey $ui.st_BackdropSel
    if ($want -eq '') { $want = ConvertTo-GlassKey ([string]$s.Backdrop) }
    $op = ConvertTo-GlassOpacity $s.WinOpacity
    $ov = Get-ComboKey $ui.st_OpacitySel
    if ($ov -ne '') { $op = ConvertTo-GlassOpacity $ov }
    # efekt ilk kez aciliyorsa gorunur bir opaklik onerilir (%100'de efekt gorunmez)
    if ($want -ne 'Yok' -and [string]$s.Backdrop -eq 'Yok' -and $op -eq 100) { $op = [int]$script:GlassDefaultOp[$want] }
    if ($want -ne [string]$s.Backdrop -or $op -ne (ConvertTo-GlassOpacity $s.WinOpacity)) {
        [void](Select-Glass $want $op)
        Load-StGlass
    }
}


# ---------------- Duman testi: tasarim ve saydamlik ----------------
# ==================================================================
#  DUMAN TESTI: tasarim ve saydamlik bolumleri (kapsamlar: tasarim, saydam; "tam" ikisini de icerir)
#  Tasarim: Ayarlar'daki acilir listelerden gercekten secim yapar; her tasarimda (Klasik dahil) menu bicimini, kose yuvarlakligini,
#  yazi tipini, ana ekran panosunu (duzenleme kipi, parca ekleme ve kaldirma, hazir duzene donus, kucuk pencere), ana ekranin iki bicimini
#  (pano / klasik durum panosu), tasarim ayrintilarinin tek tek secimini ve her temada ana ekranin goruntusunu sinar.
#  Saydamlik: Mica / Akrilik ve opaklik adimlarini secer; Windows'un efekti kabul edip etmedigini, firca
#  renklerinin beklenenle uyustugunu denetler ve her denemede pencerenin ekrandaki gercek goruntusunu (masaustu bilesimi dahil) kaydeder.
#  Gercek goruntulerde pencerenin arkasinda gorunen masaustu de yer alir; dosyalar yalnizca %TEMP%\Multimizer-duman\ekran altinda durur
#  ve bir sonraki duman testinin basinda silinir. Yalnizca arayuz durumu degisir (kopya ayar dosyasinda); sistem ayarlarina dokunulmaz.
#  Saydamlik gorunurlugu: Akrilik pencerenin arkasindaki pencereleri bulanik gosterir; test, pencerenin arkasina renkli bir zemin penceresi koyar
#  ve efekt acikken / kapaliyken alinan gercek goruntulerin sol bolgesinin ortalama renklerini karsilastirir (efekt yoksa fark sifira yakindir).
#  Surukleme: ana ekranda parca tasima ve boyutlandirma, isletim sistemi duzeyinde gercek fare girdisiyle denenir (imlec gercekten hareket eder);
#  pencerenin onunde baska bir pencere varsa girdi gonderilmez, adim uyariyla atlanir.
# ==================================================================
$script:SmokeDesigns = @('Klasik', 'Atolye', 'Sifir', 'Morpheus', 'Komuta')
# Tasarim ayrintilari: (ozellik, deger) ciftleri; her biri secilir, dogrulanir ve sonunda 'Auto'ya dondurulur
$script:SmokeOverrides = @(@('Nav', 'Fly'), @('Nav', 'Hidden'), @('Nav', 'Compact'), @('Nav', 'Rail'), @('Radius', 'Pill'), @('Radius', 'Sharp'), @('Radius', 'Soft'), @('Font', 'Mono'), @('Font', 'Sans'), @('Graph', 'scope'), @('Graph', 'none'), @('Skin', 'Neon'), @('Skin', 'Glass'), @('Skin', 'Calm'), @('Skin', 'Slate'))
# Saydamlik secenegi -> elle denenen opaklik adimlari; tema dizisi icin secenek basina opaklik
$script:SmokeGlassOps = [ordered]@{ Mica = @(100, 80, 50); Akrilik = @(90, 70, 50) }
$script:SmokeGlassThemeOp = @{ Mica = 80; Akrilik = 70 }
$script:SmokePresets = @('Atolye', 'Sifir', 'Morpheus', 'Komuta', 'Varsayilan')
$script:SmokeBoardId = ''
$script:SmokeBoardN = 0
$script:SmokeBackdrop = $null
$script:SmokeStats = @{}
$script:SmokeStatsOn = $false
$script:SmokeInputApi = $null
$script:SmokeDrag = $null
$script:SmokeMouseDown = $false

# Tasarim ve saydamlik adimlari (New-SmokeQueue cagirir). Bittiginde tasarim Klasik, saydamlik kapali, tema baslangic temasidir.
# Secimler Ayarlar > Gorunum'deki acilir listelerden yapilir (liste degisince uygulamanin kendi olayi calisir).
function Add-SmokeBoardEditParts($Q, [string]$D) {
    $Q.Enqueue((New-SmokeStep 'Page' 'panel' 900 (('sayfa panel (d' + [char]0x00FC + 'zenleme, ') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'Click' 'bd_BtnEdit' 500 (('d' + [char]0x00FC + '' + [char]0x011F + 'me: d' + [char]0x00FC + 'zeni a' + [char]0x00E7 + ' (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardCheck' 'edit' 300 (('pano d' + [char]0x00FC + 'zenleme kipi (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardAdd' '' 700 (('pano: par' + [char]0x00E7 + 'a ekle (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardCheck' 'added' 300 (('pano: par' + [char]0x00E7 + 'a eklendi mi (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $D + '-duzenle') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $D + (' d' + [char]0x00FC + 'zenleme'))))
    $Q.Enqueue((New-SmokeStep 'BoardRemove' '' 700 (('pano: par' + [char]0x00E7 + 'a kald' + [char]0x0131 + 'r (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardCheck' 'removed' 300 (('pano: par' + [char]0x00E7 + 'a kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ' m' + [char]0x0131 + ' (') + $D + ')')))
    # hazir duzen menusu: her tasarimda ayni hazir duzenler sunulur; birini secince pano o duzene gecer
    $Q.Enqueue((New-SmokeStep 'BoardLayoutMenu' '' 600 (('pano: haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen men' + [char]0x00FC + 's' + [char]0x00FC + ' (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardPreset' 'Klasik' 700 (('pano: Klasik haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zeni (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardCheck' 'edit' 300 (('pano: haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen sonras' + [char]0x0131 + ' (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $D + '-hazirduzen') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $D + (' Klasik haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen'))))
    # gercek fare girdisiyle: bir parcayi bir sutun ve bir satir kaydir; bir parcanin boyutunu bir adim degistir
    foreach ($dm in @('move', 'size')) {
        $Q.Enqueue((New-SmokeStep 'Drag' ($dm + '|down') 300 (('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme ') + $dm + (': fare bas' + [char]0x0131 + 'ld' + [char]0x0131 + ' (') + $D + ')')))
        foreach ($k in 1..5) { $Q.Enqueue((New-SmokeStep 'Drag' ($dm + '|' + [string]$k) 200 (('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme ') + $dm + ': ' + [string]$k + '/5 (' + $D + ')'))) }
        $Q.Enqueue((New-SmokeStep 'Drag' ($dm + '|up') 500 (('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme ') + $dm + (': fare b' + [char]0x0131 + 'rak' + [char]0x0131 + 'ld' + [char]0x0131 + ' (') + $D + ')')))
        $Q.Enqueue((New-SmokeStep 'Drag' ($dm + '|check') 400 (('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme ') + $dm + ' sonucu (' + $D + ')')))
    }
    $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $D + '-surukleme') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $D + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme sonras' + [char]0x0131 + ''))))
    $Q.Enqueue((New-SmokeStep 'Click' 'bd_BtnEdit' 500 (('d' + [char]0x00FC + '' + [char]0x011F + 'me: d' + [char]0x00FC + 'zeni kilitle (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 ('pano kilitli (' + $D + ')')))
    # Ayarlar'daki "Ana ekran duzenini sifirla": ozel duzen gider, tasarimin hazir duzeni gelir
    $Q.Enqueue((New-SmokeStep 'Page' 'settings' 600 (('sayfa settings (d' + [char]0x00FC + 'zeni s' + [char]0x0131 + 'f' + [char]0x0131 + 'rla, ') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'Click' 'st_BoardReset' 700 (('d' + [char]0x00FC + '' + [char]0x011F + 'me: ana ekran d' + [char]0x00FC + 'zenini s' + [char]0x0131 + 'f' + [char]0x0131 + 'rla (') + $D + ')')))
    $Q.Enqueue((New-SmokeStep 'BoardCheck' 'reset' 300 (('pano s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + ' m' + [char]0x0131 + ' (') + $D + ')')))
}

function Add-SmokeLookParts($Q, $Parts, [string]$Start) {
    if ($Parts -contains 'tasarim') {
        # 1) acilir listeler ayarlarla tutarli mi; acilan listenin gercek ekran goruntusu
        $Q.Enqueue((New-SmokeStep 'Page' 'settings' 800 ('sayfa settings (a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler)')))
        $Q.Enqueue((New-SmokeStep 'ComboCheck' '' 300 ('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler ayarlarla tutarl' + [char]0x0131 + ' m' + [char]0x0131 + ' (ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ')')))
        foreach ($cn in @('st_LookSel', 'st_ThemeSel', 'st_DesignSel', 'st_HomeSel')) {
            $Q.Enqueue((New-SmokeStep 'Reveal' $cn 500 (('listeyi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r yap ') + $cn)))
            $Q.Enqueue((New-SmokeStep 'DropDown' ($cn + '|open') 700 (('liste a' + [char]0x00E7 + ' ') + $cn)))
            $Q.Enqueue((New-SmokeStep 'DropDownCheck' $cn 200 (('a' + [char]0x00E7 + '' + [char]0x0131 + 'k liste do' + [char]0x011F + 'rula ') + $cn)))
            $Q.Enqueue((New-SmokeStep 'PopupWheel' $cn 300 (('tekerlek a' + [char]0x00E7 + '' + [char]0x0131 + 'k liste ' + [char]0x00FC + 'st' + [char]0x00FC + 'nde ') + $cn)))
            $Q.Enqueue((New-SmokeStep 'Screen' ('liste-' + $cn) 0 (('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ': a' + [char]0x00E7 + '' + [char]0x0131 + 'k liste ') + $cn)))
            $Q.Enqueue((New-SmokeStep 'DropDown' ($cn + '|close') 400 ('liste kapat ' + $cn)))
        }
        # 2) tasarimlar: her tasarimda pano (varsayilan), duzenleme, hazir duzen menusu, surukleme ve klasik durum panosu
        foreach ($d in $script:SmokeDesigns) {
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 ('sayfa settings (' + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Select' ('st_DesignSel|' + $d) 1100 (('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm ') + $d)))
            $Q.Enqueue((New-SmokeStep 'DesignCheck' $d 300 (('tasar' + [char]0x0131 + 'm do' + [char]0x011F + 'rula ') + $d)))
            $Q.Enqueue((New-SmokeStep 'HomeCheck' 'Pano' 200 (('ana ekran bi' + [char]0x00E7 + 'imi: pano (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'ComboCheck' '' 200 (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler tutarl' + [char]0x0131 + ' m' + [char]0x0131 + ' (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'NavMenu' '' 700 (('men' + [char]0x00FC + ' denemesi (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Page' 'panel' 1000 (('sayfa panel / tasar' + [char]0x0131 + 'm ') + $d)))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 (('pano do' + [char]0x011F + 'rula (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $d + '-panel') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $d + ' panel')))
            foreach ($pg in @('optimize', 'network', 'settings')) {
                $Q.Enqueue((New-SmokeStep 'Page' $pg 800 ('sayfa ' + $pg + (' / tasar' + [char]0x0131 + 'm ') + $d)))
                $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $d + '-' + $pg) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $d + ' ' + $pg)))
            }
            Add-SmokeBoardEditParts $Q $d
            # en kucuk pencerede pano
            $Q.Enqueue((New-SmokeStep 'Size' '1060x660' 600 (('pencere en k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k boyut (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Page' 'panel' 800 (('sayfa panel (k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere, ') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 (('pano k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencerede (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $d + '-kucuk') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $d + (' k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k pencere'))))
            $Q.Enqueue((New-SmokeStep 'Size' '1380x840' 600 (('pencere varsay' + [char]0x0131 + 'lan boyut (') + $d + ')')))
            # ana ekran bicimi: klasik durum panosu bu tasarimin kabugunda; "Ana ekrani duzenle" panoya geri doner
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 (('sayfa settings (ana ekran bi' + [char]0x00E7 + 'imi, ') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Select' 'st_HomeSel|Klasik' 900 (('se' + [char]0x00E7 + ' ana ekran: klasik durum panosu (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'HomeCheck' 'Klasik' 200 (('ana ekran bi' + [char]0x00E7 + 'imi: klasik (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'DesignCheck' $d 300 (('tasar' + [char]0x0131 + 'm do' + [char]0x011F + 'rula ') + $d + ' (klasik ana ekran)')))
            $Q.Enqueue((New-SmokeStep 'Page' 'panel' 1000 ('sayfa panel / klasik ana ekran / ' + $d)))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'off' 300 ('klasik durum panosu (' + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $d + '-klasikpano') 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $d + ' klasik durum panosu')))
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 (('sayfa settings (ana ekran' + [char]0x0131 + ' d' + [char]0x00FC + 'zenle, ') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Click' 'st_BoardEdit' 900 (('d' + [char]0x00FC + '' + [char]0x011F + 'me: ana ekran' + [char]0x0131 + ' d' + [char]0x00FC + 'zenle (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'HomeCheck' 'Pano' 200 (('ana ekran' + [char]0x0131 + ' d' + [char]0x00FC + 'zenle panoya ge' + [char]0x00E7 + 'irdi mi (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'edit' 300 (('pano d' + [char]0x00FC + 'zenleme kipinde (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Click' 'bd_BtnEdit' 500 (('d' + [char]0x00FC + '' + [char]0x011F + 'me: d' + [char]0x00FC + 'zeni kilitle (') + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 ('pano kilitli (' + $d + ')')))
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 600 'sayfa settings'))
        }
        # 3) tasarim ayrintilari: tek tek secilir, kabuga ve panoya yansimasi dogrulanir (Klasik tasarimda; tasarimin kendi degerlerinin tersi de Morpheus'ta denenir)
        $Q.Enqueue((New-SmokeStep 'Select' 'st_DesignSel|Klasik' 1100 ('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm Klasik (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar)')))
        $Q.Enqueue((New-SmokeStep 'Check' 'st_DsAdv|on' 400 ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' paneli a' + [char]0x00E7 + '' + [char]0x0131 + 'k')))
        $Q.Enqueue((New-SmokeStep 'Reveal' 'st_DsNavSel' 500 ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' listelerini g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r yap')))
        $Q.Enqueue((New-SmokeStep 'Shot' 'tasarim-ayrintilar-ayarlar' 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ': tasar' + [char]0x0131 + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' paneli')))
        foreach ($ov in $script:SmokeOverrides) {
            $prop = [string]$ov[0]
            $val = [string]$ov[1]
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 600 (('sayfa settings (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ') + $prop + ' ' + $val + ')')))
            $Q.Enqueue((New-SmokeStep 'Select' ('st_Ds' + $prop + 'Sel|' + $val) 800 (('se' + [char]0x00E7 + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ') + $prop + ' = ' + $val)))
            $Q.Enqueue((New-SmokeStep 'OverrideCheck' ($prop + '|' + $val) 300 (('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' do' + [char]0x011F + 'rula ') + $prop + ' = ' + $val)))
            $Q.Enqueue((New-SmokeStep 'ComboCheck' '' 200 (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler tutarl' + [char]0x0131 + ' m' + [char]0x0131 + ' (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ') + $prop + ')')))
            if ($prop -eq 'Nav') { $Q.Enqueue((New-SmokeStep 'NavMenu' '' 700 (('men' + [char]0x00FC + ' denemesi (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' Nav ') + $val + ')'))) }
            $Q.Enqueue((New-SmokeStep 'Page' 'panel' 900 (('sayfa panel / ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ') + $prop + ' = ' + $val)))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 (('pano do' + [char]0x011F + 'rula (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ') + $prop + ' = ' + $val + ')')))
            $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-ayrinti-' + $prop + '-' + $val) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ') + $prop + ' = ' + $val)))
        }
        $Q.Enqueue((New-SmokeStep 'Page' 'settings' 600 ('sayfa settings (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rla)')))
        $Q.Enqueue((New-SmokeStep 'Click' 'st_DsReset' 900 ('d' + [char]0x00FC + '' + [char]0x011F + 'me: tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n kendi de' + [char]0x011F + 'erlerine d' + [char]0x00F6 + 'n')))
        $Q.Enqueue((New-SmokeStep 'OverrideCheck' 'Reset' 300 ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + ' m' + [char]0x0131 + '')))
        $Q.Enqueue((New-SmokeStep 'ComboCheck' '' 200 ('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler tutarl' + [char]0x0131 + ' m' + [char]0x0131 + ' (s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlamadan sonra)')))
        # Morpheus: tek aralikli yazi, keskin kose ve osiloskop grafigi tasarimin kendi degeridir; ayrinti secimiyle tersi verilebilmeli
        $Q.Enqueue((New-SmokeStep 'Select' 'st_DesignSel|Morpheus' 1100 ('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm Morpheus (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + 'n tersi)')))
        foreach ($ov in @(@('Font', 'Sans'), @('Radius', 'Round'), @('Graph', 'area'), @('Nav', 'Rail'), @('Skin', 'Plain'))) {
            $Q.Enqueue((New-SmokeStep 'Select' ('st_Ds' + [string]$ov[0] + 'Sel|' + [string]$ov[1]) 800 (('se' + [char]0x00E7 + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ') + [string]$ov[0] + ' = ' + [string]$ov[1] + ' (Morpheus)')))
            $Q.Enqueue((New-SmokeStep 'OverrideCheck' ([string]$ov[0] + '|' + [string]$ov[1]) 300 (('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' do' + [char]0x011F + 'rula ') + [string]$ov[0] + ' = ' + [string]$ov[1] + ' (Morpheus)')))
        }
        $Q.Enqueue((New-SmokeStep 'Page' 'panel' 900 ('sayfa panel / Morpheus ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + '')))
        $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 ('pano do' + [char]0x011F + 'rula (Morpheus, ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar tersine)')))
        $Q.Enqueue((New-SmokeStep 'Shot' 'tasarim-Morpheus-tersine' 0 ('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' Morpheus (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n tersine)')))
        # tasarim degisince ayrintilar tasarimin degerlerine doner
        $Q.Enqueue((New-SmokeStep 'Page' 'settings' 600 'sayfa settings'))
        $Q.Enqueue((New-SmokeStep 'Select' 'st_DesignSel|Komuta' 1100 ('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm Komuta (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlanmal' + [char]0x0131 + ')')))
        $Q.Enqueue((New-SmokeStep 'OverrideCheck' 'Reset' 300 ('tasar' + [char]0x0131 + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'ince ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + ' m' + [char]0x0131 + '')))
        $Q.Enqueue((New-SmokeStep 'Check' 'st_DsAdv|off' 400 ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' paneli kapal' + [char]0x0131 + '')))
        $Q.Enqueue((New-SmokeStep 'Select' 'st_DesignSel|Klasik' 1100 ('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm Klasik')))
        $Q.Enqueue((New-SmokeStep 'DesignCheck' 'Klasik' 300 ('tasar' + [char]0x0131 + 'm do' + [char]0x011F + 'rula Klasik')))
        # 4) hazir gorunumler (tema + yerlesim + tasarim + saydamlik birlikte)
        foreach ($pr in $script:SmokePresets) {
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 'sayfa settings'))
            $Q.Enqueue((New-SmokeStep 'Select' ('st_LookSel|' + $pr) 1500 (('se' + [char]0x00E7 + ' haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm ') + $pr)))
            $Q.Enqueue((New-SmokeStep 'PresetCheck' $pr 300 (('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm do' + [char]0x011F + 'rula ') + $pr)))
            $Q.Enqueue((New-SmokeStep 'Page' 'panel' 1000 (('sayfa panel / haz' + [char]0x0131 + 'r ') + $pr)))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 (('pano haz' + [char]0x0131 + 'r ') + $pr)))
            $Q.Enqueue((New-SmokeStep 'Screen' ('hazir-' + $pr + '-panel') 0 (('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' haz' + [char]0x0131 + 'r ') + $pr)))
        }
        # 5) tasarim x tema: ana ekran her temada okunur ve renkleri temaya uyar
        foreach ($d in $script:SmokeDesigns) {
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 'sayfa settings'))
            $Q.Enqueue((New-SmokeStep 'Select' ('st_DesignSel|' + $d) 1100 (('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm ') + $d + ' (tema dizisi)')))
            foreach ($t in $script:SmokeThemes) {
                $Q.Enqueue((New-SmokeStep 'Theme' $t 250 (('tasar' + [char]0x0131 + 'm ') + $d + ' / tema ' + $t)))
                $Q.Enqueue((New-SmokeStep 'Page' 'panel' 900 ('sayfa panel / ' + $d + ' / ' + $t)))
                $Q.Enqueue((New-SmokeStep 'Shot' ('tasarim-' + $d + '-' + $t) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' tasar' + [char]0x0131 + 'm ') + $d + ' tema ' + $t)))
            }
        }
        $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 'sayfa settings'))
        $Q.Enqueue((New-SmokeStep 'Select' 'st_DesignSel|Klasik' 1100 ('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm Klasik (tema dizisi sonras' + [char]0x0131 + ')')))
        $Q.Enqueue((New-SmokeStep 'DesignCheck' 'Klasik' 300 ('tasar' + [char]0x0131 + 'm do' + [char]0x011F + 'rula Klasik')))
        $Q.Enqueue((New-SmokeStep 'Theme' $Start 250 ('tema geri: ' + $Start)))
        $Q.Enqueue((New-SmokeStep 'ComboCheck' '' 200 ('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler tutarl' + [char]0x0131 + ' m' + [char]0x0131 + ' (son)')))
        $Q.Enqueue((New-SmokeStep 'Drain' '' 1500 ('i' + [char]0x015F + ' bitsin (tasar' + [char]0x0131 + 'm)')))
    }
    if ($Parts -contains 'saydam') {
        # Ayarlar'daki saydamlik listelerinden secim; her denemede dogrulama ve ekranin gercek goruntusu
        $Q.Enqueue((New-SmokeStep 'Page' 'settings' 800 ('sayfa settings (saydaml' + [char]0x0131 + 'k se' + [char]0x00E7 + 'imleri)')))
        $Q.Enqueue((New-SmokeStep 'Theme' 'Neon' 250 ('tema Neon (saydaml' + [char]0x0131 + 'k)')))
        $Q.Enqueue((New-SmokeStep 'GlassCheck' 'Yok|*' 900 ('saydaml' + [char]0x0131 + 'k do' + [char]0x011F + 'rula (kapal' + [char]0x0131 + ')')))
        $Q.Enqueue((New-SmokeStep 'Backdrop' 'on' 900 ('pencerenin arkas' + [char]0x0131 + 'na renkli zemin')))
        $Q.Enqueue((New-SmokeStep 'Screen' 'saydam-Yok-Neon' 0 ('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + '')))
        foreach ($m in @($script:SmokeGlassOps.Keys)) {
            $Q.Enqueue((New-SmokeStep 'Select' ('st_BackdropSel|' + $m) 1300 (('se' + [char]0x00E7 + ' saydaml' + [char]0x0131 + 'k ') + $m)))
            $Q.Enqueue((New-SmokeStep 'GlassCheck' ($m + '|*') 300 (('saydaml' + [char]0x0131 + 'k do' + [char]0x011F + 'rula ') + $m)))
            foreach ($op in @($script:SmokeGlassOps[$m])) {
                $Q.Enqueue((New-SmokeStep 'Select' ('st_OpacitySel|' + [string]$op) 1100 (('se' + [char]0x00E7 + ' opakl' + [char]0x0131 + 'k %') + [string]$op + ' (' + $m + ')')))
                $Q.Enqueue((New-SmokeStep 'GlassCheck' ($m + '|' + [string]$op) 300 (('saydaml' + [char]0x0131 + 'k do' + [char]0x011F + 'rula ') + $m + ' %' + [string]$op)))
                $Q.Enqueue((New-SmokeStep 'Screen' ('saydam-' + $m + '-' + [string]$op) 0 (('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' ') + $m + ' %' + [string]$op)))
                # Akrilik arkadaki zemini bulaniklastirip karistirir: %70 ve altinda fark aranir (Mica yalnizca masaustu duvar kagidini yansitir; fark yalnizca yazilir).
                # Gercek cihazda olculen ortalama renk farki; govde ve ust/alt serit olculur, buyugu sayilir.
                # Kompakt yerlesim: %90 -> 0,6   %70 -> 3,9 ila 5,3   %50 -> 12 ila 15. Ayrintili yerlesimde govdeyi opak kartlar kapladigindan govde
                # 0,3 / 2,4 / 6,4, ust ve alt serit 1,6 / 6,4 / 13,9 cikar. Efekt kapaliyken ayni olcum 1,1'in altinda kalir.
                # Esikler, olculen en dusuk degerin yaklasik %65'i: %70 icin 2,5 ve %50 icin 8
                $minDiff = 0
                if ($m -eq 'Akrilik') {
                    if ([int]$op -le 50) { $minDiff = 8 } elseif ([int]$op -le 70) { $minDiff = 2.5 }
                }
                $Q.Enqueue((New-SmokeStep 'GlassVisible' ('saydam-' + $m + '-' + [string]$op + '|saydam-Yok-Neon|' + [string]$minDiff) 0 (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + 'k ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm' + [char]0x00FC + ' ') + $m + ' %' + [string]$op)))
            }
            # her temada bu secenek (opaklik: secenegin onerilen degeri)
            $tp = [int]$script:SmokeGlassThemeOp[$m]
            $Q.Enqueue((New-SmokeStep 'Select' ('st_OpacitySel|' + [string]$tp) 1100 (('se' + [char]0x00E7 + ' opakl' + [char]0x0131 + 'k %') + [string]$tp + ' (' + $m + ', tema dizisi)')))
            foreach ($t in $script:SmokeThemes) {
                $Q.Enqueue((New-SmokeStep 'Theme' $t 250 (('saydaml' + [char]0x0131 + 'k ') + $m + ' / tema ' + $t)))
                $Q.Enqueue((New-SmokeStep 'GlassCheck' ($m + '|' + [string]$tp) 900 (('saydaml' + [char]0x0131 + 'k do' + [char]0x011F + 'rula ') + $m + ' / ' + $t)))
                $Q.Enqueue((New-SmokeStep 'Screen' ('saydam-' + $m + '-' + $t) 0 (('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' ') + $m + ' tema ' + $t)))
            }
            $Q.Enqueue((New-SmokeStep 'Theme' 'Neon' 250 ('tema Neon (saydaml' + [char]0x0131 + 'k)')))
        }
        # acik saydamlik listesinin gercek goruntusu (acilan pencere de saydamlikla birlikte okunur olmali)
        $Q.Enqueue((New-SmokeStep 'Reveal' 'st_BackdropSel' 500 ('saydaml' + [char]0x0131 + 'k listesini g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r yap')))
        $Q.Enqueue((New-SmokeStep 'DropDown' 'st_BackdropSel|open' 700 ('liste a' + [char]0x00E7 + ' st_BackdropSel (saydaml' + [char]0x0131 + 'kla)')))
        $Q.Enqueue((New-SmokeStep 'DropDownCheck' 'st_BackdropSel' 200 ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k liste do' + [char]0x011F + 'rula st_BackdropSel')))
        $Q.Enqueue((New-SmokeStep 'PopupWheel' 'st_BackdropSel' 300 ('tekerlek a' + [char]0x00E7 + '' + [char]0x0131 + 'k liste ' + [char]0x00FC + 'st' + [char]0x00FC + 'nde st_BackdropSel')))
        $Q.Enqueue((New-SmokeStep 'Screen' 'saydam-liste-acik' 0 ('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ': a' + [char]0x00E7 + '' + [char]0x0131 + 'k saydaml' + [char]0x0131 + 'k listesi')))
        $Q.Enqueue((New-SmokeStep 'DropDown' 'st_BackdropSel|close' 400 'liste kapat st_BackdropSel'))
        # sayfalar saydamlikla (Mica %80)
        $Q.Enqueue((New-SmokeStep 'Select' 'st_BackdropSel|Mica' 1300 ('se' + [char]0x00E7 + ' saydaml' + [char]0x0131 + 'k Mica (sayfalar)')))
        $Q.Enqueue((New-SmokeStep 'Select' 'st_OpacitySel|80' 1100 ('se' + [char]0x00E7 + ' opakl' + [char]0x0131 + 'k %80 (sayfalar)')))
        foreach ($pg in @('panel', 'optimize', 'network', 'settings')) {
            $Q.Enqueue((New-SmokeStep 'Page' $pg 900 ('sayfa ' + $pg + ' / Mica %80')))
            $Q.Enqueue((New-SmokeStep 'GlassCheck' 'Mica|80' 200 (('saydaml' + [char]0x0131 + 'k do' + [char]0x011F + 'rula (sayfa ') + $pg + ')')))
            $Q.Enqueue((New-SmokeStep 'Screen' ('saydam-sayfa-' + $pg) 0 (('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' sayfa ') + $pg + ' Mica %80')))
        }
        # tasarim + saydamlik birlikte (tasarim degisince saydamlik korunur)
        foreach ($cb in @(@('Morpheus', 'Akrilik', 70), @('Komuta', 'Akrilik', 60), @('Atolye', 'Mica', 80))) {
            $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 'sayfa settings'))
            $Q.Enqueue((New-SmokeStep 'Select' ('st_DesignSel|' + $cb[0]) 1100 (('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm ') + $cb[0] + (' (saydaml' + [char]0x0131 + 'k)'))))
            $Q.Enqueue((New-SmokeStep 'Select' ('st_BackdropSel|' + $cb[1]) 1300 (('se' + [char]0x00E7 + ' saydaml' + [char]0x0131 + 'k ') + $cb[1])))
            $Q.Enqueue((New-SmokeStep 'Select' ('st_OpacitySel|' + [string]$cb[2]) 1100 (('se' + [char]0x00E7 + ' opakl' + [char]0x0131 + 'k %') + [string]$cb[2])))
            $Q.Enqueue((New-SmokeStep 'DesignCheck' $cb[0] 300 (('tasar' + [char]0x0131 + 'm do' + [char]0x011F + 'rula ') + $cb[0])))
            $Q.Enqueue((New-SmokeStep 'GlassCheck' ($cb[1] + '|' + [string]$cb[2]) 300 (('saydaml' + [char]0x0131 + 'k do' + [char]0x011F + 'rula ') + $cb[1])))
            $Q.Enqueue((New-SmokeStep 'Page' 'panel' 1000 ('sayfa panel / ' + $cb[0] + ' / ' + $cb[1])))
            $Q.Enqueue((New-SmokeStep 'BoardCheck' 'home' 300 (('pano do' + [char]0x011F + 'rula (') + $cb[0] + (', saydaml' + [char]0x0131 + 'k)'))))
            $Q.Enqueue((New-SmokeStep 'Screen' ('saydam-' + $cb[0] + '-' + $cb[1]) 0 (('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' ') + $cb[0] + ' + ' + $cb[1])))
        }
        # kapat: pencere duz renge doner
        $Q.Enqueue((New-SmokeStep 'Page' 'settings' 700 'sayfa settings'))
        $Q.Enqueue((New-SmokeStep 'Select' 'st_BackdropSel|Yok' 1300 ('se' + [char]0x00E7 + ' saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + '')))
        $Q.Enqueue((New-SmokeStep 'GlassCheck' 'Yok|*' 400 ('saydaml' + [char]0x0131 + 'k do' + [char]0x011F + 'rula (kapal' + [char]0x0131 + ', geri)')))
        $Q.Enqueue((New-SmokeStep 'ComboCheck' '' 200 ('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler tutarl' + [char]0x0131 + ' m' + [char]0x0131 + ' (saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + ')')))
        $Q.Enqueue((New-SmokeStep 'Screen' 'saydam-kapali-geri' 0 ('ger' + [char]0x00E7 + 'ek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' saydaml' + [char]0x0131 + 'k kapal' + [char]0x0131 + ' (geri)')))
        $Q.Enqueue((New-SmokeStep 'Select' 'st_DesignSel|Klasik' 1100 ('se' + [char]0x00E7 + ' tasar' + [char]0x0131 + 'm Klasik (saydaml' + [char]0x0131 + 'k sonras' + [char]0x0131 + ')')))
        $Q.Enqueue((New-SmokeStep 'DesignCheck' 'Klasik' 300 ('tasar' + [char]0x0131 + 'm do' + [char]0x011F + 'rula Klasik')))
        $Q.Enqueue((New-SmokeStep 'Backdrop' 'off' 400 ('renkli zemin kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '')))
        $Q.Enqueue((New-SmokeStep 'Theme' $Start 250 ('tema geri: ' + $Start)))
        $Q.Enqueue((New-SmokeStep 'Drain' '' 1500 ('i' + [char]0x015F + ' bitsin (saydaml' + [char]0x0131 + 'k)')))
    }
}

function Test-SmokeShown($El) {
    return ($null -ne $El -and $El.Visibility -eq $script:VisOn)
}

# ---------------- renkli zemin ve piksel olcumu ----------------
# Pencerenin arkasina parlak, seritli bir pencere koyar. Akrilik arkadakini bulanik gosterir; koyu bir masaustunde fark gozle secilemez.
function Set-SmokeFront {
    try {
        $script:Win.Topmost = $true
        $script:Win.Topmost = $false
        [void]$script:Win.Activate()
    } catch { }
}

function Show-SmokeBackdrop {
    if ($null -ne $script:SmokeBackdrop) { return }
    $win = $script:Win
    $src = [System.Windows.PresentationSource]::FromVisual($win)
    $sx = 1.0
    $sy = 1.0
    if ($null -ne $src -and $null -ne $src.CompositionTarget) {
        $sx = [double]$src.CompositionTarget.TransformToDevice.M11
        $sy = [double]$src.CompositionTarget.TransformToDevice.M22
    }
    $org = $win.PointToScreen((New-Object System.Windows.Point -ArgumentList 0.0, 0.0))
    $w = New-Object System.Windows.Window
    $w.WindowStyle = [System.Windows.WindowStyle]::None
    $w.ResizeMode = [System.Windows.ResizeMode]::NoResize
    $w.ShowInTaskbar = $false
    $w.ShowActivated = $false
    $w.WindowStartupLocation = [System.Windows.WindowStartupLocation]::Manual
    $w.Left = [double]$org.X / $sx
    $w.Top = [double]$org.Y / $sy
    $w.Width = [double]$win.ActualWidth
    $w.Height = [double]$win.ActualHeight
    $g = New-Object System.Windows.Controls.Grid
    $cols = @('#E53935', '#FDD835', '#43A047', '#00ACC1', '#1E88E5', '#8E24AA')
    $i = 0
    foreach ($c in $cols) {
        [void]$g.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
        $r = New-Object System.Windows.Shapes.Rectangle
        $r.Fill = New-Object System.Windows.Media.SolidColorBrush -ArgumentList ([System.Windows.Media.Color][System.Windows.Media.ColorConverter]::ConvertFromString($c))
        [System.Windows.Controls.Grid]::SetColumn($r, $i)
        [void]$g.Children.Add($r)
        $i++
    }
    $w.Content = (Tr $($g))
    $w.Show()
    $script:SmokeBackdrop = $w
    $script:SmokeStatsOn = $true
    Set-SmokeFront
}

function Remove-SmokeBackdrop {
    $script:SmokeStatsOn = $false
    try { if ($null -ne $script:SmokeBackdrop) { $script:SmokeBackdrop.Close() } } catch { }
    $script:SmokeBackdrop = $null
}

# Goruntunun sol bolgesinin ortalama rengi (sag tarafa baska pencereler binebilir; sol taraf pencerenin kendisidir)
function Get-SmokeLeftMean($Bmp) {
    $w = [int]$Bmp.Width
    $h = [int]$Bmp.Height
    $xa = [int]($w * 0.02)
    $xb = [int]($w * 0.40)
    $ya = [int]($h * 0.08)
    $yb = [int]($h * 0.92)
    $r = 0.0
    $g = 0.0
    $b = 0.0
    $n = 0
    for ($y = $ya; $y -lt $yb; $y += 6) {
        for ($x = $xa; $x -lt $xb; $x += 6) {
            $c = $Bmp.GetPixel($x, $y)
            $r += [double]$c.R
            $g += [double]$c.G
            $b += [double]$c.B
            $n++
        }
    }
    if ($n -lt 1) { return $null }
    $res = @{ R = ($r / $n); G = ($g / $n); B = ($b / $n) }
    # Ust ve alt serit (baslik ve durum cubugu): govdede opak kartlar camin onunu kapatabilir ve bu yerlesime gore degisir
    # (Ayrintili yerlesimde govde farki yarisina iner). Seritlerde yuzey pencerenin kendisidir; cam her yerlesimde en belirgin burada gorunur.
    # Statik icerik (yazi, simge) iki goruntude de ayni oldugundan farki etkilemez.
    $sr = 0.0
    $sg = 0.0
    $sb = 0.0
    $sn = 0
    foreach ($band in @(@(0.012, 0.070), @(0.945, 0.985))) {
        for ($y = [int]($h * [double]$band[0]); $y -lt [int]($h * [double]$band[1]); $y += 4) {
            for ($x = $xa; $x -lt $xb; $x += 6) {
                $c = $Bmp.GetPixel($x, $y)
                $sr += [double]$c.R
                $sg += [double]$c.G
                $sb += [double]$c.B
                $sn++
            }
        }
    }
    if ($sn -gt 0) { $res.BarR = ($sr / $sn); $res.BarG = ($sg / $sn); $res.BarB = ($sb / $sn) }
    return $res
}

# Windows'ta "Saydamlik efektleri" acik mi? Kapaliysa Mica ve Akrilik duz renge duser; bu durumda efektin gorunmemesi hata sayilmaz.
function Test-SmokeSysTransparency {
    try {
        $v = Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name 'EnableTransparency' -ErrorAction Stop
        if ([int]$v.EnableTransparency -eq 0) { return $false }
    } catch { }
    return $true
}

# Spec: "olculen goruntu|kapaliyken alinan goruntu|en az fark" (en az fark 0 ise yalnizca yazilir)
function Test-SmokeGlassVisible([string]$Spec) {
    $p = $Spec.Split('|')
    $a = $script:SmokeStats[[string]$p[0]]
    $b = $script:SmokeStats[[string]$p[1]]
    $min = [double]$p[2]
    if ($null -eq $a -or $null -eq $b) { Add-SmokeWarn (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + 'k ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemedi (g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' yok): ') + $Spec); return }
    $d = ([math]::Abs([double]$a.R - [double]$b.R) + [math]::Abs([double]$a.G - [double]$b.G) + [math]::Abs([double]$a.B - [double]$b.B)) / 3.0
    $info = ('ortalama renk ' + [string][int]$a.R + ',' + [string][int]$a.G + ',' + [string][int]$a.B + (' (efekt kapal' + [char]0x0131 + 'yken ') + [string][int]$b.R + ',' + [string][int]$b.G + ',' + [string][int]$b.B + '), fark ' + [string][math]::Round($d, 1))
    # Govde farki yerlesime gore degisir: Ayrintili yerlesimde opak kartlar camin onunu kapatir. Ust ve alt serit olculduyse buyuk olan fark sayilir.
    if ($null -ne $a.BarR -and $null -ne $b.BarR) {
        $dBar = ([math]::Abs([double]$a.BarR - [double]$b.BarR) + [math]::Abs([double]$a.BarG - [double]$b.BarG) + [math]::Abs([double]$a.BarB - [double]$b.BarB)) / 3.0
        $info = $info + (', ' + [char]0x00FC + 'st ve alt ' + [char]0x015F + 'erit fark' + [char]0x0131 + ' ') + [string][math]::Round($dBar, 1)
        if ($dBar -gt $d) { $d = $dBar }
    }
    if ($min -gt 0 -and $d -lt $min) {
        if ([string]$script:GlassPlan.Mode -eq 'Yok') { Add-SmokeLine (('      g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + 'k ') + [string]$p[0] + (': efekt bu oturumda uygulanm' + [char]0x0131 + 'yor (') + [string]$script:GlassPlan.Note + ('), g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nmesi beklenmez - ') + $info) }
        elseif (Test-SmokeSysTransparency) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('efekt g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor: ') + $info + ', beklenen en az ' + [string]$min) }
        else { Add-SmokeWarn (('Windows ayarlar' + [char]0x0131 + 'nda saydaml' + [char]0x0131 + 'k efektleri kapal' + [char]0x0131 + ', bu y' + [char]0x00FC + 'zden efekt g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor: ') + $info) }
    }
    else { Add-SmokeLine (('      g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + 'k ') + [string]$p[0] + ': ' + $info) }
}

# ---------------- gercek fare girdisi (yalnizca duman testi) ----------------
function Get-SmokeInputApi {
    if ($null -ne $script:SmokeInputApi) { return $script:SmokeInputApi }
    try {
        if ($null -eq ('WH.SmokeInput' -as [type])) {
            Add-Type -Namespace WH -Name SmokeInput -ErrorAction Stop -MemberDefinition '[DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y); [DllImport("user32.dll")] public static extern void mouse_event(uint flags, uint dx, uint dy, uint data, UIntPtr extra); [DllImport("user32.dll")] public static extern IntPtr WindowFromPoint(long pt); [DllImport("user32.dll")] public static extern IntPtr GetAncestor(IntPtr hwnd, uint flags);'
        }
        $script:SmokeInputApi = ('WH.SmokeInput' -as [type])
    } catch { $script:SmokeInputApi = $null }
    return $script:SmokeInputApi
}

# What: down | up | move. Move $true ise imlec once (X, Y) noktasina goturulur.
function Send-SmokeMouse([string]$What, [int]$X, [int]$Y, [bool]$Move) {
    $api = Get-SmokeInputApi
    if ($null -eq $api) { return $false }
    if ($Move) { [void]$api::SetCursorPos($X, $Y) }
    $flag = 1
    if ($What -eq 'down') { $flag = 2 } elseif ($What -eq 'up') { $flag = 4 }
    $api::mouse_event([uint32]$flag, [uint32]0, [uint32]0, [uint32]0, [UIntPtr]::Zero)
    return $true
}

# Bu ekran noktasinda uygulamanin kendi penceresi mi var? (baska bir pencere ondeyse fare girdisi gonderilmez)
function Test-SmokeWindowAt([int]$X, [int]$Y) {
    try {
        $api = Get-SmokeInputApi
        if ($null -eq $api) { return $false }
        $pt = ([int64]$Y -shl 32) -bor ([int64]$X -band 4294967295)
        $h = $api::WindowFromPoint($pt)
        if ($h -eq [IntPtr]::Zero) { return $false }
        $root = $api::GetAncestor($h, 2)
        $mine = (New-Object System.Windows.Interop.WindowInteropHelper($script:Win)).Handle
        return ([int64]$root -eq [int64]$mine)
    } catch { return $false }
}

# Suruklenecek parcayi ve fare yolunu secer: tasima icin parcanin ortasindan bir sutun ve bir satir otesine,
# boyutlandirma icin sag alt kose tutamacindan bir adim otesine. Baslangic ve bitis noktasinda uygulamanin penceresi gorunmuyorsa parca atlanir.
function Get-SmokeDragPlan([string]$Mode) {
    $m = $script:BoardMetrics
    if ($null -eq $m -or $script:BoardEdit -ne $true) { return $null }
    $sx = [double]$m.CellW + [double]$m.Gap
    $sy = [double]$m.CellH + [double]$m.Gap
    foreach ($t in @($script:BoardLayout)) {
        $v = $script:BoardViews[[string]$t.Id]
        $wd = $script:BoardWidgets[[string]$t.Type]
        if ($null -eq $v -or $null -eq $wd) { continue }
        $nm = 'Veil'
        if ($Mode -eq 'size') { $nm = 'Grip' }
        $el = $v.N[$nm]
        if ($null -eq $el) { continue }
        $ew = [double]$el.ActualWidth
        $eh = [double]$el.ActualHeight
        if ([double]::IsNaN($ew) -or [double]::IsNaN($eh) -or $ew -lt 8 -or $eh -lt 8) { continue }
        $dx = 0.0
        $dy = 0.0
        if ($Mode -eq 'move') {
            if (([int]$t.X + [int]$t.W + 1) -le 12) { $dx = $sx } elseif ([int]$t.X -ge 1) { $dx = -$sx } else { continue }
            $dy = $sy
        } else {
            if (([int]$t.W + 1) -le [int]$wd.MaxW -and ([int]$t.X + [int]$t.W + 1) -le 12) { $dx = $sx } elseif (([int]$t.W - 1) -ge [int]$wd.MinW) { $dx = -$sx }
            if (([int]$t.H + 1) -le [int]$wd.MaxH) { $dy = $sy } elseif (([int]$t.H - 1) -ge [int]$wd.MinH) { $dy = -$sy }
            if ($dx -eq 0.0 -and $dy -eq 0.0) { continue }
        }
        $px = $ew / 2.0
        $py = $eh / 2.0
        $s0 = $el.PointToScreen((New-Object System.Windows.Point -ArgumentList $px, $py))
        $s1 = $el.PointToScreen((New-Object System.Windows.Point -ArgumentList ($px + $dx), ($py + $dy)))
        $x0 = [int][math]::Round([double]$s0.X)
        $y0 = [int][math]::Round([double]$s0.Y)
        $x1 = [int][math]::Round([double]$s1.X)
        $y1 = [int][math]::Round([double]$s1.Y)
        if (-not (Test-SmokeWindowAt $x0 $y0)) { continue }
        if (-not (Test-SmokeWindowAt $x1 $y1)) { continue }
        return @{ Id = [string]$t.Id; Type = [string]$t.Type; Mode = $Mode; X0 = $x0; Y0 = $y0; X1 = $x1; Y1 = $y1; TX = [int]$t.X; TY = [int]$t.Y; TW = [int]$t.W; TH = [int]$t.H }
    }
    return $null
}

# Arg: "tasima|boyut" + "|" + down | 1..5 | up | check
function Invoke-SmokeDrag([string]$Arg) {
    $p = $Arg.Split('|')
    $mode = [string]$p[0]
    $phase = [string]$p[1]
    if ($phase -eq 'down') {
        $script:SmokeDrag = $null
        Set-SmokeFront
        $plan = Get-SmokeDragPlan $mode
        if ($null -eq $plan) { Add-SmokeWarn (('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme (') + $mode + (') atland' + [char]0x0131 + ': uygun par' + [char]0x00E7 + 'a bulunamad' + [char]0x0131 + ' ya da par' + [char]0x00E7 + 'an' + [char]0x0131 + 'n ' + [char]0x00FC + 'st' + [char]0x00FC + 'nde pencerenin kendisi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor')); return }
        $script:SmokeDrag = $plan
        if (-not (Send-SmokeMouse 'down' $plan.X0 $plan.Y0 $true)) { Add-SmokeError ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme') ('fare girdisi g' + [char]0x00F6 + 'nderilemedi'); $script:SmokeDrag = $null; return }
        $script:SmokeMouseDown = $true
        return
    }
    $d = $script:SmokeDrag
    if ($null -eq $d) { return }
    if ($phase -eq 'up') {
        [void](Send-SmokeMouse 'up' $d.X1 $d.Y1 $true)
        $script:SmokeMouseDown = $false
        return
    }
    if ($phase -eq 'check') {
        Test-SmokeDragResult
        $script:SmokeDrag = $null
        return
    }
    $i = [int]$phase
    $x = [int][math]::Round([double]$d.X0 + ([double]$d.X1 - [double]$d.X0) * $i / 5.0)
    $y = [int][math]::Round([double]$d.Y0 + ([double]$d.Y1 - [double]$d.Y0) * $i / 5.0)
    [void](Send-SmokeMouse 'move' $x $y $true)
}

function Test-SmokeDragResult {
    $d = $script:SmokeDrag
    if ($null -eq $d) { return }
    if ($null -ne $script:BoardDrag) {
        Add-SmokeError ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme') ('fare b' + [char]0x0131 + 'rak' + [char]0x0131 + 'ld' + [char]0x0131 + ' ama s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme bitmedi')
        try { Stop-BoardDrag $false } catch { }
    }
    $t = Find-BoardTile $script:BoardLayout ([string]$d.Id)
    if ($null -eq $t) { Add-SmokeError ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme') ('par' + [char]0x00E7 + 'a d' + [char]0x00FC + 'zende bulunamad' + [char]0x0131 + ''); return }
    $bad = @(Get-BoardProblems $script:BoardLayout)
    if ($bad.Count -gt 0) { Add-SmokeError ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme') (('d' + [char]0x00FC + 'zen sorunlar' + [char]0x0131 + ': ') + ($bad -join '; ')) }
    if ([string]$d.Mode -eq 'move') {
        if ([int]$t.X -eq [int]$d.TX -and [int]$t.Y -eq [int]$d.TY) { Add-SmokeError ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme') (('par' + [char]0x00E7 + 'a yerinden oynamad' + [char]0x0131 + ' (') + [string]$d.Type + ' ' + [string]$d.TX + ',' + [string]$d.TY + ')') }
        else { Add-SmokeLine (('      s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme ta' + [char]0x015F + '' + [char]0x0131 + 'ma: ') + [string]$d.Type + ' ' + [string]$d.TX + ',' + [string]$d.TY + ' -> ' + [string]$t.X + ',' + [string]$t.Y) }
    } else {
        if ([int]$t.W -eq [int]$d.TW -and [int]$t.H -eq [int]$d.TH) { Add-SmokeError ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme') (('par' + [char]0x00E7 + 'an' + [char]0x0131 + 'n boyutu de' + [char]0x011F + 'i' + [char]0x015F + 'medi (') + [string]$d.Type + ' ' + [string]$d.TW + 'x' + [string]$d.TH + ')') }
        else { Add-SmokeLine (('      s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme boyut: ') + [string]$d.Type + ' ' + [string]$d.TW + 'x' + [string]$d.TH + ' -> ' + [string]$t.W + 'x' + [string]$t.H) }
    }
    if ($script:Settings.BoardCustom -ne $true) { Add-SmokeError ('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kleme') ('d' + [char]0x00FC + 'zen de' + [char]0x011F + 'i' + [char]0x015F + 'ti ama ' + [char]0x00F6 + 'zel d' + [char]0x00FC + 'zen i' + [char]0x015F + 'areti kapal' + [char]0x0131 + '') }
}

# Test biterken ya da bozulurken: basili kalmis fare dugmesini birakir, renkli zemini kapatir
function Stop-SmokeLook {
    try { if ($script:SmokeMouseDown -eq $true) { [void](Send-SmokeMouse 'up' 0 0 $false); $script:SmokeMouseDown = $false } } catch { }
    try { Remove-SmokeBackdrop } catch { }
}

# Pencerenin ekrandaki gercek goruntusu: masaustu bilesimi (Mica, Akrilik, seffaflik) dahil. Pencerenin arkasindaki masaustu de goruntuye girer.
function Save-SmokeScreen([string]$Name) {
    try {
        $win = $script:Win
        $src = [System.Windows.PresentationSource]::FromVisual($win)
        $sx = 1.0
        $sy = 1.0
        if ($null -ne $src -and $null -ne $src.CompositionTarget) {
            $sx = [double]$src.CompositionTarget.TransformToDevice.M11
            $sy = [double]$src.CompositionTarget.TransformToDevice.M22
        }
        $org = $win.PointToScreen((New-Object System.Windows.Point -ArgumentList 0.0, 0.0))
        $pw = [int][math]::Ceiling([double]$win.ActualWidth * $sx)
        $ph = [int][math]::Ceiling([double]$win.ActualHeight * $sy)
        if ($pw -lt 50 -or $ph -lt 50) { return }
        $bmp = New-Object System.Drawing.Bitmap -ArgumentList $pw, $ph
        try {
            $gr = [System.Drawing.Graphics]::FromImage($bmp)
            try { $gr.CopyFromScreen([int]$org.X, [int]$org.Y, 0, 0, (New-Object System.Drawing.Size -ArgumentList $pw, $ph)) } finally { $gr.Dispose() }
            if ($script:SmokeStatsOn -eq $true -and $Name.StartsWith('saydam-')) { $script:SmokeStats[$Name] = Get-SmokeLeftMean $bmp }
            $bmp.Save((Join-Path $script:SmokeDir ('gercek-' + $Name + '.png')), [System.Drawing.Imaging.ImageFormat]::Png)
        } finally { $bmp.Dispose() }
        $script:SmokeShots = [int]$script:SmokeShots + 1
    } catch { Add-SmokeError 'ekran yakalama' $_.Exception.Message }
}

# Bekleyen arayuz islerini (yukleme, yerlesim) bitirir: gercek tiklamadan sonra olan, ama tek bir duman adiminda olmayan sey
function Invoke-SmokeFlush {
    try { $script:Win.Dispatcher.Invoke([Action]{ }, [System.Windows.Threading.DispatcherPriority]::ContextIdle) } catch { }
}

# Acilir menu acik mi ve en az bu kadar ogesi var mi?
function Test-SmokeNavPopup([int]$MinItems, [string]$What) {
    $pop = $script:NavPop
    # menu ilk kez kuruldugunda acilir pencere henuz yuklenmemistir; WPF acma istegini yukleme bitince uygular
    if ($null -ne $pop -and -not $pop.IsOpen) { Invoke-SmokeFlush }
    if ($null -eq $pop -or -not $pop.IsOpen) {
        $why = ''
        if ($null -ne $pop) {
            $tg = $pop.PlacementTarget
            $tv = $false
            if ($null -ne $tg) { $tv = [bool]$tg.IsVisible }
            $why = (' (pencere y' + [char]0x00FC + 'klendi=') + [string]$pop.IsLoaded + ', hedef var=' + [string]($null -ne $tg) + (', hedef g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r=') + [string]$tv + (', ' + [char]0x00F6 + '' + [char]0x011F + 'e=') + [string]@($pop.FindName('Items').Children).Count + ')'
        }
        Add-SmokeError ('men' + [char]0x00FC + '') ($What + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + '') + $why)
        return
    }
    $stack = $pop.FindName('Items')
    $n = 0
    if ($null -ne $stack) { $n = [int]$stack.Children.Count }
    if ($n -lt $MinItems) { Add-SmokeError ('men' + [char]0x00FC + '') ($What + (': ' + [char]0x00F6 + '' + [char]0x011F + 'e say' + [char]0x0131 + 's' + [char]0x0131 + ' ') + [string]$n + ', beklenen en az ' + [string]$MinItems) }
    else { Add-SmokeLine ('      ' + $What + ': ' + [string]$n + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e')) }
}

# Tasarimin kabugu gercekten oturdu mu: ayar, menu bicimi, koseler, yazi tipi, baslik yazisi.
# Beklenen degerler etkin tasarimdan (tasarim + kullanicinin tek tek sectikleri + ana ekran bicimi) okunur.
function Test-SmokeDesign([string]$Key) {
    $spec = Get-ActiveDesign
    $script:Win.UpdateLayout()
    if ([string]$script:DesignKey -ne $Key) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('etkin tasar' + [char]0x0131 + 'm ') + [string]$script:DesignKey + ', beklenen ' + $Key) }
    if ([string]$script:Settings.Design -ne $Key) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') ('bellekteki ayar ' + [string]$script:Settings.Design + ', beklenen ' + $Key) }
    $cfg = ''
    try { $cfg = [string](Get-Settings).Design } catch { }
    if ($cfg -ne $Key) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') ('dosyadaki ayar ' + $cfg + ', beklenen ' + $Key) }
    if ([int]$script:DesignFail -gt 0) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('uygulanamayan ad' + [char]0x0131 + 'm say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + [string]$script:DesignFail) }
    $nav = [string]$spec.Nav
    $wantMenu = (($nav -eq 'Hidden') -or ($nav -eq 'Compact'))
    if ((Test-SmokeShown $ui.BtnMenu) -ne $wantMenu) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('ba' + [char]0x015F + 'l' + [char]0x0131 + 'k ' + [char]0x00E7 + 'ubu' + [char]0x011F + 'undaki men' + [char]0x00FC + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yanl' + [char]0x0131 + '' + [char]0x015F + ' (men' + [char]0x00FC + ' bi' + [char]0x00E7 + 'imi ') + $nav + ')') }
    if ((Test-SmokeShown $ui.RailHost) -ne ($nav -ne 'Hidden')) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('sol men' + [char]0x00FC + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yanl' + [char]0x0131 + '' + [char]0x015F + ' (men' + [char]0x00FC + ' bi' + [char]0x00E7 + 'imi ') + $nav + ')') }
    if ((Test-SmokeShown $ui.FlyRail) -ne ($nav -eq 'Fly')) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('simge men' + [char]0x00FC + 's' + [char]0x00FC + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yanl' + [char]0x0131 + '' + [char]0x015F + ' (men' + [char]0x00FC + ' bi' + [char]0x00E7 + 'imi ') + $nav + ')') }
    $rw = [double]$ui.RailHost.ActualWidth
    if ($nav -eq 'Hidden') { if ($rw -gt 2) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('gizli men' + [char]0x00FC + ' ') + [string][int]$rw + (' px yer kapl' + [char]0x0131 + 'yor')) } }
    elseif ($nav -eq 'Fly') { if ([math]::Abs($rw - 84.0) -gt 2) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('simge men' + [char]0x00FC + 's' + [char]0x00FC + ' geni' + [char]0x015F + 'li' + [char]0x011F + 'i ') + [string][int]$rw + ' px, beklenen 84') } }
    elseif ($rw -lt 40) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('sol men' + [char]0x00FC + ' geni' + [char]0x015F + 'li' + [char]0x011F + 'i ') + [string][int]$rw + (' px, ' + [char]0x00E7 + 'ok dar')) }
    $rad = ''
    foreach ($pair in @(@('RadCard', [double]$spec.RadCard), @('RadBtn', [double]$spec.RadBtn))) {
        $cr = $script:Win.Resources[[string]$pair[0]]
        if ($null -eq $cr) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('k' + [char]0x00F6 + '' + [char]0x015F + 'e kayna' + [char]0x011F + '' + [char]0x0131 + ' yok: ') + [string]$pair[0]); continue }
        if ([math]::Abs([double]$cr.TopLeft - [double]$pair[1]) -gt 0.01) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('k' + [char]0x00F6 + '' + [char]0x015F + 'e yuvarlakl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ') + [string]$pair[0] + ' = ' + [string]$cr.TopLeft + ', beklenen ' + [string]$pair[1]) }
        $rad = $rad + ' ' + [string]$pair[0] + '=' + [string]$cr.TopLeft
    }
    $wantMono = (([bool](Get-LayoutDefaults ([string]$script:LayoutName)).Mono) -or ($spec.Mono -eq $true))
    $mono = ([string]$script:Win.FontFamily.Source -like 'Cascadia*')
    if ($mono -ne $wantMono) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('tek aral' + [char]0x0131 + 'kl' + [char]0x0131 + ' yaz' + [char]0x0131 + ' tipi ') + [string]$mono + ', beklenen ' + [string]$wantMono) }
    if ([string]$spec.Tagline -ne '' -and [string]$ui.TxtTagline.Text -ne [string](Tr $spec.Tagline)) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('ba' + [char]0x015F + 'l' + [char]0x0131 + 'k yaz' + [char]0x0131 + 's' + [char]0x0131 + ' uygulanmad' + [char]0x0131 + ': ') + [string]$ui.TxtTagline.Text) }
    Add-SmokeLine (('      tasar' + [char]0x0131 + 'm ') + $Key + (': men' + [char]0x00FC + ' ') + $nav + ' ' + [string][int]$rw + (' px, k' + [char]0x00F6 + '' + [char]0x015F + 'e') + $rad + (', tek aral' + [char]0x0131 + 'kl' + [char]0x0131 + ' ') + [string]$mono + ', grafik ' + [string]$spec.Graph + (', par' + [char]0x00E7 + 'a ') + [string]$spec.Skin)
}

# Ana ekran bicimi: Pano | Klasik. Bellekte, dosyada, acilir listede ve etkin tasarimda ayni olmali.
function Test-SmokeHome([string]$Want) {
    $mem = ConvertTo-HomeKey (Get-BoardField $script:Settings 'HomeMode')
    if ($mem -ne $Want) { Add-SmokeError 'ana ekran' (('bellekteki ana ekran bi' + [char]0x00E7 + 'imi ') + $mem + ', beklenen ' + $Want) }
    $cfg = $null
    try { $cfg = Get-Settings } catch { $cfg = $null }
    if ($null -ne $cfg -and (ConvertTo-HomeKey (Get-BoardField $cfg 'HomeMode')) -ne $Want) { Add-SmokeError 'ana ekran' (('dosyadaki ana ekran bi' + [char]0x00E7 + 'imi ') + [string](Get-BoardField $cfg 'HomeMode') + ', beklenen ' + $Want) }
    $ck = Get-ComboKey $ui.st_HomeSel
    if ($ck -ne $Want) { Add-SmokeError 'ana ekran' (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listede ') + $ck + (' se' + [char]0x00E7 + 'ili, beklenen ') + $Want) }
    if ((Test-BoardHome) -ne ($Want -eq 'Pano')) { Add-SmokeError 'ana ekran' (('pano kullan' + [char]0x0131 + 'm' + [char]0x0131 + ' ') + [string](Test-BoardHome) + (', ana ekran bi' + [char]0x00E7 + 'imi ') + $Want) }
}

# Tasarim ayrintisi. Spec: "Ozellik|Deger" ya da "Reset" (hepsi tasarimin kendi degerinde). Bellek, dosya, acilir liste ve kabuk birlikte denetlenir.
function Test-SmokeOverride([string]$Spec) {
    $cfg = $null
    try { $cfg = Get-Settings } catch { $cfg = $null }
    if ($Spec -eq 'Reset') {
        foreach ($p in @($script:DsOptions.Keys)) {
            $k = 'Ds' + [string]$p
            if ((ConvertTo-DsValue ([string]$p) (Get-BoardField $script:Settings $k)) -ne 'Auto') { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') ($k + (' bellekte Auto olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ', de' + [char]0x011F + 'er ') + [string](Get-BoardField $script:Settings $k)) }
            if ($null -ne $cfg -and (ConvertTo-DsValue ([string]$p) (Get-BoardField $cfg $k)) -ne 'Auto') { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') ($k + (' dosyada Auto olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ', de' + [char]0x011F + 'er ') + [string](Get-BoardField $cfg $k)) }
            $ck = Get-ComboKey $ui[('st_Ds' + [string]$p + 'Sel')]
            if ($ck -ne 'Auto') { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') ('st_Ds' + [string]$p + 'Sel listesinde ' + $ck + (' se' + [char]0x00E7 + 'ili, beklenen Auto')) }
        }
        if (Test-DesignOverridden $script:Settings) { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') ('tasar' + [char]0x0131 + 'm h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' se' + [char]0x00E7 + 'ilmi' + [char]0x015F + ' say' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') }
    } else {
        $q = $Spec.Split('|')
        $prop = [string]$q[0]
        $want = [string]$q[1]
        $k = 'Ds' + $prop
        $mem = ConvertTo-DsValue $prop (Get-BoardField $script:Settings $k)
        if ($mem -ne $want) { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') ($k + ' bellekte ' + $mem + ', beklenen ' + $want) }
        if ($null -ne $cfg -and (ConvertTo-DsValue $prop (Get-BoardField $cfg $k)) -ne $want) { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') ($k + ' dosyada ' + [string](Get-BoardField $cfg $k) + ', beklenen ' + $want) }
        $ck = Get-ComboKey $ui[('st_Ds' + $prop + 'Sel')]
        if ($ck -ne $want) { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') ('st_Ds' + $prop + 'Sel listesinde ' + $ck + (' se' + [char]0x00E7 + 'ili, beklenen ') + $want) }
        # etkin tasarim secimi yansitir
        $act = Get-ActiveDesign
        $got = ''
        if ($prop -eq 'Nav') { $got = [string]$act.Nav }
        elseif ($prop -eq 'Graph') { $got = [string]$act.Graph }
        elseif ($prop -eq 'Skin') { $got = [string]$act.Skin }
        elseif ($prop -eq 'Font') { if ($act.Mono -eq $true) { $got = 'Mono' } else { $got = 'Sans' } }
        elseif ($prop -eq 'Radius') {
            foreach ($rk in @($script:DsRadii.Keys)) { if ([int]$act.RadCard -eq [int]$script:DsRadii[$rk][0] -and [int]$act.RadBtn -eq [int]$script:DsRadii[$rk][1]) { $got = [string]$rk } }
        }
        if ($got -ne $want) { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') (('etkin tasar' + [char]0x0131 + 'mda ') + $prop + ' = ' + $got + ', beklenen ' + $want) }
        if ((Get-ComboKey $ui.st_LookSel) -ne 'Ozel') { Add-SmokeError ('ayr' + [char]0x0131 + 'nt' + [char]0x0131 + '') (('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm listesi ' + [char]0x00D6 + 'zel g' + [char]0x00F6 + 'stermeli, g' + [char]0x00F6 + 'sterdi' + [char]0x011F + 'i: ') + (Get-ComboKey $ui.st_LookSel)) }
    }
    Test-SmokeDesign ([string]$script:DesignKey)
}

# Panodaki parcalarin gorunumu etkin tasarimla uyusuyor mu: grafik bicimi (alan / dalga / yok), parca gorunumu (cam pariltisi, ust cizgi)
function Test-SmokeBoardSkin {
    $spec = Get-ActiveDesign
    $gr = [string]$spec.Graph
    $skin = [string]$spec.Skin
    $bad = 0
    $metric = 0
    foreach ($t in @($script:BoardLayout)) {
        $v = $script:BoardViews[[string]$t.Id]
        if ($null -eq $v) { continue }
        $n = $v.N
        if ($n.ContainsKey('Gloss') -and ((Test-SmokeShown $n.Gloss) -ne ($skin -eq 'Glass'))) { $bad++ }
        if ($n.ContainsKey('Bar') -and ((Test-SmokeShown $n.Bar) -ne ($skin -eq 'Slate'))) { $bad++ }
        if ([string]$v.Kind -eq 'metric' -and $n.ContainsKey('Gr')) {
            $metric++
            if ((Test-SmokeShown $n.Gr) -ne ($gr -ne 'none')) { $bad++ }
            elseif ($gr -ne 'none') {
                if ((Test-SmokeShown $n.Ar) -ne ($gr -eq 'area')) { $bad++ }
                if ((Test-SmokeShown $n.Gd) -ne ($gr -eq 'scope')) { $bad++ }
            }
        }
    }
    if ($bad -gt 0) { Add-SmokeError 'pano' (('par' + [char]0x00E7 + 'a g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm' + [char]0x00FC + ' etkin tasar' + [char]0x0131 + 'mla uyu' + [char]0x015F + 'muyor (') + [string]$bad + ' fark; grafik ' + $gr + (', par' + [char]0x00E7 + 'a ') + $skin + ')') }
    Add-SmokeLine (('      pano g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm' + [char]0x00FC + ': grafik ') + $gr + (', par' + [char]0x00E7 + 'a ') + $skin + ', ' + [string]$metric + (' g' + [char]0x00F6 + 'sterge'))
}

# Ana ekran panosu. Mod: off = klasik durum panosu (ana ekran bicimi Klasik) | home = kilitli | edit = duzenleme acik | added / removed = duzenleme acik, parca sayisi degisti |
# reset = "hazir duzene don" sonrasi (sayfa sarti aranmaz; yalnizca duzen verisi denetlenir)
function Test-SmokeBoard([string]$Mode) {
    $spec = Get-ActiveDesign
    $page = [string]$script:UiState.Page
    if ($Mode -eq 'off') {
        if ($spec.Board -eq $true) { Add-SmokeError 'pano' (('ana ekran bi' + [char]0x00E7 + 'imi Klasik iken tasar' + [char]0x0131 + 'm ') + [string]$script:DesignKey + (' panoyu kullanmamal' + [char]0x0131 + 'yd' + [char]0x0131 + '')) }
        if ($page -ne 'panel') { Add-SmokeError 'pano' (('klasik ana ekranda durum panosu olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ', a' + [char]0x00E7 + '' + [char]0x0131 + 'k sayfa: ') + $page) }
        return
    }
    if ($Mode -eq 'reset') {
        $pre = Get-BoardPreset ([string]$spec.Preset)
        if ($script:Settings.BoardCustom -eq $true) { Add-SmokeError 'pano' ('haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zene d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + ' ama ' + [char]0x00F6 + 'zel d' + [char]0x00FC + 'zen i' + [char]0x015F + 'areti a' + [char]0x00E7 + '' + [char]0x0131 + 'k kald' + [char]0x0131 + '') }
        $act = Get-BoardActiveLayout
        if (@($act).Count -ne @($pre).Count) { Add-SmokeError 'pano' (('haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zende ') + [string]@($pre).Count + (' par' + [char]0x00E7 + 'a olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ', etkin d' + [char]0x00FC + 'zende ') + [string]@($act).Count) }
        if ($script:BoardBuilt -and @($script:BoardLayout).Count -ne @($pre).Count) { Add-SmokeError 'pano' ('panoda ' + [string]@($script:BoardLayout).Count + (' par' + [char]0x00E7 + 'a var, haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zende ') + [string]@($pre).Count) }
        Add-SmokeLine (('      pano s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + ': ') + [string]@($pre).Count + (' par' + [char]0x00E7 + 'a (') + [string]$spec.Preset + ')')
        return
    }
    if ($spec.Board -ne $true) { Add-SmokeError 'pano' (('ana ekran bi' + [char]0x00E7 + 'imi Klasik; ') + [string]$script:DesignKey + (' tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'nda pano beklenmiyordu')); return }
    if ($page -ne 'board') { Add-SmokeError 'pano' (('ana ekran pano olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ', a' + [char]0x00E7 + '' + [char]0x0131 + 'k sayfa: ') + $page); return }
    if (-not $script:BoardBuilt -or $null -eq $ui.bd_Canvas) { Add-SmokeError 'pano' ('pano kurulmad' + [char]0x0131 + ''); return }
    $script:Win.UpdateLayout()
    $lay = $script:BoardLayout
    $n = @($lay).Count
    if ($n -lt 1) { Add-SmokeError 'pano' ('panoda par' + [char]0x00E7 + 'a yok') }
    $bad = @(Get-BoardProblems $lay)
    if ($bad.Count -gt 0) { Add-SmokeError 'pano' (('d' + [char]0x00FC + 'zen sorunlar' + [char]0x0131 + ': ') + ($bad -join '; ')) }
    $vn = @($script:BoardViews.Keys).Count
    if ($vn -ne $n) { Add-SmokeError 'pano' (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm say' + [char]0x0131 + 's' + [char]0x0131 + ' ') + [string]$vn + (', par' + [char]0x00E7 + 'a say' + [char]0x0131 + 's' + [char]0x0131 + ' ') + [string]$n) }
    $cw = [double]$ui.bd_Canvas.Width
    if ([double]::IsNaN($cw) -or $cw -lt 1) { $cw = [double]$ui.bd_Canvas.ActualWidth }
    $ch = [double]$ui.bd_Canvas.Height
    if ([double]::IsNaN($ch) -or $ch -lt 1) { $ch = [double]$ui.bd_Canvas.ActualHeight }
    $out = 0
    $editBad = 0
    $edit = ($script:BoardEdit -eq $true)
    $wantEdit = (@('edit', 'added', 'removed') -contains $Mode)
    foreach ($t in $lay) {
        $v = $script:BoardViews[[string]$t.Id]
        if ($null -eq $v) { $out++; continue }
        $el = $v.Root
        $x = [System.Windows.Controls.Canvas]::GetLeft($el)
        $y = [System.Windows.Controls.Canvas]::GetTop($el)
        $w = [double]$el.Width
        $h = [double]$el.Height
        if ([double]::IsNaN($x) -or [double]::IsNaN($y) -or [double]::IsNaN($w) -or [double]::IsNaN($h)) { $out++ }
        elseif ($w -lt 20 -or $h -lt 20 -or $x -lt -0.5 -or $y -lt -0.5 -or ($x + $w) -gt ($cw + 1.0) -or ($y + $h) -gt ($ch + 1.0)) { $out++ }
        foreach ($nm in @('Veil', 'Del', 'Grip')) {
            if ((Test-SmokeShown $v.N[$nm]) -ne $wantEdit) { $editBad++ }
        }
    }
    if ($out -gt 0) { Add-SmokeError 'pano' ([string]$out + (' par' + [char]0x00E7 + 'a tuvalin d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda, boyutsuz ya da g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'ms' + [char]0x00FC + 'z')) }
    if ($edit -ne $wantEdit) { Add-SmokeError 'pano' (('d' + [char]0x00FC + 'zenleme kipi ') + [string]$edit + ', beklenen ' + [string]$wantEdit) }
    if ($editBad -gt 0) { Add-SmokeError 'pano' (('d' + [char]0x00FC + 'zenleme denetimleri (tutama' + [char]0x00E7 + ', silme, g' + [char]0x00F6 + 'lge) ') + [string]$editBad + (' par' + [char]0x00E7 + 'ada beklenen g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + 'kte de' + [char]0x011F + 'il')) }
    if ((Test-SmokeShown $ui.bd_BtnAdd) -ne $wantEdit) { Add-SmokeError 'pano' ('Par' + [char]0x00E7 + 'a ekle d' + [char]0x00FC + '' + [char]0x011F + 'mesinin g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' d' + [char]0x00FC + 'zenleme kipine uymuyor') }
    if ((Test-SmokeShown $ui.bd_BtnLayout) -ne $wantEdit) { Add-SmokeError 'pano' ('Haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen d' + [char]0x00FC + '' + [char]0x011F + 'mesinin g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' d' + [char]0x00FC + 'zenleme kipine uymuyor') }
    if ((Test-SmokeShown $ui.bd_BtnReset) -ne $wantEdit) { Add-SmokeError 'pano' ('Varsay' + [char]0x0131 + 'lan d' + [char]0x00FC + 'zen d' + [char]0x00FC + '' + [char]0x011F + 'mesinin g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'rl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' d' + [char]0x00FC + 'zenleme kipine uymuyor') }
    if ($Mode -eq 'added' -and $n -ne [int]$script:SmokeBoardN + 1) { Add-SmokeError 'pano' (('par' + [char]0x00E7 + 'a say' + [char]0x0131 + 's' + [char]0x0131 + ' ') + [string]$n + ', beklenen ' + [string]([int]$script:SmokeBoardN + 1)) }
    if ($Mode -eq 'removed' -and $n -ne [int]$script:SmokeBoardN) { Add-SmokeError 'pano' (('par' + [char]0x00E7 + 'a say' + [char]0x0131 + 's' + [char]0x0131 + ' ') + [string]$n + ', beklenen ' + [string]$script:SmokeBoardN) }
    Add-SmokeLine ('      pano (' + $Mode + '): ' + [string]$n + (' par' + [char]0x00E7 + 'a, tuval ') + [string][int]$cw + 'x' + [string][int]$ch + (' px, d' + [char]0x00FC + 'zenleme ') + [string]$edit)
    Test-SmokeBoardSkin
}

# Saydamlik. Spec: "Secenek|Opaklik" (opaklik * ise denetlenmez). Beklenen etkin mod, bu sistemde efektin nasil uygulanacagini hesaplayan islevden gelir.
function Test-SmokeGlass([string]$Spec) {
    $p = $Spec.Split('|')
    $want = [string]$p[0]
    $opS = [string]$p[1]
    $script:Win.UpdateLayout()
    if ([string]$script:Settings.Backdrop -ne $want) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('bellekteki efekt ' + [string]$script:Settings.Backdrop + ', beklenen ' + $want + (' (uygulanamay' + [char]0x0131 + 'p kapat' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' olabilir)')) }
    $cfg = $null
    try { $cfg = Get-Settings } catch { $cfg = $null }
    if ($null -ne $cfg -and [string]$cfg.Backdrop -ne $want) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('dosyadaki efekt ' + [string]$cfg.Backdrop + ', beklenen ' + $want) }
    if ($opS -ne '*') {
        $opn = [int]$opS
        if ((ConvertTo-GlassOpacity $script:Settings.WinOpacity) -ne $opn) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('bellekteki opakl' + [char]0x0131 + 'k %') + [string]$script:Settings.WinOpacity + ', beklenen %' + $opS) }
        if ($null -ne $cfg -and (ConvertTo-GlassOpacity $cfg.WinOpacity) -ne $opn) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('dosyadaki opakl' + [char]0x0131 + 'k %') + [string]$cfg.WinOpacity + ', beklenen %' + $opS) }
    }
    $theme = [string]$script:ThemeName
    $why = ''
    try { $why = [string](Get-GlassBlockWhy $theme) } catch { $why = '' }
    $plan = Get-GlassPlan $want (Get-OsBuildNumber) $why
    if ([string]$script:GlassPlan.Mode -ne [string]$plan.Mode) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('etkin mod ' + [string]$script:GlassPlan.Mode + ', beklenen ' + [string]$plan.Mode) }
    $ap = $script:GlassApplied
    $bg = $script:Win.Background
    $bgClear = (($bg -is [System.Windows.Media.SolidColorBrush]) -and ([int]$bg.Color.A -eq 0))
    $info = ''
    if ([string]$plan.Mode -eq 'Yok') {
        if ($null -ne $ap) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('efekt kapal' + [char]0x0131 + ' olmal' + [char]0x0131 + 'yd' + [char]0x0131 + ' ama pencerede etkin kald' + [char]0x0131 + '') }
        if ($bgClear) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('pencere arka plan' + [char]0x0131 + ' saydam kald' + [char]0x0131 + '') }
        if ([double]$script:GlassAlpha -lt 0.999) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('y' + [char]0x00FC + 'zeyler yar' + [char]0x0131 + ' saydam boyal' + [char]0x0131 + ' kald' + [char]0x0131 + '') }
        $info = ('uygulanm' + [char]0x0131 + 'yor')
        if ($why -ne '') { $info = $info + ' (' + $why + ')' }
    } else {
        if ($null -eq $ap) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('efekt pencereye uygulanmad' + [char]0x0131 + ' (') + [string]$script:GlassState.Detail + ')') }
        elseif ([string]$ap.Mode -ne [string]$plan.Mode) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('uygulanan mod ' + [string]$ap.Mode + ', beklenen ' + [string]$plan.Mode) }
        if (-not $script:GlassState.Ok) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('Windows efekti kabul etmedi: ' + [string]$script:GlassState.Detail) }
        if (-not $bgClear) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('pencere arka plan' + [char]0x0131 + ' saydam de' + [char]0x011F + 'il') }
        if ($opS -ne '*' -and [math]::Abs([double]$script:GlassAlpha - [double]$opS / 100.0) -gt 0.001) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('y' + [char]0x00FC + 'zey opakl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ') + [string]$script:GlassAlpha + ', beklenen ' + [string]([double]$opS / 100.0)) }
        $wc = $null
        try { $wc = [System.Windows.Shell.WindowChrome]::GetWindowChrome($script:Win) } catch { $wc = $null }
        if ($null -eq $wc -or [math]::Abs([double]$wc.GlassFrameThickness.Left + 1.0) -gt 0.01) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') ('cam ' + [char]0x00E7 + 'er' + [char]0x00E7 + 'eve istemci alan' + [char]0x0131 + 'na yay' + [char]0x0131 + 'lmad' + [char]0x0131 + '') }
        $info = [string]$plan.Mode + ' (' + [string]$plan.Api + ('), y' + [char]0x00FC + 'zey opakl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ') + [string]$script:GlassAlpha
        if ([string]$plan.Note -ne '') { $info = $info + ' - ' + [string]$plan.Note }
    }
    $badBr = @(Get-ThemeProblems $theme)
    if ($badBr.Count -gt 0) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('f' + [char]0x0131 + 'r' + [char]0x00E7 + 'a rengi beklenenle uyu' + [char]0x015F + 'muyor: ') + ($badBr -join ', ')) }
    if ([int]$script:GlassFail -gt 0) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('efekt uygulama hatas' + [char]0x0131 + ' say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + [string]$script:GlassFail) }
    Add-SmokeLine (('      saydaml' + [char]0x0131 + 'k ') + $want + ' / ' + $opS + ' / tema ' + $theme + ': ' + $info + (', yap' + [char]0x0131 + ' ') + [string](Get-OsBuildNumber))
}

# Hazir gorunum: tema, yerlesim, tasarim, yakinlastirma ve saydamlik birlikte uygulanmis mi; liste secimi hazir gorunumu gostermeli
function Test-SmokePreset([string]$Key) {
    $p = Get-LookPreset $Key
    $g = Get-PresetGlass $Key
    if ([string]$script:ThemeName -ne [string]$p.Theme) { Add-SmokeError ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm') ('tema ' + [string]$script:ThemeName + ', beklenen ' + [string]$p.Theme) }
    if ([string]$script:LayoutName -ne [string]$p.Layout) { Add-SmokeError ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm') (('yerle' + [char]0x015F + 'im ') + [string]$script:LayoutName + ', beklenen ' + [string]$p.Layout) }
    if ([string]$script:DesignKey -ne [string]$p.Design) { Add-SmokeError ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm') (('tasar' + [char]0x0131 + 'm ') + [string]$script:DesignKey + ', beklenen ' + [string]$p.Design) }
    if ((ConvertTo-ZoomPct $script:Settings.Zoom) -ne [int]$p.Zoom) { Add-SmokeError ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm') (('yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %') + [string]$script:Settings.Zoom + ', beklenen %' + [string]$p.Zoom) }
    if ([int]$script:ThemeFail -gt 0 -or [int]$script:LayoutFail -gt 0 -or [int]$script:DesignFail -gt 0) { Add-SmokeError ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm') (('uygulanamayan ad' + [char]0x0131 + 'm: tema ') + [string]$script:ThemeFail + (', yerle' + [char]0x015F + 'im ') + [string]$script:LayoutFail + (', tasar' + [char]0x0131 + 'm ') + [string]$script:DesignFail) }
    if ((Test-DesignOverridden $script:Settings)) { Add-SmokeError ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm') ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm uyguland' + [char]0x0131 + ' ama tasar' + [char]0x0131 + 'm ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' tasar' + [char]0x0131 + 'm' + [char]0x0131 + 'n kendi de' + [char]0x011F + 'erine d' + [char]0x00F6 + 'nmedi') }
    $lk = Get-ComboKey $ui.st_LookSel
    if ($lk -ne $Key) { Add-SmokeError ('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm') (('haz' + [char]0x0131 + 'r g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm listesinde ') + $lk + (' se' + [char]0x00E7 + 'ili, beklenen ') + $Key) }
    Test-SmokeDesign ([string]$p.Design)
    if ([string]$p.HomeMode -ne '') { Test-SmokeHome ([string]$p.HomeMode) }
    Test-SmokeGlass (([string]$g.Backdrop) + '|' + [string]$g.Opacity)
    Test-SmokeCombos
}

# ---------------- Ayarlar > Gorunum: acilir listeler ----------------
# Secim kutusunda gorunen yazi (sablonun {Binding [Name]} baglamasi calisiyorsa doludur). Liste ekranda degilse '' doner.
function Get-SmokeComboText($Combo) {
    try {
        if (-not $Combo.IsVisible) { return $null }
        $cp = $Combo.Template.FindName('Cp', $Combo)
        if ($null -eq $cp) { return $null }
        $stack = New-Object System.Collections.Stack
        $stack.Push($cp)
        $n = 0
        while ($stack.Count -gt 0 -and $n -lt 400) {
            $o = $stack.Pop()
            $n++
            if ($o -is [System.Windows.Controls.TextBlock]) { return [string]$o.Text }
            $cnt = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o)
            for ($k = $cnt - 1; $k -ge 0; $k--) { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $k)) }
        }
    } catch { }
    return ''
}

# Her listenin ayarlara gore beklenen secili anahtari: @(liste adi, anahtar)
function Get-SmokeComboPairs {
    $s = $script:Settings
    $pairs = New-Object System.Collections.ArrayList
    [void]$pairs.Add(@('st_ThemeSel', (ConvertTo-ThemeChoice ([string]$s.Theme))))
    [void]$pairs.Add(@('st_LayoutSel', (ConvertTo-LayoutKey ([string]$s.Layout))))
    [void]$pairs.Add(@('st_ZoomSel', [string](Get-NearestZoomStep (ConvertTo-ZoomPct $s.Zoom))))
    [void]$pairs.Add(@('st_TouchSel', (ConvertTo-TouchKey ([string]$s.TouchTargets))))
    [void]$pairs.Add(@('st_DesignSel', (ConvertTo-DesignKey ([string]$s.Design))))
    [void]$pairs.Add(@('st_HomeSel', (ConvertTo-HomeKey (Get-BoardField $s 'HomeMode'))))
    [void]$pairs.Add(@('st_BackdropSel', (ConvertTo-GlassKey ([string]$s.Backdrop))))
    [void]$pairs.Add(@('st_OpacitySel', [string](ConvertTo-GlassOpacity $s.WinOpacity)))
    foreach ($p in @($script:DsOptions.Keys)) {
        [void]$pairs.Add(@(('st_Ds' + [string]$p + 'Sel'), (ConvertTo-DsValue ([string]$p) (Get-BoardField $s ('Ds' + [string]$p)))))
    }
    [void]$pairs.Add(@('st_LookSel', (Get-MatchingLookPreset $s)))
    return $pairs.ToArray()
}

# Acilir listeler: ogeleri var, secili oge ayarlarla uyusuyor, secim kutusunda ogenin adi yaziyor
function Test-SmokeCombos {
    $script:Win.UpdateLayout()
    $texts = 0
    foreach ($pr in @(Get-SmokeComboPairs)) {
        $name = [string]$pr[0]
        $want = [string]$pr[1]
        $c = $ui[$name]
        if ($null -eq $c) { Add-SmokeError 'liste' (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r liste yok: ') + $name); continue }
        if ([int]$c.Items.Count -lt 2) { Add-SmokeError 'liste' ($name + ' listesinde ' + [string]$c.Items.Count + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e var')); continue }
        $got = Get-ComboKey $c
        if ($got -ne $want) { Add-SmokeError 'liste' ($name + ' listesinde ' + $got + (' se' + [char]0x00E7 + 'ili, ayara g' + [char]0x00F6 + 're beklenen ') + $want); continue }
        $txt = Get-SmokeComboText $c
        if ($null -ne $txt) {
            $texts++
            $exp = [string]$c.SelectedItem['Name']
            if ($txt -ne $exp) { Add-SmokeError 'liste' ($name + (' se' + [char]0x00E7 + 'im kutusunda "') + $txt + ('" yaz' + [char]0x0131 + 'yor, beklenen "') + $exp + '"') }
        }
    }
    Add-SmokeLine (('      a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r listeler tutarl' + [char]0x0131 + '; se' + [char]0x00E7 + 'im kutusu yaz' + [char]0x0131 + 's' + [char]0x0131 + ' denetlenen: ') + [string]$texts)
}

# Acik bir listenin acilan penceresi: gercekten acik, ogeleri cizilmis ve ilk ogede yazi var
function Test-SmokeDropDown([string]$Name) {
    $c = $ui[$Name]
    if ($null -eq $c) { Add-SmokeError 'liste' (('a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r liste yok: ') + $Name); return }
    Invoke-SmokeFlush
    if (-not $c.IsDropDownOpen) { Add-SmokeError 'liste' ($Name + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + '')); return }
    $pop = $c.Template.FindName('PART_Popup', $c)
    if ($null -eq $pop -or -not $pop.IsOpen) { Add-SmokeError 'liste' ($Name + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'lan penceresi a' + [char]0x00E7 + '' + [char]0x0131 + 'k de' + [char]0x011F + 'il')); return }
    $first = $c.ItemContainerGenerator.ContainerFromIndex(0)
    if ($null -eq $first) { Add-SmokeError 'liste' ($Name + (' ' + [char]0x00F6 + '' + [char]0x011F + 'eleri ' + [char]0x00E7 + 'izilmedi')); return }
    $txt = $null
    $stack = New-Object System.Collections.Stack
    $stack.Push($first)
    $n = 0
    while ($stack.Count -gt 0 -and $n -lt 200 -and $null -eq $txt) {
        $o = $stack.Pop()
        $n++
        if ($o -is [System.Windows.Controls.TextBlock]) { $txt = [string]$o.Text; break }
        try {
            $cnt = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o)
            for ($k = $cnt - 1; $k -ge 0; $k--) { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $k)) }
        } catch { }
    }
    $exp = [string]$c.Items[0]['Name']
    if ($txt -ne $exp) { Add-SmokeError 'liste' ($Name + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'lan listede ilk ' + [char]0x00F6 + '' + [char]0x011F + 'e "') + [string]$txt + ('" yaz' + [char]0x0131 + 'yor, beklenen "') + $exp + '"') }
    else { Add-SmokeLine (('      a' + [char]0x00E7 + '' + [char]0x0131 + 'k liste ') + $Name + ': ' + [string]$c.Items.Count + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e, ilk ' + [char]0x00F6 + '' + [char]0x011F + 'e "') + $txt + '"') }
}

# Acik listenin bir ogesinden tekerlek olayi (once asagi, sonra yukari) yukseltilir: arkadaki sayfa kipirdamamali.
# Kisa liste ya da sinira gelmis liste olayi yutar; uzun liste kendi kaydirir. Sayfaya gecseydi kaydirma kaydi olusurdu.
function Test-SmokePopupWheel([string]$Name) {
    $c = $ui[$Name]
    if ($null -eq $c -or -not $c.IsDropDownOpen) { Add-SmokeError ('liste tekerle' + [char]0x011F + 'i') ($Name + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'k de' + [char]0x011F + 'il')); return }
    $first = $c.ItemContainerGenerator.ContainerFromIndex(0)
    if ($null -eq $first) { Add-SmokeError ('liste tekerle' + [char]0x011F + 'i') ($Name + (' ' + [char]0x00F6 + '' + [char]0x011F + 'eleri ' + [char]0x00E7 + 'izilmedi')); return }
    if ($null -eq (Get-ComboOfPopupSource $first)) { Add-SmokeError ('liste tekerle' + [char]0x011F + 'i') ($Name + (': ' + [char]0x00F6 + '' + [char]0x011F + 'e a' + [char]0x00E7 + '' + [char]0x0131 + 'lan pencerenin i' + [char]0x00E7 + 'inde say' + [char]0x0131 + 'lmad' + [char]0x0131 + '')); return }
    $sv = Get-PageScroller 0
    Stop-SmoothScroll
    $before = -1.0
    if ($null -ne $sv) { $before = [double]$sv.VerticalOffset }
    # Listenin kendi kaydiricisi o yonde kaydirabiliyorsa olay WPF'e birakilir; kaydiramiyorsa uygulama olayi yutmalidir
    $mustSwallow = New-Object System.Collections.ArrayList
    foreach ($dir in @(1, -1)) { [void]$mustSwallow.Add(-not ((Find-ScrollerFrom $first $dir) -is [string])) }
    $handled = New-Object System.Collections.ArrayList
    foreach ($delta in @(-360, 360)) {
        $ev = New-Object System.Windows.Input.MouseWheelEventArgs -ArgumentList ([System.Windows.Input.Mouse]::PrimaryDevice), ([Environment]::TickCount), $delta
        $ev.RoutedEvent = [System.Windows.UIElement]::PreviewMouseWheelEvent
        $first.RaiseEvent($ev)
        [void]$handled.Add([string]$ev.Handled)
    }
    $after = $before
    if ($null -ne $sv) { $after = [double]$sv.VerticalOffset }
    $bad = $false
    for ($i = 0; $i -lt 2; $i++) {
        if ($mustSwallow[$i] -and $handled[$i] -ne 'True') { $bad = $true; Add-SmokeError ('liste tekerle' + [char]0x011F + 'i') ($Name + (': liste kayd' + [char]0x0131 + 'r' + [char]0x0131 + 'lam' + [char]0x0131 + 'yorken tekerlek olay' + [char]0x0131 + ' yutulmad' + [char]0x0131 + ' (') + @(('a' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + ''), ('yukar' + [char]0x0131 + ''))[$i] + ')') }
    }
    if ($script:SmoothMap.Count -gt 0) { $bad = $true; Stop-SmoothScroll; Add-SmokeError ('liste tekerle' + [char]0x011F + 'i') ($Name + (': tekerlek arkadaki sayfay' + [char]0x0131 + ' kayd' + [char]0x0131 + 'rmaya ba' + [char]0x015F + 'lad' + [char]0x0131 + '')) }
    elseif ([math]::Abs($after - $before) -gt 0.5) { $bad = $true; Add-SmokeError ('liste tekerle' + [char]0x011F + 'i') ($Name + (': arkadaki sayfa kayd' + [char]0x0131 + ' (') + [string][int]$before + ' -> ' + [string][int]$after + ' px)') }
    if (-not $bad) { Add-SmokeLine (('      liste tekerle' + [char]0x011F + 'i ') + $Name + (': sayfa k' + [char]0x0131 + 'p' + [char]0x0131 + 'rdamad' + [char]0x0131 + ' (') + [string][int]$after + ' px), olay yutuldu: ' + ($handled -join ' / ') + (', yutulmas' + [char]0x0131 + ' gereken: ') + ($mustSwallow -join ' / ')) }
}

# Onay kutusu olarak isaretlenebilen denetimler (yalnizca bir paneli acip kapatir)
$script:SmokeSafeCheck = @('st_DsAdv')

# Invoke-SmokeStep bilinmeyen adim turlerini buraya yollar. Bu adimlar yeniden denenmez: ciktisi atilir, boylece sizan bir deger donguye yol acamaz.
function Invoke-SmokeStepLook($St) {
    $arg = [string]$St.Arg
    switch ([string]$St.Kind) {
        'Design' {
            $r = @(Select-Design $arg)
            if (-not ($r.Count -gt 0 -and $r[$r.Count - 1] -eq $true)) { Add-SmokeError ('tasar' + [char]0x0131 + 'm') (('tasar' + [char]0x0131 + 'm uygulanamad' + [char]0x0131 + ': ') + $arg) }
            # Select-* yalnizca uygular; kaydetmeyi Ayarlar sayfasi yapar. Baslangic durumu dosyaya da yazilir (kopyalanan gercek ayar baska bir durumda olabilir)
            try { Save-Settings $script:Settings } catch { }
        }
        'Touch' {
            # kullanicinin ayari yerine gecici deneme degeri (duman testi kopya ayar klasorunde calisir); Set-TouchTargets kaynaklari gunceller
            $script:Settings.TouchTargets = ConvertTo-TouchKey $arg
            Set-TouchTargets
            try { Save-Settings $script:Settings } catch { }
        }
        'Glass' {
            $gp = $arg.Split('|')
            $r = @(Select-Glass ([string]$gp[0]) ([int]$gp[1]))
            if (-not ($r.Count -gt 0 -and $r[$r.Count - 1] -eq $true)) { Add-SmokeError ('saydaml' + [char]0x0131 + 'k') (('saydaml' + [char]0x0131 + 'k uygulanamad' + [char]0x0131 + ': ') + $arg) }
            try { Save-Settings $script:Settings } catch { }
        }
        'HomeSet' {
            # Spec: "AnaEkran|Nav|Radius|Font|Graph|Skin" (baslangic ve bitis durumunu kurmak icin; ayar kopyasina yazilir)
            $hp = $arg.Split('|')
            $script:Settings.HomeMode = ConvertTo-HomeKey ([string]$hp[0])
            $hi = 1
            foreach ($dp in @($script:DsOptions.Keys)) { $script:Settings[('Ds' + [string]$dp)] = ConvertTo-DsValue ([string]$dp) ([string]$hp[$hi]); $hi++ }
            Set-AppDesign $script:DesignKey
            Save-Settings $script:Settings
            try { Load-StDesign } catch { }
        }
        'HomeCheck' { Test-SmokeHome $arg }
        'OverrideCheck' { Test-SmokeOverride $arg }
        'ComboCheck' { Test-SmokeCombos }
        'DropDownCheck' { Test-SmokeDropDown $arg }
        'PopupWheel' { Test-SmokePopupWheel $arg }
        'Check' {
            $cp = $arg.Split('|')
            $c = $ui[[string]$cp[0]]
            if ($script:SmokeSafeCheck -notcontains [string]$cp[0]) { Add-SmokeError 'onay kutusu' (('g' + [char]0x00FC + 'venli onay kutusu k' + [char]0x00FC + 'mesinde de' + [char]0x011F + 'il, i' + [char]0x015F + 'aretlenmedi: ') + [string]$cp[0]) }
            elseif ($null -eq $c) { Add-SmokeError 'onay kutusu' ('onay kutusu yok: ' + [string]$cp[0]) }
            else { $c.IsChecked = ([string]$cp[1] -eq 'on') }
        }
        'Reveal' {
            $c = $ui[$arg]
            if ($null -eq $c) { Add-SmokeError 'liste' ('denetim yok: ' + $arg) }
            else { $c.BringIntoView(); Invoke-SmokeFlush }
        }
        'GlassCheck' { Test-SmokeGlass $arg }
        'GlassVisible' { Test-SmokeGlassVisible $arg }
        'DesignCheck' { Test-SmokeDesign $arg }
        'Backdrop' { if ($arg -eq 'on') { Show-SmokeBackdrop } else { Remove-SmokeBackdrop } }
        'Drag' { Invoke-SmokeDrag $arg }
        'PresetCheck' { Test-SmokePreset $arg }
        'BoardCheck' { Test-SmokeBoard $arg }
        'Screen' { Save-SmokeScreen $arg }
        'NavMenu' {
            $spec = Get-ActiveDesign
            $nav = [string]$spec.Nav
            $script:Win.UpdateLayout()
            if ($nav -eq 'Hidden') {
                Invoke-MenuButton
                Test-SmokeNavPopup 5 ('gizli men' + [char]0x00FC + '')
                Close-NavMenu
            } elseif ($nav -eq 'Fly') {
                $fb = $null
                foreach ($x in @($script:FlyBtns)) { if ([string]$x.Tag -eq 'hiz') { $fb = $x } }
                if ($null -eq $fb) { Add-SmokeError ('men' + [char]0x00FC + '') ('simge men' + [char]0x00FC + 's' + [char]0x00FC + 'nde h' + [char]0x0131 + 'z grubu d' + [char]0x00FC + '' + [char]0x011F + 'mesi yok') }
                else {
                    $fb.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, $fb)))
                    Test-SmokeNavPopup 5 ('simge men' + [char]0x00FC + 's' + [char]0x00FC + ' alt men' + [char]0x00FC + 's' + [char]0x00FC + '')
                    Close-NavMenu
                }
            } elseif ($nav -eq 'Compact') {
                $w0 = [double]$ui.RailHost.ActualWidth
                Invoke-MenuButton
                $script:Win.UpdateLayout()
                $w1 = [double]$ui.RailHost.ActualWidth
                if ([math]::Abs($w1 - $w0) -lt 20) { Add-SmokeError ('men' + [char]0x00FC + '') (('men' + [char]0x00FC + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesi geni' + [char]0x015F + 'li' + [char]0x011F + 'i de' + [char]0x011F + 'i' + [char]0x015F + 'tirmedi (') + [string][int]$w0 + ' -> ' + [string][int]$w1 + ' px)') }
                Invoke-MenuButton
                $script:Win.UpdateLayout()
                $w2 = [double]$ui.RailHost.ActualWidth
                if ([math]::Abs($w2 - $w0) -gt 2) { Add-SmokeError ('men' + [char]0x00FC + '') (('men' + [char]0x00FC + ' eski geni' + [char]0x015F + 'li' + [char]0x011F + 'ine d' + [char]0x00F6 + 'nmedi (') + [string][int]$w0 + ' -> ' + [string][int]$w2 + ' px)') }
                else { Add-SmokeLine (('      daralan men' + [char]0x00FC + ': ') + [string][int]$w0 + ' <-> ' + [string][int]$w1 + ' px') }
            }
        }
        'BoardAdd' {
            $script:SmokeBoardN = @($script:BoardLayout).Count
            $r = @(Add-BoardWidget 'cta' 'health')
            if (-not ($r.Count -gt 0 -and $r[$r.Count - 1] -eq $true)) { Add-SmokeError 'pano' ('par' + [char]0x00E7 + 'a eklenemedi') }
            else {
                $script:SmokeBoardId = ''
                foreach ($t in $script:BoardLayout) { if ([string]$t.Type -eq 'cta' -and [string]$t.Arg -eq 'health') { $script:SmokeBoardId = [string]$t.Id } }
            }
        }
        'BoardRemove' {
            $id = [string]$script:SmokeBoardId
            $v = $null
            if ($id -ne '') { $v = $script:BoardViews[$id] }
            if ($null -eq $v) { Add-SmokeError 'pano' ('kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak par' + [char]0x00E7 + 'a bulunamad' + [char]0x0131 + ''); return $false }
            $del = $v.N['Del']
            $del.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, $del)))
        }
        'BoardLayoutMenu' {
            if ($script:BoardEdit -ne $true) { Add-SmokeError 'pano' ('haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen men' + [char]0x00FC + 's' + [char]0x00FC + ' d' + [char]0x00FC + 'zenleme kipi d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda denendi'); return $false }
            Show-BoardLayoutMenu
            Test-SmokeNavPopup (@($script:BoardPresetInfo.Keys).Count + 1) ('haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen men' + [char]0x00FC + 's' + [char]0x00FC + '')
            Close-NavMenu
        }
        'BoardPreset' {
            $r = @(Select-BoardPreset $arg)
            if (-not ($r.Count -gt 0 -and $r[$r.Count - 1] -eq $true)) { Add-SmokeError 'pano' (('haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen uygulanamad' + [char]0x0131 + ': ') + $arg) }
            else {
                $pre = Get-BoardPreset $arg
                if (@($script:BoardLayout).Count -ne @($pre).Count) { Add-SmokeError 'pano' (('haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zende ') + [string]@($pre).Count + (' par' + [char]0x00E7 + 'a var, panoda ') + [string]@($script:BoardLayout).Count) }
                if ($script:Settings.BoardCustom -ne $true) { Add-SmokeError 'pano' ('haz' + [char]0x0131 + 'r d' + [char]0x00FC + 'zen se' + [char]0x00E7 + 'ildi ama ' + [char]0x00F6 + 'zel d' + [char]0x00FC + 'zen i' + [char]0x015F + 'areti kapal' + [char]0x0131 + '') }
            }
        }
        'BoardReset' {
            Reset-BoardLayout
            Test-SmokeBoard 'reset'
        }
        default { Add-SmokeError 'duman' (('bilinmeyen ad' + [char]0x0131 + 'm t' + [char]0x00FC + 'r' + [char]0x00FC + ': ') + [string]$St.Kind) }
    }
    return $false
}


# ---------------- Kararlilik anahtarlari ----------------
# ==================================================================
#  AYARLAR > GORUNUM > KARARLILIK: guvenli cizim ve ekran karti izleme anahtarlari
#  SafeRender : pencere yalnizca yazilimla cizilir; ekran karti ve sicaklik izleme ile saydamlik kapali kalir.
#               Bir sonraki acilista etkin olur (cizim kipi pencere olusmadan once secilir).
#               Uygulama art arda iki kez beklenmedik bicimde kapanirsa kendiliginden acilir; buradan kapatilir.
#  MonGpu     : canli izlemede ekran karti (3B) yuku okunur; aninda etkin olur.
#  DebugLog   : yutulan hatalar da Kayitlar\ayrinti-GUN.txt dosyasina yazilir (Ayrintili hata gunlugu bolumu); aninda etkin olur, varsayilan kapali.
# ==================================================================
function Load-StSafe {
    $ui.st_SafeRender.IsChecked = ($script:Settings.SafeRender -eq $true)
    $ui.st_MonGpu.IsChecked = ($script:Settings.MonGpu -ne $false)
    $ui.st_DebugLog.IsChecked = ($script:Settings.DebugLog -eq $true)
}

function Save-StSafe {
    $s = $script:Settings
    $wantSafe = ($ui.st_SafeRender.IsChecked -eq $true)
    $wantGpu = ($ui.st_MonGpu.IsChecked -eq $true)
    $wantDbg = ($ui.st_DebugLog.IsChecked -eq $true)
    $oldDbg = ($s.DebugLog -eq $true)
    $s.DebugLog = $wantDbg
    $oldSafe = ($s.SafeRender -eq $true)
    $s.SafeRender = $wantSafe
    if ($oldSafe -ne $wantSafe) { if ($wantSafe) { $s.SafeRenderWhy = 'user' } else { $s.SafeRenderWhy = '' }; $s.CleanStreak = 0 }
    $s.MonGpu = $wantGpu
    # cokme sayaci yalnizca guvenli cizim elle kapatilinca sifirlanir (baska bir ayara tiklamak sayaci bozmaz)
    if ($oldSafe -and -not $wantSafe) { $s.CrashStreak = 0 }
    try { $sync.NoGpu = (-not $wantGpu) } catch { }
    if ($wantDbg -ne $oldDbg) {
        # -DebugLog ile acilan oturumda gunluk, anahtar kapali olsa da acik kalir
        try { Set-DebugLogState ($wantDbg -or $script:DebugLogArg) } catch { }
        if ($wantDbg) { Show-Toast ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' hata g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ': yutulan hatalar da Kay' + [char]0x0131 + 'tlar klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'ne yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') 'info' }
        else { Show-Toast ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' hata g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'info' }
    }
    if ($wantSafe -ne $oldSafe) {
        if ($wantSafe) { Show-Toast ('G' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim bir sonraki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta etkin olur.') 'info' }
        else { Show-Toast ('G' + [char]0x00FC + 'venli ' + [char]0x00E7 + 'izim kapat' + [char]0x0131 + 'ld' + [char]0x0131 + '; bir sonraki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta pencere ekran kart' + [char]0x0131 + 'yla ' + [char]0x00E7 + 'izilir.') 'info' }
    }
}

# ---------------- cozum merkezi sayfasi ----------------
# ==================================================================
#  COZUM MERKEZI SAYFASI
#  Sekmeler: Sorunlar (tara ve duzelt) . Diskler (sifreleme, saglik) . Kurtarma . Silme . Sorun gidericiler . Bilgisayarim . Hazirlik
#  Her islem once onizlenir, onayla calisir, gunluge yazilir. Hicbir islem Windows Update, Defender, Guvenlik Duvari ya da UAC'yi kapatmaz.
# ==================================================================
$script:SlTab = 'scan'
$script:SlDisks = $null
$script:SlLoading = $false
$script:SlPendingSteps = @()
$script:SlPendingTitle = ''

function Get-SlBr([string]$Status) {
    if ($Status -eq 'bad') { return 'BrBad' }
    if ($Status -eq 'warn') { return 'BrWarn' }
    if ($Status -eq 'ok') { return 'BrGood' }
    return 'BrInfo'
}

function Get-SlBarFor([string]$Tab) {
    switch ($Tab) {
        'scan'    { return @('sl_Scan', 'sl_ScanFull', 'sl_FixAll') }
        'disk'    { return @('sl_DiskRefresh') }
        'recover' { return @('sl_RcVol', 'sl_RcImg', 'sl_RcQuick', 'sl_RcDeep', 'sl_RcType', 'sl_RcDest', 'sl_RcRun', 'sl_RcAll', 'sl_RcNone') }
        'erase'   { return @('sl_ErFile', 'sl_ErFolder', 'sl_ErMethod', 'sl_ErVerify', 'sl_ErAfter', 'sl_ErRefresh') }
        'trouble' { return @() }
        'pc'      { return @('sl_PcRefresh', 'sl_PcCopy') }
        'prep'    { return @('sl_PrCheck', 'sl_PrFix') }
    }
    return @()
}

function Set-SlTab([string]$Tab) {
    if ($script:SlvTabs -notcontains $Tab) { $Tab = 'scan' }
    $script:SlTab = $Tab
    Show-OnlyBar 'sl' (Get-SlBarFor $Tab)
    if ($Tab -eq 'recover') { $ui.sl_RcFindRow.Visibility = $script:VisOn } else { $ui.sl_RcFindRow.Visibility = $script:VisOff }
    $ui.sl_Foot.Text = (Tr $(''))
    switch ($Tab) {
        'scan'    { Render-SlScan }
        'disk'    { Render-SlDisk }
        'recover' { Render-SlRecover }
        'erase'   { Render-SlErase }
        'trouble' { Render-SlTrouble }
        'pc'      { Render-SlPc }
        'prep'    { Render-SlPrep }
    }
}

# ---------------- Sorunlar: tara ve duzelt ----------------
function Render-SlScan {
    $ui.sl_List.Children.Clear()
    $h = $script:Health
    if ($null -eq $h) {
        Add-Note $ui.sl_List ('Hen' + [char]0x00FC + 'z tarama yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '. ' + [char]0x201C + 'Bilgisayar' + [char]0x0131 + ' tara' + [char]0x201D + ' sistemi yaln' + [char]0x0131 + 'zca okur, hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'eyi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez; bulunan sorunlar' + [char]0x0131 + 'n ' + [char]0x00E7 + 'o' + [char]0x011F + 'unu buradan d' + [char]0x00FC + 'zeltebilirsiniz.')
        return
    }
    $open = @($h.Findings | Where-Object { [string]$_.Status -ne 'ok' } | Sort-Object -Property @{ Expression = { [int]$_.Weight }; Descending = $true })
    if ($open.Count -eq 0) {
        Add-Note $ui.sl_List ('Taramada d' + [char]0x00FC + 'zeltilecek ya da dikkat edilecek bir ' + [char]0x015F + 'ey ' + [char]0x00E7 + '' + [char]0x0131 + 'kmad' + [char]0x0131 + '. Her ' + [char]0x015F + 'ey yolunda g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor.') 'good'
        $ui.sl_Foot.Text = (Tr $(('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ': ') + [string]$h.Score.All))
        return
    }
    $fixable = New-Object System.Collections.ArrayList
    $rest = New-Object System.Collections.ArrayList
    foreach ($f in $open) {
        $m = ''
        if ($null -ne $f.Fix) { $m = [string]$f.Fix.Mode }
        if ($m -eq 'Auto' -or $m -eq 'Click') { [void]$fixable.Add($f) } else { [void]$rest.Add($f) }
    }
    $groups = @(@{ T = ('D' + [char]0x00FC + 'zeltilebilir sorunlar'); L = $fixable.ToArray() }, @{ T = ('Bilgi ve elle yap' + [char]0x0131 + 'lacaklar'); L = $rest.ToArray() })
    $shown = 0
    foreach ($g in $groups) {
        if (@($g.L).Count -eq 0) { continue }
        Add-HeadRow $ui.sl_List ($g.T + ' (' + [string]@($g.L).Count + ')')
        foreach ($f in @($g.L)) {
            if ($shown -ge 80) { break }
            $shown++
            $fx = $null
            if ($null -ne $f.Fix -and ([string]$f.Fix.Mode -eq 'Auto' -or [string]$f.Fix.Mode -eq 'Click')) { $fx = $f.Fix }
            $ak = ''
            $albl = ''
            if ($null -ne $f.Action) { $ak = [string]$f.Action.Kind; if ($f.Action.ContainsKey('Label')) { $albl = [string]$f.Action.Label } }
            $b1 = ''
            $b2 = ''
            if ($null -ne $fx) {
                $b1 = ('D' + [char]0x00FC + 'zelt')
                if ($albl -ne '' -and $ak -ne 'Tweak' -and $ak -ne 'Run') { $b2 = $albl }
            } elseif ($albl -ne '') { $b1 = $albl }
            $det = [string]$f.Detail
            if ($det.Length -gt 300) { $det = $det.Substring(0, 297) + '...' }
            if ([string]$script:UiState.Mode -eq 'Expert') {
                $std = [string](Get-JsonProp $f 'Std')
                if ($std -ne '') { $det += "`r`nStandartlar: " + $std }
            }
            $data = @{ Id = [string]$f.Id; Title = [string]$f.Title; Fix = $fx; Mode = ''; Action = $f.Action }
            if ($null -ne $fx) { $data.Mode = [string]$fx.Mode }
            $row = New-ItemRow @{ Title = [string]$f.Title; Detail = $det; Tag = (Get-CatLabel ([string]$f.Cat)); BrCol = (Get-SlBr ([string]$f.Status)); Btn1 = $b1; Btn2 = $b2 } $data $false $false
            if ($b1 -ne '') { if ($null -ne $fx) { $row.FindName('Act').Add_Click($script:H_FixOne) } else { $row.FindName('Act').Add_Click($script:H_ScAct) } }
            if ($b2 -ne '') { $row.FindName('Act2').Add_Click($script:H_ScAct) }
            [void]$ui.sl_List.Children.Add($row)
        }
    }
    $ts = ''
    try { if ($script:HealthAt -gt [datetime]'2001-01-01') { $ts = ('  ' + [char]0x00B7 + '  tarama: ') + $script:HealthAt.ToString('HH:mm') } } catch { }
    $ui.sl_Foot.Text = (Tr $(('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ': ') + [string]$h.Score.All + $ts + ('  ' + [char]0x00B7 + '  D' + [char]0x00FC + 'zeltmeler Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'nabilir.')))
}

# Saglik taramasi bitince Update-HealthUi cagirir
function Update-SolveFromHealth {
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'scan') { Render-SlScan }
}

# ---------------- Diskler ----------------
function Load-SlDisk {
    if ($script:SlLoading -eq $true) { return }
    $script:SlLoading = $true
    $ok = Start-Async 'SlDisks' 'Job_SlvDisks' @{} {
        param($r)
        $script:SlLoading = $false
        if ($null -eq $r -or $r.Ok -ne $true) { $script:SlDisks = @{ Failed = $true } } else { $script:SlDisks = $r }
        if ([string]$script:UiState.Page -eq 'solve') {
            if ($script:SlTab -eq 'disk') { Render-SlDisk }
            elseif ($script:SlTab -eq 'recover') { Render-SlRecover }
            elseif ($script:SlTab -eq 'erase') { Render-SlErase }
        }
    } 'Diskler okunuyor' $false $true
    if (-not $ok) { $script:SlLoading = $false }
}

function Render-SlDisk {
    $ui.sl_List.Children.Clear()
    $d = $script:SlDisks
    if ($null -eq $d) { Set-ListNote $ui.sl_List 'Diskler okunuyor...'; Load-SlDisk; return }
    if ($d.Failed -eq $true) {
        Add-Note $ui.sl_List ('Disk bilgisi okunamad' + [char]0x0131 + '. Multimizer' + [char]0x2019 + '' + [char]0x0131 + ' y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rd' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zdan emin olun, sonra ' + [char]0x201C + 'Yenile' + [char]0x201D + 'ye bas' + [char]0x0131 + 'n.') 'warn'
        return
    }
    Add-Note $ui.sl_List ('Her s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'n ' + [char]0x015F + 'ifreleme durumu, dosya sistemi sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ve Windows' + [char]0x2019 + 'un disk hata kay' + [char]0x0131 + 'tlar' + [char]0x0131 + ' burada. ' + [char]0x015E + 'ifreleme bilgisayar' + [char]0x0131 + 'n' + [char]0x0131 + 'z ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'rsa ya da kaybolursa dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + ' korur; kurtarma anahtar' + [char]0x0131 + ' olmadan bir BIOS ya da donan' + [char]0x0131 + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'inden sonra verilere eri' + [char]0x015F + 'ilemeyebilir, bu y' + [char]0x00FC + 'zden anahtar bilgisayar' + [char]0x0131 + 'n d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda saklanmal' + [char]0x0131 + 'd' + [char]0x0131 + 'r.')
    if ($d.Sys.IsAdmin -ne $true) { Add-Note $ui.sl_List ('Multimizer y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'm' + [char]0x0131 + 'yor; ' + [char]0x015F + 'ifreleme durumu okunamayabilir ve i' + [char]0x015F + 'lemler yap' + [char]0x0131 + 'lamaz.') 'warn' }
    $n = 0
    foreach ($disk in @($d.Disks)) {
        foreach ($r in @($disk.Rows)) {
            if ([string]$r.Kind -eq 'head') { Add-HeadRow $ui.sl_List ([string]$r.Title); continue }
            $n++
            $b1 = ''; $b2 = ''
            if ([string]$r.Do -ne '') { $b1 = [string]$r.Label }
            if ([string]$r.Do2 -ne '') { $b2 = [string]$r.Label2 }
            $data = @{ Do = [string]$r.Do; Drive = [string]$disk.Drive; Method = [string]$disk.Plan.Method; IsOs = ($disk.Plan.IsOs -eq $true); Type = [string]$disk.Type; Scope = [string]$disk.Plan.Scope; Cipher = [string]$disk.Plan.Cipher }
            $row = New-ItemRow @{ Title = [string]$r.Title; Detail = [string]$r.Detail; BrCol = [string]$r.Br; Btn1 = $b1; Btn2 = $b2 } $data $false $false
            if ($b1 -ne '') {
                $row.FindName('Act').Add_Click($script:H_SlAct)
                [System.Windows.Automation.AutomationProperties]::SetName($row.FindName('Act'), (Tr $b1) + ', ' + (Tr ([string]$r.Title)) + ', ' + [string]$disk.Drive)
            }
            if ($b2 -ne '') {
                $data2 = @{ Do = [string]$r.Do2; Drive = [string]$disk.Drive; Method = [string]$disk.Plan.Method; IsOs = ($disk.Plan.IsOs -eq $true); Type = [string]$disk.Type; Scope = [string]$disk.Plan.Scope; Cipher = [string]$disk.Plan.Cipher }
                $a2 = $row.FindName('Act2')
                $a2.Tag = $data2
                [System.Windows.Automation.AutomationProperties]::SetName($a2, (Tr $b2) + ', ' + (Tr ([string]$r.Title)) + ', ' + [string]$disk.Drive)
                $a2.Add_Click($script:H_SlAct)
            }
            [void]$ui.sl_List.Children.Add($row)
        }
    }
    if ($n -eq 0) { Add-Note $ui.sl_List ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' bulunamad' + [char]0x0131 + '.') 'warn' }
    $ui.sl_Foot.Text = (Tr $(('Anahtarlar yaln' + [char]0x0131 + 'zca siz istedi' + [char]0x011F + 'inizde okunur ve g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'lmaz. Windows Update, Defender ve G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + '' + [char]0x2019 + 'na dokunulmaz.')))
}

$script:H_SlAct = { param($s, $e) Invoke-Safe { Invoke-SlAction $s.Tag } 'Eylem' }

function Invoke-SlAction($T) {
    $drive = [string]$T.Drive
    switch ([string]$T.Do) {
        'BlKey'    { & $script:H_BkBlKey ([pscustomobject]@{ Tag = @{ Drive = $drive } }) $null }
        'BlSave'   { & $script:H_BkBlSave ([pscustomobject]@{ Tag = @{ Drive = $drive } }) $null }
        'BlAddKey' { & $script:H_BkBlAdd ([pscustomobject]@{ Tag = @{ Drive = $drive } }) $null }
        'BlEnable' { Start-SlBlEnable $T }
        'BlSuspend' { Start-SlBlSimple 'Suspend' $drive }
        'BlLock'    { Start-SlBlSimple 'Lock' $drive }
        'BlDisable' { Start-SlBlSimple 'Disable' $drive }
        'BlAutoUnlock' { Start-SlBlSimple 'AutoUnlock' $drive }
        'BlResume' {
            [void](Start-Async 'Action' 'Job_Action' @{ Key = 'BlResume'; Drive = $drive } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('BitLocker korumas' + [char]0x0131 + ' s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '.') 'good' } else { Show-Toast ('Koruma s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'lemedi; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
                $script:SlDisks = $null
                if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'disk') { Render-SlDisk }
            } ('BitLocker korumas' + [char]0x0131 + ' s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'l' + [char]0x00FC + 'yor'))
        }
        'DiskScan'     { Start-SlDiskJob 'scan' $drive }
        'DiskOptimize' { Start-SlDiskJob 'optimize' $drive }
        'DiskRepair'   { Start-SlDiskRepair $drive ($T.IsOs -eq $true) }
        'Backup'       { Open-Page 'backup' }
    }
}

function Start-SlDiskJob([string]$Kind, [string]$Drive) {
    $lbl = $Drive + (' taran' + [char]0x0131 + 'yor (salt okunur)')
    if ($Kind -eq 'optimize') { $lbl = $Drive + (' iyile' + [char]0x015F + 'tiriliyor') }
    [void](Start-Async 'SlDiskOp' 'Job_SlvDiskOp' @{ Kind = $Kind; Drive = $Drive } {
        param($r)
        if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Disk i' + [char]0x015F + 'lemi tamamland' + [char]0x0131 + '; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'good' } else { Show-Toast ('Disk i' + [char]0x015F + 'lemi tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
    } $lbl)
}

function Start-SlDiskRepair([string]$Drive, [bool]$IsOs) {
    $step = @{ Id = 'chkdsk-' + $Drive.TrimEnd(':'); Title = $Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + ' onar'); Ops = @(@{ T = 'ChkdskRepair'; Drive = $Drive }); Reboot = $IsOs }
    $script:SlPendingSteps = @($step)
    $script:SlPendingTitle = $Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + ' onar')
    $txt = $Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'ndeki dosya sistemi hatalar' + [char]0x0131 + ' onar' + [char]0x0131 + 'l' + [char]0x0131 + 'r. Onar' + [char]0x0131 + 'm s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' k' + [char]0x0131 + 'sa s' + [char]0x00FC + 're kullan' + [char]0x0131 + 'lamaz yapabilir; ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an programlar' + [char]0x0131 + ' kapatman' + [char]0x0131 + 'z ' + [char]0x00F6 + 'nerilir.')
    if ($IsOs) { $txt += ("`r`n`r`nSistem s" + [char]0x00FC + "r" + [char]0x00FC + "c" + [char]0x00FC + "s" + [char]0x00FC + " yeniden ba" + [char]0x015F + "latmada onar" + [char]0x0131 + "l" + [char]0x0131 + "r.") }
    Show-Confirm ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' onar') $txt 'Onar' { Start-PlanJob $script:SlPendingSteps $script:SlPendingTitle $false $false { $script:SlDisks = $null } }
}

function Start-SlBlSimple([string]$Op, [string]$Drive) {
    $msg = ''
    $ok = ('Haz' + [char]0x0131 + 'r')
    if ($Op -eq 'Suspend') {
        $msg = $Drive + (' i' + [char]0x00E7 + 'in BitLocker korumas' + [char]0x0131 + ' bir sonraki yeniden ba' + [char]0x015F + 'latmaya kadar ask' + [char]0x0131 + 'ya al' + [char]0x0131 + 'n' + [char]0x0131 + 'r (BIOS ya da s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' g' + [char]0x00FC + 'ncellemesi ' + [char]0x00F6 + 'ncesi i' + [char]0x00E7 + 'in). Bu s' + [char]0x0131 + 'rada veriler anahtars' + [char]0x0131 + 'z okunabilir; yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'nca koruma kendili' + [char]0x011F + 'inden d' + [char]0x00F6 + 'ner.')
        $ok = ('Ask' + [char]0x0131 + 'ya al')
    } elseif ($Op -eq 'Lock') {
        $msg = $Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' kilitlenir. A' + [char]0x00E7 + 'mak i' + [char]0x00E7 + 'in parola ya da kurtarma anahtar' + [char]0x0131 + ' gerekir; anahtar' + [char]0x0131 + 'n elinizde oldu' + [char]0x011F + 'undan emin olun.')
        $ok = 'Kilitle'
    } elseif ($Op -eq 'Disable') {
        $msg = $Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + 'n ' + [char]0x015F + 'ifrelemesi kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r (' + [char]0x015F + 'ifre ' + [char]0x00E7 + '' + [char]0x00F6 + 'zme). Bundan sonra bilgisayar kaybolur ya da ' + [char]0x00E7 + 'al' + [char]0x0131 + 'n' + [char]0x0131 + 'rsa dosyalara herkes eri' + [char]0x015F + 'ebilir. ' + [char]0x0130 + '' + [char]0x015F + 'lem arka planda s' + [char]0x00FC + 'rer; s' + [char]0x00FC + 're s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' boyutuna ba' + [char]0x011F + 'l' + [char]0x0131 + 'd' + [char]0x0131 + 'r ve kapat' + [char]0x0131 + 'rsan' + [char]0x0131 + 'z kald' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' yerden devam eder.')
        $ok = ('' + [char]0x015E + 'ifrelemeyi kald' + [char]0x0131 + 'r')
    } elseif ($Op -eq 'AutoUnlock') {
        $msg = $Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ', sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden a' + [char]0x00E7 + '' + [char]0x0131 + 'lacak. S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' ba' + [char]0x015F + 'ka bir bilgisayara takt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda yine kurtarma anahtar' + [char]0x0131 + ' gerekir.')
        $ok = ('A' + [char]0x00E7 + '')
    }
    $script:SlBlPending = @{ Op = $Op; Drive = $Drive }
    Show-Confirm 'BitLocker' $msg $ok {
        [void](Start-Async 'BlOp' 'Job_BlOp' @{ Op = $script:SlBlPending.Op; Drive = $script:SlBlPending.Drive } {
            param($r)
            if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ([string]$r.Message) 'good' } else { $m = ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '.'); if ($null -ne $r -and [string]$r.Error -ne '') { $m = [string]$r.Error }; Show-Toast $m 'bad' }
            $script:SlDisks = $null
            if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'disk') { Render-SlDisk }
        } ('BitLocker i' + [char]0x015F + 'lemi'))
    }
}

function Start-SlBlEnable($T) {
    $drive = [string]$T.Drive
    if ([string]$T.Method -eq 'DeviceEncryption') {
        Open-Url 'ms-settings:deviceencryption'
        Show-Toast ('Cihaz ' + [char]0x015F + 'ifrelemesi sayfas' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '; oradan a' + [char]0x00E7 + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda kurtarma anahtar' + [char]0x0131 + ' Microsoft hesab' + [char]0x0131 + 'n' + [char]0x0131 + 'za kaydedilir.') 'info'
        return
    }
    $dir = Select-Folder (('Kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + 'n kaydedilece' + [char]0x011F + 'i klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (') + $drive + (' d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda: USB bellek ya da ba' + [char]0x015F + 'ka bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ')'))
    if ($dir -eq '') { return }
    $bad = Test-BlKeyDir $dir $drive
    if ($bad -ne '') { Show-Toast $bad 'warn'; return }
    $isOs = ($T.IsOs -eq $true)
    $cname = 'XTS-AES 256'
    if ([string]$T.Cipher -eq 'Aes256') { $cname = 'AES-256' }
    $txt = $drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' BitLocker ile ' + [char]0x015F + 'ifrelenecek (') + $cname + ', ' + (Get-BlScopeText ([string]$T.Scope)) + ').' + "`r`n`r`n" + ('' + [char]0x00D6 + 'nce 48 haneli kurtarma anahtar' + [char]0x0131 + ' olu' + [char]0x015F + 'turulup ' + [char]0x015F + 'u klas' + [char]0x00F6 + 're kaydedilir ve dosya do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r: ') + $dir + "`r`n`r`n" + ('Dosya do' + [char]0x011F + 'rulanamazsa hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey ' + [char]0x015F + 'ifrelenmez.')
    if ($isOs) { $txt += "`r`n`r`n" + ('Sistem diskinde ' + [char]0x015F + 'ifreleme bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'nca ba' + [char]0x015F + 'lar; o zamana kadar hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'mez. ' + [char]0x015E + 'ifreleme s' + [char]0x00FC + 'rerken bilgisayar' + [char]0x0131 + ' kullanabilirsiniz.') }
    else { $txt += "`r`n`r`n" + ('' + [char]0x015E + 'ifreleme hemen ba' + [char]0x015F + 'lar ve arka planda s' + [char]0x00FC + 'rer; bilgisayar' + [char]0x0131 + ' kullanabilirsiniz.') }
    $script:SlBlPending = @{ Op = 'Enable'; Drive = $drive; KeyDir = $dir; IsOs = $isOs }
    Show-Confirm ('' + [char]0x015E + 'ifrelemeyi ba' + [char]0x015F + 'lat') $txt ('Ba' + [char]0x015F + 'lat') {
        [void](Start-Async 'BlOp' 'Job_BlOp' @{ Op = 'Enable'; Drive = $script:SlBlPending.Drive; KeyDir = $script:SlBlPending.KeyDir } {
            param($r)
            $script:SlDisks = $null
            if ($null -ne $r -and $r.Ok -eq $true) {
                Show-Toast ([string]$r.Message) 'good'
                if ($r.NeedsReboot -eq $true) { Request-Reboot }
            } else {
                $m = ('' + [char]0x015E + 'ifreleme ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '.')
                if ($null -ne $r -and [string]$r.Error -ne '') { $m = [string]$r.Error }
                Show-Toast $m 'bad'
            }
            if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'disk') { Render-SlDisk }
        } ('BitLocker ' + [char]0x015F + 'ifrelemesi haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor'))
    }
}

# ---------------- Sorun gidericiler ----------------
function Render-SlTrouble {
    $ui.sl_List.Children.Clear()
    Add-Note $ui.sl_List ('Belirtiyi bulun; Multimizer ilgili hizmetleri ve ' + [char]0x00F6 + 'nbellekleri onar' + [char]0x0131 + 'r. Her i' + [char]0x015F + 'lem ' + [char]0x00F6 + 'nce ' + [char]0x00F6 + 'nizlenir, onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r ve Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r. Ki' + [char]0x015F + 'isel dosyalara dokunulmaz.')
    foreach ($s in @($script:SlvSymptoms)) {
        $hasSteps = (@($s.Steps).Count -gt 0)
        $det = [string]$s.D
        if ($s.Reboot -eq $true) { $det += (' Etkili olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'latma gerekir.') }
        $b1 = ('Bilgisayar' + [char]0x0131 + ' tara'); $b2 = ''
        if ($hasSteps) { $b1 = ('' + [char]0x00D6 + 'nizle'); $b2 = ('D' + [char]0x00FC + 'zelt') }
        $row = New-ItemRow @{ Title = [string]$s.T; Detail = $det; BrCol = 'BrInfo'; Btn1 = $b1; Btn2 = $b2 } @{ Do = 'TrPreview'; Key = [string]$s.K } $false $false
        $a1 = $row.FindName('Act')
        if (-not $hasSteps) { $a1.Tag = @{ Do = 'TrScan'; Key = [string]$s.K } }
        $a1.Add_Click($script:H_SlAct2)
        if ($hasSteps) {
            $a2 = $row.FindName('Act2')
            $a2.Tag = @{ Do = 'TrRun'; Key = [string]$s.K }
            $a2.Add_Click($script:H_SlAct2)
        }
        [void]$ui.sl_List.Children.Add($row)
        foreach ($g in @($s.Guided)) {
            $data = @{ Do = 'Go'; Page = [string]$g.Page; Sub = [string]$g.Sub; Url = [string]$g.Url }
            $gr = New-ItemRow @{ Title = (('      ' + [char]0x2192 + '  ') + [string]$g.Label); Detail = ''; BrCol = 'BrFaint'; Btn1 = ('A' + [char]0x00E7 + '') } $data $false $false
            $gr.FindName('Act').Add_Click($script:H_SlAct2)
            [void]$ui.sl_List.Children.Add($gr)
        }
    }
    $ui.sl_Foot.Text = (Tr $(('D' + [char]0x00FC + 'zelt' + [char]0x2019 + 'e bas' + [char]0x0131 + 'nca ' + [char]0x00F6 + 'nce neler yap' + [char]0x0131 + 'laca' + [char]0x011F + '' + [char]0x0131 + ' yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r; siz onaylamadan hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'maz.')))
}

$script:H_SlAct2 = { param($s, $e) Invoke-Safe { Invoke-SlAction2 $s.Tag } 'Eylem' }

function Invoke-SlAction2($T) {
    switch ([string]$T.Do) {
        'TrPreview' { Start-SlTrouble ([string]$T.Key) $true }
        'TrRun'     { Start-SlTrouble ([string]$T.Key) $false }
        'TrScan'    { if (-not (Select-TabChip 'sl' 'scan')) { Set-SlTab 'scan' }; Start-HealthScan 'Quick' $false }
        'Go' {
            if ([string]$T.Url -ne '') { Open-Url ([string]$T.Url) }
            elseif ([string]$T.Page -ne '') { Open-Page ([string]$T.Page) ([string]$T.Sub) }
        }
    }
}

function Start-SlTrouble([string]$Key, [bool]$Preview) {
    $s = Get-SlvSymptom $Key
    if ($null -eq $s) { return }
    $steps = Get-SlvTroubleSteps $Key
    if (@($steps).Count -eq 0) { return }
    $title = [string]$s.T
    if ($Preview) { Start-PlanJob $steps $title $true $false; return }
    $script:SlPendingSteps = @($steps)
    $script:SlPendingTitle = $title
    $lines = @($steps | ForEach-Object { ('' + [char]0x2022 + '  ') + [string]$_.Title })
    $txt = [string]$s.D + "`r`n`r`n" + ('Yap' + [char]0x0131 + 'lacaklar:') + "`r`n" + ($lines -join "`r`n")
    Show-Confirm 'Sorunu gider' $txt ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r') { Start-PlanJob $script:SlPendingSteps $script:SlPendingTitle $false $false }
}

# ---------------- sayfa kurulumu ----------------
function Init-Page_solve {
    Register-Tabs 'sl' $script:SlvTabs { param($s, $e) Invoke-Safe { Set-SlTab ([string]$s.Tag) } 'Sekme' }
    $ui.sl_Scan.Add_Click({ Invoke-Safe { Start-HealthScan 'Quick' $false } 'Tara' })
    $ui.sl_ScanFull.Add_Click({ Invoke-Safe { Start-HealthScan 'Full' $false } 'Tam denetim' })
    $ui.sl_FixAll.Add_Click({ Invoke-Safe { Start-FixAll } ('D' + [char]0x00FC + 'zelt') })
    $ui.sl_DiskRefresh.Add_Click({ Invoke-Safe { $script:SlDisks = $null; Render-SlDisk } 'Yenile' })
    Init-SlRecover
    Init-SlErase
    Init-SlPc
    Init-SlPrep
}

function Select-Sub_solve([string]$Sub) {
    if (-not (Select-TabChip 'sl' $Sub)) { Set-SlTab $Sub }
}

function Show-Page_solve {
    $t = Get-TabKey 'sl' $script:SlvTabs 'scan'
    Set-SlTab $t
}

# ---------------- cozum merkezi: silinen dosyalar sekmesi ----------------
# ==================================================================
#  COZUM MERKEZI: "Silinen dosyalar" sekmesi
#  Surucuyu ya da disk imajini yalnizca okur; bulunan dosyalari taranandan FARKLI bir surucuye, yeni bir klasore kaydeder.
#  Tarama ve kurtarma isleri "Kurtarma" eklentisindedir (Job_RecoverScan, Job_RecoverFiles); bu dosya arayuzu ve saf yardimcilari icerir.
# ==================================================================
$script:RcSelKey = ''
$script:RcSource = ''
$script:RcSourceKind = ''
$script:RcPart = 0
$script:RcImage = ''
$script:RcImageParts = 1
$script:RcDisk = -1
$script:RcPartCache = @{}
$script:RcPartPend = ''
$script:RcItems = @()
$script:RcMeta = $null
$script:RcScanError = ''
$script:RcGroup = 'all'
$script:RcDest = ''
$script:RcLastRun = $null
$script:RcLoading = $false
$script:RcFindTimer = $null
$script:RcRowCap = 300
$script:RcMaxResults = 20000
$script:RcPendItems = @()
$script:RcPendSource = ''
$script:RcPendPart = 0
$script:RcPendDest = ''
$script:RcPendMode = ''
$script:RcGroupNames = [ordered]@{ all = ('T' + [char]0x00FC + 'm' + [char]0x00FC + ''); img = 'Resimler'; doc = 'Belgeler'; media = 'Ses ve video'; arch = ('Ar' + [char]0x015F + 'ivler'); other = ('Di' + [char]0x011F + 'er') }

# ---------------- saf yardimcilar (arayuzden bagimsiz, testlenir) ----------------
function Get-RcExtTable {
    $defs = @(
        @{ G = 'img'; E = 'jpg jpeg jpe png gif bmp webp heic heif tif tiff ico svg psd raw cr2 cr3 nef arw dng orf rw2' },
        @{ G = 'doc'; E = 'pdf doc docx dot dotx xls xlsx xlsm ppt pptx odt ods odp txt rtf csv md epub xml html htm json msg eml pst one' },
        @{ G = 'media'; E = 'mp4 m4v avi mkv mov wmv flv webm mpg mpeg 3gp mp3 wav flac aac ogg m4a wma opus' },
        @{ G = 'arch'; E = 'zip rar 7z gz tgz tar bz2 xz cab iso apk jar' }
    )
    $t = @{}
    foreach ($d in $defs) {
        foreach ($x in ([string]$d.E).Split(' ')) { if ($x -ne '') { $t[$x] = [string]$d.G } }
    }
    return $t
}
$script:RcExtGroup = Get-RcExtTable

# Dosya uzantisinin tur grubu: img | doc | media | arch | other
function Get-RcGroup([string]$Ext) {
    $e = ([string]$Ext).Trim().TrimStart('.').ToLowerInvariant()
    $g = $script:RcExtGroup[$e]
    if ($null -eq $g) { return 'other' }
    return [string]$g
}

# Listelenebilir (sansi sifirdan buyuk) dosyalarin tur grubuna gore sayisi
function Get-RcGroupCounts($Items) {
    $c = @{ all = 0; img = 0; doc = 0; media = 0; arch = 0; other = 0 }
    foreach ($it in @($Items)) {
        if ($null -eq $it -or [int]$it.Chance -le 0) { continue }
        $c.all++
        $g = $script:RcExtGroup[([string]$it.Ext).Trim().TrimStart('.').ToLowerInvariant()]
        if ($null -eq $g) { $g = 'other' }
        $c[[string]$g]++
    }
    return $c
}

function Format-RcChance([int]$Chance) {
    $w = ('d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'k')
    if ($Chance -ge 90) { $w = ('' + [char]0x00E7 + 'ok y' + [char]0x00FC + 'ksek') } elseif ($Chance -ge 70) { $w = ('y' + [char]0x00FC + 'ksek') } elseif ($Chance -ge 40) { $w = 'orta' }
    return ('%' + [string]$Chance + ('  ' + [char]0x00B7 + '  ') + $w)
}

function Get-RcChanceBr([int]$Chance) {
    if ($Chance -ge 70) { return 'BrGood' }
    if ($Chance -ge 40) { return 'BrWarn' }
    return 'BrBad'
}

# FILETIME (UTC) -> yerel saat; gecersizse $null
function ConvertFrom-RcTime($Ft) {
    try {
        $v = [long]$Ft
        if ($v -le 0) { return $null }
        $d = [System.DateTime]::FromFileTimeUtc($v)
        if ($d.Year -lt 1990 -or $d.Year -gt 2100) { return $null }
        return $d.ToLocalTime()
    } catch { return $null }
}

function Format-RcDate($Ft) {
    $d = ConvertFrom-RcTime $Ft
    if ($null -eq $d) { return '' }
    return $d.ToString('dd.MM.yyyy HH:mm')
}

# Ham dosya adlarindaki denetim karakterleri ve essiz vekil karakterler XAML'i bozar; ekranda "_" gosterilir
function Remove-RcControl([string]$Text) {
    if ($null -eq $Text -or $Text -eq '') { return '' }
    $t = [regex]::Replace($Text, '[\u0000-\u001F\u007F\uFFFE\uFFFF]', '_')
    return [regex]::Replace($t, '[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]', '_')
}

# Bulunan bir dosyanin satir metinleri: @{ Title; Detail; Tag; BrCol }
function New-RcRowModel($It) {
    $name = Remove-RcControl ([string]$It.Name)
    if ($name.Trim() -eq '') { $name = ('(ads' + [char]0x0131 + 'z)') }
    $parts = New-Object System.Collections.ArrayList
    if ([string]$It.Kind -eq 'carve') {
        [void]$parts.Add(('' + [char]0x0130 + 'mza taramas' + [char]0x0131 + 'yla bulundu'))
    } else {
        $p = Remove-RcControl ([string]$It.Path)
        if ($p -eq '') { $p = ('(s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'n k' + [char]0x00F6 + 'k' + [char]0x00FC + ')') }
        [void]$parts.Add($p)
    }
    [void]$parts.Add((Format-Size ([double]$It.Length)))
    $m = Format-RcDate $It.Modified
    if ($m -ne '') { [void]$parts.Add(('de' + [char]0x011F + 'i' + [char]0x015F + 'iklik ') + $m) }
    if ([string]$It.Kind -ne 'carve') {
        $dd = Format-RcDate $It.Deleted
        if ($dd -ne '') { [void]$parts.Add('silinme ' + $dd) }
    }
    $det = ($parts.ToArray() -join ('  ' + [char]0x00B7 + '  '))
    $note = Remove-RcControl ([string]$It.Note)
    if ($note -ne '') { $det += "`r`n" + $note }
    $ch = [int]$It.Chance
    return @{ Title = $name; Detail = $det; Tag = (Format-RcChance $ch); BrCol = (Get-RcChanceBr $ch) }
}

# Listelenecek dosyalar: tur ve arama suzgeci, sansa gore siralama, satir siniri.
# Donus: @{ Rows (Idx, Chance dizisi); Matched; Hidden; Total }  (Hidden: sansi sifir oldugu icin gizlenenler)
function Get-RcDisplay($Items, [string]$Group, [string]$Query, [int]$Cap) {
    $q = ([string]$Query).Trim()
    $list = New-Object System.Collections.ArrayList
    $hidden = 0
    $i = -1
    foreach ($it in @($Items)) {
        $i++
        if ($null -eq $it) { continue }
        if ([int]$it.Chance -le 0) { $hidden++; continue }
        if ($Group -ne 'all' -and $Group -ne '') {
            $g = $script:RcExtGroup[([string]$it.Ext).Trim().TrimStart('.').ToLowerInvariant()]
            if ($null -eq $g) { $g = 'other' }
            if ([string]$g -ne $Group) { continue }
        }
        if ($q -ne '') {
            $nm = [string]$it.Name
            $pt = [string]$it.Path
            if ($nm.IndexOf($q, [System.StringComparison]::OrdinalIgnoreCase) -lt 0 -and $pt.IndexOf($q, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        }
        [void]$list.Add([pscustomobject]@{ Idx = $i; Chance = [int]$it.Chance; Del = [long]$it.Deleted; Name = [string]$it.Name })
    }
    $matched = $list.Count
    $sorted = @($list.ToArray() | Sort-Object -Property @{ Expression = 'Chance'; Descending = $true }, @{ Expression = 'Del'; Descending = $true }, @{ Expression = 'Name'; Descending = $false })
    if ($Cap -gt 0 -and $sorted.Count -gt $Cap) { $sorted = @($sorted | Select-Object -First $Cap) }
    return @{ Rows = $sorted; Matched = $matched; Hidden = $hidden; Total = ($i + 1) }
}

# Surucu secicideki satir metni
function Get-RcVolumeName($D, [string]$OsDrive) {
    $parts = New-Object System.Collections.ArrayList
    $head = [string]$D.Drive
    $lbl = ([string]$D.Label).Trim()
    if ($lbl -ne '') { $head += '  ' + $lbl }
    [void]$parts.Add($head)
    $fs = ([string]$D.Fs).Trim()
    if ($fs -eq '') { $fs = 'dosya sistemi yok' }
    [void]$parts.Add($fs)
    if ([double]$D.Size -gt 0) { [void]$parts.Add((Format-Size ([double]$D.Size))) }
    if ([string]$D.Bus -eq 'USB') { [void]$parts.Add('USB') }
    elseif ([string]$D.Media -eq 'SSD' -or [string]$D.Media -eq 'HDD') { [void]$parts.Add([string]$D.Media) }
    if ([string]$D.Drive -eq $OsDrive) { [void]$parts.Add('Windows') }
    if ([string]$D.State -eq 'locked') { [void]$parts.Add('kilitli') }
    return ($parts.ToArray() -join ('  ' + [char]0x00B7 + '  '))
}

# Fiziksel diskin secici satirindaki adi: "Disk 2  SanDisk Ultra  .  29,8 GB  .  USB"
function Get-RcDiskName($Dk) {
    $head = 'Disk ' + [string]$Dk.Number
    $nm = ([string]$Dk.Name).Trim()
    if ($nm -ne '') { $head += '  ' + $nm }
    $parts = New-Object System.Collections.ArrayList
    [void]$parts.Add($head)
    if ([double]$Dk.Size -gt 0) { [void]$parts.Add((Format-Size ([double]$Dk.Size))) }
    if ([string]$Dk.Bus -eq 'USB') { [void]$parts.Add('USB') }
    elseif ([string]$Dk.Media -eq 'SSD' -or [string]$Dk.Media -eq 'HDD') { [void]$parts.Add([string]$Dk.Media) }
    if ($Dk.IsSystem -eq $true) { [void]$parts.Add('Windows') }
    return ($parts.ToArray() -join ('  ' + [char]0x00B7 + '  '))
}

# Bolumun dosya sistemi adi (sifreli bolumler acikca belirtilir)
function Get-RcFsText([string]$Fs) {
    $f = ([string]$Fs).Trim()
    if ($f -ceq 'BITLOCKER') { return ('BitLocker (' + [char]0x015F + 'ifreli)') }
    if ($f -ceq 'LUKS') { return ('LUKS (' + [char]0x015F + 'ifreli)') }
    if ($f -eq '') { return ('bi' + [char]0x00E7 + 'im tan' + [char]0x0131 + 'nmad' + [char]0x0131 + '') }
    return $f
}

# Bolumun secici satirindaki metni: "bolum 2/3  .  NTFS  .  50 GB  .  E:"
function Get-RcPartText($P, [int]$Count, [string]$Letter) {
    $t = ('b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ') + [string]([int]$P.Index + 1) + '/' + [string]$Count
    $t += ('  ' + [char]0x00B7 + '  ') + (Get-RcFsText ([string]$P.Fs))
    if ([double]$P.Length -gt 0) { $t += ('  ' + [char]0x00B7 + '  ') + (Format-Size ([double]$P.Length)) }
    if ($Letter -ne '') { $t += ('  ' + [char]0x00B7 + '  ') + $Letter }
    return $t
}

# Bolumun Windows'ta surucu harfi var mi? Baslangic konumuna gore eslestirilir; yoksa ''
function Get-RcPartLetter($Dk, $P) {
    if ($null -eq $Dk) { return '' }
    foreach ($wp in @($Dk.Parts)) {
        if ($null -eq $wp) { continue }
        if ([math]::Abs([double]$wp.Offset - [double]$P.Start) -lt 1 -and [string]$wp.Letter -ne '') { return [string]$wp.Letter }
    }
    return ''
}

function New-RcChoice([string]$Key, [string]$Name, [string]$Kind) {
    $c = New-Choice $Key $Name
    $c.Kind = $Kind
    $c.Locked = $false
    $c.Media = ''
    $c.Removable = $false
    $c.IsOs = $false
    $c.Loaded = $true
    $c.Whole = $false
    $c.DiskNo = -1
    $c.Letters = @()
    return $c
}

# Bir fiziksel diskin ya da imajin secici satirlari. Bolumler okunduysa her bolum ayri satirdir, ayrica "tum disk" satiri eklenir;
# okunmadiysa disk icin tek satir doner (Loaded = $false) ve secilince bolumler okunur.
# $KeyBase: 'PD:2' ya da 'IMG'; $Cache: Job_RecoverParts sonucu ($null = okunmadi); $Dk: fiziksel disk bilgisi ($null = imaj); $KnownParts: imajda bilinen bolum sayisi
function Add-RcSourceChoices($Out, [string]$Kind, [string]$Title, [string]$KeyBase, $Cache, $Dk, [int]$KnownParts) {
    $isDisk = ($Kind -eq 'Disk')
    $loaded = ($null -ne $Cache -and $Cache.Ok -eq $true)
    $dn = -1
    $letters = @()
    $media = ''
    $isOs = $false
    $removable = $false
    if ($isDisk -and $null -ne $Dk) {
        $dn = [int]$Dk.Number
        $letters = @($Dk.Letters)
        $isOs = ($Dk.IsSystem -eq $true)
        $removable = ([string]$Dk.Bus -eq 'USB')
        $media = [string]$Dk.Media
    }
    if (-not $loaded) {
        if ($isDisk -or $KnownParts -le 1) {
            $name = $Title
            if ($isDisk) {
                if ($null -ne $Cache -and [string]$Cache.Error -ne '') { $name += ('  ' + [char]0x00B7 + '  b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler okunamad' + [char]0x0131 + '') } else { $name += ('  ' + [char]0x00B7 + '  b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mleri okumak i' + [char]0x00E7 + 'in se' + [char]0x00E7 + 'in') }
            }
            $k = $KeyBase
            if (-not $isDisk) { $k = $KeyBase + ':0' }
            $c = New-RcChoice $k $name $Kind
            $c.Loaded = (-not $isDisk)
            $c.DiskNo = $dn; $c.Letters = $letters; $c.IsOs = $isOs; $c.Removable = $removable; $c.Media = $media
            [void]$Out.Add($c)
            return
        }
        for ($i = 0; $i -lt $KnownParts; $i++) {
            $c = New-RcChoice ($KeyBase + ':' + [string]$i) ($Title + ('  ' + [char]0x00B7 + '  b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ') + [string]($i + 1) + '/' + [string]$KnownParts) $Kind
            [void]$Out.Add($c)
        }
        return
    }
    $list = @($Cache.Parts)
    if ($list.Count -eq 0) {
        $c = New-RcChoice ($KeyBase + ':0') ($Title + ('  ' + [char]0x00B7 + '  b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm d' + [char]0x00FC + 'zeni ya da dosya sistemi tan' + [char]0x0131 + 'nmad' + [char]0x0131 + ' (t' + [char]0x00FC + 'm alan imza taramas' + [char]0x0131 + ')')) $Kind
        $c.DiskNo = $dn; $c.Letters = $letters; $c.IsOs = $isOs; $c.Removable = $removable; $c.Media = $media
        [void]$Out.Add($c)
        return
    }
    $single = ($list.Count -eq 1 -and [string]$list[0].Kind -eq 'birim')
    foreach ($p in $list) {
        $label = ''
        if ($single) {
            $label = (Get-RcFsText ([string]$p.Fs))
            if ([double]$p.Length -gt 0) { $label += ('  ' + [char]0x00B7 + '  ') + (Format-Size ([double]$p.Length)) }
        } else {
            $label = Get-RcPartText $p $list.Count (Get-RcPartLetter $Dk $p)
        }
        $c = New-RcChoice ($KeyBase + ':' + [string][int]$p.Index) ($Title + ('  ' + [char]0x00B7 + '  ') + $label) $Kind
        $c.Locked = ([string]$p.Fs -ceq 'BITLOCKER')
        $c.DiskNo = $dn; $c.Letters = $letters; $c.IsOs = $isOs; $c.Removable = $removable; $c.Media = $media
        [void]$Out.Add($c)
    }
    if (-not $single) {
        $c = New-RcChoice ($KeyBase + ':all') ($Title + ('  ' + [char]0x00B7 + '  t' + [char]0x00FC + 'm disk, b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mlere bakmadan (imza taramas' + [char]0x0131 + ')')) $Kind
        $c.Whole = $true
        $c.DiskNo = $dn; $c.Letters = $letters; $c.IsOs = $isOs; $c.Removable = $removable; $c.Media = $media
        [void]$Out.Add($c)
    }
}

# Surucu secicinin ogeleri (New-Choice biciminde; Kind, Locked, Media, Removable, IsOs, Loaded, Whole, DiskNo, Letters eklenir).
# $Phys: fiziksel diskler (Job_SlvDisks), $Cache: kaynak adi (PhysicalDrive2 ya da imaj yolu) -> Job_RecoverParts sonucu
function Get-RcVolumeChoices($Disks, [string]$OsDrive, [string]$Image, [int]$Parts, $Phys = $null, $Cache = $null) {
    $out = New-Object System.Collections.ArrayList
    foreach ($d in @($Disks)) {
        if ($null -eq $d) { continue }
        $c = New-RcChoice ([string]$d.Drive) (Get-RcVolumeName $d $OsDrive) 'Drive'
        $c.Locked = ([string]$d.State -eq 'locked')
        $c.Media = [string]$d.Media
        $c.Removable = ([string]$d.Type -eq 'Removable' -or [string]$d.Bus -eq 'USB')
        $c.IsOs = ([string]$d.Drive -eq $OsDrive)
        [void]$out.Add($c)
    }
    foreach ($dk in @($Phys)) {
        if ($null -eq $dk -or [double]$dk.Size -le 0) { continue }
        $src = 'PhysicalDrive' + [string]$dk.Number
        $cached = $null
        if ($null -ne $Cache -and $Cache.ContainsKey($src)) { $cached = $Cache[$src] }
        Add-RcSourceChoices $out 'Disk' (Get-RcDiskName $dk) ('PD:' + [string]$dk.Number) $cached $dk 0
    }
    if ($Image -ne '') {
        $cached = $null
        if ($null -ne $Cache -and $Cache.ContainsKey($Image)) { $cached = $Cache[$Image] }
        $fn = [System.IO.Path]::GetFileName($Image)
        Add-RcSourceChoices $out 'Image' (('Disk imaj' + [char]0x0131 + ': ') + $fn) 'IMG' $cached $null $Parts
    }
    return , $out.ToArray()
}

# Secici anahtari -> kaynak. Donus: @{ Kind (Drive | Disk | Image | ''); Source; Part (-1: tum disk); Disk (fiziksel disk numarasi, yoksa -1) }
# Anahtarlar: "E:" (surucu), "PD:2" (disk, bolumler okunmadi), "PD:2:1" (disk 2, ikinci bolum), "PD:2:all" (tum disk), "IMG:1", "IMG:all"
function Resolve-RcKey([string]$Key, [string]$Image) {
    if ($Key -match '^IMG:all$') { return @{ Kind = 'Image'; Source = $Image; Part = -1; Disk = -1 } }
    if ($Key -match '^IMG:(\d+)$') { return @{ Kind = 'Image'; Source = $Image; Part = [int]$Matches[1]; Disk = -1 } }
    if ($Key -match '^PD:(\d{1,4}):all$') { $n = [int]$Matches[1]; return @{ Kind = 'Disk'; Source = ('PhysicalDrive' + [string]$n); Part = -1; Disk = $n } }
    if ($Key -match '^PD:(\d{1,4}):(\d+)$') { $n = [int]$Matches[1]; return @{ Kind = 'Disk'; Source = ('PhysicalDrive' + [string]$n); Part = [int]$Matches[2]; Disk = $n } }
    if ($Key -match '^PD:(\d{1,4})$') { $n = [int]$Matches[1]; return @{ Kind = 'Disk'; Source = ('PhysicalDrive' + [string]$n); Part = 0; Disk = $n } }
    if ($Key -cmatch '^[A-Za-z]:$') { return @{ Kind = 'Drive'; Source = $Key.ToUpperInvariant(); Part = 0; Disk = -1 } }
    return @{ Kind = ''; Source = ''; Part = 0; Disk = -1 }
}

# Kurtarma klasoru, taranan surucude ya da diskte olmamali (eklenti de aynisini denetler). $DiskLetters: taranan fiziksel diskteki surucu harfleri
# Donus: '' = uygun, aksi halde neden
function Test-RcDestUi([string]$Source, [string]$Kind, [string]$Dest, $DiskLetters = $null) {
    $d = ([string]$Dest).Trim()
    if ($d -eq '') { return ('Kurtarma klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'ilmedi.') }
    if ($d -cnotmatch '^([A-Za-z]:[\\/]|\\\\[^\\/])') { return ('Kurtarma klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' tam bir yol olmal' + [char]0x0131 + ' (' + [char]0x00F6 + 'rne' + [char]0x011F + 'in D:\Kurtarilan).') }
    if ($Kind -eq 'Drive' -and $Source.Length -ge 1 -and $d.Length -ge 2 -and $d.Substring(1, 1) -eq ':' -and $d.Substring(0, 1).ToUpperInvariant() -eq $Source.Substring(0, 1).ToUpperInvariant()) {
        return (('Kurtarma klas' + [char]0x00F6 + 'r' + [char]0x00FC + ', taranan ') + $Source.Substring(0, 1).ToUpperInvariant() + (': s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde olamaz. Kurtar' + [char]0x0131 + 'lan dosyalar, silinmi' + [char]0x015F + ' dosyalar' + [char]0x0131 + 'n yerine yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'p onlar' + [char]0x0131 + ' yok edebilir; ba' + [char]0x015F + 'ka bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ya da USB bellek se' + [char]0x00E7 + 'in.'))
    }
    if ($Kind -eq 'Disk' -and $d.Length -ge 2 -and $d.Substring(1, 1) -eq ':') {
        $l = $d.Substring(0, 1).ToUpperInvariant() + ':'
        foreach ($x in @($DiskLetters)) {
            if (([string]$x).ToUpperInvariant() -eq $l) {
                $no = ''
                if ($Source -match '(\d+)$') { $no = $Matches[1] }
                return (('Kurtarma klas' + [char]0x00F6 + 'r' + [char]0x00FC + ', taranan diskte (Disk ') + $no + (') olamaz. Kurtar' + [char]0x0131 + 'lan dosyalar, silinmi' + [char]0x015F + ' dosyalar' + [char]0x0131 + 'n yerine yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'p onlar' + [char]0x0131 + ' yok edebilir; ba' + [char]0x015F + 'ka bir disk ya da USB bellek se' + [char]0x00E7 + 'in.'))
            }
        }
    }
    return ''
}

# Tarama sonuc ozeti: @{ T; K (dim | warn) } satirlari
function Get-RcSummaryLines($Meta, [int]$Found, [int]$Hidden) {
    $out = New-Object System.Collections.ArrayList
    $method = [string]$Meta.Method
    $deep = ([string]$Meta.Mode -eq 'Both' -or [string]$Meta.Mode -eq 'Deep')
    $mode = ('h' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama')
    if ($method -eq 'raw') { $mode = ('t' + [char]0x00FC + 'm alanda imza taramas' + [char]0x0131 + '') }
    elseif ($method -eq 'free') { $mode = ('bo' + [char]0x015F + ' alanda imza taramas' + [char]0x0131 + '') }
    elseif ($deep) { $mode = 'derin tarama' }
    elseif ($method -eq '' -and [string]$Meta.Fs -ne 'NTFS') { $mode = ('imza taramas' + [char]0x0131 + '') }
    $l1 = [string]$Meta.Fs
    if ([int]$Meta.ClusterSize -gt 0) { $l1 += ('  ' + [char]0x00B7 + '  k' + [char]0x00FC + 'me ') + (Format-Size ([double]$Meta.ClusterSize)) }
    if ([double]$Meta.FreeBytes -gt 0) {
        if ($Meta.Raw -eq $true) { $l1 += ('  ' + [char]0x00B7 + '  taranan alan ') + (Format-Size ([double]$Meta.FreeBytes)) } else { $l1 += ('  ' + [char]0x00B7 + '  bo' + [char]0x015F + ' alan ') + (Format-Size ([double]$Meta.FreeBytes)) }
    }
    $l1 += ('  ' + [char]0x00B7 + '  ') + $mode
    [void]$out.Add(@{ T = $l1; K = 'dim' })
    if ([string]$Meta.Note -ne '') { [void]$out.Add(@{ T = [string]$Meta.Note; K = 'warn' }) }
    $st = $Meta.Stats
    if ($Found -gt 0) {
        $l2 = [string]$Found + ' dosya bulundu'
        if ($null -ne $st) {
            $a = [int]$st.FromTable
            $b = [int]$st.Carved
            if ($a -gt 0 -and $b -gt 0) { $l2 += ' (' + [string]$a + (' silinmi' + [char]0x015F + ' kay' + [char]0x0131 + 'ttan, ') + [string]$b + (' imza taramas' + [char]0x0131 + 'yla)') }
            elseif ($b -gt 0 -and $a -eq 0) { $l2 += (' (imza taramas' + [char]0x0131 + 'yla; dosya ad' + [char]0x0131 + ' ve tarihi bilinmez)') }
        }
        [void]$out.Add(@{ T = ($l2 + '.'); K = 'dim' })
    }
    if ($Hidden -gt 0) { [void]$out.Add(@{ T = ([string]$Hidden + (' kay' + [char]0x0131 + 't, disk alan' + [char]0x0131 + ' ba' + [char]0x015F + 'ka dosyalarca kullan' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' (' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ') i' + [char]0x00E7 + 'in listelenmedi.')); K = 'dim' }) }
    if ($null -ne $st -and [int]$st.Skipped -gt 0) { [void]$out.Add(@{ T = ([string][int]$st.Skipped + (' kay' + [char]0x0131 + 't atland' + [char]0x0131 + ': s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ', ' + [char]0x015F + 'ifreli ya da bozuk dosyalar kurtar' + [char]0x0131 + 'lamaz.')); K = 'dim' }) }
    if ($null -ne $st -and [double]$st.ReadErrors -gt 0) { [void]$out.Add(@{ T = ([string][int]$st.ReadErrors + (' okuma hatas' + [char]0x0131 + ' oldu; ilgili b' + [char]0x00F6 + 'lgeler s' + [char]0x0131 + 'f' + [char]0x0131 + 'r say' + [char]0x0131 + 'ld' + [char]0x0131 + ', disk sorunlu olabilir.')); K = 'warn' }) }
    if ($Meta.Truncated -eq $true) { [void]$out.Add(@{ T = (('Sonu' + [char]0x00E7 + 'lar ilk ') + [string]$script:RcMaxResults + (' kay' + [char]0x0131 + 'tla s' + [char]0x0131 + 'n' + [char]0x0131 + 'rl' + [char]0x0131 + '; t' + [char]0x00FC + 'r' + [char]0x00FC + ' ya da s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' daralt' + [char]0x0131 + 'p yeniden tarayabilirsiniz.')); K = 'warn' }) }
    if ($Meta.Canceled -eq $true) { [void]$out.Add(@{ T = ('Tarama yar' + [char]0x0131 + 'da kesildi; o ana kadar bulunanlar listelendi.'); K = 'warn' }) }
    return , $out.ToArray()
}

# Onay penceresinin metni
function Get-RcConfirmText($Items, [string]$Dest) {
    $n = 0
    $bytes = [double]0
    $low = 0
    foreach ($it in @($Items)) {
        $n++
        $bytes += [double]$it.Length
        if ([int]$it.Chance -lt 70) { $low++ }
    }
    $t = [string]$n + ' dosya (' + (Format-Size $bytes) + (') kurtar' + [char]0x0131 + 'lacak.') + "`r`n`r`n"
    $t += ('Kaydedilece' + [char]0x011F + 'i yer: ') + $Dest + "`r`n" + ('Bu klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'n i' + [char]0x00E7 + 'inde ' + [char]0x201C + 'Multimizer-Kurtarma-' + [char]0x2026 + '' + [char]0x201D + ' ad' + [char]0x0131 + 'nda yeni bir klas' + [char]0x00F6 + 'r a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r; var olan hi' + [char]0x00E7 + 'bir dosyan' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lmaz.') + "`r`n`r`n"
    $t += ('Taranan s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye ya da imaja hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey yaz' + [char]0x0131 + 'lmaz.')
    if ($low -gt 0) { $t += "`r`n`r`n" + [string]$low + (' dosyan' + [char]0x0131 + 'n kurtar' + [char]0x0131 + 'lma ' + [char]0x015F + 'ans' + [char]0x0131 + ' d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'k ya da orta; bunlar eksik ya da bozuk ' + [char]0x00E7 + '' + [char]0x0131 + 'kabilir.') }
    return $t
}

function Get-RcFootText([int]$Count, [double]$Bytes, [string]$Dest) {
    $t = ('Se' + [char]0x00E7 + 'ili: ') + [string]$Count + ' dosya'
    if ($Count -gt 0) { $t += ('  ' + [char]0x00B7 + '  ') + (Format-Size $Bytes) }
    if ($Dest -ne '') { $t += ('  ' + [char]0x00B7 + '  Hedef: ') + $Dest } else { $t += ('  ' + [char]0x00B7 + '  Hedef klas' + [char]0x00F6 + 'r hen' + [char]0x00FC + 'z se' + [char]0x00E7 + 'ilmedi') }
    return $t
}

# ---------------- seciciler ----------------
function Get-RcSelectedChoice {
    $it = $ui.sl_RcVol.SelectedItem
    if ($null -eq $it) { return $null }
    return $it
}

# Secili anahtardan kaynak bilgisini yeniler; sonuclar baska bir kaynaga aitse temizler
function Set-RcSourceFromKey {
    $r = Resolve-RcKey $script:RcSelKey $script:RcImage
    if ($null -ne $script:RcMeta -and ([string]$script:RcMeta.Source -ne [string]$r.Source -or [int]$script:RcMeta.Part -ne [int]$r.Part)) { Reset-RcResults }
    $script:RcSource = [string]$r.Source
    $script:RcSourceKind = [string]$r.Kind
    $script:RcPart = [int]$r.Part
    $script:RcDisk = [int]$r.Disk
    # onceden secilen kurtarma klasoru yeni kaynakta gecersizse unutulur
    if ($script:RcDest -ne '') {
        $why = Test-RcDestUi $script:RcSource $script:RcSourceKind $script:RcDest (Get-RcSelectedLetters)
        if ($why -ne '') { $script:RcDest = '' }
    }
}

# Secili fiziksel diskteki surucu harfleri (kurtarma klasoru bu diskte olamaz)
function Get-RcSelectedLetters {
    $ch = Get-RcSelectedChoice
    if ($null -eq $ch -or [string]$ch.Kind -ne 'Disk') { return @() }
    return @($ch.Letters)
}

function Reset-RcResults {
    $script:RcItems = @()
    $script:RcMeta = $null
    $script:RcScanError = ''
    $script:RcLastRun = $null
}

function Update-RcVolumeCombo {
    $disks = @()
    $phys = @()
    $os = ''
    $d = $script:SlDisks
    if ($null -ne $d -and $d.Failed -ne $true) {
        $disks = @($d.Disks)
        $os = [string]$d.Sys.OsDrive
        if ($null -ne $d.Phys) { $phys = @($d.Phys) }
    }
    $choices = Get-RcVolumeChoices $disks $os $script:RcImage $script:RcImageParts $phys $script:RcPartCache
    $script:RcLoading = $true
    try {
        Set-ComboChoices $ui.sl_RcVol $choices
        $key = $script:RcSelKey
        $found = $false
        foreach ($c in $choices) { if ([string]$c.Key -eq $key) { $found = $true } }
        if (-not $found) {
            $key = ''
            foreach ($c in $choices) { if ($c.IsOs -eq $true) { $key = [string]$c.Key; break } }
            if ($key -eq '' -and @($choices).Count -gt 0) { $key = [string]@($choices)[0].Key }
        }
        if ($key -ne '') { [void](Select-ComboKey $ui.sl_RcVol $key) }
        $script:RcSelKey = $key
    } finally { $script:RcLoading = $false }
    Set-RcSourceFromKey
}

function Update-RcTypeCombo {
    $cnt = Get-RcGroupCounts $script:RcItems
    $list = New-Object System.Collections.ArrayList
    foreach ($k in @($script:RcGroupNames.Keys)) {
        $nm = [string]$script:RcGroupNames[$k]
        if ($null -ne $script:RcMeta) { $nm += ' (' + [string]$cnt[$k] + ')' }
        [void]$list.Add((New-Choice $k $nm))
    }
    $script:RcLoading = $true
    try {
        Set-ComboChoices $ui.sl_RcType $list.ToArray()
        if (-not (Select-ComboKey $ui.sl_RcType $script:RcGroup)) { $script:RcGroup = 'all'; [void](Select-ComboKey $ui.sl_RcType 'all') }
    } finally { $script:RcLoading = $false }
}

function Select-RcVolume {
    if ($script:RcLoading -eq $true) { return }
    $k = Get-ComboKey $ui.sl_RcVol
    if ($k -eq '') { return }
    $script:RcSelKey = $k
    Set-RcSourceFromKey
    Update-RcTypeCombo
    Render-RcBody
    $ch = Get-RcSelectedChoice
    if ($null -ne $ch -and $ch.Loaded -eq $false -and [string]$ch.Kind -eq 'Disk') { Start-RcParts $script:RcSource }
}

function Select-RcGroup {
    if ($script:RcLoading -eq $true) { return }
    $k = Get-ComboKey $ui.sl_RcType
    if ($k -eq '') { return }
    $script:RcGroup = $k
    Render-RcBody
}

function Select-RcImage {
    $f = Select-OpenFile ('Ham disk imaj' + [char]0x0131 + ' (*.img;*.dd;*.raw;*.bin;*.001)|*.img;*.dd;*.raw;*.bin;*.001|T' + [char]0x00FC + 'm dosyalar (*.*)|*.*')
    if ($f -eq '') { return }
    $script:RcImage = $f
    $script:RcImageParts = 1
    $script:RcSelKey = 'IMG:0'
    $script:RcPartCache.Remove($f)
    Reset-RcResults
    Update-RcVolumeCombo
    Update-RcTypeCombo
    Render-RcBody
    Start-RcParts $f
}

function Select-RcDest {
    $d = Select-Folder ('Kurtar' + [char]0x0131 + 'lan dosyalar' + [char]0x0131 + 'n kaydedilece' + [char]0x011F + 'i klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in (taranan s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'den farkl' + [char]0x0131 + ' bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de olmal' + [char]0x0131 + ')')
    if ($d -eq '') { return '' }
    $why = Test-RcDestUi $script:RcSource $script:RcSourceKind $d (Get-RcSelectedLetters)
    if ($why -ne '') { Show-Toast $why 'warn'; return '' }
    $script:RcDest = $d
    Update-RcFoot
    return $d
}

# ---------------- cizim ----------------
$script:H_RcChk = { param($s, $e) Invoke-Safe { Update-RcFoot } ('Se' + [char]0x00E7 + 'im') }
$script:H_RcAct = { param($s, $e) Invoke-Safe { Invoke-RcAction $s.Tag } 'Eylem' }

function Invoke-RcAction($T) {
    switch ([string]$T.Do) {
        'RcBin'    { Open-Path 'shell:RecycleBinFolder' }
        'RcDir'    { if ([string]$T.Dir -ne '') { Open-Folder ([string]$T.Dir) } }
        'RcReport' { if ([string]$T.Report -ne '') { Open-Path ([string]$T.Report) } }
    }
}

function Update-RcFoot {
    if ([string]$script:UiState.Page -ne 'solve' -or $script:SlTab -ne 'recover') { return }
    $n = 0
    $bytes = [double]0
    $chk = Get-CheckedData $ui.sl_List
    foreach ($d in $chk) {
        if ($d -is [hashtable] -and $d.ContainsKey('Idx')) { $n++; $bytes += [double]$d.Len }
    }
    $ui.sl_Foot.Text = (Tr $((Get-RcFootText $n $bytes $script:RcDest)))
}

function Add-RcIntro {
    Add-HeadRow $ui.sl_List ('Silinen dosyalar' + [char]0x0131 + ' geri getir')
    Add-Note $ui.sl_List ('Multimizer s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' yaln' + [char]0x0131 + 'zca okur; taranan s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye, diske ya da imaja hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey yaz' + [char]0x0131 + 'lmaz. Bulunan dosyalar her zaman taranandan FARKLI bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye ya da diske, yeni bir klas' + [char]0x00F6 + 're kaydedilir ve var olan hi' + [char]0x00E7 + 'bir dosyan' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lmaz.')
    $row = New-ItemRow @{ Title = ('' + [char]0x00D6 + 'nce Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na bak' + [char]0x0131 + 'n'); Detail = ('Dosyay' + [char]0x0131 + ' Delete tu' + [char]0x015F + 'uyla sildiyseniz b' + [char]0x00FC + 'y' + [char]0x00FC + 'k olas' + [char]0x0131 + 'l' + [char]0x0131 + 'kla oradad' + [char]0x0131 + 'r; sa' + [char]0x011F + ' t' + [char]0x0131 + 'klay' + [char]0x0131 + 'p ' + [char]0x201C + 'Geri y' + [char]0x00FC + 'kle' + [char]0x201D + ' demeniz yeter. Ek tarama gerekmez.'); BrCol = 'BrInfo'; Btn1 = ('A' + [char]0x00E7 + '') } @{ Do = 'RcBin' } $false $false
    $row.FindName('Act').Add_Click($script:H_RcAct)
    [void]$ui.sl_List.Children.Add($row)
    Add-Note $ui.sl_List ('Taranabilenler: harf alm' + [char]0x0131 + '' + [char]0x015F + ' her s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' (dahili disk, USB bellek, SD kart, harici disk), harf almam' + [char]0x0131 + '' + [char]0x015F + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler, fiziksel diskin tamam' + [char]0x0131 + ' ve ham disk imajlar' + [char]0x0131 + ' (.img, .dd, .raw, .bin). NTFS, FAT12/16/32 ve exFAT' + [char]0x2019 + 'ta silinmi' + [char]0x015F + ' dosya kay' + [char]0x0131 + 'tlar' + [char]0x0131 + ' okunur: dosya ad' + [char]0x0131 + ', klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' ve tarihi korunur. ext2/3/4' + [char]0x2019 + 'te bo' + [char]0x015F + ' bloklar, ReFS, APFS, HFS+, Btrfs, XFS gibi di' + [char]0x011F + 'er bi' + [char]0x00E7 + 'imlerde ve bozuk ya da b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + ' silinmi' + [char]0x015F + ' disklerde t' + [char]0x00FC + 'm alan dosya imzalar' + [char]0x0131 + 'na g' + [char]0x00F6 + 're taran' + [char]0x0131 + 'r; bu durumda dosya ad' + [char]0x0131 + ' ve tarihi bilinmez.')
    Add-Note $ui.sl_List ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama silinmi' + [char]0x015F + ' dosya kay' + [char]0x0131 + 'tlar' + [char]0x0131 + 'n' + [char]0x0131 + ' okur. Derin tarama bo' + [char]0x015F + ' alan' + [char]0x0131 + ' ayr' + [char]0x0131 + 'ca dosya imzalar' + [char]0x0131 + 'na g' + [char]0x00F6 + 're tarar (resim, belge, ar' + [char]0x015F + 'iv, ses ve video); ad' + [char]0x0131 + ' bilinmeyen dosyalar da bulunur ama uzun s' + [char]0x00FC + 'rebilir. Kay' + [char]0x0131 + 't tutmayan bi' + [char]0x00E7 + 'imlerde h' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama da imza taramas' + [char]0x0131 + ' yapar.')
    $ch = Get-RcSelectedChoice
    if ($null -ne $ch) {
        $isDrive = ([string]$ch.Kind -eq 'Drive')
        if ($ch.Locked -eq $true) {
            if ($isDrive) { Add-Note $ui.sl_List ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' BitLocker ile kilitli. ' + [char]0x00D6 + 'nce kilidini a' + [char]0x00E7 + '' + [char]0x0131 + 'n; kilitli bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de okunabilir dosya yoktur.') 'warn' }
            else { Add-Note $ui.sl_List ('Bu b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm BitLocker ile kilitli. ' + [char]0x00D6 + 'nce kilidini a' + [char]0x00E7 + '' + [char]0x0131 + 'n; kilitli bir b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mde okunabilir dosya yoktur.') 'warn' }
        }
        if ($ch.IsOs -eq $true) {
            if ($isDrive) { Add-Note $ui.sl_List ('Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + ' tar' + [char]0x0131 + 'yorsunuz. Bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'rken bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye s' + [char]0x00FC + 'rekli yeni veri yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve silinen dosyalar' + [char]0x0131 + 'n yerini kaplar; kurtarmak istedi' + [char]0x011F + 'iniz bir dosya varsa bilgisayar' + [char]0x0131 + ' m' + [char]0x00FC + 'mk' + [char]0x00FC + 'n oldu' + [char]0x011F + 'unca az kullan' + [char]0x0131 + 'n.') 'warn' }
            else { Add-Note $ui.sl_List ('Windows' + [char]0x2019 + 'un kurulu oldu' + [char]0x011F + 'u diski tar' + [char]0x0131 + 'yorsunuz. Bilgisayar ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'rken bu diske s' + [char]0x00FC + 'rekli yeni veri yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve silinen dosyalar' + [char]0x0131 + 'n yerini kaplar; kurtarmak istedi' + [char]0x011F + 'iniz bir dosya varsa bilgisayar' + [char]0x0131 + ' m' + [char]0x00FC + 'mk' + [char]0x00FC + 'n oldu' + [char]0x011F + 'unca az kullan' + [char]0x0131 + 'n.') 'warn' }
        }
        if ([string]$ch.Media -eq 'SSD' -and $ch.Removable -ne $true) { Add-Note $ui.sl_List ('Bu bir SSD. Windows silinen verileri TRIM ile hemen temizler; bu y' + [char]0x00FC + 'zden listede bulunan dosyalar' + [char]0x0131 + 'n i' + [char]0x00E7 + 'i bo' + [char]0x015F + ' ' + [char]0x00E7 + '' + [char]0x0131 + 'kabilir. SSD' + [char]0x2019 + 'de kurtarma ' + [char]0x015F + 'ans' + [char]0x0131 + ' mekanik diske g' + [char]0x00F6 + 're ' + [char]0x00E7 + 'ok daha d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'kt' + [char]0x00FC + 'r.') 'warn' }
        if ([string]$ch.Kind -eq 'Image') { Add-Note $ui.sl_List ('Disk imaj' + [char]0x0131 + ' salt okunur a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r; ham imajlar (.img, .dd, .raw, .bin) desteklenir.') }
        if ([string]$ch.Kind -eq 'Disk') { Add-Note $ui.sl_List ('Fiziksel disk salt okunur a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r. Harf almam' + [char]0x0131 + '' + [char]0x015F + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler, Windows' + [char]0x2019 + 'un tan' + [char]0x0131 + 'mad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' bi' + [char]0x00E7 + 'imler (ext4 gibi) ve b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm tablosu bozulmu' + [char]0x015F + ' diskler de taranabilir. B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + ' silinmi' + [char]0x015F + ' ya da bi' + [char]0x00E7 + 'imlendirilmi' + [char]0x015F + ' bir diskte dosya ar' + [char]0x0131 + 'yorsan' + [char]0x0131 + 'z ' + [char]0x201C + 't' + [char]0x00FC + 'm disk' + [char]0x201D + ' sat' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') }
        if ($ch.Whole -eq $true) { Add-Note $ui.sl_List ('T' + [char]0x00FC + 'm disk se' + [char]0x00E7 + 'ildi: b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm d' + [char]0x00FC + 'zeni yok say' + [char]0x0131 + 'l' + [char]0x0131 + 'r, diskin tamam' + [char]0x0131 + ' dosya imzalar' + [char]0x0131 + 'na g' + [char]0x00F6 + 're taran' + [char]0x0131 + 'r. B' + [char]0x00FC + 'y' + [char]0x00FC + 'k disklerde saatler s' + [char]0x00FC + 'rebilir; dosya adlar' + [char]0x0131 + ' ve klas' + [char]0x00F6 + 'rler bilinmez, var olan dosyalar da listelenebilir.') 'warn' }
    }
    if ($script:IsAdmin -ne $true -and ($script:RcSourceKind -eq 'Drive' -or $script:RcSourceKind -eq 'Disk')) { Add-Note $ui.sl_List ('Multimizer y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'm' + [char]0x0131 + 'yor; s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler ve diskler okunamaz. Y' + [char]0x00F6 + 'netici olarak yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n ya da bir disk imaj' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') 'warn' }
    Add-Note $ui.sl_List ('Silinen dosyan' + [char]0x0131 + 'n bulundu' + [char]0x011F + 'u alana yeni veri yaz' + [char]0x0131 + 'ld' + [char]0x0131 + 'ysa dosya geri getirilemez. Bu y' + [char]0x00FC + 'zden kurtarmak istedi' + [char]0x011F + 'iniz dosya varsa o s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye yeni bir ' + [char]0x015F + 'ey kaydetmeyin.')
}

function Add-RcResultRow {
    $r = $script:RcLastRun
    if ($null -eq $r) { return }
    $done = 0
    $failed = 0
    if ($null -ne $r.Done) { $done = [int]$r.Done }
    if ($null -ne $r.Failed) { $failed = [int]$r.Failed }
    $title = ''
    $det = ''
    $br = 'BrGood'
    if ($done -gt 0) {
        $title = ('Kurtarma tamamland' + [char]0x0131 + ': ') + [string]$done + ' dosya, ' + (Format-Size ([double]$r.Bytes))
        $det = ('Kaydedilen klas' + [char]0x00F6 + 'r: ') + [string]$r.Dir
        if ($failed -gt 0) { $det += "`r`n" + [string]$failed + (' dosya kurtar' + [char]0x0131 + 'lamad' + [char]0x0131 + '; nedenleri raporda yaz' + [char]0x0131 + 'yor.'); $br = 'BrWarn' }
        if ($r.Canceled -eq $true) { $det += "`r`n" + ('' + [char]0x0130 + '' + [char]0x015F + 'lem yar' + [char]0x0131 + 'da kesildi.'); $br = 'BrWarn' }
    } else {
        $title = ('Hi' + [char]0x00E7 + 'bir dosya kurtar' + [char]0x0131 + 'lamad' + [char]0x0131 + '')
        $det = [string]$r.Error
        if ($det -eq '') { $det = ('Dosyalar' + [char]0x0131 + 'n disk alan' + [char]0x0131 + ' art' + [char]0x0131 + 'k okunam' + [char]0x0131 + 'yor ya da ba' + [char]0x015F + 'ka veriyle dolu olabilir. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' raporda ve g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') }
        $br = 'BrBad'
    }
    $b1 = ''
    $b2 = ''
    if ([string]$r.Dir -ne '' -and (Test-Path -LiteralPath ([string]$r.Dir))) { $b1 = ('Klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' a' + [char]0x00E7 + '') }
    if ([string]$r.Report -ne '' -and (Test-Path -LiteralPath ([string]$r.Report))) { $b2 = ('Raporu a' + [char]0x00E7 + '') }
    $row = New-ItemRow @{ Title = $title; Detail = $det; BrCol = $br; Btn1 = $b1; Btn2 = $b2 } @{ Do = 'RcDir'; Dir = [string]$r.Dir; Report = [string]$r.Report } $false $false
    if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_RcAct) }
    if ($b2 -ne '') {
        $a2 = $row.FindName('Act2')
        $a2.Tag = @{ Do = 'RcReport'; Dir = [string]$r.Dir; Report = [string]$r.Report }
        $a2.Add_Click($script:H_RcAct)
    }
    [void]$ui.sl_List.Children.Add($row)
}

function Render-RcBody {
    $ui.sl_List.Children.Clear()
    if ($null -ne $script:SlDisks -and $script:SlDisks.Failed -eq $true) { Add-Note $ui.sl_List ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' listesi okunamad' + [char]0x0131 + '; yine de ' + [char]0x201C + 'Disk imaj' + [char]0x0131 + ' se' + [char]0x00E7 + '...' + [char]0x201D + ' ile bir imaj a' + [char]0x00E7 + 'abilirsiniz.') 'warn' }
    if ($script:RcScanError -ne '') { Add-Note $ui.sl_List $script:RcScanError 'bad' }
    Add-RcResultRow
    $meta = $script:RcMeta
    if ($null -eq $meta) {
        Add-RcIntro
        Update-RcFoot
        return
    }
    $q = [string]$ui.sl_RcFind.Text
    $disp = Get-RcDisplay $script:RcItems $script:RcGroup $q $script:RcRowCap
    foreach ($ln in (Get-RcSummaryLines $meta ([int]$disp.Total - [int]$disp.Hidden) ([int]$disp.Hidden))) { Add-Note $ui.sl_List ([string]$ln.T) ([string]$ln.K) }
    $rows = @($disp.Rows)
    if ($rows.Count -eq 0) {
        if ([int]$disp.Total - [int]$disp.Hidden -le 0) {
            Add-Note $ui.sl_List ('Silinmi' + [char]0x015F + ' dosya bulunamad' + [char]0x0131 + '. SSD' + [char]0x2019 + 'lerde TRIM verileri temizlemi' + [char]0x015F + ' olabilir; ' + [char]0x201C + 'Derin tara' + [char]0x201D + ' bo' + [char]0x015F + ' alan' + [char]0x0131 + ' dosya imzalar' + [char]0x0131 + 'na g' + [char]0x00F6 + 're de arar.') 'warn'
        } else {
            Add-Note $ui.sl_List ('Bu s' + [char]0x00FC + 'zgece uyan dosya yok. T' + [char]0x00FC + 'r se' + [char]0x00E7 + 'imini ya da arama kutusunu de' + [char]0x011F + 'i' + [char]0x015F + 'tirin.')
        }
        Update-RcFoot
        return
    }
    $head = ('Kurtar' + [char]0x0131 + 'labilecek dosyalar (') + [string]$rows.Count
    if ([int]$disp.Matched -gt $rows.Count) { $head += ' / ' + [string]$disp.Matched }
    Add-HeadRow $ui.sl_List ($head + ')')
    if ([int]$disp.Matched -gt $rows.Count) { Add-Note $ui.sl_List (('Liste, kurtar' + [char]0x0131 + 'lma ' + [char]0x015F + 'ans' + [char]0x0131 + ' en y' + [char]0x00FC + 'ksek ') + [string]$rows.Count + (' dosyay' + [char]0x0131 + ' g' + [char]0x00F6 + 'sterir. Di' + [char]0x011F + 'erlerini g' + [char]0x00F6 + 'rmek i' + [char]0x00E7 + 'in t' + [char]0x00FC + 'r' + [char]0x00FC + ' ya da arama kutusunu kullan' + [char]0x0131 + 'n.')) }
    foreach ($e in $rows) {
        $it = $script:RcItems[[int]$e.Idx]
        if ($null -eq $it) { continue }
        $m = New-RcRowModel $it
        $row = New-ItemRow $m @{ Idx = [int]$e.Idx; Len = [double]$it.Length } $true $false
        $c = $row.FindName('Chk')
        $c.Add_Checked($script:H_RcChk)
        $c.Add_Unchecked($script:H_RcChk)
        [void]$ui.sl_List.Children.Add($row)
    }
    Update-RcFoot
}

function Render-SlRecover {
    $ui.sl_List.Children.Clear()
    if ($null -eq $script:SlDisks) {
        foreach ($ck in @($script:RcPartCache.Keys)) { if ([string]$ck -like 'PhysicalDrive*') { $script:RcPartCache.Remove($ck) } }
        Update-RcVolumeCombo
        Update-RcTypeCombo
        Add-Note $ui.sl_List ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler okunuyor...')
        Load-SlDisk
        return
    }
    Update-RcVolumeCombo
    Update-RcTypeCombo
    Render-RcBody
}

# ---------------- islemler ----------------
function Start-RcScan([string]$Mode) {
    if ($script:RcSource -eq '') { Show-Toast ('' + [char]0x00D6 + 'nce taranacak s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ', diski ya da disk imaj' + [char]0x0131 + 'n' + [char]0x0131 + ' se' + [char]0x00E7 + 'in.') 'warn'; return }
    $ch = Get-RcSelectedChoice
    if ($null -ne $ch -and $ch.Locked -eq $true) {
        if ($script:RcSourceKind -eq 'Drive') { Show-Toast ($script:RcSource + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' BitLocker ile kilitli; ' + [char]0x00F6 + 'nce kilidini a' + [char]0x00E7 + '' + [char]0x0131 + 'n.')) 'warn' }
        else { Show-Toast ('Bu b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm BitLocker ile kilitli; ' + [char]0x00F6 + 'nce kilidini a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') 'warn' }
        return
    }
    if (($script:RcSourceKind -eq 'Drive' -or $script:RcSourceKind -eq 'Disk') -and $script:IsAdmin -ne $true) { Show-Toast ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' ya da diski okumak i' + [char]0x00E7 + 'in Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' gerekir.') 'warn'; return }
    if ($null -ne $ch -and $ch.Loaded -eq $false -and $script:RcSourceKind -eq 'Disk') {
        Show-Toast ('Diskin b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mleri okunuyor; bitince bir b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm se' + [char]0x00E7 + 'ip yeniden taray' + [char]0x0131 + 'n.') 'info'
        Start-RcParts $script:RcSource
        return
    }
    $script:RcPendSource = $script:RcSource
    $script:RcPendPart = $script:RcPart
    $script:RcPendMode = $Mode
    $lbl = ('Silinen dosyalar taran' + [char]0x0131 + 'yor (salt okunur)')
    if ($Mode -eq 'Both') { $lbl = ('Derin tarama yap' + [char]0x0131 + 'l' + [char]0x0131 + 'yor (salt okunur)') }
    [void](Start-Async 'RcScan' 'Job_RecoverScan' @{ Source = $script:RcSource; Mode = $Mode; Partition = $script:RcPart; MaxResults = $script:RcMaxResults } {
        param($r)
        Complete-RcScan $r
    } $lbl)
}

# Fiziksel diskin ya da imajin bolumlerini (yalnizca bolum duzeni; hizli) arka planda okur
function Start-RcParts([string]$Source) {
    if ($Source -eq '' -or $script:RcPartPend -ne '') { return }
    if ($Source -match '^PhysicalDrive\d+$' -and $script:IsAdmin -ne $true) {
        $m = ('Fiziksel diskin b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mlerini okumak i' + [char]0x00E7 + 'in Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' gerekir.')
        $script:RcScanError = $m
        Show-Toast $m 'warn'
        Render-RcBody
        return
    }
    $script:RcPartPend = $Source
    $started = Start-Async 'RcParts' 'Job_RecoverParts' @{ Source = $Source } {
        param($r)
        Complete-RcParts $r
    } ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler okunuyor')
    if ($started -ne $true) { $script:RcPartPend = '' }
}

function Complete-RcParts($R) {
    $src = $script:RcPartPend
    $script:RcPartPend = ''
    if ($src -eq '') { return }
    if ($null -eq $R) { $R = @{ Ok = $false; Error = ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler okunamad' + [char]0x0131 + '.'); Parts = @() } }
    $script:RcPartCache[$src] = @{ Ok = ($R.Ok -eq $true); Error = [string]$R.Error; Parts = @($R.Parts) }
    if ($R.Ok -ne $true) {
        $m = [string]$R.Error
        if ($m -eq '') { $m = ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler okunamad' + [char]0x0131 + '.') }
        $script:RcScanError = $m
        Show-Toast $m 'bad'
    } else {
        $script:RcScanError = ''
        # secili oge bu diskin "bolumleri okumak icin secin" satiriysa ilk bolume gecilir
        if ($script:RcSelKey -match '^PD:(\d+)$' -and ('PhysicalDrive' + $Matches[1]) -eq $src) { $script:RcSelKey = $script:RcSelKey + ':0' }
    }
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'recover') {
        Update-RcVolumeCombo
        Update-RcTypeCombo
        Render-RcBody
    }
}

function Complete-RcScan($R) {
    $script:RcLastRun = $null
    if ($null -eq $R -or $R.Ok -ne $true) {
        $m = ('Tarama yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '.')
        if ($null -ne $R -and [string]$R.Error -ne '') { $m = [string]$R.Error }
        $script:RcScanError = $m
        $script:RcItems = @()
        $script:RcMeta = $null
        Show-Toast $m 'bad'
    } else {
        $script:RcScanError = ''
        $script:RcItems = @($R.Items)
        $parts = 1
        if ($null -ne $R.Partitions) { $parts = [int]$R.Partitions }
        $script:RcMeta = @{ Source = $script:RcPendSource; Part = $script:RcPendPart; Fs = [string]$R.Fs; ClusterSize = [int]$R.ClusterSize; VolumeBytes = [double]$R.VolumeBytes; FreeBytes = [double]$R.FreeBytes
            Mode = [string]$R.Mode; Truncated = ($R.Truncated -eq $true); Canceled = ($R.Canceled -eq $true); Stats = $R.Stats; Partitions = $parts
            Method = [string]$R.Method; Raw = ($R.Raw -eq $true); Note = [string]$R.Note }
        $n = 0
        foreach ($it in $script:RcItems) { if ([int]$it.Chance -gt 0) { $n++ } }
        if ($n -gt 0) { Show-Toast ([string]$n + (' silinmi' + [char]0x015F + ' dosya bulundu.')) 'good' } else { Show-Toast ('Kurtar' + [char]0x0131 + 'labilir silinmi' + [char]0x015F + ' dosya bulunamad' + [char]0x0131 + '.') 'info' }
        if ($script:RcImage -ne '' -and $script:RcPendSource -eq $script:RcImage -and $parts -gt 1 -and $script:RcImageParts -ne $parts) {
            $script:RcImageParts = $parts
            Update-RcVolumeCombo
        }
    }
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'recover') {
        Update-RcTypeCombo
        Render-RcBody
    }
}

function Start-RcRecover {
    if ($null -eq $script:RcMeta) { Show-Toast ('' + [char]0x00D6 + 'nce bir tarama yap' + [char]0x0131 + 'n.') 'warn'; return }
    $chk = Get-CheckedData $ui.sl_List
    $items = New-Object System.Collections.ArrayList
    foreach ($d in $chk) {
        if ($d -is [hashtable] -and $d.ContainsKey('Idx')) {
            $it = $script:RcItems[[int]$d.Idx]
            if ($null -ne $it) { [void]$items.Add($it) }
        }
    }
    if ($items.Count -eq 0) { Show-Toast ('Kurtar' + [char]0x0131 + 'lacak dosyalar' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    if ($script:RcDest -eq '') {
        $dd = Select-RcDest
        if ($dd -eq '') { return }
    }
    $why = Test-RcDestUi $script:RcSource $script:RcSourceKind $script:RcDest (Get-RcSelectedLetters)
    if ($why -ne '') { Show-Toast $why 'warn'; return }
    $script:RcPendItems = $items.ToArray()
    $script:RcPendSource = $script:RcSource
    $script:RcPendPart = $script:RcPart
    $script:RcPendDest = $script:RcDest
    Show-Confirm ('Dosyalar' + [char]0x0131 + ' kurtar') (Get-RcConfirmText $script:RcPendItems $script:RcPendDest) 'Kurtar' { Start-RcRecoverJob }
}

function Start-RcRecoverJob {
    [void](Start-Async 'RcFiles' 'Job_RecoverFiles' @{ Source = $script:RcPendSource; Partition = $script:RcPendPart; Dest = $script:RcPendDest; Items = $script:RcPendItems; KeepPaths = $true } {
        param($r)
        Complete-RcRecover $r
    } ('Dosyalar kurtar' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
}

function Complete-RcRecover($R) {
    if ($null -eq $R) { $R = @{ Ok = $false; Done = 0; Failed = 0; Bytes = 0; Dir = ''; Report = ''; Error = ('Kurtarma tamamlanamad' + [char]0x0131 + '.'); Canceled = $false } }
    $script:RcLastRun = $R
    if ($R.Ok -eq $true) { Show-Toast ([string]$R.Done + (' dosya kurtar' + [char]0x0131 + 'ld' + [char]0x0131 + '.')) 'good' }
    elseif ($R.Canceled -eq $true) { Show-Toast 'Kurtarma iptal edildi.' 'warn' }
    else {
        $m = ('Hi' + [char]0x00E7 + 'bir dosya kurtar' + [char]0x0131 + 'lamad' + [char]0x0131 + '.')
        if ([string]$R.Error -ne '') { $m = [string]$R.Error }
        Show-Toast $m 'bad'
    }
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'recover') { Render-RcBody }
}

function Init-SlRecover {
    $t = New-Object System.Windows.Threading.DispatcherTimer
    $t.Interval = [TimeSpan]::FromMilliseconds(320)
    $t.Add_Tick({
        $script:RcFindTimer.Stop()
        try { if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'recover') { Render-RcBody } } catch { Write-CrashLog (('Silinen dosyalar s' + [char]0x00FC + 'zgeci: ') + $_.Exception.Message) }
    })
    $script:RcFindTimer = $t
    $ui.sl_RcFind.Add_TextChanged({ if ($null -ne $script:RcFindTimer) { $script:RcFindTimer.Stop(); $script:RcFindTimer.Start() } })
    $ui.sl_RcVol.Add_SelectionChanged({ Invoke-Safe { Select-RcVolume } ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' se' + [char]0x00E7 + 'imi') })
    $ui.sl_RcType.Add_SelectionChanged({ Invoke-Safe { Select-RcGroup } ('T' + [char]0x00FC + 'r s' + [char]0x00FC + 'zgeci') })
    $ui.sl_RcImg.Add_Click({ Invoke-Safe { Select-RcImage } ('Disk imaj' + [char]0x0131 + '') })
    $ui.sl_RcQuick.Add_Click({ Invoke-Safe { Start-RcScan 'Quick' } ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' tarama') })
    $ui.sl_RcDeep.Add_Click({ Invoke-Safe { Start-RcScan 'Both' } 'Derin tarama' })
    $ui.sl_RcDest.Add_Click({ Invoke-Safe { [void](Select-RcDest) } ('Kurtarma klas' + [char]0x00F6 + 'r' + [char]0x00FC + '') })
    $ui.sl_RcRun.Add_Click({ Invoke-Safe { Start-RcRecover } 'Kurtar' })
    $ui.sl_RcAll.Add_Click({ Invoke-Safe { Set-RowChecks $ui.sl_List { param($d) $true }; Update-RcFoot } ('Hepsini se' + [char]0x00E7 + '') })
    $ui.sl_RcNone.Add_Click({ Invoke-Safe { Set-RowChecks $ui.sl_List { param($d) $false }; Update-RcFoot } ('Se' + [char]0x00E7 + 'imi temizle') })
}

# ---------------- cozum merkezi: kalici silme sekmesi ----------------
# ==================================================================
#  COZUM MERKEZI: "Kalici silme" sekmesi
#  Dort duzeyde silme: dosya ve klasor (Job_SecureDelete, Araclar sayfasiyla ortak), suruculerin bos alani (Job_WipeFree), disklerin
#  ayrilmamis alani, tek bolum ve tum disk (Job_WipeRaw). Isler "GuvenliSilme" ve "DiskSilme" eklentilerindedir; burada yalnizca
#  secenekler, onay metinleri ve sonuc gosterimi var. Geri dondurulemez islemlerde (bolum ve disk) hedefin adi elle yazdirilir.
#  Silinen dosya kurtarma sekmesiyle ayni kaynaklari kullanir: surucu, harfsiz bolum, tum disk ve USB bellek.
# ==================================================================
$script:ErPendDrive = ''
$script:ErLast = $null
$script:ErPend = $null
$script:ErOpts = @{ Method = 'random'; Verify = 'sample'; After = 'none' }
$script:ErLoading = $false
$script:ErTypedExpect = ''
$script:ErTypedAct = $null

# ---------------- saf yardimcilar (testlenir) ----------------
# Secili yazma yontemi, dogrulama ve sonraki adim (gecersiz degerler varsayilana doner)
function Get-ErOptions {
    return @{ Method = (Get-WipeMethodKey ([string]$script:ErOpts.Method)); Verify = (Get-WipeVerifyKey ([string]$script:ErOpts.Verify)); After = (Get-WipeAfterKey ([string]$script:ErOpts.After)) }
}

# Bos alan temizleme icin surucu satirlari. Kilitli, dosya sistemi olmayan ya da bos yeri cok az olan suruculer listelenmez.
# Donus: @{ Drive; Title; Detail; BrCol; Free; Size; Media; Bus; IsOs; Trim } dizisi
function Get-ErDriveModels($Disks, [string]$OsDrive) {
    $out = New-Object System.Collections.ArrayList
    foreach ($d in @($Disks)) {
        if ($null -eq $d) { continue }
        if ([string]$d.State -eq 'locked') { continue }
        if (([string]$d.Fs).Trim() -eq '') { continue }
        $free = [double]$d.Free
        if ($free -lt 67108864) { continue }
        $isOs = ([string]$d.Drive -eq $OsDrive)
        $media = [string]$d.Media
        $usb = ([string]$d.Bus -eq 'USB' -or [string]$d.Type -eq 'Removable')
        $det = ('Bo' + [char]0x015F + ' alan: ') + (Format-Size $free) + ('. Silinmi' + [char]0x015F + ' dosyalar' + [char]0x0131 + 'n kal' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r; var olan dosyalara dokunulmaz.')
        $br = 'BrInfo'
        $trim = $false
        if ($media -eq 'SSD' -and -not $usb) {
            $det += (' SSD' + [char]0x2019 + 'de tam g' + [char]0x00FC + 'vence vermez (denetleyici veriyi ba' + [char]0x015F + 'ka h' + [char]0x00FC + 'crelere ta' + [char]0x015F + '' + [char]0x0131 + 'r); as' + [char]0x0131 + 'l ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm disk ' + [char]0x015F + 'ifrelemesidir.')
            $br = 'BrWarn'
            $trim = $true
        } elseif ($usb) {
            $det += (' ' + [char]0x00C7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'labilir bellekte i' + [char]0x015F + 'lem yava' + [char]0x015F + ' olabilir.')
        }
        if ($isOs) { $det += (' Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde i' + [char]0x015F + 'lem boyunca bilgisayar' + [char]0x0131 + ' kullanmaman' + [char]0x0131 + 'z ' + [char]0x00F6 + 'nerilir.') }
        [void]$out.Add(@{ Drive = [string]$d.Drive; Title = (Get-RcVolumeName $d $OsDrive); Detail = $det; BrCol = $br; Free = $free; Size = [double]$d.Size; Media = $media; Bus = [string]$d.Bus; IsOs = $isOs; Trim = $trim })
    }
    return , $out.ToArray()
}

# Bir geciste yazilacak bos alan (bayt): bos alan eksi birakilan pay
function Get-ErFreeWork($T) {
    $w = [double]$T.Free - (Get-WipeReserve ([double]$T.Size) ($T.IsOs -eq $true))
    if ($w -lt 0) { $w = [double]0 }
    return $w
}

# Bos alan temizleme onay metni. Opts: @{ Method; Verify } (verilmezse varsayilanlar)
function Get-ErFreeConfirmText($T, $Opts = $null) {
    $method = 'random'
    $verify = 'sample'
    if ($null -ne $Opts) { $method = Get-WipeMethodKey ([string]$Opts.Method); $verify = Get-WipeVerifyKey ([string]$Opts.Verify) }
    $modes = Get-WipeModes $method
    $est = Get-WipeEstimate (Get-ErFreeWork $T) $modes.Count 'none' ([string]$T.Bus) ([string]$T.Media)
    $msg = [string]$T.Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'n' + [char]0x00FC + 'n bo' + [char]0x015F + ' alan' + [char]0x0131 + ' (') + (Format-Size ([double]$T.Free)) + (') ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'larak temizlenecek.') + "`r`n`r`n"
    $msg += ('' + [char]0x2022 + '  Var olan dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'za dokunulmaz; yaln' + [char]0x0131 + 'zca daha ' + [char]0x00F6 + 'nce silinmi' + [char]0x015F + ' dosyalar' + [char]0x0131 + 'n diskte kalan izleri yok edilir.') + "`r`n"
    $msg += ('' + [char]0x2022 + '  Y' + [char]0x00F6 + 'ntem: ') + (Get-WipeMethodName $method) + ('. Tahmini s' + [char]0x00FC + 're: ') + $est.Text + ('. ' + [char]0x0130 + 'stedi' + [char]0x011F + 'iniz an iptal edebilirsiniz.') + "`r`n"
    $pay = '%1'
    if ($T.IsOs -eq $true) { $pay = '%3' }
    $msg += ('' + [char]0x2022 + '  ' + [char]0x0130 + '' + [char]0x015F + 'lem s' + [char]0x0131 + 'ras' + [char]0x0131 + 'nda s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'de yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + $pay + (' pay bo' + [char]0x015F + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'l' + [char]0x0131 + 'r; ge' + [char]0x00E7 + 'ici dosyalar i' + [char]0x015F + ' bitince (iptal etseniz de) silinir.') + "`r`n"
    if ($verify -ne 'none') {
        $msg += ('' + [char]0x2022 + '  Do' + [char]0x011F + 'rulama: i' + [char]0x015F + 'e ba' + [char]0x015F + 'larken bilinen i' + [char]0x00E7 + 'erikli k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k test dosyalar' + [char]0x0131 + ' yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'p silinir; temizlikten sonra ayn' + [char]0x0131 + ' konumlar do' + [char]0x011F + 'rudan s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'den okunarak eski verinin kal' + [char]0x0131 + 'p kalmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'na bak' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') + "`r`n"
    }
    $msg += ('' + [char]0x2022 + '  Bu s' + [char]0x0131 + 'rada o s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye ba' + [char]0x015F + 'ka ' + [char]0x015F + 'ey kaydetmeyin; s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ge' + [char]0x00E7 + 'ici olarak neredeyse dolu g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.')
    if ([string]$T.Media -eq 'SSD') { $msg += "`r`n`r`n" + ('Not: Bu bir SSD. SSD' + [char]0x2019 + 'lerde bo' + [char]0x015F + ' alan temizleme tam g' + [char]0x00FC + 'vence vermez ve diski gereksiz y' + [char]0x0131 + 'pratt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yaln' + [char]0x0131 + 'zca ger' + [char]0x00E7 + 'ekten gerekiyorsa yap' + [char]0x0131 + 'n. Bitince silinen alanlar s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye de bildirilir (TRIM).') }
    if ($T.IsOs -eq $true) { $msg += "`r`n`r`n" + ('Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ': i' + [char]0x015F + 'lem bitene kadar program kurmay' + [char]0x0131 + 'n, g' + [char]0x00FC + 'ncelleme yapmay' + [char]0x0131 + 'n ve b' + [char]0x00FC + 'y' + [char]0x00FC + 'k dosya indirmeyin.') }
    return $msg
}

# Bolumlerin disinda kalan bosluk tahmini (Windows'un bildirdigi bolumlere gore). Motor gercek duzeni diskten okur;
# bu sayi yalnizca satirda gosterilir. Basta ve sonda 1 MiB korunur, 8 MiB'tan kucuk bosluklar sayilmaz.
# Donus: @{ Bytes; Count }
function Get-ErGapEstimate($Dk) {
    $r = @{ Bytes = [double]0; Count = 0 }
    $len = [double]$Dk.Size
    $guard = [double]1048576
    $minGap = [double]8388608
    if ($len -le ($guard * 2 + $minGap)) { return $r }
    $iv = New-Object System.Collections.ArrayList
    foreach ($pt in @($Dk.Parts)) {
        if ($null -eq $pt) { continue }
        $l = [double]$pt.Size
        if ($l -le 0) { continue }
        [void]$iv.Add(@{ S = [double]$pt.Offset; E = ([double]$pt.Offset + $l) })
    }
    $sorted = $iv.ToArray() | Sort-Object { $_.S }
    $cursor = $guard
    $limit = $len - $guard
    foreach ($x in @($sorted)) {
        if ($null -eq $x) { continue }
        if ($x.S -gt $cursor) {
            $end = [math]::Min($x.S, $limit)
            if (($end - $cursor) -ge $minGap) { $r.Bytes += ($end - $cursor); $r.Count++ }
        }
        if ($x.E -gt $cursor) { $cursor = $x.E }
    }
    if (($limit - $cursor) -ge $minGap) { $r.Bytes += ($limit - $cursor); $r.Count++ }
    return $r
}

# Bolumun Turkce tur adi (Windows'un bildirdigi tur)
function Get-ErPartTypeName([string]$Type) {
    switch (([string]$Type).Trim()) {
        'System'   { return ('EFI sistem b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + '') }
        'Reserved' { return ('Microsoft ayr' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm') }
        'Recovery' { return ('Windows kurtarma b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + '') }
        'Basic'    { return ('veri b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + '') }
        'IFS'      { return ('veri b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + '') }
        'Logical'  { return ('mant' + [char]0x0131 + 'ksal b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm') }
        'Extended' { return ('geni' + [char]0x015F + 'letilmi' + [char]0x015F + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm') }
        'XBOX'     { return ('oyun b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + '') }
    }
    return ''
}

# Disk silme bolumu icin disk ve bolum satirlari.
# Donus: @{ Number; Title; Detail; BrCol; Blocked ('' ya da neden); Gap (bayt); GapCount; Btn1; Btn2; Parts = @(@{ Number; Title; Detail; BrCol; Blocked; Btn1 }) } dizisi
function Get-ErDiskModels($Phys) {
    $out = New-Object System.Collections.ArrayList
    foreach ($dk in @($Phys)) {
        if ($null -eq $dk) { continue }
        if ([double]$dk.Size -le 0) { continue }
        $why = Test-WipeDiskAllowed $dk 'Disk'
        $gap = Get-ErGapEstimate $dk
        $parts = New-Object System.Collections.ArrayList
        $det = New-Object System.Collections.ArrayList
        $style = ([string]$dk.Style).Trim()
        if ($style -eq '' -or $style -eq 'RAW') { $style = ('b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm tablosu yok') }
        [void]$det.Add($style)
        $pcount = @($dk.Parts).Count
        if ($pcount -eq 0) { [void]$det.Add(('b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm yok')) } else { [void]$det.Add([string]$pcount + (' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm')) }
        if (@($dk.Letters).Count -gt 0) { [void]$det.Add(('s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler: ') + (@($dk.Letters) -join ', ')) }
        if ($gap.Bytes -gt 0) { [void]$det.Add(('ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan: yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + (Format-Size $gap.Bytes)) }
        $m = @{ Number = [int]$dk.Number; Title = (Get-RcDiskName $dk); Detail = ($det.ToArray() -join ('  ' + [char]0x00B7 + '  ')); BrCol = 'BrInfo'; Blocked = $why; Gap = [double]$gap.Bytes; GapCount = [int]$gap.Count
            Btn1 = ''; Btn2 = ''; Parts = @() }
        if ($why -ne '') {
            $m.Detail = $why
            $m.BrCol = 'BrWarn'
        } else {
            if ($gap.Bytes -gt 0) { $m.Btn1 = ('Ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan' + [char]0x0131 + ' sil') }
            $m.Btn2 = 'Diski tamamen sil'
            $sorted = @(@($dk.Parts) | Sort-Object { [double]$_.Offset })
            foreach ($pt in $sorted) {
                if ($null -eq $pt) { continue }
                $pwhy = Test-WipePartAllowed $dk $pt
                $t = ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ') + [string]$pt.Number
                $lbl = ([string]$pt.Label).Trim()
                if ([string]$pt.Letter -ne '') {
                    $t += ('  ' + [char]0x00B7 + '  ') + [string]$pt.Letter
                    if ($lbl -ne '') { $t += '  ' + $lbl }
                } else { $t += ('  ' + [char]0x00B7 + '  s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' harfi yok') }
                $fs = ([string]$pt.Fs).Trim()
                if ($fs -ne '') { $t += ('  ' + [char]0x00B7 + '  ') + $fs }
                $t += ('  ' + [char]0x00B7 + '  ') + (Format-Size ([double]$pt.Size))
                $tn = Get-ErPartTypeName ([string]$pt.Type)
                $pd = ''
                if ($tn -ne '') { $pd = $tn.Substring(0, 1).ToUpperInvariant() + $tn.Substring(1) + '.' }
                $pm = @{ Number = [int]$pt.Number; Title = $t; Detail = $pd; BrCol = 'BrInfo'; Blocked = $pwhy; Btn1 = ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + ' sil') }
                if ($pwhy -ne '') { $pm.Detail = $pwhy; $pm.BrCol = 'BrWarn'; $pm.Btn1 = '' }
                [void]$parts.Add($pm)
            }
            $m.Parts = $parts.ToArray()
        }
        [void]$out.Add($m)
    }
    return , $out.ToArray()
}

# Bolum ve disk silme icin islem plani (hicbir sey degistirmez). Scope: Unallocated | Partition | Disk
# Donus: @{ Ok; Why; Params; Title; Text; OkText; Expect (yazdirilacak metin; Unallocated icin bos); Bytes; Label }
function New-ErRawPlan([string]$Scope, $Dk, [int]$PartNo, $Opts) {
    $pl = @{ Ok = $false; Why = ''; Params = $null; Title = ''; Text = ''; OkText = ''; Expect = ''; Bytes = [double]0; Label = '' }
    if (@('Unallocated', 'Partition', 'Disk') -notcontains $Scope) { $pl.Why = ('Bilinmeyen silme kapsam' + [char]0x0131 + '.'); return $pl }
    if ($null -eq $Dk) { $pl.Why = ('Disk bulunamad' + [char]0x0131 + '; listeyi yenileyip yeniden deneyin.'); return $pl }
    $why = Test-WipeDiskAllowed $Dk $Scope
    if ($why -ne '') { $pl.Why = $why; return $pl }
    $part = $null
    if ($Scope -eq 'Partition') {
        foreach ($x in @($Dk.Parts)) { if ($null -ne $x -and [int]$x.Number -eq $PartNo) { $part = $x } }
        $why = Test-WipePartAllowed $Dk $part
        if ($why -ne '') { $pl.Why = $why; return $pl }
    }
    $method = Get-WipeMethodKey ([string]$Opts.Method)
    $verify = Get-WipeVerifyKey ([string]$Opts.Verify)
    $after = Get-WipeAfterKey ([string]$Opts.After)
    if ($Scope -eq 'Unallocated') { $after = 'none' }
    $bytes = [double]$Dk.Size
    if ($Scope -eq 'Partition') { $bytes = [double]$part.Size }
    if ($Scope -eq 'Unallocated') {
        $bytes = [double](Get-ErGapEstimate $Dk).Bytes
        if ($bytes -le 0) { $pl.Why = ('Bu diskte silinecek ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan yok.'); return $pl }
    }
    if ($after -eq 'fat32' -and $Scope -ne 'Unallocated' -and $bytes -gt [double]34359738368) {
        $pl.Why = ('FAT32 yaln' + [char]0x0131 + 'zca 32 GB boyuta kadar bi' + [char]0x00E7 + 'imlenebilir; ' + [char]0x201C + 'Sonra' + [char]0x201D + ' se' + [char]0x00E7 + 'ene' + [char]0x011F + 'inde NTFS ya da exFAT se' + [char]0x00E7 + 'in.')
        return $pl
    }
    $exp = Get-WipeExpect $Dk
    if ($null -ne $part) { $exp.PartOffset = [double]$part.Offset; $exp.PartSize = [double]$part.Size }
    $pn = 0
    if ($null -ne $part) { $pn = [int]$part.Number }
    $pl.Params = @{ Scope = $Scope; Disk = [int]$Dk.Number; Part = $pn; Expect = $exp; Method = $method; Verify = $verify; After = $after }
    $pl.Bytes = $bytes
    $modes = Get-WipeModes $method
    $est = Get-WipeEstimate $bytes $modes.Count $verify ([string]$Dk.Bus) ([string]$Dk.Media)
    $nm = 'Disk ' + [string]$Dk.Number
    $dn = ([string]$Dk.Name).Trim()
    if ($dn -ne '') { $nm += '  ' + $dn }
    $letters = (@($Dk.Letters) -join ', ')
    $lines = New-Object System.Collections.ArrayList
    if ($Scope -eq 'Disk') {
        $head = $nm + ' (' + (Format-Size ([double]$Dk.Size)) + ') tamamen silinecek.'
        $l1 = ('' + [char]0x2022 + '  Diskteki t' + [char]0x00FC + 'm b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve disk ba' + [char]0x015F + 'tan sona ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r')
        if ($letters -ne '') { $l1 += ' (' + $letters + ')' }
        [void]$lines.Add($l1 + ('. Geri getirilemez; kurtarma programlar' + [char]0x0131 + ' da bulamaz.'))
        $pl.Expect = 'Disk ' + [string]$Dk.Number
        $pl.Title = 'Diski tamamen sil'
        $pl.OkText = 'Diski sil'
        $pl.Label = 'Disk ' + [string]$Dk.Number + ' siliniyor'
    } elseif ($Scope -eq 'Partition') {
        $pt = ('b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ') + [string]$part.Number
        if ([string]$part.Letter -ne '') { $pt += ' (' + [string]$part.Letter + ')' }
        $head = 'Disk ' + [string]$Dk.Number + (' ' + [char]0x00FC + 'zerindeki ') + $pt + ' (' + (Format-Size ([double]$part.Size)) + ') silinecek.'
        [void]$lines.Add(('' + [char]0x2022 + '  B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mdeki t' + [char]0x00FC + 'm dosyalar kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve alan ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r. Geri getirilemez. Diskin di' + [char]0x011F + 'er b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mlerine dokunulmaz.'))
        $pl.Expect = 'Disk ' + [string]$Dk.Number + (' B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ') + [string]$part.Number
        $pl.Title = ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + ' sil')
        $pl.OkText = ('B' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + ' sil')
        $pl.Label = 'Disk ' + [string]$Dk.Number + (' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ') + [string]$part.Number + ' siliniyor'
    } else {
        $head = $nm + (': b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mlerin d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda kalan bo' + [char]0x015F + ' alan (yakla' + [char]0x015F + '' + [char]0x0131 + 'k ') + (Format-Size $bytes) + (') ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lacak.')
        [void]$lines.Add(('' + [char]0x2022 + '  Mevcut b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mlere ve dosyalara dokunulmaz; yaln' + [char]0x0131 + 'zca daha ' + [char]0x00F6 + 'nce silinmi' + [char]0x015F + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'mlerden artakalan alan yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r. Diskin ba' + [char]0x015F + '' + [char]0x0131 + 'ndaki ve sonundaki 1 MB korunur.'))
        $pl.Title = ('Ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan' + [char]0x0131 + ' sil')
        $pl.OkText = 'Sil'
        $pl.Label = 'Disk ' + [string]$Dk.Number + (' ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan siliniyor')
        if (@($Dk.Parts).Count -eq 0) {
            # bolum yoksa tum disk ayrilmamis sayilir; bolumler yanlislikla kaybolmus olabilir, bu yuzden adi yazdirilir
            $pl.Expect = 'Disk ' + [string]$Dk.Number
            $pl.Title = ('Diski ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan olarak sil')
            [void]$lines.Add(('' + [char]0x2022 + '  Diskte hi' + [char]0x00E7 + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor, bu y' + [char]0x00FC + 'zden t' + [char]0x00FC + 'm disk ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' say' + [char]0x0131 + 'l' + [char]0x0131 + 'r. B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mleri yanl' + [char]0x0131 + '' + [char]0x015F + 'l' + [char]0x0131 + 'kla kaybettiyseniz ' + [char]0x00F6 + 'nce Silinen dosyalar sekmesinde bu diski tarat' + [char]0x0131 + 'n; bu i' + [char]0x015F + 'lem i' + [char]0x00E7 + 'eri' + [char]0x011F + 'i geri getirilemez bi' + [char]0x00E7 + 'imde siler.'))
        }
    }
    [void]$lines.Add(('' + [char]0x2022 + '  Y' + [char]0x00F6 + 'ntem: ') + (Get-WipeMethodName $method) + ('; do' + [char]0x011F + 'rulama: ') + (Get-WipeVerifyName $verify) + '.')
    if ($Scope -ne 'Unallocated') { [void]$lines.Add(('' + [char]0x2022 + '  Sonunda: ') + (Get-WipeAfterName $after) + '.') }
    [void]$lines.Add(('' + [char]0x2022 + '  Tahmini s' + [char]0x00FC + 're: ') + $est.Text + ('. ' + [char]0x0130 + 'stedi' + [char]0x011F + 'iniz an iptal edebilirsiniz.'))
    if ($Scope -ne 'Unallocated') { [void]$lines.Add(('' + [char]0x2022 + '  ' + [char]0x0130 + '' + [char]0x015F + 'lem s' + [char]0x0131 + 'ras' + [char]0x0131 + 'nda diski ya da USB belle' + [char]0x011F + 'i ' + [char]0x00E7 + '' + [char]0x0131 + 'karmay' + [char]0x0131 + 'n. ' + [char]0x0130 + 'ptal ederseniz alan yar' + [char]0x0131 + 'm silinmi' + [char]0x015F + ' kal' + [char]0x0131 + 'r.')) }
    $txt = $head + "`r`n`r`n" + ($lines.ToArray() -join "`r`n")
    if ([string]$Dk.Media -eq 'SSD' -or [string]$Dk.Bus -eq 'USB') {
        $txt += "`r`n`r`n" + ('Not: SSD ve USB belleklerde denetleyici veriyi ba' + [char]0x015F + 'ka h' + [char]0x00FC + 'crelere ta' + [char]0x015F + '' + [char]0x0131 + 'yabilir; ' + [char]0x00FC + 'zerine yazma bu y' + [char]0x00FC + 'zden tam g' + [char]0x00FC + 'vence vermez (NIST SP 800-88 ' + [char]0x201C + 'Clear' + [char]0x201D + ' d' + [char]0x00FC + 'zeyi). Cihaz elden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'lacaksa ' + [char]0x00FC + 'reticinin g' + [char]0x00FC + 'venli silme arac' + [char]0x0131 + 'n' + [char]0x0131 + ' ya da ' + [char]0x015F + 'ifreleme kullan' + [char]0x0131 + 'n.')
    }
    $pl.Text = $txt
    $pl.Ok = $true
    return $pl
}

# Islem sonucu satiri: @{ Title; Detail; BrCol; Toast }. Kind: Free (varsayilan) | Raw | Trim
function Get-ErResultModel($R) {
    $kind = [string](Get-JsonProp $R 'Kind')
    if ($kind -eq 'Raw') { return (Get-ErRawResultModel $R) }
    if ($kind -eq 'Trim') { return (Get-ErTrimResultModel $R) }
    return (Get-ErFreeResultModel $R)
}

function Get-ErFreeResultModel($R) {
    $drv = [string](Get-JsonProp $R 'Drive')
    $written = [double](Get-JsonProp $R 'Written')
    if ($R.Ok -eq $true) {
        $det = (Format-Size $written) + (' ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'ld' + [char]0x0131 + '')
        $mk = [string](Get-JsonProp $R 'Method')
        if ($mk -ne '') { $det += ' (' + (Get-WipeMethodName $mk) + ')' }
        $det += ('. S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'deki silinmi' + [char]0x015F + ' dosya kal' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' art' + [char]0x0131 + 'k kurtarma programlar' + [char]0x0131 + 'yla bulunamaz.')
        $br = 'BrGood'
        $vd = Get-JsonProp $R 'Verdict'
        if ($null -ne $vd) {
            $det += ' ' + [string]$vd.Text
            if ([string]$vd.Level -eq 'warn') { $br = 'BrWarn' }
        }
        $tr = Get-JsonProp $R 'Trim'
        if ($null -ne $tr) {
            if ($tr.Ok -eq $true) { $det += (' Silinen alanlar s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye bildirildi (TRIM).') } else { $det += (' TRIM g' + [char]0x00F6 + 'nderilemedi: ') + [string]$tr.Error }
        }
        $ttl = $drv + (' bo' + [char]0x015F + ' alan' + [char]0x0131 + ' temizlendi')
        return @{ Title = $ttl; Detail = $det; BrCol = $br; Toast = ($ttl + ' (' + (Format-Size $written) + ').') }
    }
    if ($R.Canceled -eq $true) {
        $ttl = $drv + (' bo' + [char]0x015F + ' alan temizleme iptal edildi')
        $det = (Format-Size $written) + (' ' + [char]0x00FC + 'zerine yaz' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '; ge' + [char]0x00E7 + 'ici dosyalar silindi.')
        return @{ Title = $ttl; Detail = $det; BrCol = 'BrWarn'; Toast = ($ttl + '. ' + $det) }
    }
    $m = [string](Get-JsonProp $R 'Error')
    if ($m -eq '') { $m = ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') }
    $ttl = $drv + (' bo' + [char]0x015F + ' alan temizlenemedi')
    return @{ Title = $ttl; Detail = $m; BrCol = 'BrBad'; Toast = ($ttl + '. ' + $m) }
}

function Get-ErTrimResultModel($R) {
    $drv = [string](Get-JsonProp $R 'Drive')
    if ($R.Ok -eq $true) {
        $det = ('Silinen alanlar s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ye bildirildi; SSD bunlar' + [char]0x0131 + ' arka planda bo' + [char]0x015F + 'alt' + [char]0x0131 + 'r.')
        $nt = [string](Get-JsonProp $R 'Note')
        if ($nt -ne '') { $det += ' ' + $nt }
        $ttl = $drv + (' i' + [char]0x00E7 + 'in TRIM g' + [char]0x00F6 + 'nderildi')
        return @{ Title = $ttl; Detail = $det; BrCol = 'BrGood'; Toast = ($ttl + '.') }
    }
    $m = [string](Get-JsonProp $R 'Error')
    if ($m -eq '') { $m = ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') }
    $ttl = $drv + (' i' + [char]0x00E7 + 'in TRIM g' + [char]0x00F6 + 'nderilemedi')
    return @{ Title = $ttl; Detail = $m; BrCol = 'BrBad'; Toast = ($ttl + '. ' + $m) }
}

function Get-ErRawResultModel($R) {
    $scope = [string](Get-JsonProp $R 'Scope')
    $no = [int](Get-JsonProp $R 'Disk')
    $what = 'Disk ' + [string]$no
    if ($no -lt 0) { $what = ('Disk imaj' + [char]0x0131 + '') }
    $nm = ([string](Get-JsonProp $R 'Name')).Trim()
    if ($scope -eq 'Partition') { $what += (' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ') + [string](Get-JsonProp $R 'Part') }
    elseif ($scope -eq 'Unallocated') { $what += (' ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan' + [char]0x0131 + '') }
    elseif ($nm -ne '') { $what += '  ' + $nm }
    $written = [double](Get-JsonProp $R 'Written')
    $notes = @(@(Get-JsonProp $R 'Notes') | Where-Object { $null -ne $_ -and [string]$_ -ne '' })
    if ($R.Nothing -eq $true) {
        $det = ('Silinecek ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan bulunamad' + [char]0x0131 + '.')
        if ($notes.Count -gt 0) { $det = [string]$notes[0] }
        return @{ Title = ($what + (': yap' + [char]0x0131 + 'lacak bir ' + [char]0x015F + 'ey yok')); Detail = $det; BrCol = 'BrInfo'; Toast = ($what + ': ' + $det) }
    }
    if ($R.Ok -eq $true) {
        $mk = [string](Get-JsonProp $R 'Method')
        $det = (Format-Size $written) + (' yaz' + [char]0x0131 + 'ld' + [char]0x0131 + '')
        if ($mk -ne '') { $det += ' (' + (Get-WipeMethodName $mk) + ')' }
        $det += '.'
        $vk = [string](Get-JsonProp $R 'VerifyKind')
        if ($vk -ne '') { $det += (' Do' + [char]0x011F + 'rulama: ') + (Format-Size ([double](Get-JsonProp $R 'Verified'))) + (' ayg' + [char]0x0131 + 'ttan geri okundu, fark yok.') }
        else { $det += (' Do' + [char]0x011F + 'rulama yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '.') }
        $ad = [string](Get-JsonProp $R 'AfterDone')
        if ($ad -ne '') {
            $det += ' ' + $ad.Substring(0, 1).ToUpperInvariant() + $ad.Substring(1) + '.'
            $lt = [string](Get-JsonProp $R 'Letter')
            if ($lt -ne '') { $det += (' Yeni s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ': ') + $lt }
        }
        $sec = [double](Get-JsonProp $R 'Seconds')
        if ($sec -gt 0) { $det += (' S' + [char]0x00FC + 're: ') + (Format-Duration $sec) + '.' }
        $br = 'BrGood'
        foreach ($n in $notes) { $det += ' ' + [string]$n; $br = 'BrWarn' }
        $ttl = $what + ' silindi'
        return @{ Title = $ttl; Detail = $det; BrCol = $br; Toast = ($ttl + ' (' + (Format-Size $written) + ').') }
    }
    if ($R.Canceled -eq $true) {
        $ttl = $what + ' silme iptal edildi'
        $det = (Format-Size $written) + (' yaz' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '.')
        if ($R.Started -eq $true) { $det += (' B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler zaten kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '; alan yar' + [char]0x0131 + 'm silinmi' + [char]0x015F + ' durumda. Gerekirse i' + [char]0x015F + 'lemi yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') }
        return @{ Title = $ttl; Detail = $det; BrCol = 'BrWarn'; Toast = ($ttl + '. ' + $det) }
    }
    $m = [string](Get-JsonProp $R 'Error')
    if ($m -eq '') { $m = ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') }
    $det = $m
    if ($R.Started -eq $true) { $det += (' B' + [char]0x00F6 + 'l' + [char]0x00FC + 'mler kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '; alan tamamen silinmemi' + [char]0x015F + ' olabilir, i' + [char]0x015F + 'lemi yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') }
    $ttl = $what + ' silinemedi'
    return @{ Title = $ttl; Detail = $det; BrCol = 'BrBad'; Toast = ($ttl + '. ' + $det) }
}

# Dosya ve klasor silme sonucu (Araclar sayfasi ve bu sekme ortak kullanir): @{ Text; Kind (good | warn | info); Warnings }
function Get-ErSecureResultModel($R) {
    $files = [int](Get-JsonProp $R 'Files')
    $failed = [int](Get-JsonProp $R 'Failed')
    $skipped = [int](Get-JsonProp $R 'Skipped')
    $bytes = [double](Get-JsonProp $R 'Bytes')
    $passes = [int](Get-JsonProp $R 'Passes')
    $warn = @(@(Get-JsonProp $R 'Warnings') | Where-Object { $null -ne $_ -and [string]$_ -ne '' })
    if ($files -eq 0 -and $failed -eq 0 -and $skipped -eq 0) { return @{ Text = ('Silinecek dosya bulunamad' + [char]0x0131 + '.'); Kind = 'info'; Warnings = $warn } }
    $t = [string]$files + (' dosya kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silindi (') + (Format-Size $bytes) + ')'
    if ($passes -gt 1) { $t += ', ' + [string]$passes + (' ge' + [char]0x00E7 + 'i' + [char]0x015F + '') }
    $t += '.'
    $kind = 'good'
    if ($skipped -gt 0) { $t += ' ' + [string]$skipped + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e atland' + [char]0x0131 + ' (bulutta duran dosya).'); $kind = 'warn' }
    if ($failed -gt 0) { $t += ' ' + [string]$failed + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e silinemedi; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.'); $kind = 'warn' }
    return @{ Text = $t; Kind = $kind; Warnings = $warn }
}

function Show-SecureDeleteResult($R) {
    $m = Get-ErSecureResultModel $R
    Show-Toast ([string]$m.Text) ([string]$m.Kind)
    if (@($m.Warnings).Count -gt 0) {
        $lines = New-Object System.Collections.ArrayList
        foreach ($w in @($m.Warnings)) { [void]$lines.Add(('' + [char]0x2022 + '  ') + [string]$w) }
        Show-Message ('' + [char]0x00DC + 'zerine yazma garantisi s' + [char]0x0131 + 'n' + [char]0x0131 + 'rl' + [char]0x0131 + '') (($lines.ToArray() -join "`r`n") + "`r`n`r`n" + ('Bu dosyalar' + [char]0x0131 + 'n eski kopyalar' + [char]0x0131 + ' diskte kalm' + [char]0x0131 + '' + [char]0x015F + ' olabilir. S' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'n' + [char]0x00FC + 'n bo' + [char]0x015F + ' alan' + [char]0x0131 + 'n' + [char]0x0131 + ' temizleyin (' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi > Kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silme > Bo' + [char]0x015F + ' alan' + [char]0x0131 + ' temizle) ya da diski ' + [char]0x015F + 'ifreleyin.'))
    }
}

# Sonuctan sonra "Kurtarma motoruyla dene" icin kaynak anahtari ('' = gosterme)
function Get-ErRecoverKey($R) {
    if ($null -eq $R) { return '' }
    $kind = [string](Get-JsonProp $R 'Kind')
    if ($kind -eq 'Trim') { return '' }
    if ([double](Get-JsonProp $R 'Written') -le 0) { return '' }
    if ($kind -eq 'Raw') {
        $n = [int](Get-JsonProp $R 'Disk')
        if ($n -lt 0) { return '' }
        return ('PD:' + [string]$n + ':all')
    }
    $d = ([string](Get-JsonProp $R 'Drive')).Trim()
    if ($d -cmatch '^[A-Za-z]:') { return ($d.Substring(0, 1).ToUpperInvariant() + ':') }
    return ''
}

# ---------------- cizim ----------------
$script:H_ErAct = { param($s, $e) Invoke-Safe { Invoke-ErAction $s.Tag } 'Eylem' }

function Invoke-ErAction($T) {
    switch ([string]$T.Do) {
        'ErFree'    { Start-ErFree $T }
        'ErTrim'    { Start-ErTrim $T }
        'ErGap'     { Start-ErRaw 'Unallocated' ([int]$T.Disk) 0 }
        'ErPart'    { Start-ErRaw 'Partition' ([int]$T.Disk) ([int]$T.Part) }
        'ErDisk'    { Start-ErRaw 'Disk' ([int]$T.Disk) 0 }
        'ErRecover' {
            if ([string]$T.Key -ne '') {
                $script:RcSelKey = [string]$T.Key
                if (-not (Select-TabChip 'sl' 'recover')) { Set-SlTab 'recover' }
            }
        }
    }
}

function Add-ErRow($Model, $Data) {
    $row = New-ItemRow $Model $Data $false $false
    if ([string]$Model.Btn1 -ne '') { $row.FindName('Act').Add_Click($script:H_ErAct) }
    if ([string]$Model.Btn2 -ne '') { $row.FindName('Act2').Add_Click($script:H_ErAct) }
    [void]$ui.sl_List.Children.Add($row)
    return $row
}

function Render-SlErase {
    $ui.sl_List.Children.Clear()
    if ($null -ne $script:ErLast) {
        $m = Get-ErResultModel $script:ErLast
        $key = Get-ErRecoverKey $script:ErLast
        $b1 = ''
        if ($key -ne '') { $b1 = 'Kurtarma motoruyla dene' }
        [void](Add-ErRow @{ Title = $m.Title; Detail = $m.Detail; BrCol = $m.BrCol; Btn1 = $b1 } @{ Do = 'ErRecover'; Key = $key })
    }
    Add-HeadRow $ui.sl_List ('Dosya ve klas' + [char]0x00F6 + 'rleri kal' + [char]0x0131 + 'c' + [char]0x0131 + ' sil')
    Add-Note $ui.sl_List ('Normal silme dosyay' + [char]0x0131 + ' yaln' + [char]0x0131 + 'zca listeden kald' + [char]0x0131 + 'r' + [char]0x0131 + 'r; i' + [char]0x00E7 + 'eri' + [char]0x011F + 'i diskte kal' + [char]0x0131 + 'r ve kurtarma programlar' + [char]0x0131 + ' geri getirebilir. Kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silme ' + [char]0x00F6 + 'nce dosyan' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine rastgele veri yazar (ge' + [char]0x00E7 + 'i' + [char]0x015F + ' say' + [char]0x0131 + 's' + [char]0x0131 + ' Ayarlar' + [char]0x2019 + 'dan se' + [char]0x00E7 + 'ilir), sonra siler. Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na gitmez ve geri getirilemez. K' + [char]0x0131 + 'sayol noktalar' + [char]0x0131 + ' izlenmez, bulutta duran dosyalar atlan' + [char]0x0131 + 'r. Yukar' + [char]0x0131 + 'daki d' + [char]0x00FC + '' + [char]0x011F + 'melerle bir dosya ya da klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in; silmeden ' + [char]0x00F6 + 'nce ne olaca' + [char]0x011F + '' + [char]0x0131 + ' yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve onay' + [char]0x0131 + 'n' + [char]0x0131 + 'z istenir.')
