    if ($script:IsAdmin -ne $true) { Add-Note $ui.sl_List ('Multimizer y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'm' + [char]0x0131 + 'yor; disk, b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ve ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan silmek i' + [char]0x00E7 + 'in y' + [char]0x00F6 + 'netici olarak yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') 'warn' }
    $dm = Get-ErDiskModels @($script:SlDisks.Phys)
