    }
    foreach ($d in $dm) {
        $dmodel = @{ Title = [string]$d.Title; Detail = [string]$d.Detail; BrCol = [string]$d.BrCol; Btn1 = [string]$d.Btn1; Btn2 = [string]$d.Btn2 }
        $drow = New-ItemRow $dmodel @{ Do = 'ErGap'; Disk = [int]$d.Number } $false $false
        if ($d.Btn1 -ne '') { $drow.FindName('Act').Add_Click($script:H_ErAct) }
        if ($d.Btn2 -ne '') {
            $drow.FindName('Act2').Tag = @{ Do = 'ErDisk'; Disk = [int]$d.Number }
            $drow.FindName('Act2').Add_Click($script:H_ErAct)
        }
        [void]$ui.sl_List.Children.Add($drow)
        foreach ($p in @($d.Parts)) {
            $pm = @{ Title = ('      ' + [string]$p.Title); Detail = [string]$p.Detail; BrCol = [string]$p.BrCol; Btn1 = [string]$p.Btn1 }
            $prow = New-ItemRow $pm @{ Do = 'ErPart'; Disk = [int]$d.Number; Part = [int]$p.Number } $false $false
            if ($p.Btn1 -ne '') { $prow.FindName('Act').Add_Click($script:H_ErAct) }
            [void]$ui.sl_List.Children.Add($prow)
        }
    }

    Add-HeadRow $ui.sl_List 'Bilmeniz gerekenler'
    Add-Note $ui.sl_List ('' + [char]0x00DC + 'zerine yazma, silinen verinin kurtarma programlar' + [char]0x0131 + 'yla geri getirilmesini engeller. SSD ve USB belleklerde denetleyici veriyi ba' + [char]0x015F + 'ka h' + [char]0x00FC + 'crelere ta' + [char]0x015F + '' + [char]0x0131 + 'yabildi' + [char]0x011F + 'i i' + [char]0x00E7 + 'in bu y' + [char]0x00F6 + 'ntem NIST SP 800-88 Rev.1 s' + [char]0x0131 + 'n' + [char]0x0131 + 'fland' + [char]0x0131 + 'rmas' + [char]0x0131 + 'nda ' + [char]0x201C + 'Clear' + [char]0x201D + ' d' + [char]0x00FC + 'zeyindedir; cihaz elden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'lacaksa ' + [char]0x00FC + 'reticinin g' + [char]0x00FC + 'venli silme arac' + [char]0x0131 + ' ya da ' + [char]0x015F + 'ifreleme ve anahtar silme daha g' + [char]0x00FC + 'venlidir. Bir standart i' + [char]0x00E7 + 'in belgelendirme iddias' + [char]0x0131 + ' yoktur.')
    Add-Note $ui.sl_List ('Yedekler, g' + [char]0x00F6 + 'lge kopyalar (geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + '), OneDrive gibi bulut e' + [char]0x015F + 'le' + [char]0x015F + 'meleri ve dosya ad' + [char]0x0131 + ' kay' + [char]0x0131 + 'tlar' + [char]0x0131 + ' bu y' + [char]0x00F6 + 'ntemle silinmez. Windows' + [char]0x2019 + 'un ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ', Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n ya da ge' + [char]0x00E7 + 'ici dosyalar' + [char]0x0131 + 'n bulundu' + [char]0x011F + 'u diske do' + [char]0x011F + 'rudan yaz' + [char]0x0131 + 'lmaz (yaln' + [char]0x0131 + 'zca o s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'lerin bo' + [char]0x015F + ' alan' + [char]0x0131 + ' temizlenir); ' + [char]0x00E7 + 'evrimd' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ', salt okunur ve depolama havuzu ' + [char]0x00FC + 'yesi disklere dokunulmaz.')
    Add-Note $ui.sl_List ('Her i' + [char]0x015F + 'lemden sonra ' + [char]0x201C + 'Kurtarma motoruyla dene' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesi, ayn' + [char]0x0131 + ' kayna' + [char]0x011F + '' + [char]0x0131 + ' Silinen dosyalar sekmesinde tarat' + [char]0x0131 + 'p sonucu s' + [char]0x0131 + 'naman' + [char]0x0131 + 'z' + [char]0x0131 + ' sa' + [char]0x011F + 'lar.')
    $ui.sl_Foot.Text = (Tr $(('Kal' + [char]0x0131 + 'c' + [char]0x0131 + ' silme geri al' + [char]0x0131 + 'namaz. Windows Update, Defender ve G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + '' + [char]0x2019 + 'na dokunulmaz.')))
}

# ---------------- islemler ----------------
# Elle yazdirilan onay: kutuya beklenen metin yazilmadikca islem baslamaz. Pencere kapandiktan sonra cagrildigi icin
# eslesmezse yalnizca bildirim verir; kullanici dugmeye yeniden basar.
function Show-TypedConfirm([string]$Title, [string]$Text, [string]$OkText, [string]$Expect, [scriptblock]$OnOk) {
    $script:ErTypedExpect = $Expect
    $script:ErTypedAct = $OnOk
    $full = $Text + "`r`n`r`n" + ('Onaylamak i' + [char]0x00E7 + 'in kutuya ' + [char]0x015F + 'unu yaz' + [char]0x0131 + 'n:  ') + $Expect
    Show-Overlay $Title $full $OkText $true $true $true '' {
        param($typed)
        if (-not (Test-WipeTyped ([string]$typed) $script:ErTypedExpect)) {
            Show-Toast ('Yazd' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z metin e' + [char]0x015F + 'le' + [char]0x015F + 'medi; hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silinmedi.') 'warn'
            return
        }
        $act = $script:ErTypedAct
        $script:ErTypedAct = $null
        if ($null -ne $act) { & $act }
    }
}

function Find-ErDisk([int]$No) {
    $d = $script:SlDisks
    if ($null -eq $d -or $d.Failed -eq $true -or $null -eq $d.Phys) { return $null }
    foreach ($x in @($d.Phys)) { if ($null -ne $x -and [int]$x.Number -eq $No) { return $x } }
    return $null
}

function Start-ErFree($T) {
    $ep = Get-ExtProblem 'DiskSilme'
    if ($ep -ne '') { Show-Message ('Bo' + [char]0x015F + ' alan temizleme kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') $ep; return }
    $o = Get-ErOptions
    $script:ErPendDrive = [string]$T.Drive
    $script:ErPend = @{ Kind = 'Free'; Drive = [string]$T.Drive; Method = [string]$o.Method; Verify = [string]$o.Verify; Trim = ($T.Trim -eq $true) }
    Show-Confirm ('Bo' + [char]0x015F + ' alan' + [char]0x0131 + ' temizle') (Get-ErFreeConfirmText $T $o) 'Temizle' {
        $p = $script:ErPend
        [void](Start-Async 'WipeFree' 'Job_WipeFree' @{ Drive = [string]$p.Drive; Method = [string]$p.Method; Canary = ([string]$p.Verify -ne 'none'); Trim = ($p.Trim -eq $true) } {
            param($r)
            Complete-ErFree $r
        } ([string]$p.Drive + (' bo' + [char]0x015F + ' alan' + [char]0x0131 + ' temizleniyor')))
    }
}

function Start-ErTrim($T) {
    $ep = Get-ExtProblem 'DiskSilme'
    if ($ep -ne '') { Show-Message ('TRIM kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') $ep; return }
    $script:ErPendDrive = [string]$T.Drive
    $script:ErPend = @{ Kind = 'Trim'; Drive = [string]$T.Drive }
    $txt = [string]$T.Drive + (' s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' i' + [char]0x00E7 + 'in silinmi' + [char]0x015F + ' alanlar' + [char]0x0131 + 'n SSD' + [char]0x2019 + 'ye bildirilmesi (TRIM) istenecek.') + "`r`n`r`n" + ('' + [char]0x2022 + '  Hi' + [char]0x00E7 + 'bir dosyaya dokunulmaz; Windows zaten silinen alanlar' + [char]0x0131 + ' bildirir, bu i' + [char]0x015F + 'lem bekleyen bildirimleri hemen g' + [char]0x00F6 + 'nderir.') + "`r`n" + ('' + [char]0x2022 + '  S' + [char]0x00FC + 're s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' boyutuna g' + [char]0x00F6 + 're saniyelerden dakikalara uzayabilir.')
    Show-Confirm ('TRIM g' + [char]0x00F6 + 'nder') $txt ('G' + [char]0x00F6 + 'nder') {
        $p = $script:ErPend
        [void](Start-Async 'WipeTrim' 'Job_TrimVolume' @{ Drive = [string]$p.Drive } {
            param($r)
            Complete-ErTrim $r
        } ([string]$p.Drive + (' i' + [char]0x00E7 + 'in TRIM g' + [char]0x00F6 + 'nderiliyor')))
    }
}

function Start-ErRaw([string]$Scope, [int]$DiskNo, [int]$PartNo) {
    $ep = Get-ExtProblem 'DiskSilme'
    if ($ep -ne '') { Show-Message ('Disk silme kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') $ep; return }
    if ($script:IsAdmin -ne $true) {
        Show-Message ('Y' + [char]0x00F6 + 'netici izni gerekli') ('Disk, b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ve ayr' + [char]0x0131 + 'lmam' + [char]0x0131 + '' + [char]0x015F + ' alan silmek i' + [char]0x00E7 + 'in Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n y' + [char]0x00F6 + 'netici olarak ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' gerekir. Uygulamay' + [char]0x0131 + ' y' + [char]0x00F6 + 'netici olarak yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.')
        return
    }
    $pl = New-ErRawPlan $Scope (Find-ErDisk $DiskNo) $PartNo (Get-ErOptions)
    if (-not $pl.Ok) { Show-Message ('Bu i' + [char]0x015F + 'lem yap' + [char]0x0131 + 'lamaz') ([string]$pl.Why); return }
    $script:ErPend = @{ Kind = 'Raw'; Scope = $Scope; Params = $pl.Params; Label = [string]$pl.Label; Disk = $DiskNo }
    if ([string]$pl.Expect -ne '') {
        Show-TypedConfirm ([string]$pl.Title) ([string]$pl.Text) ([string]$pl.OkText) ([string]$pl.Expect) { Invoke-ErRawJob }
    } else {
        Show-Confirm ([string]$pl.Title) ([string]$pl.Text) ([string]$pl.OkText) { Invoke-ErRawJob } $true
    }
}

function Invoke-ErRawJob {
    $p = $script:ErPend
    if ($null -eq $p -or [string]$p.Kind -ne 'Raw') { return }
    [void](Start-Async 'WipeRaw' 'Job_WipeRaw' $p.Params {
        param($r)
        Complete-ErRaw $r
    } ([string]$p.Label))
}

# Ortak sonuc isleyici
function Complete-ErResult($R, [string]$Kind) {
    $drive = $script:ErPendDrive
    $scope = ''
    $disk = -1
    if ($null -ne $script:ErPend) {
        if ($null -ne $script:ErPend.Scope) { $scope = [string]$script:ErPend.Scope }
        if ($null -ne $script:ErPend.Disk) { $disk = [int]$script:ErPend.Disk }
    }
    if ($null -eq $R) {
        $R = @{ Ok = $false; Kind = $Kind; Drive = $drive; Scope = $scope; Disk = $disk; Written = 0; Canceled = $false; Error = ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') }
    } elseif ($null -ne $R.ExtError) {
        $R = @{ Ok = $false; Kind = $Kind; Drive = $drive; Scope = $scope; Disk = $disk; Written = 0; Canceled = $false; Error = [string]$R.ExtError }
    }
    $script:ErLast = $R
    $m = Get-ErResultModel $R
    $kindT = 'bad'
    if ($R.Ok -eq $true) { $kindT = 'good' } elseif ($R.Canceled -eq $true) { $kindT = 'warn' }
    if ($R.Nothing -eq $true) { $kindT = 'info' }
    Show-Toast ([string]$m.Toast) $kindT
    $script:SlDisks = $null
    # bolumler degistiyse kurtarma sekmesinin onbellegindeki bolum bilgileri gecersizdir
    try {
        if ($null -ne $script:RcPartCache) {
            foreach ($ck in @($script:RcPartCache.Keys)) { if ([string]$ck -like 'PhysicalDrive*') { $script:RcPartCache.Remove($ck) } }
        }
    } catch { }
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'erase') { Render-SlErase }
}

function Complete-ErFree($R) { Complete-ErResult $R 'Free' }
function Complete-ErTrim($R) { Complete-ErResult $R 'Trim' }
function Complete-ErRaw($R) { Complete-ErResult $R 'Raw' }

function Select-ErOption([string]$Which) {
    if ($script:ErLoading -eq $true) { return }
    $combo = $ui.sl_ErMethod
    if ($Which -eq 'Verify') { $combo = $ui.sl_ErVerify } elseif ($Which -eq 'After') { $combo = $ui.sl_ErAfter }
    $k = Get-ComboKey $combo
    if ($k -eq '') { return }
    $script:ErOpts[$Which] = $k
}

function Init-SlErase {
    $ui.sl_ErFile.Add_Click({ Invoke-Safe { Start-TlWipe $false } ('Dosyay' + [char]0x0131 + ' kal' + [char]0x0131 + 'c' + [char]0x0131 + ' sil') })
    $ui.sl_ErFolder.Add_Click({ Invoke-Safe { Start-TlWipe $true } ('Klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' kal' + [char]0x0131 + 'c' + [char]0x0131 + ' sil') })
    $ui.sl_ErRefresh.Add_Click({ Invoke-Safe { $script:SlDisks = $null; Render-SlErase } 'Diskleri yenile' })
    $script:ErLoading = $true
    try {
        $ml = Get-WipeMethodList
        $c1 = New-Object System.Collections.ArrayList
        foreach ($x in $ml) { [void]$c1.Add((New-Choice ([string]$x.Key) ([string]$x.Name))) }
        Set-ComboChoices $ui.sl_ErMethod $c1.ToArray()
        [void](Select-ComboKey $ui.sl_ErMethod ([string]$script:ErOpts.Method))
        $vl = Get-WipeVerifyList
        $c2 = New-Object System.Collections.ArrayList
        foreach ($x in $vl) { [void]$c2.Add((New-Choice ([string]$x.Key) ([string]$x.Name))) }
        Set-ComboChoices $ui.sl_ErVerify $c2.ToArray()
        [void](Select-ComboKey $ui.sl_ErVerify ([string]$script:ErOpts.Verify))
        $al = Get-WipeAfterList
        $c3 = New-Object System.Collections.ArrayList
        foreach ($x in $al) { [void]$c3.Add((New-Choice ([string]$x.Key) ([string]$x.Name))) }
        Set-ComboChoices $ui.sl_ErAfter $c3.ToArray()
        [void](Select-ComboKey $ui.sl_ErAfter ([string]$script:ErOpts.After))
    } finally { $script:ErLoading = $false }
    $ui.sl_ErMethod.Add_SelectionChanged({ Invoke-Safe { Select-ErOption 'Method' } ('Silme y' + [char]0x00F6 + 'ntemi') })
    $ui.sl_ErVerify.Add_SelectionChanged({ Invoke-Safe { Select-ErOption 'Verify' } ('Silme do' + [char]0x011F + 'rulamas' + [char]0x0131 + '') })
    $ui.sl_ErAfter.Add_SelectionChanged({ Invoke-Safe { Select-ErOption 'After' } ('Silme sonras' + [char]0x0131 + '') })
}

# ---------------- cozum merkezi: bilgisayarim sekmesi ----------------
# ==================================================================
#  COZUM MERKEZI: "Bilgisayarim" sekmesi
#  Bilgisayari tanir: model, Windows, islemci, bellek, ekran karti, diskler, ag, pil ve guvenlik donanimi. Bilgileri yalnizca okur, hicbir ayari degistirmez; Gozlemler altindaki dugmeler (yeniden baslatma, UEFI ayarina yeniden baslatma, aygitlari yeniden tarama) yalnizca onayla calisir.
#  Kullanici kipinde sade ozet, Uzman kipinde ham ayrintilar gosterilir. Altta "Gozlemler" bolumu bulunanlara gore ne yapilabilecegini soyler.
#  Toplama (Get-PcInfo) arka plan isinde calisir; yorumlama islevleri (Get-PcSections, Get-PcNotes) saf mantiktir ve ayri sinanir.
# ==================================================================
$script:PcInfo = $null
$script:PcLoading = $false

# ---------------- yorumlama (saf mantik) ----------------
function Get-PcMemSummary($I) {
    $mods = @($I.Mem.Modules)
    $total = [double]$I.Mem.TotalGB
    if ($mods.Count -eq 0) { return (Format-PcGb $total) }
    $types = @($mods | ForEach-Object { [string]$_.Type } | Where-Object { $_ -ne '' } | Select-Object -Unique)
    $speed = 0
    foreach ($m in $mods) { $sp = [int]$m.Running; if ($sp -le 0) { $sp = [int]$m.Rated }; if ($sp -gt $speed) { $speed = $sp } }
    $parts = New-Object System.Collections.ArrayList
    [void]$parts.Add((Format-PcGb $total))
    if ($types.Count -gt 0) { [void]$parts.Add(($types -join '/')) }
    if ($speed -gt 0) { [void]$parts.Add([string]$speed + ' MHz') }
    $mc = [string]$mods.Count + (' mod' + [char]0x00FC + 'l')
    if ([int]$I.Mem.SlotCount -gt $mods.Count) { $mc += ' (' + [string]([int]$I.Mem.SlotCount - $mods.Count) + (' yuva bo' + [char]0x015F + ')') }
    [void]$parts.Add($mc)
    return ($parts.ToArray() -join ('  ' + [char]0x00B7 + '  '))
}

function Get-PcSecuritySummary($I) {
    $m = $I.Machine
    $p = New-Object System.Collections.ArrayList
    if ([string]$m.Firmware -ne '') { [void]$p.Add([string]$m.Firmware) }
    if ($null -ne $m.SecureBoot) { if ($m.SecureBoot -eq $true) { [void]$p.Add(('G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme a' + [char]0x00E7 + '' + [char]0x0131 + 'k')) } else { [void]$p.Add(('G' + [char]0x00FC + 'venli ' + [char]0x00D6 + 'ny' + [char]0x00FC + 'kleme kapal' + [char]0x0131 + '')) } }
    if ($m.Tpm.Known -eq $true) {
        if ($m.Tpm.Present -eq $true) {
            $tv = ''
            if ([string]$m.Tpm.Version -ne '') { $tv = ' ' + [string]$m.Tpm.Version }
            if ($m.Tpm.Ready -eq $true) { [void]$p.Add('TPM' + $tv + (' haz' + [char]0x0131 + 'r')) } else { [void]$p.Add('TPM' + $tv + (' var, kapal' + [char]0x0131 + '')) }
        } else { [void]$p.Add('TPM yok') }
    } else { [void]$p.Add(('TPM durumu okunamad' + [char]0x0131 + ' (y' + [char]0x00F6 + 'netici gerekir)')) }
    if ($p.Count -eq 0) { return ('Okunamad' + [char]0x0131 + '') }
    return ($p.ToArray() -join ('  ' + [char]0x00B7 + '  '))
}

# Ekranda ve kopyalanan ozette gosterilen bolumler: @( @{ Title; Rows = @( @{ K; V } ) } )
function Get-PcSections($I, [bool]$Expert) {
    $out = New-Object System.Collections.ArrayList
    $m = $I.Machine
    $o = $I.Os

    $r = New-Object System.Collections.ArrayList
    $mdl = (([string]$m.Maker + ' ' + [string]$m.Model).Trim())
    if ($mdl -eq '') { $mdl = ('Okunamad' + [char]0x0131 + '') }
    [void]$r.Add(@{ K = 'Bilgisayar'; V = $mdl })
    if ([string]$m.Kind -ne '') { [void]$r.Add(@{ K = ('T' + [char]0x00FC + 'r'); V = [string]$m.Kind }) }
    $wn = [string]$o.Name
    if ($wn -eq '') { $wn = 'Windows' }
    if ([string]$o.Version -ne '') { $wn += ('  ' + [char]0x00B7 + '  ') + [string]$o.Version }
    if ([int]$o.Build -gt 0) {
        $bs = [string]$o.Build
        if ([int]$o.Ubr -gt 0) { $bs += '.' + [string]$o.Ubr }
        $wn += ('  ' + [char]0x00B7 + '  derleme ') + $bs
    }
    [void]$r.Add(@{ K = 'Windows'; V = $wn })
    if ([string]$o.Installed -ne '') { [void]$r.Add(@{ K = 'Kurulum tarihi'; V = [string]$o.Installed }) }
    if ([double]$o.UptimeHours -gt 0) { [void]$r.Add(@{ K = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'k kalma s' + [char]0x00FC + 'resi'); V = (Format-PcSpan ([double]$o.UptimeHours)) }) }
    [void]$r.Add(@{ K = ('G' + [char]0x00FC + 'venlik donan' + [char]0x0131 + 'm' + [char]0x0131 + ''); V = (Get-PcSecuritySummary $I) })
    if ($Expert) {
        if ([string]$m.Board -ne '') { [void]$r.Add(@{ K = 'Anakart'; V = [string]$m.Board }) }
        if ([string]$m.Bios -ne '') {
            $bv = [string]$m.Bios
            if ([string]$m.BiosDate -ne '') { $bv += ('  ' + [char]0x00B7 + '  ') + [string]$m.BiosDate }
            [void]$r.Add(@{ K = ('BIOS / UEFI s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ''); V = $bv })
        }
        if ([string]$o.Arch -ne '') { [void]$r.Add(@{ K = 'Mimari'; V = [string]$o.Arch }) }
        if ([string]$o.Boot -ne '') { [void]$r.Add(@{ K = ('Son a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ''); V = [string]$o.Boot }) }
    }
    [void]$out.Add(@{ Title = 'Bilgisayar ve Windows'; Rows = $r.ToArray() })

    $c = $I.Cpu
    $r = New-Object System.Collections.ArrayList
    $cn = [string]$c.Name
    if ($cn -eq '') { $cn = ('Okunamad' + [char]0x0131 + '') }
    [void]$r.Add(@{ K = ('' + [char]0x0130 + '' + [char]0x015F + 'lemci'); V = $cn })
    if ([int]$c.Cores -gt 0) { [void]$r.Add(@{ K = ('' + [char]0x00C7 + 'ekirdek'); V = [string]$c.Cores + (' ' + [char]0x00E7 + 'ekirdek, ') + [string]$c.Threads + (' i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + '') }) }
    if ($Expert) {
        if ([int]$c.Mhz -gt 0) { [void]$r.Add(@{ K = ('En y' + [char]0x00FC + 'ksek h' + [char]0x0131 + 'z'); V = [string]$c.Mhz + ' MHz' }) }
        if ([int]$c.L2KB -gt 0 -or [int]$c.L3KB -gt 0) { [void]$r.Add(@{ K = ('' + [char]0x00D6 + 'nbellek'); V = 'L2 ' + [string][math]::Round([double]$c.L2KB / 1024, 1) + (' MB  ' + [char]0x00B7 + '  L3 ') + [string][math]::Round([double]$c.L3KB / 1024, 1) + ' MB' }) }
        if ($null -ne $c.Virt) { if ($c.Virt -eq $true) { [void]$r.Add(@{ K = ('Sanalla' + [char]0x015F + 't' + [char]0x0131 + 'rma'); V = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'k') }) } else { [void]$r.Add(@{ K = ('Sanalla' + [char]0x015F + 't' + [char]0x0131 + 'rma'); V = ('Kapal' + [char]0x0131 + ' (BIOS ayar' + [char]0x0131 + ')') }) } }
    }
    [void]$out.Add(@{ Title = ('' + [char]0x0130 + '' + [char]0x015F + 'lemci'); Rows = $r.ToArray() })

    $r = New-Object System.Collections.ArrayList
    [void]$r.Add(@{ K = 'Bellek'; V = (Get-PcMemSummary $I) })
    if ($Expert) {
        $k = 0
        foreach ($md in @($I.Mem.Modules)) {
            $k++
            $line = (Format-PcGb ([double]$md.CapGB))
            if ([string]$md.Type -ne '') { $line += ('  ' + [char]0x00B7 + '  ') + [string]$md.Type }
            if ([int]$md.Running -gt 0 -and [int]$md.Rated -gt 0 -and [int]$md.Running -ne [int]$md.Rated) { $line += ('  ' + [char]0x00B7 + '  ') + [string]$md.Running + (' MHz (' + [char]0x00FC + 'retici de' + [char]0x011F + 'eri ') + [string]$md.Rated + ' MHz)' }
            elseif ([int]$md.Rated -gt 0) { $line += ('  ' + [char]0x00B7 + '  ') + [string]$md.Rated + ' MHz' }
            if ([string]$md.Maker -ne '') { $line += ('  ' + [char]0x00B7 + '  ') + [string]$md.Maker }
            if ([string]$md.Part -ne '') { $line += ('  ' + [char]0x00B7 + '  ') + [string]$md.Part }
            $slot = [string]$md.Slot
            if ($slot -eq '') { $slot = ('Mod' + [char]0x00FC + 'l ') + [string]$k }
            [void]$r.Add(@{ K = $slot; V = $line })
        }
        if ([double]$I.Mem.MaxGB -gt 0) { [void]$r.Add(@{ K = ('Desteklenen en ' + [char]0x00E7 + 'ok'); V = (Format-PcGb ([double]$I.Mem.MaxGB)) }) }
    }
    [void]$out.Add(@{ Title = 'Bellek'; Rows = $r.ToArray() })

    $r = New-Object System.Collections.ArrayList
    if (@($I.Gpu).Count -eq 0) { [void]$r.Add(@{ K = ('Ekran kart' + [char]0x0131 + ''); V = ('Okunamad' + [char]0x0131 + '') }) }
    foreach ($g in @($I.Gpu)) {
        [void]$r.Add(@{ K = ('Ekran kart' + [char]0x0131 + ''); V = [string]$g.Name })
        if ($Expert) {
            if ([string]$g.Driver -ne '') {
                $dv = [string]$g.Driver
                if ([string]$g.DriverDate -ne '') { $dv += ('  ' + [char]0x00B7 + '  ') + [string]$g.DriverDate }
                [void]$r.Add(@{ K = ('   s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ''); V = $dv })
            }
            if ([string]$g.Res -ne '') { [void]$r.Add(@{ K = '   ekran'; V = [string]$g.Res }) }
        }
    }
    [void]$out.Add(@{ Title = ('Ekran kart' + [char]0x0131 + ''); Rows = $r.ToArray() })

    $r = New-Object System.Collections.ArrayList
    if (@($I.Disks).Count -eq 0) { [void]$r.Add(@{ K = 'Diskler'; V = ('Okunamad' + [char]0x0131 + '') }) }
    foreach ($d in @($I.Disks)) {
        $line = [string]$d.Name
        if ($line -eq '') { $line = 'Disk' }
        $line += ('  ' + [char]0x00B7 + '  ') + [string]$d.Kind + ('  ' + [char]0x00B7 + '  ') + (Format-PcGb ([double]$d.SizeGB))
        if ([string]$d.Health -ne '' -and [string]$d.Health -ne 'Healthy') { $line += ('  ' + [char]0x00B7 + '  sa' + [char]0x011F + 'l' + [char]0x0131 + 'k: ') + [string]$d.Health }
        if ($Expert) {
            if ([string]$d.Style -ne '' -and [string]$d.Style -ne 'RAW') { $line += ('  ' + [char]0x00B7 + '  ') + [string]$d.Style }
            if ([string]$d.Bus -ne '') { $line += ('  ' + [char]0x00B7 + '  ') + [string]$d.Bus }
            if (@($d.Letters).Count -gt 0) { $line += ('  ' + [char]0x00B7 + '  ') + (@($d.Letters) -join ' ') }
        }
        $lbl = 'Disk ' + [string]$d.Number
        if ($d.IsSystem -eq $true) { $lbl += ' (Windows)' }
        [void]$r.Add(@{ K = $lbl; V = $line })
    }
    if ([double]$I.SysDrive.SizeGB -gt 0) { [void]$r.Add(@{ K = ([string]$I.SysDrive.Letter + (' bo' + [char]0x015F + ' alan')); V = ((Format-PcGb ([double]$I.SysDrive.FreeGB)) + ' / ' + (Format-PcGb ([double]$I.SysDrive.SizeGB))) }) }
    [void]$out.Add(@{ Title = 'Depolama'; Rows = $r.ToArray() })

    if (@($I.Net).Count -gt 0) {
        $r = New-Object System.Collections.ArrayList
        foreach ($n in @($I.Net)) {
            $line = [string]$n.Name
            if ($n.Up -eq $true) { if ([string]$n.Speed -ne '') { $line += ('  ' + [char]0x00B7 + '  ba' + [char]0x011F + 'l' + [char]0x0131 + ', ') + [string]$n.Speed } else { $line += ('  ' + [char]0x00B7 + '  ba' + [char]0x011F + 'l' + [char]0x0131 + '') } } else { $line += ('  ' + [char]0x00B7 + '  ba' + [char]0x011F + 'l' + [char]0x0131 + ' de' + [char]0x011F + 'il') }
            [void]$r.Add(@{ K = [string]$n.Kind; V = $line })
        }
        [void]$out.Add(@{ Title = ('A' + [char]0x011F + ''); Rows = $r.ToArray() })
    }

    if ($null -ne $I.Battery) {
        $b = $I.Battery
        $r = New-Object System.Collections.ArrayList
        $pl = '%' + [string]$b.Percent
        if ($b.Charging -eq $true) { $pl += ('  ' + [char]0x00B7 + '  ' + [char]0x015F + 'arj oluyor ya da fi' + [char]0x015F + 'te') } else { $pl += ('  ' + [char]0x00B7 + '  pille ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor') }
        [void]$r.Add(@{ K = ('' + [char]0x015E + 'arj'); V = $pl })
        if ([int]$b.WearPct -ge 0) {
            $wv = '%' + [string]$b.WearPct + (' a' + [char]0x015F + '' + [char]0x0131 + 'nma')
            if ($Expert -and [int]$b.DesignMWh -gt 0) { $wv += ('  ' + [char]0x00B7 + '  tasar' + [char]0x0131 + 'm ') + [string]$b.DesignMWh + (' mWh, ' + [char]0x015F + 'imdi ') + [string]$b.FullMWh + ' mWh' }
            [void]$r.Add(@{ K = ('Pil sa' + [char]0x011F + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ''); V = $wv })
        }
        [void]$out.Add(@{ Title = 'Pil'; Rows = $r.ToArray() })
    }

    if ($Expert -and @($I.Problems).Count -gt 0) {
        $r = New-Object System.Collections.ArrayList
        foreach ($p in @($I.Problems)) { [void]$r.Add(@{ K = ('Kod ' + [string]$p.Code); V = [string]$p.Name }) }
        [void]$out.Add(@{ Title = ('Sorunlu ayg' + [char]0x0131 + 'tlar'); Rows = $r.ToArray() })
    }
    return $out.ToArray()
}

# Gozlem dugmesi: @{ Label; Do; ... }. Do: Page (Sayfa, Sub) | Url (Url) | Tool (Path) | SlTab (Tab) | Reboot | Uefi | Job (Key, Confirm, Done)
function New-PcAct([string]$Label, [string]$Do, $Extra = $null) {
    $a = @{ Label = $Label; Do = $Do }
    if ($null -ne $Extra) { foreach ($k in @($Extra.Keys)) { $a[$k] = $Extra[$k] } }
    return $a
}

# Gozlemler: @( @{ Level = warn|info|good; Title; Text; A1; A2 } ). A1/A2 bulguyu duzelten ya da ilgili yere goturen dugmelerdir (yoksa $null).
# Uzman kipine ozel olanlar yalnizca $Expert iken gelir.
function Get-PcNotes($I, [bool]$Expert) {
    $n = New-Object System.Collections.ArrayList
    $m = $I.Machine
    $o = $I.Os
    $isVm = ($m.IsVm -eq $true)
    $actUefi = New-PcAct ('UEFI ayarlar' + [char]0x0131 + 'na git') 'Uefi'
    $actDev = New-PcAct ('Ayg' + [char]0x0131 + 't Y' + [char]0x00F6 + 'neticisi') 'Tool' @{ Path = 'devmgmt.msc' }
    $actWu = New-PcAct ('G' + [char]0x00FC + 'ncellemeleri ara') 'Page' @{ Page = 'wu'; Sub = '' }
    $actBackup = New-PcAct 'Yedekle' 'Page' @{ Page = 'backup'; Sub = '' }

    if ([int]$o.Build -gt 0 -and [int]$o.Build -lt 22000 -and ([string]$o.Name -match 'Windows 10')) {
        [void]$n.Add(@{ Level = 'warn'; Title = ('Windows 10 kullan' + [char]0x0131 + 'yorsunuz'); Text = ('Windows 10 i' + [char]0x00E7 + 'in standart destek 14 Ekim 2025' + [char]0x2019 + 'te sona erdi. G' + [char]0x00FC + 'venlik g' + [char]0x00FC + 'ncellemeleri almaya devam etmek i' + [char]0x00E7 + 'in uygun bilgisayarda Windows 11' + [char]0x2019 + 'e ge' + [char]0x00E7 + 'meniz ' + [char]0x00F6 + 'nerilir.')
            A1 = (New-PcAct ('Windows Update' + [char]0x2019 + 'i a' + [char]0x00E7 + '') 'Url' @{ Url = 'ms-settings:windowsupdate' }); A2 = $null })
        if ($m.Tpm.Known -eq $true -and ($m.Tpm.Present -ne $true -or ([string]$m.Tpm.Version -ne '' -and [string]$m.Tpm.Version -ne '2.0'))) {
            [void]$n.Add(@{ Level = 'info'; Title = ('Windows 11 i' + [char]0x00E7 + 'in TPM 2.0 gerekir'); Text = ('Bu bilgisayarda TPM 2.0 g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor. BIOS ayarlar' + [char]0x0131 + 'nda ' + [char]0x201C + 'fTPM' + [char]0x201D + ' ya da ' + [char]0x201C + 'PTT' + [char]0x201D + ' se' + [char]0x00E7 + 'ene' + [char]0x011F + 'i a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'rsa Windows 11 gereksinimi kar' + [char]0x015F + '' + [char]0x0131 + 'lanabilir.'); A1 = $actUefi; A2 = $null })
        }
    }

    $tot = [double]$I.Mem.TotalGB
    $actStartup = New-PcAct ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' programlar' + [char]0x0131 + '') 'Page' @{ Page = 'startup'; Sub = '' }
    if ($tot -gt 0 -and $tot -lt 4) { [void]$n.Add(@{ Level = 'warn'; Title = ('Bellek ' + [char]0x00E7 + 'ok az'); Text = (Format-PcGb $tot) + (' bellek Windows' + [char]0x2019 + 'un rahat ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yetersiz. Bellek eklemek ya da arka plan programlar' + [char]0x0131 + 'n' + [char]0x0131 + ' azaltmak belirgin fark yarat' + [char]0x0131 + 'r.'); A1 = $actStartup; A2 = $null }) }
    elseif ($tot -ge 4 -and $tot -lt 8) { [void]$n.Add(@{ Level = 'info'; Title = ('Bellek s' + [char]0x0131 + 'n' + [char]0x0131 + 'rda'); Text = (Format-PcGb $tot) + (' bellek g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k i' + [char]0x015F + 'ler i' + [char]0x00E7 + 'in yeterli, ama taray' + [char]0x0131 + 'c' + [char]0x0131 + ' ve birka' + [char]0x00E7 + ' program birlikte a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'nda zorlanabilir. 8 GB ve ' + [char]0x00FC + 'zeri ' + [char]0x00F6 + 'nerilir.'); A1 = $actStartup; A2 = $null }) }
    $mods = @($I.Mem.Modules)
    if (-not $isVm -and $mods.Count -eq 1 -and [int]$I.Mem.SlotCount -ge 2) {
        [void]$n.Add(@{ Level = 'info'; Title = ('Bellek tek kanalda ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor'); Text = ('Tek bellek mod' + [char]0x00FC + 'l' + [char]0x00FC + ' tak' + [char]0x0131 + 'l' + [char]0x0131 + ', bo' + [char]0x015F + ' yuva var. Ayn' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellikte ikinci bir mod' + [char]0x00FC + 'l ' + [char]0x00E7 + 'ift kanal sa' + [char]0x011F + 'lar; bellek bant geni' + [char]0x015F + 'li' + [char]0x011F + 'i iki kat' + [char]0x0131 + 'na ' + [char]0x00E7 + '' + [char]0x0131 + 'kar ve ' + [char]0x00F6 + 'zellikle yerle' + [char]0x015F + 'ik ekran kartlar' + [char]0x0131 + 'nda oyun ve uygulama h' + [char]0x0131 + 'z' + [char]0x0131 + ' artar. Bu bir donan' + [char]0x0131 + 'm eklemesidir, yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'mla d' + [char]0x00FC + 'zeltilemez.'); A1 = $null; A2 = $null })
    }
    if ($Expert) {
        foreach ($md in $mods) {
