# Panoya kopyalanacak duz metin ozeti
function Get-PcSummaryText($I, [bool]$Expert) {
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine(('Multimizer - Bilgisayar ' + [char]0x00F6 + 'zeti  (') + [string]$I.At + ')')
    foreach ($s in @(Get-PcSections $I $Expert)) {
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine([string]$s.Title)
        foreach ($r in @($s.Rows)) { [void]$sb.AppendLine('  ' + [string]$r.K + ': ' + [string]$r.V) }
    }
    $notes = @(Get-PcNotes $I $Expert)
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine(('G' + [char]0x00F6 + 'zlemler'))
    foreach ($t in $notes) { [void]$sb.AppendLine('  - ' + [string]$t.Title + ': ' + [string]$t.Text) }
    return $sb.ToString().TrimEnd()
}

function Set-ClipText([string]$Text) {
    try { [System.Windows.Clipboard]::SetText($Text); return $true } catch { return $false }
}

# ---------------- cizim ----------------
function Load-SlPc {
    if ($script:PcLoading -eq $true) { return }
    $script:PcLoading = $true
    $ok = Start-Async 'PcInfo' 'Job_PcInfo' @{} {
        param($r)
        Complete-SlPc $r
    } 'Bilgisayar okunuyor' $false $true
    if (-not $ok) { $script:PcLoading = $false }
}

function Complete-SlPc($R) {
    $script:PcLoading = $false
    if ($null -eq $R -or $R.Ok -ne $true) { $script:PcInfo = @{ Failed = $true } } else { $script:PcInfo = $R.Info }
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'pc') { Render-SlPc }
}

function Render-SlPc {
    $ui.sl_List.Children.Clear()
    $I = $script:PcInfo
    if ($null -eq $I) {
        Add-Note $ui.sl_List 'Bilgisayar okunuyor...'
        Load-SlPc
        return
    }
    if ($I.Failed -eq $true) {
        Add-Note $ui.sl_List ('Bilgisayar bilgisi okunamad' + [char]0x0131 + '. ' + [char]0x201C + 'Yenile' + [char]0x201D + 'ye basarak yeniden deneyin; sorun s' + [char]0x00FC + 'rerse g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn'
        return
    }
    $expert = ([string]$script:UiState.Mode -eq 'Expert')
    if ($expert) { Add-Note $ui.sl_List ('Uzman kipi: ham de' + [char]0x011F + 'erler, bellek mod' + [char]0x00FC + 'lleri, s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'mleri ve sorunlu ayg' + [char]0x0131 + 't kodlar' + [char]0x0131 + ' da g' + [char]0x00F6 + 'steriliyor.') }
    else { Add-Note $ui.sl_List ('Bilgisayar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n ne oldu' + [char]0x011F + 'unu ve neye ihtiyac' + [char]0x0131 + ' olabilece' + [char]0x011F + 'ini sade anlat' + [char]0x0131 + 'r. Bellek mod' + [char]0x00FC + 'lleri, s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' s' + [char]0x00FC + 'r' + [char]0x00FC + 'mleri ve BIOS ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'lar' + [char]0x0131 + ' i' + [char]0x00E7 + 'in sa' + [char]0x011F + ' ' + [char]0x00FC + 'stten Uzman kipine ge' + [char]0x00E7 + 'in. Bilgiler yaln' + [char]0x0131 + 'zca okunur, hi' + [char]0x00E7 + 'bir ayar de' + [char]0x011F + 'i' + [char]0x015F + 'mez; G' + [char]0x00F6 + 'zlemler alt' + [char]0x0131 + 'ndaki d' + [char]0x00FC + '' + [char]0x011F + 'meler (yeniden ba' + [char]0x015F + 'latma, UEFI ayar' + [char]0x0131 + 'na yeniden ba' + [char]0x015F + 'latma, ayg' + [char]0x0131 + 'tlar' + [char]0x0131 + ' yeniden tarama) yaln' + [char]0x0131 + 'zca onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r.') }
    foreach ($s in @(Get-PcSections $I $expert)) {
        Add-HeadRow $ui.sl_List ([string]$s.Title)
        foreach ($r in @($s.Rows)) { Add-KvRow $ui.sl_List ([string]$r.K) ([string]$r.V) }
    }
    Add-HeadRow $ui.sl_List ('G' + [char]0x00F6 + 'zlemler')
    foreach ($t in @(Get-PcNotes $I $expert)) {
        $br = 'BrInfo'
        if ([string]$t.Level -eq 'warn') { $br = 'BrWarn' } elseif ([string]$t.Level -eq 'good') { $br = 'BrGood' }
        $b1 = ''; $b2 = ''
        if ($null -ne $t.A1) { $b1 = [string]$t.A1.Label }
        if ($null -ne $t.A2) { $b2 = [string]$t.A2.Label }
        $d1 = @{ Do = '' }
        if ($null -ne $t.A1) { $d1 = $t.A1 }
        $row = New-ItemRow @{ Title = [string]$t.Title; Detail = [string]$t.Text; BrCol = $br; Btn1 = $b1; Btn2 = $b2 } $d1 $false $false
        if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_PcAct) }
        if ($b2 -ne '') {
            $a2 = $row.FindName('Act2')
            $a2.Tag = $t.A2
            $a2.Add_Click($script:H_PcAct)
        }
        [void]$ui.sl_List.Children.Add($row)
    }
    $adm = ''
    if ($I.Admin -ne $true) { $adm = ('  ' + [char]0x00B7 + '  y' + [char]0x00F6 + 'netici olmadan TPM gibi baz' + [char]0x0131 + ' bilgiler okunamayabilir') }
    $ui.sl_Foot.Text = (Tr $('Okundu: ' + [string]$I.At + $adm))
}

$script:H_PcAct = { param($s, $e) Invoke-Safe { Invoke-PcAction $s.Tag } 'Eylem' }
$script:PcPendingJob = $null

# Gozlem dugmeleri: ya ilgili sayfaya goturur ya da (onayla) bir islem calistirir
function Invoke-PcAction($T) {
    if ($null -eq $T) { return }
    switch ([string]$T.Do) {
        'Page'   { Open-Page ([string]$T.Page) ([string]$T.Sub) }
        'Url'    { Open-Url ([string]$T.Url) }
        'Tool'   { Open-Path ([string]$T.Path) }
        'SlTab'  { if (-not (Select-TabChip 'sl' ([string]$T.Tab))) { Set-SlTab ([string]$T.Tab) } }
        'Reboot' { Request-Reboot }
        'Uefi'   { Start-PcUefi }
        'Job'    { Start-PcJob $T }
    }
}

function Start-PcJob($T) {
    $script:PcPendingJob = $T
    if ([string]$T.Confirm -ne '') {
        Show-Confirm ([string]$T.Label) ([string]$T.Confirm) ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r') { Start-PcJobNow }
        return
    }
    Start-PcJobNow
}

function Start-PcJobNow {
    $T = $script:PcPendingJob
    if ($null -eq $T) { return }
    [void](Start-Async 'Action' 'Job_Action' @{ Key = [string]$T.Key } {
        param($r)
        $j = $script:PcPendingJob
        if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ([string]$j.Done) 'good' } else { Show-Toast ([string]$j.Fail) 'bad' }
    } ([string]$T.Busy))
}

# Bilgisayari dogrudan UEFI (BIOS) ayar ekranina yeniden baslatir; yalnizca UEFI kipinde calisir
function Start-PcUefi {
    $fw = ''
    if ($null -ne $script:PcInfo -and $script:PcInfo.Failed -ne $true) { $fw = [string]$script:PcInfo.Machine.Firmware }
    if ($fw -eq 'Eski BIOS') {
        Show-Toast ('Bu bilgisayar eski BIOS kipinde. BIOS ayar' + [char]0x0131 + 'na a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta ' + [char]0x00FC + 'reticinin tu' + [char]0x015F + 'uyla (genellikle Del, F2 ya da F10) girilir.') 'info'
        return
    }
    Show-Confirm ('UEFI ayarlar' + [char]0x0131 + 'na yeniden ba' + [char]0x015F + 'lat') (('Bilgisayar 30 saniye sonra yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve do' + [char]0x011F + 'rudan UEFI (BIOS) ayar ekran' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r. A' + [char]0x00E7 + '' + [char]0x0131 + 'k i' + [char]0x015F + 'lerinizi kaydedin.') + "`r`n`r`n" + ('Bu ekranda yapt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z de' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerin sorumlulu' + [char]0x011F + 'u size aittir; emin de' + [char]0x011F + 'ilseniz hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'eyi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmeden ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'n. Komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'na ' + [char]0x201C + 'iptal' + [char]0x201D + ' yazarak yeniden ba' + [char]0x015F + 'latmay' + [char]0x0131 + ' durdurabilirsiniz.')) ('Yeniden ba' + [char]0x015F + 'lat') {
        try {
            [void](Start-SystemRestart $true 30)
            Show-Toast ('Bilgisayar 30 saniye sonra UEFI ayarlar' + [char]0x0131 + 'na yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak.') 'warn'
        } catch { Show-Toast ('Yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'bad' }
    } $true
}

# Aygit yoneticisinin "donanim degisikliklerini tara" islemi (Job_Action anahtari: PcRescan)
function Invoke-PcRescanAction($P) {
    Write-WhLog ('Donan' + [char]0x0131 + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'iklikleri taran' + [char]0x0131 + 'yor (pnputil /scan-devices)...') 'INFO'
    $o = & pnputil.exe /scan-devices 2>&1
    if ($LASTEXITCODE -ne 0) { throw (('pnputil ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$LASTEXITCODE + ': ' + (($o | Out-String).Trim())) }
    Write-WhLog ('Ayg' + [char]0x0131 + 'tlar yeniden tarand' + [char]0x0131 + '.') 'OK'
}
$script:ExtraActions['PcRescan'] = 'Invoke-PcRescanAction'

# MBR2GPT donusturme uygunlugunu yalnizca denetler (diskte hicbir sey degismez)
function Invoke-PcMbr2gptAction($P) {
    Write-WhLog ('Disk GPT d' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + 't' + [char]0x00FC + 'rme uygunlu' + [char]0x011F + 'u denetleniyor (mbr2gpt /validate; salt okunur)...') 'INFO'
    $o = & mbr2gpt.exe /validate /allowFullOS 2>&1
    $txt = (($o | Out-String).Trim())
    if ($txt -ne '') { Write-WhLog $txt 'INFO' }
    if ($LASTEXITCODE -ne 0) { throw (('mbr2gpt ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' kodu ') + [string]$LASTEXITCODE) }
    Write-WhLog ('Disk GPT d' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + 't' + [char]0x00FC + 'rmeye uygun.') 'OK'
}
$script:ExtraActions['PcMbr2gpt'] = 'Invoke-PcMbr2gptAction'

function Copy-SlPc {
    $I = $script:PcInfo
    if ($null -eq $I -or $I.Failed -eq $true) { Show-Toast ('' + [char]0x00D6 + 'nce bilgisayar bilgisinin okunmas' + [char]0x0131 + 'n' + [char]0x0131 + ' bekleyin.') 'warn'; return }
    $expert = ([string]$script:UiState.Mode -eq 'Expert')
    if (Set-ClipText (Get-PcSummaryText $I $expert)) { Show-Toast ('Bilgisayar ' + [char]0x00F6 + 'zeti panoya kopyaland' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Kopyalanamad' + [char]0x0131 + '.') 'warn' }
}

function Init-SlPc {
    $ui.sl_PcRefresh.Add_Click({ Invoke-Safe { $script:PcInfo = $null; Render-SlPc } 'Yenile' })
    $ui.sl_PcCopy.Add_Click({ Invoke-Safe { Copy-SlPc } 'Kopyala' })
}

# Kullanici / Uzman kipi degisince acik sekmeyi yeniden cizer
function Update-PageMode_solve {
    if ([string]$script:UiState.Page -ne 'solve') { return }
    if ($script:SlTab -eq 'pc' -and $null -ne $script:PcInfo) { Render-SlPc }
    elseif ($script:SlTab -eq 'prep' -and $null -ne $script:PrepState) { Render-SlPrep }
    elseif ($script:SlTab -eq 'scan' -and $null -ne $script:Health) { Render-SlScan }
}

# ---------------- cozum merkezi: hazirlik sekmesi ----------------
# ==================================================================
#  COZUM MERKEZI: "Hazirlik" sekmesi
#  Multimizer'in ve araclarinin calismasi icin gereken bilesenleri (PowerShell, .NET Framework, C# derleyicisi, Visual C++, DirectX, winget,
#  bos alan, WMI, eklentiler) denetler. Denetim yalnizca okur; eksikler yalnizca onayinizla, Microsoft'un winget araciyla ve paket ozeti
#  dogrulanarak kurulur. Toplama ve kurulum isleri 127_prep_core.ps1 icindedir; burada satirlar, onaylar ve sonuc iletileri var.
# ==================================================================
$script:PrepState = $null
$script:PrepItems = @()
$script:PrepLoading = $false
$script:PrepPending = $null

function Get-PrepBr([string]$Status) {
    if ($Status -eq 'bad') { return 'BrBad' }
    if ($Status -eq 'warn') { return 'BrWarn' }
    if ($Status -eq 'ok') { return 'BrGood' }
    return 'BrInfo'
}

# Kurulum isinin sonucu -> bildirim: @{ Text; Kind (good | warn | bad) }
function Get-PrepInstallModel($R) {
    if ($null -eq $R) { return @{ Text = ('Kurulum tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.'); Kind = 'bad' } }
    $done = [int](Get-JsonProp $R 'Done')
    $failed = [int](Get-JsonProp $R 'Failed')
    $reboot = ((Get-JsonProp $R 'Reboot') -eq $true)
    $items = @(@(Get-JsonProp $R 'Items') | Where-Object { $null -ne $_ })
    if ($R.Ok -eq $true) {
        $t = [string]$done + (' bile' + [char]0x015F + 'en kuruldu.')
        $kind = 'good'
        if ($reboot) { $t += (' Etkili olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.'); $kind = 'warn' }
        return @{ Text = $t; Kind = $kind }
    }
    if ($R.Canceled -eq $true) { return @{ Text = 'Kurulum iptal edildi (' + [string]$done + (' bile' + [char]0x015F + 'en kurulmu' + [char]0x015F + 'tu).'); Kind = 'warn' } }
    $why = [string](Get-JsonProp $R 'Error')
    $bad = @($items | Where-Object { $_.Ok -ne $true })
    if ($bad.Count -gt 0) {
        $parts = New-Object System.Collections.ArrayList
        foreach ($b in $bad) {
            if ($parts.Count -ge 2) { break }
            $nm = [string]$b.Id
            if ($script:PrepPackages.ContainsKey($nm)) { $nm = [string]$script:PrepPackages[$nm] }
            [void]$parts.Add($nm + ': ' + [string]$b.Text)
        }
        $why = ($parts.ToArray() -join '; ')
        if ($bad.Count -gt 2) { $why += ' (+' + [string]($bad.Count - 2) + (' bile' + [char]0x015F + 'en daha)') }
    }
    if ($why -eq '') { $why = ('Kurulum tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') }
    $t = $why
    if ($done -gt 0) { $t = [string]$done + (' bile' + [char]0x015F + 'en kuruldu, ') + [string]$failed + (' kurulamad' + [char]0x0131 + '. ') + $why }
    return @{ Text = $t; Kind = 'bad' }
}

# ---------------- cizim ----------------
function Load-SlPrep {
    if ($script:PrepLoading -eq $true) { return }
    $script:PrepLoading = $true
    $ok = Start-Async 'PrepCheck' 'Job_PrepCheck' @{} {
        param($r)
        Complete-SlPrep $r
    } ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k denetleniyor') $false $true
    if (-not $ok) { $script:PrepLoading = $false }
}

function Complete-SlPrep($R) {
    $script:PrepLoading = $false
    if ($null -eq $R -or $R.Ok -ne $true) { $script:PrepState = @{ Failed = $true } } else { $script:PrepState = $R.State }
    $script:PrepItems = @()
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'prep') { Render-SlPrep }
}

$script:H_PrAct = { param($s, $e) Invoke-Safe { Invoke-PrepAction $s.Tag } 'Eylem' }

function Render-SlPrep {
    $ui.sl_List.Children.Clear()
    $S = $script:PrepState
    if ($null -eq $S) {
        Add-Note $ui.sl_List ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k denetleniyor...')
        Load-SlPrep
        return
    }
    if ($S.Failed -eq $true) {
        Add-Note $ui.sl_List ('Denetim yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '. ' + [char]0x201C + 'Denetle' + [char]0x201D + 'ye basarak yeniden deneyin; sorun s' + [char]0x00FC + 'rerse g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn'
        return
    }
    $expert = ([string]$script:UiState.Mode -eq 'Expert')
    $script:PrepItems = Get-PrepItems $S $expert
    Add-Note $ui.sl_List ('Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n ve ara' + [char]0x00E7 + 'lar' + [char]0x0131 + 'n' + [char]0x0131 + 'n her bilgisayarda d' + [char]0x00FC + 'zg' + [char]0x00FC + 'n ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in gereken bile' + [char]0x015F + 'enleri denetler. Denetim yaln' + [char]0x0131 + 'zca okur. Eksikler yaln' + [char]0x0131 + 'zca onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla, Microsoft' + [char]0x2019 + 'un winget arac' + [char]0x0131 + 'yla ve paket ' + [char]0x00F6 + 'zeti do' + [char]0x011F + 'rulanarak kurulur; internetten ba' + [char]0x015F + 'ka hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey indirilmez.')
    $sum = Get-PrepSummary $script:PrepItems
    $br = 'BrGood'
    if ($sum.Level -eq 'bad') { $br = 'BrBad' } elseif ($sum.Level -eq 'warn') { $br = 'BrWarn' }
    $fixList = Get-PrepInstallList $script:PrepItems
    $nFix = $fixList.Count
    $b1 = ''
    $sdata = @{ Do = '' }
    if ($nFix -gt 0) { $b1 = 'Eksikleri gider'; $sdata = @{ Do = 'FixAll' } }
    $srow = New-ItemRow @{ Title = 'Durum'; Detail = [string]$sum.Text; BrCol = $br; Btn1 = $b1 } $sdata $false $false
    if ($b1 -ne '') { $srow.FindName('Act').Add_Click($script:H_PrAct) }
    [void]$ui.sl_List.Children.Add($srow)
    $groups = @(@{ K = 'req'; T = ('Zorunlu bile' + [char]0x015F + 'enler') }, @{ K = 'rec'; T = ('' + [char]0x00D6 + 'nerilen bile' + [char]0x015F + 'enler') }, @{ K = 'opt'; T = ('' + [char]0x0130 + 'ste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' bile' + [char]0x015F + 'enler') })
    foreach ($g in $groups) {
        $rows = @($script:PrepItems | Where-Object { [string]$_.Group -eq [string]$g.K })
        if ($rows.Count -eq 0) { continue }
        Add-HeadRow $ui.sl_List ([string]$g.T)
        foreach ($it in $rows) {
            $lbl = ''
            $data = @{ Do = ''; Key = [string]$it.Key }
            if ($null -ne $it.Fix -and [string]$it.Status -ne 'ok') {
                $lbl = [string]$it.Fix.Label
                $data = @{ Key = [string]$it.Key }
                foreach ($fk in @($it.Fix.Keys)) { $data[$fk] = $it.Fix[$fk] }
            }
            $row = New-ItemRow @{ Title = [string]$it.Title; Detail = [string]$it.Detail; BrCol = (Get-PrepBr ([string]$it.Status)); Btn1 = $lbl } $data $false $false
            if ($lbl -ne '') { $row.FindName('Act').Add_Click($script:H_PrAct) }
            [void]$ui.sl_List.Children.Add($row)
        }
    }
    $ui.sl_Foot.Text = (Tr $('Denetlendi: ' + [string]$S.At + ('  ' + [char]0x00B7 + '  Kurulumlardan sonra ' + [char]0x201C + 'Denetle' + [char]0x201D + 'ye basarak sonucu do' + [char]0x011F + 'rulay' + [char]0x0131 + 'n.')))
}

# ---------------- islemler ----------------
function Invoke-PrepAction($T) {
    if ($null -eq $T) { return }
    switch ([string]$T.Do) {
        'Winget' { Start-PrepInstall @(@{ Id = [string]$T.Id; Name = [string]$T.Name }) }
        'FixAll' { Start-PrepFixAll }
        'Url'    { Open-Url ([string]$T.Url) }
        'Page'   { Open-Page ([string]$T.Page) ([string]$T.Sub) }
        'Wmi'    { Start-PrepWmi }
    }
}

# Pkgs: @( @{ Id; Name } ). Onay penceresinde neyin kurulacagi yazilir; onaylanmadan hicbir sey indirilmez.
function Start-PrepInstall($Pkgs) {
    $pk = @($Pkgs | Where-Object { $null -ne $_ })
    if ($pk.Count -eq 0) { Show-Toast ('Kurulacak eksik bile' + [char]0x015F + 'en yok.') 'info'; return }
    foreach ($x in $pk) {
        $why = Test-PrepPackage ([string]$x.Id)
        if ($why -ne '') { Show-Message ('Bu bile' + [char]0x015F + 'en kurulamaz') $why; return }
    }
    $script:PrepPending = $pk
    $lines = @($pk | ForEach-Object { ('' + [char]0x2022 + '  ') + [string]$_.Name })
    $txt = ('' + [char]0x015E + 'u bile' + [char]0x015F + 'enler Microsoft' + [char]0x2019 + 'un winget arac' + [char]0x0131 + 'yla kurulacak:') + "`r`n`r`n" + ($lines -join "`r`n") + "`r`n`r`n"
    $txt += ('' + [char]0x2022 + '  Paketler winget deposundan indirilir; paket ' + [char]0x00F6 + 'zeti (SHA-256) winget taraf' + [char]0x0131 + 'ndan do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r, uyu' + [char]0x015F + 'mazsa kurulmaz.') + "`r`n"
    $txt += ('' + [char]0x2022 + '  ' + [char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' gerekir; kurulum birka' + [char]0x00E7 + ' dakika s' + [char]0x00FC + 'rebilir. Ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + 'za ve ki' + [char]0x015F + 'isel dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'za dokunulmaz.') + "`r`n"
    $txt += ('' + [char]0x2022 + '  Baz' + [char]0x0131 + ' paketler kurulumdan sonra bilgisayar' + [char]0x0131 + 'n yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmas' + [char]0x0131 + 'n' + [char]0x0131 + ' isteyebilir.')
    Show-Confirm ('Eksik bile' + [char]0x015F + 'enleri kur') $txt 'Kur' {
        $ids = @($script:PrepPending | ForEach-Object { [string]$_.Id })
        [void](Start-Async 'PrepInstall' 'Job_PrepInstall' @{ Ids = $ids } {
            param($r)
            Complete-PrepInstall $r
        } ('Bile' + [char]0x015F + 'enler kuruluyor'))
    }
}

function Start-PrepFixAll {
    if ($null -eq $script:PrepState -or $script:PrepState.Failed -eq $true) { Show-Toast ('' + [char]0x00D6 + 'nce denetimin bitmesini bekleyin.') 'warn'; return }
    $pk = Get-PrepInstallList $script:PrepItems
    Start-PrepInstall $pk
}

function Complete-PrepInstall($R) {
    $script:PrepState = $null
    $m = Get-PrepInstallModel $R
    Show-Toast ([string]$m.Text) ([string]$m.Kind)
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'prep') { Render-SlPrep }
}

function Start-PrepWmi {
    $txt = ('WMI deposu Microsoft' + [char]0x2019 + 'un kendi arac' + [char]0x0131 + 'yla (winmgmt) do' + [char]0x011F + 'rulanacak.') + "`r`n`r`n"
    $txt += ('' + [char]0x2022 + '  Depo tutarl' + [char]0x0131 + 'ysa hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey de' + [char]0x011F + 'i' + [char]0x015F + 'mez.') + "`r`n"
    $txt += ('' + [char]0x2022 + '  Tutars' + [char]0x0131 + 'z ' + [char]0x00E7 + '' + [char]0x0131 + 'karsa ' + [char]0x201C + 'winmgmt /salvagerepository' + [char]0x201D + ' ile onar' + [char]0x0131 + 'l' + [char]0x0131 + 'r; depodaki okunabilir veriler korunur ve WMI hizmeti k' + [char]0x0131 + 'sa s' + [char]0x00FC + 're yeniden ba' + [char]0x015F + 'lar.') + "`r`n"
    $txt += ('' + [char]0x2022 + '  ' + [char]0x0130 + '' + [char]0x015F + 'lem bir dakikadan k' + [char]0x0131 + 'sa s' + [char]0x00FC + 'rer. A' + [char]0x00E7 + '' + [char]0x0131 + 'k i' + [char]0x015F + 'lerinizi kaydetmeniz yeterli, yeniden ba' + [char]0x015F + 'latma gerekmez.')
    Show-Confirm ('WMI deposunu do' + [char]0x011F + 'rula ve onar') $txt ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r') {
        [void](Start-Async 'PrepWmi' 'Job_PrepWmi' @{} {
            param($r)
            Complete-PrepWmi $r
        } 'WMI deposu denetleniyor')
    }
}

function Complete-PrepWmi($R) {
    $script:PrepState = $null
    if ($null -eq $R) { Show-Toast ('WMI denetimi tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
    else {
        $t = [string](Get-JsonProp $R 'Text')
        if ($t -eq '') { $t = ('WMI denetimi tamamland' + [char]0x0131 + '.') }
        if ($R.Ok -eq $true) { Show-Toast $t 'good' } else { Show-Toast $t 'bad' }
    }
    if ([string]$script:UiState.Page -eq 'solve' -and $script:SlTab -eq 'prep') { Render-SlPrep }
}

function Init-SlPrep {
    $ui.sl_PrCheck.Add_Click({ Invoke-Safe { $script:PrepState = $null; Render-SlPrep } 'Denetle' })
    $ui.sl_PrFix.Add_Click({ Invoke-Safe { Start-PrepFixAll } 'Eksikleri gider' })
}

# ---------------- baglantilar: komut hedefleri ----------------
# ==================================================================
#  BAGLANTILAR: komut satiri sayfa/sekme hedefleri
#  "ac <sozcuk>" komutu bir sayfayi ya da "sayfa:sekme" bicimindeki bir sekmeyi acar (ornek: solve:prep = Cozum Merkezi > Hazirlik).
# ==================================================================
function Split-CmdTarget([string]$Target) {
    $pg = $Target
    $sub = ''
    $ix = $Target.IndexOf(':')
    if ($ix -gt 0) {
        $pg = $Target.Substring(0, $ix)
        $sub = $Target.Substring($ix + 1)
    }
    return @{ Page = $pg; Sub = $sub }
}

function Open-CmdPage([string]$Target) {
    $t = Split-CmdTarget $Target
    Open-Page ([string]$t.Page) ([string]$t.Sub)
}

# ---------------- acilista hazirlik uyarisi ----------------
# ==================================================================
#  ACILISTA HAZIRLIK UYARISI
#  Her surumun ilk acilisinda bir kez, arka planda ve sessizce Hazirlik denetimi yapilir (yalnizca okuma; aga cikilmaz).
#  Zorunlu bir bilesen eksik ya da bozuksa bir onay penceresi, yalnizca onerilen bilesenler eksikse kucuk bir bildirim gosterilir.
#  Hicbir sey kurulmaz ya da degistirilmez; kurulum yalnizca Cozum Merkezi > Hazirlik sekmesinden, onayla yapilir.
#  Ilk calistirma ekrani (kullanim amaci secimi) aciksa, pencere gizliyse ya da baska bir is suruyorsa uygun ana kadar beklenir.
# ==================================================================
$script:PrepNudgeTimer = $null
$script:PrepNudgeTicks = 0

# Uyariya konu olan satirlar. Yonetici hakki, Sistem Korumasi, internet ve istege bagli bilesenler uyari sebebi sayilmaz.
$script:PrepNudgeKeys = @('ps', 'net', 'csc', 'wmi', 'data', 'ext', 'os', 'winget', 'space')

function Test-PrepNudgeKey([string]$Key) {
    if ($script:PrepNudgeKeys -contains $Key) { return $true }
    if ($Key.StartsWith('vc', [StringComparison]::Ordinal)) { return $true }
    return $false
}

# Baslik listesi tek satira: ilk Max baslik, kalani sayi olarak
function Get-PrepNudgeNames($Titles, [int]$Max = 2) {
    $all = @($Titles | Where-Object { [string]$_ -ne '' })
    $take = New-Object System.Collections.ArrayList
    foreach ($t in $all) { if ($take.Count -ge $Max) { break }; [void]$take.Add([string]$t) }
    $s = ($take.ToArray() -join ', ')
    $more = $all.Count - $take.Count
    if ($more -gt 0) { $s += ' ve ' + [string]$more + (' bile' + [char]0x015F + 'en daha') }
    return $s
}

# Saf mantik: denetim sonucundan uyari karari.
# @{ Show; Kind (bad | warn | info); Req (zorunlu eksik basliklari); Rec (onerilen eksik basliklari); Title; Text (onay penceresi); Toast (bildirim) }
function Get-PrepNudgeModel($State) {
    $m = @{ Show = $false; Kind = 'info'; Req = @(); Rec = @(); Title = ''; Text = ''; Toast = '' }
    if ($null -eq $State) { return $m }
    try { if ($State -is [hashtable] -and $State.ContainsKey('Failed') -and $State['Failed'] -eq $true) { return $m } } catch { }
    $items = $null
    try { $items = Get-PrepItems $State $false } catch { return $m }
    $req = New-Object System.Collections.ArrayList
    $rec = New-Object System.Collections.ArrayList
    foreach ($it in @($items)) {
        $st = [string]$it.Status
        if ($st -ne 'bad' -and $st -ne 'warn') { continue }
        if (-not (Test-PrepNudgeKey ([string]$it.Key))) { continue }
        if ($st -eq 'bad' -and [string]$it.Group -eq 'req') { [void]$req.Add([string]$it.Title) } else { [void]$rec.Add([string]$it.Title) }
    }
    $m.Req = $req.ToArray()
    $m.Rec = $rec.ToArray()
    if ($req.Count -eq 0 -and $rec.Count -eq 0) { return $m }
    $m.Show = $true
    if ($req.Count -gt 0) {
        $m.Kind = 'bad'
        $m.Title = ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k: eksik bile' + [char]0x015F + 'en var')
        $lines = New-Object System.Collections.ArrayList
        foreach ($t in $req) { if ($lines.Count -ge 4) { break }; [void]$lines.Add(('' + [char]0x2022 + '  ') + $t) }
        $txt = ('Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n d' + [char]0x00FC + 'zg' + [char]0x00FC + 'n ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in gereken ' + [char]0x015F + 'u bile' + [char]0x015F + 'enlerde sorun bulundu:') + "`r`n`r`n" + ($lines.ToArray() -join "`r`n")
        $more = $req.Count - $lines.Count
        if ($more -gt 0) { $txt += "`r`n" + ('' + [char]0x2022 + '  ve ') + [string]$more + (' bile' + [char]0x015F + 'en daha') }
        if ($rec.Count -gt 0) { $txt += "`r`n`r`n" + ('Ayr' + [char]0x0131 + 'ca ') + [string]$rec.Count + (' ' + [char]0x00F6 + 'nerilen bile' + [char]0x015F + 'en eksik ya da eski.') }
        $txt += "`r`n`r`n" + ('Nedenleri ve giderme ad' + [char]0x0131 + 'mlar' + [char]0x0131 + ' ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi > Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k sekmesinde. Bu denetim yaln' + [char]0x0131 + 'zca okudu: hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey kurulmad' + [char]0x0131 + ' ya da de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmedi. Bu uyar' + [char]0x0131 + ' bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde yeniden g' + [char]0x00F6 + 'sterilmez.')
        $m.Text = $txt
        $m.Toast = ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k: ') + [string]$req.Count + (' zorunlu bile' + [char]0x015F + 'ende sorun var (') + (Get-PrepNudgeNames $req.ToArray() 2) + ('). ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi > Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k sekmesine bak' + [char]0x0131 + 'n.')
        return $m
    }
    $m.Kind = 'warn'
    $m.Title = ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k: ' + [char]0x00F6 + 'neri var')
    $m.Text = ''
    $m.Toast = ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k: ') + [string]$rec.Count + (' ' + [char]0x00F6 + 'nerilen bile' + [char]0x015F + 'en eksik ya da eski (') + (Get-PrepNudgeNames $rec.ToArray() 2) + ('). ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi > Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k sekmesinden giderebilirsiniz.')
    return $m
}

# Uyari icin uygun an: pencere gorunur ve kucultulmemis, ilk calistirma ekrani bitmis, acik pencere (onay kutusu) ve calisan is yok
function Test-PrepNudgeReady {
    if (-not $script:Win.IsVisible) { return $false }
    if ($script:Win.WindowState -eq [System.Windows.WindowState]::Minimized) { return $false }
    if ($script:Settings.FirstRunDone -ne $true) { return $false }
    if ($ui.Overlay.Visibility -eq $script:VisOn) { return $false }
    if ($null -ne $script:Cur) { return $false }
    return $true
}

function Complete-PrepNudge($R) {
    if ($null -eq $R -or $R.Ok -ne $true -or $null -eq $R.State) {
        Write-WhLog ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' denetimi tamamlanamad' + [char]0x0131 + '; sonraki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta yeniden denenecek.') 'WARN'
        return
    }
    # surum bir kez isaretlenir: denetim sonucu ne olursa olsun ayni surumde yeniden sorulmaz
    try {
        $script:Settings.PrepSeen = [string]$script:AppVersion
        Save-Settings $script:Settings
    } catch { }
    $m = Get-PrepNudgeModel $R.State
    if ($m.Show -ne $true) {
        Write-WhLog ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k: eksik ya da eski bile' + [char]0x015F + 'en yok.') 'INFO'
        return
    }
    Write-WhLog (('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k: ') + [string]@($m.Req).Count + ' zorunlu, ' + [string]@($m.Rec).Count + (' ' + [char]0x00F6 + 'nerilen bile' + [char]0x015F + 'ende sorun var.')) 'WARN'
    $busy = $false
    try { if ($ui.Overlay.Visibility -eq $script:VisOn) { $busy = $true } } catch { }
    if ($m.Kind -eq 'bad' -and -not $busy) {
        Show-Confirm ([string]$m.Title) ([string]$m.Text) ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k sekmesini a' + [char]0x00E7 + '') { Open-Page 'solve' 'prep' }
    } else {
        $k = 'warn'
        if ($m.Kind -eq 'bad') { $k = 'bad' }
        Show-Toast ([string]$m.Toast) $k
    }
}

function Start-PrepNudgeCheck {
    $ok = $false
    try {
        $ok = Start-Async 'PrepNudge' 'Job_PrepCheck' @{ NoNet = $true } {
            param($r)
            Complete-PrepNudge $r
        } ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k denetleniyor') $true $true
    } catch { Write-CrashLog (('PrepNudge ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    if ($ok -ne $true) { Write-WhLog ('Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' denetimi ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '; sonraki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta yeniden denenecek.') 'WARN' }
}

function Invoke-PrepNudgeTick {
    if ([string]$script:Settings.PrepSeen -eq [string]$script:AppVersion) { $script:PrepNudgeTimer.Stop(); return }
    $script:PrepNudgeTicks = [int]$script:PrepNudgeTicks + 1
    if (-not (Test-PrepNudgeReady)) { return }
    $script:PrepNudgeTimer.Stop()
    Start-PrepNudgeCheck
}

# Acilista cagrilir: bu surumde henuz denetlenmediyse zamanlayiciyi kurar. Duman testinde ve otomatik testlerde calismaz.
function Initialize-PrepNudge {
    if ($script:SmokeMode -eq $true) { return }
    if ([string]$script:Settings.PrepSeen -eq [string]$script:AppVersion) { return }
    $script:PrepNudgeTicks = 0
    $script:PrepNudgeTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:PrepNudgeTimer.Interval = [TimeSpan]::FromSeconds(20)
    $script:PrepNudgeTimer.Add_Tick({
        try { Invoke-PrepNudgeTick } catch { Write-CrashLog ('PrepNudge: ' + $_.Exception.Message) }
    })
    $script:PrepNudgeTimer.Start()
}

# ---------------- dis araclar: Araclar sayfasi sekmesi ----------------
# ==================================================================
#  DIS ARACLAR (saglayici katmani): arayuz
#  Araclar > Dis araclar sekmesi. Liste, 132_exttools_core.ps1 icindeki sabit katalogdan gelir. Kurulu olanlar tek tikla acilir;
#  eksik olanlar yalnizca onayla ve Microsoft'un winget araciyla kurulur. "Sayfa" dugmesi aracin resmi sayfasini tarayicida acar.
#  Denetim yalnizca dosya var mi diye bakar; hicbir arac kendiliginden kurulmaz, guncellenmez ya da calistirilmaz.
# ==================================================================
$script:ExtToolState = $null
$script:ExtToolLoading = $false
$script:ExtToolPending = $null

# Grup listesi: @( @{ K; T } )
function Get-ExtToolGroups {
    $out = New-Object System.Collections.ArrayList
    foreach ($g in $script:ExtToolGroups) {
        $f = ([string]$g).Split('|')
        if ($f.Count -ge 2) { [void]$out.Add(@{ K = $f[0]; T = $f[1] }) }
    }
    return , $out.ToArray()
}

# Denetim sonucundan bir aracin durumu; kayit yoksa kurulu degil sayilir
function Get-ExtToolStateFor($State, [string]$Id) {
    $items = $null
    try { $items = $State.Items } catch { $items = $null }
    foreach ($i in @($items)) {
        if ($null -ne $i -and [string]$i.Id -eq $Id) { return $i }
    }
    return @{ Id = $Id; Installed = $false; Path = '' }
}

# Saf mantik: bir arac satirinin gorunumu ve veri nesnesi
function Get-ExtToolRowModel($Tool, $St, [bool]$Expert = $false) {
    $installed = ($null -ne $St -and $St.Installed -eq $true)
    $path = ''
    if ($installed) { $path = [string]$St.Path }
    $det = [string]$Tool.Publisher + (' ' + [char]0x00B7 + ' ') + [string]$Tool.Desc
    if ($Expert) { $det += (' ' + [char]0x00B7 + ' winget: ') + [string]$Tool.Id }
    $m = @{ Title = [string]$Tool.Name; Detail = $det; Tag = ('Kurulu de' + [char]0x011F + 'il'); BrCol = 'BrFaint'; Btn1 = 'Kur'; Btn2 = 'Sayfa' }
    if ($installed) { $m.Tag = 'Kurulu'; $m.BrCol = 'BrGood'; $m.Btn1 = ('A' + [char]0x00E7 + '') }
    $m.Data = @{ Id = [string]$Tool.Id; Name = [string]$Tool.Name; Home = [string]$Tool.Home; Path = $path; Installed = $installed }
    return $m
}

# Kurulum onay penceresinin metni
function Get-ExtToolConfirmText($Tool) {
    $b = [string][char]0x2022 + '  '
    $txt = ('' + [char]0x201C + '') + [string]$Tool.Name + ('' + [char]0x201D + ' (') + [string]$Tool.Publisher + (') Microsoft' + [char]0x2019 + 'un winget arac' + [char]0x0131 + 'yla kurulacak.') + "`r`n`r`n"
    $txt += $b + ('Paket winget deposundan indirilir; paket ' + [char]0x00F6 + 'zeti (SHA-256) winget taraf' + [char]0x0131 + 'ndan do' + [char]0x011F + 'rulan' + [char]0x0131 + 'r, uyu' + [char]0x015F + 'mazsa kurulmaz.') + "`r`n"
    $txt += $b + ('' + [char]0x201C + 'Kur' + [char]0x201D + 'a basarak arac' + [char]0x0131 + 'n lisans ko' + [char]0x015F + 'ullar' + [char]0x0131 + 'n' + [char]0x0131 + ' kabul etmi' + [char]0x015F + ' olursunuz. Ko' + [char]0x015F + 'ullar' + [char]0x0131 + ' ' + [char]0x00F6 + 'nce ' + [char]0x201C + 'Sayfa' + [char]0x201D + ' d' + [char]0x00FC + '' + [char]0x011F + 'mesiyle yay' + [char]0x0131 + 'nc' + [char]0x0131 + 'n' + [char]0x0131 + 'n sayfas' + [char]0x0131 + 'ndan okuyabilirsiniz.') + "`r`n"
    $txt += $b + ('' + [char]0x0130 + 'nternet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' gerekir. Windows, kurulum i' + [char]0x00E7 + 'in y' + [char]0x00F6 + 'netici onay' + [char]0x0131 + ' isteyebilir.') + "`r`n"
    $txt += $b + ('Ara' + [char]0x00E7 + ' Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n par' + [char]0x00E7 + 'as' + [char]0x0131 + ' de' + [char]0x011F + 'ildir; g' + [char]0x00FC + 'ncellemesini ve deste' + [char]0x011F + 'ini kendi yay' + [char]0x0131 + 'nc' + [char]0x0131 + 's' + [char]0x0131 + ' sa' + [char]0x011F + 'lar. Ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + 'za ve ki' + [char]0x015F + 'isel dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'za dokunulmaz.')
    return $txt
}

# Kurulum isinin sonucu -> bildirim: @{ Text; Kind (good | warn | bad) }
function Get-ExtToolInstallModel($R) {
    if ($null -eq $R) { return @{ Text = ('Kurulum tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.'); Kind = 'bad' } }
    $name = [string](Get-JsonProp $R 'Name')
    if ($name -eq '') { $name = [string](Get-JsonProp $R 'Id') }
    if ($name -eq '') { $name = ('Ara' + [char]0x00E7 + '') }
    $text = [string](Get-JsonProp $R 'Text')
    if ((Get-JsonProp $R 'Ok') -ne $true) {
        if ($text -eq '') { $text = 'bilinmeyen hata' }
        return @{ Text = ($name + (' kurulamad' + [char]0x0131 + ': ') + $text); Kind = 'bad' }
    }
    $kind = 'good'
    $t = $name + ' kuruldu.'
    if ((Get-JsonProp $R 'Already') -eq $true) { $t = $name + (' zaten kuruluymu' + [char]0x015F + '.') }
    if ([string](Get-JsonProp $R 'Path') -ne '') { $t += (' ' + [char]0x201C + 'A' + [char]0x00E7 + '' + [char]0x201D + ' ile ba' + [char]0x015F + 'latabilirsiniz.') }
    else { $t += (' ' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir dosya beklenen konumda bulunamad' + [char]0x0131 + '; Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + 'nden a' + [char]0x00E7 + 'abilirsiniz.'); $kind = 'warn' }
    if ((Get-JsonProp $R 'Reboot') -eq $true) { $t += (' Etkili olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.'); $kind = 'warn' }
    return @{ Text = $t; Kind = $kind }
}

# ---------------- cizim ----------------
function Load-TlExt {
    if ($script:ExtToolLoading -eq $true) { return }
    $script:ExtToolLoading = $true
    $ok = Start-Async 'ExtScan' 'Job_ExtToolScan' @{} {
        param($r)
        Complete-TlExt $r
    } ('D' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + 'lar denetleniyor') $true $true
    if (-not $ok) { $script:ExtToolLoading = $false }
}

function Complete-TlExt($R) {
    $script:ExtToolLoading = $false
    if ($null -eq $R -or $R.Ok -ne $true) { $script:ExtToolState = @{ Failed = $true } } else { $script:ExtToolState = $R }
    if ([string]$script:UiState.Page -eq 'tools' -and $script:TlTab -eq 'ext') { Render-TlExt }
}

$script:H_TlExtAct = { param($s, $e) Invoke-Safe { Invoke-TlExtAction $s.Tag } ('D' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + '') }
$script:H_TlExtPage = { param($s, $e) Invoke-Safe { Open-Url ([string]$s.Tag.Home) } 'Sayfa' }

function Render-TlExt {
    $ui.tl_List.Children.Clear()
    $S = $script:ExtToolState
    if ($null -eq $S) {
        Add-Note $ui.tl_List ('D' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + 'lar denetleniyor...')
        Load-TlExt
        return
    }
    if ($S.Failed -eq $true) {
        Add-Note $ui.tl_List ('Denetim yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '. ' + [char]0x201C + 'Yenile' + [char]0x201D + 'ye basarak yeniden deneyin; sorun s' + [char]0x00FC + 'rerse g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn'
        return
    }
    $expert = ([string]$script:UiState.Mode -eq 'Expert')
    Add-Note $ui.tl_List ('Bunlar kendi alan' + [char]0x0131 + 'nda yerle' + [char]0x015F + 'ik, s' + [char]0x00FC + 'rekli geli' + [char]0x015F + 'tirilen ara' + [char]0x00E7 + 'lard' + [char]0x0131 + 'r; Multimizer onlar' + [char]0x0131 + ' kopyalamaz, yaln' + [char]0x0131 + 'zca kurulu olup olmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'na bakar. Eksik olan, yaln' + [char]0x0131 + 'zca onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla ve Microsoft' + [char]0x2019 + 'un winget arac' + [char]0x0131 + 'yla (paket ' + [char]0x00F6 + 'zeti do' + [char]0x011F + 'rulanarak) kurulur.')
    $cat = Get-ExtToolCatalog
    foreach ($g in (Get-ExtToolGroups)) {
        $tools = @($cat | Where-Object { [string]$_.Group -eq [string]$g.K })
        if ($tools.Count -eq 0) { continue }
        Add-HeadRow $ui.tl_List ([string]$g.T)
        foreach ($t in $tools) {
            $m = Get-ExtToolRowModel $t (Get-ExtToolStateFor $S ([string]$t.Id)) $expert
            $row = New-ItemRow @{ Title = $m.Title; Detail = $m.Detail; Tag = $m.Tag; BrCol = $m.BrCol; Btn1 = $m.Btn1; Btn2 = $m.Btn2 } $m.Data $false $false
            $row.FindName('Act').Add_Click($script:H_TlExtAct)
            $row.FindName('Act2').Add_Click($script:H_TlExtPage)
            [void]$ui.tl_List.Children.Add($row)
        }
    }
    $ui.tl_Foot.Text = (Tr $('Denetlendi: ' + [string]$S.At + ('  ' + [char]0x00B7 + '  Kurulumdan sonra ' + [char]0x201C + 'Yenile' + [char]0x201D + 'ye basarak sonucu do' + [char]0x011F + 'rulay' + [char]0x0131 + 'n.')))
}

# ---------------- islemler ----------------
function Invoke-TlExtAction($T) {
    if ($null -eq $T) { return }
    if ($T.Installed -eq $true) { Open-ExtTool $T; return }
    Start-ExtToolInstall $T
}

# Kurulu araci acar; dosya denetimden sonra silinmisse listeyi yeniler
function Open-ExtTool($T) {
    $p = [string]$T.Path
    if ($p -eq '' -or -not (Test-Path -LiteralPath $p -PathType Leaf)) {
        Show-Toast ([string]$T.Name + (' bulunamad' + [char]0x0131 + '; liste yenileniyor.')) 'warn'
        $script:ExtToolState = $null
        Render-TlExt
        return
    }
    Write-WhLog (('D' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'yor: ') + [string]$T.Name) 'INFO'
    Open-Path $p
}

# T: satirin veri nesnesi. Onaylanmadan hicbir sey indirilmez ya da kurulmaz.
function Start-ExtToolInstall($T) {
    $why = Test-ExtToolId ([string]$T.Id)
    if ($why -ne '') { Show-Message ('Bu ara' + [char]0x00E7 + ' kurulamaz') $why; return }
    $tool = Get-ExtTool ([string]$T.Id)
    $script:ExtToolPending = $tool
    Show-Confirm ('D' + [char]0x0131 + '' + [char]0x015F + ' arac' + [char]0x0131 + ' kur') (Get-ExtToolConfirmText $tool) 'Kur' {
        $t = $script:ExtToolPending
        if ($null -eq $t) { return }
        [void](Start-Async 'ExtInstall' 'Job_ExtToolInstall' @{ Id = [string]$t.Id } {
            param($r)
            Complete-ExtToolInstall $r
        } ([string]$t.Name + ' kuruluyor'))
    }
}

function Complete-ExtToolInstall($R) {
    $script:ExtToolPending = $null
    $script:ExtToolState = $null
    $m = Get-ExtToolInstallModel $R
    Show-Toast ([string]$m.Text) ([string]$m.Kind)
    if ([string]$script:UiState.Page -eq 'tools' -and $script:TlTab -eq 'ext') { Render-TlExt }
}

# "Yenile" dugmesi: acik sekmeye gore
function Invoke-TlRefresh {
    if ($script:TlTab -eq 'ext') { $script:ExtToolState = $null; Render-TlExt; return }
    $script:TlProcs = $null
    Render-TlProcs
}

# ---------------- guncelleme denetimi: Ayarlar karti ----------------
# ==================================================================
#  GUNCELLEME DENETIMI: arayuz (Ayarlar > Uygulama karti)
#  Hicbir sey kendiliginden calismaz: "Guncellemeleri denetle"ye ve "Indir"e yalnizca siz basarsiniz. Indirme ayrica onay penceresinden gecer.
#  Indirilen ZIP acilmaz ve calistirilmaz; SHA-256 ozeti bildirimdekiyle tutmazsa dosya silinir.
#  Ayni kartta "Dosya butunlugunu denetle" dugmesi, yan dosyalarin (Eklenti, veri) derleme sirasinda yazilan ozetlerle tutup tutmadigina bakar.
# ==================================================================
$script:UpdLast = $null
$script:UpdBusy = $false
$script:UpdPending = $null
$script:UpdGot = ''
$script:UpdDone = $null
$script:IntBusy = $false

# Metin denetimine renk turune gore yazar (good | warn | bad | dim)
function Set-StUpdText($Ctl, [string]$Text, [string]$Kind = 'dim') {
    $Ctl.Text = (Tr $($Text))
    $key = 'BrDim'
    if ($Kind -eq 'bad') { $key = 'BrBad' } elseif ($Kind -eq 'good') { $key = 'BrGood' } elseif ($Kind -eq 'warn') { $key = 'BrWarn' }
    $Ctl.Foreground = (Get-Br $key)
}

# Saf mantik: denetim sonucundan gorunum. R bossa henuz denetlenmemistir.
# Donus: @{ Text; Kind; CanGet; Page; Info }
function Get-UpdateStateModel($R, [string]$Current) {
    $m = @{ Text = ''; Kind = 'dim'; CanGet = $false; Page = ''; Info = $null }
    if ($null -eq $R) {
        $m.Text = ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an s' + [char]0x00FC + 'r' + [char]0x00FC + 'm: ') + $Current + ('. G' + [char]0x00FC + 'ncelleme denetimi yaln' + [char]0x0131 + 'zca ' + [char]0x201C + 'G' + [char]0x00FC + 'ncellemeleri denetle' + [char]0x201D + 'ye bast' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r; uygulama kendili' + [char]0x011F + 'inden hi' + [char]0x00E7 + 'bir adrese ba' + [char]0x011F + 'lanmaz.')
        return $m
    }
    if ((Get-JsonProp $R 'Ok') -ne $true) {
        $e = [string](Get-JsonProp $R 'Error')
        if ($e -eq '') { $e = 'bilinmeyen hata' }
        $m.Text = ('Denetim yap' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $e
        $m.Kind = 'bad'
        return $m
    }
    $info = Get-JsonProp $R 'Info'
    $latest = [string](Get-JsonProp $R 'Latest')
    $at = [string](Get-JsonProp $R 'At')
    $m.Info = $info
    $m.Page = [string](Get-JsonProp $info 'Page')
    $cmp = Compare-AppVersion $latest $Current
    if ($cmp -eq 1) {
        $m.Kind = 'warn'
        $t = ('Yeni s' + [char]0x00FC + 'r' + [char]0x00FC + 'm var: ') + $latest + (' (' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an: ') + $Current + ').'
        $notes = [string](Get-JsonProp $info 'Notes')
        if ($notes -ne '') { $t += "`r`n" + $notes }
        if ((Get-JsonProp $info 'Download') -eq $true) {
            $m.CanGet = $true
            $t += "`r`n" + ('' + [char]0x0130 + 'ndirme haz' + [char]0x0131 + 'r')
            $sz = [long](Get-JsonProp $info 'Size')
            if ($sz -gt 0) { $t += ' (' + (Format-Size $sz) + ')' }
            $t += ('; ' + [char]0x201C + '' + [char]0x0130 + 'ndir' + [char]0x201D + 'e bast' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda ' + [char]0x00F6 + 'nce onay' + [char]0x0131 + 'n' + [char]0x0131 + 'z istenir.')
        } else {
            $t += "`r`n" + ('' + [char]0x0130 + 'ndirme kapal' + [char]0x0131 + ': ') + [string](Get-JsonProp $info 'Why')
        }
        $m.Text = $t + "`r`n" + 'Denetlendi: ' + $at
        return $m
    }
    $m.Kind = 'good'
    if ($cmp -eq 0) { $m.Text = ('G' + [char]0x00FC + 'ncelsiniz: ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an s' + [char]0x00FC + 'r' + [char]0x00FC + 'm (') + $Current + (') yay' + [char]0x0131 + 'mlanan en son s' + [char]0x00FC + 'r' + [char]0x00FC + 'mle ayn' + [char]0x0131 + '.') }
    elseif ($cmp -eq -1) { $m.Text = ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an s' + [char]0x00FC + 'r' + [char]0x00FC + 'm (') + $Current + ('), yay' + [char]0x0131 + 'mlanan en son s' + [char]0x00FC + 'r' + [char]0x00FC + 'mden (') + $latest + (') daha yeni; yap' + [char]0x0131 + 'lacak bir ' + [char]0x015F + 'ey yok.') }
    else { $m.Kind = 'warn'; $m.Text = ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'mler kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an: ') + $Current + (', yay' + [char]0x0131 + 'mlanan: ') + $latest + ').' }
    $m.Text += ' Denetlendi: ' + $at
    return $m
}

# Indirme onay penceresinin metni
function Get-UpdateConfirmText($Info) {
    $b = [string][char]0x2022 + '  '
    $hostName = ''
    try { $hostName = (New-Object System.Uri([string](Get-JsonProp $Info 'Url'))).Host } catch { $hostName = '' }
    $t = 'Multimizer ' + [string](Get-JsonProp $Info 'Version') + ' indirilecek.' + "`r`n`r`n"
    $t += $b + 'Kaynak: ' + $hostName + (' (yaln' + [char]0x0131 + 'zca HTTPS).') + "`r`n"
    $sz = [long](Get-JsonProp $Info 'Size')
    if ($sz -gt 0) { $t += $b + 'Boyut: ' + (Format-Size $sz) + "`r`n" }
    $t += $b + ('' + [char]0x0130 + 'ndirilen dosyan' + [char]0x0131 + 'n SHA-256 ' + [char]0x00F6 + 'zeti bildirimdekiyle kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r; tutmazsa dosya silinir.') + "`r`n"
    $t += $b + ('Dosya yaln' + [char]0x0131 + 'zca indirilir; a' + [char]0x00E7 + '' + [char]0x0131 + 'lmaz, kurulmaz, ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz. Kurmak i' + [char]0x00E7 + 'in ZIP' + [char]0x2019 + 'i kendiniz bir klas' + [char]0x00F6 + 're ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'r, yeni s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde Ayarlar > Uygulama > ' + [char]0x201C + 'Kur / g' + [char]0x00FC + 'ncelle' + [char]0x201D + 'yi kullan' + [char]0x0131 + 'rs' + [char]0x0131 + 'n' + [char]0x0131 + 'z.') + "`r`n"
    $t += $b + ('SHA-256 dosyan' + [char]0x0131 + 'n bozulmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00F6 + 'sterir, yay' + [char]0x0131 + 'nc' + [char]0x0131 + 'n' + [char]0x0131 + 'n kimli' + [char]0x011F + 'ini kan' + [char]0x0131 + 'tlamaz; adresin g' + [char]0x00FC + 'vendi' + [char]0x011F + 'iniz kayna' + [char]0x011F + 'a ait oldu' + [char]0x011F + 'undan emin olun.')
    return $t
}

# Indirme isinin sonucu -> gorunum: @{ Text; Kind; Path }
function Get-UpdateDoneModel($R) {
    if ($null -eq $R) { return @{ Text = ('' + [char]0x0130 + 'ndirme tamamlanamad' + [char]0x0131 + '. Ayarlar > ' + [char]0x0130 + 'nternet istekleri b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nde ' + [char]0x201C + 'G' + [char]0x00FC + 'ncelleme denetimi ve indirme' + [char]0x201D + ' kapal' + [char]0x0131 + ' olabilir; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.'); Kind = 'bad'; Path = '' } }
    if ((Get-JsonProp $R 'Ok') -ne $true) {
        $e = [string](Get-JsonProp $R 'Error')
        if ($e -eq '') { $e = 'bilinmeyen hata' }
        return @{ Text = ('' + [char]0x0130 + 'ndirilemedi: ') + $e; Kind = 'bad'; Path = '' }
    }
    $p = [string](Get-JsonProp $R 'Path')
    $t = ('' + [char]0x0130 + 'ndirildi ve SHA-256 ' + [char]0x00F6 + 'zeti do' + [char]0x011F + 'ruland' + [char]0x0131 + ': ') + $p
    if ((Get-JsonProp $R 'Already') -eq $true) { $t = ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'm zaten indirilmi' + [char]0x015F + ' ve ' + [char]0x00F6 + 'zeti do' + [char]0x011F + 'ru: ') + $p }
    $sz = [long](Get-JsonProp $R 'Size')
    if ($sz -gt 0) { $t += ' (' + (Format-Size $sz) + ')' }
    $t += "`r`n" + ('ZIP' + [char]0x2019 + 'i bir klas' + [char]0x00F6 + 're ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'n; yeni s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'p Ayarlar > Uygulama > ' + [char]0x201C + 'Kur / g' + [char]0x00FC + 'ncelle' + [char]0x201D + 'ye bas' + [char]0x0131 + 'n. Bu dosyaya Multimizer dokunmaz.')
    return @{ Text = $t; Kind = 'good'; Path = $p }
}

# Dosya butunlugu sonucu -> gorunum: @{ Text; Kind }
function Get-IntegrityModel($R, [bool]$Expert = $false) {
    if ($null -eq $R -or (Get-JsonProp $R 'Ok') -ne $true) {
        $e = [string](Get-JsonProp $R 'Error')
        if ($e -eq '') { $e = 'bilinmeyen hata' }
        return @{ Text = 'Denetlenemedi: ' + $e; Kind = 'bad' }
    }
    $total = [int](Get-JsonProp $R 'Total')
    $good = [int](Get-JsonProp $R 'Good')
    $bad = @(Get-JsonProp $R 'Bad' | Where-Object { $null -ne $_ })
    $m = @{ Text = ''; Kind = 'good' }
    if ($bad.Count -eq 0) {
        $m.Text = ('Yan dosyalar (Eklenti, veri) eksiksiz ve do' + [char]0x011F + 'ru: ') + [string]$good + ' / ' + [string]$total + '.'
    } else {
        $parts = New-Object System.Collections.ArrayList
        foreach ($b in $bad) {
            $why = ('' + [char]0x00F6 + 'zeti uyu' + [char]0x015F + 'muyor')
            $k = [string](Get-JsonProp $b 'Kind')
            if ($k -eq 'missing') { $why = 'yok' } elseif ($k -eq 'read') { $why = ('okunamad' + [char]0x0131 + '') }
            [void]$parts.Add([string](Get-JsonProp $b 'Rel') + ' (' + $why + ')')
        }
        $m.Kind = 'warn'
        $m.Text = 'Sorunlu yan dosya: ' + ($parts.ToArray() -join ', ') + ('. ' + [char]0x0130 + 'lgili ' + [char]0x00F6 + 'zellikler kullan' + [char]0x0131 + 'lamayabilir; ZIP dosyas' + [char]0x0131 + 'n' + [char]0x0131 + ' eksiksiz yeniden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'n.')
    }
    $h = [string](Get-JsonProp $R 'ScriptSha256')
    if ($Expert -and $h -ne '') { $m.Text += "`r`n" + ('Beti' + [char]0x011F + 'in SHA-256 ' + [char]0x00F6 + 'zeti: ') + $h }
    $m.Text += "`r`n" + 'Denetlendi: ' + [string](Get-JsonProp $R 'At')
    return $m
}

# ---------------- gorunum ----------------
function Update-StUpdateView {
    $m = Get-UpdateStateModel $script:UpdLast ([string]$script:AppVersion)
    $text = [string]$m.Text
    $kind = [string]$m.Kind
    $d = $script:UpdDone
    if ($null -ne $d) {
        $text += "`r`n`r`n" + [string]$d.Text
        if ([string]$d.Kind -eq 'bad') { $kind = 'bad' }
    }
    Set-StUpdText $ui.st_UpdState $text $kind
    $busy = ($script:UpdBusy -eq $true)
    $ui.st_UpdCheck.IsEnabled = (-not $busy)
    $ui.st_UpdGet.IsEnabled = (-not $busy)
    if ($m.CanGet -eq $true) { $ui.st_UpdGet.Visibility = $script:VisOn } else { $ui.st_UpdGet.Visibility = $script:VisOff }
    if ([string]$m.Page -ne '') { $ui.st_UpdPage.Visibility = $script:VisOn } else { $ui.st_UpdPage.Visibility = $script:VisOff }
    if ([string]$script:UpdGot -ne '') { $ui.st_UpdFolder.Visibility = $script:VisOn } else { $ui.st_UpdFolder.Visibility = $script:VisOff }
    $ui.st_IntCheck.IsEnabled = ($script:IntBusy -ne $true)
}

function Load-StUpdate {
    $u = ''
    try { $u = [string]$script:Settings.UpdateUrl } catch { $u = '' }
    $ui.st_UpdUrl.Text = (Tr $($u))
    Update-StUpdateView
}

# Adres kutusundaki degeri dogrular ve kaydeder; gecersizse kaydetmez ve nedenini soyler
function Save-StUpdateUrl {
    $t = ([string]$ui.st_UpdUrl.Text).Trim()
    $cur = ''
    try { $cur = [string]$script:Settings.UpdateUrl } catch { $cur = '' }
    if ($t -eq $cur) { return $true }
    if ($t -ne '') {
        $why = Test-UpdateUrl $t
        if ($why -ne '') { Show-Toast $why 'warn'; return $false }
    }
    $script:Settings.UpdateUrl = $t
    Save-Settings $script:Settings
    $script:UpdLast = $null
    $script:UpdDone = $null
    Update-StUpdateView
    return $true
}

# ---------------- islemler ----------------
function Start-UpdateCheck {
    if ($script:UpdBusy -eq $true) { return }
    if (-not (Save-StUpdateUrl)) { return }
    $url = ''
    try { $url = [string]$script:Settings.UpdateUrl } catch { $url = '' }
    $why = Test-UpdateUrl $url
    if ($why -ne '') { Show-Toast $why 'warn'; return }
    $script:UpdBusy = $true
    $script:UpdDone = $null
    Update-StUpdateView
    $ok = Start-Async 'UpdCheck' 'Job_UpdateCheck' @{ Url = $url; Current = [string]$script:AppVersion } {
        param($r)
        Complete-UpdateCheck $r
    } ('G' + [char]0x00FC + 'ncelleme denetleniyor')
    if (-not $ok) { $script:UpdBusy = $false; Update-StUpdateView }
}

function Complete-UpdateCheck($R) {
    $script:UpdBusy = $false
    if ($null -eq $R) { $R = @{ Ok = $false; Error = ('' + [char]0x0130 + '' + [char]0x015F + ' sonu' + [char]0x00E7 + ' d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'rmedi. Ayarlar > ' + [char]0x0130 + 'nternet istekleri b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nde ' + [char]0x201C + 'G' + [char]0x00FC + 'ncelleme denetimi ve indirme' + [char]0x201D + ' kapal' + [char]0x0131 + ' olabilir; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') } }
    $script:UpdLast = $R
    $script:UpdDone = $null
    Update-StUpdateView
    $m = Get-UpdateStateModel $R ([string]$script:AppVersion)
    $first = ([string]$m.Text -split "\r?\n")[0]
    Show-Toast $first ([string]$m.Kind)
}

# Onay penceresi acilir; "Indir" denmeden hicbir sey indirilmez
function Start-UpdateDownload {
    if ($script:UpdBusy -eq $true) { return }
    $m = Get-UpdateStateModel $script:UpdLast ([string]$script:AppVersion)
    if ($m.CanGet -ne $true -or $null -eq $m.Info) { Show-Toast ('' + [char]0x00D6 + 'nce ' + [char]0x201C + 'G' + [char]0x00FC + 'ncellemeleri denetle' + [char]0x201D + 'ye bas' + [char]0x0131 + 'n; indirilebilir bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'm bulunamad' + [char]0x0131 + '.') 'warn'; return }
    $script:UpdPending = $m.Info
    Show-Confirm ('G' + [char]0x00FC + 'ncellemeyi indir') (Get-UpdateConfirmText $m.Info) ('' + [char]0x0130 + 'ndir') {
        $i = $script:UpdPending
        if ($null -eq $i) { return }
        $script:UpdBusy = $true
        Update-StUpdateView
        $ok = Start-Async 'UpdDownload' 'Job_UpdateDownload' @{ Url = [string]$i.Url; Sha256 = [string]$i.Sha256; Version = [string]$i.Version; Size = [long]$i.Size } {
            param($r)
            Complete-UpdateDownload $r
        } ('G' + [char]0x00FC + 'ncelleme indiriliyor')
        if (-not $ok) { $script:UpdBusy = $false; Update-StUpdateView }
    }
}

function Complete-UpdateDownload($R) {
    $script:UpdBusy = $false
    $script:UpdPending = $null
    $m = Get-UpdateDoneModel $R
    if ([string]$m.Path -ne '') { $script:UpdGot = [string]$m.Path }
    $script:UpdDone = @{ Text = [string]$m.Text; Kind = [string]$m.Kind }
    Update-StUpdateView
    Show-Toast ([string]($m.Text -split "\r?\n")[0]) ([string]$m.Kind)
}

function Start-IntegrityCheck {
    if ($script:IntBusy -eq $true) { return }
    $script:IntBusy = $true
    Update-StUpdateView
    $ok = Start-Async 'IntCheck' 'Job_IntegrityCheck' @{} {
        param($r)
        Complete-IntegrityCheck $r
    } ('Dosya b' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' denetleniyor') $true
    if (-not $ok) { $script:IntBusy = $false; Update-StUpdateView }
}

function Complete-IntegrityCheck($R) {
    $script:IntBusy = $false
    $m = Get-IntegrityModel $R ([string]$script:UiState.Mode -eq 'Expert')
    Set-StUpdText $ui.st_IntState ([string]$m.Text) ([string]$m.Kind)
    Update-StUpdateView
    Show-Toast ([string]($m.Text -split "\r?\n")[0]) ([string]$m.Kind)
}

function Init-StUpdate {
    $ui.st_UpdUrl.Add_LostFocus({ if (-not $script:StLoading) { Invoke-Safe { [void](Save-StUpdateUrl) } ('G' + [char]0x00FC + 'ncelleme') } })
    $ui.st_UpdCheck.Add_Click({ Invoke-Safe { Start-UpdateCheck } ('G' + [char]0x00FC + 'ncelleme') })
    $ui.st_UpdGet.Add_Click({ Invoke-Safe { Start-UpdateDownload } ('G' + [char]0x00FC + 'ncelleme') })
    $ui.st_UpdPage.Add_Click({
        Invoke-Safe {
            $m = Get-UpdateStateModel $script:UpdLast ([string]$script:AppVersion)
            $p = [string]$m.Page
            if ($p -ne '' -and (Test-UpdateUrl $p) -eq '') { Open-Url $p }
        } ('S' + [char]0x00FC + 'r' + [char]0x00FC + 'm sayfas' + [char]0x0131 + '')
    })
    $ui.st_UpdFolder.Add_Click({ Invoke-Safe { Open-Folder (Get-UpdateDir) } ('Klas' + [char]0x00F6 + 'r') })
    $ui.st_IntCheck.Add_Click({ Invoke-Safe { Start-IntegrityCheck } ('B' + [char]0x00FC + 't' + [char]0x00FC + 'nl' + [char]0x00FC + 'k') })
}

# ---------------- dil destegi: Ayarlar karti ve kalite denetimi ----------------
# ==================================================================
#  DIL DESTEGI: Ayarlar karti, yeniden baslatma, kalite denetimi
# ==================================================================
# Dil secimi yeniden baslatmayla uygulanir: butun ekran metinleri acilista bir kez cevrilir (parcalar ve satirlar olusturulurken).
# Secilen dil Ayarlar'a "Language" olarak yazilir; "auto" Windows ekran dilini izler.

$script:LangPending = ''

function Get-LangChoiceName($L) {
    $n = [string]$L.Native
    $e = [string]$L.English
    $t = $n
    if ($n -cne $e) { $t = $n + ' (' + $e + ')' }
    $cov = 0
    try { $cov = [int]$L.Coverage } catch { $cov = 0 }
    if ([string]$L.Code -ne 'tr' -and $cov -gt 0 -and $cov -lt 100) { $t = $t + '  -  ' + (Format-Percent $cov) }
    # dil adlari ozel addir; kalite denetiminde eksik cevirisi sayilmaz
    if ($null -ne $script:LangOut) { [void]$script:LangOut.Add($t) }
    return $t
}

function Get-LangFolderUser {
    $pd = ''
    try { $pd = [Environment]::GetFolderPath('CommonApplicationData') } catch { $pd = '' }
    if ($pd -eq '') { return '' }
    return [System.IO.Path]::Combine($pd, 'Multimizer', 'dil')
}

function Get-LangEntry([string]$Code) {
    foreach ($l in @(Get-LangList)) { if ([string]$l.Code -eq $Code) { return $l } }
    return $null
}

# Ayarlar > Dil karti: acilir listeyi doldurur (Otomatik + Turkce + bulunan dil dosyalari)
function Initialize-StLang {
    if ($null -eq $ui.st_LangSel) { return }
    $ch = New-Object System.Collections.ArrayList
    [void]$ch.Add((New-Choice 'auto' 'Otomatik (Windows ekran dili)'))
    foreach ($l in @(Get-LangList $true)) { [void]$ch.Add((New-Choice ([string]$l.Code) (Get-LangChoiceName $l))) }
    Set-ComboChoices $ui.st_LangSel $ch.ToArray()
}

# Kayitli dil secimini listede gosterir (secim olayi kayit yapmaz)
function Load-StLang {
    if ($null -eq $ui.st_LangSel) { return }
    $want = 'auto'
    try { $v = [string]$script:Settings.Language; if ($v.Trim() -ne '') { $want = $v.Trim().ToLowerInvariant() } } catch { }
    if ($want -ne 'auto') { $want = Resolve-LangCode $want }
    if (-not (Select-ComboKey $ui.st_LangSel $want)) { [void](Select-ComboKey $ui.st_LangSel 'auto') }
    $script:LangPending = ''
    Update-StLangNote
}

# Secim, kayitli ayardan ya da calisan dilden farkliysa "Uygula" etkinlesir; kapsam yuzdesi ve uyari yazilir
function Update-StLangNote {
    if ($null -eq $ui.st_LangNote) { return }
    $key = Get-ComboKey $ui.st_LangSel
    if ($key -eq '') { $key = 'auto' }
    $stored = 'auto'
    try { $v = [string]$script:Settings.Language; if ($v.Trim() -ne '') { $stored = $v.Trim().ToLowerInvariant() } } catch { }
    $eff = $key
    if ($key -eq 'auto') { $eff = Get-SystemLangCode }
    $pending = (($key -ne $stored) -or ($eff -ne [string]$script:LangCode))
    $ui.st_LangApply.IsEnabled = $pending
    $cov = 100
    $e = Get-LangEntry $eff
    if ($null -ne $e) { $cov = [int]$e.Coverage }
    $msg = ''
    if ($eff -eq 'tr') {
        $msg = ('Uygulaman' + [char]0x0131 + 'n kaynak dili T' + [char]0x00FC + 'rk' + [char]0x00E7 + 'edir; t' + [char]0x00FC + 'm metinler eksiksizdir.')
    } elseif ($cov -ge 100 -or $cov -le 0) {
        $msg = ('' + [char]0x00C7 + 'eviri kapsam' + [char]0x0131 + ': %100. De' + [char]0x011F + 'i' + [char]0x015F + 'iklik uygulaman' + [char]0x0131 + 'n yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmas' + [char]0x0131 + 'yla ge' + [char]0x00E7 + 'erli olur.')
    } else {
        $msg = (('' + [char]0x00C7 + 'eviri kapsam' + [char]0x0131 + ': %') + [string]$cov + ('. ' + [char]0x00C7 + 'evrilmemi' + [char]0x015F + ' metinler ' + [char]0x0130 + 'ngilizce, o da yoksa T' + [char]0x00FC + 'rk' + [char]0x00E7 + 'e g' + [char]0x00F6 + 'sterilir. De' + [char]0x011F + 'i' + [char]0x015F + 'iklik uygulaman' + [char]0x0131 + 'n yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmas' + [char]0x0131 + 'yla ge' + [char]0x00E7 + 'erli olur.'))
    }
    if ($null -ne $e -and [bool]$e.User) { $msg = $msg + ' ' + ('Bu dil dosyas' + [char]0x0131 + ' kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nden y' + [char]0x00FC + 'klendi.') }
    $ui.st_LangNote.Text = (Tr $($msg))
}

# Yeniden baslatma yardimcisinin komut satiri: gizli bir PowerShell, bu surecin bitmesini bekler (tek-kopya kilidi birakilsin), sonra betigi yeniden acar.
# Yonetici hakki korunur: yukseltilmis surecin actigi surec de yukseltilmis acilir.
function Get-RestartArgs([string]$PsPath, [string]$ScriptPath, [int]$WaitPid) {
    $q = [string][char]39
    # Gizli baslatmada yeniden acilis de Acilis.ps1 uzerinden gider (ayni acilis ekrani ve ayni denetim); dosya yoksa betik dogrudan acilir
    $target = $ScriptPath
    $extra = ''
    if ($script:GizliMode -eq $true) {
        $ac = Join-Path (Split-Path -Parent $ScriptPath) 'Acilis.ps1'
        if (Test-Path -LiteralPath $ac) { $target = $ac; $extra = ' -Kod ' + [string](Get-Random -Minimum 100000 -Maximum 999999999) }
    }
    $inner = 'try { Wait-Process -Id ' + [string]$WaitPid + ' -Timeout 30 -ErrorAction Stop } catch { }; Start-Sleep -Milliseconds 700; Start-Process -FilePath ' + $q + $PsPath.Replace($q, $q + $q) + $q + ' -ArgumentList ' + $q + '-NoProfile -ExecutionPolicy Bypass -STA -WindowStyle Hidden -File "' + $target.Replace($q, $q + $q) + '"' + $extra + $q + ' -WindowStyle Hidden'
    $enc = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($inner))
    return ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -EncodedCommand ' + $enc)
}

function Restart-App {
    $ps = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $scr = [string]$sync.ScriptPath
    if (-not (Test-Path -LiteralPath $ps) -or [string]::IsNullOrEmpty($scr)) { return $false }
    $mine = [System.Diagnostics.Process]::GetCurrentProcess().Id
    try {
        Start-Process -FilePath $ps -ArgumentList (Get-RestartArgs $ps $scr $mine) -WindowStyle Hidden -ErrorAction Stop | Out-Null
    } catch { return $false }
    return $true
}

# Onaydan sonra: dil secimi ayara yazilir ve uygulama yeniden baslatilir (Ayarlar karti ve baslik cubugundaki dil dugmesi ortak kullanir)
function Complete-LangChange([string]$Key) {
    if ($Key -eq '') { return }
    $script:Settings.Language = $Key
    Save-Settings $script:Settings
    if (Restart-App) { Exit-App } else { Show-Toast ('Uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '; kapat' + [char]0x0131 + 'p elle a' + [char]0x00E7 + '' + [char]0x0131 + 'n. Dil ayar' + [char]0x0131 + ' kaydedildi.') 'warn' }
}

# Yeniden baslatma onayi: Tamam denirse Complete-LangChange calisir
function Confirm-LangRestart([string]$Key) {
    $script:LangPending = $Key
    $shown = $Key
    if ($Key -eq 'auto') { $shown = 'Otomatik' } else {
        $e = Get-LangEntry $Key
        if ($null -ne $e) { $shown = [string]$e.Native }
    }
    Show-Confirm ('Dil de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i') (('Aray' + [char]0x00FC + 'z dili ' + [char]0x015F + 'u olarak de' + [char]0x011F + 'i' + [char]0x015F + 'tirilecek: ') + $shown + ('. Uygulama kapan' + [char]0x0131 + 'p yeniden a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r; ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an i' + [char]0x015F + 'lem varsa ' + [char]0x00F6 + 'nce bitmesini bekleyin.')) ('Yeniden ba' + [char]0x015F + 'lat') {
        Invoke-Safe { Complete-LangChange ([string]$script:LangPending) } 'Dil'
    }
}

function Invoke-StLangApply {
    $key = Get-ComboKey $ui.st_LangSel
    if ($key -eq '') { return }
    Confirm-LangRestart $key
}

function Init-StLangEvents {
    if ($null -eq $ui.st_LangSel) { return }
    $ui.st_LangSel.Add_SelectionChanged({
        if ($script:StLoading) { return }
        Invoke-Safe { Update-StLangNote } 'Dil'
    })
    $ui.st_LangApply.Add_Click({ Invoke-Safe { Invoke-StLangApply } 'Dil' })
    $ui.st_LangFolder.Add_Click({
        Invoke-Safe {
            $d = Get-LangFolderUser
            if ($d -eq '') { return }
            if (-not (Test-Path -LiteralPath $d -PathType Container)) { [void](New-Item -ItemType Directory -Path $d -Force) }
            Open-Folder $d
        } 'Dil'
    })
}

# ---------------- kalite denetimi: ekrandaki metinleri toplar ----------------
# Gorsel ve mantiksal agacta dolasip her metin ogesini (TextBlock, dugme, aracipucu) listeler.
# Donus (acilir, @() ile alinir): { Type; Text; Visible } kayitlari. Yalnizca okur.
function Get-UiTexts($Root) {
    $res = New-Object System.Collections.ArrayList
    if ($null -eq $Root) { return $res.ToArray() }
    $seen = New-Object 'System.Collections.Generic.HashSet[object]'
    $stack = New-Object System.Collections.Stack
    $stack.Push($Root)
    while ($stack.Count -gt 0) {
        $o = $stack.Pop()
        if ($null -eq $o) { continue }
        if (-not $seen.Add($o)) { continue }
        $txt = $null
        $kind = ''
        if ($o -is [System.Windows.Controls.TextBlock]) { $txt = [string]$o.Text; $kind = 'TextBlock' }
        elseif ($o -is [System.Windows.Controls.ContentControl]) {
            if ($o.Content -is [string]) { $txt = [string]$o.Content; $kind = $o.GetType().Name }
        }
        if ($null -ne $txt -and $txt.Trim().Length -gt 0) {
            $vis = $false
            try { if ($o -is [System.Windows.UIElement]) { $vis = [bool]$o.IsVisible } } catch { $vis = $false }
            [void]$res.Add(@{ Type = $kind; Text = $txt; Visible = $vis; Element = $o })
        }
        if ($o -is [System.Windows.Controls.ItemsControl]) {
            # acilir liste ve liste ogeleri: duz metin ya da Name alanli secenek tablosu (en cok 200 oge)
            $cnt = 0
            try {
                foreach ($it in $o.Items) {
                    $cnt++
                    if ($cnt -gt 200) { break }
                    $itxt = $null
                    if ($it -is [string]) { $itxt = [string]$it }
                    elseif ($it -is [System.Collections.IDictionary] -and $it.Contains('Name')) { $itxt = [string]$it['Name'] }
                    if ($null -ne $itxt -and $itxt.Trim().Length -gt 0) { [void]$res.Add(@{ Type = 'Item'; Text = $itxt; Visible = $false; Element = $o }) }
                }
            } catch { }
        }
        if ($o -is [System.Windows.FrameworkElement]) {
            $tt = $null
            try { $tt = $o.ToolTip } catch { $tt = $null }
            if ($tt -is [string] -and $tt.Trim().Length -gt 0) { [void]$res.Add(@{ Type = 'ToolTip'; Text = [string]$tt; Visible = $false; Element = $o }) }
        }
        if ($o -is [System.Windows.Media.Visual]) {
            $n = 0
            try { $n = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($o) } catch { $n = 0 }
            for ($i = 0; $i -lt $n; $i++) { try { $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($o, $i)) } catch { } }
        }
        if ($o -is [System.Windows.DependencyObject]) {
            try { foreach ($c in [System.Windows.LogicalTreeHelper]::GetChildren($o)) { if ($c -is [System.Windows.DependencyObject]) { $stack.Push($c) } } } catch { }
        }
    }
    return $res.ToArray()
}

# Ekrandaki bir metin Tr'den gecmediyse ve Turkce harf iceriyorsa "sizinti" sayilir (cevrilmesi unutulmus bir yer)
function Test-LangLeak([string]$Text) {
    if (-not $script:LangOn -or $null -eq $script:LangSeen) { return $false }
    if ($script:LangSeen.Contains($Text)) { return $false }
    return [regex]::IsMatch($Text, ('[' + [char]0x00E7 + '' + [char]0x011F + '' + [char]0x0131 + '' + [char]0x00F6 + '' + [char]0x015F + '' + [char]0x00FC + '' + [char]0x00C7 + '' + [char]0x011E + '' + [char]0x0130 + '' + [char]0x00D6 + '' + [char]0x015E + '' + [char]0x00DC + ']'))
}

# Sabit genislikli acilir listede secili metin ceviride uzarsa kirpilmasin: genislik en uzun secenege gore buyutulur
function Fit-ComboWidth($Combo) {
    if ($null -eq $Combo -or -not $script:LangOn) { return }
    try {
        $w0 = [double]$Combo.Width
        if ([double]::IsNaN($w0) -or $w0 -le 0) { return }
        $need = 0.0
        $inf = [double]::PositiveInfinity
        foreach ($it in @($Combo.Items)) {
            $t = ''
            if ($it -is [System.Collections.IDictionary]) { if ($it.Contains('Name')) { $t = [string]$it['Name'] } } else { $t = [string]$it }
            if ($t.Length -eq 0) { continue }
            $p = New-Object System.Windows.Controls.TextBlock
            $p.Text = $t   # Tr:yok
            $p.FontFamily = $Combo.FontFamily
            $p.FontSize = [double]$Combo.FontSize
            $p.FontWeight = $Combo.FontWeight
            $p.Measure((New-Object System.Windows.Size($inf, $inf)))
            if ([double]$p.DesiredSize.Width -gt $need) { $need = [double]$p.DesiredSize.Width }
        }
        $want = [math]::Ceiling($need + 56.0)
        if ($want -gt $w0) { $Combo.Width = [math]::Min($want, 440.0) }
    } catch { }
}

# ---------------- dil destegi: duman testi dil denetimi (Duman-Dil.cmd) ----------------
# =====================================================================
#  DIL DENETIMI  (Duman testi "dil" kapsami; araclar\Duman-Dil.cmd)
#  Secili dilde her sayfanin ve sekmenin ekran metnini tarar. Yalnizca okur; ayar ya da sistem degistirmez.
#    SIZINTI : Tr'den gecmemis ve Turkce harf iceren metin (cevirisi unutulmus bir yer)
#    KESIK   : metin ekranda tam gorunmuyor (kapsayicisina sigmiyor, kisaltilmis ya da baska bir ogenin kirpmasina giriyor)
#  Sonuc dosyasi: %TEMP%\Multimizer-duman-dil.txt   Cevirisi eksik metinler: %TEMP%\Multimizer-dil-eksik.txt
#  Mantik (yalniz dizge/sayi isleri) arayuzsuz sinanir; ekran olcumleri (WPF) gercek bilgisayarda Duman-Dil.cmd ile calisir.
# =====================================================================

$script:LangScanSteps = 0
$script:LangScanTexts = 0
$script:LangScanFail = 0
$script:LangScanLeaks = New-Object System.Collections.ArrayList
$script:LangScanClips = New-Object System.Collections.ArrayList
$script:LangScanLeakSeen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
$script:LangScanClipSeen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
$script:LangScanLog = New-Object System.Collections.ArrayList

# ---------------- saf mantik (arayuz gerekmez) ----------------

# Sizinti deseni: Turkce harflerin bir kismi baska dillerde de dogaldir (almanca o u, fransizca c ...). Bu dillerde yalnizca
# Turkce'ye ozgu harflere bakilir; Turkce harf kullanan dillerde (az, tk ...) sizinti harf yoluyla anlasilamaz, desen bos doner.
function Get-LangLeakPattern([string]$Code) {
    $p = ([string]$Code).Trim().ToLowerInvariant()
    $i = $p.IndexOf('-')
    if ($i -gt 0) { $p = $p.Substring(0, $i) }
    if ($p -eq '' -or $p -eq 'tr') { return '' }
    $same = @('az', 'tk', 'crh', 'gag', 'ku', 'kmr')
    if ($same -contains $p) { return '' }
    $latin = @('en', 'de', 'fr', 'es', 'it', 'pt', 'nl', 'sv', 'da', 'no', 'nb', 'nn', 'fi', 'pl', 'cs', 'sk', 'hu', 'ro', 'ca', 'id', 'ms', 'vi', 'sl', 'hr', 'et', 'lv', 'lt')
    if ($latin -contains $p) { return ('[' + [char]0x011F + '' + [char]0x011E + '' + [char]0x0131 + '' + [char]0x0130 + '' + [char]0x015F + '' + [char]0x015E + ']') }
    return ('[' + [char]0x00E7 + '' + [char]0x011F + '' + [char]0x0131 + '' + [char]0x00F6 + '' + [char]0x015F + '' + [char]0x00FC + '' + [char]0x00C7 + '' + [char]0x011E + '' + [char]0x0130 + '' + [char]0x00D6 + '' + [char]0x015E + '' + [char]0x00DC + ']')
}

# Ekranda gorunen bir metin sizinti mi? Seen: Tr'den gecen metinler (izleme aciksa); bu kumedeki metin sizinti degildir.
function Test-LangLeakText([string]$Text, [string]$Code, $Seen) {
    if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
    if ($null -ne $Seen -and $Seen.Contains($Text)) { return $false }
    $pat = Get-LangLeakPattern $Code
    if ($pat -eq '') { return $false }
    return [regex]::IsMatch($Text, $pat)
}

# Raporda tek satira sigan kisa metin
function Format-LangSnippet([string]$Text, [int]$Max) {
    $s = ([string]$Text).Replace("`r", ' ').Replace("`n", ' ').Replace("`t", ' ')
    while ($s.Contains('  ')) { $s = $s.Replace('  ', ' ') }
    $s = $s.Trim()
    if ($Max -lt 8) { $Max = 8 }
    if ($s.Length -gt $Max) { $s = $s.Substring(0, $Max - 3) + '...' }
    return $s
}

# Ogenin gorunen payi: oge dikdortgeni (L,T,R,B) ile kirpma dikdortgeni (L,T,R,B) kesisimi; donus: @(kayipGenislik, kayipYukseklik, gorunenGenislik, gorunenYukseklik)
function Get-LangVisible([double[]]$Box, [double[]]$Clip) {
    $vl = [math]::Max($Box[0], $Clip[0])
    $vt = [math]::Max($Box[1], $Clip[1])
    $vr = [math]::Min($Box[2], $Clip[2])
    $vb = [math]::Min($Box[3], $Clip[3])
    $vw = [math]::Max(0.0, $vr - $vl)
    $vh = [math]::Max(0.0, $vb - $vt)
    $w = $Box[2] - $Box[0]
    $h = $Box[3] - $Box[1]
    return , @(($w - $vw), ($h - $vh), $vw, $vh)
}

# Kayip degerlerinden karar: '' = sorun yok, aksi halde aciklama. Tamamen kirpilan oge (gorunen 0) yalnizca yatayda sorun sayilir
# (dikeyde kapali bolum, kaydirma vb. bilerek gizlenir); gorunen payi olup kirpilan oge her iki eksende sorundur.
function Get-LangClipVerdict([double]$LostW, [double]$LostH, [double]$VisW, [double]$VisH, [double]$Tol, [double]$ClipW = 1000000.0, [double]$ClipH = 1000000.0) {
    # kirpma alani (kapsayicinin gorunen bolumu) neredeyse yoksa oge tasarim geregi gizlidir (sifir genislikli sutun, kapali panel)
    if ($ClipW -le 2.0 -or $ClipH -le 2.0) { return '' }
    if ($VisW -le 0.5 -and $VisH -gt 0.5) { return ('yatayda tamamen d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + 'da') }
    if ($VisW -le 0.5 -or $VisH -le 0.5) { return '' }
    $parts = New-Object System.Collections.ArrayList
    if ($LostW -gt $Tol) { [void]$parts.Add('yatay ' + [string][int][math]::Round($LostW) + ' px') }
    if ($LostH -gt $Tol) { [void]$parts.Add(('d' + [char]0x00FC + '' + [char]0x015F + 'ey ') + [string][int][math]::Round($LostH) + ' px') }
    if ($parts.Count -eq 0) { return '' }
    return (('k' + [char]0x0131 + 'rp' + [char]0x0131 + 'l' + [char]0x0131 + 'yor: ') + ($parts.ToArray() -join ', '))
}

# ---------------- WPF olcumleri (yalnizca gercek pencerede) ----------------

function Convert-LangRect($V, $Win, $Rect) {
    if ([object]::ReferenceEquals($V, $Win)) { return $Rect }
    $t = ([System.Windows.Media.Visual]$V).TransformToAncestor($Win)
    return $t.TransformBounds($Rect)
}

function New-LangClipArray([double]$L, [double]$T, [double]$R, [double]$B) {
    return , ([double[]]@($L, $T, $R, $B))
}

# Ogenin ve icindekilerin ekranda gorunebilecegi alan (pencere koordinatlarinda, @(sol, ust, sag, alt)).
# Kirpma kaynaklari: ClipToBounds, kaydirilamayan eksendeki ScrollViewer sinirlari, ogenin kendi yerlesim yuvasindan buyuk olmasi.
function Get-LangClip($El, $Win, $Cache) {
    $winClip = New-LangClipArray 0.0 0.0 ([double]$Win.ActualWidth) ([double]$Win.ActualHeight)
    if ($null -eq $El -or [object]::ReferenceEquals($El, $Win)) { return $winClip }
    if ($Cache.ContainsKey($El)) { return $Cache[$El] }
    $parent = $null
    try { $parent = [System.Windows.Media.VisualTreeHelper]::GetParent($El) } catch { $parent = $null }
    $c = $winClip
    if ($null -ne $parent) { $c = Get-LangClip $parent $Win $Cache }
    $l = [double]$c[0]; $t = [double]$c[1]; $r = [double]$c[2]; $b = [double]$c[3]
    $fe = $El -as [System.Windows.FrameworkElement]
    if ($null -ne $fe -and $null -ne $parent) {
        try {
            $aw = [double]$fe.ActualWidth
            $ah = [double]$fe.ActualHeight
            $own = Convert-LangRect $El $Win (New-Object System.Windows.Rect(0.0, 0.0, $aw, $ah))
            $sv = $fe -as [System.Windows.Controls.ScrollViewer]
            if ($null -ne $sv) {
                $scrX = ($sv.ComputedHorizontalScrollBarVisibility -eq [System.Windows.Visibility]::Visible)
                $scrY = ($sv.ComputedVerticalScrollBarVisibility -eq [System.Windows.Visibility]::Visible)
                # kaydirilabilen eksende icerik gorunum alaninin disina tasabilir (kirpma sayilmaz)
                if ($scrX) { $l = [double]::NegativeInfinity; $r = [double]::PositiveInfinity } else { if ($own.Left -gt $l) { $l = $own.Left }; if ($own.Right -lt $r) { $r = $own.Right } }
                if ($scrY) { $t = [double]::NegativeInfinity; $b = [double]::PositiveInfinity } else { if ($own.Top -gt $t) { $t = $own.Top }; if ($own.Bottom -lt $b) { $b = $own.Bottom } }
            } elseif ($fe.ClipToBounds -and -not ($fe -is [System.Windows.Controls.ScrollContentPresenter])) {
                if ($own.Left -gt $l) { $l = $own.Left }
                if ($own.Top -gt $t) { $t = $own.Top }
                if ($own.Right -lt $r) { $r = $own.Right }
                if ($own.Bottom -lt $b) { $b = $own.Bottom }
            }
            # ogenin kendisi yuvasindan buyukse yuvasina kirpilir
            $slot = [System.Windows.Controls.Primitives.LayoutInformation]::GetLayoutSlot($fe)
            if (-not $slot.IsEmpty) {
                $m = $fe.Margin
                if (($aw + $m.Left + $m.Right) -gt ($slot.Width + 1.5) -or ($ah + $m.Top + $m.Bottom) -gt ($slot.Height + 1.5)) {
                    $sr = Convert-LangRect $parent $Win $slot
                    if ($sr.Left -gt $l) { $l = $sr.Left }
                    if ($sr.Top -gt $t) { $t = $sr.Top }
                    if ($sr.Right -lt $r) { $r = $sr.Right }
                    if ($sr.Bottom -lt $b) { $b = $sr.Bottom }
                }
            }
        } catch { $script:LangScanFail = [int]$script:LangScanFail + 1 }
    }
    $res = New-LangClipArray $l $t $r $b
    $Cache[$El] = $res
    return $res
}

# TextBlock metninin gerektirdigi boyut: ayni yazi tipi ve bicim ayarlariyla kurulan ornek TextBlock olculur
# (FormattedText, TextBlock'tan birkac piksel farkli olcebildigi icin yanlis alarm veriyordu).
# MaxW > 0 ise o genislikte sarilir. Donus: @(genislik, yukseklik)
function Get-LangTextNeed($Tb, [double]$MaxW) {
    $p = New-Object System.Windows.Controls.TextBlock
    $p.Text = (Tr $([string]$Tb.Text))
    $p.FontFamily = $Tb.FontFamily
    $p.FontSize = [double]$Tb.FontSize
    $p.FontStyle = $Tb.FontStyle
    $p.FontWeight = $Tb.FontWeight
    $p.FontStretch = $Tb.FontStretch
    try { $p.FlowDirection = $Tb.FlowDirection } catch { }
    try { $p.Language = $Tb.Language } catch { }
    try {
        $lh = [double]$Tb.LineHeight
        if ($lh -gt 0 -and -not [double]::IsNaN($lh)) { $p.LineHeight = $lh; $p.LineStackingStrategy = $Tb.LineStackingStrategy }
    } catch { }
    try { [System.Windows.Media.TextOptions]::SetTextFormattingMode($p, [System.Windows.Media.TextOptions]::GetTextFormattingMode($Tb)) } catch { }
    $inf = [double]::PositiveInfinity
    if ($MaxW -gt 0) {
        $p.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $p.Measure((New-Object System.Windows.Size($MaxW, $inf)))
    } else {
        $p.TextWrapping = [System.Windows.TextWrapping]::NoWrap
        $p.Measure((New-Object System.Windows.Size($inf, $inf)))
    }
    return , @([double]$p.DesiredSize.Width, [double]$p.DesiredSize.Height)
}

# Bir metin ogesi icin kesik denetimi: '' = sorun yok
function Test-LangClip($El, $Win, $Cache) {
    $fe = $El -as [System.Windows.FrameworkElement]
    if ($null -eq $fe) { return '' }
    $aw = [double]$fe.ActualWidth
    $ah = [double]$fe.ActualHeight
    if ($aw -lt 2 -or $ah -lt 2) { return '' }
    $msgs = New-Object System.Collections.ArrayList
    # 1) ekranda gorunen pay (ust kapsayicilarin kirpmasi dahil)
    $own = Convert-LangRect $El $Win (New-Object System.Windows.Rect(0.0, 0.0, $aw, $ah))
    $box = [double[]]@($own.Left, $own.Top, $own.Right, $own.Bottom)
    $clip = Get-LangClip $El $Win $Cache
    $v = Get-LangVisible $box $clip
    $why = Get-LangClipVerdict ([double]$v[0]) ([double]$v[1]) ([double]$v[2]) ([double]$v[3]) 2.0 ([double]$clip[2] - [double]$clip[0]) ([double]$clip[3] - [double]$clip[1])
    if ($why -ne '') { [void]$msgs.Add($why) }
    # 2) TextBlock: kisaltma ve yukseklik yetersizligi
    $tb = $El -as [System.Windows.Controls.TextBlock]
    if ($null -ne $tb -and ([string]$tb.Text).Length -gt 0) {
        $padW = [double]$tb.Padding.Left + [double]$tb.Padding.Right
        $padH = [double]$tb.Padding.Top + [double]$tb.Padding.Bottom
        $availW = $aw - $padW
        if ([string]$tb.TextWrapping -eq 'NoWrap') {
            if ($availW -ge 4) {
                $need = Get-LangTextNeed $tb 0
                if ([double]$need[0] -gt $availW + 4.0) {
                    $note = ''
                    if ([string]$tb.TextTrimming -ne 'None') { $note = (' (sonu ... ile k' + [char]0x0131 + 'salt' + [char]0x0131 + 'l' + [char]0x0131 + 'yor)') }
                    # tani bilgisi: yanlis alarmi ayiklamak icin yazi tipi, satir ici oge sayisi ve kapsayici turu eklenir
                    try {
                        $pt = ''; $tp = ''
                        if ($null -ne $tb.Parent) { $pt = $tb.Parent.GetType().Name }
                        if ($null -ne $tb.TemplatedParent) { $tp = $tb.TemplatedParent.GetType().Name }
                        $note += ' [' + [string]$tb.FontFamily.Source + ' ' + [string]$tb.FontSize + ' ' + [string]$tb.FontWeight + ('; sat' + [char]0x0131 + 'r i' + [char]0x00E7 + 'i=') + [string]$tb.Inlines.Count + ('; ger' + [char]0x00E7 + 'ek=') + [string][int][math]::Ceiling([double]$tb.DesiredSize.Width) + (' px; ' + [char]0x00FC + 'st=') + $pt + ('; ' + [char]0x015F + 'ablon=') + $tp + ']'
                    } catch { }
                    [void]$msgs.Add(('metin ' + [string][int][math]::Ceiling([double]$need[0]) + ' px, alan ' + [string][int][math]::Floor($availW) + ' px' + $note))
                }
            }
        } elseif ($availW -ge 8) {
            # olcum farki yuzunden dogal genislikte duran metin yanlislikla sarilmasin: 4 px pay verilir
            $need = Get-LangTextNeed $tb ($availW + 4.0)
            $availH = $ah - $padH
            if ([double]$need[1] -gt $availH + 3) { [void]$msgs.Add(('y' + [char]0x00FC + 'kseklik yetersiz: gereken ') + [string][int][math]::Ceiling([double]$need[1]) + ' px, var ' + [string][int][math]::Floor($availH) + ' px') }
        }
    }
    return ($msgs.ToArray() -join '; ')
}

# Sayfa kokunden (ilk adimda tum pencereden) ekran metinlerini tarar. Where: "sayfa" ya da "sayfa/sekme"
function Invoke-SmokeLangScan([string]$Where) {
    $script:LangScanSteps = [int]$script:LangScanSteps + 1
    $win = $script:Win
    if ($null -eq $win) { return }
    # Sekme/ekran degisiminden hemen sonra olcum eskimis olabilir: tarama oncesi yerlesim zorla guncellenir
    try { $win.UpdateLayout() } catch { }
    $key = $Where
    $i = $key.IndexOf('/')
    if ($i -ge 0) { $key = $key.Substring(0, $i) }
    $root = $win
    if ([int]$script:LangScanSteps -gt 1) {
        $pg = $null
        try { $pg = $script:Pages[$key] } catch { $pg = $null }
        if ($null -ne $pg) { $root = $pg }
    }
    $recs = @(Get-UiTexts $root)
    $cache = New-Object 'System.Collections.Generic.Dictionary[object,object]'
    $code = [string]$script:LangCode
    $nNew = 0
    foreach ($r in $recs) {
        $txt = [string]$r.Text
        $kind = [string]$r.Type
        # 1) sizinti: ayni metin bir kez bildirilir
        if ($script:LangOn) {
            $lk = $txt
            if (-not $script:LangScanLeakSeen.Contains($lk)) {
                if (Test-LangLeakText $txt $code $script:LangSeen) {
                    [void]$script:LangScanLeakSeen.Add($lk)
                    [void]$script:LangScanLeaks.Add(@{ Where = $Where; Kind = $kind; Text = $txt })
                }
            }
        }
        # 2) kesik: yalnizca gorunen ve olculebilen ogeler; ayni sayfada ayni metin bir kez
        if (-not [bool]$r.Visible -or $kind -eq 'ToolTip') { continue }
        $ck = $key + '|' + $kind + '|' + $txt
        if ($script:LangScanClipSeen.Contains($ck)) { continue }
        [void]$script:LangScanClipSeen.Add($ck)
        $nNew++
        $el = $r.Element
        if ($null -eq $el -or -not ($el -is [System.Windows.Controls.TextBlock])) { continue }
        try {
            $why = Test-LangClip $el $win $cache
            if ($why -ne '') { [void]$script:LangScanClips.Add(@{ Where = $Where; Kind = $kind; Text = $txt; Detail = $why }) }
        } catch { $script:LangScanFail = [int]$script:LangScanFail + 1 }
    }
    $script:LangScanTexts = [int]$script:LangScanTexts + $nNew
    $leakN = $script:LangScanLeaks.Count
    $clipN = $script:LangScanClips.Count
    [void]$script:LangScanLog.Add($Where + ': ' + [string]$nNew + (' yeni metin; toplam s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + '=') + [string]$leakN + ' kesik=' + [string]$clipN)
}

# Sag-sol yazim yonu: dil sagdan sola ise pencere ve sol menu aynalanmis olmali
function Get-LangRtlState {
    $state = @{ Want = [bool]$script:LangRtl; Flow = ''; Mirrored = $false; Rail = '' }
    try {
        $state.Flow = [string]$script:Win.FlowDirection
        $state.Mirrored = ([string]$script:Win.FlowDirection -eq 'RightToLeft')
    } catch { }
    try {
        $rh = $ui.RailHost
        if ($null -ne $rh -and [double]$rh.ActualWidth -gt 1) {
            $rr = Convert-LangRect $rh $script:Win (New-Object System.Windows.Rect(0.0, 0.0, [double]$rh.ActualWidth, [double]$rh.ActualHeight))
            $mid = $rr.Left + ($rr.Width / 2)
            if ($mid -gt ([double]$script:Win.ActualWidth / 2)) { $state.Rail = ('sa' + [char]0x011F + '') } else { $state.Rail = 'sol' }
        }
    } catch { }
    return $state
}

function Write-SmokeLangReport {
    if ([int]$script:LangScanSteps -le 0) { return }
    $path = Join-Path ([System.IO.Path]::GetTempPath()) 'Multimizer-duman-dil.txt'
    $nl = "`r`n"
    $sb = New-Object System.Text.StringBuilder
    $on = [bool]$script:LangOn
    $cov = ''
    $nPack = 0
    try { if ($null -ne $script:LangPrimary) { $nPack = [int]$script:LangPrimary.N; $cov = [string]$script:LangPrimary.Meta['coverage'] } } catch { }
    $rtl = Get-LangRtlState
    $dirWant = ('soldan sa' + [char]0x011F + 'a')
    if ($rtl.Want) { $dirWant = ('sa' + [char]0x011F + 'dan sola') }
    $leakN = $script:LangScanLeaks.Count
    $clipN = $script:LangScanClips.Count
    $missN = 0
    try { if ($null -ne $script:LangMiss) { $missN = $script:LangMiss.Count } } catch { }
    [void]$sb.Append('MULTIMIZER DIL DENETIMI' + $nl)
    [void]$sb.Append('dil=' + [string]$script:LangCode + ' (' + [string]$script:LangName + ')  etiket=' + [string]$script:LangTag + '  etkin=' + [string]$on + '  paket=' + [string]$nPack + (' kay' + [char]0x0131 + 't  kapsam=%') + $cov + $nl)
    [void]$sb.Append(('yaz' + [char]0x0131 + 'm y' + [char]0x00F6 + 'n' + [char]0x00FC + ': istenen=') + $dirWant + '  pencere=' + [string]$rtl.Flow + ('  sol men' + [char]0x00FC + ' konumu=') + [string]$rtl.Rail + $nl)
    [void]$sb.Append(('taranan ad' + [char]0x0131 + 'm=') + [string]$script:LangScanSteps + '  metin=' + [string]$script:LangScanTexts + ('  denetim hatas' + [char]0x0131 + '=') + [string]$script:LangScanFail + $nl)
    [void]$sb.Append('OZET dil=' + [string]$script:LangCode + ' metin=' + [string]$script:LangScanTexts + ' sizinti=' + [string]$leakN + ' kesik=' + [string]$clipN + ' eksik=' + [string]$missN + ' kapsam=' + $cov + $nl)
    [void]$sb.Append($nl + ('--- SIZINTI: Tr i' + [char]0x015F + 'levinden ge' + [char]0x00E7 + 'meyen, T' + [char]0x00FC + 'rk' + [char]0x00E7 + 'e harfli metinler (') + [string]$leakN + ') ---' + $nl)
    if (-not $on) { [void]$sb.Append(('(T' + [char]0x00FC + 'rk' + [char]0x00E7 + 'e: kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'rma dili; s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + ' denetimi yap' + [char]0x0131 + 'lmaz)') + $nl) }
    foreach ($x in $script:LangScanLeaks) { [void]$sb.Append('[' + [string]$x.Where + '] ' + [string]$x.Kind + ' | ' + (Format-LangSnippet ([string]$x.Text) 200) + $nl) }
    [void]$sb.Append($nl + ('--- KESIK: ekrana s' + [char]0x0131 + '' + [char]0x011F + 'mayan ya da k' + [char]0x0131 + 'rp' + [char]0x0131 + 'lan metinler (') + [string]$clipN + ') ---' + $nl)
    foreach ($x in $script:LangScanClips) { [void]$sb.Append('[' + [string]$x.Where + '] ' + [string]$x.Kind + ' | ' + [string]$x.Detail + ' | ' + (Format-LangSnippet ([string]$x.Text) 120) + $nl) }
    [void]$sb.Append($nl + '--- ADIMLAR ---' + $nl)
    foreach ($x in $script:LangScanLog) { [void]$sb.Append([string]$x + $nl) }
    $wrote = $false
    try { [System.IO.File]::WriteAllText($path, $sb.ToString(), (New-Object System.Text.UTF8Encoding($true))); $wrote = $true } catch { }
    try { [void](Save-LangMiss) } catch { }
    Add-SmokeLine ('--- dil denetimi: dil=' + [string]$script:LangCode + '  metin=' + [string]$script:LangScanTexts + ('  s' + [char]0x0131 + 'z' + [char]0x0131 + 'nt' + [char]0x0131 + '=') + [string]$leakN + '  kesik=' + [string]$clipN + '  eksik=' + [string]$missN + ('  (ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ': ') + $path + ')')
    if ($leakN -gt 0) { Add-SmokeWarn ('dil: ' + [string]$leakN + (' metin Tr i' + [char]0x015F + 'levinden ge' + [char]0x00E7 + 'meden ekrana ' + [char]0x00E7 + '' + [char]0x0131 + 'kt' + [char]0x0131 + '')) }
    if ($clipN -gt 0) { Add-SmokeWarn ('dil: ' + [string]$clipN + (' metin ekrana s' + [char]0x0131 + '' + [char]0x011F + 'm' + [char]0x0131 + 'yor ya da k' + [char]0x0131 + 'rp' + [char]0x0131 + 'l' + [char]0x0131 + 'yor')) }
    # sagdan sola dil: pencere gercekten aynalanmis olmali; tersi de hatadir
    if ($on -and ([bool]$rtl.Want -ne [bool]$rtl.Mirrored)) { Add-SmokeError 'dil' (('yaz' + [char]0x0131 + 'm y' + [char]0x00F6 + 'n' + [char]0x00FC + ' uyu' + [char]0x015F + 'muyor: dil sa' + [char]0x011F + 'dan sola=') + [string]$rtl.Want + ', pencere=' + [string]$rtl.Flow) }
    if ($on -and [bool]$rtl.Want -and [string]$rtl.Rail -eq 'sol') { Add-SmokeWarn ('sa' + [char]0x011F + 'dan sola dilde sol men' + [char]0x00FC + ' h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' solda g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor') }
    if (-not $wrote) { Add-SmokeWarn ('dil raporu dosyas' + [char]0x0131 + ' yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + '') }
}

# ---------------- ayarlari sifirla: Ayarlar karti ve gorunum bilgisi ----------------
# ==================================================================
#  AYARLARI SIFIRLA (arayuz): Ayarlar > Sifirlama karti ve yeni gorunum bilgisi
#  Gorunum kapsami anlik uygulanir (hazir gorunum "Varsayilan" + ana ekran bicimi); Tercihler kapsami ayarlari yazar ve uygulamayi yeniden baslatir.
#  Her sifirlamadan once ayarlarin kopyasi saklanir (bkz. 143_settings_reset_core.ps1); "Son sifirlamayi geri al" kopyayi geri yukler.
# ==================================================================
$script:ResetPending = ''
$script:ResetUndoPath = ''
$script:LookNoticeTimer = $null
$script:LookNoticeTicks = 0

# Kapsam listesini doldurur (bir kez, sayfa kurulurken)
function Initialize-StReset {
    if ($null -eq $ui.st_ResetScope) { return }
    $ch = New-Object System.Collections.ArrayList
    [void]$ch.Add((New-Choice 'Gorunum' ('Yaln' + [char]0x0131 + 'zca g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm')))
    [void]$ch.Add((New-Choice 'Tercihler' ('T' + [char]0x00FC + 'm uygulama tercihleri')))
    [void]$ch.Add((New-Choice 'Fabrika' ('Her ' + [char]0x015F + 'ey: tercihler ve Windows' + [char]0x2019 + 'ta yap' + [char]0x0131 + 'lan de' + [char]0x011F + 'i' + [char]0x015F + 'iklikler')))
    Set-ComboChoices $ui.st_ResetScope $ch.ToArray()
}

# Kapsam notunu, geri alma dugmesini ve son sifirlama satirini gunceller
function Update-StReset {
    if ($null -eq $ui.st_ResetScope) { return }
    $scope = Get-ComboKey $ui.st_ResetScope
    if ($scope -eq '') { $scope = 'Gorunum' }
    if ($scope -eq 'Fabrika') {
        $ui.st_ResetNote.Text = (Tr $(('Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n bu bilgisayarda yapt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ve geri al' + [char]0x0131 + 'nabilen b' + [char]0x00FC + 't' + [char]0x00FC + 'n de' + [char]0x011F + 'i' + [char]0x015F + 'iklikler (ayarlar, hizmetler, g' + [char]0x00F6 + 'revler, g' + [char]0x00FC + '' + [char]0x00E7 + ') yeniden eskiye do' + [char]0x011F + 'ru geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r; ard' + [char]0x0131 + 'ndan uygulaman' + [char]0x0131 + 'n t' + [char]0x00FC + 'm ayarlar' + [char]0x0131 + ' varsay' + [char]0x0131 + 'lana d' + [char]0x00F6 + 'ner ve uygulama yeniden ba' + [char]0x015F + 'lar. Silinen dosyalar ve kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lan uygulamalar geri gelmez.')))
    } elseif ($scope -eq 'Tercihler') {
        $ui.st_ResetNote.Text = (Tr $(('G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'me ek olarak dil, kullan' + [char]0x0131 + 'm kipi, bildirimler, tepsi davran' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ', izleme aral' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ', g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k saklama s' + [char]0x00FC + 'resi, g' + [char]0x00FC + 'venli silme ge' + [char]0x00E7 + 'i' + [char]0x015F + ' say' + [char]0x0131 + 's' + [char]0x0131 + ' ve ana ekran pano d' + [char]0x00FC + 'zeni s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r. Uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'r.')))
    } else {
        $ui.st_ResetNote.Text = (Tr $(('Tema, yerle' + [char]0x015F + 'im, yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma, tasar' + [char]0x0131 + 'm, saydaml' + [char]0x0131 + 'k, ana ekran bi' + [char]0x00E7 + 'imi, hareket ve kayd' + [char]0x0131 + 'rma se' + [char]0x00E7 + 'enekleri ile mini izleyici konumu s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r. De' + [char]0x011F + 'i' + [char]0x015F + 'iklik hemen uygulan' + [char]0x0131 + 'r; yeniden ba' + [char]0x015F + 'latma gerekmez.')))
    }
    $bk = @(Get-ResetBackups)
    $ui.st_ResetUndo.IsEnabled = ($bk.Count -gt 0)
    if ($bk.Count -eq 0) {
        $ui.st_ResetState.Text = (Tr $(('Hen' + [char]0x00FC + 'z s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '.')))
    } else {
        $when = ([datetime]$bk[0].Time).ToString('dd.MM.yyyy HH:mm')
        if ([string]$bk[0].Scope -eq 'fabrika') { $ui.st_ResetState.Text = (Format-Tr ('Son s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama: {0} (her ' + [char]0x015F + 'ey)') $when) }
        elseif ([string]$bk[0].Scope -eq 'tercihler') { $ui.st_ResetState.Text = (Format-Tr ('Son s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama: {0} (uygulama tercihleri)') $when) }
        else { $ui.st_ResetState.Text = (Format-Tr ('Son s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama: {0} (g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm)') $when) }
    }
}

function Load-StReset {
    if ($null -eq $ui.st_ResetScope) { return }
    if ((Get-ComboKey $ui.st_ResetScope) -eq '') { [void](Select-ComboKey $ui.st_ResetScope 'Gorunum') }
    Update-StReset
}

# Onaydan sonra: kopya alinir, sonra kapsama gore sifirlanir
function Complete-StReset([string]$Scope) {
    $tag = 'gorunum'
    if ($Scope -eq 'Tercihler') { $tag = 'tercihler' }
    if ($Scope -eq 'Fabrika') { $tag = 'fabrika' }
    $bk = Save-SettingsBackup $script:Settings $tag
    if ($bk -eq '') { Show-Toast ('Ayar kopyas' + [char]0x0131 + ' yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + '; s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '.') 'bad'; return }
    $def = Get-DefaultSettings
    if ($Scope -eq 'Fabrika') {
        # once Windows'taki degisiklikler geri alinir (arka planda), sonra ayarlar sifirlanir ve uygulama yeniden baslar
        [void](Start-Async 'UndoAll' 'Job_UndoAll' @{} {
            param($r)
            Invoke-Safe {
                if ($null -eq $r) { Show-Toast ('De' + [char]0x011F + 'i' + [char]0x015F + 'iklikler geri al' + [char]0x0131 + 'namad' + [char]0x0131 + '; ayarlar s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlanmad' + [char]0x0131 + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'bad'; return }
                $script:Settings = Get-Settings
                $res = Get-ResetResult $script:Settings 'Fabrika'
                foreach ($k in @($res.Settings.Keys)) { $script:Settings[[string]$k] = $res.Settings[$k] }
                Save-Settings $script:Settings
                if ([int]$r.Errors -gt 0) { Write-WhLog (Format-Tr ('T' + [char]0x00FC + 'm' + [char]0x00FC + 'n' + [char]0x00FC + ' geri alma: {0} i' + [char]0x015F + 'lem geri al' + [char]0x0131 + 'namad' + [char]0x0131 + '; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' yukar' + [char]0x0131 + 'da.') ([int]$r.Errors)) 'WARN' }
                if (Restart-App) { Exit-App } else { Show-Toast ('Her ' + [char]0x015F + 'ey s' + [char]0x0131 + 'f' + [char]0x0131 + 'rland' + [char]0x0131 + '. Uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '; kapat' + [char]0x0131 + 'p elle a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') 'warn' }
            } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama')
        } ('T' + [char]0x00FC + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'iklikler geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'yor'))
        return
    }
    if ($Scope -eq 'Tercihler') {
        $r = Get-ResetResult $script:Settings 'Tercihler'
        foreach ($k in @($r.Settings.Keys)) { $script:Settings[[string]$k] = $r.Settings[$k] }
        Save-Settings $script:Settings
        if (Restart-App) { Exit-App } else { Show-Toast ('Uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '; kapat' + [char]0x0131 + 'p elle a' + [char]0x00E7 + '' + [char]0x0131 + 'n. S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlanan ayarlar bir sonraki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta ge' + [char]0x00E7 + 'erli olur.') 'warn' }
        return
    }
    # Gorunum: anahtarlar varsayilana yazilir, hazir gorunum (tema, yerlesim, tasarim, saydamlik, yakinlastirma) ve ana ekran bicimi anlik uygulanir
    foreach ($k in @('ReduceMotion', 'SmoothScroll', 'ToTopButton', 'FocusRing', 'TouchTargets', 'WidgetCorner', 'WidgetOpacity', 'WidgetX', 'WidgetY')) { $script:Settings[$k] = $def[$k] }
    Apply-LookPreset 'Varsayilan'
    [void](Select-HomeMode ([string]$def.HomeMode))
    $script:Settings.LookVersion = 10
    $script:Settings.LookNotice = $false
    Save-Settings $script:Settings
    try { Update-StReset } catch { }
    Show-Toast ('G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm varsay' + [char]0x0131 + 'lan de' + [char]0x011F + 'erlere d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '.') 'good'
}

function Invoke-StResetRun {
    $scope = Get-ComboKey $ui.st_ResetScope
    if ($scope -eq '') { $scope = 'Gorunum' }
    $script:ResetPending = $scope
    $danger = $false
    if ($scope -eq 'Fabrika') {
        $danger = $true
        $nj = @(Get-UndoableJournals ([string]$sync.BackupDir)).Count
        $txt = (Format-Tr ('Multimizer' + [char]0x2019 + '' + [char]0x0131 + 'n bu bilgisayarda yapt' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' geri al' + [char]0x0131 + 'nabilir b' + [char]0x00FC + 't' + [char]0x00FC + 'n de' + [char]0x011F + 'i' + [char]0x015F + 'iklikler ({0} kay' + [char]0x0131 + 't dosyas' + [char]0x0131 + ') geri al' + [char]0x0131 + 'nacak, ard' + [char]0x0131 + 'ndan uygulaman' + [char]0x0131 + 'n t' + [char]0x00FC + 'm ayarlar' + [char]0x0131 + ' varsay' + [char]0x0131 + 'lana d' + [char]0x00F6 + 'necek ve uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak. Silinen dosyalar ve kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lan uygulamalar geri gelmez. ' + [char]0x00D6 + 'nceki ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n kopyas' + [char]0x0131 + ' saklan' + [char]0x0131 + 'r.') $nj)
    } elseif ($scope -eq 'Tercihler') {
        $danger = $true
        $txt = ('T' + [char]0x00FC + 'm uygulama tercihleri varsay' + [char]0x0131 + 'lan de' + [char]0x011F + 'erlere d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'lecek ve uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak. Windows ' + [char]0x00FC + 'zerinde yap' + [char]0x0131 + 'lan de' + [char]0x011F + 'i' + [char]0x015F + 'iklikler, zamanlanm' + [char]0x0131 + '' + [char]0x015F + ' g' + [char]0x00F6 + 'revler, yedekleme ayarlar' + [char]0x0131 + ' ve a' + [char]0x011F + ' korumas' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'mez. ' + [char]0x00D6 + 'nceki ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n kopyas' + [char]0x0131 + ' saklan' + [char]0x0131 + 'r.')
    } else {
        $txt = ('G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm varsay' + [char]0x0131 + 'lan de' + [char]0x011F + 'erlere d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'lecek: beyaz tema, sade yerle' + [char]0x015F + 'im, %100 yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma, klasik tasar' + [char]0x0131 + 'm. ' + [char]0x00D6 + 'nceki ayarlar' + [char]0x0131 + 'n' + [char]0x0131 + 'z' + [char]0x0131 + 'n kopyas' + [char]0x0131 + ' saklan' + [char]0x0131 + 'r; Ayarlar > S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nden geri alabilirsiniz.')
    }
    Show-Confirm ('Ayarlar' + [char]0x0131 + ' s' + [char]0x0131 + 'f' + [char]0x0131 + 'rla') $txt ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rla') {
        Invoke-Safe {
            $sc = [string]$script:ResetPending
            $script:ResetPending = ''
            if ($sc -eq '') { return }
            Complete-StReset $sc
        } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama')
    } $danger
}

function Invoke-StResetUndo {
    $bk = @(Get-ResetBackups)
    if ($bk.Count -eq 0) { Show-Toast ('Geri al' + [char]0x0131 + 'nacak bir ayar kopyas' + [char]0x0131 + ' yok.') 'info'; return }
    $script:ResetUndoPath = [string]$bk[0].Path
    Show-Confirm ('Son s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlamay' + [char]0x0131 + ' geri al') ('Son s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlamadan ' + [char]0x00F6 + 'nceki ayarlar geri y' + [char]0x00FC + 'klenecek ve uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lacak.') ('Geri y' + [char]0x00FC + 'kle') {
        Invoke-Safe {
            $p = [string]$script:ResetUndoPath
            $script:ResetUndoPath = ''
            if ($p -eq '') { return }
            if (Restore-SettingsFromBackup $p $script:Settings) {
                $script:Settings = Get-Settings
                if (Restart-App) { Exit-App } else { Show-Toast ('Uygulama yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '; kapat' + [char]0x0131 + 'p elle a' + [char]0x00E7 + '' + [char]0x0131 + 'n.') 'warn' }
            } else {
                Show-Toast ('Ayar kopyas' + [char]0x0131 + ' okunamad' + [char]0x0131 + '; geri alma yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '.') 'bad'
            }
        } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama')
    }
}

function Init-StReset {
    if ($null -eq $ui.st_ResetScope) { return }
    $ui.st_ResetScope.Add_SelectionChanged({
        if ($script:StLoading) { return }
        Invoke-Safe { Update-StReset } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama')
    })
    $ui.st_ResetRun.Add_Click({ Invoke-Safe { Invoke-StResetRun } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama') })
    $ui.st_ResetUndo.Add_Click({ Invoke-Safe { Invoke-StResetUndo } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama') })
    $ui.st_ResetFolder.Add_Click({
        Invoke-Safe {
            $d = Get-SettingsBackupDir
            if (-not (Test-Path -LiteralPath $d -PathType Container)) { [void](New-Item -ItemType Directory -Path $d -Force) }
            Open-Folder $d
        } ('S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama')
    })
}

# Gorunum eski varsayilandan yeni varsayilana (beyaz, sade) tasindiysa pencere gorununce bir kez bilgi verilir
function Initialize-LookNotice {
    if ($script:SmokeMode -eq $true) { return }
    if ($script:Settings.LookNotice -ne $true) { return }
    $script:LookNoticeTicks = 0
    $script:LookNoticeTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:LookNoticeTimer.Interval = [TimeSpan]::FromSeconds(2)
    $script:LookNoticeTimer.Add_Tick({
        try {
            $script:LookNoticeTicks++
            if ($script:LookNoticeTicks -gt 30) { $script:LookNoticeTimer.Stop(); return }
            if (-not $script:Win.IsVisible) { return }
            if ($ui.Overlay.Visibility -eq $script:VisOn) { return }
            $script:LookNoticeTimer.Stop()
            $script:Settings.LookNotice = $false
            Save-Settings $script:Settings
            Show-Toast ('G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm g' + [char]0x00FC + 'ncellendi: varsay' + [char]0x0131 + 'lan tema beyaz ve sade oldu. ' + [char]0x00D6 + 'nceki g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'me Ayarlar > S' + [char]0x0131 + 'f' + [char]0x0131 + 'rlama b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'nden d' + [char]0x00F6 + 'nebilirsiniz.') 'info'
        } catch { Write-CrashLog ('LookNotice: ' + $_.Exception.Message) }
    })
    $script:LookNoticeTimer.Start()
}

# ---------------- ust cubuk: ana sayfa emblemi ve dil secici ----------------
# ==================================================================
#  UST CUBUK (arayuz): ana sayfa emblemi ve dil secici
#  Sol ustteki Multimizer emblemi ana sayfa dugmesidir: baska sayfadayken durum panosunu acar, zaten oradaysa sayfayi en uste kaydirir.
#  KULLANICI | UZMAN kapsulunun yanindaki dil dugmesi acilir listeyi gosterir; secim yeniden baslatmayla uygulanir
#  (Windows dili zaten secilen dilse yalnizca ayar yazilir). Satirlar 145_header_core.ps1 modelinden kurulur.
# ==================================================================
$script:LangPopClosedAt = [datetime]::MinValue
$script:LangPopFocus = $null

$script:LangRowXaml = @'
<Button xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Style="{DynamicResource BtnRow}" Padding="8,6" Margin="0,1">
  <Grid MinWidth="248">
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="24"/>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="Auto"/>
    </Grid.ColumnDefinitions>
    <ContentControl x:Name="RowCheck" Style="{DynamicResource Icon}" Tag="{DynamicResource IcoCheck}" Width="14" Height="14" Foreground="{DynamicResource BrAccent}" HorizontalAlignment="Left" VerticalAlignment="Center" Visibility="Hidden"/>
    <StackPanel Grid.Column="1" VerticalAlignment="Center">
      <TextBlock x:Name="RowName" Text="" FontSize="13" FontWeight="SemiBold" Foreground="{DynamicResource BrText}" TextTrimming="CharacterEllipsis"/>
      <TextBlock x:Name="RowSub" Text="" FontSize="11" Foreground="{DynamicResource BrDim}" Margin="0,1,0,0" TextTrimming="CharacterEllipsis"/>
    </StackPanel>
    <Border x:Name="RowChip" Grid.Column="2" Margin="12,0,0,0" Padding="6,1" CornerRadius="4" BorderThickness="1" BorderBrush="{DynamicResource BrLine}" VerticalAlignment="Center">
      <TextBlock x:Name="RowChipText" Text="" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource BrDim}"/>
    </Border>
  </Grid>
</Button>
'@

# Modelden bir liste satiri kurar (metinler kodla atanir: dil adlari ceviriden gecmez)
function New-LangRow($M) {
    $row = Read-LocalXaml ($script:LangRowXaml)
    $row.Tag = [string]$M.Code
    $row.FindName('RowName').Text = (Tr $([string]$M.Name))
    $row.FindName('RowSub').Text = (Tr $([string]$M.Sub))
    $chip = $row.FindName('RowChip')
    $chipText = $row.FindName('RowChipText')
    if ([string]$M.Chip -eq '') { $chip.Visibility = $script:VisOff } else { $chipText.Text = (Tr $([string]$M.Chip)) }
    if ([bool]$M.Checked) {
        $row.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty, 'BrActiveBg')
        $row.FindName('RowCheck').Visibility = $script:VisOn
        $chip.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BrAccentDim')
        $chipText.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'BrAccent')
    }
    $row.Add_Click($script:H_LangRow)
    return , $row
}

$script:H_LangRow = {
    param($s, $e)
    Invoke-Safe { Select-LangRow ([string]$s.Tag) } 'Dil'
}

function Select-LangRow([string]$Code) {
    Close-LangMenu
    [void](Request-LangChange $Code)
}

# Listeyi modelden yeniden kurar (her acilista; ayar ya da dil dosyalari degismis olabilir)
function Update-LangMenu {
    if ($null -eq $ui.LangItems) { return }
    $stack = $ui.LangItems
    $stack.Children.Clear()
    $script:LangPopFocus = $null
    foreach ($m in @(Get-LangMenuModel)) {
        $row = New-LangRow $m
        if ($null -eq $row) { continue }
        [void]$stack.Children.Add($row)
        if ([bool]$m.Checked -and $null -eq $script:LangPopFocus) { $script:LangPopFocus = $row }
    }
    if ($null -eq $script:LangPopFocus -and $stack.Children.Count -gt 0) { $script:LangPopFocus = $stack.Children[0] }
}

# Dil dugmesinin yazisi (calisan dilin kisa kodu) ve aracipucu
function Update-LangButton {
    if ($null -eq $ui.BtnLang -or $null -eq $ui.TxtLangCode) { return }
    $info = Get-LangButtonInfo
    $ui.TxtLangCode.Text = (Tr $([string]$info.Code))
    $ui.BtnLang.ToolTip = (Tr $([string]$info.Tip))
    try { [System.Windows.Automation.AutomationProperties]::SetName($ui.BtnLang, [string]$info.Tip) } catch { }
}

function Set-LangPopFocus {
    $el = $script:LangPopFocus
    if ($null -eq $el) { return }
    try { [void]$el.Focus() } catch { }
}

function Close-LangMenu {
    if ($null -ne $ui.LangPop -and $ui.LangPop.IsOpen) { $ui.LangPop.IsOpen = $false }
}

# Dugme: liste aciksa kapatir, kapaliysa acar
function Show-LangMenu {
    $pop = $ui.LangPop
    if ($null -eq $pop -or $null -eq $ui.LangCapsule) { return }
    if ($pop.IsOpen) { $pop.IsOpen = $false; return }
    # StaysOpen=False: dugmenin uzerine tiklamak acik listeyi once kapatir, ayni tiklama ardindan Click olarak gelir; liste hemen yeniden acilmasin
    if (([datetime]::UtcNow - $script:LangPopClosedAt).TotalMilliseconds -lt 300) { return }
    Update-LangMenu
    try { Close-NavMenu } catch { }
    $pop.PlacementTarget = $ui.LangCapsule
    $pop.IsOpen = $true
}

function Get-LangShownName([string]$Key) {
    if ($Key -eq 'auto') { return (Tr 'Otomatik') }
    foreach ($l in @(Get-LangList)) { if ([string]$l.Code -eq $Key) { return [string]$l.Native } }
    return $Key
}

# Dil secimini uygular. Donus: 'yok' | 'ayni' | 'kaydet' | 'mesgul' | 'yeniden' (onay penceresi acildi)
function Request-LangChange([string]$Key) {
    $plan = Get-LangChangePlan $Key
    $k = $Key.Trim().ToLowerInvariant()
    if ($plan -eq 'yok') { Show-Toast ('Bu dil kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor.') 'warn'; return $plan }
    if ($plan -eq 'ayni') { return $plan }
    if ($plan -eq 'kaydet') {
        # arayuz dili degismiyor (ornek: Otomatik <-> Turkce, Windows dili zaten bu): yeniden baslatmaya gerek yok
        $script:Settings.Language = $k
        Save-Settings $script:Settings
        $msg = Format-Tr 'Dil tercihi kaydedildi: {0}' (Get-LangShownName $k)
        Add-LangNameOut $msg
        Show-Toast $msg 'good'
        try { Update-LangButton } catch { }
        return $plan
    }
    $busy = $false
    try { $busy = [bool](Test-AsyncBusy) } catch { $busy = $false }
    if ($busy) { Show-Toast ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an bir i' + [char]0x015F + 'lem var; bitince dili de' + [char]0x011F + 'i' + [char]0x015F + 'tirin.') 'warn'; return 'mesgul' }
    Confirm-LangRestart $k
    return $plan
}

# Emblem: baska sayfadaysa durum panosunu acar; zaten ana sayfadaysa en uste kaydirir
function Invoke-HomeClick {
    try { Close-NavMenu } catch { }
    try { Close-LangMenu } catch { }
    $cur = [string]$script:UiState.Page
    if ($cur -eq 'panel' -or $cur -eq 'board') {
        $sv = $null
        try { $sv = Get-PageScroller 0 } catch { $sv = $null }
        if ($null -ne $sv) { try { $sv.ScrollToVerticalOffset(0) } catch { } }
    } else {
        Show-Page 'panel'
    }
    try { Focus-PageHost } catch { }
}

function Initialize-HeaderBar {
    if ($null -ne $ui.BtnHome) {
        $ui.BtnHome.Add_Click({ Invoke-Safe { Invoke-HomeClick } 'Ana sayfa' })
        try { [System.Windows.Automation.AutomationProperties]::SetName($ui.BtnHome, (Tr 'Ana sayfa')) } catch { }
    }
    if ($null -ne $ui.BtnLang) {
        $ui.BtnLang.Add_Click({ Invoke-Safe { Show-LangMenu } 'Dil' })
    }
    if ($null -ne $ui.LangPop) {
        $ui.LangPop.Add_Opened({ try { $ui.BtnLang.Tag = 'open'; Set-LangPopFocus } catch { } })
        $ui.LangPop.Add_Closed({ try { $script:LangPopClosedAt = [datetime]::UtcNow; $ui.BtnLang.Tag = '' } catch { } })
        if ($null -ne $ui.LangPop.Child) {
            $ui.LangPop.Child.Add_PreviewKeyDown({
                param($s, $e)
                if ($e.Key -eq [System.Windows.Input.Key]::Escape) {
                    try { Close-LangMenu; [void]$ui.BtnLang.Focus() } catch { }
                    $e.Handled = $true
                }
            })
        }
    }
    Update-LangButton
    try { Update-LangMenu } catch { Write-CrashLog ('Dil listesi: ' + $_.Exception.Message) }
}

# ---------------- duman testi: ust cubuk denetimleri ----------------
# Bir ogenin goruntusunu PNG olarak kaydeder (acilir listeler pencere agacinda olmadigi icin pencere goruntusunde yer almaz)
function Save-SmokeShotOf($El, [string]$Name) {
    try {
        $pw = [int][math]::Ceiling([double]$El.ActualWidth)
        $ph = [int][math]::Ceiling([double]$El.ActualHeight)
        if ($pw -lt 20 -or $ph -lt 20) { Add-SmokeError 'ust cubuk' (('g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + ' al' + [char]0x0131 + 'namad' + [char]0x0131 + ', ' + [char]0x00F6 + '' + [char]0x011F + 'e ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lmemi' + [char]0x015F + ': ') + $Name); return }
        $bmp = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($pw, $ph, 96, 96, [System.Windows.Media.PixelFormats]::Pbgra32)
        $bmp.Render($El)
        $enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
        $enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($bmp))
        $fs = [System.IO.File]::Create((Join-Path $script:SmokeDir ($Name + '.png')))
        try { $enc.Save($fs) } finally { $fs.Dispose() }
        $script:SmokeShots = $script:SmokeShots + 1
    } catch { Add-SmokeError 'ust cubuk' $_.Exception.Message }
}

function Test-SmokeHeader([string]$What) {
    if ($What -eq 'home') {
        $want = 'panel'
        try { if (Test-BoardHome) { $want = 'board' } } catch { }
        $cur = [string]$script:UiState.Page
        if ($cur -ne $want) { Add-SmokeError 'ust cubuk' (('ana sayfa emblemi durum panosunu a' + [char]0x00E7 + 'mad' + [char]0x0131 + ': ') + $cur + ' (beklenen ' + $want + ')') }
        else { Add-SmokeLine ('      ' + [char]0x00FC + 'st ' + [char]0x00E7 + 'ubuk: ana sayfa emblemi durum panosunu a' + [char]0x00E7 + 't' + [char]0x0131 + '') }
        if ($null -eq $ui.BtnHome -or [double]$ui.BtnHome.ActualWidth -lt 40 -or $ui.BtnHome.IsVisible -ne $true) { Add-SmokeError 'ust cubuk' ('ana sayfa d' + [char]0x00FC + '' + [char]0x011F + 'mesi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor') }
        return
    }
    if ($What -eq 'lang') {
        $b = $ui.BtnLang
        if ($null -eq $b -or $b.IsVisible -ne $true -or [double]$b.ActualWidth -lt 30) { Add-SmokeError 'ust cubuk' ('dil d' + [char]0x00FC + '' + [char]0x011F + 'mesi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor'); return }
        $code = [string]$ui.TxtLangCode.Text
        $want = Get-LangShortCode ([string]$script:LangCode)
        if ($code -ne $want) { Add-SmokeError 'ust cubuk' (('dil d' + [char]0x00FC + '' + [char]0x011F + 'mesindeki kod ') + $code + ', beklenen ' + $want) }
        if ([string]$b.ToolTip -eq '') { Add-SmokeError 'ust cubuk' ('dil d' + [char]0x00FC + '' + [char]0x011F + 'mesinin ipucu bo' + [char]0x015F + '') }
        # kapsul, KULLANICI | UZMAN kapsuluyla ayni yukseklikte olmali (ayni satirda duzgun hizalanir)
        $mode = $ui.SegUser.Parent.Parent
        $hm = [double]$mode.ActualHeight
        $hl = [double]$ui.LangCapsule.ActualHeight
        if ([math]::Abs($hm - $hl) -gt 1.5) { Add-SmokeError 'ust cubuk' (('dil kaps' + [char]0x00FC + 'l' + [char]0x00FC + ' ') + [string][int]$hl + (' px, kip kaps' + [char]0x00FC + 'l' + [char]0x00FC + ' ') + [string][int]$hm + (' px: y' + [char]0x00FC + 'kseklikler e' + [char]0x015F + 'it de' + [char]0x011F + 'il')) }
        Add-SmokeLine (('      ' + [char]0x00FC + 'st ' + [char]0x00E7 + 'ubuk: dil d' + [char]0x00FC + '' + [char]0x011F + 'mesi ') + $code + ' (' + [string][int]$ui.LangCapsule.ActualWidth + ' x ' + [string][int]$hl + (' px, kip kaps' + [char]0x00FC + 'l' + [char]0x00FC + ' ') + [string][int]$hm + ' px)')
        return
    }
    Add-SmokeError 'ust cubuk' ('bilinmeyen denetim: ' + $What)
}

function Test-SmokeLangPop([string]$What) {
    $pop = $ui.LangPop
    if ($null -eq $pop -or $null -eq $ui.BtnLang -or $null -eq $ui.LangItems) { Add-SmokeError 'ust cubuk' ('dil listesi ya da d' + [char]0x00FC + '' + [char]0x011F + 'mesi yok'); return }
    Show-LangMenu
    if (-not $pop.IsOpen) { Add-SmokeError 'ust cubuk' ('dil listesi a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + ''); return }
    try { [void]$script:Win.Dispatcher.Invoke([System.Action]{ }, [System.Windows.Threading.DispatcherPriority]::Render) } catch { }
    $c = $pop.Child
    try { $c.UpdateLayout() } catch { }
    $need = @(Get-LangList).Count + 1
    $got = $ui.LangItems.Children.Count
    if ($got -ne $need) { Add-SmokeError 'ust cubuk' ('dil listesinde ' + [string]$got + (' sat' + [char]0x0131 + 'r var, beklenen ') + [string]$need) }
    $marked = 0
    foreach ($r in $ui.LangItems.Children) { if ($r.FindName('RowCheck').Visibility -eq $script:VisOn) { $marked++ } }
    if ($marked -ne 1) { Add-SmokeError 'ust cubuk' ('dil listesinde ' + [string]$marked + (' sat' + [char]0x0131 + 'r i' + [char]0x015F + 'aretli, beklenen 1')) }
    if ([string]$ui.BtnLang.Tag -ne 'open') { Add-SmokeError 'ust cubuk' ('liste a' + [char]0x00E7 + '' + [char]0x0131 + 'kken dil d' + [char]0x00FC + '' + [char]0x011F + 'mesi etkin g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'mde de' + [char]0x011F + 'il') }
    if ([double]$c.ActualWidth -lt 50) {
        # acilir pencerenin yerlesimi henuz olusmadiysa elle olculur
        try {
            $c.Measure((New-Object System.Windows.Size([double]::PositiveInfinity, [double]::PositiveInfinity)))
            $c.Arrange((New-Object System.Windows.Rect(0.0, 0.0, [double]$c.DesiredSize.Width, [double]$c.DesiredSize.Height)))
        } catch { }
    }
    Save-SmokeShotOf $c ('ust-dil-listesi-' + [string]$script:LangCode)
    # gercek ekran goruntusu: acik liste pencerenin ustunde nasil duruyor (acilir pencere RenderTargetBitmap goruntusune girmez).
    # Acilir pencere once yuklenir, sonra Fade animasyonuyla belirir: yerlesim ve cizim bitsin, masaustu bileseni kareyi sunsun, sonra goruntu alinir.
    # (animasyon saati arayuz is parcacigiyla ilerler: uyku sirasinda kare uretilmez, bu yuzden kisa uykularla art arda bosaltilir)
    for ($i = 0; $i -lt 16; $i++) { Invoke-SmokeFlush; Start-Sleep -Milliseconds 50 }
    Start-Sleep -Milliseconds 120
    if (-not $pop.IsOpen) { Add-SmokeLine ('      ' + [char]0x00FC + 'st ' + [char]0x00E7 + 'ubuk: liste ekran g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + 'nden ' + [char]0x00F6 + 'nce kapand' + [char]0x0131 + ' (pencere etkinli' + [char]0x011F + 'ini yitirdi)') }
    Save-SmokeScreen ('ust-dil-listesi-' + [string]$script:LangCode)
    # ceviri sizintisi: listedeki her metin
    if ($script:LangOn -and $null -ne $script:LangScanLeaks) {
        $code = [string]$script:LangCode
        foreach ($r in @(Get-UiTexts $c)) {
            $txt = [string]$r.Text
            if ($script:LangScanLeakSeen.Contains($txt)) { continue }
            if (Test-LangLeakText $txt $code $script:LangSeen) {
                [void]$script:LangScanLeakSeen.Add($txt)
                [void]$script:LangScanLeaks.Add(@{ Where = ('' + [char]0x00FC + 'st ' + [char]0x00E7 + 'ubuk / dil listesi'); Kind = [string]$r.Type; Text = $txt })
            }
        }
    }
    Add-SmokeLine (('      ' + [char]0x00FC + 'st ' + [char]0x00E7 + 'ubuk: dil listesi a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ' (') + [string]$got + (' sat' + [char]0x0131 + 'r, ') + [string][int]$c.ActualWidth + ' x ' + [string][int]$c.ActualHeight + (' px), kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
    Close-LangMenu
    if ($pop.IsOpen) { Add-SmokeError 'ust cubuk' ('dil listesi kapanmad' + [char]0x0131 + '') }
}

