# ---------------- parola uretici ----------------
function Get-KitPwDetail {
    $p = $script:KitPw
    $parts = New-Object System.Collections.ArrayList
    [void]$parts.Add((Tr ('k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k harf')))
    if ($p.Upper) { [void]$parts.Add((Tr ('b' + [char]0x00FC + 'y' + [char]0x00FC + 'k harf'))) }
    if ($p.Digit) { [void]$parts.Add((Tr 'rakam')) }
    if ($p.Symbol) { [void]$parts.Add((Tr 'simge')) }
    $bits = Get-PasswordBits ([int]$p.Len) ([bool]$p.Upper) ([bool]$p.Digit) ([bool]$p.Symbol)
    return ((Format-Tr 'Uzunluk {0}' ([int]$p.Len)) + (' ' + [char]0x00B7 + ' ') + ($parts -join ', ') + (' ' + [char]0x00B7 + ' ') + (Format-Tr ('yakla' + [char]0x015F + '' + [char]0x0131 + 'k {0} bit') $bits) + ' (' + (Tr (Get-PasswordStrengthText $bits)) + '). ' + (Tr ('Kar' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lan karakterler (0 ve O, 1 ve l) kullan' + [char]0x0131 + 'lmaz.')))
}

function Render-KitPw {
    Add-KitBack ('Parola ' + [char]0x00FC + 'retici')
    $p = $script:KitPw
    Add-TlAction ('Parola ' + [char]0x00FC + 'ret') (Get-KitPwDetail) 'BrAccent' 'kit:pwgen' ('' + [char]0x00DC + 'ret ve kopyala') 'kit:pwlen' (Format-Tr 'Uzunluk: {0}' ([int]$p.Len))
    $sy = ('Simge: kapal' + [char]0x0131 + ''); if ($p.Symbol) { $sy = ('Simge: a' + [char]0x00E7 + '' + [char]0x0131 + 'k') }
    $dg = ('Rakam: kapal' + [char]0x0131 + ''); if ($p.Digit) { $dg = ('Rakam: a' + [char]0x00E7 + '' + [char]0x0131 + 'k') }
    Add-TlAction ('Karakter t' + [char]0x00FC + 'rleri') ('Baz' + [char]0x0131 + ' siteler simge kabul etmez; o durumda simgeyi kapat' + [char]0x0131 + 'p uzunlu' + [char]0x011F + 'u art' + [char]0x0131 + 'r' + [char]0x0131 + 'n.') 'BrDim' 'kit:pwsym' $sy 'kit:pwdig' $dg
    if ([string]$p.Value -ne '') {
        Add-HeadRow $ui.tl_List ('Son ' + [char]0x00FC + 'retilen')
        Add-KvRow $ui.tl_List 'Parola' ([string]$p.Value)
        Add-Note $ui.tl_List ('Parola panoya kopyaland' + [char]0x0131 + '; pano 60 saniye sonra temizlenir. Bu ekrandan ayr' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda parola bellekten silinir.')
    }
    $ui.tl_Foot.Text = (Tr $(('Parolalar kaydedilmez. Saklamak i' + [char]0x00E7 + 'in bir parola y' + [char]0x00F6 + 'neticisi (KeePassXC, Bitwarden) kullan' + [char]0x0131 + 'n.')))
}

function Clear-KitPw {
    $script:KitPw.Value = ''
    try { if ($null -ne $script:KitPwTimer) { $script:KitPwTimer.Stop() } } catch { }
}

function Invoke-KitPwGen {
    $p = $script:KitPw
    $x = Import-MmExt 'Parola'
    if ($x.Ok -ne $true) { Show-Toast ([string]$x.Error) 'bad'; return }
    $v = New-RandomPassword ([int]$p.Len) (Get-PasswordSets ([bool]$p.Upper) ([bool]$p.Digit) ([bool]$p.Symbol))
    $script:KitPw.Value = $v
    if (Set-ClipText $v) { Show-Toast ('Parola ' + [char]0x00FC + 'retildi ve panoya kopyaland' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Parola ' + [char]0x00FC + 'retildi; panoya kopyalanamad' + [char]0x0131 + '.') 'warn' }
    try {
        if ($null -eq $script:KitPwTimer) {
            $script:KitPwTimer = New-Object System.Windows.Threading.DispatcherTimer
            $script:KitPwTimer.Interval = [TimeSpan]::FromSeconds(60)
            $script:KitPwTimer.Add_Tick({
                try {
                    $script:KitPwTimer.Stop()
                    $cur = ''
                    try { $cur = [string][System.Windows.Clipboard]::GetText() } catch { $cur = '' }
                    if ([string]$script:KitPw.Value -ne '' -and $cur -ceq [string]$script:KitPw.Value) { try { [System.Windows.Clipboard]::Clear() } catch { } }
                } catch { Write-CrashLog ('KitPw: ' + $_.Exception.Message) }
            })
        }
        $script:KitPwTimer.Stop(); $script:KitPwTimer.Start()
    } catch { }
    Render-TlKit
}

# ---------------- toplu yeniden adlandirma ----------------
function Start-KitRenPick {
    $d = Select-Folder ('Dosyalar' + [char]0x0131 + ' yeniden adland' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in')
    if ($d -eq '') { return }
    $why = Test-RenameDirAllowed $d
    if ($why -ne '') { Show-Toast $why 'warn'; return }
    Start-KitRenScan $d
}

function Start-KitRenScan([string]$Dir) {
    [void](Start-Async 'RenScan' 'Job_RenameScan' @{ Dir = $Dir } {
        param($r)
        if ($null -eq $r -or $r.Ok -ne $true) {
            $m = ('Klas' + [char]0x00F6 + 'r okunamad' + [char]0x0131 + '.')
            if ($null -ne $r -and [string]$r.Error -ne '') { $m = [string]$r.Error }
            Show-Toast $m 'warn'; return
        }
        $script:KitRen = @{ Dir = [string]$r.Dir; Items = @($r.Items); Mode = ''; Arg = ''; Plan = $null }
        Set-KitView 'ren'
    } ('Klas' + [char]0x00F6 + 'r okunuyor'))
}

function Set-KitRenPlan([string]$Mode, [string]$Arg) {
    $names = @($script:KitRen.Items | ForEach-Object { [string]$_.Name })
    $pl = Get-RenamePlan $script:KitRen.Items $Mode $Arg $names
    if ([string]$pl.Error -ne '') { Show-Toast ([string]$pl.Error) 'warn'; return }
    $script:KitRen.Mode = $Mode; $script:KitRen.Arg = $Arg; $script:KitRen.Plan = $pl
    if ([int]$pl.Changes -eq 0) { Show-Toast ('Bu kuralla ad' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ecek dosya yok.') 'info' }
    Render-TlKit
}

function Invoke-KitRenMode([string]$Mode) {
    if ($Mode -eq 'Number') {
        Show-Input ('S' + [char]0x0131 + 'ra numaras' + [char]0x0131 + ' ver') ('Dosyalar ' + [char]0x201C + 'Ad 01, Ad 02, ' + [char]0x2026 + '' + [char]0x201D + ' bi' + [char]0x00E7 + 'iminde adland' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r (ada g' + [char]0x00F6 + 're s' + [char]0x0131 + 'rayla; uzant' + [char]0x0131 + ' korunur). Temel ad' + [char]0x0131 + ' yaz' + [char]0x0131 + 'n:') 'Dosya' { param($v) Invoke-Safe { Set-KitRenPlan 'Number' ([string]$v) } ('Yeniden adland' + [char]0x0131 + 'rma') }
        return
    }
    if ($Mode -eq 'Replace') {
        Show-Input ('Metni de' + [char]0x011F + 'i' + [char]0x015F + 'tir') ('Bi' + [char]0x00E7 + 'im: eski=>yeni   (' + [char]0x00F6 + 'rnek: IMG_=>Tatil ). Metni silmek i' + [char]0x00E7 + 'in sa' + [char]0x011F + ' taraf' + [char]0x0131 + ' bo' + [char]0x015F + ' b' + [char]0x0131 + 'rak' + [char]0x0131 + 'n. Uzant' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'mez.') '' { param($v) Invoke-Safe { Set-KitRenPlan 'Replace' ([string]$v) } ('Yeniden adland' + [char]0x0131 + 'rma') }
        return
    }
    Set-KitRenPlan $Mode ''
}

function Render-KitRename {
    Add-KitBack ('Toplu yeniden adland' + [char]0x0131 + 'rma')
    $R = $script:KitRen
    if ([string]$R.Dir -eq '') {
        Add-TlAction ('Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + 'in') ('Yaln' + [char]0x0131 + 'zca se' + [char]0x00E7 + 'ti' + [char]0x011F + 'iniz klas' + [char]0x00F6 + 'rdeki dosyalar ele al' + [char]0x0131 + 'n' + [char]0x0131 + 'r; alt klas' + [char]0x00F6 + 'rlere, gizli dosyalara ve sistem dosyalar' + [char]0x0131 + 'na dokunulmaz.') 'BrAccent' 'kit:ren' ('Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + '')
        return
    }
    Add-KvRow $ui.tl_List ('Klas' + [char]0x00F6 + 'r') ([string]$R.Dir)
    Add-KvRow $ui.tl_List 'Dosya' ([string]@($R.Items).Count)
    Add-HeadRow $ui.tl_List ('Kural se' + [char]0x00E7 + 'in')
    Add-TlAction ('S' + [char]0x0131 + 'ra numaras' + [char]0x0131 + ' ver') ('Ad 01, Ad 02, ' + [char]0x2026 + ' (foto' + [char]0x011F + 'raf ve belge dizileri i' + [char]0x00E7 + 'in).') 'BrAccent' 'kit:renmode:Number' ('Se' + [char]0x00E7 + '')
    Add-TlAction ('Metni de' + [char]0x011F + 'i' + [char]0x015F + 'tir') ('Ad' + [char]0x0131 + 'n i' + [char]0x00E7 + 'indeki bir metni ba' + [char]0x015F + 'ka bir metinle de' + [char]0x011F + 'i' + [char]0x015F + 'tirir ya da siler.') 'BrAccent' 'kit:renmode:Replace' ('Se' + [char]0x00E7 + '')
    Add-TlAction ('Ba' + [char]0x015F + '' + [char]0x0131 + 'na tarih ekle') ('Dosyan' + [char]0x0131 + 'n son de' + [char]0x011F + 'i' + [char]0x015F + 'iklik tarihi ad' + [char]0x0131 + 'n ba' + [char]0x015F + '' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r: 2026-11-14 rapor.pdf') 'BrAccent' 'kit:renmode:DatePrefix' ('Se' + [char]0x00E7 + '')
    Add-TlAction ('K' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k harfe ' + [char]0x00E7 + 'evir / bo' + [char]0x015F + 'luklar' + [char]0x0131 + ' tire yap') ('Web' + [char]0x2019 + 'e ya da ba' + [char]0x015F + 'ka sistemlere y' + [char]0x00FC + 'klenecek dosyalar i' + [char]0x00E7 + 'in.') 'BrAccent' 'kit:renmode:Lower' ('K' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k harf') 'kit:renmode:Dash' 'Tire'
    $pl = $R.Plan
    if ($null -ne $pl -and [int]$pl.Changes -gt 0) {
        Add-HeadRow $ui.tl_List (Format-Tr ('' + [char]0x00D6 + 'nizleme: {0} dosyan' + [char]0x0131 + 'n ad' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ecek') ([int]$pl.Changes))
        $k = 0
        foreach ($row in @($pl.Rows)) {
            $k++
            if ($k -gt 12) { break }
            $v = [string]$row.New
            if ([string]$row.Problem -ne '') { $v += ('   ' + [char]0x26A0 + ' ') + (Tr ([string]$row.Problem)) }
            Add-KvRow $ui.tl_List ([string]$row.Old) $v
        }
        if ([int]$pl.Changes -gt 12) { Add-Note $ui.tl_List (Format-Tr ('' + [char]0x2026 + ' ve {0} dosya daha.') ([int]$pl.Changes - 12)) }
        if ([int]$pl.Problems -gt 0) {
            Add-Note $ui.tl_List (Format-Tr ('{0} dosyada ad ' + [char]0x00E7 + 'ak' + [char]0x0131 + '' + [char]0x015F + 'mas' + [char]0x0131 + ' ya da ge' + [char]0x00E7 + 'ersiz ad var; bu kural uygulanamaz. Ba' + [char]0x015F + 'ka bir kural ya da temel ad se' + [char]0x00E7 + 'in.') ([int]$pl.Problems)) 'bad'
        } else {
            Add-TlAction 'Uygula' ('Dosyalar yeniden adland' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'r. ' + [char]0x0130 + '' + [char]0x015F + 'lem Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.') 'BrGood' 'kit:renapply' ('Yeniden adland' + [char]0x0131 + 'r')
        }
    }
    $ui.tl_Foot.Text = (Tr $(('Dosya i' + [char]0x00E7 + 'erikleri de' + [char]0x011F + 'i' + [char]0x015F + 'mez; yaln' + [char]0x0131 + 'zca adlar de' + [char]0x011F + 'i' + [char]0x015F + 'ir.')))
}

function Start-KitRenApply {
    $R = $script:KitRen
    $pl = $R.Plan
    if ($null -eq $pl -or [int]$pl.Changes -eq 0 -or [int]$pl.Problems -gt 0) { Show-Toast ('Uygulanacak bir ' + [char]0x00F6 + 'nizleme yok.') 'info'; return }
    $pairs = @($pl.Rows | ForEach-Object { @{ Old = [string]$_.Old; New = [string]$_.New } })
    $script:PendingSteps = @(@{ Title = ('Toplu yeniden adland' + [char]0x0131 + 'rma'); Ops = @(@{ T = 'Rename'; Dir = [string]$R.Dir; Pairs = $pairs }) })
    Show-Confirm ('Toplu yeniden adland' + [char]0x0131 + 'rma') (Format-Tr ('{0} dosyan' + [char]0x0131 + 'n ad' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ecek. ' + [char]0x0130 + '' + [char]0x015F + 'lem Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'nabilir.') $pairs.Count) ('Yeniden adland' + [char]0x0131 + 'r') {
        Start-PlanJob $script:PendingSteps ('Dosyalar yeniden adland' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') $false $false { Invoke-Safe { Start-KitRenScan ([string]$script:KitRen.Dir) } ('Yeniden adland' + [char]0x0131 + 'rma') }
    }
}

# ---------------- karne ----------------
function Start-KitScore {
    [void](Start-Async 'ScoreView' 'Job_ScoreView' @{} {
        param($r)
        if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Karne okunamad' + [char]0x0131 + '.') 'warn'; return }
        $script:KitScore = $r
        Set-KitView 'score'
    } ('Karne haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor'))
}

function Render-KitScore {
    Add-KitBack ('Karne: ' + [char]0x00F6 + 'nce ve sonra')
    $S = $script:KitScore
    if ($null -eq $S) { Add-Note $ui.tl_List ('Karne haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor' + [char]0x2026 + ''); return }
    $n = $S.Now
    Add-HeadRow $ui.tl_List ('' + [char]0x015E + 'u an')
    if ([int]$n.Svc -ge 0) { Add-KvRow $ui.tl_List ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an hizmet') ([string]$n.Svc) }
    if ([int]$n.Proc -ge 0) { Add-KvRow $ui.tl_List ('' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an i' + [char]0x015F + 'lem') ([string]$n.Proc) }
    if ([int]$n.FreeMb -ge 0) { Add-KvRow $ui.tl_List ('Bo' + [char]0x015F + ' bellek') ((Format-Size ([double]$n.FreeMb * 1MB))) }
    if ([double]$n.DiskFreeGb -ge 0) { Add-KvRow $ui.tl_List ('Sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + 'nde bo' + [char]0x015F + ' alan') ([string]$n.DiskFreeGb + ' GB') }
    $boots = @($S.Boots)
    if ($boots.Count -gt 0) {
        $txt = @($boots | ForEach-Object { ([datetime]$_.Time).ToString('dd.MM') + ': ' + [string][int]([double]$_.BootMs / 1000) + ' sn' }) -join ('  ' + [char]0x00B7 + '  ')
        Add-KvRow $ui.tl_List ('Son a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' s' + [char]0x00FC + 'releri') $txt
    }
    $ent = @($S.Entries)
    $w = Get-ScoreSummary $ent 7 (Get-Date)
    $m = Get-ScoreSummary $ent 30 (Get-Date)
    Add-HeadRow $ui.tl_List ('' + [char]0x00D6 + 'zet')
    Add-KvRow $ui.tl_List ('Son 7 g' + [char]0x00FC + 'n') (Format-Tr ('{0} i' + [char]0x015F + 'lem, {1} de' + [char]0x011F + 'i' + [char]0x015F + 'iklik ' + [char]0x00B7 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an hizmet {2} ' + [char]0x00B7 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'lan alan {3} GB') ([int]$w.Count) ([int]$w.Changes) (Format-Signed $w.Svc) ([string]$w.DiskFreeGb))
    Add-KvRow $ui.tl_List ('Son 30 g' + [char]0x00FC + 'n') (Format-Tr ('{0} i' + [char]0x015F + 'lem, {1} de' + [char]0x011F + 'i' + [char]0x015F + 'iklik ' + [char]0x00B7 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an hizmet {2} ' + [char]0x00B7 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'lan alan {3} GB') ([int]$m.Count) ([int]$m.Changes) (Format-Signed $m.Svc) ([string]$m.DiskFreeGb))
    $svc = @($S.Services)
    if ($svc.Count -gt 0) {
        Add-HeadRow $ui.tl_List ('En ' + [char]0x00E7 + 'ok bellek tutan hizmetler (kendi i' + [char]0x015F + 'leminde ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'anlar)')
        foreach ($x in $svc) { Add-KvRow $ui.tl_List (Limit-Text ([string]$x.Display) 60) ((Format-Tr ('yakla' + [char]0x015F + '' + [char]0x0131 + 'k {0} MB') ([int]$x.Mb)) + ('  ' + [char]0x00B7 + '  ') + [string]$x.Name) }
        Add-Note $ui.tl_List ('Bir hizmeti kapatmadan ' + [char]0x00F6 + 'nce Hizmetler sayfas' + [char]0x0131 + 'ndaki a' + [char]0x00E7 + '' + [char]0x0131 + 'klamas' + [char]0x0131 + 'n' + [char]0x0131 + ' okuyun; bellek tutmas' + [char]0x0131 + ' gereksiz oldu' + [char]0x011F + 'u anlam' + [char]0x0131 + 'na gelmez.')
    }
    Add-HeadRow $ui.tl_List ('' + [char]0x0130 + '' + [char]0x015F + 'lem ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i (' + [char]0x00F6 + 'nce ' + [char]0x2192 + ' sonra)')
    if ($ent.Count -eq 0) {
        Add-Note $ui.tl_List ('Hen' + [char]0x00FC + 'z kay' + [char]0x0131 + 't yok. ' + [char]0x0130 + 'yile' + [char]0x015F + 'tir, Temizlik ya da Hizmetler sayfas' + [char]0x0131 + 'ndan bir i' + [char]0x015F + 'lem uygulad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'zda ' + [char]0x00F6 + 'nce ve sonra ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm' + [char]0x00FC + ' burada g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.')
    } else {
        $k = 0
        foreach ($e in $ent) {
            $k++
            if ($k -gt 15) { break }
            $when = ''
            try { $when = ([datetime]::Parse([string]$e.B.Time, [System.Globalization.CultureInfo]::InvariantCulture)).ToString('dd.MM HH:mm') } catch { }
            Add-KvRow $ui.tl_List ($when + '  ' + (Limit-Text ([string]$e.Label) 40)) (Format-ScoreLine $e.A $e.B)
        }
    }
    $ui.tl_Foot.Text = (Tr $(('' + [char]0x00D6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'mler i' + [char]0x015F + 'lem an' + [char]0x0131 + 'ndaki anl' + [char]0x0131 + 'k de' + [char]0x011F + 'erlerdir; a' + [char]0x00E7 + '' + [char]0x0131 + 'k programlara g' + [char]0x00F6 + 're birka' + [char]0x00E7 + ' birim oynayabilir. Kay' + [char]0x0131 + 't yaln' + [char]0x0131 + 'zca bu bilgisayarda tutulur.')))
}

# ---------------- internete baglanan programlar ----------------
function Start-KitNet {
    [void](Start-Async 'NetTalk' 'Job_NetTalkers' @{} {
        param($r)
        if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar okunamad' + [char]0x0131 + '.') 'warn'; return }
        $script:KitNet = $r
        Set-KitView 'net'
    } ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar okunuyor'))
}

function Render-KitNet {
    Add-KitBack ('Hangi program internete ba' + [char]0x011F + 'lan' + [char]0x0131 + 'yor?')
    $S = $script:KitNet
    if ($null -eq $S) { Add-Note $ui.tl_List ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar okunuyor' + [char]0x2026 + ''); return }
    $rows = @($S.Rows)
    Add-TlAction (Format-Tr ('{0} program' + [char]0x0131 + 'n internet ba' + [char]0x011F + 'lant' + [char]0x0131 + 's' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'k') $rows.Count) (Format-Tr ('Okundu: {0}. Yerel a' + [char]0x011F + ' ve bilgisayar' + [char]0x0131 + 'n kendi i' + [char]0x00E7 + 'indeki ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar say' + [char]0x0131 + 'lmaz.') ([string]$S.At)) 'BrDim' 'kit:net' 'Yenile'
    $i = -1
    foreach ($r in $rows) {
        $i++
        $d = (Format-Tr ('{0} ba' + [char]0x011F + 'lant' + [char]0x0131 + ', {1} farkl' + [char]0x0131 + ' adres') ([int]$r.Count) ([int]$r.Hosts)) + ' (' + [string]$r.Sample + ')'
        if ([string]$r.Ports -ne '') { $d += (' ' + [char]0x00B7 + ' ') + (Tr ('ba' + [char]0x011F + 'lant' + [char]0x0131 + ' noktas' + [char]0x0131 + '')) + ' ' + [string]$r.Ports }
        if ([string]$r.Path -ne '') { $d += ('  ' + [char]0x00B7 + '  ') + (Limit-Text ([string]$r.Path) 90) }
        if ($r.Blocked -eq $true) { Add-TlAction ([string]$r.Name) ($d + ('  ' + [char]0x00B7 + '  ') + (Tr ('' + [char]0x0130 + 'nterneti kesildi (a' + [char]0x00E7 + '' + [char]0x0131 + 'k ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar kapanana kadar listede kalabilir).'))) 'BrWarn' ('kit:netopen:' + [string]$i) ('Engeli kald' + [char]0x0131 + 'r') }
        elseif ($r.CanBlock -eq $true) { Add-TlAction ([string]$r.Name) $d 'BrAccent2' ('kit:netblock:' + [string]$i) ('' + [char]0x0130 + 'nterneti kes') }
        else { Add-TlAction ([string]$r.Name) ($d + ('  ' + [char]0x00B7 + '  ') + (Tr ([string]$r.Why))) 'BrDim' 'kit:none' '' }
    }
    $ui.tl_Foot.Text = (Tr $(('Engel, Windows G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + '' + [char]0x2019 + 'na giden y' + [char]0x00F6 + 'nde bir kural olarak eklenir; A' + [char]0x011F + ' > Koruma sekmesinden ve Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan kald' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir.')))
}

function Start-KitNetRule([int]$Index, [bool]$On) {
    $rows = @($script:KitNet.Rows)
    if ($Index -lt 0 -or $Index -ge $rows.Count) { return }
    $r = $rows[$Index]
    $t = ('' + [char]0x0130 + 'nterneti kes: ') + [string]$r.Name
    if (-not $On) { $t = ('' + [char]0x0130 + 'nternet engelini kald' + [char]0x0131 + 'r: ') + [string]$r.Name }
    $script:PendingSteps = @(@{ Title = $t; Ops = @(@{ T = 'FwApp'; Program = [string]$r.Path; On = $On }) })
    if (-not $On) { Start-PlanJob $script:PendingSteps $t $false $false { Invoke-Safe { Start-KitNet } ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar') }; return }
    Show-Confirm ('' + [char]0x0130 + 'nterneti kes') (Format-Tr ('{0} program' + [char]0x0131 + 'n' + [char]0x0131 + 'n internete ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' Windows G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + ' kural' + [char]0x0131 + 'yla engellenecek. Program ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'maya devam eder ama internete ba' + [char]0x011F + 'lanamaz. ' + [char]0x0130 + 'stedi' + [char]0x011F + 'iniz zaman kald' + [char]0x0131 + 'rabilirsiniz.') ([string]$r.Name)) ('' + [char]0x0130 + 'nterneti kes') {
        Start-PlanJob $script:PendingSteps ([string]$script:PendingSteps[0].Title) $false $false { Invoke-Safe { Start-KitNet } ('Ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar') }
    } $true
}

# ---------------- acik kaynak alternatifleri ----------------
function Start-KitAlt {
    [void](Start-Async 'AltScan' 'Job_AltScan' @{} {
        param($r)
        if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Kurulu programlar okunamad' + [char]0x0131 + '.') 'warn'; return }
        $script:KitAlt = $r
        Set-KitView 'alt'
    } 'Kurulu programlar okunuyor')
}

function Render-KitAlt {
    Add-KitBack ('A' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak alternatifleri')
    $S = $script:KitAlt
    if ($null -eq $S) { Add-Note $ui.tl_List ('Kurulu programlar okunuyor' + [char]0x2026 + ''); return }
    $rows = @($S.Rows)
    if ($rows.Count -eq 0) {
        Add-Note $ui.tl_List (Format-Tr ('{0} kurulu program incelendi; a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak kar' + [char]0x015F + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' ' + [char]0x00F6 + 'nerilecek bir program bulunmad' + [char]0x0131 + '.') ([int]$S.Count))
    } else {
        Add-Note $ui.tl_List (Format-Tr ('{0} kurulu program incelendi. A' + [char]0x015F + 'a' + [char]0x011F + '' + [char]0x0131 + 'dakilerin a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak kar' + [char]0x015F + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' var. Kurulum winget deposundan, imza ve ' + [char]0x00F6 + 'zet do' + [char]0x011F + 'rulamas' + [char]0x0131 + 'yla yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r; eski program kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz, karar' + [char]0x0131 + ' siz verirsiniz.') ([int]$S.Count))
        $i = -1
        foreach ($r in $rows) {
            $i++
            $lic = Get-FossLicenseText ([string]$r.Id)
            Add-TlAction ((Limit-Text ([string]$r.Have) 50) + ('  ' + [char]0x2192 + '  ') + [string]$r.Name) ((Tr ([string]$r.Why)) + '.  ' + (Tr $lic)) 'BrAccent2' ('kit:altinst:' + [string]$i) 'Kur'
        }
    }
    Add-TlAction ('B' + [char]0x00FC + 't' + [char]0x00FC + 'n a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak ara' + [char]0x00E7 + 'lar') ('Uygulamalar > ' + [char]0x00DC + 'cretsiz ara' + [char]0x00E7 + 'lar listesinde lisans bilgisi ve ' + [char]0x201C + 'yaln' + [char]0x0131 + 'zca a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak' + [char]0x201D + ' s' + [char]0x00FC + 'zgeci bulunur.') 'BrDim' 'kit:altall' ('Listeyi a' + [char]0x00E7 + '')
    $ui.tl_Foot.Text = (Tr $(('' + [char]0x00D6 + 'neriler bu uygulaman' + [char]0x0131 + 'n i' + [char]0x00E7 + 'indeki sabit bir tablodan gelir; kurulu program listeniz hi' + [char]0x00E7 + 'bir yere g' + [char]0x00F6 + 'nderilmez.')))
}

function Start-KitAltInstall([int]$Index) {
    $rows = @($script:KitAlt.Rows)
    if ($Index -lt 0 -or $Index -ge $rows.Count) { return }
    $script:KitPending = $rows[$Index]
    Show-Confirm 'Program kur' (Format-Tr ('{0} winget deposundan kurulacak ({1}). Mevcut program' + [char]0x0131 + 'n' + [char]0x0131 + 'z kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz.') ([string]$script:KitPending.Name) ([string]$script:KitPending.Id)) 'Kur' {
        $t = $script:KitPending
        [void](Start-Async 'Foss' 'Job_WingetInstall' @{ Id = [string]$t.Id } {
            param($r)
            if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Kurulum tamamland' + [char]0x0131 + '.') 'good'; Invoke-Safe { Start-KitAlt } 'Alternatifler' }
            else { Show-Toast ('Kurulum ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'bad' }
        } ('Kuruluyor: ' + [string]$t.Name) $false $true)
    }
}

# ---------------- yeni bilgisayar adimlari ----------------
function Render-KitSetup {
    Add-KitBack ('Yeni bilgisayar / format sonras' + [char]0x0131 + ' ad' + [char]0x0131 + 'mlar' + [char]0x0131 + '')
    $st = @{ Applied = @($script:Settings.AppliedIds).Count; BackupDest = [string]$script:Settings.BackupDest; UseCase = [string]$script:Settings.UseCase; PrepSeen = [string]$script:Settings.PrepSeen; AppVersion = [string]$script:AppVersion }
    Add-Note $ui.tl_List ('Ad' + [char]0x0131 + 'mlar' + [char]0x0131 + ' s' + [char]0x0131 + 'rayla izleyin. Her ad' + [char]0x0131 + 'm ilgili sayfay' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar; i' + [char]0x015F + 'lem orada ' + [char]0x00F6 + 'nizlenir ve onay' + [char]0x0131 + 'n' + [char]0x0131 + 'zla uygulan' + [char]0x0131 + 'r. Eski bilgisayar' + [char]0x0131 + 'n' + [char]0x0131 + 'zdan ayar ta' + [char]0x015F + '' + [char]0x0131 + 'yacaksan' + [char]0x0131 + 'z ' + [char]0x00F6 + 'nce Yedekleme > Ta' + [char]0x015F + '' + [char]0x0131 + 'nma kiti sekmesinden i' + [char]0x00E7 + 'e aktar' + [char]0x0131 + 'n.')
    foreach ($s in @(Get-SetupSteps $st)) {
        $br = 'BrAccent'; $ttl = [string]$s.Title
        if ($s.Done -eq $true) { $br = 'BrGood'; $ttl = $ttl + ('  ' + [char]0x2713 + '') }
        Add-TlAction $ttl ([string]$s.Detail) $br ('kit:go:' + [string]$s.Page + ':' + [string]$s.Tab) ([string]$s.Btn)
    }
    Add-TlAction ('Ta' + [char]0x015F + '' + [char]0x0131 + 'nma kiti') ('Eski bilgisayardan d' + [char]0x0131 + '' + [char]0x015F + 'a aktard' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + 'z ayarlar' + [char]0x0131 + ', program listesini ve s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' yede' + [char]0x011F + 'ini bu bilgisayara getirir.') 'BrDim' 'kit:go:backup:kit' ('Ta' + [char]0x015F + '' + [char]0x0131 + 'nma kiti')
    $ui.tl_Foot.Text = (Tr $(('' + [char]0x2713 + ' i' + [char]0x015F + 'areti, ad' + [char]0x0131 + 'm' + [char]0x0131 + 'n bu bilgisayarda daha ' + [char]0x00F6 + 'nce yap' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00F6 + 'sterir.')))
}

# ---------------- Firefox ilkeleri ----------------
function Start-KitFirefox([bool]$Preview) {
    $steps = New-StepsFromIds $script:FirefoxTweakIds
    $steps = @($steps)
    if ($steps.Count -eq 0) { Show-Toast ('Firefox ilkeleri bulunamad' + [char]0x0131 + '.') 'warn'; return }
    $script:PendingSteps = $steps
    if ($Preview) { Start-PlanJob $script:PendingSteps ('' + [char]0x00D6 + 'nizleme: Firefox gizlilik ilkeleri') $true $false; return }
    $note = ''
    if (-not (Test-FirefoxInstalled)) { $note = ' ' + (Tr ('Firefox bu bilgisayarda kurulu g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor; ilkeler ' + [char]0x015F + 'imdi yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r ve Firefox kuruldu' + [char]0x011F + 'unda ge' + [char]0x00E7 + 'erli olur.')) }
    Show-Confirm 'Firefox gizlilik ilkeleri' ((Tr ('Firefox' + [char]0x2019 + 'un telemetrisi, ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'malar' + [char]0x0131 + ', sponsorlu i' + [char]0x00E7 + 'erikleri ve tan' + [char]0x0131 + 't' + [char]0x0131 + 'm iletileri ilkeyle kapat' + [char]0x0131 + 'lacak. Firefox ayarlar' + [char]0x0131 + 'nda ' + [char]0x201C + 'kurulu' + [char]0x015F + 'unuz taraf' + [char]0x0131 + 'ndan y' + [char]0x00F6 + 'netiliyor' + [char]0x201D + ' yaz' + [char]0x0131 + 's' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r. Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri alabilirsiniz.')) + $note) 'Uygula' {
        Start-PlanJob $script:PendingSteps ('Firefox gizlilik ilkeleri uygulan' + [char]0x0131 + 'yor') $false $false
    }
}

# ---------------- yardim paketi ----------------
function Start-KitBundle {
    $dest = [Environment]::GetFolderPath('Desktop')
    [void](Start-Async 'Bundle' 'Job_SupportBundle' @{ Dest = $dest } {
        param($r)
        if ($null -eq $r -or $r.Ok -ne $true) {
            $m = ('Yard' + [char]0x0131 + 'm paketi haz' + [char]0x0131 + 'rlanamad' + [char]0x0131 + '.')
            if ($null -ne $r -and [string]$r.Error -ne '') { $m += ' ' + [string]$r.Error }
            Show-Toast $m 'bad'; return
        }
        Show-Toast (Format-Tr ('Yard' + [char]0x0131 + 'm paketi masa' + [char]0x00FC + 'st' + [char]0x00FC + 'ne yaz' + [char]0x0131 + 'ld' + [char]0x0131 + ': {0}') ([System.IO.Path]::GetFileName([string]$r.Path))) 'good'
        try { Open-Folder ([System.IO.Path]::GetDirectoryName([string]$r.Path)) } catch { }
    } ('Yard' + [char]0x0131 + 'm paketi haz' + [char]0x0131 + 'rlan' + [char]0x0131 + 'yor'))
}

# ---------------- dugme dagitici (H_TlFileAct'in tanimadigi anahtarlar buraya duser) ----------------
function Invoke-TlExtraAct([string]$Key) {
    if (-not $Key.StartsWith('kit:')) { return }
    $p = $Key.Split(':')
    switch ([string]$p[1]) {
        'home' { Clear-KitPw; Set-KitView 'home' }
        'setup' { Set-KitView 'setup' }
        'score' { Start-KitScore }
        'net' { Start-KitNet }
        'netblock' { Start-KitNetRule ([int]$p[2]) $true }
        'netopen' { Start-KitNetRule ([int]$p[2]) $false }
        'alt' { Start-KitAlt }
        'altinst' { Start-KitAltInstall ([int]$p[2]) }
        'altall' { Open-Page 'apps' 'foss' }
        'ffxPrev' { Start-KitFirefox $true }
        'ffx' { Start-KitFirefox $false }
        'pw' { Set-KitView 'pw' }
        'pwgen' { Invoke-KitPwGen }
        'pwlen' { $script:KitPw.Len = Get-NextPwLength ([int]$script:KitPw.Len); Render-TlKit }
        'pwsym' { $script:KitPw.Symbol = (-not [bool]$script:KitPw.Symbol); Render-TlKit }
        'pwdig' { $script:KitPw.Digit = (-not [bool]$script:KitPw.Digit); Render-TlKit }
        'ren' { Start-KitRenPick }
        'renmode' { Invoke-KitRenMode ([string]$p[2]) }
        'renapply' { Start-KitRenApply }
        'bundle' { Start-KitBundle }
        'go' { $sub = ''; if ($p.Count -gt 3) { $sub = [string]$p[3] }; Open-Page ([string]$p[2]) $sub }
    }
}

# ---------------- Ucretsiz araclar listesi: lisans eki ve "yalnizca acik kaynak" suzgeci ----------------
function Get-FossDetail($Tool) {
    $d = [string]$Tool.D
    $l = Get-FossLicenseText ([string]$Tool.Id)
    if ($l -ne '') { $d = (Tr $d) + ('  ' + [char]0x00B7 + '  ') + (Tr $l) }
    return $d
}

function Add-FossFilterRow {
    $on = ($script:Settings.FossOpenOnly -eq $true)
    $btn = ('Yaln' + [char]0x0131 + 'zca a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak: kapal' + [char]0x0131 + '')
    if ($on) { $btn = ('Yaln' + [char]0x0131 + 'zca a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak: a' + [char]0x00E7 + '' + [char]0x0131 + 'k') }
    $row = New-ItemRow @{ Title = ('Lisans s' + [char]0x00FC + 'zgeci'); Detail = ('A' + [char]0x00E7 + '' + [char]0x0131 + 'kken kaynak kodu yay' + [char]0x0131 + 'mlanmayan (kapal' + [char]0x0131 + ' kaynakl' + [char]0x0131 + ') ' + [char]0x00FC + 'cretsiz ara' + [char]0x00E7 + 'lar listede g' + [char]0x00F6 + 'sterilmez. Her arac' + [char]0x0131 + 'n lisans' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'klamas' + [char]0x0131 + 'n' + [char]0x0131 + 'n sonunda yazar.'); BrCol = 'BrDim'; Btn1 = $btn } @{ Id = ''; Name = ''; Search = 'lisans acik kaynak suzgec' } $false $false
    $row.FindName('Act').Add_Click({
        Invoke-Safe {
            Set-SettingsKeys @{ FossOpenOnly = (-not ($script:Settings.FossOpenOnly -eq $true)) }
            Render-ApFoss
        } ('S' + [char]0x00FC + 'zge' + [char]0x00E7 + '')
    })
    [void]$ui.ap_List.Children.Add($row)
}

# ---------------- Yedekleme > BitLocker: sifrelemeyi acma ----------------
function Get-BlOnLabel { return ('' + [char]0x015E + 'ifrelemeyi a' + [char]0x00E7 + '') }

$script:H_BkBlOn = {
    param($s, $e)
    Invoke-Safe { Start-BlEnable ([string]$s.Tag.Drive) } ('' + [char]0x015E + 'ifreleme')
}

function Show-BlAlternatives {
    Show-Message ('Disk ' + [char]0x015F + 'ifreleme') ('Bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' Windows' + [char]0x2019 + 'un kendi ' + [char]0x015F + 'ifrelemesiyle uygulama i' + [char]0x00E7 + 'inden ' + [char]0x015F + 'ifrelenemiyor (Windows Home' + [char]0x2019 + 'da yaln' + [char]0x0131 + 'zca sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ', ' + [char]0x201C + 'Cihaz ' + [char]0x015F + 'ifrelemesi' + [char]0x201D + ' ile ' + [char]0x015F + 'ifrelenir). ' + [char]0x0130 + 'ki se' + [char]0x00E7 + 'ene' + [char]0x011F + 'iniz var: Ara' + [char]0x00E7 + 'lar > Dosya ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ' > ' + [char]0x201C + 'Dosya ' + [char]0x015F + 'ifrele (AES-256)' + [char]0x201D + ' ile tek tek dosyalar' + [char]0x0131 + ' parolayla ' + [char]0x015F + 'ifreleyebilir ya da Ara' + [char]0x00E7 + 'lar > D' + [char]0x0131 + '' + [char]0x015F + ' ara' + [char]0x00E7 + 'lar sekmesinden a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynakl' + [char]0x0131 + ' VeraCrypt' + [char]0x2019 + 'i kurup b' + [char]0x00FC + 't' + [char]0x00FC + 'n bir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'y' + [char]0x00FC + ' ya da USB belle' + [char]0x011F + 'i ' + [char]0x015F + 'ifreleyebilirsiniz.')
}

function Start-BlEnable([string]$Drive) {
    $route = Get-BlEnableRoute $Drive ([string]$env:SystemDrive) (Test-HomeEdition)
    if ($route -eq 'Settings') {
        Open-Url 'ms-settings:deviceencryption'
        Show-Toast ('Windows Home' + [char]0x2019 + 'da sistem s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' Ayarlar > Cihaz ' + [char]0x015F + 'ifrelemesi sayfas' + [char]0x0131 + 'ndan ' + [char]0x015F + 'ifrelenir; sayfa a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '. Se' + [char]0x00E7 + 'enek g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yorsa bilgisayar bunu desteklemiyordur: dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'z i' + [char]0x00E7 + 'in Ara' + [char]0x00E7 + 'lar > Dosya ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ' > Dosya ' + [char]0x015F + 'ifrele b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + 'n' + [char]0x00FC + ' kullan' + [char]0x0131 + 'n.') 'info'
        return
    }
    if ($route -eq 'Panel') {
        try { Start-Process -FilePath (Join-Path (Join-Path $env:WINDIR 'System32') 'control.exe') -ArgumentList '/name Microsoft.BitLockerDriveEncryption' -ErrorAction Stop | Out-Null; Show-Toast ('Ek s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'ler i' + [char]0x00E7 + 'in parola se' + [char]0x00E7 + 'imi gerekir; Windows' + [char]0x2019 + 'un BitLocker penceresi a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'info' }
        catch { Show-BlAlternatives }
        return
    }
    if ($route -ne 'Enable') { Show-BlAlternatives; return }
    $script:PendingDrive = $Drive
    Show-Confirm ('BitLocker' + [char]0x2019 + '' + [char]0x0131 + ' a' + [char]0x00E7 + '') (Format-Tr ('{0} s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 's' + [char]0x00FC + ' BitLocker ile ' + [char]0x015F + 'ifrelenecek (TPM ve 48 haneli kurtarma anahtar' + [char]0x0131 + '). Windows ' + [char]0x00F6 + 'nce bir donan' + [char]0x0131 + 'm s' + [char]0x0131 + 'namas' + [char]0x0131 + ' ister; ' + [char]0x015F + 'ifreleme bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'latt' + [char]0x0131 + 'ktan sonra arka planda ba' + [char]0x015F + 'lar ve ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'man' + [char]0x0131 + 'z' + [char]0x0131 + ' engellemez. ' + [char]0x0130 + '' + [char]0x015F + 'lem bitince kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + ' mutlaka bilgisayar' + [char]0x0131 + 'n DI' + [char]0x015E + 'INDA bir yere kaydedin: anahtar olmadan, donan' + [char]0x0131 + 'm de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'inden sonra dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + 'za eri' + [char]0x015F + 'emezsiniz.') $Drive) ('' + [char]0x015E + 'ifrelemeyi a' + [char]0x00E7 + '') {
        [void](Start-Async 'BlOn' 'Job_BitLockerEnable' @{ Drive = $script:PendingDrive } {
            param($r)
            $script:BkBl = $null
            if ($script:BkTab -eq 'bl') { Render-BkBl }
            if ($null -eq $r -or $r.Ok -ne $true) {
                $m = ('BitLocker a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '.')
                if ($null -ne $r -and [string]$r.Error -ne '') { $m = [string]$r.Error }
                Show-Toast $m 'bad'; return
            }
            if ($r.Verified -eq $true) { Show-Toast ('BitLocker ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + '. ' + [char]0x015E + 'imdi ' + [char]0x201C + 'Anahtar' + [char]0x0131 + ' g' + [char]0x00F6 + 'ster' + [char]0x201D + ' ya da ' + [char]0x201C + 'Dosyaya kaydet' + [char]0x201D + ' ile kurtarma anahtar' + [char]0x0131 + 'n' + [char]0x0131 + ' bilgisayar' + [char]0x0131 + 'n d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda bir yere kaydedin; ard' + [char]0x0131 + 'ndan bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'n.') 'good' }
            else { Show-Toast ('Windows komutu kabul etti ama kurtarma anahtar' + [char]0x0131 + ' do' + [char]0x011F + 'rulanamad' + [char]0x0131 + '; listeyi yenileyip durumu denetleyin.') 'warn' }
        } ('BitLocker a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
    } $true
}

