$script:AskUserXaml = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" HorizontalAlignment="Right" Background="{DynamicResource BrActiveBg}" CornerRadius="12,12,3,12" Padding="12,7" Margin="70,8,0,2">
  <TextBlock Text="@@Text@@" TextWrapping="Wrap" Foreground="{DynamicResource BrText}" FontSize="13"/>
</Border>
'@

$script:AskBotXaml = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" HorizontalAlignment="Left" Background="{DynamicResource BrCard}" BorderBrush="{DynamicResource BrLine}" BorderThickness="1" CornerRadius="12,12,12,3" Padding="14,10" Margin="0,4,46,6">
  <StackPanel>
    <TextBlock x:Name="Ttl" Text="@@Title@@" FontWeight="SemiBold" FontSize="13.5" Foreground="{DynamicResource BrText}" TextWrapping="Wrap"/>
    <TextBlock x:Name="Body" Text="@@Text@@" TextWrapping="Wrap" FontSize="12.5" Foreground="{DynamicResource BrDim}" Margin="0,4,0,0" LineHeight="19"/>
    <WrapPanel x:Name="Acts" Margin="0,9,0,0"/>
  </StackPanel>
</Border>
'@

$script:AskActXaml = @'
<Button xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Style="{DynamicResource BtnMini}" Content="@@Text@@" Tag="@@Tag@@" Margin="0,0,6,6" Padding="11,5"/>
'@

$script:AskChipXaml = @'
<Button xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Style="{DynamicResource BtnGhost}" Content="@@Text@@" Tag="@@Tag@@" Margin="0,0,6,6" Padding="10,4" FontSize="11.5"/>
'@

$script:AskReady = $false

function Add-AskUser([string]$Text) {
    $el = Read-LocalXaml ((Expand-Template $script:AskUserXaml @{ Text = $Text }))
    [void]$ui.AskChat.Children.Add($el)
}

# Answer: Get-AskAnswer sonucu
function Add-AskBot($Answer) {
    $el = Read-LocalXaml ((Expand-Template $script:AskBotXaml @{ Title = [string]$Answer.Title; Text = [string]$Answer.Text }))
    if ([string]$Answer.Title -eq '') { $el.FindName('Ttl').Visibility = $script:VisOff }
    $acts = $el.FindName('Acts')
    foreach ($a in @($Answer.Actions)) {
        if ($null -eq $a) { continue }
        $b = Read-LocalXaml ((Expand-Template $script:AskActXaml @{ Text = [string]$a.L; Tag = [string]$a.Tag }))
        $b.Add_Click({ param($s, $e) Invoke-Safe { Invoke-AskTag ([string]$s.Tag) } 'Asistan' })
        [void]$acts.Children.Add($b)
    }
    if ([string]$Answer.Also -ne '') {
        $b = Read-LocalXaml ((Expand-Template $script:AskChipXaml @{ Text = ((Tr ('' + [char]0x0130 + 'lgili')) + ': ' + (Tr ([string]$Answer.Also))); Tag = ('topic:' + [string]$Answer.AlsoKey) }))
        $b.Add_Click({ param($s, $e) Invoke-Safe { Invoke-AskTag ([string]$s.Tag) } 'Asistan' })
        [void]$acts.Children.Add($b)
    }
    if ($acts.Children.Count -eq 0) { $acts.Visibility = $script:VisOff }
    [void]$ui.AskChat.Children.Add($el)
    while ($ui.AskChat.Children.Count -gt 40) { $ui.AskChat.Children.RemoveAt(0) }
    try { $ui.AskScroll.UpdateLayout(); $ui.AskScroll.ScrollToEnd() } catch { }
}

function Invoke-Ask([string]$Text) {
    $q = ([string]$Text).Trim()
    if ($q -eq '') { return }
    if ($q.Length -gt 200) { $q = $q.Substring(0, 200) }
    Add-AskUser $q
    $hits = @()
    try { $hits = @(Get-BoardSearchResults $q) } catch { $hits = @() }
    Add-AskBot (Get-AskAnswer $q $script:CmdDefs $hits)
    $ui.AskInput.Text = (Tr $(''))
    try { [void]$ui.AskInput.Focus() } catch { }
}

function Invoke-AskTag([string]$Tag) {
    $i = $Tag.IndexOf(':')
    if ($i -lt 0) { return }
    $kind = $Tag.Substring(0, $i)
    $arg = $Tag.Substring($i + 1)
    if ($kind -eq 'topic') {
        $t = Get-AskTopic $arg
        if ($null -ne $t) { Add-AskUser ([string]$t.T); Add-AskBot @{ Title = [string]$t.T; Text = [string]$t.A; Actions = @($t.Do); Also = '' } }
        return
    }
    Hide-Ask
    if ($kind -eq 'kit') {
        Open-Page 'tools' 'kit'
        Invoke-TlExtraAct ('kit:' + $arg)
        return
    }
    Invoke-MenuTag $Tag
}

function Hide-Ask {
    if ($null -ne $ui.AskOverlay) { Set-Visible $ui.AskOverlay $false }
}

function Show-Ask([string]$Text = '') {
    if ($null -eq $ui.AskOverlay) { return }
    Close-HoverMenu
    try { Close-NavMenu } catch { }
    if (-not $script:AskReady) {
        $script:AskReady = $true
        $ui.AskChips.Children.Clear()
        foreach ($s in @(Get-AskSamples)) {
            $b = Read-LocalXaml ((Expand-Template $script:AskChipXaml @{ Text = [string]$s; Tag = [string]$s }))
            $b.Add_Click({ param($s2, $e) Invoke-Safe { Invoke-Ask ([string]$s2.Content) } 'Asistan' })
            [void]$ui.AskChips.Children.Add($b)
        }
        Add-AskBot @{ Title = 'Merhaba'; Text = ('Ne yapmak istedi' + [char]0x011F + 'inizi ya da sorununuzu kendi s' + [char]0x00F6 + 'zc' + [char]0x00FC + 'klerinizle yaz' + [char]0x0131 + 'n; ilgili a' + [char]0x00E7 + '' + [char]0x0131 + 'klamay' + [char]0x0131 + ' ve i' + [char]0x015F + 'lemleri g' + [char]0x00F6 + 'stereyim. Sayfa ve i' + [char]0x015F + 'lem adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' da arayabilirsiniz. Cevaplar bu bilgisayarda ' + [char]0x00FC + 'retilir; yazd' + [char]0x0131 + 'klar' + [char]0x0131 + 'n' + [char]0x0131 + 'z hi' + [char]0x00E7 + 'bir yere g' + [char]0x00F6 + 'nderilmez.'); Actions = @(); Also = '' }
    }
    Set-Visible $ui.AskOverlay $true
    $ui.AskInput.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Input, [Action]{ try { [void]$ui.AskInput.Focus() } catch { } }) | Out-Null
    if ($Text.Trim() -ne '') { Invoke-Ask $Text }
}

function Initialize-Ask {
    if ($null -eq $ui.AskOverlay -or $null -eq $ui.BtnAsk) { return }
    $ui.BtnAsk.Add_Click({ Invoke-Safe { Show-Ask '' } 'Asistan' })
    $ui.AskClose.Add_Click({ Invoke-Safe { Hide-Ask } 'Asistan' })
    $ui.AskSend.Add_Click({ Invoke-Safe { Invoke-Ask ([string]$ui.AskInput.Text) } 'Asistan' })
    $ui.AskInput.Add_PreviewKeyDown({
        param($s, $e)
        if ($e.Key -eq [System.Windows.Input.Key]::Enter) { $e.Handled = $true; Invoke-Safe { Invoke-Ask ([string]$ui.AskInput.Text) } 'Asistan' }
    })
    $ui.AskOverlay.Add_PreviewKeyDown({
        param($s, $e)
        if ($e.Key -eq [System.Windows.Input.Key]::Escape) { $e.Handled = $true; Hide-Ask }
    })
    # kartin disina (karartilmis alana) tiklaninca kapanir
    $ui.AskOverlay.Add_MouseLeftButtonDown({
        param($s, $e)
        try { if ([object]::ReferenceEquals($e.OriginalSource, $ui.AskOverlay)) { Hide-Ask } } catch { }
    })
    $script:Win.Add_PreviewKeyDown({
        param($s, $e)
        try {
            if ($e.Key -eq [System.Windows.Input.Key]::F1) {
                $e.Handled = $true
                if ($ui.AskOverlay.Visibility -eq $script:VisOn) { Hide-Ask } else { Show-Ask '' }
            }
        } catch { }
    })
}

# Pencere kurulurken bir kez cagrilir
function Initialize-UxExtras {
    try { Initialize-Ask } catch { Write-CrashLog ('Asistan: ' + $_.Exception.Message) }
    try { Initialize-RailHover } catch { Write-CrashLog ('Sol cubuk: ' + $_.Exception.Message) }
}

# ---------------- duman testi: "kullanim" kapsami ----------------
# Fare hareket ettirilmez; menuler ve Asistan dogrudan islevleriyle acilir, goruntuleri alinir. Pano, ayar ve sistem degismez.
function Test-SmokeUx([string]$What) {
    if ($What -eq 'ask') {
        if ($null -eq $ui.BtnAsk -or $ui.BtnAsk.IsVisible -ne $true) { Add-SmokeError 'kullanim' ('Asistan d' + [char]0x00FC + '' + [char]0x011F + 'mesi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor'); return }
        Show-Ask ''
        Invoke-SmokeFlush
        if ($ui.AskOverlay.Visibility -ne $script:VisOn) { Add-SmokeError 'kullanim' ('Asistan paneli a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + ''); return }
        Invoke-Ask ('bilgisayar' + [char]0x0131 + 'm ' + [char]0x00E7 + 'ok yava' + [char]0x015F + '')
        Invoke-SmokeFlush
        $n = $ui.AskChat.Children.Count
        if ($n -lt 3) { Add-SmokeError 'kullanim' ('Asistan sohbetinde ' + [string]$n + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e var (kar' + [char]0x015F + '' + [char]0x0131 + 'lama, soru ve cevap bekleniyordu)')) }
        $last = $ui.AskChat.Children[$n - 1]
        $acts = 0
        try { $acts = $last.FindName('Acts').Children.Count } catch { }
        if ($acts -lt 2) { Add-SmokeError 'kullanim' (('Asistan cevab' + [char]0x0131 + 'nda ') + [string]$acts + (' eylem d' + [char]0x00FC + '' + [char]0x011F + 'mesi var, en az 2 bekleniyordu')) }
        if ($ui.AskChips.Children.Count -lt 5) { Add-SmokeError 'kullanim' ('Asistan ' + [char]0x00F6 + 'rnek sorular' + [char]0x0131 + ' eksik') }
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: Asistan a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ', cevapta ') + [string]$acts + ' eylem, ' + [string]$ui.AskChips.Children.Count + (' ' + [char]0x00F6 + 'rnek soru'))
        return
    }
    if ($What -eq 'askclose') {
        Hide-Ask
        Invoke-SmokeFlush
        if ($ui.AskOverlay.Visibility -eq $script:VisOn) { Add-SmokeError 'kullanim' ('Asistan paneli kapanmad' + [char]0x0131 + '') }
        return
    }
    if ($What -eq 'hover') {
        $rb = $ui['Rail_tools']
        $items = @(Get-RailSubItemsShown 'tools')
        $want = @(Get-TlVisibleTabs ($script:UiState.Mode -eq 'Expert')).Count
        if ($items.Count -ne $want) { Add-SmokeError 'kullanim' (('Ara' + [char]0x00E7 + 'lar i' + [char]0x00E7 + 'in ') + [string]$items.Count + ' alt sekme okundu, beklenen ' + [string]$want) }
        # Araclar dugmesi kapali bir grubun icindeyse grup denetim suresince acilir, sonunda eski haline doner
        $opened = $null
        if ($null -ne $rb -and $rb.IsVisible -ne $true) {
            foreach ($g in @($script:RailGroups)) {
                if (@($g.Pages) -contains 'tools' -and -not [bool]$g.Open) { Set-GroupOpen $g $true; $opened = $g; break }
            }
            for ($i = 0; $i -lt 6; $i++) { Invoke-SmokeFlush; Start-Sleep -Milliseconds 40 }
            try { $rb.BringIntoView() } catch { }
            Invoke-SmokeFlush
        }
        if ($null -eq $rb -or $rb.IsVisible -ne $true) {
            if ($null -ne $opened) { Set-GroupOpen $opened $false }
            Add-SmokeLine ('      kullan' + [char]0x0131 + 'm: Ara' + [char]0x00E7 + 'lar d' + [char]0x00FC + '' + [char]0x011F + 'mesi bu kipte g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor; alt sekme men' + [char]0x00FC + 's' + [char]0x00FC + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + ' atland' + [char]0x0131 + '')
            return
        }
        $script:HoverPin = $true
        Show-HoverMenu $rb (@(@{ Head = ('ARA' + [char]0x00C7 + 'LAR') }) + $items)
        for ($i = 0; $i -lt 14; $i++) { Invoke-SmokeFlush; Start-Sleep -Milliseconds 50 }
        if ($null -eq $script:HoverPop -or -not $script:HoverPop.IsOpen) {
            Add-SmokeError 'kullanim' ('alt sekme men' + [char]0x00FC + 's' + [char]0x00FC + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + ''); $script:HoverPin = $false
            if ($null -ne $opened) { Set-GroupOpen $opened $false }
            return
        }
        $cnt = $script:HoverPop.FindName('Items').Children.Count
        if ($cnt -ne ($items.Count + 1)) { Add-SmokeError 'kullanim' (('alt sekme men' + [char]0x00FC + 's' + [char]0x00FC + 'nde ') + [string]$cnt + (' sat' + [char]0x0131 + 'r var')) }
        Save-SmokeScreen 'kullanim-alt-sekme-menusu'
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: alt sekme men' + [char]0x00FC + 's' + [char]0x00FC + ' ') + [string]$cnt + (' sat' + [char]0x0131 + 'rla a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + ''))
        $script:HoverPin = $false
        Close-HoverMenu
        if ($null -ne $opened) { Set-GroupOpen $opened $false; Invoke-SmokeFlush }
        return
    }
    if ($What -eq 'group') {
        if ($script:RailGroupsOn -ne $true -or $script:RailGroups.Count -eq 0) { Add-SmokeLine ('      kullan' + [char]0x0131 + 'm: sol ' + [char]0x00E7 + 'ubuk gruplar' + [char]0x0131 + ' bu yerle' + [char]0x015F + 'imde kapal' + [char]0x0131 + '; grup denetimi atland' + [char]0x0131 + ''); return }
        $g = $null
        foreach ($x in @($script:RailGroups)) { if (-not [bool]$x.Open -and $x.Header.Visibility -eq $script:VisOn) { $g = $x; break } }
        if ($null -eq $g) { Add-SmokeLine ('      kullan' + [char]0x0131 + 'm: kapal' + [char]0x0131 + ' grup yok; grup denetimi atland' + [char]0x0131 + ''); return }
        Set-GroupOpen $g $true; $g.Peek = $true
        Invoke-SmokeFlush
        if (-not [bool]$g.Open) { Add-SmokeError 'kullanim' ('grup a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + '') }
        Close-RailPeek
        Invoke-SmokeFlush
        if ([bool]$g.Open) { Add-SmokeError 'kullanim' ('ge' + [char]0x00E7 + 'ici a' + [char]0x00E7 + '' + [char]0x0131 + 'lan grup, fare ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + 'nca kapanmad' + [char]0x0131 + '') }
        else { Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: ' + [char]0x201C + '') + [string]$g.Title + ('' + [char]0x201D + ' grubu ge' + [char]0x00E7 + 'ici a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'p kapand' + [char]0x0131 + '')) }
        return
    }
    if ($What -eq 'kit') {
        Open-Page 'tools' 'kit'
        Invoke-SmokeFlush
        $n = $ui.tl_List.Children.Count
        if ($n -lt 10) { Add-SmokeError 'kullanim' (('Yard' + [char]0x0131 + 'mc' + [char]0x0131 + 'lar listesinde ') + [string]$n + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e var')); return }
        $short = 0; $tips = 0
        foreach ($row in $ui.tl_List.Children) {
            if ($row -isnot [System.Windows.Controls.Border]) { continue }
            $det = $null
            try { $det = $row.FindName('Det') } catch { }
            if ($null -eq $det) { continue }
            if ($det.TextWrapping -eq [System.Windows.TextWrapping]::NoWrap) { $short++ }
            if ($null -ne $row.ToolTip) { $tips++ }
        }
        if ((Test-FullDesc) -eq $false -and ($short -lt 5 -or $tips -lt 5)) { Add-SmokeError 'kullanim' (('k' + [char]0x0131 + 'sa a' + [char]0x00E7 + '' + [char]0x0131 + 'klama: ') + [string]$short + (' sat' + [char]0x0131 + 'r tek sat' + [char]0x0131 + 'ra indi, ') + [string]$tips + (' sat' + [char]0x0131 + 'rda ipucu var')) }
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: Yard' + [char]0x0131 + 'mc' + [char]0x0131 + 'lar ') + [string]$n + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e; ') + [string]$short + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'klama tek sat' + [char]0x0131 + 'r, ') + [string]$tips + ' ipucu')
        # parola ureteci: eklenti yuklenir, parola uretilir (panoya yazilmaz)
        $x = Import-MmExt 'Parola'
        if ($x.Ok -ne $true) { Add-SmokeError 'kullanim' (('parola eklentisi y' + [char]0x00FC + 'klenemedi: ') + [string]$x.Error); return }
        $pw = New-RandomPassword 20 (Get-PasswordSets $true $true $true)
        if ($pw.Length -ne 20 -or $pw -cnotmatch '\d' -or $pw -cnotmatch '[!#$%&*+\-=?@_]') { Add-SmokeError 'kullanim' ('' + [char]0x00FC + 'retilen parola beklenen bi' + [char]0x00E7 + 'imde de' + [char]0x011F + 'il') }
        else { Add-SmokeLine ('      kullan' + [char]0x0131 + 'm: parola ' + [char]0x00FC + 'reteci 20 karakterlik parola ' + [char]0x00FC + 'retti (panoya yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + ')') }
        return
    }
    if ($What -eq 'pano') {
        # ana ekran: izleme dongusunun ilk tam turu beklenir (en cok 20 sn), sonra ekran karti ve sicaklik kartlarinin yazilari okunur
        Open-Page 'panel'
        for ($i = 0; $i -lt 100; $i++) {
            Invoke-SmokeFlush
            $d = $sync.MonDiag
            if ($null -ne $d -and [int]$d.Tick -ge 5) { break }
            Start-Sleep -Milliseconds 200
        }
        for ($i = 0; $i -lt 16; $i++) { Invoke-SmokeFlush; Start-Sleep -Milliseconds 150 }
        $parts = New-Object System.Collections.ArrayList
        foreach ($k in @($script:BoardViews.Keys)) {
            $v = $script:BoardViews[$k]
            $t = [string]$v.Type
            if ($t -ne 'gpu' -and $t -ne 'temp') { continue }
            try { [void]$parts.Add($t + '=' + [string]$v.N.Val.Text + ' [' + [string]$v.N.Sub.Text + ']') } catch { }
        }
        $m = $sync.Mon
        $line = ('      kullan' + [char]0x0131 + 'm: pano kartlar' + [char]0x0131 + ': ') + ($parts -join '; ')
        if ($null -ne $m) { $line += (' | ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm: GPU=') + [string]$m.Gpu + (' s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k=') + [string]$m.Temp + (' GPU s' + [char]0x0131 + 'cakl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + '=') + [string]$m.GpuTemp }
        $line += (' | g' + [char]0x00FC + 'venli kip=') + [string]($sync.SafeMon -eq $true)
        Add-SmokeLine $line
        foreach ($x in $parts) { if ([string]$x -like ('*' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor*')) { Add-SmokeError 'kullanim' (('ilk ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'mden sonra kart h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' bekliyor: ') + [string]$x) } }
        return
    }
    if ($What -eq 'sorunlar') {
        # saglik taramasinin bulgulari: "sorun" sayilanlar ve her birinin tek tikla acilan eylemi var mi (yalnizca okuma)
        $h = $script:Health
        if ($null -eq $h -or $null -eq $h.Findings) { Add-SmokeLine ('      kullan' + [char]0x0131 + 'm: sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ' sonucu yok; sorun listesi atland' + [char]0x0131 + ''); return }
        $n = 0; $noAct = 0
        foreach ($f in @($h.Findings)) {
            $st = [string]$f.Status
            if ($st -ne 'bad' -and $st -ne 'warn' -and [string]$f.Id -ne 'av-excl') { continue }
            $n++
            $act = 'eylem yok'
            if ($null -ne $f.Fix) { $act = ('D' + [char]0x00FC + 'zelt') }
            elseif ($null -ne $f.Action) { $act = [string]$f.Action.Kind + ':' + [string]$f.Action.Label }
            else { $noAct++ }
            Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: bulgu [') + $st + '] ' + [string]$f.Id + (' ' + [char]0x2014 + ' ') + [string]$f.Title + (' ' + [char]0x2192 + ' ') + $act)
        }
        $pend = '?'
        try { $p = Get-PendingReboot; $pend = (@($p) -join ', ') } catch { }
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: sorun say' + [char]0x0131 + 'lan bulgu ') + [string]$n + '; eylemsiz ' + [string]$noAct + ('; yeniden ba' + [char]0x015F + 'latma nedeni: [') + $pend + (']; y' + [char]0x00F6 + 'netici=') + [string]([bool]$script:IsAdmin))
        return
    }
    if ($What -eq 'kurulum') {
        # kurulum teklifi kutusu: acilir, goruntusu alinir, secim yapilmadan kapatilir (hicbir sey kurulmaz, ayar yazilmaz)
        try { Open-Page 'panel'; Invoke-SmokeFlush } catch { }
        Show-InstallOffer
        for ($i = 0; $i -lt 6; $i++) { Invoke-SmokeFlush; Start-Sleep -Milliseconds 60 }
        if ($ui.Overlay.Visibility -ne $script:VisOn) { Add-SmokeError 'kullanim' ('kurulum teklifi kutusu a' + [char]0x00E7 + '' + [char]0x0131 + 'lmad' + [char]0x0131 + ''); return }
        Save-SmokeScreen 'kullanim-kurulum-teklifi'
        # kullanicinin "Daha sonra sor" dugmesine basmasiyla ayni yol: secim yapilmaz
        Complete-Overlay $false
        $script:ChoiceAction = $null
        Invoke-SmokeFlush
        if ($ui.Overlay.Visibility -eq $script:VisOn) { Add-SmokeError 'kullanim' ('kurulum teklifi kutusu kapanmad' + [char]0x0131 + '') }
        $need = Test-InstallOfferNeeded $script:Settings ([string]$sync.ScriptPath) (Get-InstallDir) $false
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: kurulum teklifi kutusu a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'p kapand' + [char]0x0131 + '; bu kopyada ger' + [char]0x00E7 + 'ek a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + 'ta sorulur mu: ') + [string]$need + ' (kurulu=' + [string]($script:Settings.Installed -eq $true) + ')')
        return
    }
    if ($What -eq 'desc') {
        try { Open-Page 'settings'; Invoke-SmokeFlush } catch { }
        $root = Build-Page 'settings'
        $n = 0
        $stack = New-Object System.Collections.Stack
        $stack.Push($root)
        while ($stack.Count -gt 0) {
            $cur = $stack.Pop()
            if ($cur -is [System.Windows.Controls.TextBlock]) { if ([string]$cur.Tag -eq 'desc' -and $cur.TextWrapping -eq [System.Windows.TextWrapping]::NoWrap -and $null -ne $cur.ToolTip) { $n++ }; continue }
            if ($cur -isnot [System.Windows.DependencyObject]) { continue }
            foreach ($ch in [System.Windows.LogicalTreeHelper]::GetChildren($cur)) { if ($ch -is [System.Windows.DependencyObject]) { $stack.Push($ch) } }
        }
        if ((Test-FullDesc) -eq $false -and $n -lt 3) { Add-SmokeError 'kullanim' (('Ayarlar sayfas' + [char]0x0131 + 'nda yaln' + [char]0x0131 + 'zca ') + [string]$n + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'klama tek sat' + [char]0x0131 + 'ra indi')) }
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: Ayarlar sayfas' + [char]0x0131 + 'nda ') + [string]$n + (' a' + [char]0x00E7 + '' + [char]0x0131 + 'klama tek sat' + [char]0x0131 + 'r ve ipu' + [char]0x00E7 + 'lu'))
        return
    }
    if ($What -eq 'drift') {
        # gercek ayar kaydiyla: hangi uygulanmis ayar "Windows tarafindan geri alinmis" gorunuyor (yalnizca okuma)
        $new = Get-DriftedIds
        $new = @($new)
        $applied = Get-AppliedIds
        $applied = @($applied)
        $old = New-Object System.Collections.ArrayList
        foreach ($id in $applied) {
            $c = Get-CatalogItem ([string]$id)
            if ($null -eq $c) { continue }
            try { if ((Get-TweakPending $c) -gt 0) { [void]$old.Add([string]$id) } } catch { }
        }
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: uygulanm' + [char]0x0131 + '' + [char]0x015F + ' ayar ') + [string]$applied.Count + ('; geri d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen (yeni kural, g' + [char]0x00F6 + 'revler hari' + [char]0x00E7 + '): ') + [string]$new.Count + ' [' + ($new -join ', ') + ']')
        Add-SmokeLine (('      kullan' + [char]0x0131 + 'm: eski kuralla (g' + [char]0x00F6 + 'revler dahil) geri d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen: ') + [string]$old.Count + ' [' + ($old -join ', ') + ']')
        return
    }
    Add-SmokeError 'kullanim' ('bilinmeyen denetim: ' + $What)
}

# ---------------- kurulum teklifi: once bilesenler, sonra uygulama ----------------
# ==================================================================
#  KURULUM TEKLIFI (arayuz): uygulama kurulu degilken ilk acilista "kurulsun mu?" diye sorar.
#  "Kur" secilirse sira sudur: (1) eksik bilesenler denetlenir, (2) eksikler winget ile kurulur, (3) uygulama kalici klasore kopyalanir ve kisayollar eklenir.
#  Bilesen kurulumu basarisiz olsa da uygulama kurulur; eksik kalanlar Cozum Merkezi > Hazirlik sekmesinde gorunur.
#  "Kurmadan kullan" secilirse bir daha sorulmaz (Ayarlar > Kur her zaman kullanilabilir). Pencere kapatilirsa sonraki acilista yeniden sorulur.
# ==================================================================
$script:SetupTimer = $null
$script:SetupPkgs = @()

# Saf: kurulum teklifi gosterilmeli mi?
function Test-InstallOfferNeeded($Settings, [string]$ScriptPath, [string]$InstallDir, [bool]$Smoke) {
    if ($Smoke -or $null -eq $Settings) { return $false }
    if ($Settings.Installed -eq $true -or $Settings.InstallAsked -eq $true) { return $false }
    if ([string]$ScriptPath -eq '' -or [string]$InstallDir -eq '') { return $false }
    # Klasor adi elle ayrilir: yol ayiricisi hem \ hem / olabilir
    $norm = ([string]$ScriptPath).Replace('/', '\')
    $cut = $norm.LastIndexOf('\')
    if ($cut -le 0) { return $false }
    $here = $norm.Substring(0, $cut).TrimEnd('\')
    $inst = ([string]$InstallDir).Replace('/', '\').TrimEnd('\')
    if ([string]::Equals($here, $inst, [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
    return $true
}

# Saf: kurulacak bilesenlerin ozeti (onay metni icin)
function Get-SetupDepsText($Pkgs) {
    $pk = @($Pkgs | Where-Object { $null -ne $_ })
    if ($pk.Count -eq 0) { return ('Eksik bile' + [char]0x015F + 'en yok.') }
    return ((@($pk | ForEach-Object { [string]$_.Name }) -join ', '))
}

function Show-InstallOffer {
    $opts = @(
        @{ Key = 'install'; Title = ('Kur (' + [char]0x00F6 + 'nerilir)'); Detail = ('' + [char]0x00D6 + 'nce eksik bile' + [char]0x015F + 'enler (Visual C++, .NET, DirectX) denetlenir ve winget deposundan kurulur; sonra uygulama kal' + [char]0x0131 + 'c' + [char]0x0131 + ' klas' + [char]0x00F6 + 're kopyalan' + [char]0x0131 + 'r, Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + 'ne ve masa' + [char]0x00FC + 'st' + [char]0x00FC + 'ne k' + [char]0x0131 + 'sayol eklenir. Zamanlanm' + [char]0x0131 + '' + [char]0x015F + ' bak' + [char]0x0131 + 'm, yedekleme ve rapor kurulumla kullan' + [char]0x0131 + 'labilir.') },
        @{ Key = 'portable'; Title = 'Kurmadan kullan'; Detail = ('Uygulama bulundu' + [char]0x011F + 'u klas' + [char]0x00F6 + 'rden ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'r; bilgisayara dosya kopyalanmaz ve k' + [char]0x0131 + 'sayol eklenmez. ' + [char]0x0130 + 'stedi' + [char]0x011F + 'iniz zaman Ayarlar > Kur ile kurabilirsiniz.') }
    )
    Show-Choice 'Multimizer bu bilgisayara kurulsun mu?' ('Kurulum yaln' + [char]0x0131 + 'zca bu bilgisayarda kal' + [char]0x0131 + 'r: hesap a' + [char]0x00E7 + '' + [char]0x0131 + 'lmaz, internete veri g' + [char]0x00F6 + 'nderilmez. Kald' + [char]0x0131 + 'rmak i' + [char]0x00E7 + 'in Ayarlar > Kurulumu kald' + [char]0x0131 + 'r yeterlidir.') $opts 'Daha sonra sor' {
        param($key)
        if ([string]$key -eq 'install') { Start-SetupInstall }
        elseif ([string]$key -eq 'portable') { Set-SettingsKeys @{ InstallAsked = $true }; Show-Toast ('Kurmadan kullan' + [char]0x0131 + 'l' + [char]0x0131 + 'yor. Ayarlar > Kur ile diledi' + [char]0x011F + 'iniz zaman kurabilirsiniz.') 'info' }
    }
}

# 1) bilesen denetimi
function Start-SetupInstall {
    Set-SettingsKeys @{ InstallAsked = $true }
    $ok = Start-Async 'SetupPrep' 'Job_PrepCheck' @{} {
        param($r)
        Invoke-Safe {
            $pk = @()
            if ($null -ne $r -and $r.Ok -eq $true) {
                try {
                    # Get-PrepInstallList diziyi tek nesne olarak dondurur; once degiskene alinir, sonra suzulur
                    $all = Get-PrepInstallList (Get-PrepItems $r.State $false)
                    $pk = @(@($all) | Where-Object { $null -ne $_ -and (Test-PrepPackage ([string]$_.Id)) -eq '' })
                } catch { $pk = @() }
            } else { Write-WhLog ('Bile' + [char]0x015F + 'en denetimi yap' + [char]0x0131 + 'lamad' + [char]0x0131 + '; uygulama kurulumu s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor.') 'WARN' }
            if ($pk.Count -gt 0) { Start-SetupDeps $pk } else { Write-WhLog ('Eksik bile' + [char]0x015F + 'en yok.') 'OK'; Start-SetupCopy }
        } 'Kurulum'
    } ('Kurulum 1/3: bile' + [char]0x015F + 'enler denetleniyor')
    if (-not $ok) { Show-Toast ('Kurulum ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + '; s' + [char]0x00FC + 'ren i' + [char]0x015F + 'lem bitince Ayarlar > Kur ile yeniden deneyin.') 'warn' }
}

# 2) eksik bilesenler
function Start-SetupDeps($Pkgs) {
    $script:SetupPkgs = @($Pkgs)
    Write-WhLog (('Eksik bile' + [char]0x015F + 'enler: ') + (Get-SetupDepsText $script:SetupPkgs)) 'INFO'
    $ids = @($script:SetupPkgs | ForEach-Object { [string]$_.Id })
    $ok = Start-Async 'SetupDeps' 'Job_PrepInstall' @{ Ids = $ids } {
        param($r)
        Invoke-Safe {
            $script:PrepState = $null
            if ($null -eq $r -or [int]$r.Failed -gt 0 -or [string]$r.Error -ne '') {
                Write-WhLog ('Baz' + [char]0x0131 + ' bile' + [char]0x015F + 'enler kurulamad' + [char]0x0131 + '; uygulama yine de kurulacak. Eksik kalanlar ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'm Merkezi > Haz' + [char]0x0131 + 'rl' + [char]0x0131 + 'k sekmesinde g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.') 'WARN'
            }
            Start-SetupCopy
        } 'Kurulum'
    } ('Kurulum 2/3: eksik bile' + [char]0x015F + 'enler kuruluyor')
    if (-not $ok) { Start-SetupCopy }
}

# 3) uygulama dosyalari ve kisayollar
function Start-SetupCopy {
    [void](Start-Async 'Install' 'Job_Install' @{ Desktop = $true } {
        param($r)
        Invoke-Safe {
            if ($null -ne $r -and $r.Ok -eq $true) {
                $script:Settings = Get-Settings
                Show-Toast ('Kurulum tamamland' + [char]0x0131 + '. Multimizer art' + [char]0x0131 + 'k Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + 'nden ve masa' + [char]0x00FC + 'st' + [char]0x00FC + 'ndeki k' + [char]0x0131 + 'sayoldan a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r.') 'good'
            } else { Show-Toast ('Kurulum tamamlanamad' + [char]0x0131 + '; ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte. Ayarlar > Kur ile yeniden deneyebilirsiniz.') 'bad' }
            try { if ($null -ne $ui.st_InstState) { Update-StInstall } } catch { }
        } 'Kurulum'
    } 'Kurulum 3/3: uygulama kuruluyor')
}

# Pencere gorununce bir kez sorar (ilk acilis sorusundan once). Duman testinde ve kurulu kopyada sorulmaz.
function Initialize-InstallOffer {
    $need = $false
    try { $need = Test-InstallOfferNeeded $script:Settings ([string]$sync.ScriptPath) (Get-InstallDir) ([bool]$script:SmokeMode) } catch { $need = $false }
    if (-not $need) { return }
    $script:SetupTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:SetupTimer.Interval = [TimeSpan]::FromMilliseconds(1500)
    $script:SetupTimer.Add_Tick({
        try {
            if (-not $script:Win.IsVisible) { return }
            if ($ui.Overlay.Visibility -eq $script:VisOn -or $null -ne $script:Cur) { return }
            $script:SetupTimer.Stop()
            if (Test-InstallOfferNeeded $script:Settings ([string]$sync.ScriptPath) (Get-InstallDir) ([bool]$script:SmokeMode)) { Show-InstallOffer }
        } catch { try { $script:SetupTimer.Stop() } catch { }; Write-CrashLog ('Kurulum teklifi: ' + $_.Exception.Message) }
    })
    $script:SetupTimer.Start()
}

# ---------------- canli ozellik denetimi: cekirdek (olcum, tur, geri yukleme) ----------------
# ==================================================================
#  CANLI OZELLIK DENETIMI  (duman kapsami "ozellik")
#  Gercek Windows'ta, bu bilgisayarda: katalogdaki her ayari uygulamanin kendi motoruyla uygular, sistemden BAGIMSIZ bir okumayla
#  dogrular, geri alir ve eski halle karsilastirir. Bulunan her tutarsizlik "HATA" olarak raporlanir.
#  Iki kip (ortam degiskeni MM_OZELLIK_KIP):
#    oku (varsayilan) : hicbir sey yazmaz. Her ayarin olcumunu, onizlemesini ve yalnizca-okuma denetimlerini yapar.
#    tam              : yonetici olarak calisirken gercek tur (uygula -> dogrula -> geri al -> karsilastir). Her adimdan once eski durum
#                       diskte saklanir (%TEMP%\Multimizer-duman-geri); surec oluse bile bir sonraki acilista kendiliginden geri yuklenir.
#                       Yonetici degilse "oku" kipine iner.
#  Geri alinamayan islemler (temizlik, uygulama kaldirma, Windows bilesenini kaldirma) gercek veriye uygulanmaz: onizleme ve olcum yapilir,
#  silme / yazma mantigi gecici bir deneme alaninda (klasor ya da sanal disk) sinanir.
#  Sonuc: Multimizer-duman.txt ("canli ..." satirlari) ve Multimizer-duman-ozellik.tsv
# ==================================================================

$script:LiveRows = New-Object System.Collections.ArrayList
$script:LiveMode = ''
$script:LiveDowngraded = $false
$script:LiveState = @{}
$script:LiveTsv = ''
$script:LiveT0 = $null
$script:LiveApplicable = $null

function Get-LiveDir {
    $d = Join-Path ([System.IO.Path]::GetTempPath()) 'Multimizer-duman-geri'
    try { if (-not (Test-Path -LiteralPath $d)) { [void](New-Item -ItemType Directory -Path $d -Force) } } catch { }
    return $d
}

function Get-LiveMode {
    if ($script:LiveMode -ne '') { return $script:LiveMode }
    $m = ''
    try { $m = ([string]$env:MM_OZELLIK_KIP).Trim().ToLowerInvariant() } catch { $m = '' }
    if ($m -eq 'tam' -and -not [bool]$script:IsAdmin) { $m = 'oku'; $script:LiveDowngraded = $true }
    if ($m -ne 'tam') { $m = 'oku' }
    $script:LiveMode = $m
    return $m
}

function Format-LiveMs([double]$Ms) {
    if ($Ms -ge 60000) { return ([string][math]::Round($Ms / 60000, 1) + ' dk') }
    if ($Ms -ge 1000) { return ([string][math]::Round($Ms / 1000, 1) + ' sn') }
    return ([string][int]$Ms + ' ms')
}

# Bir sonuc satiri: Durum = OK | HATA | UYARI | ATLA | BILGI.  HATA hata sayilir (cikis kodu 2), UYARI uyari sayilir.
function Add-LiveRow([string]$Area, [string]$Id, [string]$Status, [string]$Detail, [double]$Ms = 0) {
    $d = $Detail
    if ($null -eq $d) { $d = '' }
    $d = ($d -replace "[\r\n\t]+", ' ').Trim()
    $r = [pscustomobject]@{ Alan = $Area; Kimlik = $Id; Durum = $Status; Ayrinti = $d; Ms = [int]$Ms }
    [void]$script:LiveRows.Add($r)
    $text = ('      canl' + [char]0x0131 + ' ') + $Area + ' [' + $Status + '] ' + $Id
    if ($d -ne '') { $text += (' ' + [char]0x2014 + ' ') + $d }
    if ($Ms -ge 1) { $text += ' (' + (Format-LiveMs $Ms) + ')' }
    if ($Status -eq 'HATA') { Add-SmokeError 'ozellik' ($Area + '/' + $Id + ': ' + $d) }
    elseif ($Status -eq 'UYARI') { Add-SmokeWarn ($Area + '/' + $Id + ': ' + $d) }
    else { Add-SmokeLine $text }
    try { [Console]::WriteLine('  ' + $Area + ' [' + $Status + '] ' + $Id + $(if ($d.Length -gt 110) { (' ' + [char]0x2014 + ' ') + $d.Substring(0, 110) + '...' } elseif ($d -ne '') { (' ' + [char]0x2014 + ' ') + $d } else { '' })) } catch { }
    try {
        if ($script:LiveTsv -eq '') { $script:LiveTsv = Join-Path ([System.IO.Path]::GetTempPath()) 'Multimizer-duman-ozellik.tsv'; [System.IO.File]::WriteAllText($script:LiveTsv, ("Alan`tKimlik`tDurum`tMs`tAyrinti`r`n"), (New-Object System.Text.UTF8Encoding($true))) }
        [System.IO.File]::AppendAllText($script:LiveTsv, ($Area + "`t" + $Id + "`t" + $Status + "`t" + [string][int]$Ms + "`t" + $d + "`r`n"), (New-Object System.Text.UTF8Encoding($false)))
    } catch { }
}

function Get-LiveCount([string]$Status) { return @($script:LiveRows | Where-Object { $_.Durum -eq $Status }).Count }

# ---------------- gunluk kuyrugu: bir cagrinin yazdigi satirlari yakalar ----------------
function Get-LiveLogMark {
    try { return [int64](New-Object System.IO.FileInfo ([string]$sync.LogFile)).Length } catch { return [int64]0 }
}

function Get-LiveLogSince([int64]$Mark) {
    $out = @()
    try {
        $fs = [System.IO.File]::Open([string]$sync.LogFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try {
            if ($fs.Length -gt $Mark) {
                [void]$fs.Seek($Mark, [System.IO.SeekOrigin]::Begin)
                $buf = New-Object byte[] ([int]($fs.Length - $Mark))
                [void]$fs.Read($buf, 0, $buf.Length)
                $out = @(([System.Text.Encoding]::UTF8.GetString($buf)) -split "`r?`n" | Where-Object { $_ -ne '' })
            }
        } finally { $fs.Close() }
    } catch { }
    return , $out
}

function Select-LiveLines($Lines, [string]$Level) {
    return , @(@($Lines) | Where-Object { $_ -match ('^\d\d:\d\d:\d\d\s+' + $Level + '\s') })
}

# Motorun is islevini (Job_Plan, Job_Undo ...) arayuz is parcaciginin yaptigi gibi cagirir; sayac durumunu korur
function Invoke-LiveJob([string]$Fn, $Arg) {
    $keepP = $script:Preview; $keepS = $script:Silent
    $out = $null; $err = ''
    try { $out = & $Fn $Arg } catch { $err = $_.Exception.Message }
    finally { $script:Preview = $keepP; $script:Silent = $keepS }
    if ($out -is [System.Array]) {
        $h = @($out | Where-Object { $_ -is [hashtable] })
        if ($h.Count -gt 0) { $out = $h[$h.Count - 1] }
    }
    return @{ Out = $out; Err = $err }
}

# ---------------- okuma bekcisi ----------------
# Okuma isleri (Get-LiveReadJobs) hicbir sey yazmamali. Bir is yanlislikla yazmaya kalkarsa (ornegin onizleme bayragi unutulursa) is suresince
# asagidaki komutlar YEREL kapsamda "bos" islevlerle gizlenir: islem YAPILMAZ, deneme kaydedilir ve HATA olarak bildirilir. Islevler yerel kapsamda
# tanimlandigi icin is bitince kendiliginden kalkar (istisna olsa bile asil komutlar eski haline doner). Merkezi giris noktasi Invoke-Op da
# onizleme degilse hicbir sey yapmaz; Func, Mp, Feature ... dahil her ayar turu buradan gecer.
# Sinir: bekci yalnizca bu is parcaciginda calisan komutlari yakalar; ayri bir calisma alani (runspace) acan kod bekcinin disinda kalir.
$script:LiveGuardNames = @(
    'Set-Service', 'Stop-Service', 'Start-Service', 'Restart-Service', 'Suspend-Service', 'Resume-Service', 'New-Service', 'Remove-Service',
    'Set-MpPreference', 'Add-MpPreference', 'Remove-MpPreference',
    'Disable-ScheduledTask', 'Enable-ScheduledTask', 'Unregister-ScheduledTask', 'Register-ScheduledTask', 'Set-ScheduledTask',
    'Set-NetFirewallRule', 'New-NetFirewallRule', 'Remove-NetFirewallRule', 'Enable-NetFirewallRule', 'Disable-NetFirewallRule', 'Set-NetFirewallProfile',
    'Stop-Process', 'Restart-Computer', 'Stop-Computer',
    'Set-DnsClientServerAddress', 'Set-DnsClientDohServerAddress', 'Add-DnsClientDohServerAddress', 'Remove-DnsClientDohServerAddress',
    'Enable-WindowsOptionalFeature', 'Disable-WindowsOptionalFeature', 'Add-WindowsCapability', 'Remove-WindowsCapability',
    'Invoke-DismExe', 'Set-WinFeatureState', 'Set-WinCapabilityState', 'Add-AppxPackage',
    'Set-NetIPInterface', 'Set-NetConnectionProfile', 'Remove-AppxPackage', 'Remove-AppxProvisionedPackage',
    'Checkpoint-Computer', 'Enable-ComputerRestore', 'Disable-ComputerRestore', 'Set-ExecutionPolicy', 'Clear-RecycleBin', 'Optimize-Volume',
    'Enable-BitLocker', 'Disable-BitLocker', 'New-LocalUser', 'Remove-LocalUser', 'Disable-LocalUser', 'Enable-LocalUser', 'Set-LocalUser',
    'Set-ItemProperty', 'New-ItemProperty', 'Remove-ItemProperty',
    'Set-RegData', 'Remove-RegData', 'Set-SvcStart', 'Set-HostsBlock', 'Disable-KillSwitchNow', 'Invoke-Undo', 'Invoke-RestorePoint'
)
$script:LiveBlocked = New-Object System.Collections.ArrayList

function Add-LiveBlocked([string]$Name, [string]$ArgText) {
    $t = ($Name + ' ' + $ArgText).Trim()
    if ($t.Length -gt 160) { $t = $t.Substring(0, 160) + '...' }
    [void]$script:LiveBlocked.Add($t)
}

# Onizleme bayragi acik mi (bekci altindaki Invoke-Op / Invoke-Plan golgeleri bunu sorar; $script:Preview burada dogru betik kapsamindan okunur)
function Test-LivePreviewOn { return ($script:Preview -eq $true) }

# Bir okuma isini bekci altinda calistirir; Invoke-LiveJob gibi @{ Out; Err } doner. Engellenen denemeler $script:LiveBlocked icinde kalir.
# Invoke-Op ve Invoke-Plan yalnizca ONIZLEME acikken asil islevi calistirir (onizleme sistemde hicbir sey degistirmez); degilse engellenir.
function Invoke-LiveGuarded([string]$Fn, $Arg) {
    $script:LiveBlocked.Clear()
    $origOp = $null; $origPlan = $null
    try { if (Test-Path -LiteralPath 'function:Invoke-Op') { $origOp = (Get-Item -LiteralPath 'function:Invoke-Op').ScriptBlock } } catch { }
    try { if (Test-Path -LiteralPath 'function:Invoke-Plan') { $origPlan = (Get-Item -LiteralPath 'function:Invoke-Plan').ScriptBlock } } catch { }
    $defs = New-Object System.Text.StringBuilder
    foreach ($n in $script:LiveGuardNames) {
        if ($n -cnotmatch '^[A-Za-z0-9-]+$') { continue }
        [void]$defs.Append('function ' + $n + ' { Add-LiveBlocked ''' + $n + ''' (($args | ForEach-Object { [string]$_ }) -join '' '') }' + "`n")
    }
    [void]$defs.Append('function Invoke-Op($Op) { if ((Test-LivePreviewOn) -and $null -ne $OrigOp) { & $OrigOp $Op } else { Add-LiveBlocked ''Invoke-Op'' ([string]$Op.T + '' '' + [string]$Op.Name + '' '' + [string]$Op.Path) } }' + "`n")
    [void]$defs.Append(('function Invoke-Plan($Steps, [bool]$RestorePoint) { if ((Test-LivePreviewOn) -and $null -ne $OrigPlan) { & $OrigPlan $Steps $RestorePoint } else { Add-LiveBlocked ''Invoke-Plan'' ([string]@($Steps).Count + '' ad' + [char]0x0131 + 'm'') } }') + "`n")
    $res = & {
        param($JobFn, $JobArg, $DefText, $OrigOp, $OrigPlan)
        . ([scriptblock]::Create($DefText))
        Invoke-LiveJob $JobFn $JobArg
    } $Fn $Arg $defs.ToString() $origOp $origPlan
    if ($res -is [System.Array]) {
        $h = @($res | Where-Object { $_ -is [hashtable] })
        if ($h.Count -gt 0) { $res = $h[$h.Count - 1] }
    }
    if ($res -isnot [hashtable]) { $res = @{ Out = $null; Err = ('bek' + [char]0x00E7 + 'i sonucu al' + [char]0x0131 + 'namad' + [char]0x0131 + '') } }
    return $res
}

# ---------------- sistemden bagimsiz okumalar ----------------
function Get-LiveRegRaw([string]$Path, [string]$Name) {
    $r = @{ KeyExists = $false; Exists = $false; Kind = ''; Data = $null; Err = '' }
    $rp = Resolve-RegPath $Path
    $i = $rp.IndexOf('\')
    $root = $rp; $sub = ''
    if ($i -ge 0) { $root = $rp.Substring(0, $i); $sub = $rp.Substring($i + 1) }
    $hive = $null
    switch ($root.ToUpperInvariant()) {
        'HKLM' { $hive = [Microsoft.Win32.RegistryHive]::LocalMachine }
        'HKCU' { $hive = [Microsoft.Win32.RegistryHive]::CurrentUser }
        'HKU'  { $hive = [Microsoft.Win32.RegistryHive]::Users }
        'HKCR' { $hive = [Microsoft.Win32.RegistryHive]::ClassesRoot }
    }
    if ($null -eq $hive) { $r.Err = ('bilinmeyen k' + [char]0x00F6 + 'k: ') + $root; return $r }
    $base = $null
    try {
        $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey($hive, [Microsoft.Win32.RegistryView]::Registry64)
        $key = $base.OpenSubKey($sub, $false)
        if ($null -ne $key) {
            $r.KeyExists = $true
            if (@($key.GetValueNames()) -contains $Name) {
                $r.Exists = $true
                $r.Kind = $key.GetValueKind($Name).ToString()
                $r.Data = $key.GetValue($Name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            }
            $key.Close()
        }
    } catch { $r.Err = $_.Exception.Message } finally { if ($null -ne $base) { $base.Close() } }
    return $r
}

function ConvertTo-LiveUInt([object]$V) {
    $l = [int64]$V
    return [uint32]($l -band [int64]4294967295)
}

function Test-LiveDataEqual([string]$Kind, $X, $Y) {
    switch ($Kind) {
        'Binary' {
            $a = [byte[]]@($X); $b = [byte[]]@($Y)
            if ($a.Length -ne $b.Length) { return $false }
            for ($i = 0; $i -lt $a.Length; $i++) { if ($a[$i] -ne $b[$i]) { return $false } }
            return $true
        }
        'MultiString' { return ((@($X) -join [string][char]0) -ceq (@($Y) -join [string][char]0)) }
        'DWord'       { return ((ConvertTo-LiveUInt $X) -eq (ConvertTo-LiveUInt $Y)) }
        'QWord'       { return ([int64]$X -eq [int64]$Y) }
        default       { return ([string]$X -ceq [string]$Y) }
    }
}

function Test-LiveRawEqual($A, $B) {
    if ([bool]$A.Exists -ne [bool]$B.Exists) { return $false }
    if (-not [bool]$A.Exists) { return $true }
    if ([string]$A.Kind -ne [string]$B.Kind) { return $false }
    return (Test-LiveDataEqual ([string]$A.Kind) $A.Data $B.Data)
}

function Format-LiveRaw($R) {
    if ($null -eq $R -or -not [bool]$R.Exists) { return '(yok)' }
    $v = $R.Data
    if ($R.Kind -eq 'Binary') { $b = [byte[]]@($v); $s = (($b | Select-Object -First 12 | ForEach-Object { '{0:x2}' -f $_ }) -join ' '); if ($b.Length -gt 12) { $s += (' ' + [char]0x2026 + '') }; return ('bin[' + $b.Length + ']=' + $s) }
    if ($R.Kind -eq 'MultiString') { return ('[' + (@($v) -join '|') + ']') }
    return ([string]$R.Kind + ':' + [string]$v)
}

function Get-LiveSvcSnap([string]$Name) {
    $s = @{ K = 'Svc'; Name = $Name; Exists = $false; Start = -1; Delayed = $false; Status = '' }
    try {
        $tpl = $Name
        try { $tpl = Get-SvcTemplateName $Name } catch { }
        $key = 'HKLM\SYSTEM\CurrentControlSet\Services\' + $tpl
        $r = Get-LiveRegRaw $key 'Start'
        if ($r.Exists) { $s.Exists = $true; $s.Start = [int]$r.Data }
        $d = Get-LiveRegRaw $key 'DelayedAutostart'
        if ($d.Exists) { $s.Delayed = ([int]$d.Data -eq 1) }
        $sc = $null
        try { $sc = New-Object System.ServiceProcess.ServiceController($Name) } catch { }
        if ($null -ne $sc) {
            $st = $sc.Status.ToString()
            if ($st -eq 'StartPending' -or $st -eq 'ContinuePending') { $st = 'Running' }
            elseif ($st -eq 'StopPending' -or $st -eq 'PausePending') { $st = 'Stopped' }
            $s.Status = $st
        }
    } catch { }
    return $s
}

function Get-LiveTaskSnap([string]$Path, [string]$Name) {
    $s = @{ K = 'Task'; Path = $Path; Name = $Name; Exists = $false; Enabled = $false }
    try {
        $t = Get-ScheduledTask -TaskPath $Path -TaskName $Name -ErrorAction Stop
        if ($null -ne $t) { $s.Exists = $true; $s.Enabled = [bool]$t.Settings.Enabled }
    } catch { }
    return $s
}

function Get-LiveMpSnap([string]$Name) {
    $s = @{ K = 'Mp'; Name = $Name; Ok = $false; Value = '' }
    try {
        $v = (Get-MpPreference -ErrorAction Stop).$Name
        $s.Ok = $true
        $s.Value = (@($v) -join ',')
        if ($v -is [bool]) { $s.Value = ([string]$v).ToLowerInvariant() }
    } catch { }
    return $s
}

function Get-LiveFwSnap([string]$Group) {
    $s = @{ K = 'Fw'; Group = $Group; Rules = @{} }
    try {
        foreach ($r in @(Get-NetFirewallRule -Group $Group -ErrorAction Stop)) { $s.Rules[[string]$r.Name] = ([string]$r.Enabled -eq 'True') }
    } catch { }
    return $s
}

function Get-LiveEvtSnap([string]$Name) {
    $s = @{ K = 'EvtLog'; Name = $Name; Bytes = -1 }
    try {
        $cfg = New-Object System.Diagnostics.Eventing.Reader.EventLogConfiguration($Name)
        $s.Bytes = [int64]$cfg.MaximumSizeInBytes
        $cfg.Dispose()
    } catch { }
    return $s
}

function Get-LiveFeatSnap([string]$Name) {
    $s = @{ K = 'Feature'; Name = $Name; State = '' }
    try { $f = Get-WindowsOptionalFeature -Online -FeatureName $Name -ErrorAction Stop; if ($null -ne $f) { $s.State = [string]$f.State } }
    catch {
        # yonetici degil: Win32_OptionalFeature (1 acik, 2 kapali, 3 kaynak dosyalari kaldirilmis)
        try {
            $w = @(Get-CimInstance -ClassName Win32_OptionalFeature -Filter ("Name='" + ($Name -creplace "[^A-Za-z0-9\.\-_]", '') + "'") -ErrorAction Stop | Where-Object { $null -ne $_ })
            if ($w.Count -gt 0) {
                switch ([int]$w[0].InstallState) { 1 { $s.State = 'Enabled' } 2 { $s.State = 'Disabled' } 3 { $s.State = 'DisabledWithPayloadRemoved' } }
            }
        } catch { }
    }
    # yeniden baslatma bekleyen degisiklik etkin durum sayilir (uygulamanin olcumuyle ayni)
    if ($s.State -eq 'EnablePending') { $s.State = 'Enabled' } elseif ($s.State -eq 'DisablePending') { $s.State = 'Disabled' }
    return $s
}

function Get-LiveFuncSnap([string]$Name) {
    $s = @{ K = 'Func'; Name = $Name; Data = '' }
    switch ($Name) {
        'HibernateOff' {
            $r = Get-LiveRegRaw 'HKLM\SYSTEM\CurrentControlSet\Control\Power' 'HibernateEnabled'
            $s.Data = ('hib=' + $(if ($r.Exists) { [string]$r.Data } else { '?' }))
        }
        'GuestOff' {
            $u = $null
            try { $u = Get-LocalUser -ErrorAction Stop | Where-Object { $_.SID.Value -like '*-501' } | Select-Object -First 1 } catch { }
            $s.Data = $(if ($null -ne $u) { 'guest=' + [string]$u.Enabled + ';name=' + [string]$u.Name } else { 'guest=yok' })
        }
        'NetBiosOff' {
            $base = 'HKLM\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces'
            $parts = New-Object System.Collections.ArrayList
            foreach ($n in @((Get-RegSubKeyNames $base) | Where-Object { $_ -like 'Tcpip_*' } | Sort-Object)) {
                $r = Get-LiveRegRaw ($base + '\' + $n) 'NetbiosOptions'
                [void]$parts.Add($n + '=' + $(if ($r.Exists) { [string]$r.Data } else { '-' }))
            }
            $s.Data = ($parts -join ';')
        }
        'LockoutPolicy' {
            $v = $null
            try { $v = Get-SecPolValues } catch { }
            if ($null -ne $v) { $s.Data = ('thr=' + [string]$v['LockoutBadCount'] + ';dur=' + [string]$v['LockoutDuration'] + ';win=' + [string]$v['ResetLockoutCount']) }
        }
        'AuditLogon' {
            $txt = ''
            try { $txt = ((& auditpol.exe /get /category:* /r 2>&1) | Out-String) } catch { }
            $s.Data = $txt
        }
        { $_ -eq 'HostsBlock' -or $_ -eq 'HostsUnblock' } {
            $txt = ''
            try { $txt = [System.IO.File]::ReadAllText((Join-Path $env:WINDIR 'System32\drivers\etc\hosts')) } catch { $txt = '' }
            if ($txt.Length -gt 200000) { $txt = 'sha:' + (Get-ShortHash $txt) }
            $s.Name = 'Hosts'
            $s.Data = $txt
        }
        'PowerMode' {
            $ac = ''; $dc = ''; $cur = ''
            try { if (Initialize-SysNative) { $ac = [string][WH.Sys]::GetUserMode($false); $dc = [string][WH.Sys]::GetUserMode($true); $cur = [string][WH.Sys]::GetMode() } } catch { }
            $s.Data = ('ac=' + $ac + ';dc=' + $dc + ';cur=' + $cur)
        }
        'PowerPlan' {
            $act = ''; $all = ''
            try { $o = (& powercfg.exe /getactivescheme 2>&1 | Out-String); if ($o -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') { $act = $Matches[1].ToLowerInvariant() } } catch { }
            try { $o2 = (& powercfg.exe /list 2>&1 | Out-String); $all = ((([regex]::Matches($o2, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') | ForEach-Object { $_.Value.ToLowerInvariant() }) | Sort-Object) -join ',') } catch { }
            # Modern Bekleme'de ayar guc kipiyle uygulanir: yururlukteki kip de karsilastirilir
            $kip = ''
            try { if (Initialize-SysNative) { $kip = [string][WH.Sys]::GetMode() } } catch { }
            $s.Data = ('aktif=' + $act + ';kip=' + $kip + ';planlar=' + $all)
        }
    }
    return $s
}

function Get-LiveSnap($C) {
    $items = New-Object System.Collections.ArrayList
    foreach ($op in @($C.Ops)) {
        $it = $null
        try {
            switch ([string]$op.T) {
                'Reg'     { $it = @{ K = 'Reg'; Path = (Resolve-RegPath ([string]$op.Path)); Name = [string]$op.Name; Raw = (Get-LiveRegRaw ([string]$op.Path) ([string]$op.Name)) } }
                'Svc'     { $it = Get-LiveSvcSnap ([string]$op.Name) }
                'Task'    { $it = Get-LiveTaskSnap ([string]$op.Path) ([string]$op.Name) }
                'Mp'      { $it = Get-LiveMpSnap ([string]$op.Name) }
                'Fw'      { $it = Get-LiveFwSnap ([string]$op.Group) }
                'EvtLog'  { $it = Get-LiveEvtSnap ([string]$op.Name) }
                'Feature' { $it = Get-LiveFeatSnap ([string]$op.Name) }
                'Cap'     { $it = @{ K = 'Cap'; Name = [string]$op.Match; Data = (Get-LiveCapState ([string]$op.Match)) } }
                'Func'    { $it = Get-LiveFuncSnap ([string]$op.Name) }
            }
        } catch { $it = @{ K = 'Hata'; Name = [string]$op.T; Err = $_.Exception.Message } }
        if ($null -eq $it) { $it = @{ K = 'Yok'; Name = [string]$op.T } }
        [void]$items.Add($it)
    }
    return , $items.ToArray()
}

function Compare-LiveItem($X, $Y) {
    switch ([string]$X.K) {
        'Reg' {
            if (-not (Test-LiveRawEqual $X.Raw $Y.Raw)) { return ($X.Path + '\' + $X.Name + ': ' + (Format-LiveRaw $X.Raw) + ' -> ' + (Format-LiveRaw $Y.Raw)) }
        }
        'Svc' {
            if ([int]$X.Start -ne [int]$Y.Start -or [bool]$X.Delayed -ne [bool]$Y.Delayed -or [string]$X.Status -ne [string]$Y.Status) {
                return ('hizmet ' + $X.Name + (': ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' ') + $X.Start + '/' + $X.Delayed + '/' + $X.Status + ' -> ' + $Y.Start + '/' + $Y.Delayed + '/' + $Y.Status)
            }
        }
        'Task' { if ([bool]$X.Exists -ne [bool]$Y.Exists -or [bool]$X.Enabled -ne [bool]$Y.Enabled) { return (('g' + [char]0x00F6 + 'rev ') + $X.Path + $X.Name + ': ' + $X.Enabled + ' -> ' + $Y.Enabled) } }
        'Mp'   { if ([string]$X.Value -ne [string]$Y.Value) { return ('Defender ' + $X.Name + ': ' + $X.Value + ' -> ' + $Y.Value) } }
        'Fw' {
            foreach ($k in @($X.Rules.Keys)) { if ($Y.Rules.ContainsKey($k) -and [bool]$X.Rules[$k] -ne [bool]$Y.Rules[$k]) { return (('g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' kural' + [char]0x0131 + ' ') + $k + ': ' + $X.Rules[$k] + ' -> ' + $Y.Rules[$k]) } }
        }
        'EvtLog'  { if ([int64]$X.Bytes -ne [int64]$Y.Bytes) { return (('olay g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' ') + $X.Name + ': ' + $X.Bytes + ' -> ' + $Y.Bytes) } }
        'Feature' { if ([string]$X.State -ne [string]$Y.State) { return (('' + [char]0x00F6 + 'zellik ') + $X.Name + ': ' + $X.State + ' -> ' + $Y.State) } }
        'Cap' { if ([string]$X.Data -ne 'okunamadi' -and [string]$Y.Data -ne 'okunamadi' -and [string]$X.Data -ne [string]$Y.Data) { return (('bile' + [char]0x015F + 'en ') + $X.Name + ': ' + $X.Data + ' -> ' + $Y.Data) } }
        'Func' {
            if ([string]$X.Name -eq 'PowerMode') {
                # geri alma bos kullanici kipini Dengeli olarak yazar; karsilastirma yalnizca yururlukteki kipe bakar
                $cx = ''; $cy = ''
                if ([string]$X.Data -match 'cur=(.*)$') { $cx = $Matches[1] }
                if ([string]$Y.Data -match 'cur=(.*)$') { $cy = $Matches[1] }
                if ($cx -ne $cy) { return (('g' + [char]0x00FC + '' + [char]0x00E7 + ' kipi: ') + $cx + ' -> ' + $cy) }
            } elseif ([string]$X.Data -ne [string]$Y.Data) { return (('i' + [char]0x015F + 'lev ') + $X.Name + ': ' + (Get-LiveShort ([string]$X.Data)) + ' -> ' + (Get-LiveShort ([string]$Y.Data))) }
        }
    }
    return ''
}

function Get-LiveShort([string]$S, [int]$Max = 90) {
    $t = ($S -replace '\s+', ' ').Trim()
    if ($t.Length -gt $Max) { return ($t.Substring(0, $Max) + ('' + [char]0x2026 + '')) }
    return $t
}

function Compare-LiveSnap($A, $B) {
    $diff = New-Object System.Collections.ArrayList
    $a = @($A); $b = @($B)
    for ($i = 0; $i -lt $a.Count -and $i -lt $b.Count; $i++) {
        $d = Compare-LiveItem $a[$i] $b[$i]
        if ($d -ne '') { [void]$diff.Add($d) }
    }
    return , $diff.ToArray()
}

# ---------------- diske yazilan eski durum (surec oluse bile geri yuklenir) ----------------
# Ikili (REG_BINARY) veri kurtarma dosyasinda onaltilik metin olarak tutulur ('' = bos dizi)
function ConvertTo-LiveHex($Data) {
    if ($null -eq $Data) { return '' }
    $sb = New-Object System.Text.StringBuilder
    foreach ($x in [byte[]]@($Data)) { [void]$sb.Append($x.ToString('x2', [System.Globalization.CultureInfo]::InvariantCulture)) }
    return $sb.ToString()
}

function ConvertFrom-LiveHex([string]$Text) {
    if ($Text -cnotmatch '^(?:[0-9a-fA-F]{2})*$') { throw ('kurtarma dosyas' + [char]0x0131 + 'ndaki ikili veri okunamad' + [char]0x0131 + ' (onalt' + [char]0x0131 + 'l' + [char]0x0131 + 'k metin de' + [char]0x011F + 'il)') }
    $n = [int]($Text.Length / 2)
    $out = New-Object byte[] $n
    for ($i = 0; $i -lt $n; $i++) { $out[$i] = [Convert]::ToByte($Text.Substring(2 * $i, 2), 16) }
    return , $out
}

function ConvertTo-LiveSerial($Snap) {
    $out = New-Object System.Collections.ArrayList
    foreach ($it in @($Snap)) {
        if ([string]$it.K -eq 'Reg') {
            $r = $it.Raw
            $data = $null
            if ([bool]$r.Exists) {
                switch ([string]$r.Kind) {
                    'Binary'      { $data = ConvertTo-LiveHex $r.Data }
                    'MultiString' { $data = @($r.Data) }
                    'QWord'       { $data = [string][int64]$r.Data }
                    'DWord'       { $data = [string][int64]$r.Data }
                    default       { $data = [string]$r.Data }
                }
            }
            [void]$out.Add(@{ K = 'Reg'; Path = [string]$it.Path; Name = [string]$it.Name; KeyExists = [bool]$r.KeyExists; Exists = [bool]$r.Exists; Kind = [string]$r.Kind; Data = $data })
        } elseif ([string]$it.K -eq 'Fw') {
            $rules = @()
            foreach ($k in @($it.Rules.Keys)) { $rules += @{ Name = [string]$k; On = [bool]$it.Rules[$k] } }
            [void]$out.Add(@{ K = 'Fw'; Group = [string]$it.Group; Rules = $rules })
        } else {
            $h = @{}
            foreach ($k in @($it.Keys)) { $h[[string]$k] = $it[$k] }
            [void]$out.Add($h)
        }
    }
    return , $out.ToArray()
}

function Save-LiveInflight([string]$Id, $Snap) {
    try {
        $ser = ConvertTo-LiveSerial $Snap
        $o = @{ Id = $Id; Time = (Get-Date).ToString('s'); Items = $ser }
        $json = ConvertTo-Json -InputObject $o -Depth 8
        [System.IO.File]::WriteAllText((Join-Path (Get-LiveDir) 'ozellik-yarim.json'), $json, (New-Object System.Text.UTF8Encoding($false)))
    } catch { Add-LiveRow 'kurtarma' $Id 'UYARI' (('eski durum diske yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
}

function Clear-LiveInflight {
    try { $f = Join-Path (Get-LiveDir) 'ozellik-yarim.json'; if (Test-Path -LiteralPath $f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue } } catch { }
}

# Bir ogenin eski halini sisteme geri yazar (bagimsiz geri yukleme: motorun geri alma yoluna guvenmez)
function Restore-LiveItem($It) {
    $k = [string]$It.K
    if ($k -eq 'Reg') {
        $path = [string]$It.Path; $name = [string]$It.Name
        $exists = [bool]$It.Exists
        if ($exists) {
            $kind = [string]$It.Kind
            $val = $It.Data
            switch ($kind) {
                'Binary'      { $val = ConvertFrom-LiveHex ([string]$val) }
                'MultiString' { $val = [string[]]@($val) }
                'QWord'       { $val = [int64]$val }
                'DWord'       { $val = [int64]$val }
            }
            Set-RegData $path $name $kind $val
        } else {
            Remove-RegData $path $name (-not [bool]$It.KeyExists)
        }
        return
    }
    if ($k -eq 'Svc') {
        if ([int]$It.Start -gt 1) { Set-SvcStart ([string]$It.Name) ([int]$It.Start) ([bool]$It.Delayed) }
        if ([string]$It.Status -eq 'Running') {
            $sc = $null; try { $sc = New-Object System.ServiceProcess.ServiceController([string]$It.Name) } catch { }
            if ($null -ne $sc -and $sc.Status.ToString() -ne 'Running' -and [int]$It.Start -ne 4) { Start-Service -Name ([string]$It.Name) -ErrorAction SilentlyContinue }
        }
        return
    }
    if ($k -eq 'Task') {
        if (-not [bool]$It.Exists) { return }
        if ([bool]$It.Enabled) { Enable-ScheduledTask -TaskPath ([string]$It.Path) -TaskName ([string]$It.Name) -ErrorAction SilentlyContinue | Out-Null }
        else { Disable-ScheduledTask -TaskPath ([string]$It.Path) -TaskName ([string]$It.Name) -ErrorAction SilentlyContinue | Out-Null }
        return
    }
    if ($k -eq 'Mp') {
        if (-not [bool]$It.Ok) { return }
        $v = [string]$It.Value
        $splat = @{}
        if ($v -eq 'true') { $splat[[string]$It.Name] = $true }
        elseif ($v -eq 'false') { $splat[[string]$It.Name] = $false }
        elseif ($v -match '^-?\d+$') { $splat[[string]$It.Name] = [int]$v }
        else { $splat[[string]$It.Name] = $v }
        Set-MpPreference @splat -ErrorAction SilentlyContinue
        return
    }
    if ($k -eq 'Fw') {
        foreach ($r in @($It.Rules)) { Set-NetFirewallRule -Name ([string]$r.Name) -Enabled $(if ([bool]$r.On) { 'True' } else { 'False' }) -ErrorAction SilentlyContinue }
        return
    }
    if ($k -eq 'EvtLog') {
        if ([int64]$It.Bytes -gt 0) { & wevtutil.exe sl ([string]$It.Name) ('/ms:' + [int64]$It.Bytes) | Out-Null }
        return
    }
    if ($k -eq 'Func') { Restore-LiveFunc $It; return }
    if ($k -eq 'Cap') {
        if ([string]$It.Data -eq 'kurulu' -and (Get-LiveCapState ([string]$It.Name)) -ne 'kurulu') { [void](Set-WinCapabilityState ([string]$It.Name) $true) }
        return
    }
    if ($k -eq 'Feature') {
        $want = [string]$It.State
        if ($want -eq '') { return }
        $cur = [string](Get-LiveFeatSnap ([string]$It.Name)).State
        $wantOn = ($want -eq 'Enabled' -or $want -eq 'EnablePending')
        $curOn = ($cur -eq 'Enabled' -or $cur -eq 'EnablePending')
        if ($cur -ne '' -and $wantOn -ne $curOn) {
            # Windows yeniden baslatma beklerken kapatilmis ozelligi acmak cogu zaman ya hemen reddedilir ya da DISM asili kalir
            # (cihazda 15 dakika). Ozellik kurtarma listesine girer, yeniden baslatmadan sonraki tam denetimin basinda acilir.
            if ($wantOn) {
                $rn = [string](Get-CbsRebootPending)
                if ($rn -eq '' -and $script:DismNeedsReboot) { $rn = 'DISM' }
                if ($rn -ne '') { throw (('Windows bir bile' + [char]0x015F + 'en de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmay' + [char]0x0131 + ' bekliyor (') + $rn + '); ' + [string]$It.Name + (' yeniden ba' + [char]0x015F + 'latmadan sonraki tam denetimin ba' + [char]0x015F + '' + [char]0x0131 + 'nda yeniden a' + [char]0x00E7 + '' + [char]0x0131 + 'lacak')) }
            }
            [void](Set-WinFeatureState ([string]$It.Name) $wantOn)
        }
        return
    }
    if ($k -eq 'Appx') {
        if (-not (Restore-AppxItem @{ Name = [string]$It.Name; Locs = @($It.Locs) })) { throw (('uygulama paket klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nden geri kaydedilemedi: ') + [string]$It.Name) }
        return
    }
}

function Restore-LiveFunc($It) {
    $d = [string]$It.Data
    switch ([string]$It.Name) {
        'Hosts' {
            if ($d -ne '' -and $d -notlike 'sha:*') { [System.IO.File]::WriteAllText((Join-Path $env:WINDIR 'System32\drivers\etc\hosts'), $d, (New-Object System.Text.UTF8Encoding($false))) }
        }
        'HibernateOff' {
            if ($d -eq 'hib=1') { & powercfg.exe /hibernate on | Out-Null } elseif ($d -eq 'hib=0') { & powercfg.exe /hibernate off | Out-Null }
        }
        'GuestOff' {
            if ($d -match '^guest=True;name=(.+)$') { Enable-LocalUser -Name $Matches[1] -ErrorAction SilentlyContinue }
        }
        'NetBiosOff' {
            $base = 'HKLM\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces'
            foreach ($p in @($d -split ';')) {
                if ($p -match '^(Tcpip_[^=]+)=(\d+)$') { Set-RegData ($base + '\' + $Matches[1]) 'NetbiosOptions' 'DWord' ([int]$Matches[2]) }
            }
        }
        'LockoutPolicy' {
            if ($d -match 'thr=(\d+);dur=(\d+);win=(\d+)') {
                if ([int]$Matches[1] -eq 0) { & net.exe accounts /lockoutthreshold:0 | Out-Null }
                else { & net.exe accounts /lockoutthreshold:$($Matches[1]) /lockoutduration:$($Matches[2]) /lockoutwindow:$($Matches[3]) | Out-Null }
            }
        }
        'PowerMode' {
            if ($d -match 'ac=([^;]*);dc=([^;]*);cur=(.*)$') {
                $pa = $Matches[1]; $pd = $Matches[2]; $pc = $Matches[3]
                if ($pa -eq '') { $pa = $pc }
                if ($pd -eq '') { $pd = $pa }
                if ($pa -ne '' -and (Initialize-SysNative)) { [void][WH.Sys]::SetMode($pa, $pd) }
            }
        }
        'PowerPlan' {
            $kip = ''
            if ($d -match ';kip=([^;]*);') { $kip = $Matches[1] }
            if ($kip -ne '') { try { if (Initialize-SysNative) { [void][WH.Sys]::SetMode($kip, $kip) } } catch { } }
            if ($d -match 'aktif=([0-9a-f-]{36});(?:kip=[^;]*;)?planlar=(.*)$') {
                $act = $Matches[1]; $keep = @($Matches[2] -split ',' | Where-Object { $_ -ne '' })
                & powercfg.exe /setactive $act | Out-Null
                $now = (& powercfg.exe /list 2>&1 | Out-String)
                foreach ($m in [regex]::Matches($now, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')) {
                    $g = $m.Value.ToLowerInvariant()
                    if ($keep -notcontains $g -and $g -ne $act) { & powercfg.exe /delete $g | Out-Null }
                }
            }
        }
    }
}

function Restore-LiveSnap($Serial) {
    foreach ($it in @($Serial)) { try { Restore-LiveItem $it } catch { Add-LiveRow 'kurtarma' ([string]$it.K) 'HATA' (('geri yaz' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) } }
}

# Onceki (oluse ya da zaman asimina ugrayan) bir turdan kalan degisiklik varsa geri yukler
function Restore-LiveInflight {
    $f = Join-Path (Get-LiveDir) 'ozellik-yarim.json'
    if (-not (Test-Path -LiteralPath $f)) { return }
    try {
        $o = ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($f))
        if ((Get-LiveMode) -ne 'tam') {
            Add-LiveRow 'kurtarma' ([string]$o.Id) 'UYARI' ('' + [char]0x00F6 + 'nceki turdan yar' + [char]0x0131 + 'm kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik var; "tam" kipte (y' + [char]0x00F6 + 'netici) geri y' + [char]0x00FC + 'klenecek')
            return
        }
        Add-LiveRow 'kurtarma' ([string]$o.Id) 'BILGI' (('' + [char]0x00F6 + 'nceki turdan yar' + [char]0x0131 + 'm kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik geri y' + [char]0x00FC + 'kleniyor (') + [string]$o.Time + ')')
        $items = @($o.Items)
        # Reg ogeleri ConvertFrom-Json ile PSCustomObject gelir; Restore-LiveItem alan adlariyla calisir
        $errs = New-Object System.Collections.ArrayList
        foreach ($it in $items) {
            if (Test-LiveDismItem $it) {
                if (Test-LiveItemCurrent $it) { continue }
                $blk = Get-LiveDismBlock
                if ($blk -ne '') { [void]$errs.Add([string]$it.Name + ': ' + $blk); [void]$script:LiveStopKinds.Add([string]$it.K); continue }
                if ($script:LiveRestoreFailed.Contains([string]$it.Name)) { [void]$errs.Add([string]$it.Name + (': bu denetimde zaten geri y' + [char]0x00FC + 'klenemedi')); continue }
            }
            Add-LiveCompTouched ([string]$it.K) ([string]$it.Name)
            try { Restore-LiveItem $it }
            catch {
                [void]$errs.Add($_.Exception.Message)
                if (Test-LiveDismItem $it) { [void]$script:LiveRestoreFailed.Add([string]$it.Name); [void]$script:LiveStopKinds.Add([string]$it.K) }
            }
        }
        Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
        if ($errs.Count -gt 0) {
            # kaybolmasin: kalici kurtarma listesine tasinir, sonraki tam denetimde yeniden denenir
            Add-LiveUnrestored ([string]$o.Id) $items ($errs -join ' | ')
            Add-LiveRow 'kurtarma' ([string]$o.Id) 'HATA' (('yar' + [char]0x0131 + 'm kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik geri y' + [char]0x00FC + 'klenemedi (kurtarma listesine al' + [char]0x0131 + 'nd' + [char]0x0131 + '): ') + (Get-LiveShort ($errs -join ' | ') 200))
        } else { Add-LiveRow 'kurtarma' ([string]$o.Id) 'OK' ('yar' + [char]0x0131 + 'm kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik geri y' + [char]0x00FC + 'klendi') }
    } catch { Add-LiveRow 'kurtarma' 'yarim' 'HATA' (('yar' + [char]0x0131 + 'm kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik geri y' + [char]0x00FC + 'klenemedi: ') + $_.Exception.Message) }
}

# ---------------- beklenen sonuc: ayarin tanimindaki degerler uygulandi mi ----------------
function Get-LiveExpectMismatch($C, $Snap, $Lines) {
    $bad = New-Object System.Collections.ArrayList
    $ops = @($C.Ops); $sn = @($Snap)
    $skipText = (@($Lines) | Where-Object { $_ -match '\sSKIP\s' }) -join "`n"
    for ($i = 0; $i -lt $ops.Count -and $i -lt $sn.Count; $i++) {
        $op = $ops[$i]; $s = $sn[$i]
        switch ([string]$op.T) {
            'Reg' {
                $label = Get-RegOpLabel $op
                if (Test-RegDenied $label) { continue }
                if ($op.Del -eq $true) {
                    if ([bool]$s.Raw.Exists) { [void]$bad.Add($label + ': silinmedi (' + (Format-LiveRaw $s.Raw) + ')') }
                    continue
                }
                $kind = [string]$op.Kind
                if ([string]::IsNullOrEmpty($kind)) { $kind = 'DWord' }
                if (-not [bool]$s.Raw.Exists) { [void]$bad.Add($label + (': de' + [char]0x011F + 'er yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')); continue }
                if ([string]$s.Raw.Kind -ne $kind) { [void]$bad.Add($label + (': t' + [char]0x00FC + 'r ') + $s.Raw.Kind + ' (beklenen ' + $kind + ')'); continue }
                $want = $op.Value
                $ok = $false
                try { $ok = Test-LiveDataEqual $kind $want $s.Raw.Data } catch { $ok = $false }
                if (-not $ok) { [void]$bad.Add($label + ': ' + (Format-LiveRaw $s.Raw) + ' (beklenen ' + [string]$want + ')') }
            }
            'Svc' {
                if (-not [bool]$s.Exists) { continue }
                if ($skipText -match [regex]::Escape([string]$op.Name)) { continue }
                $target = 3
                try { $target = [int]$script:StartMap[[string]$op.Start] } catch { }
                if ([int]$s.Start -ne $target) { [void]$bad.Add('hizmet ' + $op.Name + (': ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' ') + $s.Start + ' (beklenen ' + $target + ')') }
            }
            'Task' {
                if (-not [bool]$s.Exists) { continue }
                $wantEnable = ([string]$op.Action -eq 'Enable')
                if ([bool]$s.Enabled -ne $wantEnable) { [void]$bad.Add(('g' + [char]0x00F6 + 'rev ') + $op.Path + $op.Name + ': ' + $(if ($s.Enabled) { ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k') } else { ('kapal' + [char]0x0131 + '') }) + ' (beklenen ' + $(if ($wantEnable) { ('a' + [char]0x00E7 + '' + [char]0x0131 + 'k') } else { ('kapal' + [char]0x0131 + '') }) + ')') }
            }
        }
    }
    return , $bad.ToArray()
}

# ---------------- hangi ayar nasil denenir ----------------
# Donus: hkcu | hklm | hizmet | ozel | onizleme | uygunsuz
# Canli uygulanip gunlukle geri alinabilen Func islemleri
$script:LiveFuncLive = @('PowerPlan', 'HibernateOff', 'GuestOff', 'NetBiosOff', 'AuditLogon', 'LockoutPolicy', 'HostsBlock', 'HostsUnblock')
# Tek yonlu Func islemleri: tam kipte canli uygulanir ama geri alinamaz (silme/temizlik/onbellek); dogrulama ikinci onizlemeyle yapilir
$script:LiveOneWay = @('OptimizeDrive', 'FlushDns', 'CleanTemp', 'CleanThumbs', 'CleanPrefetch', 'CleanWer', 'CleanLogs', 'CleanDumps', 'CleanSetupLogs', 'CleanDelivery',
    'CleanUpdateCache', 'CleanShader', 'CleanAppCaches', 'CleanBrowsers', 'CleanRecent', 'CleanMgr', 'DismCleanup', 'EmptyRecycleBin')
# Tam kipte bile yalnizca onizlenenler: bilgisayarin kurtarilabilirligini azaltan ya da kullanicinin gordugu veriyi geri
# getirilemez bicimde silenler. Onbellek ve gecici dosya temizligi (kendiliginden yeniden olusur) canli denenir.
$script:LiveKeepPreview = @('CleanRestorePoints', 'CleanMgr', 'CleanRecent')
$script:LiveKeepPreviewWhy = @{
    'CleanRestorePoints' = ('eski geri y' + [char]0x00FC + 'kleme noktalar' + [char]0x0131 + 'n' + [char]0x0131 + ' siler; silinen noktaya d' + [char]0x00F6 + 'n' + [char]0x00FC + 'lemez')
    'CleanMgr'           = ('' + [char]0x00F6 + 'nceki Windows kurulumunu (Windows.old) ve g' + [char]0x00FC + 'ncelleme yedeklerini siler; ' + [char]0x00F6 + 'nceki s' + [char]0x00FC + 'r' + [char]0x00FC + 'me d' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + ' kalkar')
    'CleanRecent'        = ('son kullan' + [char]0x0131 + 'lan dosyalar listesini siler; kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'n ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'i geri gelmez')
}

function Get-LiveKeepPreviewWhy($C) {
    $w = New-Object System.Collections.ArrayList
    foreach ($op in @($C.Ops)) {
        if ([string]$op.T -ne 'Func') { continue }
        $n = [string]$op.Name
        if ($script:LiveKeepPreviewWhy.ContainsKey($n)) { [void]$w.Add($n + ': ' + [string]$script:LiveKeepPreviewWhy[$n]) }
    }
    if ($w.Count -eq 0) { return '' }
    return (('tam kipte de yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'nizlendi (') + ($w.ToArray() -join '; ') + ')')
}

# Tek yonlu islem bu bilgisayarda canli denenebilir mi? Donus: '' (evet) ya da neden metni
function Get-LiveOneWayBlock([string]$Name) {
    if ($Name -eq 'EmptyRecycleBin') {
        $n = -1
        try { $n = [int](New-Object -ComObject Shell.Application).NameSpace(10).Items().Count } catch { }
        if ($n -ne 0) { return (('Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu dolu (') + $(if ($n -lt 0) { '?' } else { [string]$n }) + (' ' + [char]0x00F6 + '' + [char]0x011F + 'e): veri kayb' + [char]0x0131 + ' olmas' + [char]0x0131 + 'n diye yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'nizlendi')) }
    }
    return ''
}

function Get-LiveGroup($C) {
    $pr = $sync.Profile
    try { if (-not (Test-OsOk ([string]$C.OS) $pr)) { return 'uygunsuz' } } catch { }
    $types = @(@($C.Ops) | ForEach-Object { [string]$_.T } | Sort-Object -Unique)
    if ($types -contains 'Cap' -or $types -contains 'Appx' -or $types -contains 'Feature') { return 'bilesen' }
    $funcs = @(@($C.Ops) | Where-Object { [string]$_.T -eq 'Func' } | ForEach-Object { [string]$_.Name })
    foreach ($fn in $funcs) {
        if ($script:LiveKeepPreview -contains $fn) { return 'onizleme' }
        if ($script:LiveFuncLive -notcontains $fn -and $script:LiveOneWay -notcontains $fn) { return 'onizleme' }
    }
    if (@($funcs | Where-Object { $script:LiveOneWay -contains $_ }).Count -gt 0) { return 'tekyon' }
    if ([bool]$C.Irrev) { return 'onizleme' }
    if ($types.Count -eq 1 -and $types[0] -eq 'Reg') {
        $roots = @(@($C.Ops) | ForEach-Object { ([string]$_.Path).Split('\')[0].ToUpperInvariant() } | Sort-Object -Unique)
        if ($roots.Count -eq 1 -and ($roots[0] -eq 'HKCU' -or $roots[0] -eq 'HKU')) { return 'hkcu' }
        return 'hklm'
    }
    if (@($types | Where-Object { @('Svc', 'Task', 'Reg') -notcontains $_ }).Count -eq 0) { return 'hizmet' }
    return 'ozel'
}

function Get-LiveApplicable {
    if ($null -ne $script:LiveApplicable) { return $script:LiveApplicable }
    if ($null -eq $sync.Profile) { try { $pf = Get-SystemProfile; $sync.Profile = $pf } catch { } }
    $list = New-Object System.Collections.ArrayList
    foreach ($c in @($script:Catalog)) {
        $ok = $true
        try { $ok = [bool](Test-OsOk ([string]$c.OS) $sync.Profile) } catch { $ok = $true }
        if ($ok) { [void]$list.Add($c) }
    }
    $script:LiveApplicable = $list.ToArray()
    return $script:LiveApplicable
}

function Get-LiveJournalAfter([datetime]$Since) {
    $best = $null
    try {
        foreach ($f in @(Get-ChildItem -LiteralPath ([string]$sync.BackupDir) -Filter 'yedek-*.jsonl' -ErrorAction SilentlyContinue)) {
            if ($f.LastWriteTime -ge $Since.AddSeconds(-1)) { if ($null -eq $best -or $f.LastWriteTime -gt $best.LastWriteTime) { $best = $f } }
        }
    } catch { }
    if ($null -eq $best) { return '' }
    return [string]$best.FullName
}

function Wait-LiveSvc($Snap0, $C) {
    # hizmet durumu (calisiyor / durdu) gecikmeli degisir: eski haline donene kadar en cok 12 sn bekler (yalniz hizmet ogeleri yoklanir)
    $ops = @($C.Ops); $s0 = @($Snap0)
    for ($t = 0; $t -lt 12; $t++) {
        $same = $true
        for ($i = 0; $i -lt $ops.Count -and $i -lt $s0.Count; $i++) {
            if ([string]$ops[$i].T -ne 'Svc') { continue }
            if ((Compare-LiveItem $s0[$i] (Get-LiveSvcSnap ([string]$ops[$i].Name))) -ne '') { $same = $false; break }
        }
        if ($same) { break }
        Start-Sleep -Milliseconds 1000
    }
    return (Get-LiveSnap $C)
}

# ---------------- bir ayarin tam turu ----------------
function Invoke-LiveRoundTrip($C, [string]$Mode) {
    $id = [string]$C.Id
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $defects = New-Object System.Collections.ArrayList
    $notes = New-Object System.Collections.ArrayList
    $snap0 = Get-LiveSnap $C
    $p0 = Get-TweakPending $C
    $hasSvc = (@(@($C.Ops) | Where-Object { [string]$_.T -eq 'Svc' }).Count -gt 0)
    $oneWay = @(@($C.Ops) | Where-Object { [string]$_.T -eq 'Func' -and $script:LiveOneWay -contains [string]$_.Name } | ForEach-Object { [string]$_.Name })
    # olculebilirlik motorla ayni tanimdan gelir (Get-TweakPending -1 donuyorsa olculemez)
    $measurable = ($p0 -ge 0)
    $allMeas = (@(@($C.Ops) | Where-Object { -not (Test-LiveOpMeasurable $_) }).Count -eq 0)

    # 1) onizleme: hicbir sey yazmaz; olcumle tutarli mi
    $mk = Get-LiveLogMark
    $pv = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-StepsFromIds @($id)); Preview = $true; RestorePoint = $false }
    $plan = Select-LiveLines (Get-LiveLogSince $mk) 'PLAN'
    if ($pv.Err -ne '') { [void]$defects.Add(('' + [char]0x00F6 + 'nizleme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $pv.Err) }
    else {
        $chg = [int]$pv.Out.Changes
        if ($allMeas -and $p0 -ge 0 -and $chg -ne $p0) { [void]$defects.Add(('' + [char]0x00F6 + 'nizleme ') + $chg + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik diyor, ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ') + $p0 + ' bekleyen diyor') }
        $after = Get-LiveSnap $C
        $dd = Compare-LiveSnap $snap0 $after
        if ($dd.Count -gt 0) { [void]$defects.Add(('' + [char]0x00F6 + 'nizleme sistemi de' + [char]0x011F + 'i' + [char]0x015F + 'tirdi: ') + ($dd -join '; ')) }
    }
    if ($Mode -ne 'tam') {
        $st = 'OK'; if ($defects.Count -gt 0) { $st = 'HATA' }
        $txt = ('' + [char]0x00F6 + 'nizleme ') + $(if ($pv.Err -eq '') { [string]$pv.Out.Changes + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik, ') + [string]$pv.Out.Skipped + ' atlanan' } else { ('ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z') }) + ('; ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm=') + $p0
        if ($defects.Count -gt 0) { $txt += '; ' + ($defects -join ' | ') }
        Add-LiveRow 'tur' $id $st $txt $sw.ElapsedMilliseconds
        return
    }

    # 1b) tek yonlu islem bu bilgisayarda canli denenemiyorsa yalnizca onizleme (neden yazilir)
    foreach ($ow in $oneWay) {
        $why = Get-LiveOneWayBlock $ow
        if ($why -ne '') {
            $txt = ('' + [char]0x00F6 + 'nizleme ') + $(if ($pv.Err -eq '') { [string]$pv.Out.Changes + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik') } else { ('ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z') }) + '; ' + $why
            if ($defects.Count -gt 0) { Add-LiveRow 'tur' $id 'HATA' ($txt + '; ' + ($defects -join ' | ')) $sw.ElapsedMilliseconds } else { Add-LiveRow 'tur' $id 'BILGI' $txt $sw.ElapsedMilliseconds }
            return
        }
    }
    $plan0 = @($plan | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+PLAN\s+', '') })

    # 2) gercek tur: eski durum diske yazilir, sonra uygulanir
    Save-LiveInflight $id $snap0
    Add-LiveTouched $C
    $t0 = Get-Date
    $restoredBy = ''
    try {
        $mk1 = Get-LiveLogMark
        $r1 = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-StepsFromIds @($id)); Preview = $false; RestorePoint = $false }
        $log1 = Get-LiveLogSince $mk1
        $errs1 = Select-LiveLines $log1 'ERR'
        if ($r1.Err -ne '') { [void]$defects.Add(('uygulama ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r1.Err) }
        elseif ([int]$r1.Out.Errors -gt 0) { [void]$defects.Add('uygulama ' + [string]$r1.Out.Errors + ' hata verdi: ' + (Get-LiveShort ($errs1 -join ' | ') 200)) }
        $changes = 0; $skipped = 0
        if ($r1.Err -eq '') { $changes = [int]$r1.Out.Changes; $skipped = [int]$r1.Out.Skipped }

        $snap1 = Get-LiveSnap $C
        $p1 = Get-TweakPending $C
        $mis = Get-LiveExpectMismatch $C $snap1 $log1
        if ($mis.Count -gt 0) {
            $denied = (Test-TweakBlocked $C)
            if ($denied) { [void]$notes.Add(('Windows korumal' + [char]0x0131 + ': ') + (Get-LiveShort ($mis -join '; ') 160)) }
            else { [void]$defects.Add(('uygulanan de' + [char]0x011F + 'er okunam' + [char]0x0131 + 'yor: ') + (Get-LiveShort ($mis -join '; ') 240)) }
        }
        if ($measurable) {
            if ($p1 -gt 0) {
                $mk2 = Get-LiveLogMark
                [void](Invoke-LiveJob 'Job_Plan' @{ Steps = (New-StepsFromIds @($id)); Preview = $true; RestorePoint = $false })
                $plan2 = Select-LiveLines (Get-LiveLogSince $mk2) 'PLAN'
                $txt = ('uygulamadan sonra ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ') + $p1 + ' bekleyen diyor'
                if ($plan2.Count -gt 0) { $txt += ': ' + (Get-LiveShort (($plan2 | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+PLAN\s+', '') }) -join '; ') 220) }
                if (Test-TweakBlocked $C) { [void]$notes.Add($txt) } else { [void]$defects.Add($txt) }
            }
            elseif ($p1 -lt 0) { [void]$defects.Add(('uygulamadan sonra ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemiyor')) }
        }
        # uygulananlar listesi
        if ($measurable -and $p1 -eq 0 -and $changes -gt 0 -and $p0 -gt 0) {
            $ap = Get-AppliedIds
            if ($ap -notcontains $id) { [void]$defects.Add(('ayar uyguland' + [char]0x0131 + ' ama ' + [char]0x201C + 'uygulanm' + [char]0x0131 + '' + [char]0x015F + ' ayarlar' + [char]0x201D + ' listesine yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
        }

        # 2b) tek yonlu islem: ikinci onizleme ile dogrulama (bekleyen is azalmali; silinen dosyalar geri gelmez)
        $oneTxt = ''
        if ($oneWay.Count -gt 0) {
            $mkw = Get-LiveLogMark
            $pvw = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-StepsFromIds @($id)); Preview = $true; RestorePoint = $false }
            $planw = @((Select-LiveLines (Get-LiveLogSince $mkw) 'PLAN') | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+PLAN\s+', '') })
            $n0 = Get-LivePlanFiles $plan0
            $n2 = Get-LivePlanFiles $planw
            $done1 = @((Select-LiveLines $log1 'OK') | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+OK\s+', '') })
            $oneTxt = ('tek y' + [char]0x00F6 + 'nl' + [char]0x00FC + ' (') + ($oneWay -join ',') + ('): ' + [char]0x00F6 + 'nizleme ') + $(if ($n0 -ge 0) { [string]$n0 + ' dosya' } else { (Get-LiveShort ($plan0 -join '; ') 80) }) + (' ' + [char]0x2192 + ' uyguland' + [char]0x0131 + ': ') + (Get-LiveShort ($done1 -join '; ') 120)
            if ($pvw.Err -ne '') { [void]$defects.Add(('uygulamadan sonraki ' + [char]0x00F6 + 'nizleme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $pvw.Err) }
            elseif ($n0 -ge 0 -and $n2 -ge 0) {
                $oneTxt += (' ' + [char]0x2192 + ' kalan ') + [string]$n2 + ' dosya'
                if ($n0 -gt 5 -and $n2 -ge $n0) { [void]$defects.Add(('uyguland' + [char]0x0131 + ' dendi ama ikinci ' + [char]0x00F6 + 'nizleme ayn' + [char]0x0131 + ' say' + [char]0x0131 + 'da dosya g' + [char]0x00F6 + 'r' + [char]0x00FC + 'yor (') + $n0 + ('' + [char]0x2192 + '') + $n2 + ('); hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silinmemi' + [char]0x015F + ' olabilir')) }
                elseif ($n2 -gt 0 -and $n0 -gt 0 -and $n2 -gt [math]::Max(3, [int]($n0 * 0.25))) { [void]$notes.Add('kalan ' + $n2 + '/' + $n0 + (' dosya (kullan' + [char]0x0131 + 'mda ya da korumal' + [char]0x0131 + ' olabilir)')) }
            }
            if ($done1.Count -eq 0 -and $r1.Err -eq '' -and [int]$r1.Out.Skipped -eq 0 -and [int]$r1.Out.Errors -eq 0) { [void]$defects.Add(('uygulama ne yap' + [char]0x0131 + 'ld' + [char]0x0131 + ' ne atland' + [char]0x0131 + ' sat' + [char]0x0131 + 'r' + [char]0x0131 + ' yazd' + [char]0x0131 + '')) }
        }

        # 3) geri al
        $jf = Get-LiveJournalAfter $t0
        if ($changes -gt 0 -and $jf -eq '' -and $oneWay.Count -eq 0) { [void]$defects.Add(('de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yap' + [char]0x0131 + 'ld' + [char]0x0131 + ' ama geri alma g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
        if ($jf -ne '') {
            $mk3 = Get-LiveLogMark
            $r2 = Invoke-LiveJob 'Job_Undo' @{ File = $jf }
            $log3 = Get-LiveLogSince $mk3
            if ($r2.Err -ne '') { [void]$defects.Add(('geri alma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r2.Err) }
            elseif ([int]$r2.Out.Errors -gt 0) { [void]$defects.Add('geri alma ' + [string]$r2.Out.Errors + ' hata verdi: ' + (Get-LiveShort ((Select-LiveLines $log3 'ERR') -join ' | ') 200)) }
        }
        $snap2 = $null
        if ($hasSvc) { $snap2 = Wait-LiveSvc $snap0 $C } else { $snap2 = Get-LiveSnap $C }
        $d2 = Compare-LiveSnap $snap0 $snap2
        if ($d2.Count -gt 0) {
            [void]$defects.Add(('geri alma eski durumu d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'rmedi: ') + (Get-LiveShort ($d2 -join '; ') 240))
            # bagimsiz geri yukleme: sistem yine de eski haline getirilir
            Restore-LiveSnap (ConvertTo-LiveSerial $snap0)
            $restoredBy = ('ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z geri y' + [char]0x00FC + 'kleme yap' + [char]0x0131 + 'ld' + [char]0x0131 + '')
            $d3 = Compare-LiveSnap $snap0 (Get-LiveSnap $C)
            if ($d3.Count -gt 0) {
                [void]$defects.Add(('ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z geri y' + [char]0x00FC + 'kleme de eski haline getiremedi: ') + (Get-LiveShort ($d3 -join '; ') 200))
                # kalici kurtarma listesine yazilir (sonraki tam denetimin basinda yeniden denenir) ve bu turden canli deneme durdurulur
                Add-LiveUnrestored $id (ConvertTo-LiveSerial $snap0) ($d3 -join '; ')
                foreach ($it0 in @($snap0)) { if ($null -ne $it0) { [void]$script:LiveStopKinds.Add([string]$it0.K) } }
            }
        }
        $p2 = Get-TweakPending $C
        if ($measurable -and $p2 -ne $p0) { [void]$defects.Add(('geri almadan sonra ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ') + $p2 + (' (ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' ') + $p0 + ')') }
        if ($measurable -and $p0 -gt 0 -and $p2 -gt 0) {
            $ap2 = Get-AppliedIds
            if ($ap2 -contains $id) { [void]$defects.Add(('geri al' + [char]0x0131 + 'nd' + [char]0x0131 + ' ama ' + [char]0x201C + 'uygulanm' + [char]0x0131 + '' + [char]0x015F + ' ayarlar' + [char]0x201D + ' listesinde kald' + [char]0x0131 + '')) }
        }
        Clear-LiveInflight
        $st = 'OK'
        if ($defects.Count -gt 0) { $st = 'HATA' } elseif ($notes.Count -gt 0) { $st = 'UYARI' }
        $txt = ('de' + [char]0x011F + 'i' + [char]0x015F + 'iklik=') + $changes + ' atlanan=' + $skipped + (' ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ') + $p0 + ('' + [char]0x2192 + '') + $p1 + ('' + [char]0x2192 + '') + $p2
        if ($oneTxt -ne '') { $txt += '; ' + $oneTxt }
        if ($notes.Count -gt 0) { $txt += '; ' + ($notes -join ' | ') }
        if ($defects.Count -gt 0) { $txt += '; ' + ($defects -join ' | ') }
        if ($restoredBy -ne '') { $txt += '; ' + $restoredBy }
        Add-LiveRow 'tur' $id $st $txt $sw.ElapsedMilliseconds
    } catch {
        # beklenmeyen hata: eski hale getirmeyi dene
        try { Restore-LiveSnap (ConvertTo-LiveSerial $snap0); Clear-LiveInflight } catch { }
        Add-LiveRow 'tur' $id 'HATA' (('tur ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message + ' (eski hale getirildi)') $sw.ElapsedMilliseconds
    }
}

# Islem motorun olcumune giriyor mu (Get-TweakPending ile ayni tanim)
function Test-LiveOpMeasurable($Op) {
    $t = [string]$Op.T
    if (@('Reg', 'Svc', 'Task', 'Mp', 'EvtLog', 'Cap', 'Feature', 'DxGlobal', 'NetLatency') -contains $t) { return $true }
    return ($t -eq 'Func' -and $script:FuncStateful -contains [string]$Op.Name)
}

# Bir geri yukleme basarisiz olunca o turden (Feature, Cap, ...) canli deneme durdurulur
$script:LiveStopKinds = New-Object System.Collections.ArrayList

# Kalici kurtarma listesi: denetim bir degisikligi geri alamadiysa sonraki tam denetimin basinda yeniden denenir
function Get-LiveUnrestoredFile { return (Join-Path (Get-LiveDir) 'ozellik-geri-yuklenemedi.json') }

# JSON dizisini duz liste olarak okur. Windows PowerShell 5.1'de ConvertFrom-Json diziyi tek nesne olarak dondurur;
# @() ile sarilinca ic ice dizi olur ve listeye geri yazilinca her calismada bir kat daha icine girer (cihazda goruldu:
# [[[{FeatWorkFolders}]],{FeatHyperV}]). Ic ice diziler acilir; boylece eski bicimde yazilmis dosya da onarilir.
function Add-LiveFlat($List, $X) {
    if ($null -eq $X) { return }
    if ($X -is [System.Array] -or $X -is [System.Collections.ArrayList]) { foreach ($y in $X) { Add-LiveFlat $List $y }; return }
    [void]$List.Add($X)
}

function ConvertFrom-LiveJsonList([string]$Text) {
    $out = New-Object System.Collections.ArrayList
    if ([string]::IsNullOrWhiteSpace($Text)) { return $out.ToArray() }
    Add-LiveFlat $out (ConvertFrom-Json -InputObject $Text)
    return $out.ToArray()
}

function Get-LiveUnrestored {
    $f = Get-LiveUnrestoredFile
    if (-not (Test-Path -LiteralPath $f)) { return @() }
    try { return (ConvertFrom-LiveJsonList ([System.IO.File]::ReadAllText($f))) } catch { return @() }
}

function Save-LiveUnrestoredList($List) {
    $f = Get-LiveUnrestoredFile
    $arr = @($List)
    if ($arr.Count -eq 0) { try { if (Test-Path -LiteralPath $f) { Remove-Item -LiteralPath $f -Force -ErrorAction Stop } } catch { }; return }
    try { [System.IO.File]::WriteAllText($f, (ConvertTo-Json -InputObject $arr -Depth 8), (New-Object System.Text.UTF8Encoding($false))) } catch { }
}

function Add-LiveUnrestored([string]$Id, $Serial, [string]$Why) {
    $list = New-Object System.Collections.ArrayList
    foreach ($e in @(Get-LiveUnrestored)) { if ([string]$e.Id -ne $Id) { [void]$list.Add($e) } }
    $now = (Get-Date).ToString('s')
    [void]$list.Add(@{ Id = $Id; Time = $now; Why = $Why; Items = @($Serial); Build = (Get-LiveBuildTag); Tried = $now })
    Save-LiveUnrestoredList $list
    Add-LiveRisky $Serial $Why
}

# Windows derlemesi (derleme.UBR). Istege bagli bilesenlerin icerigi Windows Update'te derlemeye gore yayimlanir.
function Get-LiveBuildTag {
    $b = 0
    try { $b = [int](Get-OsBuildNumber) } catch { $b = 0 }
    $u = 0
    try { $u = [int](Get-RegValue 'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'UBR' 0) } catch { $u = 0 }
    return ([string]$b + '.' + [string]$u)
}

# Bilesenin icerigi bu derleme icin Windows Update'te yoksa (0x800F0950) ayni derlemede 3 gun dolmadan yeniden denenmez.
# Gercek bilgisayarda (18.11.2026) Adim Kaydedicisi Windows onizleme derlemesinde geri kurulamadi; her tam denetimin basinda
# yeniden denemek yalnizca sure harcayip ayni hatayi yaziyordu. Derleme degisince ya da 3 gun gecince yeniden denenir.
function Test-LiveRetryDeferred($E, [string]$Build, [datetime]$Now) {
    try {
        if ([string]$E.Why -notmatch '0x800F0950') { return $false }
        if ([string]$E.Build -eq '' -or [string]$E.Build -ne $Build) { return $false }
        $t = [datetime]::MinValue
        if ($E.Tried -is [datetime]) { $t = [datetime]$E.Tried }
        elseif (-not [datetime]::TryParse([string]$E.Tried, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$t)) { return $false }
        $age = ($Now - $t).TotalHours
        return ($age -ge 0 -and $age -lt 72)
    } catch { return $false }
}

# Kalici risk gecmisi: bu bilgisayarda bir kez geri yuklenemeyen Windows ozelligi / bileseni canli turda bir daha DEGISTIRILMEZ
# (geri yuklense bile). Gercek bilgisayarda (17.11.2026) Sanal Makine Platformu kapatildiktan sonra dosyalari yerelde bulunamadi
# (0x800F0912) ve Windows Update'ten saatlerce indirilemedi. Liste elle silinmedikce kalir: ozellik-riskli.json
function Get-LiveRiskFile { return (Join-Path (Get-LiveDir) 'ozellik-riskli.json') }

function Get-LiveRiskyNames {
    $names = New-Object System.Collections.ArrayList
    $f = Get-LiveRiskFile
    try {
        if (Test-Path -LiteralPath $f) {
            foreach ($e in @(ConvertFrom-LiveJsonList ([System.IO.File]::ReadAllText($f)))) { $n = [string]$e.Name; if ($n -ne '' -and -not $names.Contains($n)) { [void]$names.Add($n) } }
        }
    } catch { }
    # gecis: risk listesinden once geri yuklenemeyen ya da yarim kalan ozellik/bilesenler de riskli sayilir
    foreach ($e in @(Get-LiveUnrestored)) { foreach ($it in @($e.Items)) { if (@('Feature', 'Cap') -contains [string]$it.K) { $n = [string]$it.Name; if ($n -ne '' -and -not $names.Contains($n)) { [void]$names.Add($n) } } } }
    try {
        $yf = Join-Path (Get-LiveDir) 'ozellik-yarim.json'
        if (Test-Path -LiteralPath $yf) {
            $y = ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($yf))
            foreach ($it in @($y.Items)) { if (@('Feature', 'Cap') -contains [string]$it.K) { $n = [string]$it.Name; if ($n -ne '' -and -not $names.Contains($n)) { [void]$names.Add($n) } } }
        }
    } catch { }
    return $names.ToArray()
}

function Add-LiveRisky($Items, [string]$Why) {
    try {
        $f = Get-LiveRiskFile
        $cur = New-Object System.Collections.ArrayList
        if (Test-Path -LiteralPath $f) {
            foreach ($e in @(ConvertFrom-LiveJsonList ([System.IO.File]::ReadAllText($f)))) { if ($null -ne $e -and [string]$e.Name -ne '') { [void]$cur.Add(@{ K = [string]$e.K; Name = [string]$e.Name; Why = [string]$e.Why; Time = [string]$e.Time }) } }
        }
        $added = 0
        foreach ($it in @($Items)) {
            if ($null -eq $it -or @('Feature', 'Cap') -notcontains [string]$it.K) { continue }
            $n = [string]$it.Name
            if ($n -eq '' -or @($cur | Where-Object { $_.Name -eq $n }).Count -gt 0) { continue }
            [void]$cur.Add(@{ K = [string]$it.K; Name = $n; Why = (Get-LiveShort $Why 300); Time = (Get-Date).ToString('s') })
            $added++
        }
        if ($added -gt 0) { [System.IO.File]::WriteAllText($f, (ConvertTo-Json -InputObject @($cur.ToArray()) -Depth 4), (New-Object System.Text.UTF8Encoding($false))) }
    } catch { }
}

# Bu denetimde geri yuklemesi basarisiz olan ozellik/bilesen adlari (ayni ozellik ayni denetimde ikinci kez uzun sure denenmez)
$script:LiveRestoreFailed = New-Object System.Collections.ArrayList

# Denetimin canli degistirdigi ayarlar ve Windows ozellik/bilesenleri. Son durum karsilastirmasinda baslangictan farkli
# kalan bir ayarin butun islemleri Windows ozelligi/bileseniyse ve denetim bunlardan hicbirine dokunmadiysa degisiklik
# denetimden gelmemistir (gercek bilgisayar 24.11.2026: XPS Goruntuleyici denetim sirasinda Windows tarafindan kuruldu;
# denetim, yeniden baslatma beklendigi icin bilesen turlarini hic yapmamisti ama "baslangictan farkli" HATA yazildi).
$script:LiveTouchedIds = @{}
$script:LiveCompTouched = @{}

function Add-LiveCompTouched([string]$Kind, [string]$Name) {
    if ($null -eq $script:LiveCompTouched) { $script:LiveCompTouched = @{} }
    if (($Kind -eq 'Feature' -or $Kind -eq 'Cap') -and $Name -ne '') { $script:LiveCompTouched[$Kind + ':' + $Name] = $true }
}

function Get-LiveOpCompName($Op) {
    if ([string]$Op.T -eq 'Cap') { return [string]$Op.Match }
    return [string]$Op.Name
}

function Add-LiveTouched($C) {
    if ($null -eq $C) { return }
    if ($null -eq $script:LiveTouchedIds) { $script:LiveTouchedIds = @{} }
    $script:LiveTouchedIds[[string]$C.Id] = $true
    foreach ($op in @($C.Ops)) { Add-LiveCompTouched ([string]$op.T) (Get-LiveOpCompName $op) }
}

# $true: ayarin butun islemleri Windows ozelligi/bileseni ve bu denetim hicbirini degistirmedi
function Test-LiveMovedOutside($C) {
    if ($null -eq $C) { return $false }
    if ($null -ne $script:LiveTouchedIds -and $script:LiveTouchedIds.ContainsKey([string]$C.Id)) { return $false }
    $ops = @($C.Ops)
    if ($ops.Count -eq 0) { return $false }
    foreach ($op in $ops) {
        $t = [string]$op.T
        if ($t -ne 'Feature' -and $t -ne 'Cap') { return $false }
        if ($null -ne $script:LiveCompTouched -and $script:LiveCompTouched.ContainsKey($t + ':' + (Get-LiveOpCompName $op))) { return $false }
    }
    return $true
}

# Denetim sonunda: kurtarma listesindeki kayit bu arada eski durumuna donduyse (or. Windows bileseni kuruldu) listeden cikar
function Remove-LiveUnrestoredDone {
    if ((Get-LiveMode) -ne 'tam') { return }
    $list = @(Get-LiveUnrestored)
    if ($list.Count -eq 0) { return }
    $left = New-Object System.Collections.ArrayList
    foreach ($e in $list) {
        $its = @($e.Items)
        $all = ($its.Count -gt 0)
        foreach ($it in $its) {
            $ok = $false
            try { $ok = [bool](Test-LiveItemCurrent $it) } catch { $ok = $false }
            if (-not $ok) { $all = $false; break }
        }
        if ($all) { Add-LiveRow 'kurtarma' ([string]$e.Id) 'OK' (('' + [char]0x00F6 + 'nceki denetimden kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik denetim s' + [char]0x0131 + 'ras' + [char]0x0131 + 'nda eski durumuna d' + [char]0x00F6 + 'nd' + [char]0x00FC + ' (') + [string]$e.Time + ('); listeden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'ld' + [char]0x0131 + '')) }
        else { [void]$left.Add($e) }
    }
    if ($left.Count -ne $list.Count) { Save-LiveUnrestoredList $left }
}

# Ogeyi geri yuklemek icin DISM gerekiyor mu (Windows ozelligi / bileseni)
function Test-LiveDismItem($It) { return (@('Feature', 'Cap') -contains [string]$It.K) }

# DISM gerektiren oge zaten eski (istenen) durumunda mi? Oyleyse geri yuklemeye gerek yoktur; yeniden baslatma beklense de
# listeden duser (cihazda: ozellikler elle geri acildiktan sonra kurtarma listesi yeniden baslatma beklendigi icin bosalmadi)
function Test-LiveItemCurrent($It) {
    try {
        switch ([string]$It.K) {
            'Feature' { return ([string](Get-LiveFeatSnap ([string]$It.Name)).State -eq [string]$It.State) }
            'Cap' { $cur = Get-LiveCapState ([string]$It.Name); return ($cur -ne 'okunamadi' -and $cur -eq [string]$It.Data) }
        }
    } catch { }
    return $false
}

# Denetimin basinda: tam kipte yeniden geri yuklemeyi dener; okuma kipinde yalnizca bildirir
function Restore-LiveUnrestored {
    $list = @(Get-LiveUnrestored)
    if ($list.Count -eq 0) { return }
    if ((Get-LiveMode) -ne 'tam') {
        foreach ($e in $list) { Add-LiveRow 'kurtarma' ([string]$e.Id) 'UYARI' (('' + [char]0x00F6 + 'nceki tam denetimden geri y' + [char]0x00FC + 'klenemeyen de' + [char]0x011F + 'i' + [char]0x015F + 'iklik (') + [string]$e.Time + '): ' + (Get-LiveShort ([string]$e.Why) 200) + '; tam kipte yeniden denenecek') }
        return
    }
    $build = Get-LiveBuildTag
    $now = Get-Date
    $left = New-Object System.Collections.ArrayList
    foreach ($e in $list) {
        if (Test-LiveRetryDeferred $e $build $now) {
            [void]$left.Add($e)
            $names = (@($e.Items) | ForEach-Object { [string]$_.Name }) -join ', '
            Add-LiveRow 'kurtarma' ([string]$e.Id) 'UYARI' (('' + [char]0x00F6 + 'nceki denetimden kalan bile' + [char]0x015F + 'en bu Windows derlemesi (') + $build + (') i' + [char]0x00E7 + 'in Windows Update' + [char]0x2019 + 'te bulunmuyor (0x800F0950); son deneme ') + [string]$e.Tried + ('. Windows g' + [char]0x00FC + 'ncellenince ya da 3 g' + [char]0x00FC + 'n sonra yeniden denenecek: ') + $names)
            continue
        }
        $errs = New-Object System.Collections.ArrayList
        $held = ''
        $already = 0
        foreach ($it in @($e.Items)) {
            if (Test-LiveDismItem $it) {
                if (Test-LiveItemCurrent $it) { $already++; continue }
                $blk = Get-LiveDismBlock
                if ($blk -ne '') { $held = $blk; [void]$script:LiveStopKinds.Add([string]$it.K); continue }
                if ($script:LiveRestoreFailed.Contains([string]$it.Name)) { [void]$errs.Add([string]$it.Name + (': bu denetimde zaten geri y' + [char]0x00FC + 'klenemedi')); continue }
            }
            Add-LiveCompTouched ([string]$it.K) ([string]$it.Name)
            try { Restore-LiveItem $it }
            catch {
                [void]$errs.Add($_.Exception.Message)
                if (Test-LiveDismItem $it) { [void]$script:LiveRestoreFailed.Add([string]$it.Name); [void]$script:LiveStopKinds.Add([string]$it.K) }
            }
        }
        if ($held -ne '' -and $errs.Count -eq 0) {
            [void]$left.Add($e)
            Add-LiveRow 'kurtarma' ([string]$e.Id) 'UYARI' (('' + [char]0x00F6 + 'nceki denetimden kalan Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i/bile' + [char]0x015F + 'eni ' + [char]0x015F + 'imdi geri y' + [char]0x00FC + 'klenmedi: ') + $held + ('; yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p tam denetimi tekrar ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n'))
        } elseif ($errs.Count -gt 0) {
            $why = Get-LiveShort ($errs -join ' | ') 300
            [void]$left.Add(@{ Id = [string]$e.Id; Time = $e.Time; Why = $why; Items = @($e.Items); Build = $build; Tried = $now.ToString('s') })
            # icerik bu derleme icin yayimlanmamissa (0x800F0950) bu bir ortam siniridir, uygulama hatasi degil
            $lvl = 'HATA'
            if (@($errs | Where-Object { [string]$_ -notmatch '0x800F0950' }).Count -eq 0) { $lvl = 'UYARI' }
            Add-LiveRow 'kurtarma' ([string]$e.Id) $lvl (('' + [char]0x00F6 + 'nceki denetimden kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yine geri y' + [char]0x00FC + 'klenemedi: ') + (Get-LiveShort ($errs -join ' | ') 220))
        } elseif ($already -gt 0 -and $already -eq @($e.Items).Count) { Add-LiveRow 'kurtarma' ([string]$e.Id) 'OK' (('' + [char]0x00F6 + 'nceki denetimden kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik zaten eski durumunda (') + [string]$e.Time + ('); listeden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'ld' + [char]0x0131 + '')) }
        else { Add-LiveRow 'kurtarma' ([string]$e.Id) 'OK' (('' + [char]0x00F6 + 'nceki denetimden kalan de' + [char]0x011F + 'i' + [char]0x015F + 'iklik geri y' + [char]0x00FC + 'klendi (') + [string]$e.Time + ')') }
    }
    Save-LiveUnrestoredList $left
}

# DISM ile geri yukleme/tur su an baslatilabilir mi? '' = evet; aksi halde nedeni (yeniden baslatma bekleniyor, Windows Update
# kuruyor, bu oturumda DISM sure sinirini asti ya da bilesen hizmeti onceki isi hala surduruyor)
function Get-LiveDismBlock {
    if ($script:DismTimedOut) { return ('bu denetimde bir DISM i' + [char]0x015F + 'lemi s' + [char]0x00FC + 're s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x015F + 't' + [char]0x0131 + ' (bile' + [char]0x015F + 'en hizmeti h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'yor olabilir)') }
    $b = Get-LiveServicingBlock
    if ($b -ne '') { return $b }
    $p = Wait-LiveCbsIdle 180
    if ($p -ne '') { return (('Windows bile' + [char]0x015F + 'en hizmeti ' + [char]0x00F6 + 'nceki bir i' + [char]0x015F + 'i s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'yor (') + $p + ')') }
    return ''
}

# PLAN satirlarindaki "N dosya" toplami; hic yoksa -1
function Get-LivePlanFiles($Lines) {
    $sum = 0; $any = $false
    foreach ($l in @($Lines)) {
        foreach ($m in [regex]::Matches([string]$l, '(\d+) dosya')) { $sum += [int]$m.Groups[1].Value; $any = $true }
    }
    if (-not $any) { return -1 }
    return $sum
}

function Test-LiveRoundTrips([string]$Group) {
    $mode = Get-LiveMode
    $list = New-Object System.Collections.ArrayList
    foreach ($c in @(Get-LiveApplicable)) {
        if ((Get-LiveGroup $c) -eq $Group) { [void]$list.Add($c) }
    }
    # yalnizca onizlenecek grup tam kipte de gercek uygulanmaz (cihazda 18.11.2026: bu satir yokken eski geri yukleme noktalari silindi)
    $runMode = $mode
    if ($Group -eq 'onizleme') { $runMode = 'oku' }
    $gtxt = [string]$list.Count + ' ayar; kip=' + $mode
    if ($runMode -ne $mode) { $gtxt += (' (bu grup her kipte yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'nizlenir)') }
    Add-LiveRow 'tur' ('grup:' + $Group) 'BILGI' $gtxt
    $n = 0
    foreach ($c in $list) {
        $n++
        if ($runMode -ne $mode) {
            $why = Get-LiveKeepPreviewWhy $c
            if ($why -ne '') { Add-LiveRow 'tur' ('neden:' + [string]$c.Id) 'BILGI' $why }
        }
        try { Invoke-LiveRoundTrip $c $runMode } catch { Add-LiveRow 'tur' ([string]$c.Id) 'HATA' (('tur ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message) }
        if (($n % 8) -eq 0) { try { Invoke-SmokeFlush } catch { } }
    }
}

# ---------------- ortam ve yetki ----------------
function Test-LiveEnv {
    $mode = Get-LiveMode
    $txt = 'kip=' + $mode + ('; y' + [char]0x00F6 + 'netici=') + [string][bool]$script:IsAdmin
    if ($script:LiveDowngraded) { $txt += (' (tam kip istendi ama y' + [char]0x00F6 + 'netici de' + [char]0x011F + 'il: yaln' + [char]0x0131 + 'zca okuma)') }
    Add-LiveRow 'ortam' 'kip' 'BILGI' $txt
    if ($null -eq $sync.Profile) { try { $pf = Get-SystemProfile; $sync.Profile = $pf } catch { } }
    $p = $sync.Profile
    if ($null -ne $p) {
        Add-LiveRow 'ortam' 'sistem' 'BILGI' ([string]$p.OsName + ' build ' + [string]$p.Build + '.' + [string]$p.UBR + '; ' + [string]$p.Model + '; ' + [string]$p.CpuName + '; ' + [string]$p.RamGB + ' GB; disk=' + [string]$p.DiskType + ('; diz' + [char]0x00FC + 'st' + [char]0x00FC + '=') + [string]$p.IsLaptop + ('; y' + [char]0x00F6 + 'netilen=') + [string]$p.IsManaged)
    } else { Add-LiveRow 'ortam' 'sistem' 'HATA' ('sistem profili okunamad' + [char]0x0131 + '') }
    $cp = Get-LiveRegRaw 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'ConsentPromptBehaviorAdmin'
    $lua = Get-LiveRegRaw 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableLUA'
    Add-LiveRow 'ortam' 'uac' 'BILGI' ('EnableLUA=' + $(if ($lua.Exists) { [string]$lua.Data } else { '?' }) + '; ConsentPromptBehaviorAdmin=' + $(if ($cp.Exists) { [string]$cp.Data } else { '?' }))
    # yeniden baslatma bekliyor mu: motor ile bagimsiz okuma ayni sonucu vermeli
    $eng = Get-PendingReboot
    $ind = New-Object System.Collections.ArrayList
    $cbs = Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
    if ($cbs -contains 'RebootPending') { [void]$ind.Add('CBS') }
    $wu = Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update'
    if ($wu -contains 'RebootRequired') { [void]$ind.Add('WU') }
    $pf = Get-LiveRegRaw 'HKLM\SYSTEM\CurrentControlSet\Control\Session Manager' 'PendingFileRenameOperations'
    $pfTxt = ''
    if ($pf.Exists) { $pfTxt = ' PendingFileRenameOperations=' + (Get-LiveShort ((@($pf.Data) -join '|') -replace [string][char]0, '') 160) }
    $engText = ($eng -join '|')
    $bad = New-Object System.Collections.ArrayList
    if (($wu -contains 'RebootRequired') -ne ($engText -match 'Windows Update')) { [void]$bad.Add('Windows Update') }
    if (($cbs -contains 'RebootPending') -ne ($engText -match 'Bile')) { [void]$bad.Add(('Bile' + [char]0x015F + 'en servisi')) }
    if ($bad.Count -gt 0) { Add-LiveRow 'ortam' 'yeniden-baslatma' 'HATA' (('yeniden ba' + [char]0x015F + 'latma bekleme durumu uygulama ile kay' + [char]0x0131 + 't defterinde uyu' + [char]0x015F + 'muyor (') + ($bad -join ', ') + '): uygulama [' + ($eng -join ', ') + ('], kay' + [char]0x0131 + 't defteri [') + ($ind -join ',') + ']') }
    else { Add-LiveRow 'ortam' 'yeniden-baslatma' 'OK' ('uygulama: [' + ($eng -join ', ') + (']; kay' + [char]0x0131 + 't defteri: [') + ($ind -join ',') + ']' + $pfTxt) }
    # yarim kalan onceki tur ve onceki denetimden geri yuklenemeyenler
    Restore-LiveUnrestored
    Restore-LiveInflight
    $busy = Get-LiveServicingBlock
    if ($busy -ne '') { Add-LiveRow 'ortam' 'guncelleme' 'UYARI' ($busy + (': Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i / bile' + [char]0x015F + 'eni turlar' + [char]0x0131 + ' bu durumda yap' + [char]0x0131 + 'lmaz (yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'nizlenir)')) }
    else { Add-LiveRow 'ortam' 'guncelleme' 'OK' ('Windows Update g' + [char]0x00FC + 'ncelleme kurmuyor; bile' + [char]0x015F + 'en servisi yeniden ba' + [char]0x015F + 'latma beklemiyor') }
}

# Olculemeyen ayarlarin onem duzeyi. Kimlik bicimi: Id(Tur1+Tur2...). Yonetici degilken yalnizca yonetici isteyen okuyuculari
# (Windows bileseni / ozelligi, Defender) iceren ayarlar BILGI; digerleri ya da yonetici kipinde herhangi biri UYARI.
$script:LiveAdminOnlyOps = @('Cap', 'Feature', 'Mp')
function Get-LiveUnkLevel([string[]]$UnkIds, [bool]$Admin) {
    if ($Admin -or @($UnkIds).Count -eq 0) { return 'UYARI' }
    foreach ($u in @($UnkIds)) {
        $m = [regex]::Match([string]$u, '\(([^()]*)\)$')
        if (-not $m.Success) { return 'UYARI' }
        $kinds = @($m.Groups[1].Value -split '\+' | ForEach-Object { ($_ -split ':')[0] })
        if (@($kinds | Where-Object { $script:LiveAdminOnlyOps -contains $_ }).Count -eq 0) { return 'UYARI' }
    }
    return 'BILGI'
}

# ---------------- tum ayarlarin durum olcumu ----------------
function Test-LiveMeasure {
    $cat = @(Get-LiveApplicable)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $applied = 0; $pending = 0; $unk = 0; $blocked = 0; $oneWayN = 0
    $unkIds = New-Object System.Collections.ArrayList
    $slow = New-Object System.Collections.ArrayList
    # tek tek olcum PARTISIZ yapilir (her okuma taze); asagida arayuzun partili toplu olcumu bununla karsilastirilir
    foreach ($c in $cat) {
        $one = [System.Diagnostics.Stopwatch]::StartNew()
        $pv = -1
        try { $pv = Get-TweakPending $c } catch { Add-LiveRow 'olcum' ([string]$c.Id) 'HATA' (('' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message); continue }
        $script:LiveState[[string]$c.Id] = $pv
        if ($pv -eq 0 -and (Test-TweakBlocked $c)) { $blocked++ }
        elseif ($pv -eq 0) { $applied++ }
        elseif ($pv -gt 0) { $pending++ }
        else {
            $fn = @(@($c.Ops) | Where-Object { [string]$_.T -eq 'Func' } | ForEach-Object { [string]$_.Name })
            $oneWayOnly = ($fn.Count -gt 0 -and $fn.Count -eq @($c.Ops).Count -and @($fn | Where-Object { $script:LiveOneWay -contains $_ -or $script:LiveKeepPreview -contains $_ -or $_ -eq 'TimeSync' }).Count -eq $fn.Count)
            if ($oneWayOnly) { $oneWayN++ }
            else { $unk++; [void]$unkIds.Add([string]$c.Id + '(' + ((@(@($c.Ops) | ForEach-Object { [string]$_.T + $(if ([string]$_.T -eq 'Func') { ':' + [string]$_.Name } else { '' }) } | Sort-Object -Unique)) -join '+') + ')') }
        }
        if ($one.ElapsedMilliseconds -gt 1500) { [void]$slow.Add([string]$c.Id + '=' + (Format-LiveMs $one.ElapsedMilliseconds)) }
    }
    Add-LiveRow 'olcum' 'ozet' 'BILGI' ([string]$cat.Count + (' ayar: uygulanm' + [char]0x0131 + '' + [char]0x015F + ' ') + $applied + ', bekleyen ' + $pending + (', Windows korumal' + [char]0x0131 + ' ') + $blocked + (', tek y' + [char]0x00F6 + 'nl' + [char]0x00FC + ' (' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lmez) ') + $oneWayN + (', ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemeyen ') + $unk) $sw.ElapsedMilliseconds
    if ($unk -gt 0) {
        # yonetici degilken DISM ile okunan bilesenler okunamaz; uygulama her zaman yonetici olarak acildigindan arayuzde okunur
        $lvl = Get-LiveUnkLevel @($unkIds) ([bool]$script:IsAdmin)
        $why = (' ayar' + [char]0x0131 + 'n durumu ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemiyor (aray' + [char]0x00FC + 'zde durum etiketi g' + [char]0x00F6 + 'sterilmez): ')
        if ($lvl -eq 'BILGI') { $why = (' ayar' + [char]0x0131 + 'n durumu y' + [char]0x00F6 + 'netici izni olmadan okunam' + [char]0x0131 + 'yor (Windows bile' + [char]0x015F + 'enleri DISM ile okunur; uygulama her zaman y' + [char]0x00F6 + 'netici olarak a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'ndan aray' + [char]0x00FC + 'zde okunur): ') }
        Add-LiveRow 'olcum' 'olculemeyen' $lvl ($unk.ToString() + $why + ($unkIds -join ', '))
    }
    if ($slow.Count -gt 0) { Add-LiveRow 'olcum' 'yavas' 'BILGI' (('tek ba' + [char]0x015F + '' + [char]0x0131 + 'na ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'nce 1,5 saniyeden uzun s' + [char]0x00FC + 'renler (aray' + [char]0x00FC + 'z toplu ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'mde g' + [char]0x00F6 + 'rev listesini bir kez okur): ') + ($slow -join ', ')) }
    # arayuzun kullandigi toplu olcum (Job_TweakStates, partili) tek tek (partisiz) olcumle ayni sonucu vermeli ve hizli olmali
    foreach ($page in @('opt', 'sec', 'org')) {
        $pw = [System.Diagnostics.Stopwatch]::StartNew()
        $r = Invoke-LiveJob 'Job_TweakStates' @{ Page = $page }
        $pms = $pw.ElapsedMilliseconds
        if ($r.Err -eq '' -and $pms -gt 20000) { Add-LiveRow 'olcum' ('hiz:' + $page) 'UYARI' (('aray' + [char]0x00FC + 'z' + [char]0x00FC + 'n durum okumas' + [char]0x0131 + ' ') + (Format-LiveMs $pms) + (' s' + [char]0x00FC + 'rd' + [char]0x00FC + ' (20 sn ' + [char]0x00FC + 'st' + [char]0x00FC + ')')) $pms }
        elseif ($r.Err -eq '') { Add-LiveRow 'olcum' ('hiz:' + $page) 'OK' (('aray' + [char]0x00FC + 'z' + [char]0x00FC + 'n durum okumas' + [char]0x0131 + ' ') + (Format-LiveMs $pms)) $pms }
        if ($r.Err -ne '') { Add-LiveRow 'olcum' ('sayfa:' + $page) 'HATA' (('Job_TweakStates ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r.Err); continue }
        $st = $r.Out.States
        $bad = New-Object System.Collections.ArrayList
        foreach ($k in @($st.Keys)) {
            if ($script:LiveState.ContainsKey([string]$k)) {
                $mine = [int]$script:LiveState[[string]$k]
                $theirs = [int]$st[$k]
                if ($theirs -eq -3) { continue }
                if ($mine -ne $theirs) { [void]$bad.Add([string]$k + ' (tek tek ' + $mine + ', toplu ' + $theirs + ')') }
            }
        }
        if ($bad.Count -gt 0) { Add-LiveRow 'olcum' ('sayfa:' + $page) 'HATA' (('toplu ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm tutars' + [char]0x0131 + 'z: ') + ($bad -join '; ')) }
        else { Add-LiveRow 'olcum' ('sayfa:' + $page) 'OK' ([string]@($st.Keys).Count + (' ayar tutarl' + [char]0x0131 + '; geri d' + [char]0x00F6 + 'nen ayar=') + [string]@($r.Out.Drift).Count) }
    }
}

# ---------------- canli ozellik denetimi: etkiler, araclar, isler, bulgular ----------------
# ==================================================================
#  CANLI OZELLIK DENETIMI (2): etkiler, araclar, okuma isleri, saglik bulgulari
#  155_live_audit.ps1 ile birlikte calisir ("ozellik" duman kapsami). Kip kurallari orada anlatilir:
#  "oku" kipinde hicbir sey yazilmaz; "tam" kipte (yonetici) her degisiklik geri alinir ve eski halle karsilastirilir.
# ==================================================================

# ---------------- gorsel efektler: kayit defteri degil, CALISAN OTURUM ----------------
# Uygulamanin kendi bit listesi ($script:LiveMaskBits, 147) kullanilir; boylece uygulama neyi oturuma uyguluyorsa o denetlenir.
function Get-LiveSpiSet {
    $h = @{}
    foreach ($b in $script:LiveMaskBits) { $h[[string]$b] = [int][WH.Sys]::GetSpi([uint32](0x1000 + $b * 2)) }
    $h['drag'] = [int][WH.Sys]::GetSpi([uint32]0x26)
    $h['menudelay'] = [int][WH.Sys]::GetSpi([uint32]0x6A)
    return $h
}

function Format-LiveSpiSet($H) {
    return ((@($script:LiveMaskBits | ForEach-Object { 'b' + $_ + '=' + $H[[string]$_] }) + @(('s' + [char]0x00FC + 'r' + [char]0x00FC + 'kle=') + $H['drag'], ('men' + [char]0x00FC + '=') + $H['menudelay'])) -join ' ')
}

# Gorsel efektleri Windows varsayilanina ceker (yalnizca tam kip denetiminde, ayar zaten uygulanmissa; sonunda asil hale donulur)
function Set-LiveVisualDefaults {
    $desk = 'HKCU\Control Panel\Desktop'
    $adv = 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
    Set-RegData 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' 'VisualFXSetting' 'DWord' 0
    Set-RegData $desk 'UserPreferencesMask' 'Binary' ([byte[]]@(0x9E, 0x1E, 0x07, 0x80, 0x12, 0x00, 0x00, 0x00))
    Set-RegData $desk 'DragFullWindows' 'String' '1'
    Set-RegData $desk 'MenuShowDelay' 'String' '400'
    Set-RegData ($desk + '\WindowMetrics') 'MinAnimate' 'String' '1'
    Set-RegData $adv 'TaskbarAnimations' 'DWord' 1
    Set-RegData $adv 'ListviewAlphaSelect' 'DWord' 1
    Set-RegData $adv 'ListviewShadow' 'DWord' 1
    Set-RegData 'HKCU\Software\Microsoft\Windows\DWM' 'EnableAeroPeek' 'DWord' 1
}

function Wait-LiveSession {
    for ($i = 0; $i -lt 6; $i++) { try { Invoke-SmokeFlush } catch { }; Start-Sleep -Milliseconds 150 }
}

function Test-LiveVisual {
    $mode = Get-LiveMode
    $c = Get-CatalogItem 'VisualFx'
    if ($null -eq $c) { Add-LiveRow 'etki' 'gorsel' 'HATA' ('VisualFx ayar' + [char]0x0131 + ' katalogda yok'); return }
    if (-not (Initialize-SysNative)) { Add-LiveRow 'etki' 'gorsel' 'HATA' ('yerel i' + [char]0x015F + 'levler (SystemParametersInfo) y' + [char]0x00FC + 'klenemedi'); return }
    $before = Get-LiveSpiSet
    # Windows oturum acarken maskeyi okuyup oturuma uygular: kayit defteri ile calisan oturum ayni olmali (eslemenin dogrulugu)
    $raw = Get-LiveRegRaw 'HKCU\Control Panel\Desktop' 'UserPreferencesMask'
    if ($raw.Exists -and $raw.Kind -eq 'Binary') {
        $mask = [byte[]]@($raw.Data)
        $diff = New-Object System.Collections.ArrayList
        foreach ($b in $script:LiveMaskBits) {
            $want = [bool](Get-MaskBit $mask $b)
            $have = ([int]$before[[string]$b] -ne 0)
            if ($want -ne $have) { [void]$diff.Add('bit ' + $b + (' (kay' + [char]0x0131 + 't ') + $want + ', oturum ' + $have + ')') }
        }
        if ($diff.Count -gt 0) { Add-LiveRow 'etki' 'gorsel-oturum' 'UYARI' (('' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oturum kay' + [char]0x0131 + 't defteriyle uyu' + [char]0x015F + 'muyor: ') + ($diff -join ', ') + (' (oturum a' + [char]0x00E7 + '' + [char]0x0131 + 'ld' + [char]0x0131 + 'ktan sonra de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmi' + [char]0x015F + ' ya da bit e' + [char]0x015F + 'lemesi yanl' + [char]0x0131 + '' + [char]0x015F + ' olabilir)')) }
        else { Add-LiveRow 'etki' 'gorsel-oturum' 'OK' (('' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oturum kay' + [char]0x0131 + 't defteriyle uyumlu: ') + (Format-LiveSpiSet $before)) }
    } else { Add-LiveRow 'etki' 'gorsel-oturum' 'BILGI' ('UserPreferencesMask okunamad' + [char]0x0131 + '') }

    $steps = New-StepsFromIds @('VisualFx')
    $pv = Invoke-LiveJob 'Job_Plan' @{ Steps = $steps; Preview = $true; RestorePoint = $false }
    if ($pv.Err -ne '') { Add-LiveRow 'etki' 'gorsel-onizleme' 'HATA' (('' + [char]0x00F6 + 'nizleme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $pv.Err) }
    else {
        $now = Get-LiveSpiSet
        $moved = New-Object System.Collections.ArrayList
        foreach ($k in @($before.Keys)) { if ([int]$before[$k] -ne [int]$now[$k]) { [void]$moved.Add($k) } }
        if ($moved.Count -gt 0) { Add-LiveRow 'etki' 'gorsel-onizleme' 'HATA' (('' + [char]0x00F6 + 'nizleme ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oturumu de' + [char]0x011F + 'i' + [char]0x015F + 'tirdi: ') + ($moved -join ', ')) }
        else { Add-LiveRow 'etki' 'gorsel-onizleme' 'OK' ([string]$pv.Out.Changes + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik ' + [char]0x00F6 + 'nizlendi, oturum de' + [char]0x011F + 'i' + [char]0x015F + 'medi')) }
    }
    if ($mode -ne 'tam') { return }

    # gercek tur: uygula -> calisan oturumu oku -> geri al -> oturum eski haline donmeli
    $snap0 = Get-LiveSnap $c
    Save-LiveInflight 'VisualFx' $snap0
    $injected = $false
    if ((Get-TweakPending $c) -eq 0) {
        # ayar zaten uygulanmis: uygulamanin gercek etkisini gorebilmek icin once gecici olarak Windows varsayilanina cekilir
        Set-LiveVisualDefaults
        [void](Invoke-LiveRefresh @(@{ T = 'Reg'; Path = 'HKCU\Control Panel\Desktop'; Name = 'UserPreferencesMask' }))
        Wait-LiveSession
        $injected = $true
        Add-LiveRow 'etki' 'gorsel-hazirlik' 'BILGI' (('ayar zaten uygulanm' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + '; etkisini ' + [char]0x00F6 + 'l' + [char]0x00E7 + 'mek i' + [char]0x00E7 + 'in ge' + [char]0x00E7 + 'ici olarak Windows varsay' + [char]0x0131 + 'lan' + [char]0x0131 + 'na ' + [char]0x00E7 + 'ekildi: ') + (Format-LiveSpiSet (Get-LiveSpiSet)))
    }
    $before = Get-LiveSpiSet
    $snapB = Get-LiveSnap $c
    $t0 = Get-Date
    try {
        $r1 = Invoke-LiveJob 'Job_Plan' @{ Steps = $steps; Preview = $false; RestorePoint = $false }
        if ($r1.Err -ne '') { Add-LiveRow 'etki' 'gorsel-uygula' 'HATA' (('uygulama ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r1.Err) }
        Wait-LiveSession
        $after = Get-LiveSpiSet
        $declared = $null
        foreach ($op in @($c.Ops)) { if ([string]$op.Name -eq 'UserPreferencesMask') { $declared = [byte[]]@($op.Value) } }
        $bad = New-Object System.Collections.ArrayList
        if ($null -ne $declared) {
            foreach ($b in $script:LiveMaskBits) {
                $want = [bool](Get-MaskBit $declared $b)
                $have = ([int]$after[[string]$b] -ne 0)
                if ($want -ne $have) { [void]$bad.Add('bit ' + $b + (' (olmas' + [char]0x0131 + ' gereken ') + $want + ', oturumda ' + $have + ')') }
            }
        }
        if ([int]$after['drag'] -ne 0) { [void]$bad.Add(('pencereyi s' + [char]0x00FC + 'r' + [char]0x00FC + 'klerken i' + [char]0x00E7 + 'erik g' + [char]0x00F6 + 'sterme kapanmad' + [char]0x0131 + '')) }
        if ([int]$after['menudelay'] -ne 200) { [void]$bad.Add(('men' + [char]0x00FC + ' gecikmesi ') + $after['menudelay'] + (' (olmas' + [char]0x0131 + ' gereken 200)')) }
        if ($bad.Count -gt 0) { Add-LiveRow 'etki' 'gorsel-uygula' 'HATA' (('ayar kaydedildi ama ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oturuma yans' + [char]0x0131 + 'mad' + [char]0x0131 + ' (kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'n ' + [char]0x015F + 'ik' + [char]0x00E2 + 'yeti): ') + ($bad -join '; ')) }
        else { Add-LiveRow 'etki' 'gorsel-uygula' 'OK' (('' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oturum an' + [char]0x0131 + 'nda de' + [char]0x011F + 'i' + [char]0x015F + 'ti: ') + (Format-LiveSpiSet $after)) }
        $jf = Get-LiveJournalAfter $t0
        if ($jf -eq '') { Add-LiveRow 'etki' 'gorsel-geri' 'HATA' (('geri alma g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + ' (uygulama ') + $(if ($r1.Err -eq '') { [string]$r1.Out.Changes } else { '?' }) + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yapt' + [char]0x0131 + ')')) }
        else {
            $r2 = Invoke-LiveJob 'Job_Undo' @{ File = $jf }
            if ($r2.Err -ne '') { Add-LiveRow 'etki' 'gorsel-geri' 'HATA' (('geri alma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r2.Err) }
        }
        Wait-LiveSession
        $back = Get-LiveSpiSet
        $bad2 = New-Object System.Collections.ArrayList
        foreach ($k in @($before.Keys)) { if ([int]$before[$k] -ne [int]$back[$k]) { [void]$bad2.Add($k + (' (' + [char]0x00F6 + 'nce ') + $before[$k] + ', sonra ' + $back[$k] + ')') } }
        $d2 = Compare-LiveSnap $snapB (Get-LiveSnap $c)
        if ($bad2.Count -gt 0 -or $d2.Count -gt 0) {
            Add-LiveRow 'etki' 'gorsel-geri' 'HATA' (('geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'nca eski h' + [char]0x00E2 + 'le d' + [char]0x00F6 + 'nmedi: oturum [') + ($bad2 -join '; ') + ('] kay' + [char]0x0131 + 't [') + ($d2 -join '; ') + ']')
        } elseif ($jf -ne '') { Add-LiveRow 'etki' 'gorsel-geri' 'OK' ('geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'nca ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'an oturum ve kay' + [char]0x0131 + 't defteri eski haline d' + [char]0x00F6 + 'nd' + [char]0x00FC + '') }
        # son durum: denetimden onceki hal (hazirlik yapildiysa ayarin uygulanmis hali) geri yazilir ve oturuma uygulanir
        if ($injected -or $bad2.Count -gt 0 -or $d2.Count -gt 0) {
            Restore-LiveSnap (ConvertTo-LiveSerial $snap0)
            try { [void](Invoke-LiveRefresh @(@{ T = 'Reg'; Path = 'HKCU\Control Panel\Desktop'; Name = 'UserPreferencesMask' })) } catch { }
            Wait-LiveSession
            $dz = Compare-LiveSnap $snap0 (Get-LiveSnap $c)
            if ($dz.Count -gt 0) { Add-LiveRow 'etki' 'gorsel-son' 'HATA' (('denetim ' + [char]0x00F6 + 'ncesi hale d' + [char]0x00F6 + 'n' + [char]0x00FC + 'lemedi: ') + ($dz -join '; ')) }
            else { Add-LiveRow 'etki' 'gorsel-son' 'OK' ('denetim ' + [char]0x00F6 + 'ncesi hale d' + [char]0x00F6 + 'n' + [char]0x00FC + 'ld' + [char]0x00FC + '') }
        }
        Clear-LiveInflight
    } catch {
        try { Restore-LiveSnap (ConvertTo-LiveSerial $snap0); [void](Invoke-LiveRefresh @(@{ T = 'Reg'; Path = 'HKCU\Control Panel\Desktop'; Name = 'UserPreferencesMask' })); Clear-LiveInflight } catch { }
        Add-LiveRow 'etki' 'gorsel' 'HATA' (('deneme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message)
    }
}

# ---------------- guc kipi ve guc plani ----------------
function Test-LivePower {
    $mode = Get-LiveMode
    if (-not (Initialize-SysNative)) { Add-LiveRow 'etki' 'guc' 'HATA' ('yerel i' + [char]0x015F + 'levler y' + [char]0x00FC + 'klenemedi'); return }
    $modern = Test-PwModernStandby
    $cur = Get-PwModeInfo
    $act = $null
    try { $act = Get-PwActive } catch { }
    Add-LiveRow 'etki' 'guc-durum' 'BILGI' ('Modern Bekleme=' + $modern + ('; g' + [char]0x00FC + '' + [char]0x00E7 + ' kipi=') + $(if ($cur.Ok) { [string]$cur.Name } else { ('okunamad' + [char]0x0131 + '') }) + '; etkin plan=' + $(if ($null -ne $act) { [string]$act.Name } else { '?' }))
    $keys = @('High', 'Saver', 'Balanced')
    if ($mode -ne 'tam') {
        foreach ($k in $keys) {
            $r = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-PowerSetSteps $k); Preview = $true; RestorePoint = $false }
            if ($r.Err -ne '') { Add-LiveRow 'etki' ('guc-onizleme-' + $k) 'HATA' (('' + [char]0x00F6 + 'nizleme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r.Err) }
            else { Add-LiveRow 'etki' ('guc-onizleme-' + $k) 'OK' ([string]$r.Out.Changes + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik, ') + [string]$r.Out.Skipped + (' atlanan ' + [char]0x00F6 + 'nizlendi')) }
        }
        $now = Get-PwModeInfo
        if ($cur.Ok -and $now.Ok -and [string]$cur.Guid -ne [string]$now.Guid) { Add-LiveRow 'etki' 'guc-onizleme' 'HATA' ('' + [char]0x00F6 + 'nizleme g' + [char]0x00FC + '' + [char]0x00E7 + ' kipini de' + [char]0x011F + 'i' + [char]0x015F + 'tirdi') }
        return
    }
    # gercek tur: her plan icin uygula -> sistemden oku -> geri al -> eski haline donmus mu
    $snapP = Get-LiveFuncSnap 'PowerPlan'
    $snapM = Get-LiveFuncSnap 'PowerMode'
    Save-LiveInflight 'PowerPlan' @($snapP, $snapM)
    try {
        foreach ($k in $keys) {
            $t0 = Get-Date
            $mk = Get-LiveLogMark
            $r1 = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-PowerSetSteps $k); Preview = $false; RestorePoint = $false }
            $lines = Get-LiveLogSince $mk
            if ($r1.Err -ne '') { Add-LiveRow 'etki' ('guc-' + $k) 'HATA' (('uygulama ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r1.Err); continue }
            $errs = Select-LiveLines $lines 'ERR'
            $nowMode = Get-PwModeInfo
            $nowAct = $null; try { $nowAct = Get-PwActive } catch { }
            $okNow = $false; $seen = ''
            if ($modern -and (Get-PwModeKeyFor $k) -ne '') {
                $okNow = ($nowMode.Ok -and [string]$nowMode.Key -eq (Get-PwModeKeyFor $k))
                $seen = 'kip=' + $(if ($nowMode.Ok) { [string]$nowMode.Name } else { ('okunamad' + [char]0x0131 + '') })
            } else {
                $okNow = ($null -ne $nowAct -and [string]$nowAct.Guid -eq [string]$script:PwKnown[$k].Guid)
                $seen = 'plan=' + $(if ($null -ne $nowAct) { [string]$nowAct.Name } else { '?' })
            }
            if (-not $okNow) {
                $why = ''
                if ($errs.Count -gt 0) { $why = ' | ' + (Get-LiveShort (($errs | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+ERR\s+', '') }) -join ' | ') 220) }
                # uretici guc yazilimi ya da kurum ilkesi kipi kilitleyebilir: uygulama bunu acikca soylemeli, sessiz kalmamali
                $explains = ($errs.Count -gt 0 -and (($errs -join ' ') -match ('kilitl|do' + [char]0x011F + 'rulanamad' + [char]0x0131 + '|de' + [char]0x011F + 'i' + [char]0x015F + 'tirmedi')))
                if ($explains) { Add-LiveRow 'etki' ('guc-' + $k) 'UYARI' (('Windows kipi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmedi, uygulama nedenini s' + [char]0x00F6 + 'yl' + [char]0x00FC + 'yor; ') + $seen + $why) }
                else { Add-LiveRow 'etki' ('guc-' + $k) 'HATA' (('g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + ' uyguland' + [char]0x0131 + ' denildi ama sistem de' + [char]0x011F + 'i' + [char]0x015F + 'medi (') + $seen + ')' + $why) }
            } else { Add-LiveRow 'etki' ('guc-' + $k) 'OK' (('sistem ger' + [char]0x00E7 + 'ekten ') + $seen + ' oldu') }
            $jf = Get-LiveJournalAfter $t0
            if ($jf -ne '') {
                $r2 = Invoke-LiveJob 'Job_Undo' @{ File = $jf }
                if ($r2.Err -ne '') { Add-LiveRow 'etki' ('guc-geri-' + $k) 'HATA' (('geri alma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r2.Err) }
            }
        }
        $dP = Compare-LiveItem $snapP (Get-LiveFuncSnap 'PowerPlan')
        $dM = Compare-LiveItem $snapM (Get-LiveFuncSnap 'PowerMode')
        if ($dP -ne '' -or $dM -ne '') {
            Add-LiveRow 'etki' 'guc-geri' 'HATA' (('geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'nca g' + [char]0x00FC + '' + [char]0x00E7 + ' ayar' + [char]0x0131 + ' eski haline d' + [char]0x00F6 + 'nmedi: ') + $dP + ' ' + $dM)
            Restore-LiveFunc $snapP; Restore-LiveFunc $snapM
        } else { Add-LiveRow 'etki' 'guc-geri' 'OK' ('g' + [char]0x00FC + '' + [char]0x00E7 + ' kipi ve etkin plan eski haline d' + [char]0x00F6 + 'nd' + [char]0x00FC + '') }
        Clear-LiveInflight
    } catch {
        try { Restore-LiveFunc $snapP; Restore-LiveFunc $snapM; Clear-LiveInflight } catch { }
        Add-LiveRow 'etki' 'guc' 'HATA' (('deneme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message)
    }
}

# ---------------- "Windows geri aldi" yolu: sapma tespiti ve Duzelt dugmesi ----------------
function Test-LiveDrift {
    $mode = Get-LiveMode
    $d0 = Get-DriftedIds
    Add-LiveRow 'sapma' 'durum' 'BILGI' (('deneme veri klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nde geri d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nen ayar: ') + $d0.Count + $(if ($d0.Count -gt 0) { ' [' + ($d0 -join ', ') + ']' } else { '' }))
    $id = 'Transparency'
    $c = Get-CatalogItem $id
    if ($null -eq $c) { Add-LiveRow 'sapma' $id 'ATLA' ('deneme ayar' + [char]0x0131 + ' katalogda yok'); return }
    if ($mode -ne 'tam') { Add-LiveRow 'sapma' 'duzelt' 'ATLA' ('' + [char]0x201C + 'D' + [char]0x00FC + 'zelt' + [char]0x201D + ' ak' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' ger' + [char]0x00E7 + 'ek ayar yazar; yaln' + [char]0x0131 + 'zca tam kipte (y' + [char]0x00F6 + 'netici) denenir'); return }
    $snap0 = Get-LiveSnap $c
    $set0 = Get-AppliedIds
    Save-LiveInflight $id $snap0
    try {
        # 1) ayari uygula; "uygulananlar" listesine girmeli
        $r1 = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-StepsFromIds @($id)); Preview = $false; RestorePoint = $false }
        if ($r1.Err -ne '') { Add-LiveRow 'sapma' 'uygula' 'HATA' (('uygulama ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r1.Err); return }
        if ((Get-TweakPending $c) -ne 0) { Add-LiveRow 'sapma' 'uygula' 'HATA' ('ayar uygulanamad' + [char]0x0131 + ', sapma denemesi yap' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor'); return }
        $apNow = Get-AppliedIds
        if ($apNow -notcontains $id) { Add-LiveRow 'sapma' 'kayit' 'HATA' ('ayar uyguland' + [char]0x0131 + ' ama uygulananlar listesine girmedi'); return }
        Add-LiveRow 'sapma' 'kayit' 'OK' ('uygulanan ayar ' + [char]0x201C + 'uygulananlar' + [char]0x201D + ' listesine girdi')
        # 2) Windows geri aliyor: deger disaridan eski haline cevrilir
        $op = @($c.Ops)[0]
        $orig = $snap0[0].Raw
        # ayar denetimden once zaten uygulanmissa eski deger hedefle aynidir; Windows'un geri almasi hedeften farkli bir degerle taklit edilir
        $target = [int64]$op.Value
        $driftV = [int64]1
        if ($target -ne 0) { $driftV = [int64]0 }
        if ($orig.Exists -and [string]$orig.Kind -eq 'DWord' -and [int64]$orig.Data -ne $target) { $driftV = [int64]$orig.Data }
        Set-RegData ([string]$op.Path) ([string]$op.Name) 'DWord' $driftV
        $drNow = Get-DriftedIds
        if ($drNow -notcontains $id) { Add-LiveRow 'sapma' 'tespit' 'HATA' ('de' + [char]0x011F + 'er d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + 'dan eski haline ' + [char]0x00E7 + 'evrildi ama ' + [char]0x201C + 'Windows geri ald' + [char]0x0131 + '' + [char]0x201D + ' tespiti ayar' + [char]0x0131 + ' bulamad' + [char]0x0131 + ''); return }
        Add-LiveRow 'sapma' 'tespit' 'OK' ('d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + 'dan geri al' + [char]0x0131 + 'nan ayar ' + [char]0x201C + 'geri d' + [char]0x00F6 + 'nm' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x201D + ' olarak bulundu')
        # 3) saglik bulgusu ve "Duzelt" eylemi
        $fix = $null
        try {
            $script:Findings = New-Object System.Collections.ArrayList
            Chk_Drift
            $h = @($script:Findings | Where-Object { [string]$_.Id -eq 'drift' })
            if ($h.Count -ge 1) { $fix = $h[0].Fix }
        } catch { Add-LiveRow 'sapma' 'bulgu' 'HATA' (('Chk_Drift ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message) }
        if ($null -eq $fix) { Add-LiveRow 'sapma' 'bulgu' 'HATA' ('geri d' + [char]0x00F6 + 'nen ayar i' + [char]0x00E7 + 'in sa' + [char]0x011F + 'l' + [char]0x0131 + 'k bulgusu ya da ' + [char]0x201C + 'D' + [char]0x00FC + 'zelt' + [char]0x201D + ' eylemi ' + [char]0x00FC + 'retilmedi'); return }
        Add-LiveRow 'sapma' 'bulgu' 'OK' (('bulgu ve eylem var: ' + [char]0x201C + '') + [string]$fix.Label + ('' + [char]0x201D + ' (') + [string]$fix.Kind + ')')
        # 4) Duzelt'e basmak = Job_FixAll
        $fx = Invoke-LiveJob 'Job_FixAll' @{ Fixes = @($fix); Preview = $false; RestorePoint = $false }
        if ($fx.Err -ne '') { Add-LiveRow 'sapma' 'duzelt' 'HATA' (('d' + [char]0x00FC + 'zeltme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $fx.Err); return }
        $pend = Get-TweakPending $c
        $still = Get-DriftedIds
        if ($pend -ne 0 -or $still -contains $id) { Add-LiveRow 'sapma' 'duzelt' 'HATA' (('' + [char]0x201C + 'D' + [char]0x00FC + 'zelt' + [char]0x201D + ' ayar' + [char]0x0131 + ' d' + [char]0x00FC + 'zeltmedi (kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'n' + [char]0x0131 + 'n ' + [char]0x015F + 'ik' + [char]0x00E2 + 'yeti): ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm=') + $pend + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik=') + [string]$fx.Out.Changes + ' hata=' + [string]$fx.Out.Errors) }
        else { Add-LiveRow 'sapma' 'duzelt' 'OK' (('geri d' + [char]0x00F6 + 'nen ayar yeniden uyguland' + [char]0x0131 + ' ve do' + [char]0x011F + 'ruland' + [char]0x0131 + ' (de' + [char]0x011F + 'i' + [char]0x015F + 'iklik=') + [string]$fx.Out.Changes + ')') }
    } catch {
        Add-LiveRow 'sapma' $id 'HATA' (('deneme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message)
    } finally {
        try {
            Restore-LiveSnap (ConvertTo-LiveSerial $snap0)
            Save-AppliedIds $set0
            Clear-LiveInflight
        } catch { }
    }
}

# ---------------- araclar ----------------
function Get-LiveSandbox([string]$Name) {
    $d = Join-Path (Join-Path ([System.IO.Path]::GetTempPath()) 'Multimizer-duman-kum') $Name
    try { if (Test-Path -LiteralPath $d) { Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue } } catch { }
    [void](New-Item -ItemType Directory -Path $d -Force)
    return $d
}

function Test-LivePassword {
    $x = Import-MmExt 'Parola'
    if ($x.Ok -ne $true) { Add-LiveRow 'arac' 'parola' 'HATA' (('parola eklentisi y' + [char]0x00FC + 'klenemedi: ') + [string]$x.Error); return }
    $bad = New-Object System.Collections.ArrayList
    $combos = @(@($false, $false, $false), @($true, $false, $false), @($true, $true, $false), @($true, $true, $true), @($false, $false, $true))
    foreach ($cb in $combos) {
        $sets = Get-PasswordSets $cb[0] $cb[1] $cb[2]
        $pool = ($sets -join '')
        foreach ($len in @(8, 12, 20, 33, 64)) {
            for ($n = 0; $n -lt 40; $n++) {
                $pw = New-RandomPassword $len $sets
                if ($pw.Length -ne $len) { [void]$bad.Add('uzunluk ' + $pw.Length + ' (istenen ' + $len + ')'); continue }
                foreach ($ch in $pw.ToCharArray()) { if ($pool.IndexOf($ch) -lt 0) { [void]$bad.Add(('havuz d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + ' karakter: ') + $ch); break } }
                foreach ($s in $sets) { $hit = $false; foreach ($ch in $pw.ToCharArray()) { if ($s.IndexOf($ch) -ge 0) { $hit = $true; break } }; if (-not $hit) { [void]$bad.Add(('k' + [char]0x00FC + 'me eksik (') + $s.Substring(0, 3) + '...)'); break } }
            }
        }
    }
    # tekrar ve dagilim
    $sets = Get-PasswordSets $true $true $true
    # PowerShell sozlukleri buyuk/kucuk harfi ayirmaz; karakter sayimi icin sirali (ordinal) karsilastirici gerekir
    $seen = New-Object System.Collections.Hashtable ([System.StringComparer]::Ordinal); $dup = 0
    $freq = New-Object System.Collections.Hashtable ([System.StringComparer]::Ordinal)
    $pool = ($sets -join '')
    foreach ($ch in $pool.ToCharArray()) { $freq[[string]$ch] = 0 }
    $total = 0
    for ($n = 0; $n -lt 400; $n++) {
        $pw = New-RandomPassword 24 $sets
        if ($seen.ContainsKey($pw)) { $dup++ } else { $seen[$pw] = $true }
        foreach ($ch in $pw.ToCharArray()) { $freq[[string]$ch] = [int]$freq[[string]$ch] + 1; $total++ }
    }
    if ($dup -gt 0) { [void]$bad.Add($dup + ' tekrar eden parola') }
    $exp = $total / [double]$pool.Length
    $worst = 0.0
    foreach ($k in @($freq.Keys)) { $dev = [math]::Abs([double]$freq[$k] - $exp) / $exp; if ($dev -gt $worst) { $worst = $dev } }
    if ($worst -gt 0.6) { [void]$bad.Add(('karakter da' + [char]0x011F + '' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + ' dengesiz (en b' + [char]0x00FC + 'y' + [char]0x00FC + 'k sapma %') + [int]($worst * 100) + ')') }
    # uzunluk sinirlari
    if ((New-RandomPassword 3 (Get-PasswordSets $true $true $true)).Length -ne 8) { [void]$bad.Add(('' + [char]0x00E7 + 'ok k' + [char]0x0131 + 'sa istek 8 karaktere y' + [char]0x00FC + 'kseltilmedi')) }
    if ((New-RandomPassword 500 (Get-PasswordSets $true $true $true)).Length -ne 64) { [void]$bad.Add(('' + [char]0x00E7 + 'ok uzun istek 64 karaktere indirilmedi')) }
    $bits = Get-PasswordBits 20 $true $true $true
    if ($bits -lt 100 -or $bits -gt 140) { [void]$bad.Add(('entropi hesab' + [char]0x0131 + ' beklenmedik: ') + $bits) }
    if ($bad.Count -gt 0) { Add-LiveRow 'arac' 'parola' 'HATA' ((@($bad | Select-Object -First 6)) -join '; ') }
    else { Add-LiveRow 'arac' 'parola' 'OK' (('5 k' + [char]0x00FC + 'me birle' + [char]0x015F + 'imi ' + [char]0x00D7 + ' 5 uzunluk ' + [char]0x00D7 + ' 40 parola do' + [char]0x011F + 'ru; 400 parolada tekrar yok, karakter da' + [char]0x011F + '' + [char]0x0131 + 'l' + [char]0x0131 + 'm' + [char]0x0131 + ' dengeli (en b' + [char]0x00FC + 'y' + [char]0x00FC + 'k sapma %') + [int]($worst * 100) + ('); 20 karakter ' + [char]0x2248 + ' ') + $bits + ' bit') }
}

function Test-LiveRename {
    $dir = Get-LiveSandbox 'adlandir'
    $names = @('IMG_0001.jpg', 'IMG_0002.jpg', 'Tatil Raporu.docx', ('' + [char]0x00C7 + 'OK  bo' + [char]0x015F + 'luk__ve_' + [char]0x00E7 + 'izgi.txt'), 'UPPER.TXT', 'a.txt', 'b.txt', 'noext')
    foreach ($n in $names) { [System.IO.File]::WriteAllText((Join-Path $dir $n), $n, [System.Text.Encoding]::UTF8) }
    (Get-Item -LiteralPath (Join-Path $dir 'a.txt')).LastWriteTime = [datetime]'2024-03-05 10:00'
    $bad = New-Object System.Collections.ArrayList
    $why = Test-RenameDirAllowed $dir
    if ($why -ne '') { Add-LiveRow 'arac' 'adlandir' 'HATA' (('ge' + [char]0x00E7 + 'ici klas' + [char]0x00F6 + 'r reddedildi: ') + $why); return }
    $scan = Invoke-LiveJob 'Job_RenameScan' @{ Dir = $dir }
    if ($scan.Err -ne '' -or $scan.Out.Ok -ne $true) { Add-LiveRow 'arac' 'adlandir' 'HATA' (('klas' + [char]0x00F6 + 'r taramas' + [char]0x0131 + ' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $scan.Err + ' ' + [string]$scan.Out.Error); return }
    $items = @($scan.Out.Items)
    if ($items.Count -ne $names.Count) { [void]$bad.Add('tarama ' + $items.Count + ' dosya buldu, ' + $names.Count + ' bekleniyordu') }
    $existing = @(Get-ChildItem -LiteralPath $dir -File | ForEach-Object { $_.Name })
    # kuralli onizlemeler
    $p1 = Get-RenamePlan $items 'Number' 'Tatil' $existing
    if ($p1.Changes -ne $names.Count -or $p1.Problems -ne 0) { [void]$bad.Add(('numaraland' + [char]0x0131 + 'rma: ') + $p1.Changes + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik, ') + $p1.Problems + ' sorun') }
    $p2 = Get-RenamePlan $items 'Replace' 'IMG_=>Foto ' $existing
    $row = @($p2.Rows | Where-Object { $_.Old -eq 'IMG_0001.jpg' })
    if ($row.Count -ne 1 -or $row[0].New -ne 'Foto 0001.jpg') { [void]$bad.Add(('de' + [char]0x011F + 'i' + [char]0x015F + 'tir: ') + $(if ($row.Count -eq 1) { $row[0].New } else { ('sat' + [char]0x0131 + 'r yok') })) }
    $p3 = Get-RenamePlan $items 'Lower' '' $existing
    $row = @($p3.Rows | Where-Object { $_.Old -eq 'UPPER.TXT' })
    if ($row.Count -ne 1 -or $row[0].New -ne 'upper.txt') { [void]$bad.Add(('k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k harf: ') + $(if ($row.Count -eq 1) { $row[0].New } else { ('sat' + [char]0x0131 + 'r yok') })) }
    $p4 = Get-RenamePlan $items 'Dash' '' $existing
    $row = @($p4.Rows | Where-Object { $_.Old -eq 'Tatil Raporu.docx' })
    if ($row.Count -ne 1 -or $row[0].New -ne 'Tatil-Raporu.docx') { [void]$bad.Add('tire: ' + $(if ($row.Count -eq 1) { $row[0].New } else { ('sat' + [char]0x0131 + 'r yok') })) }
    $p5 = Get-RenamePlan $items 'DatePrefix' '' $existing
    $row = @($p5.Rows | Where-Object { $_.Old -eq 'a.txt' })
    if ($row.Count -ne 1 -or $row[0].New -ne '2024-03-05 a.txt') { [void]$bad.Add(('tarih ' + [char]0x00F6 + 'neki: ') + $(if ($row.Count -eq 1) { $row[0].New } else { ('sat' + [char]0x0131 + 'r yok') })) }
    # cakisma: a.txt ve b.txt ayni adi alirsa sorun isaretlenmeli
    $p6 = Get-RenamePlan @(@{ Name = 'a.txt'; Time = (Get-Date) }, @{ Name = 'b.txt'; Time = (Get-Date) }) 'Replace' 'a=>x' @('a.txt', 'b.txt', 'x.txt')
    if ($p6.Problems -lt 1) { [void]$bad.Add(('klas' + [char]0x00F6 + 'rde var olan adla ' + [char]0x00E7 + 'ak' + [char]0x0131 + '' + [char]0x015F + 'ma sorun say' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
    # gercek uygulama + geri alma (gecici klasorde, motorun kendi yolu)
    $before = (@(Get-ChildItem -LiteralPath $dir -File | ForEach-Object { $_.Name } | Sort-Object)) -join '|'
    $pairs = @($p1.Rows | ForEach-Object { @{ Old = [string]$_.Old; New = [string]$_.New } })
    $t0 = Get-Date
    $r1 = Invoke-LiveJob 'Job_Plan' @{ Steps = @(@{ Id = 'LiveRename'; Title = ('adland' + [char]0x0131 + 'rma denemesi'); Ops = @(@{ T = 'Rename'; Dir = $dir; Pairs = $pairs }); Reboot = $false }); Preview = $false; RestorePoint = $false }
    if ($r1.Err -ne '' -or [int]$r1.Out.Errors -gt 0) { [void]$bad.Add('uygulama hata verdi: ' + $r1.Err) }
    $mid = @(Get-ChildItem -LiteralPath $dir -File | ForEach-Object { $_.Name })
    foreach ($row in $p1.Rows) { if ($mid -cnotcontains [string]$row.New) { [void]$bad.Add('yeni ad diskte yok: ' + $row.New) } ; if ($mid -ccontains [string]$row.Old -and [string]$row.Old -cne [string]$row.New) { [void]$bad.Add(('eski ad h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' duruyor: ') + $row.Old) } }
    # icerik kaybolmadi mi
    foreach ($row in $p1.Rows) { $f = Join-Path $dir ([string]$row.New); if (Test-Path -LiteralPath $f) { $txt = [System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8); if ($txt -cne [string]$row.Old) { [void]$bad.Add(('i' + [char]0x00E7 + 'erik de' + [char]0x011F + 'i' + [char]0x015F + 'ti: ') + $row.New) } } }
    $jf = Get-LiveJournalAfter $t0
    if ($jf -eq '') { [void]$bad.Add(('geri alma g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
    else {
        $r2 = Invoke-LiveJob 'Job_Undo' @{ File = $jf }
        if ($r2.Err -ne '' -or [int]$r2.Out.Errors -gt 0) { [void]$bad.Add('geri alma hata verdi: ' + $r2.Err) }
        $after = (@(Get-ChildItem -LiteralPath $dir -File | ForEach-Object { $_.Name } | Sort-Object)) -join '|'
        if ($after -cne $before) { [void]$bad.Add(('geri alma eski adlar' + [char]0x0131 + ' d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'rmedi')) }
    }
    # ters yonlu takas (a<->b): iki asamali yeniden adlandirma cakismamali
    $swap = @(@{ Old = 'a.txt'; New = 'b.txt' }, @{ Old = 'b.txt'; New = 'a.txt' })
    $done = @(Invoke-RenamePairs $dir $swap)
    if ($done.Count -ne 2) { [void]$bad.Add('takas ' + $done.Count + (' dosyada yap' + [char]0x0131 + 'ld' + [char]0x0131 + '')) }
    else {
        $ta = [System.IO.File]::ReadAllText((Join-Path $dir 'a.txt')); $tb = [System.IO.File]::ReadAllText((Join-Path $dir 'b.txt'))
        if ($ta -cne 'b.txt' -or $tb -cne 'a.txt') { [void]$bad.Add(('takas i' + [char]0x00E7 + 'erikleri yer de' + [char]0x011F + 'i' + [char]0x015F + 'tirmedi')) }
    }
    # sistem klasoru reddedilir mi
    if ([string]$env:WINDIR -ne '' -and (Test-RenameDirAllowed $env:WINDIR) -eq '') { [void]$bad.Add(('Windows klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nde adland' + [char]0x0131 + 'rmaya izin verildi')) }
    if ([string]$env:SystemDrive -ne '' -and (Test-RenameDirAllowed ($env:SystemDrive + '\')) -eq '') { [void]$bad.Add(('s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' k' + [char]0x00F6 + 'k' + [char]0x00FC + 'nde adland' + [char]0x0131 + 'rmaya izin verildi')) }
    try { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    if ($bad.Count -gt 0) { Add-LiveRow 'arac' 'adlandir' 'HATA' ((@($bad | Select-Object -First 6)) -join '; ') }
    else { Add-LiveRow 'arac' 'adlandir' 'OK' ('tarama, 5 kural, ' + [char]0x00E7 + 'ak' + [char]0x0131 + '' + [char]0x015F + 'ma denetimi, uygulama, geri alma, takas ve sistem klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' reddi do' + [char]0x011F + 'ru')  }
}

function Test-LiveCrypt {
    $x = Import-MmExt 'Sifreleme'
    if ($x.Ok -ne $true) { Add-LiveRow 'arac' 'sifreleme' 'HATA' (('' + [char]0x015F + 'ifreleme eklentisi y' + [char]0x00FC + 'klenemedi: ') + [string]$x.Error); return }
    $dir = Get-LiveSandbox 'sifre'
    $bad = New-Object System.Collections.ArrayList
    $src = Join-Path $dir 'gizli belge.txt'
    $rnd = New-Object byte[] 3000017
    (New-Object System.Random 7).NextBytes($rnd)
    [System.IO.File]::WriteAllBytes($src, $rnd)
    $hash0 = (Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash
    $pw = 'Deneme-Parolasi-2026!'
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $e = Invoke-LiveJob 'Job_Crypt' @{ Mode = 'Enc'; Paths = @($src); Password = $pw }
    $encMs = $sw.ElapsedMilliseconds
    if ($e.Err -ne '' -or $e.Out.Ok -ne $true) { [void]$bad.Add(('' + [char]0x015F + 'ifreleme ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $e.Err); }
    else {
        $enc = [string]@($e.Out.Outputs)[0]
        if (-not (Test-Path -LiteralPath $enc)) { [void]$bad.Add(('' + [char]0x015F + 'ifreli dosya yok')) }
        else {
            $encHash = (Get-FileHash -LiteralPath $enc -Algorithm SHA256).Hash
            if ($encHash -eq $hash0) { [void]$bad.Add(('' + [char]0x015F + 'ifreli dosya a' + [char]0x00E7 + '' + [char]0x0131 + 'k dosyayla ayn' + [char]0x0131 + '')) }
            $bytes = [System.IO.File]::ReadAllBytes($enc)
            if ($bytes.Length -lt $rnd.Length) { [void]$bad.Add(('' + [char]0x015F + 'ifreli dosya beklenenden k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k')) }
            # dogru parola
            Remove-Item -LiteralPath $src -Force
            $sw.Restart()
            $d = Invoke-LiveJob 'Job_Crypt' @{ Mode = 'Dec'; Paths = @($enc); Password = $pw }
            $decMs = $sw.ElapsedMilliseconds
            if ($d.Err -ne '' -or $d.Out.Ok -ne $true) { [void]$bad.Add(('do' + [char]0x011F + 'ru parolayla ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'lemedi: ') + $d.Err) }
            else {
                $dec = [string]@($d.Out.Outputs)[0]
                if ((Get-FileHash -LiteralPath $dec -Algorithm SHA256).Hash -ne $hash0) { [void]$bad.Add(('' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'len dosya ' + [char]0x00F6 + 'zg' + [char]0x00FC + 'n dosyayla ayn' + [char]0x0131 + ' de' + [char]0x011F + 'il')) }
            }
            # yanlis parola (uygulama bu reddi gunluge ERR olarak yazar: beklenen satir)
            Add-SmokeExpect (': Parola yanl' + [char]0x0131 + '' + [char]0x015F + ' ya da dosya de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmi' + [char]0x015F + '') 1 ('yanl' + [char]0x0131 + '' + [char]0x015F + ' parola reddi g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')
            $w = Invoke-LiveJob 'Job_Crypt' @{ Mode = 'Dec'; Paths = @($enc); Password = 'Yanlis-Parola-1234' }
            if ($w.Err -eq '' -and $w.Out.Ok -eq $true) { [void]$bad.Add(('yanl' + [char]0x0131 + '' + [char]0x015F + ' parolayla ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'ld' + [char]0x00FC + '')) }
            # bozulmus dosya
            Add-SmokeExpect ('bozuk\.mmz: Parola yanl' + [char]0x0131 + '' + [char]0x015F + ' ya da dosya de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmi' + [char]0x015F + '') 1 ('bozulmu' + [char]0x015F + ' dosya reddi g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')
            $bytes[$bytes.Length - 40] = [byte](($bytes[$bytes.Length - 40] + 1) -band 255)
            $tam = Join-Path $dir 'bozuk.mmz'
            [System.IO.File]::WriteAllBytes($tam, $bytes)
            $t = Invoke-LiveJob 'Job_Crypt' @{ Mode = 'Dec'; Paths = @($tam); Password = $pw }
            if ($t.Err -eq '' -and $t.Out.Ok -eq $true) { [void]$bad.Add(('bozulmu' + [char]0x015F + ' dosya fark edilmedi')) }
            # kisa parola reddedilir
            Add-SmokeExpect ('Parola en az 8 karakter olmal' + [char]0x0131 + '') 1 ('k' + [char]0x0131 + 'sa parola reddi g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')
            $s = Invoke-LiveJob 'Job_Crypt' @{ Mode = 'Enc'; Paths = @($dec); Password = 'kisa' }
            if ($s.Err -eq '' -and $s.Out.Ok -eq $true) { [void]$bad.Add(('8 karakterden k' + [char]0x0131 + 'sa parola kabul edildi')) }
            if ($encMs -gt 20000 -or $decMs -gt 20000) { [void]$bad.Add(('3 MB i' + [char]0x00E7 + 'in ') + (Format-LiveMs $encMs) + ' / ' + (Format-LiveMs $decMs) + (' s' + [char]0x00FC + 'rd' + [char]0x00FC + ' (' + [char]0x00E7 + 'ok yava' + [char]0x015F + ')')) }
        }
    }
    try { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    if ($bad.Count -gt 0) { Add-LiveRow 'arac' 'sifreleme' 'HATA' ((@($bad | Select-Object -First 6)) -join '; ') }
    else { Add-LiveRow 'arac' 'sifreleme' 'OK' (('3 MB ' + [char]0x015F + 'ifrelendi (') + (Format-LiveMs $encMs) + ('), do' + [char]0x011F + 'ru parolayla aynen ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'ld' + [char]0x00FC + ' (') + (Format-LiveMs $decMs) + ('); yanl' + [char]0x0131 + '' + [char]0x015F + ' parola, bozulmu' + [char]0x015F + ' dosya ve k' + [char]0x0131 + 'sa parola reddedildi')) }
}

function Test-LiveSecureDelete {
    $x = Import-MmExt 'GuvenliSilme'
    if ($x.Ok -ne $true) { Add-LiveRow 'arac' 'guvenli-silme' 'HATA' (('g' + [char]0x00FC + 'venli silme eklentisi y' + [char]0x00FC + 'klenemedi: ') + [string]$x.Error); return }
    $dir = Get-LiveSandbox 'silme'
    $bad = New-Object System.Collections.ArrayList
    $f1 = Join-Path $dir 'bir.bin'; $f2 = Join-Path $dir 'salt okunur.txt'; $sub = Join-Path $dir 'alt klasor'
    [void](New-Item -ItemType Directory -Path $sub -Force)
    $f3 = Join-Path $sub 'ic.dat'
    [System.IO.File]::WriteAllBytes($f1, (New-Object byte[] 100000))
    [System.IO.File]::WriteAllText($f2, 'salt okunur')
    (Get-Item -LiteralPath $f2).IsReadOnly = $true
    [System.IO.File]::WriteAllText($f3, ('i' + [char]0x00E7 + ' dosya'))
    # alternatif veri akisi
    try { Set-Content -LiteralPath $f1 -Stream 'gizli' -Value ('ads i' + [char]0x00E7 + 'erik') -ErrorAction Stop } catch { }
    $r = Invoke-LiveJob 'Job_SecureDelete' @{ Paths = @($f1, $f2, $sub); Passes = 1 }
    if ($r.Err -ne '') { [void]$bad.Add(('silme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r.Err) }
    else {
        if ($r.Out.Files -lt 3) { [void]$bad.Add(('yaln' + [char]0x0131 + 'zca ') + $r.Out.Files + ' dosya silindi (3 bekleniyordu)') }
        if ($r.Out.Failed -gt 0) { [void]$bad.Add($r.Out.Failed + ' dosya silinemedi') }
    }
    foreach ($p in @($f1, $f2, $f3, $sub)) { if (Test-Path -LiteralPath $p) { [void]$bad.Add(('h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' duruyor: ') + (Split-Path -Leaf $p)) } }
    # korumali yollar reddedilmeli. Silme isine ASLA verilmez: yalnizca silme yapmayan koruma sorgusu cagrilir
    $guard = New-Object System.Collections.ArrayList
    foreach ($v in @($env:WINDIR, $env:ProgramFiles, $env:ProgramData, $env:USERPROFILE, $(if ([string]$env:SystemDrive -ne '') { $env:SystemDrive + '\' } else { '' }), $(if ([string]$env:WINDIR -ne '') { Join-Path $env:WINDIR 'System32' } else { '' }))) {
        if ([string]$v -eq '') { continue }
        [void]$guard.Add([string]$v)
        if ((Test-SecureDeleteAllowed ([string]$v)) -eq '') { [void]$bad.Add(('korumas' + [char]0x0131 + 'z yol: ') + [string]$v) }
    }
    try { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    if ($bad.Count -gt 0) { Add-LiveRow 'arac' 'guvenli-silme' 'HATA' ((@($bad | Select-Object -First 6)) -join '; ') }
    else { Add-LiveRow 'arac' 'guvenli-silme' 'OK' (('dosya, salt okunur dosya, alt ak' + [char]0x0131 + '' + [char]0x015F + 'l' + [char]0x0131 + ' dosya ve klas' + [char]0x00F6 + 'r silindi; ') + [string]$guard.Count + (' korumal' + [char]0x0131 + ' yol (Windows, Program Files, s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' k' + [char]0x00F6 + 'k' + [char]0x00FC + '...) reddedildi')) }
}

function Test-LiveMemory {
    $x = Import-MmExt 'Bellek'
    if ($x.Ok -ne $true) { Add-LiveRow 'arac' 'bellek' 'HATA' (('bellek eklentisi y' + [char]0x00FC + 'klenemedi: ') + [string]$x.Error); return }
    $r = Invoke-LiveJob 'Job_MemTrim' @{ Standby = $false }
    if ($r.Err -ne '') { Add-LiveRow 'arac' 'bellek' 'HATA' (('bellek bo' + [char]0x015F + 'altma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r.Err); return }
    if ($r.Out.Ok -ne $true) { Add-LiveRow 'arac' 'bellek' 'HATA' ('bellek bo' + [char]0x015F + 'altma ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z d' + [char]0x00F6 + 'nd' + [char]0x00FC + ''); return }
    $m = ('i' + [char]0x015F + 'lem=') + [string]$r.Out.Count + ('; bo' + [char]0x015F + ' bellek ') + [int]$r.Out.Before + (' ' + [char]0x2192 + ' ') + [int]$r.Out.After + ' MB'
    if ([int]$r.Out.Count -lt 5) { Add-LiveRow 'arac' 'bellek' 'UYARI' (('' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'ma k' + [char]0x00FC + 'mesi bo' + [char]0x015F + 'alt' + [char]0x0131 + 'lan i' + [char]0x015F + 'lem say' + [char]0x0131 + 's' + [char]0x0131 + ' ' + [char]0x00E7 + 'ok az: ') + $m) }
    else { Add-LiveRow 'arac' 'bellek' 'OK' $m }
}

function Test-LiveTools {
    Test-LivePassword
    Test-LiveRename
    Test-LiveCrypt
    Test-LiveSecureDelete
    Test-LiveMemory
}

# ---------------- okuma amacli arka plan isleri: gercek bilgisayarda calisiyor mu ----------------
function Get-LiveResultSummary($Out) {
    if ($null -eq $Out) { return ('sonu' + [char]0x00E7 + ' bo' + [char]0x015F + '') }
    if ($Out -is [hashtable]) {
        $parts = New-Object System.Collections.ArrayList
        foreach ($k in @($Out.Keys | Sort-Object)) {
            $v = $Out[$k]
            if ($v -is [System.Array] -or $v -is [System.Collections.ArrayList]) { [void]$parts.Add([string]$k + '=' + @($v).Count) }
            elseif ($v -is [hashtable]) { [void]$parts.Add([string]$k + '={' + @($v.Keys).Count + '}') }
            elseif ($v -is [bool]) { [void]$parts.Add([string]$k + '=' + $v) }
            elseif ($v -is [string] -and $v.Length -le 24) { [void]$parts.Add([string]$k + '=' + $v) }
            elseif ($v -is [ValueType]) { [void]$parts.Add([string]$k + '=' + [string]$v) }
        }
        return ((@($parts | Select-Object -First 8)) -join ' ')
    }
    if ($Out -is [System.Array]) { return ('dizi ' + @($Out).Count) }
    return ([string]$Out.GetType().Name)
}

function Get-LiveReadJobs {
    $kum = Get-LiveSandbox 'is'
    [System.IO.File]::WriteAllText((Join-Path $kum 'ornek.txt'), 'ornek')
    [System.IO.File]::WriteAllText((Join-Path $kum 'ornek2.txt'), 'ornek')
    $ownIp = ''
    try { $ownIp = [string](@(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction Stop | Where-Object { $_.IPAddress -match '^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)' } | Select-Object -First 1 -ExpandProperty IPAddress)[0]) } catch { }
    $list = New-Object System.Collections.ArrayList
    $add = { param($fn, $arg, $grp, $slow) [void]$list.Add(@{ Fn = $fn; Arg = $arg; Group = $grp; Slow = [bool]$slow }) }
    # sistem
    foreach ($f in @('Job_PcInfo', 'Job_PowerInfo', 'Job_PowerStates', 'Job_PowerPreview', 'Job_Inventory', 'Job_Procs', 'Job_Services', 'Job_TaskInfo', 'Job_Startup', 'Job_Programs', 'Job_Apps', 'Job_ScoreView', 'Job_PrivacyStatus', 'Job_PrivacyUse', 'Job_Lifespan', 'Job_FocusState', 'Job_PathInfo', 'Job_IntegrityCheck')) { & $add $f @{} 'sistem' $false }
    & $add 'Job_Adaptive' @{ Preview = $true; RestorePoint = $false; Services = $true } 'sistem' $false
    & $add 'Job_SmartZero' @{ Preview = $true; RestorePoint = $false } 'sistem' $false
    & $add 'Job_TweakStateIds' @{ Ids = @('VisualFx', 'Transparency', 'Telemetry') } 'sistem' $false
    # depolama
    foreach ($f in @('Job_CleanScan', 'Job_RecycleList', 'Job_SlvDisks', 'Job_ShadowList', 'Job_BitLockerInfo', 'Job_AltScan')) { & $add $f @{} 'depolama' $false }
    & $add 'Job_DiskUsage' @{ Path = $kum } 'depolama' $false
    & $add 'Job_LargeFiles' @{ Path = $kum; Top = 10; MinMB = 0.000001 } 'depolama' $false
    & $add 'Job_Duplicates' @{ Path = $kum; MinMB = 0.000001 } 'depolama' $false
    & $add 'Job_FileInfo' @{ Path = (Join-Path $kum 'ornek.txt') } 'depolama' $false
    & $add 'Job_CompressEstimate' @{ Path = $kum } 'depolama' $false
    & $add 'Job_CompressScan' @{ MinMB = 250 } 'depolama' $true
    & $add 'Job_FindPhotoRec' @{} 'depolama' $false
    # guncellemeler
    foreach ($f in @('Job_InstalledUpdates', 'Job_WuHistory', 'Job_WingetPinList')) { & $add $f @{} 'guncelleme' $false }
    & $add 'Job_WuSearch' @{} 'guncelleme' $true
    & $add 'Job_WingetCheck' @{} 'guncelleme' $true
    # ag
    foreach ($f in @('Job_VpnStatus', 'Job_KsContext', 'Job_NetTalkers', 'Job_NetProtect', 'Job_FwBlocks', 'Job_ArpCheck', 'Job_Neighbors')) { & $add $f @{} 'ag' $false }
    & $add 'Job_Ping' @{ Host = '127.0.0.1'; Trace = $false } 'ag' $false
    & $add 'Job_Net' @{} 'ag' $true
    & $add 'Job_LanSweep' @{} 'ag' $true
    if ($ownIp -ne '') { & $add 'Job_PortCheck' @{ Host = $ownIp } 'ag' $true }
    & $add 'Job_LeakTest' @{} 'ag' $true
    & $add 'Job_DnsBench' @{} 'ag' $true
    # oyun
    & $add 'Job_GameScan' @{ Custom = @() } 'oyun' $true
    & $add 'Job_ExtToolScan' @{} 'oyun' $false
    & $add 'Job_PrepCheck' @{ NoNet = $true } 'oyun' $false
    # saglik ve raporlar (tam tarama ayrica "bulgu" bolumunde)
    & $add 'Job_Report' @{} 'saglik' $true
    & $add 'Job_SupportBundle' @{ Dest = $kum } 'saglik' $true
    return $list.ToArray()
}

# Sonucu "Ok = $false" donmesi hata sayilmayan isler: bu bilgisayarda o durum normal (ornegin etkin VPN yokken kill-switch baglami bos doner)
$script:LiveOkFalseInfo = @('Job_KsContext')

function Get-LiveWhy($Out) {
    $why = ''
    if ($Out -is [hashtable]) {
        foreach ($k in @('Error', 'Msg', 'Message', 'Reason', 'Why')) { if ($Out.ContainsKey($k) -and [string]$Out[$k] -ne '') { $why = [string]$Out[$k]; break } }
        if ($why -eq '' -and $Out.ContainsKey('Errors') -and [int]$Out.Errors -gt 0) { $why = [string][int]$Out.Errors + (' ad' + [char]0x0131 + 'm hata verdi') }
        if ($why -eq '' -and $Out.ContainsKey('Summary') -and [string]$Out.Summary -ne '') { $why = [string]$Out.Summary }
    }
    return $why
}

function Test-LiveJobs([string]$Group) {
    [void](Get-LiveMode)
    $all = @(Get-LiveReadJobs | Where-Object { $_.Group -eq $Group })
    foreach ($j in $all) {
        $fn = [string]$j.Fn
        if ($null -eq (Get-Command $fn -ErrorAction SilentlyContinue)) { Add-LiveRow 'is' $fn 'ATLA' ('bu s' + [char]0x00FC + 'r' + [char]0x00FC + 'mde i' + [char]0x015F + 'lev yok'); continue }
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $mk = Get-LiveLogMark
        $r = Invoke-LiveGuarded $fn $j.Arg
        $blocked = @($script:LiveBlocked.ToArray())
        $lines = Get-LiveLogSince $mk
        $ms = $sw.ElapsedMilliseconds
        $errs = Select-LiveLines $lines 'ERR'
        $errText = ''
        if ($errs.Count -gt 0) { $errText = Get-LiveShort (($errs | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+ERR\s+', '') }) -join ' | ') 220 }
        if ($blocked.Count -gt 0) {
            Add-LiveRow 'is' $fn 'HATA' (('okuma i' + [char]0x015F + 'i sistemi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmeye kalk' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + ' (bek' + [char]0x00E7 + 'i engelledi, hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '): ') + (Get-LiveShort ($blocked -join ' | ') 260)) $ms
            continue
        }
        if ($r.Err -ne '') { Add-LiveRow 'is' $fn 'HATA' (('i' + [char]0x015F + ' ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + (Get-LiveShort $r.Err 220)) $ms; continue }
        $out = $r.Out
        $sum = Get-LiveResultSummary $out
        if ($null -eq $out) { Add-LiveRow 'is' $fn 'UYARI' ('i' + [char]0x015F + ' sonu' + [char]0x00E7 + ' d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'rmedi') $ms; continue }
        $okFalse = ($out -is [hashtable] -and $out.ContainsKey('Ok') -and $out.Ok -eq $false)
        if ($okFalse) {
            $why = Get-LiveWhy $out
            if ($errText -ne '') { $why = ($why + (' [g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k: ') + $errText + ']').Trim() }
            if ($script:LiveOkFalseInfo -contains $fn) { Add-LiveRow 'is' $fn 'BILGI' (('bu bilgisayarda bo' + [char]0x015F + ' d' + [char]0x00F6 + 'nd' + [char]0x00FC + ': ') + (Get-LiveShort $why 200)) $ms; continue }
            Add-LiveRow 'is' $fn 'UYARI' (('i' + [char]0x015F + ' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z d' + [char]0x00F6 + 'nd' + [char]0x00FC + ': ') + (Get-LiveShort $why 260)) $ms; continue
        }
        if ($errs.Count -gt 0) { Add-LiveRow 'is' $fn 'UYARI' (('i' + [char]0x015F + ' sonu' + [char]0x00E7 + ' verdi ama g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e hata yazd' + [char]0x0131 + ': ') + $errText + ' [' + $sum + ']') $ms; continue }
        $note = ''
        if ($ms -gt 30000 -and -not [bool]$j.Slow) { $note = (' (yava' + [char]0x015F + ': ') + (Format-LiveMs $ms) + ')' }
        Add-LiveRow 'is' $fn 'OK' ($sum + $note) $ms
        try { Invoke-SmokeFlush } catch { }
    }
}

# ---------------- algilayicilar ve izleme: uygulamanin gosterdigi, Windows'un gercek degeriyle ayni mi ----------------
function Test-LiveSensors {
    try { Open-Page 'panel' } catch { }
    # izleme dongusunun ilk turlari beklenir (en cok 25 sn)
    for ($i = 0; $i -lt 100; $i++) {
        try { Invoke-SmokeFlush } catch { }
        $d = $sync.MonDiag
        if ($null -ne $d -and [int]$d.Tick -ge 6) { break }
        Start-Sleep -Milliseconds 250
    }
    $m = $sync.Mon
    if ($null -eq $m -or @($m.Keys).Count -eq 0) { Add-LiveRow 'sensor' 'izleme' 'HATA' ('izleme d' + [char]0x00F6 + 'ng' + [char]0x00FC + 's' + [char]0x00FC + ' hi' + [char]0x00E7 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ' + [char]0x00FC + 'retmedi'); return }
    $age = 999
    try { $age = ([DateTime]::UtcNow - [DateTime]$sync.MonBeat).TotalSeconds } catch { }
    if ($age -gt 15) { Add-LiveRow 'sensor' 'izleme' 'HATA' (('izleme d' + [char]0x00F6 + 'ng' + [char]0x00FC + 's' + [char]0x00FC + ' ') + [int]$age + (' sn ' + [char]0x00F6 + 'nce durmu' + [char]0x015F + '')) } else { Add-LiveRow 'sensor' 'izleme' 'OK' (('izleme canl' + [char]0x0131 + ', son ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm ') + [int]$age + (' sn ' + [char]0x00F6 + 'nce; tur=') + [string]$sync.MonDiag.Tick) }
    # bellek: uygulama ile Windows
    try {
        $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $totalGB = [double]$os.TotalVisibleMemorySize / 1MB
        $usedPct = 100.0 * (1.0 - [double]$os.FreePhysicalMemory / [double]$os.TotalVisibleMemorySize)
        $dt = [math]::Abs([double]$m.RamTotalGB - $totalGB)
        $dp = [math]::Abs([double]$m.Ram - $usedPct)
        if ($dt -gt 0.6) { Add-LiveRow 'sensor' 'bellek' 'HATA' ('toplam bellek uygulamada ' + [math]::Round([double]$m.RamTotalGB, 1) + (' GB, Windows taraf' + [char]0x0131 + 'nda ') + [math]::Round($totalGB, 1) + ' GB') }
        elseif ($dp -gt 12) { Add-LiveRow 'sensor' 'bellek' 'HATA' (('bellek dolulu' + [char]0x011F + 'u uygulamada %') + [int]$m.Ram + (', Windows taraf' + [char]0x0131 + 'nda %') + [int]$usedPct) }
        else { Add-LiveRow 'sensor' 'bellek' 'OK' ('uygulama %' + [int]$m.Ram + ' / ' + [math]::Round([double]$m.RamTotalGB, 1) + ' GB, Windows %' + [int]$usedPct + ' / ' + [math]::Round($totalGB, 1) + ' GB') }
    } catch { Add-LiveRow 'sensor' 'bellek' 'UYARI' (('Windows bellek de' + [char]0x011F + 'eri okunamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    # islemci yuku: uygulamanin okudugu sayacla AYNI olcumu (Processor Information \ % Processor Utility) bagimsiz bir sayac nesnesiyle yeniden oku
    try {
        $pc = $null
        $cname = '% Processor Utility'
        try { $pc = New-Object System.Diagnostics.PerformanceCounter('Processor Information', '% Processor Utility', '_Total', $true) } catch { $pc = $null }
        if ($null -eq $pc) { try { $cname = '% Processor Time'; $pc = New-Object System.Diagnostics.PerformanceCounter('Processor', '% Processor Time', '_Total', $true) } catch { $pc = $null } }
        if ($null -ne $pc) {
            try {
                [void]$pc.NextValue()
                Start-Sleep -Milliseconds 1200
                $refCpu = [math]::Min(100.0, [double]$pc.NextValue())
                $appCpu = 0.0
                try { $appCpu = [double]$m.Cpu } catch { }
                $cpuTxt = 'uygulama %' + [int]$appCpu + (', ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z okuma (') + $cname + ') %' + [int]$refCpu
                if ([math]::Abs($appCpu - $refCpu) -gt 35) { Add-LiveRow 'sensor' 'islemci' 'UYARI' (('i' + [char]0x015F + 'lemci y' + [char]0x00FC + 'k' + [char]0x00FC + ' iki okumada ' + [char]0x00E7 + 'ok farkl' + [char]0x0131 + ': ') + $cpuTxt) }
                else { Add-LiveRow 'sensor' 'islemci' 'OK' $cpuTxt }
            } finally { $pc.Dispose() }
        } else { Add-LiveRow 'sensor' 'islemci' 'BILGI' (('ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z i' + [char]0x015F + 'lemci sayac' + [char]0x0131 + ' a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '; uygulama %') + [int]$m.Cpu) }
    } catch { Add-LiveRow 'sensor' 'islemci' 'BILGI' (('i' + [char]0x015F + 'lemci kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'rmas' + [char]0x0131 + ' yap' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) }
    # ekran karti
    $gpuLoad = [double]$m.Gpu
    $gpuT = -1.0
    try { $gpuT = [double](Get-GpuTemp) } catch { }
    $appGpuT = -1.0
    try { if ($null -ne $m.GpuTemp) { $appGpuT = [double]$m.GpuTemp } } catch { }
    if ($gpuT -gt 0 -and $appGpuT -le 0) { Add-LiveRow 'sensor' 'ekran-karti-sicaklik' 'HATA' (('Windows ekran kart' + [char]0x0131 + ' s' + [char]0x0131 + 'cakl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' veriyor (') + [string]$gpuT + (' ' + [char]0x00B0 + 'C) ama izleme d' + [char]0x00F6 + 'ng' + [char]0x00FC + 's' + [char]0x00FC + ' bunu panoya ta' + [char]0x015F + '' + [char]0x0131 + 'm' + [char]0x0131 + 'yor')) }
    Add-LiveRow 'sensor' 'ekran-karti' $(if ($gpuT -gt 0) { 'OK' } else { 'UYARI' }) (('y' + [char]0x00FC + 'k=') + $(if ($gpuLoad -ge 0) { '%' + [int]$gpuLoad } else { ('' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemedi') }) + ('; s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k=') + $(if ($gpuT -gt 0) { [string]$gpuT + (' ' + [char]0x00B0 + 'C') } else { ('' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemedi (s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' bu de' + [char]0x011F + 'eri vermiyor olabilir)') }))
    # islemci sicakligi: iki yol
    $tAcpi = -1.0; $tPerf = -1.0
    try { foreach ($z in @(Get-CimInstance -Namespace 'root/wmi' -ClassName 'MSAcpi_ThermalZoneTemperature' -OperationTimeoutSec 5 -ErrorAction Stop)) { $c = ([double]$z.CurrentTemperature / 10.0) - 273.15; if ($c -gt $tAcpi) { $tAcpi = $c } } } catch { }
    try { foreach ($z in @(Get-CimInstance -ClassName 'Win32_PerfFormattedData_Counters_ThermalZoneInformation' -OperationTimeoutSec 5 -ErrorAction Stop)) { $c = [double]$z.Temperature - 273.15; if ($c -gt $tPerf) { $tPerf = $c } } } catch { }
    $appT = [double]$m.Temp
    $txt = 'uygulama=' + $(if ($appT -gt 0) { [string]$appT + (' ' + [char]0x00B0 + 'C') } else { 'yok' }) + '; ACPI=' + $(if ($tAcpi -gt 0) { [string][math]::Round($tAcpi, 1) } else { 'yok' }) + ('; saya' + [char]0x00E7 + '=') + $(if ($tPerf -gt 0) { [string][math]::Round($tPerf, 1) } else { 'yok' })
    if (($tAcpi -gt 0 -or $tPerf -gt 0) -and $appT -le 0) { Add-LiveRow 'sensor' 'islemci-sicakligi' 'HATA' (('Windows s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k veriyor ama uygulama ' + [char]0x201C + '' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'lemedi' + [char]0x201D + ' diyor: ') + $txt) }
    elseif ($appT -gt 0) { Add-LiveRow 'sensor' 'islemci-sicakligi' 'OK' $txt }
    else { Add-LiveRow 'sensor' 'islemci-sicakligi' 'BILGI' (('bu bilgisayarda Windows hi' + [char]0x00E7 + 'bir yoldan s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k vermiyor: ') + $txt) }
    # kartlarin yazisi: "olculuyor" ya da "sensor yok" nedenli mi
    try {
        foreach ($k in @($script:BoardViews.Keys)) {
            $v = $script:BoardViews[$k]
            $t = [string]$v.Type
            if ($t -ne 'gpu' -and $t -ne 'temp') { continue }
            $val = ''; $sub = ''
            try { $val = [string]$v.N.Val.Text; $sub = [string]$v.N.Sub.Text } catch { }
            if ($val -match ('' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor')) { Add-LiveRow 'sensor' ('kart-' + $t) 'HATA' (('ilk ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'mlerden sonra kart h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' ' + [char]0x201C + '' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'l' + [char]0x00FC + 'yor' + [char]0x201D + ' yaz' + [char]0x0131 + 'yor: ') + $val + ' [' + $sub + ']') }
            else { Add-LiveRow 'sensor' ('kart-' + $t) 'BILGI' ($val + ' [' + $sub + ']') }
        }
    } catch { }
}

# ---------------- saglik taramasi bulgulari: Windows'un kendi okumasiyla ayni mi ----------------
function Get-LiveFinding($Findings, [string]$Id) {
    foreach ($f in @($Findings)) { if ([string]$f.Id -eq $Id) { return $f } }
    return $null
}

function Test-LiveFindings {
    $r = Invoke-LiveJob 'Job_Health' @{ Level = 'Full' }
    if ($r.Err -ne '' -or $null -eq $r.Out) { Add-LiveRow 'bulgu' 'tarama' 'HATA' (('sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ' ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r.Err); return }
    $f = @($r.Out.Findings)
    $by = @{}
    foreach ($x in $f) { $by[[string]$x.Status] = [int]$by[[string]$x.Status] + 1 }
    Add-LiveRow 'bulgu' 'tarama' 'BILGI' ([string]$f.Count + ' bulgu: ' + (($by.Keys | Sort-Object | ForEach-Object { $_ + '=' + $by[$_] }) -join ' ') + '; puan ' + [string]$r.Out.Score.All)
    $nonOk = @($f | Where-Object { @('bad', 'warn') -contains [string]$_.Status })
    if ($nonOk.Count -gt 0) {
        $nonTxt = (@($nonOk | ForEach-Object { '[' + [string]$_.Status + '] ' + [string]$_.Id + ': ' + (Get-LiveShort ([string]$_.Title) 70) })) -join ' | '
        Add-LiveRow 'bulgu' 'sorunlu' 'BILGI' (Get-LiveShort $nonTxt 900)
    }
    # kopya kimlik ve bos metin
    $ids = @{}; $dups = New-Object System.Collections.ArrayList; $empty = New-Object System.Collections.ArrayList
    foreach ($x in $f) {
        $k = [string]$x.Id
        if ($ids.ContainsKey($k)) { [void]$dups.Add($k) } else { $ids[$k] = $true }
        if ([string]$x.Title -eq '') { [void]$empty.Add($k) }
    }
    if ($dups.Count -gt 0) { Add-LiveRow 'bulgu' 'kopya' 'HATA' (('ayn' + [char]0x0131 + ' kimlikle birden ' + [char]0x00E7 + 'ok bulgu: ') + ($dups -join ', ')) }
    if ($empty.Count -gt 0) { Add-LiveRow 'bulgu' 'bos-baslik' 'HATA' (('ba' + [char]0x015F + 'l' + [char]0x0131 + 'ks' + [char]0x0131 + 'z bulgu: ') + ($empty -join ', ')) }
    # "sorun" olan her bulgunun bir eylemi (Fix ya da Action) var mi
    $noAct = New-Object System.Collections.ArrayList
    foreach ($x in $f) { if (@('bad', 'warn') -contains [string]$x.Status -and $null -eq $x.Fix -and $null -eq $x.Action) { [void]$noAct.Add([string]$x.Id) } }
    if ($noAct.Count -gt 0) { Add-LiveRow 'bulgu' 'eylemsiz' 'BILGI' (('eylemi olmayan sorun bulgular' + [char]0x0131 + ' (yaln' + [char]0x0131 + 'zca bilgi): ') + ($noAct -join ', ')) }
    # --- bagimsiz capraz denetim: uygulamanin yargisi (ok / info / warn / bad) Windows'un kendi okumasiyla ayni mi
    #     Her satir: Id = bulgu kimligi, Expect = kabul edilen durumlar ('yok' = bulgu hic uretilmemeli), Note = Windows'un verdigi deger
    $checks = New-Object System.Collections.ArrayList
    # guvenlik duvari
    try {
        $fp = @(Get-NetFirewallProfile -ErrorAction Stop)
        $allOn = (@($fp | Where-Object { [string]$_.Enabled -ne 'True' }).Count -eq 0)
        [void]$checks.Add(@{ Id = 'fw'; Expect = @($(if ($allOn) { 'ok' } else { 'bad' })); Note = 'profiller: ' + (($fp | ForEach-Object { [string]$_.Name + '=' + [string]$_.Enabled }) -join ' ') })
    } catch { }
    # Defender gercek zamanli koruma (ucuncu taraf antivirus varsa Defender pasif olabilir)
    try {
        $mp = Get-MpComputerStatus -ErrorAction Stop
        $third = @()
        try { $third = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntivirusProduct -ErrorAction Stop | Where-Object { [string]$_.displayName -notmatch 'Windows Defender|Microsoft Defender' }) } catch { }
        if ([bool]$mp.RealTimeProtectionEnabled) { [void]$checks.Add(@{ Id = 'av-rt'; Expect = @('ok'); Note = 'RealTimeProtectionEnabled=True' }) }
        elseif ($third.Count -gt 0) { [void]$checks.Add(@{ Id = 'av-3p'; Expect = @('ok'); Note = ('Defender pasif, ' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'nc' + [char]0x00FC + ' taraf antivir' + [char]0x00FC + 's: ') + [string]$third[0].displayName }) }
        else { [void]$checks.Add(@{ Id = 'av-rt'; Expect = @('bad'); Note = ('RealTimeProtectionEnabled=False, ba' + [char]0x015F + 'ka antivir' + [char]0x00FC + 's yok') }) }
        [void]$checks.Add(@{ Id = 'av-tamper'; Expect = @($(if ([bool]$mp.IsTamperProtected) { 'ok' } else { 'warn' })); Note = 'IsTamperProtected=' + [string]$mp.IsTamperProtected })
    } catch { }
    # UAC
    $lua = Get-LiveRegRaw 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableLUA'
    $cpa = Get-LiveRegRaw 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'ConsentPromptBehaviorAdmin'
    $luaV = 1; if ($lua.Exists) { $luaV = [int]$lua.Data }
    $cpaV = 5; if ($cpa.Exists) { $cpaV = [int]$cpa.Data }
    [void]$checks.Add(@{ Id = 'uac'; Expect = @($(if ($luaV -eq 0) { 'bad' } elseif ($cpaV -eq 0) { 'warn' } else { 'ok' })); Note = 'EnableLUA=' + $luaV + ' ConsentPromptBehaviorAdmin=' + $cpaV })
    # Uzak Masaustu: kapaliysa bulgu uretilmez, aciksa "info" ya da (NLA kapaliysa) "bad"
    $rdp = Get-LiveRegRaw 'HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server' 'fDenyTSConnections'
    $rdpV = 1; if ($rdp.Exists) { $rdpV = [int]$rdp.Data }
    $nlaR = Get-LiveRegRaw 'HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' 'UserAuthentication'
    $nlaV = 1; if ($nlaR.Exists) { $nlaV = [int]$nlaR.Data }
    [void]$checks.Add(@{ Id = 'rdp'; Expect = @($(if ($rdpV -ne 0) { 'yok' } elseif ($nlaV -eq 0) { 'bad' } else { 'info' })); Note = 'fDenyTSConnections=' + $rdpV + ' UserAuthentication=' + $nlaV })
    # TPM ve guvenli onyukleme (Get-Tpm yonetici ister; okunamazsa karsilastirma yapilmaz)
    try { $tp = Get-Tpm -ErrorAction Stop; [void]$checks.Add(@{ Id = 'tpm'; Expect = @($(if ([bool]$tp.TpmPresent) { 'ok' } else { 'info' })); Note = 'TpmPresent=' + [string]$tp.TpmPresent + ' Ready=' + [string]$tp.TpmReady }) } catch { }
    try { $sb = [bool](Confirm-SecureBootUEFI -ErrorAction Stop); [void]$checks.Add(@{ Id = 'sboot'; Expect = @($(if ($sb) { 'ok' } else { 'warn' })); Note = 'SecureBoot=' + [string]$sb }) } catch { }
    # geri yukleme noktasi
    try { $rp = @(Get-ComputerRestorePoint -ErrorAction Stop); [void]$checks.Add(@{ Id = 'rp'; Expect = @($(if ($rp.Count -gt 0) { 'ok' } else { 'info' })); Note = ('geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + '=') + [string]$rp.Count }) } catch { [void]$checks.Add(@{ Id = 'rp'; Expect = @('info'); Note = ('Sistem Geri Y' + [char]0x00FC + 'kleme kapal' + [char]0x0131 + ' ya da okunam' + [char]0x0131 + 'yor') }) }
    # SMB 1.0
    try { $smb = Get-SmbServerConfiguration -ErrorAction Stop; [void]$checks.Add(@{ Id = 'smb1'; Expect = @($(if ([bool]$smb.EnableSMB1Protocol) { 'bad' } else { 'yok' })); Note = 'EnableSMB1Protocol=' + [string]$smb.EnableSMB1Protocol }) } catch { }
    foreach ($ck in $checks) {
        $x = Get-LiveFinding $f ([string]$ck.Id)
        $exp = @($ck.Expect)
        if ($null -eq $x) {
            if ($exp -contains 'yok') { Add-LiveRow 'bulgu' ([string]$ck.Id) 'OK' ('bulgu yok, Windows: ' + $ck.Note) }
            else { Add-LiveRow 'bulgu' ([string]$ck.Id) 'HATA' (('bulgu ' + [char]0x00FC + 'retilmedi ama Windows ') + $ck.Note + ' (beklenen durum: ' + ($exp -join '/') + ')') }
            continue
        }
        $got = [string]$x.Status
        if ($exp -contains $got) { Add-LiveRow 'bulgu' ([string]$ck.Id) 'OK' (('uygulama ' + [char]0x201C + '') + $got + ('' + [char]0x201D + ', Windows: ') + $ck.Note) }
        else { Add-LiveRow 'bulgu' ([string]$ck.Id) 'HATA' (('uygulaman' + [char]0x0131 + 'n yarg' + [char]0x0131 + 's' + [char]0x0131 + ' Windows ile ' + [char]0x00E7 + 'eli' + [char]0x015F + 'iyor: uygulama ' + [char]0x201C + '') + $got + ('' + [char]0x201D + ' diyor, beklenen ') + ($exp -join '/') + '; Windows: ' + $ck.Note + ' | ' + (Get-LiveShort ([string]$x.Title) 100)) }
    }
}


# ---------------- son: baslangic durumuna donuldu mu, sayilar ----------------
# ---------------- Windows bilesenleri (Cap) ve Magaza uygulamalari (Appx) ----------------
# oku: her bilesen ayari onizlenir, motorun karari (kaldirilacak / zaten yok / korumali) bagimsiz okumayla karsilastirilir; uygulama listesi okunur.
# tam: her mekanizmadan bir temsilci gercekten kaldirilip uygulamanin kendi "geri al" akisiyla geri getirilir
#      (bilesen: Add-WindowsCapability internet ister; uygulama: paket klasorundeki AppxManifest.xml ile yeniden kayit).
#      Diger bilesenler ayni motordan gecer; onlar onizleme + bagimsiz durum okumasiyla dogrulanir.
$script:LiveCapPrefer = @('App.StepsRecorder', 'MathRecognizer', 'XPS.Viewer', 'Print.Fax.Scan', 'Microsoft.Windows.WordPad', 'Microsoft.Windows.PowerShell.ISE', 'Media.WindowsMediaPlayer', 'Browser.InternetExplorer')

function Get-LiveCapState([string]$Match) {
    try {
        $all = @(Get-WindowsCapability -Online -ErrorAction Stop | Where-Object { ([string]$_.Name) -like ($Match + '*') })
        if ($all.Count -eq 0) { return 'yok' }
        if (@($all | Where-Object { @('Installed', 'InstallPending') -contains [string]$_.State }).Count -gt 0) { return 'kurulu' }
        return 'kaldirilmis'
    } catch { return 'okunamadi' }
}

function Get-LiveAppxState([string]$Pattern) {
    try {
        $p = @()
        if ($script:IsAdmin) { try { $p = @(Get-AppxPackage -AllUsers -Name $Pattern -ErrorAction Stop) } catch { $p = @() } }
        if ($p.Count -eq 0) { $p = @(Get-AppxPackage -Name $Pattern -ErrorAction Stop) }
        if ($p.Count -eq 0) { return 'yok' }
        return 'kurulu'
    } catch { return 'okunamadi' }
}

function Test-LiveComponents {
    $mode = Get-LiveMode
    $list = @(Get-LiveApplicable | Where-Object { (Get-LiveGroup $_) -eq 'bilesen' })
    Add-LiveRow 'bilesen' 'grup' 'BILGI' ([string]$list.Count + (' bile' + [char]0x015F + 'en ayar' + [char]0x0131 + '; kip=') + $mode)
    $capPick = $null
    $unread = 0
    foreach ($c in $list) {
        $id = [string]$c.Id
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $defects = New-Object System.Collections.ArrayList
        $states = New-Object System.Collections.ArrayList
        $mk = Get-LiveLogMark
        $pv = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-StepsFromIds @($id)); Preview = $true; RestorePoint = $false }
        [void](Get-LiveLogSince $mk)
        if ($pv.Err -ne '') { Add-LiveRow 'bilesen' $id 'HATA' (('' + [char]0x00F6 + 'nizleme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $pv.Err) $sw.ElapsedMilliseconds; continue }
        $chg = [int]$pv.Out.Changes
        $pureFeat = (@(@($c.Ops) | Where-Object { [string]$_.T -ne 'Feature' }).Count -eq 0)
        $featNeed = 0
        foreach ($op in @($c.Ops)) {
            if ([string]$op.T -eq 'Feature') {
                $fs = [string](Get-LiveFeatSnap ([string]$op.Name)).State
                if ($fs -eq '') { $fs = ('yok/okunamad' + [char]0x0131 + '') }
                [void]$states.Add([string]$op.Name + '=' + $fs)
                if ($fs -eq ('yok/okunamad' + [char]0x0131 + '')) { continue }
                $wantOn = ([string]$op.State -eq 'Enabled')
                $isOn = ($fs -eq 'Enabled')
                if ($wantOn -ne $isOn) { $featNeed++ }
                continue
            }
            if ([string]$op.T -ne 'Cap') { continue }
            $m = [string]$op.Match
            $st = Get-LiveCapState $m
            [void]$states.Add($m + '=' + $st)
            if ($st -eq 'okunamadi') { $unread++; continue }
            $wantAbsent = ([string]$op.State -ne 'Installed')
            if ($st -eq 'kurulu' -and $wantAbsent -and $chg -eq 0) { [void]$defects.Add(('bile' + [char]0x015F + 'en kurulu ama ' + [char]0x00F6 + 'nizleme kald' + [char]0x0131 + 'rma planlamad' + [char]0x0131 + ': ') + $m) }
            if ($st -ne 'kurulu' -and $wantAbsent -and $chg -gt 0) { [void]$defects.Add(('bile' + [char]0x015F + 'en zaten yok ama ' + [char]0x00F6 + 'nizleme kald' + [char]0x0131 + 'raca' + [char]0x011F + '' + [char]0x0131 + 'm diyor: ') + $m) }
            if ($null -eq $capPick -and $st -eq 'kurulu' -and $wantAbsent -and $script:LiveCapPrefer -contains $m -and @($c.Ops).Count -eq 1) { $capPick = $c }
        }
        # yalnizca Windows ozelligi iceren ayarda motorun karari bagimsiz okumayla ayni olmali
        if ($pureFeat -and $featNeed -ne $chg) { [void]$defects.Add(('' + [char]0x00F6 + 'nizleme ') + $chg + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik diyor, ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z okuma ') + $featNeed + (' ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'in farkl' + [char]0x0131 + ' oldu' + [char]0x011F + 'unu g' + [char]0x00F6 + 'steriyor')) }
        $txt = ('' + [char]0x00F6 + 'nizleme ') + $chg + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik, ') + [string]$pv.Out.Skipped + ' atlanan; durum: ' + ($states -join ', ')
        if ($defects.Count -gt 0) { Add-LiveRow 'bilesen' $id 'HATA' ($txt + '; ' + ($defects -join ' | ')) $sw.ElapsedMilliseconds }
        else { Add-LiveRow 'bilesen' $id 'OK' $txt $sw.ElapsedMilliseconds }
    }
    if ($unread -gt 0) { Add-LiveRow 'bilesen' 'durum-okuma' 'BILGI' ([string]$unread + (' bile' + [char]0x015F + 'enin durumu ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z okunamad' + [char]0x0131 + ' (DISM y' + [char]0x00F6 + 'netici ister); tam kipte okunur')) }

    # Magaza uygulamalari: kaldirilabilir liste
    $ra = Invoke-LiveJob 'Job_Apps' @{}
    $appPick = ''
    if ($ra.Err -ne '') { Add-LiveRow 'bilesen' 'uygulama-liste' 'HATA' (('liste ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $ra.Err) }
    else {
        $rows = @($ra.Out.Rows)
        $bad = 0
        foreach ($r in $rows) {
            $st = Get-LiveAppxState ([string]$r.Pattern)
            if ($st -eq 'yok') { $bad++ }
            if ($appPick -eq '' -and $st -eq 'kurulu' -and [bool]$r.R) { $appPick = [string]$r.Pattern }
        }
        if ($bad -gt 0) { Add-LiveRow 'bilesen' 'uygulama-liste' $(if ($script:IsAdmin) { 'HATA' } else { 'UYARI' }) ([string]$rows.Count + ' uygulama listelendi; ' + $bad + (' tanesi ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z okumada y' + [char]0x00FC + 'kl' + [char]0x00FC + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nm' + [char]0x00FC + 'yor') + $(if ($script:IsAdmin) { '' } else { (' (y' + [char]0x00F6 + 'netici olmayan okuma yaln' + [char]0x0131 + 'zca bu kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'y' + [char]0x0131 + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'r)') })) }
        else { Add-LiveRow 'bilesen' 'uygulama-liste' 'OK' ([string]$rows.Count + (' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir uygulama; hepsi ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z okumada da y' + [char]0x00FC + 'kl' + [char]0x00FC + '')) }
        if ($appPick -ne '') {
            $mkP = Get-LiveLogMark
            $steps = @(@{ Id = 'Apps'; Title = 'Denetim: uygulama'; Ops = @(@{ T = 'Appx'; Name = $appPick }); Reboot = $false })
            $pvA = Invoke-LiveJob 'Job_Plan' @{ Steps = $steps; Preview = $true; RestorePoint = $false }
            $planA = @((Select-LiveLines (Get-LiveLogSince $mkP) 'PLAN') | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+PLAN\s+', '') })
            $errA = @((Select-LiveLines (Get-LiveLogSince $mkP) 'ERR') | ForEach-Object { ($_ -replace '^\d\d:\d\d:\d\d\s+ERR\s+', '') })
            if ($pvA.Err -ne '') { Add-LiveRow 'bilesen' 'uygulama-onizleme' 'HATA' (('' + [char]0x00F6 + 'nizleme ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $pvA.Err) }
            elseif ([int]$pvA.Out.Errors -gt 0) { Add-LiveRow 'bilesen' 'uygulama-onizleme' 'HATA' ($appPick + (': ' + [char]0x00F6 + 'nizleme hata verdi: ') + (Get-LiveShort ($errA -join ' | ') 160)) }
            elseif ([int]$pvA.Out.Changes -lt 1) { Add-LiveRow 'bilesen' 'uygulama-onizleme' 'HATA' ($appPick + (' y' + [char]0x00FC + 'kl' + [char]0x00FC + ' ama ' + [char]0x00F6 + 'nizleme kald' + [char]0x0131 + 'rma planlamad' + [char]0x0131 + '')) }
            else { Add-LiveRow 'bilesen' 'uygulama-onizleme' 'OK' ($appPick + ': ' + (Get-LiveShort ($planA -join '; ') 120)) }
        } else { Add-LiveRow 'bilesen' 'uygulama-onizleme' 'BILGI' ('' + [char]0x00F6 + 'nerilen kald' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir uygulama kalmam' + [char]0x0131 + '' + [char]0x015F + '; ' + [char]0x00F6 + 'nizleme denenmedi') }
    }

    if ($mode -ne 'tam') {
        Add-LiveRow 'bilesen' 'canli' 'ATLA' ('bile' + [char]0x015F + 'en ve uygulama kald' + [char]0x0131 + 'rma ger' + [char]0x00E7 + 'ek sistemi de' + [char]0x011F + 'i' + [char]0x015F + 'tirir; temsilci tur yaln' + [char]0x0131 + 'zca tam kipte (y' + [char]0x00F6 + 'netici) yap' + [char]0x0131 + 'l' + [char]0x0131 + 'r')
        return
    }

    # tam: Windows ozellikleri. Hepsi gercekten uygulanip geri alinir: once hafifler, sonra yeniden baslatma bekletebilen ya da
    # indirme gerektiren agirlar (WSL, Hyper-V, sanal makine platformu, .NET 3.5, DirectPlay; bu surumde olmayanlar atlanir).
    # Baslangic engeli (Windows Update kuruyor / bilesen servisi zaten yeniden baslatma bekliyor) bolum basinda bir kez okunur:
    # turlarin kendi biraktigi bekleyen islem sonraki turlari (bilesen turu dahil) engellemez.
    $script:LiveSvcBlock0 = Get-LiveServicingBlock
    Test-LiveFeatureTrips $list

    # tam: temsilci bilesen
    $busyC = [string]$script:LiveSvcBlock0
    if ($busyC -eq '') { $busyC = Get-ServicingBusy }
    if ($busyC -eq '' -and $script:DismTimedOut) { $busyC = ('bu denetimde bir DISM i' + [char]0x015F + 'lemi s' + [char]0x00FC + 're s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x015F + 't' + [char]0x0131 + '') }
    $capName = ''
    if ($null -ne $capPick) { $capName = [string]@($capPick.Ops)[0].Match }
    if ($null -eq $capPick) { Add-LiveRow 'bilesen' 'bilesen-tur' 'BILGI' (('kurulu ve denenebilir bile' + [char]0x015F + 'en yok (tercih listesi: ') + ($script:LiveCapPrefer -join ', ') + ')') }
    elseif ($busyC -ne '') { Add-LiveRow 'bilesen' 'bilesen-tur' 'BILGI' ($busyC + ('; bile' + [char]0x015F + 'en turu yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
    elseif ($script:LiveStopKinds -contains 'Cap') { Add-LiveRow 'bilesen' 'bilesen-tur' 'BILGI' ('' + [char]0x00F6 + 'nceki bir bile' + [char]0x015F + 'en geri kurulamad' + [char]0x0131 + ' ya da DISM s' + [char]0x00FC + 're s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x015F + 't' + [char]0x0131 + '; g' + [char]0x00FC + 'venlik i' + [char]0x00E7 + 'in tur yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '') }
    elseif (@(Get-LiveRiskyNames) -contains $capName) { Add-LiveRow 'bilesen' 'bilesen-tur' 'BILGI' (('bu bilgisayarda daha ' + [char]0x00F6 + 'nce geri kurulamad' + [char]0x0131 + ': ') + $capName + ('; canl' + [char]0x0131 + ' turda de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmez')) }
    elseif (-not (Test-LiveCapLive)) { Add-LiveRow 'bilesen' 'bilesen-tur' 'BILGI' (('temsilci bile' + [char]0x015F + 'en ') + $capName + (' canl' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lmad' + [char]0x0131 + ': ') + $script:LiveCapWhy + ('. Kald' + [char]0x0131 + 'rma plan' + [char]0x0131 + ' ' + [char]0x00F6 + 'nizlendi; bilerek denemek i' + [char]0x00E7 + 'in MM_BILESEN_CANLI=1')) }
    else {
        $cbc = Wait-LiveCbsIdle 180
        if ($cbc -ne '') { Add-LiveRow 'bilesen' 'bilesen-tur' 'BILGI' (('Windows bile' + [char]0x015F + 'en hizmeti ' + [char]0x00F6 + 'nceki i' + [char]0x015F + 'i s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'yor (') + $cbc + ('); bile' + [char]0x015F + 'en turu yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
        else { Invoke-LiveCapTrip $capPick }
    }
    # Magaza uygulamasi kaldirma geri alinamaz: motor uygulamayi tum kullanicilardan ve Windows goruntusunden siler, dosyalar gider,
    # yalnizca Microsoft Store'dan geri gelir (cihazda 18.11.2026: Microsoft 365 Copilot boyle kaldirildi). Bu yuzden temsilci
    # uygulama yalnizca onizlenir; kullanici bilerek bir paket adi verirse (MM_UYGULAMA_CANLI) yalnizca o uygulama canli denenir.
    $appOpt = [string]$env:MM_UYGULAMA_CANLI
    if ($appOpt -ne '') {
        if ($appOpt -cnotmatch '^[A-Za-z0-9\.\-_]{3,120}$') { Add-LiveRow 'bilesen' 'uygulama-tur' 'HATA' (('MM_UYGULAMA_CANLI ge' + [char]0x00E7 + 'ersiz paket ad' + [char]0x0131 + ': ') + $appOpt) }
        elseif ((Get-LiveAppxState $appOpt) -ne 'kurulu') { Add-LiveRow 'bilesen' 'uygulama-tur' 'BILGI' ('MM_UYGULAMA_CANLI=' + $appOpt + (': bu uygulama y' + [char]0x00FC + 'kl' + [char]0x00FC + ' de' + [char]0x011F + 'il; tur yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
        else { Invoke-LiveAppxTrip $appOpt }
    }
    elseif ($appPick -eq '') { Add-LiveRow 'bilesen' 'uygulama-tur' 'BILGI' ('denenecek y' + [char]0x00FC + 'kl' + [char]0x00FC + ' uygulama yok') }
    else { Add-LiveRow 'bilesen' 'uygulama-tur' 'BILGI' ('temsilci uygulama ' + $appPick + (' canl' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lmad' + [char]0x0131 + ': kald' + [char]0x0131 + 'rma uygulamay' + [char]0x0131 + ' t' + [char]0x00FC + 'm kullan' + [char]0x0131 + 'c' + [char]0x0131 + 'lardan ve Windows g' + [char]0x00F6 + 'r' + [char]0x00FC + 'nt' + [char]0x00FC + 's' + [char]0x00FC + 'nden siler, yaln' + [char]0x0131 + 'zca Microsoft Store' + [char]0x2019 + 'dan geri gelir. Kald' + [char]0x0131 + 'rma plan' + [char]0x0131 + ' ' + [char]0x00F6 + 'nizlendi; bilerek denemek i' + [char]0x00E7 + 'in MM_UYGULAMA_CANLI=<paket ad' + [char]0x0131 + '>')) }
}

# Hafif Windows ozellikleri (yerel kaynakla saniyeler icinde acilip kapanir): canli turda once bunlar denenir.
# Agir olanlar (WSL, Sanal Makine Platformu, Hyper-V, .NET 3.5, DirectPlay...) de tam kipte canli denenir ama en sona birakilir:
# yeniden baslatma bekletebilir ya da Windows Update'ten indirme gerektirebilir; biri geri yuklenemezse kalan ozellik turlari durur.
$script:LiveSvcBlock0 = $null
$script:LiveFeatLight = @('Printing-Foundation-InternetPrinting-Client', 'WorkFolders-Client', 'SMB1Protocol', 'SMB1Protocol-Client', 'SMB1Protocol-Server',
    'SMB1Protocol-Deprecation', 'MicrosoftWindowsPowerShellV2', 'MicrosoftWindowsPowerShellV2Root', 'Printing-XPSServices-Features', 'TelnetClient', 'TFTP',
    'Printing-Foundation-LPDPrintService', 'Printing-Foundation-LPRPortMonitor', 'MSRDC-Infrastructure', 'Internet-Explorer-Optional-amd64')

# Ozellik turlarinin sirasi (kararli; katalog sirasi korunur):
#  1) ozelligi KAPATAN turlar: geri almak ozelligi yeniden acmayi gerektirir; bilesen hizmeti temizken yapilir,
#  2) ozelligi ACAN turlar,
#  3) Windows bilesenini (FOD) de kaldiran turlar: kaldirma yeniden baslatma bekletir, geri kurulum Windows Update'ten iner.
# Her grupta hafifler once, agirlar sonra. Cihazda (18.11.2026) XPS turu bekleyen islem biraktiktan sonra Is Klasorleri
# kapatildi ve hemen yeniden acilamadi (0x371B); onceki denetimde ayni sira tesadufen sorunsuz gecmisti.
function Get-LiveFeatureOrder($List) {
    $items = @(@($List) | Where-Object { @(@($_.Ops) | Where-Object { [string]$_.T -eq 'Feature' }).Count -gt 0 })
    $groups = @()
    for ($i = 0; $i -lt 6; $i++) { $groups += , (New-Object System.Collections.ArrayList) }
    foreach ($c in $items) {
        $fops = @(@($c.Ops) | Where-Object { [string]$_.T -eq 'Feature' })
        $names = @($fops | ForEach-Object { [string]$_.Name })
        $heavy = (@($names | Where-Object { $script:LiveFeatLight -notcontains $_ }).Count -gt 0)
        $hasCap = (@(@($c.Ops) | Where-Object { [string]$_.T -eq 'Cap' }).Count -gt 0)
        $offs = (@($fops | Where-Object { [string]$_.State -ne 'Enabled' }).Count -gt 0)
        $g = 1
        if ($hasCap) { $g = 2 } elseif ($offs) { $g = 0 }
        $k = 2 * $g
        if ($heavy) { $k++ }
        [void]$groups[$k].Add($c)
    }
    $out = New-Object System.Collections.ArrayList
    foreach ($gl in $groups) { foreach ($x in $gl) { [void]$out.Add($x) } }
    return $out.ToArray()
}

# Ogenin canli turda kaldiracagi, su an kurulu Windows bilesenleri (FOD). Kaldirilan bilesen yalnizca Windows Update'ten geri
# kurulur ve icerik her zaman bulunmaz: cihazda 18.11.2026 22:49'da XPS Goruntuleyici ve Adim Kaydedicisi 0x800F0950 ile geri
# kurulamadi (once iki denetimde sorunsuz geri gelmislerdi). Bu yuzden bilesen kaldirma varsayilan olarak yalnizca onizlenir.
function Get-LiveCapRemovals($C) {
    $names = New-Object System.Collections.ArrayList
    foreach ($op in @($C.Ops)) {
        if ([string]$op.T -ne 'Cap' -or [string]$op.State -eq 'Installed') { continue }
        $m = [string]$op.Match
        if ((Get-LiveCapState $m) -eq 'kurulu') { [void]$names.Add($m) }
    }
    return $names.ToArray()
}
function Test-LiveCapLive { return ([string]$env:MM_BILESEN_CANLI -eq '1') }
$script:LiveCapWhy = ('kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lan bile' + [char]0x015F + 'en yaln' + [char]0x0131 + 'zca Windows Update' + [char]0x2019 + 'ten geri kurulabilir ve i' + [char]0x00E7 + 'erik her zaman bulunmaz (bu bilgisayarda 18.11.2026' + [char]0x2019 + 'da 0x800F0950 ile geri kurulamad' + [char]0x0131 + ')')

# Bu denetimde Windows bir bilesen degisikligi icin yeniden baslatma bekliyor mu? (CBS anahtari ya da DISM'in
# "once yeniden baslatin" kodu). '' = beklemiyor.
function Get-LiveRebootNeed {
    $p = [string](Get-CbsRebootPending)
    if ($p -ne '') { return $p }
    if ($script:DismNeedsReboot) { return 'DISM' }
    return ''
}

# Windows bileseni / ozelligi turu simdi yapilabilir mi? Windows Update kurulum yapiyorsa ya da bilesen servisi yeniden baslatma
# bekliyorsa DISM islemi uzun surebilir, reddedilebilir (0x800F082F) ya da yarim kalabilir: tur yapilmaz, yalnizca onizlenir.
function Get-LiveServicingBlock {
    $busy = Get-ServicingBusy
    if ($busy -ne '') { return $busy }
    try {
        $cbs = Get-RegSubKeyNames 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
        foreach ($k in @('RebootPending', 'RebootInProgress', 'PackagesPending')) {
            if ($cbs -contains $k) { return (('Windows bir bile' + [char]0x015F + 'en de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmay' + [char]0x0131 + ' bekliyor (') + $k + ('; yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p tam denetimi tekrarlay' + [char]0x0131 + 'n)')) }
        }
    } catch { }
    return ''
}

# Bilesen hizmeti surecleri: dism/DismHost calisiyorsa yeni DISM istegi siraya girer ve uzun sure bekler (cihazda 20 dakika goruldu).
# TiWorker (Windows Modules Installer Worker) DISM bittikten sonra bir sure daha calisabilir: beklenir ama tek basina engel sayilmaz.
$script:LiveCbsHard = @('dism', 'DismHost')
$script:LiveCbsSoft = @('TiWorker')

function Get-LiveProcNames([string[]]$Names) {
    $found = New-Object System.Collections.ArrayList
    foreach ($n in @($Names)) { try { if (@(Get-Process -Name $n -ErrorAction SilentlyContinue).Count -gt 0) { [void]$found.Add($n) } } catch { } }
    return ($found.ToArray() -join ', ')
}

# En cok $MaxSec saniye bilesen hizmetinin bosalmasini bekler. Donus: hala calisan dism/DismHost ('' = DISM baslatilabilir)
function Wait-LiveCbsIdle([int]$MaxSec = 180) {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    while ($true) {
        $hard = Get-LiveProcNames $script:LiveCbsHard
        $soft = Get-LiveProcNames $script:LiveCbsSoft
        if ($hard -eq '' -and $soft -eq '') { return '' }
        if ($sw.Elapsed.TotalSeconds -ge $MaxSec) { return $hard }
        Start-Sleep -Seconds 5
    }
}

# Ozellik turu bu ozelligi gercekten degistirecek mi: istenen durum ile simdiki durum farkli mi ('' = okunamadi / yok: degistirmez)
function Get-LiveFeatChange($Op) {
    $cur = [string](Get-LiveFeatSnap ([string]$Op.Name)).State
    if ($cur -eq '') { return '' }
    $curOn = (@('Enabled', 'EnablePending') -contains $cur)
    $wantOn = ([string]$Op.State -eq 'Enabled')
    if ($curOn -eq $wantOn) { return '' }
    if ($wantOn) { return 'ac' }
    return 'kapat'
}

function Test-LiveFeatureTrips($List) {
    $items = @(Get-LiveFeatureOrder $List)
    if ($items.Count -eq 0) { return }
    # Bolum basinda Windows Update kuruyorsa ya da bilesen servisi zaten yeniden baslatma bekliyorsa baslangic durumu belirsizdir:
    # hicbir ozellik turu yapilmaz (yalnizca onizlenir). Turlarin kendi biraktigi bekleyen islem yalnizca ozelligi KAPATAN
    # turlari durdurur (asagida 3); acan turlar ve bilesen turlari bekleyen islemle de geri alinabiliyor.
    $block = $script:LiveSvcBlock0
    if ($null -eq $block) { $block = Get-LiveServicingBlock }
    $block = [string]$block
    $risky = @(Get-LiveRiskyNames)
    $heavyOk = ([string]$env:MM_OZELLIK_AGIR -eq '1')
    foreach ($c in $items) {
        $id = [string]$c.Id
        $fops = @(@($c.Ops) | Where-Object { [string]$_.T -eq 'Feature' })
        $names = @($fops | ForEach-Object { [string]$_.Name })
        $heavy = @($names | Where-Object { $script:LiveFeatLight -notcontains $_ })
        if ($block -ne '') { Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' ($block + ('; tur yap' + [char]0x0131 + 'lmad' + [char]0x0131 + ' (geri al' + [char]0x0131 + 'namayacak yar' + [char]0x0131 + 'm i' + [char]0x015F + ' b' + [char]0x0131 + 'rakmamak i' + [char]0x00E7 + 'in)')); Invoke-LiveRoundTrip $c 'oku'; continue }
        if ($script:LiveStopKinds -contains 'Feature') { Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' ('' + [char]0x00F6 + 'nceki bir Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i geri y' + [char]0x00FC + 'klenemedi ya da DISM s' + [char]0x00FC + 're s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x015F + 't' + [char]0x0131 + '; g' + [char]0x00FC + 'venlik i' + [char]0x00E7 + 'in bu tur yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'nizlendi'); Invoke-LiveRoundTrip $c 'oku'; continue }
        $busy = Get-ServicingBusy
        if ($busy -ne '') { Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' ($busy + ('; tur yap' + [char]0x0131 + 'lmad' + [char]0x0131 + ' (geri al' + [char]0x0131 + 'namayacak yar' + [char]0x0131 + 'm i' + [char]0x015F + ' b' + [char]0x0131 + 'rakmamak i' + [char]0x00E7 + 'in)')); Invoke-LiveRoundTrip $c 'oku'; continue }
        # bu turun degistirecegi ozellikler (simdiki durum istenenden farkliysa)
        $chg = @{}
        foreach ($op in $fops) { $w = Get-LiveFeatChange $op; if ($w -ne '') { $chg[[string]$op.Name] = $w } }
        # 1) bu bilgisayarda daha once geri yuklenemeyen ozellik: bir daha degistirilmez (yalnizca okunur ve onizlenir)
        $rk = @($chg.Keys | Where-Object { $risky -contains $_ } | Sort-Object)
        if ($rk.Count -gt 0) {
            Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' (('bu bilgisayarda daha ' + [char]0x00F6 + 'nce geri y' + [char]0x00FC + 'klenemedi: ') + ($rk -join ', ') + ('; canl' + [char]0x0131 + ' turda de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmez, yaln' + [char]0x0131 + 'zca okundu ve ' + [char]0x00F6 + 'nizlendi (liste: ozellik-riskli.json)'))
            Invoke-LiveRoundTrip $c 'oku'; continue
        }
        # 2) agir ozelligi KAPATMAK: geri acmak dosyalarini Windows Update'ten indirmeyi gerektirebilir (cihazda saatlerce acilamadi)
        $hk = @($chg.Keys | Where-Object { $chg[$_] -eq 'kapat' -and $script:LiveFeatLight -notcontains $_ } | Sort-Object)
        if ($hk.Count -gt 0 -and -not $heavyOk) {
            Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' (('a' + [char]0x011F + '' + [char]0x0131 + 'r Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i a' + [char]0x00E7 + '' + [char]0x0131 + 'k: ') + ($hk -join ', ') + ('; kapat' + [char]0x0131 + 'p geri a' + [char]0x00E7 + 'mak dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + ' Windows Update' + [char]0x2019 + 'ten indirmeyi gerektirebilir (bu bilgisayarda Sanal Makine Platformu b' + [char]0x00F6 + 'yle geri a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '). Canl' + [char]0x0131 + ' kapat' + [char]0x0131 + 'lmad' + [char]0x0131 + '; durum okundu ve ' + [char]0x00F6 + 'nizlendi. Bilerek denemek i' + [char]0x00E7 + 'in: MM_OZELLIK_AGIR=1'))
            Invoke-LiveRoundTrip $c 'oku'; continue
        }
        # 3a) Windows bilesenini de kaldiran oge: geri kurulum Windows Update'e bagli, varsayilan olarak yalnizca onizlenir
        $capRm = @(Get-LiveCapRemovals $c)
        if ($capRm.Count -gt 0 -and -not (Test-LiveCapLive)) {
            Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' (('Windows bile' + [char]0x015F + 'eni kald' + [char]0x0131 + 'rma canl' + [char]0x0131 + ' denenmedi (') + ($capRm -join ', ') + '): ' + $script:LiveCapWhy + ('. Durum okundu ve ' + [char]0x00F6 + 'nizlendi; bilerek denemek i' + [char]0x00E7 + 'in MM_BILESEN_CANLI=1'))
            Invoke-LiveRoundTrip $c 'oku'; continue
        }
        # 3) ozelligi KAPATAN tur, bu denetimde Windows yeniden baslatma beklerken yapilmaz: kapatilan ozelligi hemen geri acmak
        #    bu durumda basarisiz olabiliyor (cihazda Is Klasorleri 0x371B ile acilamadi) ve ozellik kapali kalir.
        $offk = @($chg.Keys | Where-Object { $chg[$_] -eq 'kapat' } | Sort-Object)
        if ($offk.Count -gt 0) {
            $rn = Get-LiveRebootNeed
            if ($rn -ne '') {
                Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' (('Windows bu denetimdeki ' + [char]0x00F6 + 'nceki bir bile' + [char]0x015F + 'en de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'latma bekliyor (') + $rn + ('); kapat' + [char]0x0131 + 'lan ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i hemen geri a' + [char]0x00E7 + 'mak bu durumda ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z olabiliyor (bu bilgisayarda ' + [char]0x0130 + '' + [char]0x015F + ' Klas' + [char]0x00F6 + 'rleri b' + [char]0x00F6 + 'yle a' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + '). ') + ($offk -join ', ') + (' canl' + [char]0x0131 + ' kapat' + [char]0x0131 + 'lmad' + [char]0x0131 + '; durum okundu ve ' + [char]0x00F6 + 'nizlendi, yeniden ba' + [char]0x015F + 'latmadan sonraki denetimde canl' + [char]0x0131 + ' denenir.'))
                Invoke-LiveRoundTrip $c 'oku'; continue
            }
        }
        # 4) bilesen hizmeti bos mu (onceki turun DISM'i ya da Windows bakim isi suruyorsa yeni istek asili kalir)
        $cb = Wait-LiveCbsIdle 180
        if ($cb -ne '') {
            [void]$script:LiveStopKinds.Add('Feature'); [void]$script:LiveStopKinds.Add('Cap')
            Add-LiveRow 'bilesen' ('tur:' + $id) 'BILGI' (('Windows bile' + [char]0x015F + 'en hizmeti ' + [char]0x00F6 + 'nceki i' + [char]0x015F + 'i s' + [char]0x00FC + 'rd' + [char]0x00FC + 'r' + [char]0x00FC + 'yor (') + $cb + ('); kalan ' + [char]0x00F6 + 'zellik ve bile' + [char]0x015F + 'en turlar' + [char]0x0131 + ' yap' + [char]0x0131 + 'lmad' + [char]0x0131 + ', yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'nizlendi'))
            Invoke-LiveRoundTrip $c 'oku'; continue
        }
        if ($heavy.Count -gt 0) { Add-LiveRow 'bilesen' ('agir:' + $id) 'BILGI' (('a' + [char]0x011F + '' + [char]0x0131 + 'r Windows ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'i (') + ($heavy -join ', ') + ('): canl' + [char]0x0131 + ' deneniyor; yeniden ba' + [char]0x015F + 'latma bekletebilir ya da Windows Update indirmesi gerektirebilir')) }
        # uygula -> dogrula -> geri al -> karsilastir (genel tur; satir 'tur' alaninda yazilir)
        Invoke-LiveRoundTrip $c 'tam'
        # DISM bu turda sure sinirini astiysa bilesen hizmeti arka planda calisiyor olabilir: kalan DISM turlari yapilmaz
        if ($script:DismTimedOut -and -not ($script:LiveStopKinds -contains 'Feature')) {
            [void]$script:LiveStopKinds.Add('Feature'); [void]$script:LiveStopKinds.Add('Cap')
            Add-LiveRow 'bilesen' ('dism:' + $id) 'UYARI' ('DISM s' + [char]0x00FC + 're s' + [char]0x0131 + 'n' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x015F + 't' + [char]0x0131 + '; kalan ' + [char]0x00F6 + 'zellik ve bile' + [char]0x015F + 'en turlar' + [char]0x0131 + ' yap' + [char]0x0131 + 'lmad' + [char]0x0131 + '. Bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'p tam denetimi tekrarlay' + [char]0x0131 + 'n.')
        }
    }
}

function Invoke-LiveCapTrip($C) {
    $id = [string]$C.Id
    $m = [string]@($C.Ops)[0].Match
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $defects = New-Object System.Collections.ArrayList
    Save-LiveInflight $id @(@{ K = 'Cap'; Name = $m; Data = 'kurulu' })
    Add-LiveCompTouched 'Cap' $m
    $t0 = Get-Date
    try {
        $mk1 = Get-LiveLogMark
        $r1 = Invoke-LiveJob 'Job_Plan' @{ Steps = (New-StepsFromIds @($id)); Preview = $false; RestorePoint = $false }
        $log1 = Get-LiveLogSince $mk1
        if ($r1.Err -ne '') { [void]$defects.Add(('kald' + [char]0x0131 + 'rma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r1.Err) }
        elseif ([int]$r1.Out.Errors -gt 0) { [void]$defects.Add(('kald' + [char]0x0131 + 'rma ') + [string]$r1.Out.Errors + ' hata verdi: ' + (Get-LiveShort ((Select-LiveLines $log1 'ERR') -join ' | ') 200)) }
        $st1 = Get-LiveCapState $m
        if ($defects.Count -eq 0 -and $st1 -eq 'kurulu') { [void]$defects.Add(('kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ' dendi ama DISM h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' kurulu g' + [char]0x00F6 + 'r' + [char]0x00FC + 'yor')) }
        $jf = Get-LiveJournalAfter $t0
        $st2 = ''
        $capWhy = ''
        if ($jf -eq '') { [void]$defects.Add(('geri alma g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
        else {
            $mk2 = Get-LiveLogMark
            $r2 = Invoke-LiveJob 'Job_Undo' @{ File = $jf }
            $log2 = Get-LiveLogSince $mk2
            if ($r2.Err -ne '') { [void]$defects.Add(('geri alma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r2.Err) }
            elseif ([int]$r2.Out.Errors -gt 0) { [void]$defects.Add('geri alma ' + [string]$r2.Out.Errors + ' hata verdi: ' + (Get-LiveShort ((Select-LiveLines $log2 'ERR') -join ' | ') 200)) }
            $st2 = Get-LiveCapState $m
            if ($st2 -ne 'kurulu') {
                [void]$defects.Add(('geri alma bile' + [char]0x015F + 'eni geri kuramad' + [char]0x0131 + ' (internet / Windows Update eri' + [char]0x015F + 'imi gerekir); elle: Add-WindowsCapability -Online -Name ') + $m)
                try { [void](Set-WinCapabilityState $m $true); $st2 = Get-LiveCapState $m } catch { $capWhy = [string]$_.Exception.Message }
            }
        }
        if ($st2 -eq 'kurulu') { Clear-LiveInflight }
        else {
            # geri kurulamadi: kalici kurtarma listesine alinir (sonraki tam denetimde yeniden denenir), bilesen turlari durur
            Add-LiveUnrestored $id @(@{ K = 'Cap'; Name = $m; Data = 'kurulu' }) (('bile' + [char]0x015F + 'en geri kurulamad' + [char]0x0131 + ': ') + $m + $(if ($capWhy -ne '') { ' (' + (Get-LiveShort $capWhy 200) + ')' } else { '' }))
            [void]$script:LiveStopKinds.Add('Cap')
            Clear-LiveInflight
        }
        $st = 'OK'; if ($defects.Count -gt 0) { $st = 'HATA' }
        Add-LiveRow 'bilesen' ('tur:' + $id) $st (('temsilci bile' + [char]0x015F + 'en ') + $m + (': kald' + [char]0x0131 + 'rma ' + [char]0x2192 + ' ') + $st1 + (' ' + [char]0x2192 + ' geri al ' + [char]0x2192 + ' ') + $st2 + $(if ($defects.Count -gt 0) { '; ' + ($defects -join ' | ') } else { '' })) $sw.ElapsedMilliseconds
    } catch {
        try { [void](Set-WinCapabilityState $m $true); Clear-LiveInflight } catch { }
        Add-LiveRow 'bilesen' ('tur:' + $id) 'HATA' (('tur ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message) $sw.ElapsedMilliseconds
    }
}

function Invoke-LiveAppxTrip([string]$Pattern) {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $defects = New-Object System.Collections.ArrayList
    $locs = @()
    try { $locs = @(Get-AppxSafe $Pattern | ForEach-Object { [string]$_.InstallLocation } | Where-Object { $_ -ne '' } | Sort-Object -Unique) } catch { }
    Save-LiveInflight ('appx:' + $Pattern) @(@{ K = 'Appx'; Name = $Pattern; Locs = $locs })
    $t0 = Get-Date
    try {
        $steps = @(@{ Id = 'Apps'; Title = 'Denetim: uygulama'; Ops = @(@{ T = 'Appx'; Name = $Pattern }); Reboot = $false })
        $mk1 = Get-LiveLogMark
        $r1 = Invoke-LiveJob 'Job_Plan' @{ Steps = $steps; Preview = $false; RestorePoint = $false }
        $log1 = Get-LiveLogSince $mk1
        if ($r1.Err -ne '') { [void]$defects.Add(('kald' + [char]0x0131 + 'rma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r1.Err) }
        elseif ([int]$r1.Out.Errors -gt 0) { [void]$defects.Add(('kald' + [char]0x0131 + 'rma ') + [string]$r1.Out.Errors + ' hata verdi: ' + (Get-LiveShort ((Select-LiveLines $log1 'ERR') -join ' | ') 200)) }
        $st1 = Get-LiveAppxState $Pattern
        if ($defects.Count -eq 0 -and $st1 -eq 'kurulu') { [void]$defects.Add(('kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + ' dendi ama paket h' + [char]0x00E2 + 'l' + [char]0x00E2 + ' y' + [char]0x00FC + 'kl' + [char]0x00FC + ' g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor')) }
        $jf = Get-LiveJournalAfter $t0
        $st2 = ''
        $note = ''
        if ($jf -eq '') { [void]$defects.Add(('geri alma g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + '' + [char]0x00FC + ' yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + '')) }
        else {
            $mk2 = Get-LiveLogMark
            $r2 = Invoke-LiveJob 'Job_Undo' @{ File = $jf }
            [void](Get-LiveLogSince $mk2)
            if ($r2.Err -ne '') { [void]$defects.Add(('geri alma ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $r2.Err) }
            $st2 = Get-LiveAppxState $Pattern
            if ($st2 -ne 'kurulu') {
                $note = ('uygulama paket klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nden geri kaydedilemedi (dosyalar silinmi' + [char]0x015F + '); Microsoft Store''dan yeniden y' + [char]0x00FC + 'klenebilir: ') + $Pattern
            }
        }
        Clear-LiveInflight
        $st = 'OK'
        if ($defects.Count -gt 0) { $st = 'HATA' } elseif ($note -ne '') { $st = 'UYARI' }
        $txt = 'temsilci uygulama ' + $Pattern + (': kald' + [char]0x0131 + 'rma ' + [char]0x2192 + ' ') + $st1 + (' ' + [char]0x2192 + ' geri al ' + [char]0x2192 + ' ') + $st2
        if ($note -ne '') { $txt += '; ' + $note }
        if ($defects.Count -gt 0) { $txt += '; ' + ($defects -join ' | ') }
        Add-LiveRow 'bilesen' 'uygulama-tur' $st $txt $sw.ElapsedMilliseconds
    } catch {
        try { Restore-LiveInflight } catch { }
        Add-LiveRow 'bilesen' 'uygulama-tur' 'HATA' (('tur ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message) $sw.ElapsedMilliseconds
    }
}

function Complete-LiveAudit {
    $mode = Get-LiveMode
    # bilerek yapilan olumsuz denemelerin gunluk satirlari gercekten yazildi mi (once gunluk son kez taranir)
    try { Invoke-SmokeFlush } catch { }
    try { [void](Read-SmokeLogDelta) } catch { }
    $missingLog = @(Get-SmokeExpectMissing)
    if ($missingLog.Count -gt 0) { Add-LiveRow 'ozet' 'beklenen-gunluk' 'HATA' (('olumsuz denemelerin g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k sat' + [char]0x0131 + 'r' + [char]0x0131 + ' yaz' + [char]0x0131 + 'lmad' + [char]0x0131 + ': ') + ($missingLog -join '; ')) }
    # sistem denetimin basindaki haline donmus olmali: tum ayarlarin olcumu yeniden alinip basla karsilastirilir
    $moved = New-Object System.Collections.ArrayList
    $outside = New-Object System.Collections.ArrayList
    $n = 0
    foreach ($c in @(Get-LiveApplicable)) {
        $id = [string]$c.Id
        if (-not $script:LiveState.ContainsKey($id)) { continue }
        $n++
        $now = -1
        try { $now = Get-TweakPending $c } catch { }
        if ([int]$now -ne [int]$script:LiveState[$id]) {
            $mv = $id + ' (' + $script:LiveState[$id] + ('' + [char]0x2192 + '') + $now + ')'
            if (Test-LiveMovedOutside $c) { [void]$outside.Add($mv) } else { [void]$moved.Add($mv) }
        }
    }
    if ($outside.Count -gt 0) { Add-LiveRow 'ozet' 'dis-degisiklik' 'UYARI' (('denetimin de' + [char]0x011F + 'i' + [char]0x015F + 'tirmedi' + [char]0x011F + 'i Windows ' + [char]0x00F6 + 'zellik/bile' + [char]0x015F + 'enleri denetim s' + [char]0x0131 + 'ras' + [char]0x0131 + 'nda ba' + [char]0x015F + 'ka bir yoldan de' + [char]0x011F + 'i' + [char]0x015F + 'ti (Windows Update, Windows ya da kullan' + [char]0x0131 + 'c' + [char]0x0131 + '): ') + ($outside -join ', ')) }
    # kurtarma listesindeki kayit denetim sirasinda eski durumuna donduyse listeden cikar, sonra kalanlari yaz
    try { Remove-LiveUnrestoredDone } catch { }
    # denetimin geri yukleyemedigi degisiklikler (kalici kurtarma listesi) ozet olarak yazilir
    $unr = @(Get-LiveUnrestored)
    if ($unr.Count -gt 0) { Add-LiveRow 'ozet' 'kurtarma-listesi' 'HATA' ([string]$unr.Count + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik geri y' + [char]0x00FC + 'klenemedi ve kurtarma listesinde bekliyor (bir sonraki tam denetimde yeniden denenir): ') + (($unr | ForEach-Object { [string]$_.Id + ': ' + (Get-LiveShort ([string]$_.Why) 120) }) -join ' | ')) }
    if ($n -eq 0) { Add-LiveRow 'ozet' 'son-durum' 'BILGI' ('ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + '' + [char]0x00FC + 'm' + [char]0x00FC + ' al' + [char]0x0131 + 'nmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' i' + [char]0x00E7 + 'in son durum kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + '') }
    elseif ($moved.Count -gt 0) { Add-LiveRow 'ozet' 'son-durum' 'HATA' (('denetim sonunda ba' + [char]0x015F + 'lang' + [char]0x0131 + '' + [char]0x00E7 + 'tan farkl' + [char]0x0131 + ' kalan ayarlar: ') + ($moved -join ', ')) }
    else { Add-LiveRow 'ozet' 'son-durum' 'OK' ([string]($n - $outside.Count) + (' ayar' + [char]0x0131 + 'n durumu denetim ba' + [char]0x015F + 'lang' + [char]0x0131 + 'c' + [char]0x0131 + 'yla ayn' + [char]0x0131 + '')) }
    # yarim kalan geri yukleme dosyasi
    $f = Join-Path (Get-LiveDir) 'ozellik-yarim.json'
    if (Test-Path -LiteralPath $f) { Add-LiveRow 'ozet' 'yarim' 'UYARI' ('diskte yar' + [char]0x0131 + 'm kalan geri y' + [char]0x00FC + 'kleme dosyas' + [char]0x0131 + ' duruyor (bir sonraki tam denetimde otomatik geri y' + [char]0x00FC + 'klenir)') }
    # sayilar
    $ok = Get-LiveCount 'OK'; $err = Get-LiveCount 'HATA'; $warn = Get-LiveCount 'UYARI'; $skip = Get-LiveCount 'ATLA'; $info = Get-LiveCount 'BILGI'
    $sec = 0
    try { if ($null -ne $script:LiveT0) { $sec = [int]((Get-Date) - $script:LiveT0).TotalSeconds } } catch { }
    $byArea = @{}
    foreach ($r in @($script:LiveRows)) { if ($r.Durum -eq 'HATA') { $byArea[[string]$r.Alan] = [int]$byArea[[string]$r.Alan] + 1 } }
    $areaTxt = ''
    if ($byArea.Count -gt 0) { $areaTxt = ' (' + ((@($byArea.Keys | Sort-Object) | ForEach-Object { $_ + '=' + $byArea[$_] }) -join ', ') + ')' }
    Add-SmokeLine (('canl' + [char]0x0131 + ' ' + [char]0x00F6 + 'zet: kip=') + $mode + '; ' + $ok + ' tamam, ' + $err + ' hata' + $areaTxt + ', ' + $warn + (' uyar' + [char]0x0131 + ', ') + $skip + (' atland' + [char]0x0131 + ', ') + $info + (' bilgi; s' + [char]0x00FC + 're ') + (Format-LiveMs ($sec * 1000)))
    try { Add-SmokeLine (('canl' + [char]0x0131 + ' ' + [char]0x00F6 + 'zet: ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' tablo ') + [string]$script:LiveTsv) } catch { }
    try { [Console]::WriteLine('  ozet: ' + $ok + ' tamam, ' + $err + ' hata, ' + $warn + ' uyari, ' + $skip + ' atlandi') } catch { }
}

# ---------------- duman adimi: "LiveCheck" ----------------
# Arg: ortam | olcum | tur:<grup> | etki | sapma | arac | is:<grup> | sensor | bulgu | ozet
function Test-SmokeLive([string]$Arg) {
    $parts = $Arg.Split(':')
    $kind = $parts[0]
    $sub = ''
    if ($parts.Count -gt 1) { $sub = $parts[1] }
    if ($null -eq $script:LiveT0) { $script:LiveT0 = Get-Date }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    Add-SmokeLine (('    canl' + [char]0x0131 + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm: ') + $Arg + (' ba' + [char]0x015F + 'lad' + [char]0x0131 + ''))
    try {
        switch ($kind) {
            'ortam'  { Test-LiveEnv }
            'olcum'  { Test-LiveMeasure }
            'tur'    { Test-LiveRoundTrips $sub }
            'etki'   { Test-LiveVisual; Test-LivePower }
            'sapma'  { Test-LiveDrift }
            'arac'   { Test-LiveTools }
            'is'     { Test-LiveJobs $sub }
            'bilesen' { Test-LiveComponents }
            'sensor' { Test-LiveSensors }
            'bulgu'  { Test-LiveFindings }
            'ozet'   { Complete-LiveAudit }
            default  { Add-LiveRow 'ozellik' $Arg 'HATA' ('bilinmeyen denetim b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm' + [char]0x00FC + '') }
        }
    } catch {
        Add-LiveRow $kind $sub 'HATA' (('b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm ' + [char]0x00E7 + '' + [char]0x00F6 + 'kt' + [char]0x00FC + ': ') + $_.Exception.Message + (' (sat' + [char]0x0131 + 'r ') + [string]$_.InvocationInfo.ScriptLineNumber + ')')
        if ((Get-LiveMode) -eq 'tam') { try { Restore-LiveInflight } catch { } }
    }
    Add-SmokeLine (('    canl' + [char]0x0131 + ' b' + [char]0x00F6 + 'l' + [char]0x00FC + 'm: ') + $Arg + ' bitti (' + (Format-LiveMs $sw.ElapsedMilliseconds) + ')')
    try { Invoke-SmokeFlush } catch { }
}

# ---------------- cokme kaydi: yakalanmayan istisna ve konsol sinyali kancalari, duman cikis korumasi ----------------
# ---------------- Cokme kaydi: yakalanmayan istisnalar ve konsol sinyalleri ----------------
# Arka plan is parcaciginda patlayan bir istisna ya da konsola gelen bir kapatma sinyali sureci sessizce oldurur; ne kullanici ne duman
# testi nedenini gorur. Bu kanca uc kaynagi dosyaya yazar: AppDomain.UnhandledException, TaskScheduler.UnobservedTaskException ve
# SetConsoleCtrlHandler (Ctrl+C / Ctrl+Break / konsol penceresi kapatildi / oturum kapaniyor / sistem kapaniyor).
# Ctrl+C ve Ctrl+Break yutulur (uygulamanin kendi kapanis akisi vardir); pencere/oturum kapanisi engellenemez, yalnizca kaydedilir.
$script:CrashHookOn = $false
function Initialize-CrashHooks([string]$Path) {
    if ($script:CrashHookOn) { return $true }
    try {
        if (-not ('WH.CrashLog' -as [type])) {
            $src = @'
using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Threading.Tasks;
namespace WH {
    public static class CrashLog {
        public delegate bool CtrlHandler(int ctrlType);
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern bool SetConsoleCtrlHandler(CtrlHandler handler, bool add);
        static CtrlHandler _ctrl;
        static string _path;
        static readonly object _lock = new object();
        public static int LastCtrl = -1;
        public static int Count = 0;
        public static bool Install(string path) {
            _path = path;
            try { AppDomain.CurrentDomain.UnhandledException += OnUnhandled; } catch { }
            try { TaskScheduler.UnobservedTaskException += OnTask; } catch { }
            bool ok = false;
            try { _ctrl = new CtrlHandler(OnCtrl); ok = SetConsoleCtrlHandler(_ctrl, true); } catch { }
            return ok;
        }
        public static void SetPath(string path) { _path = path; }
        public static void Write(string text) {
            Count++;
            try { lock (_lock) { File.AppendAllText(_path, DateTime.Now.ToString("HH:mm:ss.fff") + "  " + text + "\r\n"); } } catch { }
        }
        static void OnUnhandled(object s, UnhandledExceptionEventArgs e) {
            object ex = e.ExceptionObject;
            Write("HATA  yakalanmayan istisna (" + (e.IsTerminating ? "surec kapaniyor" : "surec devam ediyor") + "): " + (ex == null ? "?" : ex.ToString()));
        }
        static void OnTask(object s, UnobservedTaskExceptionEventArgs e) {
            Write("UYARI  gozlenmeyen gorev hatasi: " + (e.Exception == null ? "?" : e.Exception.ToString()));
            try { e.SetObserved(); } catch { }
        }
        static bool OnCtrl(int t) {
            LastCtrl = t;
            string n = t == 0 ? "Ctrl+C (yutuldu)" : t == 1 ? "Ctrl+Break (yutuldu)" : t == 2 ? "konsol penceresi kapatildi" : t == 5 ? "oturum kapatiliyor" : t == 6 ? "sistem kapaniyor" : ("tur " + t);
            Write((t <= 1 ? "UYARI" : "HATA") + "  konsol denetim sinyali: " + n);
            return t <= 1;
        }
    }
}
'@
            Add-Type -TypeDefinition $src -ErrorAction Stop
        }
        $r = [WH.CrashLog]::Install($Path)
        $script:CrashHookOn = $true
        return [bool]$r
    } catch {
        try { Write-CrashLog (('' + [char]0x00C7 + '' + [char]0x00F6 + 'kme kancas' + [char]0x0131 + ' kurulamad' + [char]0x0131 + ': ') + $_.Exception.Message) } catch { }
        return $false
    }
}

# Duman testi surerken kullanicinin kapatma istegi (pencere X'i, tepsi > Cikis) denetimi yarida kesmesin: pencere gizlenir, istek kaydedilir.
# Durdurmak isteyen konsol penceresini kapatir (bu sinyal yukaridaki kancayla gunluge duser). Testin kendi bitisi SmokeFinishing ile gecer.
$script:SmokeFinishing = $false
function Test-SmokeExitBlocked {
    if (-not $script:SmokeMode -or $script:SmokeFinishing) { return $false }
    try { Add-SmokeWarn ('' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' iste' + [char]0x011F + 'i duman testi bitene dek yok say' + [char]0x0131 + 'ld' + [char]0x0131 + ' (durdurmak i' + [char]0x00E7 + 'in konsol penceresini kapat' + [char]0x0131 + 'n)') } catch { }
    try { Add-Trace ('duman: ' + [char]0x00E7 + '' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + ' iste' + [char]0x011F + 'i yok say' + [char]0x0131 + 'ld' + [char]0x0131 + '') } catch { }
    try { $script:Win.Hide() } catch { }
    return $true
}

function Init-Page_backup {
    Register-Tabs 'bk' $script:BkTabs { param($s, $e) Invoke-Safe { Set-BkTab ([string]$s.Tag) } 'Sekme' }
    Init-BkFiles
    $ui.bk_AddSrc.Add_Click({ Invoke-Safe { Add-BkSource } 'Ekle' })
    $ui.bk_Dest.Add_Click({ Invoke-Safe { Set-BkDest } 'Hedef' })
    $ui.bk_Preview.Add_Click({ Invoke-Safe { Start-BackupNow $true } ([string][char]0x00D6 + 'nizle') })
    $ui.bk_Run.Add_Click({ Invoke-Safe { Start-BackupNow $false } 'Yedekle' })
    $ui.bk_Restore.Add_Click({ Invoke-Safe { Start-BkRestore } ('Geri y' + [char]0x00FC + 'kle') })
    $ui.bk_ModeCopy.Add_Click({ Invoke-Safe { Update-BkMode 'Kopya' } ('Y' + [char]0x00F6 + 'ntem') })
    $ui.bk_ModeDate.Add_Click({ Invoke-Safe { Update-BkMode 'Tarihli' } ('Y' + [char]0x00F6 + 'ntem') })
    $ui.bk_RbRefresh.Add_Click({
        Invoke-Safe {
            if ($script:BkTab -eq 'recycle') { $script:BkRecycle = $null; Render-BkRecycle }
            else { $script:BkShadow = $null; Set-BkTab $script:BkTab }
        } 'Yenile'
    })
    $ui.bk_RbRestore.Add_Click({
        Invoke-Safe {
            $sel = (Get-CheckedData $ui.bk_List)
            if ($sel.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce dosya i' + [char]0x015F + 'aretleyin.') 'warn'; return }
            $paths = @($sel | ForEach-Object { [string]$_.Path })
            [void](Start-Async 'RbRestore' 'Job_RecycleRestore' @{ Paths = $paths } {
                param($r)
                if ($null -ne $r) { Show-Toast ([string]$r.Restored + (' dosya geri y' + [char]0x00FC + 'klendi.')) 'good' }
                $script:BkRecycle = $null
                if ($script:BkTab -eq 'recycle') { Render-BkRecycle }
            } ('Geri y' + [char]0x00FC + 'kleniyor'))
        } ('Geri y' + [char]0x00FC + 'kle')
    })
    $ui.bk_RpNew.Add_Click({
        Invoke-Safe {
            [void](Start-Async 'Action' 'Job_Action' @{ Key = 'RpCreate' } { param($r) $script:BkShadow = $null; if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turuldu.') 'good' } else { Show-Toast ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }; if ($script:BkTab -eq 'points') { Render-BkPoints } } ('Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131))
        } 'Nokta'
    })
    $ui.bk_RpOpen.Add_Click({ Invoke-Safe { Start-Process -FilePath 'rstrui.exe' | Out-Null } ('Geri y' + [char]0x00FC + 'kle') })
    $ui.bk_KitRun.Add_Click({ Invoke-Safe { Start-BkKit } 'Kit' })
    $ui.bk_PhotoGet.Add_Click({
        Invoke-Safe {
            [void](Start-Async 'Foss' 'Job_WingetInstall' @{ Id = 'CGSecurity.TestDisk' } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast 'TestDisk/PhotoRec kuruldu.' 'good' } else { Show-Toast ('Kurulamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn' }
                $script:BkPhoto = $null
                if ($script:BkTab -eq 'recover') { Render-BkRecover }
            } 'TestDisk ve PhotoRec kuruluyor')
        } 'Kur'
    })
    $ui.bk_PhotoRun.Add_Click({
        Invoke-Safe {
            $p = [string]$script:BkPhoto
            if ($p -eq '') { Show-Toast ('PhotoRec bulunamad' + [char]0x0131 + '; ' + [char]0x00F6 + 'nce kurun.') 'warn'; return }
            Start-Process -FilePath $p | Out-Null
        } 'PhotoRec'
    })
}

function Select-Sub_backup([string]$Sub) {
    if (-not (Select-TabChip 'bk' $Sub)) { Set-BkTab $Sub }
}

function Show-Page_backup {
    $t = Get-TabKey 'bk' $script:BkTabs 'files'
    Set-BkTab $t
}

# ==================================================================
#  SAYFA: Sirket Yonetimi  (rapor ve envanter, sirket ilkeleri, zamanlanmis gorevler, profil disa/ice aktarma)
# ==================================================================
$script:CoTabs = @('report', 'policy', 'sched', 'profile')
$script:CoTab = 'report'
$script:CoItems = @()
$script:CoSel = @{}
$script:CoInv = $null
$script:CoTasks = $null

function Set-CoTab([string]$Tab) {
    $script:CoTab = $Tab
    Set-Visible $ui.co_OrgBox ($Tab -eq 'report')
    switch ($Tab) {
        'report' { Show-OnlyBar 'co' @('co_Report', 'co_OpenReports', 'co_Inv'); Render-CoReport }
        'policy' { Show-OnlyBar 'co' @('co_P1', 'co_P0', 'co_Preview', 'co_Apply'); Render-CoPolicy }
        'sched' { Show-OnlyBar 'co' @('co_TaskRefresh', 'co_TaskEdit'); Render-CoSched }
        'profile' { Show-OnlyBar 'co' @('co_Export', 'co_Import'); Render-CoProfile }
    }
}

# ---------------- rapor ve envanter ----------------
function Render-CoReport {
    $ui.co_List.Children.Clear()
    $st = $script:Settings
    $ui.co_Org.Text = (Tr $([string]$st.Org))
    $ui.co_Contact.Text = (Tr $([string]$st.Contact))
    $lr = [string]$st.LastReport
    if ($lr -eq '') { $lr = ('hen' + [char]0x00FC + 'z olu' + [char]0x015F + 'turulmad' + [char]0x0131) }
    Add-KvRow $ui.co_List 'Son rapor' $lr
    if ([int]$st.LastHealth -gt 0) { Add-KvRow $ui.co_List ('Son sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131) ([string]$st.LastHealth) }
    $p = $sync.Profile
    if ($null -ne $p) {
        Add-KvRow $ui.co_List 'Bilgisayar' ([string]$p.Hostname + (' ' + [char]0x00B7 + ' ') + [string]$p.Model)
        $mg = ('Ba' + [char]0x011F + [char]0x0131 + 'ms' + [char]0x0131 + 'z (i' + [char]0x015F + ' grubu)')
        if ([string]$p.JoinType -match 'Domain') { $mg = ('Etki alan' + [char]0x0131 + ': ') + [string]$p.Domain } elseif ([string]$p.JoinType -match 'AzureAD') { $mg = 'Microsoft Entra ID (Azure AD)' }
        if ($p.MdmManaged) { $mg += (' ' + [char]0x00B7 + ' MDM/Intune') }
        Add-KvRow $ui.co_List ('Y' + [char]0x00F6 + 'netim') $mg
    }
    if ($null -ne $script:CoInv) {
        foreach ($sec in @($script:CoInv)) {
            Add-HeadRow $ui.co_List ([string]$sec.Title)
            $hdr = @($sec.Headers)
            $n = 0
            foreach ($r in @($sec.Rows)) {
                if ($n -ge 14) { Add-Note $ui.co_List ('... ve ' + [string](@($sec.Rows).Count - 14) + (' sat' + [char]0x0131 + 'r daha (tam liste HTML raporda).')); break }
                $cells = @($r)
                if ($cells.Count -ge 2 -and $hdr.Count -le 2) { Add-KvRow $ui.co_List ([string]$cells[0]) ([string]$cells[1]) }
                else { $row = New-ItemRow @{ Title = [string]$cells[0]; Detail = ((@($cells | Select-Object -Skip 1) | Where-Object { [string]$_ -ne '' }) -join (' ' + [char]0x00B7 + ' ')); BrCol = 'BrAccent2' } @{} $false $false; [void]$ui.co_List.Children.Add($row) }
                $n++
            }
        }
        $ui.co_Foot.Text = (Tr $(('Envanter bilgisayar ' + [char]0x00FC + 'zerinde okundu; hi' + [char]0x00E7 + 'bir yere g' + [char]0x00F6 + 'nderilmez. Tam ve yazd' + [char]0x0131 + 'r' + [char]0x0131 + 'labilir s' + [char]0x00FC + 'r' + [char]0x00FC + 'm i' + [char]0x00E7 + 'in ' + [char]0x201C + 'Rapor olu' + [char]0x015F + 'tur' + [char]0x201D + '.')))
    } else {
        Add-Note $ui.co_List ([string][char]0x201C + 'Envanteri g' + [char]0x00F6 + 'ster' + [char]0x201D + ' donan' + [char]0x0131 + 'm, disk, a' + [char]0x011F + ', kullan' + [char]0x0131 + 'c' + [char]0x0131 + ', g' + [char]0x00FC + 'ncelleme ve program listesini okur. ' + [char]0x201C + 'Rapor olu' + [char]0x015F + 'tur' + [char]0x201D + ' ayn' + [char]0x0131 + ' bilgileri sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + 'yla birlikte HTML dosyas' + [char]0x0131 + ' yapar (yazd' + [char]0x0131 + 'r/PDF i' + [char]0x00E7 + 'in uygundur).')
        $ui.co_Foot.Text = (Tr $(('Kurum ad' + [char]0x0131 + ' ve ileti' + [char]0x015F + 'im bilgisi raporun ' + [char]0x00FC + 'st k' + [char]0x0131 + 'sm' + [char]0x0131 + 'nda g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.')))
    }
}

function Start-CoInventory {
    Set-ListNote $ui.co_List ('Envanter toplan' + [char]0x0131 + 'yor... (30-60 saniye s' + [char]0x00FC + 'rebilir)')
    [void](Start-Async 'Inventory' 'Job_Inventory' @{} {
        param($r)
        if ($null -eq $r) { Set-ListNote $ui.co_List ('Envanter okunamad' + [char]0x0131 + '.') 'bad'; return }
        $script:CoInv = @($r.Sections)
        if ($script:CoTab -eq 'report') { Render-CoReport }
    } ('Envanter toplan' + [char]0x0131 + 'yor'))
}

# ---------------- sirket ilkeleri ----------------
$script:H_CoChk = { param($s, $e) $script:CoSel[[string]$s.Tag] = ($s.IsChecked -eq $true); Update-CoFoot }

function Update-CoFoot {
    $n = 0
    foreach ($k in @($script:CoSel.Keys)) { if ($script:CoSel[$k] -eq $true) { $n++ } }
    $ui.co_Foot.Text = (Tr $(([string]$n + (' ilke se' + [char]0x00E7 + 'ili. Bunlar kurum ilkeleridir; Intune/GPO ile y' + [char]0x00F6 + 'netilen bilgisayarlarda BT biriminizle g' + [char]0x00F6 + 'r' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'n.'))))
}

function Render-CoPolicy {
    $ui.co_List.Children.Clear()
    if ($script:CoItems.Count -eq 0) { $script:CoItems = (Get-CatalogFor 'org' '' $sync.Profile) }
    $last = ''
    foreach ($c in $script:CoItems) {
        $cn = [string]$script:CatNames[[string]$c.Cat]
        if ($cn -ne $last) { Add-HeadRow $ui.co_List $cn; $last = $cn }
        $lv = Get-OpLevelInfo ([int]$c.Level)
        $det = [string]$c.Desc
        if ($det.Length -gt 230) { $det = $det.Substring(0, 227) + '...' }
        $flags = @()
        if ($c.Reboot -eq $true) { $flags += ('yeniden ba' + [char]0x015F + 'latma gerekir') }
        if ($c.Irrev -eq $true) { $flags += ('geri al' + [char]0x0131 + 'namaz') }
        if ($flags.Count -gt 0) { $det += ('  [' + ($flags -join ', ') + ']') }
        $row = New-ItemRow @{ Title = [string]$c.Title; Detail = $det; Tag = $lv.Text; BrCol = $lv.Br } @{ Id = [string]$c.Id } $true ($script:CoSel[[string]$c.Id] -eq $true)
        $chk = $row.FindName('Chk')
        $chk.Tag = [string]$c.Id
        $chk.Add_Click($script:H_CoChk)
        [void]$ui.co_List.Children.Add($row)
    }
    Update-CoFoot
}

function Get-CoSelectedIds {
    $ids = New-Object System.Collections.ArrayList
    foreach ($c in $script:CoItems) { if ($script:CoSel[[string]$c.Id] -eq $true) { [void]$ids.Add([string]$c.Id) } }
    return , $ids.ToArray()
}

function Start-CoApply([bool]$Preview) {
    $ids = Get-CoSelectedIds
    if ($ids.Count -eq 0) { Show-Toast ([string][char]0x00D6 + 'nce ilke se' + [char]0x00E7 + 'in.') 'warn'; return }
    $steps = New-StepsFromIds $ids
    if ($Preview) { Start-PlanJob $steps ([string][char]0x00D6 + 'nizleme: ' + [char]0x015F + 'irket ilkeleri') $true $false; return }
    $script:PendingSteps = $steps
    $names = @($ids | ForEach-Object { $c = Get-CatalogItem $_; if ($null -ne $c) { [string]$c.Title } })
    Show-Confirm ([string][char]0x015E + 'irket ilkelerini uygula') ([string]$ids.Count + " ilke uygulanacak:`r`n`r`n" + (Format-NameList $names 10) + ("`r`n`r`nEski de" + [char]0x011F + "erler kaydedilir; Ge" + [char]0x00E7 + "mi" + [char]0x015F + " sayfas" + [char]0x0131 + "ndan geri al" + [char]0x0131 + "nabilir.")) 'Uygula' {
        Start-PlanJob $script:PendingSteps ([string][char]0x015E + 'irket ilkeleri uygulan' + [char]0x0131 + 'yor') $false ($script:Settings.RestorePoint -eq $true)
    }
}

# ---------------- zamanlanmis gorevler ----------------
$script:TaskNames = @{ Bakim = ('Haftal' + [char]0x0131 + 'k bak' + [char]0x0131 + 'm'); Yedek = ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k dosya yede' + [char]0x011F + 'i'); Rapor = ('Haftal' + [char]0x0131 + 'k sistem raporu'); Tepsi = ('Oturum a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'nda tepside ba' + [char]0x015F + 'lat') }

$script:H_CoRunTask = {
    param($s, $e)
    Invoke-Safe {
        $n = [string]$s.Tag.Name
        try { Start-ScheduledTask -TaskPath $script:TaskFolder -TaskName $n -ErrorAction Stop; Show-Toast ('G' + [char]0x00F6 + 'rev ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + ' (arka planda ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'r).') 'good' }
        catch { Show-Toast (('Ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'warn' }
    } ('G' + [char]0x00F6 + 'rev')
}

function Render-CoSched {
    $ui.co_List.Children.Clear()
    $rows = $script:CoTasks
    if ($null -eq $rows) { Set-ListNote $ui.co_List ('G' + [char]0x00F6 + 'revler okunuyor...'); Load-CoTasks; return }
    $rows = @($rows)
    if ($rows.Count -eq 0) {
        Add-Note $ui.co_List ('Kurulu zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'rev yok. Ayarlar sayfas' + [char]0x0131 + 'ndan haftal' + [char]0x0131 + 'k bak' + [char]0x0131 + 'm, g' + [char]0x00FC + 'nl' + [char]0x00FC + 'k yedek veya haftal' + [char]0x0131 + 'k rapor g' + [char]0x00F6 + 'revlerini a' + [char]0x00E7 + 'abilirsiniz.')
        $ui.co_Foot.Text = (Tr $(''))
        return
    }
    foreach ($t in $rows) {
        $title = [string]$script:TaskNames[[string]$t.Name]
        if ($title -eq '') { $title = [string]$t.Name }
        $det = ('Sonraki: ' + $(if ([string]$t.Next -ne '') { [string]$t.Next } else { '-' }) + (' ' + [char]0x00B7 + ' Son ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'ma: ') + $(if ([string]$t.Last -ne '') { [string]$t.Last } else { '-' }))
        $br = 'BrGood'
        if ([string]$t.State -eq 'Disabled') { $br = 'BrFaint' }
        elseif ([int]$t.Result -ne 0 -and [int]$t.Result -ne 267011 -and [int]$t.Result -ne 267009) { $br = 'BrWarn' }
        $row = New-ItemRow @{ Title = $title; Detail = $det; Tag = [string]$t.State; BrCol = $br; Btn1 = ([string][char]0x015E + 'imdi ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r') } @{ Name = [string]$t.Name } $false $false
        $row.FindName('Act').Add_Click($script:H_CoRunTask)
        [void]$ui.co_List.Children.Add($row)
    }
    $ui.co_Foot.Text = (Tr $(('G' + [char]0x00F6 + 'revler oturum a' + [char]0x00E7 + [char]0x0131 + 'k oldu' + [char]0x011F + 'unda, gizli pencerede ve en y' + [char]0x00FC + 'ksek yetkiyle ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'r. Kay' + [char]0x0131 + 'tlar Kay' + [char]0x0131 + 'tlar klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'ndedir.')))
}

function Load-CoTasks {
    [void](Start-Async 'TaskInfo' 'Job_TaskInfo' @{} {
        param($r)
        $script:CoTasks = @(Get-ResultRows $r)
        if ($script:CoTab -eq 'sched') { Render-CoSched }
    } ('G' + [char]0x00F6 + 'revler okunuyor') $true $true)
}

# ---------------- profil ----------------
function Render-CoProfile {
    $ui.co_List.Children.Clear()
    Add-HeadRow $ui.co_List ('Bir kez haz' + [char]0x0131 + 'rlay' + [char]0x0131 + 'n, bir' + [char]0x00E7 + 'ok bilgisayara uygulay' + [char]0x0131 + 'n')
    $lines = @(
        ('1. Bu bilgisayarda Optimizasyon, G' + [char]0x00FC + 'venlik, ' + [char]0x015E + 'irket ilkeleri sayfalar' + [char]0x0131 + 'nda istedi' + [char]0x011F + 'iniz ayarlar' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin (Hizmetler ve Uygulamalar sayfas' + [char]0x0131 + 'ndaki i' + [char]0x015F + 'aretler de eklenir).'),
        ('2. ' + [char]0x201C + 'Profili d' + [char]0x0131 + [char]0x015F + 'a aktar...' + [char]0x201D + ' ile bir .json dosyas' + [char]0x0131 + ' kaydedin. Dosya yaln' + [char]0x0131 + 'zca ayar kimliklerini ve hizmet/uygulama adlar' + [char]0x0131 + 'n' + [char]0x0131 + ' i' + [char]0x00E7 + 'erir; hi' + [char]0x00E7 + 'bir ki' + [char]0x015F + 'isel veri yoktur.'),
        ('3. Di' + [char]0x011F + 'er bilgisayarlarda ' + [char]0x201C + 'Profil uygula...' + [char]0x201D + ' ile ya da komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'yla uygulay' + [char]0x0131 + 'n. ' + [char]0x00D6 + 'nce ' + [char]0x00F6 + 'nizleme g' + [char]0x00F6 + 'sterilir; her bilgisayarda ayr' + [char]0x0131 + ' geri alma kayd' + [char]0x0131 + ' tutulur.')
    )
    foreach ($l in $lines) { Add-Note $ui.co_List $l }
    Add-HeadRow $ui.co_List ('Komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' (GPO, Intune, zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'rev, uzak betik)')
    $cmd = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "C:\Yol\Multimizer.ps1" -Cli -Gorev Profil -Profil "C:\Yol\profil.json" -Sessiz'
    $row = New-ItemRow @{ Title = $cmd; Detail = ('Y' + [char]0x00F6 + 'netici yetkisiyle ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'r; ' + [char]0x00E7 + [char]0x0131 + 'kt' + [char]0x0131 + ' Kay' + [char]0x0131 + 'tlar klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'ne yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r. Di' + [char]0x011F + 'er g' + [char]0x00F6 + 'revler: Bakim, Rapor, Yedekle, Durum, Guncelle.'); BrCol = 'BrAccent'; Btn1 = 'Kopyala' } @{ Cmd = $cmd } $false $false
    $row.FindName('Act').Add_Click({ param($s, $e) try { [System.Windows.Clipboard]::SetText([string]$s.Tag.Cmd); Show-Toast ('Komut panoya kopyaland' + [char]0x0131 + '.') 'good' } catch { Show-Toast ('Kopyalanamad' + [char]0x0131 + '.') 'warn' } })
    [void]$ui.co_List.Children.Add($row)
    $ui.co_Foot.Text = (Tr $(('Profil uygulan' + [char]0x0131 + 'rken yaln' + [char]0x0131 + 'zca katalogdaki ayarlar, korumas' + [char]0x0131 + 'z hizmetler ve listelenmi' + [char]0x015F + ' Ma' + [char]0x011F + 'aza uygulamalar' + [char]0x0131 + ' i' + [char]0x015F + 'lenir; ba' + [char]0x015F + 'ka bir komut ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lmaz.')))
}

function Get-CoProfileSelection {
    $ids = New-Object System.Collections.ArrayList
    foreach ($c in $script:OpItems) { if ($script:OpSel[[string]$c.Id] -eq $true) { [void]$ids.Add([string]$c.Id) } }
    foreach ($c in $script:ScItems) { if ($script:ScSel[[string]$c.Id] -eq $true) { [void]$ids.Add([string]$c.Id) } }
    foreach ($c in $script:CoItems) { if ($script:CoSel[[string]$c.Id] -eq $true) { [void]$ids.Add([string]$c.Id) } }
    $svc = New-Object System.Collections.ArrayList
    if ($script:Pages.ContainsKey('services')) {
        foreach ($d in (Get-CheckedData $ui.sv_List)) {
            $m = 'Off'; if ([string]$d.Rec -eq 'Man') { $m = 'Man' }
            [void]$svc.Add(@{ Name = [string]$d.Name; Mode = $m })
        }
    }
    $apps = New-Object System.Collections.ArrayList
    if ($script:Pages.ContainsKey('apps') -and $script:ApTab -eq 'store') {
        foreach ($d in (Get-CheckedData $ui.ap_List)) { [void]$apps.Add([string]$d.Pattern) }
    }
    return @{ Ids = $ids.ToArray(); Services = $svc.ToArray(); Apps = $apps.ToArray() }
}

function Start-CoExport {
    $sel = Get-CoProfileSelection
    $n = @($sel.Ids).Count + @($sel.Services).Count + @($sel.Apps).Count
    if ($n -eq 0) { Show-Toast ('D' + [char]0x0131 + [char]0x015F + 'a aktar' + [char]0x0131 + 'lacak se' + [char]0x00E7 + 'im yok. ' + [char]0x00D6 + 'nce Optimizasyon / G' + [char]0x00FC + 'venlik / ' + [char]0x015E + 'irket ilkeleri sayfalar' + [char]0x0131 + 'nda ayar i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $def = [string]$script:Settings.Org
    if ($def -eq '') { $def = ([string][char]0x015E + 'irket profili') }
    $script:PendingSel = $sel
    Show-Input ('Profil ad' + [char]0x0131) ([string]$n + (' ' + [char]0x00F6 + [char]0x011F + 'e profile eklenecek. Profile bir ad verin:')) $def {
        param($name)
        $file = Select-SaveFile 'Profil (*.json)|*.json' 'sirket-profili.json'
        if ($file -eq '') { return }
        try {
            $o = New-ProfileObject $name $script:PendingSel.Ids $script:PendingSel.Services $script:PendingSel.Apps
            Save-JsonFile $o $file 6
            Show-Toast ('Profil kaydedildi: ' + $file) 'good'
        } catch { Show-Toast ('Kaydedilemedi: ' + $_.Exception.Message) 'bad' }
    }
}

function Start-CoImport {
    $file = Select-OpenFile 'Profil (*.json)|*.json'
    if ($file -eq '') { return }
    $prof = $null
    try { $prof = Read-ProfileFile $file } catch { Show-Toast ($_.Exception.Message) 'bad'; return }
    $script:PendingProfile = $file
    $notes = New-Object System.Collections.ArrayList
    [void](Get-ProfileSteps $prof $notes)
    $txt = ('Profil: ' + [string]$prof.Name + "`r`n" + [string]@($prof.Tweaks).Count + ' ayar, ' + [string]@($prof.Services).Count + ' hizmet, ' + [string]@($prof.Apps).Count + ' uygulama')
    if ($notes.Count -gt 0) { $txt += ("`r`n`r`nAtlanacaklar:`r`n" + (Format-NameList $notes 6)) }
    $txt += (("`r`n`r`n" + [char]0x00D6 + "nce " + [char]0x00F6 + "nizleme " + [char]0x00E7 + "al" + [char]0x0131 + [char]0x015F + "t" + [char]0x0131 + "r" + [char]0x0131 + "l" + [char]0x0131 + "r; hi" + [char]0x00E7 + "bir " + [char]0x015F + "ey de" + [char]0x011F + "i" + [char]0x015F + "mez."))
    Show-Confirm ('Profili ' + [char]0x00F6 + 'nizle') $txt ([string][char]0x00D6 + 'nizle') {
        [void](Start-Async 'ProfPrev' 'Job_ProfileApply' @{ Path = $script:PendingProfile; Preview = $true; RestorePoint = $false } {
            param($r)
            if ($null -eq $r) { Show-Toast ([string][char]0x00D6 + 'nizleme tamamlanamad' + [char]0x0131 + '.') 'bad'; return }
            Show-Confirm 'Profili uygula' ([string][char]0x00D6 + 'nizleme g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte. Profil ' + [char]0x015F + 'imdi ger' + [char]0x00E7 + 'ekten uygulans' + [char]0x0131 + 'n m' + [char]0x0131 + '? (Geri y' + [char]0x00FC + 'kleme noktas' + [char]0x0131 + ' olu' + [char]0x015F + 'turulur, de' + [char]0x011F + 'i' + [char]0x015F + 'iklikler geri al' + [char]0x0131 + 'nabilir.)') 'Uygula' {
                [void](Start-Async 'ProfApply' 'Job_ProfileApply' @{ Path = $script:PendingProfile; Preview = $false; RestorePoint = ($script:Settings.RestorePoint -eq $true) } { param($r2) Complete-PlanJob $r2 } ('Profil uygulan' + [char]0x0131 + 'yor'))
            }
        } ('Profil ' + [char]0x00F6 + 'nizleniyor'))
    }
}

function Init-Page_company {
    Register-Tabs 'co' $script:CoTabs { param($s, $e) Invoke-Safe { Set-CoTab ([string]$s.Tag) } 'Sekme' }
    $ui.co_Report.Add_Click({ Invoke-Safe { Start-ReportNow } 'Rapor' })
    $ui.co_OpenReports.Add_Click({ Invoke-Safe { Open-Folder $sync.ReportDir } ('Klas' + [char]0x00F6 + 'r') })
    $ui.co_Inv.Add_Click({ Invoke-Safe { Start-CoInventory } 'Envanter' })
    $ui.co_SaveOrg.Add_Click({
        Invoke-Safe {
            $script:Settings.Org = [string]$ui.co_Org.Text
            $script:Settings.Contact = [string]$ui.co_Contact.Text
            Save-Settings $script:Settings
            Show-Toast 'Kurum bilgileri kaydedildi.' 'good'
        } 'Kaydet'
    })
    $ui.co_P1.Add_Click({
        Invoke-Safe {
            $script:CoSel = @{}
            foreach ($id in (Get-PresetIds 2 'org' $sync.Profile)) { $script:CoSel[[string]$id] = $true }
            Render-CoPolicy
        } ('Se' + [char]0x00E7)
    })
    $ui.co_P0.Add_Click({ Invoke-Safe { $script:CoSel = @{}; Render-CoPolicy } 'Temizle' })
    $ui.co_Preview.Add_Click({ Invoke-Safe { Start-CoApply $true } ([string][char]0x00D6 + 'nizle') })
    $ui.co_Apply.Add_Click({ Invoke-Safe { Start-CoApply $false } 'Uygula' })
    $ui.co_TaskRefresh.Add_Click({ Invoke-Safe { $script:CoTasks = $null; Render-CoSched } 'Yenile' })
    $ui.co_TaskEdit.Add_Click({ Invoke-Safe { Open-Page 'settings' } 'Ayarlar' })
    $ui.co_Export.Add_Click({ Invoke-Safe { Start-CoExport } ('D' + [char]0x0131 + [char]0x015F + 'a aktar') })
    $ui.co_Import.Add_Click({ Invoke-Safe { Start-CoImport } ([string][char]0x0130 + [char]0x00E7 + 'e aktar') })
}

function Select-Sub_company([string]$Sub) {
    if (-not (Select-TabChip 'co' $Sub)) { Set-CoTab $Sub }
}

function Show-Page_company {
    $t = Get-TabKey 'co' $script:CoTabs 'report'
    Set-CoTab $t
}


# ---------------- Sayfa: Araclar ----------------
# ==================================================================
#  SAYFA: Araclar  (Windows yonetim araclari, islemler, sistem onarimi, dosya araclari, sistem ekleri)
# ==================================================================
$script:TlTabs = @('win', 'procs', 'repair', 'files', 'sys', 'ext', 'kit')
$script:TlTab = 'win'
$script:TlProcs = $null
$script:TlSel = @{ SFC = $false; Check = $true; Scan = $false; Restore = $false; ChkDsk = $false }
$script:TlFileInfo = $null
$script:TlPath = $null
$script:TlFocus = $null
$script:TlMem = ''

$script:H_TlOpen = {
    param($s, $e)
    Invoke-Safe {
        $t = $s.Tag
        $c = [string]$t.C
        if ($c -match '^windowsdefender:|^ms-settings:') { Open-Url $c; return }
        try {
            if ([string]$t.A -ne '') { Start-Process -FilePath $c -ArgumentList ([string]$t.A) -ErrorAction Stop | Out-Null }
            else { Start-Process -FilePath $c -ErrorAction Stop | Out-Null }
        } catch { Show-Toast (('A' + [char]0x00E7 + '' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (bu Windows s' + [char]0x00FC + 'r' + [char]0x00FC + 'm' + [char]0x00FC + 'nde olmayabilir): ') + [string]$t.N) 'warn' }
    } ('Ara' + [char]0x00E7 + '')
}

function Render-TlWin {
    $ui.tl_List.Children.Clear()
    foreach ($t in $script:WinTools) {
        $row = New-ItemRow @{ Title = [string]$t.N; Detail = [string]$t.D; Tag = [string]$t.C; BrCol = 'BrAccent'; Btn1 = ('A' + [char]0x00E7 + '') } @{ N = [string]$t.N; C = [string]$t.C; A = [string]$t.A } $false $false
        $row.FindName('Act').Add_Click($script:H_TlOpen)
        [void]$ui.tl_List.Children.Add($row)
    }
    $ui.tl_Foot.Text = (Tr $(('Bunlar Windows' + [char]0x2019 + 'un kendi ara' + [char]0x00E7 + 'lar' + [char]0x0131 + 'd' + [char]0x0131 + 'r; bu uygulama onlar' + [char]0x0131 + 'n yerine bir ' + [char]0x015F + 'ey kurmaz.')))
}

# ---------------- islemler ----------------
$script:H_TlKill = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        $script:PendingPid = [int]$d.Pid
        Show-Confirm ('' + [char]0x0130 + '' + [char]0x015F + 'lemi sonland' + [char]0x0131 + 'r') ([string]$d.Name + ' (PID ' + [string]$d.Pid + ") sonland$([char]0x0131)r$([char]0x0131)lacak. Kaydedilmemi$([char]0x015F) i$([char]0x015F)ler kaybolabilir.") ('Sonland' + [char]0x0131 + 'r') {
            [void](Start-Async 'Kill' 'Job_Kill' @{ Pid = $script:PendingPid } {
                param($r)
                if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('' + [char]0x0130 + '' + [char]0x015F + 'lem sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ' (korumal' + [char]0x0131 + ' olabilir).') 'warn' }
                Load-TlProcs
            } ('' + [char]0x0130 + '' + [char]0x015F + 'lem sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
        } $true
    } ('Sonland' + [char]0x0131 + 'r')
}

# Programi kapatmadan arka plana itmek icin: onceligi dusurur (program kapaninca sifirlanir)
$script:H_TlLower = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        [void](Start-Async 'Priority' 'Job_Priority' @{ Pid = [int]$d.Pid; Level = 'BelowNormal' } {
            param($r)
            if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('' + [char]0x00D6 + 'ncelik d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + '; program kapan' + [char]0x0131 + 'nca kendili' + [char]0x011F + 'inden s' + [char]0x0131 + 'f' + [char]0x0131 + 'rlan' + [char]0x0131 + 'r.') 'good' } else { Show-Toast ('' + [char]0x00D6 + 'ncelik de' + [char]0x011F + 'i' + [char]0x015F + 'tirilemedi (korumal' + [char]0x0131 + ' olabilir).') 'warn' }
        } (('' + [char]0x00D6 + 'ncelik d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r' + [char]0x00FC + 'l' + [char]0x00FC + 'yor: ') + [string]$d.Name))
    } ('' + [char]0x00D6 + 'ncelik')
}

function Render-TlProcs {
    $ui.tl_List.Children.Clear()
    $rows = $script:TlProcs
    if ($null -eq $rows) { Set-ListNote $ui.tl_List ('' + [char]0x0130 + '' + [char]0x015F + 'lemler okunuyor...'); Load-TlProcs; return }
    $rows = @($rows)
    foreach ($r in $rows) {
        $det = ('PID ' + [string]$r.Pid)
        if ([string]$r.Title -ne '') { $det += ((' ' + [char]0x00B7 + ' ') + (Limit-Text ([string]$r.Title) 60)) }
        if ([string]$r.Path -ne '') { $det += ((' ' + [char]0x00B7 + ' ') + (Limit-Text ([string]$r.Path) 70)) }
        $b1 = ('Sonland' + [char]0x0131 + 'r'); $b2 = ('' + [char]0x00D6 + 'nceli' + [char]0x011F + 'i d' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'r'); $br = 'BrBlue'
        if ($r.Critical -eq $true) { $b1 = ''; $b2 = ''; $br = 'BrFaint' }
        $row = New-ItemRow @{ Title = [string]$r.Name; Detail = $det; Tag = (Format-Size ([double]$r.Mem)); BrCol = $br; Btn1 = $b1; Btn2 = $b2 } @{ Pid = [int]$r.Pid; Name = [string]$r.Name } $false $false
        if ($b1 -ne '') { $row.FindName('Act').Add_Click($script:H_TlKill) }
        if ($b2 -ne '') { $row.FindName('Act2').Add_Click($script:H_TlLower) }
        [void]$ui.tl_List.Children.Add($row)
    }
    $ui.tl_Foot.Text = (Tr $((('Bellek kullan' + [char]0x0131 + 'm' + [char]0x0131 + 'na g' + [char]0x00F6 + 're ilk ') + [string]$rows.Count + (' i' + [char]0x015F + 'lem. Sistem i' + [char]0x00E7 + 'in gerekli i' + [char]0x015F + 'lemler (gri) sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'lamaz.'))))
}

function Load-TlProcs {
    [void](Start-Async 'Procs' 'Job_Procs' @{} {
        param($r)
        $script:TlProcs = @(Get-ResultRows $r)
        if ($script:TlTab -eq 'procs') { Render-TlProcs }
    } ('' + [char]0x0130 + '' + [char]0x015F + 'lemler okunuyor') $true $true)
}

# ---------------- onarim ----------------
$script:H_TlChk = { param($s, $e) $script:TlSel[[string]$s.Tag] = ($s.IsChecked -eq $true) }

function Render-TlRepair {
    $ui.tl_List.Children.Clear()
    $info = @{
        Check = ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' (saniyeler): Windows imaj' + [char]0x0131 + 'nda bozulma i' + [char]0x015F + 'areti var m' + [char]0x0131 + ' bakar.')
        SFC = ('Orta (5-20 dk): korumal' + [char]0x0131 + ' sistem dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + ' denetler ve bozuklar' + [char]0x0131 + ' onar' + [char]0x0131 + 'r.')
        Scan = ('Uzun (10-30 dk): imaj' + [char]0x0131 + ' ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' tarar, hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'eyi de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez.')
        Restore = ('Uzun (15-40 dk, internet gerekir): Windows imaj' + [char]0x0131 + 'n' + [char]0x0131 + ' Windows Update' + [char]0x2019 + 'ten onar' + [char]0x0131 + 'r. SFC hata verirse bunu ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n.')
        ChkDsk = ('Orta: diski ' + [char]0x00E7 + 'evrimi' + [char]0x00E7 + 'i tarar (yeniden ba' + [char]0x015F + 'latma gerekmez); bozukluk bulursa bildirir.')
    }
    foreach ($k in @($script:RepairSteps.Keys)) {
        $st = $script:RepairSteps[$k]
        $row = New-ItemRow @{ Title = [string]$st.Label; Detail = [string]$info[$k]; BrCol = 'BrAccent2' } @{ Key = [string]$k } $true ($script:TlSel[[string]$k] -eq $true)
        $c = $row.FindName('Chk')
        $c.Tag = [string]$k
        $c.Add_Click($script:H_TlChk)
        [void]$ui.tl_List.Children.Add($row)
    }
    $ui.tl_Foot.Text = (Tr $(('' + [char]0x00D6 + 'nerilen s' + [char]0x0131 + 'ra: DISM H' + [char]0x0131 + 'zl' + [char]0x0131 + ' kontrol ' + [char]0x2192 + ' SFC ' + [char]0x2192 + ' gerekirse DISM Onar. ' + [char]0x00C7 + 'al' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'rken bilgisayar' + [char]0x0131 + ' kapatmay' + [char]0x0131 + 'n; soldaki g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kten ilerlemeyi izleyin.')))
}

function Start-TlRepair {
    $keys = @($script:RepairSteps.Keys | Where-Object { $script:TlSel[[string]$_] -eq $true })
    if ($keys.Count -eq 0) { Show-Toast ('' + [char]0x00D6 + 'nce ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak ad' + [char]0x0131 + 'mlar' + [char]0x0131 + ' i' + [char]0x015F + 'aretleyin.') 'warn'; return }
    $sel = @{}
    foreach ($k in $keys) { $sel[[string]$k] = $true }
    $script:PendingRepair = $sel
    Show-Confirm ('Sistem onar' + [char]0x0131 + 'm' + [char]0x0131 + '') ([string]$keys.Count + (' onar' + [char]0x0131 + 'm ad' + [char]0x0131 + 'm' + [char]0x0131 + ' s' + [char]0x0131 + 'rayla ' + [char]0x00E7 + 'al' + [char]0x0131 + '' + [char]0x015F + 'acak. Bu i' + [char]0x015F + 'lem 10-60 dakika s' + [char]0x00FC + 'rebilir; bu s' + [char]0x0131 + 'rada bilgisayar' + [char]0x0131 + ' kullanabilirsiniz ama kapatmay' + [char]0x0131 + 'n.')) ('Ba' + [char]0x015F + 'lat') {
        [void](Start-Async 'Repair' 'Job_Repair' $script:PendingRepair {
            param($r)
            if ($null -ne $r) { Show-Toast ('Onar' + [char]0x0131 + 'm ad' + [char]0x0131 + 'mlar' + [char]0x0131 + ' tamamland' + [char]0x0131 + '; sonu' + [char]0x00E7 + 'lar g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'good'; Show-Notify ('Onar' + [char]0x0131 + 'm tamamland' + [char]0x0131 + '') ('Sistem onar' + [char]0x0131 + 'm ad' + [char]0x0131 + 'mlar' + [char]0x0131 + ' tamamland' + [char]0x0131 + '.') 'good' }
        } ('Sistem onar' + [char]0x0131 + 'm' + [char]0x0131 + ''))
    }
}

# ---------------- dosya araclari: ozet / imza, guvenli silme, (istege bagli) sifreleme ----------------
function Start-TlFileInfo {
    $f = Select-OpenFile ('T' + [char]0x00FC + 'm dosyalar (*.*)|*.*')
    if ($f -eq '') { return }
    [void](Start-Async 'FileInfo' 'Job_FileInfo' @{ Path = $f } {
        param($r)
        if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Dosya okunamad' + [char]0x0131 + '.') 'warn'; return }
        $script:TlFileInfo = $r
        if ($script:TlTab -eq 'files') { Render-TlFiles }
    } ('Dosya ' + [char]0x00F6 + 'zeti hesaplan' + [char]0x0131 + 'yor'))
}

function Start-TlWipe([bool]$Folder) {
    $ep = Get-ExtProblem 'GuvenliSilme'
    if ($ep -ne '') { Show-Message ('G' + [char]0x00FC + 'venli silme kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') $ep; return }
    $t = ''
    if ($Folder) { $t = Select-Folder ('' + [char]0x0130 + '' + [char]0x00E7 + 'indekilerle birlikte g' + [char]0x00FC + 'venli silinecek klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' se' + [char]0x00E7 + 'in') } else { $t = Select-OpenFile ('T' + [char]0x00FC + 'm dosyalar (*.*)|*.*') }
    if ($t -eq '') { return }
    $why = Test-SecureDeleteAllowed $t
    if ($why -ne '') { Show-Toast $why 'warn'; return }
    $script:PendingWipe = @($t)
    $passes = 1
    try { $passes = [int]$script:Settings.WipePasses } catch { $passes = 1 }
    if ($passes -lt 1) { $passes = 1 }
    $script:PendingWipePasses = $passes
    $what = 'Bu dosya'
    if ($Folder) { $what = ('Bu klas' + [char]0x00F6 + 'r ve i' + [char]0x00E7 + 'indeki her ' + [char]0x015F + 'ey') }
    $txt = ($what + (' geri getirilemeyecek ' + [char]0x015F + 'ekilde silinecek:') + "`r`n" + $t + "`r`n`r`n$([char]0x00DC)zerine " + [string]$passes + (' kez rastgele veri yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r, sonra silinir. Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na gitmez; kurtarma programlar' + [char]0x0131 + ' da getiremez.'))
    $txt += ("`r`n`r`nK" + [char]0x0131 + "sayollar izlenmez (yaln" + [char]0x0131 + "zca k" + [char]0x0131 + "sayolun kendisi kald" + [char]0x0131 + "r" + [char]0x0131 + "l" + [char]0x0131 + "r) ve bulutta duran dosyalar atlan" + [char]0x0131 + "r. Yedekler, g" + [char]0x00F6 + "lge kopyalar ve dosya ad" + [char]0x0131 + " kay" + [char]0x0131 + "tlar" + [char]0x0131 + " silinmez; bunlar i" + [char]0x00E7 + "in " + [char]0x00C7 + "" + [char]0x00F6 + "z" + [char]0x00FC + "m Merkezi > Kal" + [char]0x0131 + "c" + [char]0x0131 + " silme sekmesindeki bo" + [char]0x015F + " alan temizli" + [char]0x011F + "ini de kullan" + [char]0x0131 + "n.")
    if ([string]$sync.Profile.DiskType -eq 'SSD') { $txt += "`r`n`r`nNot: Bu bilgisayar$([char]0x0131)n diski SSD. SSD$([char]0x2019)ler veriyi ba$([char]0x015F)ka h$([char]0x00FC)crelere ta$([char]0x015F)$([char]0x0131)d$([char]0x0131)$([char]0x011F)$([char]0x0131) i$([char]0x00E7)in dosya baz$([char]0x0131)nda silme tam g$([char]0x00FC)vence vermez; ger$([char]0x00E7)ek g$([char]0x00FC)vence i$([char]0x00E7)in disk $([char]0x015F)ifrelemesi (BitLocker) gerekir." }
    Show-Confirm ('G' + [char]0x00FC + 'venli sil (geri al' + [char]0x0131 + 'namaz)') $txt ('Kal' + [char]0x0131 + 'c' + [char]0x0131 + ' olarak sil') {
        [void](Start-Async 'Wipe' 'Job_SecureDelete' @{ Paths = $script:PendingWipe; Passes = $script:PendingWipePasses } {
            param($r)
            if ($null -eq $r) { Show-Toast ('Silme tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad'; return }
            if ($null -ne $r.ExtError) { Show-Message ('G' + [char]0x00FC + 'venli silme kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') ([string]$r.ExtError); return }
            Show-SecureDeleteResult $r
        } ('G' + [char]0x00FC + 'venli siliniyor'))
    } $true
}

function Start-TlCrypt([string]$Mode) {
    # Eklenti dosyasi yoksa ya da degistirilmisse parola sormadan once soyle
    $ep = Get-ExtProblem 'Sifreleme'
    if ($ep -ne '') { Show-Message ('Dosya ' + [char]0x015F + 'ifreleme kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') $ep; return }
    $filter = ('T' + [char]0x00FC + 'm dosyalar (*.*)|*.*')
    if ($Mode -eq 'Dec') { $filter = ('Multimizer ' + [char]0x015F + 'ifreli dosya (*.mmz)|*.mmz|T' + [char]0x00FC + 'm dosyalar (*.*)|*.*') }
    $f = Select-OpenFile $filter
    if ($f -eq '') { return }
    $script:PendingCrypt = @{ Mode = $Mode; Paths = @($f); Password = '' }
    $leaf = Split-Path -Leaf $f
    if ($Mode -eq 'Enc') {
        Show-Password ('Dosyay' + [char]0x0131 + ' ' + [char]0x015F + 'ifrele') ($leaf + " i$([char]0x00E7)in bir parola belirleyin (en az 8 karakter) ve do$([char]0x011F)rulamak i$([char]0x00E7)in iki kez yaz$([char]0x0131)n.`r`n`r`nParolay$([char]0x0131) unutursan$([char]0x0131)z dosya hi$([char]0x00E7)bir $([char]0x015F)ekilde a$([char]0x00E7)$([char]0x0131)lamaz. $([char]0x00D6)zg$([char]0x00FC)n dosya silinmez; $([char]0x015F)ifreli kopya yan$([char]0x0131)na .mmz uzant$([char]0x0131)s$([char]0x0131)yla yaz$([char]0x0131)l$([char]0x0131)r.") $true {
            param($pw)
            $script:PendingCrypt.Password = [string]$pw
            Start-TlCryptJob
        }
    } else {
        Show-Password ('Dosyay' + [char]0x0131 + ' ' + [char]0x00E7 + '' + [char]0x00F6 + 'z') ($leaf + (' dosyas' + [char]0x0131 + 'n' + [char]0x0131 + 'n parolas' + [char]0x0131 + 'n' + [char]0x0131 + ' yaz' + [char]0x0131 + 'n. ' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'len dosya yan' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r; ' + [char]0x015F + 'ifreli dosya silinmez.')) $false {
            param($pw)
            $script:PendingCrypt.Password = [string]$pw
            Start-TlCryptJob
        }
    }
}

function Start-TlCryptJob {
    $lbl = ('Dosya ' + [char]0x015F + 'ifreleniyor')
    if ([string]$script:PendingCrypt.Mode -eq 'Dec') { $lbl = ('Dosya ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'l' + [char]0x00FC + 'yor') }
    [void](Start-Async 'Crypt' 'Job_Crypt' $script:PendingCrypt {
        param($r)
        # Parola bellekte tutulmaz
        $script:PendingCrypt = $null
        if ($null -eq $r) { Show-Toast ('' + [char]0x0130 + '' + [char]0x015F + 'lem tamamlanamad' + [char]0x0131 + '.') 'bad'; return }
        if ($null -ne $r.ExtError) { Show-Message ('Dosya ' + [char]0x015F + 'ifreleme kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') ([string]$r.ExtError); return }
        if ($r.Ok -eq $true) {
            $out = [string]@($r.Outputs)[0]
            if ([string]$r.Mode -eq 'Enc') { Show-Toast (('' + [char]0x015E + 'ifrelendi: ') + (Split-Path -Leaf $out) + ('. ' + [char]0x00D6 + 'zg' + [char]0x00FC + 'n dosya yerinde duruyor; gerekmiyorsa ' + [char]0x201C + 'G' + [char]0x00FC + 'venli sil' + [char]0x201D + ' ile kald' + [char]0x0131 + 'rabilirsiniz.')) 'good' }
            else { Show-Toast (('' + [char]0x00C7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'ld' + [char]0x00FC + ': ') + (Split-Path -Leaf $out)) 'good' }
        } else { Show-Toast ('Ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: parola yanl' + [char]0x0131 + '' + [char]0x015F + ' olabilir ya da dosya bozulmu' + [char]0x015F + '. Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kte.') 'warn' }
    } $lbl)
}

$script:H_TlFileAct = {
    param($s, $e)
    Invoke-Safe {
        switch ([string]$s.Tag.Key) {
            'hash' { Start-TlFileInfo }
            default { Invoke-TlExtraAct ([string]$s.Tag.Key) }
            'wipeFile' { Start-TlWipe $false }
            'wipeDir' { Start-TlWipe $true }
            'enc' { Start-TlCrypt 'Enc' }
            'dec' { Start-TlCrypt 'Dec' }
            'copyHash' { try { [System.Windows.Clipboard]::SetText([string]$script:TlFileInfo.Sha256); Show-Toast ('' + [char]0x00D6 + 'zet panoya kopyaland' + [char]0x0131 + '.') 'good' } catch { Show-Toast ('Kopyalanamad' + [char]0x0131 + '.') 'warn' } }
            'vt' { Open-Url ('https://www.virustotal.com/gui/file/' + [string]$script:TlFileInfo.Sha256) }
        }
    } ('Dosya arac' + [char]0x0131 + '')
}

function Add-TlAction([string]$Title, [string]$Detail, [string]$Br, [string]$Key1, [string]$Btn1, [string]$Key2 = '', [string]$Btn2 = '') {
    $row = New-ItemRow @{ Title = $Title; Detail = $Detail; BrCol = $Br; Btn1 = $Btn1; Btn2 = $Btn2 } @{ Key = $Key1 } $false $false
    $row.FindName('Act').Add_Click($script:H_TlFileAct)
    if ($Btn2 -ne '') {
        $a2 = $row.FindName('Act2')
        $a2.Tag = @{ Key = $Key2 }
        $a2.Add_Click($script:H_TlFileAct)
    }
    [void]$ui.tl_List.Children.Add($row)
}

function Render-TlFiles {
    $ui.tl_List.Children.Clear()
    Add-TlAction ('Dosya ' + [char]0x00F6 + 'zeti ve dijital imza') ('Bir dosyan' + [char]0x0131 + 'n SHA-256 ' + [char]0x00F6 + 'zetini ve kimin imzalad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' g' + [char]0x00F6 + 'sterir. ' + [char]0x0130 + 'ndirdi' + [char]0x011F + 'iniz bir program' + [char]0x0131 + 'n ' + [char]0x00F6 + 'zg' + [char]0x00FC + 'n olup olmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'n' + [char]0x0131 + ' yay' + [char]0x0131 + 'nc' + [char]0x0131 + 'n' + [char]0x0131 + 'n verdi' + [char]0x011F + 'i ' + [char]0x00F6 + 'zetle kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'rabilirsiniz.') 'BrAccent' 'hash' ('Dosya se' + [char]0x00E7 + '...')
    Add-TlAction ('G' + [char]0x00FC + 'venli sil') ('Dosyan' + [char]0x0131 + 'n ' + [char]0x00FC + 'zerine rastgele veri yaz' + [char]0x0131 + 'p siler; geri getirilemez. Mekanik diskte kesindir, SSD' + [char]0x2019 + 'de tam g' + [char]0x00FC + 'vence vermez (orada disk ' + [char]0x015F + 'ifrelemesi gerekir).') 'BrBad' 'wipeFile' ('Dosya se' + [char]0x00E7 + '...') 'wipeDir' ('Klas' + [char]0x00F6 + 'r se' + [char]0x00E7 + '...')
    if ($script:Settings.OptCrypto -eq $true) {
        Add-TlAction ('Dosya ' + [char]0x015F + 'ifrele (AES-256)') ('Dosyay' + [char]0x0131 + ' parolayla ' + [char]0x015F + 'ifreleyip yan' + [char]0x0131 + 'na .mmz olarak yazar; ' + [char]0x00F6 + 'zg' + [char]0x00FC + 'n dosyaya dokunmaz. Parolay' + [char]0x0131 + ' unutursan' + [char]0x0131 + 'z dosya a' + [char]0x00E7 + '' + [char]0x0131 + 'lamaz.') 'BrAccent2' 'enc' ('' + [char]0x015E + 'ifrele...') 'dec' ('' + [char]0x00C7 + '' + [char]0x00F6 + 'z...')
    } else {
        Add-Note $ui.tl_List ('Dosya ' + [char]0x015F + 'ifreleme Ayarlar > ' + [char]0x0130 + 'ste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellikler' + [char]0x2019 + 'den a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'r. T' + [char]0x00FC + 'm diski korumak i' + [char]0x00E7 + 'in Windows' + [char]0x2019 + 'un BitLocker' + [char]0x2019 + '' + [char]0x0131 + ', ta' + [char]0x015F + '' + [char]0x0131 + 'nabilir ' + [char]0x015F + 'ifreli kasa i' + [char]0x00E7 + 'in a' + [char]0x00E7 + '' + [char]0x0131 + 'k kaynak VeraCrypt daha uygundur.')
    }
    $fi = $script:TlFileInfo
    if ($null -ne $fi) {
        Add-HeadRow $ui.tl_List (('Sonu' + [char]0x00E7 + ': ') + [string]$fi.Name)
        Add-KvRow $ui.tl_List 'Yol' ([string]$fi.Path)
        Add-KvRow $ui.tl_List 'Boyut' (Format-Size ([double]$fi.Size))
        Add-KvRow $ui.tl_List 'SHA-256' ([string]$fi.Sha256)
        $sig = [string]$fi.SigStatus
        $sigText = ('' + [char]0x0130 + 'mzas' + [char]0x0131 + 'z')
        if ($sig -eq 'Valid') { $sigText = ('Ge' + [char]0x00E7 + 'erli imza') } elseif ($sig -eq 'NotSigned') { $sigText = ('' + [char]0x0130 + 'mzas' + [char]0x0131 + 'z (her imzas' + [char]0x0131 + 'z dosya zararl' + [char]0x0131 + ' de' + [char]0x011F + 'ildir, ama kayna' + [char]0x011F + '' + [char]0x0131 + 'na dikkat edin)') }
        elseif ($sig -eq 'HashMismatch') { $sigText = ('' + [char]0x0130 + 'MZA BOZUK: dosya imzaland' + [char]0x0131 + 'ktan sonra de' + [char]0x011F + 'i' + [char]0x015F + 'tirilmi' + [char]0x015F + '') } elseif ($sig -ne '') { $sigText = $sig }
        Add-KvRow $ui.tl_List 'Dijital imza' $sigText
        if ([string]$fi.Signer -ne '') { Add-KvRow $ui.tl_List ('' + [char]0x0130 + 'mzalayan') (Limit-Text ([string]$fi.Signer) 120) }
        if ([string]$fi.Product -ne '' -or [string]$fi.Company -ne '') { Add-KvRow $ui.tl_List ('' + [char]0x00DC + 'r' + [char]0x00FC + 'n / yay' + [char]0x0131 + 'nc' + [char]0x0131 + '') (([string]$fi.Product + '  ' + [string]$fi.Version + ('  ' + [char]0x00B7 + '  ') + [string]$fi.Company).Trim()) }
        if ($script:Settings.OptVt -eq $true) {
            Add-TlAction ('Bu ' + [char]0x00F6 + 'zetle ne yapay' + [char]0x0131 + 'm?') ('VirusTotal yaln' + [char]0x0131 + 'zca ' + [char]0x00F6 + 'zeti al' + [char]0x0131 + 'r; dosya y' + [char]0x00FC + 'klenmez. ' + [char]0x00D6 + 'zet daha ' + [char]0x00F6 + 'nce g' + [char]0x00F6 + 'r' + [char]0x00FC + 'lmediyse sonu' + [char]0x00E7 + ' ' + [char]0x00E7 + '' + [char]0x0131 + 'kmaz.') 'BrFaint' 'copyHash' ('' + [char]0x00D6 + 'zeti kopyala') 'vt' ('VirusTotal' + [char]0x2019 + 'da ara')
        } else {
            Add-TlAction ('Bu ' + [char]0x00F6 + 'zetle ne yapay' + [char]0x0131 + 'm?') ('Yay' + [char]0x0131 + 'nc' + [char]0x0131 + 'n' + [char]0x0131 + 'n sitesindeki SHA-256 de' + [char]0x011F + 'eriyle kar' + [char]0x015F + '' + [char]0x0131 + 'la' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'n; birebir ayn' + [char]0x0131 + 'ysa dosya ' + [char]0x00F6 + 'zg' + [char]0x00FC + 'nd' + [char]0x00FC + 'r.') 'BrFaint' 'copyHash' ('' + [char]0x00D6 + 'zeti kopyala')
        }
    }
    $ui.tl_Foot.Text = (Tr $(('G' + [char]0x00FC + 'venli silme ve ' + [char]0x015F + 'ifreleme d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'nda bu sekmedeki i' + [char]0x015F + 'lemler yaln' + [char]0x0131 + 'zca okur.')))
}

# ---------------- sistem ekleri: PATH denetimi, (istege bagli) bellek bosaltici ve odak kipi ----------------
function Start-TlPathCheck {
    [void](Start-Async 'PathInfo' 'Job_PathInfo' @{} {
        param($r)
        if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('PATH okunamad' + [char]0x0131 + '.') 'warn'; return }
        $script:TlPath = $r
        if ($script:TlTab -eq 'sys') { Render-TlSys }
    } 'PATH denetleniyor')
}

function Start-TlPathClean([bool]$Preview) {
    $p = $script:TlPath
    if ($null -eq $p -or [int]$p.Bad -eq 0) { Show-Toast 'Temizlenecek girdi yok.' 'info'; return }
    $script:PendingSteps = New-PathCleanSteps ([string]$p.Clean) ([string]$p.Kind)
    if ($Preview) { Start-PlanJob $script:PendingSteps ('' + [char]0x00D6 + 'nizleme: PATH temizli' + [char]0x011F + 'i') $true $false; return }
    Show-Confirm ('PATH temizli' + [char]0x011F + 'i') ([string]$p.Bad + (' girdi (art' + [char]0x0131 + 'k var olmayan ya da yinelenen klas' + [char]0x00F6 + 'rler) sistem PATH de' + [char]0x011F + 'erinden ' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'lacak. Eski de' + [char]0x011F + 'er kaydedilir; Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r. A' + [char]0x00E7 + '' + [char]0x0131 + 'k programlar de' + [char]0x011F + 'i' + [char]0x015F + 'ikli' + [char]0x011F + 'i yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'l' + [char]0x0131 + 'nca g' + [char]0x00F6 + 'r' + [char]0x00FC + 'r.')) 'Temizle' {
        Start-PlanJob $script:PendingSteps 'PATH temizleniyor' $false $false { $script:TlPath = $null; if ($script:TlTab -eq 'sys') { Render-TlSys } }
    }
}

function Start-TlMem {
    $ep = Get-ExtProblem 'Bellek'
    if ($ep -ne '') { Show-Message ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ' kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') $ep; return }
    [void](Start-Async 'MemTrim' 'Job_MemTrim' @{ Standby = $true } {
        param($r)
        if ($null -ne $r -and $null -ne $r.ExtError) { Show-Message ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ' kullan' + [char]0x0131 + 'lam' + [char]0x0131 + 'yor') ([string]$r.ExtError); return }
        if ($null -eq $r -or $r.Ok -ne $true) { Show-Toast ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'lamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + '' + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'warn'; return }
        $script:TlMem = (('Son bo' + [char]0x015F + 'altma: bo' + [char]0x015F + ' bellek ') + [string][int]$r.Before + (' MB ' + [char]0x2192 + ' ') + [string][int]$r.After + ' MB')
        Show-Toast (('Bo' + [char]0x015F + ' bellek ') + [string][int]$r.Before + (' MB' + [char]0x2019 + 'tan ') + [string][int]$r.After + (' MB' + [char]0x2019 + 'a ' + [char]0x00E7 + '' + [char]0x0131 + 'kt' + [char]0x0131 + '. Etki ge' + [char]0x00E7 + 'icidir.')) 'good'
        if ($script:TlTab -eq 'sys') { Render-TlSys }
    } ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
}

function Start-TlFocus([bool]$On) {
    $lbl = ('Odak kipi a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + 'yor')
    if (-not $On) { $lbl = ('Odak kipi kapat' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') }
    [void](Start-Async 'Focus' 'Job_Focus' @{ On = $On } {
        param($r)
        if ($null -eq $r) { Show-Toast ('Odak kipi de' + [char]0x011F + 'i' + [char]0x015F + 'tirilemedi.') 'warn'; return }
        $script:TlFocus = ($r.On -eq $true)
        if ($r.On -eq $true) { Show-Toast (('Odak kipi a' + [char]0x00E7 + '' + [char]0x0131 + 'k: ') + [string]$r.Count + (' arka plan hizmeti ge' + [char]0x00E7 + 'ici olarak durduruldu.')) 'good' }
        else { Show-Toast (('Odak kipi kapand' + [char]0x0131 + ': ') + [string]$r.Count + (' hizmet geri ba' + [char]0x015F + 'lat' + [char]0x0131 + 'ld' + [char]0x0131 + '.')) 'good' }
        if ($script:TlTab -eq 'sys') { Render-TlSys }
        Update-TrayMenuState
    } $lbl)
}

function Load-TlFocusState {
    [void](Start-Async 'FocusState' 'Job_FocusState' @{} {
        param($r)
        $script:TlFocus = ($null -ne $r -and $r.On -eq $true)
        if ($script:TlTab -eq 'sys') { Render-TlSys }
        Update-TrayMenuState
    } 'Odak kipi durumu okunuyor' $true $true)
}

$script:H_TlSysAct = {
    param($s, $e)
    Invoke-Safe {
        switch ([string]$s.Tag.Key) {
            'pathCheck' { Start-TlPathCheck }
            'pathPrev' { Start-TlPathClean $true }
            'pathClean' { Start-TlPathClean $false }
            'mem' { Start-TlMem }
            'focusOn' { Start-TlFocus $true }
            'focusOff' { Start-TlFocus $false }
            'settings' { Show-Page 'settings' }
        }
    } 'Sistem eki'
}

function Add-TlSysAction([string]$Title, [string]$Detail, [string]$Br, [string]$Key1, [string]$Btn1, [string]$Key2 = '', [string]$Btn2 = '', [string]$Tag = '') {
    $row = New-ItemRow @{ Title = $Title; Detail = $Detail; BrCol = $Br; Btn1 = $Btn1; Btn2 = $Btn2; Tag = $Tag } @{ Key = $Key1 } $false $false
    $row.FindName('Act').Add_Click($script:H_TlSysAct)
    if ($Btn2 -ne '') {
        $a2 = $row.FindName('Act2')
        $a2.Tag = @{ Key = $Key2 }
        $a2.Add_Click($script:H_TlSysAct)
    }
    [void]$ui.tl_List.Children.Add($row)
}

function Render-TlSys {
    $ui.tl_List.Children.Clear()
    $p = $script:TlPath
    if ($null -eq $p) {
        Add-TlSysAction 'Sistem PATH denetimi' ('PATH i' + [char]0x00E7 + 'inde art' + [char]0x0131 + 'k var olmayan ya da iki kez yaz' + [char]0x0131 + 'lm' + [char]0x0131 + '' + [char]0x015F + ' klas' + [char]0x00F6 + 'rleri bulur. Kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lan programlar geride ' + [char]0x00E7 + 'o' + [char]0x011F + 'u zaman b' + [char]0x00F6 + 'yle girdiler b' + [char]0x0131 + 'rak' + [char]0x0131 + 'r.') 'BrAccent' 'pathCheck' 'Denetle'
    } else {
        $tag = 'temiz'
        if ([int]$p.Bad -gt 0) { $tag = ([string]$p.Bad + ' sorunlu girdi') }
        Add-TlSysAction 'Sistem PATH denetimi' ([string]@($p.Entries).Count + ' girdi okundu.') 'BrAccent' 'pathPrev' ('' + [char]0x00D6 + 'nizle') 'pathClean' 'Temizle' $tag
        foreach ($en in @($p.Entries)) {
            if ($en.Missing -ne $true -and $en.Dup -ne $true) { continue }
            $why = ('klas' + [char]0x00F6 + 'r yok')
            if ($en.Dup -eq $true) { $why = 'yinelenen' }
            Add-KvRow $ui.tl_List $why ([string]$en.Text)
        }
    }
    $any = $false
    if ($script:Settings.OptRam -eq $true) {
        $any = $true
        $d = ('Programlar' + [char]0x0131 + 'n kullanmad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' belle' + [char]0x011F + 'i ve bekleme ' + [char]0x00F6 + 'nbelle' + [char]0x011F + 'ini bo' + [char]0x015F + 'alt' + [char]0x0131 + 'r. Etkisi ge' + [char]0x00E7 + 'icidir; bellek darl' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + 'nda anl' + [char]0x0131 + 'k rahatlama sa' + [char]0x011F + 'lar, s' + [char]0x0131 + 'k kullanmak sistemi yava' + [char]0x015F + 'lat' + [char]0x0131 + 'r.')
        if ($script:TlMem -ne '') { $d += ('  ' + $script:TlMem) }
        Add-TlSysAction ('Belle' + [char]0x011F + 'i bo' + [char]0x015F + 'alt') $d 'BrAccent2' 'mem' ('Bo' + [char]0x015F + 'alt')
    }
    if ($script:Settings.OptFocus -eq $true) {
        $any = $true
        if ($null -eq $script:TlFocus) { Load-TlFocusState }
        $d = ('Arama dizini, SysMain, tan' + [char]0x0131 + 'lama gibi arka plan hizmetlerini ge' + [char]0x00E7 + 'ici olarak durdurur ve g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + 'n' + [char]0x0131 + ' y' + [char]0x00FC + 'kseltir. Kapat' + [char]0x0131 + 'nca ya da bilgisayar yeniden ba' + [char]0x015F + 'lay' + [char]0x0131 + 'nca her ' + [char]0x015F + 'ey eski h' + [char]0x00E2 + 'line d' + [char]0x00F6 + 'ner.')
        if ($script:TlFocus -eq $true) { Add-TlSysAction 'Odak / oyun kipi' $d 'BrGood' 'focusOff' 'Kapat' '' '' ('A' + [char]0x00C7 + 'IK') }
        else { Add-TlSysAction 'Odak / oyun kipi' $d 'BrFaint' 'focusOn' ('A' + [char]0x00E7 + '') '' '' ('kapal' + [char]0x0131 + '') }
    }
    if (-not $any) {
        Add-TlSysAction ('Bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ' ve odak kipi') ('Bu iki ' + [char]0x00F6 + 'zellik iste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + 'd' + [char]0x0131 + 'r ve kapal' + [char]0x0131 + ' gelir. Ayarlar > ' + [char]0x0130 + 'ste' + [char]0x011F + 'e ba' + [char]0x011F + 'l' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellikler' + [char]0x2019 + 'den a' + [char]0x00E7 + 'abilirsiniz.') 'BrFaint' 'settings' ('Ayarlar' + [char]0x0131 + ' a' + [char]0x00E7 + '')
    }
    $ui.tl_Foot.Text = (Tr $(('PATH temizli' + [char]0x011F + 'i ' + [char]0x00F6 + 'nizlenir ve Ge' + [char]0x00E7 + 'mi' + [char]0x015F + ' sayfas' + [char]0x0131 + 'ndan geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'r.')))
}

function Set-TlTab([string]$Tab) {
    $script:TlTab = $Tab
    switch ($Tab) {
        'win' { Show-OnlyBar 'tl' @(); Render-TlWin }
        'procs' { Show-OnlyBar 'tl' @('tl_Refresh'); Render-TlProcs }
        'repair' { Show-OnlyBar 'tl' @('tl_Repair'); Render-TlRepair }
        'files' { Show-OnlyBar 'tl' @(); Render-TlFiles }
        'sys' { Show-OnlyBar 'tl' @(); Render-TlSys }
        'ext' { Show-OnlyBar 'tl' @('tl_Refresh'); Render-TlExt }
        'kit' { Show-OnlyBar 'tl' @(); Render-TlKit }
    }
}

function Init-Page_tools {
    Register-Tabs 'tl' $script:TlTabs { param($s, $e) Invoke-Safe { Set-TlTab ([string]$s.Tag) } 'Sekme' }
    $ui.tl_Refresh.Add_Click({ Invoke-Safe { Invoke-TlRefresh } 'Yenile' })
    $ui.tl_Repair.Add_Click({ Invoke-Safe { Start-TlRepair } ('Onar' + [char]0x0131 + 'm') })
}

function Select-Sub_tools([string]$Sub) {
    if (Test-TlNeedsExpert $Sub ($script:UiState.Mode -eq 'Expert')) { Set-UiMode 'Expert' $true }
    if (-not (Select-TabChip 'tl' $Sub)) { Set-TlTab $Sub }
}

function Show-Page_tools {
    $exp = ($script:UiState.Mode -eq 'Expert')
    $vis = @(Get-TlVisibleTabs $exp)
    foreach ($k in @($script:TlTabs)) { $c = $ui['tl_Tab_' + [string]$k]; if ($null -ne $c) { Set-Visible $c ($vis -contains [string]$k) } }
    $cur = Get-TabKey 'tl' $script:TlTabs 'win'
    $t = Get-TlStartTab $exp $cur
    if ($t -ne $cur -and (Select-TabChip 'tl' $t)) { return }
    Set-TlTab $t
}

# ==================================================================
#  SAYFA: Gecmis ve Geri Alma  (her oturumun degisiklik kaydi; tek tikla geri al)
# ==================================================================
function Get-JournalRows {
    $rows = New-Object System.Collections.ArrayList
    $dir = [string]$sync.BackupDir
    if (-not (Test-Path -LiteralPath $dir)) { return , @() }
    $files = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '\.(jsonl|json)$' -and $_.Name -notmatch '\.geri-alindi\.' } | Sort-Object LastWriteTime -Descending | Select-Object -First 80)
    foreach ($f in $files) {
        $hdr = $null; $n = 0
        try {
            if ($f.Extension -eq '.jsonl') {
                $lines = @([System.IO.File]::ReadAllLines($f.FullName))
                if ($lines.Count -gt 0) { $hdr = ConvertFrom-Json -InputObject $lines[0]; $n = $lines.Count - 1 }
            } else {
                $o = Read-JsonFile $f.FullName
                if ($null -ne $o.Items) { $n = @($o.Items).Count; $hdr = @{ Created = [string]$f.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'); User = ''; Computer = '' } }
            }
        } catch { continue }
        if ($null -eq $hdr) { continue }
        if ($hdr -is [hashtable]) { $created = [string]$hdr.Created; $user = [string]$hdr.User; $comp = [string]$hdr.Computer }
        else { $created = [string]$hdr.Created; $user = [string]$hdr.User; $comp = [string]$hdr.Computer }
        $reg = [System.IO.Path]::ChangeExtension($f.FullName, '.geri.reg')
        [void]$rows.Add(@{ File = $f.FullName; Name = $f.Name; Created = $created; User = $user; Computer = $comp; Count = $n; Size = [double]$f.Length; Reg = $(if (Test-Path -LiteralPath $reg) { $reg } else { '' }) })
    }
    return , $rows.ToArray()
}

$script:H_HiUndo = {
    param($s, $e)
    Invoke-Safe {
        $d = $s.Tag
        $script:PendingFile = [string]$d.File
        Show-Confirm ('De' + [char]0x011F + 'i' + [char]0x015F + 'iklikleri geri al') ([string]$d.Created + ' tarihli oturumun ' + [string]$d.Count + (" de" + [char]0x011F + "i" + [char]0x015F + "ikli" + [char]0x011F + "i geri al" + [char]0x0131 + "nacak.`r`n`r`nKay" + [char]0x0131 + "t defteri de" + [char]0x011F + "erleri, hizmet ve g" + [char]0x00F6 + "rev durumlar" + [char]0x0131 + " eski h" + [char]0x00E2 + "llerine d" + [char]0x00F6 + "ner. Silinen ge" + [char]0x00E7 + "ici dosyalar ve kald" + [char]0x0131 + "r" + [char]0x0131 + "lan uygulamalar geri gelmez.")) 'Geri al' {
            [void](Start-Async 'Undo' 'Job_Undo' @{ File = $script:PendingFile } {
                param($r)
                if ($null -ne $r) {
                    $kind = 'good'; if ([int]$r.Errors -gt 0) { $kind = 'warn' }
                    Show-Toast ([string]$r.Summary) $kind
                    $script:HealthAt = [datetime]::MinValue
                }
                Render-History
            } ('De' + [char]0x011F + 'i' + [char]0x015F + 'iklikler geri al' + [char]0x0131 + 'n' + [char]0x0131 + 'yor'))
        } $true
    } 'Geri al'
}

$script:H_HiShow = {
    param($s, $e)
    Invoke-Safe {
        $f = [string]$s.Tag.File
        $target = $f
        try { Start-Process -FilePath 'explorer.exe' -ArgumentList ('/select,"' + $target + '"') | Out-Null } catch { Open-Folder $sync.BackupDir }
    } ('G' + [char]0x00F6 + 'ster')
}

function Render-History {
    $ui.hi_List.Children.Clear()
    $rows = (Get-JournalRows)
    if ($rows.Count -eq 0) {
        Add-Note $ui.hi_List ('Hen' + [char]0x00FC + 'z kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik yok. Optimizasyon, Hizmetler gibi sayfalardan uygulad' + [char]0x0131 + [char]0x011F + [char]0x0131 + 'n' + [char]0x0131 + 'z her ' + [char]0x015F + 'ey burada g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'r.')
        $ui.hi_Foot.Text = (Tr $(''))
        return
    }
    foreach ($r in $rows) {
        $det = ([string]$r.Count + (' de' + [char]0x011F + 'i' + [char]0x015F + 'iklik'))
        if ([string]$r.User -ne '') { $det += ((' ' + [char]0x00B7 + ' ') + [string]$r.User) }
        if ([string]$r.Computer -ne '') { $det += ((' ' + [char]0x00B7 + ' ') + [string]$r.Computer) }
        if ([string]$r.Reg -ne '') { $det += (' ' + [char]0x00B7 + ' .geri.reg dosyas' + [char]0x0131 + ' var (' + [char]0x00E7 + 'ift t' + [char]0x0131 + 'klayarak da d' + [char]0x00F6 + 'nebilirsiniz)') }
        $title = [string]$r.Created
        if ($title -eq '') { $title = [string]$r.Name }
        $row = New-ItemRow @{ Title = $title; Detail = $det; Tag = (Format-Size ([double]$r.Size)); BrCol = 'BrAccent2'; Btn1 = 'Geri al'; Btn2 = ('Dosyay' + [char]0x0131 + ' g' + [char]0x00F6 + 'ster') } $r $false $false
        $row.FindName('Act').Add_Click($script:H_HiUndo)
        $row.FindName('Act2').Add_Click($script:H_HiShow)
        [void]$ui.hi_List.Children.Add($row)
    }
    $ui.hi_Foot.Text = (Tr $(([string]$rows.Count + (' oturum. Kay' + [char]0x0131 + 'tlar ') + [string]$sync.BackupDir + (' klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'nde saklan' + [char]0x0131 + 'r.'))))
}

function Init-Page_history {
    $ui.hi_Refresh.Add_Click({ Invoke-Safe { Render-History } 'Yenile' })
    $ui.hi_Folder.Add_Click({ Invoke-Safe { Open-Folder $sync.BackupDir } ('Klas' + [char]0x00F6 + 'r') })
    $ui.hi_Logs.Add_Click({ Invoke-Safe { Open-Folder $script:LogDir } ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'kler') })
}

function Show-Page_history { Render-History }

# ==================================================================
#  SAYFA: Ayarlar  (davranis, otomatik bakim, kurulum)
# ==================================================================
$script:StLoading = $false
$script:StDays = @('Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday')
$script:StMaintBoxes = @{}

function Save-StGeneral {
    if ($script:StLoading) { return }
    $s = $script:Settings
    $s.TrayMinimize = ($ui.st_Tray.IsChecked -eq $true)
    $s.TrayOnMinimize = ($ui.st_TrayMin.IsChecked -eq $true)
    $s.Notify = ($ui.st_Notify.IsChecked -eq $true)
    $s.RestorePoint = ($ui.st_Rp.IsChecked -eq $true)
    $s.ExpertConfirm = ($ui.st_Confirm.IsChecked -eq $true)
    foreach ($k in @('1', '2', '5')) {
        if ($ui['st_Mon' + $k].IsChecked -eq $true) { $s.MonitorSec = [int]$k; $sync.MonInterval = [int]$k }
    }
    Save-Settings $s
}

function Get-StDay {
    foreach ($d in $script:StDays) { if ($ui['st_Day_' + $d].IsChecked -eq $true) { return $d } }
    return 'Sunday'
}

function Load-StFromSettings {
    $script:StLoading = $true
    $s = $script:Settings
    $ui.st_Tray.IsChecked = ($s.TrayMinimize -eq $true)
    $ui.st_TrayMin.IsChecked = (Get-TrayOnMinimize)
    $ui.st_Notify.IsChecked = ($s.Notify -eq $true)
    $ui.st_Rp.IsChecked = ($s.RestorePoint -eq $true)
    $ui.st_Confirm.IsChecked = ($s.ExpertConfirm -ne $false)
    $ms = [int]$s.MonitorSec
    if ($ms -ge 5) { $ui.st_Mon5.IsChecked = $true } elseif ($ms -ge 2) { $ui.st_Mon2.IsChecked = $true } else { $ui.st_Mon1.IsChecked = $true }
    $ui.st_MaintOn.IsChecked = ($s.MaintEnabled -eq $true)
    $day = [string]$s.MaintDay
    if ($script:StDays -notcontains $day) { $day = 'Sunday' }
    $ui['st_Day_' + $day].IsChecked = $true
    $ui.st_MaintTime.Text = (Tr $([string]$s.MaintTime))
    $ui.st_BkOn.IsChecked = ($s.BackupSchedEnabled -eq $true)
    $ui.st_BkTime.Text = (Tr $([string]$s.BackupSchedTime))
    $ui.st_RepOn.IsChecked = ($s.ReportEnabled -eq $true)
    $ui.st_Autostart.IsChecked = ($s.Autostart -eq $true)
    $sel = @($s.MaintItems)
    foreach ($k in @($script:StMaintBoxes.Keys)) { $script:StMaintBoxes[$k].IsChecked = ($sel -contains $k) }
    Load-StExtra
    $script:StLoading = $false
    Update-StInstall
}

function Update-StInstall {
    $inst = Join-Path (Join-Path $sync.DataDir 'Uygulama') 'Multimizer.ps1'
    if (Test-Path -LiteralPath $inst) { $ui.st_InstState.Text = (Tr $(('Kurulu: ' + $inst + (' (Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + 'nden a' + [char]0x00E7 + 'abilirsiniz).')))) }
    else { $ui.st_InstState.Text = (Tr $(('Kurulu de' + [char]0x011F + 'il. ' + [char]0x201C + 'Kur' + [char]0x201D + ' ile uygulama kal' + [char]0x0131 + 'c' + [char]0x0131 + ' klas' + [char]0x00F6 + 're kopyalan' + [char]0x0131 + 'r; Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + ' ve masa' + [char]0x00FC + 'st' + [char]0x00FC + ' k' + [char]0x0131 + 'sayollar' + [char]0x0131 + ' olu' + [char]0x015F + 'ur. Zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'revler ve otomatik ba' + [char]0x015F + 'latma da buna ihtiya' + [char]0x00E7 + ' duyar.'))) }
}

function Save-StSchedule {
    $s = $script:Settings
    $tm = [string]$ui.st_MaintTime.Text
    $tb = [string]$ui.st_BkTime.Text
    if ($tm -notmatch '^([01]?\d|2[0-3]):([0-5]\d)$') { Show-Toast ('Bak' + [char]0x0131 + 'm saati SS:DD bi' + [char]0x00E7 + 'iminde olmal' + [char]0x0131 + ' (' + [char]0x00F6 + 'r. 03:00).') 'warn'; return $false }
    if ($tb -notmatch '^([01]?\d|2[0-3]):([0-5]\d)$') { Show-Toast ('Yedek saati SS:DD bi' + [char]0x00E7 + 'iminde olmal' + [char]0x0131 + ' (' + [char]0x00F6 + 'r. 21:00).') 'warn'; return $false }
    $s.MaintEnabled = ($ui.st_MaintOn.IsChecked -eq $true)
    $s.MaintDay = (Get-StDay)
    $s.MaintTime = $tm
    $s.BackupSchedEnabled = ($ui.st_BkOn.IsChecked -eq $true)
    $s.BackupSchedTime = $tb
    $s.ReportEnabled = ($ui.st_RepOn.IsChecked -eq $true)
    $s.Autostart = ($ui.st_Autostart.IsChecked -eq $true)
    $items = New-Object System.Collections.ArrayList
    foreach ($k in @($script:StMaintBoxes.Keys)) { if ($script:StMaintBoxes[$k].IsChecked -eq $true) { [void]$items.Add([string]$k) } }
    $s.MaintItems = $items.ToArray()
    Save-Settings $s
    return $true
}

function Start-StSync {
    if (-not (Save-StSchedule)) { return }
    if ($script:Settings.BackupSchedEnabled -eq $true -and (@($script:Settings.BackupSources).Count -eq 0 -or [string]$script:Settings.BackupDest -eq '')) {
        Show-Toast ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k yedek a' + [char]0x00E7 + [char]0x0131 + 'k ama Yedek sayfas' + [char]0x0131 + 'nda klas' + [char]0x00F6 + 'r/hedef se' + [char]0x00E7 + 'ilmemi' + [char]0x015F + '; yedek g' + [char]0x00F6 + 'revi bo' + [char]0x015F + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'r.') 'warn'
    }
    [void](Start-Async 'SyncTasks' 'Job_SyncTasks' @{} {
        param($r)
        if ($null -ne $r -and $r.Ok -eq $true) {
            Show-Toast ('Zamanlama kaydedildi ve g' + [char]0x00F6 + 'revler g' + [char]0x00FC + 'ncellendi.') 'good'
            $script:CoTasks = $null
        } else { Show-Toast ('Zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'revler kurulamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
        Update-StInstall
        Update-TrayMenuState
    } ('Zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'revler g' + [char]0x00FC + 'ncelleniyor'))
}

function Init-Page_settings {
    # bakim adimlari: katalogdaki "Temizlik" kategorisinden geri alinabilir/guvenli olanlar
    $ui.st_MaintList.Children.Clear()
    foreach ($c in (Get-CatalogFor 'opt' 'Temizlik' $sync.Profile)) {
        if ([int]$c.Level -ge 4) { continue }
        $cb = New-Object System.Windows.Controls.CheckBox
        $cb.Content = (Tr $([string]$c.Title))
        $cb.Margin = New-Object System.Windows.Thickness -ArgumentList 0, 3, 0, 3
        $cb.Tag = [string]$c.Id
        $cb.Add_Click({ if (-not $script:StLoading) { Invoke-Safe { [void](Save-StSchedule) } ('Bak' + [char]0x0131 + 'm') } })
        $script:StMaintBoxes[[string]$c.Id] = $cb
        [void]$ui.st_MaintList.Children.Add($cb)
    }
    foreach ($n in @('st_Tray', 'st_TrayMin', 'st_Notify', 'st_Rp', 'st_Confirm', 'st_Mon1', 'st_Mon2', 'st_Mon5')) {
        $ui[$n].Add_Click({ Invoke-Safe { Save-StGeneral } 'Ayar' })
    }
    $ui.st_Sched.Add_Click({ Invoke-Safe { Start-StSync } 'Zamanlama' })
    $ui.st_Autostart.Add_Click({ Invoke-Safe { Start-StSync } ('Ba' + [char]0x015F + 'lang' + [char]0x0131 + [char]0x00E7) })
    $ui.st_Install.Add_Click({
        Invoke-Safe {
            Show-Confirm ('Uygulamay' + [char]0x0131 + ' kur') ('Uygulama kal' + [char]0x0131 + 'c' + [char]0x0131 + ' bir klas' + [char]0x00F6 + 're kopyalan' + [char]0x0131 + 'r; Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + 'ne ve masa' + [char]0x00FC + 'st' + [char]0x00FC + 'ne k' + [char]0x0131 + 'sayol eklenir (y' + [char]0x00F6 + 'netici izniyle a' + [char]0x00E7 + [char]0x0131 + 'l' + [char]0x0131 + 'r).') 'Kur' {
                [void](Start-Async 'Install' 'Job_Install' @{ Desktop = $true } {
                    param($r)
                    if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Kurulum tamamland' + [char]0x0131 + '.') 'good'; $script:Settings = Get-Settings } else { Show-Toast ('Kurulum ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
                    Update-StInstall
                } 'Uygulama kuruluyor')
            }
        } 'Kur'
    })
    $ui.st_Uninstall.Add_Click({
        Invoke-Safe {
            Show-Confirm ('Kurulumu kald' + [char]0x0131 + 'r') ('K' + [char]0x0131 + 'sayollar, zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'revler ve kurulu kopya silinir. Kay' + [char]0x0131 + 'tlar, yedekler ve raporlar korunur.') ('Kald' + [char]0x0131 + 'r') {
                [void](Start-Async 'Uninstall' 'Job_Uninstall' @{} {
                    param($r)
                    $script:Settings = Get-Settings
                    Load-StFromSettings
                    if ($null -ne $r -and $r.Ok -eq $true) { Show-Toast ('Kurulum kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'good' } else { Show-Toast ('Kald' + [char]0x0131 + 'rma tamamlanamad' + [char]0x0131 + '; g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + 'e bak' + [char]0x0131 + 'n.') 'bad' }
                } ('Kurulum kald' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor'))
            } $true
        } ('Kald' + [char]0x0131 + 'r')
    })
    $ui.st_OpenData.Add_Click({ Invoke-Safe { Open-Folder $sync.DataDir } ('Klas' + [char]0x00F6 + 'r') })
    Init-StUpdate
    Initialize-StLang
    Init-StLangEvents
    Initialize-StReset
    Init-StReset
    Init-StExtra
}

function Show-Page_settings {
    Load-StFromSettings
    $p = $sync.Profile
    $os = ''
    if ($null -ne $p) { $os = ([string]$p.OsName + ' ' + [string]$p.Version) }
    $ui.st_About.Text = (Tr $((('Multimizer v') + $script:AppVersion + "`r`n" + $os + ("`r`nVeri klas" + [char]0x00F6 + "r" + [char]0x00FC + ": ") + [string]$sync.DataDir + ("`r`nG" + [char]0x00FC + "nl" + [char]0x00FC + "k: ") + [string]$sync.LogFile)))
    $ui.st_Sig.Text = (Tr $((Get-SigLine)))
}

# ==================================================================
#  ARAYUZ KABUGU: pencere olusturma, gezinme, kullanici/uzman kipi, baslik dugmeleri, zamanlayicilar
# ==================================================================
$script:App = $null
$script:NavBusy = $false
$script:ModeBusy = $false
$script:ChromeFallback = $false
$script:UiState = @{ Page = ''; Mode = 'User'; LastAlert = [datetime]::MinValue; CpuHigh = 0; LastHealthAt = [datetime]::MinValue }

$script:PageTitles = [ordered]@{
    panel    = 'DURUM PANOSU'
    board    = 'ANA EKRAN'
    optimize = ('OPT' + [char]0x0130 + 'M' + [char]0x0130 + 'ZASYON')
    services = ('H' + [char]0x0130 + 'ZMET Y' + [char]0x00D6 + 'NET' + [char]0x0130 + 'C' + [char]0x0130 + 'S' + [char]0x0130)
    apps     = 'UYGULAMALAR'
    clean    = ('TEM' + [char]0x0130 + 'ZL' + [char]0x0130 + 'K VE D' + [char]0x0130 + 'SK')
    power    = ('G' + [char]0x00DC + '' + [char]0x00C7 + '')
    gaming   = 'OYUN'
    smart    = 'AKILLI BAKIM'
    security = ('G' + [char]0x00DC + 'VENL' + [char]0x0130 + 'K')
    updates  = ('G' + [char]0x00DC + 'NCELLEMELER')
    network  = ('A' + [char]0x011E + ' ARA' + [char]0x00C7 + 'LARI')
    backup   = 'YEDEK VE KURTARMA'
    solve    = ('' + [char]0x00C7 + '' + [char]0x00D6 + 'Z' + [char]0x00DC + 'M MERKEZ' + [char]0x0130 + '')
    company  = ([string][char]0x015E + [char]0x0130 + 'RKET Y' + [char]0x00D6 + 'NET' + [char]0x0130 + 'M' + [char]0x0130)
    tools    = ('ARA' + [char]0x00C7 + 'LAR')
    history  = ('GE' + [char]0x00C7 + 'M' + [char]0x0130 + [char]0x015E + ' VE GER' + [char]0x0130 + ' ALMA')
    settings = 'AYARLAR'
}
$script:ExpertPages = @('services', 'company')

# ---------------- uygulama simgesi (New-AppIconBitmap cekirdekte tanimlidir) ----------------
function Get-WpfIcon {
    try {
        $bmp = New-AppIconBitmap 32
        $hicon = $bmp.GetHicon()
        $src = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon($hicon, [System.Windows.Int32Rect]::Empty, [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions())
        $src.Freeze()
        return $src
    } catch { return $null }
}

# ---------------- pencere ----------------
function New-MainWindow {
    $xaml = $script:XamlMain.Replace('@@ICONS@@', $script:IconXaml).Replace('@@RES@@', $script:XamlRes)
    $w = $null
    try {
        $w = Read-LocalXaml ($xaml)
    } catch {
        Write-CrashLog ('Ozel cerceve yuklenemedi, sistem cercevesi kullanilacak: ' + $_.Exception.Message)
        $x2 = [regex]::Replace($xaml, '(?s)<shell:WindowChrome\.WindowChrome>.*?</shell:WindowChrome\.WindowChrome>', '')
        $x2 = [regex]::Replace($x2, '\s+shell:WindowChrome\.IsHitTestVisibleInChrome="True"', '')
        $x2 = $x2.Replace('WindowStyle="None"', 'WindowStyle="SingleBorderWindow"')
        $x2 = $x2.Replace('xmlns:shell="clr-namespace:System.Windows.Shell;assembly=PresentationFramework"', '')
        $w = Read-LocalXaml ($x2)
        $script:ChromeFallback = $true
    }
    $script:Win = $w
    Register-XamlNames $xaml $w
    $ic = Get-WpfIcon
    if ($null -ne $ic) { $w.Icon = $ic }
    return $w
}

# ---------------- sayfa yukleme ve gezinme ----------------
function Build-Page([string]$Key) {
    if ($script:Pages.ContainsKey($Key)) { return $script:Pages[$Key] }
    $xaml = Get-Variable -Scope Script -Name ('Page_' + $Key) -ValueOnly
    $xaml = Add-DescTags ([string]$xaml)
    $root = Read-LocalXaml ($xaml)
    Register-XamlNames $xaml $root
    $root.Visibility = $script:VisOff
    [void]$ui.PageHost.Children.Add($root)
    $script:Pages[$Key] = $root
    $init = 'Init-Page_' + $Key
    if (Get-Command -Name $init -CommandType Function -ErrorAction Ignore) {
        try { & $init } catch { Show-Crash $_ $init }
    }
    try { [void](Set-PageDescCompact $root) } catch { }
    if ($script:CardsOn -eq $true) {
        try { Update-PageCards $root $true (Get-CardOpenCount $Key) } catch { Write-CrashLog ('Kartlar (' + $Key + '): ' + $_.Exception.Message) }
    }
    if ($Key -eq 'panel') {
        try { Set-PanelReflow $root } catch { Write-CrashLog ('Durum panosu yerlesimi: ' + $_.Exception.Message) }
    }
    return $root
}

function Show-Page([string]$Key) {
    if ($Key -eq 'panel') { try { if (Test-BoardHome) { $Key = 'board' } } catch { } }
    if (-not $script:PageTitles.Contains($Key)) { return }
    if ($Key -eq 'board' -and -not $script:Pages.ContainsKey('panel')) { try { [void](Build-Page 'panel') } catch { Write-CrashLog ('Klasik panel kurulamadi: ' + $_.Exception.Message) } }
    if (($script:ExpertPages -contains $Key) -and $script:UiState.Mode -ne 'Expert') { Set-UiMode 'Expert' $true }
    $root = $null
    try { $root = Build-Page $Key } catch { Show-Crash $_ (('Sayfa y' + [char]0x00FC + 'klenemedi: ') + $Key); return }
    foreach ($k in @($script:Pages.Keys)) {
        if ($k -ne $Key) { $script:Pages[$k].Visibility = $script:VisOff }
    }
    $root.Visibility = $script:VisOn
    $script:UiState.Page = $Key
    try { Add-Trace ('sayfa: ' + $Key) } catch { }
    $ui.TxtPageName.Text = (Tr $([string]$script:PageTitles[$Key]))
    $railKey = $Key
    if ($Key -eq 'board') { $railKey = 'panel' }
    $rb = $ui['Rail_' + $railKey]
    if ($null -ne $rb -and $rb.IsChecked -ne $true) {
        $script:NavBusy = $true
        $rb.IsChecked = $true
        $script:NavBusy = $false
    }
    try { Sync-RailGroups $railKey; Sync-FlyRail $Key; Close-NavMenu; Update-ToTop $null } catch { Write-CrashLog ('Sayfa gecisi (menu): ' + $_.Exception.Message) }
    $fn = 'Show-Page_' + $Key
    if (Get-Command -Name $fn -CommandType Function -ErrorAction Ignore) {
        try { & $fn } catch { Show-Crash $_ $fn }
    }
}

# Baska sayfadan bir alt sekmeye gitmek icin (or. bulgudan "Baslangic")
function Open-Page([string]$Key, [string]$Sub = '') {
    $map = @{ startup = 'apps'; wu = 'updates'; compress = 'clean' }
    $page = $Key
    if ($map.ContainsKey($Key)) { $page = $map[$Key]; if ($Sub -eq '') { $Sub = $Key } }
    $script:UiState.Sub = $Sub
    Show-Page $page
    $fn = 'Select-Sub_' + $page
    if ($Sub -ne '' -and (Get-Command -Name $fn -CommandType Function -ErrorAction Ignore)) {
        try { & $fn $Sub } catch { Show-Crash $_ $fn }
    }
}

function Set-UiMode([string]$Mode, [bool]$Quiet = $false) {
    $script:UiState.Mode = $Mode
    $script:Settings.Mode = $Mode
    if (-not $Quiet) { Save-Settings $script:Settings }
    $exp = ($Mode -eq 'Expert')
    foreach ($k in $script:ExpertPages) { Set-Visible $ui['Rail_' + $k] $exp }
    $script:ModeBusy = $true
    $ui.SegUser.IsChecked = (-not $exp)
    $ui.SegExpert.IsChecked = $exp
    $script:ModeBusy = $false
    if (-not $exp -and ($script:ExpertPages -contains $script:UiState.Page)) { Show-Page 'panel' }
    foreach ($k in @($script:Pages.Keys)) {
        $fn = 'Update-PageMode_' + $k
        if (Get-Command -Name $fn -CommandType Function -ErrorAction Ignore) {
            try { & $fn } catch { Show-Crash $_ $fn }
        }
    }
    try { Update-RailDensity } catch { }
    if (-not $Quiet) {
        if ($exp) { Show-Toast ('Uzman kip: t' + [char]0x00FC + 'm sayfalar ve ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ' se' + [char]0x00E7 + 'enekler a' + [char]0x00E7 + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'info' }
        else { Show-Toast ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' kipi: uygulama g' + [char]0x00FC + 'venli se' + [char]0x00E7 + 'imleri sizin i' + [char]0x00E7 + 'in yapar.') 'info' }
    }
}

# ---------------- kapatma / tepsi ----------------
function Exit-App {
    if (Test-SmokeExitBlocked) { return }
    $script:Quitting = $true
    try { Add-Trace 'cikis istendi' } catch { }
    try { if (Get-Command -Name 'Close-Widget' -CommandType Function -ErrorAction Ignore) { Close-Widget } } catch { }
    try { $script:App.Shutdown() } catch { try { $script:Win.Close() } catch { } }
}

# ---------------- zamanlayicilar ----------------
function Start-UiTimers {
    $script:PumpTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:PumpTimer.Interval = [TimeSpan]::FromMilliseconds(150)
    $script:PumpTimer.Add_Tick({
        try { Update-AsyncUi; Update-MonitorStart; Update-Toasts; Sync-LogScroll } catch { Write-CrashLog ('PumpTimer: ' + $_.Exception.Message) }
    })
    $script:PumpTimer.Start()
    $script:MonTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:MonTimer.Interval = [TimeSpan]::FromMilliseconds(1500)
    $script:MonTimer.Add_Tick({
        try { Update-MonitorUi } catch { Write-CrashLog ('MonTimer: ' + $_.Exception.Message) }
        try { if ($sync.DebugLog -eq $true) { [void](Save-DebugErrors 'ana') } } catch { }
    })
    $script:MonTimer.Start()
    Initialize-NetWatch
    Initialize-KsWatch
    Initialize-GuardWatch
    try { Initialize-InstallOffer } catch { Write-CrashLog ('Kurulum teklifi: ' + $_.Exception.Message) }
    Initialize-FirstRun
    try { Initialize-PrepNudge } catch { Write-CrashLog ('PrepNudge: ' + $_.Exception.Message) }
    try { Initialize-LookNotice } catch { Write-CrashLog ('LookNotice: ' + $_.Exception.Message) }
}

function Update-MonitorUi {
    try { Test-MonitorAlive } catch { }
    $ui.TxtClock.Text = (Tr $((Get-Date).ToString('dd.MM.yyyy  HH:mm')))
    $online = $false
    try { $online = [System.Net.NetworkInformation.NetworkInterface]::GetIsNetworkAvailable() } catch { }
    if ($online) { $ui.DotNet.Fill = (Get-Br 'BrGood') } else { $ui.DotNet.Fill = (Get-Br 'BrBad') }
    $m = $sync.Mon
    if ($null -eq $m -or -not $m.ContainsKey('Cpu')) { return }
    try { Invoke-BoardTick $m } catch { Write-CrashLog ('Pano: ' + $_.Exception.Message) }
    if ($script:UiState.Page -eq 'panel' -and $script:Win.IsVisible) {
        $fn = 'Update-Gauges'
        if (Get-Command -Name $fn -CommandType Function -ErrorAction Ignore) { & $fn $m }
    }
    if (Get-Command -Name 'Update-TrayTip' -CommandType Function -ErrorAction Ignore) { Update-TrayTip $m }
    Test-ResourceAlert $m
    if (Get-Command -Name 'Update-MonitorExtras' -CommandType Function -ErrorAction Ignore) { Update-MonitorExtras $m }
}

# Asiri yuk bildirimi: art arda yuksek CPU ya da RAM (10 dakikada en fazla bir bildirim)
function Test-ResourceAlert($M) {
    if ($script:Settings.Notify -ne $true) { return }
    if ([double]$M.Cpu -ge 95) { $script:UiState.CpuHigh++ } else { $script:UiState.CpuHigh = 0 }
    $why = ''
    if ($script:UiState.CpuHigh -ge 20) { $why = ([string][char]0x0130 + [char]0x015F + 'lemci uzun s' + [char]0x00FC + 'redir %95 ' + [char]0x00FC + 'zerinde ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'yor.') }
    elseif ([double]$M.Ram -ge 95) { $why = ('Bellek %95 ' + [char]0x00FC + 'zerinde dolu.') }
    if ($why -eq '') { return }
    if (((Get-Date) - $script:UiState.LastAlert).TotalMinutes -lt 10) { return }
    $script:UiState.LastAlert = Get-Date
    $script:UiState.CpuHigh = 0
    $top = ''
    try { if ($M.ContainsKey('Top') -and @($M.Top).Count -gt 0) { $top = (' En ' + [char]0x00E7 + 'ok kullanan: ') + [string]@($M.Top)[0].Name } } catch { }
    Show-Notify ('Sistem yo' + [char]0x011F + 'un') ($why + $top) 'warn'
}

# ---------------- kabuk olaylari ----------------
function Initialize-Shell {
    $w = $script:Win
    $ui.TxtSig.Text = (Tr $((Get-SigLine)))
    $ui.TxtVer.Text = (Tr $(('v' + $script:AppVersion + '  MULTIMIZER')))
    $w.Add_SizeChanged({ try { Update-RailDensity } catch { } })

    foreach ($k in $script:PageTitles.Keys) {
        $rb = $ui['Rail_' + $k]
        if ($null -ne $rb) {
            $rb.Add_Checked({ param($s, $e) if (-not $script:NavBusy) { Invoke-Safe { Show-Page ([string]$s.Tag) } 'Gezinme' } })
        }
    }
    $ui.SegUser.Add_Checked({ if (-not $script:ModeBusy) { Invoke-Safe { Set-UiMode 'User' } 'Kip' } })
    $ui.SegExpert.Add_Checked({ if (-not $script:ModeBusy) { Invoke-Safe { Set-UiMode 'Expert' } 'Kip' } })

    $ui.BtnMin.Add_Click({ $script:Win.WindowState = [System.Windows.WindowState]::Minimized })
    $ui.BtnMax.Add_Click({
        if ($script:Win.WindowState -eq [System.Windows.WindowState]::Maximized) { $script:Win.WindowState = [System.Windows.WindowState]::Normal }
        else { $script:Win.WindowState = [System.Windows.WindowState]::Maximized }
    })
    $ui.BtnClose.Add_Click({ Invoke-Safe { Invoke-CloseRequest } 'Kapat' })
    $ui.BtnPower.Add_Click({ Invoke-Safe { Request-FullExit } ('G' + [char]0x00FC + '' + [char]0x00E7 + '') })
    $ui.BtnLogToggle.Add_Click({ Invoke-Safe { Switch-LogPanel } ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k') })
    $ui.BtnCmdToggle.Add_Click({ Invoke-Safe { Switch-CmdPanel } 'Komut' })
    try { Initialize-HeaderBar } catch { Write-CrashLog ('Ust cubuk: ' + $_.Exception.Message) }
    try { Initialize-UxExtras } catch { Write-CrashLog ('Kullanim: ' + $_.Exception.Message) }
    $ui.BtnCancel.Add_Click({ Stop-Async })
    $ui.BtnLogClear.Add_Click({ Clear-Log })
    $ui.BtnLogCopy.Add_Click({
        $sb = New-Object System.Text.StringBuilder
        foreach ($c in $ui.LogStack.Children) { [void]$sb.AppendLine([string]$c.Text) }
        try { [System.Windows.Clipboard]::SetText($sb.ToString()); Show-Toast ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k panoya kopyaland' + [char]0x0131 + '.') 'good' } catch { Show-Toast ('Kopyalanamad' + [char]0x0131 + '.') 'warn' }
    })
    $ui.BtnLogOpen.Add_Click({ Open-Folder $script:LogDir })

    # onay kutusu
    $ui.OvOk.Add_Click({ Invoke-Safe { Complete-Overlay $true } 'Onay' })
    $ui.OvCancel.Add_Click({ Invoke-Safe { Complete-Overlay $false } 'Onay' })
    $ui.Overlay.Add_PreviewKeyDown({
        param($s, $e)
        if ($e.Key -eq [System.Windows.Input.Key]::Escape) { Complete-Overlay $false; $e.Handled = $true }
        elseif ($e.Key -eq [System.Windows.Input.Key]::Enter -and ($ui.OvInput.Visibility -eq $script:VisOn -or $ui.OvPw1.Visibility -eq $script:VisOn)) { Complete-Overlay $true; $e.Handled = $true }
    })

    $w.Add_StateChanged({
        try { Invoke-WindowStateChanged } catch { Write-CrashLog ('Pencere durumu: ' + $_.Exception.Message) }
    })
    $w.Add_Closing({
        param($s, $e)
        if (-not $script:Quitting) { $e.Cancel = $true; Invoke-Safe { Invoke-CloseRequest } 'Kapat' }
    })
    $w.Add_PreviewKeyDown({
        param($s, $e)
        try {
            $ctrl = ([System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Control) -ne 0
            if ($ctrl -and $e.Key -eq [System.Windows.Input.Key]::K) { Switch-CmdPanel $true; $e.Handled = $true }
            elseif ($e.Key -eq [System.Windows.Input.Key]::F5) {
                $fn = 'Show-Page_' + $script:UiState.Page
                if (Get-Command -Name $fn -CommandType Function -ErrorAction Ignore) { & $fn }
                $e.Handled = $true
            }
        } catch { }
    })
    $w.Add_Deactivated({ try { $ui.CmdPop.IsOpen = $false } catch { }; try { Close-LangMenu } catch { } })
}

