    ag          = ('A' + [char]0x011F + ' sayfas' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar ve ba' + [char]0x011F + 'lant' + [char]0x0131 + 'lar' + [char]0x0131 + ' okur')
    ping        = 'Ping: "ping 1.1.1.1"'
