    dns         = ('DNS h' + [char]0x0131 + 'z ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x00FC + 'm' + [char]0x00FC + ' sayfas' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar')
    hiz         = ([string][char]0x0130 + 'nternet h' + [char]0x0131 + 'z testi')
    port        = ('Dinleyen portlar' + [char]0x0131 + ' listeler')
    islemler    = ('En ' + [char]0x00E7 + 'ok CPU kullanan i' + [char]0x015F + 'lemleri listeler')
    oldur       = ([string][char]0x0130 + [char]0x015F + 'lemi sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'r: "oldur 1234"')
    ac          = ('Sayfa a' + [char]0x00E7 + ': "ac guvenlik" (panel, optimizasyon, hizmetler, uygulamalar, temizlik, ...)')
    mod         = 'Kip: "mod kullanici" veya "mod uzman"'
