    kur         = ('Uygulamay' + [char]0x0131 + ' kurar (Ba' + [char]0x015F + 'lat men' + [char]0x00FC + 's' + [char]0x00FC + ' ve masa' + [char]0x00FC + 'st' + [char]0x00FC + ' k' + [char]0x0131 + 'sayolu)')
    log         = ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k: "log temizle" ' + [char]0x00B7 + ' "log ac"')
    temizle     = ('Komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ' + [char]0x00E7 + [char]0x0131 + 'kt' + [char]0x0131 + 's' + [char]0x0131 + 'n' + [char]0x0131 + ' temizler')
    tepsi       = 'Pencereyi tepsiye indirir'
    yenidenbaslat = ('Bilgisayar' + [char]0x0131 + ' yeniden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'r (30 sn, "iptal" ile durdurulur)')
    iptal       = ('Bekleyen yeniden ba' + [char]0x015F + 'latmay' + [char]0x0131 + ' iptal eder')
