$script:CmdPages = @{
    panel = 'panel'; pano = 'panel'; durum = 'panel'; board = 'board'; duzen = 'board'; hizlandir = 'optimize'; optimizasyon = 'optimize'; optimize = 'optimize'; hizmetler = 'services'; hizmet = 'services'
    uygulamalar = 'apps'; uygulama = 'apps'; baslangic = 'startup'; temizlik = 'clean'; disk = 'clean'; guvenlik = 'security'
    guncelleme = 'updates'; guncellemeler = 'updates'; ag = 'network'; yedek = 'backup'; kurtarma = 'backup'; sirket = 'company'
    araclar = 'tools'; gecmis = 'history'; ayarlar = 'settings'
    guc = 'power'; power = 'power'; oyun = 'gaming'; gaming = 'gaming'; akilli = 'smart'; bakim = 'smart'; otomasyon = 'smart'; sikistir = 'compress'
    cozum = 'solve'; coz = 'solve'; sorun = 'solve'; onar = 'solve'; solve = 'solve'; bitlocker = 'solve'; sifrele = 'solve'; kurtar = 'solve'
    hazirlik = 'solve:prep'; bilgisayarim = 'solve:pc'; donanim = 'solve:pc'; silinen = 'solve:recover'; silme = 'solve:erase'; diskler = 'solve:disk'; harici = 'tools:ext'; disaraclar = 'tools:ext'
}

function Out-Cmd([string]$Text, [string]$Kind = 'text') {
    $k = 'BrText'
    switch ($Kind) { 'ok' { $k = 'BrGood' } 'err' { $k = 'BrBad' } 'warn' { $k = 'BrWarn' } 'info' { $k = 'BrDim' } 'acc' { $k = 'BrAccent' } }
    Add-CmdLine $Text $k
}

function Switch-CmdPanel($Force = $null) {
    $open = ($ui.CmdPanel.Visibility -eq $script:VisOn)
    if ($null -eq $Force) { $want = (-not $open) } else { $want = [bool]$Force }
    Set-Visible $ui.CmdPanel $want
    $script:CmdAutoOff = $false
    if ($want) {
        $ui.CmdPanel.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Input, [Action]{ try { [void]$ui.CmdInput.Focus() } catch { } }) | Out-Null
    } else { $ui.CmdPop.IsOpen = $false }
}

function Start-CmdJob([string]$Name, [string]$Entry, $Params, [scriptblock]$Done, [string]$Label) {
    $prevDone = $script:CmdDone
    $script:CmdDone = $Done
    $ok = Start-Async $Name $Entry $Params {
        param($r)
        $script:CmdEcho = $false
        $d = $script:CmdDone
        $script:CmdDone = $null
        if ($null -ne $d) { & $d $r }
    } $Label
    if ($ok) { $script:CmdEcho = $true } else { $script:CmdDone = $prevDone; Out-Cmd ('Ba' + [char]0x015F + 'ka bir i' + [char]0x015F + 'lem s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor; bitince tekrar deneyin.') 'warn' }
}

# ---------------- tamamlama ----------------
function Get-CmdSuggestions([string]$Text) {
    $raw = ConvertTo-AsciiKey $Text
    $res = New-Object System.Collections.ArrayList
    if ($raw.Trim() -eq '') { return , @() }
    $m = [regex]::Match($raw, '^\s*(\S*)(\s+(.*))?$')
    $first = $m.Groups[1].Value
    $hasSecond = $m.Groups[2].Success
    if (-not $hasSecond) {
        foreach ($k in $script:CmdDefs.Keys) {
            if ($k.StartsWith($first)) { [void]$res.Add(@{ Name = $k; Desc = [string]$script:CmdDefs[$k]; Insert = $k }) }
        }
        if ($res.Count -eq 0) {
            foreach ($k in $script:CmdDefs.Keys) { if ($k.Contains($first)) { [void]$res.Add(@{ Name = $k; Desc = [string]$script:CmdDefs[$k]; Insert = $k }) } }
        }
        return , $res.ToArray()
    }
    $rest = $m.Groups[3].Value
    $opts = @()
    switch ($first) {
        'ac' { $opts = @($script:CmdPages.Keys | Sort-Object) }
        'mod' { $opts = @('kullanici', 'uzman') }
        'log' { $opts = @('temizle', 'ac') }
        'saglik' { $opts = @('tam') }
        'yedekle' { $opts = @('onizle') }
    }
    foreach ($o in $opts) {
        if ($o.StartsWith($rest)) { [void]$res.Add(@{ Name = ($first + ' ' + $o); Desc = ''; Insert = ($first + ' ' + $o) }) }
    }
    return , $res.ToArray()
}

function Update-CmdPopup {
    if ($script:CmdSuppress) { return }
    $txt = [string]$ui.CmdInput.Text
    $sug = (Get-CmdSuggestions $txt)
    $script:CmdSug = $sug
    $ui.CmdList.Items.Clear()
    if ($sug.Count -eq 0 -or $txt.Trim() -eq '') { $ui.CmdPop.IsOpen = $false; return }
    $n = 0
    foreach ($s in $sug) {
        if ($n -ge 9) { break }
        $lbi = New-Object System.Windows.Controls.ListBoxItem
        $lbi.Style = $script:Win.FindResource('AcItem')
        $lbi.Content = (Tr $((New-RowElement 'CmdItem' @{ Name = [string]$s.Name; Desc = [string]$s.Desc })))
        $lbi.Tag = [string]$s.Insert
        [void]$ui.CmdList.Items.Add($lbi)
        $n++
    }
    $ui.CmdPop.IsOpen = $true
}

function Set-CmdText([string]$T) {
    $script:CmdSuppress = $true
    $ui.CmdInput.Text = (Tr $($T))
    $ui.CmdInput.CaretIndex = $T.Length
    $script:CmdSuppress = $false
}

function Accept-CmdSuggestion {
    $it = $ui.CmdList.SelectedItem
    if ($null -eq $it -and $ui.CmdList.Items.Count -gt 0) { $it = $ui.CmdList.Items[0] }
    if ($null -eq $it) { return $false }
    Set-CmdText (([string]$it.Tag) + ' ')
    $ui.CmdPop.IsOpen = $false
    return $true
}

# ---------------- yurutme ----------------
function Split-CmdLine([string]$Line) {
    $parts = New-Object System.Collections.ArrayList
    foreach ($m in [regex]::Matches($Line.Trim(), '"([^"]*)"|(\S+)')) {
        if ($m.Groups[1].Success) { [void]$parts.Add($m.Groups[1].Value) } else { [void]$parts.Add($m.Groups[2].Value) }
    }
    return , $parts.ToArray()
}

function Invoke-CmdLine([string]$Line) {
    $line = $Line.Trim()
    if ($line -eq '') { return }
    [void]$script:CmdHist.Add($line)
    while ($script:CmdHist.Count -gt 60) { $script:CmdHist.RemoveAt(0) }
    $script:CmdHistPos = $script:CmdHist.Count
    Out-Cmd ('> ' + $line) 'acc'
    $parts = (Split-CmdLine $line)
    if ($parts.Count -eq 0) { return }
    $cmd = ConvertTo-AsciiKey ([string]$parts[0])
    $args1 = @()
    if ($parts.Count -gt 1) { $args1 = @($parts | Select-Object -Skip 1) }
    $a0 = ''
    if ($args1.Count -gt 0) { $a0 = ConvertTo-AsciiKey ([string]$args1[0]) }
    if ($cmd -eq '?') { $cmd = 'yardim' }
    if ($cmd -eq 'cls' -or $cmd -eq 'clear') { $cmd = 'temizle' }
    if ($cmd -eq 'exit' -or $cmd -eq 'quit') { $cmd = 'cik' }
    switch ($cmd) {
        'yardim' {
            foreach ($k in $script:CmdDefs.Keys) { Out-Cmd (('  ' + $k.PadRight(14)) + [string]$script:CmdDefs[$k]) 'info' }
            Out-Cmd ('  Ctrl+K komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'n' + [char]0x0131 + ' a' + [char]0x00E7 + 'ar, Tab tamamlar, Yukar' + [char]0x0131 + '/A' + [char]0x015F + 'a' + [char]0x011F + [char]0x0131 + ' ge' + [char]0x00E7 + 'mi' + [char]0x015F + 'te gezer.') 'info'
        }
        'durum' { Show-CmdStatus }
        'saglik' {
            $lvl = 'Quick'; if ($a0 -eq 'tam') { $lvl = 'Full' }
            Start-HealthScan $lvl $false
            Out-Cmd ('Tarama ba' + [char]0x015F + 'lad' + [char]0x0131 + '; sonu' + [char]0x00E7 + 'lar Durum Panosu ve G' + [char]0x00FC + 'venlik sayfas' + [char]0x0131 + 'nda.') 'info'
        }
        'guvenlik' { $script:HealthAt = Get-Date; Open-Page 'security'; Start-HealthScan 'Full' $false; Out-Cmd ('Tam denetim ba' + [char]0x015F + 'lad' + [char]0x0131 + '.') 'info' }
        'bakim' { Start-QuickMaint }
        'tara' { $script:ClScan = $null; Open-Page 'clean'; if (-not (Test-AsyncBusy)) { Start-ClScan }; Out-Cmd ('Tarama ba' + [char]0x015F + 'lad' + [char]0x0131 + ' (hi' + [char]0x00E7 + 'bir ' + [char]0x015F + 'ey silinmez).') 'info' }
        'hizmet' { Invoke-CmdService $args1 }
        'guncelle' { Open-Page 'updates'; Start-UpCheck; Out-Cmd ('G' + [char]0x00FC + 'ncelleme denetimi ba' + [char]0x015F + 'lad' + [char]0x0131 + '.') 'info' }
        'yedekle' { Start-BackupNow ($a0 -eq 'onizle') }
        'rapor' { Start-ReportNow }
        'ag' { Open-Page 'network'; if (-not (Test-AsyncBusy)) { Start-NwScan } }
        'ping' {
            if ($args1.Count -eq 0) { Out-Cmd ('Kullan' + [char]0x0131 + 'm: ping <adres>') 'warn'; return }
            Start-CmdJob 'Ping' 'Job_Ping' @{ Host = [string]$args1[0]; Trace = $false } { param($r) } 'Ping'
        }
        'iz' {
            if ($args1.Count -eq 0) { Out-Cmd ('Kullan' + [char]0x0131 + 'm: iz <adres>') 'warn'; return }
            Start-CmdJob 'Ping' 'Job_Ping' @{ Host = [string]$args1[0]; Trace = $true } { param($r) } 'Yol izleme'
        }
        'dns' { Open-Page 'network' 'dns'; Out-Cmd ([string][char]0x201C + 'DNS h' + [char]0x0131 + 'zlar' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x00F6 + 'l' + [char]0x00E7 + [char]0x201D + ' d' + [char]0x00FC + [char]0x011F + 'mesine bas' + [char]0x0131 + 'n.') 'info' }
        'hiz' {
            Start-CmdJob 'Speed' 'Job_SpeedTest' @{} {
                param($r)
                if ($null -eq $r) { Out-Cmd ('H' + [char]0x0131 + 'z testi tamamlanamad' + [char]0x0131 + '.') 'err'; return }
                $script:NwSpeed = $r; $script:NwSpeedAt = Get-Date
                Out-Cmd ((([string][char]0x0130 + 'ndirme ') + ([double]$r.Down).ToString('0.0') + (' Mb/sn ' + [char]0x00B7 + ' y' + [char]0x00FC + 'kleme ') + ([double]$r.Up).ToString('0.0') + (' Mb/sn ' + [char]0x00B7 + ' gecikme ') + [string][int][double]$r.Latency + ' ms')) 'ok'
            } ([string][char]0x0130 + 'nternet h' + [char]0x0131 + 'z testi')
        }
        'port' {
            if ($null -eq $script:TopoSnap) { Out-Cmd ('A' + [char]0x011F + ' bilgisi hen' + [char]0x00FC + 'z okunmad' + [char]0x0131 + '; okunuyor, birka' + [char]0x00E7 + ' saniye sonra tekrar deneyin.') 'warn'; Start-NwScan; return }
            foreach ($l in @($script:TopoSnap.Listen)) { Out-Cmd (('  ' + [string]$l.Port).PadRight(10) + [string]$l.Proc + '  (' + [string]$l.Addr + ')') 'info' }
            Out-Cmd ('Toplam ' + [string]@($script:TopoSnap.Listen).Count + ' dinleyen port.') 'ok'
        }
        'islemler' {
            $m = $sync.Mon
            if ($null -eq $m -or -not $m.ContainsKey('Top')) { Out-Cmd ([string][char]0x0130 + 'zleme verisi hen' + [char]0x00FC + 'z yok.') 'warn'; return }
            foreach ($t in @($m.Top)) { Out-Cmd (('  ' + [string]$t.Name).PadRight(28) + '%' + [string]$t.Cpu) 'info' }
        }
        'oldur' {
            $pid1 = 0
            if ($args1.Count -eq 0 -or -not [int]::TryParse([string]$args1[0], [ref]$pid1)) { Out-Cmd ('Kullan' + [char]0x0131 + 'm: oldur <PID>   (PID i' + [char]0x00E7 + 'in "islemler" ya da Ara' + [char]0x00E7 + 'lar > ' + [char]0x0130 + [char]0x015F + 'lemler)') 'warn'; return }
            $script:PendingPid = $pid1
            Show-Confirm ([string][char]0x0130 + [char]0x015F + 'lemi sonland' + [char]0x0131 + 'r') ('PID ' + [string]$pid1 + (' sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'lacak. Sistem i' + [char]0x015F + 'lemleri korunur.')) ('Sonland' + [char]0x0131 + 'r') {
                Start-CmdJob 'Kill' 'Job_Kill' @{ Pid = $script:PendingPid } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Out-Cmd ([string][char]0x0130 + [char]0x015F + 'lem sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'ok' } else { Out-Cmd ('Sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + '.') 'err' } } ([string][char]0x0130 + [char]0x015F + 'lem sonland' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor')
            } $true
        }
        'ac' {
            if ($a0 -eq '') { Out-Cmd ('Sayfalar: ' + ((@($script:CmdPages.Keys | Sort-Object)) -join ', ')) 'info'; return }
            if ($script:CmdPages.ContainsKey($a0)) { Open-CmdPage ([string]$script:CmdPages[$a0]); Out-Cmd ('A' + [char]0x00E7 + [char]0x0131 + 'ld' + [char]0x0131 + '.') 'ok' } else { Out-Cmd ('B' + [char]0x00F6 + 'yle bir sayfa yok. "ac" yazarak listeyi g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n.') 'warn' }
        }
        'mod' {
            if ($a0 -eq 'uzman') { Set-UiMode 'Expert'; Out-Cmd 'Uzman kip.' 'ok' }
            elseif ($a0 -eq 'kullanici') { Set-UiMode 'User'; Out-Cmd ('Kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' kipi.') 'ok' }
            else { Out-Cmd (([string][char]0x015E + 'u an: ') + [string]$script:UiState.Mode + ('. Kullan' + [char]0x0131 + 'm: mod kullanici | mod uzman')) 'info' }
        }
        'profil' {
            if ($args1.Count -eq 0) { Out-Cmd ('Kullan' + [char]0x0131 + 'm: profil <dosya.json>') 'warn'; return }
            $f = [string]$args1[0]
            if (-not (Test-Path -LiteralPath $f)) { Out-Cmd ('Dosya bulunamad' + [char]0x0131 + '.') 'err'; return }
            $script:PendingProfile = $f
            Start-CmdJob 'ProfPrev' 'Job_ProfileApply' @{ Path = $f; Preview = $true; RestorePoint = $false } {
                param($r)
                if ($null -eq $r) { Out-Cmd ([string][char]0x00D6 + 'nizleme tamamlanamad' + [char]0x0131 + '.') 'err'; return }
                Show-Confirm 'Profili uygula' ([string][char]0x00D6 + 'nizleme komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'nda. Profil ' + [char]0x015F + 'imdi uygulans' + [char]0x0131 + 'n m' + [char]0x0131 + '?') 'Uygula' {
                    Start-CmdJob 'ProfApply' 'Job_ProfileApply' @{ Path = $script:PendingProfile; Preview = $false; RestorePoint = ($script:Settings.RestorePoint -eq $true) } { param($r2) Complete-PlanJob $r2 } ('Profil uygulan' + [char]0x0131 + 'yor')
                }
            } ('Profil ' + [char]0x00F6 + 'nizleniyor')
        }
        'kur' {
            Start-CmdJob 'Install' 'Job_Install' @{ Desktop = $true } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Out-Cmd 'Kuruldu.' 'ok'; $script:Settings = Get-Settings } else { Out-Cmd ('Kurulum ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z.') 'err' } } 'Uygulama kuruluyor'
        }
        'log' {
            if ($a0 -eq 'temizle') { Clear-Log; Out-Cmd ('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k paneli temizlendi.') 'ok' }
            elseif ($a0 -eq 'ac') { Open-Folder $script:LogDir }
            else { Out-Cmd (('G' + [char]0x00FC + 'nl' + [char]0x00FC + 'k dosyas' + [char]0x0131 + ': ') + [string]$sync.LogFile) 'info' }
        }
        'temizle' { $ui.CmdOut.Children.Clear() }
        'tepsi' { Hide-ToTray }
        'yenidenbaslat' { Request-Reboot }
        'iptal' {
            try { Start-Process -FilePath 'shutdown.exe' -ArgumentList '/a' -WindowStyle Hidden | Out-Null; Out-Cmd ('Yeniden ba' + [char]0x015F + 'latma iptal istendi.') 'ok' } catch { Out-Cmd ([string][char]0x0130 + 'ptal edilemedi.') 'err' }
        }
        'surum' { Out-Cmd (('Multimizer v') + $script:AppVersion + '   ' + (Get-SigLine)) 'acc' }
        'cik' { Exit-App }
        default { Out-Cmd ('Bilinmeyen komut: ' + [string]$parts[0] + ('   ("yardim" yaz' + [char]0x0131 + 'n)')) 'warn' }
    }
}

function Show-CmdStatus {
    $p = $sync.Profile
    if ($null -ne $p) { Out-Cmd ('Bilgisayar : ' + [string]$p.Hostname + '  |  ' + [string]$p.OsName + ' ' + [string]$p.Version) 'info' }
    $m = $sync.Mon
    if ($null -ne $m -and $m.ContainsKey('Cpu')) {
        Out-Cmd (([string][char]0x0130 + [char]0x015F + 'lemci   : %') + [string]$m.Cpu + '   Bellek: %' + [string]$m.Ram + ' (' + [string]$m.RamUsedGB + ' / ' + [string]$m.RamTotalGB + (' GB)   Disk etkinli' + [char]0x011F + 'i: %') + [string]$m.Disk) 'info'
        if ($m.ContainsKey('Boot') -and $null -ne $m.Boot) { Out-Cmd (('A' + [char]0x00E7 + [char]0x0131 + 'k kalma : ') + (Format-Duration (((Get-Date) - [datetime]$m.Boot).TotalSeconds))) 'info' }
    } else { Out-Cmd ([string][char]0x0130 + 'zleme verisi hen' + [char]0x00FC + 'z haz' + [char]0x0131 + 'r de' + [char]0x011F + 'il.') 'warn' }
    if ($null -ne $script:Health) {
        $s = $script:Health.Score
        Out-Cmd (('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k     : ') + [string]$s.All + ('   (g' + [char]0x00FC + 'venlik ') + [string]$s.Sec + ', performans ' + [string]$s.Perf + (', bak' + [char]0x0131 + 'm ') + [string]$s.Maint + ')') 'ok'
        $bad = @($script:Health.Findings | Where-Object { $_.Status -eq 'bad' -or $_.Status -eq 'warn' })
        foreach ($b in @($bad | Select-Object -First 5)) { Out-Cmd ('  ! ' + [string]$b.Title) 'warn' }
    } else { Out-Cmd ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k     : hen' + [char]0x00FC + 'z taranmad' + [char]0x0131 + ' ("saglik" yaz' + [char]0x0131 + 'n)') 'info' }
    $lm = [string]$script:Settings.LastMaint; if ($lm -eq '') { $lm = '-' }
    $lb = [string]$script:Settings.LastBackup; if ($lb -eq '') { $lb = '-' }
    Out-Cmd (('Son bak' + [char]0x0131 + 'm  : ') + $lm + '   Son yedek: ' + $lb) 'info'
}

function Invoke-CmdService($Args1) {
    $a = @($Args1)
    if ($a.Count -eq 0) { Out-Cmd ('Kullan' + [char]0x0131 + 'm: hizmet <ad>   ya da   hizmet <ad> durdur|baslat|yeniden') 'warn'; return }
    $q = [string]$a[0]
    $act = ''
    if ($a.Count -gt 1) { $act = ConvertTo-AsciiKey ([string]$a[1]) }
    $found = @()
    try { $found = @(Get-Service -ErrorAction Stop | Where-Object { $_.Name -like ('*' + $q + '*') -or $_.DisplayName -like ('*' + $q + '*') } | Select-Object -First 15) } catch { }
    if ($found.Count -eq 0) { Out-Cmd ('E' + [char]0x015F + 'le' + [char]0x015F + 'en hizmet yok.') 'warn'; return }
    if ($act -eq '') {
        foreach ($s in $found) { Out-Cmd (('  ' + [string]$s.Name).PadRight(30) + (ConvertTo-StateText ([string]$s.Status)).PadRight(14) + [string]$s.StartType + '   ' + [string]$s.DisplayName) 'info' }
        Out-Cmd ('Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + ' ve ' + [char]0x00F6 + 'neri i' + [char]0x00E7 + 'in: ac hizmetler') 'info'
        return
    }
    $map = @{ durdur = 'Stop'; baslat = 'Start'; yeniden = 'Restart'; yenidenbaslat = 'Restart' }
    if (-not $map.ContainsKey($act)) { Out-Cmd 'Eylem: durdur | baslat | yeniden' 'warn'; return }
    $exact = @($found | Where-Object { [string]$_.Name -ieq $q })
    if ($exact.Count -ne 1) { Out-Cmd ('Eylem i' + [char]0x00E7 + 'in tam hizmet ad' + [char]0x0131 + ' gerekir (' + [char]0x00F6 + 'r. Spooler).') 'warn'; return }
    $svcName = [string]$exact[0].Name
    $action = [string]$map[$act]
    Start-CmdJob 'SvcAct' 'Job_ServiceAction' @{ Name = $svcName; Action = $action } { param($r) if ($null -ne $r -and $r.Ok -eq $true) { Out-Cmd 'Tamam.' 'ok' } else { Out-Cmd ('Ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z (korumal' + [char]0x0131 + ' olabilir).') 'err' } } ('Hizmet: ' + $svcName)
}

function Init-CmdLine {
    $ui.CmdInput.Add_TextChanged({ try { Update-CmdPopup } catch { } })
    $ui.CmdInput.Add_PreviewKeyDown({
        param($s, $e)
        try {
            $k = $e.Key
            $open = ($ui.CmdPop.IsOpen -eq $true)
            if ($k -eq [System.Windows.Input.Key]::Down) {
                if ($open -and $ui.CmdList.Items.Count -gt 0) {
                    $i = $ui.CmdList.SelectedIndex + 1
                    if ($i -ge $ui.CmdList.Items.Count) { $i = 0 }
                    $ui.CmdList.SelectedIndex = $i
                } elseif ($script:CmdHist.Count -gt 0) {
                    if ($script:CmdHistPos -lt $script:CmdHist.Count - 1) { $script:CmdHistPos++; Set-CmdText ([string]$script:CmdHist[$script:CmdHistPos]) }
                    else { $script:CmdHistPos = $script:CmdHist.Count; Set-CmdText '' }
                }
                $e.Handled = $true
            } elseif ($k -eq [System.Windows.Input.Key]::Up) {
                if ($open -and $ui.CmdList.Items.Count -gt 0) {
                    $i = $ui.CmdList.SelectedIndex - 1
                    if ($i -lt 0) { $i = $ui.CmdList.Items.Count - 1 }
                    $ui.CmdList.SelectedIndex = $i
                } elseif ($script:CmdHist.Count -gt 0) {
                    if ($script:CmdHistPos -gt 0) { $script:CmdHistPos-- }
                    Set-CmdText ([string]$script:CmdHist[$script:CmdHistPos])
                }
                $e.Handled = $true
            } elseif ($k -eq [System.Windows.Input.Key]::Tab) {
                if ($open) { [void](Accept-CmdSuggestion) }
                $e.Handled = $true
            } elseif ($k -eq [System.Windows.Input.Key]::Escape) {
                if ($open) { $ui.CmdPop.IsOpen = $false } else { Switch-CmdPanel $false }
                $e.Handled = $true
            } elseif ($k -eq [System.Windows.Input.Key]::Return -or $k -eq [System.Windows.Input.Key]::Enter) {
                if ($open -and $ui.CmdList.SelectedIndex -ge 0) { [void](Accept-CmdSuggestion) }
                $ui.CmdPop.IsOpen = $false
                $t = [string]$ui.CmdInput.Text
                Set-CmdText ''
                Invoke-Safe { Invoke-CmdLine $t } 'Komut'
                $e.Handled = $true
            }
        } catch { Write-CrashLog (('Komut tu' + [char]0x015F + 'u: ') + $_.Exception.Message) }
    })
    $ui.CmdList.Add_PreviewMouseLeftButtonUp({
        try { if ($null -ne $ui.CmdList.SelectedItem) { [void](Accept-CmdSuggestion); [void]$ui.CmdInput.Focus() } } catch { }
    })
    Out-Cmd (('Multimizer v') + $script:AppVersion + (' ' + [char]0x00B7 + ' komut sat' + [char]0x0131 + 'r' + [char]0x0131 + '. "yardim" yaz' + [char]0x0131 + 'n, Tab ile tamamlay' + [char]0x0131 + 'n.')) 'acc'
}

# ==================================================================
#  BILDIRIM ALANI (TEPSI): simge, sag tik menusu, bildirimler, canli ipucu
#  Pencere kapatilinca (ayar aciksa) uygulama tepsiye kuculur ve izlemeye devam eder.
# ==================================================================
$script:Tray = $null
$script:TrayMenu = $null
$script:TrayItems = @{}
$script:TrayIconObj = $null
$script:TrayHintShown = $false
$script:TrayTipAt = [datetime]::MinValue

function New-TrayIconObject {
    try {
        $bmp = New-AppIconBitmap 32
        $h = $bmp.GetHicon()
        return [System.Drawing.Icon]::FromHandle($h)
    } catch {
        Write-CrashLog ('Tepsi simgesi cizilemedi: ' + $_.Exception.Message)
        return [System.Drawing.SystemIcons]::Application
    }
}

# Baslik ve metin kisaltilir (Windows sinirlari: 63 / 255 karakter)
function Show-Notify([string]$Title, [string]$Text, [string]$Kind = 'info') {
    if ($script:Settings.Notify -ne $true) { return }
    if ($null -eq $script:Tray) { return }
    try {
        # Pencere acik ve ondeyse uygulama ici bildirim yeterli
        if ($script:Win.IsVisible -and $script:Win.IsActive -and $script:Win.WindowState -ne [System.Windows.WindowState]::Minimized) { return }
        $icon = [System.Windows.Forms.ToolTipIcon]::Info
        if ($Kind -eq 'warn') { $icon = [System.Windows.Forms.ToolTipIcon]::Warning }
        elseif ($Kind -eq 'bad') { $icon = [System.Windows.Forms.ToolTipIcon]::Error }
        $t = Limit-Text (Tr $Title) 60
        $x = Limit-Text (Tr $Text) 240
        $script:Tray.ShowBalloonTip(6000, $t, $x, $icon)
    } catch { Write-CrashLog ('Show-Notify: ' + $_.Exception.Message) }
}

function Update-TrayTip($M) {
    if ($null -eq $script:Tray) { return }
    if (((Get-Date) - $script:TrayTipAt).TotalSeconds -lt 4) { return }
    $script:TrayTipAt = Get-Date
    try {
        $t = (('Multimizer  ' + [char]0x0130 + [char]0x015F + 'lemci ') + (Format-Pct ([double]$M.Cpu)) + '  Bellek ' + (Format-Pct ([double]$M.Ram)))
        $t = Tr $t
        if ($t.Length -gt 63) { $t = $t.Substring(0, 63) }
        $script:Tray.Text = $t # Tr:yok
    } catch { }
}

function Update-TrayMenuState {
    if ($null -eq $script:Tray) { return }
    try {
        $script:TrayItems['notify'].Checked = ($script:Settings.Notify -eq $true)
        $script:TrayItems['ksoff'].Visible = (Test-KsUiOn)
        if ($script:Settings.MaintEnabled -eq $true) {
            $script:TrayItems['sched'].Text = (Tr $((('Zamanlanm' + [char]0x0131 + [char]0x015F + ' bak' + [char]0x0131 + 'm: a' + [char]0x00E7 + [char]0x0131 + 'k (') + [string]$script:Settings.MaintTime + ')')))
        } else {
            $script:TrayItems['sched'].Text = (Tr $(('Zamanlanm' + [char]0x0131 + [char]0x015F + ' bak' + [char]0x0131 + 'm: kapal' + [char]0x0131)))
        }
    } catch { }
}

function Add-TrayItem([string]$Key, [string]$Text, [scriptblock]$OnClick) {
    $it = New-Object System.Windows.Forms.ToolStripMenuItem
    $it.Text = (Tr $($Text))
    if ($null -ne $OnClick) { $it.Add_Click($OnClick) }
    [void]$script:TrayMenu.Items.Add($it)
    $script:TrayItems[$Key] = $it
    return $it
}

function Initialize-Tray {
    try {
        $script:TrayIconObj = New-TrayIconObject
        $script:TrayMenu = New-Object System.Windows.Forms.ContextMenuStrip
        $n = New-Object System.Windows.Forms.NotifyIcon
        $n.Icon = $script:TrayIconObj
        $n.Text = (Tr $(('Multimizer')))
        $n.ContextMenuStrip = $script:TrayMenu
        $script:Tray = $n

        $it = Add-TrayItem 'open' ('A' + [char]0x00E7) { Invoke-Safe { Restore-FromTray } 'Tepsi' }
        $it.Font = New-Object System.Drawing.Font -ArgumentList $it.Font, ([System.Drawing.FontStyle]::Bold)
        [void](Add-TrayItem 'maint' ('H' + [char]0x0131 + 'zl' + [char]0x0131 + ' bak' + [char]0x0131 + 'm...') { Invoke-Safe { Restore-FromTray; Start-QuickMaint } 'Tepsi' })
        [void](Add-TrayItem 'health' ('Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k denetimi') { Invoke-Safe { Restore-FromTray; Show-Page 'panel'; Start-HealthScan 'Quick' $false } 'Tepsi' })
        [void](Add-TrayItem 'report' ('Sistem raporu olu' + [char]0x015F + 'tur') { Invoke-Safe { Start-ReportNow } 'Tepsi' })
        [void](Add-TrayItem 'cmd' ('Komut sat' + [char]0x0131 + 'r' + [char]0x0131) { Invoke-Safe { Restore-FromTray; Switch-CmdPanel $true } 'Tepsi' })
        [void](Add-TrayItem 'ksoff' ('Kill-switch' + [char]0x2019 + 'i kapat (internet eri' + [char]0x015F + 'imini a' + [char]0x00E7 + ')') { Invoke-Safe { Start-KsOffNow } 'Tepsi' })
        [void]$script:TrayMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        $s = Add-TrayItem 'sched' ('Zamanlanm' + [char]0x0131 + [char]0x015F + ' bak' + [char]0x0131 + 'm') { Invoke-Safe { Restore-FromTray; Show-Page 'settings' } 'Tepsi' }
        $nt = Add-TrayItem 'notify' 'Bildirimler' {
            Invoke-Safe {
                $script:Settings.Notify = (-not ($script:Settings.Notify -eq $true))
                Save-Settings $script:Settings
                Update-TrayMenuState
                if ($script:Pages.ContainsKey('settings')) { Load-StFromSettings }
            } 'Tepsi'
        }
        $nt.CheckOnClick = $false
        [void]$script:TrayMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        [void](Add-TrayItem 'exit' 'Tamamen kapat' {
            Invoke-Safe {
                if (Test-AsyncBusy) {
                    Restore-FromTray
                    Show-Confirm ([string][char]0x0130 + [char]0x015F + 'lem s' + [char]0x00FC + 'r' + [char]0x00FC + 'yor') ('Devam eden i' + [char]0x015F + 'lem iptal edilip uygulama kapat' + [char]0x0131 + 'ls' + [char]0x0131 + 'n m' + [char]0x0131 + '?') 'Kapat' { Exit-App } $true
                } else { Exit-App }
            } 'Tepsi'
        })
        $n.Add_DoubleClick({ Invoke-Safe { Restore-FromTray } 'Tepsi' })
        $n.Add_MouseClick({ param($s, $e) if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) { Invoke-Safe { Restore-FromTray } 'Tepsi' } })
        $n.Add_BalloonTipClicked({ Invoke-Safe { Restore-FromTray } 'Tepsi' })
        $n.Visible = $true
        Update-TrayMenuState
    } catch {
        Write-CrashLog ('Tepsi kurulamadi: ' + $_.Exception.Message)
        $script:Tray = $null
    }
}

function Remove-Tray {
    try {
        if ($null -ne $script:Tray) {
            $script:Tray.Visible = $false
            $script:Tray.Dispose()
        }
        if ($null -ne $script:TrayMenu) { $script:TrayMenu.Dispose() }
    } catch { }
    $script:Tray = $null
}

# ==================================================================
#  KOMUT SATIRI KIPI (-Cli -Gorev ...) ve KENDI KENDINE SINAMA (-OzTest)
#  Zamanlanmis gorevler, GPO / Intune betikleri ve uzaktan yonetim icin pencere acmadan calisir.
#  Cikis kodlari: 0 = tamam, 1 = hata / gecersiz kullanim, 2 = kritik bulgu var (Durum), 3 = baska gorev calisiyor
# ==================================================================
function ConvertTo-CliKey([string]$Text) {
    $t = $Text.ToLowerInvariant()
    $t = $t.Replace([string][char]0x0131, 'i').Replace([string][char]0x00FC, 'u').Replace([string][char]0x00E7, 'c')
    $t = $t.Replace([string][char]0x015F, 's').Replace([string][char]0x00F6, 'o').Replace([string][char]0x011F, 'g')
    return $t.Trim()
}

# Bir is islevini dogrudan calistirir; ciktidaki son tabloyu sonuc olarak dondurur
function Invoke-CliJob([string]$Entry, $Params) {
    $res = $null
    try {
        if (Test-NetBlocked $Entry) { Write-WhLog (Get-NetBlockText $Entry) 'WARN'; return $null }
        $xe = Get-ExtError $Entry
        if ($xe -ne '') { Write-WhLog $xe 'ERR'; return $null }
        $out = @(& $Entry $Params)
        foreach ($o in $out) {
            $b = $o
            if ($b -is [psobject]) { $b = $b.psobject.BaseObject }
            if ($b -is [hashtable]) { $res = $b }
        }
    } catch {
        Write-WhLog (('G' + [char]0x00F6 + 'rev hatas' + [char]0x0131 + ' (') + $Entry + '): ' + $_.Exception.Message) 'ERR'
    }
    return $res
}


# ---------------- Komut satiri: ag gorevleri ----------------
# ==================================================================
#  KOMUT SATIRI: -Gorev Duzelt / AgBul / AgKoruma / KorumaAc
# ==================================================================

# Saglik bulgularindan guvenle (Otomatik) duzeltilebilenleri duzeltir; oncesi ve sonrasi puani yazar
function Invoke-CliFix {
    $code = 0
    $h = Invoke-CliJob 'Job_Health' @{ Level = 'Full' }
    if ($null -eq $h) { return 1 }
    $before = [int]$h.Score.All
    $list = Get-FixList $h.Findings
    $auto = @($list | Where-Object { $_.Mode -eq 'Auto' })
    $click = @($list | Where-Object { $_.Mode -eq 'Click' })
    Write-Raw ''
    Write-Raw (('  Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ': ') + [string]$before + ' / 100')
    if ($auto.Count -eq 0) {
        Write-WhLog ('Otomatik d' + [char]0x00FC + 'zeltilecek bulgu yok.') 'OK'
    } else {
        foreach ($a in $auto) { Write-Raw (('  [D' + [char]0x00DC + 'ZELT] ') + [string]$a.Fix.Label + ' - ' + [string]$a.Title) }
        $st = Get-Settings
        $fixes = @($auto | ForEach-Object { $_.Fix })
        $r = Invoke-CliJob 'Job_FixAll' @{ Fixes = $fixes; Preview = $false; RestorePoint = ($st.RestorePoint -eq $true) }
        if ($null -eq $r -or [int]$r.Errors -gt 0) { $code = 1 }
        if ($null -ne $r -and $r.Reboot -eq $true) { Write-WhLog ('Baz' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'ikliklerin ge' + [char]0x00E7 + 'erli olmas' + [char]0x0131 + ' i' + [char]0x00E7 + 'in yeniden ba' + [char]0x015F + 'latma gerekiyor (kendili' + [char]0x011F + 'inden ba' + [char]0x015F + 'lat' + [char]0x0131 + 'lmaz).') 'WARN' }
        $h2 = Invoke-CliJob 'Job_Health' @{ Level = 'Full' }
        if ($null -ne $h2) {
            Write-Raw (('  Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ': ') + [string]$before + ' -> ' + [string]$h2.Score.All)
            foreach ($x in @($h2.Findings)) { if ($x.Status -eq 'bad') { if ($code -eq 0) { $code = 2 } } }
        }
    }
    if ($click.Count -gt 0) { Write-Raw ('  Onay isteyen ' + [string]$click.Count + (' bulgu uygulanmad' + [char]0x0131 + '; aray' + [char]0x00FC + 'zde G' + [char]0x00FC + 'venlik > D' + [char]0x00FC + 'zeltme plan' + [char]0x0131 + ' sekmesinden se' + [char]0x00E7 + 'ebilirsiniz.')) }
    return $code
}

function Write-CliDevices($R) {
    Write-Raw ''
    Write-Raw (('  A' + [char]0x011F + ': ') + [string]$R.Ctx.Ip + '/' + [string]$R.Ctx.Prefix + ('   A' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi: ') + [string]$R.Ctx.Gateway + '   ' + [string]@($R.Devices).Count + ' cihaz')
    Write-Raw ''
    Write-Raw ('  ' + 'ADRES'.PadRight(16) + 'MAC'.PadRight(19) + ('T' + [char]0x00DC + 'R').PadRight(34) + ('AD / ' + [char]0x00DC + 'RET' + [char]0x0130 + 'C' + [char]0x0130 + ''))
    foreach ($d in @($R.Devices)) {
        $ti = Get-DevTypeInfo ([string]$d.Type)
        $flags = ''
        if ($d.IsSelf -eq $true) { $flags += ' [bu bilgisayar]' }
        if ($d.IsGateway -eq $true) { $flags += (' [a' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi]') }
        if ($d.Blocked -eq $true) { $flags += (' [ENGELL' + [char]0x0130 + ']') }
        elseif ($d.New -eq $true) { $flags += (' [tan' + [char]0x0131 + 'd' + [char]0x0131 + 'k de' + [char]0x011F + 'il]') }
        $lab = [string]$ti.L
        if ([int]$d.Conf -gt 0 -and $d.IsSelf -ne $true) { $lab += ' (%' + [string]$d.Conf + ')' }
        $nm = Get-DeviceTitle $d
        Write-Raw ('  ' + ([string]$d.Ip).PadRight(16) + ([string]$d.Mac).PadRight(19) + $lab.PadRight(34) + $nm + $flags)
        foreach ($rk in @($d.Risks)) { Write-Raw ('      ! ' + [string]$rk.Text) }
    }
    foreach ($a in @($R.Alerts)) {
        $tag = '[UYARI] '
        if ($a.Sev -eq 'bad') { $tag = ('[KR' + [char]0x0130 + 'T' + [char]0x0130 + 'K]') }
        Write-Raw ('  ' + $tag + ' ' + [string]$a.Text)
    }
}

# Yerel agdaki cihazlari bulur ve turunu yazar. Cikis kodu: 2 = ag gecidi degisimi ya da ciddi aciklik
function Invoke-CliLan {
    $deep = (Test-Opt 'OptScan')
    $r = Invoke-CliJob 'Job_LanScan' @{ Deep = $deep }
    if ($null -eq $r -or $r.Ok -ne $true) {
        if ($null -ne $r) { Write-WhLog (('A' + [char]0x011F + ' taranamad' + [char]0x0131 + ': ') + [string]$r.Error) 'ERR' }
        return 1
    }
    Write-CliDevices $r
    foreach ($a in @($r.Alerts)) { if ($a.Sev -eq 'bad') { return 2 } }
    return 0
}

# Bu bilgisayarin ag tarafi: guvenlik duvari, paylasimlar, Wi-Fi, ag gecidi butunlugu
function Invoke-CliNetProtect {
    $r = Invoke-CliJob 'Job_NetProtect' @{}
    if ($null -eq $r) { return 1 }
    $code = 0
    Write-Raw ''
    foreach ($x in @($r.Findings)) {
        $tag = ''
        if ($x.Status -eq 'bad') { $tag = ('[KR' + [char]0x0130 + 'T' + [char]0x0130 + 'K]'); $code = 2 } elseif ($x.Status -eq 'warn') { $tag = '[UYARI] ' } elseif ($x.Status -eq 'info') { $tag = ('[B' + [char]0x0130 + 'LG' + [char]0x0130 + '] ') }
        if ($tag -eq '') { continue }
        Write-Raw ('  ' + $tag + ' ' + [string]$x.Title)
    }
    if (@($r.Findings | Where-Object { $_.Status -ne 'ok' }).Count -eq 0) { Write-WhLog ('A' + [char]0x011F + ' korumas' + [char]0x0131 + 'nda sorun bulunmad' + [char]0x0131 + '.') 'OK' }
    return $code
}

# Acil durum: Multimizer'in ekledigi tum ag engellerini (cihaz engelleri, kill-switch) kaldirir
function Invoke-CliEmergency {
    $n = 0
    try {
        $rules = @(Get-NetFirewallRule -Group $script:FwDevGroup -ErrorAction Stop)
        $n = $rules.Count
        if ($n -gt 0) { Remove-NetFirewallRule -Group $script:FwDevGroup -ErrorAction Stop }
    } catch { Write-WhLog (('Cihaz engelleri kald' + [char]0x0131 + 'r' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'WARN' }
    Write-WhLog ([string]$n + (' cihaz engeli kural' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'ld' + [char]0x0131 + '.')) 'OK'
    if (Get-Command -Name 'Disable-KillSwitchNow' -CommandType Function -ErrorAction Ignore) {
        try { Disable-KillSwitchNow } catch { Write-WhLog (('Kill-switch kapat' + [char]0x0131 + 'lamad' + [char]0x0131 + ': ') + $_.Exception.Message) 'ERR'; return 1 }
    }
    return 0
}

# ---------------- komut satiri: guc plani, akilli bakim, akilli temizlik, sikistirma ----------------
function Get-CliPowerKey([string]$Text) {
    $t = ([string]$Text).Trim().ToLowerInvariant()
    if ($t -match '^(dengeli|balanced)$') { return 'Balanced' }
    if ($t -match '^(tasarruf|saver|powersaver)$') { return 'Saver' }
    if ($t -match '^(yuksek|y.ksek|high)$') { return 'High' }
    if ($t -match '^(nihai|ultimate)$') { return 'Ultimate' }
    return ''
}

function Invoke-CliPower {
    $k = Get-CliPowerKey ([string]$Deger)
    if ($k -eq '') { Write-WhLog ('Kullan' + [char]0x0131 + 'm: -Gorev GucPlani -Deger Dengeli | Tasarruf | Yuksek | Nihai') 'ERR'; return 1 }
    $r = Invoke-CliJob 'Job_Plan' @{ Steps = (New-PowerSetSteps $k); Preview = $false; RestorePoint = $false }
    if ($null -eq $r -or [int]$r.Errors -gt 0) { return 1 }
    return 0
}

function Invoke-CliSmartZero {
    $st = Get-Settings
    $r = Invoke-CliJob 'Job_SmartZero' @{ Preview = $false; RestorePoint = ($st.RestorePoint -eq $true) }
    if ($null -eq $r -or [int]$r.Errors -gt 0) { return 1 }
    if ($r.Reboot -eq $true) { return 3 }
    return 0
}

function Invoke-CliSmartClean {
    $r = Invoke-CliJob 'Job_Plan' @{ Steps = (New-StepsFromIds ([string[]]@($script:SmSafeClean))); Preview = $false; RestorePoint = $false }
    if ($null -eq $r -or [int]$r.Errors -gt 0) { return 1 }
    return 0
}

function Invoke-CliCompress {
    $v = ([string]$Deger).Trim()
    if ($v -eq '') { Write-WhLog ('Kullan' + [char]0x0131 + 'm: -Gorev Sikistir -Deger "D:\Oyunlar\Oyun"   ya da   -Deger CompactOS') 'ERR'; return 1 }
    $steps = $null
    if ($v -match '^(?i)compactos$') {
        $steps = @(@{ Id = 'compactos'; Title = 'CompactOS'; Ops = @(@{ T = 'CompactOs'; State = 'always' }); Reboot = $false })
    } else {
        $why = Test-CompressAllowed $v
        if ($why -ne '') { Write-WhLog (('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'lamaz: ') + $why) 'ERR'; return 1 }
        $steps = New-CompressSteps @($v) 'xpress4k' 'compress'
    }
    $r = Invoke-CliJob 'Job_Plan' @{ Steps = $steps; Preview = $false; RestorePoint = $false }
    if ($null -eq $r -or [int]$r.Errors -gt 0) { return 1 }
    return 0
}

