    Write-Raw ''
    Write-Raw ('    Bakim     Se' + [char]0x00E7 + 'ili bak' + [char]0x0131 + 'm ad' + [char]0x0131 + 'mlar' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'r (ge' + [char]0x00E7 + 'ici dosya temizli' + [char]0x011F + 'i, disk optimizasyonu vb.)')
