    Write-Raw ('    Durum     Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ' ve bulgular' + [char]0x0131 + ' yazar (kritik bulgu varsa ' + [char]0x00E7 + [char]0x0131 + 'k' + [char]0x0131 + [char]0x015F + ' kodu 2)')
    Write-Raw ('    Guncelle  winget ile g' + [char]0x00FC + 'ncellenebilir programlar' + [char]0x0131 + ' g' + [char]0x00FC + 'nceller')
    Write-Raw ('    Profil    -Profil ile verilen ayar profilini uygular (geri al' + [char]0x0131 + 'nabilir)')
    Write-Raw ('    Duzelt    Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k bulgular' + [char]0x0131 + 'ndan g' + [char]0x00FC + 'venle d' + [char]0x00FC + 'zeltilebilenleri d' + [char]0x00FC + 'zeltir (' + [char]0x00F6 + 'ncesi/sonras' + [char]0x0131 + ' puan)')
    Write-Raw ('    AgBul     A' + [char]0x011F + 'daki cihazlar' + [char]0x0131 + ' bulur, t' + [char]0x00FC + 'r' + [char]0x00FC + 'n' + [char]0x00FC + ' ve ad' + [char]0x0131 + 'n' + [char]0x0131 + ' yazar')
    Write-Raw ('    AgKoruma  Bu bilgisayar' + [char]0x0131 + 'n a' + [char]0x011F + ' korumas' + [char]0x0131 + 'n' + [char]0x0131 + ' denetler')
    Write-Raw ('    KorumaAc  Acil durum: cihaz engellerini ve kill-switch kural' + [char]0x0131 + 'n' + [char]0x0131 + ' kald' + [char]0x0131 + 'r' + [char]0x0131 + 'r')
    Write-Raw (('    GucPlani  -Deger Dengeli | Tasarruf | Yuksek | Nihai: g' + [char]0x00FC + '' + [char]0x00E7 + ' plan' + [char]0x0131 + 'n' + [char]0x0131 + ' de' + [char]0x011F + 'i' + [char]0x015F + 'tirir (geri al' + [char]0x0131 + 'nabilir)'))
    Write-Raw (('    AkilliBakim     S' + [char]0x0131 + 'f' + [char]0x0131 + 'r dokunu' + [char]0x015F + ': bu bilgisayara uygun g' + [char]0x00FC + 'venli ayarlar ve ge' + [char]0x00E7 + 'ici dosya temizli' + [char]0x011F + 'i'))
    Write-Raw (('    AkilliTemizlik  G' + [char]0x00FC + 'venli temizlik kategorileri (ge' + [char]0x00E7 + 'ici dosyalar, g' + [char]0x00FC + 'nl' + [char]0x00FC + 'kler, ' + [char]0x00F6 + 'nbellekler)'))
    Write-Raw (('    Sikistir  -Deger <klas' + [char]0x00F6 + 'r> | CompactOS: klas' + [char]0x00F6 + 'r' + [char]0x00FC + ' ya da Windows sistem dosyalar' + [char]0x0131 + 'n' + [char]0x0131 + ' s' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'r'))
    Write-Raw ('    AyarSifirla     -Deger Gorunum | Tercihler: g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm' + [char]0x00FC + ' ya da uygulama tercihlerini varsay' + [char]0x0131 + 'lana d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'r (' + [char]0x00F6 + 'nceki ayarlar AyarYedekleri klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'ne kopyalan' + [char]0x0131 + 'r; uygulama kapal' + [char]0x0131 + 'yken)')
    Write-Raw (('    GorunumSifirla  G' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm' + [char]0x00FC + ' en g' + [char]0x00FC + 'venli bi' + [char]0x00E7 + 'ime d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'r (tema Neon, yerle' + [char]0x015F + 'im Ayr' + [char]0x0131 + 'nt' + [char]0x0131 + 'l' + [char]0x0131 + ', yak' + [char]0x0131 + 'nla' + [char]0x015F + 't' + [char]0x0131 + 'rma %100, mini izleyici kapal' + [char]0x0131 + '); uygulama a' + [char]0x00E7 + '' + [char]0x0131 + 'lmazsa kullan' + [char]0x0131 + 'n'))
    Write-Raw (('    GuvenliCizim    Yaln' + [char]0x0131 + 'zca yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'mla ' + [char]0x00E7 + 'izim + GPU / s' + [char]0x0131 + 'cakl' + [char]0x0131 + 'k izleme kapal' + [char]0x0131 + ' (-Deger Ac | Kapat | Durum); ekran kart' + [char]0x0131 + ' kaynakl' + [char]0x0131 + ' kapanmalara kar' + [char]0x015F + '' + [char]0x0131 + ''))
    Write-Raw ''
}

function Write-CliStatus($Res) {
    if ($null -eq $Res) { return }
    $sc = $Res.Score
    $f = @($Res.Findings)
    Write-Raw ''
    Write-Raw (('  Sa' + [char]0x011F + 'l' + [char]0x0131 + 'k puan' + [char]0x0131 + ': ') + [string]$sc.All + (' / 100   (g' + [char]0x00FC + 'venlik ') + [string]$sc.Sec + ', performans ' + [string]$sc.Perf + (', bak' + [char]0x0131 + 'm ') + [string]$sc.Maint + ')')
    foreach ($x in $f) {
        $tag = ''
        if ($x.Status -eq 'bad') { $tag = ('[KR' + [char]0x0130 + 'T' + [char]0x0130 + 'K]') } elseif ($x.Status -eq 'warn') { $tag = '[UYARI] ' } elseif ($x.Status -eq 'info') { $tag = ('[B' + [char]0x0130 + 'LG' + [char]0x0130 + '] ') }
        if ($tag -eq '') { continue }
        $line = ('  ' + $tag + ' ' + [string]$x.Title)
        if ([string]$x.Detail -ne '') { $line += (' - ' + [string]$x.Detail) }
        Write-Raw $line
    }
}

function Invoke-CliMode {
    $code = 0
    $mutex = $null
    $got = $true
    try {
        $mutex = New-Object System.Threading.Mutex($false, 'Global\Multimizer-Gorev')
        try { $got = $mutex.WaitOne(0) } catch [System.Threading.AbandonedMutexException] { $got = $true }
    } catch { $got = $true }
    if (-not $got) {
        Write-WhLog ('Ba' + [char]0x015F + 'ka bir g' + [char]0x00F6 + 'rev ' + [char]0x015F + 'u anda ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + [char]0x0131 + 'yor; bu ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'rma atland' + [char]0x0131 + '.') 'WARN'
        return 3
    }
    try {
        $key = ConvertTo-CliKey $Gorev
        Write-Raw ''
        Write-Raw (('  Multimizer v') + $script:AppVersion + '   ' + (Get-SigLine))
        Write-Raw (('  G' + [char]0x00F6 + 'rev: ') + $Gorev + '   Bilgisayar: ' + $env:COMPUTERNAME + '   ' + (Get-Date -Format 'dd.MM.yyyy HH:mm'))
        switch ($key) {
            'bakim' {
                $r = Invoke-CliJob 'Job_Maint' @{ Items = @(); Preview = $false }
                if ($null -eq $r -or [int]$r.Errors -gt 0) { $code = 1 }
            }
            'rapor' {
                $r = Invoke-CliJob 'Job_Report' @{}
                if ($null -eq $r) { $code = 1 }
            }
            'yedekle' {
                $r = Invoke-CliJob 'Job_Backup' @{ Preview = $false; Sources = @(); Dest = ''; Mode = '' }
                if ($null -eq $r -or $r.Ok -ne $true) { $code = 1 }
            }
            'durum' {
                $r = Invoke-CliJob 'Job_Health' @{ Level = 'Full' }
                if ($null -eq $r) { $code = 1 }
                else {
                    Write-CliStatus $r
                    foreach ($x in @($r.Findings)) { if ($x.Status -eq 'bad') { $code = 2 } }
                }
            }
            'guncelle' {
                $c = Invoke-CliJob 'Job_WingetCheck' @{}
                if ($null -eq $c) { $code = 1 }
                else {
                    $ids = New-Object System.Collections.ArrayList
                    foreach ($row in @($c.Rows)) { if ($row.Explicit -ne $true -and [string]$row.Id -ne '') { [void]$ids.Add([string]$row.Id) } }
                    if ($ids.Count -eq 0) { Write-WhLog ('G' + [char]0x00FC + 'ncellenecek program yok.') 'OK' }
                    else {
                        $r = Invoke-CliJob 'Job_WingetUpgrade' @{ Ids = $ids.ToArray() }
                        if ($null -eq $r) { $code = 1 }
                    }
                }
            }
            'duzelt' { $code = Invoke-CliFix }
            'agbul' { $code = Invoke-CliLan }
            'agkoruma' { $code = Invoke-CliNetProtect }
            'korumaac' { $code = Invoke-CliEmergency }
            'gucplani' { $code = Invoke-CliPower }
            'akillibakim' { $code = Invoke-CliSmartZero }
            'akillitemizlik' { $code = Invoke-CliSmartClean }
            'sikistir' { $code = Invoke-CliCompress }
            'ayarsifirla' { $code = Invoke-CliResetSettings }
            'gorunumsifirla' { $code = Invoke-CliResetUi }
            'guvenlicizim' { $code = Invoke-CliSafeRender }
            'profil' {
                if ([string]$Profil -eq '' -or -not (Test-Path -LiteralPath $Profil)) {
                    Write-WhLog ('Profil dosyas' + [char]0x0131 + ' bulunamad' + [char]0x0131 + '. Kullan' + [char]0x0131 + 'm: -Gorev Profil -Profil C:\yol\profil.json') 'ERR'
                    $code = 1
                } else {
                    $r = Invoke-CliJob 'Job_ProfileApply' @{ Path = $Profil; Preview = $false; RestorePoint = $true }
                    if ($null -eq $r -or $r.Ok -eq $false -or [int]$r.Errors -gt 0) { $code = 1 }
                }
            }
            default {
                if ($key -ne '') { Write-WhLog (('Bilinmeyen g' + [char]0x00F6 + 'rev: ') + $Gorev) 'ERR' }
                Show-CliUsage
                $code = 1
            }
        }
        Write-WhLog (('G' + [char]0x00F6 + 'rev tamamland' + [char]0x0131 + ', ' + [char]0x00E7 + [char]0x0131 + 'k' + [char]0x0131 + [char]0x015F + ' kodu ') + [string]$code) 'INFO'
    } catch {
        Write-WhLog (('G' + [char]0x00F6 + 'rev ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z: ') + $_.Exception.Message) 'ERR'
        $code = 1
    } finally {
        try { if ($null -ne $mutex) { $mutex.ReleaseMutex(); $mutex.Dispose() } } catch { }
    }
    return $code
}

# ==================================================================
#  KENDI KENDINE SINAMA:  Multimizer.ps1 -OzTest
#  Sistemde kalici degisiklik yapmaz (gecici bir kayit defteri anahtari olusturur ve siler).
#  Sonuc: ProgramData\Multimizer\ozsinama.txt  ve ekranda ozet
# ==================================================================
$script:SelfLines = New-Object System.Collections.ArrayList
$script:SelfFail = 0
$script:SelfTotal = 0
$script:SelfWarn = 0

function Add-SelfLine([string]$Text) {
    [void]$script:SelfLines.Add($Text)
    Write-Host $Text
}

# Govde: '' / $true / $null = basarili;  metin = basarisiz (metin = neden);  $false = basarisiz
function Test-Step([string]$Name, [scriptblock]$Body, [bool]$WarnOnly = $false) {
    $script:SelfTotal++
    $ok = $true
    $why = ''
    try {
        $out = @(& $Body)
        $r = $null
        if ($out.Count -gt 0) { $r = $out[$out.Count - 1] }
        if ($r -is [string] -and $r -ne '') { $ok = $false; $why = $r }
        elseif ($r -is [bool] -and $r -eq $false) { $ok = $false; $why = ('ko' + [char]0x015F + 'ul sa' + [char]0x011F + 'lanmad' + [char]0x0131) }
    } catch {
        $ok = $false
        $why = [string]$_.Exception.Message
    }
    if ($ok) { Add-SelfLine ('  [TAMAM]  ' + $Name) }
    elseif ($WarnOnly) { $script:SelfWarn++; Add-SelfLine ('  [UYARI]  ' + $Name + ' : ' + $why) }
    else { $script:SelfFail++; Add-SelfLine ('  [HATA]   ' + $Name + ' : ' + $why) }
}

function Invoke-SelfTest {
    Add-SelfLine (('Multimizer v') + $script:AppVersion + (' kendi kendine s' + [char]0x0131 + 'nama  ') + (Get-Date -Format 'dd.MM.yyyy HH:mm'))
    $p = $sync.Profile
    if ($null -ne $p) { Add-SelfLine ('Sistem: ' + [string]$p.OsName + ' ' + [string]$p.Version + ' (derleme ' + [string]$p.Build + ')  PowerShell ' + $PSVersionTable.PSVersion.ToString()) }
    Add-SelfLine ''

    Test-Step ([string][char]0x00C7 + 'ekirdek i' + [char]0x015F + 'levler y' + [char]0x00FC + 'kl' + [char]0x00FC) {
        $need = @('Job_Plan', 'Job_Undo', 'Job_Repair', 'Job_Services', 'Job_Maint', 'Job_Health', 'Job_Report', 'Job_Backup', 'Job_WuSearch', 'Job_WingetCheck', 'Job_Install', 'Job_SyncTasks', 'Job_ProfileApply', 'Job_Monitor', 'Invoke-Plan', 'Invoke-Undo', 'Get-ServiceRows', 'Get-HealthFindings', 'Start-Async', 'New-AppIconBitmap')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
    }

    Test-Step ('Ayar dosyas' + [char]0x0131 + ' yaz / oku') {
        $f = Join-Path $script:DataDir 'sinama-ayar.json'
        $s = Get-DefaultSettings
        $s.Org = 'Sinama'
        Save-JsonFile $s $f 4
        $o = ConvertTo-Hashtable (Read-JsonFile $f)
        Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
        if ([string]$o.Org -ne 'Sinama') { return ('de' + [char]0x011F + 'er geri okunamad' + [char]0x0131) }
        if (@($o.MaintItems).Count -lt 1) { return ('varsay' + [char]0x0131 + 'lan bak' + [char]0x0131 + 'm ad' + [char]0x0131 + 'mlar' + [char]0x0131 + ' bo' + [char]0x015F) }
    }

    Test-Step ('Katalog tutarl' + [char]0x0131 + ' (benzersiz kimlik, ge' + [char]0x00E7 + 'erli i' + [char]0x015F + 'lem t' + [char]0x00FC + 'r' + [char]0x00FC + ')') {
        $types = @('Reg', 'Svc', 'Task', 'Appx', 'Mp', 'Dns', 'Feature', 'Func', 'Fw', 'EvtLog') + @($script:MoreOps.Keys | ForEach-Object { [string]$_ })
        $seen = @{}
        foreach ($c in $script:Catalog) {
            $id = [string]$c.Id
            if ($seen.ContainsKey($id)) { return ('yinelenen kimlik: ' + $id) }
            $seen[$id] = $true
            foreach ($op in @($c.Ops)) { if ($types -notcontains [string]$op.T) { return ($id + (': ge' + [char]0x00E7 + 'ersiz i' + [char]0x015F + 'lem t' + [char]0x00FC + 'r' + [char]0x00FC + ' ') + [string]$op.T) } }
        }
        if ($script:Catalog.Count -lt 60) { return (('katalog k' + [char]0x00FC + [char]0x00E7 + [char]0x00FC + 'k: ') + $script:Catalog.Count) }
    }

    Test-Step ('Katalogda g' + [char]0x00FC + 'venlik kap' + [char]0x0131 + 's' + [char]0x0131 + 'na tak' + [char]0x0131 + 'lan i' + [char]0x015F + 'lem yok (Defender, G' + [char]0x00FC + 'venlik Duvar' + [char]0x0131 + ', UAC, Windows Update)') {
        $bad = New-Object System.Collections.ArrayList
        foreach ($c in $script:Catalog) {
            foreach ($op in @($c.Ops)) {
                if ([string]$op.T -eq 'Reg' -and (Test-RegWriteBlocked (Resolve-RegPath ([string]$op.Path)) ([string]$op.Name)) -ne '') { [void]$bad.Add([string]$c.Id + ':' + [string]$op.Name) }
                if ([string]$op.T -eq 'Svc' -and (Test-SvcLocked ([string]$op.Name))) { [void]$bad.Add([string]$c.Id + ':' + [string]$op.Name) }
            }
        }
        if ($bad.Count -gt 0) { return (('kap' + [char]0x0131 + 'ya tak' + [char]0x0131 + 'lan: ') + ($bad -join ', ')) }
    }

    Test-Step ('Haz' + [char]0x0131 + 'r ayar d' + [char]0x00FC + 'zeyleri (1-3) kimlik ' + [char]0x00FC + 'retiyor') {
        foreach ($lv in 1, 2, 3) {
            $ids = (Get-PresetIds $lv 'opt' $sync.Profile)
            if ($ids.Count -lt 3) { return (('d' + [char]0x00FC + 'zey ') + $lv + (' ' + [char]0x00E7 + 'ok az ' + [char]0x00F6 + [char]0x011F + 'e: ') + $ids.Count) }
            $st = (New-StepsFromIds ([string[]]$ids))
            if ($st.Count -ne $ids.Count) { return (('d' + [char]0x00FC + 'zey ') + $lv + (': ad' + [char]0x0131 + 'm say' + [char]0x0131 + 's' + [char]0x0131 + ' uyu' + [char]0x015F + 'muyor')) }
        }
    }

    Test-Step ('Hizmet bilgi taban' + [char]0x0131 + ' ve kilitli hizmetler') {
        $e = Get-SvcKbEntry 'DiagTrack'
        if ($null -eq $e -or $e.Rec -ne 'Off') { return ('DiagTrack ' + [char]0x00F6 + 'nerisi yanl' + [char]0x0131 + [char]0x015F) }
        foreach ($n in 'WinDefend', 'mpssvc', 'wuauserv', 'RpcSs', 'EventLog') { if (-not (Test-SvcLocked $n)) { return ($n + (' kilitli de' + [char]0x011F + 'il')) } }
    }

    Test-Step ('A' + [char]0x011F + ' cihaz tan' + [char]0x0131 + 'ma tablolar' + [char]0x0131 + '') {
        $m = Get-OuiMap
        if ($m.Count -lt 20000) { return (('' + [char]0x00FC + 'retici listesi k' + [char]0x00FC + '' + [char]0x00E7 + '' + [char]0x00FC + 'k: ') + $m.Count) }
        if ((Get-MacVendor 'F0F61C112233') -ne 'Apple') { return ('Apple ' + [char]0x00FC + 'reticisi bulunamad' + [char]0x0131 + '') }
        foreach ($tn in @('vendor', 'host', 'mdns', 'upnp', 'ssdp', 'http')) {
            $txt = ''
            switch ($tn) { 'vendor' { $txt = $script:RuleVendor } 'host' { $txt = $script:RuleHost } 'mdns' { $txt = $script:RuleMdns } 'upnp' { $txt = $script:RuleUpnp } 'ssdp' { $txt = $script:RuleSsdp } 'http' { $txt = $script:RuleHttp } }
            $want = @(($txt -split "`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' -and -not $_.StartsWith('#') }).Count
            $got = (Get-RuleTable $tn).Count
            if ($got -ne $want) { return ($tn + (' kural tablosunda ge' + [char]0x00E7 + 'ersiz sat' + [char]0x0131 + 'r var (') + [string]$got + '/' + [string]$want + ')') }
        }
    }

    Test-Step ('A' + [char]0x011F + ' paket ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'mleyicileri (NetBIOS, mDNS)') {
        $q = New-NbstatQuery
        if ($q.Length -ne 50) { return ('NetBIOS sorgusu yanl' + [char]0x0131 + '' + [char]0x015F + ' uzunlukta') }
        $d = New-DnsQuery '_airplay._tcp.local' 12 $true
        if ($d.Length -lt 30 -or $d[5] -ne 1) { return ('mDNS sorgusu yanl' + [char]0x0131 + '' + [char]0x015F + '') }
        if ((ConvertFrom-DnsPacket ([byte[]](1, 2, 3))).Count -ne 0) { return 'bozuk paket kabul edildi' }
        if ($null -ne (ConvertFrom-NbstatReply ([byte[]](1, 2, 3)))) { return ('bozuk NetBIOS yan' + [char]0x0131 + 't' + [char]0x0131 + ' kabul edildi') }
        $u = ConvertFrom-UpnpXml '<root xmlns="urn:schemas-upnp-org:device-1-0"><device><friendlyName>Deneme</friendlyName></device></root>'
        if ($u.Friendly -ne 'Deneme') { return ('UPnP a' + [char]0x00E7 + '' + [char]0x0131 + 'klamas' + [char]0x0131 + ' ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'lemedi') }
        $x = ConvertFrom-UpnpXml '<!DOCTYPE r [<!ENTITY x SYSTEM "file:///c:/windows/win.ini">]><root><device><friendlyName>&x;</friendlyName></device></root>'
        if ($x.Friendly -ne '') { return ('DTD i' + [char]0x00E7 + 'eren XML reddedilmedi') }
    }

    Test-Step ('Cihaz t' + [char]0x00FC + 'r' + [char]0x00FC + ' s' + [char]0x0131 + 'n' + [char]0x0131 + 'fland' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131 + 's' + [char]0x0131) {
        $md = New-MdnsEvidence
        [void]$md.Services.Add('_companion-link._tcp.local')
        $md.Txt['rpmd'] = 'iPhone14,5'
        $ev = @{ Ip = '192.168.1.50'; Mac = ''; Vendor = 'Apple'; Random = $false; Ttl = 64; Rdns = ''; Nb = $null; Mdns = $md; Ssdp = $null; Upnp = $null; Ports = @(); Http = $null; IsGateway = $false; IsSelf = $false; UserName = '' }
        $c = Get-DeviceClass $ev
        if ($c.Type -ne 'phone') { return ('iPhone ' + [string]$c.Type + (' say' + [char]0x0131 + 'ld' + [char]0x0131 + '')) }
        $ev2 = @{ Ip = '192.168.1.1'; Mac = ''; Vendor = 'TP-LINK'; Random = $false; Ttl = 64; Rdns = ''; Nb = $null; Mdns = $null; Ssdp = $null; Upnp = $null; Ports = @(); Http = $null; IsGateway = $true; IsSelf = $false; UserName = '' }
        if ((Get-DeviceClass $ev2).Type -ne 'router') { return ('a' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi y' + [char]0x00F6 + 'nlendirici say' + [char]0x0131 + 'lmad' + [char]0x0131 + '') }
        $ev3 = @{ Ip = '192.168.1.60'; Mac = ''; Vendor = ''; Random = $false; Ttl = 0; Rdns = ''; Nb = $null; Mdns = $null; Ssdp = $null; Upnp = $null; Ports = @(); Http = $null; IsGateway = $false; IsSelf = $false; UserName = '' }
        if ((Get-DeviceClass $ev3).Type -ne 'unknown') { return ('ipucu yokken t' + [char]0x00FC + 'r uydurdu') }
    }

    Test-Step ('Ayg' + [char]0x0131 + 't engelleme korumalar' + [char]0x0131) {
        if ((Test-DevBlockAllowed '8.8.8.8') -eq '') { return 'genel adres engellenebiliyor' }
        if ((Test-DevBlockAllowed '169.254.1.1') -eq '') { return 'link-local engellenebiliyor' }
        $s = Get-DefaultSettings
        if (-not $s.ContainsKey('GwBaseline') -or -not $s.ContainsKey('KnownDevices')) { return ('ayar anahtarlar' + [char]0x0131 + ' eksik') }
    }

    Test-Step 'Hizmetler okunuyor' {
        $rows = (Get-ServiceRows)
        if ($rows.Count -lt 40) { return ('az hizmet: ' + $rows.Count) }
        foreach ($r in $rows) { if ($r.Locked -eq $true -and $r.Rec -eq 'Off') { return (('kilitli hizmet i' + [char]0x00E7 + 'in "kapat" ' + [char]0x00F6 + 'nerisi: ') + [string]$r.Name) } }
    }

    Test-Step ('Uygulama ve ara' + [char]0x00E7 + ' listeleri dolu') {
        if (@($script:AppCatalog).Count -lt 20) { return ('uygulama katalo' + [char]0x011F + 'u k' + [char]0x00FC + [char]0x00E7 + [char]0x00FC + 'k') }
        if (@($script:WinTools).Count -lt 10) { return ('Windows ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ' listesi k' + [char]0x00FC + [char]0x00E7 + [char]0x00FC + 'k') }
    }

    Test-Step ('Ana pencere XAML ayr' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') {
        $xaml = $script:XamlMain.Replace('@@ICONS@@', $script:IconXaml).Replace('@@RES@@', $script:XamlRes)
        $w = Read-LocalXaml ($xaml)
        if ($null -eq $w) { return ('pencere olu' + [char]0x015F + 'mad' + [char]0x0131) }
        $names = @('PageHost', 'LogStack', 'CmdInput', 'CmdList', 'Overlay')
        foreach ($n in $names) { if ($null -eq $w.FindName($n)) { return (('eksik ' + [char]0x00F6 + [char]0x011F + 'e: ') + $n) } }
    }

    Test-Step ('T' + [char]0x00FC + 'm sayfa XAML dosyalar' + [char]0x0131 + ' ayr' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') {
        $vars = @(Get-Variable -Scope Script -Name 'Page_*' | Where-Object { $_.Name -cmatch '^Page_[a-z]+$' })
        if ($vars.Count -lt 13) { return (('sayfa say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + $vars.Count) }
        foreach ($v in $vars) {
            try { [void][System.Windows.Markup.XamlReader]::Parse([string]$v.Value) }
            catch { return ($v.Name + ': ' + $_.Exception.Message) }
        }
    }

    Test-Step ('Sat' + [char]0x0131 + 'r ' + [char]0x015F + 'ablonlar' + [char]0x0131 + ' ayr' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'l' + [char]0x0131 + 'yor') {
        $vars = @(Get-Variable -Scope Script -Name 'Row_*' | Where-Object { $_.Name -cmatch '^Row_[A-Za-z]+$' })
        if ($vars.Count -lt 6) { return (([string][char]0x015F + 'ablon say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + $vars.Count + ' (' + (($vars | ForEach-Object { [string]$_.Name }) -join ', ') + ')') }
        foreach ($v in $vars) {
            $x = [regex]::Replace([string]$v.Value, '@@(Br\w*|Ico\w*)@@', 'BrText')
            $x = [regex]::Replace($x, '@@\w+@@', 'x')
            try { [void][System.Windows.Markup.XamlReader]::Parse($x) }
            catch { return ($v.Name + ': ' + $_.Exception.Message) }
        }
    }

    Test-Step ('Uygulama simgesi ' + [char]0x00E7 + 'iziliyor') {
        $b = New-AppIconBitmap 32
        if ($b.Width -ne 32) { return ('simge boyutu yanl' + [char]0x0131 + [char]0x015F) }
        $b.Dispose()
    }

    Test-Step ('Komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' ayr' + [char]0x0131 + [char]0x015F + 't' + [char]0x0131 + 'r' + [char]0x0131 + 'c' + [char]0x0131) {
        $a = Split-CmdLine ('ping "bir iki" ' + [char]0x00FC + [char]0x00E7)
        if ($a.Count -ne 3 -or [string]$a[1] -ne 'bir iki') { return (('beklenmeyen sonu' + [char]0x00E7 + ': ') + ($a -join '|')) }
    }

    Test-Step ('Kay' + [char]0x0131 + 't defteri: ' + [char]0x00F6 + 'nizleme de' + [char]0x011F + 'i' + [char]0x015F + 'tirmez, uygula yazar, geri al eski h' + [char]0x00E2 + 'le d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'r') {
        $rk = 'HKCU\Software\MultimizerSinama'
        try {
            Set-RegData $rk 'Deger' 'DWord' 1
            Set-RegData $rk 'Metin' 'String' 'eski'
            $steps = @(@{ Title = 'Sinama'; Ops = @((RegOp $rk 'Deger' 7), (RegOp $rk 'Yeni' 'abc' 'String'), (RegDel $rk 'Metin')) })
            Reset-Counters
            $script:Preview = $true
            Invoke-Plan $steps $false
            if ([int](Get-RegValue $rk 'Deger' -1) -ne 1) { return ([string][char]0x00F6 + 'nizleme de' + [char]0x011F + 'eri de' + [char]0x011F + 'i' + [char]0x015F + 'tirdi') }
            if ($script:Changes -ne 3) { return (([string][char]0x00F6 + 'nizleme ad' + [char]0x0131 + 'm say' + [char]0x0131 + 's' + [char]0x0131 + ': ') + $script:Changes) }
            Reset-Counters
            $script:Preview = $false
            $before = @(Get-ChildItem -LiteralPath $sync.BackupDir -Filter 'yedek-*.jsonl' -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
            Invoke-Plan $steps $false
            if ([int](Get-RegValue $rk 'Deger' -1) -ne 7) { return ('uygula de' + [char]0x011F + 'eri yazmad' + [char]0x0131) }
            if ($null -ne (Get-RegValue $rk 'Metin' $null)) { return ('silme uygulanmad' + [char]0x0131) }
            $after = @(Get-ChildItem -LiteralPath $sync.BackupDir -Filter 'yedek-*.jsonl' -ErrorAction SilentlyContinue | Where-Object { $before -notcontains $_.FullName })
            if ($after.Count -lt 1) { return ('de' + [char]0x011F + 'i' + [char]0x015F + 'iklik g' + [char]0x00FC + 'nl' + [char]0x00FC + [char]0x011F + [char]0x00FC + ' yaz' + [char]0x0131 + 'lmad' + [char]0x0131) }
            $jf = $after[0].FullName
            Reset-Counters
            Invoke-Undo $jf
            if ([int](Get-RegValue $rk 'Deger' -1) -ne 1) { return ('geri alma Deger de' + [char]0x011F + 'erini d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'rmedi') }
            if ([string](Get-RegValue $rk 'Metin' '') -ne 'eski') { return ('geri alma silinen de' + [char]0x011F + 'eri d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'rmedi') }
            if ($null -ne (Get-RegValue $rk 'Yeni' $null)) { return ('geri alma yeni de' + [char]0x011F + 'eri silmedi') }
            foreach ($f in @($after)) {
                Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue
                Remove-Item -LiteralPath ([System.IO.Path]::ChangeExtension($f.FullName, '.geri.reg')) -Force -ErrorAction SilentlyContinue
                Remove-Item -LiteralPath ([System.IO.Path]::ChangeExtension($f.FullName, '.geri-alindi.jsonl')) -Force -ErrorAction SilentlyContinue
            }
        } finally {
            $script:Preview = $false
            try {
                $sp = Split-RegPath $rk
                $bk = Get-RegBaseKey $sp[0]
                try { $bk.DeleteSubKeyTree($sp[1], $false) } finally { $bk.Close() }
            } catch { }
        }
    }

    Test-Step ('G' + [char]0x00FC + 'venlik kap' + [char]0x0131 + 's' + [char]0x0131 + ': Defender / g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ' ilkeleri yaz' + [char]0x0131 + 'lamaz') {
        $a = Test-RegWriteBlocked 'HKLM\SOFTWARE\Policies\Microsoft\Windows Defender' 'DisableAntiSpyware'
        if ($a -eq '') { return ('Defender ilkesi korumas' + [char]0x0131 + 'z') }
        $b = Test-RegWriteBlocked 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableLUA'
        if ($b -eq '') { return ('UAC ilkesi korumas' + [char]0x0131 + 'z') }
    }

    Test-Step ('Ayar profili: d' + [char]0x0131 + [char]0x015F + 'a aktar, do' + [char]0x011F + 'rula') {
        $ids = @($script:Catalog | Where-Object { [int]$_.Level -le 2 } | Select-Object -First 3 | ForEach-Object { [string]$_.Id })
        $prof = New-ProfileObject 'Sinama' $ids @() @()
        $notes = New-Object System.Collections.ArrayList
        $st = (Get-ProfileSteps $prof $notes)
        if ($st.Count -lt 1) { return ('profil ad' + [char]0x0131 + 'm' + [char]0x0131 + ' ' + [char]0x00FC + 'retilmedi') }
    }

    Test-Step ('Arka plan ' + [char]0x00E7 + 'al' + [char]0x0131 + [char]0x015F + 'ma alan' + [char]0x0131 + ' (runspace) ' + [char]0x00E7 + 'ekirde' + [char]0x011F + 'i y' + [char]0x00FC + 'kl' + [char]0x00FC + 'yor') {
        Initialize-Work
        Wait-CoreRunspace $script:Work
        $ps = [powershell]::Create()
        $ps.Runspace = $script:Work.Rs
        [void]$ps.AddScript('(Get-SigLine) + "|" + [string](Get-Command Job_Plan -ErrorAction Ignore).Name')
        $o = @($ps.Invoke())
        $err = @($ps.Streams.Error)
        $ps.Dispose()
        if ($o.Count -lt 1) { return ([string][char]0x00E7 + [char]0x0131 + 'kt' + [char]0x0131 + ' yok') }
        if (([string]$o[0]) -notmatch 'Job_Plan$') { return (('Job_Plan bulunamad' + [char]0x0131 + ': ') + [string]$o[0] + ' ' + ($err -join ';')) }
    }

    Test-Step ('Zamanlanm' + [char]0x0131 + [char]0x015F + ' g' + [char]0x00F6 + 'rev yetenekleri (Register-ScheduledTask vb.)') {
        foreach ($c in 'Register-ScheduledTask', 'New-ScheduledTaskTrigger', 'Get-ScheduledTaskInfo', 'Unregister-ScheduledTask') {
            if ($null -eq (Get-Command -Name $c -ErrorAction Ignore)) { return ($c + (' bulunamad' + [char]0x0131)) }
        }
        $tt = ConvertTo-TaskTime '03:15' '03:00'
        if ($tt.Minute -ne 15 -or $tt.Hour -ne 3) { return ('saat d' + [char]0x00F6 + 'n' + [char]0x00FC + [char]0x015F + [char]0x00FC + 'm' + [char]0x00FC + ' ba' + [char]0x015F + 'ar' + [char]0x0131 + 's' + [char]0x0131 + 'z') }
    }

    Test-Step ('Windows ara' + [char]0x00E7 + 'lar' + [char]0x0131 + ': robocopy, sfc, dism, powercfg, schtasks, netsh') {
        $miss = @()
        foreach ($e in 'robocopy.exe', 'sfc.exe', 'dism.exe', 'powercfg.exe', 'schtasks.exe', 'netsh.exe', 'shutdown.exe') {
            if (-not (Test-Path -LiteralPath (Join-Path (Join-Path $env:WINDIR 'System32') $e))) { $miss += $e }
        }
        if ($miss.Count -gt 0) { return (('bulunamad' + [char]0x0131 + ': ') + ($miss -join ', ')) }
    }

    Test-Step ('winget kullan' + [char]0x0131 + 'labilir (program g' + [char]0x00FC + 'ncelleme i' + [char]0x00E7 + 'in; yoksa yaln' + [char]0x0131 + 'zca uyar' + [char]0x0131 + ')') {
        if ((Get-WingetPath) -eq '') { return ('winget yok: Program g' + [char]0x00FC + 'ncelleme devre d' + [char]0x0131 + [char]0x015F + [char]0x0131 + ' kal' + [char]0x0131 + 'r') }
    } $true

    Test-Step ('Canl' + [char]0x0131 + ' izleme verisi (CPU / RAM) ' + [char]0x00FC + 'retilebiliyor') {
        $c = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        if ([double]$c.TotalVisibleMemorySize -le 0) { return ('bellek bilgisi okunamad' + [char]0x0131) }
    }

    Test-Step ('VPN: WireGuard yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rmas' + [char]0x0131 + ' do' + [char]0x011F + 'rulan' + [char]0x0131 + 'yor (ge' + [char]0x00E7 + 'erli kabul, tehlikeli reddedilir)') {
        $need = @('ConvertFrom-WgConfig', 'ConvertTo-WgConfText', 'Get-WgSummary', 'ConvertTo-WgName', 'Test-WgKey')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
        $k1 = [Convert]::ToBase64String([byte[]](1..32 | ForEach-Object { [byte](($_ * 7) % 251) }))
        $k2 = [Convert]::ToBase64String([byte[]](1..32 | ForEach-Object { [byte](($_ * 11) % 251) }))
        $good = "[Interface]`nPrivateKey = $k1`nAddress = 10.64.0.2/32`nDNS = 10.64.0.1`n`n[Peer]`nPublicKey = $k2`nAllowedIPs = 0.0.0.0/0, ::/0`nEndpoint = 203.0.113.10:51820`nPersistentKeepalive = 25`n"
        $c = ConvertFrom-WgConfig $good
        if ($c.Ok -ne $true) { return (('ge' + [char]0x00E7 + 'erli yap' + [char]0x0131 + 'land' + [char]0x0131 + 'rma reddedildi: ') + (@($c.Errors) -join ' | ')) }
        $sm = Get-WgSummary $c
        if (([string]($sm | ConvertTo-Json -Depth 5)).Contains($k1)) { return ('' + [char]0x00F6 + 'zet ' + [char]0x00F6 + 'zel anahtar' + [char]0x0131 + ' i' + [char]0x00E7 + 'eriyor') }
        $bad = ConvertFrom-WgConfig ($good + "PostUp = calc.exe`n")
        if ($bad.Ok -eq $true) { return ('PostUp sat' + [char]0x0131 + 'r' + [char]0x0131 + ' kabul edildi') }
        $bad2 = ConvertFrom-WgConfig ($good -replace '203\.0\.113\.10:51820', '203.0.113.10')
        if ($bad2.Ok -eq $true) { return ('ba' + [char]0x011F + 'lant' + [char]0x0131 + ' noktas' + [char]0x0131 + 'z Endpoint kabul edildi') }
        if (-not (Test-WgKey $k1)) { return ('ge' + [char]0x00E7 + 'erli anahtar reddedildi') }
        if (Test-WgKey ('k' + [char]0x0131 + 'sa')) { return ('ge' + [char]0x00E7 + 'ersiz anahtar kabul edildi') }
        $n = ConvertTo-WgName ('C:\Users\x\Ev A' + [char]0x011F + '' + [char]0x0131 + '.conf')
        if ($n -cnotmatch '^[A-Za-z0-9_=+.\-]{1,32}$') { return (('t' + [char]0x00FC + 'nel ad' + [char]0x0131 + ' g' + [char]0x00FC + 'venli de' + [char]0x011F + 'il: ') + $n) }
    }

    Test-Step ('VPN: kill-switch kurallar' + [char]0x0131 + ' (yerel g' + [char]0x00FC + 'venlik duvar' + [char]0x0131 + ', her zaman kapat' + [char]0x0131 + 'labilir)') {
        $need = @('New-KsRuleSpecs', 'Get-IpRangesExcept4', 'Disable-KillSwitchNow', 'Get-KsState', 'Job_KsVerify', 'Invoke-CliEmergency')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
        $r = @(Get-IpRangesExcept4 @('10.64.0.1'))
        if (($r -join ' ') -ne '0.0.0.0-10.64.0.0 10.64.0.2-255.255.255.255') { return (('adres aral' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' yanl' + [char]0x0131 + '' + [char]0x015F + ': ') + ($r -join ' ')) }
        $ctx = @{ Endpoints = @('203.0.113.10'); TunnelAddrs = @('10.64.0.2'); Alias = 'Ev_Agi'; Dns = @('10.64.0.1'); AllowLan = $true }
        $sp = @(New-KsRuleSpecs $ctx)
        $ids = @($sp | ForEach-Object { [string]$_.Id })
        foreach ($must in 'endpoint', 'tunnel', 'dhcp4', 'dns4-udp', 'dns4-tcp') { if ($ids -notcontains $must) { return ('kural yok: ' + $must) } }
        foreach ($s in $sp) {
            if ($s.P.Direction -ne 'Outbound') { return (('y' + [char]0x00F6 + 'n giden de' + [char]0x011F + 'il: ') + [string]$s.Id) }
            if (@('Allow', 'Block') -notcontains [string]$s.P.Action) { return (('eylem ge' + [char]0x00E7 + 'ersiz: ') + [string]$s.Id) }
        }
        $ep = @($sp | Where-Object { $_.Id -eq 'endpoint' })[0]
        if ($ep.P.Action -ne 'Allow') { return ('VPN sunucusuna izin kural' + [char]0x0131 + ' yok; ba' + [char]0x011F + 'lant' + [char]0x0131 + ' kurulamazd' + [char]0x0131 + '') }
    }

    Test-Step ('A' + [char]0x011F + ': cihaz engelleme kendi bilgisayar' + [char]0x0131 + ', a' + [char]0x011F + ' ge' + [char]0x00E7 + 'idi ve genel adresleri reddediyor') {
        if ($null -eq (Get-Command -Name 'Test-DevBlockAllowed' -CommandType Function -ErrorAction Ignore)) { return 'Test-DevBlockAllowed yok' }
        if ((Test-DevBlockAllowed '8.8.8.8') -eq '') { return 'genel adres engellenebiliyor' }
        if ((Test-DevBlockAllowed '169.254.10.10') -eq '') { return ('ba' + [char]0x011F + 'lant' + [char]0x0131 + '-yerel adres engellenebiliyor') }
        $own = ''
        try { $own = [string](@(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction Stop | Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254.*' } | Select-Object -First 1)[0].IPAddress) } catch { }
        if ($own -ne '' -and (Test-DevBlockAllowed $own) -eq '') { return ('bu bilgisayar' + [char]0x0131 + 'n kendi adresi engellenebiliyor') }
    }

    Test-Step ('Tema: ' + [char]0x00FC + '' + [char]0x00E7 + ' teman' + [char]0x0131 + 'n renk anahtarlar' + [char]0x0131 + ' ve de' + [char]0x011F + 'erleri ge' + [char]0x00E7 + 'erli') {
        if ($null -eq $script:Themes) { return 'tema tablosu yok' }
        $keys = @{}
        foreach ($m in [regex]::Matches([string]$script:XamlRes, 'SolidColorBrush x:Key="(Br[A-Za-z0-9]+)"')) { $keys[$m.Groups[1].Value] = $true }
        $neon = @($script:Themes['Neon'].Keys)
        foreach ($tn in @($script:Themes.Keys)) {
            $t = $script:Themes[$tn]
            if (@($t.Keys).Count -ne $neon.Count) { return ($tn + (': anahtar say' + [char]0x0131 + 's' + [char]0x0131 + ' Neon ile ayn' + [char]0x0131 + ' de' + [char]0x011F + 'il')) }
            foreach ($k in @($t.Keys)) {
                if (-not $keys.ContainsKey([string]$k)) { return ($tn + (': aray' + [char]0x00FC + 'zde ') + [string]$k + ' rengi yok') }
                try { [void][System.Windows.Media.ColorConverter]::ConvertFromString([string]$t[$k]) } catch { return ($tn + ': ' + [string]$k + (' rengi ' + [char]0x00E7 + '' + [char]0x00F6 + 'z' + [char]0x00FC + 'lemedi')) }
            }
        }
    }

    Test-Step ('' + [char]0x0130 + 'nternet istekleri: her ' + [char]0x00F6 + 'zelli' + [char]0x011F + 'in i' + [char]0x015F + 'i tan' + [char]0x0131 + 'ml' + [char]0x0131 + ', kapal' + [char]0x0131 + ' ' + [char]0x00F6 + 'zellik i' + [char]0x015F + 'i engelliyor') {
        if ($null -eq $script:NetFeatures -or $script:NetFeatures.Count -lt 5) { return ('' + [char]0x00F6 + 'zellik tablosu eksik') }
        foreach ($k in @($script:NetFeatures.Keys)) {
            foreach ($j in @($script:NetFeatures[$k].Jobs)) {
                if ($null -eq (Get-Command -Name $j -CommandType Function -ErrorAction Ignore)) { return ([string]$k + (': i' + [char]0x015F + ' yok: ') + [string]$j) }
            }
        }
        if ((Test-NetBlocked 'Job_Health') -eq $true) { return ('sa' + [char]0x011F + 'l' + [char]0x0131 + 'k taramas' + [char]0x0131 + ' internet anahtar' + [char]0x0131 + 'na ba' + [char]0x011F + 'l' + [char]0x0131 + ' olmamal' + [char]0x0131 + '') }
    }

    Test-Step ('G' + [char]0x00FC + 'ncelleme denetimi: duraklat, ertele ve s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + ' ad' + [char]0x0131 + 'mlar' + [char]0x0131 + ' g' + [char]0x00FC + 'venlik kap' + [char]0x0131 + 's' + [char]0x0131 + 'ndan ge' + [char]0x00E7 + 'iyor') {
        $need = @('New-WuPauseSteps', 'New-WuDeferSteps', 'New-WuDriverSteps', 'Get-WuControlState', 'Job_InstalledUpdates', 'Job_WuUninstall', 'Job_WingetPin')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
        $all = New-Object System.Collections.ArrayList
        foreach ($st in @((New-WuPauseSteps 7), (New-WuPauseSteps 0), (New-WuDeferSteps 180), (New-WuDeferSteps 0), (New-WuDriverSteps $true), (New-WuDriverSteps $false))) { foreach ($x in @($st)) { [void]$all.Add($x) } }
        if ($all.Count -lt 6) { return (('ad' + [char]0x0131 + 'm say' + [char]0x0131 + 's' + [char]0x0131 + ' eksik: ') + [string]$all.Count) }
        foreach ($stp in $all) {
            foreach ($op in @($stp.Ops)) {
                if ((Test-RegWriteBlocked (Resolve-RegPath ([string]$op.Path)) ([string]$op.Name)) -ne '') { return (('g' + [char]0x00FC + 'venlik kap' + [char]0x0131 + 's' + [char]0x0131 + 'na tak' + [char]0x0131 + 'ld' + [char]0x0131 + ': ') + [string]$op.Name) }
                if ([string]$op.Name -match '^(NoAutoUpdate|AUOptions|DisableWindowsUpdateAccess|SetDisableUXWUAccess)$') { return (('Windows Update kapatan de' + [char]0x011F + 'er: ') + [string]$op.Name) }
            }
        }
        if (@(New-WuPauseSteps 99).Count -ne 0) { return ('35 g' + [char]0x00FC + 'nden uzun duraklatma kabul edildi') }
        if (@(New-WuDeferSteps 400).Count -ne 0) { return ('365 g' + [char]0x00FC + 'nden uzun erteleme kabul edildi') }
    }

    Test-Step ('Dosya temizli' + [char]0x011F + 'i: sistem yollar' + [char]0x0131 + ' ve b' + [char]0x00FC + 'y' + [char]0x00FC + 'k dosyalar Geri D' + [char]0x00F6 + 'n' + [char]0x00FC + '' + [char]0x015F + '' + [char]0x00FC + 'm Kutusu' + [char]0x2019 + 'na g' + [char]0x00F6 + 'nderilmez, kopyalarda biri kal' + [char]0x0131 + 'r') {
        $need = @('Get-RecycleVerdict', 'Job_RecycleFiles', 'Get-DupFullGroups', 'Job_LargeFiles', 'Job_Duplicates')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
        $win = [string]$env:WINDIR
        if ($win -ne '' -and (Get-RecycleVerdict (Join-Path $win 'System32\kernel32.dll') 1000 'Fixed' 1000000000) -eq '') { return ('Windows klas' + [char]0x00F6 + 'r' + [char]0x00FC + 'ndeki dosya g' + [char]0x00F6 + 'nderilebiliyor') }
        if ((Get-RecycleVerdict 'D:\x\a.bin' 1000 'Removable' 1000000000) -eq '') { return ('' + [char]0x00E7 + '' + [char]0x0131 + 'kar' + [char]0x0131 + 'labilir s' + [char]0x00FC + 'r' + [char]0x00FC + 'c' + [char]0x00FC + 'deki dosya g' + [char]0x00F6 + 'nderilebiliyor') }
        if ((Get-RecycleVerdict 'D:\x\a.bin' 900000000 'Fixed' 1000000000) -eq '') { return ('Kutuya s' + [char]0x0131 + '' + [char]0x011F + 'mayacak dosya g' + [char]0x00F6 + 'nderilebiliyor') }
        $two = @(@{ Group = '1' }, @{ Group = '1' })
        if (@(Get-DupFullGroups $two @{ '1' = 2 }).Count -ne 1) { return ('t' + [char]0x00FC + 'm kopyalar' + [char]0x0131 + ' i' + [char]0x015F + 'aretlenen grup yakalanmad' + [char]0x0131 + '') }
        if (@(Get-DupFullGroups $two @{ '1' = 3 }).Count -ne 0) { return ('biri kalan grup yanl' + [char]0x0131 + '' + [char]0x015F + ' yakaland' + [char]0x0131 + '') }
    }

    Test-Step ('' + [char]0x015E + 'ifreli yedek: depo yolu ve komut sat' + [char]0x0131 + 'r' + [char]0x0131 + ' (parola komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'nda yok, ge' + [char]0x00E7 + 'ici dosyalar d' + [char]0x0131 + '' + [char]0x015F + 'ar' + [char]0x0131 + 'da)') {
        $need = @('Find-Restic', 'Get-ResticRepoPath', 'New-ResticBackupArgs', 'Format-ProcessArg', 'Invoke-Restic', 'Job_ResticBackup', 'Job_ResticSnapshots', 'Job_ResticRestore')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
        $tmpd = [System.IO.Path]::GetTempPath()
        $repo = Get-ResticRepoPath $tmpd
        if ($repo -notmatch '\.restic$' -or $repo -notlike ('*' + [string]$env:COMPUTERNAME + '*')) { return ('depo yolu beklenmedik: ' + $repo) }
        $a = @(New-ResticBackupArgs $repo @($tmpd) $false)
        if ($a[0] -ne 'backup' -or $a -notcontains '--repo' -or $a -notcontains $repo) { return 'yedek komutu eksik' }
        if (@($a | Where-Object { [string]$_ -match 'password|parola' }).Count -gt 0) { return ('parola komut sat' + [char]0x0131 + 'r' + [char]0x0131 + 'nda g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'yor') }
        if ($a -contains '--dry-run') { return ('ger' + [char]0x00E7 + 'ek yedekte --dry-run var') }
        if ((@(New-ResticBackupArgs $repo @($tmpd) $true)) -notcontains '--dry-run') { return ('' + [char]0x00F6 + 'nizlemede --dry-run yok') }
        if ((Format-ProcessArg 'a b') -ne '"a b"') { return ('bo' + [char]0x015F + 'luklu ba' + [char]0x011F + '' + [char]0x0131 + 'ms' + [char]0x0131 + 'z de' + [char]0x011F + 'i' + [char]0x015F + 'ken t' + [char]0x0131 + 'rnaklanm' + [char]0x0131 + 'yor') }
    }

    Test-Step ('Kullan' + [char]0x0131 + 'm t' + [char]0x00FC + 'r' + [char]0x00FC + ': her se' + [char]0x00E7 + 'enek var olan sayfa ve sekmeye gidiyor') {
        if ($null -eq $script:UseCases -or $script:UseCases.Count -lt 4) { return ('kullan' + [char]0x0131 + 'm t' + [char]0x00FC + 'r' + [char]0x00FC + ' tablosu eksik') }
        $pre = @{ optimize = 'op'; company = 'co'; clean = 'cl'; updates = 'up'; backup = 'bk'; network = 'nw'; security = 'sc'; gaming = 'gm'; power = 'pw'; smart = 'sm' }
        foreach ($k in @($script:UseCases.Keys)) {
            $u = $script:UseCases[$k]
            $pv = Get-Variable -Name ('Page_' + [string]$u.Page) -Scope Script -ErrorAction SilentlyContinue
            if ($null -eq $pv) { return ([string]$k + ': sayfa yok: ' + [string]$u.Page) }
            if ([string]$u.Sub -ne '') {
                if (-not $pre.ContainsKey([string]$u.Page)) { return ([string]$k + (': sayfa ' + [char]0x00F6 + 'n eki bilinmiyor')) }
                if (([string]$pv.Value) -notmatch ('x:Name="' + $pre[[string]$u.Page] + '_Tab_' + [string]$u.Sub + '"')) { return ([string]$k + ': sekme yok: ' + [string]$u.Sub) }
            }
            if ([string]$u.Hint -eq '' -or [string]$u.T -eq '') { return ([string]$k + ': metin eksik') }
        }
    }

    Test-Step ('Aray' + [char]0x00FC + 'z: yeni sekmelerin d' + [char]0x00FC + '' + [char]0x011F + 'me ve alan adlar' + [char]0x0131 + ' sayfa tan' + [char]0x0131 + 'mlar' + [char]0x0131 + 'nda var') {
        $want = @{
            clean   = @('cl_Tab_big', 'cl_Tab_dup', 'cl_FScan', 'cl_FPick', 'cl_FAuto', 'cl_FRecycle')
            updates = @('up_Tab_ctl', 'up_Tab_inst', 'up_Pause', 'up_Resume', 'up_Defer', 'up_DeferOff', 'up_DrvToggle', 'up_Uninstall', 'up_Pin', 'up_Unpin', 'up_PinList')
            backup  = @('bk_Tab_bl', 'bk_BlRefresh', 'bk_BlWeb', 'bk_ModeRestic', 'bk_ResticInfo', 'bk_ResticGet', 'bk_ResticSnaps')
            settings = @('st_UseCase', 'st_UseCaseText')
        }
        foreach ($pg in @($want.Keys)) {
            $pv = Get-Variable -Name ('Page_' + $pg) -Scope Script -ErrorAction SilentlyContinue
            if ($null -eq $pv) { return ('sayfa yok: ' + $pg) }
            foreach ($n in $want[$pg]) { if (([string]$pv.Value) -notmatch ('x:Name="' + $n + '"')) { return ($pg + ': ' + $n + ' yok') } }
        }
        if ([string]$script:XamlMain -notmatch 'x:Name="OvChoices"') { return 'OvChoices yok' }
    }

    Test-Step ('Veri ve eklenti dosyalar' + [char]0x0131 + ' yerinde, SHA-256 ' + [char]0x00F6 + 'zetleri tutuyor') {
        $bad = New-Object System.Collections.ArrayList
        foreach ($rel in @($script:PackHash.Keys | Sort-Object)) {
            $r = Get-PackFileText ([string]$rel)
            if ($r.Ok -ne $true) { [void]$bad.Add([string]$rel + ' (' + [string]$r.Kind + ')') }
        }
        if ($bad.Count -gt 0) { return ('sorunlu dosya: ' + ($bad -join ', ') + ('. ZIP dosyas' + [char]0x0131 + 'n' + [char]0x0131 + 'n tamam' + [char]0x0131 + 'n' + [char]0x0131 + ' ' + [char]0x00E7 + '' + [char]0x0131 + 'kart' + [char]0x0131 + 'n.')) }
    } $true

    Test-Step ('' + [char]0x00DC + 'retici tablosu (OUI) y' + [char]0x00FC + 'klenir') {
        $m = Get-OuiMap
        if ($m.Count -lt 30000) { return (('tablo bo' + [char]0x015F + ' ya da eksik: ') + [string]$m.Count + (' kay' + [char]0x0131 + 't')) }
    } $true

    Test-Step (('Eklentiler y' + [char]0x00FC + 'klenir (' + [char]0x015F + 'ifreleme, bellek bo' + [char]0x015F + 'alt' + [char]0x0131 + 'c' + [char]0x0131 + ', g' + [char]0x00FC + 'venli silme, Wi-Fi d' + [char]0x0131 + '' + [char]0x015F + 'a aktarma, disk koruma, kurtarma, disk silme)')) {
        foreach ($n in $script:MmExtNames) {
            $r = Import-MmExt $n
            if ($r.Ok -ne $true) { return ([string]$n + ': ' + [string]$r.Error) }
        }
    } $true

    Test-Step ('G' + [char]0x00FC + '' + [char]0x00E7 + ': plan tablosu, ' + [char]0x015F + 'ablonlar ve ' + [char]0x00F6 + 'nizleme farklar' + [char]0x0131 + '') {
        $need = @('Get-PwList', 'Get-PwActive', 'Find-PwScheme', 'Get-PwValue', 'Get-PwSnapshot', 'Compare-PwSnapshot', 'Format-PwValue', 'Invoke-PowerSetOp', 'Invoke-PowerCustomOp', 'Invoke-PowerDeleteOp', 'Invoke-PowerCpuMaxOp', 'Job_PowerInfo', 'Job_PowerPreview', 'Get-PwLive')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
        $keys = @{}
        foreach ($d in $script:PwSet) {
            if ($keys.ContainsKey([string]$d.K)) { return ('yinelenen ayar: ' + [string]$d.K) }
            $keys[[string]$d.K] = $true
            if ([string]$d.Sub -notmatch ('^' + $script:GuidRx + '$') -or [string]$d.Id -notmatch ('^' + $script:GuidRx + '$')) { return (('ge' + [char]0x00E7 + 'ersiz GUID: ') + [string]$d.K) }
        }
        foreach ($t in $script:PwTemplates.Keys) {
            $tp = $script:PwTemplates[$t]
            if (-not $script:PwKnown.Contains([string]$tp.Base)) { return (('' + [char]0x015F + 'ablon taban' + [char]0x0131 + ' bilinmiyor: ') + [string]$t) }
            foreach ($k in @($tp['Values'].Keys)) { if (-not $keys.ContainsKey([string]$k)) { return (('' + [char]0x015F + 'ablonda bilinmeyen ayar: ') + [string]$k) } }
        }
        $a = @{ CpuMax = @{ Ac = 100; Dc = 100 }; Display = @{ Ac = 600; Dc = 300 } }
        $b = @{ CpuMax = @{ Ac = 80; Dc = 100 }; Display = @{ Ac = 600; Dc = 300 } }
        $d = @(Compare-PwSnapshot $a $b)
        if ($d.Count -ne 1 -or [string]$d[0].K -ne 'CpuMax') { return ('fark hesab' + [char]0x0131 + ' yanl' + [char]0x0131 + '' + [char]0x015F + '') }
        if ((Format-PwValue (Get-PwDef 'Display') 0) -ne ('Hi' + [char]0x00E7 + 'bir zaman')) { return ('s' + [char]0x00FC + 're bi' + [char]0x00E7 + 'imi yanl' + [char]0x0131 + '' + [char]0x015F + '') }
        if ((Get-PwSafeName 'a"b;c&d') -match '["&;]') { return ('plan ad' + [char]0x0131 + ' temizlenmiyor') }
        foreach ($k in @('PowerSet', 'PowerCustom', 'PowerDelete', 'PowerCpuMax')) { if (-not $script:MoreOps.ContainsKey($k)) { return (('i' + [char]0x015F + 'lem kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'il: ') + $k) } }
        foreach ($k in @('PowerNew', 'PowerDel', 'PowerCpuMax')) { if (-not $script:MoreUndo.ContainsKey($k)) { return (('geri alma kay' + [char]0x0131 + 'tl' + [char]0x0131 + ' de' + [char]0x011F + 'il: ') + $k) } }
    }

    Test-Step ('Oyun: oyun ba' + [char]0x015F + '' + [char]0x0131 + 'na ayarlar yaln' + [char]0x0131 + 'zca Windows grafik tercihlerine yaz' + [char]0x0131 + 'l' + [char]0x0131 + 'r, di' + [char]0x011F + 'er ayarlar korunur') {
        $need = @('Job_GameScan', 'Get-GmSteamGames', 'Get-GmEpicGames', 'Get-GmGogGames', 'Find-GmMainExe', 'Get-GmRunning', 'Invoke-GameFlagsOp', 'Merge-DxGlobal', 'Job_GameBoost')
        $miss = @($need | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction Ignore) })
        if ($miss.Count -gt 0) { return ('eksik: ' + ($miss -join ', ')) }
        if ($script:GmGpuKey -notlike 'HKCU\*' -or $script:GmLayersKey -notlike 'HKCU\*') { return ('oyun ayarlar' + [char]0x0131 + ' kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' dal' + [char]0x0131 + ' d' + [char]0x0131 + '' + [char]0x015F + '' + [char]0x0131 + 'na yaz' + [char]0x0131 + 'yor') }
        $m = Merge-DxGlobal 'AutoHDREnable=1;SwapEffectUpgradeEnable=0;' @{ SwapEffectUpgradeEnable = '1'; VRROptimizeEnable = '1' }
        if ($m -notmatch 'AutoHDREnable=1' -or $m -notmatch 'SwapEffectUpgradeEnable=1' -or $m -notmatch 'VRROptimizeEnable=1') { return (('DirectX ayarlar' + [char]0x0131 + ' birle' + [char]0x015F + 'tirilemedi: ') + $m) }
        if (Test-GmExePath 'C:\x\"a.exe') { return ('ge' + [char]0x00E7 + 'ersiz yol kabul edildi') }
