    Test-Step ('S' + [char]0x0131 + 'k' + [char]0x0131 + '' + [char]0x015F + 't' + [char]0x0131 + 'rma: Windows, g' + [char]0x00FC + 'venlik ve kullan' + [char]0x0131 + 'c' + [char]0x0131 + ' ana klas' + [char]0x00F6 + 'rleri reddedilir') {
