        foreach ($x in $o) {
            $bx = $x
            if ($bx -is [psobject]) { $bx = $bx.psobject.BaseObject }
            if ($bx -is [hashtable]) { $r = $bx }
        }
        if ($null -eq $r) { return (('arka plan s' + [char]0x0131 + 'namas' + [char]0x0131 + ' sonu' + [char]0x00E7 + ' vermedi ') + ($err -join ';')) }
        if ($r.Ok -ne $true) { return (('arka plan i' + [char]0x015F + ' par' + [char]0x00E7 + 'ac' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ': ') + (@($r.Bad) -join '; ') + (' [k' + [char]0x00FC + 'lt' + [char]0x00FC + 'r: ') + [string]$r.Culture + ']') }
    }

    Add-SelfLine ''
    $okN = $script:SelfTotal - $script:SelfFail
    $sum = (('Sonu' + [char]0x00E7 + ': ') + $okN + ' / ' + $script:SelfTotal + (' s' + [char]0x0131 + 'nama ba' + [char]0x015F + 'ar' + [char]0x0131 + 'l' + [char]0x0131 + ', ') + $script:SelfFail + ' hata, ' + $script:SelfWarn + (' uyar' + [char]0x0131 + '.'))
    Add-SelfLine $sum
    Add-SelfLine ('   ' + (Get-SigLine))
    $report = Join-Path $script:DataDir 'ozsinama.txt'
    try { [System.IO.File]::WriteAllText($report, (($script:SelfLines.ToArray()) -join "`r`n"), (New-Object System.Text.UTF8Encoding($true))) } catch { }
    if (-not $Sessiz) {
        try {
            $icon = 'Information'
            if ($script:SelfFail -gt 0) { $icon = 'Warning' }
            $msg = $sum + ("`r`n`r`nAyr" + [char]0x0131 + "nt" + [char]0x0131 + "lar: ") + $report
            if ($script:SelfFail -gt 0) {
                $bad = @($script:SelfLines | Where-Object { $_ -like '  [HATA]*' })
                $msg += ("`r`n`r`n" + ($bad -join "`r`n"))
            }
            [void][System.Windows.MessageBox]::Show($msg, ('Multimizer - S' + [char]0x0131 + 'nama'), 'OK', $icon)
        } catch { }
    }
    return $script:SelfFail
}

# ==================================================================
#  ANA AKIS
#    -OzTest         kendi kendine sinama
#    -Cli -Gorev ..  pencere acmadan gorev calistirma
#    (varsayilan)    Multimizer arayuzu;  -Tepsi ile pencere gizli (yalnizca bildirim alani) baslar
# ==================================================================
function Hide-ConsoleWindow {
    if ($Gizli) { return }
    try {
        if (-not ('WH.ConsoleWin' -as [type])) {
            Add-Type -Namespace WH -Name ConsoleWin -MemberDefinition '[DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow(); [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow); [DllImport("kernel32.dll")] public static extern uint GetConsoleProcessList(uint[] processList, uint processCount);'
        }
        $h = [WH.ConsoleWin]::GetConsoleWindow()
        if ($h -eq [IntPtr]::Zero) { return }
        $list = New-Object 'uint32[]' 8
        $n = [WH.ConsoleWin]::GetConsoleProcessList($list, 8)
        # Konsolu yalnizca bu islem kullaniyorsa gizle; baskalariyla paylasiliyorsa yalnizca simge durumuna kucult
        if ($n -le 1) { [void][WH.ConsoleWin]::ShowWindow($h, 0) } else { [void][WH.ConsoleWin]::ShowWindow($h, 6) }
    } catch { }
}

# Calisan baska bir kopya varsa onu one getirip cikar
function Test-SingleInstance {
    $script:GuiMutex = $null
    $script:ShowEvent = $null
    $got = $true
    try {
        $script:GuiMutex = New-Object System.Threading.Mutex($false, 'Global\Multimizer-Arayuz')
        try { $got = $script:GuiMutex.WaitOne(0) } catch [System.Threading.AbandonedMutexException] { $got = $true }
    } catch { return $true }
    if (-not $got) {
        try {
            $ev = [System.Threading.EventWaitHandle]::OpenExisting('Global\Multimizer-Goster')
            [void]$ev.Set()
        } catch { }
        return $false
    }
    try { $script:ShowEvent = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::AutoReset, 'Global\Multimizer-Goster') } catch { }
    return $true
}

function Start-ShowSignalTimer {
    if ($null -eq $script:ShowEvent) { return }
    $script:SigTicks = 0
    $script:SigFired = 0
    $script:SigTimer = New-Object System.Windows.Threading.DispatcherTimer -ArgumentList ([System.Windows.Threading.DispatcherPriority]::Normal)
    $script:SigTimer.Interval = [TimeSpan]::FromMilliseconds(400)
    $script:SigTimer.Add_Tick({
        try {
            $script:SigTicks = [int]$script:SigTicks + 1
            if ($script:ShowEvent.WaitOne(0)) {
                $script:SigFired = [int]$script:SigFired + 1
                Restore-FromTray
            }
        } catch { Write-CrashLog ('Ikinci acilis sinyali: ' + $_.Exception.Message) }
    })
    $script:SigTimer.Start()
}

function Invoke-GuiMode {
    Set-SplashStep 'pencere'
    # onceki oturum beklenmedik bittiyse bu oturum guvenli kipte acilir; oturum kaydi ve izi baslar
    try { Start-SessionTrace } catch { Write-CrashLog ('Oturum izi: ' + $_.Exception.Message) }
    # onceki acilislar tamamlanmadiysa gorunum varsayilana doner (cokme dongusunu keser)
    try { Invoke-BootGuard } catch { }

    $mode = 'User'
    if ([string]$script:Settings.Mode -eq 'Expert') { $mode = 'Expert' }
    $script:UiState.Mode = $mode
    $script:StartHidden = [bool]$Tepsi

    $app = New-Object System.Windows.Application
    $app.ShutdownMode = [System.Windows.ShutdownMode]::OnExplicitShutdown
    $script:App = $app
    $app.Add_DispatcherUnhandledException({
        param($s, $e)
        $e.Handled = $true
        try {
            $storm = Register-UiError
            $em = [string]$e.Exception.Message
            Write-CrashLog ('Yakalanmamis hata: ' + $em + ' :: ' + ([string]$e.Exception.StackTrace -replace '\s+', ' '))
            if (-not (Test-ErrorBurst $em)) { Show-Toast ('Hata: ' + $em) 'bad' }
            if ($storm) { Stop-ErrorStorm }
        } catch { }
    })
    # Windows oturumu kapanirken surec zorla sonlandirilabilir: bu bir cokme sayilmasin
    $app.Add_SessionEnding({ $script:Quitting = $true; try { Stop-SessionTrace 'windows-oturumu-kapaniyor' } catch { } })

    # guvenli kipte WPF yalnizca yazilimla cizer (ilk pencere olusmadan once ayarlanmalidir)
    try { Set-RenderMode } catch { }
    $w = New-MainWindow
    try { Initialize-SessionHooks } catch { }
    Initialize-Appearance
    Initialize-Shell
    try { Initialize-Layout } catch { Write-CrashLog ('Yerlesim: ' + $_.Exception.Message) }
    try { Initialize-Design } catch { Write-CrashLog ('Tasarim: ' + $_.Exception.Message) }
    try { Initialize-Glass } catch { Write-CrashLog ('Saydamlik: ' + $_.Exception.Message) }
    Init-CmdLine
    try { Initialize-Scrolling } catch { Write-CrashLog ('Kaydirma: ' + $_.Exception.Message) }
    try { Register-A11yNames } catch { Write-CrashLog (('Eri' + [char]0x015F + 'ilebilirlik: ') + $_.Exception.Message) }
    try { Initialize-Responsive } catch { Write-CrashLog ('Duyarli yerlesim: ' + $_.Exception.Message) }
    Initialize-Tray
    Start-UiTimers
    Start-ShowSignalTimer
    Set-UiMode $mode $true

    if ($script:StartHidden) {
        $w.WindowState = [System.Windows.WindowState]::Minimized
        $w.ShowInTaskbar = $false
    }

    $w.Add_Loaded({
        try {
            try { Start-Monitor } catch { Show-Crash $_ 'Izleyici' }
            try { Show-Page 'panel' } catch { Show-Crash $_ 'Panel' }
            Write-WhLog (('Haz' + [char]0x0131 + 'r. ') + [string]$sync.Profile.OsName + ' ' + [string]$sync.Profile.Version) 'INFO'
            try { Complete-Splash } catch { }
            try { Set-SessionOpen } catch { }
            if ($script:Settings.HideConsole -ne $false -and -not $script:SmokeMode) { Hide-ConsoleWindow }
            if ($script:StartHidden) {
                $script:TrayHintShown = $true
                $script:Win.Hide()
            } elseif ($script:SafeBoot) {
                Show-Toast ('' + [char]0x00D6 + 'nceki a' + [char]0x00E7 + '' + [char]0x0131 + 'l' + [char]0x0131 + '' + [char]0x015F + ' tamamlanamad' + [char]0x0131 + '' + [char]0x011F + '' + [char]0x0131 + ' i' + [char]0x00E7 + 'in g' + [char]0x00F6 + 'r' + [char]0x00FC + 'n' + [char]0x00FC + 'm g' + [char]0x00FC + 'venli de' + [char]0x011F + 'erlere d' + [char]0x00F6 + 'nd' + [char]0x00FC + 'r' + [char]0x00FC + 'ld' + [char]0x00FC + ' (Neon tema, mini izleyici kapal' + [char]0x0131 + '). Ayarlar sayfas' + [char]0x0131 + 'ndan yeniden se' + [char]0x00E7 + 'ebilirsiniz.') 'warn'
            } elseif ($script:Settings.Installed -ne $true) {
                Show-Toast ([string][char]0x0130 + 'pucu: Ayarlar sayfas' + [char]0x0131 + 'ndaki ' + [char]0x201C + 'Kur' + [char]0x201D + ' ile uygulamay' + [char]0x0131 + ' kal' + [char]0x0131 + 'c' + [char]0x0131 + ' h' + [char]0x00E2 + 'le getirip zamanlanm' + [char]0x0131 + [char]0x015F + ' bak' + [char]0x0131 + 'm' + [char]0x0131 + ' a' + [char]0x00E7 + 'abilirsiniz.') 'info'
            }
        } catch { Show-Crash $_ 'Loaded' }
        try { Start-BootOkTimer } catch { }
        if ($script:SmokeMode) { try { Start-SmokeRun } catch { Add-SmokeError 'duman baslatma' $_.Exception.Message; Complete-SmokeRun } }
    })

    $script:RunFailed = $false
    try {
        [void]$app.Run($w)
    } catch {
        $script:RunFailed = $true
        $runMsg = [string]$_.Exception.Message
        Write-CrashLog ('Run: ' + $runMsg + ' :: ' + ([string]$_.ScriptStackTrace -replace '\s+', ' '))
        try { Show-StartFailure $runMsg } catch { }
    }
    if (-not $script:RunFailed) { try { Confirm-BootOk } catch { } }

    # ---- kapanis ----
    try { $script:PumpTimer.Stop(); $script:MonTimer.Stop() } catch { }
    try { [void](Save-DebugErrors 'ana') } catch { }
    try { if ($null -ne $script:SigTimer) { $script:SigTimer.Stop() } } catch { }
    Remove-Tray
    try { [void](Remove-ShadowLinks) } catch { }
    Stop-AllWork
    try { if ($null -ne $script:GuiMutex) { $script:GuiMutex.ReleaseMutex() } } catch { }
    $sessWhy = 'normal'
    if ($script:RunFailed) { $sessWhy = 'baslatma-hatasi' } elseif ($script:StormDone) { $sessWhy = 'hata-firtinasi' }
    try { Stop-SessionTrace $sessWhy } catch { }
    if ($script:RunFailed) { return 4 }
    if ($script:StormDone -and -not $script:SmokeMode) { return 5 }
    return 0
}

# ------------------------------------------------------------------
#  Baslangic
# ------------------------------------------------------------------
# Baska bir kopya aciksa agir hazirliklara girmeden onu one getirip cik
if (-not $Cli -and -not $OzTest -and -not $Duman) {
    if (-not (Test-SingleInstance)) {
        Stop-Splash ('Multimizer zaten a' + [char]0x00E7 + '' + [char]0x0131 + 'k; mevcut pencere ' + [char]0x00F6 + 'ne getirildi.')
        try { Restore-ConsoleGuard } catch { }
        [Environment]::Exit(0)
    }
}
Set-SplashStep 'ayarlar'
$script:Settings = Get-Settings
$sync.Settings = $script:Settings
try { Initialize-Lang } catch { }
try { Set-DebugLogState (($script:Settings.DebugLog -eq $true) -or $script:DebugLogArg) } catch { }
# Windows'un korudugu (yazilamayan) kayit degerleri: is parcaciklariyla paylasilir (bkz. Windows'un korudugu kayit degerleri bolumu)
$sync.RegDenied = [hashtable]::Synchronized(@{})
try { foreach ($rl in @($script:Settings.RegDenied)) { if ([string]$rl -ne '') { $sync.RegDenied[([string]$rl).ToLowerInvariant()] = $true } } } catch { }
try { [void](Remove-OldLogs ([int]$script:Settings.KeepLogDays) $script:LogDir) } catch { }
$ms = [int]$script:Settings.MonitorSec
if ($ms -lt 1) { $ms = 2 }
$sync.MonInterval = $ms

if (-not $Cli -and -not $OzTest) {
    # Arka plan calisma alani pencere hazirlanirken isinsin
    Set-SplashStep 'calisma'
    try { Initialize-Work } catch { }
}

Set-SplashStep 'sistem'
$sync.Profile = Get-SystemProfile
if (-not [string]::IsNullOrEmpty([string]$sync.Profile.TargetSid)) { $sync.TargetSid = [string]$sync.Profile.TargetSid }

if ($OzTest) {
    Stop-Splash
    $nr = @(Invoke-SelfTest)
    try { [void](Save-DebugErrors 'ana') } catch { }
    $n = 1
    if ($nr.Count -gt 0) { $n = [int]$nr[$nr.Count - 1] }
    try { Stop-AllWork } catch { }
    try { Restore-ConsoleGuard } catch { }
    [Environment]::Exit([int]$n)
}

if ($Cli) {
    if ($Sessiz) { $sync.Echo = $false }
    $cr = @(Invoke-CliMode)
    try { [void](Save-DebugErrors 'ana') } catch { }
    $code = 1
    if ($cr.Count -gt 0) { $code = [int]$cr[$cr.Count - 1] }
    [Environment]::Exit([int]$code)
}

$exitCode = 1
if ($Duman) { Initialize-Smoke }
else { try { [void](Initialize-CrashHooks (Join-Path $script:LogDir ('hata-' + (Get-Date -Format 'yyyyMMdd') + '.txt'))) } catch { } }
try {
    $gr = @(Invoke-GuiMode)
    $exitCode = 0
    if ($gr.Count -gt 0) { $exitCode = [int]$gr[$gr.Count - 1] }
    if ($Duman) { $exitCode = [int]$script:SmokeExit }
} catch {
    $msg = [string]$_.Exception.Message
    try { Write-CrashLog ('Baslatma hatasi: ' + $msg + ' :: ' + ([string]$_.ScriptStackTrace -replace '\s+', ' ')) } catch { }
    try { Show-StartFailure $msg } catch { }
}

try { Restore-ConsoleGuard } catch { }
Write-Host ''
Write-Host (('   Te' + [char]0x015F + 'ekk' + [char]0x00FC + 'rler.   Multimizer   ') + (Get-SigLine)) -ForegroundColor Cyan
Write-Host ''
try { Stop-AllWork } catch { }
[Environment]::Exit([int]$exitCode)
